# iOS Habit Tracking App

Here's a complete implementation of a native iOS habit tracking application using Swift and SwiftUI. This app allows users to track daily habits with progress visualization.

## 1. Project Setup

First, create a new SwiftUI project in Xcode.

## 2. Data Models

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var color: String

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily, completionDates: [Date] = [], color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = completionDates
        self.color = color
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }
}
```

## 3. View Models

```swift
// HabitStore.swift
import Foundation
import SwiftUI

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let data = try? Data(contentsOf: try Self.fileURL()) else {
                DispatchQueue.main.async {
                    self?.habits = []
                }
                return
            }
            guard let habits = try? JSONDecoder().decode([Habit].self, from: data) else {
                DispatchQueue.main.async {
                    self?.habits = []
                }
                return
            }
            DispatchQueue.main.async {
                self?.habits = habits
            }
        }
    }

    func save() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let habits = self?.habits else { return }
            guard let data = try? JSONEncoder().encode(habits) else { return }
            try? data.write(to: try Self.fileURL(), options: [.atomicWrite])
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        save()
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].isCompletedToday {
                habits[index].completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                habits[index].completionDates.append(Date())
            }
            save()
        }
    }

    func streakCount(for habit: Habit) -> Int {
        let calendar = Calendar.current
        var currentDate = Date()
        var streak = 0

        while true {
            if habit.completionDates.contains(where: { calendar.isDate($0, inSameDayAs: currentDate) }) {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
            } else {
                break
            }
        }

        return streak
    }
}
```

