// HabitDetailView.swift
struct HabitDetailView: View {
    let habit: Habit
    @ObservedObject var store: HabitStore
    @State private var showingEdit = false

    var body: some View {
        VStack {
            Text(habit.name)
                .font(.largeTitle)
                .padding()

            Text(habit.description)
                .font(.body)
                .foregroundColor(.gray)
                .padding(.bottom)

            Text("Frequency: \(habit.frequency.rawValue)")
                .font(.subheadline)

            Text("Current Streak: \(store.streakCount(for: habit)) days")
                .font(.subheadline)
                .padding(.bottom)

            ProgressView(value: Double(store.streakCount(for: habit)), total: 30)
                .padding()

            Button(action: {
                store.toggleCompletion(for: habit)
            }) {
                Text(habit.isCompletedToday ? "Mark as Incomplete" : "Mark as Complete")
                    .frame(maxWidth: .infinity)
                    .padding()
                    .background(habit.isCompletedToday ? Color.red : Color.green)
                    .foregroundColor(.white)
                    .cornerRadius(10)
            }
            .padding()

            Spacer()
        }
        .navigationTitle(habit.name)
        .toolbar {
            ToolbarItem(placement: .navigationBarTrailing) {
                Button("Edit") {
                    showingEdit = true
