### Habit Detail View
```swift
// HabitDetailView.swift
import SwiftUI

struct HabitDetailView: View {
    @EnvironmentObject var habitStore: HabitStore
    @State var habit: Habit
    @State private var showingEditView = false

    var body: some View {
        Form {
            Section(header: Text("Details")) {
                Text(habit.description)
                Text("Frequency: \(habit.frequency.rawValue)")
            }

            Section(header: Text("Completion")) {
                ForEach(getLast7Days(), id: \.self) { date in
                    HStack {
                        Text(date, style: .date)
                        Spacer()
                        Image(systemName: habit.completionStatus[date.startOfDay] ?? false ? "checkmark.circle.fill" : "circle")
                            .foregroundColor(habit.completionStatus[date.startOfDay] ?? false ? .green : .gray)
                    }
                }
            }

            Section {
                Button("Edit Habit") {
                    showingEditView = true
                }
            }
        }
        .navigationTitle(habit.name)
        .sheet(isPresented: $showingEditView) {
            EditHabitView(habit: $habit)
        }
        .onChange(of: habit) { newHabit in
            habitStore.updateHabit(newHabit)
        }
    }

    private func getLast7Days() -> [Date] {
        let calendar = Calendar.current
        return (0..<7).compactMap { calendar.date(byAdding: .day, value: -$0, to: Date()) }
    }
}
```

