```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var completionDates: [Date]
    var targetFrequency: Int // Number of times per week

    var isCompleteToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var weeklyProgress: Double {
        let currentWeekDates = getCurrentWeekDates()
        let completedDays = completionDates.filter { currentWeekDates.contains($0) }.count
        return Double(completedDays) / Double(targetFrequency)
    }

    private func getCurrentWeekDates() -> [Date] {
        let calendar = Calendar.current
        let today = Date()
        let weekStart = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: today))!

        return (0..<7).compactMap { day in
            calendar.date(byAdding: .day, value: day, to: weekStart)
        }
    }

    init(id: UUID = UUID(), name: String, description: String, targetFrequency: Int) {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.completionDates = []
    }

    mutating func toggleCompletion() {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: Date()) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(Date())
        }
    }
}
```

### HabitStore.swift
```swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    static func load(completion: @escaping (Result<[Habit], Error>)->Void) {
        DispatchQueue.global(qos: .background).async {
            do {
                let fileURL = try fileURL()
                guard let file = try? FileHandle(forReadingFrom: fileURL) else {
                    DispatchQueue.main.async {
                        completion(.success([]))
                    }
                    return
                }
                let habits = try JSONDecoder().decode([Habit].self, from: file.availableData)
                DispatchQueue.main.async {
                    completion(.success(habits))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(error))
                }
            }
        }
    }

    static func save(habits: [Habit], completion: @escaping (Result<Int, Error>)->Void) {
        DispatchQueue.global(qos: .background).async {
            do {
                let data = try JSONEncoder().encode(habits)
                let outfile = try fileURL()
                try data.write(to: outfile)
                DispatchQueue.main.async {
                    completion(.success(habits.count))
                }
            } catch {
                DispatchQueue.main.async {
                    completion(.failure(error))
                }
            }
        }
    }
}
