// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var completionDates: [Date]
    var targetFrequency: Int // Number of times per day to complete

    init(id: UUID = UUID(), name: String, description: String = "", targetFrequency: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.completionDates = []
    }

    // Check if habit was completed on a specific date
    func wasCompleted(on date: Date) -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    // Get completion count for a specific date
    func completionCount(on date: Date) -> Int {
        let calendar = Calendar.current
        return completionDates.filter { calendar.isDate($0, inSameDayAs: date) }.count
    }

    // Mark habit as completed
    mutating func markCompleted() {
        completionDates.append(Date())
    }

    // Remove the most recent completion
    mutating func undoCompletion() {
        if !completionDates.isEmpty {
            completionDates.removeLast()
        }
    }
}
