import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var targetFrequency: Int // e.g., 1 for daily, 7 for weekly
    var completionDates: [Date]

    init(id: UUID = UUID(), name: String, description: String, targetFrequency: Int, completionDates: [Date] = []) {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.completionDates = completionDates
    }

    // Check if habit was completed on a specific date
    func wasCompleted(on date: Date) -> Bool {
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: date) }
    }

    // Toggle completion status for a date
    mutating func toggleCompletion(on date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }

    // Calculate completion percentage for a date range
    func completionPercentage(from startDate: Date, to endDate: Date) -> Double {
        let daysInRange = Calendar.current.dateComponents([.day], from: startDate, to: endDate).day ?? 0
        let completedDays = completionDates.filter { $0 >= startDate && $0 <= endDate }.count
        return Double(completedDays) / Double(daysInRange)
    }
}
