import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var targetFrequency: Int // e.g., 1 for daily, 7 for weekly
    var completionDates: [Date]
    var color: String // Hex color code

    init(id: UUID = UUID(), name: String, description: String = "", targetFrequency: Int = 1, completionDates: [Date] = [], color: String = "#34C759") {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.completionDates = completionDates
        self.color = color
    }

    var isCompletedToday: Bool {
        return completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var streak: Int {
        guard let lastCompletion = completionDates.sorted().last else { return 0 }

        let calendar = Calendar.current
        var currentDate = lastCompletion
        var streakCount = 0

        while calendar.isDateInToday(currentDate) || calendar.isDateInYesterday(currentDate) {
            if completionDates.contains(where: { calendar.isDate($0, inSameDayAs: currentDate) }) {
                streakCount += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
            } else {
                break
            }
        }

        return streakCount
    }
}
```

