```swift
import SwiftUI

struct CalendarView: View {
    let habit: Habit
    @State private var currentMonth = Date()

    var body: some View {
        VStack {
            HStack {
                Button(action: { previousMonth() }) {
                    Image(systemName: "chevron.left")
                }

                Spacer()

                Text(currentMonth, formatter: monthFormatter)
                    .font(.headline)

                Spacer()

                Button(action: { nextMonth() }) {
                    Image(systemName: "chevron.right")
                }
            }
            .padding(.horizontal)

            LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 7), spacing: 8) {
                ForEach(weekdaySymbols, id: \.self) { symbol in
                    Text(symbol)
                        .font(.caption)
                        .foregroundColor(.secondary)
                }

                ForEach(daysInMonth(), id: \.self) { date in
                    if let date = date {
                        DayView(date: date, isCompleted: habit.completionDates.contains { Calendar.current.isDate($0, inSameDayAs: date) })
                    } else {
                        Color.clear
                    }
                }
            }
            .padding()
        }
    }

    private var monthFormatter: DateFormatter {
        let formatter = DateFormatter()
        formatter.dateFormat = "MMMM yyyy"
        return formatter
    }

    private var weekdaySymbols: [String] {
        Calendar.current.shortWeekdaySymbols
    }

    private func daysInMonth() -> [Date?] {
        guard let monthInterval = Calendar.current.dateInterval(of: .month, for: currentMonth) else {
            return []
        }

        let daysInMonth = Calendar.current.range(of: .day, in: .month, for: currentMonth)?.count ?? 0
        let firstDayOfMonth = monthInterval.start
        let firstWeekday = Calendar.current.component(.weekday, from: firstDayOfMonth)

        var days: [Date?] = Array(repeating: nil, count: firstWeekday - 1)

        for day in 1...daysInMonth {
            if let date = Calendar.current.date(byAdding: .day, value: day - 1, to: firstDayOfMonth) {
                days.append(date)
            }
        }

        return days
    }

    private func previousMonth() {
        if let newDate = Calendar.current.date(byAdding: .month, value: -1, to: currentMonth) {
            currentMonth = newDate
        }
    }

    private func nextMonth() {
        if let newDate = Calendar.current.date(byAdding: .month, value: 1, to: currentMonth) {
            currentMonth = newDate
        }
    }
}

struct DayView: View {
    let date: Date
    let isCompleted: Bool

