# iOS Habit Tracking App

Here's a complete implementation of a native iOS habit tracking application using Swift and SwiftUI. This app allows users to track daily habits with progress visualization.

## 1. Project Setup

First, create a new SwiftUI project in Xcode. Then add these files:

### Habit Model
```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var completionCount: Int
    var targetCount: Int
    var isCompletedToday: Bool
    var lastCompletedDate: Date?

    init(id: UUID = UUID(), name: String, description: String = "", targetCount: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.targetCount = targetCount
        self.completionCount = 0
        self.isCompletedToday = false
    }

    mutating func toggleCompletion() {
        if isCompletedToday {
            completionCount -= 1
        } else {
            completionCount += 1
            lastCompletedDate = Date()
        }
        isCompletedToday.toggle()
    }

    mutating func resetDailyStatus() {
        isCompletedToday = false
    }
}
```

### Data Manager
```swift
// HabitDataManager.swift
import Foundation

class HabitDataManager: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func resetDailyStatus() {
        for i in 0..<habits.count {
            habits[i].resetDailyStatus()
        }
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Stay hydrated", targetCount: 8),
            Habit(name: "Exercise", description: "30 minutes of workout"),
            Habit(name: "Read", description: "Read for 20 minutes", targetCount: 1)
        ]
    }
}
```

