    @StateObject private var dataManager = HabitDataManager()

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environmentObject(dataManager)
                .onAppear {
                    // Check if we need to reset daily status
                    let calendar = Calendar.current
                    let now = Date()

                    if let lastResetDate = UserDefaults.standard.object(forKey: "LastResetDate") as? Date {
                        if !calendar.isDateInToday(lastResetDate) {
                            dataManager.resetDailyStatus()
                            UserDefaults.standard.set(now, forKey: "LastResetDate")
                        }
                    } else {
                        UserDefaults.standard.set(now, forKey: "LastResetDate")
                    }
                }
        }
    }
}
