### Data Persistence
```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() async throws {
        let task = Task<[Habit], Error> {
            let fileURL = try Self.fileURL()
            guard let data = try? Data(contentsOf: fileURL) else {
                return []
            }
            let habits = try JSONDecoder().decode([Habit].self, from: data)
            return habits
        }
        let habits = try await task.value
        self.habits = habits
    }

    func save(habits: [Habit]) async throws {
        let task = Task {
            let data = try JSONEncoder().encode(habits)
            let outfile = try Self.fileURL()
            try data.write(to: outfile)
        }
        _ = try await task.value
    }

    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]

            if Calendar.current.isDateInToday(updatedHabit.lastCompletedDate ?? .distantPast) {
                // Already completed today, decrement
                updatedHabit.completionCount -= 1
                updatedHabit.isCompletedToday = false
                updatedHabit.lastCompletedDate = nil
            } else {
                // New completion
                updatedHabit.completionCount += 1
                updatedHabit.isCompletedToday = true
                updatedHabit.lastCompletedDate = Date()
            }

            habits[index] = updatedHabit

            Task {
                do {
                    try await save(habits: habits)
                } catch {
                    print("Error saving habits: \(error)")
                }
            }
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        Task {
            do {
                try await save(habits: habits)
            } catch {
                print("Error saving habits: \(error)")
            }
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        Task {
            do {
                try await save(habits: habits)
            } catch {
                print("Error saving habits: \(error)")
            }
        }
    }

    func resetDailyCompletions() {
        for i in 0..<habits.count {
            habits[i].isCompletedToday = false
            if !Calendar.current.isDateInToday(habits[i].lastCompletedDate ?? .distantPast) {
                habits[i].lastCompletedDate = nil
            }
        }

        Task {
            do {
                try await save(habits: habits)
            } catch {
                print("Error saving habits: \(error)")
            }
        }
    }
}
```

