# iOS Habit Tracking App

Here's a complete implementation of a native iOS habit tracking application using Swift and SwiftUI. This app allows users to track daily habits with progress visualization.

## 1. Project Setup

First, create a new SwiftUI project in Xcode. Then add these files:

### Habit Model
```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var completionDates: [Date]
    var targetFrequency: Int // Number of times per day to complete

    init(id: UUID = UUID(), name: String, description: String = "", targetFrequency: Int = 1) {
        self.id = id
        self.name = name
        self.description = description
        self.completionDates = []
        self.targetFrequency = targetFrequency
    }

    // Check if habit was completed on a specific date
    func wasCompleted(on date: Date) -> Bool {
        return completionDates.contains { Calendar.current.isDate($0, inSameDayAs: date) }
    }

    // Get count of completions for a specific date
    func completionCount(on date: Date) -> Int {
        return completionDates.filter { Calendar.current.isDate($0, inSameDayAs: date) }.count
    }

    // Mark habit as completed
    mutating func markCompleted() {
        completionDates.append(Date())
    }

    // Remove the most recent completion
    mutating func undoCompletion() {
        if !completionDates.isEmpty {
            completionDates.removeLast()
        }
    }
}
```

### Data Persistence
```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func markHabitCompleted(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].markCompleted()
            saveHabits()
        }
    }

    func undoHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].undoCompletion()
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none saved
        habits = [
            Habit(name: "Drink Water", description: "Stay hydrated", targetFrequency: 8),
            Habit(name: "Exercise", description: "30 minutes of physical activity"),
            Habit(name: "Read", description: "Read for 20 minutes")
        ]
    }
}
