                HStack(spacing: 10) {
                    ForEach(getLast7Days(), id: \.self) { date in
                        VStack {
                            Text(date, style: .date)
                                .font(.caption)

                            Text("\(habit.completionCount(on: date))")
                                .font(.title2)
