                updatedHabit.lastCompletedDate = Date()
            }

            habits[index] = updatedHabit
            saveHabits()
        }
    }

    func resetDailyCompletion() {
        for i in 0..<habits.count {
            habits[i].isCompletedToday = false
        }
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none saved
        habits = [
            Habit(name: "Drink Water", description: "Stay hydrated", targetCount: 8, color: "blue"),
            Habit(name: "Exercise", description: "30 minutes of workout", targetCount: 1, color: "green"),
            Habit(name: "Read", description: "Read for 20 minutes", targetCount: 1, color: "purple")
        ]
    }
}
