```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var streak: Int
    var lastCompleted: Date?
    var completionDates: [Date]

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.streak = 0
        self.completionDates = []
    }

    mutating func completeHabit() {
        let today = Calendar.current.startOfDay(for: Date())

        // Only allow completing once per day
        if let lastCompleted = lastCompleted, Calendar.current.isDate(lastCompleted, inSameDayAs: today) {
            return
        }

        streak += 1
        lastCompleted = today
        completionDates.append(today)
    }

    mutating func resetStreak() {
        streak = 0
    }
}

extension Habit {
    var progressPercentage: Double {
        guard !completionDates.isEmpty else { return 0 }

        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        // Get the earliest date in the completionDates array
        guard let earliestDate = completionDates.min() else { return 0 }

        // Calculate the number of days between the earliest date and today
        let components = calendar.dateComponents([.day], from: earliestDate, to: today)
        let totalDays = components.day ?? 0

        // Calculate the percentage of days completed
        let percentage = Double(completionDates.count) / Double(totalDays + 1) * 100
        return min(percentage, 100)
    }
}
