### Data Persistence
```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private static func fileURL() throws -> URL {
        try FileManager.default.url(for: .documentDirectory,
                                   in: .userDomainMask,
                                   appropriateFor: nil,
                                   create: false)
            .appendingPathComponent("habits.data")
    }

    func load() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let data = try? Data(contentsOf: try Self.fileURL()) else {
                DispatchQueue.main.async {
                    self?.habits = []
                }
                return
            }
            guard let habits = try? JSONDecoder().decode([Habit].self, from: data) else {
                DispatchQueue.main.async {
                    self?.habits = []
                }
                return
            }
            DispatchQueue.main.async {
                self?.habits = habits
            }
        }
    }

    func save() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let habits = self?.habits else { return }
            guard let data = try? JSONEncoder().encode(habits) else {
                fatalError("Error encoding habits")
            }
            do {
                let outfile = try Self.fileURL()
                try data.write(to: outfile)
            } catch {
                fatalError("Error writing habits to file")
            }
        }
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        save()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            save()
        }
    }

    func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        save()
    }

    func resetDailyCompletion() {
        let calendar = Calendar.current
        let now = Date()

        for i in 0..<habits.count {
            if let lastCompletedDate = habits[i].lastCompletedDate {
                if !calendar.isDateInToday(lastCompletedDate) {
                    habits[i].isCompletedToday = false
                }
            }
        }
        save()
    }
}
