```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var targetFrequency: Int // e.g., 1 for daily, 7 for weekly
    var completionDates: [Date]
    var color: String // Hex color code

    init(id: UUID = UUID(), name: String, description: String = "", targetFrequency: Int, color: String = "#3498DB") {
        self.id = id
        self.name = name
        self.description = description
        self.targetFrequency = targetFrequency
        self.completionDates = []
        self.color = color
    }

    var isCompleteToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var completionPercentage: Double {
        let daysSinceStart = Calendar.current.dateComponents([.day], from: completionDates.first ?? Date(), to: Date()).day ?? 1
        let targetDays = daysSinceStart > 0 ? daysSinceStart : 1
        return Double(completionDates.count) / Double(targetDays)
    }
}
```

### HabitStore.swift
```swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func toggleCompletion(for habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].isCompleteToday {
                habits[index].completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                habits[index].completionDates.append(Date())
            }
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Stay hydrated", targetFrequency: 1, color: "#3498DB"),
            Habit(name: "Exercise", description: "30 minutes of activity", targetFrequency: 1, color: "#E74C3C"),
            Habit(name: "Read", description: "Read for 20 minutes", targetFrequency: 1, color: "#2ECC71")
        ]
    }
}
