```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var streak: Int

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String, frequency: Frequency) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.streak = 0
    }

    mutating func toggleCompletion(for date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
            streak = 0
        } else {
            completionDates.append(date)
            updateStreak()
        }
    }

    private mutating func updateStreak() {
        guard let lastDate = completionDates.max() else { return }

        let calendar = Calendar.current
        var currentDate = calendar.startOfDay(for: Date())
        var newStreak = 0

        while calendar.isDate(lastDate, inSameDayAs: currentDate) ||
              completionDates.contains(where: { calendar.isDate($0, inSameDayAs: currentDate) }) {
            newStreak += 1
            currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate)!
        }

        streak = newStreak
    }
}
```

## 3. Habit Store

Create a class to manage habits and persistence:

```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func toggleCompletion(for habit: Habit, on date: Date) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].toggleCompletion(for: date)
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Drink 8 glasses of water daily", frequency: .daily),
            Habit(name: "Exercise", description: "Workout for 30 minutes", frequency: .daily)
        ]
    }
}
