```swift
import SwiftUI

struct AddHabitView: View {
    @Environment(\.dismiss) var dismiss
    @ObservedObject var habitStore: HabitStore

    @State private var name = ""
    @State private var description = ""
    @State private var frequency: Habit.Frequency = .daily
    @State private var reminders: [Habit.Reminder] = []
    @State private var newReminderTime = Date()

    var habit: Habit?

    var body: some View {
        NavigationView {
            Form {
                Section(header: Text("Habit Details")) {
                    TextField("Name", text: $name)
                    TextField("Description", text: $description)
                    Picker("Frequency", selection: $frequency) {
                        ForEach(Habit.Frequency.allCases, id: \.self) { freq in
                            Text(freq.rawValue)
                        }
                    }
                }

                Section(header: Text("Reminders")) {
                    ForEach(reminders) { reminder in
                        HStack {
                            Text("\(reminder.time.hour ?? 0):\(String(format: "%02d", reminder.time.minute ?? 0))")
                            Spacer()
                            Toggle("", isOn: .constant(reminder.isActive))
                                .labelsHidden()
                        }
                    }
                    .onDelete(perform: deleteReminders)

                    HStack {
                        DatePicker("", selection: $newReminderTime, displayedComponents: .hourAndMinute)
                            .labelsHidden()
                        Button("Add Reminder") {
                            let calendar = Calendar.current
                            let components = calendar.dateComponents([.hour, .minute], from: newReminderTime)
                            reminders.append(Habit.Reminder(time: components))
                        }
                    }
                }
            }
            .navigationTitle(habit == nil ? "Add Habit" : "Edit Habit")
            .toolbar {
                ToolbarItem(placement: .navigationBarLeading) {
                    Button("Cancel") {
                        dismiss()
                    }
                }
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button("Save") {
                        saveHabit()
                        dismiss()
                    }
                    .disabled(name.isEmpty)
                }
            }
            .onAppear {
                if let habit = habit {
                    name = habit.name
                    description = habit.description
                    frequency = habit.frequency
                    reminders = habit.reminders
                }
            }
        }
    }

    func saveHabit() {
        let newHabit = Habit(
            id: habit?.id ?? UUID(),
            name: name,
            description: description,
            frequency: frequency,
            streak: habit?.streak ?? 0,
            lastCompleted: habit?.lastCompleted,
            isCompletedToday: habit?.isCompletedToday ?? false,
            reminders: reminders
        )

        if let habit = habit {
            habitStore.updateHabit(newHabit)
        } else {
            habitStore.addHabit(newHabit)
        }
    }

    func deleteReminders(at offsets: IndexSet) {
        reminders.remove(atOffsets: offsets)
    }
}
