        }
    }

    func deleteHabit(at indexSet: IndexSet) {
        habits.remove(atOffsets: indexSet)
        saveHabits()
    }

    func toggleHabitCompletion(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if habits[index].isCompletedToday {
                habits[index].completionDates.removeAll { Calendar.current.isDateInToday($0) }
            } else {
                habits[index].completionDates.append(Date())
            }
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
            }
        }
    }

    func getCompletionPercentage(for habit: Habit) -> Double {
        let calendar = Calendar.current
        let now = Date()

        switch habit.frequency {
        case .daily:
            let startOfDay = calendar.startOfDay(for: now)
            let endOfDay = calendar.date(byAdding: .day, value: 1, to: startOfDay)!
            let completedDays = habit.completionDates.filter { $0 >= startOfDay && $0 < endOfDay }
            return Double(completedDays.count) / 1.0

        case .weekly:
            let startOfWeek = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now))!
            let endOfWeek = calendar.date(byAdding: .day, value: 7, to: startOfWeek)!
            let completedDays = habit.completionDates.filter { $0 >= startOfWeek && $0 < endOfWeek }
            return Double(completedDays.count) / 7.0

        case .monthly:
            let startOfMonth = calendar.date(from: calendar.dateComponents([.year, .month], from: now))!
            let endOfMonth = calendar.date(byAdding: .month, value: 1, to: startOfMonth)!
            let completedDays = habit.completionDates.filter { $0 >= startOfMonth && $0 < endOfMonth }
            let daysInMonth = calendar.range(of: .day, in: .month, for: now)!.count
            return Double(completedDays.count) / Double(daysInMonth)
        }
    }
}
