import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var title: String
    var description: String
    var goal: Int
    var frequency: Frequency
    var completionDates: [Date]
    var createdAt: Date

    enum Frequency: String, CaseIterable, Codable {
        case daily, weekly, monthly
    }

    init(id: UUID = UUID(), title: String, description: String = "", goal: Int, frequency: Frequency, completionDates: [Date] = [], createdAt: Date = Date()) {
        self.id = id
        self.title = title
        self.description = description
        self.goal = goal
        self.frequency = frequency
        self.completionDates = completionDates
        self.createdAt = createdAt
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var progress: Double {
        let completedCount = completionDates.count
        return Double(completedCount) / Double(goal)
    }
}
