import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetCount: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, targetCount: Int = 7, color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.targetCount = targetCount
        self.color = color
        self.completionDates = []
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var completionCount: Int {
        completionDates.count
    }

    var progress: Double {
        Double(completionCount) / Double(targetCount)
    }

    mutating func toggleCompletion(for date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }
}
