    private let calendar = Calendar.current
    private let daysOfWeek = ["S", "M", "T", "W", "T", "F", "S"]

    var body: some View {
        VStack {
            // Weekday headers
            HStack {
                ForEach(daysOfWeek, id: \.self) { day in
                    Text(day)
                        .frame(maxWidth: .infinity)
                        .font(.caption)
                }
            }

            // Calendar grid
            LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 7)) {
                ForEach(0..<42, id: \.self) { index in
                    let date = calendar.date(byAdding: .day, value: index - 15, to: currentDate)!
                    let isCompleted = habit.completionDates.contains { calendar.isDate($0, inSameDayAs: date) }
                    let isCurrentMonth = calendar.isDate(date, equalTo: currentDate, toGranularity: .month)

                    Button(action: {
                        habit.toggleCompletion(for: date)
                    }) {
                        Circle()
                            .fill(isCompleted ? Color(habit.color) : Color.clear)
                            .overlay(
                                Text("\(calendar.component(.day, from: date))")
                                    .foregroundColor(isCurrentMonth ? .primary : .secondary)
                            )
                            .frame(width: 30, height: 30)
                    }
                    .disabled(!isCurrentMonth)
                }
            }
        }
    }
}
