                            description: description,
                            frequency: frequency,
                            targetCount: targetCount,
                            color: color
                        )
                        store.addHabit(newHabit)
                    }
                    dismiss()
                }
                .disabled(name.isEmpty)
            }
        }
        .navigationTitle(habit == nil ? "Add Habit" : "Edit Habit")
