            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Drink 8 glasses of water daily", frequency: .daily, targetCount: 8),
            Habit(name: "Exercise", description: "Workout for 30 minutes", frequency: .daily, targetCount: 1),
            Habit(name: "Read", description: "Read for 20 minutes", frequency: .daily, targetCount: 1)
