```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var streak: Int
    var lastCompleted: Date?
    var completionDates: [Date]

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, streak: Int = 0, lastCompleted: Date? = nil, completionDates: [Date] = []) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.streak = streak
        self.lastCompleted = lastCompleted
        self.completionDates = completionDates
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    mutating func completeHabit() {
        let today = Date()

        // If last completed was yesterday, increment streak
        if let lastCompleted = lastCompleted, Calendar.current.isDateInYesterday(lastCompleted) {
            streak += 1
        } else if let lastCompleted = lastCompleted, !Calendar.current.isDateInToday(lastCompleted) {
            // If not consecutive, reset streak
            streak = 1
        } else if lastCompleted == nil {
            // First completion
            streak = 1
        }

        lastCompleted = today
        completionDates.append(today)
    }
}
```

### HabitStore.swift
```swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func completeHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].completeHabit()
            saveHabits()
        }
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Drink 8 glasses of water daily", frequency: .daily),
            Habit(name: "Read", description: "Read for 30 minutes", frequency: .daily),
            Habit(name: "Exercise", description: "Workout for 30 minutes", frequency: .daily)
        ]
    }
}
