```swift
// Models/Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetPerWeek: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily, targetPerWeek: Int = 1, color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetPerWeek = targetPerWeek
        self.color = color
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
    }

    var isCompletedToday: Bool {
        completionDates.contains { Calendar.current.isDateInToday($0) }
    }

    var weeklyCompletionCount: Int {
        let calendar = Calendar.current
        let startOfWeek = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: Date()))!
        let endOfWeek = calendar.date(byAdding: .day, value: 6, to: startOfWeek)!

        return completionDates.filter { $0 >= startOfWeek && $0 <= endOfWeek }.count
    }
}
```

