```swift
// Models/Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var streak: Int
    var isCompletedToday: Bool

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency = .daily) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.streak = 0
        self.isCompletedToday = false
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let targetDate = calendar.startOfDay(for: date)

        if targetDate == today {
            isCompletedToday.toggle()

            if isCompletedToday {
                // Mark as completed today
                if !completionDates.contains(where: { calendar.isDate($0, inSameDayAs: today) }) {
                    completionDates.append(today)
                }

                // Update streak
                let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!
                if completionDates.contains(where: { calendar.isDate($0, inSameDayAs: yesterday) }) {
                    streak += 1
                } else {
                    streak = 1
                }
            } else {
                // Remove today's completion
                completionDates.removeAll { calendar.isDate($0, inSameDayAs: today) }

                // Reset streak if needed
                if streak > 0 {
                    streak = 0
                }
            }
        } else {
            // For past dates, just toggle the completion status
            if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: targetDate) }) {
                completionDates.remove(at: index)
            } else {
                completionDates.append(targetDate)
            }
        }
    }

    func isCompleted(on date: Date) -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }
}
