struct CalendarView: View {
    @Binding var habit: Habit
    var onDateTapped: (Date) -> Void

    let calendar = Calendar.current
    let daysOfWeek = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]

    var body: some View {
        VStack {
            // Weekday headers
            HStack {
                ForEach(daysOfWeek, id: \.self) { day in
                    Text(day)
                        .frame(maxWidth: .infinity)
                        .font(.caption)
                }
            }

            // Calendar grid
            let month = calendar.component(.month, from: Date())
            let year = calendar.component(.year, from: Date())
            let daysInMonth = calendar.range(of: .day, in: .month, for: Date())?.count ?? 30

            LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 7)) {
                // Add empty cells for days before the 1st of the month
                ForEach(0..<firstWeekdayOfMonth(month: month, year: year), id: \.self) { _ in
                    Color.clear
                        .frame(height: 30)
                }

                // Days of the month
                ForEach(1...daysInMonth, id: \.self) { day in
                    let date = calendar.date(from: DateComponents(year: year, month: month, day: day)) ?? Date()
                    let isCompleted = habit.isCompleted(on: date)

                    Button(action: {
                        onDateTapped(date)
                    }) {
                        Text("\(day)")
                            .frame(width: 30, height: 30)
                            .background(isCompleted ? Color.green.opacity(0.3) : Color.clear)
                            .clipShape(Circle())
                    }
                }
            }
        }
        .padding()
    }

    private func firstWeekdayOfMonth(month: Int, year: Int) -> Int {
        let components = DateComponents(year: year, month: month, day: 1)
        let firstDayOfMonth = calendar.date(from: components) ?? Date()
        return calendar.component(.weekday, from: firstDayOfMonth) - 1
    }
}
