```swift
// Models/Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var streak: Int
    var createdAt: Date

    enum Frequency: String, Codable, CaseIterable {
        case daily, weekly, monthly
    }

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, completionDates: [Date] = [], streak: Int = 0, createdAt: Date = Date()) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = completionDates
        self.streak = streak
        self.createdAt = createdAt
    }

    mutating func toggleCompletion(for date: Date) {
        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
            streak = 0
        } else {
            completionDates.append(date)
            updateStreak()
        }
    }

    private mutating func updateStreak() {
        guard let lastCompletion = completionDates.sorted().last else { return }

        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!

        if calendar.isDate(lastCompletion, inSameDayAs: yesterday) {
            streak += 1
        } else if !calendar.isDate(lastCompletion, inSameDayAs: today) {
            streak = 1
        }
    }
}
