```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var streak: Int
    var lastCompleted: Date?
    var isCompletedToday: Bool

    enum Frequency: String, Codable, CaseIterable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    init(id: UUID = UUID(), name: String, description: String, frequency: Frequency) {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.streak = 0
        self.lastCompleted = nil
        self.isCompletedToday = false
    }

    mutating func complete() {
        let calendar = Calendar.current
        let now = Date()

        if let lastCompleted = lastCompleted {
            let daysSinceLast = calendar.dateComponents([.day], from: lastCompleted, to: now).day ?? 0

            if daysSinceLast == 1 {
                streak += 1
            } else if daysSinceLast > 1 {
                streak = 1
            }
        } else {
            streak = 1
        }

        lastCompleted = now
        isCompletedToday = true
    }

    mutating func resetDailyStatus() {
        isCompletedToday = false
    }
}
```

### HabitStore.swift
```swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(_ habit: Habit) {
        habits.append(habit)
        saveHabits()
    }

    func updateHabit(_ habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = habit
            saveHabits()
        }
    }

    func deleteHabit(_ habit: Habit) {
        habits.removeAll { $0.id == habit.id }
        saveHabits()
    }

    func completeHabit(_ habit: Habit) {
        if var updatedHabit = habits.first(where: { $0.id == habit.id }) {
            updatedHabit.complete()
            updateHabit(updatedHabit)
        }
    }

    func resetDailyStatus() {
        for index in habits.indices {
            habits[index].resetDailyStatus()
        }
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none exist
        habits = [
            Habit(name: "Drink Water", description: "Drink 8 glasses of water daily", frequency: .daily),
            Habit(name: "Exercise", description: "30 minutes of exercise", frequency: .daily),
            Habit(name: "Read", description: "Read for 20 minutes", frequency: .daily)
        ]
    }
}
