### Habit.swift
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetCount: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, targetCount: Int = 7, color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetCount = targetCount
        self.color = color
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var progress: Double {
        let calendar = Calendar.current
        let now = Date()

        switch frequency {
        case .daily:
            let startOfDay = calendar.startOfDay(for: now)
            let completedToday = completionDates.contains { calendar.isDate($0, inSameDayAs: startOfDay) }
            return completedToday ? 1.0 : 0.0
        case .weekly:
            let startOfWeek = calendar.date(from: calendar.dateComponents([.yearForWeekOfYear, .weekOfYear], from: now))!
            let endOfWeek = calendar.date(byAdding: .day, value: 6, to: startOfWeek)!
            let completedThisWeek = completionDates.filter { $0 >= startOfWeek && $0 <= endOfWeek }.count
            return Double(completedThisWeek) / Double(targetCount)
        case .monthly:
            let startOfMonth = calendar.date(from: calendar.dateComponents([.year, .month], from: now))!
            let endOfMonth = calendar.date(byAdding: .month, value: 1, to: startOfMonth)!
            let completedThisMonth = completionDates.filter { $0 >= startOfMonth && $0 <= endOfMonth }.count
            return Double(completedThisMonth) / Double(targetCount)
        }
    }

    var isCompleted: Bool {
        progress >= 1.0
    }
}
