```swift
import SwiftUI
import Charts

struct ProgressView: View {
    @ObservedObject var habitStore: HabitStore

    var body: some View {
        NavigationView {
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    // Overall progress
                    Section(header: Text("Overall Progress").font(.headline)) {
                        ProgressView(value: overallProgress)
                            .progressViewStyle(LinearProgressViewStyle(tint: .blue))
                            .padding(.vertical)

                        Text("\(Int(overallProgress * 100))% of habits completed")
                            .font(.subheadline)
                            .foregroundColor(.gray)
                    }
                    .padding()

                    // Weekly chart
                    Section(header: Text("Weekly Progress").font(.headline)) {
                        if #available(iOS 16.0, *) {
                            Chart {
                                ForEach(habitStore.habits) { habit in
                                    BarMark(
                                        x: .value("Day", habit.name),
                                        y: .value("Progress", habit.progress * 100)
                                    )
                                    .foregroundStyle(by: .value("Habit", habit.name))
                                }
                            }
                            .frame(height: 300)
                            .padding()
                        } else {
                            // Fallback for iOS versions before 16.0
                            Text("Chart requires iOS 16 or later")
                                .foregroundColor(.gray)
                        }
                    }

                    // Streak information
                    Section(header: Text("Streaks").font(.headline)) {
                        ForEach(habitStore.habits) { habit in
                            HStack {
                                Text(habit.name)
                                Spacer()
                                Text("\(currentStreak(for: habit)) day streak")
                                    .foregroundColor(.gray)
                            }
                        }
                    }
                    .padding()
                }
            }
            .navigationTitle("Progress")
        }
    }

    private var overallProgress: Double {
        guard !habitStore.habits.isEmpty else { return 0 }
        let completedCount = habitStore.habits.filter { $0.isCompleted }.count
        return Double(completedCount) / Double(habitStore.habits.count)
    }

    private func currentStreak(for habit: Habit) -> Int {
        let sortedDates = habit.completionDates.sorted(by: >)
        var streak = 0
        var currentDate = Calendar.current.startOfDay(for: Date())

        for date in sortedDates {
            let dateStart = Calendar.current.startOfDay(for: date)
            if dateStart == currentDate {
                streak += 1
                currentDate = Calendar.current.date(byAdding: .day, value: -1, to: currentDate)!
            } else {
                break
            }
        }

        return streak
    }
}
