import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var frequency: Frequency
    var completionDates: [Date]
    var targetCount: Int
    var color: String

    init(id: UUID = UUID(), name: String, description: String = "", frequency: Frequency, targetCount: Int = 7, color: String = "blue") {
        self.id = id
        self.name = name
        self.description = description
        self.frequency = frequency
        self.completionDates = []
        self.targetCount = targetCount
        self.color = color
    }

    enum Frequency: String, CaseIterable, Codable {
        case daily = "Daily"
        case weekly = "Weekly"
        case monthly = "Monthly"
    }

    var progress: Double {
        let completed = completionDates.count
        return Double(completed) / Double(targetCount)
    }

    var isCompletedToday: Bool {
        guard let lastCompletion = completionDates.last else { return false }
        return Calendar.current.isDateInToday(lastCompletion)
    }

    mutating func toggleCompletion() {
        if isCompletedToday {
            completionDates.removeAll { Calendar.current.isDateInToday($0) }
        } else {
            completionDates.append(Date())
        }
    }
}
