# Minimal iOS Habit Tracking App

Here's a simple habit tracking app for iOS using SwiftUI. This implementation includes core functionality for tracking habits with minimal code.

## App Structure

1. **Habit Model**: Represents a habit with name, completion status, and streak
2. **View Models**: Manages habit data
3. **Views**: Displays habits and allows tracking

## Implementation

### 1. Habit Model

```swift
// Habit.swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var isCompletedToday: Bool
    var streak: Int
    var lastCompletedDate: Date?

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.isCompletedToday = false
        self.streak = 0
        self.lastCompletedDate = nil
    }
}
```

### 2. Habit Store (View Model)

```swift
// HabitStore.swift
import Foundation

class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
        saveHabits()
    }

    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]

            // Check if we're completing today for the first time
            let calendar = Calendar.current
            let today = calendar.startOfDay(for: Date())

            if !updatedHabit.isCompletedToday {
                // First completion today - check if we should increment streak
                if let lastDate = updatedHabit.lastCompletedDate {
                    let lastDay = calendar.startOfDay(for: lastDate)
                    let dayBeforeToday = calendar.date(byAdding: .day, value: -1, to: today)!

                    if lastDay == dayBeforeToday {
                        // Consecutive day - increment streak
                        updatedHabit.streak += 1
                    } else if lastDay != today {
                        // Not consecutive - reset streak
                        updatedHabit.streak = 1
                    }
                } else {
                    // First time ever - start streak
                    updatedHabit.streak = 1
                }

                updatedHabit.isCompletedToday = true
                updatedHabit.lastCompletedDate = Date()
            } else {
                // Undo completion - decrement streak if appropriate
                if updatedHabit.streak > 0 {
                    updatedHabit.streak -= 1
                }
                updatedHabit.isCompletedToday = false
                updatedHabit.lastCompletedDate = nil
            }

            habits[index] = updatedHabit
            saveHabits()
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                resetDailyCompletionStatus()
            }
        }
    }

    private func resetDailyCompletionStatus() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        for i in 0..<habits.count {
            if let lastDate = habits[i].lastCompletedDate {
                let lastDay = calendar.startOfDay(for: lastDate)
                if lastDay != today {
                    habits[i].isCompletedToday = false
                }
            }
        }
    }
}
```

