2. Replace the default ContentView with the following code

## Code Implementation

```swift
import SwiftUI

// MARK: - Data Models
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var description: String
    var streak: Int
    var lastCompleted: Date?
    var isCompletedToday: Bool

    init(name: String, description: String = "") {
        self.id = UUID()
        self.name = name
        self.description = description
        self.streak = 0
        self.lastCompleted = nil
        self.isCompletedToday = false
    }
}

// MARK: - View Models
class HabitStore: ObservableObject {
    @Published var habits: [Habit] = []

    private let saveKey = "Habits"

    init() {
        loadHabits()
    }

    func addHabit(name: String, description: String = "") {
        let newHabit = Habit(name: name, description: description)
        habits.append(newHabit)
        saveHabits()
    }

    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            var updatedHabit = habits[index]

            if updatedHabit.isCompletedToday {
                // Undo completion
                updatedHabit.isCompletedToday = false
                updatedHabit.streak -= 1
            } else {
                // Mark as completed
                updatedHabit.isCompletedToday = true

                // Check if it's consecutive day
                if let lastCompleted = updatedHabit.lastCompleted {
                    let calendar = Calendar.current
                    if calendar.isDateInYesterday(lastCompleted) {
                        updatedHabit.streak += 1
                    } else if !calendar.isDateInToday(lastCompleted) {
                        updatedHabit.streak = 1
                    }
                } else {
                    updatedHabit.streak = 1
                }

                updatedHabit.lastCompleted = Date()
            }

            habits[index] = updatedHabit
            saveHabits()
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        saveHabits()
    }

    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: saveKey)
        }
    }

    private func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: saveKey) {
            if let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
                habits = decoded
                return
            }
        }

        // Default habits if none saved
        habits = [
            Habit(name: "Drink water", description: "At least 8 glasses a day"),
            Habit(name: "Exercise", description: "30 minutes of physical activity"),
            Habit(name: "Read", description: "Read for 20 minutes")
        ]
    }
}

// MARK: - Views
