import SwiftUI

// Habit model
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completionDates: [Date]
    var streak: Int

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.completionDates = []
        self.streak = 0
    }

    // Check if habit was completed today
    var isCompletedToday: Bool {
        guard let lastCompletion = completionDates.last else { return false }
        return Calendar.current.isDateInToday(lastCompletion)
    }

    // Calculate current streak
    mutating func updateStreak() {
        guard let lastCompletion = completionDates.last else {
            streak = 0
            return
        }

        let calendar = Calendar.current
        let today = Date()
        let yesterday = calendar.date(byAdding: .day, value: -1, to: today)!

        if calendar.isDateInToday(lastCompletion) {
            // Already completed today
            return
        } else if calendar.isDate(lastCompletion, inSameDayAs: yesterday) {
            // Completed yesterday - increment streak
            streak += 1
        } else {
            // Not consecutive - reset streak
            streak = 1
        }

        completionDates.append(today)
    }
}

// ViewModel
class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    // Add a new habit
    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
        saveHabits()
    }

    // Toggle habit completion
    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index].updateStreak()
            saveHabits()
        }
    }

    // Save habits to UserDefaults
    private func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    // Load habits from UserDefaults
    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits"),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }
}

