        DispatchQueue.global(qos: .background).async { [weak self] in
            do {
                let fileURL = try Self.fileURL()
                guard let data = try? Data(contentsOf: fileURL) else {
                    DispatchQueue.main.async {
                        self?.habits = []
                    }
                    return
                }
                let habits = try JSONDecoder().decode([Habit].self, from: data)
                DispatchQueue.main.async {
                    self?.habits = habits
                }
            } catch {
                DispatchQueue.main.async {
                    self?.habits = []
                }
            }
        }
    }

    func save() {
        DispatchQueue.global(qos: .background).async { [weak self] in
            guard let habits = self?.habits else { return }
            do {
                let data = try JSONEncoder().encode(habits)
                let outfile = try Self.fileURL()
                try data.write(to: outfile)
            } catch {
                print(error)
            }
        }
    }

    func addHabit(name: String) {
        let newHabit = Habit(name: name)
        habits.append(newHabit)
        save()
    }

    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            if let lastDate = habit.completionDates.last,
               Calendar.current.isDateInToday(lastDate) {
                // Remove today's completion if it exists
                habits[index].completionDates.removeLast()
            } else {
                // Add today's completion
                habits[index].completionDates.append(Date())
            }
            save()
        }
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        save()
    }
}

