struct HabitRow: View {
    let habit: Habit
    let onToggle: () -> Void

    var body: some View {
        HStack {
            VStack(alignment: .leading) {
                Text(habit.name)
                    .font(.headline)
                Text("Streak: \(calculateStreak()) days")
                    .font(.subheadline)
                    .foregroundColor(.secondary)
            }

            Spacer()

            Button(action: onToggle) {
                Image(systemName: isCompletedToday() ? "checkmark.circle.fill" : "circle")
                    .foregroundColor(isCompletedToday() ? .green : .gray)
            }
        }
    }

    private func isCompletedToday() -> Bool {
        guard let lastDate = habit.completionDates.last else { return false }
        return Calendar.current.isDateInToday(lastDate)
    }

    private func calculateStreak() -> Int {
        guard !habit.completionDates.isEmpty else { return 0 }

        let sortedDates = habit.completionDates.sorted(by: >)
        var streak = 1
        var previousDate = sortedDates[0]

        for date in sortedDates.dropFirst() {
            let daysBetween = Calendar.current.dateComponents([.day], from: date, to: previousDate).day ?? 0
            if daysBetween == 1 {
                streak += 1
                previousDate = date
            } else {
                break
            }
        }

        return streak
    }
}

