```swift
import SwiftUI

// Habit Model
struct Habit: Identifiable, Codable {
    let id = UUID()
    var name: String
    var completionDates: [Date]
}

// ViewModel
class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    init() {
        loadHabits()
    }

    func addHabit(name: String) {
        let newHabit = Habit(name: name, completionDates: [])
        habits.append(newHabit)
        saveHabits()
    }

    func toggleHabitCompletion(habit: Habit) {
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            let today = Calendar.current.startOfDay(for: Date())

            if habits[index].completionDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
                // Remove today's completion if it exists
                habits[index].completionDates.removeAll { Calendar.current.isDate($0, inSameDayAs: today) }
            } else {
                // Add today's completion
                habits[index].completionDates.append(Date())
            }

            saveHabits()
        }
    }

    func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits"),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }
}

// Main View
struct ContentView: View {
    @StateObject private var viewModel = HabitViewModel()
    @State private var newHabitName = ""

    var body: some View {
        NavigationStack {
            VStack {
                // Add new habit section
                HStack {
                    TextField("New habit", text: $newHabitName)
                        .textFieldStyle(.roundedBorder)

                    Button(action: {
                        if !newHabitName.isEmpty {
                            viewModel.addHabit(name: newHabitName)
                            newHabitName = ""
                        }
                    }) {
                        Image(systemName: "plus.circle.fill")
                            .font(.title)
                    }
                }
                .padding()

                // Habit list
                List {
                    ForEach(viewModel.habits) { habit in
                        HabitRow(habit: habit, viewModel: viewModel)
                    }
                    .onDelete { indices in
                        viewModel.habits.remove(atOffsets: indices)
                        viewModel.saveHabits()
                    }
                }
                .listStyle(.plain)
            }
            .navigationTitle("Habit Tracker")
        }
    }
}

// Habit Row View
struct HabitRow: View {
    let habit: Habit
    @ObservedObject var viewModel: HabitViewModel

    var body: some View {
        HStack {
            Button(action: {
                viewModel.toggleHabitCompletion(habit: habit)
            }) {
                Image(systemName: isCompletedToday() ? "checkmark.circle.fill" : "circle")
                    .foregroundColor(isCompletedToday() ? .green : .gray)
            }

            Text(habit.name)
                .strikethrough(isCompletedToday())

            Spacer()

            Text("\(habit.completionDates.count) days")
                .font(.caption)
                .foregroundColor(.secondary)
        }
    }

    private func isCompletedToday() -> Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return habit.completionDates.contains { Calendar.current.isDate($0, inSameDayAs: today) }
    }
}

