class BankingRepository(private val apiService: BankingApiService) {

    suspend fun login(username: String, password: String): Result<User> {
        return try {
            val response = apiService.login(username, password)
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Login failed"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(accountNumber: String): Result<List<Transaction>> {
        return try {
            val response = apiService.getTransactions(accountNumber)
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Failed to fetch transactions"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun transferFunds(
        fromAccount: String,
        toAccount: String,
        amount: Double,
        description: String
    ): Result<Boolean> {
        return try {
            val response = apiService.transferFunds(
                TransferRequest(fromAccount, toAccount, amount, description)
            )
            Result.success(response.isSuccessful)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
