### 2. Authentication Flow

```kotlin
// ui/auth/LoginActivity.kt
class LoginActivity : AppCompatActivity() {
    private lateinit var binding: ActivityLoginBinding
    private lateinit var authViewModel: AuthViewModel

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityLoginBinding.inflate(layoutInflater)
        setContentView(binding.root)

        authViewModel = ViewModelProvider(this).get(AuthViewModel::class.java)

        binding.loginButton.setOnClickListener {
            val email = binding.emailEditText.text.toString()
            val password = binding.passwordEditText.text.toString()

            authViewModel.login(email, password).observe(this, { result ->
                when (result) {
                    is Result.Success -> {
                        // Navigate to dashboard
                        startActivity(Intent(this, DashboardActivity::class.java))
                        finish()
                    }
                    is Result.Error -> {
                        Toast.makeText(this, result.exception.message, Toast.LENGTH_SHORT).show()
                    }
                }
            })
        }
    }
}
```

### 3. Dashboard Activity

```kotlin
// ui/dashboard/DashboardActivity.kt
class DashboardActivity : AppCompatActivity() {
    private lateinit var binding: ActivityDashboardBinding
    private lateinit var dashboardViewModel: DashboardViewModel

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityDashboardBinding.inflate(layoutInflater)
        setContentView(binding.root)

        dashboardViewModel = ViewModelProvider(this).get(DashboardViewModel::class.java)

        setupViews()
        observeData()
    }

    private fun setupViews() {
        // Setup RecyclerView for accounts
        val accountsAdapter = AccountsAdapter()
        binding.accountsRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@DashboardActivity)
            adapter = accountsAdapter
        }

        // Setup RecyclerView for recent transactions
        val transactionsAdapter = TransactionsAdapter()
        binding.transactionsRecyclerView.apply {
            layoutManager = LinearLayoutManager(this@DashboardActivity)
            adapter = transactionsAdapter
        }

        // Setup click listeners
        binding.transferButton.setOnClickListener {
            startActivity(Intent(this, TransferActivity::class.java))
        }
    }

    private fun observeData() {
        dashboardViewModel.accounts.observe(this, { accounts ->
            (binding.accountsRecyclerView.adapter as AccountsAdapter).submitList(accounts)
        })

        dashboardViewModel.recentTransactions.observe(this, { transactions ->
            (binding.transactionsRecyclerView.adapter as TransactionsAdapter).submitList(transactions)
        })
    }
}
```

