### 5. Repository Pattern

```kotlin
// data/repository/BankingRepository.kt
class BankingRepository(
    private val remoteDataSource: RemoteDataSource,
    private val localDataSource: LocalDataSource
) {
    suspend fun login(email: String, password: String): Result<User> {
        return try {
            val user = remoteDataSource.login(email, password)
            localDataSource.saveUser(user)
            Result.Success(user)
        } catch (e: Exception) {
            Result.Error(e)
        }
    }

    suspend fun getAccounts(userId: String): Result<List<Account>> {
        return try {
            val accounts = remoteDataSource.getAccounts(userId)
            localDataSource.saveAccounts(accounts)
            Result.Success(accounts)
        } catch (e: Exception) {
            // Fallback to local data if network fails
            val localAccounts = localDataSource.getAccounts(userId)
            if (localAccounts.isNotEmpty()) {
                Result.Success(localAccounts)
            } else {
                Result.Error(e)
            }
        }
    }

    suspend fun transferFunds(
        amount: Double,
        recipientAccount: String,
        description: String
    ): Result<Transaction> {
        return try {
            val transaction = remoteDataSource.transferFunds(amount, recipientAccount, description)
            localDataSource.saveTransaction(transaction)
            Result.Success(transaction)
        } catch (e: Exception) {
            Result.Error(e)
        }
    }
}
```

