@Module
@InstallIn(SingletonComponent::class)
object AppModule {
    @Provides
    @Singleton
    fun provideRemoteDataSource(): RemoteDataSource {
        return RetrofitRemoteDataSource()
    }

    @Provides
    @Singleton
    fun provideLocalDataSource(app: Application): LocalDataSource {
        return RoomLocalDataSource(app)
    }

    @Provides
    @Singleton
    fun provideBankingRepository(
        remoteDataSource: RemoteDataSource,
        localDataSource: LocalDataSource
    ): BankingRepository {
        return BankingRepository(remoteDataSource, localDataSource)
    }
}
