### 4. Repository Pattern

```kotlin
// BankRepository.kt
interface BankRepository {
    suspend fun getUserAccount(): User
    suspend fun getTransactions(): List<Transaction>
    suspend fun transferFunds(amount: Double, recipientAccount: String): Boolean
    suspend fun depositFunds(amount: Double): Boolean
    suspend fun withdrawFunds(amount: Double): Boolean
}

// Mock implementation for demo purposes
class MockBankRepository : BankRepository {
    private val user = User(
        id = "1",
        name = "John Doe",
        email = "john.doe@example.com",
        accountNumber = "1234567890",
        balance = 5000.00
    )

    private val transactions = mutableListOf(
        Transaction(
            id = "1",
            date = "2023-01-15",
            amount = 1000.00,
            type = "DEPOSIT",
            description = "Salary deposit",
            balanceAfter = 5000.00
        ),
        Transaction(
            id = "2",
            date = "2023-01-20",
            amount = 50.00,
            type = "WITHDRAWAL",
            description = "Grocery shopping",
            balanceAfter = 4950.00
        )
    )

    override suspend fun getUserAccount(): User = user

    override suspend fun getTransactions(): List<Transaction> = transactions

    override suspend fun transferFunds(amount: Double, recipientAccount: String): Boolean {
        if (user.balance >= amount) {
            user.balance -= amount
            transactions.add(
                Transaction(
                    id = (transactions.size + 1).toString(),
                    date = java.time.LocalDate.now().toString(),
                    amount = amount,
                    type = "WITHDRAWAL",
                    description = "Transfer to $recipientAccount",
                    balanceAfter = user.balance
                )
            )
            return true
        }
        return false
    }

    override suspend fun depositFunds(amount: Double): Boolean {
        user.balance += amount
        transactions.add(
            Transaction(
                id = (transactions.size + 1).toString(),
                date = java.time.LocalDate.now().toString(),
                amount = amount,
                type = "DEPOSIT",
                description = "Deposit",
                balanceAfter = user.balance
            )
        )
        return true
    }

    override suspend fun withdrawFunds(amount: Double): Boolean {
        if (user.balance >= amount) {
            user.balance -= amount
            transactions.add(
                Transaction(
                    id = (transactions.size + 1).toString(),
                    date = java.time.LocalDate.now().toString(),
                    amount = amount,
                    type = "WITHDRAWAL",
                    description = "Withdrawal",
                    balanceAfter = user.balance
                )
            )
            return true
        }
        return false
    }
}
