### 5. ViewModel

```kotlin
// BankViewModel.kt
class BankViewModel(private val repository: BankRepository) : ViewModel() {
    private val _user = MutableLiveData<User>()
    val user: LiveData<User> = _user

    private val _transactions = MutableLiveData<List<Transaction>>()
    val transactions: LiveData<List<Transaction>> = _transactions

    private val _transferResult = MutableLiveData<Boolean>()
    val transferResult: LiveData<Boolean> = _transferResult

    private val _error = MutableLiveData<String>()
    val error: LiveData<String> = _error

    fun loadUserData() {
        viewModelScope.launch {
            try {
                _user.value = repository.getUserAccount()
            } catch (e: Exception) {
                _error.value = "Failed to load user data"
            }
        }
    }

    fun loadTransactions() {
        viewModelScope.launch {
            try {
                _transactions.value = repository.getTransactions()
            } catch (e: Exception) {
                _error.value = "Failed to load transactions"
            }
        }
    }

    fun transferFunds(amount: Double, recipientAccount: String) {
        viewModelScope.launch {
            try {
                _transferResult.value = repository.transferFunds(amount, recipientAccount)
                if (_transferResult.value == true) {
                    loadUserData()
                    loadTransactions()
                }
            } catch (e: Exception) {
                _error.value = "Transfer failed"
            }
        }
    }

    fun depositFunds(amount: Double) {
        viewModelScope.launch {
            try {
                val success = repository.depositFunds(amount)
                if (success) {
                    loadUserData()
                    loadTransactions()
                }
            } catch (e: Exception) {
                _error.value = "Deposit failed"
            }
        }
    }

    fun withdrawFunds(amount: Double) {
        viewModelScope.launch {
            try {
                val success = repository.withdrawFunds(amount)
                if (success) {
                    loadUserData()
                    loadTransactions()
                }
            } catch (e: Exception) {
                _error.value = "Withdrawal failed"
            }
        }
    }
}
