class HomeFragment : Fragment() {
    private var _binding: FragmentHomeBinding? = null
    private val binding get() = _binding!!
    private lateinit var viewModel: BankViewModel

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentHomeBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        viewModel = ViewModelProvider(requireActivity()).get(BankViewModel::class.java)

        setupObservers()
        setupButtons()
    }

    private fun setupObservers() {
        viewModel.user.observe(viewLifecycleOwner) { user ->
            user?.let {
                binding.tvAccountName.text = user.name
                binding.tvAccountNumber.text = "Account: ${user.accountNumber}"
                binding.tvBalance.text = "Balance: $${"%.2f".format(user.balance)}"
            }
        }
    }

    private fun setupButtons() {
        binding.btnDeposit.setOnClickListener {
            showAmountDialog("Deposit") { amount ->
                viewModel.depositFunds(amount)
            }
        }

        binding.btnWithdraw.setOnClickListener {
            showAmountDialog("Withdraw") { amount ->
                viewModel.withdrawFunds(amount)
            }
        }
    }

    private fun showAmountDialog(title: String, onAmountEntered: (Double) -> Unit) {
        val dialogView = LayoutInflater.from(requireContext()).inflate(R.layout.dialog_amount_input, null)
        val etAmount = dialogView.findViewById<EditText>(R.id.etAmount)

        AlertDialog.Builder(requireContext())
            .setTitle(title)
            .setView(dialogView)
            .setPositiveButton("Submit") { _, _ ->
                val amount = etAmount.text.toString().toDoubleOrNull()
                if (amount != null && amount > 0) {
                    onAmountEntered(amount)
                } else {
                    Toast.makeText(requireContext(), "Please enter a valid amount", Toast.LENGTH_SHORT).show()
                }
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
