class TransferFragment : Fragment() {
    private var _binding: FragmentTransferBinding? = null
    private val binding get() = _binding!!
    private lateinit var viewModel: BankViewModel

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentTransferBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        viewModel = ViewModelProvider(requireActivity()).get(BankViewModel::class.java)

        setupObservers()
        setupButton()
    }

    private fun setupObservers() {
        viewModel.transferResult.observe(viewLifecycleOwner) { success ->
            success?.let {
                if (it) {
                    Toast.makeText(requireContext(), "Transfer successful", Toast.LENGTH_SHORT).show()
                    binding.etRecipientAccount.text.clear()
                    binding.etAmount.text.clear()
                } else {
                    Toast.makeText(requireContext(), "Transfer failed", Toast.LENGTH_SHORT).show()
                }
            }
        }
    }

    private fun setupButton() {
        binding.btnTransfer.setOnClickListener {
            val recipientAccount = binding.etRecipientAccount.text.toString()
            val amount = binding.etAmount.text.toString().toDoubleOrNull()

            if (recipientAccount.isNotEmpty() && amount != null && amount > 0) {
                viewModel.transferFunds(amount, recipientAccount)
            } else {
                Toast.makeText(requireContext(), "Please enter valid details", Toast.LENGTH_SHORT).show()
            }
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
