### 5. Transaction Fragment

```kotlin
// app/src/main/java/com/example/bankingapp/ui/transactions/TransactionsFragment.kt
class TransactionsFragment : Fragment() {
    private lateinit var binding: FragmentTransactionsBinding
    private lateinit var viewModel: TransactionsViewModel
    private lateinit var adapter: TransactionsAdapter

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        binding = FragmentTransactionsBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        viewModel = ViewModelProvider(this)[TransactionsViewModel::class.java]
        setupRecyclerView()
        setupObservers()
        loadTransactions()
    }

    private fun setupRecyclerView() {
        adapter = TransactionsAdapter()
        binding.rvTransactions.layoutManager = LinearLayoutManager(requireContext())
        binding.rvTransactions.adapter = adapter
    }

    private fun setupObservers() {
        viewModel.transactions.observe(viewLifecycleOwner) { result ->
            when (result) {
                is Result.Success -> {
                    adapter.submitList(result.data)
                    binding.progressBar.visibility = View.GONE
                }
                is Result.Error -> {
                    Toast.makeText(requireContext(), result.exception.message, Toast.LENGTH_SHORT).show()
                    binding.progressBar.visibility = View.GONE
                }
            }
        }
    }

    private fun loadTransactions() {
        binding.progressBar.visibility = View.VISIBLE
        viewModel.loadTransactions()
    }
}
