```kotlin
// app/src/main/java/com/example/bankingapp/ui/transactions/FundTransferActivity.kt
class FundTransferActivity : AppCompatActivity() {
    private lateinit var binding: ActivityFundTransferBinding
    private lateinit var viewModel: FundTransferViewModel

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityFundTransferBinding.inflate(layoutInflater)
        setContentView(binding.root)

        viewModel = ViewModelProvider(this)[FundTransferViewModel::class.java]

        setupToolbar()
        setupClickListeners()
        setupObservers()
    }

    private fun setupToolbar() {
        setSupportActionBar(binding.toolbar)
        supportActionBar?.setDisplayHomeAsUpEnabled(true)
        supportActionBar?.title = "Fund Transfer"
    }

    private fun setupClickListeners() {
        binding.btnTransfer.setOnClickListener {
            val toAccount = binding.etAccountNumber.text.toString()
            val amount = binding.etAmount.text.toString().toDoubleOrNull() ?: 0.0
            val description = binding.etDescription.text.toString()

            if (validateInputs(toAccount, amount)) {
                viewModel.transferFunds(toAccount, amount, description)
            }
        }
    }

    private fun validateInputs(toAccount: String, amount: Double): Boolean {
        if (toAccount.isBlank()) {
            binding.etAccountNumber.error = "Account number is required"
            return false
        }

        if (amount <= 0) {
            binding.etAmount.error = "Amount must be greater than zero"
            return false
        }

        return true
    }

    private fun setupObservers() {
        viewModel.transferResult.observe(this) { result ->
            when (result) {
                is Result.Success -> {
                    Toast.makeText(this, "Transfer successful", Toast.LENGTH_SHORT).show()
                    finish()
                }
                is Result.Error -> {
                    Toast.makeText(this, result.exception.message, Toast.LENGTH_SHORT).show()
                }
            }
        }
    }
}
