### 6. Fund Transfer

```kotlin
// app/src/main/java/com/example/bankingapp/ui/transactions/TransferFragment.kt
class TransferFragment : Fragment() {
    private var _binding: FragmentTransferBinding? = null
    private val binding get() = _binding!!
    private val viewModel: TransferViewModel by viewModels()

    override fun onCreateView(
        inflater: LayoutInflater,
        container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        _binding = FragmentTransferBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        setupObservers()
        setupListeners()
        viewModel.loadAccounts()
    }

    private fun setupObservers() {
        viewModel.accounts.observe(viewLifecycleOwner) { accounts ->
            val adapter = ArrayAdapter(
                requireContext(),
                android.R.layout.simple_spinner_item,
                accounts.map { "${it.accountNumber} (${it.balance} ${it.currency})" }
            )
            adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
            binding.spFromAccount.adapter = adapter
            binding.spToAccount.adapter = adapter
        }

        viewModel.transferResult.observe(viewLifecycleOwner) { result ->
            result.onSuccess {
                Toast.makeText(requireContext(), "Transfer successful", Toast.LENGTH_SHORT).show()
                findNavController().popBackStack()
            }.onFailure { exception ->
                Toast.makeText(requireContext(), exception.message, Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun setupListeners() {
        binding.btnTransfer.setOnClickListener {
            val fromAccount = viewModel.accounts.value?.get(binding.spFromAccount.selectedItemPosition)
            val toAccount = viewModel.accounts.value?.get(binding.spToAccount.selectedItemPosition)
            val amount = binding.etAmount.text.toString().toDoubleOrNull()
            val description = binding.etDescription.text.toString()

            if (fromAccount != null && toAccount != null && amount != null && amount > 0) {
                viewModel.transferFunds(
                    fromAccount.id,
                    toAccount.id,
                    amount,
                    description
                )
            } else {
                Toast.makeText(requireContext(), "Please fill all fields correctly", Toast.LENGTH_SHORT).show()
            }
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null
    }
}
