### 3.2. API Service

```kotlin
// ApiService.kt
interface ApiService {
    @POST("auth/login")
    suspend fun login(@Body credentials: LoginRequest): Response<User>

    @POST("auth/register")
    suspend fun register(@Body user: RegisterRequest): Response<User>

    @GET("accounts/{accountNumber}")
    suspend fun getAccountDetails(@Path("accountNumber") accountNumber: String): Response<Account>

    @GET("transactions/{accountNumber}")
    suspend fun getTransactions(
        @Path("accountNumber") accountNumber: String,
        @Query("limit") limit: Int = 20
    ): Response<List<Transaction>>

    @POST("transactions/transfer")
    suspend fun transferFunds(@Body transferRequest: TransferRequest): Response<Transaction>
}

data class LoginRequest(val email: String, val password: String)
data class RegisterRequest(val name: String, val email: String, val password: String)
data class TransferRequest(
    val fromAccount: String,
    val toAccount: String,
    val amount: Double,
    val description: String
)
```

### 3.3. Repository

```kotlin
// BankingRepository.kt
class BankingRepository(private val apiService: ApiService) {
    suspend fun login(email: String, password: String): Result<User> {
        return try {
            val response = apiService.login(LoginRequest(email, password))
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Login failed: ${response.message()}"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun register(name: String, email: String, password: String): Result<User> {
        return try {
            val response = apiService.register(RegisterRequest(name, email, password))
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Registration failed: ${response.message()}"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccountDetails(accountNumber: String): Result<Account> {
        return try {
            val response = apiService.getAccountDetails(accountNumber)
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Failed to fetch account details"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(accountNumber: String): Result<List<Transaction>> {
        return try {
            val response = apiService.getTransactions(accountNumber)
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Failed to fetch transactions"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun transferFunds(
        fromAccount: String,
        toAccount: String,
        amount: Double,
        description: String
    ): Result<Transaction> {
        return try {
            val response = apiService.transferFunds(
                TransferRequest(fromAccount, toAccount, amount, description)
            )
            if (response.isSuccessful) {
                Result.success(response.body()!!)
            } else {
                Result.failure(Exception("Transfer failed: ${response.message()}"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}
