### 3.4. ViewModel

```kotlin
// BankingViewModel.kt
class BankingViewModel(private val repository: BankingRepository) : ViewModel() {
    private val _user = MutableLiveData<User?>()
    val user: LiveData<User?> = _user

    private val _account = MutableLiveData<Account?>()
    val account: LiveData<Account?> = _account

    private val _transactions = MutableLiveData<List<Transaction>>()
    val transactions: LiveData<List<Transaction>> = _transactions

    private val _isLoading = MutableLiveData<Boolean>()
    val isLoading: LiveData<Boolean> = _isLoading

    private val _error = MutableLiveData<String?>()
    val error: LiveData<String?> = _error

    fun login(email: String, password: String) {
        viewModelScope.launch {
            _isLoading.value = true
            when (val result = repository.login(email, password)) {
                is Result.Success -> {
                    _user.value = result.data
                    fetchAccountDetails(result.data.accountNumber)
                }
                is Result.Failure -> {
                    _error.value = result.exception.message
                }
            }
            _isLoading.value = false
        }
    }

    private fun fetchAccountDetails(accountNumber: String) {
        viewModelScope.launch {
            _isLoading.value = true
            when (val result = repository.getAccountDetails(accountNumber)) {
                is Result.Success -> {
                    _account.value = result.data
                    fetchTransactions(accountNumber)
                }
                is Result.Failure -> {
                    _error.value = result.exception.message
                }
            }
            _isLoading.value = false
        }
    }

    private fun fetchTransactions(accountNumber: String) {
        viewModelScope.launch {
            _isLoading.value = true
            when (val result = repository.getTransactions(accountNumber)) {
                is Result.Success -> {
                    _transactions.value = result.data
                }
                is Result.Failure -> {
                    _error.value = result.exception.message
                }
            }
            _isLoading.value = false
        }
    }

    fun transferFunds(toAccount: String, amount: Double, description: String) {
        viewModelScope.launch {
            _isLoading.value = true
            val fromAccount = _account.value?.accountNumber ?: return@launch

            when (val result = repository.transferFunds(fromAccount, toAccount, amount, description)) {
                is Result.Success -> {
                    // Refresh data after successful transfer
                    fetchAccountDetails(fromAccount)
                }
                is Result.Failure -> {
                    _error.value = result.exception.message
                }
            }
            _isLoading.value = false
        }
    }

    fun clearError() {
        _error.value = null
    }
}
