### 5.2. Secure Storage

```kotlin
// SecureStorage.kt
object SecureStorage {
    private const val FILENAME = "banking_app_credentials"
    private const val ALIAS = "banking_app_key"

    fun encryptData(context: Context, data: String): ByteArray {
        val masterKey = MasterKey.Builder(context)
            .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
            .build()

        val encryptedInfo = EncryptedFile.Builder(
            context,
            File(context.filesDir, FILENAME),
            masterKey,
            EncryptedFile.FileEncryptionScheme.AES256_GCM_HKDF_4KB
        ).build()

        encryptedInfo.openFileOutput().use { outputStream ->
            outputStream.write(data.toByteArray())
        }

        return encryptedInfo.openFileInput().readBytes()
    }

    fun decryptData(context: Context): String? {
        return try {
            val masterKey = MasterKey.Builder(context)
                .setKeyScheme(MasterKey.KeyScheme.AES256_GCM)
                .build()

            val encryptedFile = EncryptedFile.Builder(
                context,
                File(context.filesDir, FILENAME),
                masterKey,
                EncryptedFile.FileEncryptionScheme.AES256_GCM_HKDF_4KB
            ).build()

            encryptedFile.openFileInput().use { inputStream ->
                String(inputStream.readBytes())
            }
        } catch (e: Exception) {
            null
        }
    }
}
