# Offline-First Field Surveying App with Sync Capability

Below is a comprehensive implementation of an offline-first field surveying app that syncs data when reconnected to the network. This example uses React with TypeScript, but the concepts can be adapted to other frameworks.

## Core Features
- Offline data storage using IndexedDB
- Background sync when connection is restored
- Conflict resolution strategies
- Data validation
- User-friendly UI with offline indicators

## Implementation

### 1. Main App Component (`App.tsx`)

```tsx
import React, { useState, useEffect } from 'react';
import { SurveyForm } from './SurveyForm';
import { SyncStatus } from './SyncStatus';
import { useOfflineStorage } from './hooks/useOfflineStorage';
import { useNetworkStatus } from './hooks/useNetworkStatus';

export const App: React.FC = () => {
  const [surveys, setSurveys] = useState<any[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const { saveSurvey, getAllSurveys, syncWithServer } = useOfflineStorage();
  const { isOnline } = useNetworkStatus();

  useEffect(() => {
    const loadSurveys = async () => {
      const storedSurveys = await getAllSurveys();
      setSurveys(storedSurveys);
    };
    loadSurveys();
  }, [getAllSurveys]);

  const handleSubmit = async (surveyData: any) => {
    const newSurvey = await saveSurvey(surveyData);
    setSurveys(prev => [...prev, newSurvey]);

    if (isOnline) {
      setIsSyncing(true);
      try {
        await syncWithServer();
      } finally {
        setIsSyncing(false);
      }
    }
  };

  return (
    <div className="app">
      <h1>Field Survey App</h1>
      <SyncStatus isOnline={isOnline} isSyncing={isSyncing} />
      <SurveyForm onSubmit={handleSubmit} />
      <div className="survey-list">
        <h2>Saved Surveys</h2>
        {surveys.length === 0 ? (
          <p>No surveys saved yet.</p>
        ) : (
          <ul>
            {surveys.map((survey) => (
              <li key={survey.id}>
                {survey.location} - {new Date(survey.timestamp).toLocaleString()}
                {survey.isSynced ? ' (Synced)' : ' (Pending)'}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};
```

### 2. Survey Form Component (`SurveyForm.tsx`)

```tsx
import React, { useState } from 'react';

interface SurveyFormProps {
  onSubmit: (data: any) => void;
}

export const SurveyForm: React.FC<SurveyFormProps> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    location: '',
    notes: '',
    photos: [] as File[],
    gpsCoordinates: { lat: 0, lng: 0 },
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      setFormData(prev => ({
        ...prev,
        photos: Array.from(e.target.files || [])
      }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Get GPS coordinates (simulated for this example)
    navigator.geolocation.getCurrentPosition(
      (position) => {
        const surveyData = {
          ...formData,
          gpsCoordinates: {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          },
          timestamp: new Date().toISOString(),
          isSynced: false,
        };
        onSubmit(surveyData);
        setFormData({
          location: '',
          notes: '',
          photos: [],
          gpsCoordinates: { lat: 0, lng: 0 },
        });
      },
      (error) => {
        alert(`Could not get GPS coordinates: ${error.message}`);
      }
    );
  };

  return (
    <form onSubmit={handleSubmit} className="survey-form">
      <div className="form-group">
        <label htmlFor="location">Location</label>
        <input
          type="text"
          id="location"
          name="location"
          value={formData.location}
          onChange={handleChange}
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="notes">Notes</label>
        <textarea
          id="notes"
          name="notes"
          value={formData.notes}
          onChange={handleChange}
        />
      </div>

      <div className="form-group">
        <label htmlFor="photos">Photos</label>
        <input
          type="file"
          id="photos"
          name="photos"
          accept="image/*"
          multiple
          onChange={handleFileChange}
        />
      </div>

      <button type="submit" className="submit-btn">
        Save Survey
      </button>
    </form>
  );
};
