### 4. Offline Storage Hook (`useOfflineStorage.ts`)

```ts
import { useCallback } from 'react';
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: {
      id: string;
      location: string;
      notes: string;
      photos: File[];
      gpsCoordinates: { lat: number; lng: number };
      timestamp: string;
      isSynced: boolean;
    };
  };
}

export const useOfflineStorage = () => {
  const dbPromise = useCallback(() => {
    return openDB<SurveyDB>('survey-db', 1, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('surveys')) {
          db.createObjectStore('surveys', { keyPath: 'id' });
        }
      },
    });
  }, []);

  const saveSurvey = useCallback(async (surveyData: any) => {
    const db = await dbPromise();
    const id = Date.now().toString();
    const survey = { ...surveyData, id, isSynced: false };
    await db.put('surveys', survey);
    return survey;
  }, [dbPromise]);

  const getAllSurveys = useCallback(async () => {
    const db = await dbPromise();
    return await db.getAll('surveys');
  }, [dbPromise]);

  const markAsSynced = useCallback(async (id: string) => {
    const db = await dbPromise();
    const survey = await db.get('surveys', id);
    if (survey) {
      await db.put('surveys', { ...survey, isSynced: true });
    }
  }, [dbPromise]);

  const syncWithServer = useCallback(async () => {
    const db = await dbPromise();
    const unsyncedSurveys = (await db.getAll('surveys')).filter(s => !s.isSynced);

