### 2. Offline Data Hook

```typescript
// src/hooks/useOfflineData.ts
import { useState, useEffect } from 'react';
import { openDB, DBSchema } from 'idb';

interface Survey {
  id: string;
  location: string;
  notes: string;
  timestamp: number;
  status: 'pending' | 'synced' | 'conflicted';
  version?: number;
}

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-status': string };
  };
}

export const useOfflineData = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [db, setDb] = useState<IDBPDatabase<SurveyDB> | null>(null);

  useEffect(() => {
    const initDB = async () => {
      const database = await openDB<SurveyDB>('surveyDB', 1, {
        upgrade(db) {
          const store = db.createObjectStore('surveys', {
            keyPath: 'id',
          });
          store.createIndex('by-status', 'status');
        },
      });
      setDb(database);
      await loadSurveys(database);
    };

    initDB();

    return () => {
      if (db) {
        db.close();
      }
    };
  }, []);

  const loadSurveys = async (database: IDBPDatabase<SurveyDB>) => {
    const allSurveys = await database.getAll('surveys');
    setSurveys(allSurveys);
  };

  const addSurvey = async (survey: Omit<Survey, 'id' | 'timestamp' | 'status'>) => {
    if (!db) return;

    const newSurvey: Survey = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      status: 'pending',
      ...survey,
    };

    await db.add('surveys', newSurvey);
    await loadSurveys(db);
  };

  const updateSurvey = async (updatedSurvey: Survey) => {
    if (!db) return;

    // Increment version for conflict resolution
    const existing = await db.get('surveys', updatedSurvey.id);
    if (existing) {
      updatedSurvey.version = (existing.version || 0) + 1;
    }

    await db.put('surveys', updatedSurvey);
    await loadSurveys(db);
  };

  const syncData = async () => {
    if (!db) return;

    const pendingSurveys = await db.getAllFromIndex(
      'surveys',
      'by-status',
      'pending'
    );

    if (pendingSurveys.length === 0) return;

    try {
      // Simulate API call
      const response = await fetch('https://api.example.com/surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(pendingSurveys),
      });

      if (response.ok) {
        // Mark as synced
        const tx = db.transaction('surveys', 'readwrite');
        for (const survey of pendingSurveys) {
          survey.status = 'synced';
          await tx.store.put(survey);
        }
        await tx.done;
        await loadSurveys(db);
      }
    } catch (error) {
      console.error('Sync failed:', error);
      // Handle conflicts if needed
    }
  };

  return { surveys, addSurvey, updateSurvey, syncData };
};
