### 7. Service Worker for Background Sync

```javascript
// public/sw.js
const CACHE_NAME = 'survey-app-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS_TO_CACHE))
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => response || fetch(event.request))
  );
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDB('surveyDB', 1);
  const pendingSurveys = await db.getAllFromIndex(
    'surveys',
    'by-status',
    'pending'
  );

  if (pendingSurveys.length === 0) return;

  try {
    const response = await fetch('https://api.example.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (response.ok) {
      const tx = db.transaction('surveys', 'readwrite');
      for (const survey of pendingSurveys) {
        survey.status = 'synced';
        await tx.store.put(survey);
      }
      await tx.done;
    }
  } catch (error) {
    console.error('Background sync failed:', error);
  }
}
