// syncService.ts
import { Survey, SyncStatus } from './types';
import { surveyService } from './surveyService';

class SyncService {
  private syncInterval: NodeJS.Timeout | null = null;
  private syncStatus: SyncStatus = {
    lastSync: null,
    pendingCount: 0,
    isSyncing: false,
  };

  constructor() {
    this.initSync();
  }

  private async initSync() {
    // Check for pending surveys on startup
    await this.checkPendingSurveys();

    // Set up periodic sync checks
    this.syncInterval = setInterval(() => {
      if (navigator.onLine) {
        this.syncData();
      }
    }, 30000); // Check every 30 seconds
  }

  async checkPendingSurveys() {
    const pendingSurveys = await surveyService.getPendingSurveys();
    this.syncStatus.pendingCount = pendingSurveys.length;
  }

  async syncData(): Promise<void> {
    if (this.syncStatus.isSyncing) return;

    try {
      this.syncStatus.isSyncing = true;
      const pendingSurveys = await surveyService.getPendingSurveys();

      if (pendingSurveys.length === 0) {
        this.syncStatus.isSyncing = false;
        return;
      }

      // Simulate API call to sync data
      const response = await this.sendToServer(pendingSurveys);

      if (response.success) {
        // Mark surveys as synced
        for (const survey of pendingSurveys) {
          await surveyService.saveSurvey({
            ...survey,
            status: 'submitted' // Assuming server updates status
          });
        }

        this.syncStatus.lastSync = new Date().toISOString();
        this.syncStatus.pendingCount = 0;
      }
    } catch (error) {
      console.error('Sync failed:', error);
    } finally {
      this.syncStatus.isSyncing = false;
    }
  }

  private async sendToServer(surveys: Survey[]): Promise<{ success: boolean }> {
    // In a real app, this would be an actual API call
    return new Promise((resolve) => {
      setTimeout(() => {
        console.log('Syncing surveys:', surveys);
        resolve({ success: true });
      }, 1000);
    });
  }

  getSyncStatus(): SyncStatus {
    return { ...this.syncStatus };
  }

  cleanup() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }
  }
}

export const syncService = new SyncService();
