// App.tsx
import React, { useState, useEffect } from 'react';
import { Survey, SyncStatus } from './types';
import { surveyService } from './surveyService';
import { syncService } from './syncService';

const App: React.FC = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>({
    lastSync: null,
    pendingCount: 0,
    isSyncing: false,
  });

  useEffect(() => {
    // Initialize services
    const init = async () => {
      await surveyService.init();
      const loadedSurveys = await surveyService.getAllSurveys();
      setSurveys(loadedSurveys);
    };

    init();

    // Set up sync status listener
    const interval = setInterval(() => {
      setSyncStatus(syncService.getSyncStatus());
    }, 1000);

    // Listen for online/offline events
    const handleOnline = () => syncService.syncData();
    const handleOffline = () => console.log('Offline mode');

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      clearInterval(interval);
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      syncService.cleanup();
    };
  }, []);

  const handleSaveSurvey = async (survey: Survey) => {
    await surveyService.saveSurvey(survey);
    const updatedSurveys = await surveyService.getAllSurveys();
    setSurveys(updatedSurveys);
  };

  const handleSubmitSurvey = async (survey: Survey) => {
    const updatedSurvey = {
      ...survey,
      status: 'submitted' as const,
      lastModified: new Date().toISOString(),
    };
    await handleSaveSurvey(updatedSurvey);
    await syncService.checkPendingSurveys();
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className="sync-status">
          {navigator.onLine ? '✅ Online' : '❌ Offline'}
          {syncStatus.isSyncing && ' - Syncing...'}
          {syncStatus.lastSync && ` - Last sync: ${new Date(syncStatus.lastSync).toLocaleTimeString()}`}
          {syncStatus.pendingCount > 0 && ` - ${syncStatus.pendingCount} pending`}
        </div>
      </header>

      <main>
        <SurveyList
          surveys={surveys}
          onSave={handleSaveSurvey}
          onSubmit={handleSubmitSurvey}
        />
      </main>
    </div>
  );
};

interface SurveyListProps {
  surveys: Survey[];
  onSave: (survey: Survey) => Promise<void>;
  onSubmit: (survey: Survey) => Promise<void>;
}

const SurveyList: React.FC<SurveyListProps> = ({ surveys, onSave, onSubmit }) => {
  const [editingSurvey, setEditingSurvey] = useState<Survey | null>(null);

  const handleEdit = (survey: Survey) => {
    setEditingSurvey(survey);
  };

  const handleSave = async (updatedSurvey: Survey) => {
    await onSave(updatedSurvey);
    setEditingSurvey(null);
  };

  return (
    <div className="survey-list">
      {surveys.map((survey) => (
        <div key={survey.id} className="survey-card">
          <h3>{survey.title}</h3>
          <p>Status: {survey.status}</p>
          <p>Last modified: {new Date(survey.lastModified).toLocaleString()}</p>
          <button onClick={() => handleEdit(survey)}>Edit</button>
          {survey.status === 'draft' && (
            <button onClick={() => onSubmit(survey)}>Submit</button>
          )}
        </div>
      ))}

      {editingSurvey && (
        <SurveyForm
          survey={editingSurvey}
          onSave={handleSave}
          onCancel={() => setEditingSurvey(null)}
        />
      )}
    </div>
  );
};

interface SurveyFormProps {
  survey: Survey;
  onSave: (survey: Survey) => Promise<void>;
  onCancel: () => void;
}

const SurveyForm: React.FC<SurveyFormProps> = ({ survey, onSave, onCancel }) => {
  const [formData, setFormData] = useState<Survey>(survey);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave(formData);
  };

  return (
    <form onSubmit={handleSubmit} className="survey-form">
      <h2>{survey.id ? 'Edit Survey' : 'New Survey'}</h2>

      <div>
        <label>Title:</label>
        <input
          type="text"
          name="title"
          value={formData.title}
          onChange={handleChange}
          required
        />
      </div>

      <div>
        <label>Notes:</label>
        <textarea
          name="notes"
          value={formData.notes}
          onChange={handleChange}
        />
      </div>

      <div>
        <button type="submit">Save</button>
        <button type="button" onClick={onCancel}>Cancel</button>
      </div>
    </form>
  );
};

export default App;
