import { Survey, SyncQueueItem } from './types';

const DB_NAME = 'FieldSurveyDB';
const STORE_NAME = 'surveys';
const SYNC_QUEUE_NAME = 'syncQueue';

class SurveyService {
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, 1);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(SYNC_QUEUE_NAME)) {
          db.createObjectStore(SYNC_QUEUE_NAME, { keyPath: 'surveyId' });
        }
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  // Local storage operations
  async saveSurvey(survey: Survey): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(survey);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getSurveys(): Promise<Survey[]> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async getSurveyById(id: string): Promise<Survey | undefined> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get(id);

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  // Sync queue operations
  async addToSyncQueue(item: SyncQueueItem): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(SYNC_QUEUE_NAME, 'readwrite');
      const store = transaction.objectStore(SYNC_QUEUE_NAME);
      const request = store.put(item);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  async getSyncQueue(): Promise<SyncQueueItem[]> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(SYNC_QUEUE_NAME, 'readonly');
      const store = transaction.objectStore(SYNC_QUEUE_NAME);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async clearSyncQueue(): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(SYNC_QUEUE_NAME, 'readwrite');
      const store = transaction.objectStore(SYNC_QUEUE_NAME);
      const request = store.clear();

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  // Sync with server
  async syncWithServer(): Promise<void> {
    if (!navigator.onLine) {
      console.log('Offline - skipping sync');
      return;
    }

    try {
      const queue = await this.getSyncQueue();
      if (queue.length === 0) return;

      console.log(`Syncing ${queue.length} items with server...`);

      // Process each item in the queue
      for (const item of queue) {
        try {
          // Simulate API call to server
          await this.simulateServerSync(item);

          // If successful, remove from queue
          await this.removeFromSyncQueue(item.surveyId);
        } catch (error) {
          console.error(`Failed to sync item ${item.surveyId}:`, error);
          // Keep in queue for next sync attempt
        }
      }

      console.log('Sync completed');
    } catch (error) {
      console.error('Sync error:', error);
      throw error;
    }
  }

  private async simulateServerSync(item: SyncQueueItem): Promise<void> {
    // In a real app, this would be an actual API call
    console.log(`Simulating server sync for ${item.surveyId} (${item.action})`);

    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 500));

    // Simulate occasional failure
    if (Math.random() < 0.1) {
      throw new Error('Simulated server error');
    }

    // Update local record to mark as synced
    const survey = await this.getSurveyById(item.surveyId);
    if (survey) {
      survey.isSynced = true;
      await this.saveSurvey(survey);
    }
  }

  private async removeFromSyncQueue(surveyId: string): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(SYNC_QUEUE_NAME, 'readwrite');
