// useSurvey.ts (React hook)
import { useState, useEffect } from 'react';
import { surveyService } from './surveyService';
import { Survey, SyncQueueItem } from './types';

export const useSurvey = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);

  // Load surveys from local storage
  useEffect(() => {
    const loadSurveys = async () => {
      try {
        const loadedSurveys = await surveyService.getSurveys();
        setSurveys(loadedSurveys);
      } catch (error) {
        console.error('Failed to load surveys:', error);
      }
    };

    loadSurveys();
  }, []);

  // Check for network status changes
  useEffect(() => {
    const handleOnlineStatusChange = () => {
      if (navigator.onLine) {
        syncData();
      }
    };

    window.addEventListener('online', handleOnlineStatusChange);
    return () => window.removeEventListener('online', handleOnlineStatusChange);
  }, []);

  // Periodic sync check
  useEffect(() => {
    const interval = setInterval(() => {
      if (navigator.onLine) {
        syncData();
      }
    }, 300000); // Every 5 minutes

    return () => clearInterval(interval);
  }, []);

  const syncData = async () => {
    if (isSyncing) return;

    setIsSyncing(true);
    try {
      await surveyService.syncWithServer();
      const updatedSurveys = await surveyService.getSurveys();
      setSurveys(updatedSurveys);
      setLastSyncTime(new Date());
    } catch (error) {
      console.error('Sync failed:', error);
    } finally {
      setIsSyncing(false);
    }
  };

  const addSurvey = async (survey: Omit<Survey, 'id' | 'isSynced'>) => {
    const newSurvey: Survey = {
      ...survey,
      id: Date.now().toString(),
      isSynced: false,
    };

    try {
      await surveyService.saveSurvey(newSurvey);

      // Add to sync queue
      const syncItem: SyncQueueItem = {
        surveyId: newSurvey.id,
        action: 'create',
        data: newSurvey,
        timestamp: Date.now(),
      };
      await surveyService.addToSyncQueue(syncItem);

      setSurveys(prev => [...prev, newSurvey]);

      // Trigger sync if online
      if (navigator.onLine) {
        syncData();
      }
    } catch (error) {
      console.error('Failed to add survey:', error);
      throw error;
    }
  };

  const updateSurvey = async (id: string, updates: Partial<Survey>) => {
    try {
      const existingSurvey = await surveyService.getSurveyById(id);
      if (!existingSurvey) throw new Error('Survey not found');

      const updatedSurvey = { ...existingSurvey, ...updates, isSynced: false };
      await surveyService.saveSurvey(updatedSurvey);

      // Add to sync queue
      const syncItem: SyncQueueItem = {
        surveyId: id,
        action: 'update',
        data: updates,
        timestamp: Date.now(),
      };
      await surveyService.addToSyncQueue(syncItem);

      setSurveys(prev => prev.map(s => s.id === id ? updatedSurvey : s));

      // Trigger sync if online
      if (navigator.onLine) {
        syncData();
      }
    } catch (error) {
      console.error('Failed to update survey:', error);
      throw error;
    }
  };

  const deleteSurvey = async (id: string) => {
    try {
      // Add to sync queue first
      const syncItem: SyncQueueItem = {
        surveyId: id,
        action: 'delete',
        data: {},
        timestamp: Date.now(),
      };
      await surveyService.addToSyncQueue(syncItem);

      // Remove from local storage
      await surveyService.removeFromSyncQueue(id);

      setSurveys(prev => prev.filter(s => s.id !== id));

      // Trigger sync if online
      if (navigator.onLine) {
        syncData();
      }
    } catch (error) {
      console.error('Failed to delete survey:', error);
      throw error;
    }
  };

  return {
    surveys,
    isSyncing,
    lastSyncTime,
    addSurvey,
    updateSurvey,
    deleteSurvey,
    syncData,
  };
};
