const SurveyApp: React.FC = () => {
  const {
    surveys,
    isSyncing,
    lastSyncTime,
    addSurvey,
    updateSurvey,
    deleteSurvey,
    syncData,
  } = useSurvey();

  const [newSurvey, setNewSurvey] = useState<Omit<Survey, 'id' | 'isSynced'>>({
    title: '',
    location: { latitude: 0, longitude: 0 },
    photos: [],
    notes: '',
    timestamp: Date.now(),
  });

  const [editingId, setEditingId] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setNewSurvey(prev => ({
      ...prev,
      [name]: name === 'latitude' || name === 'longitude'
        ? { ...prev.location, [name]: parseFloat(value) || 0 }
        : value,
    }));
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onload = (event) => {
        if (event.target?.result) {
          setNewSurvey(prev => ({
            ...prev,
            photos: [...prev.photos, event.target!.result as string],
          }));
        }
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingId) {
        await updateSurvey(editingId, newSurvey);
        setEditingId(null);
      } else {
        await addSurvey(newSurvey);
      }
      setNewSurvey({
        title: '',
        location: { latitude: 0, longitude: 0 },
        photos: [],
        notes: '',
        timestamp: Date.now(),
      });
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error) {
      alert('Failed to save survey. Please try again.');
    }
  };

  const handleEdit = (survey: Survey) => {
    setNewSurvey({
      title: survey.title,
      location: survey.location,
      photos: survey.photos,
      notes: survey.notes,
      timestamp: survey.timestamp,
    });
    setEditingId(survey.id);
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this survey?')) {
      try {
        await deleteSurvey(id);
      } catch (error) {
        alert('Failed to delete survey. Please try again.');
      }
    }
  };

  return (
    <div className="survey-app">
      <header>
        <h1>Field Survey App</h1>
        <div className="sync-status">
          {isSyncing ? (
            <span>Syncing... <span className="spinner"></span></span>
          ) : (
            <span>
              {lastSyncTime
                ? `Last synced: ${lastSyncTime.toLocaleTimeString()}`
                : 'Not synced yet'}
              <button onClick={syncData} disabled={!navigator.onLine}>
                {navigator.onLine ? 'Sync Now' : 'Offline'}
              </button>
            </span>
          )}
        </div>
      </header>

      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label>Title:</label>
          <input
            type="text"
            name="title"
            value={newSurvey.title}
            onChange={handleInputChange}
            required
          />
        </div>

        <div className="form-group">
          <label>Location:</label>
          <div className="location-inputs">
            <input
              type="number"
              name="latitude"
              placeholder="Latitude"
              value={newSurvey.location.latitude}
              onChange={handleInputChange}
              step="any"
              required
            />
            <input
              type="number"
              name="longitude"
              placeholder="Longitude"
              value={newSurvey.location.longitude}
              onChange={handleInputChange}
              step="any"
              required
            />
          </div>
        </div>

        <div className="form-group">
          <label>Photos:</label>
          <input
            type="file"
            accept="image/*"
            onChange={handlePhotoUpload}
            ref={fileInputRef}
          />
          <div className="photo-preview">
            {newSurvey.photos.map((photo, index) => (
              <img
                key={index}
                src={photo}
                alt={`Preview ${index}`}
                style={{ width: '100px', height: '100px', objectFit: 'cover' }}
              />
            ))}
          </div>
        </div>

        <div className="form-group">
          <label>Notes:</label>
          <textarea
            name="notes"
            value={newSurvey.notes}
            onChange={handleInputChange}
          />
        </div>

        <button type="submit">
          {editingId ? 'Update Survey' : 'Add Survey'}
        </button>
        {editingId && (
          <button type="button" onClick={() => {
            setEditingId(null);
            setNewSurvey({
              title: '',
              location: { latitude: 0, longitude: 0 },
              photos: [],
              notes: '',
              timestamp: Date.now(),
            });
          }}>
            Cancel
          </button>
        )}
      </form>

      <div className="survey-list">
        <h2>Saved Surveys</h2>
        {surveys.length === 0 ? (
          <p>No surveys saved yet.</p>
        ) : (
          <ul>
            {surveys.map(survey => (
