        <SurveyList surveys={surveys} onUpdate={updateSurvey} />
      </main>

      {!isOnline && (
        <div className="offline-notice">
          You're currently offline. Changes will sync when you're back online.
        </div>
      )}
    </div>
  );
};

export default App;
