### 2. Offline Data Hook

```typescript
// src/hooks/useOfflineData.ts
import { useState, useEffect } from 'react';
import { openDB, DBSchema } from 'idb';
import { Survey } from '../types';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-timestamp': number };
  };
  pendingSync: {
    key: string;
    value: Survey;
  };
}

export const useOfflineData = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [db, setDb] = useState<IDBPDatabase<SurveyDB> | null>(null);

  useEffect(() => {
    const initDB = async () => {
      const database = await openDB<SurveyDB>('survey-db', 1, {
        upgrade(db) {
          if (!db.objectStoreNames.contains('surveys')) {
            const store = db.createObjectStore('surveys', {
              keyPath: 'id',
            });
            store.createIndex('by-timestamp', 'timestamp');
          }

          if (!db.objectStoreNames.contains('pendingSync')) {
            db.createObjectStore('pendingSync', {
              keyPath: 'id',
            });
          }
        },
      });
      setDb(database);
      await loadSurveys(database);
    };

    initDB();

    return () => {
      if (db) {
        db.close();
      }
    };
  }, []);

  const loadSurveys = async (database: IDBPDatabase<SurveyDB>) => {
    const tx = database.transaction('surveys', 'readonly');
    const store = tx.objectStore('surveys');
    const allSurveys = await store.getAll();
    setSurveys(allSurveys);
  };

  const addSurvey = async (survey: Survey) => {
    if (!db) return;

    const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');
    const surveysStore = tx.objectStore('surveys');
    const pendingStore = tx.objectStore('pendingSync');

    await surveysStore.add(survey);
    await pendingStore.add(survey);

    await loadSurveys(db);
  };

  const updateSurvey = async (updatedSurvey: Survey) => {
    if (!db) return;

    const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');
    const surveysStore = tx.objectStore('surveys');
    const pendingStore = tx.objectStore('pendingSync');

    await surveysStore.put(updatedSurvey);
    await pendingStore.put(updatedSurvey);

    await loadSurveys(db);
  };

  const syncData = async () => {
    if (!db) return;

    const tx = db.transaction(['pendingSync', 'surveys'], 'readwrite');
    const pendingStore = tx.objectStore('pendingSync');
    const surveysStore = tx.objectStore('surveys');

    const pendingSurveys = await pendingStore.getAll();

    if (pendingSurveys.length === 0) return;

    try {
      // Simulate API call to sync with server
      const response = await fetch('/api/sync', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(pendingSurveys),
      });

      if (response.ok) {
        // Clear pending sync items
        const clearTx = db.transaction('pendingSync', 'readwrite');
        const clearStore = clearTx.objectStore('pendingSync');
        await clearStore.clear();
      } else {
        console.error('Sync failed:', await response.text());
      }
    } catch (error) {
      console.error('Sync error:', error);
      throw error;
    }
  };

  return {
    surveys,
    addSurvey,
    updateSurvey,
    syncData,
  };
};
