### 8. Service Worker for Offline Support

```javascript
// public/sw.js
const CACHE_NAME = 'survey-app-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
  // Add other assets you want to cache
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(ASSETS_TO_CACHE))
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        // Clone the request
        const fetchRequest = event.request.clone();

        return fetch(fetchRequest).then(
          (response) => {
            // Check if we received a valid response
            if (!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Clone the response
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDB('survey-db', 1);
  const tx = db.transaction(['pendingSync', 'surveys'], 'readwrite');
  const pendingStore = tx.objectStore('pendingSync');
  const surveysStore = tx.objectStore('surveys');

  const pendingSurveys = await pendingStore.getAll();

  if (pendingSurveys.length === 0) return;

  try {
    const response = await fetch('https://api.example.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (response.ok) {
      // Clear pending sync queue
      await pendingStore.clear();

      // Update local data with server response if needed
      // This would depend on your API design
    }
  } catch (error) {
    console.error('Background sync error:', error);
  }
}
