### 2. Offline Data Hook

```typescript
// src/hooks/useOfflineData.ts
import { useState, useEffect } from 'react';
import { openDB, DBSchema } from 'idb';
import { Survey } from '../types';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-timestamp': number };
  };
  pendingSync: {
    key: string;
    value: { action: 'add' | 'update'; survey: Survey };
  };
}

export const useOfflineData = () => {
  const [db, setDb] = useState<IDBPDatabase<SurveyDB> | null>(null);
  const [surveys, setSurveys] = useState<Survey[]>([]);

  useEffect(() => {
    const initDB = async () => {
      const database = await openDB<SurveyDB>('survey-db', 1, {
        upgrade(db) {
          if (!db.objectStoreNames.contains('surveys')) {
            const store = db.createObjectStore('surveys', {
              keyPath: 'id',
            });
            store.createIndex('by-timestamp', 'timestamp');
          }

          if (!db.objectStoreNames.contains('pendingSync')) {
            db.createObjectStore('pendingSync', {
              keyPath: 'id',
              autoIncrement: true,
            });
          }
        },
      });
      setDb(database);
      await loadSurveys(database);
    };

    initDB();

    return () => {
      if (db) {
        db.close();
      }
    };
  }, []);

  const loadSurveys = async (database: IDBPDatabase<SurveyDB>) => {
    const tx = database.transaction('surveys', 'readonly');
    const store = tx.objectStore('surveys');
    const allSurveys = await store.getAll();
    setSurveys(allSurveys);
  };

  const addSurvey = async (survey: Omit<Survey, 'id' | 'timestamp'>) => {
    if (!db) return;

    const newSurvey: Survey = {
      ...survey,
      id: crypto.randomUUID(),
      timestamp: Date.now(),
      isSynced: false,
    };

    // Add to local DB
    const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');
    await tx.objectStore('surveys').add(newSurvey);
    await tx.objectStore('pendingSync').add({
      action: 'add',
      survey: newSurvey,
    });

    await loadSurveys(db);
  };

  const updateSurvey = async (updatedSurvey: Survey) => {
    if (!db) return;

    // Update in local DB
    const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');
    await tx.objectStore('surveys').put(updatedSurvey);
    await tx.objectStore('pendingSync').add({
      action: 'update',
      survey: updatedSurvey,
    });

    await loadSurveys(db);
  };

  const syncData = async () => {
    if (!db) return;

    const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');
    const pendingStore = tx.objectStore('pendingSync');
    const surveyStore = tx.objectStore('surveys');

    const pendingActions = await pendingStore.getAll();

    for (const action of pendingActions) {
      try {
        // Simulate API call - replace with your actual API endpoint
        const response = await fetch('/api/surveys', {
          method: action.action === 'add' ? 'POST' : 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(action.survey),
        });

        if (response.ok) {
          // Mark as synced
          const updatedSurvey = {
            ...action.survey,
            isSynced: true,
          };
          await surveyStore.put(updatedSurvey);
          await pendingStore.delete(action.id);
        }
      } catch (error) {
        console.error('Sync failed for survey:', action.survey.id, error);
        // Continue with next item even if one fails
      }
    }

    await loadSurveys(db);
  };

  return {
    surveys,
    addSurvey,
    updateSurvey,
    syncData,
  };
};
