### 8. Service Worker for Background Sync

```javascript
// public/sw.js
const CACHE_NAME = 'survey-app-v1';
const urlsToCache = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        // Clone the request
        const fetchRequest = event.request.clone();

        return fetch(fetchRequest).then(
          (response) => {
            // Check if we received a valid response
            if (!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Clone the response
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDB('survey-db', 1);
  const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');
  const pendingStore = tx.objectStore('pendingSync');
  const surveyStore = tx.objectStore('surveys');

  const pendingActions = await pendingStore.getAll();

  for (const action of pendingActions) {
    try {
      const response = await fetch('/api/surveys', {
        method: action.action === 'add' ? 'POST' : 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(action.survey),
      });

      if (response.ok) {
        const updatedSurvey = {
          ...action.survey,
          isSynced: true,
        };
        await surveyStore.put(updatedSurvey);
        await pendingStore.delete(action.id);
      }
    } catch (error) {
      console.error('Background sync failed:', error);
    }
  }
}
```

