### 2. Offline Data Hook (`hooks/useOfflineData.ts`)

```typescript
import { useState, useEffect, useCallback } from 'react';
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: SurveyData;
    indexes: { 'by-timestamp': number; 'by-synced': boolean };
  };
}

interface SurveyData {
  id: string;
  location: string;
  observations: string;
  photos: string[];
  timestamp: number;
  synced: boolean;
  syncAttempts: number;
  lastModified: number;
}

export const useOfflineData = () => {
  const [db, setDb] = useState<IDBPDatabase<SurveyDB> | null>(null);
  const [surveys, setSurveys] = useState<SurveyData[]>([]);

  // Initialize database
  useEffect(() => {
    const initDB = async () => {
      const database = await openDB<SurveyDB>('field-surveys', 1, {
        upgrade(db) {
          const store = db.createObjectStore('surveys', {
            keyPath: 'id',
          });
          store.createIndex('by-timestamp', 'timestamp');
          store.createIndex('by-synced', 'synced');
        },
      });
      setDb(database);

      // Load initial data
      const allSurveys = await database.getAll('surveys');
      setSurveys(allSurveys);
    };

    initDB();
  }, []);

  const addSurvey = useCallback(
    async (surveyData: Omit<SurveyData, 'id' | 'synced' | 'syncAttempts' | 'lastModified'>) => {
      if (!db) throw new Error('Database not initialized');

      const newSurvey: SurveyData = {
        ...surveyData,
        id: crypto.randomUUID(),
        synced: false,
        syncAttempts: 0,
        lastModified: Date.now(),
        timestamp: Date.now(),
      };

      await db.add('surveys', newSurvey);
      setSurveys((prev) => [...prev, newSurvey]);
    },
    [db]
  );

  const syncData = useCallback(async () => {
    if (!db) throw new Error('Database not initialized');

    // Get unsynced surveys
    const unsyncedSurveys = await db.getAllFromIndex(
      'surveys',
      'by-synced',
      false
    );

    if (unsyncedSurveys.length === 0) return;

    // Simulate API call
    const syncSurvey = async (survey: SurveyData) => {
      try {
        // In a real app, this would be an actual API call
        // await fetch('/api/surveys', { method: 'POST', body: JSON.stringify(survey) });

        // Simulate network delay
        await new Promise(resolve => setTimeout(resolve, 500));

        // Mark as synced
        const updatedSurvey = { ...survey, synced: true, lastModified: Date.now() };
        await db.put('surveys', updatedSurvey);

        // Update local state
        setSurveys(prev => prev.map(s => s.id === survey.id ? updatedSurvey : s));
      } catch (error) {
        console.error('Sync failed:', error);
        // Increment sync attempts
        const updatedSurvey = {
          ...survey,
          syncAttempts: survey.syncAttempts + 1,
          lastModified: Date.now()
        };
        await db.put('surveys', updatedSurvey);
        setSurveys(prev => prev.map(s => s.id === survey.id ? updatedSurvey : s));
      }
    };

    // Sync in parallel with limited concurrency
    const batchSize = 3;
    for (let i = 0; i < unsyncedSurveys.length; i += batchSize) {
      const batch = unsyncedSurveys.slice(i, i + batchSize);
      await Promise.all(batch.map(syncSurvey));
    }
  }, [db]);

  return { surveys, addSurvey, syncData };
};
```

### 3. Network Status Hook (`hooks/useNetworkStatus.ts`)

```typescript
import { useState, useEffect } from 'react';

export const useNetworkStatus = () => {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [isSlowConnection, setIsSlowConnection] = useState(false);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Check connection speed periodically
    const checkConnectionSpeed = async () => {
      try {
        const startTime = performance.now();
        await fetch('https://httpbin.org/get', { method: 'HEAD', mode: 'no-cors' });
        const duration = performance.now() - startTime;
        setIsSlowConnection(duration > 1000); // Consider slow if > 1 second
      } catch {
        setIsSlowConnection(true);
      }
    };

    const interval = setInterval(checkConnectionSpeed, 30000); // Check every 30 seconds
    checkConnectionSpeed(); // Initial check

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      clearInterval(interval);
    };
  }, []);

  return { isOnline, isSlowConnection };
};
