### 6. Service Worker for Background Sync (`service-worker.js`)

```javascript
const CACHE_NAME = 'field-survey-cache-v1';
const urlsToCache = [
  '/',
  '/index.html',
  '/styles.css',
  '/app.js',
  // Add other assets you want to cache
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(urlsToCache))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache-first strategy
        if (response) {
          return response;
        }

        return fetch(event.request).then(
          (response) => {
            // Check if we received a valid response
            if (!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Clone the response
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

// Background sync for when the app is closed
self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDB('field-surveys', 1);
  const unsyncedSurveys = await db.getAllFromIndex('surveys', 'by-synced', false);

  if (unsyncedSurveys.length === 0) return;

  try {
    // Simulate API call
    await new Promise(resolve => setTimeout(resolve, 1000));

    // Mark as synced
    for (const survey of unsyncedSurveys) {
      await db.put('surveys', { ...survey, synced: true });
    }

    // Notify the client
    self.clients.matchAll().then(clients => {
      clients.forEach(client => client.postMessage({ type: 'SYNC_COMPLETE' }));
    });
  } catch (error) {
    console.error('Background sync failed:', error);
  }
}
