// syncService.ts
import { Survey } from './types';
import { surveyService } from './surveyService';

const API_ENDPOINT = 'https://api.example.com/surveys';

export class SyncService {
  private syncInterval: number | null = null;
  private isSyncing = false;

  constructor(private onSyncStatusChange: (isOnline: boolean) => void) {
    this.setupNetworkListener();
    this.startPeriodicSync();
  }

  private setupNetworkListener() {
    window.addEventListener('online', () => {
      this.onSyncStatusChange(true);
      this.syncPendingSurveys();
    });

    window.addEventListener('offline', () => {
      this.onSyncStatusChange(false);
    });
  }

  private startPeriodicSync() {
    // Sync every 5 minutes when online
    this.syncInterval = window.setInterval(() => {
      if (navigator.onLine) {
        this.syncPendingSurveys();
      }
    }, 5 * 60 * 1000);
  }

  async syncPendingSurveys(): Promise<void> {
    if (this.isSyncing || !navigator.onLine) return;

    this.isSyncing = true;

    try {
      const surveys = await surveyService.getAllSurveys();
      const pendingSurveys = surveys.filter(s => s.status === 'pending');

      for (const survey of pendingSurveys) {
        try {
          await this.syncSingleSurvey(survey);
        } catch (error) {
          console.error(`Failed to sync survey ${survey.id}:`, error);
          // Update survey status to failed and increment retry count
          await surveyService.saveSurvey({
            ...survey,
            status: 'failed',
            retries: (survey.retries || 0) + 1
          });
        }
      }
    } finally {
      this.isSyncing = false;
    }
  }

  private async syncSingleSurvey(survey: Survey): Promise<void> {
    const response = await fetch(API_ENDPOINT, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(survey),
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    // Update survey status to synced
    await surveyService.saveSurvey({
      ...survey,
      status: 'synced'
    });
  }

  async retryFailedSurveys(): Promise<void> {
    const surveys = await surveyService.getAllSurveys();
    const failedSurveys = surveys.filter(s => s.status === 'failed');

    for (const survey of failedSurveys) {
      try {
        await this.syncSingleSurvey(survey);
      } catch (error) {
        console.error(`Retry failed for survey ${survey.id}:`, error);
      }
    }
  }

  cleanup() {
    if (this.syncInterval) {
      clearInterval(this.syncInterval);
    }
  }
}
