import { SyncService } from './syncService';

const App: React.FC = () => {
  const [state, setState] = useState<AppState>({
    surveys: [],
    isOnline: navigator.onLine,
    syncInProgress: false,
    lastSyncTime: null,
  });

  const syncService = new SyncService((isOnline) => {
    setState(prev => ({ ...prev, isOnline }));
  });

  const loadSurveys = useCallback(async () => {
    const surveys = await surveyService.getAllSurveys();
    setState(prev => ({ ...prev, surveys }));
  }, []);

  useEffect(() => {
    loadSurveys();
    return () => syncService.cleanup();
  }, [loadSurveys]);

  const handleNewSurvey = async (surveyData: Omit<Survey, 'id' | 'timestamp' | 'status'>) => {
    const newSurvey: Survey = {
      id: Date.now().toString(),
      timestamp: new Date().toISOString(),
      status: navigator.onLine ? 'pending' : 'synced', // Mark as synced if offline
      ...surveyData,
    };

    await surveyService.saveSurvey(newSurvey);
    await loadSurveys();

    if (navigator.onLine) {
      syncService.syncPendingSurveys();
    }
  };

  const handleRetryFailed = async () => {
    if (!navigator.onLine) {
      alert('You need to be online to retry failed surveys');
      return;
    }

    setState(prev => ({ ...prev, syncInProgress: true }));
    await syncService.retryFailedSurveys();
    await loadSurveys();
    setState(prev => ({ ...prev, syncInProgress: false }));
  };

  const handleManualSync = async () => {
    if (!navigator.onLine) {
      alert('You need to be online to sync');
      return;
