```typescript
// surveyService.ts
import { Survey } from './types';

const DB_NAME = 'FieldSurveyDB';
const STORE_NAME = 'surveys';

class SurveyService {
  private db: IDBDatabase | null = null;
  private pendingSyncQueue: Survey[] = [];

  constructor() {
    this.initDB();
    this.setupSyncListener();
  }

  private async initDB(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, 1);

      request.onerror = (event) => {
        console.error('Database error:', event);
        reject('Failed to open database');
      };

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
    });
  }

  private setupSyncListener(): void {
    window.addEventListener('online', this.syncPendingSurveys.bind(this));
  }

  async addSurvey(survey: Omit<Survey, 'id' | 'status' | 'lastModified'>): Promise<Survey> {
    if (!this.db) await this.initDB();

    const newSurvey: Survey = {
      ...survey,
      id: Date.now().toString(),
      status: 'pending',
      lastModified: new Date().toISOString()
    };

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.add(newSurvey);

      request.onsuccess = () => {
        this.pendingSyncQueue.push(newSurvey);
        this.syncPendingSurveys();
        resolve(newSurvey);
      };

      request.onerror = (event) => {
        console.error('Error adding survey:', event);
        reject('Failed to add survey');
      };
    });
  }

  async getSurveys(): Promise<Survey[]> {
    if (!this.db) await this.initDB();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readonly');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.getAll();

      request.onsuccess = () => {
        resolve(request.result);
      };

      request.onerror = (event) => {
        console.error('Error fetching surveys:', event);
        reject('Failed to fetch surveys');
      };
    });
  }

  async updateSurvey(survey: Survey): Promise<void> {
    if (!this.db) await this.initDB();

    const updatedSurvey = {
      ...survey,
      lastModified: new Date().toISOString()
    };

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(STORE_NAME, 'readwrite');
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(updatedSurvey);

      request.onsuccess = () => {
        if (updatedSurvey.status === 'pending') {
          this.pendingSyncQueue.push(updatedSurvey);
        }
        this.syncPendingSurveys();
        resolve();
      };

      request.onerror = (event) => {
        console.error('Error updating survey:', event);
        reject('Failed to update survey');
      };
    });
  }

  async syncPendingSurveys(): Promise<void> {
    if (!navigator.onLine) return;

    const surveysToSync = await this.getSurveys();
    const pendingSurveys = surveysToSync.filter(s => s.status === 'pending');

    if (pendingSurveys.length === 0) return;

    try {
      // Simulate API call to your backend
      const response = await fetch('https://your-api.com/surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(pendingSurveys),
      });

      if (response.ok) {
        // Update local status to 'synced'
        for (const survey of pendingSurveys) {
          await this.updateSurvey({
            ...survey,
            status: 'synced',
            lastModified: new Date().toISOString()
          });
        }

        this.pendingSyncQueue = this.pendingSyncQueue.filter(
          s => !pendingSurveys.some(ps => ps.id === s.id)
        );
      } else {
        console.error('Sync failed with status:', response.status);
        // Mark as failed to retry later
        for (const survey of pendingSurveys) {
          await this.updateSurvey({
            ...survey,
            status: 'failed',
            lastModified: new Date().toISOString()
          });
        }
      }
    } catch (error) {
      console.error('Sync error:', error);
      // Mark as failed to retry later
      for (const survey of pendingSurveys) {
        await this.updateSurvey({
          ...survey,
          status: 'failed',
          lastModified: new Date().toISOString()
        });
      }
    }
  }

  async getSyncStatus(): Promise<SyncStatus> {
    const surveys = await this.getSurveys();
    const pendingCount = surveys.filter(s => s.status === 'pending').length;

    return {
      isOnline: navigator.onLine,
      lastSync: localStorage.getItem('lastSyncTime'),
      pendingCount
    };
  }
}

export const surveyService = new SurveyService();
