## Data Storage Service

```typescript
// storageService.ts
import { SurveyData } from './types';

const STORAGE_KEY = 'fieldSurveyData';

export const saveSurvey = async (survey: SurveyData): Promise<void> => {
  try {
    const existingData = await getAllSurveys();
    const updatedData = [...existingData, survey];
    await localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedData));
  } catch (error) {
    console.error('Failed to save survey:', error);
    throw error;
  }
};

export const getAllSurveys = async (): Promise<SurveyData[]> => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch (error) {
    console.error('Failed to retrieve surveys:', error);
    return [];
  }
};

export const updateSurveyStatus = async (id: string, status: SurveyData['status']): Promise<void> => {
  const surveys = await getAllSurveys();
  const updatedSurveys = surveys.map(survey =>
    survey.id === id ? { ...survey, status } : survey
  );
  await localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedSurveys));
};

export const clearSyncedSurveys = async (): Promise<void> => {
  const surveys = await getAllSurveys();
  const pendingSurveys = surveys.filter(survey => survey.status === 'pending');
  await localStorage.setItem(STORAGE_KEY, JSON.stringify(pendingSurveys));
};
