## Sync Service

```typescript
// syncService.ts
import { SurveyData } from './types';
import { getAllSurveys, updateSurveyStatus, clearSyncedSurveys } from './storageService';

const API_ENDPOINT = 'https://your-api-endpoint.com/surveys';

export const syncSurveys = async (): Promise<{ success: number; failed: number }> => {
  const surveys = await getAllSurveys();
  const pendingSurveys = surveys.filter(survey => survey.status === 'pending');

  if (pendingSurveys.length === 0) {
    return { success: 0, failed: 0 };
  }

  let successCount = 0;
  let failedCount = 0;

  for (const survey of pendingSurveys) {
    try {
      // Prepare data for API (convert photos if needed)
      const payload = {
        ...survey,
        photos: survey.photos?.map(photo => ({
          data: photo,
          type: 'image/jpeg' // adjust based on your actual photo format
        }))
      };

      const response = await fetch(API_ENDPOINT, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        await updateSurveyStatus(survey.id, 'synced');
        successCount++;
      } else {
        await updateSurveyStatus(survey.id, 'failed');
        failedCount++;
      }
    } catch (error) {
      console.error('Sync failed for survey:', survey.id, error);
      await updateSurveyStatus(survey.id, 'failed');
      failedCount++;
    }
  }

  // Clean up synced surveys after a successful sync
  if (successCount > 0) {
    await clearSyncedSurveys();
  }

  return { success: successCount, failed: failedCount };
};
