## Main App Component

```typescript
// App.tsx
import React, { useState, useEffect } from 'react';
import { SurveyData } from './types';
import { saveSurvey, getAllSurveys } from './storageService';
import { syncSurveys } from './syncService';
import { useNetworkStatus } from './networkService';

const App: React.FC = () => {
  const [surveys, setSurveys] = useState<SurveyData[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<{ success: number; failed: number } | null>(null);
  const isOnline = useNetworkStatus();

  // Load surveys on initial render
  useEffect(() => {
    const loadSurveys = async () => {
      const savedSurveys = await getAllSurveys();
      setSurveys(savedSurveys);
    };
    loadSurveys();
  }, []);

  // Auto-sync when coming back online
  useEffect(() => {
    if (isOnline) {
      handleSync();
    }
  }, [isOnline]);

  const handleSync = async () => {
    if (!isOnline) return;

    setIsSyncing(true);
    try {
      const result = await syncSurveys();
      setSyncStatus(result);

      // Refresh surveys after sync
      const updatedSurveys = await getAllSurveys();
      setSurveys(updatedSurveys);
    } catch (error) {
      console.error('Sync error:', error);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleNewSurvey = async (formData: Record<string, any>, location: GeolocationPosition) => {
    const newSurvey: SurveyData = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      location: {
        latitude: location.coords.latitude,
        longitude: location.coords.longitude,
        accuracy: location.coords.accuracy,
      },
      formData,
      status: isOnline ? 'synced' : 'pending',
    };

    try {
      await saveSurvey(newSurvey);
      setSurveys(prev => [...prev, newSurvey]);

      // If online, attempt immediate sync
      if (isOnline) {
        await syncSurveys();
      }
    } catch (error) {
      console.error('Failed to save survey:', error);
    }
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className="status">
          <span>Status: {isOnline ? 'Online' : 'Offline'}</span>
          {isSyncing && <span>Syncing...</span>}
          {syncStatus && (
            <span>
              Synced: {syncStatus.success} | Failed: {syncStatus.failed}
            </span>
          )}
        </div>
      </header>

      <main>
        <SurveyForm onSubmit={handleNewSurvey} />
        <SurveyList surveys={surveys} />
      </main>

      {!isOnline && (
        <div className="offline-notice">
          You're offline. Surveys will sync when you reconnect.
        </div>
      )}
    </div>
  );
};

export default App;
```

