// SurveyForm.tsx
import React, { useState } from 'react';

interface SurveyFormProps {
  onSubmit: (formData: Record<string, any>, location: GeolocationPosition) => void;
}

const SurveyForm: React.FC<SurveyFormProps> = ({ onSubmit }) => {
  const [formData, setFormData] = useState({
    species: '',
    count: 1,
    notes: '',
  });
  const [location, setLocation] = useState<GeolocationPosition | null>(null);
  const [isLoading, setIsLoading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const getLocation = (): Promise<GeolocationPosition> => {
    return new Promise((resolve, reject) => {
      if (!navigator.geolocation) {
        reject(new Error('Geolocation is not supported by your browser'));
      } else {
        navigator.geolocation.getCurrentPosition(
          position => resolve(position),
          error => reject(error),
          { enableHighAccuracy: true }
        );
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const position = await getLocation();
      setLocation(position);
      onSubmit(formData, position);
      // Reset form
      setFormData({ species: '', count: 1, notes: '' });
    } catch (error) {
      console.error('Error getting location:', error);
      alert('Could not get your location. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>New Survey</h2>

      <div className="form-group">
        <label htmlFor="species">Species:</label>
        <input
          type="text"
          id="species"
          name="species"
          value={formData.species}
          onChange={handleChange}
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="count">Count:</label>
        <input
          type="number"
          id="count"
          name="count"
          value={formData.count}
          onChange={handleChange}
          min="1"
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="notes">Notes:</label>
        <textarea
          id="notes"
          name="notes"
          value={formData.notes}
          onChange={handleChange}
        />
      </div>

      <button type="submit" disabled={isLoading}>
        {isLoading ? 'Saving...' : 'Submit Survey'}
      </button>

      {location && (
        <div className="location-info">
          <p>Location recorded: {location.coords.latitude}, {location.coords.longitude}</p>
          <p>Accuracy: {location.coords.accuracy?.toFixed(2)} meters</p>
        </div>
      )}
    </form>
  );
};

export default SurveyForm;
