// survey-app/src/services/dbService.ts
import { openDB, DBSchema } from 'idb';
import { Survey, SurveyResponse } from '../types';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-date': Date };
  };
  responses: {
    key: string;
    value: SurveyResponse;
    indexes: { 'by-survey': string; 'by-date': Date };
  };
  syncQueue: {
    key: string;
    value: {
      type: 'survey' | 'response';
      action: 'create' | 'update' | 'delete';
      data: any;
      timestamp: Date;
    };
  };
}

const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;

export const initDB = async () => {
  return openDB<SurveyDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const surveyStore = db.createObjectStore('surveys', {
          keyPath: 'id',
        });
        surveyStore.createIndex('by-date', 'createdAt');
      }

      if (!db.objectStoreNames.contains('responses')) {
        const responseStore = db.createObjectStore('responses', {
          keyPath: 'id',
        });
        responseStore.createIndex('by-survey', 'surveyId');
        responseStore.createIndex('by-date', 'timestamp');
      }

      if (!db.objectStoreNames.contains('syncQueue')) {
        db.createObjectStore('syncQueue', {
          keyPath: 'id',
          autoIncrement: true,
        });
      }
    },
  });
};

export const getDB = async () => {
  return initDB();
};

// Survey operations
export const getSurveys = async (): Promise<Survey[]> => {
  const db = await getDB();
  return db.getAll('surveys');
};

export const getSurveyById = async (id: string): Promise<Survey | undefined> => {
  const db = await getDB();
  return db.get('surveys', id);
};

export const saveSurvey = async (survey: Survey): Promise<void> => {
  const db = await getDB();
  const tx = db.transaction(['surveys', 'syncQueue'], 'readwrite');

  await tx.objectStore('surveys').put(survey);

  // Add to sync queue if not synced
  if (!survey.isSynced) {
    await tx.objectStore('syncQueue').add({
      type: 'survey',
      action: survey.id ? 'update' : 'create',
      data: survey,
      timestamp: new Date(),
    });
  }

  await tx.done;
};

// Response operations
export const getResponses = async (surveyId?: string): Promise<SurveyResponse[]> => {
  const db = await getDB();
  if (surveyId) {
    return db.getAllFromIndex('responses', 'by-survey', surveyId);
  }
  return db.getAll('responses');
};

export const saveResponse = async (response: SurveyResponse): Promise<void> => {
  const db = await getDB();
  const tx = db.transaction(['responses', 'syncQueue'], 'readwrite');

  await tx.objectStore('responses').put(response);

  // Add to sync queue if not synced
  if (!response.isSynced) {
    await tx.objectStore('syncQueue').add({
      type: 'response',
      action: response.id ? 'update' : 'create',
      data: response,
      timestamp: new Date(),
    });
  }

  await tx.done;
};

// Sync operations
export const getSyncQueue = async (): Promise<any[]> => {
  const db = await getDB();
  return db.getAll('syncQueue');
};

export const clearSyncQueue = async (): Promise<void> => {
  const db = await getDB();
  const tx = db.transaction('syncQueue', 'readwrite');
  await tx.objectStore('syncQueue').clear();
  await tx.done;
};

export const removeFromSyncQueue = async (id: number): Promise<void> => {
  const db = await getDB();
  const tx = db.transaction('syncQueue', 'readwrite');
  await tx.objectStore('syncQueue').delete(id);
  await tx.done;
};
