```typescript
// survey-app/src/services/syncService.ts
import { getSyncQueue, clearSyncQueue, removeFromSyncQueue } from './dbService';
import { Survey, SurveyResponse } from '../types';

const API_BASE_URL = 'https://api.yoursurveyapp.com';

interface SyncResult {
  success: boolean;
  message: string;
  syncedItems: number;
}

export const syncData = async (): Promise<SyncResult> => {
  if (!navigator.onLine) {
    return {
      success: false,
      message: 'No internet connection',
      syncedItems: 0,
    };
  }

  try {
    const queue = await getSyncQueue();
    let syncedItems = 0;

    for (const item of queue) {
      try {
        let response;

        switch (item.type) {
          case 'survey':
            if (item.action === 'create' || item.action === 'update') {
              response = await fetch(`${API_BASE_URL}/surveys`, {
                method: item.action === 'create' ? 'POST' : 'PUT',
                headers: {
                  'Content-Type': 'application/json',
                },
                body: JSON.stringify(item.data),
              });
            } else if (item.action === 'delete') {
              response = await fetch(`${API_BASE_URL}/surveys/${item.data.id}`, {
                method: 'DELETE',
              });
            }
            break;

          case 'response':
            if (item.action === 'create' || item.action === 'update') {
              response = await fetch(`${API_BASE_URL}/responses`, {
                method: item.action === 'create' ? 'POST' : 'PUT',
                headers: {
                  'Content-Type': 'application/json',
                },
                body: JSON.stringify(item.data),
              });
            } else if (item.action === 'delete') {
              response = await fetch(`${API_BASE_URL}/responses/${item.data.id}`, {
                method: 'DELETE',
              });
            }
            break;
        }

        if (response && response.ok) {
          // Mark as synced in local DB
          if (item.type === 'survey') {
            const survey: Survey = await response.json();
            survey.isSynced = true;
            // Update local DB
            // ... (implementation depends on your DB structure)
          } else if (item.type === 'response') {
            const resp: SurveyResponse = await response.json();
            resp.isSynced = true;
            // Update local DB
            // ... (implementation depends on your DB structure)
          }

          // Remove from sync queue
          await removeFromSyncQueue(item.id);
          syncedItems++;
        }
      } catch (error) {
        console.error('Error syncing item:', error);
        // Continue with next item
      }
    }

    return {
      success: true,
      message: `Synced ${syncedItems} items`,
      syncedItems,
    };
  } catch (error) {
    console.error('Sync error:', error);
    return {
      success: false,
      message: 'Sync failed',
      syncedItems: 0,
    };
  }
};

// Register service worker for background sync
export const registerSyncServiceWorker = async () => {
  if ('serviceWorker' in navigator && 'SyncManager' in window) {
    try {
      const registration = await navigator.serviceWorker.register('/sw.js');
      console.log('ServiceWorker registration successful');

      // Check for pending sync
      if (navigator.onLine) {
        const queue = await getSyncQueue();
        if (queue.length > 0) {
          await registration.sync.register('sync-data');
        }
      }
    } catch (error) {
      console.error('ServiceWorker registration failed:', error);
    }
  }
};
