// survey-app/src/hooks/useSync.ts
import { useState, useEffect } from 'react';
import { syncData, registerSyncServiceWorker } from '../services/syncService';
import { getSyncQueue } from '../services/dbService';

export const useSync = () => {
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [syncStatus, setSyncStatus] = useState({
    lastSync: null as Date | null,
    pendingChanges: 0,
    isSyncing: false,
  });

  useEffect(() => {
    // Register service worker for background sync
    registerSyncServiceWorker();

    // Set up online/offline listeners
    const handleOnline = () => {
      setIsOnline(true);
      checkPendingSync();
    };

    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Initial check
    checkPendingSync();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const checkPendingSync = async () => {
    const queue = await getSyncQueue();
    setSyncStatus(prev => ({
      ...prev,
      pendingChanges: queue.length,
    }));

    // If online and we have pending changes, trigger sync
    if (navigator.onLine && queue.length > 0) {
      performSync();
    }
  };

  const performSync = async () => {
    if (syncStatus.isSyncing) return;

    setSyncStatus(prev => ({ ...prev, isSyncing: true }));

    try {
      const result = await syncData();

      if (result.success) {
        setSyncStatus(prev => ({
          ...prev,
          lastSync: new Date(),
          pendingChanges: 0,
        }));
      } else {
        // If sync failed, check queue again
        checkPendingSync();
      }
    } catch (error) {
      console.error('Sync error:', error);
    } finally {
      setSyncStatus(prev => ({ ...prev, isSyncing: false }));
    }
  };

  return {
    isOnline,
    syncStatus,
    performSync,
    checkPendingSync,
  };
};
