    updatedAt: new Date(),
    isSynced: false,
    questions: [],
    responses: [],
  });
  const [isLoading, setIsLoading] = useState(false);
  const { isOnline } = useSync();

  useEffect(() => {
    if (surveyId) {
      loadSurvey();
    }
  }, [surveyId]);

  const loadSurvey = async () => {
    setIsLoading(true);
    try {
      const loadedSurvey = await getSurveyById(surveyId!);
      if (loadedSurvey) {
        setSurvey(loadedSurvey);
      }
    } catch (error) {
      console.error('Error loading survey:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

