// survey-app/src/components/ResponseForm.tsx
import React, { useState, useEffect } from 'react';
import { saveResponse, getSurveyById } from '../services/dbService';
import { Survey, SurveyResponse } from '../types';
import { useSync } from '../hooks/useSync';

interface ResponseFormProps {
  surveyId: string;
  onSave: () => void;
}

const ResponseForm: React.FC<ResponseFormProps> = ({ surveyId, onSave }) => {
  const [survey, setSurvey] = useState<Survey | null>(null);
  const [answers, setAnswers] = useState<Record<string, any>>({});
  const [isLoading, setIsLoading] = useState(false);
  const [location, setLocation] = useState<{ latitude: number; longitude: number } | null>(null);
  const { isOnline } = useSync();

  useEffect(() => {
    loadSurvey();
    getLocation();
  }, [surveyId]);

  const loadSurvey = async () => {
    setIsLoading(true);
    try {
      const loadedSurvey = await getSurveyById(surveyId);
      if (loadedSurvey) {
        setSurvey(loadedSurvey);
        // Initialize answers with empty values
        const initialAnswers: Record<string, any> = {};
        loadedSurvey.questions.forEach(question => {
          initialAnswers[question.id] = question.type === 'checkbox' ? [] : '';
        });
        setAnswers(initialAnswers);
      }
    } catch (error) {
      console.error('Error loading survey:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const getLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setLocation({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        (error) => {
          console.error('Error getting location:', error);
        }
      );
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const response: SurveyResponse = {
        id: Date.now().toString(),
        surveyId,
        userId: 'current-user-id', // Replace with actual user ID
        answers,
        timestamp: new Date(),
        location,
        isSynced: false,
      };

      await saveResponse(response);
      onSave();
    } catch (error) {
      console.error('Error saving response:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleAnswerChange = (questionId: string, value: any) => {
    setAnswers(prev => ({
      ...prev,
      [questionId]: value,
    }));
  };

  const handleCheckboxChange = (questionId: string, option: string) => {
    setAnswers(prev => {
      const currentValue = prev[questionId] || [];
      const newValue = currentValue.includes(option)
        ? currentValue.filter((item: string) => item !== option)
        : [...currentValue, option];

      return {
        ...prev,
        [questionId]: newValue,
      };
    });
  };

  if (isLoading) {
    return <div>Loading...</div>;
  }

  if (!survey) {
    return <div>Survey not found</div>;
  }

  return (
    <form onSubmit={handleSubmit} className="response-form">
      <h2>{survey.title}</h2>
      <p>{survey.description}</p>

      {survey.questions.map(question => (
        <div key={question.id} className="question-item">
          <label>
            {question.text}
            {question.required && <span className="required">*</span>}
          </label>

          {question.type === 'text' && (
            <input
              type="text"
              value={answers[question.id] || ''}
              onChange={(e) => handleAnswerChange(question.id, e.target.value)}
              required={question.required}
            />
          )}

          {question.type === 'number' && (
            <input
              type="number"
              value={answers[question.id] || ''}
              onChange={(e) => handleAnswerChange(question.id, e.target.value)}
              required={question.required}
            />
          )}

          {question.type === 'multiple-choice' && (
            <select
              value={answers[question.id] || ''}
              onChange={(e) => handleAnswerChange(question.id, e.target.value)}
              required={question.required}
            >
              <option value="">Select an option</option>
              {question.options?.map(option => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </select>
          )}

          {question.type === 'checkbox' && (
            <div className="checkbox-group">
              {question.options?.map(option => (
                <label key={option}>
                  <input
                    type="checkbox"
                    checked={(answers[question.id] || []).includes(option)}
                    onChange={() => handleCheckboxChange(question.id, option)}
                  />
                  {option}
                </label>
              ))}
            </div>
          )}
        </div>
      ))}

      <div className="form-actions">
        <button type="submit" disabled={isLoading}>
          {isLoading ? 'Submitting...' : 'Submit Response'}
        </button>
        {!isOnline && (
          <span className="offline-warning">
            Your response will be saved locally and synced when you're back online
          </span>
        )}
      </div>
    </form>
  );
};

export default ResponseForm;
