## Database Service (IndexedDB)

```typescript
// dbService.ts
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: {
      'by-status': string;
      'by-timestamp': string;
    };
  };
  syncQueue: {
    key: string;
    value: SyncQueueItem;
    indexes: {
      'by-timestamp': string;
    };
  };
}

const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;

export const initDB = async () => {
  return openDB<SurveyDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const store = db.createObjectStore('surveys', { keyPath: 'id' });
        store.createIndex('by-status', 'status');
        store.createIndex('by-timestamp', 'timestamp');
      }

      if (!db.objectStoreNames.contains('syncQueue')) {
        const store = db.createObjectStore('syncQueue', {
          keyPath: 'surveyId',
          autoIncrement: true
        });
        store.createIndex('by-timestamp', 'timestamp');
      }
    },
  });
};

export const getDB = async () => {
  return await initDB();
};

// Survey operations
export const addSurvey = async (survey: Survey) => {
  const db = await getDB();
  await db.add('surveys', survey);

  // Add to sync queue if not synced
  if (survey.status !== 'synced') {
    await addToSyncQueue({
      surveyId: survey.id,
      action: 'create',
      data: survey,
      timestamp: new Date().toISOString()
    });
  }
};

export const updateSurvey = async (survey: Survey) => {
  const db = await getDB();
  await db.put('surveys', survey);

  // Add to sync queue if not synced
  if (survey.status !== 'synced') {
    await addToSyncQueue({
      surveyId: survey.id,
      action: 'update',
      data: survey,
      timestamp: new Date().toISOString()
    });
  }
};

export const getSurveys = async (status?: 'pending' | 'synced' | 'failed') => {
  const db = await getDB();
  if (status) {
    return await db.getAllFromIndex('surveys', 'by-status', status);
  }
  return await db.getAll('surveys');
};

// Sync queue operations
export const addToSyncQueue = async (item: SyncQueueItem) => {
  const db = await getDB();
  await db.put('syncQueue', item);
};

export const getSyncQueue = async () => {
  const db = await getDB();
  return await db.getAll('syncQueue');
};

export const removeFromSyncQueue = async (surveyId: string) => {
  const db = await getDB();
  await db.delete('syncQueue', surveyId);
};
```

## Sync Service

```typescript
// syncService.ts
import { getSyncQueue, removeFromSyncQueue, updateSurvey } from './dbService';
import { Survey } from './types';

const API_BASE_URL = 'https://your-api-endpoint.com/api/surveys';

export const syncData = async () => {
  if (!navigator.onLine) {
    console.log('Offline - skipping sync');
    return;
  }

  const queue = await getSyncQueue();

  if (queue.length === 0) {
    console.log('No items to sync');
    return;
  }

  console.log(`Syncing ${queue.length} items...`);

  for (const item of queue) {
    try {
      let response;

      switch (item.action) {
        case 'create':
          response = await fetch(`${API_BASE_URL}`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(item.data),
          });
          break;
        case 'update':
          response = await fetch(`${API_BASE_URL}/${item.surveyId}`, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(item.data),
          });
          break;
        case 'delete':
          response = await fetch(`${API_BASE_URL}/${item.surveyId}`, {
            method: 'DELETE',
          });
          break;
      }

      if (response && response.ok) {
        // Update survey status to synced
        const updatedSurvey: Survey = {
          ...item.data,
          status: 'synced',
          lastModified: new Date().toISOString()
        };
        await updateSurvey(updatedSurvey);
        await removeFromSyncQueue(item.surveyId);
        console.log(`Synced survey ${item.surveyId}`);
      } else {
        throw new Error(`Failed to sync survey ${item.surveyId}`);
      }
    } catch (error) {
      console.error(`Error syncing survey ${item.surveyId}:`, error);
      // Update survey status to failed
      const failedSurvey: Survey = {
        ...item.data,
        status: 'failed',
        lastModified: new Date().toISOString()
      };
      await updateSurvey(failedSurvey);
    }
  }
};

// Set up periodic sync checks
export const setupSyncInterval = (intervalMs = 30000) => {
  setInterval(async () => {
    if (navigator.onLine) {
      await syncData();
    }
  }, intervalMs);
};

// Listen for online/offline events
export const setupNetworkListeners = () => {
  window.addEventListener('online', async () => {
    console.log('Back online - attempting sync');
    await syncData();
  });

  window.addEventListener('offline', () => {
    console.log('Offline - sync will resume when connection is restored');
  });
};
```

