  onSave: () => void;
}

const SurveyForm: React.FC<SurveyFormProps> = ({ initialSurvey, onSave }) => {
  const [survey, setSurvey] = useState<Survey>(initialSurvey || {
    id: Date.now().toString(),
    title: '',
    location: { latitude: 0, longitude: 0 },
    timestamp: new Date().toISOString(),
    data: {},
    status: 'pending',
    lastModified: new Date().toISOString()
  });

  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setSurvey(prev => ({
      ...prev,
      data: {
        ...prev.data,
        [name]: value
      },
      lastModified: new Date().toISOString()
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      if (initialSurvey) {
        await updateSurvey(survey);
      } else {
        await addSurvey(survey);
      }
      onSave();
    } catch (error) {
      console.error('Error saving survey:', error);
      alert('Failed to save survey. Please try again.');
    }
  };

  const getLocation = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          setSurvey(prev => ({
            ...prev,
            location: {
              latitude: position.coords.latitude,
              longitude: position.coords.longitude
            }
          }));
        },
        (error) => {
          console.error('Error getting location:', error);
          alert('Could not get your location. Please enable location services.');
        }
      );
    } else {
      alert('Geolocation is not supported by this browser.');
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>Title:</label>
        <input
          type="text"
          value={survey.title}
          onChange={(e) => setSurvey({ ...survey, title: e.target.value })}
          required
        />
      </div>

      <div>
        <label>Location:</label>
        <button type="button" onClick={getLocation}>
          Get Current Location
        </button>
        <div>
          Lat: {survey.location.latitude}, Long: {survey.location.longitude}
        </div>
      </div>

      {/* Example survey fields */}
      <div>
        <label>Observation:</label>
        <input
          type="text"
          name="observation"
          value={survey.data.observation || ''}
          onChange={handleChange}
        />
      </div>

      <div>
        <label>Notes:</label>
        <textarea
          name="notes"
          value={survey.data.notes || ''}
          onChange={handleChange}
        />
      </div>

      <button type="submit">Save Survey</button>

      <div className="status">
        Status: {survey.status}
        {!isOnline && <span> (Offline - changes will sync when connected)</span>}
      </div>
    </form>
  );
};

export default SurveyForm;
