const App = () => {
  const [surveys, setSurveys] = useState([]);
  const [newSurvey, setNewSurvey] = useState({
    id: '',
    location: '',
    notes: '',
    timestamp: '',
    isSynced: false
  });
  const [isConnected, setIsConnected] = useState(false);
  const [syncStatus, setSyncStatus] = useState('');

  // Initialize database tables
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'CREATE TABLE IF NOT EXISTS surveys (id TEXT PRIMARY KEY, location TEXT, notes TEXT, timestamp TEXT, isSynced INTEGER);'
      );
      tx.executeSql(
        'CREATE TABLE IF NOT EXISTS sync_queue (id TEXT PRIMARY KEY, action TEXT, data TEXT, timestamp TEXT);'
      );
    });

    // Load existing surveys
    loadSurveys();

    // Set up network listener
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  // Load surveys from database
  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys ORDER BY timestamp DESC',
        [],
        (_, { rows: { _array } }) => {
          setSurveys(_array.map(item => ({
            ...item,
            isSynced: item.isSynced === 1
          })));
        }
      );
    });
  };

  // Add a new survey (works offline)
  const addSurvey = () => {
    if (!newSurvey.location.trim()) {
      Alert.alert('Error', 'Please enter a location');
      return;
    }

    const surveyId = uuidv4();
    const timestamp = new Date().toISOString();

    const surveyToAdd = {
      id: surveyId,
      location: newSurvey.location,
      notes: newSurvey.notes,
      timestamp: timestamp,
      isSynced: false
    };

    db.transaction(tx => {
      tx.executeSql(
        'INSERT INTO surveys (id, location, notes, timestamp, isSynced) VALUES (?, ?, ?, ?, ?)',
        [surveyId, newSurvey.location, newSurvey.notes, timestamp, 0],
        () => {
          // Add to sync queue if not connected
          if (!isConnected) {
            tx.executeSql(
              'INSERT INTO sync_queue (id, action, data, timestamp) VALUES (?, ?, ?, ?)',
              [surveyId, 'create', JSON.stringify(surveyToAdd), timestamp]
            );
          }

          setSurveys([surveyToAdd, ...surveys]);
          setNewSurvey({ id: '', location: '', notes: '', timestamp: '', isSynced: false });
        },
        (_, error) => {
          console.error('Error adding survey:', error);
          Alert.alert('Error', 'Failed to save survey');
        }
      );
    });
  };

  // Sync data with server when connected
  const syncData = async () => {
    setSyncStatus('Syncing...');

    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM sync_queue ORDER BY timestamp ASC',
        [],
        async (_, { rows: { _array } }) => {
          if (_array.length === 0) {
            setSyncStatus('All data synced');
            return;
          }

          for (const item of _array) {
            try {
              // Simulate API call to server
              await simulateServerSync(item);

              // Remove from queue and mark as synced
              tx.executeSql('DELETE FROM sync_queue WHERE id = ?', [item.id]);
              tx.executeSql('UPDATE surveys SET isSynced = 1 WHERE id = ?', [item.id]);

              // Update local state
              setSurveys(prev => prev.map(survey =>
                survey.id === item.id ? { ...survey, isSynced: true } : survey
              ));
            } catch (error) {
              console.error('Sync error:', error);
              setSyncStatus('Sync partially completed with errors');
              break;
            }
          }

          setSyncStatus('Sync completed');
        }
      );
    });
  };

  // Simulate server sync (replace with actual API call)
  const simulateServerSync = async (item) => {
    return new Promise((resolve, reject) => {
