```typescript
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-date': Date };
  };
}

const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;

export const initDB = async () => {
  return openDB<SurveyDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const store = db.createObjectStore('surveys', { keyPath: 'id' });
        store.createIndex('by-date', 'createdAt');
      }
    },
  });
};

export const addSurvey = async (survey: Survey) => {
  const db = await initDB();
  await db.put('surveys', survey);
};

export const getAllSurveys = async (): Promise<Survey[]> => {
  const db = await initDB();
  return db.getAll('surveys');
};

export const getUnsyncedSurveys = async (): Promise<Survey[]> => {
  const db = await initDB();
  return db.getAllFromIndex('surveys', 'by-date', IDBKeyRange.lowerBound(0));
};

export const markAsSynced = async (id: string) => {
  const db = await initDB();
  const tx = db.transaction('surveys', 'readwrite');
  const survey = await tx.store.get(id);
  if (survey) {
    survey.isSynced = true;
    await tx.store.put(survey);
  }
  await tx.done;
};
