```typescript
import { getUnsyncedSurveys, markAsSynced } from './db';
import { syncSurveys } from './api';

export const syncData = async () => {
  if (!navigator.onLine) {
    console.log('Offline, skipping sync');
    return false;
  }

  try {
    const unsyncedSurveys = await getUnsyncedSurveys();
    if (unsyncedSurveys.length === 0) {
      console.log('No unsynced surveys');
      return true;
    }

    console.log(`Syncing ${unsyncedSurveys.length} surveys...`);
    const syncedSurveys = await syncSurveys(unsyncedSurveys);

    // Mark as synced in local DB
    for (const survey of syncedSurveys) {
      await markAsSynced(survey.id);
    }

    console.log('Sync completed successfully');
    return true;
  } catch (error) {
    console.error('Sync failed:', error);
    return false;
  }
};

// Set up periodic sync
export const setupPeriodicSync = (interval: number = 300000) => { // 5 minutes
  setInterval(async () => {
    if (navigator.onLine) {
      await syncData();
    }
  }, interval);
};
