### 3. Offline Data Hook (`useOfflineData.ts`)

```tsx
import { useState, useEffect, useCallback } from 'react';
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: SurveyData;
    indexes: { 'by-timestamp': string };
  };
}

export const useOfflineData = () => {
  const [surveys, setSurveys] = useState<SurveyData[]>([]);
  const [db, setDb] = useState<IDBPDatabase<SurveyDB> | null>(null);

  // Initialize database
  useEffect(() => {
    const initDB = async () => {
      const database = await openDB<SurveyDB>('FieldSurveyDB', 1, {
        upgrade(db) {
          const store = db.createObjectStore('surveys', {
            keyPath: 'id',
          });
          store.createIndex('by-timestamp', 'timestamp');
        },
      });
      setDb(database);
    };

    initDB();

    return () => {
      if (db) db.close();
    };
  }, []);

  // Load surveys from IndexedDB
  const loadSurveys = useCallback(async () => {
    if (!db) return;

    const tx = db.transaction('surveys', 'readonly');
    const store = tx.objectStore('surveys');
    const allSurveys = await store.getAll();
    setSurveys(allSurveys);
  }, [db]);

  useEffect(() => {
    if (db) {
      loadSurveys();
    }
  }, [db, loadSurveys]);

  // Add survey to IndexedDB
  const addSurvey = useCallback(async (survey: SurveyData) => {
    if (!db) throw new Error('Database not initialized');

    const tx = db.transaction('surveys', 'readwrite');
    const store = tx.objectStore('surveys');
    await store.put(survey);
    await loadSurveys();
  }, [db, loadSurveys]);

  // Sync data with server
  const syncData = useCallback(async () => {
    if (!db) return;

    const tx = db.transaction('surveys', 'readwrite');
    const store = tx.objectStore('surveys');
    const allSurveys = await store.getAll();

    if (allSurveys.length === 0) return;

    try {
      // Simulate API call to sync with server
      const response = await fetch('/api/sync-surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(allSurveys),
      });

      if (response.ok) {
        // Clear synced surveys from local storage
        const clearTx = db.transaction('surveys', 'readwrite');
        const clearStore = clearTx.objectStore('surveys');
        await Promise.all(allSurveys.map(survey => clearStore.delete(survey.id)));
        await loadSurveys();
      }
    } catch (error) {
      console.error('Sync failed:', error);
      // Implement retry logic or conflict resolution
    }
  }, [db, loadSurveys]);

  return {
    surveys,
    addSurvey,
    syncData,
  };
};
```

