    if (!isOnline) return 'Offline';
    if (lastSync) {
      const minutesAgo = Math.floor((Date.now() - lastSync.getTime()) / 60000);
      return `Last synced ${minutesAgo} minutes ago`;
    }
    return 'Ready to sync';
  };

  const getStatusColor = () => {
    if (isSyncing) return 'yellow';
    if (!isOnline) return 'red';
    return 'green';
  };

  return (
    <div className="sync-status" style={{ color: getStatusColor() }}>
      {getStatusText()}
    </div>
  );
};
