      const store = tx.objectStore('surveys');
      const allSurveys = await store.getAll();
      setSurveys(allSurveys);
    };

    loadSurveys();
  }, [db]);

  const addSurvey = useCallback(
    async (surveyData: SurveyData) => {
      if (!db) throw new Error('Database not initialized');

      const id = Date.now().toString();
      const surveyWithMeta = {
        ...surveyData,
        id,
        lastModified: Date.now(),
        isSynced: false,
      };

      const tx = db.transaction('surveys', 'readwrite');
      const store = tx.objectStore('surveys');
      await store.put(surveyWithMeta);
      await tx.done;

      setSurveys(prev => [...prev, surveyWithMeta]);
    },
    [db]
  );

  const syncData = useCallback(async () => {
    if (!db) throw new Error('Database not initialized');

    // Get unsynced surveys
    const tx = db.transaction('surveys', 'readonly');
    const store = tx.objectStore('surveys');
    const unsyncedSurveys = await store.getAll();
    const surveysToSync = unsyncedSurveys.filter(s => !s.isSynced);

    if (surveysToSync.length === 0) return;

    try {
      // Simulate API call to sync data
      const response = await fetch('/api/sync-surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(surveysToSync),
      });

      if (!response.ok) throw new Error('Sync failed');

      // Mark as synced
      const updateTx = db.transaction('surveys', 'readwrite');
      const updateStore = updateTx.objectStore('surveys');

      for (const survey of surveysToSync) {
        await updateStore.put({ ...survey, isSynced: true });
      }

      await updateTx.done;

      // Refresh local state
      const allSurveys = await store.getAll();
      setSurveys(allSurveys);
    } catch (error) {
      console.error('Sync error:', error);
      // Implement retry logic or show error to user
    }
  }, [db]);

  return { surveys, addSurvey, syncData };
};
