### 4. Service Worker for Background Sync (`service-worker.ts`)

```typescript
const CACHE_NAME = 'survey-app-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
  '/offline.html',
];

// Install service worker
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(ASSETS_TO_CACHE))
  );
});

// Activate service worker
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then(cacheNames => {
      return Promise.all(
        cacheNames.map(cache => {
          if (cache !== CACHE_NAME) {
            return caches.delete(cache);
          }
        })
      );
    })
  );
});

// Fetch with network falling back to cache
self.addEventListener('fetch', (event) => {
  event.respondWith(
    fetch(event.request)
      .catch(() => caches.match(event.request))
      .then(response => response || caches.match('/offline.html'))
  );
});

// Background sync
self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  const db = await openDB('surveyDB', 1);
  const tx = db.transaction('surveys', 'readonly');
  const store = tx.objectStore('surveys');
  const unsyncedSurveys = await store.getAll();

  if (unsyncedSurveys.length === 0) return;

  try {
    const response = await fetch('/api/sync-surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(unsyncedSurveys),
    });

    if (response.ok) {
      // Mark as synced
      const updateTx = db.transaction('surveys', 'readwrite');
      const updateStore = updateTx.objectStore('surveys');

      for (const survey of unsyncedSurveys) {
        await updateStore.put({ ...survey, isSynced: true });
      }

      await updateTx.done;
    }
  } catch (error) {
    console.error('Background sync failed:', error);
    // Implement retry logic
  }
}
