```typescript
// src/services/dbService.ts
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: SurveyData;
    indexes: { 'by-date': Date; 'by-status': string };
  };
}

interface SurveyData {
  id: string;
  title: string;
  location: {
    latitude: number;
    longitude: number;
  };
  data: any;
  status: 'pending' | 'synced' | 'error';
  createdAt: Date;
  updatedAt: Date;
}

let dbPromise: Promise<IDBPDatabase<SurveyDB>>;

export const initDB = async () => {
  dbPromise = openDB<SurveyDB>('FieldSurveyDB', 1, {
    upgrade(db) {
      const store = db.createObjectStore('surveys', {
        keyPath: 'id',
      });
      store.createIndex('by-date', 'createdAt');
      store.createIndex('by-status', 'status');
    },
  });
};

export const saveSurvey = async (survey: Omit<SurveyData, 'id' | 'createdAt' | 'updatedAt'>) => {
  const db = await dbPromise;
  const id = Date.now().toString();
  const timestamp = new Date();

  const surveyData: SurveyData = {
    id,
    ...survey,
    status: 'pending',
    createdAt: timestamp,
    updatedAt: timestamp,
  };

  await db.put('surveys', surveyData);
  return surveyData;
};

export const getAllSurveys = async () => {
  const db = await dbPromise;
  return db.getAll('surveys');
};

export const getPendingSurveys = async () => {
  const db = await dbPromise;
  return db.getAllFromIndex('surveys', 'by-status', 'pending');
};

export const updateSurveyStatus = async (id: string, status: SurveyData['status']) => {
  const db = await dbPromise;
  const survey = await db.get('surveys', id);
  if (survey) {
    survey.status = status;
    survey.updatedAt = new Date();
    await db.put('surveys', survey);
  }
};

export const syncData = async () => {
  const pendingSurveys = await getPendingSurveys();
  if (pendingSurveys.length === 0) return false;

  try {
    // Simulate API call to your backend
    const response = await fetch('https://your-api.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (response.ok) {
      // Update local status to 'synced'
      await Promise.all(
        pendingSurveys.map(survey =>
          updateSurveyStatus(survey.id, 'synced')
        )
      );
      return true;
    } else {
      // Mark as error if sync fails
      await Promise.all(
        pendingSurveys.map(survey =>
          updateSurveyStatus(survey.id, 'error')
        )
      );
      throw new Error('Sync failed');
    }
  } catch (error) {
    console.error('Sync error:', error);
    // Mark as error if network fails
    await Promise.all(
      pendingSurveys.map(survey =>
        updateSurveyStatus(survey.id, 'error')
      )
    );
    throw error;
  }
};
