## Service Worker for Background Sync

```javascript
// public/sw.js
const CACHE_NAME = 'field-survey-cache-v1';
const urlsToCache = [
  '/',
  '/index.html',
  '/static/js/bundle.js',
  '/static/css/main.css',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => {
        return cache.addAll(urlsToCache);
      })
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request)
      .then((response) => {
        // Cache hit - return response
        if (response) {
          return response;
        }

        // Clone the request
        const fetchRequest = event.request.clone();

        return fetch(fetchRequest).then(
          (response) => {
            // Check if we received a valid response
            if (!response || response.status !== 200 || response.type !== 'basic') {
              return response;
            }

            // Clone the response
            const responseToCache = response.clone();

            caches.open(CACHE_NAME)
              .then((cache) => {
                cache.put(event.request, responseToCache);
              });

            return response;
          }
        );
      })
  );
});

// Background sync for pending surveys
self.addEventListener('sync', (event) => {
  if (event.tag === 'sync-surveys') {
    event.waitUntil(syncSurveys());
  }
});

async function syncSurveys() {
  try {
    // Open the database
    const db = await openDB('FieldSurveyDB', 1);

    // Get pending surveys
    const tx = db.transaction('surveys', 'readwrite');
    const store = tx.objectStore('surveys');
    const index = store.index('by-status');
    const pendingSurveys = await index.getAll('pending');

    if (pendingSurveys.length === 0) return;

    // Try to sync with the server
    const response = await fetch('https://your-api.com/surveys', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(pendingSurveys),
    });

    if (response.ok) {
      // Update local status to 'synced'
      for (const survey of pendingSurveys) {
        survey.status = 'synced';
        survey.updatedAt = new Date();
        await store.put(survey);
      }
    } else {
      // Mark as error if sync fails
      for (const survey of pendingSurveys) {
        survey.status = 'error';
        survey.updatedAt = new Date();
        await store.put(survey);
      }
    }
  } catch (error) {
    console.error('Background sync failed:', error);
  }
}
