## Core Architecture

```javascript
// App.js - Main App Component
import React, { useEffect, useState } from 'react';
import { View, Text, Button, StyleSheet } from 'react-native';
import { createStackNavigator } from '@react-navigation/stack';
import { NavigationContainer } from '@react-navigation/native';
import NetInfo from '@react-native-community/netinfo';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';

const Stack = createStackNavigator();

// Survey Form Component
const SurveyForm = ({ navigation }) => {
  const [formData, setFormData] = useState({
    location: '',
    observations: '',
    timestamp: new Date().toISOString(),
    photos: []
  });

  const saveSurvey = async () => {
    try {
      // Save to local storage first
      const existingSurveys = await AsyncStorage.getItem('offlineSurveys');
      const surveys = existingSurveys ? JSON.parse(existingSurveys) : [];
      surveys.push(formData);
      await AsyncStorage.setItem('offlineSurveys', JSON.stringify(surveys));

      // Check network status
      const netInfo = await NetInfo.fetch();
      if (netInfo.isConnected) {
        await syncSurveys();
      }

      navigation.navigate('Home');
    } catch (error) {
      console.error('Error saving survey:', error);
    }
  };

  return (
    <View style={styles.container}>
      {/* Form inputs would go here */}
      <Button title="Save Survey" onPress={saveSurvey} />
    </View>
  );
};

// Home Screen Component
const HomeScreen = ({ navigation }) => {
  const [syncStatus, setSyncStatus] = useState('Not synced');

  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      if (state.isConnected) {
        syncSurveys();
      }
    });

    return () => unsubscribe();
  }, []);

  const syncSurveys = async () => {
    try {
      setSyncStatus('Syncing...');
      const offlineSurveys = await AsyncStorage.getItem('offlineSurveys');
      if (offlineSurveys) {
        const surveys = JSON.parse(offlineSurveys);

        // Send to server
        await axios.post('https://your-api-endpoint.com/surveys', surveys);

        // Clear local storage after successful sync
        await AsyncStorage.removeItem('offlineSurveys');
        setSyncStatus('Synced');
      }
    } catch (error) {
      console.error('Sync error:', error);
      setSyncStatus('Sync failed');
    }
  };

  return (
    <View style={styles.container}>
      <Text>Field Survey App</Text>
      <Text>Sync Status: {syncStatus}</Text>
      <Button
        title="New Survey"
        onPress={() => navigation.navigate('SurveyForm')}
      />
      <Button title="Sync Now" onPress={syncSurveys} />
    </View>
  );
};

