```typescript
// db.ts
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: {
      'by-date': Date;
      'by-sync-status': boolean;
    };
  };
  pendingSync: {
    key: string;
    value: {
      action: 'create' | 'update' | 'delete';
      data: Survey;
      timestamp: Date;
    };
  };
}

const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;

export const initDB = async () => {
  return openDB<SurveyDB>(DB_NAME, DB_VERSION, {
    upgrade(db) {
      if (!db.objectStoreNames.contains('surveys')) {
        const store = db.createObjectStore('surveys', { keyPath: 'id' });
        store.createIndex('by-date', 'createdAt');
        store.createIndex('by-sync-status', 'isSynced');
      }

      if (!db.objectStoreNames.contains('pendingSync')) {
        db.createObjectStore('pendingSync', { keyPath: 'id' });
      }
    },
  });
};

export const getAllSurveys = async (): Promise<Survey[]> => {
  const db = await initDB();
  return db.getAll('surveys');
};

export const getSurveyById = async (id: string): Promise<Survey | undefined> => {
  const db = await initDB();
  return db.get('surveys', id);
};

export const saveSurvey = async (survey: Survey): Promise<string> => {
  const db = await initDB();
  const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');

  // Update or add the survey
  await tx.objectStore('surveys').put(survey);

  // If not synced, add to pending sync queue
  if (!survey.isSynced) {
    await tx.objectStore('pendingSync').put({
      id: `sync-${Date.now()}`,
      action: survey.id.startsWith('temp-') ? 'create' : 'update',
      data: survey,
      timestamp: new Date(),
    });
  }

  await tx.done;
  return survey.id;
};

export const deleteSurvey = async (id: string): Promise<void> => {
  const db = await initDB();
  const tx = db.transaction(['surveys', 'pendingSync'], 'readwrite');

  // Delete from surveys
  await tx.objectStore('surveys').delete(id);

  // Add to pending sync if it was synced before
  const survey = await tx.objectStore('surveys').get(id);
  if (survey && survey.isSynced) {
    await tx.objectStore('pendingSync').put({
      id: `sync-${Date.now()}`,
      action: 'delete',
      data: survey,
      timestamp: new Date(),
    });
  }

  await tx.done;
};

export const getPendingSyncItems = async (): Promise<Array<{ id: string; action: string; data: Survey }>> => {
  const db = await initDB();
  return db.getAll('pendingSync');
};

export const clearPendingSyncItem = async (id: string): Promise<void> => {
  const db = await initDB();
  await db.delete('pendingSync', id);
};
