## Sync Service

```typescript
// syncService.ts
import { getPendingSyncItems, clearPendingSyncItem, saveSurvey } from './db';

const API_BASE_URL = 'https://your-api-endpoint.com/api';

export const syncData = async (): Promise<void> => {
  if (!navigator.onLine) {
    console.log('Offline - skipping sync');
    return;
  }

  const pendingItems = await getPendingSyncItems();

  for (const item of pendingItems) {
    try {
      let response;

      switch (item.action) {
        case 'create':
          response = await fetch(`${API_BASE_URL}/surveys`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(item.data),
          });
          break;

        case 'update':
          response = await fetch(`${API_BASE_URL}/surveys/${item.data.id}`, {
            method: 'PUT',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(item.data),
          });
          break;

        case 'delete':
          response = await fetch(`${API_BASE_URL}/surveys/${item.data.id}`, {
            method: 'DELETE',
          });
          break;
      }

      if (response && response.ok) {
        // Update local record to mark as synced
        if (item.action !== 'delete') {
          const updatedSurvey = await response.json();
          await saveSurvey({ ...updatedSurvey, isSynced: true });
        }

        // Remove from pending sync queue
        await clearPendingSyncItem(item.id);
      } else {
        console.error(`Failed to sync item ${item.id}: ${response?.statusText}`);
      }
    } catch (error) {
      console.error(`Error syncing item ${item.id}:`, error);
      // Could implement retry logic here
    }
  }
};

// Periodic sync check
export const setupPeriodicSync = (intervalMinutes = 5) => {
  setInterval(() => {
    if (navigator.onLine) {
      syncData();
    }
  }, intervalMinutes * 60 * 1000);
};
