const CACHE_NAME = 'field-survey-cache-v1';
const ASSETS_TO_CACHE = [
  '/',
  '/index.html',
  '/styles.css',
  '/app.js',
  '/manifest.json',
  // Add other essential assets
];

self.addEventListener('install', (event) => {
