const SurveyForm: React.FC<SurveyFormProps> = ({ surveyId }) => {
  const [survey, setSurvey] = useState<Survey | null>(null);
  const [responses, setResponses] = useState<Record<string, SurveyResponse>>({});
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const loadSurvey = async () => {
      if (surveyId) {
        const loadedSurvey = await getSurveyById(surveyId);
        if (loadedSurvey) {
          setSurvey(loadedSurvey);
          // Initialize responses
          const initialResponses: Record<string, SurveyResponse> = {};
          loadedSurvey.questions.forEach(q => {
            const existingResponse = loadedSurvey.responses.find(r => r.questionId === q.id);
            if (existingResponse) {
              initialResponses[q.id] = existingResponse;
            }
          });
          setResponses(initialResponses);
        }
      } else {
        // Create new survey
        const newSurvey: Survey = {
          id: `temp-${Date.now()}`,
          title: '',
          location: { latitude: 0, longitude: 0 },
          questions: [],
          responses: [],
          createdAt: new Date(),
          updatedAt: new Date(),
          isSynced: false,
        };
        setSurvey(newSurvey);
      }
    };

    loadSurvey();

    // Set up online/offline listeners
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, [surveyId]);

  const handleResponseChange = (questionId: string, value: any) => {
    setResponses(prev => ({
      ...prev,
      [questionId]: {
        questionId,
        value,
        timestamp: new Date(),
      },
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!survey) return;

    const updatedSurvey: Survey = {
      ...survey,
      responses: Object.values(responses),
      updatedAt: new Date(),
      isSynced: false, // Will be marked as synced after successful sync
    };

    await saveSurvey(updatedSurvey);

    // Request background sync if online
    if (navigator.onLine && 'serviceWorker' in navigator && 'SyncManager' in window) {
      try {
        const registration = await navigator.serviceWorker.ready;
        await registration.sync.register('sync-data');
      } catch (error) {
        console.error('Sync registration failed:', error);
      }
    }

    // Show feedback to user
    alert('Survey saved! Data will sync when connection is available.');
  };

  if (!survey) return <div>Loading...</div>;

  return (
    <form onSubmit={handleSubmit}>
      <h2>{survey.title || 'New Survey'}</h2>

      <div className="status">
        {isOnline ? '✅ Online' : '⚠️ Offline'}
      </div>

      {survey.questions.map(question => (
        <div key={question.id} className="question">
          <label>{question.text}</label>

          {question.type === 'text' && (
            <input
              type="text"
              value={responses[question.id]?.value || ''}
              onChange={(e) => handleResponseChange(question.id, e.target.value)}
            />
          )}

          {question.type === 'number' && (
            <input
              type="number"
              value={responses[question.id]?.value || ''}
              onChange={(e) => handleResponseChange(question.id, parseFloat(e.target.value))}
            />
          )}

          {question.type === 'boolean' && (
            <select
              value={responses[question.id]?.value || ''}
              onChange={(e) => handleResponseChange(question.id, e.target.value === 'true')}
            >
              <option value="">Select</option>
              <option value="true">Yes</option>
              <option value="false">No</option>
            </select>
          )}

          {question.type === 'multiple-choice' && (
            <select
              value={responses[question.id]?.value || ''}
              onChange={(e) => handleResponseChange(question.id, e.target.value)}
            >
              <option value="">Select</option>
              {question.options?.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
          )}
        </div>
      ))}

      <button type="submit">Save Survey</button>
    </form>
  );
};

export default SurveyForm;
