# Offline-First Field Surveying App Implementation

Below is an initial implementation of an offline-first field surveying application that syncs data when reconnected to the network. This implementation uses React with TypeScript and IndexedDB for local storage.

## Core Components

### 1. Database Service (IndexedDB)

```typescript
// src/services/database.ts
interface Survey {
  id: string;
  title: string;
  location: {
    latitude: number;
    longitude: number;
  };
  questions: {
    id: string;
    text: string;
    answer: string;
  }[];
  createdAt: Date;
  updatedAt: Date;
  isSynced: boolean;
}

class DatabaseService {
  private dbName = 'FieldSurveyDB';
  private storeName = 'surveys';
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(this.storeName)) {
          db.createObjectStore(this.storeName, { keyPath: 'id' });
        }
      };
    });
  }

  async getAllSurveys(): Promise<Survey[]> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(this.storeName, 'readonly');
      const store = transaction.objectStore(this.storeName);
      const request = store.getAll();

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
    });
  }

  async getSurvey(id: string): Promise<Survey | undefined> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(this.storeName, 'readonly');
      const store = transaction.objectStore(this.storeName);
      const request = store.get(id);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);
    });
  }

  async saveSurvey(survey: Survey): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(this.storeName, 'readwrite');
      const store = transaction.objectStore(this.storeName);
      const request = store.put(survey);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
    });
  }

  async deleteSurvey(id: string): Promise<void> {
    if (!this.db) await this.init();

    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(this.storeName, 'readwrite');
      const store = transaction.objectStore(this.storeName);
      const request = store.delete(id);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve();
    });
  }

  async getUnsyncedSurveys(): Promise<Survey[]> {
    const allSurveys = await this.getAllSurveys();
    return allSurveys.filter(survey => !survey.isSynced);
  }
}

export const dbService = new DatabaseService();
```

### 2. Sync Service

```typescript
// src/services/sync.ts
import { dbService } from './database';

class SyncService {
  private syncInterval: number = 60000; // 1 minute
  private syncTimeout: NodeJS.Timeout | null = null;

  constructor() {
    // Check for sync when app starts
    this.checkForSync();

    // Set up periodic sync checks
    this.setupPeriodicSync();
  }

  private setupPeriodicSync() {
    this.syncTimeout = setInterval(() => {
      this.checkForSync();
    }, this.syncInterval);
  }

  async checkForSync() {
    if (navigator.onLine) {
      const unsyncedSurveys = await dbService.getUnsyncedSurveys();

      if (unsyncedSurveys.length > 0) {
        await this.syncSurveys(unsyncedSurveys);
      }
    }
  }

  private async syncSurveys(surveys: Survey[]) {
    try {
      // In a real app, this would be your API endpoint
      const response = await fetch('https://api.example.com/surveys', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(surveys),
      });

      if (response.ok) {
        // Mark surveys as synced
        for (const survey of surveys) {
          survey.isSynced = true;
          await dbService.saveSurvey(survey);
        }
      }
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }

  cleanup() {
    if (this.syncTimeout) {
      clearInterval(this.syncTimeout);
    }
  }
}

export const syncService = new SyncService();
