```typescript
// src/App.tsx
import React, { useState, useEffect } from 'react';
import { dbService } from './services/database';
import { syncService } from './services/sync';

interface Survey {
  id: string;
  title: string;
  location: {
    latitude: number;
    longitude: number;
  };
  questions: {
    id: string;
    text: string;
    answer: string;
  }[];
  createdAt: Date;
  updatedAt: Date;
  isSynced: boolean;
}

const App: React.FC = () => {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [currentSurvey, setCurrentSurvey] = useState<Survey | null>(null);

  useEffect(() => {
    // Initialize database
    dbService.init().then(loadSurveys);

    // Set up online/offline listeners
    const handleOnline = () => {
      setIsOnline(true);
      syncService.checkForSync();
    };

    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      syncService.cleanup();
    };
  }, []);

  const loadSurveys = async () => {
    const loadedSurveys = await dbService.getAllSurveys();
    setSurveys(loadedSurveys);
  };

  const createNewSurvey = async () => {
    const newSurvey: Survey = {
      id: Date.now().toString(),
      title: `Survey ${new Date().toLocaleDateString()}`,
      location: { latitude: 0, longitude: 0 },
      questions: [],
      createdAt: new Date(),
      updatedAt: new Date(),
      isSynced: false,
    };

    await dbService.saveSurvey(newSurvey);
    setCurrentSurvey(newSurvey);
    await loadSurveys();
  };

  const saveSurvey = async (survey: Survey) => {
    survey.updatedAt = new Date();
    survey.isSynced = false;
    await dbService.saveSurvey(survey);
    setCurrentSurvey(survey);
    await loadSurveys();
  };

  const deleteSurvey = async (id: string) => {
    await dbService.deleteSurvey(id);
    if (currentSurvey?.id === id) {
      setCurrentSurvey(null);
    }
    await loadSurveys();
  };

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className={`status ${isOnline ? 'online' : 'offline'}`}>
          {isOnline ? 'Online' : 'Offline'}
        </div>
      </header>

      <main>
        {currentSurvey ? (
          <SurveyForm
            survey={currentSurvey}
            onSave={saveSurvey}
            onCancel={() => setCurrentSurvey(null)}
          />
        ) : (
          <div>
            <button onClick={createNewSurvey}>New Survey</button>
            <SurveyList
              surveys={surveys}
              onSelect={setCurrentSurvey}
              onDelete={deleteSurvey}
            />
          </div>
        )}
      </main>
    </div>
  );
};

interface SurveyFormProps {
  survey: Survey;
  onSave: (survey: Survey) => void;
  onCancel: () => void;
}

const SurveyForm: React.FC<SurveyFormProps> = ({ survey, onSave, onCancel }) => {
  const [title, setTitle] = useState(survey.title);
  const [questions, setQuestions] = useState(survey.questions);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...survey,
      title,
      questions,
    });
  };

  const addQuestion = () => {
    setQuestions([
      ...questions,
      {
        id: Date.now().toString(),
        text: '',
        answer: '',
      },
    ]);
  };

  const updateQuestion = (id: string, field: 'text' | 'answer', value: string) => {
    setQuestions(
      questions.map(q =>
        q.id === id ? { ...q, [field]: value } : q
      )
    );
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>Title:</label>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />
      </div>

      <div>
        <h3>Questions</h3>
        {questions.map(question => (
          <div key={question.id} className="question">
            <input
              type="text"
              placeholder="Question text"
              value={question.text}
              onChange={(e) => updateQuestion(question.id, 'text', e.target.value)}
              required
            />
            <input
              type="text"
              placeholder="Answer"
              value={question.answer}
              onChange={(e) => updateQuestion(question.id, 'answer', e.target.value)}
            />
          </div>
        ))}
        <button type="button" onClick={addQuestion}>Add Question</button>
      </div>

      <div className="form-actions">
        <button type="submit">Save</button>
        <button type="button" onClick={onCancel}>Cancel</button>
      </div>
    </form>
  );
};

interface SurveyListProps {
  surveys: Survey[];
  onSelect: (survey: Survey) => void;
  onDelete: (id: string) => void;
}

const SurveyList: React.FC<SurveyListProps> = ({ surveys, onSelect, onDelete }) => {
  return (
    <div className="survey-list">
      <h2>Saved Surveys</h2>
      {surveys.length === 0 ? (
        <p>No surveys yet. Create one to get started!</p>
      ) : (
        <ul>
          {surveys.map(survey => (
            <li key={survey.id}>
              <div>
                <strong>{survey.title}</strong>
                <span className={`sync-status ${survey.isSynced ? 'synced' : 'unsynced'}`}>
                  {survey.isSynced ? 'Synced' : 'Not synced'}
                </span>
              </div>
              <div className="survey-actions">
                <button onClick={() => onSelect(survey)}>Edit</button>
                <button onClick={() => onDelete(survey.id)}>Delete</button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default App;
