// services/storageService.js
import AsyncStorage from '@react-native-async-storage/async-storage';

const STORAGE_KEYS = {
  PENDING_SURVEYS: 'pendingSurveys',
  COMPLETED_SURVEYS: 'completedSurveys',
  LAST_SYNC_TIME: 'lastSyncTime'
};

export const saveSurveyLocally = async (surveyData) => {
  try {
    // Get existing surveys or initialize empty array
    const existingSurveys = await getLocalSurveys();
    existingSurveys.push(surveyData);

    // Save updated list
    await AsyncStorage.setItem(
      STORAGE_KEYS.PENDING_SURVEYS,
      JSON.stringify(existingSurveys)
    );

    return true;
  } catch (error) {
    console.error('Error saving survey locally:', error);
    return false;
  }
};

export const getLocalSurveys = async () => {
  try {
    const surveys = await AsyncStorage.getItem(STORAGE_KEYS.PENDING_SURVEYS);
    return surveys ? JSON.parse(surveys) : [];
  } catch (error) {
    console.error('Error getting local surveys:', error);
    return [];
  }
};

export const clearPendingSurveys = async () => {
  try {
    await AsyncStorage.removeItem(STORAGE_KEYS.PENDING_SURVEYS);
    return true;
  } catch (error) {
    console.error('Error clearing pending surveys:', error);
    return false;
  }
};

export const saveLastSyncTime = async (timestamp) => {
  try {
    await AsyncStorage.setItem(STORAGE_KEYS.LAST_SYNC_TIME, timestamp);
    return true;
  } catch (error) {
    console.error('Error saving sync time:', error);
    return false;
  }
};

export const getLastSyncTime = async () => {
  try {
    return await AsyncStorage.getItem(STORAGE_KEYS.LAST_SYNC_TIME);
  } catch (error) {
    console.error('Error getting sync time:', error);
    return null;
  }
};
