## API Sync Service

```javascript
// services/apiService.js
import { getLocalSurveys, clearPendingSurveys } from './storageService';

const API_BASE_URL = 'https://your-api-endpoint.com';

export const syncData = async () => {
  try {
    const pendingSurveys = await getLocalSurveys();

    if (pendingSurveys.length === 0) {
      return { success: true, message: 'No surveys to sync' };
    }

    // Send data to server
    const response = await fetch(`${API_BASE_URL}/surveys/sync`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${await getAuthToken()}`
      },
      body: JSON.stringify({ surveys: pendingSurveys })
    });

    if (!response.ok) {
      throw new Error('Sync failed');
    }

    // Clear local data after successful sync
    await clearPendingSurveys();

    return { success: true, message: 'Sync completed successfully' };
  } catch (error) {
    console.error('Sync error:', error);
    return { success: false, message: error.message };
  }
};

const getAuthToken = async () => {
  // Implement your authentication token retrieval logic
  return 'your-auth-token';
};
