// components/SyncStatus.js
import React from 'react';
import { View, Text, StyleSheet, TouchableOpacity } from 'react-native';
import Icon from 'react-native-vector-icons/MaterialIcons';

const SyncStatus = ({ isConnected, syncInProgress, lastSyncTime, onSync }) => {
  const formatTime = (isoString) => {
    if (!isoString) return 'Never';
    const date = new Date(isoString);
    return date.toLocaleTimeString();
  };

  return (
    <View style={styles.container}>
      <TouchableOpacity onPress={onSync} disabled={!isConnected || syncInProgress}>
        {syncInProgress ? (
          <Icon name="sync" size={24} color="#4CAF50" style={styles.spinner} />
        ) : (
          <Icon
            name={isConnected ? "sync" : "sync-disabled"}
            size={24}
            color={isConnected ? "#4CAF50" : "#9E9E9E"}
          />
        )}
      </TouchableOpacity>
      <Text style={styles.text}>
        {isConnected ? 'Connected' : 'Offline'} | Last sync: {formatTime(lastSyncTime)}
      </Text>
    </View>
  );
};

