```typescript
// services/LocalDatabase.ts
import { openDB, DBSchema } from 'idb';

interface SurveyDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-status': string; 'by-date': Date };
  };
}

export class LocalDatabase {
  private static instance: LocalDatabase;
  private dbPromise: Promise<IDBPDatabase<SurveyDB>>;

  private constructor() {
    this.dbPromise = openDB<SurveyDB>('FieldSurveyDB', 1, {
      upgrade(db) {
        const store = db.createObjectStore('surveys', { keyPath: 'id' });
        store.createIndex('by-status', 'status');
        store.createIndex('by-date', 'createdAt');
      },
    });
  }

  public static getInstance(): LocalDatabase {
    if (!LocalDatabase.instance) {
      LocalDatabase.instance = new LocalDatabase();
    }
    return LocalDatabase.instance;
  }

  async addSurvey(survey: Survey): Promise<string> {
    const db = await this.dbPromise;
    await db.put('surveys', survey);
    return survey.id;
  }

  async getSurveys(): Promise<Survey[]> {
    const db = await this.dbPromise;
    return db.getAll('surveys');
  }

  async getSurvey(id: string): Promise<Survey | undefined> {
    const db = await this.dbPromise;
    return db.get('surveys', id);
  }

  async updateSurvey(survey: Survey): Promise<void> {
    const db = await this.dbPromise;
    await db.put('surveys', survey);
  }

  async deleteSurvey(id: string): Promise<void> {
    const db = await this.dbPromise;
    await db.delete('surveys', id);
  }

  async getUnsyncedSurveys(): Promise<Survey[]> {
    const db = await this.dbPromise;
    return db.getAllFromIndex('surveys', 'by-status', 'draft');
  }
}
