### 3. Sync Service

```typescript
// services/SyncService.ts
import { LocalDatabase } from './LocalDatabase';

export class SyncService {
  private db: LocalDatabase;
  private syncInterval: number = 60000; // 1 minute
  private syncTimer: NodeJS.Timeout | null = null;

  constructor() {
    this.db = LocalDatabase.getInstance();
    this.setupNetworkListener();
  }

  private setupNetworkListener() {
    window.addEventListener('online', () => {
      console.log('Network connection restored. Starting sync...');
      this.syncData();
    });

    window.addEventListener('offline', () => {
      console.log('Network connection lost. Working offline.');
    });
  }

  public startPeriodicSync() {
    if (this.syncTimer) {
      clearInterval(this.syncTimer);
    }
    this.syncTimer = setInterval(() => {
      if (navigator.onLine) {
        this.syncData();
      }
    }, this.syncInterval);
  }

  public stopPeriodicSync() {
    if (this.syncTimer) {
      clearInterval(this.syncTimer);
      this.syncTimer = null;
    }
  }

  public async syncData(): Promise<void> {
    if (!navigator.onLine) {
      console.log('Cannot sync - offline');
      return;
    }

    try {
      const unsyncedSurveys = await this.db.getUnsyncedSurveys();

      if (unsyncedSurveys.length === 0) {
        console.log('No surveys to sync');
        return;
      }

      console.log(`Syncing ${unsyncedSurveys.length} surveys...`);

      // Simulate API call to sync data
      const response = await this.sendSurveysToServer(unsyncedSurveys);

      if (response.success) {
        // Mark surveys as synced
        for (const survey of unsyncedSurveys) {
          survey.isSynced = true;
          await this.db.updateSurvey(survey);
        }
        console.log('Sync completed successfully');
      } else {
        console.error('Sync failed:', response.error);
      }
    } catch (error) {
      console.error('Sync error:', error);
    }
  }

  private async sendSurveysToServer(surveys: Survey[]): Promise<{ success: boolean; error?: string }> {
    // In a real app, this would be an actual API call
    console.log('Sending surveys to server:', surveys);

    // Simulate network request
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({ success: true });
      }, 1000);
    });
  }
}
