## Backend (Node.js)

```javascript
// server.js
const express = require('express');
const bodyParser = require('body-parser');
const sqlite3 = require('sqlite3').verbose();

const app = express();
app.use(bodyParser.json());

// Initialize database
const db = new sqlite3.Database('./surveyData.db', (err) => {
  if (err) {
    console.error('Database connection error:', err.message);
  } else {
    console.log('Connected to the SQLite database.');
    initializeDatabase();
  }
});

function initializeDatabase() {
  db.run(`
    CREATE TABLE IF NOT EXISTS surveys (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      location TEXT NOT NULL,
      notes TEXT,
      status TEXT DEFAULT 'synced',
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      synced_at DATETIME
    )
  `);
}

// Sync endpoint
app.post('/sync', (req, res) => {
  const surveys = req.body.surveys;

  if (!surveys || !Array.isArray(surveys)) {
    return res.status(400).json({ success: false, message: 'Invalid data format' });
  }

  const stmt = db.prepare(`
    INSERT INTO surveys (location, notes, status, created_at, synced_at)
    VALUES (?, ?, ?, ?, datetime('now'))
  `);

  db.serialize(() => {
    db.run('BEGIN TRANSACTION');

    surveys.forEach(survey => {
      stmt.run(
        survey.location,
        survey.notes,
        'synced',
        survey.created_at
      );
    });

    stmt.finalize();

    db.run('COMMIT', (err) => {
      if (err) {
        db.run('ROLLBACK');
        console.error('Transaction error:', err);
        return res.status(500).json({ success: false, message: 'Database error' });
      }

      res.json({ success: true, message: 'Data synced successfully' });
    });
  });
});

// Get all surveys (for admin view)
app.get('/surveys', (req, res) => {
  db.all('SELECT * FROM surveys ORDER BY created_at DESC', [], (err, rows) => {
    if (err) {
      return res.status(500).json({ success: false, message: 'Database error' });
    }
    res.json({ success: true, surveys: rows });
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
