        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(survey),
      });

      if (response.ok) {
        await markAsSynced(db, survey.id);
      }
    } catch (error) {
      console.error('Failed to sync survey:', survey.id, error);
      // Continue with next survey even if one fails
    }
  }
};
