  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (' +
      'id INTEGER PRIMARY KEY AUTOINCREMENT,' +
      'title TEXT,' +
      'description TEXT,' +
      'created_at DATETIME DEFAULT CURRENT_TIMESTAMP,' +
      'is_synced INTEGER DEFAULT 0' +
      ');'
    );
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS survey_questions (' +
      'id INTEGER PRIMARY KEY AUTOINCREMENT,' +
      'survey_id INTEGER,' +
      'question TEXT,' +
      'answer_type TEXT,' +
      'options TEXT,' +
      'FOREIGN KEY(survey_id) REFERENCES surveys(id)' +
      ');'
    );
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS survey_responses (' +
      'id INTEGER PRIMARY KEY AUTOINCREMENT,' +
      'survey_id INTEGER,' +
      'question_id INTEGER,' +
      'response TEXT,' +
      'created_at DATETIME DEFAULT CURRENT_TIMESTAMP,' +
      'is_synced INTEGER DEFAULT 0,' +
      'FOREIGN KEY(survey_id) REFERENCES surveys(id),' +
      'FOREIGN KEY(question_id) REFERENCES survey_questions(id)' +
      ');'
    );
  });
};

// Survey Screen
const SurveyScreen = ({ navigation }) => {
  const [surveys, setSurveys] = useState([]);
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    initializeDatabase();
    loadSurveys();
    checkConnection();

    // Set up network listener
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncData();
      }
    });

    return () => unsubscribe();
  }, []);

  const loadSurveys = () => {
    db.transaction(tx => {
      tx.executeSql('SELECT * FROM surveys ORDER BY created_at DESC', [], (tx, results) => {
        const rows = results.rows.raw();
        setSurveys(rows);
      });
    });
  };

  const checkConnection = async () => {
    const state = await NetInfo.fetch();
    setIsConnected(state.isConnected);
  };

  const syncData = async () => {
    try {
      // Get unsynced surveys
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE is_synced = 0',
          [],
          async (tx, results) => {
            const unsyncedSurveys = results.rows.raw();
            if (unsyncedSurveys.length > 0) {
              // Simulate API call to sync data
              await fetch('https://api.example.com/sync-surveys', {
                method: 'POST',
                headers: {
                  'Content-Type': 'application/json',
                },
                body: JSON.stringify(unsyncedSurveys),
              });

              // Mark as synced
              tx.executeSql('UPDATE surveys SET is_synced = 1 WHERE is_synced = 0');
            }
          }
        );
      });

      // Get unsynced responses
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM survey_responses WHERE is_synced = 0',
          [],
          async (tx, results) => {
            const unsyncedResponses = results.rows.raw();
            if (unsyncedResponses.length > 0) {
              // Simulate API call to sync data
              await fetch('https://api.example.com/sync-responses', {
                method: 'POST',
                headers: {
                  'Content-Type': 'application/json',
                },
                body: JSON.stringify(unsyncedResponses),
              });

              // Mark as synced
              tx.executeSql('UPDATE survey_responses SET is_synced = 1 WHERE is_synced = 0');
            }
          }
        );
      });
    } catch (error) {
      console.error('Sync error:', error);
    }
  };

  return (
