          <Text>{survey.title}</Text>
          <Text>{survey.description}</Text>
          <Text style={survey.is_synced ? styles.synced : styles.notSynced}>
            {survey.is_synced ? 'Synced' : 'Pending'}
          </Text>
          <Button
            title="View Responses"
            onPress={() => navigation.navigate('SurveyResponses', { surveyId: survey.id })}
          />
        </View>
      ))}
    </View>
  );
};

