## Database Layer (IndexedDB)

```typescript
// db.ts - IndexedDB implementation
class SurveyDatabase {
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('FieldSurveyDB', 1);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Create object stores
        if (!db.objectStoreNames.contains('surveys')) {
          db.createObjectStore('surveys', { keyPath: 'id' });
        }

        if (!db.objectStoreNames.contains('responses')) {
          db.createObjectStore('responses', { keyPath: 'id' });
        }

        if (!db.objectStoreNames.contains('syncQueue')) {
          db.createObjectStore('syncQueue', { keyPath: 'id' });
        }
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  async getSurveys(): Promise<Survey[]> {
    return this._getAll<Survey>('surveys');
  }

  async saveSurvey(survey: Survey): Promise<void> {
    await this._put('surveys', survey);
  }

  async saveResponse(response: SurveyResponse): Promise<void> {
    await this._put('responses', response);
    await this._addToSyncQueue(response.id, 'response');
  }

  async getUnsyncedResponses(): Promise<SurveyResponse[]> {
    const responses = await this._getAll<SurveyResponse>('responses');
    return responses.filter(r => !r.isSynced);
  }

  async markAsSynced(ids: string[], type: 'survey' | 'response'): Promise<void> {
    const storeName = type === 'survey' ? 'surveys' : 'responses';
    const tx = this.db!.transaction(storeName, 'readwrite');
    const store = tx.objectStore(storeName);

    for (const id of ids) {
      const request = store.get(id);
      request.onsuccess = () => {
        const item = request.result;
        if (item) {
          item.isSynced = true;
          store.put(item);
        }
      };
    }

    return new Promise((resolve, reject) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }

  private async _getAll<T>(storeName: string): Promise<T[]> {
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction(storeName, 'readonly');
      const store = tx.objectStore(storeName);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  private async _put(storeName: string, item: any): Promise<void> {
    return new Promise((resolve, reject) => {
      const tx = this.db!.transaction(storeName, 'readwrite');
      const store = tx.objectStore(storeName);
      const request = store.put(item);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }

  private async _addToSyncQueue(id: string, type: 'survey' | 'response'): Promise<void> {
    const queueItem = {
      id: `${type}-${id}-${Date.now()}`,
      type,
      referenceId: id,
      timestamp: new Date()
    };

    await this._put('syncQueue', queueItem);
  }
}
