## Sync Manager

```typescript
// sync.ts - Sync management
class SyncManager {
  private db: SurveyDatabase;
  private apiUrl: string;
  private syncInterval: number;
  private syncTimeout: NodeJS.Timeout | null = null;

  constructor(db: SurveyDatabase, apiUrl: string, syncInterval = 30000) {
    this.db = db;
    this.apiUrl = apiUrl;
    this.syncInterval = syncInterval;
  }

  startPeriodicSync(): void {
    this.sync();
    this.syncTimeout = setInterval(() => this.sync(), this.syncInterval);
  }

  stopPeriodicSync(): void {
    if (this.syncTimeout) {
      clearInterval(this.syncTimeout);
      this.syncTimeout = null;
    }
  }

  async sync(): Promise<void> {
    if (!navigator.onLine) {
      console.log('Offline - skipping sync');
      return;
    }

    try {
      // Sync surveys (download new/updated surveys)
      await this.syncSurveys();

      // Sync responses (upload unsynced responses)
      await this.syncResponses();
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }

  private async syncSurveys(): Promise<void> {
    // Get last sync timestamp from local storage
    const lastSync = localStorage.getItem('lastSurveySync');
    const params = lastSync ? `?since=${lastSync}` : '';

    const response = await fetch(`${this.apiUrl}/surveys${params}`);
    if (!response.ok) throw new Error('Failed to fetch surveys');

    const surveys: Survey[] = await response.json();

    if (surveys.length > 0) {
      // Save new/updated surveys to local DB
      for (const survey of surveys) {
        await this.db.saveSurvey(survey);
      }

      // Update last sync timestamp
      localStorage.setItem('lastSurveySync', new Date().toISOString());
    }
  }

  private async syncResponses(): Promise<void> {
    const unsyncedResponses = await this.db.getUnsyncedResponses();

    if (unsyncedResponses.length === 0) return;

    const response = await fetch(`${this.apiUrl}/responses`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(unsyncedResponses),
    });

    if (!response.ok) throw new Error('Failed to sync responses');

    // Mark responses as synced in local DB
    const syncedIds = unsyncedResponses.map(r => r.id);
    await this.db.markAsSynced(syncedIds, 'response');
  }
}
