// components/SurveyForm.tsx
import React, { useState } from 'react';
import { Survey, SurveyResponse } from '../types';
import { SurveyDatabase } from '../db';

interface SurveyFormProps {
  survey: Survey;
  db: SurveyDatabase;
  onComplete: () => void;
}

export const SurveyForm: React.FC<SurveyFormProps> = ({ survey, db, onComplete }) => {
  const [responses, setResponses] = useState<Record<string, any>>({});
  const [location, setLocation] = useState<GeolocationPosition | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (questionId: string, value: any) => {
    setResponses(prev => ({ ...prev, [questionId]: value }));
  };

  const handleLocationCapture = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (position) => setLocation(position),
        (error) => console.error('Error getting location:', error)
      );
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const response: SurveyResponse = {
        id: crypto.randomUUID(),
        surveyId: survey.id,
        responses,
        location: location ? {
          latitude: location.coords.latitude,
          longitude: location.coords.longitude,
          accuracy: location.coords.accuracy
        } : undefined,
        timestamp: new Date(),
        isSynced: false
      };

      await db.saveResponse(response);
      onComplete();
    } catch (error) {
      console.error('Failed to save response:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="survey-form">
      <h2>{survey.title}</h2>
      <p>{survey.description}</p>

      {survey.questions.map(question => (
        <div key={question.id} className="question">
          <label>
            {question.text}
            {question.required && <span className="required">*</span>}
          </label>

          {question.type === 'text' && (
            <input
              type="text"
              value={responses[question.id] || ''}
              onChange={(e) => handleChange(question.id, e.target.value)}
              required={question.required}
            />
          )}

          {question.type === 'number' && (
            <input
              type="number"
              value={responses[question.id] || ''}
              onChange={(e) => handleChange(question.id, e.target.value)}
              required={question.required}
            />
          )}

          {question.type === 'radio' && question.options && (
            <div className="radio-group">
              {question.options.map(option => (
                <label key={option}>
                  <input
                    type="radio"
                    name={question.id}
                    value={option}
                    checked={responses[question.id] === option}
                    onChange={() => handleChange(question.id, option)}
                    required={question.required}
                  />
                  {option}
                </label>
              ))}
            </div>
          )}

          {question.type === 'checkbox' && question.options && (
            <div className="checkbox-group">
              {question.options.map(option => (
                <label key={option}>
                  <input
                    type="checkbox"
                    checked={responses[question.id]?.includes(option) || false}
                    onChange={(e) => {
                      const current = responses[question.id] || [];
                      const newValue = e.target.checked
                        ? [...current, option]
                        : current.filter((item: string) => item !== option);
                      handleChange(question.id, newValue);
                    }}
                  />
                  {option}
                </label>
              ))}
            </div>
          )}

          {question.type === 'photo' && (
            <div className="photo-upload">
              <input
                type="file"
                accept="image/*"
                capture="environment"
                onChange={(e) => {
                  if (e.target.files && e.target.files[0]) {
                    const file = e.target.files[0];
                    // Handle file upload (could be stored in IndexedDB or converted to base64)
                    handleChange(question.id, URL.createObjectURL(file));
                  }
                }}
              />
              {responses[question.id] && (
                <img
                  src={responses[question.id]}
                  alt="Preview"
                  style={{ maxWidth: '100%', maxHeight: '200px' }}
                />
              )}
            </div>
          )}
        </div>
      ))}

      <div className="location-section">
        <button type="button" onClick={handleLocationCapture}>
          Capture Location
