import React, { useEffect, useState } from 'react';
import { SurveyDatabase } from './db';
import { SyncManager } from './sync';
import { SurveyList } from './components/SurveyList';
import { SurveyForm } from './components/SurveyForm';

const API_URL = 'https://api.yoursurveyapp.com';

export const App: React.FC = () => {
  const [db, setDb] = useState<SurveyDatabase | null>(null);
  const [syncManager, setSyncManager] = useState<SyncManager | null>(null);
  const [currentSurvey, setCurrentSurvey] = useState<Survey | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    // Initialize database and sync manager
    const initialize = async () => {
      const database = new SurveyDatabase();
      await database.init();
      setDb(database);

      const manager = new SyncManager(database, API_URL);
      manager.startPeriodicSync();
      setSyncManager(manager);

      // Set up online/offline event listeners
      window.addEventListener('online', () => {
        setIsOnline(true);
        manager.sync();
      });

      window.addEventListener('offline', () => setIsOnline(false));

      return () => {
        manager.stopPeriodicSync();
        window.removeEventListener('online', () => {});
        window.removeEventListener('offline', () => {});
      };
    };

    initialize();
  }, []);

  const handleSurveyComplete = () => {
    setCurrentSurvey(null);
  };

  if (!db) return <div>Initializing app...</div>;

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className={`status ${isOnline ? 'online' : 'offline'}`}>
          {isOnline ? 'Online' : 'Offline'}
