## Database Layer (IndexedDB)

```typescript
// db.ts - IndexedDB wrapper
class SurveyDatabase {
  private db: IDBDatabase | null = null;

  async init(): Promise<void> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open('FieldSurveyDB', 1);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        if (!db.objectStoreNames.contains('surveys')) {
          db.createObjectStore('surveys', { keyPath: 'id' });
        }

        if (!db.objectStoreNames.contains('responses')) {
          db.createObjectStore('responses', { keyPath: 'id' });
        }
      };

      request.onsuccess = () => {
        this.db = request.result;
        resolve();
      };

      request.onerror = () => reject(request.error);
    });
  }

  async getSurveys(): Promise<Survey[]> {
    return this.getAll<Survey>('surveys');
  }

  async getResponses(): Promise<Response[]> {
    return this.getAll<Response>('responses');
  }

  async saveSurvey(survey: Survey): Promise<void> {
    await this.save('surveys', survey);
  }

  async saveResponse(response: Response): Promise<void> {
    await this.save('responses', response);
  }

  async markAsSynced(ids: string[], storeName: 'surveys' | 'responses'): Promise<void> {
    const transaction = this.db!.transaction(storeName, 'readwrite');
    const store = transaction.objectStore(storeName);

    for (const id of ids) {
      const request = store.get(id);
      request.onsuccess = () => {
        const item = request.result;
        if (item) {
          item.isSynced = true;
          store.put(item);
        }
      };
    }

    return new Promise((resolve, reject) => {
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error);
    });
  }

  private async getAll<T>(storeName: string): Promise<T[]> {
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(storeName, 'readonly');
      const store = transaction.objectStore(storeName);
      const request = store.getAll();

      request.onsuccess = () => resolve(request.result as T[]);
      request.onerror = () => reject(request.error);
    });
  }

  private async save<T extends { id: string }>(storeName: string, item: T): Promise<void> {
    return new Promise((resolve, reject) => {
      const transaction = this.db!.transaction(storeName, 'readwrite');
      const store = transaction.objectStore(storeName);
      const request = store.put(item);

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  }
}
