## Sync Manager

```typescript
// sync.ts - Sync manager
class SyncManager {
  private db: SurveyDatabase;
  private apiUrl: string;
  private syncInterval: number = 30000; // 30 seconds
  private isSyncing: boolean = false;

  constructor(db: SurveyDatabase, apiUrl: string) {
    this.db = db;
    this.apiUrl = apiUrl;
  }

  async startSync(): Promise<void> {
    // Initial sync
    await this.syncData();

    // Set up periodic sync
    setInterval(() => this.syncData(), this.syncInterval);

    // Listen for online status changes
    window.addEventListener('online', () => this.syncData());
  }

  private async syncData(): Promise<void> {
    if (this.isSyncing || !navigator.onLine) return;

    this.isSyncing = true;

    try {
      // Sync surveys
      const unsyncedSurveys = (await this.db.getSurveys()).filter(s => !s.isSynced);
      if (unsyncedSurveys.length > 0) {
        await this.syncSurveys(unsyncedSurveys);
      }

      // Sync responses
      const unsyncedResponses = (await this.db.getResponses()).filter(r => !r.isSynced);
      if (unsyncedResponses.length > 0) {
        await this.syncResponses(unsyncedResponses);
      }
    } catch (error) {
      console.error('Sync failed:', error);
    } finally {
      this.isSyncing = false;
    }
  }

  private async syncSurveys(surveys: Survey[]): Promise<void> {
    const response = await fetch(`${this.apiUrl}/surveys`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(surveys)
    });

    if (response.ok) {
      const syncedIds = surveys.map(s => s.id);
      await this.db.markAsSynced(syncedIds, 'surveys');
    }
  }

  private async syncResponses(responses: Response[]): Promise<void> {
    // Handle file uploads first
    const responsesWithFiles = responses.filter(r =>
      r.answers.some(a => a.value instanceof File)
    );

    if (responsesWithFiles.length > 0) {
      await this.uploadFiles(responsesWithFiles);
    }

    // Then sync all responses
    const response = await fetch(`${this.apiUrl}/responses`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(responses)
    });

    if (response.ok) {
      const syncedIds = responses.map(r => r.id);
      await this.db.markAsSynced(syncedIds, 'responses');
    }
  }

  private async uploadFiles(responses: Response[]): Promise<void> {
    for (const response of responses) {
      for (const answer of response.answers) {
        if (answer.value instanceof File) {
          const formData = new FormData();
          formData.append('file', answer.value);

          const uploadResponse = await fetch(`${this.apiUrl}/uploads`, {
            method: 'POST',
            body: formData
          });

          if (uploadResponse.ok) {
            const { fileId } = await uploadResponse.json();
            answer.value = fileId; // Replace file with reference ID
          }
        }
      }
    }
  }
}
