Below is a conceptual implementation of an offline-first field surveying app with sync capabilities. This example uses React Native for the mobile interface, but the core concepts can be adapted to other platforms.

## Core Architecture

```javascript
// App.js - Main application structure
import React, { useEffect, useState } from 'react';
import { View, Text, Button, StyleSheet } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { createStackNavigator } from '@react-navigation/stack';
import AsyncStorage from '@react-native-async-storage/async-storage';
import NetInfo from '@react-native-community/netinfo';

// Database setup
import { openDatabase } from 'react-native-sqlite-storage';
const db = openDatabase({ name: 'surveyApp.db' });

// Survey screens
import SurveyListScreen from './screens/SurveyListScreen';
import SurveyFormScreen from './screens/SurveyFormScreen';
import SyncScreen from './screens/SyncScreen';

// API service
import { syncData } from './services/apiService';

const Stack = createStackNavigator();

const App = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [syncStatus, setSyncStatus] = useState('idle');

  // Initialize database
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'CREATE TABLE IF NOT EXISTS surveys (' +
        'id INTEGER PRIMARY KEY AUTOINCREMENT, ' +
        'title TEXT, ' +
        'description TEXT, ' +
        'location TEXT, ' +
        'data JSON, ' +
        'status TEXT DEFAULT "pending", ' +
        'created_at DATETIME DEFAULT CURRENT_TIMESTAMP, ' +
        'updated_at DATETIME DEFAULT CURRENT_TIMESTAMP' +
        ');'
      );
    });
  }, []);

  // Network status monitoring
  useEffect(() => {
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncPendingData();
      }
    });

    return () => unsubscribe();
  }, []);

  // Sync pending data when online
  const syncPendingData = async () => {
    try {
      setSyncStatus('syncing');
      const pendingSurveys = await getPendingSurveys();

      for (const survey of pendingSurveys) {
        await syncData(survey);
        await updateSurveyStatus(survey.id, 'synced');
      }

      setSyncStatus('success');
    } catch (error) {
      console.error('Sync error:', error);
      setSyncStatus('error');
    }
  };

  // Database operations
  const getPendingSurveys = () => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE status = ?',
          ['pending'],
          (tx, results) => {
            const surveys = [];
            for (let i = 0; i < results.rows.length; i++) {
              surveys.push(results.rows.item(i));
            }
            resolve(surveys);
          },
          (error) => reject(error)
        );
      });
    });
  };

  const updateSurveyStatus = (id, status) => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'UPDATE surveys SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?',
          [status, id],
          (tx, results) => resolve(results),
          (error) => reject(error)
        );
      });
    });
  };

  return (
    <NavigationContainer>
      <Stack.Navigator>
        <Stack.Screen
          name="SurveyList"
          component={SurveyListScreen}
