## Sync Screen

```javascript
// screens/SyncScreen.js
import React, { useState, useEffect } from 'react';
import { View, Text, Button, StyleSheet, ActivityIndicator } from 'react-native';
import { openDatabase } from 'react-native-sqlite-storage';
import { syncData } from '../services/apiService';

const db = openDatabase({ name: 'surveyApp.db' });

const SyncScreen = ({ navigation }) => {
  const [syncStatus, setSyncStatus] = useState('idle');
  const [progress, setProgress] = useState(0);
  const [pendingCount, setPendingCount] = useState(0);

  useEffect(() => {
    checkPendingSurveys();
  }, []);

  const checkPendingSurveys = () => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT COUNT(*) as count FROM surveys WHERE status = ?',
        ['pending'],
        (tx, results) => {
          setPendingCount(results.rows.item(0).count);
        },
        (error) => console.error('Error checking pending surveys:', error)
      );
    });
  };

  const startSync = async () => {
    setSyncStatus('syncing');
    setProgress(0);

    try {
      const pendingSurveys = await getPendingSurveys();
      const total = pendingSurveys.length;

      for (let i = 0; i < total; i++) {
        const survey = pendingSurveys[i];
        await syncData(survey);
        await updateSurveyStatus(survey.id, 'synced');
        setProgress(Math.round(((i + 1) / total) * 100));
      }

      setSyncStatus('success');
      checkPendingSurveys();
    } catch (error) {
      console.error('Sync error:', error);
      setSyncStatus('error');
    }
  };

  const getPendingSurveys = () => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE status = ?',
          ['pending'],
          (tx, results) => {
            const surveys = [];
            for (let i = 0; i < results.rows.length; i++) {
              surveys.push(results.rows.item(i));
            }
            resolve(surveys);
          },
          (error) => reject(error)
        );
      });
    });
  };

  const updateSurveyStatus = (id, status) => {
    return new Promise((resolve, reject) => {
      db.transaction(tx => {
        tx.executeSql(
          'UPDATE surveys SET status = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?',
          [status, id],
          (tx, results) => resolve(results),
          (error) => reject(error)
        );
      });
    });
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Data Synchronization</Text>

      <View style={styles.statusContainer}>
        <Text style={styles.statusLabel}>Pending Surveys:</Text>
        <Text style={styles.statusValue}>{pendingCount}</Text>
      </View>

      {syncStatus === 'syncing' && (
        <View style={styles.progressContainer}>
          <ActivityIndicator size="large" color="#4CAF50" />
          <Text style={styles.progressText}>{progress}% Complete</Text>
        </View>
      )}

      {syncStatus === 'success' && (
        <Text style={styles.successText}>Sync completed successfully!</Text>
      )}

      {syncStatus === 'error' && (
        <Text style={styles.errorText}>Sync failed. Please try again.</Text>
      )}

      <Button
        title="Start Sync"
        onPress={startSync}
        disabled={syncStatus === 'syncing' || pendingCount === 0}
      />

      <Button
        title="Back to Surveys"
        onPress={() => navigation.goBack()}
        color="#999"
      />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 16,
    justifyContent: 'center',
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 20,
    textAlign: 'center',
  },
  statusContainer: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 20,
