## Database Service Implementation

```javascript
// services/database.js
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';

const DB_KEY = '@surveys';
const SYNC_QUEUE_KEY = '@syncQueue';

// Initialize database
export const initDB = async () => {
  try {
    const surveys = await AsyncStorage.getItem(DB_KEY);
    if (!surveys) {
      await AsyncStorage.setItem(DB_KEY, JSON.stringify([]));
    }
  } catch (error) {
    console.error('Database initialization failed:', error);
  }
};

// Save survey offline
export const saveSurveyOffline = async (surveyData) => {
  try {
    // Add timestamp for offline tracking
    const surveyWithMeta = {
      ...surveyData,
      _id: Date.now().toString(),
      _isOffline: true,
      _lastModified: new Date().toISOString()
    };

    // Get existing surveys
    const existingSurveys = await getAllSurveys();

    // Add new survey
    const updatedSurveys = [...existingSurveys, surveyWithMeta];

    // Save to local storage
    await AsyncStorage.setItem(DB_KEY, JSON.stringify(updatedSurveys));

    // Add to sync queue if not connected
    const netInfo = await NetInfo.fetch();
    if (!netInfo.isConnected) {
      const syncQueue = await AsyncStorage.getItem(SYNC_QUEUE_KEY);
      const queue = syncQueue ? JSON.parse(syncQueue) : [];
      queue.push(surveyWithMeta._id);
      await AsyncStorage.setItem(SYNC_QUEUE_KEY, JSON.stringify(queue));
    }

    return surveyWithMeta;
  } catch (error) {
    console.error('Failed to save survey offline:', error);
    throw error;
  }
};

// Get all surveys (both online and offline)
export const getAllSurveys = async () => {
  try {
    const surveys = await AsyncStorage.getItem(DB_KEY);
    return surveys ? JSON.parse(surveys) : [];
  } catch (error) {
    console.error('Failed to get surveys:', error);
    return [];
  }
};

// Sync with server
export const syncWithServer = async () => {
  try {
    // Get sync queue
    const syncQueue = await AsyncStorage.getItem(SYNC_QUEUE_KEY);
    const queue = syncQueue ? JSON.parse(syncQueue) : [];

    if (queue.length === 0) return;

    // Get all surveys
    const allSurveys = await getAllSurveys();

    // Process each item in queue
    const newQueue = [];
    for (const surveyId of queue) {
      const survey = allSurveys.find(s => s._id === surveyId);
      if (survey) {
        try {
          // Send to server
          const response = await axios.post('https://api.example.com/surveys', survey);

          // If successful, remove from local storage and mark as synced
          if (response.status === 200 || response.status === 201) {
            const updatedSurveys = allSurveys.map(s =>
              s._id === surveyId ? { ...s, _isOffline: false } : s
            );
            await AsyncStorage.setItem(DB_KEY, JSON.stringify(updatedSurveys));
          } else {
            newQueue.push(surveyId);
          }
        } catch (error) {
          console.error('Failed to sync survey:', surveyId, error);
          newQueue.push(surveyId);
        }
      }
    }

    // Update sync queue
    await AsyncStorage.setItem(SYNC_QUEUE_KEY, JSON.stringify(newQueue));
  } catch (error) {
    console.error('Sync process failed:', error);
    throw error;
  }
};
