## Local Database (IndexedDB)

```javascript
class LocalDatabase {
  constructor() {
    this.dbName = 'FieldSurveyDB';
    this.version = 1;
    this.db = null;
  }

  async init() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(this.dbName, this.version);

      request.onupgradeneeded = (event) => {
        const db = event.target.result;

        // Create object stores
        if (!db.objectStoreNames.contains('surveys')) {
          const surveyStore = db.createObjectStore('surveys', { keyPath: 'id' });
          surveyStore.createIndex('status', 'status', { unique: false });
          surveyStore.createIndex('lastModified', 'lastModified', { unique: false });
        }

        if (!db.objectStoreNames.contains('syncQueue')) {
          db.createObjectStore('syncQueue', { keyPath: 'id' });
        }
      };

      request.onsuccess = (event) => {
        this.db = event.target.result;
        resolve();
      };

      request.onerror = (event) => {
        reject(event.target.error);
      };
    });
  }

  async saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(['surveys'], 'readwrite');
      const store = transaction.objectStore('surveys');

      const request = store.put({
        ...surveyData,
        status: 'pending',
        lastModified: new Date().toISOString()
      });

      request.onsuccess = () => resolve(request.result);
      request.onerror = (event) => reject(event.target.error);
    });
  }

  async getSurveys(statusFilter = null) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(['surveys'], 'readonly');
      const store = transaction.objectStore('surveys');

      let request;
      if (statusFilter) {
        const index = store.index('status');
        request = index.getAll(statusFilter);
      } else {
        request = store.getAll();
      }

      request.onsuccess = () => resolve(request.result);
      request.onerror = (event) => reject(event.target.error);
    });
  }

  async addToSyncQueue(surveyId) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(['syncQueue'], 'readwrite');
      const store = transaction.objectStore('syncQueue');

      const request = store.put({
        id: surveyId,
        timestamp: new Date().toISOString()
      });

      request.onsuccess = () => resolve();
      request.onerror = (event) => reject(event.target.error);
    });
  }

  async getSyncQueue() {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(['syncQueue'], 'readonly');
      const store = transaction.objectStore('syncQueue');

      const request = store.getAll();

      request.onsuccess = () => resolve(request.result);
      request.onerror = (event) => reject(event.target.error);
    });
  }

  async removeFromSyncQueue(surveyId) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(['syncQueue'], 'readwrite');
      const store = transaction.objectStore('syncQueue');

      const request = store.delete(surveyId);

      request.onsuccess = () => resolve();
      request.onerror = (event) => reject(event.target.error);
    });
  }

  async updateSurveyStatus(surveyId, status) {
    return new Promise((resolve, reject) => {
      const transaction = this.db.transaction(['surveys'], 'readwrite');
      const store = transaction.objectStore('surveys');

      const getRequest = store.get(surveyId);

      getRequest.onsuccess = () => {
        const survey = getRequest.result;
        survey.status = status;
        survey.lastModified = new Date().toISOString();

        const updateRequest = store.put(survey);

        updateRequest.onsuccess = () => resolve();
        updateRequest.onerror = (event) => reject(event.target.error);
      };

      getRequest.onerror = (event) => reject(event.target.error);
    });
  }
}
```

## Sync Manager

```javascript
class SyncManager {
  constructor(db) {
    this.db = db;
    this.apiEndpoint = 'https://api.example.com/surveys';
    this.syncInterval = 30000; // 30 seconds
    this.isSyncing = false;
  }

  async sync() {
    if (this.isSyncing) return;

    this.isSyncing = true;

    try {
      const queue = await this.db.getSyncQueue();

      if (queue.length === 0) {
        this.isSyncing = false;
        return;
      }

      for (const item of queue) {
        try {
          const survey = await this.db.getSurveyById(item.id);

          if (survey.status === 'pending') {
            const response = await fetch(this.apiEndpoint, {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
              },
              body: JSON.stringify(survey)
            });

            if (response.ok) {
              await this.db.updateSurveyStatus(item.id, 'synced');
              await this.db.removeFromSyncQueue(item.id);
            } else {
              // Handle retry logic or partial sync
              console.warn(`Failed to sync survey ${item.id}, will retry`);
            }
          }
        } catch (error) {
          console.error(`Error syncing survey ${item.id}:`, error);
          // Continue with next item
        }
      }
    } finally {
      this.isSyncing = false;
    }
  }

  async scheduleSync() {
    setInterval(() => this.sync(), this.syncInterval);
  }

  async handleOnline() {
    await this.sync();
    this.scheduleSync();
  }

  async handleOffline() {
    // Stop scheduled syncs when offline
    clearInterval(this.syncInterval);
  }
}
