    // Initialize database
    initDB();

    // Check network status
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
      if (state.isConnected) {
        syncPendingSurveys();
      }
    });

    // Load pending surveys count
    getAllSurveys().then(surveys => {
