// services/database.js
import { openDatabase } from 'react-native-sqlite-storage';

const db = openDatabase({ name: 'surveys.db', location: 'default' });

export const initDB = () => {
  db.transaction(tx => {
    tx.executeSql(
      `CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        location TEXT,
        notes TEXT,
        photos TEXT,
        timestamp TEXT,
        synced BOOLEAN DEFAULT 0
      );`,
      [],
      () => console.log('Database initialized'),
      error => console.error('Error initializing database:', error)
    );
  });
};

export const saveSurveyOffline = (survey) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys (location, notes, photos, timestamp, synced)
         VALUES (?, ?, ?, ?, ?)`,
        [
          survey.location,
          survey.notes,
          JSON.stringify(survey.photos),
          survey.timestamp,
          survey.synced ? 1 : 0
        ],
        (_, result) => resolve(result),
        (_, error) => reject(error)
      );
    });
  });
};

export const getAllSurveys = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys',
        [],
        (_, result) => {
          const surveys = [];
          for (let i = 0; i < result.rows.length; i++) {
            const item = result.rows.item(i);
            surveys.push({
              ...item,
              photos: JSON.parse(item.photos),
              synced: item.synced === 1
            });
          }
          resolve(surveys);
        },
        (_, error) => reject(error)
      );
    });
  });
};

export const syncSurveys = async () => {
  const surveys = await getAllSurveys();
  const unsynced = surveys.filter(s => !s.synced);

  for (const survey of unsynced) {
    try {
      await uploadSurvey(survey);
      await saveSurveyOffline({ ...survey, synced: true });
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }
};
