```typescript
// db.ts
import { openDB, DBSchema } from 'idb';

interface SurveyAppDB extends DBSchema {
  surveys: {
    key: string;
    value: Survey;
    indexes: { 'by-date': Date };
  };
  responses: {
    key: string;
    value: SurveyResponse;
    indexes: { 'by-survey': string; 'by-date': Date };
  };
}

const dbPromise = openDB<SurveyAppDB>('SurveyAppDB', 1, {
  upgrade(db) {
    const surveysStore = db.createObjectStore('surveys', { keyPath: 'id' });
    surveysStore.createIndex('by-date', 'createdAt');

    const responsesStore = db.createObjectStore('responses', { keyPath: 'id' });
    responsesStore.createIndex('by-survey', 'surveyId');
    responsesStore.createIndex('by-date', 'timestamp');
  },
});

export async function getSurveys(): Promise<Survey[]> {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function getSurvey(id: string): Promise<Survey | undefined> {
  const db = await dbPromise;
  return db.get('surveys', id);
}

export async function saveSurvey(survey: Survey): Promise<void> {
  const db = await dbPromise;
  await db.put('surveys', survey);
}

export async function getResponses(surveyId?: string): Promise<SurveyResponse[]> {
  const db = await dbPromise;
  if (surveyId) {
    return db.getAllFromIndex('responses', 'by-survey', surveyId);
  }
  return db.getAll('responses');
}

export async function saveResponse(response: SurveyResponse): Promise<void> {
  const db = await dbPromise;
  await db.put('responses', response);
}

export async function getUnsyncedData(): Promise<{
  surveys: Survey[];
  responses: SurveyResponse[];
}> {
  const db = await dbPromise;
  const surveys = await db.getAll('surveys');
  const responses = await db.getAll('responses');

  return {
    surveys: surveys.filter(s => !s.isSynced),
    responses: responses.filter(r => !r.isSynced),
  };
}

export async function markAsSynced(ids: { surveys?: string[]; responses?: string[] }): Promise<void> {
  const db = await dbPromise;

  if (ids.surveys) {
    const tx = db.transaction('surveys', 'readwrite');
    for (const id of ids.surveys) {
      const survey = await tx.store.get(id);
      if (survey) {
        survey.isSynced = true;
        await tx.store.put(survey);
      }
    }
    await tx.done;
  }

  if (ids.responses) {
    const tx = db.transaction('responses', 'readwrite');
    for (const id of ids.responses) {
      const response = await tx.store.get(id);
      if (response) {
        response.isSynced = true;
        await tx.store.put(response);
      }
    }
    await tx.done;
  }
}
