```typescript
// syncService.ts
import { getUnsyncedData, markAsSynced } from './db';

const API_BASE_URL = 'https://api.yoursurveyapp.com';

export async function syncData(): Promise<void> {
  if (!navigator.onLine) {
    console.log('No internet connection, skipping sync');
    return;
  }

  try {
    const unsyncedData = await getUnsyncedData();

    // Sync surveys first (if needed)
    if (unsyncedData.surveys.length > 0) {
      const response = await fetch(`${API_BASE_URL}/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(unsyncedData.surveys),
      });

      if (response.ok) {
        await markAsSynced({
          surveys: unsyncedData.surveys.map(s => s.id),
        });
      }
    }

    // Sync responses
    if (unsyncedData.responses.length > 0) {
      const response = await fetch(`${API_BASE_URL}/responses`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(unsyncedData.responses),
      });

      if (response.ok) {
        await markAsSynced({
          responses: unsyncedData.responses.map(r => r.id),
        });
      }
    }

    console.log('Sync completed successfully');
  } catch (error) {
    console.error('Sync failed:', error);
    throw error;
  }
}

// Set up periodic sync
export function setupPeriodicSync(intervalMinutes: number = 5): void {
  setInterval(() => {
    if (navigator.onLine) {
      syncData().catch(console.error);
    }
  }, intervalMinutes * 60 * 1000);

  // Also sync when coming back online
  window.addEventListener('online', () => {
    syncData().catch(console.error);
  });
}
