## Sync Manager

```javascript
class SyncManager {
  constructor(db) {
    this.db = db;
    this.apiEndpoint = 'https://api.example.com/surveys';
    this.isSyncing = false;
  }

  async sync() {
    if (this.isSyncing) return;

    this.isSyncing = true;

    try {
      const queue = await this.db.getSyncQueue();

      if (queue.length === 0) {
        this.isSyncing = false;
        return;
      }

      for (const item of queue) {
        try {
          const response = await fetch(this.apiEndpoint, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify(item.data),
          });

          if (response.ok) {
            // Remove from queue if successful
            await this.db.removeFromSyncQueue(item.id);
          } else {
            // Keep in queue for retry
            console.warn('Sync failed for item', item.id);
          }
        } catch (error) {
          console.error('Sync error:', error);
          // Keep in queue for retry
        }
      }
    } finally {
      this.isSyncing = false;
    }
  }

  async queueForSync(data) {
    await this.db.addToSyncQueue(data);
    await this.sync(); // Try immediate sync
  }
}
