    } catch (error) {
      console.error('Sync error:', error);
      throw error;
    }
  },

  // Periodic sync check
  startPeriodicSync: (interval = 300000) => { // 5 minutes default
    const syncInterval = setInterval(async () => {
      const isConnected = await NetInfo.fetch().then(state => state.isConnected);
      if (isConnected) {
        const hasUnsyncedData = await SyncManager.checkForUnsyncedData();
        if (hasUnsyncedData) {
          await SyncManager.syncData();
        }
      }
    }, interval);

    return () => clearInterval(syncInterval);
  }
};

// Helper functions
const getUnsyncedResponses = () => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM survey_responses WHERE is_synced = 0',
        [],
        (tx, results) => {
          const responses = [];
          for (let i = 0; i < results.rows.length; i++) {
            responses.push(results.rows.item(i));
          }
          resolve(responses);
        },
        (error) => {
          reject(error);
        }
      );
    });
  });
};

const markResponsesAsSynced = (responseIds) => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE survey_responses SET is_synced = 1, synced_at = CURRENT_TIMESTAMP WHERE id IN (${responseIds.join(',')})`,
        [],
        () => resolve(),
        (error) => reject(error)
      );
    });
  });
};

// Main App Component
const App = () => {
  const [isConnected, setIsConnected] = useState(false);
  const [hasUnsyncedData, setHasUnsyncedData] = useState(false);

  useEffect(() => {
    // Initialize database
    initDatabase();

    // Set up network listener
    const unsubscribe = NetInfo.addEventListener(state => {
      setIsConnected(state.isConnected);
    });

    // Check for unsynced data periodically
    const checkUnsyncedInterval = setInterval(async () => {
      const hasData = await SyncManager.checkForUnsyncedData();
      setHasUnsyncedData(hasData);
    }, 5000);

    // Start periodic sync
    const stopSync = SyncManager.startPeriodicSync();

    return () => {
      unsubscribe();
      clearInterval(checkUnsyncedInterval);
      stopSync();
    };
  }, []);

  const handleManualSync = async () => {
    if (!isConnected) {
      alert('No internet connection');
      return;
    }

    try {
      await SyncManager.syncData();
      alert('Sync completed successfully');
      setHasUnsyncedData(false);
    } catch (error) {
