          {hasUnsyncedData && isConnected && ' - Unsynced data available'}
        </Text>
        {hasUnsyncedData && isConnected && (
          <Button title="Sync Now" onPress={handleManualSync} />
        )}
      </View>
    </NavigationContainer>
  );
};

