### 2. Network Sync Service

```javascript
// syncService.js
import { getUnsyncedSurveys, getUnsyncedResponses, markAsSynced } from './database';
import NetInfo from '@react-native-community/netinfo';

const API_BASE_URL = 'https://your-api-endpoint.com/api';

export const syncData = async () => {
  try {
    const state = await NetInfo.fetch();
    if (!state.isConnected) return false;

    // Sync surveys
    const unsyncedSurveys = await getUnsyncedSurveys();
    if (unsyncedSurveys.length > 0) {
      const response = await fetch(`${API_BASE_URL}/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(unsyncedSurveys),
      });

      if (response.ok) {
        const syncedIds = unsyncedSurveys.map(survey => survey.id);
        await markAsSynced('surveys', syncedIds);
      }
    }

    // Sync responses
    const unsyncedResponses = await getUnsyncedResponses();
    if (unsyncedResponses.length > 0) {
      const response = await fetch(`${API_BASE_URL}/responses`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(unsyncedResponses),
      });

      if (response.ok) {
        const syncedIds = unsyncedResponses.map(resp => resp.id);
        await markAsSynced('survey_responses', syncedIds);
      }
    }

    return true;
  } catch (error) {
    console.error('Sync error:', error);
    return false;
  }
};

// Set up periodic sync checks
export const setupSyncListener = () => {
  NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncData();
    }
  });

  // Also check periodically in case network state changes weren't detected
  setInterval(() => {
    NetInfo.fetch().then(state => {
      if (state.isConnected) {
        syncData();
      }
    });
  }, 300000); // Check every 5 minutes
};
```

