## Sync Manager

```typescript
// sync.ts - Sync manager
class SyncManager {
  private db: SurveyDatabase;
  private apiUrl: string;
  private syncInterval: number = 30000; // 30 seconds
  private syncTimeout: NodeJS.Timeout | null = null;

  constructor(db: SurveyDatabase, apiUrl: string) {
    this.db = db;
    this.apiUrl = apiUrl;
  }

  startSync(): void {
    this.sync();
    this.scheduleNextSync();
  }

  stopSync(): void {
    if (this.syncTimeout) {
      clearTimeout(this.syncTimeout);
      this.syncTimeout = null;
    }
  }

  private scheduleNextSync(): void {
    this.syncTimeout = setTimeout(() => {
      this.sync();
      this.scheduleNextSync();
    }, this.syncInterval);
  }

  private async sync(): Promise<void> {
    if (!navigator.onLine) return;

    try {
      // Sync surveys
      const unsyncedSurveys = (await this.db.getSurveys()).filter(s => !s.isSynced);
      if (unsyncedSurveys.length > 0) {
        await this.uploadSurveys(unsyncedSurveys);
      }

      // Sync responses
      const unsyncedResponses = (await this.db.getResponses()).filter(r => !r.isSynced);
      if (unsyncedResponses.length > 0) {
        await this.uploadResponses(unsyncedResponses);
      }

      // Download any new surveys from server
      await this.downloadSurveys();
    } catch (error) {
      console.error('Sync failed:', error);
    }
  }

  private async uploadSurveys(surveys: Survey[]): Promise<void> {
    const response = await fetch(`${this.apiUrl}/surveys`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(surveys)
    });

    if (response.ok) {
      const syncedIds = surveys.map(s => s.id);
      await this.db.markAsSynced(syncedIds, 'surveys');
    }
  }

  private async uploadResponses(responses: SurveyResponse[]): Promise<void> {
    const response = await fetch(`${this.apiUrl}/responses`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(responses)
    });

    if (response.ok) {
      const syncedIds = responses.map(r => r.id);
      await this.db.markAsSynced(syncedIds, 'responses');
    }
  }

  private async downloadSurveys(): Promise<void> {
    const response = await fetch(`${this.apiUrl}/surveys`);
    if (response.ok) {
      const surveys = await response.json();
      for (const survey of surveys) {
        await this.db.saveSurvey({
          ...survey,
          isSynced: true
        });
      }
    }
  }
}
