const SurveyForm: React.FC<SurveyFormProps> = ({ survey, db, onComplete }) => {
  const [responses, setResponses] = useState<Record<string, any>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (questionId: string, value: any) => {
    setResponses(prev => ({
      ...prev,
      [questionId]: value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      const response: SurveyResponse = {
        id: crypto.randomUUID(),
        surveyId: survey.id,
        responses,
        createdAt: new Date(),
        updatedAt: new Date(),
        isSynced: false
      };

      await db.saveResponse(response);
      onComplete();
    } catch (error) {
      console.error('Error saving response:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>{survey.title}</h2>
      <p>{survey.description}</p>

      {survey.questions.map(question => (
        <div key={question.id} className="question">
          <label>
            {question.text}
            {question.required && <span className="required">*</span>}
          </label>

          {question.type === 'text' && (
            <input
              type="text"
              value={responses[question.id] || ''}
              onChange={(e) => handleChange(question.id, e.target.value)}
              required={question.required}
            />
          )}

          {question.type === 'number' && (
            <input
              type="number"
              value={responses[question.id] || ''}
              onChange={(e) => handleChange(question.id, e.target.value)}
              required={question.required}
            />
          )}

          {question.type === 'multiple-choice' && (
            <select
              value={responses[question.id] || ''}
              onChange={(e) => handleChange(question.id, e.target.value)}
              required={question.required}
            >
              <option value="">Select an option</option>
              {question.options?.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
          )}

          {question.type === 'photo' && (
            <input
              type="file"
              accept="image/*"
              onChange={(e) => {
                if (e.target.files && e.target.files[0]) {
                  const reader = new FileReader();
                  reader.onload = () => {
                    handleChange(question.id, reader.result);
                  };
                  reader.readAsDataURL(e.target.files[0]);
                }
              }}
              required={question.required}
            />
          )}
        </div>
      ))}

      <button type="submit" disabled={isSubmitting}>
        {isSubmitting ? 'Submitting...' : 'Submit Survey'}
      </button>
    </form>
  );
};

export default SurveyForm;
```

## App Initialization

```tsx
// App.tsx - Main app component
import React, { useEffect, useState } from 'react';
import { SurveyDatabase } from './db';
import { SyncManager } from './sync';
import SurveyList from './SurveyList';
import SurveyForm from './SurveyForm';

const App: React.FC = () => {
  const [db, setDb] = useState<SurveyDatabase | null>(null);
  const [syncManager, setSyncManager] = useState<SyncManager | null>(null);
  const [selectedSurvey, setSelectedSurvey] = useState<Survey | null>(null);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  useEffect(() => {
    const initializeApp = async () => {
      const database = new SurveyDatabase();
      await database.init();
      setDb(database);

      const manager = new SyncManager(database, 'https://api.example.com');
      manager.startSync();
      setSyncManager(manager);
    };

    initializeApp();

    // Set up online/offline event listeners
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      syncManager?.stopSync();
    };
  }, []);

  if (!db) return <div>Initializing app...</div>;

  return (
    <div className="app">
      <header>
        <h1>Field Survey App</h1>
        <div className={`connection-status ${isOnline ? 'online' : 'offline'}`}>
          {isOnline ? 'Online' : 'Offline'}
        </div>
      </header>

      <main>
        {selectedSurvey ? (
          <SurveyForm
            survey={selectedSurvey}
            db={db}
            onComplete={() => setSelectedSurvey(null)}
          />
        ) : (
          <SurveyList db={db} />
        )}
      </main>
    </div>
  );
};

export default App;
