```javascript
// Database setup
let db;
const DB_NAME = 'FieldSurveyDB';
const STORE_NAME = 'surveys';
const SYNC_STORE_NAME = 'syncQueue';

const initDB = () => {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject('Database error');
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve();
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
            if (!db.objectStoreNames.contains(SYNC_STORE_NAME)) {
                db.createObjectStore(SYNC_STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
};

// Save survey to IndexedDB
const saveSurvey = (survey) => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.add(survey);

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject('Error saving survey: ' + event.target.error);
        };
    });
};

// Get all surveys from IndexedDB
const getSurveys = () => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject('Error getting surveys: ' + event.target.error);
        };
    });
};

// Add survey to sync queue
const addToSyncQueue = (survey) => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([SYNC_STORE_NAME], 'readwrite');
        const store = transaction.objectStore(SYNC_STORE_NAME);
        const request = store.add(survey);

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject('Error adding to sync queue: ' + event.target.error);
        };
    });
};

// Get all items from sync queue
const getSyncQueue = () => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([SYNC_STORE_NAME], 'readonly');
        const store = transaction.objectStore(SYNC_STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject('Error getting sync queue: ' + event.target.error);
        };
    });
};

// Remove item from sync queue
const removeFromSyncQueue = (id) => {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([SYNC_STORE_NAME], 'readwrite');
        const store = transaction.objectStore(SYNC_STORE_NAME);
        const request = store.delete(id);

        request.onsuccess = () => {
            resolve();
        };

        request.onerror = (event) => {
            reject('Error removing from sync queue: ' + event.target.error);
        };
    });
};

// Simulate API call to sync data
const syncData = async () => {
    const statusElement = document.getElementById('status');
    statusElement.textContent = 'Syncing data...';
    statusElement.className = 'status syncing';

    try {
        const queue = await getSyncQueue();

        if (queue.length === 0) {
            statusElement.textContent = 'No data to sync';
            statusElement.className = 'status online';
            return;
        }

        // Simulate API call (in a real app, this would be a fetch to your server)
        await new Promise(resolve => setTimeout(resolve, 1000));

        // In a real app, you would process the queue and send data to server
        // For this demo, we'll just clear the queue
        for (const item of queue) {
            await removeFromSyncQueue(item.id);
        }

        statusElement.textContent = `Synced ${queue.length} surveys`;
        statusElement.className = 'status online';
    } catch (error) {
        console.error('Sync error:', error);
        statusElement.textContent = 'Sync failed - will retry when online';
        statusElement.className = 'status offline';
    }
};

// Display surveys in the UI
const displaySurveys = async () => {
    const surveyList = document.getElementById('surveyList');
    surveyList.innerHTML = '';

    try {
        const surveys = await getSurveys();

        if (surveys.length === 0) {
            surveyList.innerHTML = '<p>No surveys saved yet.</p>';
            return;
        }

        surveys.forEach(survey => {
            const surveyElement = document.createElement('div');
            surveyElement.className = 'survey-item';
            surveyElement.innerHTML = `
                <h3>${survey.location}</h3>
                <p><strong>Date:</strong> ${survey.date}</p>
                <p>${survey.observation}</p>
            `;
            surveyList.appendChild(surveyElement);
        });
    } catch (error) {
        console.error('Error displaying surveys:', error);
        surveyList.innerHTML = '<p>Error loading surveys</p>';
    }
};

// Handle form submission
const setupForm = () => {
    const form = document.querySelector('.survey-form');
    const saveBtn = document.getElementById('saveBtn');

    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        saveBtn.disabled = true;

        const survey = {
            location: document.getElementById('location').value,
            observation: document.getElementById('observation').value,
            date: document.getElementById('date').value,
            timestamp: new Date().toISOString()
        };

        try {
            // Save to local DB
            await saveSurvey(survey);

            // Add to sync queue
            await addToSyncQueue(survey);

            // Clear form
            form.reset();

            // Update UI
            await displaySurveys();

            // Try to sync if online
            if (navigator.onLine) {
                await syncData();
            } else {
                const statusElement = document.getElementById('status');
                statusElement.textContent = 'Survey saved - will sync when online';
                statusElement.className = 'status offline';
            }
        } catch (error) {
            console.error('Error saving survey:', error);
            alert('Error saving survey. Please try again.');
        } finally {
            saveBtn.disabled = false;
        }
    });
};

// Check connection status
const updateConnectionStatus = () => {
    const statusElement = document.getElementById('status');

    if (navigator.onLine) {
        statusElement.textContent = 'Online - syncing data...';
        statusElement.className = 'status online';
        syncData();
    } else {
        statusElement.textContent = 'Offline - surveys will sync when online';
        statusElement.className = 'status offline';
    }
};

// Initialize the app
const initApp = async () => {
    try {
        await initDB();
        setupForm();
        await displaySurveys();

        // Set up connection status monitoring
        window.addEventListener('online', updateConnectionStatus);
        window.addEventListener('offline', updateConnectionStatus);

        // Initial connection check
        updateConnectionStatus();
    } catch (error) {
        console.error('App initialization failed:', error);
        alert('App initialization failed. Please refresh the page.');
    }
};

// Start the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
