## JavaScript (app.js)

```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;
let isOnline = navigator.onLine;

// Initialize the app
document.addEventListener('DOMContentLoaded', async () => {
    updateConnectionStatus();
    await initDB();
    loadSavedSurveys();

    // Set up event listeners
    document.getElementById('saveSurvey').addEventListener('click', saveSurvey);
    window.addEventListener('online', handleConnectionChange);
    window.addEventListener('offline', handleConnectionChange);
});

// Initialize IndexedDB
async function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            }
        };
    });
}

// Save survey to IndexedDB
async function saveSurvey() {
    const location = document.getElementById('location').value;
    const species = document.getElementById('species').value;
    const count = document.getElementById('count').value;
    const notes = document.getElementById('notes').value;

    if (!location || !species || !count) {
        alert('Please fill in all required fields');
        return;
    }

    const survey = {
        location,
        species,
        count: parseInt(count),
        notes,
        timestamp: new Date().toISOString(),
        synced: false
    };

    try {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.add(survey);

        request.onsuccess = () => {
            // Clear form
            document.getElementById('location').value = '';
            document.getElementById('species').value = '';
            document.getElementById('count').value = '';
            document.getElementById('notes').value = '';

            loadSavedSurveys();
            updateSyncStatus('Survey saved locally');
        };

        request.onerror = (event) => {
            console.error('Error saving survey:', event.target.error);
        };
    } catch (error) {
        console.error('Error saving survey:', error);
    }
}

// Load saved surveys from IndexedDB
async function loadSavedSurveys() {
    const container = document.getElementById('savedSurveys');
    container.innerHTML = '';

    try {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const index = store.index('timestamp');
        const request = index.openCursor(null, 'prev'); // Get most recent first

        request.onsuccess = (event) => {
            const cursor = event.target.result;
            if (cursor) {
                const survey = cursor.value;
                const surveyElement = document.createElement('div');
                surveyElement.className = 'survey-item';
                surveyElement.innerHTML = `
                    <h3>${survey.species} (${survey.count})</h3>
                    <p><strong>Location:</strong> ${survey.location}</p>
                    <p><strong>Notes:</strong> ${survey.notes || 'None'}</p>
                    <p><small>${new Date(survey.timestamp).toLocaleString()}</small></p>
                    <p class="sync-status">${survey.synced ? '✅ Synced' : '⏳ Not synced'}</p>
                `;
                container.appendChild(surveyElement);
                cursor.continue();
            }
        };

        request.onerror = (event) => {
            console.error('Error loading surveys:', event.target.error);
        };
    } catch (error) {
        console.error('Error loading surveys:', error);
    }
}

// Sync data when online
async function syncData() {
    if (!isOnline) return;

    try {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const index = store.index('timestamp');
        const request = index.openCursor();

        const unsyncedSurveys = [];

        request.onsuccess = (event) => {
            const cursor = event.target.result;
            if (cursor) {
                if (!cursor.value.synced) {
                    unsyncedSurveys.push(cursor.value);
                }
                cursor.continue();
            } else {
                // All surveys processed
                if (unsyncedSurveys.length > 0) {
                    // Simulate syncing to a server
                    updateSyncStatus(`Syncing ${unsyncedSurveys.length} surveys...`);

                    // In a real app, you would use fetch() to send to your server
                    // For this demo, we'll just mark as synced after a delay
                    setTimeout(() => {
                        unsyncedSurveys.forEach(survey => {
                            survey.synced = true;
                            const updateRequest = store.put(survey);
                            updateRequest.onsuccess = () => {
                                updateSyncStatus(`Synced ${unsyncedSurveys.length} surveys`);
                                loadSavedSurveys();
                            };
                        });
                    }, 1000);
                }
            }
        };
    } catch (error) {
        console.error('Error syncing data:', error);
    }
}

// Connection status handling
function updateConnectionStatus() {
    isOnline = navigator.onLine;
    const statusElement = document.getElementById('connectionStatus');
    statusElement.textContent = isOnline ? 'Online - Ready to sync' : 'Offline - Working locally';
    statusElement.className = isOnline ? 'status online' : 'status offline';

    if (isOnline) {
        syncData();
    }
}

function handleConnectionChange() {
    updateConnectionStatus();
}

function updateSyncStatus(message) {
    const syncStatusElement = document.getElementById('syncStatus');
    syncStatusElement.textContent = message;
}
