## JavaScript (app.js)

```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;
let isOnline = navigator.onLine;

// Initialize the app
document.addEventListener('DOMContentLoaded', () => {
    initDB();
    updateConnectionStatus();
    setupEventListeners();

    // Check for pending syncs when coming back online
    window.addEventListener('online', () => {
        updateConnectionStatus();
        syncPendingSurveys();
    });

    window.addEventListener('offline', updateConnectionStatus);
});

// Initialize IndexedDB
function initDB() {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => {
        console.error('Database error:', event.target.error);
    };

    request.onsuccess = (event) => {
        db = event.target.result;
        displaySurveys();
        syncPendingSurveys();
    };

    request.onupgradeneeded = (event) => {
        const db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
            const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            store.createIndex('timestamp', 'timestamp', { unique: false });
            store.createIndex('synced', 'synced', { unique: false });
        }
    };
}

// Update connection status display
function updateConnectionStatus() {
    isOnline = navigator.onLine;
    const statusElement = document.getElementById('connectionStatus');
    statusElement.textContent = isOnline ? 'Online - Ready to sync' : 'Offline - Surveys will be saved locally';
    statusElement.className = isOnline ? 'status online' : 'status offline';
}

// Setup event listeners
function setupEventListeners() {
    document.getElementById('saveSurvey').addEventListener('click', saveSurvey);
}

// Save survey to database
function saveSurvey() {
    const location = document.getElementById('location').value;
    const species = document.getElementById('species').value;
    const count = document.getElementById('count').value;
    const notes = document.getElementById('notes').value;

    if (!location || !species || !count) {
        alert('Please fill in all required fields');
        return;
    }

    const survey = {
        location,
        species,
        count: parseInt(count),
        notes,
        timestamp: new Date().toISOString(),
        synced: false
    };

    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(survey);

    request.onsuccess = () => {
        // Clear form
        document.getElementById('location').value = '';
        document.getElementById('species').value = '';
        document.getElementById('count').value = '';
        document.getElementById('notes').value = '';

        displaySurveys();

        if (isOnline) {
            syncSurvey(request.result);
        } else {
            updateSyncStatus('Survey saved locally. Will sync when online.');
        }
    };

    request.onerror = (event) => {
        console.error('Error saving survey:', event.target.error);
    };
}

// Display saved surveys
function displaySurveys() {
    const listElement = document.getElementById('surveyList');
    listElement.innerHTML = '';

    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const index = store.index('timestamp');
    const request = index.openCursor(null, 'prev'); // Show newest first

    request.onsuccess = (event) => {
        const cursor = event.target.result;
        if (cursor) {
            const survey = cursor.value;
            const item = document.createElement('div');
            item.className = 'survey-item';
            item.innerHTML = `
                <h3>${survey.species} (${survey.count})</h3>
                <p><strong>Location:</strong> ${survey.location}</p>
                <p><strong>Notes:</strong> ${survey.notes || 'None'}</p>
                <p><small>${new Date(survey.timestamp).toLocaleString()}</small></p>
                <p class="sync-status ${survey.synced ? 'synced' : 'pending'}">
                    ${survey.synced ? 'Synced' : 'Pending sync'}
                </p>
            `;
            listElement.appendChild(item);
            cursor.continue();
        }
    };
}

// Sync a single survey with the server
function syncSurvey(id) {
    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(id);

    request.onsuccess = (event) => {
        const survey = event.target.result;

        if (survey && !survey.synced) {
            // Simulate API call to sync with server
            // In a real app, this would be a fetch() to your backend
            console.log('Syncing survey:', survey);

            // Simulate network delay
            setTimeout(() => {
                // Mark as synced
                survey.synced = true;
                const updateRequest = store.put(survey);

                updateRequest.onsuccess = () => {
                    displaySurveys();
                    updateSyncStatus('Survey synced successfully');
                };

                updateRequest.onerror = (event) => {
                    console.error('Error updating survey sync status:', event.target.error);
                };
            }, 1000);
        }
    };

    request.onerror = (event) => {
        console.error('Error getting survey for sync:', event.target.error);
    };
}

// Sync all pending surveys
function syncPendingSurveys() {
    if (!isOnline) return;

    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const index = store.index('synced');
    const request = index.openCursor(IDBKeyRange.only(false));

    request.onsuccess = (event) => {
        const cursor = event.target.result;
        if (cursor) {
            syncSurvey(cursor.primaryKey);
            cursor.continue();
        } else {
            updateSyncStatus('All surveys synced');
        }
    };
}

// Update sync status display
function updateSyncStatus(message) {
    const syncStatusElement = document.getElementById('syncStatus');
    syncStatusElement.textContent = message;
    syncStatusElement.className = 'sync-status ' + (message.includes('synced') ? 'synced' : 'pending');
}
