    if (navigator.onLine) {
        statusElement.textContent = 'Online';
        statusElement.style.color = 'green';
        syncData();
    } else {
        statusElement.textContent = 'Offline';
        statusElement.style.color = 'red';
    }
}

// Save survey to IndexedDB
function saveSurvey(survey) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readwrite');
        const store = transaction.objectStore(storeName);
        const request = store.add(survey);

        request.onsuccess = () => {
            resolve(request.result);
            displaySurveys();
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Get all surveys from IndexedDB
function getSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([storeName], 'readonly');
        const store = transaction.objectStore(storeName);
        const request = store.getAll();

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Display surveys in the UI
async function displaySurveys() {
    const surveys = await getSurveys();
    const list = document.getElementById('survey-list');
    list.innerHTML = '';

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <strong>${survey.location}</strong><br>
