async function syncData() {
    if (!navigator.onLine) return;

    const syncStatus = document.getElementById('sync-status');
    syncStatus.textContent = 'Syncing data...';

    try {
        const surveys = await getSurveys();

        // In a real app, you would send this to your server
        // For this example, we'll just simulate the sync
        console.log('Data to sync:', surveys);

        // Clear the local database after sync (in a real app, you might want to keep until confirmed)
        await clearSurveys();

        syncStatus.textContent = 'Sync complete!';
        displaySurveys();
