## 3. app.js
```javascript
// Database setup
let db;
const DB_NAME = 'SurveyDB';
const STORE_NAME = 'surveys';

async function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject('Database error');
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Save survey to IndexedDB
async function saveSurvey(survey) {
    if (!db) await initDB();

    return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.add(survey);

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Get all pending surveys
async function getPendingSurveys() {
    if (!db) await initDB();

    return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => resolve(request.result);
        request.onerror = (event) => reject(event.target.error);
    });
}

// Delete a survey from IndexedDB
async function deleteSurvey(id) {
    if (!db) await initDB();

    return new Promise((resolve, reject) => {
        const transaction = db.transaction(STORE_NAME, 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.delete(id);

        request.onsuccess = () => resolve();
        request.onerror = (event) => reject(event.target.error);
    });
}

// Simulate syncing to server
async function syncSurveys() {
    const surveys = await getPendingSurveys();

    if (surveys.length === 0) {
        alert('No surveys to sync');
        return;
    }

    // In a real app, you would send these to your server
    console.log('Syncing surveys:', surveys);

    // Simulate network request
    try {
        // This would be a fetch() to your API in a real app
        await new Promise(resolve => setTimeout(resolve, 1000));

        // Remove synced surveys from local storage
        for (const survey of surveys) {
            await deleteSurvey(survey.id);
        }

        alert(`Successfully synced ${surveys.length} surveys`);
        updatePendingList();
    } catch (error) {
        console.error('Sync failed:', error);
        alert('Sync failed. Will retry when online.');
    }
}

// Update the pending surveys list
async function updatePendingList() {
    const surveys = await getPendingSurveys();
    const list = document.getElementById('pending-list');

    list.innerHTML = '';
    if (surveys.length === 0) {
        list.innerHTML = '<li>No pending surveys</li>';
        return;
    }

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.textContent = `${survey.location} - ${survey.date}`;
        list.appendChild(li);
    });
}

// Check connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    const isOnline = navigator.onLine;

    statusElement.textContent = isOnline ? 'Online' : 'Offline';
    statusElement.className = isOnline ? 'online' : 'offline';

    if (isOnline) {
        syncSurveys();
    }
}

// Event listeners
document.addEventListener('DOMContentLoaded', async () => {
    // Initialize database
    await initDB();

    // Update connection status
    updateConnectionStatus();
    window.addEventListener('online', updateConnectionStatus);
    window.addEventListener('offline', updateConnectionStatus);

    // Form submission
    document.getElementById('survey-form').addEventListener('submit', async (e) => {
        e.preventDefault();

        const survey = {
            location: document.getElementById('location').value,
            observation: document.getElementById('observation').value,
            date: document.getElementById('date').value,
            timestamp: new Date().toISOString()
        };

        try {
            await saveSurvey(survey);
            alert('Survey saved locally. Will sync when online.');
            document.getElementById('survey-form').reset();
            updatePendingList();
        } catch (error) {
            console.error('Error saving survey:', error);
            alert('Error saving survey. Please try again.');
        }
    });

    // Sync button
    document.getElementById('sync-btn').addEventListener('click', syncSurveys);

    // Initial update of pending list
    updatePendingList();
});

