        syncStatusElement.textContent = `Synced ${unsyncedSurveys.length} surveys`;
        displaySurveys();
    } catch (error) {
        console.error('Sync error:', error);
        syncStatusElement.textContent = 'Sync failed. Will retry when online.';
    }
}

// Get unsynced surveys
async function getUnsyncedSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const index = store.index('timestamp');
        const request = index.getAll();

        request.onsuccess = () => {
            const unsynced = request.result.filter(survey => !survey.synced);
            resolve(unsynced);
        };
        request.onerror = (event) => reject(event.target.error);
    });
}

// Simulate server sync (replace with real API call)
