        await new Promise(resolve => setTimeout(resolve, 1000));

        // Mark all as synced
        for (const survey of unsynced) {
            await markAsSynced(survey.id);
        }

        showSyncStatus(`Synced ${unsynced.length} surveys`, 'success');
        displaySurveys();
    } catch (error) {
        showSyncStatus('Sync failed: ' + error, 'error');
    }
}

