                        <p>${survey.observation}</p>
                        ${survey.photo ? `<img src="${survey.photo}" style="max-width: 200px;">` : ''}
                    </li>
                `;
            });
            html += '</ul>';
            listElement.innerHTML = html;
        };

        request.onerror = (event) => {
            console.error('Error loading surveys:', event.target.error);
        };

        await tx.complete;
    } catch (error) {
        console.error('Transaction error:', error);
    }
}

// Sync data with server (simulated)
async function syncData() {
    if (!navigator.onLine) return;

    try {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = async (event) => {
            const surveys = event.target.result;
            if (surveys.length === 0) {
                updateSyncStatus('No surveys to sync');
                return;
            }

            // Simulate API call to sync data
            updateSyncStatus(`Syncing ${surveys.length} surveys...`);

            // In a real app, you would send this to your server
            // For this example, we'll just simulate a successful sync
            await new Promise(resolve => setTimeout(resolve, 1000));

            // Clear synced data
            const clearTx = db.transaction(STORE_NAME, 'readwrite');
            const clearStore = clearTx.objectStore(STORE_NAME);
            clearStore.clear();

            await clearTx.complete;

            updateSyncStatus(`Successfully synced ${surveys.length} surveys`);
            displaySurveys();
        };

        request.onerror = (event) => {
            console.error('Error syncing data:', event.target.error);
            updateSyncStatus('Error syncing data', true);
        };

        await tx.complete;
    } catch (error) {
        console.error('Sync error:', error);
        updateSyncStatus('Error syncing data', true);
    }
}

// Update sync status message
function updateSyncStatus(message, isError = false) {
    const statusElement = document.getElementById('syncStatus');
    statusElement.textContent = message;
    statusElement.style.color = isError ? 'red' : 'green';
}

// Handle form submission
document.getElementById('saveSurvey').addEventListener('click', async () => {
    const location = document.getElementById('location').value;
    const observation = document.getElementById('observation').value;
    const photoInput = document.getElementById('photo');

