## JavaScript (app.js)

```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;
let isOnline = navigator.onLine;

// Initialize the app
document.addEventListener('DOMContentLoaded', () => {
    initDB();
    updateConnectionStatus();
    setupEventListeners();

    // Check for pending surveys to sync
    if (isOnline) {
        syncPendingSurveys();
    }
});

// Initialize IndexedDB
function initDB() {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onerror = (event) => {
        console.error('Database error:', event.target.error);
    };

    request.onsuccess = (event) => {
        db = event.target.result;
        loadPendingSurveys();
    };

    request.onupgradeneeded = (event) => {
        db = event.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
            db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
        }
    };
}

// Setup event listeners
function setupEventListeners() {
    document.getElementById('saveSurvey').addEventListener('click', saveSurvey);
    window.addEventListener('online', () => {
        isOnline = true;
        updateConnectionStatus();
        syncPendingSurveys();
    });
    window.addEventListener('offline', () => {
        isOnline = false;
        updateConnectionStatus();
    });
}

// Update connection status display
function updateConnectionStatus() {
    const statusElement = document.getElementById('connectionStatus');
    statusElement.textContent = isOnline ? 'Online - Ready to sync' : 'Offline - Surveys will be saved locally';
    statusElement.className = isOnline ? 'status online' : 'status offline';
}

// Save survey to IndexedDB
function saveSurvey() {
    const location = document.getElementById('location').value;
    const species = document.getElementById('species').value;
    const count = document.getElementById('count').value;
    const notes = document.getElementById('notes').value;

    if (!location || !species || !count) {
        alert('Please fill in all required fields');
        return;
    }

    const survey = {
        location,
        species,
        count: parseInt(count),
        notes,
        timestamp: new Date().toISOString(),
        synced: false
    };

    const transaction = db.transaction([STORE_NAME], 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.add(survey);

    request.onsuccess = () => {
        document.getElementById('saveStatus').textContent = 'Survey saved locally';
        document.getElementById('location').value = '';
        document.getElementById('species').value = '';
        document.getElementById('count').value = '';
        document.getElementById('notes').value = '';

        loadPendingSurveys();

        if (isOnline) {
            syncSurvey(request.result);
        }
    };

    request.onerror = (event) => {
        console.error('Error saving survey:', event.target.error);
        document.getElementById('saveStatus').textContent = 'Error saving survey';
    };
}

// Load pending surveys from IndexedDB
function loadPendingSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result;
        const pendingList = document.getElementById('pendingList');

        if (surveys.length === 0) {
            pendingList.innerHTML = '<p>No pending surveys</p>';
            return;
        }

        let html = '<ul>';
        surveys.forEach(survey => {
            html += `<li>
                <strong>${survey.species}</strong> at ${survey.location} (${survey.count})
                <span style="color: ${survey.synced ? 'green' : 'red'}">
                    ${survey.synced ? 'Synced' : 'Pending'}
                </span>
                <br><small>${new Date(survey.timestamp).toLocaleString()}</small>
            </li>`;
        });
        html += '</ul>';
        pendingList.innerHTML = html;
    };
}

// Sync all pending surveys
function syncPendingSurveys() {
    if (!isOnline) return;

    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result.filter(survey => !survey.synced);

        if (surveys.length === 0) {
            document.getElementById('saveStatus').textContent = 'All surveys synced';
            return;
        }

        document.getElementById('saveStatus').textContent = `Syncing ${surveys.length} surveys...`;

        // In a real app, you would send these to your server
        // For this example, we'll just mark them as synced
        surveys.forEach(survey => {
            syncSurvey(survey.id);
        });
    };
}

// Simulate syncing a single survey
function syncSurvey(id) {
    // In a real app, you would send the survey data to your server here
    // For this example, we'll just mark it as synced after a delay

    setTimeout(() => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.get(id);

        request.onsuccess = (event) => {
            const survey = event.target.result;
            if (survey) {
                survey.synced = true;
                store.put(survey);
                loadPendingSurveys();
                document.getElementById('saveStatus').textContent = 'Survey synced successfully';
            }
        };
    }, 1000); // Simulate network delay
}
