```javascript
// Database setup
let db;
const DB_NAME = 'SurveyAppDB';
const STORE_NAME = 'surveys';
const SYNC_STORE_NAME = 'syncQueue';

const connectionStatus = document.getElementById('connection-status');
const syncStatus = document.getElementById('sync-status');
const surveyForm = document.getElementById('survey-form');
const surveyItems = document.getElementById('survey-items');

// Initialize the database
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, 1);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;

            // Create object stores
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }

            if (!db.objectStoreNames.contains(SYNC_STORE_NAME)) {
                db.createObjectStore(SYNC_STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Check connection status
function updateConnectionStatus() {
    if (navigator.onLine) {
        connectionStatus.textContent = 'Online';
        connectionStatus.className = 'online';
        syncData();
    } else {
        connectionStatus.textContent = 'Offline';
        connectionStatus.className = 'offline';
    }
}

// Save survey to IndexedDB
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);

        const request = store.add(surveyData);

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Queue data for sync when offline
function queueForSync(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([SYNC_STORE_NAME], 'readwrite');
        const store = transaction.objectStore(SYNC_STORE_NAME);

        const request = store.add(surveyData);

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            reject(event.target.error);
        };
    });
}

// Sync data with server (simulated)
async function syncData() {
    if (!navigator.onLine) return;

    syncStatus.textContent = 'Syncing...';
    syncStatus.className = 'syncing';

    try {
        const transaction = db.transaction([SYNC_STORE_NAME, STORE_NAME], 'readwrite');
        const syncStore = transaction.objectStore(SYNC_STORE_NAME);
        const surveyStore = transaction.objectStore(STORE_NAME);

        const request = syncStore.getAll();

        request.onsuccess = async (event) => {
            const itemsToSync = event.target.result;

            if (itemsToSync.length === 0) {
                syncStatus.textContent = 'All synced';
                syncStatus.className = 'synced';
                return;
            }

            // Simulate API call to sync data
            for (const item of itemsToSync) {
                // In a real app, you would send to your server here
                console.log('Syncing item:', item);

                // Remove from sync queue
                const deleteRequest = syncStore.delete(item.id);
                deleteRequest.onsuccess = () => {
                    console.log('Item removed from sync queue');
                };
            }

            syncStatus.textContent = 'All synced';
            syncStatus.className = 'synced';
        };

        request.onerror = (event) => {
            console.error('Error syncing data:', event.target.error);
            syncStatus.textContent = 'Sync failed';
            syncStatus.className = 'offline';
        };
    } catch (error) {
        console.error('Sync error:', error);
        syncStatus.textContent = 'Sync failed';
        syncStatus.className = 'offline';
    }
}

// Load saved surveys from IndexedDB
function loadSurveys() {
    const transaction = db.transaction([STORE_NAME], 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.getAll();

    request.onsuccess = (event) => {
        const surveys = event.target.result;
        displaySurveys(surveys);
    };

    request.onerror = (event) => {
        console.error('Error loading surveys:', event.target.error);
    };
}

// Display surveys in the UI
function displaySurveys(surveys) {
    surveyItems.innerHTML = '';

    if (surveys.length === 0) {
        surveyItems.innerHTML = '<li>No surveys saved yet.</li>';
        return;
    }

    surveys.forEach(survey => {
        const li = document.createElement('li');
        li.innerHTML = `
            <h3>${survey.location}</h3>
            <p><strong>Species:</strong> ${survey.species}</p>
            <p><strong>Count:</strong> ${survey.count}</p>
            <p><strong>Notes:</strong> ${survey.notes || 'None'}</p>
            <small>ID: ${survey.id}</small>
        `;
        surveyItems.appendChild(li);
    });
}

// Handle form submission
surveyForm.addEventListener('submit', async (e) => {
    e.preventDefault();

    const surveyData = {
        location: document.getElementById('location').value,
        species: document.getElementById('species').value,
        count: document.getElementById('count').value,
        notes: document.getElementById('notes').value,
        timestamp: new Date().toISOString()
    };

    try {
        // Save to local DB
        const id = await saveSurvey(surveyData);
        surveyData.id = id;

        // If offline, queue for sync
        if (!navigator.onLine) {
            await queueForSync(surveyData);
            alert('Survey saved locally. Will sync when online.');
        } else {
            // If online, sync immediately
            await syncData();
        }

        // Clear form
        surveyForm.reset();

        // Refresh display
        loadSurveys();
    } catch (error) {
        console.error('Error saving survey:', error);
        alert('Error saving survey. Please try again.');
    }
});

// Event listeners
window.addEventListener('online', updateConnectionStatus);
window.addEventListener('offline', updateConnectionStatus);

// Initialize app
async function initApp() {
    try {
        await initDB();
        updateConnectionStatus();
        loadSurveys();

        // Check for sync periodically
        setInterval(() => {
            if (navigator.onLine) {
                syncData();
            }
        }, 30000); // Check every 30 seconds
    } catch (error) {
        console.error('Initialization error:', error);
    }
}

initApp();
