## JavaScript (app.js)

```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';
let db;

async function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject('Error opening database');
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                const store = db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
                store.createIndex('timestamp', 'timestamp', { unique: false });
            }
        };
    });
}

// UI elements
const statusDiv = document.getElementById('status');
const saveBtn = document.getElementById('saveBtn');
const surveysList = document.getElementById('surveys');

// Form elements
const locationInput = document.getElementById('location');
const observationInput = document.getElementById('observation');
const photoInput = document.getElementById('photo');

// Connection status
let isOnline = navigator.onLine;
updateStatus();

// Event listeners
window.addEventListener('online', () => {
    isOnline = true;
    updateStatus();
    syncData();
});

window.addEventListener('offline', () => {
    isOnline = false;
    updateStatus();
});

saveBtn.addEventListener('click', saveSurvey);

// Initialize
initDB().then(() => {
    loadSurveys();
    if (isOnline) {
        syncData();
    }
});

// Functions
function updateStatus() {
    if (isOnline) {
        statusDiv.textContent = 'Online - Data will sync automatically';
        statusDiv.className = 'status online';
    } else {
        statusDiv.textContent = 'Offline - Data will be saved locally and synced when reconnected';
        statusDiv.className = 'status offline';
    }
}

async function saveSurvey() {
    if (!locationInput.value || !observationInput.value) {
        alert('Please fill in all required fields');
        return;
    }

    const survey = {
        location: locationInput.value,
        observation: observationInput.value,
        timestamp: new Date().toISOString(),
        synced: false
    };

    // Handle photo if provided
    if (photoInput.files.length > 0) {
        const file = photoInput.files[0];
        survey.photo = await fileToBase64(file);
    }

    try {
        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        const request = store.add(survey);

        request.onsuccess = () => {
            locationInput.value = '';
            observationInput.value = '';
            photoInput.value = '';
            loadSurveys();

            if (isOnline) {
                syncData();
            }
        };

        request.onerror = (event) => {
            console.error('Error saving survey:', event.target.error);
        };
    } catch (error) {
        console.error('Error saving survey:', error);
    }
}

async function loadSurveys() {
    try {
        const tx = db.transaction(STORE_NAME, 'readonly');
        const store = tx.objectStore(STORE_NAME);
        const index = store.index('timestamp');
        const request = index.openCursor(null, 'prev'); // Get newest first

        surveysList.innerHTML = '';

        request.onsuccess = (event) => {
            const cursor = event.target.result;
            if (cursor) {
                const survey = cursor.value;
                const li = document.createElement('li');
                li.innerHTML = `
                    <strong>${survey.location}</strong> - ${new Date(survey.timestamp).toLocaleString()}
                    <p>${survey.observation}</p>
                    ${survey.photo ? `<img src="${survey.photo}" width="100">` : ''}
                    <span class="sync-status">${survey.synced ? 'Synced' : 'Pending sync'}</span>
                `;
                surveysList.appendChild(li);
                cursor.continue();
            }
        };
    } catch (error) {
        console.error('Error loading surveys:', error);
    }
}

async function syncData() {
    if (!isOnline) return;

    try {
        statusDiv.textContent = 'Syncing data...';
        statusDiv.className = 'status syncing';

        const tx = db.transaction(STORE_NAME, 'readwrite');
        const store = tx.objectStore(STORE_NAME);
        const index = store.index('timestamp');
        const request = index.openCursor();

        const surveysToSync = [];

        request.onsuccess = (event) => {
            const cursor = event.target.result;
            if (cursor) {
                const survey = cursor.value;
                if (!survey.synced) {
                    surveysToSync.push(survey);
                }
                cursor.continue();
            } else {
                // All surveys processed, now sync them
                if (surveysToSync.length > 0) {
                    // In a real app, you would send this to your server
                    // For this example, we'll just mark them as synced
                    console.log('Syncing surveys:', surveysToSync);

                    // Simulate API call
                    setTimeout(() => {
                        surveysToSync.forEach(survey => {
                            const updateTx = db.transaction(STORE_NAME, 'readwrite');
                            const updateStore = updateTx.objectStore(STORE_NAME);
                            survey.synced = true;
                            updateStore.put(survey);
                        });

                        loadSurveys();
                        updateStatus();
                    }, 1000);
                } else {
                    updateStatus();
                }
            }
        };
    } catch (error) {
        console.error('Error syncing data:', error);
        updateStatus();
    }
}

function fileToBase64(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result);
        reader.onerror = error => reject(error);
    });
}
