    console.log('Syncing data:', unsyncedSurveys);

    // In a real app, you would send to your server here
    // For this example, we'll just mark as synced
    const transaction = db.transaction([storeName], 'readwrite');
    const store = transaction.objectStore(storeName);

    unsyncedSurveys.forEach(survey => {
        const updatedSurvey = { ...survey, synced: true };
        store.put(updatedSurvey);
    });

    transaction.oncomplete = () => {
        console.log('Data synced successfully');
        displaySurveys();
        updateSyncStatus();
    };

    transaction.onerror = (event) => {
        console.error('Error syncing data:', event.target.error);
    };
}

// Update sync status UI
async function updateSyncStatus() {
    const surveys = await getSurveys();
    const unsyncedCount = surveys.filter(survey => !survey.synced).length;
    const syncStatus = document.getElementById('syncStatus');

    if (unsyncedCount > 0) {
        syncStatus.textContent = `${unsyncedCount} surveys pending sync`;
        syncStatus.className = 'sync-status pending';
    } else {
        syncStatus.textContent = 'All surveys synced';
        syncStatus.className = 'sync-status synced';
    }
}

// Initialize the app
async function init() {
    try {
        await openDB();
        updateConnectionStatus();
        displaySurveys();

        // Set up event listeners
        document.getElementById('saveSurvey').addEventListener('click', async () => {
            const location = document.getElementById('location').value;
            const species = document.getElementById('species').value;
            const count = document.getElementById('count').value;
            const notes = document.getElementById('notes').value;

            if (!location || !species || !count) {
                alert('Please fill in all required fields');
                return;
            }

            const surveyData = {
                location,
                species,
                count: parseInt(count),
                notes,
                timestamp: new Date().toISOString(),
                synced: false
            };

            await saveSurvey(surveyData);

            // Clear form
            document.getElementById('location').value = '';
            document.getElementById('species').value = '';
            document.getElementById('count').value = '';
            document.getElementById('notes').value = '';
        });

        // Listen for connection changes
        window.addEventListener('online', updateConnectionStatus);
        window.addEventListener('offline', updateConnectionStatus);

    } catch (error) {
        console.error('Initialization error:', error);
        alert('Error initializing the app. Please check the console for details.');
    }
}

// Start the app
init();
```

