```javascript
// Database setup
const DB_NAME = 'FieldSurveyDB';
const DB_VERSION = 1;
const STORE_NAME = 'surveys';

let db;
let isOnline = navigator.onLine;

// Initialize the database
function initDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(DB_NAME, DB_VERSION);

        request.onerror = (event) => {
            console.error('Database error:', event.target.error);
            reject(event.target.error);
        };

        request.onsuccess = (event) => {
            db = event.target.result;
            resolve(db);
        };

        request.onupgradeneeded = (event) => {
            const db = event.target.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'id', autoIncrement: true });
            }
        };
    });
}

// Save survey data (works offline)
function saveSurvey(surveyData) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.add(surveyData);

        request.onsuccess = () => {
            console.log('Survey saved locally');
            resolve();
        };

        request.onerror = (event) => {
            console.error('Error saving survey:', event.target.error);
            reject(event.target.error);
        };
    });
}

// Get all pending surveys
function getPendingSurveys() {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.getAll();

        request.onsuccess = () => {
            resolve(request.result);
        };

        request.onerror = (event) => {
            console.error('Error getting pending surveys:', event.target.error);
            reject(event.target.error);
        };
    });
}

// Delete a survey after successful sync
function deleteSurvey(id) {
    return new Promise((resolve, reject) => {
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        const request = store.delete(id);

        request.onsuccess = () => {
            console.log('Survey deleted after sync');
            resolve();
        };

        request.onerror = (event) => {
            console.error('Error deleting survey:', event.target.error);
            reject(event.target.error);
        };
    });
}

// Simulate syncing to server (in a real app, this would be an actual API call)
async function syncSurveys() {
    if (!isOnline) {
        alert('You are offline. Data will sync automatically when you reconnect.');
        return;
    }

    const pendingSurveys = await getPendingSurveys();

    if (pendingSurveys.length === 0) {
        alert('No pending surveys to sync.');
        return;
    }

    // Simulate API call
    console.log('Syncing surveys:', pendingSurveys);

    // In a real app, you would:
    // 1. Send data to your server
    // 2. Wait for success response
    // 3. Then delete from local storage

    // For this demo, we'll just simulate a successful sync
    for (const survey of pendingSurveys) {
        await deleteSurvey(survey.id);
    }

    alert(`Successfully synced ${pendingSurveys.length} surveys!`);
    updatePendingList();
}

// Update the UI with pending surveys
async function updatePendingList() {
    const pendingList = document.getElementById('pending-list');
    const pendingSurveys = await getPendingSurveys();

    pendingList.innerHTML = '';

    if (pendingSurveys.length === 0) {
        pendingList.innerHTML = '<li>No pending surveys</li>';
        return;
    }

    pendingSurveys.forEach(survey => {
        const li = document.createElement('li');
        li.textContent = `${survey.location} - ${survey.species} (${survey.count})`;
        pendingList.appendChild(li);
    });
}

// Update connection status
function updateConnectionStatus() {
    const statusElement = document.getElementById('connection-status');
    const syncBtn = document.getElementById('sync-btn');

    if (isOnline) {
        statusElement.textContent = 'Online';
        statusElement.className = 'online';
        syncBtn.disabled = false;
    } else {
        statusElement.textContent = 'Offline';
        statusElement.className = 'offline';
        syncBtn.disabled = true;
    }
}

// Event listeners
document.addEventListener('DOMContentLoaded', async () => {
    await initDB();
    updatePendingList();
    updateConnectionStatus();

    // Form submission
    document.getElementById('survey-form').addEventListener('submit', async (e) => {
        e.preventDefault();

        const surveyData = {
            location: document.getElementById('location').value,
            species: document.getElementById('species').value,
            count: document.getElementById('count').value,
            notes: document.getElementById('notes').value,
            timestamp: new Date().toISOString()
        };

        await saveSurvey(surveyData);
        document.getElementById('survey-form').reset();
        updatePendingList();

        if (isOnline) {
            // If online, try to sync immediately
            await syncSurveys();
        } else {
            alert('Survey saved locally. It will sync when you reconnect.');
        }
    });

    // Sync button
    document.getElementById('sync-btn').addEventListener('click', syncSurveys);
});

// Connection status events
window.addEventListener('online', () => {
    isOnline = true;
    updateConnectionStatus();
    syncSurveys(); // Try to sync when coming back online
});

window.addEventListener('offline', () => {
    isOnline = false;
    updateConnectionStatus();
});
