# Social Messaging App with Real-Time Notifications and Monetization

Below is a comprehensive code example for a social messaging app with real-time notifications and in-app monetization features. This implementation uses Node.js with Express for the backend, Socket.io for real-time communication, and React for the frontend.

## Backend Implementation (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const stripe = require('stripe')('your_stripe_secret_key');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(express.json());

// MongoDB Connection
mongoose.connect('mongodb://localhost:27017/socialmessaging', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// Models
const User = mongoose.model('User', new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  profilePicture: String,
  premium: { type: Boolean, default: false },
  premiumExpiry: Date,
  createdAt: { type: Date, default: Date.now }
}));

const Message = mongoose.model('Message', new mongoose.Schema({
  sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  receiver: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: String,
  timestamp: { type: Date, default: Date.now },
  read: { type: Boolean, default: false }
}));

const Notification = mongoose.model('Notification', new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  type: String, // 'message', 'friend_request', 'premium_feature'
  content: String,
  read: { type: Boolean, default: false },
  createdAt: { type: Date, default: Date.now }
}));

// Authentication Middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).send('Access denied');

  try {
    const decoded = jwt.verify(token, 'your_jwt_secret');
    req.user = decoded;
    next();
  } catch (error) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = new User({ username, email, password: hashedPassword });
    await user.save();

    const token = jwt.sign({ _id: user._id }, 'your_jwt_secret');
    res.status(201).send({ user, token });
  } catch (error) {
    res.status(400).send(error.message);
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await User.findOne({ email });
    if (!user) throw new Error('User not found');

    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) throw new Error('Invalid credentials');

    const token = jwt.sign({ _id: user._id }, 'your_jwt_secret');
    res.send({ user, token });
  } catch (error) {
    res.status(400).send(error.message);
  }
});

app.get('/api/users', authenticate, async (req, res) => {
  try {
    const users = await User.find({ _id: { $ne: req.user._id } }).select('-password');
    res.send(users);
  } catch (error) {
    res.status(500).send(error.message);
  }
});

app.post('/api/messages', authenticate, async (req, res) => {
  try {
    const { receiverId, content } = req.body;
    const message = new Message({
      sender: req.user._id,
      receiver: receiverId,
      content
    });
    await message.save();

    // Create notification for receiver
    const notification = new Notification({
      user: receiverId,
      type: 'message',
      content: `New message from ${req.user.username}`
    });
    await notification.save();

    // Emit real-time message
    io.to(receiverId.toString()).emit('newMessage', message);

    res.status(201).send(message);
  } catch (error) {
    res.status(400).send(error.message);
  }
});

app.get('/api/messages/:userId', authenticate, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.user._id, receiver: req.params.userId },
        { sender: req.params.userId, receiver: req.user._id }
      ]
    }).sort('timestamp');

    // Mark messages as read
    await Message.updateMany(
      { sender: req.params.userId, receiver: req.user._id, read: false },
      { read: true }
    );

    res.send(messages);
  } catch (error) {
    res.status(500).send(error.message);
  }
});

app.get('/api/notifications', authenticate, async (req, res) => {
  try {
    const notifications = await Notification.find({ user: req.user._id }).sort('-createdAt');
    res.send(notifications);
  } catch (error) {
    res.status(500).send(error.message);
  }
});

app.post('/api/notifications/read', authenticate, async (req, res) => {
  try {
    await Notification.updateMany(
      { user: req.user._id, read: false },
      { read: true }
    );
    res.send({ success: true });
  } catch (error) {
    res.status(500).send(error.message);
  }
});

// Premium Features
app.post('/api/premium/subscribe', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.user._id);
    if (!user) throw new Error('User not found');

    // Create Stripe checkout session
    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [{
        price_data: {
          currency: 'usd',
          product_data: {
            name: 'Premium Subscription',
          },
          unit_amount: 999, // $9.99
        },
        quantity: 1,
      }],
      mode: 'payment',
      success_url: 'http://localhost:3000/success',
      cancel_url: 'http://localhost:3000/cancel',
      metadata: {
        userId: user._id.toString()
      }
    });

    res.send({ url: session.url });
  } catch (error) {
    res.status(500).send(error.message);
  }
});

// Webhook for Stripe
app.post('/api/webhook', express.raw({type: 'application/json'}), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, 'your_stripe_webhook_secret');
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.metadata.userId;

    // Update user to premium
    await User.findByIdAndUpdate(userId, {
      premium: true,
      premiumExpiry: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // 30 days
    });

    // Create notification
    const notification = new Notification({
      user: userId,
      type: 'premium_feature',
      content: 'Your premium subscription is active!'
    });
    await notification.save();

    // Emit real-time notification
    io.to(userId).emit('newNotification', notification);
  }

  res.json({received: true});
});

// Socket.io Connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (userId) => {
    socket.join(userId);
    console.log(`User ${userId} joined`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

