    } catch (error) {
      alert(error.response.data);
    }
  };

  return (
    <div className="auth-container">
      <h2>Register</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Register</button>
      </form>
    </div>
  );
};

const Dashboard = ({ user, token, socket }) => {
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/users', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setUsers(response.data);
      } catch (error) {
        console.error(error);
      }
    };

    const fetchNotifications = async () => {
      try {
        const response = await axios.get('http://localhost:5000/api/notifications', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setNotifications(response.data);
      } catch (error) {
        console.error(error);
      }
    };

    fetchUsers();
    fetchNotifications();

    // Join socket room
    if (socket && user) {
      socket.emit('join', user._id);
    }

    // Listen for new messages
    if (socket) {
      socket.on('newMessage', (message) => {
        if (selectedUser && message.sender === selectedUser._id) {
          setMessages(prev => [...prev, message]);
        }
        fetchNotifications();
      });

      socket.on('newNotification', (notification) => {
        setNotifications(prev => [notification, ...prev]);
      });
    }

    return () => {
      if (socket) {
        socket.off('newMessage');
        socket.off('newNotification');
      }
    };
  }, [user, token, socket, selectedUser]);

  const selectUser = async (user) => {
    setSelectedUser(user);
    try {
      const response = await axios.get(`http://localhost:5000/api/messages/${user._id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setMessages(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  const sendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedUser) return;

    try {
      const response = await axios.post('http://localhost:5000/api/messages', {
        receiverId: selectedUser._id,
        content: newMessage
      }, {
        headers: { Authorization: `Bearer ${token}` }
      });

      setMessages(prev => [...prev, response.data]);
      setNewMessage('');
    } catch (error) {
      console.error(error);
    }
  };

  const markNotificationsAsRead = async () => {
    try {
      await axios.post('http://localhost:5000/api/notifications/read', {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    } catch (error) {
      console.error(error);
    }
  };

  const subscribeToPremium = async () => {
    try {
      const response = await axios.post('http://localhost:5000/api/premium/subscribe', {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      window.location.href = response.data.url;
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div className="dashboard">
      <div className="sidebar">
        <div className="user-info">
          <img src={user.profilePicture || '/default-avatar.png'} alt="Profile" />
          <h3>{user.username}</h3>
          {user.premium ? (
            <span className="premium-badge">Premium</span>
          ) : (
            <button onClick={subscribeToPremium} className="premium-button">Go Premium</button>
          )}
        </div>
        <div className="notifications">
          <button onClick={() => {
            setShowNotifications(!showNotifications);
            if (!showNotifications) markNotificationsAsRead();
          }}>
            Notifications ({notifications.filter(n => !n.read).length})
          </button>
          {showNotifications && (
            <div className="notification-dropdown">
              {notifications.length > 0 ? (
                notifications.map(notification => (
                  <div key={notification._id} className={`notification ${notification.read ? '' : 'unread'}`}>
                    {notification.content}
                  </div>
                ))
              ) : (
                <div>No notifications</div>
              )}
            </div>
          )}
        </div>
        <div className="user-list">
          <h3>Users</h3>
          {users.map(u => (
            <div
              key={u._id}
              className={`user-item ${selectedUser?._id === u._id ? 'selected' : ''}`}
              onClick={() => selectUser(u)}
            >
              <img src={u.profilePicture || '/default-avatar.png'} alt="Profile" />
              <span>{u.username}</span>
            </div>
          ))}
        </div>
      </div>
      <div className="chat-area">
        {selectedUser ? (
          <>
            <div className="chat-header">
              <h2>{selectedUser.username}</h2>
            </div>
            <div className="messages">
              {messages.map(message => (
                <div
                  key={message._id}
                  className={`message ${message.sender === user._id ? 'sent' : 'received'}`}
                >
                  <div className="message-content">{message.content}</div>
                  <div className="message-time">
                    {new Date(message.timestamp).toLocaleTimeString()}
                  </div>
                </div>
              ))}
            </div>
            <form onSubmit={sendMessage} className="message-form">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
              />
              <button type="submit">Send</button>
            </form>
          </>
        ) : (
          <div className="no-chat-selected">
            <h2>Select a user to start chatting</h2>
          </div>
        )}
      </div>
    </div>
  );
};

const SuccessPage = () => {
  return (
    <div className="success-page">
      <h1>Payment Successful!</h1>
      <p>Your premium subscription is now active.</p>
      <a href="/">Return to Dashboard</a>
    </div>
  );
};

const CancelPage = () => {
  return (
    <div className="cancel-page">
      <h1>Payment Cancelled</h1>
      <p>Your premium subscription was not completed.</p>
      <a href="/">Return to Dashboard</a>
    </div>
  );
};

function App() {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token') || null);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    if (token) {
      // Initialize socket connection
      const newSocket = io('http://localhost:5000');
      setSocket(newSocket);

      // Fetch user data
      axios.get('http://localhost:5000/api/users/me', {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(response => setUser(response.data))
      .catch(() => {
        setUser(null);
        setToken(null);
        localStorage.removeItem('token');
      });

      return () => newSocket.close();
    }
  }, [token]);

  const logout = () => {
    setUser(null);
    setToken(null);
    localStorage.removeItem('token');
    if (socket) socket.disconnect();
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route
            path="/"
            element={
              token ? (
                <Dashboard user={user} token={token} socket={socket} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/login"
            element={token ? <Navigate to="/" /> : <Login setUser={setUser} setToken={setToken} />}
          />
          <Route
            path="/register"
            element={token ? <Navigate to="/" /> : <Register setUser={setUser} setToken={setToken} />}
          />
          <Route path="/success" element={<SuccessPage />} />
          <Route path="/cancel" element={<CancelPage />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
```

