# Social Messaging App with Real-Time Notifications and Monetization

Below is a comprehensive code implementation for a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js with Express for the backend, React for the frontend, and Firebase for real-time capabilities.

## Backend Implementation (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const stripe = require('stripe')('your_stripe_secret_key');
const admin = require('firebase-admin');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json');
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: 'https://your-project.firebaseio.com'
});

// MongoDB Connection
mongoose.connect('mongodb://localhost:27017/socialmessaging', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// User Model
const UserSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  profilePicture: String,
  premium: { type: Boolean, default: false },
  premiumExpiry: Date,
  fcmToken: String
});

const User = mongoose.model('User', UserSchema);

// Message Model
const MessageSchema = new mongoose.Schema({
  sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  receiver: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: String,
  timestamp: { type: Date, default: Date.now },
  read: { type: Boolean, default: false }
});

const Message = mongoose.model('Message', MessageSchema);

// Middleware
app.use(express.json());

// Authentication Middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).send('Access denied');

  try {
    const verified = jwt.verify(token, 'your_jwt_secret');
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/api/register', async (req, res) => {
  try {
    const { username, email, password } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = new User({ username, email, password: hashedPassword });
    await user.save();
    res.status(201).send('User registered');
  } catch (err) {
    res.status(400).send(err.message);
  }
});

app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await User.findOne({ email });
    if (!user) return res.status(400).send('User not found');

    const validPass = await bcrypt.compare(password, user.password);
    if (!validPass) return res.status(400).send('Invalid password');

    const token = jwt.sign({ _id: user._id }, 'your_jwt_secret', { expiresIn: '1h' });
    res.send({ token, user: { _id: user._id, username: user.username, premium: user.premium } });
  } catch (err) {
    res.status(400).send(err.message);
  }
});

// Premium Subscription
app.post('/api/create-subscription', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.user._id);
    if (!user) return res.status(404).send('User not found');

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [{
        price_data: {
          currency: 'usd',
          product_data: {
            name: 'Premium Subscription',
          },
          unit_amount: 999, // $9.99
        },
        quantity: 1,
      }],
      mode: 'subscription',
      success_url: 'https://yourapp.com/success?session_id={CHECKOUT_SESSION_ID}',
      cancel_url: 'https://yourapp.com/cancel',
      metadata: {
        userId: user._id.toString()
      }
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).send(err.message);
  }
});

// Webhook for Stripe
app.post('/api/webhook', express.raw({type: 'application/json'}), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(req.body, sig, 'your_webhook_secret');
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === 'checkout.session.completed') {
    const session = event.data.object;
    const userId = session.metadata.userId;

    // Update user to premium
    await User.findByIdAndUpdate(userId, {
      premium: true,
      premiumExpiry: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000) // 30 days
    });
  }

  res.json({received: true});
});

// Socket.IO for real-time messaging
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (userId) => {
    socket.join(userId);
  });

  socket.on('sendMessage', async ({ senderId, receiverId, content }) => {
    try {
      const message = new Message({ sender: senderId, receiver: receiverId, content });
      await message.save();

      // Emit to receiver
      io.to(receiverId).emit('newMessage', message);

      // Send push notification if user is not online
      const receiver = await User.findById(receiverId);
      if (receiver.fcmToken) {
        const payload = {
          notification: {
            title: 'New Message',
            body: content
          }
        };

        admin.messaging().sendToDevice(receiver.fcmToken, payload)
          .then(response => console.log('Notification sent'))
          .catch(error => console.log('Error sending notification:', error));
      }
    } catch (err) {
      console.error('Error sending message:', err);
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

## Frontend Implementation (React)

```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import io from 'socket.io-client';
import axios from 'axios';
import { initializeApp } from 'firebase/app';
import { getMessaging, getToken, onMessage } from 'firebase/messaging';

// Firebase configuration
const firebaseConfig = {
  apiKey: "your_api_key",
  authDomain: "your_project.firebaseapp.com",
  projectId: "your_project",
  storageBucket: "your_project.appspot.com",
  messagingSenderId: "your_sender_id",
  appId: "your_app_id"
};

const firebaseApp = initializeApp(firebaseConfig);
const messaging = getMessaging(firebaseApp);

function App() {
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [socket, setSocket] = useState(null);
  const [newMessage, setNewMessage] = useState('');

  useEffect(() => {
    // Check for existing user
    const token = localStorage.getItem('token');
    if (token) {
      axios.get('/api/user', { headers: { Authorization: `Bearer ${token}` } })
        .then(res => setUser(res.data))
        .catch(err => console.error(err));
    }

    // Initialize Socket.IO
    const newSocket = io('http://localhost:5000');
    setSocket(newSocket);

    // Request notification permission
    Notification.requestPermission().then(permission => {
      if (permission === 'granted') {
        getToken(messaging, { vapidKey: 'your_vapid_key' })
          .then(currentToken => {
            if (currentToken) {
              // Send token to server
              axios.post('/api/update-fcm-token', { token: currentToken });
            }
          })
          .catch(err => console.error('Error getting FCM token:', err));
      }
    });

    // Listen for messages
    onMessage(messaging, (payload) => {
      console.log('Message received:', payload);
      // Handle foreground notifications
    });

    return () => newSocket.close();
  }, []);

  const handleLogin = async (email, password) => {
    try {
      const res = await axios.post('/api/login', { email, password });
      localStorage.setItem('token', res.data.token);
      setUser(res.data.user);
      socket.emit('join', res.data.user._id);
    } catch (err) {
      console.error(err);
    }
  };

  const handleSendMessage = async (receiverId) => {
    if (!newMessage.trim()) return;

    try {
      socket.emit('sendMessage', {
        senderId: user._id,
        receiverId,
        content: newMessage
      });
      setNewMessage('');
    } catch (err) {
      console.error(err);
    }
  };

  const handleUpgradeToPremium = async () => {
    try {
      const res = await axios.post('/api/create-subscription', {}, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      window.location.href = res.data.url;
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <Router>
      <div className="app">
        <header>
          <h1>SocialMessenger</h1>
          {user && (
            <div className="user-info">
              <span>Welcome, {user.username}</span>
              {!user.premium && (
                <button onClick={handleUpgradeToPremium}>Upgrade to Premium</button>
              )}
            </div>
          )}
        </header>

        <Switch>
          <Route path="/login">
            <Login onLogin={handleLogin} />
          </Route>
          <Route path="/">
            {user ? (
              <Chat
                user={user}
                messages={messages}
                newMessage={newMessage}
                setNewMessage={setNewMessage}
                onSendMessage={handleSendMessage}
              />
            ) : (
              <div>Please login to start messaging</div>
            )}
          </Route>
        </Switch>
      </div>
    </Router>
  );
}

// Chat Component
function Chat({ user, messages, newMessage, setNewMessage, onSendMessage }) {
  const [receiverId, setReceiverId] = useState('');

  return (
    <div className="chat-container">
      <div className="message-list">
        {messages.map((msg, index) => (
          <div key={index} className={`message ${msg.sender === user._id ? 'sent' : 'received'}`}>
            {msg.content}
          </div>
        ))}
      </div>

      <div className="message-input">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type your message..."
        />
        <input
          type="text"
          value={receiverId}
          onChange={(e) => setReceiverId(e.target.value)}
          placeholder="Receiver ID"
        />
        <button onClick={() => onSendMessage(receiverId)}>Send</button>
      </div>
    </div>
  );
}

// Login Component
function Login({ onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    onLogin(email, password);
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="Email"
        required
      />
      <input
        type="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        placeholder="Password"
        required
      />
      <button type="submit">Login</button>
    </form>
  );
}

export default App;
```

