import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { io } from 'socket.io-client';
import axios from 'axios';
import Login from './components/Auth/Login';
import Register from './components/Auth/Register';
import Dashboard from './components/Dashboard/Dashboard';
import Chat from './components/Chat/Chat';
import Profile from './components/Profile/Profile';
import Subscriptions from './components/Subscriptions/Subscriptions';
import { AuthContext } from './context/AuthContext';
import { SocketContext } from './context/SocketContext';

const App = () => {
  const [user, setUser] = useState(null);
  const [socket, setSocket] = useState(null);

  // Initialize socket connection
  useEffect(() => {
    if (user) {
      const newSocket = io(process.env.REACT_APP_API_URL, {
        auth: {
          token: localStorage.getItem('token')
        }
      });

      setSocket(newSocket);

      return () => newSocket.close();
    }
  }, [user]);

  // Check for existing token on app load
  useEffect(() => {
    const token = localStorage.getItem('token');
    if (token) {
      axios.get(`${process.env.REACT_APP_API_URL}/api/auth/verify`, {
        headers: { Authorization: `Bearer ${token}` }
      })
      .then(response => {
        setUser(response.data.user);
      })
      .catch(() => {
        localStorage.removeItem('token');
      });
    }
  }, []);

  const login = (userData, token) => {
    localStorage.setItem('token', token);
    setUser(userData);
  };

  const logout = () => {
    if (socket) {
      socket.emit('logout');
      socket.close();
    }
    localStorage.removeItem('token');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      <SocketContext.Provider value={socket}>
        <Router>
          <Routes>
            <Route path="/login" element={user ? <Navigate to="/" /> : <Login />} />
            <Route path="/register" element={user ? <Navigate to="/" /> : <Register />} />
            <Route path="/" element={user ? <Dashboard /> : <Navigate to="/login" />} />
            <Route path="/chat/:userId" element={user ? <Chat /> : <Navigate to="/login" />} />
            <Route path="/profile" element={user ? <Profile /> : <Navigate to="/login" />} />
            <Route path="/subscriptions" element={user ? <Subscriptions /> : <Navigate to="/login" />} />
          </Routes>
        </Router>
      </SocketContext.Provider>
    </AuthContext.Provider>
  );
};

export default App;
```

### 3. Chat Component (components/Chat/Chat.js)

```jsx
import React, { useState, useEffect, useContext, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { SocketContext } from '../../context/SocketContext';
import { AuthContext } from '../../context/AuthContext';
import Message from './Message';
import PremiumMessageModal from './PremiumMessageModal';

const Chat = () => {
  const { userId } = useParams();
  const socket = useContext(SocketContext);
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [typing, setTyping] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [showPremiumModal, setShowPremiumModal] = useState(false);
  const messagesEndRef = useRef(null);

  // Fetch messages
  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/${userId}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setMessages(response.data);
      } catch (error) {
        console.error('Error fetching messages:', error);
      }
    };

    fetchMessages();
  }, [userId]);

  // Socket event listeners
  useEffect(() => {
    if (socket) {
      socket.on('new message', (message) => {
        if (message.sender === userId || message.receiver === userId) {
          setMessages(prev => [...prev, message]);
        }
      });

      socket.on('typing', ({ from }) => {
        if (from === userId) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 3000);
        }
      });

      return () => {
        socket.off('new message');
        socket.off('typing');
      };
    }
  }, [socket, userId]);

  // Scroll to bottom when messages change
  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim() === '') return;

    if (user.premium) {
      // Send premium message
      socket.emit('private message', {
        to: userId,
        message: newMessage,
        isPremium: true
      });
    } else {
      // Check if message contains premium content
      if (newMessage.includes('💎') || newMessage.includes('premium')) {
        setShowPremiumModal(true);
        return;
      }

      // Send regular message
      socket.emit('private message', {
        to: userId,
        message: newMessage
      });
    }

    setNewMessage('');
  };

  const handleTyping = () => {
    if (!typing) {
      setTyping(true);
      socket.emit('typing', { to: userId });
      setTimeout(() => {
        setTyping(false);
        socket.emit('stop typing', { to: userId });
      }, 3000);
    }
  };

  return (
    <div className="chat-container">
      <div className="messages-container">
        {messages.map((message) => (
          <Message
            key={message._id}
            message={message}
            isOwnMessage={message.sender._id === user.id}
          />
        ))}
        {isTyping && <div className="typing-indicator">User is typing...</div>}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={handleTyping}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>

      {showPremiumModal && (
        <PremiumMessageModal onClose={() => setShowPremiumModal(false)} />
      )}
    </div>
  );
};

export default Chat;
```

