    const fetchUsers = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/auth/users', {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });

        if (response.ok) {
          const data = await response.json();
          setUsers(data.filter(u => u._id !== user._id));
        }
      } catch (error) {
        console.error('Error fetching users:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchUsers();
  }, [user]);

  const handleUserSelect = (user) => {
    setSelectedUser(user);
    // Fetch previous messages with this user
    fetchMessages(user._id);
  };

  const fetchMessages = async (receiverId) => {
    try {
      const response = await fetch(`http://localhost:5000/api/messages/${receiverId}`, {
        headers: {
          'x-auth-token': localStorage.getItem('token')
        }
      });

      if (response.ok) {
        const data = await response.json();
        // Update messages in context
        // This would be more efficient with a proper state management solution
      }
    } catch (error) {
      console.error('Error fetching messages:', error);
    }
  };

  const sendMessage = (content) => {
    if (!selectedUser) return;

    const messageData = {
      senderId: user._id,
      receiverId: selectedUser._id,
      content,
      type: 'text'
    };

    socket.emit('sendMessage', messageData);
  };

  return (
