### 3. Subscriptions Component (`pages/Subscriptions.js`)

```jsx
import React, { useState, useEffect, useContext } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import AuthContext from '../context/AuthContext';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

function Subscriptions() {
  const { user } = useContext(AuthContext);
  const [subscription, setSubscription] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchSubscriptionStatus = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/subscriptions/status', {
          headers: {
            'x-auth-token': localStorage.getItem('token')
          }
        });

        if (response.ok) {
          const data = await response.json();
          setSubscription(data);
        }
      } catch (err) {
        setError('Failed to fetch subscription status');
        console.error(err);
      } finally {
        setLoading(false);
      }
    };

    fetchSubscriptionStatus();
  }, []);

  const handleSubscribe = async (plan) => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch('http://localhost:5000/api/subscriptions/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': localStorage.getItem('token')
        },
        body: JSON.stringify({ plan })
      });

      if (!response.ok) {
        throw new Error('Failed to create subscription');
      }

      const { subscriptionId, clientSecret } = await response.json();

      const stripe = await stripePromise;

      const { error } = await stripe.confirmPayment({
        elements: null,
        clientSecret,
        confirmParams: {
          return_url: `${window.location.origin}/subscriptions?subscription_id=${subscriptionId}`,
        },
      });

      if (error) {
        setError(error.message);
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="subscriptions-container">
      <h2>Premium Subscriptions</h2>

      {error && <div className="error-message">{error}</div>}

      {subscription?.active ? (
        <div className="active-subscription">
          <h3>Your Current Plan: {subscription.plan}</h3>
          <p>Expires: {new Date(subscription.currentPeriodEnd).toLocaleDateString()}</p>
          <button onClick={() => handleSubscribe('premium')}>
            Upgrade Plan
          </button>
        </div>
      ) : (
        <div className="subscription-plans">
          <div className="plan-card">
            <h3>Basic Plan</h3>
            <p>$5/month</p>
            <ul>
              <li>Basic messaging features</li>
              <li>Limited storage</li>
            </ul>
            <button onClick={() => handleSubscribe('basic')}>
              Subscribe
            </button>
          </div>

          <div className="plan-card premium">
            <h3>Premium Plan</h3>
            <p>$10/month</p>
            <ul>
              <li>All basic features</li>
              <li>Unlimited storage</li>
              <li>Priority support</li>
            </ul>
            <button onClick={() => handleSubscribe('premium')}>
              Subscribe
            </button>
          </div>

          <div className="plan-card enterprise">
            <h3>Enterprise Plan</h3>
            <p>$20/month</p>
            <ul>
              <li>All premium features</li>
              <li>Advanced analytics</li>
              <li>Dedicated account manager</li>
            </ul>
            <button onClick={() => handleSubscribe('enterprise')}>
              Subscribe
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

export default Subscriptions;
```

