import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import { io } from 'socket.io-client';
import AuthContext from './context/AuthContext';
import PrivateRoute from './components/PrivateRoute';
import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Chat from './pages/Chat';
import Notifications from './pages/Notifications';
import Premium from './pages/Premium';
import Navbar from './components/Navbar';

const socket = io('http://localhost:5000');

function App() {
  const [auth, setAuth] = useState({
    token: localStorage.getItem('token'),
    user: null
  });

  useEffect(() => {
    if (auth.token) {
      // Fetch user data
      fetchUserData();
    }
  }, [auth.token]);

  const fetchUserData = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/auth/me', {
        headers: {
          'x-auth-token': auth.token
        }
      });

      const data = await res.json();
      setAuth({ ...auth, user: data });

      // Join user's room for real-time notifications
      socket.emit('joinRoom', data._id);
    } catch (err) {
      console.error(err);
      logout();
    }
  };

  const login = (token) => {
    localStorage.setItem('token', token);
    setAuth({ ...auth, token });
  };

  const logout = () => {
    localStorage.removeItem('token');
    setAuth({ token: null, user: null });
  };

  return (
    <AuthContext.Provider value={{ auth, login, logout }}>
      <Router>
        <div className="app">
          <Navbar />
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/chat/:userId" element={<PrivateRoute><Chat socket={socket} /></PrivateRoute>} />
            <Route path="/notifications" element={<PrivateRoute><Notifications socket={socket} /></PrivateRoute>} />
            <Route path="/premium" element={<PrivateRoute><Premium /></PrivateRoute>} />
          </Routes>
        </div>
      </Router>
    </AuthContext.Provider>
  );
}

export default App;
```

