```javascript
import React, { useState, useEffect, useContext, useRef } from 'react';
import { useParams } from 'react-router-dom';
import AuthContext from '../context/AuthContext';
import Message from '../components/Message';

const Chat = ({ socket }) => {
  const { userId } = useParams();
  const { auth } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [recipient, setRecipient] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch messages
    const fetchMessages = async () => {
      try {
        const res = await fetch(`http://localhost:5000/api/messages/${userId}`, {
          headers: {
            'x-auth-token': auth.token
          }
        });

        const data = await res.json();
        setMessages(data);

        // Mark messages as read
        await fetch(`http://localhost:5000/api/messages/read/${userId}`, {
          method: 'PUT',
          headers: {
            'x-auth-token': auth.token
          }
        });
      } catch (err) {
        console.error(err);
      }
    };

    // Fetch recipient info
    const fetchRecipient = async () => {
      try {
        const res = await fetch(`http://localhost:5000/api/users/${userId}`, {
          headers: {
            'x-auth-token': auth.token
          }
        });

        const data = await res.json();
        setRecipient(data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMessages();
    fetchRecipient();

    // Listen for new messages
    socket.on('newMessage', (message) => {
      if (message.sender === userId || message.recipient === userId) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off('newMessage');
    };
  }, [userId, auth.token, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async (e) => {
    e.preventDefault();

    if (!newMessage.trim()) return;

    try {
      const res = await fetch('http://localhost:5000/api/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': auth.token
        },
        body: JSON.stringify({
          recipientId: userId,
          content: newMessage
        })
      });

      const data = await res.json();
      setMessages(prev => [...prev, data]);
      setNewMessage('');
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        {recipient && (
          <>
            <img src={recipient.profilePicture || '/default-avatar.png'} alt={recipient.username} />
            <h2>{recipient.username}</h2>
          </>
        )}
      </div>

      <div className="messages-container">
        {messages.map(message => (
          <Message
            key={message._id}
            message={message}
            isOwnMessage={message.sender === auth.user._id}
          />
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={sendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

export default Chat;
```

