```javascript
require('dotenv').config();
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const mongoose = require('mongoose');
const cors = require('cors');
const authRoutes = require('./routes/auth');
const messageRoutes = require('./routes/messages');
const userRoutes = require('./routes/users');
const subscriptionRoutes = require('./routes/subscriptions');
const { authenticateSocket } = require('./middleware/auth');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(express.json());

// Database connection
mongoose.connect(process.env.MONGODB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true
})
.then(() => console.log('Connected to MongoDB'))
.catch(err => console.error('MongoDB connection error:', err));

// Routes
app.use('/api/auth', authRoutes);
app.use('/api/messages', messageRoutes);
app.use('/api/users', userRoutes);
app.use('/api/subscriptions', subscriptionRoutes);

// Socket.io connection
io.use(authenticateSocket);

io.on('connection', (socket) => {
  console.log('New client connected:', socket.userId);

  // Join user's personal room
  socket.join(socket.userId);

  // Handle private messages
  socket.on('private message', ({ to, content }) => {
    const message = {
      from: socket.userId,
      to,
      content,
      timestamp: new Date()
    };

    // Save to database (in a real app, you'd do this asynchronously)
    // Then emit to recipient
    socket.to(to).emit('private message', message);
  });

  // Handle typing indicators
  socket.on('typing', ({ to }) => {
    socket.to(to).emit('typing', { from: socket.userId });
  });

  // Handle read receipts
  socket.on('read', ({ messageId, from }) => {
    socket.to(from).emit('read', { messageId });
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected:', socket.userId);
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Something went wrong!' });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
