#### Message Routes (`routes/messages.js`)

```javascript
const express = require('express');
const router = express.Router();
const Message = require('../models/Message');
const User = require('../models/User');
const { authenticate } = require('../middleware/auth');

// Get conversation messages
router.get('/:userId', authenticate, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.userId, recipient: req.params.userId },
        { sender: req.params.userId, recipient: req.userId }
      ]
    })
    .sort({ timestamp: 1 })
    .populate('sender', 'username profilePicture')
    .populate('recipient', 'username profilePicture');

    res.json(messages);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Send message
router.post('/:userId', authenticate, async (req, res) => {
  try {
    const { content, isPremium } = req.body;

    // Check if recipient exists
    const recipient = await User.findById(req.params.userId);
    if (!recipient) {
      return res.status(404).json({ error: 'Recipient not found' });
    }

    // Check if sender is premium if sending premium message
    if (isPremium) {
      const sender = await User.findById(req.userId);
      if (!sender.premium) {
        return res.status(403).json({ error: 'Premium feature requires subscription' });
      }
    }

    const message = new Message({
      sender: req.userId,
      recipient: req.params.userId,
      content,
      isPremium
    });

    await message.save();

    // Populate sender info
    await message.populate('sender', 'username profilePicture');

    res.status(201).json(message);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Mark message as read
router.put('/:messageId/read', authenticate, async (req, res) => {
  try {
    const message = await Message.findById(req.params.messageId);

    if (!message) {
      return res.status(404).json({ error: 'Message not found' });
    }

    if (message.recipient.toString() !== req.userId) {
      return res.status(403).json({ error: 'Not authorized' });
    }

    message.read = true;
    message.readAt = new Date();
    await message.save();

    res.json(message);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

module.exports = router;
```

#### Subscription Routes (`routes/subscriptions.js`)

```javascript
const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const Subscription = require('../models/Subscription');
const { authenticate } = require('../middleware/auth');

// Create subscription
router.post('/create', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.userId);

    // Create Stripe customer if not exists
    if (!user.stripeCustomerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username
      });
      user.stripeCustomerId = customer.id;
      await user.save();
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: user.stripeCustomerId,
      items: [{ price: process.env.STRIPE_PREMIUM_PRICE_ID }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: user._id,
      stripeSubscriptionId: subscription.id,
      status: subscription.status,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Get current subscription
router.get('/current', authenticate, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({ user: req.userId, status: 'active' });

    if (!subscription) {
      return res.json({ active: false });
    }

    res.json({
      active: true,
      subscriptionId: subscription.stripeSubscriptionId,
      currentPeriodEnd: subscription.currentPeriodEnd
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// Webhook for Stripe events
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    console.error('Webhook error:', err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'invoice.payment_succeeded':
      const paymentIntent = event.data.object;
      // Update user's premium status
      const customerId = paymentIntent.customer;
      const user = await User.findOne({ stripeCustomerId: customerId });

      if (user) {
        user.premium = true;
        user.premiumExpiration = new Date(paymentIntent.lines.data[0].period.end * 1000);
        await user.save();
      }
      break;

    case 'customer.subscription.deleted':
      const subscription = event.data.object;
      // Update user's premium status
      const deletedUser = await User.findOne({ stripeCustomerId: subscription.customer });

      if (deletedUser) {
        deletedUser.premium = false;
        deletedUser.premiumExpiration = null;
        await deletedUser.save();
      }
      break;

    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

module.exports = router;
```

### 5. Middleware

#### Authentication Middleware (`middleware/auth.js`)

```javascript
const jwt = require('jsonwebtoken');

// JWT Authentication
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ error: 'No token, authorization denied' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Token is not valid' });
  }
};

// Socket.io Authentication
const authenticateSocket = (socket, next) => {
  const token = socket.handshake.auth.token;

  if (!token) {
    return next(new Error('Authentication error: No token provided'));
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    socket.userId = decoded.userId;
    next();
  } catch (err) {
    next(new Error('Authentication error: Invalid token'));
  }
};

module.exports = { authenticate, authenticateSocket };
```

