#### Chat Component (`components/Chat/Chat.js`)

```javascript
import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../../context/AuthContext';
import { useSocket } from '../../context/SocketContext';
import Message from './Message';
import PremiumMessage from './PremiumMessage';

function Chat() {
  const { userId } = useParams();
  const { user } = useAuth();
  const socket = useSocket();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [isPremiumMessage, setIsPremiumMessage] = useState(false);
  const [isTyping, setIsTyping] = useState(false);
  const [typingUser, setTypingUser] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    const fetchMessages = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/${userId}`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setMessages(response.data);
      } catch (err) {
        console.error('Error fetching messages:', err);
      }
    };

    fetchMessages();
  }, [userId]);

  useEffect(() => {
    if (socket) {
      // Listen for incoming messages
      socket.on('private message', (message) => {
        if (message.from === userId || message.to === userId) {
          setMessages(prev => [...prev, message]);
        }
      });

      // Listen for typing indicators
      socket.on('typing', ({ from }) => {
        if (from === userId) {
          setTypingUser(from);
          setIsTyping(true);

          // Clear typing indicator after 3 seconds
          setTimeout(() => {
            setIsTyping(false);
            setTypingUser(null);
          }, 3000);
        }
      });

      // Listen for read receipts
      socket.on('read', ({ messageId }) => {
        setMessages(prev => prev.map(msg =>
          msg._id === messageId ? { ...msg, read: true, readAt: new Date() } : msg
        ));
      });
    }

    return () => {
      if (socket) {
        socket.off('private message');
        socket.off('typing');
        socket.off('read');
      }
    };
  }, [socket, userId]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (e) => {
    e.preventDefault();

    if (!newMessage.trim()) return;

    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/messages/${userId}`,
        { content: newMessage, isPremium: isPremiumMessage },
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );

      setMessages(prev => [...prev, response.data]);
      setNewMessage('');
      setIsPremiumMessage(false);

      // Emit message via socket
      if (socket) {
        socket.emit('private message', {
          to: userId,
          content: newMessage,
          isPremium: isPremiumMessage
        });
      }
    } catch (err) {
      console.error('Error sending message:', err);
      alert(err.response?.data?.error || 'Failed to send message');
    }
  };

  const handleTyping = () => {
    if (socket && !isTyping) {
      socket.emit('typing', { to: userId });
    }
  };

  const handleReadReceipt = (messageId) => {
    if (socket) {
      socket.emit('read', { messageId, from: userId });
    }
  };

  return (
    <div className="chat-container">
      <div className="messages">
        {messages.map((message) => (
          message.isPremium ?
            <PremiumMessage
              key={message._id}
              message={message}
              isOwnMessage={message.sender._id === user.id}
              onRead={() => handleReadReceipt(message._id)}
            /> :
            <Message
              key={message._id}
              message={message}
              isOwnMessage={message.sender._id === user.id}
              onRead={() => handleReadReceipt(message._id)}
            />
        ))}
        <div ref={messagesEndRef} />

        {isTyping && typingUser === userId && (
          <div className="typing-indicator">
            <span className="dot"></span>
            <span className="dot"></span>
            <span className="dot"></span>
          </div>
        )}
      </div>

      <form onSubmit={handleSendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={handleTyping}
          placeholder="Type a message..."
          className="message-input"
        />
        {user.premium && (
          <label className="premium-toggle">
            <input
              type="checkbox"
              checked={isPremiumMessage}
              onChange={(e) => setIsPremiumMessage(e.checked)}
            />
            Premium Message
          </label>
        )}
        <button type="submit" className="send-button">Send</button>
      </form>
    </div>
  );
}

export default Chat;
```

