        {},
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );

      const stripe = await stripePromise;
      const { error } = await stripe.redirectToCheckout({
        sessionId: response.data.clientSecret
      });

      if (error) {
        console.error('Stripe error:', error);
        alert('Failed to redirect to checkout');
      }
    } catch (err) {
      console.error('Subscription error:', err);
      alert('Failed to create subscription');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="premium-container">
      <h1>Premium Features</h1>

      {subscription?.active ? (
        <div className="active-subscription">
          <h2>You're a Premium Member!</h2>
          <p>Your subscription will renew on {new Date(subscription.currentPeriodEnd).toLocaleDateString()}</p>
          <p>Enjoy all premium features including:</p>
          <ul>
            <li>Send premium messages</li>
            <li>Exclusive content</li>
            <li>Priority support</li>
          </ul>
        </div>
      ) : (
        <div className="subscription-options">
          <h2>Upgrade to Premium</h2>
          <p>Get access to exclusive features and enhanced messaging capabilities.</p>

          <div className="pricing-plan">
            <h3>Monthly Plan</h3>
            <p className="price">$9.99/month</p>
            <button onClick={handleSubscribe} disabled={loading}>
              {loading ? 'Processing...' : 'Subscribe Now'}
            </button>
          </div>

          <div className="premium-benefits">
            <h3>What you'll get:</h3>
            <ul>
              <li>Send premium messages with special formatting</li>
              <li>Access to exclusive content</li>
              <li>Priority customer support</li>
              <li>Ad-free experience</li>
            </ul>
          </div>
        </div>
      )}
    </div>
  );
}

export default Premium;
