#### Subscription Routes (routes/subscriptions.js)

```javascript
const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const Subscription = require('../models/Subscription');
const authMiddleware = require('../middleware/auth');

// Create subscription
router.post('/create', authMiddleware, async (req, res) => {
  try {
    const { plan } = req.body;
    const user = await User.findById(req.user.id);

    // Create Stripe customer if not exists
    if (!user.stripeCustomerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username
      });
      user.stripeCustomerId = customer.id;
      await user.save();
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: user.stripeCustomerId,
      items: [{ price: process.env[`STRIPE_${plan.toUpperCase()}_PRICE_ID`] }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent'],
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: user._id,
      plan,
      stripeSubscriptionId: subscription.id,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Webhook for Stripe events
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    console.error(err);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'invoice.payment_succeeded':
      const subscription = event.data.object;
      await handleSuccessfulPayment(subscription);
      break;
    case 'customer.subscription.deleted':
      const deletedSubscription = event.data.object;
      await handleSubscriptionDeletion(deletedSubscription);
      break;
    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

async function handleSuccessfulPayment(subscription) {
  try {
    const user = await User.findOne({ stripeCustomerId: subscription.customer });
    if (user) {
      user.premium = true;
      user.premiumExpiration = new Date(subscription.current_period_end * 1000);
      await user.save();

      await Subscription.findOneAndUpdate(
        { stripeSubscriptionId: subscription.id },
        { status: 'active' }
      );
    }
  } catch (err) {
    console.error('Error handling successful payment:', err);
  }
}

async function handleSubscriptionDeletion(subscription) {
  try {
    const user = await User.findOne({ stripeCustomerId: subscription.customer });
    if (user) {
      user.premium = false;
      await user.save();

      await Subscription.findOneAndUpdate(
        { stripeSubscriptionId: subscription.id },
        { status: 'canceled' }
      );
    }
  } catch (err) {
    console.error('Error handling subscription deletion:', err);
  }
}

module.exports = router;
```

