#### Chat Page (pages/Chat.js)

```javascript
import React, { useState, useEffect, useContext, useRef } from 'react';
import { useParams } from 'react-router-dom';
import { Box, TextField, Button, Typography, Paper, Avatar } from '@mui/material';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

const Chat = () => {
  const { userId } = useParams();
  const { user, socket } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState('');
  const [receiver, setReceiver] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch messages
    const fetchMessages = async () => {
      try {
        const res = await axios.get(`/api/messages/${userId}`, {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        });
        setMessages(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    // Fetch receiver info
    const fetchReceiver = async () => {
      try {
        const res = await axios.get(`/api/users/${userId}`, {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        });
        setReceiver(res.data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchMessages();
    fetchReceiver();

    // Join room
    socket.emit('joinRoom', user.id);

    // Listen for new messages
    socket.on('receiveMessage', (newMessage) => {
      if (newMessage.sender === userId || newMessage.receiver === userId) {
        setMessages(prev => [...prev, newMessage]);
      }
    });

    return () => {
      socket.off('receiveMessage');
    };
  }, [userId, user.id, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async (e) => {
    e.preventDefault();
    if (message.trim() === '') return;

    try {
      const newMessage = {
        sender: user.id,
        receiver: userId,
        content: message,
        createdAt: new Date()
      };

      // Send message via socket
      socket.emit('sendMessage', newMessage);

      // Add to local state
      setMessages(prev => [...prev, newMessage]);
      setMessage('');

      // Mark messages as read
      await axios.put(`/api/messages/read/${userId}`, {}, {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: 'calc(100vh - 64px)', p: 2 }}>
      <Typography variant="h5" gutterBottom>
        {receiver ? `Chat with ${receiver.username}` : 'Loading...'}
      </Typography>

      <Paper sx={{ flex: 1, overflow: 'auto', p: 2, mb: 2 }}>
        {messages.map((msg, index) => (
          <Box
            key={index}
            sx={{
              display: 'flex',
              justifyContent: msg.sender === user.id ? 'flex-end' : 'flex-start',
              mb: 1
            }}
          >
            <Box
              sx={{
                maxWidth: '70%',
                p: 1.5,
                borderRadius: 2,
                backgroundColor: msg.sender === user.id ? 'primary.main' : 'grey.300',
                color: msg.sender === user.id ? 'white' : 'black'
              }}
            >
              <Typography variant="body1">{msg.content}</Typography>
              <Typography variant="caption" sx={{ display: 'block', textAlign: 'right', mt: 0.5 }}>
                {new Date(msg.createdAt).toLocaleTimeString()}
              </Typography>
            </Box>
          </Box>
        ))}
        <div ref={messagesEndRef} />
      </Paper>

      <Box component="form" onSubmit={sendMessage} sx={{ display: 'flex' }}>
        <TextField
          fullWidth
          variant="outlined"
          placeholder="Type a message..."
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          sx={{ mr: 1 }}
        />
        <Button type="submit" variant="contained" color="primary">
          Send
        </Button>
      </Box>
    </Box>
  );
};

export default Chat;
```

