            onClick={() => setSelectedUser(u)}
          >
            {u.username}
          </div>
        ))}
      </div>
      <div className="chat-area">
        {selectedUser ? (
          <>
            <div className="messages">
              {messages
                .filter(m => (m.sender === user.id && m.receiver === selectedUser.id) ||
                             (m.sender === selectedUser.id && m.receiver === user.id))
                .map((message, index) => (
                  <Message
                    key={index}
                    message={message}
                    isOwnMessage={message.sender === user.id}
                  />
                ))}
            </div>
            <MessageInput onSendMessage={handleSendMessage} />
          </>
        ) : (
          <div className="no-user-selected">Select a user to start chatting</div>
        )}
      </div>
    </div>
  );
};

