### 4. Subscription Component (`pages/Subscriptions.js`)

```javascript
import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

const CheckoutForm = ({ plan, onSuccess }) => {
  const stripe = useStripe();
  const elements = useElements();
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!stripe || !elements) {
      return;
    }

    setLoading(true);

    try {
      const response = await fetch('http://localhost:5000/api/subscriptions/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ plan })
      });

      const { clientSecret } = await response.json();

      const { error: stripeError, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: {
          card: elements.getElement(CardElement),
        },
      });

      if (stripeError) {
        setError(stripeError.message);
      } else if (paymentIntent.status === 'succeeded') {
        onSuccess();
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <CardElement />
      {error && <div className="error">{error}</div>}
      <button type="submit" disabled={!stripe || loading}>
        {loading ? 'Processing...' : `Subscribe to ${plan} plan`}
      </button>
    </form>
  );
};

const Subscriptions = () => {
  const { user } = useContext(AuthContext);
  const [currentPlan, setCurrentPlan] = useState(null);
  const [showCheckout, setShowCheckout] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState('basic');

  useEffect(() => {
    const fetchSubscription = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/subscriptions/current', {
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`
          }
        });
        const data = await response.json();
        setCurrentPlan(data);
      } catch (err) {
        console.error(err);
      }
    };

    fetchSubscription();
  }, []);

  const handleSubscribe = (plan) => {
    setSelectedPlan(plan);
    setShowCheckout(true);
  };

  const handleCancel = async () => {
    try {
      await fetch('http://localhost:5000/api/subscriptions/cancel', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });
      setCurrentPlan(null);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="subscriptions-container">
      <h1>Subscriptions</h1>

      {currentPlan ? (
        <div className="current-plan">
          <h2>Your Current Plan: {currentPlan.plan}</h2>
          <p>Expires: {new Date(currentPlan.currentPeriodEnd).toLocaleDateString()}</p>
          <button onClick={handleCancel}>Cancel Subscription</button>
        </div>
      ) : (
        <div className="plans">
          <h2>Choose a Plan</h2>
          <div className="plan-cards">
            <div className="plan-card">
              <h3>Basic</h3>
              <p>$5/month</p>
              <ul>
                <li>Standard messaging</li>
                <li>Basic notifications</li>
              </ul>
              <button onClick={() => handleSubscribe('basic')}>Subscribe</button>
            </div>
            <div className="plan-card premium">
              <h3>Premium</h3>
              <p>$10/month</p>
              <ul>
                <li>All Basic features</li>
                <li>Priority support</li>
                <li>Ad-free experience</li>
              </ul>
              <button onClick={() => handleSubscribe('premium')}>Subscribe</button>
            </div>
            <div className="plan-card pro">
              <h3>Pro</h3>
              <p>$15/month</p>
              <ul>
                <li>All Premium features</li>
                <li>Exclusive content</li>
                <li>Early access to new features</li>
              </ul>
              <button onClick={() => handleSubscribe('pro')}>Subscribe</button>
            </div>
          </div>
        </div>
      )}

      {showCheckout && (
        <div className="checkout-modal">
          <div className="checkout-content">
            <h2>Complete Your Subscription</h2>
            <Elements stripe={stripePromise}>
              <CheckoutForm
                plan={selectedPlan}
                onSuccess={() => {
                  setShowCheckout(false);
                  // Refresh subscription status
                  window.location.reload();
                }}
              />
            </Elements>
            <button onClick={() => setShowCheckout(false)}>Cancel</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Subscriptions;
