### 2. Socket.io Implementation (socket.js)

```javascript
const Message = require('./models/Message');
const Notification = require('./models/Notification');
const User = require('./models/User');

let onlineUsers = new Map();

module.exports.setupSocket = (io) => {
  io.on('connection', (socket) => {
    console.log('New client connected:', socket.id);

    // User connects
    socket.on('user_connected', async (userId) => {
      onlineUsers.set(userId, socket.id);
      socket.userId = userId;

      // Notify friends that user is online
      const user = await User.findById(userId).populate('friends');
      if (user && user.friends) {
        user.friends.forEach(friend => {
          if (onlineUsers.has(friend._id.toString())) {
            io.to(onlineUsers.get(friend._id.toString())).emit('friend_online', userId);
          }
        });
      }
    });

    // Send message
    socket.on('send_message', async (data) => {
      try {
        const { senderId, receiverId, content, isPremium } = data;

        // Check if sender is premium if message is premium
        if (isPremium) {
          const sender = await User.findById(senderId);
          if (!sender || !sender.isPremium) {
            socket.emit('error', 'Only premium users can send premium messages');
            return;
          }
        }

        const message = new Message({
          sender: senderId,
          receiver: receiverId,
          content,
          isPremium
        });

        await message.save();

        // Send to receiver if online
        if (onlineUsers.has(receiverId)) {
          io.to(onlineUsers.get(receiverId)).emit('receive_message', message);
        }

        // Create notification for receiver
        const notification = new Notification({
          user: receiverId,
          type: 'message',
          content: `New message from ${senderId}`,
          relatedId: message._id
        });

        await notification.save();

        // Send notification to receiver if online
        if (onlineUsers.has(receiverId)) {
          io.to(onlineUsers.get(receiverId)).emit('new_notification', notification);
        }

        socket.emit('message_sent', message);
      } catch (error) {
        console.error('Error sending message:', error);
        socket.emit('error', 'Failed to send message');
      }
    });

    // Typing indicator
    socket.on('typing', (data) => {
      const { receiverId } = data;
      if (onlineUsers.has(receiverId)) {
        io.to(onlineUsers.get(receiverId)).emit('user_typing', {
          senderId: socket.userId,
          isTyping: true
        });
      }
    });

    // Stop typing
    socket.on('stop_typing', (data) => {
      const { receiverId } = data;
      if (onlineUsers.has(receiverId)) {
        io.to(onlineUsers.get(receiverId)).emit('user_typing', {
          senderId: socket.userId,
          isTyping: false
        });
      }
    });

    // Disconnect
    socket.on('disconnect', async () => {
      console.log('Client disconnected:', socket.id);

      if (socket.userId) {
        onlineUsers.delete(socket.userId);

        // Notify friends that user is offline
        const user = await User.findById(socket.userId).populate('friends');
        if (user && user.friends) {
          user.friends.forEach(friend => {
            if (onlineUsers.has(friend._id.toString())) {
              io.to(onlineUsers.get(friend._id.toString())).emit('friend_offline', socket.userId);
            }
          });
        }
      }
    });
  });
};
```

