### 4. Premium Features (routes/premium.js)

```javascript
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const User = require('../models/User');
const PremiumFeature = require('../models/PremiumFeature');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

// Get premium features
router.get('/features', async (req, res) => {
  try {
    const features = await PremiumFeature.find();
    res.json(features);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch premium features' });
  }
});

// Purchase premium subscription
router.post('/subscribe', auth, async (req, res) => {
  try {
    const { paymentMethodId, planId } = req.body;
    const user = await User.findById(req.user.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Create Stripe customer if not exists
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        payment_method: paymentMethodId,
        invoice_settings: {
          default_payment_method: paymentMethodId
        }
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: customerId,
      items: [{ plan: planId }],
      expand: ['latest_invoice.payment_intent']
    });

    // Update user premium status
    user.isPremium = true;
    user.premiumExpiration = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days
    await user.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (error) {
    console.error('Subscription error:', error);
    res.status(500).json({ error: 'Failed to create subscription' });
  }
});

// Purchase coins
router.post('/buy-coins', auth, async (req, res) => {
  try {
    const { amount, paymentMethodId } = req.body;
    const user = await User.findById(req.user.id);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Create payment intent
    const paymentIntent = await stripe.paymentIntents.create({
      amount: amount * 100, // in cents
      currency: 'usd',
      payment_method: paymentMethodId,
      confirm: true,
      description: `Purchase of ${amount} coins`
    });

    // Update user coins
    user.coins += amount;
    await user.save();

    res.json({
      success: true,
      coins: user.coins,
      paymentIntentId: paymentIntent.id
    });
  } catch (error) {
    console.error('Payment error:', error);
    res.status(500).json({ error: 'Failed to process payment' });
  }
});

// Use coins for premium feature
router.post('/use-coins', auth, async (req, res) => {
  try {
    const { featureId, quantity } = req.body;
    const user = await User.findById(req.user.id);
    const feature = await PremiumFeature.findById(featureId);

    if (!user || !feature) {
      return res.status(404).json({ error: 'User or feature not found' });
    }

    const totalCost = feature.coinCost * quantity;

    if (user.coins < totalCost) {
      return res.status(400).json({ error: 'Insufficient coins' });
    }

    // Deduct coins
    user.coins -= totalCost;
    await user.save();

    // Apply premium feature (implementation depends on feature)
    // For example, if it's a boost feature:
    if (feature.type === 'boost') {
      // Implement boost logic here
    }

    res.json({
      success: true,
      coinsRemaining: user.coins,
      featureApplied: true
    });
  } catch (error) {
    console.error('Coin usage error:', error);
    res.status(500).json({ error: 'Failed to use coins' });
  }
});

module.exports = router;
```

