### 1. Real-time Messaging Component

```jsx
import React, { useState, useEffect, useRef } from 'react';
import { io } from 'socket.io-client';
import { useSelector, useDispatch } from 'react-redux';
import { fetchMessages, sendMessage } from '../redux/actions/messageActions';
import { fetchNotifications } from '../redux/actions/notificationActions';

const MessagingApp = () => {
  const [message, setMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState([]);
  const [onlineFriends, setOnlineFriends] = useState([]);
  const [selectedFriend, setSelectedFriend] = useState(null);
  const socketRef = useRef();
  const messagesEndRef = useRef(null);

  const dispatch = useDispatch();
  const { user } = useSelector(state => state.auth);
  const { messages } = useSelector(state => state.messages);
  const { friends } = useSelector(state => state.users);

  useEffect(() => {
    // Connect to socket server
    socketRef.current = io(process.env.REACT_APP_SOCKET_URL, {
      withCredentials: true,
      query: { userId: user._id }
    });

    // Set up socket event listeners
    const socket = socketRef.current;

    socket.on('connect', () => {
      console.log('Connected to socket server');
      socket.emit('user_connected', user._id);
    });

    socket.on('receive_message', (newMessage) => {
      dispatch({ type: 'ADD_MESSAGE', payload: newMessage });
      if (newMessage.sender !== selectedFriend?._id) {
        // Show notification for new message from other friend
      }
    });

    socket.on('new_notification', (notification) => {
      dispatch(fetchNotifications());
    });

    socket.on('friend_online', (friendId) => {
      setOnlineFriends(prev => [...prev, friendId]);
    });

    socket.on('friend_offline', (friendId) => {
      setOnlineFriends(prev => prev.filter(id => id !== friendId));
    });

    socket.on('user_typing', ({ senderId, isTyping }) => {
      if (isTyping) {
        setTypingUsers(prev => [...prev, senderId]);
      } else {
        setTypingUsers(prev => prev.filter(id => id !== senderId));
      }
    });

    socket.on('error', (error) => {
      console.error('Socket error:', error);
      // Show error to user
    });

    return () => {
      socket.disconnect();
    };
  }, [user._id, dispatch, selectedFriend]);

  useEffect(() => {
    if (selectedFriend) {
      dispatch(fetchMessages(selectedFriend._id));
    }
  }, [selectedFriend, dispatch]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!message.trim() || !selectedFriend) return;

    const newMessage = {
      senderId: user._id,
      receiverId: selectedFriend._id,
      content: message,
      isPremium: false // Set to true if premium message
    };

    socketRef.current.emit('send_message', newMessage);
    setMessage('');
    socketRef.current.emit('stop_typing', { receiverId: selectedFriend._id });
  };

  const handleTyping = () => {
    if (!isTyping && selectedFriend) {
      setIsTyping(true);
      socketRef.current.emit('typing', { receiverId: selectedFriend._id });

      // Reset typing status after 3 seconds of inactivity
      setTimeout(() => {
        if (isTyping) {
          setIsTyping(false);
          socketRef.current.emit('stop_typing', { receiverId: selectedFriend._id });
        }
      }, 3000);
    }
  };

  return (
    <div className="messaging-app">
      <div className="friends-list">
        {friends.map(friend => (
          <div
            key={friend._id}
            className={`friend-item ${selectedFriend?._id === friend._id ? 'selected' : ''}`}
            onClick={() => setSelectedFriend(friend)}
          >
            <span className={`status-indicator ${onlineFriends.includes(friend._id) ? 'online' : 'offline'}`}></span>
            {friend.username}
          </div>
        ))}
      </div>

      <div className="chat-container">
        {selectedFriend ? (
          <>
            <div className="chat-header">
              <h3>{selectedFriend.username}</h3>
              {typingUsers.includes(selectedFriend._id) && (
                <p className="typing-indicator">{selectedFriend.username} is typing...</p>
              )}
            </div>

            <div className="messages-container">
              {messages.map((msg, index) => (
                <div
                  key={index}
                  className={`message ${msg.sender === user._id ? 'sent' : 'received'}`}
                >
                  <p>{msg.content}</p>
                  {msg.isPremium && <span className="premium-badge">Premium</span>}
                  <span className="timestamp">{new Date(msg.createdAt).toLocaleTimeString()}</span>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSendMessage} className="message-form">
              <input
                type="text"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                onKeyDown={handleTyping}
                placeholder="Type a message..."
              />
              <button type="submit">Send</button>
            </form>
          </>
        ) : (
          <div className="no-friend-selected">
            Select a friend to start chatting
          </div>
        )}
      </div>

      <div className="notifications-panel">
        {/* Notification component would go here */}
      </div>
    </div>
  );
};

export default MessagingApp;
```

