          </div>

          {selectedFeature && (
            <div className="feature-quantity">
              <h4>Quantity</h4>
              <input
                type="number"
                min="1"
                value={featureQuantity}
                onChange={(e) => setFeatureQuantity(parseInt(e.target.value) || 1)}
