#### Subscription Routes (routes/subscriptions.js)

```javascript
const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const Subscription = require('../models/Subscription');
const User = require('../models/User');
const auth = require('../middleware/auth');

// Create subscription
router.post('/create', auth, async (req, res) => {
  try {
    const { plan, paymentMethodId } = req.body;

    // Get user
    const user = await User.findById(req.user.id);

    // Create customer in Stripe
    const customer = await stripe.customers.create({
      email: user.email,
      payment_method: paymentMethodId,
      invoice_settings: {
        default_payment_method: paymentMethodId
      }
    });

    // Create subscription in Stripe
    const subscription = await stripe.subscriptions.create({
      customer: customer.id,
      items: [{ price: process.env[`${plan.toUpperCase()}_PLAN_ID`] }],
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: user.id,
      plan,
      stripeSubscriptionId: subscription.id,
      status: subscription.status,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });
    await newSubscription.save();

    // Update user to premium
    user.premium = true;
    await user.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (error) {
    console.error(error.message);
    res.status(500).send('Server error');
  }
});

// Get user's subscription
router.get('/', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({ user: req.user.id })
      .sort({ createdAt: -1 });

    if (!subscription) {
      return res.status(404).json({ error: 'No subscription found' });
    }

    res.json(subscription);
  } catch (error) {
    console.error(error.message);
    res.status(500).send('Server error');
  }
});

// Cancel subscription
router.post('/cancel', auth, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({ user: req.user.id })
      .sort({ createdAt: -1 });

    if (!subscription) {
      return res.status(404).json({ error: 'No subscription found' });
    }

    // Cancel in Stripe
    const canceledSubscription = await stripe.subscriptions.del(
      subscription.stripeSubscriptionId
    );

    // Update in database
    subscription.status = canceledSubscription.status;
    await subscription.save();

    // Update user to non-premium
    const user = await User.findById(req.user.id);
    user.premium = false;
    await user.save();

    res.json({ msg: 'Subscription canceled' });
  } catch (error) {
    console.error(error.message);
    res.status(500).send('Server error');
  }
});

module.exports = router;
```

### 5. Middleware (middleware/auth.js)

```javascript
const jwt = require('jsonwebtoken');

module.exports = function(req, res, next) {
  // Get token from header
  const token = req.header('x-auth-token');

  // Check if no token
  if (!token) {
    return res.status(401).json({ error: 'No token, authorization denied' });
  }

  // Verify token
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded.user;
    next();
  } catch (error) {
    res.status(401).json({ error: 'Token is not valid' });
  }
};
