// components/Chat.js
import React, { useState, useEffect, useRef } from 'react';
import { useParams } from 'react-router-dom';
import axios from 'axios';
import { format } from 'date-fns';

const Chat = ({ user, socket, unreadNotifications }) => {
  const { userId } = useParams();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [chatUser, setChatUser] = useState(null);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch chat user details
    axios.get(`http://localhost:5000/api/users/${userId}`, {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
    })
    .then(response => {
      setChatUser(response.data);
    })
    .catch(error => {
      console.error('Error fetching user:', error);
    });

    // Fetch messages
    axios.get(`http://localhost:5000/api/messages/${userId}`, {
      headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
    })
    .then(response => {
      setMessages(response.data);
    })
    .catch(error => {
      console.error('Error fetching messages:', error);
    });

    // Listen for new messages
    socket.on('message', (message) => {
      if (
        (message.sender === user._id && message.receiver === userId) ||
        (message.sender === userId && message.receiver === user._id)
      ) {
        setMessages(prev => [...prev, message]);
      }
    });

    return () => {
      socket.off('message');
    };
  }, [userId, socket, user]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim() === '') return;

    const messageData = {
      receiverId: userId,
      content: newMessage,
      type: 'text'
    };

    socket.emit('sendMessage', messageData);
    setNewMessage('');
  };

  return (
    <div className="chat-container">
      <div className="chat-header">
        <h2>{chatUser ? chatUser.username : 'Loading...'}</h2>
        <div className="notification-badge">
          {unreadNotifications > 0 && (
            <span className="badge">{unreadNotifications}</span>
          )}
        </div>
      </div>

      <div className="messages-container">
        {messages.map((message) => (
          <div
            key={message._id}
            className={`message ${message.sender === user._id ? 'sent' : 'received'}`}
          >
            <div className="message-content">
              <p>{message.content}</p>
              <span className="timestamp">
                {format(new Date(message.timestamp), 'HH:mm')}
              </span>
            </div>
          </div>
        ))}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSendMessage} className="message-form">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type a message..."
        />
        <button type="submit">Send</button>
      </form>
    </div>
  );
};

export default Chat;
