import React, { useState } from 'react';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { loadStripe } from '@stripe/stripe-js';
import axios from 'axios';

const stripePromise = loadStripe('your_stripe_publishable_key');

const CheckoutForm = ({ user, onSuccess }) => {
  const stripe = useStripe();
  const elements = useElements();
  const [error, setError] = useState(null);
  const [processing, setProcessing] = useState(false);

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!stripe || !elements) {
      return;
    }

    setProcessing(true);

    try {
      const { error: stripeError, paymentMethod } = await stripe.createPaymentMethod({
        type: 'card',
        card: elements.getElement(CardElement),
      });

      if (stripeError) {
        setError(stripeError.message);
        setProcessing(false);
        return;
      }

      const response = await axios.post(
        'http://localhost:5000/api/premium/subscribe',
        { paymentMethodId: paymentMethod.id },
        { headers: { Authorization: `Bearer ${localStorage.getItem('token')}` } }
      );

      if (response.data.clientSecret) {
        const { error: confirmError } = await stripe.confirmCardPayment(
          response.data.clientSecret
        );

        if (confirmError) {
          setError(confirmError.message);
          setProcessing(false);
          return;
        }

        onSuccess();
      }
    } catch (err) {
      setError(err.response?.data?.message || 'An error occurred');
      setProcessing(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div className="form-group">
        <CardElement options={{ style: { base: { fontSize: '16px' } } }} />
      </div>
      {error && <div className="error-message">{error}</div>}
      <button type="submit" disabled={!stripe || processing}>
        {processing ? 'Processing...' : 'Subscribe for $9.99/month'}
      </button>
    </form>
  );
};

const Premium = ({ user, unreadNotifications }) => {
  const [subscribed, setSubscribed] = useState(user?.premium || false);

  const handleSuccess = () => {
    setSubscribed(true);
  };

  return (
    <div className="premium-container">
      <div className="premium-header">
        <h2>Premium Features</h2>
        <div className="notification-badge">
          {unreadNotifications > 0 && (
            <span className="badge">{unreadNotifications}</span>
          )}
        </div>
      </div>

      {subscribed ? (
        <div className="premium-active">
          <h3>Your Premium Subscription is Active!</h3>
          <p>Expires on: {new Date(user.premiumExpiry).toLocaleDateString()}</p>
          <ul>
            <li>✓ Unlimited messages</li>
            <li>✓ Premium profile badge</li>
            <li>✓ Exclusive features</li>
          </ul>
        </div>
      ) : (
        <div className="premium-offer">
          <h3>Upgrade to Premium</h3>
          <p>Get access to exclusive features and benefits:</p>
          <ul>
            <li>✓ Unlimited messages</li>
            <li>✓ Premium profile badge</li>
            <li>✓ Exclusive features</li>
          </ul>
          <div className="payment-form">
            <Elements stripe={stripePromise}>
              <CheckoutForm user={user} onSuccess={handleSuccess} />
            </Elements>
