### 2. Chat Component (`components/chat/Chat.js`)

```javascript
import React, { useContext, useEffect, useState } from 'react';
import { ChatContext } from '../../context/ChatContext';
import { AuthContext } from '../../context/AuthContext';
import Message from './Message';
import MessageInput from './MessageInput';

const Chat = () => {
  const { chatState, setChatState } = useContext(ChatContext);
  const { authState } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (chatState.socket && authState.user) {
      // Join user's room
      chatState.socket.emit('joinRoom', authState.user.id);

      // Listen for new messages
      chatState.socket.on('newMessage', (message) => {
        setMessages(prev => [...prev, message]);
      });

      // Load initial messages
      loadMessages();
    }

    return () => {
      if (chatState.socket) {
        chatState.socket.off('newMessage');
      }
    };
  }, [chatState.socket, authState.user]);

  const loadMessages = async () => {
    try {
      setLoading(true);
      const res = await fetch(`${process.env.REACT_APP_API_URL}/api/messages/${chatState.currentChat}`, {
        headers: {
          'x-auth-token': authState.token
        }
      });
      const data = await res.json();
      setMessages(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const sendMessage = (content) => {
    if (chatState.socket && authState.user) {
      chatState.socket.emit('sendMessage', {
        senderId: authState.user.id,
        receiverId: chatState.currentChat,
        content
      });
    }
  };

  return (
    <div className="chat-container">
      <div className="messages-container">
        {loading ? (
          <p>Loading messages...</p>
        ) : (
          messages.map((message) => (
            <Message key={message._id} message={message} />
          ))
        )}
      </div>
      <MessageInput onSendMessage={sendMessage} />
    </div>
  );
};

export default Chat;
