```javascript
import React, { useContext, useEffect } from 'react';
import { NotificationContext } from '../../context/NotificationContext';
import { AuthContext } from '../../context/AuthContext';
import NotificationItem from './NotificationItem';

const Notifications = () => {
  const { notificationState, setNotificationState } = useContext(NotificationContext);
  const { authState } = useContext(AuthContext);

  useEffect(() => {
    if (authState.token) {
      loadNotifications();
    }
  }, [authState.token]);

  const loadNotifications = async () => {
    try {
      const res = await fetch(`${process.env.REACT_APP_API_URL}/api/notifications`, {
        headers: {
          'x-auth-token': authState.token
        }
      });
      const data = await res.json();
      setNotificationState({
        notifications: data,
        unreadCount: data.filter(n => !n.isRead).length
      });
    } catch (err) {
      console.error(err);
    }
  };

  const markAsRead = async (id) => {
    try {
      await fetch(`${process.env.REACT_APP_API_URL}/api/notifications/${id}`, {
        method: 'PUT',
        headers: {
          'x-auth-token': authState.token
        }
      });

      // Update local state
      setNotificationState(prev => ({
        notifications: prev.notifications.map(n =>
          n._id === id ? { ...n, isRead: true } : n
        ),
        unreadCount: prev.unreadCount - 1
      }));
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="notifications-container">
      <h2>Notifications</h2>
      {notificationState.notifications.length === 0 ? (
        <p>No notifications yet</p>
      ) : (
        notificationState.notifications.map(notification => (
          <NotificationItem
            key={notification._id}
            notification={notification}
            onMarkAsRead={markAsRead}
          />
        ))
      )}
    </div>
  );
};

export default Notifications;
