  const [success, setSuccess] = useState(false);

  useEffect(() => {
    if (authState.token) {
      loadSubscription();
    }
  }, [authState.token]);

  const loadSubscription = async () => {
    try {
      const res = await fetch(`${process.env.REACT_APP_API_URL}/api/subscriptions`, {
        headers: {
          'x-auth-token': authState.token
        }
      });

      if (res.ok) {
        const data = await res.json();
        setSubscription(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!stripe || !elements) {
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // Create subscription on backend
      const res = await fetch(`${process.env.REACT_APP_API_URL}/api/subscriptions/create`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-auth-token': authState.token
        },
        body: JSON.stringify({ plan })
      });

      const { clientSecret } = await res.json();

      // Confirm payment
      const { error: stripeError, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
        payment_method: {
          card: elements.getElement(CardElement),
        },
      });

      if (stripeError) {
        setError(stripeError.message);
      } else if (paymentIntent.status === 'succeeded') {
        setSuccess(true);
        loadSubscription();
      }
    } catch (err) {
      setError('An error occurred. Please try again.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async () => {
    try {
      setLoading(true);
      await fetch(`${process.env.REACT_APP_API_URL}/api/subscriptions/cancel`, {
        method: 'POST',
        headers: {
          'x-auth-token': authState.token
        }
      });
      setSubscription(null);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="subscriptions-container">
      <h2>Subscriptions</h2>

      {subscription ? (
        <div className="current-subscription">
          <h3>Current Plan: {subscription.plan}</h3>
          <p>Status: {subscription.status}</p>
          <p>Expires: {new Date(subscription.currentPeriodEnd).toLocaleDateString()}</p>
          <button onClick={handleCancel} disabled={loading}>
            {loading ? 'Processing...' : 'Cancel Subscription'}
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit}>
          <div className="plan-selection">
            <label>
              <input
                type="radio"
                value="basic"
                checked={plan === 'basic'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Basic ($5/month)
            </label>
            <label>
              <input
                type="radio"
                value="premium"
                checked={plan === 'premium'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Premium ($10/month)
            </label>
            <label>
              <input
                type="radio"
                value="enterprise"
                checked={plan === 'enterprise'}
                onChange={(e) => setPlan(e.target.value)}
              />
              Enterprise ($20/month)
            </label>
          </div>

          <div className="payment-form">
            <CardElement options={{ style: { base: { fontSize: '16px' } } }} />
          </div>

          {error && <div className="error">{error}</div>}
          {success && <div className="success">Subscription successful!</div>}

          <button type="submit" disabled={!stripe || loading}>
            {loading ? 'Processing...' : 'Subscribe'}
          </button>
        </form>
      )}
    </div>
  );
};

export default Subscriptions;
```

