#### Subscription Routes (routes/subscriptions.js)

```javascript
const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const User = require('../models/User');
const Subscription = require('../models/Subscription');
const { authenticate } = require('../middleware/auth');

// Create subscription
router.post('/create', authenticate, async (req, res) => {
  try {
    const { plan } = req.body;
    const user = await User.findById(req.userId);

    // Check if user already has an active subscription
    const existingSubscription = await Subscription.findOne({
      user: req.userId,
      status: 'active'
    });

    if (existingSubscription) {
      return res.status(400).json({ message: 'You already have an active subscription' });
    }

    // Create Stripe customer if not exists
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    // Create subscription
    const priceId = getPriceIdForPlan(plan);
    const subscription = await stripe.subscriptions.create({
      customer: customerId,
      items: [{ price: priceId }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent'],
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: req.userId,
      plan,
      stripeSubscriptionId: subscription.id,
      status: subscription.status,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Get current subscription
router.get('/current', authenticate, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({
      user: req.userId,
      status: 'active'
    });

    if (!subscription) {
      return res.json({ hasSubscription: false });
    }

    res.json({
      hasSubscription: true,
      plan: subscription.plan,
      currentPeriodEnd: subscription.currentPeriodEnd
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Cancel subscription
router.post('/cancel', authenticate, async (req, res) => {
  try {
    const subscription = await Subscription.findOne({
      user: req.userId,
      status: 'active'
    });

    if (!subscription) {
      return res.status(404).json({ message: 'No active subscription found' });
    }

    // Cancel in Stripe
    await stripe.subscriptions.del(subscription.stripeSubscriptionId);

    // Update in database
    subscription.status = 'canceled';
    await subscription.save();

    // Update user premium status
    await User.findByIdAndUpdate(req.userId, {
      premium: false,
      premiumExpiry: null
    });

    res.json({ message: 'Subscription canceled successfully' });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Webhook for Stripe events
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    console.error('Webhook error:', err.message);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'invoice.payment_succeeded':
      const paymentIntent = event.data.object;
      // Update subscription status in database
      await handleSuccessfulPayment(paymentIntent.subscription);
      break;
    case 'customer.subscription.deleted':
      const subscription = event.data.object;
      // Update subscription status in database
      await handleSubscriptionDeletion(subscription.id);
      break;
    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

async function handleSuccessfulPayment(subscriptionId) {
  const subscription = await Subscription.findOne({ stripeSubscriptionId: subscriptionId });

  if (subscription) {
    subscription.status = 'active';
    subscription.currentPeriodEnd = new Date(subscription.currentPeriodEnd * 1000);
    await subscription.save();

    // Update user premium status
    await User.findByIdAndUpdate(subscription.user, {
      premium: true,
      premiumExpiry: subscription.currentPeriodEnd
    });
  }
}

async function handleSubscriptionDeletion(subscriptionId) {
  const subscription = await Subscription.findOne({ stripeSubscriptionId: subscriptionId });

  if (subscription) {
    subscription.status = 'canceled';
    await subscription.save();

    // Update user premium status
    await User.findByIdAndUpdate(subscription.user, {
      premium: false,
      premiumExpiry: null
    });
  }
}

function getPriceIdForPlan(plan) {
  const plans = {
    basic: process.env.STRIPE_BASIC_PRICE_ID,
    premium: process.env.STRIPE_PREMIUM_PRICE_ID,
    ultimate: process.env.STRIPE_ULTIMATE_PRICE_ID
  };

  return plans[plan] || plans.basic;
}

module.exports = router;
```

### 5. Middleware

#### Auth Middleware (middleware/auth.js)

```javascript
const jwt = require('jsonwebtoken');

const authenticate = (req, res, next) => {
  const token = req.header('x-auth-token');

  if (!token) {
    return res.status(401).json({ message: 'No token, authorization denied' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    res.status(401).json({ message: 'Token is not valid' });
  }
};

const authenticateSocket = (socket, next) => {
  const token = socket.handshake.auth.token;

  if (!token) {
    return next(new Error('Authentication error'));
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    socket.userId = decoded.userId;
    next();
  } catch (err) {
    next(new Error('Authentication error'));
  }
};

module.exports = { authenticate, authenticateSocket };
```

