import SocketContext from '../../context/SocketContext';

const Chat = () => {
  const { userId } = useParams();
  const { user } = useContext(AuthContext);
  const socket = useContext(SocketContext);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [contact, setContact] = useState(null);
  const [isTyping, setIsTyping] = useState(false);
  const [typingUsers, setTypingUsers] = useState({});
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch messages
    axios.get(`/api/messages/${userId}`, {
      headers: { 'x-auth-token': localStorage.getItem('token') }
    })
    .then(res => {
      setMessages(res.data);
      // Mark messages as read
      axios.put(`/api/messages/read/${userId}`, {}, {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
    })
    .catch(err => console.error('Error fetching messages:', err));

    // Fetch contact info
    axios.get(`/api/users/${userId}`, {
      headers: { 'x-auth-token': localStorage.getItem('token') }
    })
    .then(res => setContact(res.data))
    .catch(err => console.error('Error fetching contact:', err));

    // Scroll to bottom
    scrollToBottom();
  }, [userId]);

  useEffect(() => {
    if (socket) {
      // Listen for new messages
      socket.on('private message', (message) => {
        if (message.sender === userId || message.receiver === userId) {
          setMessages(prev => [...prev, message]);
          scrollToBottom();
        }
      });

      // Listen for typing indicators
      socket.on('typing', ({ from }) => {
        setTypingUsers(prev => ({ ...prev, [from]: true }));
      });

      socket.on('stop typing', ({ from }) => {
        setTypingUsers(prev => {
          const newTypingUsers = { ...prev };
          delete newTypingUsers[from];
          return newTypingUsers;
        });
      });

      return () => {
        socket.off('private message');
        socket.off('typing');
        socket.off('stop typing');
      };
    }
  }, [socket, userId]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (newMessage.trim() === '') return;

    socket.emit('private message', {
      to: userId,
      message: newMessage
    });

    setNewMessage('');
    socket.emit('stop typing', { to: userId });
  };

  const handleTyping = () => {
    socket.emit('typing', { to: userId });
  };

  const handleStopTyping = () => {
    socket.emit('stop typing', { to: userId });
  };

  const handleSendPremiumMessage = () => {
    if (!user.premium) {
      alert('Premium feature requires subscription');
      return;
    }

    axios.post(`/api/messages/premium/${userId}`, {
      content: newMessage
    }, {
      headers: { 'x-auth-token': localStorage.getItem('token') }
    })
    .then(res => {
      setMessages(prev => [...prev, res.data]);
      setNewMessage('');
      scrollToBottom();
    })
    .catch(err => console.error('Error sending premium message:', err));
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
      {/* Header */}
      <Box sx={{ p: 2, borderBottom: '1px solid #e0e0e0', display: 'flex', alignItems: 'center' }}>
        {contact && (
          <>
            <Avatar src={contact.profilePicture} alt={contact.username} />
            <Box sx={{ ml: 2 }}>
              <Typography variant="h6">{contact.username}</Typography>
              <Typography variant="body2" color="text.secondary">
                {contact.status === 'online' ? 'Online' : `Last seen: ${new Date(contact.lastSeen).toLocaleString()}`}
              </Typography>
            </Box>
          </>
        )}
      </Box>

      {/* Messages */}
      <Box sx={{ flex: 1, overflowY: 'auto', p: 2 }}>
        {messages.map((message, index) => (
          <Box
            key={index}
            sx={{
              display: 'flex',
              justifyContent: message.sender._id === user._id ? 'flex-end' : 'flex-start',
              mb: 1
            }}
          >
            <Paper
              elevation={1}
              sx={{
                p: 1.5,
                maxWidth: '70%',
                backgroundColor: message.sender._id === user._id ? 'primary.main' : 'grey.200',
                color: message.sender._id === user._id ? 'white' : 'black',
                borderRadius: message.sender._id === user._id ? '12px 12px 0 12px' : '12px 12px 12px 0',
                position: 'relative'
              }}
            >
              {message.isPremium && (
                <StarIcon sx={{ fontSize: 16, color: 'gold', position: 'absolute', top: 2, right: 2 }} />
              )}
              <Typography variant="body1">{message.content}</Typography>
              <Typography variant="caption" sx={{ display: 'block', textAlign: 'right', mt: 0.5 }}>
                {new Date(message.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </Typography>
            </Paper>
          </Box>
        ))}

        {Object.keys(typingUsers).length > 0 && (
          <Typography variant="caption" sx={{ ml: 2, color: 'text.secondary' }}>
            {Object.keys(typingUsers).map(userId => (
              <span key={userId}>Typing...</span>
            ))}
          </Typography>
        )}

        <div ref={messagesEndRef} />
      </Box>

      {/* Input */}
      <Box sx={{ p: 2, borderTop: '1px solid #e0e0e0', display: 'flex' }}>
        <TextField
          fullWidth
          variant="outlined"
          placeholder="Type a message..."
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              handleSendMessage(e);
            } else {
              handleTyping();
            }
          }}
          onBlur={handleStopTyping}
          sx={{ mr: 1 }}
        />
        <IconButton
          color="primary"
          onClick={handleSendMessage}
          sx={{ mr: 1 }}
        >
          <SendIcon />
        </IconButton>
        {user.premium && (
          <IconButton
            color="secondary"
            onClick={handleSendPremiumMessage}
            title="Send Premium Message"
          >
            <StarIcon />
          </IconButton>
        )}
      </Box>
    </Box>
  );
};

export default Chat;
