import React, { useState, useEffect, useContext } from 'react';
import axios from 'axios';
import { loadStripe } from '@stripe/stripe-js';
import { CardElement, Elements, useStripe, useElements } from '@stripe/react-stripe-js';
import { Box, Typography, Button, Card, CardContent, CardActions, Grid, CircularProgress } from '@mui/material';
import StarIcon from '@mui/icons-material/Star';
import AuthContext from '../../context/AuthContext';

const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLIC_KEY);

const Subscription = () => {
  const { user } = useContext(AuthContext);
  const [currentSubscription, setCurrentSubscription] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Fetch current subscription
    axios.get('/api/subscriptions/current', {
      headers: { 'x-auth-token': localStorage.getItem('token') }
    })
    .then(res => {
      setCurrentSubscription(res.data);
      setLoading(false);
    })
    .catch(err => {
      console.error('Error fetching subscription:', err);
      setLoading(false);
    });
  }, []);

  const handleSubscribe = async (plan) => {
    try {
      setLoading(true);
      const res = await axios.post('/api/subscriptions/create', { plan }, {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });

      const { clientSecret } = res.data;

      const stripe = await stripePromise;
      const { error } = await stripe.confirmPayment({
        elements: elements,
        clientSecret,
        confirmParams: {
          return_url: `${window.location.origin}/subscription`,
        },
      });

      if (error) {
        console.error('Payment error:', error);
        alert('Payment failed. Please try again.');
      } else {
        // Payment succeeded, refresh subscription status
        const subscriptionRes = await axios.get('/api/subscriptions/current', {
          headers: { 'x-auth-token': localStorage.getItem('token') }
        });
        setCurrentSubscription(subscriptionRes.data);
      }
    } catch (err) {
      console.error('Subscription error:', err);
      alert('Subscription failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = async () => {
    try {
      setLoading(true);
      await axios.post('/api/subscriptions/cancel', {}, {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });

      // Refresh subscription status
      const subscriptionRes = await axios.get('/api/subscriptions/current', {
        headers: { 'x-auth-token': localStorage.getItem('token') }
      });
      setCurrentSubscription(subscriptionRes.data);
    } catch (err) {
      console.error('Cancel error:', err);
      alert('Failed to cancel subscription. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Premium Subscription
      </Typography>

      {currentSubscription?.hasSubscription ? (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Current Plan: {currentSubscription.plan.charAt(0).toUpperCase() + currentSubscription.plan.slice(1)}
            </Typography>
            <Typography variant="body1">
              Status: Active
            </Typography>
            <Typography variant="body1">
              Renews on: {new Date(currentSubscription.currentPeriodEnd).toLocaleDateString()}
            </Typography>
          </CardContent>
          <CardActions>
            <Button
              variant="contained"
              color="error"
              onClick={handleCancel}
              disabled={loading}
            >
              Cancel Subscription
            </Button>
          </CardActions>
        </Card>
      ) : (
        <Elements stripe={stripePromise}>
          <SubscriptionForm
            onSubscribe={handleSubscribe}
            loading={loading}
          />
        </Elements>
      )}
    </Box>
  );
};

