import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { io } from 'socket.io-client';
import axios from 'axios';
import Login from './components/Login';
import Register from './components/Register';
import Chat from './components/Chat';
import Premium from './components/Premium';
import Navbar from './components/Navbar';
import ProtectedRoute from './components/ProtectedRoute';

const socket = io(process.env.REACT_APP_API_URL, {
  autoConnect: false
});

function App() {
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    // Check if user is logged in
    const checkAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        if (token) {
          const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/auth/me`, {
            headers: { Authorization: `Bearer ${token}` }
          });
          setUser(res.data);

          // Connect to socket
          socket.auth = { token };
          socket.connect();

          // Listen for notifications
          socket.on('notification', (notification) => {
            setNotifications(prev => [...prev, notification]);
          });
        }
      } catch (err) {
        console.error('Auth check failed:', err);
        localStorage.removeItem('token');
      }
    };

    checkAuth();

    return () => {
      socket.disconnect();
    };
  }, []);

  const handleLogin = (userData, token) => {
    localStorage.setItem('token', token);
    setUser(userData);
    socket.auth = { token };
    socket.connect();
  };

  const handleLogout = () => {
    localStorage.removeItem('token');
    setUser(null);
    socket.disconnect();
  };

  return (
    <Router>
      <Navbar user={user} onLogout={handleLogout} notifications={notifications} />
      <Routes>
        <Route path="/login" element={<Login onLogin={handleLogin} />} />
        <Route path="/register" element={<Register onRegister={handleLogin} />} />
        <Route
          path="/chat"
          element={
            <ProtectedRoute user={user}>
              <Chat user={user} socket={socket} />
            </ProtectedRoute>
          }
        />
        <Route
          path="/premium"
          element={
            <ProtectedRoute user={user}>
              <Premium user={user} />
            </ProtectedRoute>
          }
        />
        <Route path="/" element={<h1>Welcome to Social Messenger</h1>} />
      </Routes>
    </Router>
  );
}

export default App;
```

### 3. Chat Component (components/Chat.js)

```javascript
import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

const Chat = ({ user, socket }) => {
  const [contacts, setContacts] = useState([]);
  const [selectedContact, setSelectedContact] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    // Fetch contacts
    const fetchContacts = async () => {
      try {
        const token = localStorage.getItem('token');
        const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/users/contacts`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setContacts(res.data);
      } catch (err) {
        console.error('Error fetching contacts:', err);
      }
    };

    fetchContacts();
  }, []);

  useEffect(() => {
    if (selectedContact) {
      // Fetch messages with selected contact
      const fetchMessages = async () => {
        try {
          const token = localStorage.getItem('token');
          const res = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/${selectedContact._id}`, {
            headers: { Authorization: `Bearer ${token}` }
          });
          setMessages(res.data);
        } catch (err) {
          console.error('Error fetching messages:', err);
        }
      };

      fetchMessages();

      // Listen for new messages
      socket.on('private message', ({ from, to, message, timestamp }) => {
        if ((from === selectedContact._id && to === user._id) ||
            (from === user._id && to === selectedContact._id)) {
          setMessages(prev => [...prev, { sender: from, content: message, timestamp }]);
        }
      });

      // Listen for typing indicators
      socket.on('typing', ({ from }) => {
        if (from === selectedContact._id) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 2000);
        }
      });

      return () => {
        socket.off('private message');
        socket.off('typing');
      };
    }
  }, [selectedContact, user._id, socket]);

  useEffect(() => {
    // Scroll to bottom when messages change
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!newMessage.trim() || !selectedContact) return;

    socket.emit('private message', {
      to: selectedContact._id,
      message: newMessage
    });

    setNewMessage('');
  };

  const handleTyping = () => {
    if (selectedContact) {
      socket.emit('typing', { to: selectedContact._id });
    }
  };

  return (
    <div className="chat-container">
      <div className="contacts-list">
        <h2>Contacts</h2>
        {contacts.map(contact => (
          <div
            key={contact._id}
            className={`contact-item ${selectedContact?._id === contact._id ? 'selected' : ''}`}
            onClick={() => setSelectedContact(contact)}
          >
            <img src={contact.profilePicture || '/default-avatar.png'} alt={contact.username} />
            <span>{contact.username}</span>
            {contact.status === 'online' && <span className="online-status"></span>}
          </div>
        ))}
      </div>

      <div className="chat-area">
        {selectedContact ? (
          <>
            <div className="chat-header">
              <h2>{selectedContact.username}</h2>
              {isTyping && <p>{selectedContact.username} is typing...</p>}
            </div>

            <div className="messages-container">
              {messages.map((msg, index) => (
                <div
                  key={index}
                  className={`message ${msg.sender === user._id ? 'sent' : 'received'}`}
                >
                  <p>{msg.content}</p>
                  <small>{new Date(msg.timestamp).toLocaleTimeString()}</small>
                </div>
              ))}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSendMessage} className="message-form">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyDown={handleTyping}
                placeholder="Type a message..."
              />
              <button type="submit">Send</button>
            </form>
          </>
        ) : (
          <div className="no-contact-selected">
            <p>Select a contact to start chatting</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Chat;
```

