### 5. Authentication Middleware (middleware/auth.js)

```javascript
const jwt = require('jsonwebtoken');
const User = require('../models/User');

const authenticate = async (req, res, next) => {
  try {
    const token = req.header('Authorization').replace('Bearer ', '');
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    const user = await User.findOne({ _id: decoded._id });

    if (!user) {
      throw new Error();
    }

    req.token = token;
    req.user = user;
    next();
  } catch (err) {
    res.status(401).send({ error: 'Please authenticate.' });
  }
};

const authenticateSocket = async (socket, next) => {
  try {
    const token = socket.handshake.auth.token;
    if (!token) {
      return next(new Error('Authentication error'));
    }

    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    const user = await User.findOne({ _id: decoded._id });

    if (!user) {
      return next(new Error('Authentication error'));
    }

    socket.userId = user._id.toString();
    next();
  } catch (err) {
    next(new Error('Authentication error'));
  }
};

module.exports = { authenticate, authenticateSocket };
```

### 6. Payment Routes (routes/payments.js)

```javascript
const express = require('express');
const router = express.Router();
const { authenticate } = require('../middleware/auth');
const Payment = require('../models/Payment');
const User = require('../models/User');
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);

// Create a payment intent
router.post('/create-payment-intent', authenticate, async (req, res) => {
  try {
    const { amount, currency, product, productDetails } = req.body;

    const paymentIntent = await stripe.paymentIntents.create({
      amount: amount * 100, // Stripe uses cents
      currency,
      metadata: {
        userId: req.user._id.toString(),
        product,
        productDetails: JSON.stringify(productDetails)
      }
    });

    res.send({
      clientSecret: paymentIntent.client_secret
    });
  } catch (err) {
    res.status(500).send({ error: err.message });
  }
});

// Handle successful payment webhook
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the payment_intent.succeeded event
  if (event.type === 'payment_intent.succeeded') {
    const paymentIntent = event.data.object;
    const userId = paymentIntent.metadata.userId;
    const product = paymentIntent.metadata.product;
    const productDetails = JSON.parse(paymentIntent.metadata.productDetails);

    try {
      // Create payment record
      const payment = new Payment({
        user: userId,
        amount: paymentIntent.amount / 100,
        currency: paymentIntent.currency,
        paymentMethod: paymentIntent.payment_method_types[0],
        transactionId: paymentIntent.id,
        status: 'completed',
        product,
        productDetails
      });

      await payment.save();

      // Update user based on product
      if (product === 'premium_subscription') {
        const user = await User.findById(userId);
        user.premiumStatus = true;
        user.premiumExpiration = new Date(Date.now() + productDetails.duration * 24 * 60 * 60 * 1000);
        await user.save();
      } else if (product === 'coins_package') {
        const user = await User.findById(userId);
        user.coins += productDetails.amount;
        await user.save();
      }
    } catch (err) {
      console.error('Error processing successful payment:', err);
    }
  }

  res.json({ received: true });
});

// Get user's payment history
router.get('/history', authenticate, async (req, res) => {
  try {
    const payments = await Payment.find({ user: req.user._id })
      .sort({ createdAt: -1 })
      .limit(20);

    res.send(payments);
  } catch (err) {
    res.status(500).send({ error: err.message });
  }
});

// Get premium subscription options
router.get('/premium-options', authenticate, async (req, res) => {
  try {
    const options = [
      {
        name: 'Monthly Premium',
        price: 9.99,
        duration: 30,
        features: ['Ad-free experience', 'Special emojis', 'Priority support']
      },
      {
