### 2. ChatPage.js

```javascript
import React, { useState, useEffect, useContext, useRef } from 'react';
import { SocketContext } from '../context/SocketContext';
import { AuthContext } from '../context/AuthContext';
import Message from '../components/Message';
import UserList from '../components/UserList';
import axios from 'axios';

const ChatPage = () => {
  const socket = useContext(SocketContext);
  const { user } = useContext(AuthContext);
  const [messages, setMessages] = useState([]);
  const [currentChat, setCurrentChat] = useState(null);
  const [messageInput, setMessageInput] = useState('');
  const [users, setUsers] = useState([]);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    if (socket && user) {
      // Listen for incoming messages
      socket.on('private message', (message) => {
        if (message.from === currentChat?._id || message.to === currentChat?._id) {
          setMessages(prev => [...prev, message]);
        }
      });

      // Listen for typing indicators
      socket.on('typing', ({ from }) => {
        if (from === currentChat?._id) {
          setIsTyping(true);
          setTimeout(() => setIsTyping(false), 3000);
        }
      });

      // Listen for message read receipts
      socket.on('message read', ({ messageId }) => {
        setMessages(prev => prev.map(msg =>
          msg._id === messageId ? { ...msg, isRead: true } : msg
        ));
      });

      // Fetch initial messages when chat changes
      if (currentChat) {
        fetchMessages(currentChat._id);
      }

      // Fetch user list
      fetchUsers();
    }

    return () => {
      if (socket) {
        socket.off('private message');
        socket.off('typing');
        socket.off('message read');
      }
    };
  }, [socket, user, currentChat]);

  const fetchMessages = async (userId) => {
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/messages/${userId}`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setMessages(response.data);
    } catch (err) {
      console.error('Error fetching messages:', err);
    }
  };

  const fetchUsers = async () => {
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/users`, {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
      });
      setUsers(response.data);
    } catch (err) {
      console.error('Error fetching users:', err);
    }
  };

  const handleSendMessage = (e) => {
    e.preventDefault();
    if (!messageInput.trim() || !currentChat) return;

    const message = {
      content: messageInput,
      to: currentChat._id
    };

    socket.emit('private message', message);
    setMessageInput('');
  };

  const handleTyping = () => {
    if (currentChat && socket) {
      socket.emit('typing', { to: currentChat._id });
    }
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  return (
    <div className="chat-container">
      <UserList
        users={users}
        currentChat={currentChat}
        onSelectUser={setCurrentChat}
      />

      <div className="chat-area">
        {currentChat ? (
          <>
            <div className="chat-header">
              <h2>{currentChat.username}</h2>
              {isTyping && <span className="typing-indicator">typing...</span>}
            </div>

            <div className="messages">
              {messages.map((message) => (
                <Message
                  key={message._id}
                  message={message}
                  isOwnMessage={message.from === user._id}
                />
              ))}
              <div ref={messagesEndRef} />
            </div>

            <form onSubmit={handleSendMessage} className="message-form">
              <input
                type="text"
                value={messageInput}
                onChange={(e) => setMessageInput(e.target.value)}
                onKeyDown={handleTyping}
                placeholder="Type a message..."
              />
              <button type="submit">Send</button>
            </form>
          </>
        ) : (
          <div className="no-chat-selected">
            <p>Select a user to start chatting</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage;
```

