  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchPremiumOptions = async () => {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/payments/premium-options`, {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        });
        setPremiumOptions(response.data);
      } catch (err) {
        setError('Failed to load premium options');
        console.error(err);
      }
    };

    fetchPremiumOptions();
  }, []);

  const handlePurchase = async () => {
    if (!selectedOption) return;

    setLoading(true);
    setError(null);

    try {
      const stripe = await stripePromise;

      // Create payment intent
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/payments/create-payment-intent`,
