      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/payments/create-payment-intent`,
        {
          amount: selectedPackage.price,
          currency: 'USD',
          product: 'coins_package',
          productDetails: {
            amount: selectedPackage.amount,
            bonus: selectedPackage.bonus
          }
        },
        {
          headers: { Authorization: `Bearer ${localStorage.getItem('token')}` }
        }
      );

      // Confirm payment with Stripe
      const { error: stripeError } = await stripe.confirmPayment({
        elements: null,
        clientSecret: response.data.clientSecret,
        confirmParams: {
          return_url: `${window.location.origin}/coins?success=true`,
        },
      });

      if (stripeError) {
        setError(stripeError.message);
      }
    } catch (err) {
      setError('Failed to process payment');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  // Check for successful payment
  useEffect(() => {
    const query = new URLSearchParams(window.location.search);
    if (query.get('success') === 'true') {
      // Update user context to reflect new coin balance
      // In a real app, you would fetch the updated user data
      updateUser({ ...user, coins: user.coins + selectedPackage.amount + selectedPackage.bonus });
      window.history.replaceState({}, document.title, '/coins');
    }
  }, [user, updateUser, selectedPackage]);

  return (
    <div className="coins-page">
      <h1>Buy Coins</h1>

      <div className="coin-balance">
        <h2>Your Coins: {user.coins}</h2>
      </div>

      <div className="coin-packages">
        {coinPackages.map((pkg, index) => (
          <div
            key={index}
            className={`package-card ${selectedPackage === pkg ? 'selected' : ''}`}
            onClick={() => setSelectedPackage(pkg)}
          >
            <h3>{pkg.name}</h3>
            <p className="coins">{pkg.amount} coins</p>
            {pkg.bonus > 0 && <p className="bonus">+{pkg.bonus} bonus coins</p>}
            <p className="price">${pkg.price.toFixed(2)}</p>
          </div>
        ))}
      </div>

      <button
        onClick={handlePurchase}
        disabled={!selectedPackage || loading}
        className="purchase-button"
      >
        {loading ? 'Processing...' : 'Buy Coins'}
      </button>

      {error && <div className="error-message">{error}</div>}
    </div>
  );
};

export default CoinsPage;
```

