```javascript
const express = require('express');
const router = express.Router();
const Message = require('../models/Message');
const auth = require('../middleware/auth');
const { io } = require('../server');

// Send message
router.post('/', auth, async (req, res) => {
  try {
    const { receiverId, content } = req.body;
    const senderId = req.user.id;

    const message = new Message({
      sender: senderId,
      receiver: receiverId,
      content
    });

    await message.save();

    // Emit message to receiver
    io.to(receiverId.toString()).emit('newMessage', message);

    res.status(201).json(message);
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Get messages between two users
router.get('/:userId', auth, async (req, res) => {
  try {
    const userId = req.params.userId;
    const currentUserId = req.user.id;

    const messages = await Message.find({
      $or: [
        { sender: currentUserId, receiver: userId },
        { sender: userId, receiver: currentUserId }
      ]
    }).sort({ createdAt: 1 });

    res.json(messages);
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Mark messages as read
router.put('/read/:userId', auth, async (req, res) => {
  try {
    const userId = req.params.userId;
    const currentUserId = req.user.id;

    await Message.updateMany(
      { sender: userId, receiver: currentUserId, isRead: false },
      { $set: { isRead: true } }
    );

    res.json({ message: 'Messages marked as read' });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

module.exports = router;
```

#### Subscription Routes (`routes/subscriptions.js`)

```javascript
const express = require('express');
const router = express.Router();
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
const auth = require('../middleware/auth');
const User = require('../models/User');
const Subscription = require('../models/Subscription');

// Create subscription
router.post('/create', auth, async (req, res) => {
  try {
    const { plan } = req.body;
    const userId = req.user.id;

    // Get user
    const user = await User.findById(userId);
    if (!user) {
      return res.status(404).json({ message: 'User not found' });
    }

    // Determine price based on plan
    let priceId;
    switch (plan) {
      case 'basic':
        priceId = process.env.STRIPE_BASIC_PRICE_ID;
        break;
      case 'premium':
        priceId = process.env.STRIPE_PREMIUM_PRICE_ID;
        break;
      case 'pro':
        priceId = process.env.STRIPE_PRO_PRICE_ID;
        break;
      default:
        return res.status(400).json({ message: 'Invalid plan' });
    }

    // Create Stripe customer if not exists
    let customerId = user.stripeCustomerId;
    if (!customerId) {
      const customer = await stripe.customers.create({
        email: user.email,
        name: user.username
      });
      customerId = customer.id;
      user.stripeCustomerId = customerId;
      await user.save();
    }

    // Create subscription
    const subscription = await stripe.subscriptions.create({
      customer: customerId,
      items: [{ price: priceId }],
      payment_behavior: 'default_incomplete',
      expand: ['latest_invoice.payment_intent']
    });

    // Save subscription to database
    const newSubscription = new Subscription({
      user: userId,
      plan,
      stripeSubscriptionId: subscription.id,
      status: subscription.status,
      currentPeriodEnd: new Date(subscription.current_period_end * 1000)
    });

    await newSubscription.save();

    res.json({
      subscriptionId: subscription.id,
      clientSecret: subscription.latest_invoice.payment_intent.client_secret
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

// Webhook for Stripe events
router.post('/webhook', express.raw({ type: 'application/json' }), async (req, res) => {
  const sig = req.headers['stripe-signature'];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    console.error(err);
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  // Handle the event
  switch (event.type) {
    case 'invoice.payment_succeeded':
      const subscription = event.data.object;
      // Update user subscription status
      await Subscription.findOneAndUpdate(
        { stripeSubscriptionId: subscription.subscription },
        {
          status: 'active',
          currentPeriodEnd: new Date(subscription.lines.data[0].current_period_end * 1000)
        }
      );

      // Update user premium status
      const sub = await Subscription.findOne({ stripeSubscriptionId: subscription.subscription });
      await User.findByIdAndUpdate(sub.user, {
        isPremium: true,
        subscriptionPlan: sub.plan,
        subscriptionEndDate: sub.currentPeriodEnd
      });
      break;

    case 'customer.subscription.deleted':
      const canceledSubscription = event.data.object;
      // Update subscription status
      await Subscription.findOneAndUpdate(
        { stripeSubscriptionId: canceledSubscription.id },
        { status: 'canceled' }
      );

      // Update user premium status
      const canceledSub = await Subscription.findOne({ stripeSubscriptionId: canceledSubscription.id });
      await User.findByIdAndUpdate(canceledSub.user, {
        isPremium: false,
        subscriptionPlan: 'free',
        subscriptionEndDate: null
      });
      break;

    default:
      console.log(`Unhandled event type ${event.type}`);
  }

  res.json({ received: true });
});

module.exports = router;
```

### 5. Middleware (`middleware/auth.js`)

```javascript
const jwt = require('jsonwebtoken');

module.exports = function(req, res, next) {
  // Get token from header
  const token = req.header('x-auth-token');

  // Check if no token
  if (!token) {
    return res.status(401).json({ message: 'No token, authorization denied' });
  }

  // Verify token
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ message: 'Token is not valid' });
  }
};
