# Social Messaging App Implementation

Below is an initial implementation outline for a social messaging app with real-time notifications and in-app monetization features.

## Core Architecture

```python
# app.py - Main application file
from flask import Flask, request, jsonify
from flask_socketio import SocketIO, emit
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import generate_password_hash, check_password_hash
import jwt
import datetime
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///messaging_app.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False

db = SQLAlchemy(app)
socketio = SocketIO(app, cors_allowed_origins="*")

# Database Models
class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(128))
    profile_picture = db.Column(db.String(200))
    premium_status = db.Column(db.Boolean, default=False)
    premium_expiry = db.Column(db.DateTime)
    created_at = db.Column(db.DateTime, default=datetime.datetime.utcnow)

    def set_password(self, password):
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

class Message(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    sender_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    receiver_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    content = db.Column(db.Text, nullable=False)
    timestamp = db.Column(db.DateTime, default=datetime.datetime.utcnow)
    is_read = db.Column(db.Boolean, default=False)
    is_premium = db.Column(db.Boolean, default=False)

class Notification(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    message_id = db.Column(db.Integer, db.ForeignKey('message.id'), nullable=False)
    is_read = db.Column(db.Boolean, default=False)
    created_at = db.Column(db.DateTime, default=datetime.datetime.utcnow)

class PremiumFeature(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text)
    price = db.Column(db.Float, nullable=False)
    duration_days = db.Column(db.Integer, nullable=False)

# Authentication Decorator
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing!'}), 403
        try:
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=["HS256"])
            current_user = User.query.filter_by(id=data['user_id']).first()
        except:
            return jsonify({'message': 'Token is invalid!'}), 403
        return f(current_user, *args, **kwargs)
    return decorated

# Routes
@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if User.query.filter_by(username=data['username']).first():
        return jsonify({'message': 'Username already exists'}), 400
    if User.query.filter_by(email=data['email']).first():
        return jsonify({'message': 'Email already exists'}), 400

    new_user = User(username=data['username'], email=data['email'])
    new_user.set_password(data['password'])
    db.session.add(new_user)
    db.session.commit()

    return jsonify({'message': 'User created successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    user = User.query.filter_by(username=data['username']).first()

    if not user or not user.check_password(data['password']):
        return jsonify({'message': 'Invalid credentials'}), 401

    token = jwt.encode({
        'user_id': user.id,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
    }, app.config['SECRET_KEY'])

    return jsonify({'token': token})

# SocketIO Events
@socketio.on('connect')
@token_required
def handle_connect(current_user):
    print(f'User {current_user.username} connected')

@socketio.on('disconnect')
@token_required
def handle_disconnect(current_user):
    print(f'User {current_user.username} disconnected')

@socketio.on('send_message')
@token_required
def handle_send_message(current_user, data):
    receiver = User.query.get(data['receiver_id'])
    if not receiver:
        emit('error', {'message': 'Receiver not found'})
        return

    new_message = Message(
        sender_id=current_user.id,
        receiver_id=receiver.id,
        content=data['content'],
        is_premium=data.get('is_premium', False)
    )
    db.session.add(new_message)
    db.session.commit()

    # Create notification
    notification = Notification(
        user_id=receiver.id,
        message_id=new_message.id
    )
    db.session.add(notification)
    db.session.commit()

    # Emit to receiver
    emit('new_message', {
        'sender_id': current_user.id,
        'content': data['content'],
        'timestamp': new_message.timestamp.isoformat(),
        'is_premium': new_message.is_premium
    }, room=receiver.id)

    # Emit notification to receiver
    emit('new_notification', {
        'message_id': new_message.id,
        'sender_id': current_user.id,
        'content': data['content'],
        'timestamp': notification.created_at.isoformat()
    }, room=receiver.id)

# Premium Features
@app.route('/premium/features', methods=['GET'])
def get_premium_features():
    features = PremiumFeature.query.all()
    return jsonify([{
        'id': f.id,
        'name': f.name,
        'description': f.description,
        'price': f.price,
        'duration_days': f.duration_days
    } for f in features])

@app.route('/premium/purchase', methods=['POST'])
@token_required
def purchase_premium(current_user):
    data = request.get_json()
    feature = PremiumFeature.query.get(data['feature_id'])

    if not feature:
        return jsonify({'message': 'Feature not found'}), 404

