// functions/index.js
const functions = require('firebase-functions');
const admin = require('firebase-admin');
admin.initializeApp();

exports.checkPremiumExpiration = functions.pubsub.schedule('every 24 hours').onRun(async (context) => {
  const now = admin.firestore.Timestamp.now();
  const usersRef = admin.firestore().collection('users');

  // Find users whose premium has expired
  const expiredUsers = await usersRef
    .where('isPremium', '==', true)
    .where('premiumExpiration', '<', now)
    .get();

  const batch = admin.firestore().batch();

  expiredUsers.forEach((doc) => {
    batch.update(doc.ref, {
      isPremium: false,
      premiumExpiration: null
    });
  });

  await batch.commit();
  console.log(`Updated ${expiredUsers.size} users whose premium has expired`);
});

