@app.route('/messages', methods=['POST'])
def send_message():
    data = request.get_json()
    token = request.headers.get('Authorization')

    try:
        payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
        sender_id = payload['user_id']
    except:
        return jsonify({'message': 'Invalid token'}), 401

    receiver = User.query.filter_by(username=data['receiver']).first()
    if not receiver:
        return jsonify({'message': 'Receiver not found'}), 404

    message = Message(
        sender_id=sender_id,
        receiver_id=receiver.id,
        content=data['content'],
        is_premium=data.get('is_premium', False)
    )
    db.session.add(message)
    db.session.commit()

    # Create notification for receiver
    notification = Notification(
        user_id=receiver.id,
        message_id=message.id,
        content=f"New message from {User.query.get(sender_id).username}"
    )
    db.session.add(notification)
    db.session.commit()

    # Emit real-time notification
    socketio.emit(f'new_message_{receiver.id}', {
        'message': message.content,
        'sender': User.query.get(sender_id).username,
        'timestamp': message.timestamp.isoformat()
    })

    return jsonify({'message': 'Message sent successfully'}), 201

@app.route('/messages/<int:user_id>', methods=['GET'])
def get_messages(user_id):
    token = request.headers.get('Authorization')

    try:
        payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
        current_user_id = payload['user_id']
    except:
        return jsonify({'message': 'Invalid token'}), 401

    messages = Message.query.filter(
        ((Message.sender_id == current_user_id) & (Message.receiver_id == user_id)) |
        ((Message.sender_id == user_id) & (Message.receiver_id == current_user_id))
    ).order_by(Message.timestamp).all()

    return jsonify([{
        'id': msg.id,
        'sender': User.query.get(msg.sender_id).username,
        'content': msg.content,
        'timestamp': msg.timestamp.isoformat(),
        'is_read': msg.is_read,
        'is_premium': msg.is_premium
    } for msg in messages]), 200
