                    'product_data': {
                        'name': feature.name,
                    },
                    'unit_amount': int(feature.price * 100),
                },
                'quantity': 1,
            }],
            mode='payment',
            success_url=url_for('premium_success', _external=True) + f'?session_id={{CHECKOUT_SESSION_ID}}',
            cancel_url=url_for('premium_cancel', _external=True),
            metadata={
                'user_id': user_id,
                'feature_id': feature.id
            }
        )
        return jsonify({'session_id': checkout_session.id}), 200
    except Exception as e:
        return jsonify({'message': str(e)}), 500

@app.route('/premium/success')
