    session_id = request.args.get('session_id')
    session = stripe.checkout.Session.retrieve(session_id)

    user_id = int(session.metadata.user_id)
    feature_id = int(session.metadata.feature_id)

    user = User.query.get(user_id)
    feature = PremiumFeature.query.get(feature_id)

    if user and feature:
        user.premium_status = True
        user.premium_expiry = datetime.datetime.utcnow() + datetime.timedelta(days=feature.duration_days)
        db.session.commit()

        # Create notification
        notification = Notification(
            user_id=user.id,
            content=f"Premium subscription activated: {feature.name}"
        )
        db.session.add(notification)
        db.session.commit()

        return jsonify({'message': 'Premium subscription activated successfully'}), 200

    return jsonify({'message': 'Error activating premium subscription'}), 400

