    current_user.premium_status = True
    current_user.premium_expiry = datetime.datetime.utcnow() + datetime.timedelta(days=feature.duration_days)
    db.session.commit()

    return jsonify({
        'message': 'Premium subscription activated',
        'expiry_date': current_user.premium_expiry.isoformat()
    })

# Notifications
@app.route('/notifications', methods=['GET'])
@token_required
def get_notifications(current_user):
    notifications = Notification.query.filter_by(user_id=current_user.id).order_by(Notification.created_at.desc()).all()

    return jsonify([{
        'id': n.id,
        'message_id': n.message_id,
        'is_read': n.is_read,
        'created_at': n.created_at.isoformat()
    } for n in notifications])

@app.route('/notifications/mark_read', methods=['POST'])
@token_required
def mark_notification_read(current_user):
    data = request.get_json()
    notification = Notification.query.get(data['notification_id'])

    if not notification or notification.user_id != current_user.id:
        return jsonify({'message': 'Notification not found'}), 404

    notification.is_read = True
    db.session.commit()

    return jsonify({'message': 'Notification marked as read'})

