## Frontend Implementation (React Example)

```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';
import axios from 'axios';

const socket = io('http://localhost:5000');

function App() {
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [currentUser, setCurrentUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [premiumFeatures, setPremiumFeatures] = useState([]);

  // Authentication
  const login = async (username, password) => {
    try {
      const response = await axios.post('http://localhost:5000/login', {
        username,
        password
      });
      setToken(response.data.token);
      localStorage.setItem('token', response.data.token);
      // Fetch user data
      const userResponse = await axios.get('http://localhost:5000/user', {
        headers: { Authorization: response.data.token }
      });
      setCurrentUser(userResponse.data);
    } catch (error) {
      console.error('Login failed:', error);
    }
  };

  // Socket.IO setup
  useEffect(() => {
    if (token) {
      socket.on('new_message', (data) => {
        setMessages(prev => [...prev, data]);
      });

      socket.on('new_notification', (data) => {
        setNotifications(prev => [...prev, data]);
      });

      return () => {
        socket.off('new_message');
        socket.off('new_notification');
      };
    }
  }, [token]);

  // Fetch premium features
  useEffect(() => {
    const fetchPremiumFeatures = async () => {
      try {
        const response = await axios.get('http://localhost:5000/premium/features');
        setPremiumFeatures(response.data);
      } catch (error) {
        console.error('Error fetching premium features:', error);
      }
    };
    fetchPremiumFeatures();
  }, []);

  // Send message
  const sendMessage = (receiver, content, isPremium = false) => {
    socket.emit('send_message', {
      receiver,
      content,
      is_premium: isPremium
    });
  };

  // Purchase premium
  const purchasePremium = async (featureId) => {
    try {
      await axios.post('http://localhost:5000/premium/purchase', {
        feature_id: featureId
      }, {
        headers: { Authorization: token }
      });
      // Refresh user data
      const userResponse = await axios.get('http://localhost:5000/user', {
        headers: { Authorization: token }
      });
      setCurrentUser(userResponse.data);
    } catch (error) {
      console.error('Purchase failed:', error);
    }
  };

  return (
    <div className="app">
      {!currentUser ? (
        <LoginForm onLogin={login} />
      ) : (
        <div className="main-app">
          <div className="sidebar">
            <UserProfile user={currentUser} />
            <PremiumFeatures
              features={premiumFeatures}
              onPurchase={purchasePremium}
            />
          </div>
          <div className="chat-area">
            <MessageList messages={messages} />
            <MessageInput onSendMessage={sendMessage} />
          </div>
          <div className="notifications">
            <NotificationList
              notifications={notifications}
              onMarkRead={(id) => {
                // Mark notification as read
                axios.post('http://localhost:5000/notifications/mark_read', {
                  notification_id: id
                }, {
                  headers: { Authorization: token }
                });
              }}
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
```

