## Real-time Messaging with Socket.IO

```python
# realtime.py
from flask_socketio import join_room, leave_room
from models import User, Message, Notification
from database import db

@socketio.on('connect')
def handle_connect():
    print('Client connected')

@socketio.on('disconnect')
def handle_disconnect():
    print('Client disconnected')

@socketio.on('join')
def on_join(data):
    username = data['username']
    user = User.query.filter_by(username=username).first()
    if user:
        join_room(str(user.id))
        emit('status', {'msg': f'{username} has entered the room.'}, room=str(user.id))

@socketio.on('leave')
def on_leave(data):
    username = data['username']
    user = User.query.filter_by(username=username).first()
    if user:
        leave_room(str(user.id))
        emit('status', {'msg': f'{username} has left the room.'}, room=str(user.id))

@socketio.on('send_message')
def handle_message(data):
    sender_username = data['sender']
    recipient_username = data['recipient']
    content = data['content']

    sender = User.query.filter_by(username=sender_username).first()
    recipient = User.query.filter_by(username=recipient_username).first()

    if sender and recipient:
        message = Message(
            content=content,
            sender_id=sender.id,
            recipient_id=recipient.id
        )
        db.session.add(message)
        db.session.commit()

        # Create notification for recipient
        notification = Notification(
            user_id=recipient.id,
            content=f'New message from {sender_username}',
            type='message'
        )
        db.session.add(notification)
        db.session.commit()

        # Emit to recipient's room
        emit('new_message', {
            'sender': sender_username,
            'content': content,
            'timestamp': message.timestamp.isoformat()
        }, room=str(recipient.id))

        # Emit notification to recipient
        emit('new_notification', {
            'content': notification.content,
            'timestamp': notification.timestamp.isoformat(),
            'type': notification.type
        }, room=str(recipient.id))
