## Monetization Implementation

```python
# monetization.py
from flask import Blueprint, request, jsonify
from models import User, Subscription
from extensions import db
import stripe

monetization = Blueprint('monetization', __name__)

@monetization.route('/create-subscription', methods=['POST'])
def create_subscription():
    data = request.json
    user_id = data['user_id']
    payment_method_id = data['payment_method_id']
    plan = data['plan']  # 'basic' or 'premium'

    user = User.query.get(user_id)
    if not user:
        return jsonify({'error': 'User not found'}), 404

    # Create customer in Stripe
    customer = stripe.Customer.create(
        email=user.email,
        payment_method=payment_method_id,
        invoice_settings={'default_payment_method': payment_method_id}
    )

    # Create subscription
    subscription = stripe.Subscription.create(
        customer=customer.id,
        items=[{'price': get_price_id_for_plan(plan)}],
        expand=['latest_invoice.payment_intent']
    )

    # Save subscription to database
    user_subscription = Subscription(
        user_id=user_id,
        stripe_customer_id=customer.id,
        stripe_subscription_id=subscription.id,
        plan=plan
    )
    db.session.add(user_subscription)

    # Update user premium status
    user.premium_status = True
    db.session.commit()

    return jsonify({
        'subscription_id': subscription.id,
        'client_secret': subscription.latest_invoice.payment_intent.client_secret
    })

def get_price_id_for_plan(plan):
    # This would be configured in your Stripe dashboard
    if plan == 'basic':
        return 'price_basic_monthly'
    elif plan == 'premium':
        return 'price_premium_monthly'
    else:
        raise ValueError('Invalid plan')

@monetization.route('/webhook', methods=['POST'])
def stripe_webhook():
    payload = request.data
    sig_header = request.headers.get('Stripe-Signature')
    event = None

    try:
        event = stripe.Webhook.construct_event(
            payload, sig_header, app.config['STRIPE_WEBHOOK_SECRET']
        )
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except stripe.error.SignatureVerificationError as e:
        return jsonify({'error': str(e)}), 400

    # Handle the event
    if event['type'] == 'invoice.payment_succeeded':
        subscription = event['data']['object']
        handle_successful_payment(subscription)
    elif event['type'] == 'customer.subscription.deleted':
        subscription = event['data']['object']
        handle_subscription_cancellation(subscription)

    return jsonify({'success': True})

def handle_successful_payment(subscription):
    # Update user premium status
    user_subscription = Subscription.query.filter_by(
        stripe_subscription_id=subscription.id
    ).first()
    if user_subscription:
        user = User.query.get(user_subscription.user_id)
        user.premium_status = True
        db.session.commit()

def handle_subscription_cancellation(subscription):
    # Update user premium status
    user_subscription = Subscription.query.filter_by(
        stripe_subscription_id=subscription.id
    ).first()
    if user_subscription:
        user = User.query.get(user_subscription.user_id)
        user.premium_status = False
        db.session.commit()
```

