// App.js
import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';
import axios from 'axios';

const socket = io('http://localhost:5000');

function App() {
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [receiverId, setReceiverId] = useState('');
  const [premiumFeatures, setPremiumFeatures] = useState([]);

  useEffect(() => {
    // Check if user is logged in
    const token = localStorage.getItem('token');
    if (token) {
      axios.get('/api/user', {
        headers: { Authorization: token }
      }).then(response => {
        setUser(response.data);
      });
    }

    // Load premium features
    axios.get('/api/premium/features').then(response => {
      setPremiumFeatures(response.data);
    });

    // Socket.io listeners
    socket.on('new_message', (data) => {
      setMessages(prev => [...prev, data]);
    });

    socket.on('new_notification', (data) => {
      setNotifications(prev => [...prev, data]);
    });

    return () => {
      socket.off('new_message');
      socket.off('new_notification');
    };
  }, []);

  const handleLogin = (username, password) => {
    axios.post('/api/login', { username, password })
      .then(response => {
        localStorage.setItem('token', response.data.token);
        setUser({ username });
        socket.connect();
      })
      .catch(error => {
        alert('Login failed');
      });
  };

  const handleSendMessage = () => {
    if (!newMessage.trim()) return;

    socket.emit('send_message', {
      receiver_id: receiverId,
      content: newMessage,
      is_premium: user.premium_status
    });

    setNewMessage('');
  };

  const handlePurchasePremium = (featureId) => {
    axios.post('/api/premium/purchase', { feature_id: featureId }, {
      headers: { Authorization: localStorage.getItem('token') }
    })
    .then(response => {
      alert(`Premium activated! Expires: ${new Date(response.data.expiry_date).toLocaleDateString()}`);
      setUser({ ...user, premium_status: true });
    })
    .catch(error => {
      alert('Purchase failed');
    });
  };

  return (
    <div className="app">
      {!user ? (
        <LoginForm onLogin={handleLogin} />
      ) : (
        <div className="chat-container">
          <div className="messages">
            {messages.map((msg, index) => (
              <div key={index} className={`message ${msg.is_premium ? 'premium' : ''}`}>
                <strong>{msg.sender_id}:</strong> {msg.content}
              </div>
            ))}
          </div>

          <div className="message-input">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              placeholder="Type your message..."
            />
            <input
              type="text"
              value={receiverId}
              onChange={(e) => setReceiverId(e.target.value)}
              placeholder="Receiver ID"
            />
            <button onClick={handleSendMessage}>Send</button>
          </div>

          <div className="notifications">
            <h3>Notifications</h3>
            {notifications.map((notif, index) => (
              <div key={index} className={`notification ${notif.is_read ? 'read' : 'unread'}`}>
                New message from {notif.sender_id}
              </div>
            ))}
          </div>

          {!user.premium_status && (
            <div className="premium-section">
              <h3>Premium Features</h3>
              {premiumFeatures.map(feature => (
                <div key={feature.id} className="premium-option">
                  <h4>{feature.name}</h4>
                  <p>{feature.description}</p>
                  <p>${feature.price} for {feature.duration_days} days</p>
                  <button onClick={() => handlePurchasePremium(feature.id)}>Purchase</button>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

