```javascript
// MessageComponent.js
import React, { useState, useEffect } from 'react';
import io from 'socket.io-client';

const socket = io('http://localhost:5000');

function MessageComponent({ currentUserId, receiverId }) {
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');

  useEffect(() => {
    // Fetch initial messages
    fetch(`/api/messages?receiver_id=${receiverId}`)
      .then(res => res.json())
      .then(data => setMessages(data));

    // Join user room
    socket.emit('join_room', { user_id: currentUserId });

    // Listen for new messages
    socket.on('new_message', (data) => {
      if (data.sender_id === receiverId || data.sender_id === currentUserId) {
        setMessages(prev => [...prev, data]);
      }
    });

    return () => {
      socket.off('new_message');
    };
  }, [currentUserId, receiverId]);

  const sendMessage = () => {
    if (newMessage.trim()) {
      socket.emit('send_message', {
        sender_id: currentUserId,
        receiver_id: receiverId,
        content: newMessage
      });
      setNewMessage('');
    }
  };

  return (
    <div>
      <div className="messages">
        {messages.map(msg => (
          <div key={msg.message_id} className={msg.sender_id === currentUserId ? 'sent' : 'received'}>
            {msg.content}
          </div>
        ))}
      </div>
      <input
        type="text"
        value={newMessage}
        onChange={(e) => setNewMessage(e.target.value)}
        onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
