def login():
    data = request.get_json()
    user = User.query.filter_by(username=data['username']).first()

    if not user or not user.check_password(data['password']):
        return jsonify({'message': 'Invalid credentials'}), 401

    token = jwt.encode({
        'user_id': user.id,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
    }, app.config['SECRET_KEY'])

    return jsonify({'token': token})

@app.route('/messages', methods=['POST'])
@token_required
def send_message(current_user):
    data = request.get_json()
    recipient = User.query.get(data['recipient_id'])

    if not recipient:
        return jsonify({'message': 'Recipient not found'}), 404

    is_premium = data.get('is_premium', False)

    if is_premium and not current_user.premium:
        return jsonify({'message': 'Premium feature requires subscription'}), 403

    new_message = Message(
        content=data['content'],
        user_id=current_user.id,
        recipient_id=recipient.id,
        is_premium=is_premium
    )

    db.session.add(new_message)
    db.session.commit()

    # Create notification for recipient
    new_notification = Notification(
        user_id=recipient.id,
        message_id=new_message.id
    )
    db.session.add(new_notification)
    db.session.commit()

    # Emit real-time notification
    socketio.emit('new_message', {
        'message_id': new_message.id,
        'sender_id': current_user.id,
        'recipient_id': recipient.id,
        'content': new_message.content,
        'timestamp': new_message.timestamp.isoformat()
    }, room=str(recipient.id))

    return jsonify({'message': 'Message sent successfully'}), 201

@app.route('/messages/<int:message_id>', methods=['GET'])
@token_required
def get_message(current_user, message_id):
    message = Message.query.get(message_id)

    if not message:
        return jsonify({'message': 'Message not found'}), 404

    if message.user_id != current_user.id and message.recipient_id != current_user.id:
        return jsonify({'message': 'Unauthorized'}), 403

    if message.is_premium and not current_user.premium:
        return jsonify({'message': 'Premium content requires subscription'}), 403

    if message.recipient_id == current_user.id:
        message.is_read = True
        db.session.commit()

    return jsonify({
        'id': message.id,
        'content': message.content,
        'timestamp': message.timestamp.isoformat(),
        'sender_id': message.user_id,
        'recipient_id': message.recipient_id,
        'is_premium': message.is_premium
    })

@app.route('/notifications', methods=['GET'])
@token_required
def get_notifications(current_user):
    notifications = Notification.query.filter_by(
        user_id=current_user.id,
        is_read=False
    ).order_by(Notification.timestamp.desc()).all()

    return jsonify([{
        'id': n.id,
        'message_id': n.message_id,
        'timestamp': n.timestamp.isoformat()
    } for n in notifications])

