@app.route('/premium/subscribe', methods=['POST'])
@token_required
def subscribe_premium(current_user):
    data = request.get_json()
    # In a real app, you would integrate with a payment processor here
    # For this example, we'll just simulate a successful subscription

    current_user.premium = True
    current_user.premium_expiry = datetime.datetime.utcnow() + datetime.timedelta(days=30)
    db.session.commit()

    return jsonify({
        'message': 'Premium subscription activated',
        'expiry': current_user.premium_expiry.isoformat()
    })

@app.route('/premium/status', methods=['GET'])
@token_required
def premium_status(current_user):
    if current_user.premium and current_user.premium_expiry > datetime.datetime.utcnow():
        return jsonify({
            'premium': True,
            'expiry': current_user.premium_expiry.isoformat()
        })
    else:
        current_user.premium = False
        db.session.commit()
        return jsonify({'premium': False})

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    socketio.run(app, debug=True)
