```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// User authentication (simplified)
app.post('/login', (req, res) => {
    const { username } = req.body;
    if (!username) return res.status(400).send('Username required');

    // In a real app, you'd verify credentials here
    users[username] = { username, online: true };
    res.json({ success: true, username });
});

// Message endpoints
app.post('/send', (req, res) => {
    const { from, to, text, isPremium } = req.body;
    if (!from || !to || !text) return res.status(400).send('Missing fields');

    const message = { from, to, text, timestamp: new Date(), isPremium };
    messages.push(message);

    // Emit to recipient if online
    if (users[to] && users[to].socketId) {
        io.to(users[to].socketId).emit('new-message', message);
    }

    res.json({ success: true });
});

// Premium features
app.post('/upgrade', (req, res) => {
    const { username } = req.body;
    if (!username) return res.status(400).send('Username required');

    // In a real app, you'd process payment here
    premiumUsers.add(username);
    res.json({ success: true, isPremium: true });
});

// Socket.io connection handling
io.on('connection', (socket) => {
    console.log('New client connected');

    socket.on('register', (username) => {
        if (users[username]) {
            users[username].socketId = socket.id;
            users[username].online = true;
            io.emit('user-status', { username, online: true });
        }
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
        for (const [username, user] of Object.entries(users)) {
            if (user.socketId === socket.id) {
                user.online = false;
                io.emit('user-status', { username, online: false });
                break;
            }
        }
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
