# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a minimal working version of a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time communication, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication endpoint
app.post('/login', (req, res) => {
    const { username, password } = req.body;
    // Simple authentication - replace with proper auth in production
    if (username && password) {
        users[username] = { password, online: true };
        res.json({ success: true, username });
    } else {
        res.status(401).json({ success: false, message: 'Invalid credentials' });
    }
});

// Message endpoint
app.post('/message', (req, res) => {
    const { sender, recipient, content, isPremium } = req.body;

    if (isPremium && !premiumUsers.has(sender)) {
        return res.status(403).json({ success: false, message: 'Premium feature' });
    }

    const message = { sender, recipient, content, timestamp: new Date(), isPremium };
    messages.push(message);

    // Emit to recipient if online
    if (users[recipient] && users[recipient].online) {
        io.to(recipient).emit('new message', message);
    }

    res.json({ success: true });
});

// Premium subscription endpoint
app.post('/subscribe', (req, res) => {
    const { username } = req.body;
    premiumUsers.add(username);
    res.json({ success: true, message: 'Premium subscription activated' });
});

// Socket.io connection handling
io.on('connection', (socket) => {
    const username = socket.handshake.query.username;
    if (username) {
        users[username].online = true;
        socket.join(username);

        // Notify friends
        Object.keys(users).forEach(user => {
            if (user !== username && users[user].online) {
                io.to(user).emit('user status', { username, online: true });
            }
        });
    }

    socket.on('disconnect', () => {
        if (username) {
            users[username].online = false;
            Object.keys(users).forEach(user => {
                if (user !== username && users[user].online) {
                    io.to(user).emit('user status', { username, online: false });
                }
            });
        }
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
