    users[username] = { username, password, premium: false };
    res.json({ success: true, username });
  } else {
    res.status(401).json({ success: false, message: 'Invalid credentials' });
  }
});

// Message endpoints
app.post('/send-message', (req, res) => {
  const { sender, receiver, content } = req.body;

  if (!users[sender] || !users[receiver]) {
    return res.status(400).json({ success: false, message: 'Invalid users' });
  }

  const message = {
    id: Date.now().toString(),
    sender,
    receiver,
    content,
    timestamp: new Date().toISOString(),
    read: false
  };

  if (!messages[receiver]) messages[receiver] = [];
  messages[receiver].push(message);

  // Send notification to receiver
  if (!notifications[receiver]) notifications[receiver] = [];
  notifications[receiver].push({
    id: Date.now().toString(),
    type: 'message',
    sender,
    content: `New message from ${sender}`,
    timestamp: new Date().toISOString(),
    read: false
  });

  // Emit real-time notification
  io.to(receiver).emit('new-notification', {
    type: 'message',
    sender,
    content: `New message from ${sender}`
  });

  res.json({ success: true, message });
});

app.get('/messages/:username', (req, res) => {
  const username = req.params.username;
  res.json({ messages: messages[username] || [] });
});

app.get('/notifications/:username', (req, res) => {
  const username = req.params.username;
  res.json({ notifications: notifications[username] || [] });
});

// Monetization endpoints
app.post('/upgrade-to-premium', (req, res) => {
  const { username } = req.body;

  if (!users[username]) {
    return res.status(400).json({ success: false, message: 'User not found' });
  }

  // In a real app, process payment here
  users[username].premium = true;

  // Send premium notification
  if (!notifications[username]) notifications[username] = [];
  notifications[username].push({
    id: Date.now().toString(),
    type: 'premium',
    content: 'You are now a premium user!',
    timestamp: new Date().toISOString(),
    read: false
  });

  io.to(username).emit('new-notification', {
    type: 'premium',
    content: 'You are now a premium user!'
  });

  res.json({ success: true, message: 'Upgraded to premium' });
});

// Socket.io connection handling
io.on('connection', (socket) => {
