# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and in-app monetization. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

// Middleware
app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization;
  if (!token || !users[token]) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = users[token];
  next();
};

// Routes
app.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (users[username]) {
    return res.status(400).json({ error: 'Username already exists' });
  }

  const token = Math.random().toString(36).substring(2);
  users[token] = { username, password, isPremium: false };
  res.json({ token });
});

app.post('/login', (req, res) => {
  const { username, password } = req.body;
  const token = Object.keys(users).find(key =>
    users[key].username === username && users[key].password === password
  );

  if (!token) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  res.json({ token });
});

// Premium subscription endpoint
app.post('/subscribe', authenticate, (req, res) => {
  const { user } = req;
  user.isPremium = true;
  premiumUsers.add(user.username);
  res.json({ success: true, message: 'Premium subscription activated!' });
});

// Socket.io for real-time messaging
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('sendMessage', (data) => {
    const { token, message } = data;
    const user = users[token];

    if (!user) return;

    const newMessage = {
      id: messages.length + 1,
      text: message,
      sender: user.username,
      timestamp: new Date().toISOString(),
      isPremium: premiumUsers.has(user.username)
    };

    messages.push(newMessage);
    io.emit('newMessage', newMessage);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

