```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { initializeApp } from 'firebase/app';
import { getAuth, signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { getFirestore, collection, query, where, onSnapshot, addDoc, doc, updateDoc } from 'firebase/firestore';
import { getMessaging, getToken, onMessage } from 'firebase/messaging';

// Firebase configuration
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);
const messaging = getMessaging(app);

function App() {
  const [user, setUser] = useState(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [selectedUser, setSelectedUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [isPremium, setIsPremium] = useState(false);

  // Authentication
  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      setUser(userCredential.user);
    } catch (error) {
      alert(error.message);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      await fetch('http://localhost:5000/api/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, username })
      });
      setUser(userCredential.user);
    } catch (error) {
      alert(error.message);
    }
  };

  // Get FCM token for push notifications
  useEffect(() => {
    if (user) {
      getToken(messaging, { vapidKey: 'YOUR_VAPID_KEY' }).then((currentToken) => {
        if (currentToken) {
          // Send the token to your server and update the user's FCM token
          updateDoc(doc(db, 'users', user.uid), {
            fcmToken: currentToken
          });
        } else {
          console.log('No registration token available.');
        }
      }).catch((err) => {
        console.log('An error occurred while retrieving token.', err);
      });

      // Listen for incoming messages
      const unsubscribe = onMessage(messaging, (payload) => {
        console.log('Message received. ', payload);
        // You can show a notification here
      });

      return () => unsubscribe();
    }
  }, [user]);

  // Get all users
  useEffect(() => {
    if (user) {
      const q = query(collection(db, 'users'));
      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const usersList = [];
        querySnapshot.forEach((doc) => {
          if (doc.id !== user.uid) {
            usersList.push({ id: doc.id, ...doc.data() });
          }
        });
        setUsers(usersList);
      });

      return () => unsubscribe();
    }
  }, [user]);

  // Get messages with selected user
  useEffect(() => {
    if (user && selectedUser) {
      const q = query(
        collection(db, 'messages'),
        where('senderId', 'in', [user.uid, selectedUser.id]),
        where('receiverId', 'in', [user.uid, selectedUser.id]),
        orderBy('timestamp', 'asc')
      );

      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const messagesList = [];
        querySnapshot.forEach((doc) => {
          messagesList.push({ id: doc.id, ...doc.data() });
        });
        setMessages(messagesList);
      });

      return () => unsubscribe();
    }
  }, [user, selectedUser]);

  // Check premium status
  useEffect(() => {
    if (user) {
      const unsubscribe = onSnapshot(doc(db, 'users', user.uid), (doc) => {
        if (doc.exists()) {
          setIsPremium(doc.data().premium);
        }
      });

      return () => unsubscribe();
    }
  }, [user]);

  const sendMessage = async () => {
    if (!newMessage.trim()) return;

    try {
      const response = await fetch('http://localhost:5000/api/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          senderId: user.uid,
          receiverId: selectedUser.id,
          content: newMessage
        })
      });

      if (!response.ok) {
        const error = await response.json();
        alert(error.error);
      } else {
        setNewMessage('');
      }
    } catch (error) {
      alert(error.message);
    }
  };

  const upgradeToPremium = async () => {
    try {
      // In a real app, you would integrate with a payment processor
      const response = await fetch('http://localhost:5000/api/premium/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.uid,
          paymentToken: 'fake-payment-token' // Replace with actual payment token
        })
      });

      if (response.ok) {
        alert('Successfully upgraded to premium!');
      } else {
        const error = await response.json();
        alert(error.error);
      }
    } catch (error) {
      alert(error.message);
    }
  };

  if (!user) {
    return (
      <div className="auth-container">
        <h1>Social Messaging App</h1>
        <form onSubmit={handleLogin}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Login</button>
        </form>
        <form onSubmit={handleRegister}>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Register</button>
        </form>
      </div>
    );
  }

  return (
    <div className="app-container">
      <div className="sidebar">
        <h2>Users</h2>
        <ul>
          {users.map((u) => (
            <li
              key={u.id}
              onClick={() => setSelectedUser(u)}
              className={selectedUser?.id === u.id ? 'selected' : ''}
            >
              {u.username} {u.premium && <span className="premium-badge">⭐</span>}
            </li>
          ))}
        </ul>
        <div className="premium-section">
          {isPremium ? (
            <p>You're a premium user! 🎉</p>
          ) : (
            <button onClick={upgradeToPremium}>Upgrade to Premium</button>
          )}
        </div>
      </div>

      <div className="chat-container">
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.username}</h2>
            <div className="messages">
              {messages.map((msg) => (
                <div
                  key={msg.id}
                  className={`message ${msg.senderId === user.uid ? 'sent' : 'received'}`}
                >
                  <p>{msg.content}</p>
                  <small>{new Date(msg.timestamp?.toDate()).toLocaleTimeString()}</small>
                </div>
              ))}
            </div>
            <div className="message-input">
              <input
                type="text"
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                placeholder="Type a message..."
                onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
              />
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a user to start chatting</p>
        )}
      </div>
    </div>
  );
}

export default App;
