# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and basic in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and MongoDB for data storage.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const mongoose = require('mongoose');
const http = require('http');
const socketIo = require('socket.io');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// MongoDB connection
mongoose.connect('mongodb://localhost:27017/messagingApp', {
  useNewUrlParser: true,
  useUnifiedTopology: true
});

// User Schema
const userSchema = new mongoose.Schema({
  username: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  premium: { type: Boolean, default: false },
  coins: { type: Number, default: 0 }
});

const User = mongoose.model('User', userSchema);

// Message Schema
const messageSchema = new mongoose.Schema({
  sender: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  receiver: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  content: String,
  timestamp: { type: Date, default: Date.now },
  read: { type: Boolean, default: false }
});

const Message = mongoose.model('Message', messageSchema);

// Middleware
app.use(express.json());

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.header('Authorization')?.replace('Bearer ', '');
  if (!token) return res.status(401).send('Access denied');

  try {
    const verified = jwt.verify(token, 'your-secret-key');
    req.user = verified;
    next();
  } catch (err) {
    res.status(400).send('Invalid token');
  }
};

// Routes
app.post('/register', async (req, res) => {
  try {
    const { username, password } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = new User({ username, password: hashedPassword });
    await user.save();
    res.status(201).send('User created');
  } catch (err) {
    res.status(400).send(err.message);
  }
});

app.post('/login', async (req, res) => {
  try {
    const { username, password } = req.body;
    const user = await User.findOne({ username });
    if (!user) return res.status(400).send('User not found');

    const validPassword = await bcrypt.compare(password, user.password);
    if (!validPassword) return res.status(400).send('Invalid password');

    const token = jwt.sign({ _id: user._id }, 'your-secret-key');
    res.send({ token });
  } catch (err) {
    res.status(400).send(err.message);
  }
});

// Get messages
app.get('/messages', authenticate, async (req, res) => {
  try {
    const messages = await Message.find({
      $or: [
        { sender: req.user._id },
        { receiver: req.user._id }
      ]
    }).populate('sender', 'username').populate('receiver', 'username');
    res.send(messages);
  } catch (err) {
    res.status(400).send(err.message);
  }
});

// Monetization endpoints
app.post('/purchase-premium', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.user._id);
    if (!user) return res.status(404).send('User not found');

    // In a real app, you would verify payment here
    user.premium = true;
    await user.save();
    res.send('Premium subscription activated');
  } catch (err) {
    res.status(400).send(err.message);
  }
});

app.post('/earn-coins', authenticate, async (req, res) => {
  try {
    const user = await User.findById(req.user._id);
    if (!user) return res.status(404).send('User not found');

    // Simple coin earning logic (in a real app, this would be more complex)
    user.coins += 10;
    await user.save();
    res.send(`Coins earned! Total: ${user.coins}`);
  } catch (err) {
    res.status(400).send(err.message);
  }
});

// Socket.io for real-time messaging
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('sendMessage', async ({ receiverId, content }) => {
    try {
      const sender = await User.findById(socket.handshake.auth.token._id);
      if (!sender) return;

      const message = new Message({
        sender: sender._id,
        receiver: receiverId,
        content
      });

      await message.save();

      // Emit to both sender and receiver
      io.to(socket.id).emit('message', message);
      io.to(receiverId).emit('message', message);

      // Emit notification
      io.to(receiverId).emit('notification', {
        type: 'message',
        from: sender.username,
        content: content.substring(0, 20) + (content.length > 20 ? '...' : '')
      });
    } catch (err) {
      console.error(err);
    }
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

