# Minimal Social Messaging App with Real-Time Notifications and Monetization

Here's a basic implementation of a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// In-memory storage (replace with database in production)
const users = {};
const messages = {};
const notifications = {};

// User authentication (simplified)
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // In a real app, verify credentials against database
  users[username] = { username, password, premium: false };
  res.json({ success: true, username });
});

// Message endpoints
app.post('/send-message', (req, res) => {
  const { sender, recipient, content } = req.body;

  if (!messages[recipient]) {
    messages[recipient] = [];
  }

  const message = { sender, content, timestamp: new Date() };
  messages[recipient].push(message);

  // Send real-time notification
  io.to(recipient).emit('new-message', message);

  // Create notification
  if (!notifications[recipient]) {
    notifications[recipient] = [];
  }
  notifications[recipient].push({
    type: 'message',
    sender,
    content: `New message from ${sender}`,
    timestamp: new Date(),
    read: false
  });

  io.to(recipient).emit('new-notification', {
    type: 'message',
    sender,
    content: `New message from ${sender}`
  });

  res.json({ success: true });
});

app.get('/messages/:username', (req, res) => {
  const username = req.params.username;
  res.json(messages[username] || []);
});

app.get('/notifications/:username', (req, res) => {
  const username = req.params.username;
  res.json(notifications[username] || []);
});

// Monetization endpoints
app.post('/purchase-premium', (req, res) => {
  const { username } = req.body;

  if (users[username]) {
    users[username].premium = true;
    res.json({ success: true, premium: true });
  } else {
    res.status(404).json({ success: false, message: 'User not found' });
  }
});

app.get('/user-status/:username', (req, res) => {
  const username = req.params.username;
  if (users[username]) {
    res.json({ premium: users[username].premium });
  } else {
    res.status(404).json({ success: false, message: 'User not found' });
  }
});

// Socket.io connection
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (username) => {
    socket.join(username);
    console.log(`${username} joined`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 5000;
server.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

