      </form>
    </div>

    <div id="chat-container" class="chat-container" style="display: none;">
      <div style="display: flex; justify-content: space-between; align-items: center;">
        <h2>Welcome, <span id="current-user"></span><span id="premium-badge" class="premium-badge" style="display: none;">PREMIUM</span></h2>
        <button id="logout-btn">Logout</button>
      </div>

      <div class="premium-section" id="premium-section">
        <h3>Upgrade to Premium</h3>
        <p>Get access to exclusive features and support the app!</p>
        <button id="upgrade-btn">Upgrade for $4.99/month</button>
      </div>

      <div class="messages" id="messages"></div>

      <form id="message-form" class="message-form">
        <input type="text" id="recipient" placeholder="Recipient" required>
        <textarea id="message-content" placeholder="Your message" required></textarea>
        <button type="submit">Send Message</button>
      </form>
    </div>
  </div>

  <div class="notifications" id="notifications">
    <h3>Notifications</h3>
    <div id="notification-list"></div>
  </div>

  <script src="https://cdn.socket.io/4.5.4/socket.io.min.js"></script>
  <script>
    const socket = io('http://localhost:5000');
    let currentUser = '';

    // Login
    document.getElementById('login-form').addEventListener('submit', async (e) => {
      e.preventDefault();
      const username = document.getElementById('username').value;
      const password = document.getElementById('password').value;

      const response = await fetch('http://localhost:5000/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username, password })
      });

      const data = await response.json();

      if (data.success) {
        currentUser = username;
        document.getElementById('current-user').textContent = username;
        document.getElementById('login-container').style.display = 'none';
        document.getElementById('chat-container').style.display = 'block';

        // Join user's room
        socket.emit('join', username);

        // Load messages and notifications
        loadMessages();
        loadNotifications();

        // Check premium status
        checkPremiumStatus();
      }
    });

    // Logout
    document.getElementById('logout-btn').addEventListener('click', () => {
      currentUser = '';
      document.getElementById('login-container').style.display = 'block';
      document.getElementById('chat-container').style.display = 'none';
    });

    // Send message
    document.getElementById('message-form').addEventListener('submit', async (e) => {
      e.preventDefault();
      const recipient = document.getElementById('recipient').value;
      const content = document.getElementById('message-content').value;

      const response = await fetch('http://localhost:5000/send-message', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sender: currentUser, recipient, content })
      });

      const data = await response.json();

      if (data.success) {
        document.getElementById('message-content').value = '';
        loadMessages();
      }
    });

    // Load messages
    async function loadMessages() {
      const response = await fetch(`http://localhost:5000/messages/${currentUser}`);
      const messages = await response.json();

      const messagesContainer = document.getElementById('messages');
      messagesContainer.innerHTML = '';

      messages.forEach(msg => {
        const messageElement = document.createElement('div');
        messageElement.className = 'message';
        messageElement.innerHTML = `
          <div class="message-sender">${msg.sender}</div>
          <div class="message-content">${msg.content}</div>
          <div class="message-time">${new Date(msg.timestamp).toLocaleString()}</div>
        `;
        messagesContainer.appendChild(messageElement);
      });

      // Scroll to bottom
      messagesContainer.scrollTop = messagesContainer.scrollHeight;
    }

    // Load notifications
    async function loadNotifications() {
      const response = await fetch(`http://localhost:5000/notifications/${currentUser}`);
      const notifications = await response.json();

      const notificationList = document.getElementById('notification-list');
      notificationList.innerHTML = '';

      notifications.forEach(notification => {
        const notificationElement = document.createElement('div');
        notificationElement.className = `notification ${notification.read ? '' : 'unread'}`;
        notificationElement.textContent = notification.content;
        notificationElement.addEventListener('click', () => {
          // Mark as read (in a real app, you'd update the server)
          notification.read = true;
          loadNotifications();
        });
        notificationList.appendChild(notificationElement);
      });
    }

    // Check premium status
    async function checkPremiumStatus() {
      const response = await fetch(`http://localhost:5000/user-status/${currentUser}`);
      const data = await response.json();

      if (data.premium) {
        document.getElementById('premium-badge').style.display = 'inline';
        document.getElementById('premium-section').style.display = 'none';
      }
    }

    // Upgrade to premium
    document.getElementById('upgrade-btn').addEventListener('click', async () => {
      const response = await fetch('http://localhost:5000/purchase-premium', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: currentUser })
      });

      const data = await response.json();

      if (data.success) {
        alert('Upgrade successful! You now have premium features.');
        checkPremiumStatus();
      }
    });

    // Socket.io event listeners
    socket.on('new-message', (message) => {
      if (message.sender !== currentUser) {
        loadMessages();
      }
    });

    socket.on('new-notification', (notification) => {
      loadNotifications();
    });
  </script>
</body>
</html>
