# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and in-app monetization features. This example uses Node.js for the backend, React for the frontend, and Firebase for real-time capabilities and monetization.

## Backend (Node.js + Express + Firebase)

```javascript
// server.js
const express = require('express');
const admin = require('firebase-admin');
const cors = require('cors');
const bodyParser = require('body-parser');

// Initialize Firebase Admin
const serviceAccount = require('./serviceAccountKey.json');
admin.initializeApp({
  credential: admin.credential.cert(serviceAccount),
  databaseURL: "https://your-project.firebaseio.com"
});

const db = admin.firestore();
const app = express();
app.use(cors());
app.use(bodyParser.json());

// User authentication
app.post('/api/register', async (req, res) => {
  try {
    const { email, password, username } = req.body;
    const userRecord = await admin.auth().createUser({
      email,
      password,
      displayName: username
    });

    await db.collection('users').doc(userRecord.uid).set({
      username,
      email,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      premium: false
    });

    res.status(201).json({ uid: userRecord.uid });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Send message
app.post('/api/messages', async (req, res) => {
  try {
    const { senderId, receiverId, content } = req.body;

    // Check if sender is premium or has remaining free messages
    const userDoc = await db.collection('users').doc(senderId).get();
    const userData = userDoc.data();

    if (!userData.premium && userData.freeMessages <= 0) {
      return res.status(403).json({ error: "Free message limit reached. Upgrade to premium." });
    }

    const messageRef = await db.collection('messages').add({
      senderId,
      receiverId,
      content,
      timestamp: admin.firestore.FieldValue.serverTimestamp(),
      read: false
    });

    // Decrement free messages if not premium
    if (!userData.premium) {
      await db.collection('users').doc(senderId).update({
        freeMessages: admin.firestore.FieldValue.increment(-1)
      });
    }

    // Send push notification to receiver
    const receiverDoc = await db.collection('users').doc(receiverId).get();
    const receiverData = receiverDoc.data();

    if (receiverData.fcmToken) {
      const message = {
        notification: {
          title: 'New Message',
          body: `You have a new message from ${userData.username}`
        },
        token: receiverData.fcmToken
      };

      await admin.messaging().send(message);
    }

    res.status(201).json({ id: messageRef.id });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Get messages between two users
app.get('/api/messages/:userId1/:userId2', async (req, res) => {
  try {
    const { userId1, userId2 } = req.params;

    const messagesRef = db.collection('messages')
      .where('senderId', 'in', [userId1, userId2])
      .where('receiverId', 'in', [userId1, userId2])
      .orderBy('timestamp', 'asc');

    const snapshot = await messagesRef.get();
    const messages = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

    res.json(messages);
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

// Premium subscription endpoint
app.post('/api/subscribe', async (req, res) => {
  try {
    const { userId, paymentToken } = req.body;

    // In a real app, you would verify the payment token with your payment processor

    await db.collection('users').doc(userId).update({
      premium: true,
      freeMessages: 100, // Reset free messages
      subscriptionStart: admin.firestore.FieldValue.serverTimestamp()
    });

    res.json({ success: true });
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

## Frontend (React)

```jsx
// App.js
import React, { useState, useEffect } from 'react';
import { initializeApp } from 'firebase/app';
import { getAuth, signInWithEmailAndPassword, createUserWithEmailAndPassword } from 'firebase/auth';
import { getFirestore, collection, query, where, onSnapshot, addDoc } from 'firebase/firestore';
import { getMessaging, getToken, onMessage } from 'firebase/messaging';

// Firebase configuration
const firebaseConfig = {
  apiKey: "YOUR_API_KEY",
  authDomain: "YOUR_AUTH_DOMAIN",
  projectId: "YOUR_PROJECT_ID",
  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

const firebaseApp = initializeApp(firebaseConfig);
const auth = getAuth(firebaseApp);
const db = getFirestore(firebaseApp);
const messaging = getMessaging(firebaseApp);

function App() {
  const [user, setUser] = useState(null);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [message, setMessage] = useState('');
  const [messages, setMessages] = useState([]);
  const [recipient, setRecipient] = useState('');
  const [isPremium, setIsPremium] = useState(false);

  // Request notification permission and get token
  useEffect(() => {
    if (user) {
      Notification.requestPermission().then(permission => {
        if (permission === 'granted') {
          getToken(messaging, { vapidKey: 'YOUR_VAPID_KEY' }).then(token => {
            // Send token to server to save for user
            fetch('/api/save-fcm-token', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ userId: user.uid, token })
            });
          });
        }
      });

      // Listen for incoming messages
      const unsubscribe = onMessage(messaging, (payload) => {
        console.log('Message received: ', payload);
        // You can show a notification here
      });

      return () => unsubscribe();
    }
  }, [user]);

  // Listen for messages in real-time
  useEffect(() => {
    if (user && recipient) {
      const q = query(
        collection(db, 'messages'),
        where('senderId', 'in', [user.uid, recipient]),
        where('receiverId', 'in', [user.uid, recipient]),
        orderBy('timestamp', 'asc')
      );

      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const msgs = [];
        querySnapshot.forEach((doc) => {
          msgs.push({ id: doc.id, ...doc.data() });
        });
        setMessages(msgs);
      });

      return () => unsubscribe();
    }
  }, [user, recipient]);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      setUser(userCredential.user);
      // Check if user is premium
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));
      setIsPremium(userDoc.data().premium);
    } catch (error) {
      alert(error.message);
    }
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      await addDoc(collection(db, 'users'), {
        uid: userCredential.user.uid,
        username,
        email,
        premium: false,
        freeMessages: 10 // Initial free messages
      });
      setUser(userCredential.user);
      setIsPremium(false);
    } catch (error) {
      alert(error.message);
    }
  };

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!user || !recipient || !message) return;

    try {
      await fetch('/api/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          senderId: user.uid,
          receiverId: recipient,
          content: message
        })
      });
      setMessage('');
    } catch (error) {
      alert(error.message);
    }
  };

  const handleUpgrade = async () => {
    try {
      // In a real app, you would integrate with a payment processor
      const response = await fetch('/api/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: user.uid, paymentToken: 'test_token' })
      });
      const result = await response.json();
      if (result.success) {
        setIsPremium(true);
        alert('Successfully upgraded to premium!');
      }
    } catch (error) {
      alert(error.message);
    }
  };

  if (!user) {
    return (
      <div>
        <h1>Login</h1>
        <form onSubmit={handleLogin}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Login</button>
        </form>

        <h1>Register</h1>
        <form onSubmit={handleRegister}>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Register</button>
        </form>
      </div>
    );
  }

  return (
    <div>
      <h1>Welcome, {user.displayName || user.email}</h1>
      {isPremium ? (
        <p>Premium User</p>
      ) : (
        <button onClick={handleUpgrade}>Upgrade to Premium</button>
      )}

      <div>
        <h2>Send Message</h2>
        <input
          type="text"
          placeholder="Recipient ID"
          value={recipient}
          onChange={(e) => setRecipient(e.target.value)}
        />
        <input
          type="text"
          placeholder="Message"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
        />
        <button onClick={handleSendMessage}>Send</button>
      </div>

      <div>
        <h2>Messages</h2>
        {messages.map(msg => (
          <div key={msg.id}>
            <strong>{msg.senderId === user.uid ? 'You' : 'Them'}:</strong> {msg.content}
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
