  storageBucket: "YOUR_STORAGE_BUCKET",
  messagingSenderId: "YOUR_SENDER_ID",
  appId: "YOUR_APP_ID"
};

// Initialize Firebase
const app = initializeApp(firebaseConfig);
const auth = getAuth(app);
const db = getFirestore(app);
const messaging = getMessaging(app);

function App() {
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [recipient, setRecipient] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [isRegistering, setIsRegistering] = useState(false);
  const [isPremium, setIsPremium] = useState(false);

  // Handle authentication
  const handleAuth = async (e) => {
    e.preventDefault();
    try {
      if (isRegistering) {
        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        // Register with backend
        await fetch('http://localhost:5000/api/register', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ email, password, username })
        });
        setUser(userCredential.user);
      } else {
        const userCredential = await signInWithEmailAndPassword(auth, email, password);
        setUser(userCredential.user);
      }
    } catch (error) {
      alert(error.message);
    }
  };

  // Listen for auth state changes
  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (user) => {
      if (user) {
        setUser(user);
        // Get user data from Firestore
        const userDoc = await db.collection('users').doc(user.uid).get();
        if (userDoc.exists) {
          setIsPremium(userDoc.data().premium);
        }

        // Request notification permission
        if ('Notification' in window && Notification.permission !== 'granted') {
          Notification.requestPermission().then(permission => {
            if (permission === 'granted') {
              getToken(messaging, { vapidKey: 'YOUR_VAPID_KEY' }).then((currentToken) => {
                if (currentToken) {
                  // Save the token to Firestore
                  db.collection('users').doc(user.uid).update({
                    fcmToken: currentToken
                  });
                }
              });
            }
          });
        }

        // Listen for messages
        const messagesQuery = query(
          collection(db, 'messages'),
          where('receiverId', '==', user.uid),
          orderBy('timestamp', 'desc')
        );

        const unsubscribeMessages = onSnapshot(messagesQuery, (snapshot) => {
          const messagesData = snapshot.docs.map(doc => ({
            id: doc.id,
            ...doc.data()
          }));
          setMessages(messagesData);
        });

        return () => unsubscribeMessages();
      } else {
        setUser(null);
        setMessages([]);
      }
    });

    return () => unsubscribe();
  }, []);

  // Listen for foreground messages
  useEffect(() => {
    const unsubscribe = onMessage(messaging, (payload) => {
      console.log('Message received. ', payload);
      // You can show a notification here
      new Notification(payload.notification.title, {
        body: payload.notification.body,
      });
    });

    return () => unsubscribe();
  }, []);

  // Send message
  const sendMessage = async () => {
    if (!newMessage.trim() || !recipient.trim()) return;

    try {
      const response = await fetch('http://localhost:5000/api/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          senderId: user.uid,
          receiverId: recipient,
          content: newMessage
        })
      });

      if (!response.ok) {
        const error = await response.json();
        alert(error.error);
      } else {
        setNewMessage('');
        setRecipient('');
      }
    } catch (error) {
      alert(error.message);
    }
  };

  // Subscribe to premium
  const subscribeToPremium = async () => {
    try {
      // In a real app, you would integrate with a payment processor
      const response = await fetch('http://localhost:5000/api/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.uid,
          paymentToken: 'fake-payment-token' // In real app, this would be from Stripe/PayPal
        })
      });

      if (response.ok) {
        setIsPremium(true);
        alert('Successfully subscribed to premium!');
      }
    } catch (error) {
      alert(error.message);
    }
  };

  if (!user) {
    return (
      <div className="auth-container">
        <h1>{isRegistering ? 'Register' : 'Login'}</h1>
        <form onSubmit={handleAuth}>
          {isRegistering && (
            <div>
              <label>Username:</label>
              <input
                type="text"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
              />
            </div>
          )}
          <div>
            <label>Email:</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div>
            <label>Password:</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <button type="submit">{isRegistering ? 'Register' : 'Login'}</button>
        </form>
        <button onClick={() => setIsRegistering(!isRegistering)}>
          {isRegistering ? 'Already have an account? Login' : 'Need an account? Register'}
        </button>
      </div>
    );
  }

  return (
    <div className="app-container">
      <h1>Welcome, {user.displayName || user.email}</h1>
      {isPremium ? (
        <p>Premium Member ✨</p>
      ) : (
        <div className="premium-prompt">
          <p>Upgrade to premium for unlimited messages!</p>
          <button onClick={subscribeToPremium}>Subscribe Now</button>
        </div>
      )}

      <div className="message-form">
        <h2>Send Message</h2>
        <input
          type="text"
          placeholder="Recipient ID"
          value={recipient}
          onChange={(e) => setRecipient(e.target.value)}
        />
        <textarea
          placeholder="Type your message..."
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
        />
        <button onClick={sendMessage}>Send</button>
      </div>

      <div className="messages-list">
        <h2>Your Messages</h2>
        {messages.length === 0 ? (
          <p>No messages yet.</p>
        ) : (
          messages.map((message) => (
            <div key={message.id} className="message">
              <p><strong>From:</strong> {message.senderId}</p>
              <p>{message.content}</p>
              <small>{new Date(message.timestamp?.toDate()).toLocaleString()}</small>
            </div>
          ))
        )}
      </div>

      <button onClick={() => auth.signOut()}>Logout</button>
    </div>
  );
}

export default App;
```

