# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and in-app monetization. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication endpoint
app.post('/api/login', (req, res) => {
    const { username, password } = req.body;
    // Simple authentication - replace with proper auth in production
    if (username && password) {
        users[username] = { username, password, isPremium: premiumUsers.has(username) };
        res.json({ success: true, username, isPremium: premiumUsers.has(username) });
    } else {
        res.status(401).json({ success: false, message: 'Invalid credentials' });
    }
});

// Message endpoint
app.post('/api/messages', (req, res) => {
    const { sender, content } = req.body;
    if (!sender || !content) {
        return res.status(400).json({ success: false, message: 'Missing sender or content' });
    }

    const message = {
        id: Date.now().toString(),
        sender,
        content,
        timestamp: new Date().toISOString(),
        isPremium: premiumUsers.has(sender)
    };

    messages.push(message);
    io.emit('newMessage', message);
    res.json({ success: true, message });
});

// Premium subscription endpoint
app.post('/api/premium/subscribe', (req, res) => {
    const { username } = req.body;
    if (!username || !users[username]) {
        return res.status(400).json({ success: false, message: 'Invalid user' });
    }

    // In a real app, this would process payment
    premiumUsers.add(username);
    users[username].isPremium = true;

    io.emit('premiumStatusUpdate', { username, isPremium: true });
    res.json({ success: true, isPremium: true });
});

// Real-time connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Send existing messages to new client
    socket.emit('initialMessages', messages.filter(msg => !msg.isPremium || premiumUsers.has(socket.handshake.query.username)));

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

