# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and basic in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time functionality, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

// Middleware
app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization;
  if (!token || !users[token]) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  req.user = users[token];
  next();
};

// API Routes
app.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (users[username]) {
    return res.status(400).json({ error: 'Username already exists' });
  }
  users[username] = { username, password, isPremium: false };
  res.json({ token: username });
});

app.post('/login', (req, res) => {
  const { username, password } = req.body;
  const user = users[username];
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }
  res.json({ token: username });
});

app.get('/messages', authenticate, (req, res) => {
  res.json(messages.filter(m => !m.isPremium || req.user.isPremium));
});

app.post('/messages', authenticate, (req, res) => {
  const { text, isPremium } = req.body;
  const message = {
    id: Date.now().toString(),
    text,
    sender: req.user.username,
    timestamp: new Date().toISOString(),
    isPremium
  };
  messages.push(message);
  io.emit('new-message', message);
  res.json(message);
});

// Premium features
app.post('/upgrade', authenticate, (req, res) => {
  // In a real app, this would integrate with a payment processor
  req.user.isPremium = true;
  premiumUsers.add(req.user.username);
  res.json({ success: true, message: 'Upgraded to premium!' });
});

// Socket.io for real-time
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });

  // Send initial messages to new client
  const user = users[socket.handshake.query.token];
  if (user) {
    const userMessages = messages.filter(m => !m.isPremium || user.isPremium);
    socket.emit('initial-messages', userMessages);
  }
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

