      const response = await fetch('/upgrade', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': token
        }
      });

      if (response.ok) {
        isPremium = true;
        document.getElementById('premium-section').style.display = 'none';
