        // Refresh messages to show premium content
        const messagesResponse = await fetch('/messages', {
          headers: { 'Authorization': token }
        });
        const messages = await messagesResponse.json();
        const messagesDiv = document.getElementById('messages');
        messagesDiv.innerHTML = '';
        messages.forEach(addMessageToDOM);
      } else {
        alert('Upgrade failed');
      }
    }

    // Add premium message checkbox
    const premiumCheckbox = document.createElement('input');
    premiumCheckbox.type = 'checkbox';
    premiumCheckbox.id = 'premium-checkbox';
    const premiumLabel = document.createElement('label');
    premiumLabel.htmlFor = 'premium-checkbox';
    premiumLabel.textContent = 'Premium message';
    premiumLabel.className = 'premium-only';

    const messageInput = document.getElementById('message-input');
    messageInput.parentNode.insertBefore(premiumCheckbox, messageInput.nextSibling);
    messageInput.parentNode.insertBefore(premiumLabel, premiumCheckbox.nextSibling);
  </script>
</body>
</html>
