```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication endpoint
app.post('/login', (req, res) => {
    const { username, password } = req.body;

    // Simple authentication (replace with proper auth in production)
    if (username && password) {
        users[username] = { username, password, isPremium: premiumUsers.has(username) };
        res.json({ success: true, username, isPremium: premiumUsers.has(username) });
    } else {
        res.status(401).json({ success: false, message: 'Invalid credentials' });
    }
});

// Message endpoint
app.post('/message', (req, res) => {
    const { username, text, isPremium } = req.body;

    if (!users[username]) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
    }

    const message = {
        id: Date.now().toString(),
        username,
        text,
        timestamp: new Date().toISOString(),
        isPremium
    };

    messages.push(message);
    io.emit('newMessage', message);
    res.json({ success: true, message });
});

// Premium upgrade endpoint
app.post('/upgrade', (req, res) => {
    const { username } = req.body;

    if (!users[username]) {
        return res.status(401).json({ success: false, message: 'Unauthorized' });
    }

    // In a real app, this would process payment
    premiumUsers.add(username);
    users[username].isPremium = true;

    res.json({ success: true, isPremium: true });
});

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Send existing messages to new client
    socket.emit('initialMessages', messages);

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

