          });
        }
      });

      // Listen for incoming messages
      const unsubscribe = onMessage(messaging, (payload) => {
        console.log('Message received. ', payload);
        // Handle the message (e.g., show a notification)
      });

      return () => unsubscribe();
    }
  }, [user]);

  // Listen for auth state changes
  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(async (user) => {
      if (user) {
        setUser(user);
        // Fetch user data from Firestore
        const userDoc = await db.collection('users').doc(user.uid).get();
        setIsPremium(userDoc.data().premium);

        // Listen for contacts
        const contactsQuery = query(
          collection(db, 'users'),
          where('uid', '!=', user.uid)
        );
        const unsubscribeContacts = onSnapshot(contactsQuery, (snapshot) => {
          setContacts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        });

        return () => unsubscribeContacts();
      } else {
        setUser(null);
        setContacts([]);
      }
    });

    return () => unsubscribe();
  }, []);

  // Listen for messages when a contact is selected
  useEffect(() => {
    if (user && selectedUser) {
      const messagesQuery = query(
        collection(db, 'messages'),
        where('senderId', 'in', [user.uid, selectedUser.id]),
        where('receiverId', 'in', [user.uid, selectedUser.id]),
        orderBy('timestamp', 'asc')
      );

      const unsubscribe = onSnapshot(messagesQuery, (snapshot) => {
        setMessages(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      });

      return () => unsubscribe();
    }
  }, [user, selectedUser]);

  const handleLogin = async (e) => {
