```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// Authentication endpoint
app.post('/api/login', (req, res) => {
    const { username, password } = req.body;
    // Simple authentication - replace with proper auth in production
    if (username && password) {
        users[username] = { username, password, isPremium: premiumUsers.has(username) };
        res.json({ success: true, username, isPremium: users[username].isPremium });
    } else {
        res.status(401).json({ success: false, message: 'Invalid credentials' });
    }
});

// Message endpoint
app.post('/api/messages', (req, res) => {
    const { sender, recipient, content } = req.body;
    if (!sender || !recipient || !content) {
        return res.status(400).json({ success: false, message: 'Missing required fields' });
    }

    const message = { sender, recipient, content, timestamp: new Date() };
    messages.push(message);

    // Emit to recipient if online
    if (users[recipient] && users[recipient].socketId) {
        io.to(users[recipient].socketId).emit('new-message', message);
    }

    res.json({ success: true, message });
});

// Premium subscription endpoint
app.post('/api/premium/subscribe', (req, res) => {
    const { username } = req.body;
    if (!username || !users[username]) {
        return res.status(400).json({ success: false, message: 'User not found' });
    }

    // In a real app, this would process payment
    premiumUsers.add(username);
    users[username].isPremium = true;

    res.json({ success: true, isPremium: true });
});

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    socket.on('register', (username) => {
        if (users[username]) {
            users[username].socketId = socket.id;
            socket.emit('user-data', users[username]);
        }
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
        // Remove socket ID when user disconnects
        for (const username in users) {
            if (users[username].socketId === socket.id) {
                delete users[username].socketId;
                break;
            }
        }
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

