```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');
const cors = require('cors');

const app = express();
const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// Middleware
app.use(cors());
app.use(bodyParser.json());

// In-memory storage (replace with database in production)
const users = {};
const messages = {};
const notifications = {};

// User authentication (simplified)
app.post('/login', (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).send('Username required');

  // In a real app, you'd verify credentials here
  users[username] = { id: Date.now().toString(), username };
  res.json({ user: users[username] });
});

// Message endpoints
app.post('/messages', (req, res) => {
  const { sender, recipient, content } = req.body;
  if (!sender || !recipient || !content) {
    return res.status(400).send('Missing required fields');
  }

  const message = {
    id: Date.now().toString(),
    sender,
    recipient,
    content,
    timestamp: new Date().toISOString()
  };

  // Store message
  if (!messages[recipient]) messages[recipient] = [];
  messages[recipient].push(message);

  // Send notification
  if (!notifications[recipient]) notifications[recipient] = [];
  notifications[recipient].push({
    id: Date.now().toString(),
    type: 'message',
    sender,
    content: `New message from ${sender}`,
    timestamp: new Date().toISOString(),
    read: false
  });

  // Emit real-time events
  io.to(recipient).emit('newMessage', message);
  io.to(recipient).emit('newNotification', notifications[recipient][notifications[recipient].length - 1]);

  res.json(message);
});

app.get('/messages/:username', (req, res) => {
  const { username } = req.params;
  res.json(messages[username] || []);
});

app.get('/notifications/:username', (req, res) => {
  const { username } = req.params;
  res.json(notifications[username] || []);
});

// Monetization endpoints
app.post('/purchase', (req, res) => {
  const { userId, productId, amount } = req.body;

  // In a real app, you would process payment here
  console.log(`Processing purchase for user ${userId}: ${productId} for $${amount}`);

  // Simulate successful purchase
  setTimeout(() => {
    res.json({
      success: true,
      transactionId: Date.now().toString(),
      productId,
      amount
    });
  }, 1000);
});

// Socket.io connection handling
io.on('connection', (socket) => {
  console.log('New client connected');

  socket.on('join', (username) => {
    socket.join(username);
    console.log(`${username} joined`);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
