      notifications.forEach(notification => {
        const notificationDiv = document.createElement('div');
        notificationDiv.className = `notification-item ${notification.read ? '' : 'unread'}`;

        notificationDiv.innerHTML = `
          <strong>${notification.type}</strong>: ${notification.content}
          <div style="font-size: 0.8em; color: #666;">${new Date(notification.timestamp).toLocaleString()}</div>
        `;

        notificationList.appendChild(notificationDiv);
      });
    }

