# Minimal Social Messaging App with Real-Time Notifications and Monetization

Below is a minimal working version of a social messaging app with real-time notifications and basic in-app monetization features. This example uses Node.js with Express for the backend, Socket.io for real-time communication, and a simple frontend with HTML/CSS/JavaScript.

## Backend (Node.js/Express)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const bodyParser = require('body-parser');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage (replace with database in production)
const users = {};
const messages = [];
const premiumUsers = new Set();

app.use(bodyParser.json());
app.use(express.static('public'));

// User authentication (simplified)
app.post('/login', (req, res) => {
    const { username } = req.body;
    if (!username) return res.status(400).send('Username required');

    // In a real app, you'd verify credentials here
    users[username] = { username, online: true };
    res.json({ success: true, username });
});

// Message handling
app.post('/send', (req, res) => {
    const { from, to, text, isPremium } = req.body;

    if (!from || !to || !text) {
        return res.status(400).send('Missing required fields');
    }

    const message = { from, to, text, timestamp: new Date(), isPremium };
    messages.push(message);

    // Emit to recipient if online
    if (users[to] && users[to].socketId) {
        io.to(users[to].socketId).emit('new-message', message);
    }

    res.json({ success: true });
});

// Premium subscription endpoint
app.post('/subscribe', (req, res) => {
    const { username } = req.body;

    if (!username) return res.status(400).send('Username required');

    // In a real app, you'd process payment here
    premiumUsers.add(username);
    res.json({ success: true, isPremium: true });
});

// Socket.io connection handling
io.on('connection', (socket) => {
    const username = socket.handshake.query.username;

    if (username) {
        users[username].socketId = socket.id;
        users[username].online = true;

        // Notify others about online status
        socket.broadcast.emit('user-status', { username, online: true });

        // Send existing messages to the user
        const userMessages = messages.filter(m => m.to === username);
        socket.emit('initial-messages', userMessages);

        socket.on('disconnect', () => {
            if (users[username]) {
                users[username].online = false;
                socket.broadcast.emit('user-status', { username, online: false });
            }
        });
    }
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

