            notificationDiv.className = 'notification';
            notificationDiv.textContent = text;
            notificationsDiv.appendChild(notificationDiv);

            // Remove after 5 seconds
            setTimeout(() => {
                notificationsDiv.removeChild(notificationDiv);
            }, 5000);
        }

        function upgradeToPremium() {
            fetch('/subscribe', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username: currentUser })
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    isPremium = true;
                    document.getElementById('premiumBadge').style.display = 'inline';
                    document.getElementById('premiumButton').style.display = 'none';
                    alert('You are now a premium user! Enjoy premium features.');
                }
            });
        }
    </script>
</body>
</html>
```

## Features Implemented

1. **Real-Time Messaging**:
   - WebSocket connection using Socket.io
   - Instant message delivery to recipients
   - Online/offline status notifications

2. **Basic Authentication**:
   - Simple username-based login
   - User session management

3. **Monetization**:
   - Premium message feature (highlighted in UI)
   - Premium subscription endpoint
   - Visual indicators for premium users and messages

4. **Notifications**:
   - Real-time message notifications
   - User status change notifications

