                            <!-- Activity items will be added here -->
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
    <script>
        // Dashboard initialization
        document.addEventListener('DOMContentLoaded', function() {
            // Update current time
            updateCurrentTime();
            setInterval(updateCurrentTime, 1000);

            // Initialize charts
            const salesChart = initSalesChart();
            const userActivityChart = initUserActivityChart();

            // Generate initial data
            generateInitialData(salesChart, userActivityChart);

            // Set up form submission
            setupFormHandler(salesChart, userActivityChart);

            // Set up refresh button
            document.getElementById('refresh-btn').addEventListener('click', function() {
                refreshData(salesChart, userActivityChart);
            });

            // Simulate real-time updates
            setInterval(() => {
                updateRealTimeData(salesChart, userActivityChart);
            }, 5000);
        });

        // Update current time display
        function updateCurrentTime() {
            const now = new Date();
            document.getElementById('current-time').textContent = now.toLocaleTimeString();
        }

        // Initialize sales chart
        function initSalesChart() {
            const ctx = document.getElementById('salesChart').getContext('2d');
            return new Chart(ctx, {
                type: 'line',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Sales',
                        data: [],
                        borderColor: 'rgb(75, 192, 192)',
                        tension: 0.1,
                        fill: true,
                        backgroundColor: 'rgba(75, 192, 192, 0.2)'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        }

        // Initialize user activity chart
        function initUserActivityChart() {
            const ctx = document.getElementById('userActivityChart').getContext('2d');
            return new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Active Users',
                        data: [],
                        backgroundColor: 'rgba(54, 162, 235, 0.5)',
                        borderColor: 'rgba(54, 162, 235, 1)',
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        }

        // Generate initial data
        function generateInitialData(salesChart, userActivityChart) {
            // Generate random data for the last 7 days
            const labels = [];
            const salesData = [];
            const userData = [];

            for (let i = 6; i >= 0; i--) {
                const date = new Date();
                date.setDate(date.getDate() - i);
                labels.push(date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }));

                salesData.push(Math.floor(Math.random() * 1000) + 100);
                userData.push(Math.floor(Math.random() * 500) + 50);
            }

            // Update charts
            salesChart.data.labels = labels;
            salesChart.data.datasets[0].data = salesData;
            salesChart.update();

            userActivityChart.data.labels = labels;
            userActivityChart.data.datasets[0].data = userData;
            userActivityChart.update();

            // Update stats
            document.getElementById('active-users').textContent = userData[userData.length - 1];
            document.getElementById('total-sales').textContent = salesData.reduce((a, b) => a + b, 0);

            // Add initial activity log entries
            addActivityLog('Dashboard initialized', 'System');
            addActivityLog('Initial data loaded', 'System');
        }

        // Set up form handler
        function setupFormHandler(salesChart, userActivityChart) {
            const form = document.getElementById('data-form');
            const alertContainer = document.getElementById('form-alert');

            form.addEventListener('submit', function(e) {
                e.preventDefault();

                // Validate form
                if (!form.checkValidity()) {
                    showAlert('Please fill in all required fields', 'danger');
                    return;
                }

                // Get form values
                const type = document.getElementById('data-type').value;
                const value = parseFloat(document.getElementById('data-value').value);
                const date = new Date(document.getElementById('data-date').value);
                const description = document.getElementById('data-description').value;

                // Format date for display
                const formattedDate = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

                // Update appropriate chart based on data type
                if (type === 'sales') {
                    // Add to sales chart
                    salesChart.data.labels.push(formattedDate);
                    salesChart.data.datasets[0].data.push(value);
                    salesChart.update();

                    // Update total sales
                    const totalSales = salesChart.data.datasets[0].data.reduce((a, b) => a + b, 0);
                    document.getElementById('total-sales').textContent = totalSales;

                    showAlert('Sales data added successfully', 'success');
                } else if (type === 'users') {
                    // Add to user activity chart
                    userActivityChart.data.labels.push(formattedDate);
                    userActivityChart.data.datasets[0].data.push(value);
                    userActivityChart.update();

                    // Update active users
                    document.getElementById('active-users').textContent = value;

                    showAlert('User data added successfully', 'success');
                } else if (type === 'revenue') {
                    // For revenue, we'll just log it as an activity
                    showAlert('Revenue data recorded', 'success');
                }

                // Add to activity log
                addActivityLog(`${type.charAt(0).toUpperCase() + type.slice(1)} data added: ${value}`, 'User');

                // Reset form
                form.reset();
            });

            // Show alert message
            function showAlert(message, type) {
                alertContainer.innerHTML = `
                    <div class="alert alert-${type} alert-dismissible fade show" role="alert">
                        ${message}
                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
                    </div>
                `;
            }
        }

        // Add entry to activity log
        function addActivityLog(message, source) {
            const logEntry = document.createElement('div');
            logEntry.className = 'list-group-item list-group-item-action';
            logEntry.innerHTML = `
                <div class="d-flex w-100 justify-content-between">
                    <small>${new Date().toLocaleTimeString()}</small>
                    <small class="text-muted">${source}</small>
                </div>
                <p class="mb-1">${message}</p>
            `;

            const activityLog = document.getElementById('activity-log');
            activityLog.prepend(logEntry);

            // Limit to 10 entries
            if (activityLog.children.length > 10) {
                activityLog.removeChild(activityLog.lastChild);
            }
        }

        // Refresh data (simulate fetching new data)
        function refreshData(salesChart, userActivityChart) {
            // Generate new random data for today
            const today = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
            const newSales = Math.floor(Math.random() * 1000) + 100;
            const newUsers = Math.floor(Math.random() * 500) + 50;

            // Update sales chart
            if (salesChart.data.labels[salesChart.data.labels.length - 1] === today) {
                // Update today's data
                salesChart.data.datasets[0].data[salesChart.data.datasets[0].data.length - 1] = newSales;
            } else {
                // Add new data point
                salesChart.data.labels.push(today);
                salesChart.data.datasets[0].data.push(newSales);
            }
            salesChart.update();

            // Update user activity chart
            if (userActivityChart.data.labels[userActivityChart.data.labels.length - 1] === today) {
                // Update today's data
                userActivityChart.data.datasets[0].data[userActivityChart.data.datasets[0].data.length - 1] = newUsers;
            } else {
                // Add new data point
                userActivityChart.data.labels.push(today);
                userActivityChart.data.datasets[0].data.push(newUsers);
            }
            userActivityChart.update();

            // Update stats
            document.getElementById('active-users').textContent = newUsers;
            const totalSales = salesChart.data.datasets[0].data.reduce((a, b) => a + b, 0);
            document.getElementById('total-sales').textContent = totalSales;

            // Add to activity log
            addActivityLog('Data refreshed with new values', 'System');
        }

        // Simulate real-time data updates
        function updateRealTimeData(salesChart, userActivityChart) {
            // Generate small random changes
            const today = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

            // Update sales data
            if (salesChart.data.labels[salesChart.data.labels.length - 1] === today) {
                const lastValue = salesChart.data.datasets[0].data[salesChart.data.datasets[0].data.length - 1];
                const change = Math.floor(Math.random() * 50) - 25; // Random change between -25 and +25
                const newValue = Math.max(0, lastValue + change);

                salesChart.data.datasets[0].data[salesChart.data.datasets[0].data.length - 1] = newValue;
                salesChart.update();

                // Update total sales
                const totalSales = salesChart.data.datasets[0].data.reduce((a, b) => a + b, 0);
                document.getElementById('total-sales').textContent = totalSales;
            }

            // Update user data
            if (userActivityChart.data.labels[userActivityChart.data.labels.length - 1] === today) {
                const lastValue = userActivityChart.data.datasets[0].data[userActivityChart.data.datasets[0].data.length - 1];
                const change = Math.floor(Math.random() * 20) - 10; // Random change between -10 and +10
                const newValue = Math.max(0, lastValue + change);

                userActivityChart.data.datasets[0].data[userActivityChart.data.datasets[0].data.length - 1] = newValue;
                userActivityChart.update();

                // Update active users
                document.getElementById('active-users').textContent = newValue;
            }

            // Add to activity log occasionally
            if (Math.random() > 0.7) { // 30% chance
                const messages = [
                    'System check completed',
                    'Data synchronization successful',
                    'New user registered',
                    'Payment processed',
                    'Inventory updated'
                ];
                const randomMessage = messages[Math.floor(Math.random() * messages.length)];
                addActivityLog(randomMessage, 'System');
            }
        }
    </script>
</body>
</html>
