## JavaScript (script.js)

```javascript
// Initialize charts
let salesChart, userGrowthChart;

// Sample data
let dashboardData = {
    totalUsers: 1250,
    totalRevenue: 45200,
    totalOrders: 890,
    salesData: {
        labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
        datasets: [{
            label: 'Sales',
            data: [1200, 1900, 3000, 5000, 2000, 3000],
            backgroundColor: 'rgba(54, 162, 235, 0.2)',
            borderColor: 'rgba(54, 162, 235, 1)',
            borderWidth: 2,
            tension: 0.1
        }]
    },
    userGrowthData: {
        labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
        datasets: [{
            label: 'New Users',
            data: [50, 120, 200, 150, 300, 250],
            backgroundColor: 'rgba(46, 204, 113, 0.2)',
            borderColor: 'rgba(46, 204, 113, 1)',
            borderWidth: 2,
            tension: 0.1
        }]
    },
    tableData: []
};

// Initialize the dashboard
function initDashboard() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Update stats cards
    updateStatsCards();

    // Initialize charts
    initCharts();

    // Set up form handler
    setupFormHandler();

    // Load saved data from localStorage if available
    loadSavedData();
}

// Update date and time display
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
}

// Update stats cards with data
function updateStatsCards() {
    document.getElementById('total-users').textContent = dashboardData.totalUsers;
    document.getElementById('total-revenue').textContent = `$${dashboardData.totalRevenue.toLocaleString()}`;
    document.getElementById('total-orders').textContent = dashboardData.totalOrders;
}

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('salesChart').getContext('2d');
    const userGrowthCtx = document.getElementById('userGrowthChart').getContext('2d');

    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: dashboardData.salesData,
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    userGrowthChart = new Chart(userGrowthCtx, {
        type: 'line',
        data: dashboardData.userGrowthData,
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Set up form handler
function setupFormHandler() {
    const form = document.getElementById('data-form');

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const label = document.getElementById('data-label').value;
        const value = parseInt(document.getElementById('data-value').value);
        const color = document.getElementById('data-color').value;

        // Add data to table
        addDataToTable(label, value, color);

        // Update charts with new data
        updateCharts(label, value, color);

        // Update stats cards
        updateStats();

        // Save data to localStorage
        saveData();

        // Reset form
        form.reset();
    });
}

// Add data to the table
function addDataToTable(label, value, color) {
    const tableBody = document.querySelector('#data-table tbody');
    const newRow = document.createElement('tr');

    // Create color indicator
    const colorIndicator = document.createElement('div');
    colorIndicator.style.width = '20px';
    colorIndicator.style.height = '20px';
    colorIndicator.style.backgroundColor = color;
    colorIndicator.style.borderRadius = '4px';
    colorIndicator.style.display = 'inline-block';
    colorIndicator.style.marginRight = '10px';

    // Create delete button
    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'btn-delete';
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', function() {
        // Remove from table
        tableBody.removeChild(newRow);

        // Remove from data array
        dashboardData.tableData = dashboardData.tableData.filter(item => item.label !== label);

        // Update charts
        updateChartsAfterDelete(label);

        // Update stats
        updateStats();

        // Save data
        saveData();
    });

    newRow.innerHTML = `
        <td>${label}</td>
        <td>${value}</td>
        <td></td>
        <td></td>
    `;

    // Add color indicator to the color cell
    newRow.cells[2].appendChild(colorIndicator);

    // Add delete button to actions cell
    newRow.cells[3].appendChild(deleteBtn);

    tableBody.appendChild(newRow);

    // Add to data array
    dashboardData.tableData.push({ label, value, color });
}

// Update charts with new data
function updateCharts(label, value, color) {
    // Update sales chart
    salesChart.data.labels.push(label);
    salesChart.data.datasets[0].data.push(value);
    salesChart.data.datasets[0].backgroundColor.push(`${color}33`); // Add transparency
    salesChart.data.datasets[0].borderColor.push(color);
    salesChart.update();

    // Update user growth chart (for demo, we'll just add a similar value)
    userGrowthChart.data.labels.push(label);
    userGrowthChart.data.datasets[0].data.push(Math.floor(value * 0.4)); // 40% of sales value
    userGrowthChart.data.datasets[0].backgroundColor.push(`${color}33`);
    userGrowthChart.data.datasets[0].borderColor.push(color);
    userGrowthChart.update();
}

// Update charts after deleting data
function updateChartsAfterDelete(label) {
    // Find index of the label to remove
    const index = salesChart.data.labels.indexOf(label);

    if (index !== -1) {
        // Remove from sales chart
        salesChart.data.labels.splice(index, 1);
        salesChart.data.datasets[0].data.splice(index, 1);
        salesChart.data.datasets[0].backgroundColor.splice(index, 1);
        salesChart.data.datasets[0].borderColor.splice(index, 1);
        salesChart.update();

        // Remove from user growth chart
        userGrowthChart.data.labels.splice(index, 1);
        userGrowthChart.data.datasets[0].data.splice(index, 1);
        userGrowthChart.data.datasets[0].backgroundColor.splice(index, 1);
        userGrowthChart.data.datasets[0].borderColor.splice(index, 1);
        userGrowthChart.update();
    }
}

// Update stats based on table data
function updateStats() {
    // Calculate totals from table data
    const totalValue = dashboardData.tableData.reduce((sum, item) => sum + item.value, 0);

    // Update stats cards (for demo, we'll just add to existing values)
    dashboardData.totalUsers += Math.floor(totalValue * 0.1);
    dashboardData.totalRevenue += totalValue * 10;
    dashboardData.totalOrders += Math.floor(totalValue * 0.05);

    updateStatsCards();
}

// Save data to localStorage
function saveData() {
    localStorage.setItem('dashboardData', JSON.stringify(dashboardData));
}

// Load data from localStorage
function loadSavedData() {
    const savedData = localStorage.getItem('dashboardData');
    if (savedData) {
        dashboardData = JSON.parse(savedData);

        // Update stats cards
        updateStatsCards();

        // Update charts
        salesChart.data = dashboardData.salesData;
        userGrowthChart.data = dashboardData.userGrowthData;
        salesChart.update();
        userGrowthChart.update();

        // Update table
        const tableBody = document.querySelector('#data-table tbody');
        tableBody.innerHTML = ''; // Clear existing rows

        dashboardData.tableData.forEach(item => {
            addDataToTable(item.label, item.value, item.color);
        });
    }
}

// Initialize the dashboard when the page loads
document.addEventListener('DOMContentLoaded', initDashboard);
```

## Features Implemented

1. **Real-Time Data Visualization**:
   - Two interactive charts using Chart.js (line charts)
   - Dynamic updates when new data is added or removed

2. **Form Handling**:
   - Form with validation (required fields, number input)
   - Color picker for customizing data points
   - Form submission handler that updates all components

3. **Interactive Elements**:
   - Delete functionality for table rows
   - Responsive design that works on different screen sizes
   - Real-time date and time display

4. **Data Persistence**:
   - Uses localStorage to save data between sessions
   - Automatically loads saved data on page load

5. **UI Components**:
   - Stats cards for key metrics
   - Navigation sidebar
   - Responsive table for displaying data
   - Clean, modern design with CSS variables for easy theming

## How to Use

1. Save the three files (index.html, styles.css, script.js) in the same directory
2. Open index.html in a web browser
3. Use the form to add new data points
4. The charts and stats will update automatically
5. Data will persist between page refreshes

You can extend this dashboard by:
- Adding more chart types
- Implementing user authentication
- Connecting to a backend API for real data
- Adding more complex form validation
- Implementing dark mode toggle

