        document.getElementById('total-revenue').textContent = '$125,432';
        document.getElementById('growth-rate').textContent = '12.5%';
    }, 1000);
}

// Set up event listeners
function setupEventListeners() {
    // Refresh button
    document.getElementById('refresh-btn').addEventListener('click', function() {
        loadDashboardData();
        updateChartsWithNewData();
        alert('Data refreshed!');
    });

    // Export button
    document.getElementById('export-btn').addEventListener('click', function() {
        alert('Report exported successfully!');
    });

    // Form submission
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const dataType = document.getElementById('data-type').value;
        const dataValue = document.getElementById('data-value').value;
        const dataDate = document.getElementById('data-date').value;
        const dataDescription = document.getElementById('data-description').value;

        // Validate form
        if (!dataType || !dataValue || !dataDate) {
            alert('Please fill in all required fields!');
            return;
        }

        // Process form data (in a real app, this would send to a server)
        console.log('Form submitted:', {
            type: dataType,
            value: dataValue,
            date: dataDate,
            description: dataDescription
        });

        // Update charts with new data
        updateChartsWithNewData(dataType, dataValue, dataDate);

        // Reset form
        this.reset();

        alert('Data submitted successfully!');
    });
}

// Update charts with new data
function updateChartsWithNewData(dataType, dataValue, dataDate) {
    // Simulate updating charts with new data
    if (dataType === 'sales') {
        const newData = [...window.salesChart.data.datasets[0].data];
        newData[newData.length - 1] = parseInt(dataValue);
        window.salesChart.data.datasets[0].data = newData;
        window.salesChart.update();
    } else if (dataType === 'users') {
        const newData = [...window.userGrowthChart.data.datasets[0].data];
        newData[newData.length - 1] = parseInt(dataValue);
        window.userGrowthChart.data.datasets[0].data = newData;
        window.userGrowthChart.update();
    }

    // Update stats cards
    if (dataType === 'revenue') {
        document.getElementById('total-revenue').textContent = `$${dataValue}`;
    }
}

// Simulate real-time data updates
function updateRealTimeData() {
    // Generate random data for simulation
    const randomSales = Math.floor(Math.random() * 1000) + 500;
    const randomUsers = Math.floor(Math.random() * 200) + 50;

    // Update charts
    const salesData = [...window.salesChart.data.datasets[0].data];
    salesData.shift();
    salesData.push(randomSales);
    window.salesChart.data.datasets[0].data = salesData;
    window.salesChart.update();

    const userData = [...window.userGrowthChart.data.datasets[0].data];
    userData.shift();
    userData.push(randomUsers);
    window.userGrowthChart.data.datasets[0].data = userData;
    window.userGrowthChart.update();

    // Update stats cards
    const currentUsers = parseInt(document.getElementById('total-users').textContent.replace(/,/g, '')) + randomUsers;
    document.getElementById('total-users').textContent = currentUsers.toLocaleString();

    const currentOrders = parseInt(document.getElementById('total-orders').textContent.replace(/,/g, '')) + Math.floor(randomUsers * 0.7);
    document.getElementById('total-orders').textContent = currentOrders.toLocaleString();

    const currentRevenue = parseFloat(document.getElementById('total-revenue').textContent.replace('$', '')) + (randomSales * 0.5);
    document.getElementById('total-revenue').textContent = `$${currentRevenue.toFixed(2)}`;
}
