## JavaScript (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const realtimeChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Data Values',
                data: [],
                borderColor: 'rgb(52, 152, 219)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.3,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    display: false
                }
            }
        }
    });

    // Simulate real-time data updates
    let dataCounter = 0;
    setInterval(() => {
        const newValue = Math.floor(Math.random() * 100) + 1;
        const newLabel = new Date().toLocaleTimeString();

        // Update chart
        realtimeChart.data.labels.push(newLabel);
        realtimeChart.data.datasets[0].data.push(newValue);

        // Keep only the last 20 data points
        if (realtimeChart.data.labels.length > 20) {
            realtimeChart.data.labels.shift();
            realtimeChart.data.datasets[0].data.shift();
        }

        realtimeChart.update();

        // Update stats
        document.getElementById('total-users').textContent = (parseInt(document.getElementById('total-users').textContent) + Math.floor(Math.random() * 5)).toString();
        document.getElementById('active-sessions').textContent = (parseInt(document.getElementById('active-sessions').textContent) + Math.floor(Math.random() * 3)).toString();
        document.getElementById('conversion-rate').textContent = (Math.random() * 10).toFixed(1) + '%';
        document.getElementById('revenue').textContent = '$' + (parseInt(document.getElementById('revenue').textContent.replace('$', '')) + Math.floor(Math.random() * 100)).toString();

        dataCounter++;
    }, 3000);

    // Form handling
    const dataForm = document.getElementById('data-form');
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const name = document.getElementById('data-name').value;
        const value = document.getElementById('data-value').value;
        const category = document.getElementById('data-category').value;
        const date = document.getElementById('data-date').value;

        // Validate form
        if (!name || !value || !category || !date) {
            alert('Please fill in all fields');
            return;
        }

        // Add to activity log
        addActivityItem(`Submitted ${category} data: ${name} (${value})`, new Date().toLocaleString());

        // Add to chart if it's a numeric value
        if (!isNaN(value)) {
            realtimeChart.data.labels.push(new Date().toLocaleTimeString());
            realtimeChart.data.datasets[0].data.push(parseFloat(value));

            // Keep only the last 20 data points
            if (realtimeChart.data.labels.length > 20) {
                realtimeChart.data.labels.shift();
                realtimeChart.data.datasets[0].data.shift();
            }

            realtimeChart.update();
        }

        // Reset form
        dataForm.reset();

        // Show success message
        alert('Data submitted successfully!');
    });

    // Function to update date and time
    function updateDateTime() {
        const now = new Date();
        document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
        document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        });
    }

    // Function to add activity item
    function addActivityItem(message, time) {
        const activityLog = document.getElementById('activity-log');
        const activityItem = document.createElement('div');
        activityItem.className = 'activity-item';

        activityItem.innerHTML = `
            <div class="activity-content">${message}</div>
            <div class="activity-time">${time}</div>
        `;

        activityLog.prepend(activityItem);

        // Limit to 10 items
        if (activityLog.children.length > 10) {
            activityLog.removeChild(activityLog.lastChild);
        }
    }

    // Initial activity items
    addActivityItem('Dashboard initialized', new Date().toLocaleString());
    addActivityItem('Real-time data visualization started', new Date().toLocaleString());
});
