## JavaScript (script.js)

```javascript
// Update date and time
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
}

// Initialize charts
let salesChart, userGrowthChart;

// Sample data
let salesData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [{
        label: 'Sales',
        data: [12000, 19000, 15000, 17000, 22000, 25000],
        backgroundColor: 'rgba(54, 162, 235, 0.2)',
        borderColor: 'rgba(54, 162, 235, 1)',
        borderWidth: 2,
        tension: 0.4,
        fill: true
    }]
};

let userGrowthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [{
        label: 'New Users',
        data: [500, 800, 1200, 1500, 2000, 2500],
        backgroundColor: 'rgba(46, 204, 113, 0.2)',
        borderColor: 'rgba(46, 204, 113, 1)',
        borderWidth: 2,
        tension: 0.4,
        fill: true
    }]
};

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('salesChart').getContext('2d');
    const userGrowthCtx = document.getElementById('userGrowthChart').getContext('2d');

    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: salesData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    userGrowthChart = new Chart(userGrowthCtx, {
        type: 'line',
        data: userGrowthData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Update stats cards
function updateStats() {
    // Calculate totals from chart data
    const totalUsers = userGrowthData.datasets[0].data.reduce((a, b) => a + b, 0);
    const totalRevenue = salesData.datasets[0].data.reduce((a, b) => a + b, 0);
    const totalOrders = Math.floor(totalRevenue / 1000); // Simple calculation
    const averageRating = (Math.random() * 2 + 3).toFixed(1); // Random rating between 3-5

    document.getElementById('total-users').textContent = totalUsers;
    document.getElementById('total-revenue').textContent = `$${totalRevenue.toLocaleString()}`;
    document.getElementById('total-orders').textContent = totalOrders;
    document.getElementById('average-rating').textContent = averageRating;
}

// Add activity item
function addActivityItem(message) {
    const activityList = document.getElementById('activity-list');
    const now = new Date();

    const activityItem = document.createElement('div');
    activityItem.className = 'activity-item';
    activityItem.innerHTML = `
        <i class="fas fa-bell"></i>
        <div>
            <p>${message}</p>
            <span class="time">${now.toLocaleTimeString('en-US')}</span>
        </div>
    `;

    activityList.prepend(activityItem);

    // Limit to 5 items
    if (activityList.children.length > 5) {
        activityList.removeChild(activityList.lastChild);
    }
}

// Handle form submission
document.getElementById('data-form').addEventListener('submit', function(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseInt(document.getElementById('data-value').value);
    const color = document.getElementById('data-color').value;

    // Add to sales chart
    salesData.labels.push(label);
    salesData.datasets[0].data.push(value);

    // Update chart
    salesChart.update();

    // Add to user growth chart if it's a number
    if (!isNaN(value)) {
        userGrowthData.labels.push(label);
        userGrowthData.datasets[0].data.push(value);
        userGrowthChart.update();
    }

    // Update stats
    updateStats();

    // Add activity
    addActivityItem(`Added new data point: ${label} (${value})`);

    // Reset form
    this.reset();

    // Show success message (could be replaced with a proper notification system)
    alert('Data added successfully!');
});

// Initialize everything when the page loads
document.addEventListener('DOMContentLoaded', function() {
    updateDateTime();
    initCharts();
    updateStats();

    // Update time every second
    setInterval(updateDateTime, 1000);

    // Add some initial activity
    addActivityItem('Dashboard initialized');
    addActivityItem('Charts loaded successfully');
});

// Simulate real-time updates
function simulateRealTimeUpdates() {
    setInterval(() => {
        // Add random data points
        const months = ['Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const randomMonth = months[Math.floor(Math.random() * months.length)];
        const randomSales = Math.floor(Math.random() * 10000) + 10000;
        const randomUsers = Math.floor(Math.random() * 500) + 200;

        salesData.labels.push(randomMonth);
        salesData.datasets[0].data.push(randomSales);

        userGrowthData.labels.push(randomMonth);
        userGrowthData.datasets[0].data.push(randomUsers);

        salesChart.update();
        userGrowthChart.update();
        updateStats();

        addActivityItem(`New data received: ${randomMonth} (Sales: $${randomSales}, Users: ${randomUsers})`);
    }, 15000); // Update every 15 seconds
}

// Start real-time simulation
simulateRealTimeUpdates();
```

## Features Implemented

1. **Real-Time Data Visualization**:
   - Interactive charts using Chart.js
   - Automatic updates to charts and stats
   - Simulated real-time data updates

2. **Form Handling**:
   - Form validation
   - Dynamic data addition to charts
   - Success feedback

3. **Dashboard Components**:
   - Responsive layout
   - Navigation sidebar
   - Stats cards
   - Activity log
   - Current date/time display

4. **Interactive Elements**:
   - Hover effects on navigation
   - Color pickers for data points
   - Dynamic updates to all components

## How to Use

1. Save the three files (index.html, styles.css, script.js) in the same directory
2. Open index.html in a modern web browser
3. Use the form to add new data points
4. Watch as the charts and stats update in real-time
5. The dashboard will also simulate real-time updates every 15 seconds

This implementation provides a solid foundation that you can extend with additional features like:
- User authentication
- Data persistence (using localStorage or a backend API)
- More advanced chart types
- Export functionality
- Dark mode toggle

