                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'right',
                        }
                    }
                }
            });
        }

        // Populate data table
        function populateTable() {
            dataTableBody.innerHTML = '';

            dashboardData.tableData.forEach(item => {
                const row = document.createElement('tr');
                row.innerHTML = `
                    <td>${item.id}</td>
                    <td>${item.name}</td>
                    <td>$${item.value}</td>
                    <td>${item.date}</td>
                    <td><span class="badge bg-${getStatusBadgeClass(item.status)}">${item.status}</span></td>
                `;
                dataTableBody.appendChild(row);
            });
        }

        // Get badge class based on status
        function getStatusBadgeClass(status) {
            switch(status) {
                case 'Active': return 'success';
                case 'Inactive': return 'secondary';
                case 'Pending': return 'warning';
                default: return 'primary';
            }
        }

        // Set up event listeners
        function setupEventListeners() {
            // Refresh button
            refreshBtn.addEventListener('click', refreshData);

            // Form submission
            submitDataBtn.addEventListener('click', handleFormSubmit);

            // Simulate real-time updates
            setInterval(simulateRealTimeUpdates, 5000);
        }

        // Refresh data
        function refreshData() {
            // In a real app, this would fetch fresh data from a server
            console.log('Refreshing data...');

            // For demo purposes, we'll just update some values
            dashboardData.stats.totalUsers += Math.floor(Math.random() * 10) - 5;
            dashboardData.stats.totalRevenue = (parseFloat(dashboardData.stats.totalRevenue) + (Math.random() * 100 - 50)).toFixed(2);
            dashboardData.stats.activeSessions += Math.floor(Math.random() * 5) - 2;
            dashboardData.stats.conversionRate = (parseFloat(dashboardData.stats.conversionRate) + (Math.random() * 2 - 1)).toFixed(1);

            // Update charts with new data
            updateCharts();

            // Update stats display
            updateStats();
        }

        // Update charts with new data
        function updateCharts() {
            // Update user growth chart
            userGrowthChart.data.datasets[0].data = dashboardData.userGrowth.data;
            userGrowthChart.update();

            // Update revenue chart
            revenueChart.data.datasets[0].data = dashboardData.revenueData.data;
            revenueChart.update();
        }

        // Handle form submission
        function handleFormSubmit() {
            if (!dataForm.checkValidity()) {
                showFormAlert('Please fill in all required fields.');
                return;
            }

            // Get form values
            const name = document.getElementById('dataName').value;
            const value = document.getElementById('dataValue').value;
            const date = document.getElementById('dataDate').value;
            const status = document.getElementById('dataStatus').value;

            // Create new data item
            const newItem = {
                id: dashboardData.tableData.length + 1,
                name,
                value,
                date,
                status
            };

            // Add to table data
            dashboardData.tableData.unshift(newItem);

            // Update table
            populateTable();

            // Update stats (simplified for demo)
            dashboardData.stats.totalUsers++;
            dashboardData.stats.totalRevenue = (parseFloat(dashboardData.stats.totalRevenue) + parseFloat(value)).toFixed(2);

            // Update charts (simplified for demo)
            dashboardData.userGrowth.data.push(parseInt(value));
            dashboardData.userGrowth.labels.push(new Date(date).toLocaleString('default', { month: 'short' }));

            // Update display
            updateStats();
            updateCharts();

            // Reset form
            dataForm.reset();

            // Close modal
            const modal = bootstrap.Modal.getInstance(document.getElementById('dataFormModal'));
            modal.hide();

            // Show success message
            alert('Data added successfully!');
        }

        // Show form alert
        function showFormAlert(message) {
            formAlert.textContent = message;
            formAlert.style.display = 'block';

            setTimeout(() => {
                formAlert.style.display = 'none';
            }, 3000);
        }

        // Simulate real-time updates
        function simulateRealTimeUpdates() {
            // Update some stats randomly
            dashboardData.stats.activeSessions += Math.floor(Math.random() * 3) - 1;
            dashboardData.stats.conversionRate = (parseFloat(dashboardData.stats.conversionRate) + (Math.random() * 0.5 - 0.25)).toFixed(1);

            // Update charts with new data
            updateCharts();

            // Update stats display
            updateStats();
        }

        // Initialize the dashboard when the page loads
        document.addEventListener('DOMContentLoaded', initDashboard);
    </script>
</body>
</html>
```

## Key Features of This Implementation:

1. **Responsive Design**:
   - Works on both desktop and mobile devices
   - Collapsible sidebar for mobile view

2. **Real-Time Data Visualization**:
   - Line chart for user growth trends
