        };

        // Initialize charts
        function initCharts() {
            const userGrowthCtx = document.getElementById('userGrowthChart').getContext('2d');
            const revenueCtx = document.getElementById('revenueChart').getContext('2d');

            // User Growth Chart
            userGrowthChart = new Chart(userGrowthCtx, {
                type: 'line',
                data: {
                    labels: userGrowthData.daily.labels,
                    datasets: [{
                        label: 'Users',
                        data: userGrowthData.daily.data,
                        backgroundColor: 'rgba(52, 152, 219, 0.2)',
                        borderColor: 'rgba(52, 152, 219, 1)',
                        borderWidth: 2,
                        tension: 0.3,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });

            // Revenue Chart
            revenueChart = new Chart(revenueCtx, {
                type: 'doughnut',
                data: {
                    labels: revenueData.labels,
                    datasets: [{
                        data: revenueData.data,
                        backgroundColor: [
                            'rgba(52, 152, 219, 0.7)',
                            'rgba(46, 204, 113, 0.7)',
                            'rgba(241, 196, 15, 0.7)',
                            'rgba(231, 76, 60, 0.7)',
                            'rgba(155, 89, 182, 0.7)'
                        ],
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'right'
                        }
                    }
                }
            });
        }

        // Update charts based on time period
        function updateUserGrowthChart(period) {
            userGrowthChart.data.labels = userGrowthData[period].labels;
            userGrowthChart.data.datasets[0].data = userGrowthData[period].data;
            userGrowthChart.update();
        }

        // Update stats with random data (simulating real-time updates)
        function updateStats() {
            document.getElementById('total-users').textContent = Math.floor(Math.random() * 10000) + 5000;
            document.getElementById('active-sessions').textContent = Math.floor(Math.random() * 500) + 200;
            document.getElementById('conversion-rate').textContent = (Math.random() * 10 + 5).toFixed(1) + '%';
            document.getElementById('revenue').textContent = '$' + (Math.random() * 10000 + 5000).toFixed(2);
        }

        // Update current time
        function updateCurrentTime() {
            const now = new Date();
            document.getElementById('current-time').textContent = now.toLocaleTimeString();
        }

        // Handle form submission
        function handleFormSubmit(event) {
            event.preventDefault();

            const form = event.target;
            const formData = {
                type: form.querySelector('#data-type').value,
                value: form.querySelector('#data-value').value,
                date: form.querySelector('#data-date').value,
                description: form.querySelector('#data-description').value
            };

            // Add to activity table
            const tableBody = document.getElementById('activity-table');
            const newRow = tableBody.insertRow(0);

            newRow.innerHTML = `
                <td>${formData.type}</td>
                <td>${formData.value}</td>
                <td>${formData.date}</td>
                <td>${formData.description || '-'}</td>
            `;

            // Update charts based on form data
            if (formData.type === 'users') {
                // Add to current period data
                const currentPeriod = document.querySelector('.btn-group .active').id.replace('-btn', '');
                userGrowthData[currentPeriod].data[userGrowthData[currentPeriod].data.length - 1] = parseInt(formData.value);
                updateUserGrowthChart(currentPeriod);
            } else if (formData.type === 'revenue') {
                // Update revenue chart
                revenueData.data[0] = parseInt(formData.value);
                revenueChart.data.datasets[0].data = revenueData.data;
                revenueChart.update();
            }

            // Reset form
            form.reset();

            // Show success message
            alert('Data submitted successfully!');
        }

        // Initialize the dashboard
        document.addEventListener('DOMContentLoaded', function() {
            // Initialize charts
            initCharts();

            // Set up time updater
            updateCurrentTime();
            setInterval(updateCurrentTime, 1000);

            // Set up stats updater
            updateStats();
            setInterval(updateStats, 5000);

            // Set up chart time period buttons
            document.getElementById('daily-btn').addEventListener('click', function() {
                document.querySelectorAll('.btn-group .btn').forEach(btn => btn.classList.remove('active'));
                this.classList.add('active');
                updateUserGrowthChart('daily');
            });

            document.getElementById('weekly-btn').addEventListener('click', function() {
                document.querySelectorAll('.btn-group .btn').forEach(btn => btn.classList.remove('active'));
                this.classList.add('active');
                updateUserGrowthChart('weekly');
            });

            document.getElementById('monthly-btn').addEventListener('click', function() {
                document.querySelectorAll('.btn-group .btn').forEach(btn => btn.classList.remove('active'));
                this.classList.add('active');
                updateUserGrowthChart('monthly');
            });

            // Set up refresh button
            document.getElementById('refresh-btn').addEventListener('click', function() {
                updateStats();
                const currentPeriod = document.querySelector('.btn-group .active').id.replace('-btn', '');
                updateUserGrowthChart(currentPeriod);
            });

            // Set up form submission
            document.getElementById('data-form').addEventListener('submit', handleFormSubmit);
        });
    </script>
</body>
