## JavaScript (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const usersChart = initChart('usersChart', 'line', 'Users Over Time', 'rgba(52, 152, 219, 0.2)', 'rgba(52, 152, 219, 1)');
    const revenueChart = initChart('revenueChart', 'bar', 'Revenue', 'rgba(46, 204, 113, 0.2)', 'rgba(46, 204, 113, 1)');
    const sessionsChart = initChart('sessionsChart', 'line', 'Active Sessions', 'rgba(231, 76, 60, 0.2)', 'rgba(231, 76, 60, 1)');
    const reportChart = initChart('reportChart', 'line', 'Report Data', 'rgba(155, 89, 182, 0.2)', 'rgba(155, 89, 182, 1)');

    // Initialize data
    let dashboardData = {
        totalUsers: 0,
        totalRevenue: 0,
        activeSessions: 0,
        userHistory: [],
        revenueHistory: [],
        sessionHistory: [],
        activityLog: []
    };

    // Load saved settings
    loadSettings();

    // Tab navigation
    document.querySelectorAll('.main-nav a').forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const tabId = this.getAttribute('data-tab');

            document.querySelectorAll('.main-nav li').forEach(li => {
                li.classList.remove('active');
            });

            document.querySelectorAll('.tab-content').forEach(tab => {
                tab.classList.remove('active');
            });

            this.parentElement.classList.add('active');
            document.getElementById(tabId).classList.add('active');
        });
    });

    // Data entry form handling
    document.getElementById('data-entry-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const eventType = document.getElementById('event-type').value;
        const eventValue = parseFloat(document.getElementById('event-value').value);
        const eventDescription = document.getElementById('event-description').value;

        if (!eventType || isNaN(eventValue)) {
            showFormResponse('Please fill in all required fields correctly.', 'error');
            return;
        }

        // Process the data
        const timestamp = new Date().toISOString();
        const newEvent = {
            timestamp,
            type: eventType,
            value: eventValue,
            description: eventDescription
        };

        // Update dashboard data
        switch(eventType) {
            case 'user_signup':
                dashboardData.totalUsers += eventValue;
                dashboardData.userHistory.push({ x: timestamp, y: dashboardData.totalUsers });
                break;
            case 'purchase':
                dashboardData.totalRevenue += eventValue;
                dashboardData.revenueHistory.push({ x: timestamp, y: dashboardData.totalRevenue });
                break;
            case 'session_start':
                dashboardData.activeSessions += eventValue;
                dashboardData.sessionHistory.push({ x: timestamp, y: dashboardData.activeSessions });
                break;
            case 'session_end':
                dashboardData.activeSessions = Math.max(0, dashboardData.activeSessions - eventValue);
                dashboardData.sessionHistory.push({ x: timestamp, y: dashboardData.activeSessions });
                break;
        }

        // Add to activity log
        dashboardData.activityLog.unshift({
            time: new Date().toLocaleTimeString(),
            event: eventType.replace('_', ' ').toUpperCase(),
            value: eventValue
        });

        // Update UI
        updateDashboardUI();
        updateActivityTable();

        // Show success message
        showFormResponse('Data submitted successfully!', 'success');

        // Reset form
        this.reset();
    });

    // Report generation
    document.getElementById('generate-report').addEventListener('click', function() {
        const reportType = document.getElementById('report-type').value;
        const reportDate = document.getElementById('report-date').value;

        // In a real app, you would fetch data based on these parameters
        console.log(`Generating ${reportType} report for ${reportDate || 'all time'}`);

        // For demo purposes, we'll just show some sample data
        const sampleData = generateSampleReportData(reportType);

        // Update report chart
        updateReportChart(reportChart, sampleData);

        // Update report stats
        document.getElementById('report-total-events').textContent = sampleData.totalEvents;
        document.getElementById('report-avg-value').textContent = `$${sampleData.avgValue.toFixed(2)}`;
    });

    // Settings form handling
    document.getElementById('settings-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const refreshRate = document.getElementById('refresh-rate').value;
        const theme = document.getElementById('theme').value;
        const notifications = document.getElementById('notifications').checked;

        // Save settings (in a real app, this would be to localStorage or a backend)
        localStorage.setItem('dashboardSettings', JSON.stringify({
            refreshRate,
            theme,
            notifications
        }));

        // Apply theme
        applyTheme(theme);

        // Show success message
        showFormResponse('Settings saved successfully!', 'success');
    });

    // Initial UI update
    updateDashboardUI();
    updateActivityTable();

    // Set up data refresh
    let refreshInterval = setInterval(() => {
        // In a real app, you would fetch new data here
        simulateDataUpdate();
    }, 10000); // Default refresh rate (10 seconds)

    // Function to update date and time
    function updateDateTime() {
        const now = new Date();
        document.getElementById('current-date').textContent = now.toLocaleDateString();
        document.getElementById('current-time').textContent = now.toLocaleTimeString();
    }

    // Function to initialize a chart
    function initChart(canvasId, type, label, bgColor, borderColor) {
        const ctx = document.getElementById(canvasId).getContext('2d');
        return new Chart(ctx, {
            type: type,
            data: {
                labels: [],
                datasets: [{
                    label: label,
                    data: [],
                    backgroundColor: bgColor,
                    borderColor: borderColor,
                    borderWidth: 2,
                    tension: 0.1,
                    fill: true
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        type: 'time',
                        time: {
                            unit: 'minute',
                            displayFormats: {
                                minute: 'HH:mm'
                            }
                        }
                    },
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    }

    // Function to update dashboard UI
    function updateDashboardUI() {
        document.getElementById('total-users').textContent = dashboardData.totalUsers;
        document.getElementById('total-revenue').textContent = `$${dashboardData.totalRevenue.toFixed(2)}`;
        document.getElementById('active-sessions').textContent = dashboardData.activeSessions;

        // Update charts
        updateChart(usersChart, dashboardData.userHistory);
        updateChart(revenueChart, dashboardData.revenueHistory);
        updateChart(sessionsChart, dashboardData.sessionHistory);
    }

    // Function to update a specific chart
    function updateChart(chart, data) {
        chart.data.labels = data.map(item => item.x);
        chart.data.datasets[0].data = data.map(item => item.y);
        chart.update();
    }

    // Function to update activity table
    function updateActivityTable() {
        const tableBody = document.querySelector('#activity-table tbody');
        tableBody.innerHTML = '';

        dashboardData.activityLog.slice(0, 10).forEach(activity => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${activity.time}</td>
                <td>${activity.event}</td>
                <td>${activity.value}</td>
            `;
            tableBody.appendChild(row);
        });
    }

    // Function to show form response
    function showFormResponse(message, type) {
        const responseElement = document.getElementById('form-response');
        responseElement.textContent = message;
        responseElement.className = 'form-response ' + type;

        // Hide after 5 seconds
        setTimeout(() => {
            responseElement.style.display = 'none';
        }, 5000);
    }

    // Function to update report chart
    function updateReportChart(chart, data) {
        chart.data.labels = data.labels;
        chart.data.datasets[0].data = data.values;
        chart.update();
    }

    // Function to generate sample report data
    function generateSampleReportData(reportType) {
        // In a real app, this would fetch data from an API
        const now = new Date();
        const labels = [];
        const values = [];

        // Generate sample data based on report type
        switch(reportType) {
            case 'daily':
                for (let i = 0; i < 24; i++) {
                    labels.push(`${i}:00`);
                    values.push(Math.floor(Math.random() * 100) + 10);
                }
                break;
            case 'weekly':
                const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
                for (let i = 0; i < 7; i++) {
                    labels.push(days[i]);
                    values.push(Math.floor(Math.random() * 500) + 100);
                }
                break;
            case 'monthly':
                for (let i = 1; i <= 30; i++) {
                    labels.push(`${i}`);
                    values.push(Math.floor(Math.random() * 1000) + 200);
                }
                break;
        }

        const totalEvents = values.reduce((a, b) => a + b, 0);
        const avgValue = totalEvents / values.length;

        return {
            labels,
            values,
            totalEvents,
            avgValue
        };
    }

    // Function to simulate data updates (for demo purposes)
    function simulateDataUpdate() {
        const eventTypes = ['user_signup', 'purchase', 'session_start', 'session_end'];
        const randomEvent = eventTypes[Math.floor(Math.random() * eventTypes.length)];
        const randomValue = Math.floor(Math.random() * 10) + 1;

        // Process the simulated data
        const timestamp = new Date().toISOString();
        const newEvent = {
            timestamp,
            type: randomEvent,
            value: randomValue,
            description: 'Simulated data update'
        };

        // Update dashboard data
        switch(randomEvent) {
            case 'user_signup':
                dashboardData.totalUsers += randomValue;
                dashboardData.userHistory.push({ x: timestamp, y: dashboardData.totalUsers });
                break;
            case 'purchase':
                dashboardData.totalRevenue += randomValue;
                dashboardData.revenueHistory.push({ x: timestamp, y: dashboardData.totalRevenue });
                break;
            case 'session_start':
                dashboardData.activeSessions += randomValue;
                dashboardData.sessionHistory.push({ x: timestamp, y: dashboardData.activeSessions });
                break;
            case 'session_end':
                dashboardData.activeSessions = Math.max(0, dashboardData.activeSessions - randomValue);
                dashboardData.sessionHistory.push({ x: timestamp, y: dashboardData.activeSessions });
                break;
        }

        // Add to activity log
        dashboardData.activityLog.unshift({
            time: new Date().toLocaleTimeString(),
            event: randomEvent.replace('_', ' ').toUpperCase(),
            value: randomValue
        });

        // Update UI
        updateDashboardUI();
        updateActivityTable();
    }

    // Function to load settings
    function loadSettings() {
        const savedSettings = localStorage.getItem('dashboardSettings');
        if (savedSettings) {
            const settings = JSON.parse(savedSettings);

            // Apply settings
            document.getElementById('refresh-rate').value = settings.refreshRate || 10;
            document.getElementById('theme').value = settings.theme || 'light';
            document.getElementById('notifications').checked = settings.notifications !== false;

            // Apply theme
            applyTheme(settings.theme || 'light');
        }
    }

    // Function to apply theme
    function applyTheme(theme) {
        if (theme === 'dark') {
            document.body.classList.add('dark-theme');
        } else {
            document.body.classList.remove('dark-theme');
        }
    }
});
