                    <li><a href="#">Analytics</a></li>
                    <li><a href="#">Reports</a></li>
                    <li><a href="#">Settings</a></li>
                </ul>
            </nav>
        </div>

        <div class="main-content">
            <div class="card">
                <div class="card-header">
                    <h3>Sales Overview</h3>
                    <button class="refresh-btn" id="refreshSales">Refresh</button>
                </div>
                <div class="chart-container">
                    <canvas id="salesChart"></canvas>
                </div>
            </div>

            <div class="card">
                <div class="card-header">
                    <h3>User Activity</h3>
                    <button class="refresh-btn" id="refreshActivity">Refresh</button>
                </div>
                <div class="chart-container">
                    <canvas id="activityChart"></canvas>
                </div>
            </div>

            <div class="card form-card">
                <div class="card-header">
                    <h3>Add New Data</h3>
                </div>
                <div class="alert alert-success" id="successAlert">Data submitted successfully!</div>
                <div class="alert alert-danger" id="errorAlert">Please fill in all required fields.</div>
                <form id="dataForm">
                    <div class="form-group">
                        <label for="dataType">Data Type</label>
                        <select id="dataType" name="dataType" required>
                            <option value="">Select a type</option>
                            <option value="sales">Sales</option>
                            <option value="users">Users</option>
                            <option value="revenue">Revenue</option>
                        </select>
                    </div>
                    <div class="form-group">
                        <label for="dataValue">Value</label>
                        <input type="number" id="dataValue" name="dataValue" required>
                    </div>
                    <div class="form-group">
                        <label for="dataDate">Date</label>
                        <input type="date" id="dataDate" name="dataDate" required>
                    </div>
                    <div class="form-group">
                        <label for="dataNotes">Notes (Optional)</label>
                        <textarea id="dataNotes" name="dataNotes"></textarea>
                    </div>
                    <button type="submit" class="btn">Submit</button>
                    <button type="reset" class="btn btn-danger">Reset</button>
                </form>
            </div>
        </div>
    </div>

    <script>
        // Initialize charts
        const salesCtx = document.getElementById('salesChart').getContext('2d');
        const activityCtx = document.getElementById('activityChart').getContext('2d');

        // Sample data
        let salesData = {
            labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
            datasets: [{
                label: 'Monthly Sales',
                data: [120, 190, 300, 500, 200, 300],
                backgroundColor: 'rgba(52, 152, 219, 0.5)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 1
            }]
        };

        let activityData = {
            labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
            datasets: [{
                label: 'Daily Active Users',
                data: [150, 200, 180, 220, 250, 300, 280],
                backgroundColor: 'rgba(46, 204, 113, 0.5)',
                borderColor: 'rgba(46, 204, 113, 1)',
                borderWidth: 1
            }]
        };

        // Create charts
        const salesChart = new Chart(salesCtx, {
            type: 'bar',
            data: salesData,
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

        const activityChart = new Chart(activityCtx, {
            type: 'line',
            data: activityData,
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

        // Refresh buttons
        document.getElementById('refreshSales').addEventListener('click', function() {
            // Simulate fetching new data
            salesData.datasets[0].data = salesData.datasets[0].data.map(() => Math.floor(Math.random() * 500) + 50);
            salesChart.update();
        });

        document.getElementById('refreshActivity').addEventListener('click', function() {
            // Simulate fetching new data
            activityData.datasets[0].data = activityData.datasets[0].data.map(() => Math.floor(Math.random() * 300) + 50);
            activityChart.update();
        });

        // Form handling
        const dataForm = document.getElementById('dataForm');
        const successAlert = document.getElementById('successAlert');
        const errorAlert = document.getElementById('errorAlert');

        dataForm.addEventListener('submit', function(e) {
            e.preventDefault();

            // Validate form
            const dataType = document.getElementById('dataType').value;
            const dataValue = document.getElementById('dataValue').value;
            const dataDate = document.getElementById('dataDate').value;

            if (!dataType || !dataValue || !dataDate) {
                errorAlert.style.display = 'block';
                setTimeout(() => {
                    errorAlert.style.display = 'none';
                }, 3000);
                return;
            }

            // Process form data
            const formData = {
                type: dataType,
                value: parseFloat(dataValue),
                date: new Date(dataDate),
                notes: document.getElementById('dataNotes').value
            };

            // Here you would typically send the data to a server
            console.log('Form data submitted:', formData);

            // Show success message
            successAlert.style.display = 'block';
            setTimeout(() => {
                successAlert.style.display = 'none';
            }, 3000);

            // Reset form
            dataForm.reset();

            // Update charts based on form data
            if (formData.type === 'sales') {
                // Add new data point to sales chart
                const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
                const month = monthNames[formData.date.getMonth()];

                if (!salesData.labels.includes(month)) {
                    salesData.labels.push(month);
                    salesData.datasets[0].data.push(formData.value);
                } else {
                    const index = salesData.labels.indexOf(month);
                    salesData.datasets[0].data[index] = formData.value;
                }

                salesChart.update();
            } else if (formData.type === 'users') {
                // Add new data point to activity chart
                const dayNames = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
                const day = dayNames[formData.date.getDay()];

                if (!activityData.labels.includes(day)) {
                    activityData.labels.push(day);
                    activityData.datasets[0].data.push(formData.value);
                } else {
                    const index = activityData.labels.indexOf(day);
                    activityData.datasets[0].data[index] = formData.value;
                }

                activityChart.update();
            }
        });

        // Sidebar navigation
        const navLinks = document.querySelectorAll('.sidebar nav ul li a');
        navLinks.forEach(link => {
            link.addEventListener('click', function(e) {
                e.preventDefault();
                navLinks.forEach(l => l.classList.remove('active'));
                this.classList.add('active');
                // Here you would typically load different content based on the selection
                console.log('Navigated to:', this.textContent);
            });
        });
    </script>
</body>
</html>
```

