## JavaScript (script.js)

```javascript
// Dashboard Data and State
let dashboardData = {
    sales: [],
    traffic: [],
    temperature: [],
    allData: []
};

// Chart instance
let mainChart;

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Set current date and time
    updateCurrentDateTime();
    setInterval(updateCurrentDateTime, 1000);

    // Initialize chart
    initChart();

    // Set default timestamp to now
    const now = new Date();
    const localDateTime = now.toISOString().slice(0, 16);
    document.getElementById('timestamp').value = localDateTime;

    // Form submission handler
    document.getElementById('dataForm').addEventListener('submit', handleFormSubmit);

    // Simulate incoming data (for demo purposes)
    simulateIncomingData();
});

// Update current date and time display
function updateCurrentDateTime() {
    const now = new Date();
    const options = {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

// Initialize the main chart
function initChart() {
    const ctx = document.getElementById('mainChart').getContext('2d');

    mainChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Sales',
                    data: [],
                    borderColor: '#3498db',
                    backgroundColor: 'rgba(52, 152, 219, 0.1)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Website Traffic',
                    data: [],
                    borderColor: '#2ecc71',
                    backgroundColor: 'rgba(46, 204, 113, 0.1)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Temperature',
                    data: [],
                    borderColor: '#e74c3c',
                    backgroundColor: 'rgba(231, 76, 60, 0.1)',
                    tension: 0.3,
                    fill: true
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                tooltip: {
                    mode: 'index',
                    intersect: false
                }
            }
        }
    });
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const data = {
        type: formData.get('dataType'),
        value: parseFloat(formData.get('value')),
        timestamp: new Date(formData.get('timestamp')),
        notes: formData.get('notes') || ''
    };

    // Add data to our dataset
    dashboardData[data.type].push(data);
    dashboardData.allData.push(data);

    // Update UI
    updateChart();
    updateDataTable();
    updateStatistics();

    // Reset form
    form.reset();

    // Set default timestamp to now
    const now = new Date();
    const localDateTime = now.toISOString().slice(0, 16);
    document.getElementById('timestamp').value = localDateTime;
}

// Update the chart with new data
function updateChart() {
    // Prepare data for chart
    const labels = [...new Set(dashboardData.allData.map(item => item.timestamp.toLocaleDateString()))];
    const salesData = labels.map(date => {
        return dashboardData.sales
            .filter(item => item.timestamp.toLocaleDateString() === date)
            .reduce((sum, item) => sum + item.value, 0);
    });

    const trafficData = labels.map(date => {
        return dashboardData.traffic
            .filter(item => item.timestamp.toLocaleDateString() === date)
            .reduce((sum, item) => sum + item.value, 0);
    });

    const tempData = labels.map(date => {
        return dashboardData.temperature
            .filter(item => item.timestamp.toLocaleDateString() === date)
            .reduce((sum, item) => sum + item.value, 0);
    });

    // Update chart data
    mainChart.data.labels = labels;
    mainChart.data.datasets[0].data = salesData;
    mainChart.data.datasets[1].data = trafficData;
    mainChart.data.datasets[2].data = tempData;

    mainChart.update();
}

// Update the data table
function updateDataTable() {
    const tableBody = document.querySelector('#dataTable tbody');
    tableBody.innerHTML = '';

    // Sort data by timestamp (newest first)
    const sortedData = [...dashboardData.allData].sort((a, b) => b.timestamp - a.timestamp);

    // Only show last 10 entries
    const recentData = sortedData.slice(0, 10);

    recentData.forEach(item => {
        const row = document.createElement('tr');

        const typeCell = document.createElement('td');
        typeCell.textContent = item.type.charAt(0).toUpperCase() + item.type.slice(1);
        row.appendChild(typeCell);

        const valueCell = document.createElement('td');
        valueCell.textContent = item.value.toFixed(2);
        row.appendChild(valueCell);

        const timeCell = document.createElement('td');
        timeCell.textContent = item.timestamp.toLocaleString();
        row.appendChild(timeCell);

        const notesCell = document.createElement('td');
        notesCell.textContent = item.notes || '-';
        row.appendChild(notesCell);

        tableBody.appendChild(row);
    });
}

// Update statistics display
function updateStatistics() {
    const totalPoints = dashboardData.allData.length;
    const averageValue = totalPoints > 0
        ? (dashboardData.allData.reduce((sum, item) => sum + item.value, 0) / totalPoints).toFixed(2)
        : '0.00';
    const lastUpdate = totalPoints > 0
        ? dashboardData.allData[dashboardData.allData.length - 1].timestamp.toLocaleString()
        : 'Never';

    document.getElementById('totalDataPoints').textContent = totalPoints;
    document.getElementById('averageValue').textContent = averageValue;
    document.getElementById('lastUpdate').textContent = lastUpdate;
}

// Simulate incoming data (for demo purposes)
function simulateIncomingData() {
    // Add some initial data
    const now = new Date();
    const dataTypes = ['sales', 'traffic', 'temperature'];

    for (let i = 0; i < 5; i++) {
        const type = dataTypes[Math.floor(Math.random() * dataTypes.length)];
        const value = Math.random() * 100;
        const timestamp = new Date(now.getTime() - (5 - i) * 3600000); // Subtract hours

        const data = {
            type,
            value,
            timestamp,
            notes: `Simulated data point ${i + 1}`
        };

        dashboardData[type].push(data);
        dashboardData.allData.push(data);
    }

    // Update UI with initial data
    updateChart();
    updateDataTable();
    updateStatistics();

    // Simulate new data every 5 seconds
    setInterval(() => {
        const type = dataTypes[Math.floor(Math.random() * dataTypes.length)];
        const value = Math.random() * 100;
        const timestamp = new Date();

        const data = {
            type,
            value,
            timestamp,
            notes: 'Simulated real-time data'
        };

        dashboardData[type].push(data);
        dashboardData.allData.push(data);

        updateChart();
        updateDataTable();
        updateStatistics();
    }, 5000);
}
```

