## JavaScript (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const salesChart = initChart('salesChart', 'bar', 'Sales Overview', ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'], [12000, 19000, 3000, 5000, 2000, 3000]);
    const userGrowthChart = initChart('userGrowthChart', 'line', 'User Growth', ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'], [100, 250, 400, 600, 800, 1000]);

    // Initialize data table
    const dataTable = document.querySelector('#data-table tbody');

    // Form submission handler
    const dataForm = document.getElementById('data-form');
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();

        const formData = new FormData(dataForm);
        const newData = {
            label: formData.get('label'),
            value: parseFloat(formData.get('value')),
            type: formData.get('type')
        };

        // Add to table
        addDataToTable(newData, dataTable);

        // Update chart based on type
        if (newData.type === 'bar') {
            salesChart.data.labels.push(newData.label);
            salesChart.data.datasets[0].data.push(newData.value);
            salesChart.update();
        } else if (newData.type === 'line') {
            userGrowthChart.data.labels.push(newData.label);
            userGrowthChart.data.datasets[0].data.push(newData.value);
            userGrowthChart.update();
        }

        // Reset form
        dataForm.reset();

        // Update summary cards
        updateSummaryCards();
    });

    // Initial data
    const initialData = [
        { label: 'Q1', value: 12000, type: 'bar' },
        { label: 'Q2', value: 19000, type: 'bar' },
        { label: 'Q3', value: 3000, type: 'bar' },
        { label: 'Q4', value: 5000, type: 'bar' },
        { label: 'Jan', value: 100, type: 'line' },
        { label: 'Feb', value: 250, type: 'line' },
        { label: 'Mar', value: 400, type: 'line' },
        { label: 'Apr', value: 600, type: 'line' },
        { label: 'May', value: 800, type: 'line' },
        { label: 'Jun', value: 1000, type: 'line' }
    ];

    // Add initial data to table
    initialData.forEach(data => addDataToTable(data, dataTable));

    // Update summary cards with initial data
    updateSummaryCards();
});

// Function to update date and time
function updateDateTime() {
    const now = new Date();
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
}

// Function to initialize a chart
function initChart(canvasId, type, title, labels, data) {
    const ctx = document.getElementById(canvasId).getContext('2d');
    return new Chart(ctx, {
        type: type,
        data: {
            labels: labels,
            datasets: [{
                label: title,
                data: data,
                backgroundColor: type === 'pie' ? [
                    'rgba(75, 192, 192, 0.7)',
                    'rgba(54, 162, 235, 0.7)',
                    'rgba(255, 206, 86, 0.7)',
                    'rgba(75, 192, 192, 0.7)',
                    'rgba(153, 102, 255, 0.7)',
                    'rgba(255, 159, 64, 0.7)'
                ] : 'rgba(75, 192, 192, 0.7)',
                borderColor: type === 'pie' ? [
                    'rgba(75, 192, 192, 1)',
                    'rgba(54, 162, 235, 1)',
                    'rgba(255, 206, 86, 1)',
                    'rgba(75, 192, 192, 1)',
                    'rgba(153, 102, 255, 1)',
                    'rgba(255, 159, 64, 1)'
                ] : 'rgba(75, 192, 192, 1)',
                borderWidth: 1,
                tension: 0.1,
                fill: type === 'line' ? true : false
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                title: {
                    display: true,
                    text: title
                }
            }
        }
    });
}

// Function to add data to the table
function addDataToTable(data, tableBody) {
    const row = document.createElement('tr');

    const labelCell = document.createElement('td');
    labelCell.textContent = data.label;
    row.appendChild(labelCell);

    const valueCell = document.createElement('td');
    valueCell.textContent = data.value;
    row.appendChild(valueCell);

    const typeCell = document.createElement('td');
    typeCell.textContent = data.type;
    row.appendChild(typeCell);

    const actionsCell = document.createElement('td');
    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'btn-delete';
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', function() {
        row.remove();
        updateSummaryCards();
    });
    actionsCell.appendChild(deleteBtn);
    row.appendChild(actionsCell);

    tableBody.appendChild(row);
}

// Function to update summary cards
function updateSummaryCards() {
    const tableRows = document.querySelectorAll('#data-table tbody tr');
    let totalUsers = 0;
    let totalRevenue = 0;
    let totalTasks = 0;

    tableRows.forEach(row => {
        const value = parseFloat(row.cells[1].textContent);
        const type = row.cells[2].textContent;

        if (type === 'bar') {
            totalRevenue += value;
        } else if (type === 'line') {
            totalUsers += value;
        } else {
            totalTasks += value;
        }
    });

    document.getElementById('total-users').textContent = totalUsers;
    document.getElementById('total-revenue').textContent = `$${totalRevenue.toLocaleString()}`;
    document.getElementById('total-tasks').textContent = totalTasks;
}
