```javascript
// Dashboard Data
let dashboardData = {
    labels: ['January', 'February', 'March', 'April', 'May', 'June'],
    datasets: [{
        label: 'Sample Data',
        data: [65, 59, 80, 81, 56, 55],
        backgroundColor: [
            'rgba(54, 162, 235, 0.5)',
            'rgba(255, 99, 132, 0.5)',
            'rgba(75, 192, 192, 0.5)',
            'rgba(153, 102, 255, 0.5)',
            'rgba(255, 159, 64, 0.5)',
            'rgba(255, 205, 86, 0.5)'
        ],
        borderColor: [
            'rgba(54, 162, 235, 1)',
            'rgba(255, 99, 132, 1)',
            'rgba(75, 192, 192, 1)',
            'rgba(153, 102, 255, 1)',
            'rgba(255, 159, 64, 1)',
            'rgba(255, 205, 86, 1)'
        ],
        borderWidth: 1
    }]
};

// Chart configuration
let chartConfig = {
    type: 'bar',
    data: dashboardData,
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: true
            }
        },
        plugins: {
            legend: {
                position: 'top',
            },
            tooltip: {
                callbacks: {
                    label: function(context) {
                        return `${context.dataset.label}: ${context.raw}`;
                    }
                }
            }
        }
    }
};

// Initialize chart
let mainChart = new Chart(
    document.getElementById('main-chart'),
    chartConfig
);

// DOM elements
const dataForm = document.getElementById('data-form');
const dataTable = document.getElementById('data-table').querySelector('tbody');
const chartTypeSelect = document.getElementById('chart-type');
const updateIntervalInput = document.getElementById('update-interval');
const toggleRealtimeBtn = document.getElementById('toggle-realtime');
const clearDataBtn = document.getElementById('clear-data');
const currentDateElement = document.getElementById('current-date');
const currentTimeElement = document.getElementById('current-time');

// State variables
let isRealtimeActive = true;
let updateInterval = 5000;
let updateIntervalId = null;

// Initialize the dashboard
function initDashboard() {
    updateDateTime();
    renderDataTable();
    startRealtimeUpdates();

    // Event listeners
    dataForm.addEventListener('submit', handleFormSubmit);
    chartTypeSelect.addEventListener('change', handleChartTypeChange);
    updateIntervalInput.addEventListener('change', handleUpdateIntervalChange);
    toggleRealtimeBtn.addEventListener('click', toggleRealtimeUpdates);
    clearDataBtn.addEventListener('click', clearAllData);
}

// Update date and time
function updateDateTime() {
    const now = new Date();
    currentDateElement.textContent = now.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    });
    currentTimeElement.textContent = now.toLocaleTimeString('en-US');

    // Update every second
    setTimeout(updateDateTime, 1000);
}

// Render data table
function renderDataTable() {
    dataTable.innerHTML = '';

    dashboardData.labels.forEach((label, index) => {
        const value = dashboardData.datasets[0].data[index];
        const color = dashboardData.datasets[0].backgroundColor[index];

        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${label}</td>
            <td>${value}</td>
            <td><div style="width: 20px; height: 20px; background-color: ${color}; border-radius: 3px;"></div></td>
            <td><button class="action-btn" data-index="${index}">Delete</button></td>
        `;

        dataTable.appendChild(row);
    });

    // Add event listeners to delete buttons
    document.querySelectorAll('.action-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const index = parseInt(e.target.getAttribute('data-index'));
            deleteDataPoint(index);
        });
    });
}

// Handle form submission
function handleFormSubmit(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const color = document.getElementById('data-color').value;

    // Add new data point
    dashboardData.labels.push(label);
    dashboardData.datasets[0].data.push(value);
    dashboardData.datasets[0].backgroundColor.push(`${color}80`); // 80 for 50% opacity
    dashboardData.datasets[0].borderColor.push(color);

    // Update chart and table
    mainChart.update();
    renderDataTable();

    // Reset form
    dataForm.reset();
}

// Handle chart type change
function handleChartTypeChange(e) {
    const newType = e.target.value;
    mainChart.destroy();

    chartConfig.type = newType;
    mainChart = new Chart(
        document.getElementById('main-chart'),
        chartConfig
    );
}

// Handle update interval change
function handleUpdateIntervalChange(e) {
    updateInterval = parseInt(e.target.value);

    if (isRealtimeActive) {
        clearInterval(updateIntervalId);
        startRealtimeUpdates();
    }
}

// Toggle realtime updates
function toggleRealtimeUpdates() {
    isRealtimeActive = !isRealtimeActive;

    if (isRealtimeActive) {
        toggleRealtimeBtn.textContent = 'Pause Updates';
        toggleRealtimeBtn.style.backgroundColor = '#2ecc71';
        startRealtimeUpdates();
    } else {
        toggleRealtimeBtn.textContent = 'Resume Updates';
        toggleRealtimeBtn.style.backgroundColor = '#f39c12';
        clearInterval(updateIntervalId);
    }
}

// Start realtime updates
function startRealtimeUpdates() {
    if (updateIntervalId) {
        clearInterval(updateIntervalId);
    }

    updateIntervalId = setInterval(() => {
        if (isRealtimeActive) {
            updateChartData();
        }
    }, updateInterval);
}

// Update chart data with random values
function updateChartData() {
    dashboardData.datasets[0].data = dashboardData.datasets[0].data.map(() => {
        return Math.floor(Math.random() * 100);
    });

    mainChart.update();
}

// Delete a data point
function deleteDataPoint(index) {
    dashboardData.labels.splice(index, 1);
    dashboardData.datasets[0].data.splice(index, 1);
    dashboardData.datasets[0].backgroundColor.splice(index, 1);
    dashboardData.datasets[0].borderColor.splice(index, 1);

    mainChart.update();
    renderDataTable();
}

// Clear all data
function clearAllData() {
    dashboardData.labels = [];
    dashboardData.datasets[0].data = [];
    dashboardData.datasets[0].backgroundColor = [];
    dashboardData.datasets[0].borderColor = [];

    mainChart.update();
    renderDataTable();
}

// Initialize the dashboard when the page loads
window.addEventListener('DOMContentLoaded', initDashboard);
```

## Features

1. **Real-time Data Visualization**:
   - Interactive charts using Chart.js
   - Multiple chart types (bar, line, pie, doughnut)
   - Automatic updates with configurable interval
   - Toggle to pause/resume updates

2. **Form Handling**:
   - Add new data points with labels, values, and colors
