## JavaScript (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const mainChartCtx = document.getElementById('mainChart').getContext('2d');
    const mainChart = new Chart(mainChartCtx, {
        type: 'line',
        data: {
            labels: generateLabels('daily', 7),
            datasets: [{
                label: 'Sales',
                data: generateRandomData(7, 100, 1000),
                borderColor: 'rgba(52, 152, 219, 1)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.4,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Initialize metrics
    updateMetrics();

    // Initialize data table
    updateDataTable('sales', 'daily');

    // Form submission handler
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const dataType = document.getElementById('dataType').value;
        const timeRange = document.getElementById('timeRange').value;
        const customValue = document.getElementById('customValue').value;

        // Update chart based on form data
        updateChart(mainChart, dataType, timeRange, customValue);

        // Update metrics
        updateMetrics(dataType, customValue);

        // Update data table
        updateDataTable(dataType, timeRange);
    });

    // Simulate real-time updates
    setInterval(() => {
        updateRealTimeData(mainChart);
    }, 5000);
});

// Helper functions
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    };
    document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
}

function generateLabels(timeRange, count) {
    const labels = [];
    const now = new Date();

    for (let i = 0; i < count; i++) {
        let date = new Date(now);

        if (timeRange === 'daily') {
            date.setDate(now.getDate() - (count - 1 - i));
            labels.push(date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }));
        } else if (timeRange === 'weekly') {
            date.setDate(now.getDate() - (count - 1 - i) * 7);
            labels.push(`Week ${getWeekNumber(date)}`);
        } else if (timeRange === 'monthly') {
            date.setMonth(now.getMonth() - (count - 1 - i));
            labels.push(date.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }));
        }
    }

    return labels;
}

function getWeekNumber(date) {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear = (date - firstDayOfYear) / 86400000;
    return Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7);
}

function generateRandomData(count, min, max) {
    return Array.from({length: count}, () => Math.floor(Math.random() * (max - min + 1)) + min);
}

function updateChart(chart, dataType, timeRange, customValue) {
    const count = timeRange === 'daily' ? 7 : timeRange === 'weekly' ? 4 : 6;
    const labels = generateLabels(timeRange, count);

    let data = generateRandomData(count, 100, 1000);

    // Apply custom value if provided
    if (customValue && !isNaN(customValue)) {
        data[data.length - 1] = parseInt(customValue);
    }

    // Update chart data based on data type
    let labelText = '';
    let color = '';

    switch(dataType) {
        case 'sales':
            labelText = 'Sales';
            color = 'rgba(52, 152, 219, 1)';
            break;
        case 'traffic':
            labelText = 'Traffic';
            color = 'rgba(46, 204, 113, 1)';
            break;
        case 'temperature':
            labelText = 'Temperature (°C)';
            color = 'rgba(231, 76, 60, 1)';
            data = generateRandomData(count, 10, 30);
            break;
    }

    chart.data.labels = labels;
    chart.data.datasets[0].label = labelText;
    chart.data.datasets[0].data = data;
    chart.data.datasets[0].borderColor = color;
    chart.data.datasets[0].backgroundColor = color.replace('1)', '0.1)');

    chart.update();
}

function updateMetrics(dataType = 'sales', customValue = null) {
    // Generate random metrics or use custom value
    const totalSales = customValue && dataType === 'sales' ? parseInt(customValue) :
                      Math.floor(Math.random() * 10000) + 5000;
    const activeUsers = Math.floor(Math.random() * 1000) + 100;
    const conversionRate = (Math.random() * 10).toFixed(1);

    document.getElementById('totalSales').textContent = `$${totalSales.toLocaleString()}`;
    document.getElementById('activeUsers').textContent = activeUsers.toLocaleString();
    document.getElementById('conversionRate').textContent = `${conversionRate}%`;
}

function updateDataTable(dataType, timeRange) {
    const tableBody = document.querySelector('#dataTable tbody');
    tableBody.innerHTML = '';

    const count = timeRange === 'daily' ? 7 : timeRange === 'weekly' ? 4 : 6;
    const labels = generateLabels(timeRange, count);
    const data = generateRandomData(count, 100, 1000);

    for (let i = 0; i < count; i++) {
        const row = document.createElement('tr');

        const dateCell = document.createElement('td');
        dateCell.textContent = labels[i];
        row.appendChild(dateCell);

        const valueCell = document.createElement('td');
        valueCell.textContent = dataType === 'temperature' ?
            `${data[i]}°C` : `$${data[i].toLocaleString()}`;
        row.appendChild(valueCell);

        const changeCell = document.createElement('td');
        const change = Math.floor(Math.random() * 20) - 10;
        changeCell.textContent = `${change > 0 ? '+' : ''}${change}%`;
        changeCell.style.color = change > 0 ? '#2ecc71' : '#e74c3c';
        row.appendChild(changeCell);

        tableBody.appendChild(row);
    }
}

function updateRealTimeData(chart) {
    // Add new data point to the chart
    const newDataPoint = Math.floor(Math.random() * 1000) + 100;
    const newLabel = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });

    // Remove first data point if we have more than 20
    if (chart.data.labels.length > 20) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
    }

    chart.data.labels.push(newLabel);
    chart.data.datasets[0].data.push(newDataPoint);
    chart.update();

    // Update metrics slightly
    const currentSales = parseInt(document.getElementById('totalSales').textContent.replace(/[^0-9]/g, ''));
    const change = Math.floor(Math.random() * 100) - 50;
    document.getElementById('totalSales').textContent = `$${(currentSales + change).toLocaleString()}`;

    // Update data table with new data
    const tableBody = document.querySelector('#dataTable tbody');
    if (tableBody.rows.length > 0) {
        const lastRow = tableBody.rows[tableBody.rows.length - 1];
        lastRow.cells[1].textContent = `$${newDataPoint.toLocaleString()}`;
    }
}
