    <script>
        // Initialize charts
        const ctx = document.getElementById('realtimeChart').getContext('2d');
        let realtimeChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: [{
                    label: 'Real-Time Data',
                    data: [],
                    backgroundColor: 'rgba(52, 152, 219, 0.2)',
                    borderColor: 'rgba(52, 152, 219, 1)',
                    borderWidth: 2,
                    tension: 0.1,
                    fill: true
                }]
            },
            options: {
                responsive: true,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                plugins: {
                    legend: {
                        position: 'top',
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return `${context.dataset.label}: ${context.raw}`;
                            }
                        }
                    }
                }
            }
        });

        // Simulate real-time data updates
        function updateChart() {
            const now = new Date();
            const timeString = now.toLocaleTimeString();

            // Add new data point
            const newValue = Math.floor(Math.random() * 100) + 1;
            realtimeChart.data.labels.push(timeString);
            realtimeChart.data.datasets[0].data.push(newValue);

            // Limit the number of data points displayed
            if (realtimeChart.data.labels.length > 20) {
                realtimeChart.data.labels.shift();
                realtimeChart.data.datasets[0].data.shift();
            }

            realtimeChart.update();

            // Update summary cards
            document.getElementById('total-users').textContent = Math.floor(Math.random() * 1000) + 500;
            document.getElementById('active-sessions').textContent = Math.floor(Math.random() * 500) + 100;
            document.getElementById('revenue').textContent = `$${(Math.random() * 10000).toFixed(2)}`;
            document.getElementById('conversion-rate').textContent = `${(Math.random() * 100).toFixed(1)}%`;
        }

        // Update chart every 3 seconds
        setInterval(updateChart, 3000);

        // Form handling
        const dataForm = document.getElementById('dataForm');
        const activityTable = document.getElementById('activityTable').getElementsByTagName('tbody')[0];

        dataForm.addEventListener('submit', function(e) {
            e.preventDefault();

            // Get form values
            const dataType = document.getElementById('dataType').value;
            const dataValue = document.getElementById('dataValue').value;
            const dataDescription = document.getElementById('dataDescription').value;

            // Create new table row
            const newRow = activityTable.insertRow();
            const cell1 = newRow.insertCell(0);
            const cell2 = newRow.insertCell(1);
            const cell3 = newRow.insertCell(2);
            const cell4 = newRow.insertCell(3);
            const cell5 = newRow.insertCell(4);
            const cell6 = newRow.insertCell(5);

            // Generate a random ID
            const id = Math.floor(Math.random() * 10000);

            // Format the current date
            const now = new Date();
            const dateString = now.toLocaleDateString() + ' ' + now.toLocaleTimeString();

            // Populate cells
            cell1.textContent = id;
            cell2.textContent = dataType.charAt(0).toUpperCase() + dataType.slice(1);
            cell3.textContent = dataValue;
            cell4.textContent = dataDescription;
            cell5.innerHTML = `<span class="status-active">Active</span>`;
            cell6.textContent = dateString;

            // Reset form
            dataForm.reset();

            // Show success message
            alert('Data submitted successfully!');
        });

        // Sidebar navigation
        const navLinks = document.querySelectorAll('.sidebar nav ul li a');
        navLinks.forEach(link => {
            link.addEventListener('click', function(e) {
                e.preventDefault();
                navLinks.forEach(l => l.classList.remove('active'));
                this.classList.add('active');
                // Here you would typically load different content based on the clicked link
                alert(`Navigating to ${this.textContent} section`);
            });
        });

        // Initialize with some sample data
        function initializeSampleData() {
            const sampleData = [
                { id: 1001, type: 'Users', value: 45, description: 'New user registrations', status: 'Active', date: '2023-05-15 10:30 AM' },
                { id: 1002, type: 'Sessions', value: 23, description: 'Active user sessions', status: 'Active', date: '2023-05-15 11:15 AM' },
                { id: 1003, type: 'Revenue', value: 1250, description: 'Daily sales revenue', status: 'Active', date: '2023-05-15 12:45 PM' }
            ];

            sampleData.forEach(data => {
                const newRow = activityTable.insertRow();
                const cell1 = newRow.insertCell(0);
                const cell2 = newRow.insertCell(1);
                const cell3 = newRow.insertCell(2);
                const cell4 = newRow.insertCell(3);
                const cell5 = newRow.insertCell(4);
                const cell6 = newRow.insertCell(5);

                cell1.textContent = data.id;
                cell2.textContent = data.type;
                cell3.textContent = data.value;
                cell4.textContent = data.description;
                cell5.innerHTML = `<span class="status-active">${data.status}</span>`;
                cell6.textContent = data.date;
            });
        }

        // Initialize the dashboard
        initializeSampleData();
        updateChart();
    </script>
</body>
</html>
```

## Features of this Dashboard:

1. **Real-Time Data Visualization**:
   - Uses Chart.js to create an interactive line chart that updates every 3 seconds
   - Simulates real-time data with random values

2. **Form Handling**:
   - Interactive form for submitting new data
   - Form validation
   - Data is displayed in a table below the form

3. **Responsive Design**:
   - Adapts to different screen sizes
   - Mobile-friendly layout

4. **Interactive Elements**:
   - Clickable sidebar navigation
   - Hover effects on cards and table rows
   - Form submission with feedback

5. **Summary Cards**:
   - Displays key metrics in visually appealing cards
   - Values update in real-time

6. **Data Table**:
   - Displays recent activity in a clean, sortable table
   - Status indicators for different data states

To use this dashboard, simply copy the entire code into an HTML file and open it in a web browser. No additional dependencies are required beyond the Chart.js library which is loaded from a CDN.

