    <script>
        // Sample initial data
        let salesData = {
            labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
            datasets: [{
                label: 'Sales',
                data: [120, 190, 300, 500, 200, 300],
                backgroundColor: 'rgba(66, 133, 244, 0.2)',
                borderColor: 'rgba(66, 133, 244, 1)',
                borderWidth: 2,
                tension: 0.1
            }]
        };

        let revenueData = {
            labels: ['Product A', 'Product B', 'Product C', 'Product D'],
            datasets: [{
                label: 'Revenue',
                data: [300, 500, 100, 200],
                backgroundColor: [
                    'rgba(66, 133, 244, 0.7)',
                    'rgba(52, 168, 83, 0.7)',
                    'rgba(234, 67, 53, 0.7)',
                    'rgba(251, 188, 5, 0.7)'
                ],
                borderColor: [
                    'rgba(66, 133, 244, 1)',
                    'rgba(52, 168, 83, 1)',
                    'rgba(234, 67, 53, 1)',
                    'rgba(251, 188, 5, 1)'
                ],
                borderWidth: 1
            }]
        };

        let usersData = {
            labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
            datasets: [{
                label: 'New Users',
                data: [50, 100, 150, 200, 250, 300],
                backgroundColor: 'rgba(52, 168, 83, 0.2)',
                borderColor: 'rgba(52, 168, 83, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }]
        };

        // Initialize charts
        const salesChart = new Chart(document.getElementById('salesChart'), {
            type: 'line',
            data: salesData,
            options: {
                responsive: true,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

        const revenueChart = new Chart(document.getElementById('revenueChart'), {
            type: 'doughnut',
            data: revenueData,
            options: {
                responsive: true,
                plugins: {
                    legend: {
                        position: 'right',
                    }
                }
            }
        });

        const usersChart = new Chart(document.getElementById('usersChart'), {
            type: 'bar',
            data: usersData,
            options: {
                responsive: true,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });

        // Form handling
        document.getElementById('dataForm').addEventListener('submit', function(e) {
            e.preventDefault();

            const dataType = document.getElementById('dataType').value;
            const dataValue = parseFloat(document.getElementById('dataValue').value);
            const dataDate = document.getElementById('dataDate').value;
            const dataNotes = document.getElementById('dataNotes').value;

            // Update charts based on form data
            if (dataType === 'sales') {
                // Add new data point to sales chart
                const month = new Date(dataDate).toLocaleString('default', { month: 'short' });
                if (!salesData.labels.includes(month)) {
                    salesData.labels.push(month);
                    salesData.datasets[0].data.push(dataValue);
                } else {
                    const index = salesData.labels.indexOf(month);
                    salesData.datasets[0].data[index] += dataValue;
                }
                salesChart.update();

                // Update total sales
                document.getElementById('totalSales').textContent =
                    (parseFloat(document.getElementById('totalSales').textContent) + dataValue).toFixed(2);
            }
            else if (dataType === 'revenue') {
                // Add new data point to revenue chart
                revenueData.datasets[0].data.push(dataValue);
                revenueData.labels.push(`Product ${revenueData.labels.length + 1}`);
                revenueChart.update();

                // Update total revenue
                document.getElementById('totalRevenue').textContent =
                    (parseFloat(document.getElementById('totalRevenue').textContent) + dataValue).toFixed(2);
            }
            else if (dataType === 'users') {
