        // Initialize totals
        document.getElementById('totalSales').textContent =
            salesData.datasets[0].data.reduce((a, b) => a + b, 0).toFixed(2);
        document.getElementById('totalRevenue').textContent =
            revenueData.datasets[0].data.reduce((a, b) => a + b, 0).toFixed(2);

        // Simulate real-time updates (every 10 seconds)
        setInterval(() => {
            // Add random data point to sales
            const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            const randomMonth = months[Math.floor(Math.random() * months.length)];
            const randomValue = Math.floor(Math.random() * 100) + 50;

            if (!salesData.labels.includes(randomMonth)) {
                salesData.labels.push(randomMonth);
                salesData.datasets[0].data.push(randomValue);
            } else {
                const index = salesData.labels.indexOf(randomMonth);
                salesData.datasets[0].data[index] += randomValue;
            }

            salesChart.update();

            // Update total sales
            document.getElementById('totalSales').textContent =
                salesData.datasets[0].data.reduce((a, b) => a + b, 0).toFixed(2);

            // Add to activity log
            const activityLog = document.getElementById('activityLog');
            const activityItem = document.createElement('div');
            activityItem.style.padding = '10px';
            activityItem.style.borderBottom = '1px solid #eee';
            activityItem.innerHTML = `
                <strong>Real-time Update</strong>:
                ${randomValue} sales added in ${randomMonth}
            `;
            activityLog.prepend(activityItem);
        }, 10000);
    </script>
</body>
</html>
```

