## JavaScript (script.js)

```javascript
// Dashboard Data
let dashboardData = {
    sales: {
        labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
        data: [12000, 15000, 18000, 22000, 25000, 28000],
        total: 28000,
        change: 12.5
    },
    users: {
        labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
        data: [500, 700, 900, 1200, 1500, 1800],
        total: 1800,
        change: -5.2
    },
    revenue: {
        labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
        data: [8000, 10000, 12000, 15000, 18000, 22000],
        total: 22000,
        change: 15.8
    },
    activities: [
        { icon: 'fas fa-dollar-sign', title: 'New Sale', description: 'Order #12345 completed', time: '2 minutes ago' },
        { icon: 'fas fa-user-plus', title: 'New User', description: 'John Doe registered', time: '5 minutes ago' },
        { icon: 'fas fa-chart-line', title: 'Revenue Update', description: 'Monthly revenue reached $22,000', time: '1 hour ago' },
        { icon: 'fas fa-cog', title: 'System Update', description: 'Dashboard updated to v2.1', time: '2 hours ago' }
    ]
};

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const salesChart = initChart('sales-chart', 'Sales Overview', dashboardData.sales.labels, dashboardData.sales.data, 'rgba(67, 97, 238, 0.8)');
    const usersChart = initChart('users-chart', 'User Growth', dashboardData.users.labels, dashboardData.users.data, 'rgba(76, 201, 240, 0.8)');

    // Update card values
    updateCardValues();

    // Populate activity list
    populateActivityList();

    // Handle form submission
    const form = document.getElementById('data-form');
    form.addEventListener('submit', function(e) {
        e.preventDefault();
        handleFormSubmit(salesChart, usersChart);
    });

    // Add some random data updates for demonstration
    setInterval(() => {
        addRandomData(salesChart, usersChart);
    }, 5000);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Initialize a chart
function initChart(canvasId, title, labels, data, color) {
    const ctx = document.getElementById(canvasId).getContext('2d');
    return new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: title,
                data: data,
                backgroundColor: color,
                borderColor: color,
                borderWidth: 2,
                tension: 0.3,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    display: false
                }
            }
        }
    });
}

// Update card values
function updateCardValues() {
    document.getElementById('total-sales').textContent = `$${dashboardData.sales.total.toLocaleString()}`;
    document.getElementById('sales-change').textContent = `${dashboardData.sales.change > 0 ? '+' : ''}${dashboardData.sales.change}%`;
    document.getElementById('sales-change').className = dashboardData.sales.change > 0 ? 'positive' : 'negative';

    document.getElementById('active-users').textContent = dashboardData.users.total.toLocaleString();
    document.getElementById('users-change').textContent = `${dashboardData.users.change > 0 ? '+' : ''}${dashboardData.users.change}%`;
    document.getElementById('users-change').className = dashboardData.users.change > 0 ? 'positive' : 'negative';

    document.getElementById('total-revenue').textContent = `$${dashboardData.revenue.total.toLocaleString()}`;
    document.getElementById('revenue-change').textContent = `${dashboardData.revenue.change > 0 ? '+' : ''}${dashboardData.revenue.change}%`;
    document.getElementById('revenue-change').className = dashboardData.revenue.change > 0 ? 'positive' : 'negative';
}

// Populate activity list
function populateActivityList() {
    const activityList = document.getElementById('activity-list');
    activityList.innerHTML = '';

    dashboardData.activities.forEach(activity => {
        const activityItem = document.createElement('div');
        activityItem.className = 'activity-item';
        activityItem.innerHTML = `
            <div class="activity-icon"><i class="${activity.icon}"></i></div>
            <div class="activity-content">
                <h4>${activity.title}</h4>
                <p>${activity.description}</p>
            </div>
            <div class="activity-time">${activity.time}</div>
        `;
        activityList.appendChild(activityItem);
    });
}

// Handle form submission
function handleFormSubmit(salesChart, usersChart) {
    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const type = document.getElementById('data-type').value;

    if (!label || isNaN(value)) {
        alert('Please fill in all fields correctly');
        return;
    }

    // Update the appropriate dataset
    if (type === 'sales') {
        dashboardData.sales.labels.push(label);
        dashboardData.sales.data.push(value);
        dashboardData.sales.total += value;
        dashboardData.sales.change = ((value - dashboardData.sales.data[dashboardData.sales.data.length - 2]) / dashboardData.sales.data[dashboardData.sales.data.length - 2] * 100).toFixed(1);

        // Update chart
        salesChart.data.labels = dashboardData.sales.labels;
        salesChart.data.datasets[0].data = dashboardData.sales.data;
        salesChart.update();
    } else if (type === 'users') {
        dashboardData.users.labels.push(label);
        dashboardData.users.data.push(value);
        dashboardData.users.total += value;
        dashboardData.users.change = ((value - dashboardData.users.data[dashboardData.users.data.length - 2]) / dashboardData.users.data[dashboardData.users.data.length - 2] * 100).toFixed(1);

        // Update chart
        usersChart.data.labels = dashboardData.users.labels;
        usersChart.data.datasets[0].data = dashboardData.users.data;
        usersChart.update();
    } else if (type === 'revenue') {
        dashboardData.revenue.labels.push(label);
        dashboardData.revenue.data.push(value);
        dashboardData.revenue.total += value;
        dashboardData.revenue.change = ((value - dashboardData.revenue.data[dashboardData.revenue.data.length - 2]) / dashboardData.revenue.data[dashboardData.revenue.data.length - 2] * 100).toFixed(1);
    }

    // Update card values
    updateCardValues();

    // Add to activity list
    const newActivity = {
        icon: type === 'sales' ? 'fas fa-dollar-sign' :
              type === 'users' ? 'fas fa-user-plus' : 'fas fa-chart-line',
        title: `New ${type.charAt(0).toUpperCase() + type.slice(1)} Data`,
        description: `${label}: ${value}`,
        time: 'Just now'
    };

    dashboardData.activities.unshift(newActivity);
    if (dashboardData.activities.length > 5) {
        dashboardData.activities.pop();
    }
    populateActivityList();

    // Reset form
    document.getElementById('data-form').reset();
}

// Add random data for demonstration
function addRandomData(salesChart, usersChart) {
    const months = ['Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const randomMonth = months[Math.floor(Math.random() * months.length)];

    // Random sales data
    const newSales = Math.floor(Math.random() * 5000) + 10000;
    dashboardData.sales.labels.push(randomMonth);
    dashboardData.sales.data.push(newSales);
    dashboardData.sales.total += newSales;
    dashboardData.sales.change = ((newSales - dashboardData.sales.data[dashboardData.sales.data.length - 2]) / dashboardData.sales.data[dashboardData.sales.data.length - 2] * 100).toFixed(1);

    // Random users data
    const newUsers = Math.floor(Math.random() * 200) + 300;
    dashboardData.users.labels.push(randomMonth);
    dashboardData.users.data.push(newUsers);
    dashboardData.users.total += newUsers;
    dashboardData.users.change = ((newUsers - dashboardData.users.data[dashboardData.users.data.length - 2]) / dashboardData.users.data[dashboardData.users.data.length - 2] * 100).toFixed(1);

    // Update charts
    salesChart.data.labels = dashboardData.sales.labels;
    salesChart.data.datasets[0].data = dashboardData.sales.data;
    salesChart.update();

    usersChart.data.labels = dashboardData.users.labels;
    usersChart.data.datasets[0].data = dashboardData.users.data;
    usersChart.update();

    // Update card values
    updateCardValues();

    // Add to activity list
    const newActivity = {
        icon: 'fas fa-chart-line',
        title: 'Automatic Data Update',
        description: `Added ${randomMonth} data`,
        time: 'Just now'
    };

    dashboardData.activities.unshift(newActivity);
    if (dashboardData.activities.length > 5) {
        dashboardData.activities.pop();
    }
    populateActivityList();
}
