    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <script>
        // Dashboard Data
        let dashboardData = {
            sales: [],
            users: [],
            revenue: [],
            allDataPoints: []
        };

        // Chart Instances
        let salesChart, userGrowthChart;

        // Initialize the dashboard
        document.addEventListener('DOMContentLoaded', function() {
            // Initialize charts
            initCharts();

            // Set up event listeners
            setupEventListeners();

            // Load initial data
            loadInitialData();

            // Update current time
            updateCurrentTime();
            setInterval(updateCurrentTime, 1000);

            // Simulate real-time data updates
            setInterval(simulateRealTimeData, 5000);
        });

        // Initialize charts
        function initCharts() {
            const salesCtx = document.getElementById('salesChart').getContext('2d');
            const userGrowthCtx = document.getElementById('userGrowthChart').getContext('2d');

            // Sales Chart
            salesChart = new Chart(salesCtx, {
                type: 'line',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Sales',
                        data: [],
                        borderColor: 'rgb(75, 192, 192)',
                        tension: 0.1,
                        fill: true,
                        backgroundColor: 'rgba(75, 192, 192, 0.2)'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });

            // User Growth Chart
            userGrowthChart = new Chart(userGrowthCtx, {
                type: 'bar',
                data: {
                    labels: [],
                    datasets: [{
                        label: 'Users',
                        data: [],
                        backgroundColor: 'rgba(54, 162, 235, 0.5)',
                        borderColor: 'rgba(54, 162, 235, 1)',
                        borderWidth: 1
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        }

        // Set up event listeners
        function setupEventListeners() {
            // Form submission
            document.getElementById('data-form').addEventListener('submit', function(e) {
                e.preventDefault();
                handleFormSubmission();
            });

            // Refresh button
            document.getElementById('refresh-btn').addEventListener('click', function() {
                refreshDashboard();
            });
        }

        // Load initial data
        function loadInitialData() {
            // Simulate loading initial data
            const initialSales = [
                { date: '2023-01-01', value: 1200 },
                { date: '2023-02-01', value: 1900 },
                { date: '2023-03-01', value: 3000 },
                { date: '2023-04-01', value: 2500 },
                { date: '2023-05-01', value: 3200 }
            ];

            const initialUsers = [
                { date: '2023-01-01', value: 500 },
                { date: '2023-02-01', value: 700 },
                { date: '2023-03-01', value: 1200 },
                { date: '2023-04-01', value: 1500 },
                { date: '2023-05-01', value: 1800 }
            ];

            // Add initial data to dashboard
            initialSales.forEach(item => addDataPoint('sales', item.date, item.value, 'Initial Sales Data'));
            initialUsers.forEach(item => addDataPoint('users', item.date, item.value, 'Initial User Data'));

            // Update charts
            updateCharts();

            // Show alert
            showAlert('Dashboard initialized with sample data. You can add more data using the form.');
        }

        // Handle form submission
        function handleFormSubmission() {
            const name = document.getElementById('data-name').value;
            const value = parseFloat(document.getElementById('data-value').value);
            const category = document.getElementById('data-category').value;
            const date = document.getElementById('data-date').value;

            if (!name || isNaN(value) || !category || !date) {
                showAlert('Please fill in all fields correctly.', 'danger');
                return;
            }

            // Add the data point
            addDataPoint(category, date, value, name);

            // Update charts
            updateCharts();

            // Reset form
            document.getElementById('data-form').reset();

            // Show success message
            showAlert(`New ${category} data point added successfully!`, 'success');
        }

        // Add a data point to the dashboard
        function addDataPoint(category, date, value, name) {
            const dataPoint = {
                id: Date.now(),
                name: name,
                value: value,
                category: category,
                date: date,
                timestamp: new Date().toLocaleString()
            };

            // Add to appropriate category array
            if (category === 'sales') {
                dashboardData.sales.push(dataPoint);
            } else if (category === 'users') {
                dashboardData.users.push(dataPoint);
            } else if (category === 'revenue') {
                dashboardData.revenue.push(dataPoint);
            }

            // Add to all data points
            dashboardData.allDataPoints.push(dataPoint);

            // Update recent data points display
            updateRecentDataPoints();

            // Update key metrics
            updateKeyMetrics();
        }

        // Update charts with current data
        function updateCharts() {
            // Update sales chart
            const salesLabels = dashboardData.sales.map(item => item.date);
            const salesValues = dashboardData.sales.map(item => item.value);

            salesChart.data.labels = salesLabels;
            salesChart.data.datasets[0].data = salesValues;
            salesChart.update();

            // Update user growth chart
            const userLabels = dashboardData.users.map(item => item.date);
            const userValues = dashboardData.users.map(item => item.value);

            userGrowthChart.data.labels = userLabels;
            userGrowthChart.data.datasets[0].data = userValues;
            userGrowthChart.update();
        }

        // Update recent data points display
        function updateRecentDataPoints() {
            const container = document.getElementById('data-points-container');
            container.innerHTML = '';

            // Get last 5 data points
            const recentData = dashboardData.allDataPoints.slice(-5).reverse();

            if (recentData.length === 0) {
                container.innerHTML = '<p class="text-muted">No data points added yet.</p>';
                return;
            }

            recentData.forEach(dataPoint => {
                const dataPointElement = document.createElement('div');
                dataPointElement.className = 'data-point mb-2';
                dataPointElement.innerHTML = `
                    <div class="d-flex justify-content-between">
                        <div>
                            <h5>${dataPoint.name}</h5>
                            <p class="mb-1">${dataPoint.category.charAt(0).toUpperCase() + dataPoint.category.slice(1)}</p>
                        </div>
                        <div class="text-end">
                            <p class="mb-1">${dataPoint.value}</p>
                            <small class="text-muted">${dataPoint.date}</small>
                        </div>
                    </div>
                `;
                container.appendChild(dataPointElement);
            });
        }

        // Update key metrics display
        function updateKeyMetrics() {
            // Calculate total sales
            const totalSales = dashboardData.sales.reduce((sum, item) => sum + item.value, 0);
            document.getElementById('total-sales').textContent = `$${totalSales.toLocaleString()}`;

            // Calculate new users
            const newUsers = dashboardData.users.reduce((sum, item) => sum + item.value, 0);
            document.getElementById('new-users').textContent = newUsers.toLocaleString();

            // Calculate total revenue (assuming revenue is in the same units as sales for this example)
            const totalRevenue = dashboardData.revenue.reduce((sum, item) => sum + item.value, 0);
            document.getElementById('total-revenue').textContent = `$${totalRevenue.toLocaleString()}`;

            // Update data points count
            document.getElementById('data-points-count').textContent = dashboardData.allDataPoints.length.toLocaleString();
        }

        // Refresh dashboard
        function refreshDashboard() {
            // In a real application, this would fetch fresh data from a server
            updateCharts();
            updateRecentDataPoints();
            updateKeyMetrics();
            showAlert('Dashboard refreshed with latest data.', 'info');
        }

        // Simulate real-time data updates
        function simulateRealTimeData() {
            // Generate random data for simulation
            const categories = ['sales', 'users', 'revenue'];
            const randomCategory = categories[Math.floor(Math.random() * categories.length)];
            const randomValue = Math.floor(Math.random() * 1000) + 100;
            const today = new Date().toISOString().split('T')[0];

            // Add simulated data point
            addDataPoint(randomCategory, today, randomValue, `Simulated ${randomCategory} data`);

            // Update charts
            updateCharts();

            // Show notification
            showAlert(`New ${randomCategory} data point added (simulated)`, 'info');
        }

        // Update current time display
        function updateCurrentTime() {
            const now = new Date();
            const timeString = now.toLocaleTimeString();
            const dateString = now.toLocaleDateString();
            document.getElementById('current-time').textContent = `${dateString} ${timeString}`;
        }

        // Show alert modal
        function showAlert(message, type = 'info') {
            const modal = new bootstrap.Modal(document.getElementById('alertModal'));
            const modalBody = document.getElementById('alertModalBody');

            // Set alert type and message
            modalBody.innerHTML = `
                <div class="alert alert-${type}" role="alert">
                    ${message}
                </div>
            `;

            // Show modal
            modal.show();

            // Auto-close after 3 seconds
            setTimeout(() => {
                modal.hide();
            }, 3000);
        }
    </script>
</body>
</html>
```

## Key Features of This Dashboard:

1. **Real-Time Data Visualization**:
   - Interactive charts using Chart.js
   - Automatic updates when new data is added
   - Simulated real-time data updates

2. **Form Handling**:
   - Form validation
   - Data submission handling
   - Success/error notifications

3. **Responsive Design**:
   - Works on different screen sizes
   - Bootstrap 5 for responsive components

4. **Interactive Elements**:
   - Refresh button to update data
   - Current time display
   - Alert notifications

5. **Data Management**:
   - Categorized data storage
   - Recent data points display
   - Key metrics calculation

To use this dashboard, simply copy the entire code into an HTML file and open it in a browser. You can then:
- Add new data points using the form
- View the data in charts
- See recent data points
- Monitor key metrics
- Refresh the dashboard to get latest data

For a production environment, you would want to connect this to a backend API for persistent data storage and more robust data handling.

