// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const userGrowthChart = initUserGrowthChart();
    const dataDistributionChart = initDataDistributionChart();

    // Initialize data
    let dashboardData = {
        totalUsers: 0,
        activeSessions: 0,
        dataPoints: 0,
        userGrowthData: [],
        dataDistribution: {
            labels: ['Users', 'Transactions', 'Sensors'],
            values: [0, 0, 0]
        },
        submissions: []
    };

    // Load saved data from localStorage if available
    if (localStorage.getItem('dashboardData')) {
        dashboardData = JSON.parse(localStorage.getItem('dashboardData'));
        updateDashboard(dashboardData);
    }

    // Set up navigation
    setupNavigation();

    // Set up form submission
    setupDataForm(dashboardData);

    // Set up report generation
    setupReportGeneration();

    // Set up settings form
    setupSettingsForm();

    // Simulate real-time data updates
    setInterval(() => {
        simulateDataUpdates(dashboardData);
        updateDashboard(dashboardData);
    }, 10000); // Update every 10 seconds
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Initialize User Growth Chart
function initUserGrowthChart() {
    const ctx = document.getElementById('userGrowthChart').getContext('2d');
    return new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'User Growth',
                data: [],
                backgroundColor: 'rgba(52, 152, 219, 0.2)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: true
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Initialize Data Distribution Chart
function initDataDistributionChart() {
    const ctx = document.getElementById('dataDistributionChart').getContext('2d');
    return new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: ['Users', 'Transactions', 'Sensors'],
            datasets: [{
                data: [0, 0, 0],
                backgroundColor: [
                    'rgba(52, 152, 219, 0.7)',
                    'rgba(46, 204, 113, 0.7)',
                    'rgba(231, 76, 60, 0.7)'
                ],
                borderColor: [
                    'rgba(52, 152, 219, 1)',
                    'rgba(46, 204, 113, 1)',
                    'rgba(231, 76, 60, 1)'
                ],
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            plugins: {
                legend: {
                    position: 'right',
                }
            }
        }
    });
}

// Update all dashboard elements
function updateDashboard(data) {
    // Update stats cards
    document.getElementById('total-users').textContent = data.totalUsers;
    document.getElementById('active-sessions').textContent = data.activeSessions;
    document.getElementById('data-points').textContent = data.dataPoints;

    // Update charts
    updateUserGrowthChart(data.userGrowthData);
    updateDataDistributionChart(data.dataDistribution);

    // Update submissions table
    updateSubmissionsTable(data.submissions);

    // Save data to localStorage
    localStorage.setItem('dashboardData', JSON.stringify(data));
}

// Update User Growth Chart
function updateUserGrowthChart(data) {
    const chart = Chart.getChart('userGrowthChart');
    if (chart) {
        chart.data.labels = data.map(item => item.date);
        chart.data.datasets[0].data = data.map(item => item.value);
        chart.update();
    }
}

// Update Data Distribution Chart
function updateDataDistributionChart(data) {
    const chart = Chart.getChart('dataDistributionChart');
    if (chart) {
        chart.data.labels = data.labels;
        chart.data.datasets[0].data = data.values;
        chart.update();
    }
}

// Update submissions table
function updateSubmissionsTable(submissions) {
    const tableBody = document.querySelector('#submissions-table tbody');
    tableBody.innerHTML = '';

    // Show most recent submissions first
    const recentSubmissions = [...submissions].reverse().slice(0, 5);

    recentSubmissions.forEach(submission => {
        const row = document.createElement('tr');

        const typeCell = document.createElement('td');
        typeCell.textContent = submission.type;
        row.appendChild(typeCell);

        const valueCell = document.createElement('td');
        valueCell.textContent = submission.value;
        row.appendChild(valueCell);

        const timestampCell = document.createElement('td');
        timestampCell.textContent = new Date(submission.timestamp).toLocaleString();
        row.appendChild(timestampCell);

        const descriptionCell = document.createElement('td');
        descriptionCell.textContent = submission.description || '-';
        row.appendChild(descriptionCell);

        tableBody.appendChild(row);
    });
}

// Set up navigation between sections
function setupNavigation() {
    const navLinks = document.querySelectorAll('.sidebar-nav a');
    const sections = document.querySelectorAll('.dashboard-section');

    navLinks.forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();

            // Remove active class from all links and sections
            navLinks.forEach(l => l.classList.remove('active'));
            sections.forEach(s => s.classList.remove('active'));

            // Add active class to clicked link and corresponding section
            this.classList.add('active');
            const sectionId = this.getAttribute('data-section');
            document.getElementById(sectionId).classList.add('active');
        });
    });
}

// Set up data form submission
function setupDataForm(data) {
    const form = document.getElementById('data-form');

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const type = document.getElementById('data-type').value;
        const value = parseFloat(document.getElementById('data-value').value);
        const timestamp = document.getElementById('data-timestamp').value;
        const description = document.getElementById('data-description').value;

        // Create new submission
        const newSubmission = {
            type,
            value,
            timestamp: new Date(timestamp).toISOString(),
            description
        };

        // Add to submissions array
        data.submissions.push(newSubmission);

        // Update dashboard data
        data.dataPoints += 1;

        // Update specific data based on type
        switch(type) {
            case 'user':
                data.totalUsers += value;
                break;
            case 'transaction':
                data.activeSessions += value;
                break;
            case 'sensor':
                // For sensor data, we'll just add to data points
                break;
        }

        // Update user growth data (simplified example)
        const today = new Date().toISOString().split('T')[0];
        const existingEntry = data.userGrowthData.find(entry => entry.date === today);

        if (existingEntry) {
            existingEntry.value += value;
        } else {
            data.userGrowthData.push({
                date: today,
                value: value
            });
        }

        // Update data distribution
        const index = data.dataDistribution.labels.indexOf(
            type.charAt(0).toUpperCase() + type.slice(1) + 's'
        );
        if (index !== -1) {
            data.dataDistribution.values[index] += value;
        }

        // Update dashboard
        updateDashboard(data);

        // Reset form
        form.reset();

        // Show success message
        alert('Data submitted successfully!');
    });
}

// Set up report generation
function setupReportGeneration() {
    const generateBtn = document.getElementById('generate-report');
    const reportContent = document.getElementById('report-content');

    generateBtn.addEventListener('click', function() {
        const reportType = document.getElementById('report-type').value;
        const reportDate = document.getElementById('report-date').value;

        // In a real application, this would fetch data from a server
        // For this example, we'll generate a mock report

        let reportHTML = `<h4>${reportType.charAt(0).toUpperCase() + reportType.slice(1)} Report</h4>`;
        reportHTML += `<p><strong>Date:</strong> ${reportDate || 'All time'}</p>`;

        // Generate mock report content
        reportHTML += `
            <div class="report-stats">
                <div class="report-stat">
                    <h5>Total Users</h5>
                    <p>${Math.floor(Math.random() * 1000) + 500}</p>
                </div>
                <div class="report-stat">
                    <h5>Active Sessions</h5>
                    <p>${Math.floor(Math.random() * 500) + 200}</p>
                </div>
                <div class="report-stat">
                    <h5>Data Points</h5>
                    <p>${Math.floor(Math.random() * 2000) + 1000}</p>
                </div>
            </div>
            <div class="report-summary">
                <h5>Summary</h5>
                <p>This report provides an overview of system performance during the selected period.
                The data shows steady growth in user engagement and data collection activities.</p>
            </div>
        `;

        reportContent.innerHTML = reportHTML;
    });
}

// Set up settings form
function setupSettingsForm() {
    const form = document.getElementById('settings-form');

    // Load saved settings
    if (localStorage.getItem('dashboardSettings')) {
        const settings = JSON.parse(localStorage.getItem('dashboardSettings'));
        document.getElementById('refresh-rate').value = settings.refreshRate || 10;
        document.getElementById('theme').value = settings.theme || 'light';
        document.getElementById('notifications').checked = settings.notifications !== false;

        // Apply theme
        if (settings.theme === 'dark') {
            document.body.classList.add('dark-theme');
        }
    }

    form.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get settings values
        const refreshRate = parseInt(document.getElementById('refresh-rate').value);
        const theme = document.getElementById('theme').value;
        const notifications = document.getElementById('notifications').checked;

        // Save settings
        const settings = {
            refreshRate,
            theme,
            notifications
        };

        localStorage.setItem('dashboardSettings', JSON.stringify(settings));

        // Apply theme
        if (theme === 'dark') {
            document.body.classList.add('dark-theme');
        } else {
            document.body.classList.remove('dark-theme');
        }

        // Show success message
        alert('Settings saved successfully!');
    });
}

// Simulate real-time data updates
function simulateDataUpdates(data) {
    // Simulate random data changes
    const randomChange = Math.floor(Math.random() * 10) + 1;
    const changeType = Math.random();

    if (changeType < 0.3) {
        data.totalUsers += randomChange;
    } else if (changeType < 0.6) {
        data.activeSessions += randomChange;
    } else {
        data.dataPoints += randomChange;
    }

    // Update user growth data
    const today = new Date().toISOString().split('T')[0];
    const existingEntry = data.userGrowthData.find(entry => entry.date === today);

    if (existingEntry) {
        existingEntry.value += randomChange;
    } else {
        data.userGrowthData.push({
            date: today,
            value: randomChange
        });
    }

    // Update data distribution
    const distributionIndex = Math.floor(Math.random() * 3);
    data.dataDistribution.values[distributionIndex] += randomChange;
}
