            mainChart.data.labels.push(formattedTime);
            mainChart.data.datasets[datasetIndex].data.push(dataValue);
            mainChart.update();

            // Update stats cards
            updateStatsCards(dataType, dataValue);

            // Add to activity log
            addToActivityLog(dataType, dataValue, dataTimestamp);

            // Reset form
            dataForm.reset();
        }
    });

    // Simulate real-time data (for demonstration)
    setInterval(() => {
        const randomType = ['sales', 'traffic', 'inventory'][Math.floor(Math.random() * 3)];
        const randomValue = Math.floor(Math.random() * 100) + 1;
        const now = new Date();

        const formattedTime = now.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
        const datasetIndex = getDatasetIndex(randomType);

        if (datasetIndex !== -1) {
            // Update chart data
            mainChart.data.labels.push(formattedTime);
            mainChart.data.datasets[datasetIndex].data.push(randomValue);

            // Limit the number of data points to keep the chart readable
            if (mainChart.data.labels.length > 10) {
                mainChart.data.labels.shift();
                mainChart.data.datasets.forEach(dataset => {
                    dataset.data.shift();
                });
            }

            mainChart.update();

            // Update stats cards
            updateStatsCards(randomType, randomValue);

            // Add to activity log
            addToActivityLog(randomType, randomValue, now);
        }
    }, 5000); // Update every 5 seconds
});

// Helper functions
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    });
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
}

function getDatasetIndex(dataType) {
    const typeMap = {
        'sales': 0,
        'traffic': 1,
        'inventory': 2
    };
    return typeMap[dataType] !== undefined ? typeMap[dataType] : -1;
}

function updateStatsCards(dataType, value) {
    switch(dataType) {
        case 'sales':
            const currentSales = parseFloat(document.getElementById('total-sales').textContent.replace('$', ''));
            document.getElementById('total-sales').textContent = `$${(currentSales + value).toFixed(2)}`;
            break;
        case 'traffic':
            const currentUsers = parseInt(document.getElementById('active-users').textContent);
            document.getElementById('active-users').textContent = currentUsers + value;
            break;
        case 'inventory':
            const currentInventory = parseInt(document.getElementById('inventory-level').textContent);
            document.getElementById('inventory-level').textContent = currentInventory + value;
            break;
    }
}

function addToActivityLog(dataType, value, timestamp) {
    const activityLog = document.getElementById('activity-log');
    const newItem = document.createElement('li');

    const formattedTime = timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
    const formattedDate = timestamp.toLocaleDateString();

    newItem.innerHTML = `
        <strong>${formattedTime}</strong> - ${formattedDate}: Added ${value} to ${dataType}
    `;

    // Add new item at the top
    if (activityLog.firstChild) {
        activityLog.insertBefore(newItem, activityLog.firstChild);
    } else {
        activityLog.appendChild(newItem);
    }

    // Limit to 10 items
    if (activityLog.children.length > 10) {
        activityLog.removeChild(activityLog.lastChild);
    }
}
