## JavaScript (script.js)

```javascript
// Dashboard Data Management
class Dashboard {
    constructor() {
        this.data = [];
        this.charts = {};
        this.init();
    }

    init() {
        // Initialize form handling
        this.initForm();

        // Initialize charts
        this.initCharts();

        // Update current date/time
        this.updateDateTime();
        setInterval(() => this.updateDateTime(), 1000);

        // Load sample data
        this.loadSampleData();
    }

    initForm() {
        const form = document.getElementById('dataForm');

        form.addEventListener('submit', (e) => {
            e.preventDefault();

            const formData = new FormData(form);
            const newData = {
                type: formData.get('dataType'),
                value: parseFloat(formData.get('value')),
                timestamp: new Date(formData.get('timestamp')),
                notes: formData.get('notes') || ''
            };

            this.addData(newData);
            form.reset();
        });
    }

    initCharts() {
        const ctx = document.getElementById('mainChart').getContext('2d');

        this.charts.mainChart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: []
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                plugins: {
                    title: {
                        display: true,
                        text: 'Real-Time Data Visualization',
                        font: {
                            size: 16
                        }
                    },
                    legend: {
                        position: 'top',
                    }
                }
            }
        });
    }

    updateDateTime() {
        const now = new Date();
        const options = {
            weekday: 'short',
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        };
        document.getElementById('currentDateTime').textContent = now.toLocaleDateString('en-US', options);
    }

    loadSampleData() {
        // Generate some sample data
        const types = ['sales', 'traffic', 'temperature'];
        const now = new Date();

        for (let i = 0; i < 10; i++) {
            const type = types[Math.floor(Math.random() * types.length)];
            const value = Math.random() * 1000;
            const timestamp = new Date(now.getTime() - (10 - i) * 3600000); // 1 hour intervals

            this.addData({
                type,
                value,
                timestamp,
                notes: `Sample data point ${i + 1}`
            }, false);
        }

        this.updateStats();
        this.updateCharts();
    }

    addData(data, updateStats = true) {
        this.data.push(data);

        // Update table
        this.updateTable();

        if (updateStats) {
            this.updateStats();
            this.updateCharts();
        }
    }

    updateTable() {
        const tableBody = document.querySelector('#dataTable tbody');
        tableBody.innerHTML = '';

        // Sort data by timestamp (newest first)
        const sortedData = [...this.data].sort((a, b) => b.timestamp - a.timestamp);

        // Only show last 10 entries
        const displayData = sortedData.slice(0, 10);

        displayData.forEach(item => {
            const row = document.createElement('tr');

            row.innerHTML = `
                <td>${item.type}</td>
                <td>${item.value.toFixed(2)}</td>
                <td>${item.timestamp.toLocaleString()}</td>
                <td>${item.notes}</td>
            `;

            tableBody.appendChild(row);
        });
    }

    updateStats() {
        if (this.data.length === 0) return;

        const totalRecords = this.data.length;
        const sum = this.data.reduce((acc, item) => acc + item.value, 0);
        const average = sum / totalRecords;
        const lastUpdate = this.data[this.data.length - 1].timestamp;

        document.getElementById('totalRecords').textContent = totalRecords;
        document.getElementById('averageValue').textContent = average.toFixed(2);
        document.getElementById('lastUpdate').textContent = lastUpdate.toLocaleString();
    }

    updateCharts() {
        if (this.data.length === 0) return;

        // Group data by type
        const groupedData = {};
        this.data.forEach(item => {
            if (!groupedData[item.type]) {
                groupedData[item.type] = {
                    label: item.type,
                    data: [],
                    timestamps: [],
                    borderColor: this.getColorForType(item.type),
                    backgroundColor: this.getColorForType(item.type, 0.2),
                    tension: 0.1,
                    fill: true
                };
            }
            groupedData[item.type].data.push(item.value);
            groupedData[item.type].timestamps.push(item.timestamp);
        });

        // Prepare chart data
        const chartData = {
            labels: this.data.map(item => item.timestamp.toLocaleTimeString()),
            datasets: Object.values(groupedData)
        };

        // Update chart
        this.charts.mainChart.data = chartData;
        this.charts.mainChart.update();
    }

    getColorForType(type, alpha = 1) {
        const colors = {
            'sales': `rgba(52, 152, 219, ${alpha})`,
            'traffic': `rgba(46, 204, 113, ${alpha})`,
            'temperature': `rgba(243, 156, 18, ${alpha})`
        };
        return colors[type] || `rgba(155, 89, 182, ${alpha})`;
    }
}

// Initialize the dashboard when the page loads
document.addEventListener('DOMContentLoaded', () => {
    new Dashboard();
});
