    });

    // Initial data load
    updateDashboard(mainChart);

    // Simulate real-time updates
    setInterval(() => {
        updateRealTimeData(mainChart);
    }, 5000);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Update dashboard with new data
function updateDashboard(chart) {
    const dataSource = document.getElementById('data-source').value;
    const timeRange = document.getElementById('time-range').value;
    const threshold = parseInt(document.getElementById('threshold').value);

    // Simulate API call to get data
    fetchData(dataSource, timeRange).then(data => {
        // Update chart
        chart.data.labels = data.labels;
        chart.data.datasets[0].data = data.values;
        chart.data.datasets[0].label = data.label;
        chart.update();

        // Update stats
        document.getElementById('total-sales').textContent = data.stats.totalSales || '$0.00';
        document.getElementById('active-users').textContent = data.stats.activeUsers || '0';
        document.getElementById('conversion-rate').textContent = data.stats.conversionRate || '0%';

        // Check for alerts
        checkAlerts(data.values, threshold);
    });
}

// Simulate real-time data updates
function updateRealTimeData(chart) {
    const dataSource = document.getElementById('data-source').value;
    const threshold = parseInt(document.getElementById('threshold').value);

    // Simulate API call for real-time update
    fetchRealTimeData(dataSource).then(newData => {
        // Update chart with new data point
        if (chart.data.labels.length > 0) {
            chart.data.labels.push(newData.label);
            chart.data.datasets[0].data.push(newData.value);

            // Keep only the last 20 data points
            if (chart.data.labels.length > 20) {
                chart.data.labels.shift();
                chart.data.datasets[0].data.shift();
            }

            chart.update();
        }

        // Check for alerts
        checkAlerts([newData.value], threshold);
    });
}

// Simulate API call to fetch data
function fetchData(dataSource, timeRange) {
    return new Promise((resolve) => {
        setTimeout(() => {
            // Generate mock data based on parameters
            let labels = [];
            let values = [];
            let label = '';
            let stats = {};

            switch(dataSource) {
                case 'sales':
                    label = 'Sales ($)';
                    stats = {
                        totalSales: '$12,450.00',
                        activeUsers: '1,234',
                        conversionRate: '4.2%'
                    };
                    break;
                case 'traffic':
                    label = 'Visitors';
                    stats = {
                        totalSales: '$8,765.00',
                        activeUsers: '3,456',
                        conversionRate: '2.8%'
                    };
                    break;
                case 'inventory':
                    label = 'Items in Stock';
                    stats = {
                        totalSales: '$5,678.00',
                        activeUsers: '890',
                        conversionRate: '1.5%'
                    };
                    break;
            }

            // Generate time labels based on range
            const now = new Date();
            const count = timeRange === 'daily' ? 24 : timeRange === 'weekly' ? 7 : 30;

            for (let i = count - 1; i >= 0; i--) {
                const date = new Date(now);
                if (timeRange === 'daily') {
                    date.setHours(now.getHours() - i);
                    labels.push(date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
                } else {
                    date.setDate(now.getDate() - i);
                    labels.push(date.toLocaleDateString());
                }

                // Generate random values
                values.push(Math.floor(Math.random() * 100) + 1);
            }

            resolve({ labels, values, label, stats });
        }, 500);
    });
}

// Simulate API call for real-time data
function fetchRealTimeData(dataSource) {
    return new Promise((resolve) => {
        setTimeout(() => {
            const now = new Date();
            const label = now.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
            const value = Math.floor(Math.random() * 100) + 1;

            resolve({ label, value });
        }, 300);
    });
}

// Check for alerts based on threshold
function checkAlerts(values, threshold) {
    const alertsContainer = document.getElementById('alerts-container');
    alertsContainer.innerHTML = '';

    values.forEach((value, index) => {
        if (value > threshold) {
            const alertElement = document.createElement('div');
            alertElement.className = 'alert-item warning';
            alertElement.textContent = `Alert: Value ${value} exceeds threshold of ${threshold} at point ${index + 1}`;
            alertsContainer.appendChild(alertElement);
        }
    });

    if (alertsContainer.children.length === 0) {
        alertsContainer.innerHTML = '<p>No alerts at this time.</p>';
    }
}
