```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize time display
    updateTime();
    setInterval(updateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    let chartType = 'line';
    let isRealtime = true;

    // Sample data
    let chartData = {
        labels: [],
        datasets: [
            {
                label: 'Sales',
                data: [],
                borderColor: 'rgba(52, 152, 219, 1)',
                backgroundColor: 'rgba(52, 152, 219, 0.2)',
                borderWidth: 2,
                fill: true,
                tension: 0.4
            },
            {
                label: 'Revenue',
                data: [],
                borderColor: 'rgba(46, 204, 113, 1)',
                backgroundColor: 'rgba(46, 204, 113, 0.2)',
                borderWidth: 2,
                fill: true,
                tension: 0.4
            },
            {
                label: 'Users',
                data: [],
                borderColor: 'rgba(241, 196, 15, 1)',
                backgroundColor: 'rgba(241, 196, 15, 0.2)',
                borderWidth: 2,
                fill: true,
                tension: 0.4
            }
        ]
    };

    // Create chart
    let realtimeChart = new Chart(ctx, {
        type: chartType,
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            animation: {
                duration: 0
            }
        }
    });

    // Generate initial data
    generateInitialData();

    // Set up real-time updates
    let updateInterval = setInterval(updateChartData, 2000);

    // Toggle real-time updates
    document.getElementById('toggle-realtime').addEventListener('click', function() {
        isRealtime = !isRealtime;
        this.textContent = isRealtime ? 'Pause' : 'Resume';

        if (isRealtime) {
            updateInterval = setInterval(updateChartData, 2000);
        } else {
            clearInterval(updateInterval);
        }
    });

    // Change chart type
    document.getElementById('chart-type').addEventListener('change', function() {
        chartType = this.value;
        realtimeChart.destroy();
        realtimeChart = new Chart(ctx, {
            type: chartType,
            data: chartData,
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                animation: {
                    duration: 0
                }
            }
        });
    });

    // Form submission handling
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const formStatus = document.getElementById('form-status');
        const name = document.getElementById('data-name').value;
        const value = parseFloat(document.getElementById('data-value').value);
        const category = document.getElementById('data-category').value;

        // Simulate API call
        setTimeout(() => {
            // In a real app, you would send this to a backend API
            console.log('Data submitted:', { name, value, category });

            // Update chart with new data
            const timestamp = new Date().toLocaleTimeString();
            chartData.labels.push(timestamp);

            // Update the appropriate dataset based on category
            const datasetIndex = chartData.datasets.findIndex(ds => ds.label.toLowerCase() === category);
            if (datasetIndex !== -1) {
                chartData.datasets[datasetIndex].data.push(value);
            }

            // Keep only the last 20 data points
            if (chartData.labels.length > 20) {
                chartData.labels.shift();
                chartData.datasets.forEach(ds => {
                    ds.data.shift();
                });
            }

            realtimeChart.update();

            // Show success message
            formStatus.textContent = 'Data submitted successfully!';
            formStatus.className = 'form-status success';

            // Reset form
            this.reset();

            // Hide message after 3 seconds
            setTimeout(() => {
                formStatus.style.display = 'none';
            }, 3000);
        }, 500);
    });

    // Helper functions
    function updateTime() {
        const now = new Date();
        document.getElementById('current-time').textContent = now.toLocaleTimeString();
    }

    function generateInitialData() {
        const now = new Date();
        const hours = 20;

        for (let i = hours; i >= 0; i--) {
            const time = new Date(now - i * 60 * 60 * 1000).toLocaleTimeString();
            chartData.labels.push(time);

            chartData.datasets[0].data.push(Math.floor(Math.random() * 100) + 10);
            chartData.datasets[1].data.push(Math.floor(Math.random() * 500) + 50);
            chartData.datasets[2].data.push(Math.floor(Math.random() * 200) + 20);
        }

        realtimeChart.update();
    }

    function updateChartData() {
        if (!isRealtime) return;

        const timestamp = new Date().toLocaleTimeString();
        chartData.labels.push(timestamp);

        // Update each dataset with new random data
        chartData.datasets.forEach(ds => {
            const lastValue = ds.data[ds.data.length - 1] || 0;
            const newValue = lastValue + (Math.random() * 20 - 10); // Small random change
            ds.data.push(Math.max(0, newValue)); // Ensure no negative values
        });

        // Keep only the last 20 data points
        if (chartData.labels.length > 20) {
            chartData.labels.shift();
            chartData.datasets.forEach(ds => {
                ds.data.shift();
            });
        }

        realtimeChart.update();
    }
});
