```javascript
// Initialize charts
let salesChart, trafficChart;

// Sample data
let salesData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [{
        label: 'Sales',
        data: [1200, 1900, 3000, 5000, 2000, 3000],
        backgroundColor: 'rgba(52, 152, 219, 0.2)',
        borderColor: 'rgba(52, 152, 219, 1)',
        borderWidth: 2,
        tension: 0.3
    }]
};

let trafficData = {
    labels: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'],
    datasets: [{
        label: 'Visitors',
        data: [1500, 2200, 1800, 2400, 2100, 2700, 3000],
        backgroundColor: 'rgba(46, 204, 113, 0.2)',
        borderColor: 'rgba(46, 204, 113, 1)',
        borderWidth: 2,
        tension: 0.3
    }]
};

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    initCharts();

    // Set up form submission
    const form = document.getElementById('data-form');
    form.addEventListener('submit', handleFormSubmit);

    // Load initial data
    loadInitialData();
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const options = {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    };

    document.getElementById('current-date').textContent = now.toLocaleDateString('en-US', options);
    document.getElementById('current-time').textContent = now.toLocaleTimeString('en-US');
}

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('sales-chart').getContext('2d');
    const trafficCtx = document.getElementById('traffic-chart').getContext('2d');

    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: salesData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    trafficChart = new Chart(trafficCtx, {
        type: 'line',
        data: trafficData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Handle form submission
function handleFormSubmit(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const category = document.getElementById('data-category').value;

    // Add data to the appropriate chart
    updateChartData(category, label, value);

    // Add to data table
    addToDataTable(label, value, category);

    // Reset form
    e.target.reset();
}

// Update chart data based on category
function updateChartData(category, label, value) {
    if (category === 'sales') {
        // Update sales chart
        salesData.labels.push(label);
        salesData.datasets[0].data.push(value);
        salesChart.update();
    } else if (category === 'traffic') {
        // Update traffic chart
        trafficData.labels.push(label);
        trafficData.datasets[0].data.push(value);
        trafficChart.update();
    }
    // Conversions would go to a different chart if we had one
}

// Add data to the table
function addToDataTable(label, value, category) {
    const tableBody = document.querySelector('#data-table tbody');
    const newRow = document.createElement('tr');

    const timestamp = new Date().toLocaleString();

    newRow.innerHTML = `
        <td>${label}</td>
        <td>${value}</td>
        <td>${category.charAt(0).toUpperCase() + category.slice(1)}</td>
        <td>${timestamp}</td>
    `;

    tableBody.prepend(newRow);

    // Limit table rows to 10
    if (tableBody.children.length > 10) {
        tableBody.removeChild(tableBody.lastChild);
    }
}

// Load initial data
function loadInitialData() {
    // This would typically come from an API in a real application
    const initialData = [
        { label: 'Q1', value: 1200, category: 'sales' },
        { label: 'Q2', value: 1900, category: 'sales' },
        { label: 'Q3', value: 3000, category: 'sales' },
        { label: 'Q4', value: 5000, category: 'sales' },
        { label: 'Mon', value: 1500, category: 'traffic' },
        { label: 'Tue', value: 2200, category: 'traffic' },
        { label: 'Wed', value: 1800, category: 'traffic' }
    ];

    initialData.forEach(item => {
        updateChartData(item.category, item.label, item.value);
        addToDataTable(item.label, item.value, item.category);
    });
}
