## JavaScript Functionality (script.js)

```javascript
// Dashboard Data
let dashboardData = {
    sales: [],
    users: [],
    revenue: [],
    settings: {
        refreshRate: 5,
        theme: 'light'
    }
};

// DOM Elements
const currentDateElement = document.getElementById('current-date');
const currentTimeElement = document.getElementById('current-time');
const mainChartCanvas = document.getElementById('main-chart');
const reportChartCanvas = document.getElementById('report-chart');
const dataForm = document.getElementById('data-form');
const settingsForm = document.getElementById('settings-form');
const totalSalesElement = document.getElementById('total-sales');
const activeUsersElement = document.getElementById('active-users');
const totalRevenueElement = document.getElementById('total-revenue');

// Initialize Charts
let mainChart, reportChart;

// Initialize the dashboard
function initDashboard() {
    // Set current date and time
    updateDateTime();

    // Initialize charts
    initCharts();

    // Set up event listeners
    setupEventListeners();

    // Load initial data
    loadInitialData();

    // Start data refresh interval
    startDataRefresh();
}

// Update date and time display
function updateDateTime() {
    const now = new Date();
    currentDateElement.textContent = now.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    });
    currentTimeElement.textContent = now.toLocaleTimeString('en-US');

    // Update every second
    setTimeout(updateDateTime, 1000);
}

// Initialize charts
function initCharts() {
    // Main chart configuration
    const mainChartConfig = {
        type: 'line',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Sales',
                    data: [],
                    borderColor: '#3498db',
                    backgroundColor: 'rgba(52, 152, 219, 0.2)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Users',
                    data: [],
                    borderColor: '#2ecc71',
                    backgroundColor: 'rgba(46, 204, 113, 0.2)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Revenue',
                    data: [],
                    borderColor: '#e74c3c',
                    backgroundColor: 'rgba(231, 76, 60, 0.2)',
                    tension: 0.3,
                    fill: true
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    };

    // Report chart configuration
    const reportChartConfig = {
        type: 'bar',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Sales',
                    data: [],
                    backgroundColor: 'rgba(52, 152, 219, 0.7)'
                },
                {
                    label: 'Users',
                    data: [],
                    backgroundColor: 'rgba(46, 204, 113, 0.7)'
                },
                {
                    label: 'Revenue',
                    data: [],
                    backgroundColor: 'rgba(231, 76, 60, 0.7)'
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    };

    // Create charts
    mainChart = new Chart(mainChartCanvas, mainChartConfig);
    reportChart = new Chart(reportChartCanvas, reportChartConfig);
}

// Set up event listeners
function setupEventListeners() {
    // Tab navigation
    document.querySelectorAll('.main-nav a').forEach(link => {
        link.addEventListener('click', function(e) {
            e.preventDefault();
            const tabId = this.getAttribute('data-tab');

            // Update active tab
            document.querySelectorAll('.main-nav li').forEach(li => {
                li.classList.remove('active');
            });
            this.parentElement.classList.add('active');

            // Show selected tab content
            document.querySelectorAll('.tab-content').forEach(tab => {
                tab.classList.remove('active');
            });
            document.getElementById(tabId).classList.add('active');

            // Update report chart if reports tab is selected
            if (tabId === 'reports') {
                updateReportChart();
            }
        });
    });

    // Data form submission
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();
        addNewData();
    });

    // Settings form submission
    settingsForm.addEventListener('submit', function(e) {
        e.preventDefault();
        saveSettings();
    });

    // Generate report button
    document.querySelector('.btn-generate').addEventListener('click', function() {
        updateReportChart();
    });
}

// Load initial data
function loadInitialData() {
    // Simulate loading data from an API
    setTimeout(() => {
        // Generate some sample data
        const now = new Date();
        const labels = [];
        const salesData = [];
        const usersData = [];
        const revenueData = [];

        for (let i = 6; i >= 0; i--) {
            const date = new Date(now);
            date.setDate(now.getDate() - i);
            labels.push(date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }));

            // Generate random data
            salesData.push(Math.floor(Math.random() * 1000) + 100);
            usersData.push(Math.floor(Math.random() * 500) + 50);
            revenueData.push(Math.floor(Math.random() * 5000) + 1000);
        }

        // Update dashboard data
        dashboardData.sales = salesData;
        dashboardData.users = usersData;
        dashboardData.revenue = revenueData;

        // Update charts
        updateMainChart(labels, salesData, usersData, revenueData);

        // Update stats cards
        updateStatsCards();
    }, 1000);
}

// Add new data from form
function addNewData() {
    const labelInput = document.getElementById('data-label');
    const valueInput = document.getElementById('data-value');
    const categorySelect = document.getElementById('data-category');

    const label = labelInput.value.trim();
    const value = parseFloat(valueInput.value);
    const category = categorySelect.value;

    if (label && !isNaN(value)) {
        // Add to dashboard data
        dashboardData[category].push(value);

        // Update charts
        const labels = mainChart.data.labels;
        labels.push(label);
        if (labels.length > 7) {
            labels.shift();
            dashboardData.sales.shift();
            dashboardData.users.shift();
            dashboardData.revenue.shift();
        }

        updateMainChart(labels, dashboardData.sales, dashboardData.users, dashboardData.revenue);

        // Update stats cards
        updateStatsCards();

        // Reset form
        labelInput.value = '';
        valueInput.value = '';
    }
}

// Update main chart
function updateMainChart(labels, salesData, usersData, revenueData) {
    mainChart.data.labels = labels;
    mainChart.data.datasets[0].data = salesData;
    mainChart.data.datasets[1].data = usersData;
    mainChart.data.datasets[2].data = revenueData;
    mainChart.update();
}

// Update stats cards
function updateStatsCards() {
    if (dashboardData.sales.length > 0) {
        totalSalesElement.textContent = `$${dashboardData.sales[dashboardData.sales.length - 1]}`;
    }

    if (dashboardData.users.length > 0) {
        activeUsersElement.textContent = dashboardData.users[dashboardData.users.length - 1];
    }

    if (dashboardData.revenue.length > 0) {
        totalRevenueElement.textContent = `$${dashboardData.revenue[dashboardData.revenue.length - 1]}`;
    }
}

// Update report chart based on selected period
function updateReportChart() {
    const periodSelect = document.getElementById('report-period');
    const period = periodSelect.value;

    // Simulate generating report data based on period
    const now = new Date();
    const labels = [];
    const salesData = [];
    const usersData = [];
    const revenueData = [];

    let days;
    switch (period) {
        case 'daily':
            days = 7;
            break;
        case 'weekly':
            days = 28;
            break;
        case 'monthly':
            days = 90;
            break;
        default:
            days = 7;
    }

    for (let i = days - 1; i >= 0; i--) {
        const date = new Date(now);
        date.setDate(now.getDate() - i);

        let label;
        if (period === 'daily') {
            label = date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        } else if (period === 'weekly') {
            label = `Week ${Math.ceil((date.getDate() + 1) / 7)}`;
        } else {
            label = date.toLocaleDateString('en-US', { month: 'short' });
        }

        labels.push(label);

        // Generate random data (in a real app, this would come from an API)
        salesData.push(Math.floor(Math.random() * 1000) + 100);
        usersData.push(Math.floor(Math.random() * 500) + 50);
        revenueData.push(Math.floor(Math.random() * 5000) + 1000);
    }

    // Update report chart
    reportChart.data.labels = labels;
    reportChart.data.datasets[0].data = salesData;
    reportChart.data.datasets[1].data = usersData;
    reportChart.data.datasets[2].data = revenueData;
    reportChart.update();
}

// Save settings
function saveSettings() {
    const refreshRateInput = document.getElementById('refresh-rate');
    const themeSelect = document.getElementById('theme');

    const refreshRate = parseInt(refreshRateInput.value);
    const theme = themeSelect.value;

    // Update settings
    dashboardData.settings.refreshRate = refreshRate;
    dashboardData.settings.theme = theme;

    // Apply theme
    document.body.className = theme === 'dark' ? 'dark-theme' : '';

    // Restart data refresh with new interval
    startDataRefresh();

    // Show confirmation
    alert('Settings saved successfully!');
}

// Start data refresh interval
function startDataRefresh() {
    // Clear any existing interval
    if (window.dataRefreshInterval) {
        clearInterval(window.dataRefreshInterval);
    }

    // Set new interval
    window.dataRefreshInterval = setInterval(() => {
        // Simulate fetching new data
        const newSales = Math.floor(Math.random() * 1000) + 100;
        const newUsers = Math.floor(Math.random() * 500) + 50;
        const newRevenue = Math.floor(Math.random() * 5000) + 1000;

        // Update data
        dashboardData.sales.push(newSales);
        dashboardData.users.push(newUsers);
        dashboardData.revenue.push(newRevenue);

        // Keep only the last 7 data points
        if (dashboardData.sales.length > 7) {
            dashboardData.sales.shift();
            dashboardData.users.shift();
            dashboardData.revenue.shift();
        }

        // Update charts
        const labels = mainChart.data.labels;
        if (labels.length === 0) {
            // Initialize labels if empty
            const now = new Date();
            for (let i = 6; i >= 0; i--) {
                const date = new Date(now);
                date.setDate(now.getDate() - i);
                labels.push(date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }));
            }
        } else {
            // Rotate labels
            labels.push(labels.shift());
        }

        updateMainChart(labels, dashboardData.sales, dashboardData.users, dashboardData.revenue);

        // Update stats cards
        updateStatsCards();
    }, dashboardData.settings.refreshRate * 1000);
}

// Initialize the dashboard when the page loads
document.addEventListener('DOMContentLoaded', initDashboard);
```

