## JavaScript Functionality (script.js)

```javascript
// Sample data storage
let dashboardData = {
    sales: [],
    traffic: [],
    temperature: []
};

// Chart instance
let mainChart;

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Set current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    initChart();

    // Set up form submission
    document.getElementById('dataForm').addEventListener('submit', handleFormSubmit);

    // Set up refresh rate change
    document.getElementById('refreshRate').addEventListener('change', function() {
        const rate = parseInt(this.value);
        clearInterval(window.dataRefreshInterval);
        window.dataRefreshInterval = setInterval(updateDashboard, rate);
    });

    // Set up dark mode toggle
    document.getElementById('toggleDarkMode').addEventListener('click', toggleDarkMode);

    // Initial data load
    loadSampleData();
    updateDashboard();

    // Set initial refresh interval
    const initialRate = parseInt(document.getElementById('refreshRate').value);
    window.dataRefreshInterval = setInterval(updateDashboard, initialRate);
});

// Update current date and time display
function updateDateTime() {
    const now = new Date();
    document.getElementById('currentDateTime').textContent = now.toLocaleString();
}

// Initialize the main chart
function initChart() {
    const ctx = document.getElementById('mainChart').getContext('2d');
    mainChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Sales',
                    data: [],
                    borderColor: 'rgb(52, 152, 219)',
                    backgroundColor: 'rgba(52, 152, 219, 0.1)',
                    tension: 0.1,
                    fill: true
                },
                {
                    label: 'Website Traffic',
                    data: [],
                    borderColor: 'rgb(46, 204, 113)',
                    backgroundColor: 'rgba(46, 204, 113, 0.1)',
                    tension: 0.1,
                    fill: true
                },
                {
                    label: 'Temperature',
                    data: [],
                    borderColor: 'rgb(231, 76, 60)',
                    backgroundColor: 'rgba(231, 76, 60, 0.1)',
                    tension: 0.1,
                    fill: true
                }
            ]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                tooltip: {
                    mode: 'index',
                    intersect: false
                }
            }
        }
    });
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const data = {
        type: formData.get('dataType'),
        value: parseFloat(formData.get('value')),
        timestamp: new Date(formData.get('timestamp'))
    };

    // Add data to storage
    dashboardData[data.type].push(data);

    // Update dashboard
    updateDashboard();

    // Reset form
    form.reset();

    // Show success message (in a real app, you might want a more sophisticated notification)
    alert('Data added successfully!');
}

// Update all dashboard components
function updateDashboard() {
    updateChart();
    updateStats();
    updateDataTable();
    updateLastUpdated();
}

// Update the chart with current data
function updateChart() {
    // Prepare data for chart
    const allData = [...dashboardData.sales, ...dashboardData.traffic, ...dashboardData.temperature];
    const sortedData = allData.sort((a, b) => a.timestamp - b.timestamp);

    // Get unique timestamps for labels
    const uniqueTimestamps = [...new Set(sortedData.map(item => item.timestamp.toLocaleString()))];

    // Prepare datasets
    const salesData = [];
    const trafficData = [];
    const tempData = [];

    uniqueTimestamps.forEach(timestamp => {
        const salesPoint = sortedData.find(item =>
            item.type === 'sales' && item.timestamp.toLocaleString() === timestamp);
        const trafficPoint = sortedData.find(item =>
            item.type === 'traffic' && item.timestamp.toLocaleString() === timestamp);
        const tempPoint = sortedData.find(item =>
            item.type === 'temperature' && item.timestamp.toLocaleString() === timestamp);

        salesData.push(salesPoint ? salesPoint.value : null);
        trafficData.push(trafficPoint ? trafficPoint.value : null);
        tempData.push(tempPoint ? tempPoint.value : null);
    });

    // Update chart data
    mainChart.data.labels = uniqueTimestamps;
    mainChart.data.datasets[0].data = salesData;
    mainChart.data.datasets[1].data = trafficData;
    mainChart.data.datasets[2].data = tempData;

    mainChart.update();
}

// Update statistics cards
function updateStats() {
    const allData = [...dashboardData.sales, ...dashboardData.traffic, ...dashboardData.temperature];

    // Total data points
    document.getElementById('totalPoints').textContent = allData.length;

    // Average value
    if (allData.length > 0) {
        const sum = allData.reduce((acc, item) => acc + item.value, 0);
        const avg = sum / allData.length;
        document.getElementById('avgValue').textContent = avg.toFixed(2);
    } else {
        document.getElementById('avgValue').textContent = '0';
    }
}

// Update data table
function updateDataTable() {
    const tableBody = document.querySelector('#dataTable tbody');
    tableBody.innerHTML = '';

    // Combine and sort all data by timestamp (newest first)
    const allData = [...dashboardData.sales, ...dashboardData.traffic, ...dashboardData.temperature]
        .sort((a, b) => b.timestamp - a.timestamp)
        .slice(0, 10); // Show only the 10 most recent entries

    allData.forEach(item => {
        const row = document.createElement('tr');

        const typeCell = document.createElement('td');
        typeCell.textContent = item.type.charAt(0).toUpperCase() + item.type.slice(1);
        row.appendChild(typeCell);

        const valueCell = document.createElement('td');
        valueCell.textContent = item.value;
        row.appendChild(valueCell);

        const timeCell = document.createElement('td');
        timeCell.textContent = item.timestamp.toLocaleString();
        row.appendChild(timeCell);

        tableBody.appendChild(row);
    });
}

// Update last updated time
function updateLastUpdated() {
    const now = new Date();
    document.getElementById('lastUpdated').textContent = now.toLocaleString();
}

// Toggle dark mode
function toggleDarkMode() {
    document.body.classList.toggle('dark-mode');
}

// Load some sample data for demonstration
function loadSampleData() {
    const now = new Date();

    // Sales data
    for (let i = 0; i < 5; i++) {
        dashboardData.sales.push({
            type: 'sales',
            value: Math.floor(Math.random() * 100) + 50,
            timestamp: new Date(now.getTime() - (5 - i) * 24 * 60 * 60 * 1000)
        });
    }

    // Traffic data
    for (let i = 0; i < 5; i++) {
        dashboardData.traffic.push({
            type: 'traffic',
            value: Math.floor(Math.random() * 500) + 100,
            timestamp: new Date(now.getTime() - (5 - i) * 24 * 60 * 60 * 1000)
        });
    }

    // Temperature data
    for (let i = 0; i < 5; i++) {
        dashboardData.temperature.push({
            type: 'temperature',
            value: Math.floor(Math.random() * 20) + 10,
            timestamp: new Date(now.getTime() - (5 - i) * 24 * 60 * 60 * 1000)
        });
    }
}
