            borderColor: 'rgb(52, 152, 219)',
            backgroundColor: 'rgba(52, 152, 219, 0.2)',
            tension: 0.1,
            fill: true
        }]
    };

    // Create chart
    let realtimeChart = new Chart(ctx, {
        type: chartType,
        data: chartData,
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                title: {
                    display: true,
                    text: 'Real-Time Data Visualization'
                }
            }
        }
    });

    // Toggle chart type
    document.getElementById('toggleChart').addEventListener('click', function() {
        chartType = chartType === 'line' ? 'bar' : 'line';
        realtimeChart.destroy();
        realtimeChart = new Chart(ctx, {
            type: chartType,
            data: chartData,
            options: realtimeChart.options
        });
    });

    // Change data source
    document.getElementById('dataSource').addEventListener('change', function() {
        currentDataSource = this.value;
        updateChartData(realtimeChart, currentDataSource);
    });

    // Simulate real-time updates
    setInterval(function() {
        updateChartData(realtimeChart, currentDataSource);
    }, 5000);

    // Form submission
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const formData = {
            type: document.getElementById('dataType').value,
            value: parseFloat(document.getElementById('dataValue').value),
            timestamp: new Date(document.getElementById('dataTimestamp').value).toISOString(),
            notes: document.getElementById('dataNotes').value
        };

        // In a real application, you would send this to a server
        console.log('Form submitted:', formData);

        // Add to table
        addDataToTable(formData);

        // Reset form
        this.reset();

        // Show success message
        alert('Data submitted successfully!');
    });

    // Initialize with sample data
    initializeSampleData();
});

// Helper functions
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

function generateTimeLabels(count) {
    const labels = [];
    const now = new Date();

    for (let i = 0; i < count; i++) {
        const time = new Date(now.getTime() - (count - i) * 300000); // 5 minutes interval
        labels.push(time.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
    }

    return labels;
}

function generateRandomData(count) {
    return Array.from({length: count}, () => Math.floor(Math.random() * 100));
}

function updateChartData(chart, dataSource) {
    // In a real application, you would fetch data from an API
    const newData = generateRandomData(20);

    chart.data.datasets[0].data = newData;
    chart.data.datasets[0].label = `${dataSource.charAt(0).toUpperCase() + dataSource.slice(1)} Data`;

    // Update colors based on data source
    switch(dataSource) {
        case 'sales':
            chart.data.datasets[0].borderColor = 'rgb(52, 152, 219)';
            chart.data.datasets[0].backgroundColor = 'rgba(52, 152, 219, 0.2)';
            break;
        case 'traffic':
            chart.data.datasets[0].borderColor = 'rgb(46, 204, 113)';
            chart.data.datasets[0].backgroundColor = 'rgba(46, 204, 113, 0.2)';
            break;
        case 'users':
            chart.data.datasets[0].borderColor = 'rgb(231, 76, 60)';
            chart.data.datasets[0].backgroundColor = 'rgba(231, 76, 60, 0.2)';
            break;
    }

    chart.update();
}

function addDataToTable(data) {
    const tableBody = document.querySelector('#dataTable tbody');
    const newRow = document.createElement('tr');

    const typeCell = document.createElement('td');
    typeCell.textContent = data.type.charAt(0).toUpperCase() + data.type.slice(1);

    const valueCell = document.createElement('td');
    valueCell.textContent = data.value;

    const timestampCell = document.createElement('td');
    timestampCell.textContent = new Date(data.timestamp).toLocaleString();

    const notesCell = document.createElement('td');
    notesCell.textContent = data.notes || '-';

    newRow.appendChild(typeCell);
    newRow.appendChild(valueCell);
    newRow.appendChild(timestampCell);
    newRow.appendChild(notesCell);

    tableBody.prepend(newRow);

    // Limit table rows to 10
    if (tableBody.children.length > 10) {
        tableBody.removeChild(tableBody.lastChild);
    }
}

function initializeSampleData() {
    const sampleData = [
        { type: 'sales', value: 45, timestamp: new Date(Date.now() - 3600000).toISOString(), notes: 'Initial data' },
        { type: 'traffic', value: 23, timestamp: new Date(Date.now() - 1800000).toISOString(), notes: 'Morning traffic' },
        { type: 'users', value: 12, timestamp: new Date(Date.now() - 900000).toISOString(), notes: 'Active users' }
    ];

    sampleData.forEach(data => addDataToTable(data));
}
```

