// Generate mock data for demonstration
function generateMockData() {
    const dataSource = document.getElementById('data-source').value;
    const timeRange = document.getElementById('time-range').value;

    // Determine number of data points based on time range
    let points;
    switch(timeRange) {
        case 'day': points = 24; break;
        case 'week': points = 7; break;
        case 'month': points = 30; break;
        default: points = 7;
    }

    // Generate labels based on time range
    const labels = [];
    const now = new Date();

    for (let i = 0; i < points; i++) {
        const date = new Date(now);
        date.setDate(now.getDate() - i);

        switch(timeRange) {
            case 'day':
                labels.unshift(date.toLocaleTimeString('en-US', {hour: '2-digit', minute: '2-digit'}));
                break;
            case 'week':
                labels.unshift(date.toLocaleDateString('en-US', {weekday: 'short'}));
                break;
            case 'month':
                labels.unshift(date.toLocaleDateString('en-US', {month: 'short', day: 'numeric'}));
                break;
        }
    }

    // Generate mock data based on data source
    const mainData = [];
    const secondaryData = [];
    const baseValue = Math.floor(Math.random() * 1000) + 100;

    for (let i = 0; i < points; i++) {
        let value;
        switch(dataSource) {
            case 'sales':
                value = baseValue + Math.floor(Math.random() * 200) - 100;
                break;
            case 'traffic':
                value = baseValue + Math.floor(Math.random() * 500) - 250;
                break;
            case 'inventory':
                value = baseValue + Math.floor(Math.random() * 100) - 50;
                break;
            default:
                value = baseValue + Math.floor(Math.random() * 300) - 150;
        }

        mainData.push(value);
        secondaryData.push(value * 0.75 + Math.floor(Math.random() * 50) - 25);
    }

    // Calculate quick stats
    const total = mainData.reduce((a, b) => a + b, 0);
    const avg = total / mainData.length;
    const max = Math.max(...mainData);
    const min = Math.min(...mainData);

    return {
        labels,
        mainData,
        secondaryData,
        total,
        avg,
        max,
        min,
        dataSource,
        timeRange
    };
}

// Update charts with new data
function updateCharts(data) {
    // Update main chart
    mainChart.data.labels = data.labels;
    mainChart.data.datasets[0].data = data.mainData;
    mainChart.data.datasets[0].label = `${data.dataSource} Data`;
    mainChart.options.plugins.title.text = `${data.dataSource} Data (${data.timeRange})`;
    mainChart.update();

    // Update secondary chart
    secondaryChart.data.labels = data.labels;
    secondaryChart.data.datasets[0].data = data.secondaryData;
    secondaryChart.data.datasets[0].label = `Related ${data.dataSource}`;
    secondaryChart.options.plugins.title.text = `Related ${data.dataSource} (${data.timeRange})`;
    secondaryChart.update();
}

// Update quick stats display
function updateQuickStats(data) {
    // Format values based on data source
    let totalFormatted, avgFormatted;

    switch(data.dataSource) {
        case 'sales':
            totalFormatted = `$${data.total.toFixed(2)}`;
            avgFormatted = `$${data.avg.toFixed(2)}`;
            break;
        case 'traffic':
            totalFormatted = `${data.total.toFixed(0)} visits`;
            avgFormatted = `${data.avg.toFixed(0)} visits`;
            break;
        case 'inventory':
            totalFormatted = `${data.total.toFixed(0)} units`;
            avgFormatted = `${data.avg.toFixed(0)} units`;
            break;
        default:
            totalFormatted = data.total.toFixed(2);
            avgFormatted = data.avg.toFixed(2);
    }

    totalSalesElement.textContent = totalFormatted;
    activeUsersElement.textContent = avgFormatted;
    conversionRateElement.textContent = `${((data.max - data.min) / data.avg * 100).toFixed(1)}%`;
}
