    submitData(formData);

    // Reset form
    dataForm.reset();
}

// Simulate data submission
function submitData(data) {
    // In a real application, this would be an API call
    console.log('Submitting data:', data);

    // Update dashboard with new data
    const newData = { ...dashboardData };

    // Add new data point to appropriate dataset
    if (data.type === 'sales') {
        newData.salesData.push({ date: data.date, value: data.value });
        newData.totalSales += data.value;
    } else if (data.type === 'users') {
        newData.usersData.push({ date: data.date, value: data.value });
        newData.activeUsers += data.value;
    } else if (data.type === 'revenue') {
        newData.totalRevenue += data.value;
    }

    // Update dashboard
    updateDashboard(newData);

    // Show success message
    alert('Data submitted successfully!');
}

