};

// DOM elements
const dataForm = document.getElementById('data-form');
const dataTable = document.getElementById('data-table').getElementsByTagName('tbody')[0];
const totalSalesElement = document.getElementById('total-sales');
const activeUsersElement = document.getElementById('active-users');
const totalRevenueElement = document.getElementById('total-revenue');

// Chart instances
let salesChart, usersChart;

// Initialize charts
function initCharts() {
    const salesCtx = document.getElementById('sales-chart').getContext('2d');
    const usersCtx = document.getElementById('users-chart').getContext('2d');

    salesChart = new Chart(salesCtx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Sales',
                data: [],
                borderColor: 'rgb(52, 152, 219)',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                tension: 0.1
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    usersChart = new Chart(usersCtx, {
        type: 'bar',
        data: {
            labels: [],
            datasets: [{
                label: 'Active Users',
                data: [],
                backgroundColor: 'rgba(46, 204, 113, 0.7)',
                borderColor: 'rgb(46, 204, 113)',
                borderWidth: 1
            }]
        },
        options: {
            responsive: true,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });
}

// Update dashboard statistics
function updateStats() {
    totalSalesElement.textContent = `$${dashboardData.totalSales.toLocaleString()}`;
    activeUsersElement.textContent = dashboardData.activeUsers.toLocaleString();
    totalRevenueElement.textContent = `$${dashboardData.totalRevenue.toLocaleString()}`;
}

// Update charts with new data
function updateCharts() {
    // Update sales chart
    salesChart.data.labels = dashboardData.sales.map(item => item.label);
    salesChart.data.datasets[0].data = dashboardData.sales.map(item => item.value);
    salesChart.update();

    // Update users chart
    usersChart.data.labels = dashboardData.users.map(item => item.label);
    usersChart.data.datasets[0].data = dashboardData.users.map(item => item.value);
    usersChart.update();
}

// Add data to the table
function addToTable(label, value, category, timestamp) {
    const row = dataTable.insertRow();
    row.insertCell(0).textContent = label;
    row.insertCell(1).textContent = value;
    row.insertCell(2).textContent = category.charAt(0).toUpperCase() + category.slice(1);
    row.insertCell(3).textContent = timestamp;
}

// Handle form submission
dataForm.addEventListener('submit', function(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const category = document.getElementById('data-category').value;
    const timestamp = new Date().toLocaleString();

    // Add data to appropriate category
    const dataPoint = { label, value, timestamp };

    switch(category) {
        case 'sales':
            dashboardData.sales.push(dataPoint);
            dashboardData.totalSales += value;
            break;
        case 'revenue':
            dashboardData.revenue.push(dataPoint);
            dashboardData.totalRevenue += value;
            break;
        case 'users':
            dashboardData.users.push(dataPoint);
            dashboardData.activeUsers += value;
            break;
    }

    // Update dashboard
    updateStats();
    updateCharts();
    addToTable(label, value, category, timestamp);

    // Reset form
    dataForm.reset();
});

// Update date and time
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Simulate real-time data updates
function simulateRealTimeData() {
    // Generate random data every 5 seconds
    setInterval(() => {
        const categories = ['sales', 'revenue', 'users'];
        const randomCategory = categories[Math.floor(Math.random() * categories.length)];
        const randomValue = Math.floor(Math.random() * 100) + 10;
        const label = `Auto ${new Date().toLocaleTimeString()}`;

        // Add data to appropriate category
        const dataPoint = { label, value: randomValue, timestamp: new Date().toLocaleString() };

        switch(randomCategory) {
            case 'sales':
                dashboardData.sales.push(dataPoint);
                dashboardData.totalSales += randomValue;
                break;
            case 'revenue':
                dashboardData.revenue.push(dataPoint);
                dashboardData.totalRevenue += randomValue;
                break;
            case 'users':
                dashboardData.users.push(dataPoint);
                dashboardData.activeUsers += randomValue;
                break;
        }

        // Update dashboard
        updateStats();
        updateCharts();
        addToTable(label, randomValue, randomCategory, dataPoint.timestamp);
    }, 5000);
}

// Initialize the dashboard
function initDashboard() {
    initCharts();
    updateStats();
    updateDateTime();
    setInterval(updateDateTime, 1000);
    simulateRealTimeData();
}

// Start the dashboard when the page loads
window.addEventListener('DOMContentLoaded', initDashboard);
