// Update current date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Fetch data and update charts
async function fetchDataAndUpdateCharts(mainChart, secondaryChart) {
    try {
        // In a real application, this would be an API call
        // For demo purposes, we'll generate mock data
        const mockData = generateMockData();

        // Update quick stats
        document.getElementById('total-sales').textContent = `$${mockData.totalSales.toFixed(2)}`;
        document.getElementById('active-users').textContent = mockData.activeUsers;
        document.getElementById('conversion-rate').textContent = `${mockData.conversionRate}%`;

        // Update main chart
        mainChart.data.labels = mockData.labels;
        mainChart.data.datasets[0].data = mockData.mainChartData;
        mainChart.update();

        // Update secondary chart
        secondaryChart.data.labels = mockData.labels;
        secondaryChart.data.datasets[0].data = mockData.secondaryChartData;
        secondaryChart.update();

    } catch (error) {
        console.error('Error fetching data:', error);
    }
}

// Generate mock data for demonstration
function generateMockData() {
    const dataSource = document.getElementById('data-source').value;
    const timeRange = document.getElementById('time-range').value;
    const filterTerm = document.getElementById('data-filter').value.toLowerCase();

    // Generate labels based on time range
    let labels = [];
    const now = new Date();

    switch(timeRange) {
        case 'day':
            for (let i = 23; i >= 0; i--) {
                const hour = new Date(now);
                hour.setHours(now.getHours() - i);
                labels.push(hour.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
            }
            break;
        case 'week':
            for (let i = 6; i >= 0; i--) {
                const day = new Date(now);
                day.setDate(now.getDate() - i);
                labels.push(day.toLocaleDateString([], {weekday: 'short'}));
            }
            break;
        case 'month':
            for (let i = 29; i >= 0; i--) {
                const day = new Date(now);
                day.setDate(now.getDate() - i);
                labels.push(day.toLocaleDateString([], {month: 'short', day: 'numeric'}));
            }
            break;
    }

    // Generate data based on data source
    let mainChartData = [];
    let secondaryChartData = [];
    let totalSales = 0;
    let activeUsers = 0;
    let conversionRate = 0;

    for (let i = 0; i < labels.length; i++) {
        let value1, value2;

        switch(dataSource) {
            case 'sales':
                value1 = Math.floor(Math.random() * 1000) + 100;
                value2 = Math.floor(Math.random() * 500) + 50;
                totalSales += value1;
                activeUsers = Math.floor(Math.random() * 1000) + 500;
                conversionRate = Math.floor(Math.random() * 20) + 5;
                break;
            case 'traffic':
                value1 = Math.floor(Math.random() * 5000) + 1000;
                value2 = Math.floor(Math.random() * 2000) + 500;
                totalSales = Math.floor(Math.random() * 10000) + 5000;
                activeUsers = value1;
                conversionRate = Math.floor(Math.random() * 15) + 3;
                break;
            case 'inventory':
                value1 = Math.floor(Math.random() * 200) + 50;
                value2 = Math.floor(Math.random() * 100) + 20;
                totalSales = Math.floor(Math.random() * 5000) + 1000;
                activeUsers = Math.floor(Math.random() * 500) + 200;
                conversionRate = Math.floor(Math.random() * 10) + 2;
                break;
        }

        // Apply filter if present
        if (filterTerm && !labels[i].toLowerCase().includes(filterTerm)) {
            value1 = 0;
            value2 = 0;
        }

        mainChartData.push(value1);
        secondaryChartData.push(value2);
    }

    return {
        labels,
        mainChartData,
        secondaryChartData,
        totalSales,
        activeUsers,
        conversionRate
    };
}
