        day: 'numeric'
    });
    currentTimeElement.textContent = now.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
}

// Update statistics
function updateStatistics() {
    if (dashboardData.allData.length === 0) {
        totalPointsElement.textContent = '0';
        avgValueElement.textContent = '0';
        lastUpdatedElement.textContent = 'Never';
        return;
    }

    const total = dashboardData.allData.length;
    const sum = dashboardData.allData.reduce((acc, item) => acc + item.value, 0);
    const avg = (sum / total).toFixed(2);
    const lastUpdated = new Date(dashboardData.allData[dashboardData.allData.length - 1].timestamp);

    totalPointsElement.textContent = total;
    avgValueElement.textContent = avg;
    lastUpdatedElement.textContent = lastUpdated.toLocaleString();
}

// Update recent data list
function updateRecentData() {
    recentDataList.innerHTML = '';

    // Get last 5 data points
    const recentData = dashboardData.allData.slice(-5).reverse();

    recentData.forEach(item => {
        const li = document.createElement('li');
        const date = new Date(item.timestamp);

        li.innerHTML = `
            <span>${item.type.charAt(0).toUpperCase() + item.type.slice(1)}</span>
            <span>${item.value}</span>
            <span>${date.toLocaleString()}</span>
        `;
        recentDataList.appendChild(li);
    });
}

// Update chart
function updateChart() {
    // Get data for the selected type
    const selectedType = document.getElementById('data-type').value;
    const data = dashboardData[selectedType] || [];

    // Prepare chart data
    const labels = data.map(item => {
        const date = new Date(item.timestamp);
        return date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    });

    const values = data.map(item => item.value);

    // Update chart
    chart.data.labels = labels;
    chart.data.datasets[0].data = values;
    chart.data.datasets[0].label = `${selectedType.charAt(0).toUpperCase() + selectedType.slice(1)} Data`;

    // Update chart colors based on type
    switch(selectedType) {
        case 'sales':
            chart.data.datasets[0].borderColor = 'rgba(52, 152, 219, 1)';
            chart.data.datasets[0].backgroundColor = 'rgba(52, 152, 219, 0.1)';
            break;
        case 'traffic':
            chart.data.datasets[0].borderColor = 'rgba(46, 204, 113, 1)';
            chart.data.datasets[0].backgroundColor = 'rgba(46, 204, 113, 0.1)';
            break;
        case 'temperature':
            chart.data.datasets[0].borderColor = 'rgba(231, 76, 60, 1)';
            chart.data.datasets[0].backgroundColor = 'rgba(231, 76, 60, 0.1)';
            break;
    }

    chart.update();
}

// Form submission handler
dataForm.addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('data-type').value;
    const dataValue = parseFloat(document.getElementById('data-value').value);
    const dataTimestamp = new Date(document.getElementById('data-timestamp').value).getTime();

    // Validate inputs
    if (isNaN(dataValue) || dataValue <= 0) {
        alert('Please enter a valid positive number for the value.');
        return;
    }

    if (isNaN(dataTimestamp)) {
        alert('Please select a valid timestamp.');
        return;
    }

    // Create new data point
    const newDataPoint = {
        type: dataType,
        value: dataValue,
        timestamp: dataTimestamp
    };

    // Add to appropriate array
    dashboardData[dataType].push(newDataPoint);
    dashboardData.allData.push(newDataPoint);

    // Update UI
    updateStatistics();
    updateRecentData();
    updateChart();

    // Reset form
    dataForm.reset();

    // Set default timestamp to now
    const now = new Date();
    document.getElementById('data-timestamp').value = now.toISOString().slice(0, 16);
});

// Data type change handler
document.getElementById('data-type').addEventListener('change', updateChart);

// Initialize dashboard
function initDashboard() {
    // Set default timestamp to now
    const now = new Date();
    document.getElementById('data-timestamp').value = now.toISOString().slice(0, 16);

    // Update date/time every second
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initial UI updates
    updateStatistics();
    updateRecentData();
    updateChart();
}

// Start dashboard
initDashboard();

// Simulate incoming real-time data (for demonstration)
function simulateRealTimeData() {
    const dataTypes = ['sales', 'traffic', 'temperature'];
    const randomType = dataTypes[Math.floor(Math.random() * dataTypes.length)];
    const randomValue = Math.floor(Math.random() * 100) + 1;
    const now = new Date();

    const newDataPoint = {
        type: randomType,
        value: randomValue,
        timestamp: now.getTime()
    };

    dashboardData[randomType].push(newDataPoint);
    dashboardData.allData.push(newDataPoint);

    updateStatistics();
    updateRecentData();
    updateChart();
}

// Simulate data every 5 seconds (for demonstration)
setInterval(simulateRealTimeData, 5000);
