## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize charts
    const mainChartCtx = document.getElementById('main-chart').getContext('2d');
    let mainChart = createChart(mainChartCtx, 'line', 'Sales Data', [], []);

    // Form handling
    const dataForm = document.getElementById('data-form');
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();
        updateDashboard();
    });

    // Time range toggle
    const timeRangeSelect = document.getElementById('time-range');
    const customRangeDiv = document.getElementById('custom-range');

    timeRangeSelect.addEventListener('change', function() {
        if (this.value === 'custom') {
            customRangeDiv.style.display = 'block';
        } else {
            customRangeDiv.style.display = 'none';
        }
    });

    // Initial data load
    updateDashboard();

    // Simulate real-time updates
    setInterval(updateRealTimeData, 5000);
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Create chart
function createChart(ctx, type, label, labels, data) {
    return new Chart(ctx, {
        type: type,
        data: {
            labels: labels,
            datasets: [{
                label: label,
                data: data,
                backgroundColor: 'rgba(52, 152, 219, 0.5)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 2,
                tension: 0.1,
                fill: type === 'line' ? true : false
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                tooltip: {
                    mode: 'index',
                    intersect: false,
                }
            }
        }
    });
}

// Update dashboard with new data
function updateDashboard() {
    const dataSource = document.getElementById('data-source').value;
    const timeRange = document.getElementById('time-range').value;
    const visualizationType = document.getElementById('visualization-type').value;

    // Simulate API call to get data
    const data = generateSampleData(dataSource, timeRange);

    // Update chart
    const mainChartCtx = document.getElementById('main-chart').getContext('2d');
    const existingChart = Chart.getChart(mainChartCtx);

    if (existingChart) {
        existingChart.destroy();
    }

    const chartTitle = getChartTitle(dataSource);
    mainChart = createChart(mainChartCtx, visualizationType, chartTitle, data.labels, data.values);

    // Update summary metrics
    document.getElementById('total-sales').textContent = `$${data.total.toFixed(2)}`;
    document.getElementById('active-users').textContent = data.activeUsers;
    document.getElementById('conversion-rate').textContent = `${data.conversionRate}%`;

    // Update data table
    updateDataTable(data.tableData);
}

// Generate sample data based on parameters
function generateSampleData(dataSource, timeRange) {
    const now = new Date();
    const labels = [];
    const values = [];
    let tableData = [];
    let total = 0;
    let activeUsers = 0;
    let conversionRate = 0;

    // Determine number of data points based on time range
    let points = 24;
    if (timeRange === '7d') points = 7;
    if (timeRange === '30d') points = 30;

    // Generate data based on source
    for (let i = 0; i < points; i++) {
        const date = new Date(now);
        date.setHours(now.getHours() - i);

        let value = 0;
        let label = '';

        switch(dataSource) {
            case 'sales':
                value = Math.floor(Math.random() * 1000) + 100;
                label = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                break;
            case 'traffic':
                value = Math.floor(Math.random() * 5000) + 1000;
                label = date.toLocaleDateString();
                break;
            case 'inventory':
                value = Math.floor(Math.random() * 200) + 50;
                label = `Item ${i + 1}`;
                break;
        }

        labels.unshift(label);
        values.unshift(value);
        total += value;

        // Create table data
        const change = Math.floor(Math.random() * 20) - 10;
        tableData.unshift({
            timestamp: date.toLocaleString(),
            value: value,
            change: change
        });
    }

    // Calculate additional metrics
    activeUsers = Math.floor(Math.random() * 1000) + 500;
    conversionRate = Math.floor((Math.random() * 10) + 1);

    return {
        labels: labels,
        values: values,
        total: total,
        activeUsers: activeUsers,
        conversionRate: conversionRate,
        tableData: tableData
    };
}

// Get chart title based on data source
function getChartTitle(dataSource) {
    switch(dataSource) {
        case 'sales': return 'Sales Over Time';
        case 'traffic': return 'Website Traffic';
        case 'inventory': return 'Inventory Levels';
        default: return 'Data Visualization';
    }
}

// Update data table
function updateDataTable(data) {
    const tableBody = document.querySelector('#data-table tbody');
    tableBody.innerHTML = '';

    data.forEach(item => {
        const row = document.createElement('tr');

        const timestampCell = document.createElement('td');
        timestampCell.textContent = item.timestamp;
        row.appendChild(timestampCell);

        const valueCell = document.createElement('td');
        valueCell.textContent = item.value;
        row.appendChild(valueCell);

        const changeCell = document.createElement('td');
        changeCell.textContent = `${item.change > 0 ? '+' : ''}${item.change}%`;
        changeCell.style.color = item.change > 0 ? 'var(--success-color)' : 'var(--danger-color)';
        row.appendChild(changeCell);

        tableBody.appendChild(row);
    });
}

// Simulate real-time data updates
function updateRealTimeData() {
    const dataSource = document.getElementById('data-source').value;
    const timeRange = document.getElementById('time-range').value;

    // Simulate new data point
    const now = new Date();
    let newValue = 0;
    let newLabel = '';

    switch(dataSource) {
        case 'sales':
            newValue = Math.floor(Math.random() * 1000) + 100;
            newLabel = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            break;
        case 'traffic':
            newValue = Math.floor(Math.random() * 5000) + 1000;
            newLabel = now.toLocaleDateString();
            break;
        case 'inventory':
            newValue = Math.floor(Math.random() * 200) + 50;
            newLabel = `Item ${Math.floor(Math.random() * 20) + 1}`;
            break;
    }

    // Update chart
    const mainChartCtx = document.getElementById('main-chart').getContext('2d');
    const chart = Chart.getChart(mainChartCtx);

    if (chart) {
        // Remove oldest data point if we have too many
        if (chart.data.labels.length >= 24) {
            chart.data.labels.shift();
            chart.data.datasets[0].data.shift();
        }

        // Add new data point
        chart.data.labels.push(newLabel);
        chart.data.datasets[0].data.push(newValue);
        chart.update();
    }

    // Update summary metrics slightly
    const currentTotal = parseFloat(document.getElementById('total-sales').textContent.replace('$', ''));
    const currentUsers = parseInt(document.getElementById('active-users').textContent);
    const currentRate = parseInt(document.getElementById('conversion-rate').textContent.replace('%', ''));

    document.getElementById('total-sales').textContent = `$${(currentTotal + (newValue * 0.01)).toFixed(2)}`;
    document.getElementById('active-users').textContent = currentUsers + Math.floor(Math.random() * 5) - 2;
    document.getElementById('conversion-rate').textContent = `${currentRate + Math.floor(Math.random() * 3) - 1}%`;

    // Update table with new data
    const tableData = [{
        timestamp: now.toLocaleString(),
        value: newValue,
        change: Math.floor(Math.random() * 20) - 10
    }];

    updateDataTable(tableData);
}
