## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('main-chart').getContext('2d');
    let mainChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [{
                label: 'Data Values',
                data: [],
                backgroundColor: 'rgba(52, 152, 219, 0.2)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 2,
                tension: 0.3,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Form handling
    const dataForm = document.getElementById('data-form');
    const timeRangeSelect = document.getElementById('time-range');
    const customRangeDiv = document.getElementById('custom-range');

    // Show/hide custom date range fields
    timeRangeSelect.addEventListener('change', function() {
        if (this.value === 'custom') {
            customRangeDiv.style.display = 'block';
        } else {
            customRangeDiv.style.display = 'none';
        }
    });

    // Form submission
    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();

        // Get form values
        const dataSource = document.getElementById('data-source').value;
        const timeRange = document.getElementById('time-range').value;
        const chartType = document.getElementById('chart-type').value;

        // Simulate data fetching
        fetchData(dataSource, timeRange)
            .then(data => {
                updateChart(mainChart, data, chartType);
                updateDataTable(data);
                updateStats(data);
            })
            .catch(error => {
                console.error('Error fetching data:', error);
            });
    });

    // Initial data load
    fetchData('sales', '24h')
        .then(data => {
            updateChart(mainChart, data, 'line');
            updateDataTable(data);
            updateStats(data);
        });
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Simulate data fetching
function fetchData(dataSource, timeRange) {
    return new Promise((resolve) => {
        // Simulate API delay
        setTimeout(() => {
            // Generate random data based on parameters
            const dataPoints = getDataPoints(timeRange);
            const data = {
                labels: dataPoints.map(point => point.label),
                values: dataPoints.map(point => point.value),
                source: dataSource,
                range: timeRange,
                timestamp: new Date().toISOString()
            };
            resolve(data);
        }, 500);
    });
}

// Generate data points based on time range
function getDataPoints(timeRange) {
    const now = new Date();
    const points = [];
    let count, interval;

    switch(timeRange) {
        case '24h':
            count = 24;
            interval = 1; // hours
            break;
        case '7d':
            count = 7;
            interval = 24; // days
            break;
        case '30d':
            count = 30;
            interval = 24; // days
            break;
        default:
            count = 7;
            interval = 24;
    }

    for (let i = count - 1; i >= 0; i--) {
        const date = new Date(now);
        date.setHours(now.getHours() - (i * interval));

        let label;
        if (timeRange === '24h') {
            label = date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'});
        } else {
            label = date.toLocaleDateString();
        }

        points.push({
            label: label,
            value: Math.floor(Math.random() * 100) + 10
        });
    }

    return points;
}

// Update the chart with new data
function updateChart(chart, data, chartType) {
    chart.data.labels = data.labels;
    chart.data.datasets[0].data = data.values;
    chart.data.datasets[0].label = `${data.source} Data`;

    // Update chart type
    chart.config.type = chartType;

    // Update chart colors based on type
    if (chartType === 'pie') {
        chart.data.datasets[0].backgroundColor = [
            'rgba(52, 152, 219, 0.7)',
            'rgba(46, 204, 113, 0.7)',
            'rgba(241, 196, 15, 0.7)',
            'rgba(231, 76, 60, 0.7)',
            'rgba(155, 89, 182, 0.7)',
            'rgba(52, 73, 94, 0.7)'
        ];
        chart.data.datasets[0].borderColor = 'rgba(255, 255, 255, 0.8)';
    } else {
        chart.data.datasets[0].backgroundColor = 'rgba(52, 152, 219, 0.2)';
        chart.data.datasets[0].borderColor = 'rgba(52, 152, 219, 1)';
    }

    chart.update();
}

// Update the data table
function updateDataTable(data) {
    const tableBody = document.querySelector('#data-table tbody');
    tableBody.innerHTML = '';

    data.labels.forEach((label, index) => {
        const row = document.createElement('tr');
        const value = data.values[index];
        const prevValue = index > 0 ? data.values[index - 1] : value;
        const change = ((value - prevValue) / prevValue * 100).toFixed(1);

        row.innerHTML = `
            <td>${label}</td>
            <td>${value}</td>
            <td class="${change >= 0 ? 'positive' : 'negative'}">${change}%</td>
        `;

        tableBody.appendChild(row);
    });
}

// Update statistics panel
function updateStats(data) {
    const totalItems = data.values.length;
    const avgValue = (data.values.reduce((a, b) => a + b, 0) / totalItems).toFixed(2);
    const lastUpdate = new Date(data.timestamp).toLocaleTimeString();

    document.getElementById('total-items').textContent = totalItems;
    document.getElementById('avg-value').textContent = `$${avgValue}`;
    document.getElementById('last-update').textContent = lastUpdate;
}
