## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    let chartType = 'line';
    let isRealtime = true;

    // Sample data
    let chartData = {
        labels: [],
        datasets: [{
            label: 'Data Values',
            data: [],
            backgroundColor: 'rgba(52, 152, 219, 0.2)',
            borderColor: 'rgba(52, 152, 219, 1)',
            borderWidth: 2,
            tension: 0.1,
            fill: true
        }]
    };

    // Create chart
    let realtimeChart = new Chart(ctx, {
        type: chartType,
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            animation: {
                duration: 0 // Disable animation for real-time updates
            }
        }
    });

    // Update chart with new data
    function updateChart(newData) {
        if (chartData.labels.length >= 20) {
            chartData.labels.shift();
            chartData.datasets[0].data.shift();
        }

        chartData.labels.push(new Date().toLocaleTimeString());
        chartData.datasets[0].data.push(newData.value);

        realtimeChart.update();
    }

    // Toggle real-time updates
    document.getElementById('toggle-realtime').addEventListener('click', function() {
        isRealtime = !isRealtime;
        this.textContent = isRealtime ? 'Pause' : 'Resume';
    });

    // Change chart type
    document.getElementById('chart-type').addEventListener('change', function() {
        chartType = this.value;
        realtimeChart.destroy();

        realtimeChart = new Chart(ctx, {
            type: chartType,
            data: chartData,
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                animation: {
                    duration: 0
                }
            }
        });
    });

    // Form submission handler
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const name = document.getElementById('data-name').value;
        const value = parseFloat(document.getElementById('data-value').value);
        const category = document.getElementById('data-category').value;

        // Add to table
        addToTable(name, value, category);

        // Update chart if real-time is enabled
        if (isRealtime) {
            updateChart({ value: value });
        }

        // Reset form
        this.reset();
    });

    // Add data to table
    function addToTable(name, value, category) {
        const tableBody = document.querySelector('#data-table tbody');
        const newRow = document.createElement('tr');

        const timestamp = new Date().toLocaleString();
        newRow.innerHTML = `
            <td>${timestamp}</td>
            <td>${name}</td>
            <td>${value}</td>
            <td>${category}</td>
        `;

        tableBody.prepend(newRow);

        // Limit table rows to 10
        if (tableBody.children.length > 10) {
            tableBody.removeChild(tableBody.lastChild);
        }
    }

    // Simulate real-time data (for demo purposes)
    function simulateRealTimeData() {
        if (isRealtime) {
            const randomValue = Math.floor(Math.random() * 100) + 1;
            updateChart({ value: randomValue });
            addToTable('Simulated Data', randomValue, 'category' + Math.floor(Math.random() * 3 + 1));
        }
    }

    // Simulate data every 3 seconds
    setInterval(simulateRealTimeData, 3000);

    // Update date and time display
    function updateDateTime() {
        const now = new Date();
        document.getElementById('current-date').textContent = now.toLocaleDateString();
        document.getElementById('current-time').textContent = now.toLocaleTimeString();
    }
});
