## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize real-time chart
    initRealTimeChart();

    // Form handling
    const form = document.getElementById('data-form');
    form.addEventListener('submit', handleFormSubmit);
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Real-time chart variables
let realtimeChart;
let chartData = {
    labels: [],
    datasets: [{
        label: 'Real-Time Data',
        data: [],
        borderColor: 'rgb(52, 152, 219)',
        backgroundColor: 'rgba(52, 152, 219, 0.2)',
        tension: 0.1,
        fill: true
    }]
};
let isPaused = false;
let chartType = 'line';

// Initialize real-time chart
function initRealTimeChart() {
    const ctx = document.getElementById('realtimeChart').getContext('2d');

    realtimeChart = new Chart(ctx, {
        type: chartType,
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            animation: {
                duration: 0 // general animation time
            },
            hover: {
                animationDuration: 0 // duration of animations when hovering an item
            },
            responsiveAnimationDuration: 0 // animation duration after a resize
        }
    });

    // Simulate real-time data updates
    setInterval(updateChartData, 1000);

    // Add event listeners for chart controls
    document.getElementById('toggle-realtime').addEventListener('click', toggleRealTime);
    document.getElementById('chart-type').addEventListener('change', changeChartType);
}

// Update chart data with new values
function updateChartData() {
    if (isPaused) return;

    const now = new Date();
    const timeString = now.toLocaleTimeString();

    // Add new data point
    chartData.labels.push(timeString);
    chartData.datasets[0].data.push(Math.floor(Math.random() * 100));

    // Keep only the last 20 data points
    if (chartData.labels.length > 20) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    // Update chart
    realtimeChart.update();
}

// Toggle real-time updates
function toggleRealTime() {
    isPaused = !isPaused;
    const button = document.getElementById('toggle-realtime');
    button.textContent = isPaused ? 'Resume' : 'Pause';
}

// Change chart type
function changeChartType(event) {
    chartType = event.target.value;
    realtimeChart.destroy();
    initRealTimeChart();
}

// Handle form submission
function handleFormSubmit(event) {
    event.preventDefault();

    const form = event.target;
    const formData = new FormData(form);
    const formStatus = document.getElementById('form-status');

    // Simulate form submission (in a real app, this would be an API call)
    setTimeout(() => {
        // Simulate success or error
        const isSuccess = Math.random() > 0.2; // 80% chance of success

        if (isSuccess) {
            formStatus.textContent = 'Data submitted successfully!';
            formStatus.className = 'form-status success';

            // Add the submitted data to the chart
            const dataName = formData.get('data-name');
            const dataValue = parseFloat(formData.get('data-value'));

            // Update chart with new data
            chartData.labels.push(dataName);
            chartData.datasets[0].data.push(dataValue);
            realtimeChart.update();

            // Reset form
            form.reset();
        } else {
            formStatus.textContent = 'Error submitting data. Please try again.';
            formStatus.className = 'form-status error';
        }

        // Hide status message after 5 seconds
        setTimeout(() => {
            formStatus.style.display = 'none';
        }, 5000);
    }, 1000);
}
