## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Initialize date and time display
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('main-chart').getContext('2d');
    const mainChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: []
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                title: {
                    display: true,
                    text: 'Real-Time Data Visualization'
                }
            }
        }
    });

    // Sample data storage
    let dashboardData = {
        sales: [],
        traffic: [],
        inventory: []
    };

    // Form submission handler
    document.getElementById('data-form').addEventListener('submit', function(e) {
        e.preventDefault();

        const dataType = document.getElementById('data-type').value;
        const dataValue = parseFloat(document.getElementById('data-value').value);
        const timestamp = new Date(document.getElementById('data-timestamp').value);

        // Add data to storage
        dashboardData[dataType].push({
            value: dataValue,
            timestamp: timestamp
        });

        // Update chart
        updateChart(mainChart, dashboardData);

        // Update table
        updateDataTable(dashboardData);

        // Reset form
        this.reset();

        // Show success message
        showNotification('Data submitted successfully!', 'success');
    });

    // Real-time data simulation
    let realTimeActive = true;
    let refreshInterval = 10000; // 10 seconds

    // Update refresh interval
    document.getElementById('refresh-interval').addEventListener('change', function() {
        refreshInterval = parseInt(this.value) * 1000;
    });

    // Toggle real-time updates
    document.getElementById('toggle-realtime').addEventListener('click', function() {
        realTimeActive = !realTimeActive;
        this.textContent = realTimeActive ? 'Pause Real-Time Updates' : 'Resume Real-Time Updates';
        this.style.backgroundColor = realTimeActive ? '#2ecc71' : '#e74c3c';
    });

    // Simulate real-time data updates
    function simulateRealTimeData() {
        if (!realTimeActive) return;

        const dataTypes = ['sales', 'traffic', 'inventory'];
        const randomType = dataTypes[Math.floor(Math.random() * dataTypes.length)];
        const randomValue = Math.floor(Math.random() * 100) + 1;

        dashboardData[randomType].push({
            value: randomValue,
            timestamp: new Date()
        });

        // Update chart and table
        updateChart(mainChart, dashboardData);
        updateDataTable(dashboardData);

        // Schedule next update
        setTimeout(simulateRealTimeData, refreshInterval);
    }

    // Start real-time simulation
    simulateRealTimeData();

    // Initial chart update
    updateChart(mainChart, dashboardData);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Update chart with new data
function updateChart(chart, data) {
    // Prepare datasets
    const datasets = [];

    // Colors for different data types
    const colors = {
        sales: 'rgba(52, 152, 219, 0.7)',
        traffic: 'rgba(46, 204, 113, 0.7)',
        inventory: 'rgba(241, 196, 15, 0.7)'
    };

    // Add each data type to chart
    for (const [type, values] of Object.entries(data)) {
        if (values.length > 0) {
            datasets.push({
                label: type.charAt(0).toUpperCase() + type.slice(1),
                data: values.map(item => item.value),
                borderColor: colors[type],
                backgroundColor: colors[type],
                tension: 0.1,
                fill: false
            });
        }
    }

    // Update chart data
    chart.data.datasets = datasets;

    // Update labels (using timestamps from the first data type)
    if (Object.values(data).some(arr => arr.length > 0)) {
        const firstDataType = Object.keys(data).find(key => data[key].length > 0);
        chart.data.labels = data[firstDataType].map(item =>
            item.timestamp.toLocaleTimeString()
        );
    }

    chart.update();
}

// Update data table
function updateDataTable(data) {
    const tableBody = document.querySelector('#data-table tbody');
    tableBody.innerHTML = '';

    // Combine all data points and sort by timestamp
    const allData = [];
    for (const [type, values] of Object.entries(data)) {
        values.forEach(item => {
            allData.push({
                type: type,
                value: item.value,
                timestamp: item.timestamp
            });
        });
    }

    // Sort by timestamp (newest first)
    allData.sort((a, b) => b.timestamp - a.timestamp);

    // Display only the last 10 entries
    const recentData = allData.slice(0, 10);

    // Add rows to table
    recentData.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.type.charAt(0).toUpperCase() + item.type.slice(1)}</td>
            <td>${item.value}</td>
            <td>${item.timestamp.toLocaleString()}</td>
        `;
        tableBody.appendChild(row);
    });
}

// Show notification
function showNotification(message, type = 'info') {
    const notification = document.createElement('div');
    notification.className = `notification ${type}`;
    notification.textContent = message;

    document.body.appendChild(notification);

    setTimeout(() => {
        notification.style.opacity = '0';
        setTimeout(() => {
            document.body.removeChild(notification);
        }, 500);
    }, 3000);
}
