## JavaScript Functionality (script.js)

```javascript
// Dashboard Data
let dashboardData = {
    sales: [],
    users: [],
    revenue: []
};

// Chart instance
let mainChart;

// Initialize the dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    initChart();

    // Set up form submission
    document.getElementById('data-form').addEventListener('submit', handleFormSubmit);

    // Generate some initial data
    generateInitialData();
});

// Update current date and time
function updateDateTime() {
    const now = new Date();
    const dateOptions = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    const timeOptions = { hour: '2-digit', minute: '2-digit', second: '2-digit' };

    document.getElementById('current-date').textContent = now.toLocaleDateString(undefined, dateOptions);
    document.getElementById('current-time').textContent = now.toLocaleTimeString(undefined, timeOptions);
}

// Initialize the main chart
function initChart() {
    const ctx = document.getElementById('main-chart').getContext('2d');

    mainChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: [],
            datasets: [
                {
                    label: 'Sales',
                    data: [],
                    borderColor: 'rgb(52, 152, 219)',
                    backgroundColor: 'rgba(52, 152, 219, 0.1)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Users',
                    data: [],
                    borderColor: 'rgb(46, 204, 113)',
                    backgroundColor: 'rgba(46, 204, 113, 0.1)',
                    tension: 0.3,
                    fill: true
                },
                {
                    label: 'Revenue',
                    data: [],
                    borderColor: 'rgb(230, 126, 34)',
                    backgroundColor: 'rgba(230, 126, 34, 0.1)',
                    tension: 0.3,
                    fill: true
                }
            ]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                tooltip: {
                    mode: 'index',
                    intersect: false,
                }
            }
        }
    });
}

// Handle form submission
function handleFormSubmit(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const category = document.getElementById('data-category').value;

    // Add data to the appropriate category
    const timestamp = new Date().toLocaleString();
    const newData = { label, value, category, timestamp };

    dashboardData[category].push(newData);

    // Update the chart and table
    updateChart();
    updateStats();
    updateTable();

    // Reset form
    e.target.reset();
}

// Update the chart with new data
function updateChart() {
    // Get the last 10 data points for each category
    const salesData = dashboardData.sales.slice(-10).map(item => item.value);
    const usersData = dashboardData.users.slice(-10).map(item => item.value);
    const revenueData = dashboardData.revenue.slice(-10).map(item => item.value);

    // Update chart data
    mainChart.data.datasets[0].data = salesData;
    mainChart.data.datasets[1].data = usersData;
    mainChart.data.datasets[2].data = revenueData;

    // Update labels (using timestamps)
    const allTimestamps = [
        ...dashboardData.sales.map(item => item.timestamp),
        ...dashboardData.users.map(item => item.timestamp),
        ...dashboardData.revenue.map(item => item.timestamp)
    ].sort();

    // Get unique timestamps and limit to last 10
    const uniqueTimestamps = [...new Set(allTimestamps)].slice(-10);
    mainChart.data.labels = uniqueTimestamps;

    mainChart.update();
}

// Update the statistics cards
function updateStats() {
    // Calculate totals
    const totalSales = dashboardData.sales.reduce((sum, item) => sum + item.value, 0);
    const totalUsers = dashboardData.users.reduce((sum, item) => sum + item.value, 0);
    const totalRevenue = dashboardData.revenue.reduce((sum, item) => sum + item.value, 0);

    // Update DOM
    document.getElementById('total-sales').textContent = `$${totalSales.toFixed(2)}`;
    document.getElementById('active-users').textContent = totalUsers;
    document.getElementById('total-revenue').textContent = `$${totalRevenue.toFixed(2)}`;
}

// Update the data table
function updateTable() {
    const tableBody = document.querySelector('#data-table tbody');
    tableBody.innerHTML = '';

    // Combine all data and sort by timestamp (newest first)
    const allData = [
        ...dashboardData.sales.map(item => ({...item, type: 'sales'})),
        ...dashboardData.users.map(item => ({...item, type: 'users'})),
        ...dashboardData.revenue.map(item => ({...item, type: 'revenue'}))
    ].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

    // Display only the last 10 entries
    const recentData = allData.slice(0, 10);

    recentData.forEach(item => {
        const row = document.createElement('tr');
        row.innerHTML = `
            <td>${item.label}</td>
            <td>${item.value}</td>
            <td>${item.category.charAt(0).toUpperCase() + item.category.slice(1)}</td>
            <td>${item.timestamp}</td>
        `;
        tableBody.appendChild(row);
    });
}

// Generate some initial data for demonstration
function generateInitialData() {
    const categories = ['sales', 'users', 'revenue'];
    const labels = ['Q1', 'Q2', 'Q3', 'Q4', 'Year End'];

    for (let i = 0; i < 5; i++) {
        categories.forEach(category => {
            const value = Math.floor(Math.random() * 1000) + 100;
            const timestamp = new Date(Date.now() - (5 - i) * 24 * 60 * 60 * 1000).toLocaleString();

            dashboardData[category].push({
                label: labels[i],
                value: category === 'users' ? value : value / 10, // Users are smaller numbers
                category,
                timestamp
            });
        });
    }

    updateChart();
    updateStats();
    updateTable();
}
