## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    let chartData = {
        labels: [],
        datasets: [{
            label: 'Data Values',
            data: [],
            backgroundColor: 'rgba(52, 152, 219, 0.2)',
            borderColor: 'rgba(52, 152, 219, 1)',
            borderWidth: 2,
            tension: 0.1,
            fill: true
        }]
    };

    const chartConfig = {
        type: 'line',
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            },
            animation: {
                duration: 1000
            }
        }
    };

    const realtimeChart = new Chart(ctx, chartConfig);

    // Chart controls
    let isPaused = false;
    const toggleRealtimeBtn = document.getElementById('toggle-realtime');
    const chartTypeSelect = document.getElementById('chart-type');

    toggleRealtimeBtn.addEventListener('click', function() {
        isPaused = !isPaused;
        this.textContent = isPaused ? 'Resume' : 'Pause';
    });

    chartTypeSelect.addEventListener('change', function() {
        realtimeChart.config.type = this.value;
        realtimeChart.update();
    });

    // Form handling
    const dataForm = document.getElementById('data-form');
    const dataTable = document.getElementById('data-table').getElementsByTagName('tbody')[0];

    dataForm.addEventListener('submit', function(e) {
        e.preventDefault();

        const label = document.getElementById('data-label').value;
        const value = parseFloat(document.getElementById('data-value').value);
        const category = document.getElementById('data-category').value;
        const timestamp = new Date().toLocaleString();

        // Add data to chart
        if (!isPaused) {
            const now = new Date();
            const timeString = now.toLocaleTimeString();

            // Keep only the last 20 data points
            if (chartData.labels.length > 20) {
                chartData.labels.shift();
                chartData.datasets[0].data.shift();
            }

            chartData.labels.push(timeString);
            chartData.datasets[0].data.push(value);
            realtimeChart.update();
        }

        // Add data to table
        const newRow = dataTable.insertRow();
        newRow.innerHTML = `
            <td>${timestamp}</td>
            <td>${label}</td>
            <td>${value}</td>
            <td>${category}</td>
        `;

        // Scroll table to show new entry
        dataTable.parentNode.scrollTop = dataTable.parentNode.scrollHeight;

        // Reset form
        dataForm.reset();
    });

    // Simulate real-time data (for demonstration)
    setInterval(function() {
        if (!isPaused) {
            const randomValue = Math.floor(Math.random() * 100) + 1;
            const now = new Date();
            const timeString = now.toLocaleTimeString();

            // Keep only the last 20 data points
            if (chartData.labels.length > 20) {
                chartData.labels.shift();
                chartData.datasets[0].data.shift();
            }

            chartData.labels.push(timeString);
            chartData.datasets[0].data.push(randomValue);
            realtimeChart.update();

            // Add to table
            const newRow = dataTable.insertRow();
            newRow.innerHTML = `
                <td>${now.toLocaleString()}</td>
                <td>Auto Data</td>
                <td>${randomValue}</td>
                <td>Auto</td>
            `;

            // Scroll table to show new entry
            dataTable.parentNode.scrollTop = dataTable.parentNode.scrollHeight;
        }
    }, 5000);
});

// Update date and time display
function updateDateTime() {
    const now = new Date();
    document.getElementById('current-date').textContent = now.toLocaleDateString();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}
