## JavaScript Functionality (script.js)

```javascript
// Initialize dashboard data
let dashboardData = {
    sales: [],
    revenue: [],
    users: [],
    labels: []
};

// DOM elements
const dataForm = document.getElementById('data-form');
const dataTableBody = document.querySelector('#data-table tbody');
const mainChartCtx = document.getElementById('main-chart').getContext('2d');
const totalSalesEl = document.getElementById('total-sales');
const totalRevenueEl = document.getElementById('total-revenue');
const activeUsersEl = document.getElementById('active-users');
const currentDateEl = document.getElementById('current-date');
const currentTimeEl = document.getElementById('current-time');

// Initialize Chart
let mainChart = new Chart(mainChartCtx, {
    type: 'bar',
    data: {
        labels: [],
        datasets: [
            {
                label: 'Sales',
                data: [],
                backgroundColor: 'rgba(52, 152, 219, 0.7)',
                borderColor: 'rgba(52, 152, 219, 1)',
                borderWidth: 1
            },
            {
                label: 'Revenue',
                data: [],
                backgroundColor: 'rgba(46, 204, 113, 0.7)',
                borderColor: 'rgba(46, 204, 113, 1)',
                borderWidth: 1
            },
            {
                label: 'Users',
                data: [],
                backgroundColor: 'rgba(155, 89, 182, 0.7)',
                borderColor: 'rgba(155, 89, 182, 1)',
                borderWidth: 1
            }
        ]
    },
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Update date and time
function updateDateTime() {
    const now = new Date();
    currentDateEl.textContent = now.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
    });
    currentTimeEl.textContent = now.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
    });
}

// Update summary cards
function updateSummaryCards() {
    const totalSales = dashboardData.sales.reduce((sum, val) => sum + val, 0);
    const totalRevenue = dashboardData.revenue.reduce((sum, val) => sum + val, 0);
    const totalUsers = dashboardData.users.reduce((sum, val) => sum + val, 0);

    totalSalesEl.textContent = `$${totalSales.toLocaleString()}`;
    totalRevenueEl.textContent = `$${totalRevenue.toLocaleString()}`;
    activeUsersEl.textContent = totalUsers.toLocaleString();
}

// Update chart data
function updateChart() {
    mainChart.data.labels = dashboardData.labels;
    mainChart.data.datasets[0].data = dashboardData.sales;
    mainChart.data.datasets[1].data = dashboardData.revenue;
    mainChart.data.datasets[2].data = dashboardData.users;
    mainChart.update();
}

// Add new data entry to table
function addDataToTable(label, value, category, timestamp) {
    const row = document.createElement('tr');
    row.innerHTML = `
        <td>${label}</td>
        <td>${value}</td>
        <td>${category}</td>
        <td>${timestamp}</td>
    `;
    dataTableBody.prepend(row);

    // Limit table rows to 10
    if (dataTableBody.children.length > 10) {
        dataTableBody.removeChild(dataTableBody.lastChild);
    }
}

// Handle form submission
dataForm.addEventListener('submit', function(e) {
    e.preventDefault();

    const label = document.getElementById('data-label').value;
    const value = parseFloat(document.getElementById('data-value').value);
    const category = document.getElementById('data-category').value;
    const timestamp = new Date().toLocaleString();

    // Add data to appropriate array
    dashboardData.labels.push(label);
    dashboardData[category].push(value);

    // Add to table
    addDataToTable(label, value, category, timestamp);

    // Update dashboard
    updateChart();
    updateSummaryCards();

    // Reset form
    dataForm.reset();

    // Limit data points to 10
    if (dashboardData.labels.length > 10) {
        dashboardData.labels.shift();
        dashboardData.sales.shift();
        dashboardData.revenue.shift();
        dashboardData.users.shift();
    }
});

// Initialize dashboard
function initDashboard() {
    // Update date and time every second
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Add some initial data
    const initialData = [
        { label: 'Jan', sales: 1200, revenue: 15000, users: 500 },
        { label: 'Feb', sales: 1900, revenue: 22000, users: 700 },
        { label: 'Mar', sales: 3000, revenue: 35000, users: 1200 }
    ];

    initialData.forEach(item => {
        dashboardData.labels.push(item.label);
        dashboardData.sales.push(item.sales);
        dashboardData.revenue.push(item.revenue);
        dashboardData.users.push(item.users);

        addDataToTable(
            item.label,
            item.sales,
            'sales',
            new Date().toLocaleString()
        );
    });

    updateChart();
    updateSummaryCards();
}

// Start the dashboard
initDashboard();
```

