## JavaScript Functionality (script.js)

```javascript
// Dashboard initialization
document.addEventListener('DOMContentLoaded', function() {
    // Update current date and time
    updateDateTime();
    setInterval(updateDateTime, 1000);

    // Initialize chart
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    let chartType = 'line';
    let currentDataSource = 'sales';

    // Sample data
    let chartData = {
        labels: generateTimeLabels(20),
        datasets: [{
            label: 'Sales Data',
            data: generateRandomData(20, 100, 500),
            borderColor: 'rgba(52, 152, 219, 1)',
            backgroundColor: 'rgba(52, 152, 219, 0.2)',
            tension: 0.1,
            fill: true
        }]
    };

    // Create chart
    const realtimeChart = new Chart(ctx, {
        type: chartType,
        data: chartData,
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: true
                }
            }
        }
    });

    // Update chart with new data
    function updateChart() {
        // Remove first element and add new one
        chartData.labels.shift();
        chartData.labels.push(getCurrentTime());

        chartData.datasets[0].data.shift();
        chartData.datasets[0].data.push(getRandomValue(100, 500));

        realtimeChart.update();
    }

    // Simulate real-time updates
    setInterval(updateChart, 3000);

    // Toggle chart type
    document.getElementById('toggleChart').addEventListener('click', function() {
        chartType = chartType === 'line' ? 'bar' : 'line';
        realtimeChart.config.type = chartType;
        realtimeChart.update();
    });

    // Change data source
    document.getElementById('dataSource').addEventListener('change', function() {
        currentDataSource = this.value;

        // Update chart title and data
        switch(currentDataSource) {
            case 'sales':
                realtimeChart.data.datasets[0].label = 'Sales Data';
                realtimeChart.data.datasets[0].borderColor = 'rgba(52, 152, 219, 1)';
                realtimeChart.data.datasets[0].backgroundColor = 'rgba(52, 152, 219, 0.2)';
                break;
            case 'traffic':
                realtimeChart.data.datasets[0].label = 'Website Traffic';
                realtimeChart.data.datasets[0].borderColor = 'rgba(46, 204, 113, 1)';
                realtimeChart.data.datasets[0].backgroundColor = 'rgba(46, 204, 113, 0.2)';
                break;
            case 'temperature':
                realtimeChart.data.datasets[0].label = 'Temperature (°C)';
                realtimeChart.data.datasets[0].borderColor = 'rgba(231, 76, 60, 1)';
                realtimeChart.data.datasets[0].backgroundColor = 'rgba(231, 76, 60, 0.2)';
                break;
        }

        // Generate new data for the selected source
        realtimeChart.data.datasets[0].data = generateRandomData(20,
            currentDataSource === 'temperature' ? 10 : 100,
            currentDataSource === 'temperature' ? 30 : 500);

        realtimeChart.update();
    });

    // Handle form submission
    document.getElementById('dataForm').addEventListener('submit', function(e) {
        e.preventDefault();

        const formData = new FormData(this);
        const formResponse = document.getElementById('formResponse');

        // Simulate API call
        setTimeout(() => {
            // In a real application, you would send this to your backend
            console.log('Form data submitted:', {
                dataType: formData.get('dataType'),
                dataValue: formData.get('dataValue'),
                dataTimestamp: formData.get('dataTimestamp')
            });

            // Show success message
            formResponse.textContent = 'Data submitted successfully!';
            formResponse.className = 'form-response success';

            // Reset form
            this.reset();

            // Hide message after 3 seconds
            setTimeout(() => {
                formResponse.style.display = 'none';
            }, 3000);
        }, 500);
    });
});

// Helper functions
function updateDateTime() {
    const now = new Date();
    document.getElementById('currentDateTime').textContent = now.toLocaleString();
}

function generateTimeLabels(count) {
    const labels = [];
    const now = new Date();

    for (let i = count - 1; i >= 0; i--) {
        const date = new Date(now.getTime() - i * 3000);
        labels.push(date.toLocaleTimeString());
    }

    return labels;
}

function generateRandomData(count, min, max) {
    const data = [];
    for (let i = 0; i < count; i++) {
        data.push(getRandomValue(min, max));
    }
    return data;
}

function getRandomValue(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function getCurrentTime() {
    return new Date().toLocaleTimeString();
}
