## JavaScript (script.js)

```javascript
// Initialize chart
let dataChart;
const ctx = document.getElementById('data-chart').getContext('2d');

// Sample data generators
function generateTemperatureData(points) {
    const data = [];
    const now = new Date();
    const baseTemp = 20 + Math.random() * 10;

    for (let i = 0; i < points; i++) {
        const time = new Date(now - (points - i) * 3600000);
        const value = baseTemp + Math.sin(i * 0.5) * 3 + Math.random() * 2;
        data.push({ time, value: parseFloat(value.toFixed(1)) });
    }

    return data;
}

function generateHumidityData(points) {
    const data = [];
    const now = new Date();
    const baseHumidity = 40 + Math.random() * 20;

    for (let i = 0; i < points; i++) {
        const time = new Date(now - (points - i) * 3600000);
        const value = baseHumidity + Math.sin(i * 0.3) * 5 + Math.random() * 3;
        data.push({ time, value: parseFloat(value.toFixed(1)) });
    }

    return data;
}

function generatePressureData(points) {
    const data = [];
    const now = new Date();
    const basePressure = 1010 + Math.random() * 10;

    for (let i = 0; i < points; i++) {
        const time = new Date(now - (points - i) * 3600000);
        const value = basePressure + Math.sin(i * 0.2) * 2 + Math.random() * 1;
        data.push({ time, value: parseFloat(value.toFixed(1)) });
    }

    return data;
}

// Update time display
function updateTime() {
    const now = new Date();
    document.getElementById('current-time').textContent = now.toLocaleTimeString();
}

// Update chart with new data
function updateChart(dataType, timeRange) {
    let data;
    let points;

    // Determine number of data points based on time range
    switch (timeRange) {
        case '1h':
            points = 60;
            break;
        case '6h':
            points = 360;
            break;
        case '12h':
            points = 720;
            break;
        case '24h':
            points = 1440;
            break;
        default:
            points = 60;
    }

    // Generate appropriate data
    switch (dataType) {
        case 'temperature':
            data = generateTemperatureData(points);
            break;
        case 'humidity':
            data = generateHumidityData(points);
            break;
        case 'pressure':
            data = generatePressureData(points);
            break;
        default:
            data = generateTemperatureData(points);
    }

    // Calculate statistics
    const values = data.map(item => item.value);
    const currentValue = values[values.length - 1];
    const average = values.reduce((a, b) => a + b, 0) / values.length;
    const max = Math.max(...values);
    const min = Math.min(...values);

    // Update statistics display
    document.getElementById('current-value').textContent = `${currentValue} ${getUnit(dataType)}`;
    document.getElementById('average-value').textContent = `${average.toFixed(1)} ${getUnit(dataType)}`;
    document.getElementById('max-value').textContent = `${max} ${getUnit(dataType)}`;
    document.getElementById('min-value').textContent = `${min} ${getUnit(dataType)}`;

    // Destroy previous chart if it exists
    if (dataChart) {
        dataChart.destroy();
    }

    // Create new chart
    dataChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: data.map(item => item.time.toLocaleTimeString()),
            datasets: [{
                label: getLabel(dataType),
                data: data.map(item => item.value),
                borderColor: getColor(dataType),
                backgroundColor: getColor(dataType).replace('1)', '0.2)'),
                tension: 0.3,
                fill: true,
                borderWidth: 2,
                pointRadius: 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    title: {
                        display: true,
                        text: 'Time'
                    }
                },
                y: {
                    title: {
                        display: true,
                        text: getUnit(dataType)
                    }
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            return `${context.dataset.label}: ${context.raw} ${getUnit(dataType)}`;
                        }
                    }
                }
            }
        }
    });
}

// Helper functions
function getLabel(dataType) {
    switch (dataType) {
        case 'temperature': return 'Temperature';
        case 'humidity': return 'Humidity';
        case 'pressure': return 'Pressure';
        default: return 'Value';
    }
}

function getUnit(dataType) {
    switch (dataType) {
        case 'temperature': return '°C';
        case 'humidity': return '%';
        case 'pressure': return 'hPa';
        default: return '';
    }
}

function getColor(dataType) {
    switch (dataType) {
        case 'temperature': return 'rgba(255, 99, 132, 1)';
        case 'humidity': return 'rgba(54, 162, 235, 1)';
        case 'pressure': return 'rgba(75, 192, 192, 1)';
        default: return 'rgba(153, 102, 255, 1)';
    }
}

// Form submission handler
document.getElementById('data-form').addEventListener('submit', function(e) {
    e.preventDefault();
    const dataType = document.getElementById('data-type').value;
    const timeRange = document.getElementById('time-range').value;
    updateChart(dataType, timeRange);
});

// Initialize dashboard
document.addEventListener('DOMContentLoaded', function() {
    // Update time every second
    updateTime();
    setInterval(updateTime, 1000);

    // Initialize with default values
    updateChart('temperature', '1h');
});
