```javascript
// Initialize chart
const ctx = document.getElementById('dataChart').getContext('2d');
const dataChart = new Chart(ctx, {
    type: 'line',
    data: {
        labels: ['Initial'],
        datasets: [{
            label: 'Data Values',
            data: [0],
            backgroundColor: 'rgba(75, 192, 192, 0.2)',
            borderColor: 'rgba(75, 192, 192, 1)',
            borderWidth: 2,
            tension: 0.1
        }]
    },
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Simulate WebSocket connection
const connectionStatus = document.getElementById('connection-status');
let isConnected = false;

// Simulate connection status
function updateConnectionStatus() {
    if (isConnected) {
        connectionStatus.textContent = 'Connected';
        connectionStatus.style.color = 'green';
    } else {
        connectionStatus.textContent = 'Disconnected';
        connectionStatus.style.color = 'red';
    }
}

// Simulate real-time data updates
function simulateRealTimeData() {
    if (!isConnected) return;

    // Generate random data point
    const newValue = Math.floor(Math.random() * 100);
    const newLabel = new Date().toLocaleTimeString();

    // Update chart
    dataChart.data.labels.push(newLabel);
    dataChart.data.datasets[0].data.push(newValue);

    // Limit to 20 data points
    if (dataChart.data.labels.length > 20) {
        dataChart.data.labels.shift();
        dataChart.data.datasets[0].data.shift();
    }

    dataChart.update();

    // Call again after random interval (1-5 seconds)
    setTimeout(simulateRealTimeData, Math.random() * 4000 + 1000);
}

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const valueInput = document.getElementById('dataValue');
    const labelInput = document.getElementById('dataLabel');

    const newValue = parseFloat(valueInput.value);
    const newLabel = labelInput.value || new Date().toLocaleTimeString();

    // Update chart with form data
    dataChart.data.labels.push(newLabel);
    dataChart.data.datasets[0].data.push(newValue);

    // Limit to 20 data points
    if (dataChart.data.labels.length > 20) {
        dataChart.data.labels.shift();
        dataChart.data.datasets[0].data.shift();
    }

    dataChart.update();

    // Reset form
    valueInput.value = '';
    labelInput.value = '';
});

// Simulate connection after 1 second
setTimeout(() => {
    isConnected = true;
    updateConnectionStatus();
    simulateRealTimeData();
}, 1000);

// Simulate occasional disconnections
setInterval(() => {
    isConnected = !isConnected;
    updateConnectionStatus();

    if (isConnected) {
        simulateRealTimeData();
    }
}, 15000);
