    labels: ['Initial', 'Data', 'Points'],
    datasets: [{
        label: 'Live Data',
        data: [10, 20, 30],
        backgroundColor: 'rgba(52, 152, 219, 0.5)',
        borderColor: 'rgba(52, 152, 219, 1)',
        borderWidth: 2,
        tension: 0.1
    }]
};

const liveChart = new Chart(ctx, {
    type: 'line',
    data: chartData,
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        },
        animation: {
            duration: 1000
        }
    }
});

// Form submission handler
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const value = parseFloat(document.getElementById('dataValue').value);
    const label = document.getElementById('dataLabel').value;

    if (!isNaN(value) && label) {
        // Update chart data
        liveChart.data.labels.push(label);
        liveChart.data.datasets[0].data.push(value);

        // Limit to last 10 data points
        if (liveChart.data.labels.length > 10) {
            liveChart.data.labels.shift();
            liveChart.data.datasets[0].data.shift();
        }

        liveChart.update();

        // Reset form
        document.getElementById('dataValue').value = '';
        document.getElementById('dataLabel').value = '';

        // Show success message
        alert('Data added successfully!');
    } else {
        alert('Please enter valid data');
    }
});

// Simulate real-time data updates
function simulateRealTimeData() {
    setInterval(() => {
        const randomValue = Math.floor(Math.random() * 50) + 1;
        const timestamp = new Date().toLocaleTimeString();

        liveChart.data.labels.push(timestamp);
        liveChart.data.datasets[0].data.push(randomValue);

        if (liveChart.data.labels.length > 10) {
            liveChart.data.labels.shift();
            liveChart.data.datasets[0].data.shift();
        }

        liveChart.update();
    }, 3000);
}

// Start simulation
simulateRealTimeData();
```

