// Initialize chart
const ctx = document.getElementById('dataChart').getContext('2d');
let dataChart = new Chart(ctx, {
    type: 'line',
    data: {
        labels: [],
        datasets: [{
            label: 'Data Points',
            data: [],
            borderColor: 'rgb(52, 152, 219)',
            backgroundColor: 'rgba(52, 152, 219, 0.1)',
            tension: 0.1,
            fill: true
        }]
    },
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Simulate WebSocket connection
const connectionStatus = document.getElementById('connection-status');
let isConnected = false;

// Simulate connection status
function updateConnectionStatus() {
    if (isConnected) {
        connectionStatus.textContent = 'Connected';
        connectionStatus.style.color = '#27ae60';
    } else {
        connectionStatus.textContent = 'Disconnected';
        connectionStatus.style.color = '#e74c3c';
    }
}

// Simulate real-time data updates
function simulateDataUpdate() {
    if (!isConnected) return;

    // Generate random data point
    const value = Math.floor(Math.random() * 100) + 1;
    const label = `Auto ${new Date().toLocaleTimeString()}`;

    // Update chart
    dataChart.data.labels.push(label);
    dataChart.data.datasets[0].data.push(value);

    // Limit to 20 data points
    if (dataChart.data.labels.length > 20) {
        dataChart.data.labels.shift();
        dataChart.data.datasets[0].data.shift();
    }

    dataChart.update();
}

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const valueInput = document.getElementById('dataValue');
    const labelInput = document.getElementById('dataLabel');

    const value = parseFloat(valueInput.value);
    const label = labelInput.value.trim();

    if (isNaN(value) || label === '') {
        alert('Please enter valid data');
        return;
    }

    // Update chart with form data
    dataChart.data.labels.push(label);
    dataChart.data.datasets[0].data.push(value);

    // Limit to 20 data points
    if (dataChart.data.labels.length > 20) {
        dataChart.data.labels.shift();
        dataChart.data.datasets[0].data.shift();
    }

    dataChart.update();

    // Reset form
    valueInput.value = '';
    labelInput.value = '';
});

// Simulate connection/disconnection
function toggleConnection() {
    isConnected = !isConnected;
    updateConnectionStatus();
}

// Initial setup
updateConnectionStatus();
setInterval(simulateDataUpdate, 3000); // Simulate data every 3 seconds
setInterval(toggleConnection, 15000); // Toggle connection every 15 seconds
```

