```javascript
// Sample initial data
let dashboardData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [
        {
            label: 'Sales',
            data: [120, 190, 300, 500, 200, 300],
            backgroundColor: 'rgba(75, 192, 192, 0.2)',
            borderColor: 'rgba(75, 192, 192, 1)',
            borderWidth: 1
        },
        {
            label: 'Users',
            data: [50, 80, 120, 150, 90, 110],
            backgroundColor: 'rgba(153, 102, 255, 0.2)',
            borderColor: 'rgba(153, 102, 255, 1)',
            borderWidth: 1
        }
    ]
};

// Initialize chart
const ctx = document.getElementById('dataChart').getContext('2d');
const dataChart = new Chart(ctx, {
    type: 'bar',
    data: dashboardData,
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: true
            }
        }
    }
});

// Form handling
const dataForm = document.getElementById('dataForm');
const formStatus = document.getElementById('formStatus');

dataForm.addEventListener('submit', function(e) {
    e.preventDefault();

    // Get form values
    const dataType = document.getElementById('dataType').value;
    const value = parseFloat(document.getElementById('value').value);
    const date = new Date(document.getElementById('date').value);

    // Validate date is within current year
    const currentYear = new Date().getFullYear();
    if (date.getFullYear() !== currentYear) {
        showStatus('Error: Please select a date within the current year.', 'error');
        return;
    }

    // Update chart data
    const month = date.toLocaleString('default', { month: 'short' });
    const monthIndex = dashboardData.labels.indexOf(month);

    if (monthIndex === -1) {
        showStatus('Error: Only months from Jan to Jun are supported in this demo.', 'error');
        return;
    }

    // Find or create dataset
    let dataset = dashboardData.datasets.find(ds => ds.label.toLowerCase() === dataType);

    if (!dataset) {
        // Create new dataset with random color
        const randomColor = `rgba(${Math.floor(Math.random() * 255)}, ${Math.floor(Math.random() * 255)}, ${Math.floor(Math.random() * 255)}, 0.2)`;
        const randomBorderColor = `rgba(${Math.floor(Math.random() * 255)}, ${Math.floor(Math.random() * 255)}, ${Math.floor(Math.random() * 255)}, 1)`;

        dataset = {
            label: dataType.charAt(0).toUpperCase() + dataType.slice(1),
            data: [0, 0, 0, 0, 0, 0],
            backgroundColor: randomColor,
            borderColor: randomBorderColor,
            borderWidth: 1
        };
        dashboardData.datasets.push(dataset);
    }

    // Update the specific month's data
    dataset.data[monthIndex] = value;

    // Update chart
    dataChart.update();

    // Show success message
    showStatus(`Successfully added ${value} to ${dataType} for ${month}.`, 'success');

    // Reset form
    dataForm.reset();
});

// Refresh button
document.getElementById('refreshBtn').addEventListener('click', function() {
    // Simulate fetching new data
    dashboardData.datasets.forEach(dataset => {
        dataset.data = dataset.data.map(value => Math.floor(value * (0.8 + Math.random() * 0.4)));
    });

    dataChart.update();
    showStatus('Data refreshed with simulated new values.', 'success');
});

// Helper function to show status messages
function showStatus(message, type) {
    formStatus.textContent = message;
    formStatus.className = `status ${type}`;
    formStatus.style.display = 'block';

    // Hide after 3 seconds
    setTimeout(() => {
        formStatus.style.display = 'none';
    }, 3000);
}

// Simulate real-time updates
setInterval(() => {
    // Randomly update one data point
    const randomDatasetIndex = Math.floor(Math.random() * dashboardData.datasets.length);
    const randomMonthIndex = Math.floor(Math.random() * dashboardData.labels.length);
    const randomChange = Math.floor(Math.random() * 50) - 25; // -25 to +25

    const currentValue = dashboardData.datasets[randomDatasetIndex].data[randomMonthIndex];
    const newValue = Math.max(0, currentValue + randomChange);

    dashboardData.datasets[randomDatasetIndex].data[randomMonthIndex] = newValue;
    dataChart.update();
}, 5000);
```

