        const formData = new FormData(form);
        const data = {
            name: formData.get('dataName'),
            value: parseFloat(formData.get('dataValue'))
        };

        // Simulate API call
        setTimeout(() => {
            // Add to chart
            realtimeChart.data.labels.push(data.name);
            realtimeChart.data.datasets[0].data.push(data.value);
