        statusElement.style.color = "green";
    } else {
        statusElement.textContent = "Disconnected";
        statusElement.style.color = "red";
    }
}

// Simulate receiving data
function simulateDataUpdate() {
    if (!isConnected) return;

    const categories = ['A', 'B', 'C'];
    const randomCategory = categories[Math.floor(Math.random() * categories.length)];
    const randomValue = Math.floor(Math.random() * 100);

    addDataToChart(randomCategory, randomValue);
}

// Add data to chart
function addDataToChart(category, value) {
    const now = new Date();
    const timeString = now.toLocaleTimeString();

    // Update chart data
    dataChart.data.labels.push(timeString);

    // Find the dataset index for the category
    const datasetIndex = dataChart.data.datasets.findIndex(ds =>
        ds.label === `Category ${category}`
    );

    if (datasetIndex !== -1) {
        dataChart.data.datasets[datasetIndex].data.push(value);
    }

    // Limit data points to 20 for better performance
    if (dataChart.data.labels.length > 20) {
        dataChart.data.labels.shift();
        dataChart.data.datasets.forEach(dataset => {
            dataset.data.shift();
        });
    }

    dataChart.update();
}

// Form handling
