    isConnected = !isConnected;
    updateConnectionStatus();

    if (isConnected) {
        // Start data simulation
        dataUpdateInterval = setInterval(simulateDataUpdate, 2000);
    } else {
        // Stop data simulation
        clearInterval(dataUpdateInterval);
    }
}

