    type: 'line',
    data: {
        labels: [],
        datasets: [{
            label: 'Temperature (°C)',
            data: [],
            borderColor: 'rgb(255, 99, 132)',
            backgroundColor: 'rgba(255, 99, 132, 0.1)',
            tension: 0.1,
            borderWidth: 2,
            pointRadius: 3
        }]
    },
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: false
            }
        }
    }
});

// Simulate WebSocket connection
let socket = {
    onmessage: null,
    close: function() {}
};

// Data storage
let dataPoints = [];
const maxDataPoints = 20;
let updateInterval = 1000;
let currentDataType = 'temperature';

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    // Update settings
    currentDataType = document.getElementById('dataType').value;
    updateInterval = parseInt(document.getElementById('updateInterval').value);

    // Update chart label
    dataChart.data.datasets[0].label = getDataLabel(currentDataType);
    dataChart.update();

    // Restart data simulation
    stopDataSimulation();
    startDataSimulation();
});

// Helper function to get appropriate label
function getDataLabel(dataType) {
    const labels = {
        'temperature': 'Temperature (°C)',
        'humidity': 'Humidity (%)',
        'pressure': 'Pressure (hPa)'
    };
    return labels[dataType] || dataType;
}

// Simulate data generation
function generateData() {
    let value;

    switch(currentDataType) {
        case 'temperature':
            value = 20 + Math.random() * 10; // 20-30°C
            break;
        case 'humidity':
            value = 40 + Math.random() * 30; // 40-70%
            break;
        case 'pressure':
            value = 1000 + Math.random() * 50; // 1000-1050 hPa
            break;
        default:
            value = Math.random() * 100;
    }

    return Math.round(value * 10) / 10; // Round to 1 decimal
}

// Update chart with new data
function updateChart(newValue) {
    const now = new Date();
    const timeString = now.toLocaleTimeString();

    // Add new data point
    dataPoints.push({ time: timeString, value: newValue });

    // Keep only the most recent points
    if (dataPoints.length > maxDataPoints) {
        dataPoints.shift();
    }

    // Update chart
    dataChart.data.labels = dataPoints.map(point => point.time);
    dataChart.data.datasets[0].data = dataPoints.map(point => point.value);
    dataChart.update();
}

// Simulate WebSocket message
function simulateWebSocketMessage() {
    const newValue = generateData();

    // Simulate WebSocket message event
    if (socket.onmessage) {
        socket.onmessage({ data: JSON.stringify({
            type: currentDataType,
            value: newValue,
            timestamp: new Date().toISOString()
        }) });
    }

    // Update chart directly for demo purposes
    updateChart(newValue);
}

// Start data simulation
