```javascript
// Initialize chart
let dataChart;
const ctx = document.getElementById('dataChart').getContext('2d');

// Generate random data for demonstration
function generateRandomData(type, count) {
    const data = [];
    const labels = [];
    const now = new Date();

    for (let i = 0; i < count; i++) {
        const time = new Date(now.getTime() - (count - i) * 60000); // 1 minute intervals
        labels.push(time.toLocaleTimeString());

        // Generate different data based on type
        switch(type) {
            case 'temperature':
                data.push(20 + Math.random() * 10); // 20-30°C
                break;
            case 'humidity':
                data.push(40 + Math.random() * 20); // 40-60%
                break;
            case 'pressure':
                data.push(980 + Math.random() * 40); // 980-1020 hPa
                break;
        }
    }

    return { labels, data };
}

// Update the chart with new data
function updateChart(type, timeRange) {
    // Determine number of data points based on time range
    let count;
    switch(timeRange) {
        case '1h': count = 60; break;
        case '6h': count = 360; break;
        case '24h': count = 1440; break;
        default: count = 60;
    }

    const { labels, data } = generateRandomData(type, count);

    // Destroy previous chart if it exists
    if (dataChart) {
        dataChart.destroy();
    }

    // Create new chart
    dataChart = new Chart(ctx, {
        type: 'line',
        data: {
            labels: labels,
            datasets: [{
                label: type.charAt(0).toUpperCase() + type.slice(1),
                data: data,
                borderColor: '#3498db',
                backgroundColor: 'rgba(52, 152, 219, 0.1)',
                borderWidth: 2,
                tension: 0.3,
                fill: true
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                y: {
                    beginAtZero: false
                }
            },
            plugins: {
                legend: {
                    position: 'top',
                },
                tooltip: {
                    mode: 'index',
                    intersect: false,
                }
            }
        }
    });

    // Update last updated time
    document.getElementById('lastUpdated').textContent = new Date().toLocaleString();
}

// Handle form submission
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('dataType').value;
    const timeRange = document.getElementById('timeRange').value;

    updateChart(dataType, timeRange);
});

// Initialize with default values
document.addEventListener('DOMContentLoaded', function() {
    updateChart('temperature', '1h');

    // Simulate real-time updates every 5 seconds
    setInterval(() => {
        const dataType = document.getElementById('dataType').value;
        const timeRange = document.getElementById('timeRange').value;
        updateChart(dataType, timeRange);
    }, 5000);
});
```

