## JavaScript (app.js)

```javascript
// Initialize chart
const ctx = document.getElementById('realtimeChart').getContext('2d');
let chartData = {
    labels: [],
    datasets: [{
        label: 'Temperature (°C)',
        data: [],
        borderColor: 'rgb(255, 99, 132)',
        backgroundColor: 'rgba(255, 99, 132, 0.2)',
        tension: 0.1
    }]
};

const realtimeChart = new Chart(ctx, {
    type: 'line',
    data: chartData,
    options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
            y: {
                beginAtZero: false
            }
        }
    }
});

// Data storage
let allData = [];
let isStreaming = false;
let dataStreamInterval;

// Form handling
document.getElementById('dataForm').addEventListener('submit', function(e) {
    e.preventDefault();

    const dataType = document.getElementById('dataType').value;
    const value = parseFloat(document.getElementById('value').value);
    const timestamp = new Date(document.getElementById('timestamp').value);

    // Add to data storage
    allData.push({
        type: dataType,
        value: value,
        timestamp: timestamp
    });

    // Update chart if it's the right type
    if (dataType === 'temperature') {
        updateChart(dataType, value, timestamp);
    }

    // Update recent entries
    updateRecentEntries();

    // Update summary stats
    updateSummaryStats();

    // Reset form
    this.reset();
});

// Toggle data stream
document.getElementById('toggleData').addEventListener('click', function() {
    isStreaming = !isStreaming;
    this.textContent = isStreaming ? 'Stop Data Stream' : 'Start Data Stream';

    if (isStreaming) {
        startDataStream();
    } else {
        stopDataStream();
    }
});

// Start simulated data stream
function startDataStream() {
    dataStreamInterval = setInterval(() => {
        const randomValue = Math.random() * 30 + 10; // Random temp between 10-40°C
        const timestamp = new Date();

        allData.push({
            type: 'temperature',
            value: randomValue,
            timestamp: timestamp
        });

        updateChart('temperature', randomValue, timestamp);
        updateRecentEntries();
        updateSummaryStats();
    }, 2000);
}

// Stop data stream
function stopDataStream() {
    clearInterval(dataStreamInterval);
}

// Update chart with new data
function updateChart(type, value, timestamp) {
    if (type !== 'temperature') return;

    // Add new data point
    chartData.labels.push(timestamp.toLocaleTimeString());
    chartData.datasets[0].data.push(value);

    // Limit to last 20 points
    if (chartData.labels.length > 20) {
        chartData.labels.shift();
        chartData.datasets[0].data.shift();
    }

    realtimeChart.update();
}

// Update recent entries display
function updateRecentEntries() {
    const container = document.getElementById('recentEntries');
    container.innerHTML = '';

    // Show last 5 entries
    const recent = allData.slice(-5).reverse();

    recent.forEach(entry => {
        const div = document.createElement('div');
        div.style.padding = '8px';
        div.style.borderBottom = '1px solid #eee';
        div.innerHTML = `
            <strong>${entry.type}</strong>: ${entry.value.toFixed(1)}
            <br><small>${entry.timestamp.toLocaleString()}</small>
        `;
        container.appendChild(div);
    });
}

// Update summary statistics
function updateSummaryStats() {
    const container = document.getElementById('summaryStats');
    container.innerHTML = '';

    if (allData.length === 0) {
        container.innerHTML = '<p>No data available</p>';
        return;
    }

    // Calculate stats for each data type
    const types = [...new Set(allData.map(item => item.type))];

    types.forEach(type => {
        const typeData = allData.filter(item => item.type === type).map(item => item.value);
        const avg = typeData.reduce((a, b) => a + b, 0) / typeData.length;
        const min = Math.min(...typeData);
        const max = Math.max(...typeData);

        const div = document.createElement('div');
        div.style.marginBottom = '15px';
        div.innerHTML = `
            <h3>${type.charAt(0).toUpperCase() + type.slice(1)}</h3>
            <p>Count: ${typeData.length}</p>
            <p>Average: ${avg.toFixed(1)}</p>
            <p>Min: ${min.toFixed(1)}</p>
            <p>Max: ${max.toFixed(1)}</p>
        `;
        container.appendChild(div);
    });
}

// Initialize with some sample data
function initializeSampleData() {
    const now = new Date();
    const sampleData = [
        { type: 'temperature', value: 22.5, timestamp: new Date(now - 1000*60*5) },
        { type: 'temperature', value: 23.1, timestamp: new Date(now - 1000*60*4) },
        { type: 'temperature', value: 21.8, timestamp: new Date(now - 1000*60*3) },
        { type: 'humidity', value: 45.2, timestamp: new Date(now - 1000*60*2) },
        { type: 'humidity', value: 46.7, timestamp: new Date(now - 1000*60*1) }
    ];

    allData.push(...sampleData);

    // Update chart with sample temperature data
    sampleData.filter(item => item.type === 'temperature').forEach(item => {
        updateChart(item.type, item.value, item.timestamp);
    });

    updateRecentEntries();
    updateSummaryStats();
}

// Initialize the dashboard
initializeSampleData();
```

