// Initialize chart
const ctx = document.getElementById('dataChart').getContext('2d');
let dataChart = new Chart(ctx, {
    type: 'line',
    data: {
        labels: [],
        datasets: [{
            label: 'Temperature (°C)',
            data: [],
            borderColor: 'rgb(255, 99, 132)',
            backgroundColor: 'rgba(255, 99, 132, 0.1)',
            tension: 0.1
        }, {
            label: 'Humidity (%)',
            data: [],
            borderColor: 'rgb(54, 162, 235)',
            backgroundColor: 'rgba(54, 162, 235, 0.1)',
            tension: 0.1
        }, {
            label: 'Pressure (hPa)',
            data: [],
            borderColor: 'rgb(75, 192, 192)',
            backgroundColor: 'rgba(75, 192, 192, 0.1)',
            tension: 0.1
        }]
    },
    options: {
        responsive: true,
        scales: {
            y: {
                beginAtZero: false
            }
        }
    }
});

// Form handling
const form = document.getElementById('dataForm');
const statusMessage = document.getElementById('statusMessage');

form.addEventListener('submit', function(e) {
    e.preventDefault();

    // Get form values
    const dataType = document.getElementById('dataType').value;
    const value = parseFloat(document.getElementById('value').value);
    const timestamp = new Date(document.getElementById('timestamp').value);

    // Validate
    if (isNaN(value) || !timestamp) {
        showStatus('Please enter valid data', 'error');
        return;
    }

    // Add data to chart
    const formattedTime = timestamp.toLocaleTimeString();
    dataChart.data.labels.push(formattedTime);

    // Update the appropriate dataset
    const datasetIndex = getDatasetIndex(dataType);
    if (datasetIndex !== -1) {
        dataChart.data.datasets[datasetIndex].data.push(value);
    }

    // Update chart
    dataChart.update();

    // Reset form
    form.reset();

    // Show success message
    showStatus('Data added successfully!', 'success');
});

// Helper function to get dataset index based on data type
function getDatasetIndex(dataType) {
    const types = ['temperature', 'humidity', 'pressure'];
    return types.indexOf(dataType);
}

// Helper function to show status messages
function showStatus(message, type) {
    statusMessage.textContent = message;
    statusMessage.className = `status ${type}`;
    statusMessage.style.display = 'block';

    // Hide message after 3 seconds
    setTimeout(() => {
        statusMessage.style.display = 'none';
    }, 3000);
}

// Simulate real-time data updates
function simulateRealTimeData() {
    setInterval(() => {
        const now = new Date();
        const formattedTime = now.toLocaleTimeString();

        // Add a new data point for each type
        dataChart.data.labels.push(formattedTime);

        // Generate random values for each dataset
        dataChart.data.datasets[0].data.push(Math.random() * 30 + 10); // Temperature 10-40°C
        dataChart.data.datasets[1].data.push(Math.random() * 50 + 30);  // Humidity 30-80%
        dataChart.data.datasets[2].data.push(Math.random() * 50 + 950); // Pressure 950-1000 hPa

        // Keep only the last 20 data points
        if (dataChart.data.labels.length > 20) {
            dataChart.data.labels.shift();
            dataChart.data.datasets.forEach(dataset => {
                dataset.data.shift();
            });
        }

        dataChart.update();
    }, 3000); // Update every 3 seconds
}

// Start simulation when page loads
window.addEventListener('load', simulateRealTimeData);
```

