  "*://*.zendesk.com/analytics/*"
];

// Initialize blocked count
let blockedCount = 0;

// Web request listener to block tracking scripts
chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    // Check if the request is from a third-party domain
    const isThirdParty = new URL(details.url).hostname !== new URL(details.initiator || details.url).hostname;

    // Check if the request matches any tracking patterns
    const isTracking = trackingPatterns.some(pattern => {
      const regex = new RegExp(pattern.replace(/\*/g, '.*'));
      return regex.test(details.url);
    });

    if (isThirdParty && isTracking) {
      blockedCount++;
      chrome.storage.local.set({ blockedCount });
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

