  // Toggle blocking button
  const toggleButton = document.getElementById('toggle-blocking');
  chrome.storage.local.get(['blockingEnabled'], (result) => {
    const isEnabled = result.blockingEnabled !== false; // default to true
    toggleButton.textContent = isEnabled ? 'Disable Blocking' : 'Enable Blocking';
  });

  toggleButton.addEventListener('click', () => {
    chrome.storage.local.get(['blockingEnabled'], (result) => {
      const newState = !(result.blockingEnabled !== false);
      chrome.storage.local.set({ blockingEnabled: newState });

      // Update button text
      toggleButton.textContent = newState ? 'Disable Blocking' : 'Enable Blocking';

      // Reload the active tab to apply changes
      chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
        if (tabs[0]) {
          chrome.tabs.reload(tabs[0].id);
        }
      });
    });
  });
});
