chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    // Check if blocking is enabled
    return new Promise((resolve) => {
      chrome.storage.sync.get(['blockingEnabled', 'whitelist'], (data) => {
        if (!data.blockingEnabled) {
          resolve({ cancel: false });
          return;
        }

        // Check if URL is in whitelist
        const url = new URL(details.url);
        if (data.whitelist && data.whitelist.includes(url.hostname)) {
          resolve({ cancel: false });
          return;
        }

        // Check against tracking domains and scripts
        const isTracking = trackingDomains.some(domain =>
          details.url.includes(domain)
        ) || trackingScripts.some(pattern =>
          new RegExp(pattern.replace(/\*/g, '.*')).test(details.url)
        );

        if (isTracking) {
          // Update blocked count
          chrome.storage.sync.get(['blockedCount'], (countData) => {
            chrome.storage.sync.set({
              blockedCount: (countData.blockedCount || 0) + 1
            });
          });

          resolve({ cancel: true });
        } else {
          resolve({ cancel: false });
        }
      });
    });
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);
