```javascript
document.addEventListener('DOMContentLoaded', () => {
  const blockingToggle = document.getElementById('blocking-toggle');
  const statusText = document.getElementById('status-text');
  const blockedCount = document.getElementById('blocked-count');
  const whitelistInput = document.getElementById('whitelist-input');
  const whitelistAdd = document.getElementById('whitelist-add');
  const whitelistList = document.getElementById('whitelist-list');

  // Load saved settings
  chrome.storage.sync.get(['blockingEnabled', 'blockedCount', 'whitelist'], (data) => {
    blockingToggle.checked = data.blockingEnabled !== false;
    updateStatusText();
    blockedCount.textContent = data.blockedCount || 0;

    // Load whitelist
    if (data.whitelist) {
      data.whitelist.forEach(domain => {
        addWhitelistItem(domain);
      });
    }
  });

  // Toggle blocking
  blockingToggle.addEventListener('change', () => {
    chrome.storage.sync.set({ blockingEnabled: blockingToggle.checked });
    updateStatusText();
  });

  function updateStatusText() {
    statusText.textContent = `Blocking is ${blockingToggle.checked ? 'ON' : 'OFF'}`;
  }

  // Add to whitelist
  whitelistAdd.addEventListener('click', () => {
    const domain = whitelistInput.value.trim();
    if (domain) {
      chrome.storage.sync.get(['whitelist'], (data) => {
        const whitelist = data.whitelist || [];
        if (!whitelist.includes(domain)) {
          whitelist.push(domain);
          chrome.storage.sync.set({ whitelist }, () => {
            addWhitelistItem(domain);
            whitelistInput.value = '';
          });
        }
      });
    }
  });

  // Add whitelist item to UI
  function addWhitelistItem(domain) {
    const li = document.createElement('li');
    li.textContent = domain;

    const removeBtn = document.createElement('button');
    removeBtn.textContent = '×';
    removeBtn.addEventListener('click', () => {
      chrome.storage.sync.get(['whitelist'], (data) => {
        const whitelist = data.whitelist || [];
        const index = whitelist.indexOf(domain);
        if (index > -1) {
          whitelist.splice(index, 1);
          chrome.storage.sync.set({ whitelist }, () => {
            li.remove();
          });
        }
      });
    });

    li.appendChild(removeBtn);
    whitelistList.appendChild(li);
  }
});
```

