```javascript
// List of known tracking domains and scripts
const trackingDomains = [
  "google-analytics.com",
  "facebook.com",
  "facebook.net",
  "doubleclick.net",
  "adobe.com",
  "googletagmanager.com",
  "googleadservices.com",
  "googlesyndication.com",
  "scorecardresearch.com",
  "mathtag.com",
  "optimizely.com",
  "hotjar.com",
  "newrelic.com",
  "mixpanel.com",
  "amplitude.com",
  "segment.com",
  "intercom.io",
  "hubspot.com",
  "linkedin.com",
  "twitter.com",
  "pinterest.com",
  "snapchat.com",
  "tiktok.com",
  "adservice.google.com",
  "analytics.google.com",
  "youtube.com/ptracking"
];

// List of known tracking script patterns
const trackingScripts = [
  "*://*.google-analytics.com/*",
  "*://*.googletagmanager.com/*",
  "*://*.facebook.com/tr/*",
  "*://*.facebook.com/connect/*",
  "*://*.facebook.net/*",
  "*://*.doubleclick.net/*",
  "*://*.adobe.com/*",
  "*://*.scorecardresearch.com/*",
  "*://*.mathtag.com/*",
  "*://*.optimizely.com/*",
  "*://*.hotjar.com/*",
  "*://*.newrelic.com/*",
  "*://*.mixpanel.com/*",
  "*://*.amplitude.com/*",
  "*://*.segment.com/*",
  "*://*.intercom.io/*",
  "*://*.hubspot.com/*",
  "*://*.linkedin.com/analytics/*",
  "*://*.twitter.com/i/adsct*",
  "*://*.pinterest.com/ads/*",
  "*://*.snapchat.com/*",
  "*://*.tiktok.com/*",
  "*://*.adservice.google.com/*",
  "*://*.analytics.google.com/*",
  "*://*.youtube.com/ptracking*"
];

// Blocked requests counter
let blockedCount = 0;

// Initialize storage
chrome.storage.local.get(["blockedCount"], (result) => {
  if (result.blockedCount) {
    blockedCount = result.blockedCount;
  }
});

// Web request listener to block tracking scripts
chrome.webRequest.onBeforeRequest.addListener(
  (details) => {
    // Check if the request URL matches any tracking pattern
    const isTracking = trackingScripts.some(pattern => {
      const regex = new RegExp(pattern.replace(/\*/g, '.*'));
      return regex.test(details.url);
    });

    if (isTracking) {
      blockedCount++;
      chrome.storage.local.set({ blockedCount });
      return { cancel: true };
    }

    return { cancel: false };
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);

// Update badge with blocked count
function updateBadge() {
  chrome.action.setBadgeText({ text: blockedCount.toString() });
  chrome.action.setBadgeBackgroundColor({ color: "#4CAF50" });
}

// Listen for storage changes
chrome.storage.onChanged.addListener((changes) => {
  if (changes.blockedCount) {
    blockedCount = changes.blockedCount.newValue;
    updateBadge();
  }
});

// Initialize badge
updateBadge();
```

