                    <option value="TSLA">Tesla (TSLA)</option>
                </select>
            </div>

            <div class="control-group">
                <label for="timeframe-select">Timeframe:</label>
                <select id="timeframe-select">
                    <option value="1d">1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m" selected>1 Month</option>
                    <option value="3m">3 Months</option>
                    <option value="1y">1 Year</option>
                    <option value="5y">5 Years</option>
                </select>
            </div>

            <div class="control-group">
                <label for="update-interval">Update Interval:</label>
                <select id="update-interval">
                    <option value="5000">5 seconds</option>
                    <option value="10000">10 seconds</option>
                    <option value="30000" selected>30 seconds</option>
                    <option value="60000">1 minute</option>
                </select>
            </div>

            <button id="reset-btn">Reset View</button>
        </div>

        <div id="heatmap-container">
            <div class="loading">Loading data...</div>
            <div class="tooltip" id="tooltip"></div>
        </div>

        <div class="legend" id="legend"></div>
    </div>

    <script>
        // Configuration
        const config = {
            margin: { top: 20, right: 20, bottom: 60, left: 60 },
            width: 1000,
            height: 500,
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            timeFormat: "%Y-%m-%d %H:%M",
            dateFormat: "%Y-%m-%d"
        };

        // DOM elements
        const container = d3.select("#heatmap-container");
        const svg = container.append("svg")
            .attr("width", config.width + config.margin.left + config.margin.right)
            .attr("height", config.height + config.margin.top + config.margin.bottom)
            .append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        const tooltip = d3.select("#tooltip");

        // Data variables
        let stockData = [];
        let xScale, yScale;
        let zoom;
        let updateIntervalId;

        // Initialize the visualization
        function init() {
            // Set up zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Add reset button functionality
            d3.select("#reset-btn").on("click", resetZoom);

            // Initialize with default values
            updateData();

            // Set up interval for updates
            const intervalSelect = d3.select("#update-interval");
            intervalSelect.on("change", () => {
                clearInterval(updateIntervalId);
                const interval = +intervalSelect.property("value");
                updateIntervalId = setInterval(updateData, interval);
            });

            // Trigger initial update
            const initialInterval = +intervalSelect.property("value");
            updateIntervalId = setInterval(updateData, initialInterval);

            // Set up control changes
            d3.select("#stock-select").on("change", updateData);
            d3.select("#timeframe-select").on("change", updateData);
        }

        // Update data based on current selections
        function updateData() {
            const stock = d3.select("#stock-select").property("value");
            const timeframe = d3.select("#timeframe-select").property("value");

            // Show loading indicator
            container.select(".loading").style("display", "block");

            // In a real application, you would fetch data from an API
            // For this demo, we'll generate mock data
            fetchMockData(stock, timeframe).then(data => {
                stockData = data;
                renderHeatmap();
                container.select(".loading").style("display", "none");
            });
        }

        // Generate mock data (in a real app, replace with API call)
        function fetchMockData(stock, timeframe) {
            return new Promise((resolve) => {
                setTimeout(() => {
                    const now = new Date();
                    const endDate = new Date(now);
                    let startDate;

                    // Set start date based on timeframe
                    switch(timeframe) {
                        case "1d":
                            startDate = new Date(now);
                            startDate.setDate(now.getDate() - 1);
                            break;
                        case "1w":
                            startDate = new Date(now);
                            startDate.setDate(now.getDate() - 7);
                            break;
                        case "1m":
                            startDate = new Date(now);
                            startDate.setMonth(now.getMonth() - 1);
                            break;
                        case "3m":
                            startDate = new Date(now);
                            startDate.setMonth(now.getMonth() - 3);
                            break;
                        case "1y":
                            startDate = new Date(now);
                            startDate.setFullYear(now.getFullYear() - 1);
                            break;
                        case "5y":
                            startDate = new Date(now);
                            startDate.setFullYear(now.getFullYear() - 5);
                            break;
                        default:
                            startDate = new Date(now);
                            startDate.setMonth(now.getMonth() - 1);
                    }

                    // Generate mock data points
                    const data = [];
                    const currentDate = new Date(startDate);

                    while (currentDate <= endDate) {
                        // For each hour in the day
                        for (let hour = 0; hour < 24; hour++) {
                            const date = new Date(currentDate);
                            date.setHours(hour);

                            // Generate a random price change (mock data)
                            const change = (Math.random() * 0.2 - 0.1).toFixed(4);

                            data.push({
                                date: new Date(date),
                                hour: hour,
                                change: parseFloat(change)
                            });
                        }

                        currentDate.setDate(currentDate.getDate() + 1);
                    }

                    resolve(data);
                }, 500); // Simulate network delay
            });
        }

        // Render the heatmap
        function renderHeatmap() {
            if (stockData.length === 0) return;

            // Clear previous content
            svg.selectAll("*").remove();

            // Set up scales
            const dates = Array.from(new Set(stockData.map(d => d.date.toDateString())));
            const hours = Array.from(new Set(stockData.map(d => d.hour)));

            xScale = d3.scaleBand()
                .domain(dates)
                .range([0, config.width])
                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(hours)
                .range([0, config.height])
                .padding(0.01);

            // Create heatmap cells
            const cells = svg.selectAll(".cell")
                .data(stockData)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.date.toDateString()))
                .attr("y", d => yScale(d.hour))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip);

            // Add axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d => {
                    const date = new Date(d);
                    return d3.timeFormat(config.dateFormat)(date);
                });

            const yAxis = d3.axisLeft(yScale)
                .tickFormat(d => `${d}:00`);

            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${config.height})`)
                .call(xAxis)
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.append("g")
                .attr("class", "y-axis")
                .call(yAxis);

            // Add axis labels
            svg.append("text")
                .attr("class", "x-label")
                .attr("x", config.width / 2)
                .attr("y", config.height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Date");

            svg.append("text")
                .attr("class", "y-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", -config.margin.left + 15)
                .style("text-anchor", "middle")
                .text("Hour of Day");

            // Add legend
            renderLegend();
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            const date = d3.timeFormat(config.timeFormat)(d.date);
            const change = (d.change * 100).toFixed(2);

            tooltip.style("display", "block")
                .html(`
                    <strong>Date:</strong> ${date}<br>
                    <strong>Hour:</strong> ${d.hour}:00<br>
                    <strong>Change:</strong> ${change}%<br>
                    <strong>Color:</strong> ${d.change > 0 ? "Green (Positive)" : d.change < 0 ? "Red (Negative)" : "Neutral"}
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.style("display", "none");
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the zoom transformation to the cells
            svg.selectAll(".cell")
                .attr("transform", transform);

            // Adjust the axes
            svg.select(".x-axis").call(
                d3.axisBottom(xScale).scale(transform.rescaleX(xScale))
            );

            svg.select(".y-axis").call(
                d3.axisLeft(yScale).scale(transform.rescaleY(yScale))
            );
        }

        // Reset zoom to default
        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Render the legend
        function renderLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            // Create legend items
            const legendItems = [
                { color: config.colorScale(-0.1), label: "-10% or less" },
                { color: config.colorScale(-0.05), label: "-5%" },
                { color: config.colorScale(0), label: "0%" },
                { color: config.colorScale(0.05), label: "+5%" },
                { color: config.colorScale(0.1), label: "+10% or more" }
            ];

            legend.selectAll(".legend-item")
                .data(legendItems)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);
    </script>
</body>
</html>
```

## Key Features

1. **Interactive Heatmap**:
   - Color-coded representation of stock price changes (green for positive, red for negative)
   - Tooltips showing detailed information on hover

2. **Real-Time Updates**:
   - Configurable update intervals (5s to 1 minute)
   - Simulated data fetching with loading indicators

3. **Zoom/Pan Interactions**:
   - Mouse-based zooming and panning
   - Reset button to return to default view

4. **Customization Options**:
   - Select different stocks (AAPL, MSFT, etc.)
   - Choose different timeframes (1 day to 5 years)
   - Adjustable update frequency

5. **Responsive Design**:
   - Works on different screen sizes
   - Clean, modern UI with proper spacing

## Implementation Notes

- This uses D3.js for data visualization
- The mock data generation simulates real-time updates
- In a production environment, you would replace the `fetchMockData` function with actual API calls to a financial data provider
- The color scale uses a red-yellow-green gradient to represent price changes
- The visualization includes proper axes, labels, and a legend

To use this in a real application, you would need to:
1. Replace the mock data generation with actual API calls
2. Add error handling for API failures
3. Potentially add authentication for premium data sources
4. Optimize performance for large datasets

