        const timeframeSelect = d3.select("#timeframe");
        const stockSelect = d3.select("#stock-select");
        const updateIntervalSelect = d3.select("#update-interval");

        // Data variables
        let stockData = [];
        let timePoints = [];
        let selectedStocks = Array.from(stockSelect.node().selectedOptions).map(opt => opt.value);
        let currentTimeframe = timeframeSelect.node().value;

        // Initialize the visualization
        function init() {
            // Set up event listeners
            timeframeSelect.on("change", handleTimeframeChange);
            stockSelect.on("change", handleStockSelectionChange);
            updateIntervalSelect.on("change", handleUpdateIntervalChange);

            // Initial data fetch
            fetchStockData();

            // Set up periodic updates
            setInterval(fetchStockData, config.updateInterval);
        }

        // Handle timeframe change
        function handleTimeframeChange() {
            currentTimeframe = this.value;
            fetchStockData();
        }

        // Handle stock selection change
        function handleStockSelectionChange() {
            selectedStocks = Array.from(this.selectedOptions).map(opt => opt.value);
            fetchStockData();
        }

        // Handle update interval change
        function handleUpdateIntervalChange() {
            config.updateInterval = parseInt(this.value) * 1000;
            // Restart the interval with new value
            clearInterval(window.updateInterval);
            window.updateInterval = setInterval(fetchStockData, config.updateInterval);
        }

        // Fetch stock data (simulated with random data for demo)
