                // const response = await fetch(`/api/stocks?symbols=${selectedStocks.join(',')}&timeframe=${currentTimeframe}`);
                // const data = await response.json();

                // Simulate API response with random data
                const data = generateRandomStockData(selectedStocks, currentTimeframe);

                // Process the data
                processStockData(data);

                // Update the visualization
                updateVisualization();

                // Hide loading indicator
                heatmapContainer.select(".loading").style("display", "none");
            } catch (error) {
                console.error("Error fetching stock data:", error);
                heatmapContainer.select(".loading").text("Error loading data. Please try again.");
            }
        }

        // Generate random stock data for demonstration
        function generateRandomStockData(symbols, timeframe) {
            const now = new Date();
            const timePoints = [];
            const data = [];

            // Determine time points based on timeframe
            const timeframeConfig = {
                '1d': { count: 24, interval: 'hour' },
                '1w': { count: 7, interval: 'day' },
                '1m': { count: 30, interval: 'day' },
                '3m': { count: 90, interval: 'day' },
                '1y': { count: 12, interval: 'month' }
            };

            const { count, interval } = timeframeConfig[timeframe];

            for (let i = 0; i < count; i++) {
                const date = new Date(now);
                if (interval === 'hour') {
                    date.setHours(now.getHours() - i);
                } else if (interval === 'day') {
                    date.setDate(now.getDate() - i);
                } else if (interval === 'month') {
                    date.setMonth(now.getMonth() - i);
                }
                timePoints.push(date);
