                    const priceChange = dailyChange * (1 + Math.sin(i * 0.5)) + (Math.random() - 0.5) * 0.02;
                    const price = basePrice * (1 + priceChange * i);

                    data.push({
                        symbol,
                        time,
                        price,
                        change: priceChange
                    });
                });
            });

            return { timePoints: timePoints.reverse(), data };
        }

