                { color: config.colorScale(-0.1), label: "-10%" },
                { color: config.colorScale(-0.05), label: "-5%" },
                { color: config.colorScale(0), label: "0%" },
                { color: config.colorScale(0.05), label: "+5%" },
                { color: config.colorScale(0.1), label: "+10%" }
            ];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);
        }

        // Update data from API
        async function updateData() {
            d3.select("#loading").style("display", "block");

            const timeframe = d3.select("#timeframe").property("value");
            const selectedStocks = Array.from(d3.select("#stocks").selectAll("option:checked").nodes())
                .map(option => option.value);

            try {
                // In a real application, you would fetch data from an API
                // For this example, we'll generate mock data
                const mockData = generateMockData(selectedStocks, timeframe);
                processData(mockData);
            } catch (error) {
                console.error("Error fetching data:", error);
                d3.select("#loading").text("Error loading data. Please try again.");
            }
        }

        // Generate mock data for demonstration
        function generateMockData(stocks, timeframe) {
            const now = new Date();
            let startDate, interval, points;

            switch(timeframe) {
                case "1d":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 1);
                    interval = 15 * 60 * 1000; // 15 minutes
                    points = 96; // 24 hours * 4
                    break;
                case "1w":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 7);
                    interval = 60 * 60 * 1000; // 1 hour
                    points = 168; // 7 days * 24
                    break;
                case "1m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    points = 14 * 24; // ~1 month * 24
                    break;
                case "3m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 3);
                    interval = 12 * 60 * 60 * 1000; // 12 hours
                    points = 30 * 24; // ~3 months * 24
                    break;
                case "1y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 1);
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    points = 365; // ~1 year
                    break;
                case "5y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 5);
                    interval = 7 * 24 * 60 * 60 * 1000; // 1 week
                    points = 5 * 52; // ~5 years * 52 weeks
                    break;
                default:
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    interval = 6 * 60 * 60 * 1000;
                    points = 14 * 24;
            }

            const data = [];
            const basePrices = {};

            // Initialize base prices
            stocks.forEach(stock => {
                basePrices[stock] = 100 + Math.random() * 200;
            });

            // Generate data points
            for (let i = 0; i < points; i++) {
                const timestamp = new Date(startDate.getTime() + i * interval);

                stocks.forEach(stock => {
                    // Simulate price movement with some randomness
                    const change = (Math.random() - 0.5) * 0.05; // -2.5% to +2.5% change
                    basePrices[stock] *= (1 + change);

                    data.push({
                        stock: stock,
                        date: timestamp,
                        price: basePrices[stock],
                        change: change
                    });
                });
            }

            return data;
        }

        // Process and visualize the data
        function processData(data) {
            // Group data by stock and date
            const nestedData = d3.group(data, d => d.stock, d => d.date);

            // Convert to array of objects
            heatmapData = Array.from(nestedData, ([stock, dates]) => {
                return {
                    stock: stock,
                    dates: Array.from(dates, ([date, values]) => {
                        return {
                            date: date,
                            price: values[0].price,
                            change: values[0].change
                        };
                    })
                };
            });

            // Sort stocks alphabetically
            heatmapData.sort((a, b) => a.stock.localeCompare(b.stock));

            // Get all unique dates
            const allDates = Array.from(new Set(data.map(d => d.date))).sort((a, b) => a - b);

            // Set up scales
            xScale = d3.scaleBand()
                .domain(allDates.map(d => d3.timeFormat("%Y-%m-%d %H:%M")(d)))
                .range([0, config.width])
                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(heatmapData.map(d => d.stock))
                .range([0, config.height])
                .padding(0.01);

            // Remove previous elements
            svg.selectAll("*").remove();

            // Add X axis
            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height})`)
                .call(d3.axisBottom(xScale)
                    .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(allDates.length / 10) === 0))
                    .tickFormat(d => {
                        const date = new Date(d);
                        return d3.timeFormat("%b %d")(date);
                    }))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end")
                .attr("class", "axis-label");

            // Add Y axis
            svg.append("g")
                .attr("class", "y-axis")
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .attr("class", "axis-label");

            // Add X axis label
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height + config.margin.bottom - 20)
                .style("text-anchor", "middle")
                .text("Date");

            // Add Y axis label
            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock");

            // Create heatmap cells
            const cells = svg.selectAll(".cell")
                .data(heatmapData.flatMap(d => d.dates.map(dateData => ({
                    stock: d.stock,
                    date: dateData.date,
                    change: dateData.change
                }))))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d3.timeFormat("%Y-%m-%d %H:%M")(d.date)))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change))
                .on("mouseover", function(event, d) {
                    const tooltip = d3.select("#tooltip");
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            ${d3.timeFormat("%b %d, %Y %H:%M")(d.date)}<br>
                            Change: ${(d.change * 100).toFixed(2)}%
                        `);
                })
                .on("mousemove", function(event) {
                    d3.select("#tooltip")
                        .style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("visibility", "hidden");
                });

            // Add zoom rectangle
            svg.append("rect")
                .attr("class", "zoom")
                .attr("width", config.width)
                .attr("height", config.height)
                .style("fill", "none")
                .style("pointer-events", "all");

            d3.select("#loading").style("display", "none");
        }

        // Zoom function
        function zoomed(event) {
            const transform = event.transform;

            // Apply the zoom transformation to the x and y scales
            const newXScale = transform.rescaleX(xScale);
            const newYScale = transform.rescaleY(yScale);

            // Update the axes
            svg.select(".x-axis").call(d3.axisBottom(newXScale)
                .tickValues(newXScale.domain().filter((d, i) => i % Math.ceil(xScale.domain().length / 10) === 0))
                .tickFormat(d => {
                    const date = new Date(d);
                    return d3.timeFormat("%b %d")(date);
                }))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.select(".y-axis").call(d3.axisLeft(newYScale));

            // Update the heatmap cells
            svg.selectAll(".cell")
                .attr("x", d => newXScale(d3.timeFormat("%Y-%m-%d %H:%M")(d.date)))
                .attr("y", d => newYScale(d.stock))
                .attr("width", newXScale.bandwidth())
                .attr("height", newYScale.bandwidth());
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);

        // Clean up when the page is unloaded
        window.addEventListener("beforeunload", () => {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }
        });
    </script>
</body>
</html>
