                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 15)
                .style("text-anchor", "middle")
                .text("Time");

            // Add a group for the heatmap cells
            svg.append("g")
                .attr("class", "heatmap-group");

            // Create legend
            createLegend();

            // Load initial data
            loadData();

            // Set up event listeners
            timeframeSelect.addEventListener("change", () => {
                currentTimeframe = timeframeSelect.value;
                loadData();
            });

            stockSelect.addEventListener("change", () => {
                currentStock = stockSelect.value;
                loadData();
            });

            updateBtn.addEventListener("click", loadData);

            // Set up periodic updates
            setInterval(loadData, config.updateInterval);
        }

        // Create color legend
        function createLegend() {
            const legend = d3.select("#legend");
            const legendData = [
                { value: -0.1, color: config.colorScale(-0.1) },
                { value: -0.05, color: config.colorScale(-0.05) },
                { value: 0, color: config.colorScale(0) },
                { value: 0.05, color: config.colorScale(0.05) },
                { value: 0.1, color: config.colorScale(0.1) }
            ];

            legend.selectAll("*").remove();

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color}"></div>
                    <span>${(d.value * 100).toFixed(1)}%</span>
                `);
        }

        // Load data from API
        async function loadData() {
            if (isLoading) return;

            isLoading = true;
            heatmapContainer.select(".loading").style("display", "block");

            try {
                // In a real application, you would fetch from a stock API
                // For this demo, we'll generate synthetic data
                const data = generateSyntheticData(currentStock, currentTimeframe);

                // Process the data
                processData(data);

                // Update the visualization
                updateVisualization();
            } catch (error) {
                console.error("Error loading data:", error);
            } finally {
                isLoading = false;
                heatmapContainer.select(".loading").style("display", "none");
            }
        }

        // Generate synthetic data for demonstration
        function generateSyntheticData(stockSymbol, timeframe) {
            const now = new Date();
            let startDate, interval, pointsPerDay;

            // Set parameters based on timeframe
            switch (timeframe) {
                case "1d":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 1);
                    interval = 5 * 60 * 1000; // 5 minutes
                    pointsPerDay = 24 * 12; // 5-minute intervals in a day
                    break;
                case "1w":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 7);
                    interval = 15 * 60 * 1000; // 15 minutes
                    pointsPerDay = 24 * 4; // 15-minute intervals in a day
                    break;
                case "1m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    interval = 60 * 60 * 1000; // 1 hour
                    pointsPerDay = 24; // 1-hour intervals in a day
                    break;
                case "3m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 3);
                    interval = 4 * 60 * 60 * 1000; // 4 hours
                    pointsPerDay = 6; // 4-hour intervals in a day
                    break;
                case "1y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 1);
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    pointsPerDay = 1; // 1 point per day
                    break;
                case "5y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 5);
                    interval = 7 * 24 * 60 * 60 * 1000; // 1 week
                    pointsPerDay = 1; // 1 point per week
                    break;
                default:
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    interval = 60 * 60 * 1000; // 1 hour
                    pointsPerDay = 24; // 1-hour intervals in a day
            }

            // Generate data points
            const data = [];
            const days = Math.ceil((now - startDate) / (24 * 60 * 60 * 1000));

            for (let day = 0; day < days; day++) {
                const dayDate = new Date(startDate);
                dayDate.setDate(startDate.getDate() + day);

                for (let point = 0; point < pointsPerDay; point++) {
                    const pointTime = new Date(dayDate);
                    pointTime.setTime(dayDate.getTime() + point * interval);

                    // Skip future points
                    if (pointTime > now) continue;

                    // Generate synthetic price change (percentage)
                    // This is just for demonstration - in a real app you'd use actual data
                    const priceChange = (Math.random() * 0.2 - 0.1).toFixed(4);

                    data.push({
                        date: pointTime,
                        time: pointTime,
                        priceChange: parseFloat(priceChange),
                        stock: stockSymbol
                    });
                }
            }

            return data;
        }

        // Process the data into a format suitable for the heatmap
        function processData(data) {
            // Group data by date and time
            const nestedData = d3.group(data, d => d3.timeDay(d.date), d => d3.timeHour(d.time));

            // Convert to array of objects with date, time, and priceChange
            stockData = Array.from(nestedData, ([date, timeMap]) => {
                return {
                    date,
                    times: Array.from(timeMap, ([time, values]) => {
                        // For each time, take the average price change
                        const avgChange = d3.mean(values, v => v.priceChange);
                        return { time, priceChange: avgChange };
                    })
                };
            });

            // Sort by date
            stockData.sort((a, b) => a.date - b.date);
        }

        // Update the visualization with new data
        function updateVisualization() {
            const svg = heatmapContainer.select("svg");
            const heatmapGroup = svg.select(".heatmap-group");

            // Clear previous content
            heatmapGroup.selectAll("*").remove();

            // Get all unique times across all dates
            const allTimes = new Set();
            stockData.forEach(day => {
                day.times.forEach(timeObj => {
                    allTimes.add(timeObj.time);
                });
            });

            // Convert to array and sort
            const sortedTimes = Array.from(allTimes).sort((a, b) => a - b);

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(stockData.map(d => d.date))
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(sortedTimes)
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.05);

            // Update axes
            const xAxis = d3.axisBottom(xScale).tickFormat(d3.timeFormat("%b %d"));
            const yAxis = d3.axisLeft(yScale).tickFormat(d3.timeFormat("%H:%M"));

            svg.select(".x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(xAxis);

            svg.select(".y-axis")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(yAxis);

            // Create heatmap cells
            const cells = heatmapGroup.selectAll(".heatmap-cell")
                .data(stockData)
                .enter()
                .append("g")
                .attr("class", "heatmap-cell")
                .attr("transform", d => `translate(${xScale(d.date)}, 0)`);

            cells.selectAll("rect")
                .data(d => d.times)
                .enter()
                .append("rect")
                .attr("x", 0)
                .attr("y", d => yScale(d.time))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.priceChange))
                .on("mouseover", function(event, d) {
                    const [x, y] = d3.pointer(event);
                    tooltip.style("display", "block")
                        .html(`
                            <strong>${currentStock}</strong><br>
                            Date: ${d3.timeFormat("%b %d, %Y")(d.time)}<br>
                            Time: ${d3.timeFormat("%H:%M")(d.time)}<br>
                            Change: ${(d.priceChange * 100).toFixed(2)}%
                        `)
                        .style("left", `${x + 10}px`)
                        .style("top", `${y + 10}px`);
                })
                .on("mouseout", () => {
                    tooltip.style("display", "none");
                });
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);
    </script>
</body>
</html>
```

## Features

1. **Interactive Heatmap**:
   - Visualizes stock price changes as a color-coded grid
   - Each cell represents a time interval (5min, 15min, 1hr, etc.) with color indicating price change

2. **Real-Time Updates**:
   - Data refreshes every 30 seconds (configurable)
   - Manual update button available

3. **Zoom/Pan Interactions**:
   - Mouse wheel to zoom in/out
   - Click and drag to pan around the visualization
   - Smooth transitions when zooming/panning

4. **Customization Options**:
