                    startDate.setMonth(now.getMonth() - 1);
                    break;
                case '3m':
                    startDate.setMonth(now.getMonth() - 3);
                    break;
                case '1y':
                    startDate.setFullYear(now.getFullYear() - 1);
                    break;
                case '5y':
                    startDate.setFullYear(now.getFullYear() - 5);
                    break;
            }

            // Generate dates
            const dates = [];
            for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
                dates.push(new Date(d));
            }

            // Generate mock data for each stock and date
            const mockData = [];
            stocks.forEach(stock => {
                dates.forEach(date => {
                    // Generate a random price change percentage between -5% and +5%
                    const changePercent = (Math.random() * 10 - 5).toFixed(2);

                    mockData.push({
                        stock: stock,
                        date: new Date(date),
                        changePercent: parseFloat(changePercent)
                    });
                });
            });

            return mockData;
        }

        // Update the heatmap with new data
        function updateHeatmap(newData) {
            data = newData;

            // Get unique stocks and dates
            const stocks = [...new Set(data.map(d => d.stock))];
            const dates = [...new Set(data.map(d => d.date))].sort((a, b) => a - b);

