            const cells = heatmap.selectAll('rect')
                .data(data, d => `${d.stock}-${d.date}`);

            // Remove old cells
            cells.exit().remove();

            // Add new cells
            const newCells = cells.enter()
                .append('rect')
                .attr('x', d => xScale(d.date))
                .attr('y', d => yScale(d.stock))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(d.changePercent))
                .on('mouseover', showTooltip)
                .on('mouseout', hideTooltip);

            // Update existing cells
            cells.merge(newCells)
                .transition()
                .duration(500)
                .attr('x', d => xScale(d.date))
                .attr('y', d => yScale(d.stock))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(d.changePercent));

            // Update legend
            createLegend();

            // Reset zoom
            resetZoom();
        }

