    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 600,
            margin: { top: 50, right: 30, bottom: 50, left: 80 },
            colorScale: d3.scaleSequential(d3.interpolateRdYlBu).domain([0, 1]),
            updateInterval: 30000 // 30 seconds
        };

        // Global variables
        let svg, xScale, yScale, heatmap, tooltip, zoom;
        let currentData = [];
        let isUpdating = false;
        let updateIntervalId = null;

        // Initialize the visualization
        document.addEventListener('DOMContentLoaded', () => {
            initVisualization();
            setupEventListeners();

            // Initial data load
            updateData();

            // Set up automatic updates
            updateIntervalId = setInterval(updateData, config.updateInterval);
        });

        function initVisualization() {
            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create tooltip
