                .attr("class", "heatmap-group");

            // Add axes groups
            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`);

            svg.append("g")
                .attr("class", "y-axis")
                .attr("transform", `translate(${config.margin.left}, 0)`);

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 10)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 20)
                .style("text-anchor", "middle")
                .text("Price ($)");
        }

        function setupEventListeners() {
            document.getElementById("update-btn").addEventListener("click", () => {
                updateData();
            });

            document.getElementById("timeframe").addEventListener("change", () => {
                updateData();
            });

            document.getElementById("stock-select").addEventListener("change", () => {
                updateData();
            });

            // Handle window resize
            window.addEventListener("resize", () => {
                // You could add responsive resizing here
            });
        }

        function zoomed(event) {
            const { transform } = event;
            heatmap.attr("transform", transform);
            svg.select(".x-axis").call(xAxis.scale(transform.rescaleX(xScale)));
            svg.select(".y-axis").call(yAxis.scale(transform.rescaleY(yScale)));
        }

        function updateData() {
            if (isUpdating) return;

            isUpdating = true;
            document.getElementById("loading").style.display = "block";

            const stockSymbol = document.getElementById("stock-select").value;
            const timeframe = document.getElementById("timeframe").value;

            // In a real application, you would fetch data from an API
            // For this example, we'll simulate data
            simulateDataFetch(stockSymbol, timeframe)
                .then(data => {
                    currentData = data;
                    renderHeatmap();
                    document.getElementById("loading").style.display = "none";
                    isUpdating = false;
                })
                .catch(error => {
                    console.error("Error fetching data:", error);
                    document.getElementById("loading").style.display = "none";
                    isUpdating = false;
                });
        }

        // Simulate data fetching (replace with real API call)
        function simulateDataFetch(stockSymbol, timeframe) {
            return new Promise((resolve) => {
                setTimeout(() => {
                    // Generate simulated data
                    const now = new Date();
                    const endDate = new Date(now);
                    const startDate = new Date(now);

                    // Adjust timeframe
                    switch (timeframe) {
                        case "1d":
                            startDate.setDate(now.getDate() - 1);
                            break;
                        case "5d":
                            startDate.setDate(now.getDate() - 5);
                            break;
                        case "1mo":
                            startDate.setMonth(now.getMonth() - 1);
                            break;
                        case "3mo":
                            startDate.setMonth(now.getMonth() - 3);
                            break;
                        case "1y":
                            startDate.setFullYear(now.getFullYear() - 1);
                            break;
                        case "5y":
                            startDate.setFullYear(now.getFullYear() - 5);
                            break;
                    }

                    // Generate time points (hourly for 1 day, daily otherwise)
                    const timePoints = [];
                    const current = new Date(startDate);

                    if (timeframe === "1d") {
                        while (current <= endDate) {
                            timePoints.push(new Date(current));
                            current.setHours(current.getHours() + 1);
                        }
                    } else {
                        while (current <= endDate) {
                            timePoints.push(new Date(current));
                            current.setDate(current.getDate() + 1);
                        }
                    }

                    // Generate price points (simulated)
                    const pricePoints = [];
                    const basePrice = 100 + Math.random() * 200; // Random base price
                    let currentPrice = basePrice;

                    timePoints.forEach((time, i) => {
                        // Simulate price movement
                        if (i > 0) {
                            const change = (Math.random() - 0.5) * 5; // Random change between -2.5 and +2.5
                            currentPrice += change;
                        }

                        pricePoints.push({
                            time: time,
                            price: currentPrice,
                            volume: Math.floor(Math.random() * 1000000) // Random volume
                        });
                    });

                    // Create heatmap data (time vs price with volume as intensity)
                    const heatmapData = [];
                    const timeExtent = d3.extent(timePoints, d => d);
                    const priceExtent = d3.extent(pricePoints, d => d.price);

                    // Create a grid of time and price points
                    const timeBins = d3.timeDays(timeExtent[0], timeExtent[1]);
                    if (timeframe === "1d") {
                        timeBins.length = 0;
                        for (let i = 0; i < 24; i++) {
                            const date = new Date(timeExtent[0]);
                            date.setHours(i);
                            timeBins.push(date);
                        }
                    }

                    const priceBins = d3.range(priceExtent[0], priceExtent[1], (priceExtent[1] - priceExtent[0]) / 20);

                    timeBins.forEach(time => {
                        priceBins.forEach(price => {
                            // Find the closest data point
                            const closest = pricePoints.reduce((prev, curr) => {
                                const prevDiff = Math.abs(prev.time - time) + Math.abs(prev.price - price);
                                const currDiff = Math.abs(curr.time - time) + Math.abs(curr.price - price);
                                return currDiff < prevDiff ? curr : prev;
                            });

                            heatmapData.push({
                                time: time,
                                price: price,
                                volume: closest.volume,
                                value: (closest.volume / 1000000) // Normalize volume
                            });
                        });
                    });

                    resolve(heatmapData);
                }, 500); // Simulate network delay
            });
        }

        function renderHeatmap() {
            if (!currentData || currentData.length === 0) return;

            // Clear previous heatmap
            heatmap.selectAll("*").remove();

            // Set up scales
            const timeExtent = d3.extent(currentData, d => d.time);
            const priceExtent = d3.extent(currentData, d => d.price);

            xScale = d3.scaleTime()
                .domain(timeExtent)
                .range([config.margin.left, config.width - config.margin.right]);

            yScale = d3.scaleLinear()
                .domain(priceExtent)
                .range([config.height - config.margin.bottom, config.margin.top]);

            // Create axes
            const xAxis = d3.axisBottom(xScale);
            const yAxis = d3.axisLeft(yScale);

            svg.select(".x-axis").call(xAxis);
            svg.select(".y-axis").call(yAxis);

            // Create color scale based on volume
            const volumeExtent = d3.extent(currentData, d => d.volume);
            const colorScale = d3.scaleSequential(d3.interpolateRdYlBu)
                .domain([volumeExtent[0], volumeExtent[1]]);

            // Create heatmap cells
            const cellWidth = (config.width - config.margin.left - config.margin.right) / d3.timeDays(timeExtent[0], timeExtent[1]).length;
            const cellHeight = (config.height - config.margin.top - config.margin.bottom) / 20;

            heatmap.selectAll("rect")
                .data(currentData)
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.price + (priceExtent[1] - priceExtent[0]) / 40)) // Adjust for cell height
                .attr("width", cellWidth)
                .attr("height", cellHeight)
                .attr("fill", d => colorScale(d.volume))
                .on("mouseover", (event, d) => {
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${document.getElementById("stock-select").value}</strong><br>
                            Time: ${d.time.toLocaleString()}<br>
                            Price: $${d.price.toFixed(2)}<br>
                            Volume: ${d.volume.toLocaleString()}
                        `)
                        .style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", () => {
                    tooltip.style("visibility", "hidden");
                });

            // Reset zoom
            svg.call(zoom.transform, d3.zoomIdentity);
        }

        // Clean up when page is unloaded
        window.addEventListener('beforeunload', () => {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }
        });
    </script>
</body>
</html>
