                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(stocks)
                .range([config.margin.top, config.height - config.margin.bottom])
                .padding(0.01);

            // Color scale based on price change
            const changes = data.map(d => d.change);
            const minChange = d3.min(changes);
            const maxChange = d3.max(changes);

            colorScale = d3.scaleSequential()
                .domain([minChange, maxChange])
                .interpolator(config.colorScheme);

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d => {
                    const date = new Date(d);
                    return currentTimeframe === '1d' ?
                        d3.timeFormat("%H:%M")(date) :
                        d3.timeFormat("%b %d")(date);
                });

            const yAxis = d3.axisLeft(yScale);

            // Add axes to SVG
            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(xAxis)
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end")
                .attr("class", "axis-label");

            svg.append("g")
                .attr("class", "y-axis")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 10)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("y", 20)
                .attr("x", -config.height / 2)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Add heatmap cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(data)
                .enter()
                .append("rect")
                .attr("class", "heatmap-cell")
                .attr("x", d => xScale(d3.timeFormat("%Y-%m-%d %H:%M")(d.date)))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", showTooltip)
                .on("mousemove", moveTooltip)
                .on("mouseout", hideTooltip);

            // Add legend
            updateLegend(minChange, maxChange);
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            tooltip.transition()
                .duration(200)
                .style("opacity", .9);

            tooltip.html(`
                <strong>${d.stock}</strong><br>
                Date: ${d3.timeFormat("%Y-%m-%d %H:%M")(d.date)}<br>
                Price: $${d.price.toFixed(2)}<br>
                Change: ${d.change.toFixed(2)}%
            `)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");
        }

        // Move tooltip with mouse
        function moveTooltip(event) {
            tooltip.style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY - 28) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.transition()
                .duration(500)
                .style("opacity", 0);
        }

        // Update the legend
        function updateLegend(minChange, maxChange) {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            // Create legend items
            const legendItems = [
                { label: "Decrease", value: minChange },
                { label: "Neutral", value: 0 },
                { label: "Increase", value: maxChange }
            ];

            legendItems.forEach(item => {
                const legendItem = legend.append("div")
                    .attr("class", "legend-item");

                legendItem.append("div")
                    .attr("class", "legend-color")
                    .style("background-color", colorScale(item.value));

                legendItem.append("span")
                    .text(item.label);
            });
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);

        // Clean up when leaving the page
        window.addEventListener("beforeunload", stopAutoUpdate);
    </script>
</body>
</html>
