    <script>
        // Configuration
        const config = {
            margin: { top: 50, right: 30, bottom: 80, left: 100 },
            width: 1000,
            height: 500,
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            updateInterval: 10000, // 10 seconds
            isUpdating: true
        };

        // DOM elements
        const heatmapContainer = d3.select("#heatmap-container");
        const tooltip = d3.select(".tooltip");
        const timeframeSelect = document.getElementById("timeframe");
        const stockSelect = document.getElementById("stock-select");
        const updateIntervalSelect = document.getElementById("update-interval");
        const toggleUpdatesBtn = document.getElementById("toggle-updates");

        // Data variables
        let stockData = {};
        let allDates = [];
        let allStocks = [];
        let updateIntervalId = null;

        // Initialize the visualization
        function init() {
            // Set up event listeners
            timeframeSelect.addEventListener("change", handleTimeframeChange);
            updateIntervalSelect.addEventListener("change", handleUpdateIntervalChange);
            toggleUpdatesBtn.addEventListener("click", toggleUpdates);

            // Initial data fetch
            fetchData();

            // Set up periodic updates
            startUpdates();
        }

        // Fetch data from API (simulated with mock data)
        async function fetchData() {
            try {
                // In a real application, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
                // For this example, we'll use mock data
                const mockData = generateMockData();

                processData(mockData);
                renderHeatmap();
            } catch (error) {
                console.error("Error fetching data:", error);
                heatmapContainer.select(".loading").text("Error loading data. Please try again.");
            }
        }

        // Process the fetched data
        function processData(data) {
            stockData = {};
            allDates = [];
            allStocks = [];

            // Group data by stock and collect all unique dates and stocks
            data.forEach(item => {
                if (!stockData[item.symbol]) {
                    stockData[item.symbol] = [];
                    allStocks.push(item.symbol);
                }
                stockData[item.symbol].push(item);

                if (!allDates.includes(item.date)) {
                    allDates.push(item.date);
                }
            });

            // Sort dates chronologically
            allDates.sort((a, b) => new Date(a) - new Date(b));

            // Sort stocks alphabetically
            allStocks.sort();
        }

        // Generate mock data for demonstration
        function generateMockData() {
            const symbols = Array.from(stockSelect.selectedOptions).map(opt => opt.value);
            const timeframe = timeframeSelect.value;
            const now = new Date();
            let startDate, interval, count;

            // Determine date range based on timeframe
            switch (timeframe) {
                case "1d":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 1);
                    interval = 3600000; // 1 hour
                    count = 24;
                    break;
                case "1w":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 7);
                    interval = 21600000; // 6 hours
                    count = 28;
                    break;
                case "1m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    interval = 86400000; // 1 day
                    count = 30;
                    break;
                case "3m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 3);
                    interval = 86400000; // 1 day
                    count = 90;
                    break;
                case "1y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 1);
                    interval = 86400000; // 1 day
                    count = 252; // ~trading days in a year
                    break;
                case "5y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 5);
                    interval = 86400000 * 7; // 1 week
                    count = 260; // ~weeks in 5 years
                    break;
                default:
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    interval = 86400000; // 1 day
                    count = 30;
            }

            const mockData = [];

            // Generate data for each symbol
            symbols.forEach(symbol => {
                const basePrice = 100 + Math.random() * 200; // Random base price between 100-300
                let currentPrice = basePrice;

                for (let i = 0; i < count; i++) {
                    const date = new Date(startDate.getTime() + i * interval);
                    const dateStr = date.toISOString().split('T')[0];

                    // Simulate price movement
                    const change = (Math.random() - 0.5) * 0.1; // Random change between -0.05 and +0.05
                    currentPrice = currentPrice * (1 + change);

                    mockData.push({
                        symbol: symbol,
                        date: dateStr,
                        open: currentPrice * (1 - Math.random() * 0.02),
                        high: currentPrice * (1 + Math.random() * 0.03),
                        low: currentPrice * (1 - Math.random() * 0.03),
                        close: currentPrice,
                        volume: Math.floor(Math.random() * 1000000)
                    });
                }
            });

            return mockData;
        }

        // Render the heatmap
        function renderHeatmap() {
            // Clear previous visualization
            heatmapContainer.select("svg").remove();
            heatmapContainer.select(".loading").remove();

            // Get selected stocks
            const selectedStocks = Array.from(stockSelect.selectedOptions).map(opt => opt.value);

            // Filter data for selected stocks
            const filteredStocks = allStocks.filter(stock => selectedStocks.includes(stock));
            const filteredData = filteredStocks.flatMap(stock => stockData[stock]);

            if (filteredData.length === 0) {
                heatmapContainer.append("div")
                    .attr("class", "loading")
                    .text("No data available for selected stocks and timeframe.");
                return;
            }

            // Set up SVG
            const svg = heatmapContainer.append("svg")
                .attr("width", config.width + config.margin.left + config.margin.right)
                .attr("height", config.height + config.margin.top + config.margin.bottom)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(allDates)
                .range([0, config.width])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(filteredStocks)
                .range([0, config.height])
                .padding(0.01);

            // Calculate daily returns for each stock
            const dailyReturns = {};
            filteredStocks.forEach(stock => {
                dailyReturns[stock] = [];
                const stockData = filteredData.filter(d => d.symbol === stock);

                for (let i = 1; i < stockData.length; i++) {
                    const prevClose = stockData[i-1].close;
                    const currentClose = stockData[i].close;
                    const dailyReturn = (currentClose - prevClose) / prevClose;
                    dailyReturns[stock].push({
                        date: stockData[i].date,
                        return: dailyReturn
                    });
                }
            });

            // Create heatmap cells
            svg.selectAll(".cell")
                .data(filteredData)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => {
                    // Find the daily return for this date and stock
                    const returns = dailyReturns[d.symbol];
                    const returnData = returns.find(r => r.date === d.date);
                    if (returnData) {
                        return config.colorScale(returnData.return);
                    }
                    return "#eee"; // Default color if no return data
                })
                .on("mouseover", function(event, d) {
                    const returns = dailyReturns[d.symbol];
                    const returnData = returns.find(r => r.date === d.date);
                    const returnValue = returnData ? (returnData.return * 100).toFixed(2) + "%" : "N/A";

                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            Date: ${d.date}<br>
                            Open: $${d.open.toFixed(2)}<br>
                            High: $${d.high.toFixed(2)}<br>
                            Low: $${d.low.toFixed(2)}<br>
                            Close: $${d.close.toFixed(2)}<br>
                            Volume: ${d.volume.toLocaleString()}<br>
                            Daily Return: ${returnValue}
                        `)
                        .style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                });

            // Add x-axis
            svg.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${config.height})`)
                .call(d3.axisBottom(xScale)
                    .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(allDates.length / 10) === 0))
                    .tickFormat(d3.timeFormat("%b %d")))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end")
                .attr("class", "axis-label");

            // Add y-axis
            svg.append("g")
                .attr("class", "axis axis--y")
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height + config.margin.bottom - 20)
                .style("text-anchor", "middle")
                .text("Date");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            function zoomed(event) {
                const transform = event.transform;
                svg.attr("transform", transform);
            }

            // Add legend
            renderLegend();
        }

        // Render the color legend
        function renderLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendData = [
                { color: config.colorScale(-0.1), label: "-10%" },
                { color: config.colorScale(-0.05), label: "-5%" },
                { color: config.colorScale(0), label: "0%" },
                { color: config.colorScale(0.05), label: "+5%" },
                { color: config.colorScale(0.1), label: "+10%" }
            ];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);
        }

        // Handle timeframe change
        function handleTimeframeChange() {
            fetchData();
        }

        // Handle update interval change
        function handleUpdateIntervalChange() {
            config.updateInterval = parseInt(updateIntervalSelect.value) * 1000;
            if (config.isUpdating) {
                clearInterval(updateIntervalId);
                startUpdates();
            }
        }

        // Toggle updates
        function toggleUpdates() {
            config.isUpdating = !config.isUpdating;
            toggleUpdatesBtn.textContent = config.isUpdating ? "Pause Updates" : "Resume Updates";

            if (config.isUpdating) {
                startUpdates();
            } else {
                clearInterval(updateIntervalId);
            }
        }

        // Start periodic updates
        function startUpdates() {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }

            updateIntervalId = setInterval(() => {
                if (config.isUpdating) {
                    fetchData();
                }
            }, config.updateInterval);
        }

        // Initialize the application
        init();
    </script>
</body>
</html>
```

