                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(stockData.map(d => d.date))
                .range([0, width])
                .padding(0.1);

            const yScale = d3.scaleLinear()
                .domain([d3.min(stockData, d => d.low), d3.max(stockData, d => d.high)])
                .range([height, 0]);

            // Color scale based on price change
            const colorScale = d3.scaleQuantile()
                .domain(stockData.map(d => d.percentChange))
                .range(config.colors);

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [width, height]])
                .on("zoom", (event) => {
                    const newXScale = event.transform.rescaleX(xScale);
                    svg.selectAll(".bar")
                        .attr("x", d => newXScale(d.date))
                        .attr("width", newXScale.bandwidth());

                    // Update axes
                    svg.select(".x-axis").call(d3.axisBottom(newXScale).tickFormat(d3.timeFormat("%b %d")));
                });

            // Add zoom behavior to SVG
            svg.call(zoom);

            // Add bars
            svg.selectAll(".bar")
                .data(stockData)
                .enter()
                .append("rect")
                .attr("class", "bar")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(Math.max(d.open, d.close)))
                .attr("width", xScale.bandwidth())
                .attr("height", d => Math.abs(yScale(d.open) - yScale(d.close)))
                .attr("fill", d => colorScale(d.percentChange))
                .on("mouseover", function(event, d) {
                    tooltip.style("display", "block")
                        .html(`
                            <strong>${currentStock}</strong><br>
                            Date: ${d3.timeFormat("%Y-%m-%d")(d.date)}<br>
                            Open: ${d.open.toFixed(2)}<br>
                            Close: ${d.close.toFixed(2)}<br>
                            High: ${d.high.toFixed(2)}<br>
                            Low: ${d.low.toFixed(2)}<br>
                            Change: ${d.priceChange.toFixed(2)} (${d.percentChange.toFixed(2)}%)
                        `);
                })
                .on("mousemove", function(event) {
                    tooltip.style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("display", "none");
                });

            // Add high-low lines
            svg.selectAll(".high-line")
                .data(stockData)
                .enter()
                .append("line")
                .attr("class", "high-line")
                .attr("x1", d => xScale(d.date) + xScale.bandwidth() / 2)
                .attr("x2", d => xScale(d.date) + xScale.bandwidth() / 2)
                .attr("y1", d => yScale(d.low))
                .attr("y2", d => yScale(d.high))
                .attr("stroke", "black")
                .attr("stroke-width", 1);

            // Add x-axis
            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${height})`)
                .call(d3.axisBottom(xScale).tickFormat(d3.timeFormat("%b %d")));

            // Add y-axis
            svg.append("g")
                .attr("class", "y-axis")
                .call(d3.axisLeft(yScale));

            // Add axis labels
            svg.append("text")
                .attr("class", "x-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Date");

            svg.append("text")
                .attr("class", "y-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Price ($)");

            // Add title
            svg.append("text")
                .attr("class", "title")
                .attr("x", width / 2)
                .attr("y", -20)
                .style("text-anchor", "middle")
                .style("font-size", "16px")
                .text(`${currentStock} Stock Price Heatmap (${currentTimeframe})`);
        }

        // Update the legend
        function updateLegend() {
            legendContainer.selectAll("*").remove();

            const legendItems = config.colors.map((color, i) => {
                const percentChange = d3.scaleQuantile()
                    .domain(stockData.map(d => d.percentChange))
                    .range(config.colors)
                    .invertExtent(color);

                return {
                    color,
                    range: percentChange
                };
            });

            const legend = legendContainer.selectAll(".legend-item")
                .data(legendItems)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legend.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d.color);

            legend.append("span")
                .text(d => {
                    const [min, max] = d.range;
                    if (min === undefined) return `> ${max.toFixed(2)}%`;
                    if (max === undefined) return `< ${min.toFixed(2)}%`;
                    return `${min.toFixed(2)}% - ${max.toFixed(2)}%`;
                });
        }

        // Initialize the application
        init();
    </script>
</body>
</html>
```

