    <script>
        // Configuration
        const config = {
            margin: { top: 50, right: 30, bottom: 30, left: 100 },
            width: 1000,
            height: 500,
            cellSize: 30,
            updateInterval: 5000 // 5 seconds
        };

        // DOM elements
        const heatmapContainer = d3.select("#heatmap-container");
        const tooltip = d3.select("#tooltip");
        const legendContainer = d3.select("#legend");

        // Data variables
        let stockData = [];
        let timePoints = [];
        let selectedStocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "TSLA"];
        let timeframe = "1m";
        let colorScaleType = "interpolateRdYlGn";
        let isUpdating = false;
        let updateIntervalId = null;

        // Initialize the visualization
        function init() {
            // Set up event listeners
            d3.select("#update-btn").on("click", updateHeatmap);
            d3.select("#timeframe").on("change", function() {
                timeframe = this.value;
            });
            d3.select("#stock-select").on("change", function() {
                selectedStocks = Array.from(this.selectedOptions).map(opt => opt.value);
            });
            d3.select("#color-scale").on("change", function() {
                colorScaleType = this.value;
                if (stockData.length > 0) {
                    updateHeatmap();
                }
            });

            // Initial load
            loadInitialData();
        }

        // Load initial data
        function loadInitialData() {
            // In a real application, you would fetch historical data here
            // For this demo, we'll generate synthetic data
            generateSyntheticData();

            // Start real-time updates
            startRealTimeUpdates();

            // Render the heatmap
            renderHeatmap();
        }

        // Generate synthetic data for demonstration
        function generateSyntheticData() {
            const now = new Date();
            const endDate = new Date(now);
            let startDate;

            // Set start date based on timeframe
            switch(timeframe) {
                case "1d":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 1);
                    break;
                case "1w":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 7);
                    break;
                case "1m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    break;
                case "3m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 3);
                    break;
                case "1y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 1);
                    break;
                default:
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
            }

            // Generate time points (hourly for 1 day, daily otherwise)
            timePoints = [];
            let currentDate = new Date(startDate);

            if (timeframe === "1d") {
                // Hourly data for 1 day
                while (currentDate <= now) {
                    timePoints.push(new Date(currentDate));
                    currentDate.setHours(currentDate.getHours() + 1);
                }
            } else {
                // Daily data for other timeframes
                while (currentDate <= now) {
                    timePoints.push(new Date(currentDate));
                    currentDate.setDate(currentDate.getDate() + 1);
                }
            }

            // Generate synthetic stock data
            stockData = selectedStocks.map(stock => {
                const basePrice = 100 + Math.random() * 200;
                const volatility = 0.01 + Math.random() * 0.05;

                return {
                    symbol: stock,
                    name: getStockName(stock),
                    prices: timePoints.map((date, i) => {
                        // Generate a price that trends slightly over time
                        const trend = i / timePoints.length * 10;
                        // Add some randomness
                        const randomFactor = (Math.random() - 0.5) * 2;
                        return basePrice + trend + randomFactor;
                    })
                };
            });
        }

        // Helper function to get stock names
        function getStockName(symbol) {
            const names = {
                "AAPL": "Apple Inc.",
                "MSFT": "Microsoft Corporation",
                "GOOGL": "Alphabet Inc.",
                "AMZN": "Amazon.com Inc.",
                "TSLA": "Tesla Inc.",
                "META": "Meta Platforms Inc.",
                "NVDA": "NVIDIA Corporation",
                "JPM": "JPMorgan Chase & Co.",
                "V": "Visa Inc.",
                "WMT": "Walmart Inc."
            };
            return names[symbol] || symbol;
        }

        // Start real-time updates
        function startRealTimeUpdates() {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }

            updateIntervalId = setInterval(() => {
                if (!isUpdating) {
                    updateData();
                }
            }, config.updateInterval);
        }

        // Update data with new values
        function updateData() {
            isUpdating = true;

            // In a real application, you would fetch new data here
            // For this demo, we'll simulate updates
            const now = new Date();

            // Add new time point
            timePoints.push(now);

            // Update each stock with a new price
            stockData.forEach(stock => {
                const lastPrice = stock.prices[stock.prices.length - 1];
                const change = (Math.random() - 0.5) * 2; // Random change between -2 and +2
                const newPrice = lastPrice + change;
                stock.prices.push(newPrice);
            });

            // Remove oldest time point if we've exceeded the timeframe
            let maxPoints;
            switch(timeframe) {
                case "1d": maxPoints = 24; break;
                case "1w": maxPoints = 7; break;
                case "1m": maxPoints = 30; break;
                case "3m": maxPoints = 90; break;
                case "1y": maxPoints = 365; break;
                default: maxPoints = 30;
            }

            if (timePoints.length > maxPoints) {
                timePoints.shift();
                stockData.forEach(stock => {
                    stock.prices.shift();
                });
            }

            // Update the visualization
            renderHeatmap();

            isUpdating = false;
        }

        // Update the heatmap with new parameters
        function updateHeatmap() {
            if (isUpdating) return;

            isUpdating = true;

            // Show loading state
            heatmapContainer.select(".loading").style("display", "block");

            // Generate new data based on current selections
            generateSyntheticData();

            // Render the updated heatmap
            renderHeatmap();

            isUpdating = false;
        }

        // Render the heatmap
        function renderHeatmap() {
            // Clear previous visualization
            heatmapContainer.selectAll("svg").remove();
            heatmapContainer.select(".loading").style("display", "none");

            // Calculate dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = heatmapContainer.append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Determine the value range for color scaling
            const allPrices = stockData.flatMap(stock => stock.prices);
            const minPrice = d3.min(allPrices);
            const maxPrice = d3.max(allPrices);

            // Create color scale
            const colorScale = d3.scaleSequential()
                .domain([minPrice, maxPrice])
                .interpolator(d3[colorScaleType]);

            // Create scales for x and y axes
            const xScale = d3.scaleBand()
                .domain(timePoints.map((d, i) => i))
                .range([0, width])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(stockData.map(stock => stock.symbol))
                .range([0, height])
                .padding(0.01);

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(i => {
                    const date = timePoints[i];
                    if (timeframe === "1d") {
                        return d3.timeFormat("%H:%M")(date);
                    } else {
                        return d3.timeFormat("%b %d")(date);
                    }
                })
                .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(timePoints.length / 10) === 0));

            const yAxis = d3.axisLeft(yScale);

            // Add axes to the SVG
            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${height})`)
                .call(xAxis)
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.append("g")
                .attr("class", "y-axis")
                .call(yAxis);

            // Add axis labels
            svg.append("text")
                .attr("class", "x-label")
                .attr("x", width / 2)
                .attr("y", height + config.margin.bottom - 10)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "y-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -height / 2)
                .attr("y", -config.margin.left + 20)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Add cells to the heatmap
            const cells = svg.selectAll(".cell")
                .data(stockData.flatMap(stock =>
                    stock.prices.map((price, i) => ({
                        symbol: stock.symbol,
                        timeIndex: i,
                        price: price
                    }))
                ))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.timeIndex))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    const date = timePoints[d.timeIndex];
                    const formattedDate = timeframe === "1d"
                        ? d3.timeFormat("%b %d, %H:%M")(date)
                        : d3.timeFormat("%b %d, %Y")(date);

                    tooltip.style("display", "block")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            ${formattedDate}<br>
                            Price: $${d.price.toFixed(2)}
                        `)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("display", "none");
                });

            // Add zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.attr("transform", `translate(${config.margin.left},${config.margin.top}) scale(${transform.k})`);
                });

            heatmapContainer.call(zoom);

            // Add legend
            renderLegend(colorScale, minPrice, maxPrice);

            // Add zoom/pan instructions
            svg.append("text")
                .attr("x", width - 10)
                .attr("y", height - 10)
                .attr("text-anchor", "end")
                .style("font-size", "10px")
                .style("fill", "#666")
                .text("Use mouse wheel to zoom, drag to pan");
        }

        // Render the legend
        function renderLegend(colorScale, minPrice, maxPrice) {
            legendContainer.html("");

            const legendWidth = 300;
            const legendHeight = 20;
            const legendScale = d3.scaleLinear()
                .domain([minPrice, maxPrice])
                .range([0, legendWidth]);

            const legendAxis = d3.axisBottom(legendScale)
                .ticks(5)
                .tickFormat(d => `$${d.toFixed(2)}`);

            const legendSvg = legendContainer.append("svg")
                .attr("width", legendWidth + 50)
                .attr("height", legendHeight + 30)
                .append("g")
                .attr("transform", "translate(20,10)");

            // Add color gradient
            const gradient = legendSvg.append("defs")
                .append("linearGradient")
                .attr("id", "legend-gradient")
                .attr("x1", "0%")
                .attr("y1", "0%")
                .attr("x2", "100%")
                .attr("y2", "0%");

            gradient.append("stop")
                .attr("offset", "0%")
                .attr("stop-color", colorScale(minPrice));

            gradient.append("stop")
                .attr("offset", "100%")
                .attr("stop-color", colorScale(maxPrice));

            legendSvg.append("rect")
                .attr("width", legendWidth)
                .attr("height", legendHeight)
                .style("fill", "url(#legend-gradient)");

            // Add axis
            legendSvg.append("g")
                .attr("class", "legend-axis")
                .attr("transform", `translate(0,${legendHeight})`)
                .call(legendAxis);
        }

        // Initialize the application when the DOM is loaded
        document.addEventListener("DOMContentLoaded", init);
    </script>
</body>
</html>
