                this.zoom = d3.zoom()
                    .scaleExtent([1, 10])
                    .on("zoom", (event) => this.zoomed(event));

                this.svg.call(this.zoom);

                // Set up event listeners
                d3.select("#stock-select").on("change", () => this.handleStockChange());
                d3.select("#timeframe-select").on("change", () => this.handleTimeframeChange());
                d3.select("#update-interval").on("change", () => this.handleUpdateIntervalChange());
                d3.select("#reset-btn").on("change", () => this.resetZoom());

                // Initial data load
                this.loadData();

                // Set up periodic updates
                this.setupAutoUpdate();
            }

            handleStockChange() {
                this.currentStock = d3.select("#stock-select").property("value");
                this.loadData();
