            handleTimeframeChange() {
                this.currentTimeframe = d3.select("#timeframe-select").property("value");
                this.loadData();
            }

            handleUpdateIntervalChange() {
                const interval = parseInt(d3.select("#update-interval").property("value")) * 1000;
                clearInterval(this.updateInterval);
                this.setupAutoUpdate(interval);
            }

            setupAutoUpdate(interval = 10000) {
                this.updateInterval = setInterval(() => {
                    this.loadData(true);
                }, interval);
            }

            resetZoom() {
                this.svg.transition()
                    .duration(750)
                    .call(this.zoom.transform, d3.zoomIdentity);
            }

            zoomed(event) {
                const { transform } = event;
                this.svg.selectAll("g").attr("transform", transform);
            }

            async loadData(isUpdate = false) {
                if (this.isLoading) return;

                this.isLoading = true;
                d3.select("#heatmap-container .loading").style("display", "block");

                try {
                    // In a real application, you would fetch data from an API
                    // For this demo, we'll generate mock data
                    const mockData = this.generateMockData();

                    // Cache the data
                    this.stockDataCache[`${this.currentStock}-${this.currentTimeframe}`] = mockData;

                    // Update the visualization
                    this.updateVisualization(mockData, isUpdate);
                } catch (error) {
                    console.error("Error loading data:", error);
                } finally {
                    this.isLoading = false;
                    d3.select("#heatmap-container .loading").style("display", "none");
                }
            }

            generateMockData() {
                // Generate mock data based on current stock and timeframe
                const now = new Date();
                const timeframes = {
                    '1d': { count: 24, interval: 'hour' },
                    '1w': { count: 7, interval: 'day' },
                    '1m': { count: 30, interval: 'day' },
                    '3m': { count: 90, interval: 'day' },
                    '1y': { count: 12, interval: 'month' },
                    '5y': { count: 60, interval: 'month' }
                };

                const { count, interval } = timeframes[this.currentTimeframe];
                const data = [];

                for (let i = 0; i < count; i++) {
                    const date = new Date(now);
                    if (interval === 'hour') {
                        date.setHours(now.getHours() - i);
                    } else if (interval === 'day') {
                        date.setDate(now.getDate() - i);
                    } else if (interval === 'month') {
                        date.setMonth(now.getMonth() - i);
                    }

                    // Generate random price data for each hour in the interval
                    const hoursInInterval = interval === 'hour' ? 1 : 24;
                    for (let h = 0; h < hoursInInterval; h++) {
                        const hourDate = new Date(date);
                        hourDate.setHours(h);

                        // Generate random price data (in a real app, this would come from an API)
                        const open = 100 + Math.random() * 100;
                        const close = open + (Math.random() * 20 - 10);
                        const high = Math.max(open, close) + Math.random() * 5;
                        const low = Math.min(open, close) - Math.random() * 5;
                        const volume = Math.floor(Math.random() * 1000000);

                        data.push({
                            date: hourDate,
                            open,
                            close,
                            high,
                            low,
                            volume
                        });
                    }
                }

                return data.sort((a, b) => a.date - b.date);
            }

            updateVisualization(data, isUpdate = false) {
                const container = d3.select("#heatmap-container");
                const width = container.node().getBoundingClientRect().width;
                const height = container.node().getBoundingClientRect().height;

                // Clear previous visualization
                this.svg.selectAll("*").remove();

                // Create scales
                const margin = { top: 20, right: 20, bottom: 60, left: 60 };
                const innerWidth = width - margin.left - margin.right;
                const innerHeight = height - margin.top - margin.bottom;

                // Group by date (for daily view) or by hour (for hourly view)
                const groupedData = d3.groups(
                    data,
                    d => d3.timeDay(d.date),
                    d => d3.timeHour(d.date)
                );

                // Flatten the data for the heatmap
                const heatmapData = [];
                groupedData.forEach(([day, hours]) => {
                    hours.forEach(([hour, values]) => {
                        if (values.length > 0) {
                            const first = values[0];
                            const last = values[values.length - 1];
                            heatmapData.push({
                                day,
                                hour,
                                open: first.open,
                                close: last.close,
                                high: Math.max(...values.map(v => v.high)),
                                low: Math.min(...values.map(v => v.low)),
                                volume: values.reduce((sum, v) => sum + v.volume, 0)
                            });
                        }
                    });
                });

                // Create scales
                const days = Array.from(new Set(heatmapData.map(d => d.day)));
                const hours = Array.from(new Set(heatmapData.map(d => d.hour)));

                this.xScale = d3.scaleBand()
                    .domain(days)
                    .range([margin.left, innerWidth + margin.left])
                    .padding(0.05);

                this.yScale = d3.scaleBand()
                    .domain(hours)
                    .range([margin.top, innerHeight + margin.top])
                    .padding(0.05);

                // Color scale based on price change
                const priceChanges = heatmapData.map(d => d.close - d.open);
                const maxChange = Math.max(...priceChanges.map(Math.abs));

                this.colorScale = d3.scaleDiverging()
                    .domain([-maxChange, 0, maxChange])
                    .interpolator(d3.interpolateRdYlGn);

                // Create the heatmap
                const cells = this.svg.append("g")
                    .selectAll("rect")
                    .data(heatmapData)
                    .join("rect")
                    .attr("x", d => this.xScale(d.day))
                    .attr("y", d => this.yScale(d.hour))
                    .attr("width", this.xScale.bandwidth())
                    .attr("height", this.yScale.bandwidth())
                    .attr("fill", d => this.colorScale(d.close - d.open))
                    .on("mouseover", (event, d) => this.showTooltip(event, d))
                    .on("mouseout", () => this.hideTooltip());

                // Add axes
                const xAxis = d3.axisBottom(this.xScale)
                    .tickFormat(d3.timeFormat("%a %m/%d"))
                    .tickSizeOuter(0);

                const yAxis = d3.axisLeft(this.yScale)
                    .tickFormat(d3.timeFormat("%H:%M"))
                    .tickSizeOuter(0);

                this.svg.append("g")
                    .attr("transform", `translate(0,${innerHeight + margin.top})`)
                    .call(xAxis)
                    .selectAll("text")
                    .attr("transform", "rotate(-45)")
                    .style("text-anchor", "end");

                this.svg.append("g")
                    .attr("transform", `translate(${margin.left},0)`)
                    .call(yAxis);

                // Add axis labels
                this.svg.append("text")
                    .attr("x", width / 2)
                    .attr("y", height - 10)
                    .style("text-anchor", "middle")
                    .text("Date");

                this.svg.append("text")
                    .attr("transform", "rotate(-90)")
                    .attr("y", 20)
                    .attr("x", -height / 2)
                    .style("text-anchor", "middle")
                    .text("Time");

                // Create legend
                this.createLegend();

                // Add zoom behavior
                this.svg.call(this.zoom);
            }

            createLegend() {
                const legend = d3.select("#legend");
                legend.selectAll("*").remove();

                const legendData = [
                    { color: this.colorScale(-10), label: "Price Decrease" },
                    { color: this.colorScale(0), label: "No Change" },
                    { color: this.colorScale(10), label: "Price Increase" }
                ];

                const legendItems = legend.selectAll(".legend-item")
                    .data(legendData)
                    .enter()
                    .append("div")
                    .attr("class", "legend-item");

                legendItems.append("div")
                    .attr("class", "legend-color")
                    .style("background-color", d => d.color);

                legendItems.append("span")
                    .text(d => d.label);
            }

            showTooltip(event, d) {
                const formatTime = d3.timeFormat("%a %b %d %H:%M");
                const formatCurrency = d => `$${d.toFixed(2)}`;

                this.tooltip.style("visibility", "visible")
                    .html(`
                        <strong>${this.currentStock}</strong><br>
                        Date: ${formatTime(d.day)}<br>
                        Time: ${formatTime(d.hour)}<br>
                        Open: ${formatCurrency(d.open)}<br>
                        Close: ${formatCurrency(d.close)}<br>
                        High: ${formatCurrency(d.high)}<br>
                        Low: ${formatCurrency(d.low)}<br>
                        Volume: ${d.volume.toLocaleString()}
                    `)
                    .style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY + 10) + "px");
            }

            hideTooltip() {
                this.tooltip.style("visibility", "hidden");
            }
        }

        // Initialize the application when the DOM is loaded
        document.addEventListener("DOMContentLoaded", () => {
            new StockHeatmap();
        });
    </script>
</body>
</html>
