            stockData = stocks.map(stock => {
                const values = [];
                for (let i = 0; i < numTimePoints; i++) {
                    // Generate random price change between -5% and +5%
                    const change = (Math.random() * 10 - 5) / 100;
                    const price = 100 + (Math.random() * 200); // Base price between 100 and 300
                    values.push({
                        time: i,
                        value: price * (1 + change),
                        change: change
                    });
                }
                return {
                    stock: stock,
                    values: values
                };
            });

            // Create scales
            xScale = d3.scaleBand()
                .domain(timeLabels)
                .range([0, config.width - config.margin.left - config.margin.right])
                .padding(0.05);

            yScale = d3.scaleBand()
                .domain(stocks)
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.05);

            // Get all values for color scale
            const allValues = stockData.flatMap(d => d.values.map(v => v.value));
            const minValue = d3.min(allValues);
            const maxValue = d3.max(allValues);

            colorScale = d3.scaleQuantile()
                .domain([minValue, maxValue])
                .range(config.colors);
        }

        // Update the visualization with new data
        function updateVisualization() {
            // Update axes
            xAxis.call(d3.axisBottom(xScale))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            yAxis.call(d3.axisLeft(yScale));

            // Bind data to cells
            const cells = heatmap.selectAll(".cell")
                .data(stockData.flatMap(d => d.values.map(v => ({
                    stock: d.stock,
                    time: v.time,
                    value: v.value,
                    change: v.change
                }))));

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(xScale.domain()[d.time]))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.value))
                .on("mouseover", showTooltip)
                .on("mouseout", hideTooltip)
                .merge(cells)
                .transition()
                .duration(500)
                .attr("x", d => xScale(xScale.domain()[d.time]))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.value));

            // Remove old cells
            cells.exit().remove();

            // Update legend
            updateLegend();
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            tooltip.style("display", "block")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${xScale.domain()[d.time]}<br>
                    Price: $${d.value.toFixed(2)}<br>
                    Change: ${(d.change * 100).toFixed(2)}%
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            tooltip.style("display", "none");
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the heatmap group
            heatmap.attr("transform",
                `translate(${config.margin.left + transform.x},${config.margin.top + transform.y})` +
                ` scale(${transform.k})`);

            // Adjust the axes
            xAxis.call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            yAxis.call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));

            // Adjust cell positions
            heatmap.selectAll(".cell")
                .attr("x", d => transform.applyX(xScale(xScale.domain()[d.time])))
                .attr("y", d => transform.applyY(yScale(d.stock)))
                .attr("width", xScale.bandwidth() * transform.k)
                .attr("height", yScale.bandwidth() * transform.k);
        }

        // Update the legend
        function updateLegend() {
            // Clear existing legend
            legendContainer.html("");

            // Get the quantile thresholds
            const thresholds = colorScale.quantiles();

            // Create legend items
            const legendItems = legendContainer.selectAll(".legend-item")
                .data(thresholds)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            // Add color squares
            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", (d, i) => config.colors[i]);

            // Add labels
            legendItems.append("span")
                .text((d, i) => {
                    if (i === 0) {
                        return `< ${d.toFixed(2)}`;
                    } else if (i === thresholds.length - 1) {
                        return `≥ ${d.toFixed(2)}`;
                    } else {
                        return `${thresholds[i-1].toFixed(2)} - ${d.toFixed(2)}`;
                    }
                });
        }

        // Initialize the visualization when the page loads
        document.addEventListener("DOMContentLoaded", init);

        // Clean up when the page unloads
        window.addEventListener("beforeunload", () => {
            clearInterval(updateInterval);
        });
    </script>
</body>
</html>
