            width: 1200,
            height: 600,
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            updateInterval: 30000 // 30 seconds
        };

        // Main variables
        let svg, heatmap, xScale, yScale, xAxis, yAxis, zoom;
        let data = [];
        let currentTimeframe = '1m';
        let selectedStocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'FB', 'NVDA', 'JPM', 'V', 'WMT'];
        let updateIntervalId;

        // Initialize the visualization
        function init() {
            // Set up SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", "100%")
                .attr("height", "100%")
                .attr("viewBox", `0 0 ${config.width} ${config.height}`);

            // Add zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Create heatmap group
            heatmap = svg.append("g")
                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

            // Add tooltip
            const tooltip = d3.select("#tooltip");

            // Set up event listeners
            document.getElementById('timeframe').addEventListener('change', handleTimeframeChange);
            document.getElementById('stock-select').addEventListener('change', handleStockSelection);
            document.getElementById('update-btn').addEventListener('click', fetchData);
            document.getElementById('reset-btn').addEventListener('click', resetView);

            // Initial data fetch
            fetchData();

            // Set up periodic updates
            updateIntervalId = setInterval(fetchData, config.updateInterval);
        }

        // Fetch stock data (simulated with mock data)
        async function fetchData() {
            try {
                // Show loading indicator
                d3.select(".loading").style("display", "block");

                // In a real application, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
                // For this example, we'll use mock data
                const mockData = generateMockData();

                // Process the data
                processData(mockData);

                // Hide loading indicator
                d3.select(".loading").style("display", "none");
            } catch (error) {
                console.error("Error fetching data:", error);
                d3.select(".loading").text("Error loading data. Please try again.");
            }
        }

        // Generate mock data for demonstration
        function generateMockData() {
            const timeframe = document.getElementById('timeframe').value;
            const stocks = Array.from(document.getElementById('stock-select').selectedOptions).map(opt => opt.value);

            // Determine number of time points based on timeframe
            let numTimePoints;
            switch(timeframe) {
                case '1d': numTimePoints = 24; break; // Hourly
                case '1w': numTimePoints = 7; break; // Daily
                case '1m': numTimePoints = 30; break; // Daily
                case '3m': numTimePoints = 90; break; // Daily
                case '1y': numTimePoints = 252; break; // Daily
                default: numTimePoints = 30;
            }

            // Generate time points
            const now = new Date();
            const timePoints = [];
            for (let i = 0; i < numTimePoints; i++) {
                let date;
                switch(timeframe) {
                    case '1d':
                        date = new Date(now.getTime() - (23 - i) * 60 * 60 * 1000);
                        break;
                    case '1w':
                        date = new Date(now.getTime() - (6 - i) * 24 * 60 * 60 * 1000);
                        break;
                    default:
                        date = new Date(now.getTime() - (numTimePoints - 1 - i) * 24 * 60 * 60 * 1000);
                }
                timePoints.push(date);
            }

            // Generate mock data for each stock
            const data = [];
            stocks.forEach(stock => {
                const basePrice = 100 + Math.random() * 200;
                let prevPrice = basePrice;

                timePoints.forEach(time => {
                    // Simulate price movement
                    const change = (Math.random() - 0.5) * 0.1; // Random change between -0.05 and 0.05
                    const price = prevPrice * (1 + change);
                    prevPrice = price;

                    data.push({
                        stock: stock,
                        time: time,
                        price: price,
                        change: change
                    });
                });
            });

            return data;
        }

        // Process the data and update the visualization
        function processData(rawData) {
            // Group data by stock
            const nestedData = d3.group(rawData, d => d.stock);

            // Convert to array of objects with stock and values
            data = Array.from(nestedData, ([stock, values]) => ({
                stock: stock,
                values: values
            }));

            // Sort stocks alphabetically
            data.sort((a, b) => a.stock.localeCompare(b.stock));

            // Update the visualization
            updateVisualization();
        }

        // Update the visualization with current data
        function updateVisualization() {
            if (!data || data.length === 0) return;

            // Get all time points (assuming all stocks have the same time points)
            const allTimes = data[0].values.map(d => d.time);

            // Set up scales
            xScale = d3.scaleBand()
                .domain(allTimes)
                .range([0, config.width - config.margin.left - config.margin.right])
                .padding(0.05);

            yScale = d3.scaleBand()
                .domain(data.map(d => d.stock))
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.1);

            // Create color scale based on price changes
            const allChanges = data.flatMap(d => d.values.map(v => v.change));
            const minChange = d3.min(allChanges);
            const maxChange = d3.max(allChanges);
            config.colorScale.domain([minChange, maxChange]);

            // Create heatmap cells
            const cells = heatmap.selectAll(".cell")
                .data(data.flatMap(d => d.values.map(v => ({
                    stock: d.stock,
                    time: v.time,
                    change: v.change,
                    price: v.price
                }))));

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change))
                .on("mouseover", function(event, d) {
                    const tooltip = d3.select("#tooltip");
                    tooltip.html(`
                        <strong>${d.stock}</strong><br>
                        ${d.time.toLocaleString()}<br>
                        Price: ${d.price.toFixed(2)}<br>
                        Change: ${(d.change * 100).toFixed(2)}%
                    `)
                    .style("visibility", "visible")
                    .style("top", (event.pageY - 10) + "px")
                    .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("visibility", "hidden");
                });

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change));

            // Remove old cells
            cells.exit().remove();

            // Update axes
            updateAxes();

            // Update legend
            updateLegend(minChange, maxChange);
        }

        // Update the axes
        function updateAxes() {
            // Remove existing axes
            heatmap.selectAll(".axis").remove();

            // Create x-axis
            xAxis = d3.axisBottom(xScale)
                .tickFormat(d => {
                    const timeframe = document.getElementById('timeframe').value;
                    if (timeframe === '1d') {
                        return d3.timeFormat("%H:%M")(d);
                    } else {
                        return d3.timeFormat("%b %d")(d);
                    }
                })
                .tickSizeOuter(0);

            heatmap.append("g")
                .attr("class", "axis x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.top - config.margin.bottom})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-45)");

            // Create y-axis
            yAxis = d3.axisLeft(yScale)
                .tickSizeOuter(0);

            heatmap.append("g")
                .attr("class", "axis y-axis")
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            heatmap.append("text")
                .attr("class", "axis-label")
                .attr("x", (config.width - config.margin.left - config.margin.right) / 2)
                .attr("y", config.height - config.margin.top - config.margin.bottom + 40)
                .style("text-anchor", "middle")
                .text("Time");

            heatmap.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -(config.height - config.margin.top - config.margin.bottom) / 2)
                .attr("y", -50)
                .style("text-anchor", "middle")
                .text("Stock");
        }

        // Update the legend
        function updateLegend(minChange, maxChange) {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            // Create legend items
            const legendItems = [
                { label: "Decrease", value: minChange },
                { label: "Neutral", value: 0 },
                { label: "Increase", value: maxChange }
            ];

            legendItems.forEach(item => {
                const legendItem = legend.append("div")
                    .attr("class", "legend-item");

                legendItem.append("div")
                    .attr("class", "legend-color")
                    .style("background-color", config.colorScale(item.value));

                legendItem.append("span")
                    .text(item.label);
            });
        }

        // Handle timeframe change
        function handleTimeframeChange() {
            currentTimeframe = document.getElementById('timeframe').value;
            fetchData();
        }

        // Handle stock selection change
        function handleStockSelection() {
            selectedStocks = Array.from(document.getElementById('stock-select').selectedOptions).map(opt => opt.value);
            fetchData();
        }

        // Reset the view to default
        function resetView() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Handle zoom/pan
        function zoomed(event) {
            heatmap.attr("transform", event.transform);

            // Adjust axis labels
            heatmap.selectAll(".x-axis text")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", `rotate(-45) translate(${event.transform.x}, ${event.transform.y})`);

            heatmap.selectAll(".y-axis text")
                .attr("transform", `translate(${event.transform.x}, ${event.transform.y})`);
        }

        // Initialize the visualization when the page loads
        window.addEventListener('load', init);

        // Clean up when the page is unloaded
        window.addEventListener('beforeunload', () => {
            if (updateIntervalId) {
                clearInterval(updateIntervalId);
            }
        });
    </script>
</body>
</html>
