                    <option value="MSFT" selected>MSFT (Microsoft)</option>
                    <option value="GOOGL" selected>GOOGL (Alphabet)</option>
                    <option value="AMZN" selected>AMZN (Amazon)</option>
                    <option value="TSLA" selected>TSLA (Tesla)</option>
                    <option value="META" selected>META (Meta)</option>
                    <option value="NVDA" selected>NVDA (NVIDIA)</option>
                    <option value="JPM" selected>JPM (JPMorgan Chase)</option>
                    <option value="V" selected>V (Visa)</option>
                    <option value="WMT" selected>WMT (Walmart)</option>
                </select>
            </div>

            <div class="control-group">
                <button id="update-btn">Update</button>
            </div>
        </div>

        <div id="heatmap-container">
            <div class="tooltip" id="tooltip"></div>
            <div class="loading" id="loading">Loading data...</div>
        </div>

        <div class="legend" id="legend"></div>
    </div>

    <script>
        // Configuration
        const config = {
            margin: { top: 50, right: 30, bottom: 30, left: 100 },
            width: 1000,
            height: 500,
            colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]),
            updateInterval: 60000, // 1 minute
            maxDataPoints: 100
        };

        // DOM elements
        const heatmapContainer = d3.select("#heatmap-container");
        const tooltip = d3.select("#tooltip");
        const loadingIndicator = d3.select("#loading");
        const legendContainer = d3.select("#legend");

        // Data variables
        let stockData = [];
        let timeframe = "1m";
        let selectedStocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "META", "NVDA", "JPM", "V", "WMT"];
        let updateIntervalId = null;

        // Initialize the visualization
        function init() {
            // Set up event listeners
            d3.select("#timeframe").on("change", function() {
                timeframe = this.value;
            });

            d3.select("#stocks").on("change", function() {
                selectedStocks = Array.from(this.selectedOptions).map(opt => opt.value);
            });

            d3.select("#update-btn").on("click", function() {
                fetchData();
            });

            // Initial data fetch
            fetchData();

            // Set up auto-refresh
            updateIntervalId = setInterval(fetchData, config.updateInterval);
        }

        // Fetch stock data (simulated with mock data)
        async function fetchData() {
            loadingIndicator.style("display", "block");

            try {
                // In a real application, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
                // For this example, we'll use mock data
                const mockData = generateMockData(selectedStocks, timeframe);
                processData(mockData);
            } catch (error) {
                console.error("Error fetching data:", error);
                loadingIndicator.text("Error loading data. Please try again.");
            } finally {
                loadingIndicator.style("display", "none");
            }
        }

        // Process the data and update the visualization
        function processData(data) {
            stockData = data;

            // Sort stocks alphabetically
            stockData.sort((a, b) => a.symbol.localeCompare(b.symbol));

            // Create or update the heatmap
            createHeatmap();
        }

        // Create the heatmap visualization
        function createHeatmap() {
            // Clear previous visualization
            heatmapContainer.selectAll("svg").remove();

            // Set up dimensions
            const width = config.width - config.margin.left - config.margin.right;
            const height = config.height - config.margin.top - config.margin.bottom;

            // Create SVG
            const svg = heatmapContainer.append("svg")
                .attr("width", config.width)
                .attr("height", config.height)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(stockData[0].prices.map(d => d.date))
                .range([0, width])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(stockData.map(d => d.symbol))
                .range([0, height])
                .padding(0.05);

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .translateExtent([[0, 0], [width, height]])
                .on("zoom", (event) => {
                    svg.attr("transform", event.transform);
                });

            // Apply zoom to the SVG
            svg.call(zoom);

            // Add X axis
            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0,${height})`)
                .call(d3.axisBottom(xScale).tickFormat(d3.timeFormat("%b %d")))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            // Add Y axis
            svg.append("g")
                .attr("class", "y-axis")
                .call(d3.axisLeft(yScale));

            // Add cells
            const cells = svg.selectAll(".cell")
                .data(stockData.flatMap(d => d.prices.map(p => ({
                    symbol: d.symbol,
                    date: p.date,
                    price: p.price,
                    change: p.change
                }))))
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => config.colorScale(d.change))
                .on("mouseover", function(event, d) {
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            Date: ${d3.timeFormat("%b %d, %Y")(d.date)}<br>
                            Price: $${d.price.toFixed(2)}<br>
                            Change: ${(d.change * 100).toFixed(2)}%
                        `);
                })
                .on("mousemove", function(event) {
                    tooltip.style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                });

            // Add legend
            createLegend();
        }

        // Create the color legend
        function createLegend() {
            legendContainer.selectAll("*").remove();

            const legendData = [
                { color: config.colorScale(-0.1), label: "-10%" },
                { color: config.colorScale(-0.05), label: "-5%" },
                { color: config.colorScale(0), label: "0%" },
                { color: config.colorScale(0.05), label: "5%" },
                { color: config.colorScale(0.1), label: "10%" }
            ];

            const legendItems = legendContainer.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d.color);

            legendItems.append("span")
                .text(d => d.label);
        }

        // Generate mock data for demonstration
        function generateMockData(stocks, timeframe) {
            const now = new Date();
            let startDate, numDays;

            switch(timeframe) {
                case "1d":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 1);
                    numDays = 1;
                    break;
                case "1w":
                    startDate = new Date(now);
                    startDate.setDate(now.getDate() - 7);
                    numDays = 7;
                    break;
                case "1m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    numDays = 30;
                    break;
                case "3m":
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 3);
                    numDays = 90;
                    break;
                case "1y":
                    startDate = new Date(now);
                    startDate.setFullYear(now.getFullYear() - 1);
                    numDays = 365;
                    break;
                default:
                    startDate = new Date(now);
                    startDate.setMonth(now.getMonth() - 1);
                    numDays = 30;
            }

            // Limit the number of data points
            const step = Math.max(1, Math.floor(numDays / config.maxDataPoints));

            return stocks.map(symbol => {
                const prices = [];
                let basePrice = 100 + Math.random() * 200; // Random base price between 100-300

                for (let i = 0; i < numDays; i += step) {
                    const date = new Date(startDate);
                    date.setDate(startDate.getDate() + i);

                    // Generate random price change
                    const change = (Math.random() - 0.5) * 0.2; // Random change between -10% and +10%
                    const price = basePrice * (1 + change);

                    prices.push({
                        date: date,
                        price: price,
                        change: change
                    });

                    basePrice = price;
                }

                return {
                    symbol: symbol,
                    prices: prices
                };
            });
        }

        // Initialize the application when the DOM is loaded
        document.addEventListener("DOMContentLoaded", init);
    </script>
</body>
</html>
```

