                    const value = Math.random() * 100; // Random value for the heatmap

                    data.push({
                        time: time.toLocaleString(),
                        priceLevel: priceLevel,
                        value: value
                    });
                }
            }

            return data;
        }

        // Initialize the visualization when the page loads
        window.addEventListener("load", init);
