            }

            // Generate simulated stock price data
            function generateSimulatedData(stock, timeRange) {
                // Determine number of time points based on time range
                let numPoints;
                switch(timeRange) {
                    case '1d': numPoints = 24; break; // 1 hour intervals
                    case '1w': numPoints = 168; break; // 1 hour intervals
                    case '1m': numPoints = 30; break; // 1 day intervals
                    case '3m': numPoints = 90; break; // 1 day intervals
                    case '1y': numPoints = 252; break; // 1 day intervals
                    default: numPoints = 30;
                }

                // Generate random price levels (for demonstration)
                const priceLevels = Array.from({length: 20}, (_, i) => config.minPrice + i * 5);

                // Generate time labels
                const timeLabels = [];
                const now = new Date();

                for (let i = 0; i < numPoints; i++) {
                    let date;
                    switch(timeRange) {
                        case '1d':
                            date = new Date(now.getTime() - (24 - i) * 60 * 60 * 1000);
                            timeLabels.push(date.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'}));
                            break;
                        case '1w':
                            date = new Date(now.getTime() - (168 - i) * 60 * 60 * 1000);
                            timeLabels.push(date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], {hour: '2-digit'}));
                            break;
                        default:
                            date = new Date(now.getTime() - (numPoints - i) * 24 * 60 * 60 * 1000);
                            timeLabels.push(date.toLocaleDateString());
                    }
                }

                // Generate data points
                currentData = [];
                for (let i = 0; i < numPoints; i++) {
                    for (let j = 0; j < priceLevels.length; j++) {
                        // Simulate price movement with some randomness
                        const basePrice = priceLevels[j];
                        const variation = (Math.random() - 0.5) * 10; // Random variation
                        const price = Math.max(config.minPrice, Math.min(config.maxPrice, basePrice + variation));

                        currentData.push({
                            time: i,
                            priceLevel: j,
                            price: price,
                            timeLabel: timeLabels[i],
                            priceLabel: `$${price.toFixed(2)}`
                        });
                    }
                }

                // Update the visualization
                updateVisualization();
            }

            // Update the visualization with new data
            function updateVisualization() {
                // Get unique time and price levels
                const times = [...new Set(currentData.map(d => d.time))];
                const priceLevels = [...new Set(currentData.map(d => d.priceLevel))];

                // Update scales
                xScale.domain(times);
                yScale.domain(priceLevels);

                // Create a nested data structure for easier access
                const nestedData = d3.group(currentData, d => d.time, d => d.priceLevel);

                // Create heatmap cells
                const cells = heatmapGroup.selectAll('.heatmap-cell')
                    .data(currentData, d => `${d.time}-${d.priceLevel}`);

                // Enter new cells
                cells.enter()
                    .append('rect')
                    .attr('class', 'heatmap-cell')
                    .attr('x', d => xScale(d.time))
                    .attr('y', d => yScale(d.priceLevel))
                    .attr('width', xScale.bandwidth())
                    .attr('height', yScale.bandwidth())
                    .attr('fill', d => colorScale(d.price))
                    .on('mouseover', function(event, d) {
                        tooltip.style('visibility', 'visible')
                            .html(`<strong>${stockSelect.value}</strong><br>
                                  Time: ${d.timeLabel}<br>
                                  Price: ${d.priceLabel}<br>
                                  Level: ${d.priceLevel}`);
                    })
                    .on('mousemove', function(event) {
                        tooltip.style('top', (event.pageY - 10) + 'px')
                            .style('left', (event.pageX + 10) + 'px');
                    })
                    .on('mouseout', function() {
                        tooltip.style('visibility', 'hidden');
                    });

                // Update existing cells
                cells.transition()
                    .duration(500)
                    .attr('fill', d => colorScale(d.price));

                // Remove old cells
                cells.exit().remove();

                // Update axes
                updateAxes();
            }

            // Update the axes based on current scales
            function updateAxes() {
                // Get unique time labels
                const timeLabels = [...new Set(currentData.map(d => d.timeLabel))];

                // Update x-axis
                const xAxis = d3.axisBottom(xScale)
                    .tickValues(xScale.domain().filter((_, i) => i % Math.ceil(xScale.domain().length / 10) === 0))
                    .tickFormat((d, i) => timeLabels[d]);

                svg.select('.axis--x')
                    .transition()
                    .duration(500)
                    .call(xAxis)
                    .selectAll('text')
                    .style('text-anchor', 'end')
                    .attr('dx', '-.8em')
                    .attr('dy', '.15em')
                    .attr('transform', 'rotate(-45)');

                // Update y-axis
                const yAxis = d3.axisLeft(yScale)
                    .tickFormat(d => `$${config.minPrice + d * 5}`);

                svg.select('.axis--y')
                    .transition()
                    .duration(500)
                    .call(yAxis);
            }

            // Handle zoom/pan events
            function zoomed(event) {
                const transform = event.transform;

                // Apply the transform to the heatmap group
                heatmapGroup.attr('transform',
                    `translate(${config.margin.left + transform.x}, ${config.margin.top + transform.y}) scale(${transform.k})`);

                // Adjust the scales
                const newXScale = transform.rescaleX(xScale);
                const newYScale = transform.rescaleY(yScale);

                // Update the axes with the new scales
                const xAxis = d3.axisBottom(newXScale)
                    .tickValues(newXScale.domain().filter((_, i) => i % Math.ceil(newXScale.domain().length / 10) === 0))
                    .tickFormat((d, i) => {
                        const timeLabels = [...new Set(currentData.map(d => d.timeLabel))];
                        return timeLabels[d];
                    });

                svg.select('.axis--x')
                    .call(xAxis)
                    .selectAll('text')
                    .style('text-anchor', 'end')
                    .attr('dx', '-.8em')
                    .attr('dy', '.15em')
                    .attr('transform', 'rotate(-45)');

                const yAxis = d3.axisLeft(newYScale)
                    .tickFormat(d => `$${config.minPrice + d * 5}`);

                svg.select('.axis--y')
                    .call(yAxis);
            }

            // Reset the view to default
            function resetView() {
                svg.transition()
                    .duration(750)
                    .call(zoom.transform, d3.zoomIdentity);
            }

            // Set up the update interval based on user selection
            function setupUpdateInterval() {
                const interval = parseInt(updateIntervalSelect.value);

                // Clear any existing interval
                if (window.updateInterval) {
                    clearInterval(window.updateInterval);
                }

                // Set up new interval
                window.updateInterval = setInterval(() => {
                    // In a real application, you would fetch new data here
                    // For this demo, we'll just update the data with slight variations
                    updateData();
                }, interval);
            }

            // Clean up when the page is unloaded
            window.addEventListener('beforeunload', function() {
                if (window.updateInterval) {
                    clearInterval(window.updateInterval);
                }
            });
        });
    </script>
