        // Start auto-updating the data
        function startAutoUpdate() {
            if (updateIntervalId) clearInterval(updateIntervalId);
            updateIntervalId = setInterval(fetchData, config.updateInterval);
        }

        // Fetch data from API (simulated with mock data)
        async function fetchData() {
            d3.select('.loading').style('display', 'block');

            try {
                // In a real implementation, you would fetch from an API like:
                // const response = await fetch(`https://api.example.com/stocks?symbols=${selectedStocks.join(',')}&timeframe=${currentTimeframe}`);
                // const newData = await response.json();

                // Simulate API call with mock data
                const mockData = generateMockData();
                processData(mockData);
            } catch (error) {
                console.error('Error fetching data:', error);
            } finally {
                d3.select('.loading').style('display', 'none');
            }
        }

        // Generate mock data for demonstration
        function generateMockData() {
            const now = new Date();
            const timeframes = {
                '1d': { days: 1, interval: 'hour' },
                '5d': { days: 5, interval: 'hour' },
                '1mo': { days: 30, interval: 'day' },
                '3mo': { days: 90, interval: 'day' },
                '1y': { days: 365, interval: 'day' },
                '5y': { days: 365 * 5, interval: 'week' }
            };

            const { days, interval } = timeframes[currentTimeframe];
            const dates = [];
            const data = [];

            // Generate dates
            for (let i = 0; i < days; i++) {
                const date = new Date(now);
                date.setDate(date.getDate() - i);

                if (interval === 'hour') {
                    for (let h = 0; h < 24; h++) {
                        const hourDate = new Date(date);
                        hourDate.setHours(h);
                        dates.push(hourDate);
                    }
                } else if (interval === 'day') {
                    dates.push(date);
                } else if (interval === 'week') {
                    if (i % 7 === 0) dates.push(date);
                }
            }

            // Generate data for each stock
            selectedStocks.forEach(stock => {
                const basePrice = 100 + Math.random() * 200;
                const volatility = 0.01 + Math.random() * 0.05;

                dates.forEach(date => {
                    const price = basePrice * (1 + (Math.random() - 0.5) * volatility);
                    const change = (price - basePrice) / basePrice * 100;

                    data.push({
                        stock,
                        date,
                        price: price.toFixed(2),
                        change: change.toFixed(2)
                    });
                });
            });

            return data;
        }

        // Process the data and update the visualization
        function processData(newData) {
            data = newData;

            // Get unique dates and stocks
            const dates = [...new Set(data.map(d => d.date))].sort((a, b) => a - b);
            const stocks = [...new Set(data.map(d => d.stock))];

            // Update scales
            xScale = d3.scaleBand()
                .domain(dates)
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(stocks)
                .range([config.height - config.margin.bottom, config.margin.top])
                .padding(0.01);

            // Update color scale domain
            const changes = data.map(d => parseFloat(d.change));
            colorScale.domain([
                d3.quantile(changes, 0.1),
                d3.quantile(changes, 0.3),
                d3.quantile(changes, 0.5),
                d3.quantile(changes, 0.7),
                d3.quantile(changes, 0.9)
            ]);

            // Update legend
            createLegend();

            // Update the visualization
            updateVisualization();
        }

        // Update the visualization with current data
        function updateVisualization() {
            // Remove existing elements
            svg.selectAll('*').remove();

            // Create a group for the heatmap
            const heatmap = svg.append('g');

            // Add rectangles for each data point
            heatmap.selectAll('rect')
                .data(data)
                .enter()
                .append('rect')
                .attr('x', d => xScale(d.date))
                .attr('y', d => yScale(d.stock))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(parseFloat(d.change)))
                .on('mouseover', showTooltip)
                .on('mouseout', hideTooltip);

            // Add x-axis
            svg.append('g')
                .attr('transform', `translate(0, ${config.height - config.margin.bottom})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d3.timeFormat('%b %d'))
                    .tickSizeOuter(0))
                .selectAll('text')
                .attr('transform', 'rotate(-45)')
                .style('text-anchor', 'end');

            // Add y-axis
            svg.append('g')
                .attr('transform', `translate(${config.margin.left}, 0)`)
                .call(d3.axisLeft(yScale).tickSizeOuter(0));

            // Add axis labels
            svg.append('text')
                .attr('x', config.width / 2)
                .attr('y', config.height - 5)
                .style('text-anchor', 'middle')
                .text('Date');

            svg.append('text')
                .attr('transform', 'rotate(-90)')
                .attr('y', 15)
                .attr('x', -config.height / 2)
                .style('text-anchor', 'middle')
                .text('Stock');
        }

        // Show tooltip on hover
        function showTooltip(event, d) {
            const tooltip = d3.select('#tooltip');
            tooltip.style('visibility', 'visible')
                .html(`
                    <strong>${d.stock}</strong><br>
                    Date: ${d3.timeFormat('%Y-%m-%d')(d.date)}<br>
                    Price: $${d.price}<br>
                    Change: ${d.change}%
                `)
                .style('top', (event.pageY - 10) + 'px')
                .style('left', (event.pageX + 10) + 'px');
        }

        // Hide tooltip
        function hideTooltip() {
            d3.select('#tooltip').style('visibility', 'hidden');
        }

        // Handle zoom/pan interactions
        function handleZoom(event) {
            const transform = event.transform;
            svg.selectAll('g').attr('transform', transform);
        }

        // Clean up when the page is unloaded
        window.addEventListener('beforeunload', () => {
            if (updateIntervalId) clearInterval(updateIntervalId);
        });
    </script>
</body>
</html>
```

