                    Date: ${d3.timeFormat("%b %d, %Y")(d.date)}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change > 0 ? '+' : ''}${d.change.toFixed(2)}
                `)
                .style("left", (event.pageX + 10) + "px")
                .style("top", (event.pageY + 10) + "px");
        }

        // Hide tooltip
        function hideTooltip() {
            d3.select(".tooltip").style("visibility", "hidden");
        }

        // Handle zoom/pan
        function zoomed(event) {
            const { transform } = event;

            // Apply the transform to the cells
            svg.selectAll(".cell")
                .attr("transform", transform);

            // Adjust the axes
            svg.select(".x-axis").call(
                d3.axisBottom(xScale).scale(transform.rescaleX(xScale))
            );

            svg.select(".y-axis").call(
                d3.axisLeft(yScale).scale(transform.rescaleY(yScale))
            );
        }

        // Render the legend
        function renderLegend(priceExtent) {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendData = colorScale.range().map((color, i) => {
                const domain = colorScale.invertExtent(color);
                return {
                    color: color,
                    min: domain[0],
                    max: domain[1]
                };
            });

            const legendItems = legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d.color);

            legendItems.append("div")
                .text(d => `$${d.min.toFixed(2)} - $${d.max.toFixed(2)}`);
        }

        // Start periodic updates
        function startPeriodicUpdates() {
            if (updateIntervalId) clearInterval(updateIntervalId);

            updateIntervalId = setInterval(() => {
                if (!isLoading) {
                    updateData();
                }
            }, config.updateInterval);
        }

        // Initialize when the page loads
        document.addEventListener("DOMContentLoaded", init);

        // Clean up when the page unloads
        window.addEventListener("beforeunload", () => {
            if (updateIntervalId) clearInterval(updateIntervalId);
        });
    </script>
