                <label for="stocks">Stocks:</label>
                <select id="stocks" multiple size="5">
                    <option value="AAPL" selected>AAPL (Apple)</option>
                    <option value="MSFT" selected>MSFT (Microsoft)</option>
                    <option value="GOOGL" selected>GOOGL (Alphabet)</option>
                    <option value="AMZN" selected>AMZN (Amazon)</option>
                    <option value="TSLA" selected>TSLA (Tesla)</option>
                    <option value="FB" selected>FB (Meta)</option>
                    <option value="NVDA" selected>NVDA (NVIDIA)</option>
                    <option value="BRK.B" selected>BRK.B (Berkshire Hathaway)</option>
                    <option value="JPM" selected>JPM (JPMorgan Chase)</option>
                    <option value="V" selected>V (Visa)</option>
                </select>
            </div>

            <div class="control-group">
                <button id="update-btn">Update Data</button>
                <button id="reset-btn">Reset View</button>
            </div>
        </div>

        <div id="heatmap-container">
            <div class="loading">Loading data...</div>
        </div>

        <div class="legend" id="legend"></div>
    </div>

    <div class="tooltip" id="tooltip"></div>

    <script>
        // Configuration
        const config = {
            margin: { top: 40, right: 30, bottom: 80, left: 60 },
            width: 1000,
            height: 500,
            colors: ["#d73027", "#fc8d59", "#fee090", "#ffffbf", "#e0f3f8", "#91bfdb", "#4575b4"],
            colorDomain: [-0.1, -0.05, -0.01, 0, 0.01, 0.05, 0.1]
        };

        // Global variables
        let svg, heatmap, xScale, yScale, colorScale, xAxis, yAxis;
        let zoom;
        let data = [];
        let updateInterval;

        // Initialize the visualization
        document.addEventListener('DOMContentLoaded', function() {
            initVisualization();
            setupEventListeners();
            fetchData();
            startAutoUpdate();
        });

        function initVisualization() {
            // Clear any existing SVG
            d3.select("#heatmap-container").selectAll("*").remove();

            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width + config.margin.left + config.margin.right)
                .attr("height", config.height + config.margin.top + config.margin.bottom)
                .append("g")
                .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

            // Create color scale
            colorScale = d3.scaleThreshold()
                .domain(config.colorDomain)
                .range(config.colors);

            // Create zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            // Apply zoom to the SVG
            svg.call(zoom);

            // Create tooltip
            const tooltip = d3.select("#tooltip");

            // Create legend
            createLegend();
        }

        function createLegend() {
            const legend = d3.select("#legend");

            // Clear existing legend
            legend.selectAll("*").remove();

            // Create legend items
            const legendItems = legend.selectAll(".legend-item")
                .data(colorScale.range().map((color, i) => {
                    return {
                        color: color,
                        range: i === 0 ? `< ${config.colorDomain[i]}` :
                               i === config.colorDomain.length ? `≥ ${config.colorDomain[i-1]}` :
                               `${config.colorDomain[i-1]} to ${config.colorDomain[i]}`
                    };
                }))
                .enter()
                .append("div")
                .attr("class", "legend-item");

            legendItems.append("div")
                .attr("class", "legend-color")
                .style("background-color", d => d.color);

            legendItems.append("span")
                .text(d => d.range);
        }

        function setupEventListeners() {
            document.getElementById("update-btn").addEventListener("click", function() {
                fetchData();
            });

            document.getElementById("reset-btn").addEventListener("click", function() {
                resetView();
            });

            document.getElementById("timeframe").addEventListener("change", function() {
                fetchData();
            });

            document.getElementById("stocks").addEventListener("change", function() {
                fetchData();
            });
        }

        function startAutoUpdate() {
            // Update data every 5 minutes (300000 ms)
            updateInterval = setInterval(fetchData, 300000);
        }

        function stopAutoUpdate() {
            if (updateInterval) {
                clearInterval(updateInterval);
            }
        }

        function resetView() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        function zoomed(event) {
            const { transform } = event;
            heatmap.attr("transform", transform);
            xAxis.call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            yAxis.call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }

        async function fetchData() {
            // Show loading indicator
            d3.select("#heatmap-container").select(".loading").style("display", "block");

            try {
                const timeframe = document.getElementById("timeframe").value;
                const selectedStocks = Array.from(document.getElementById("stocks").selectedOptions)
                    .map(option => option.value);

                // In a real application, you would fetch data from an API
                // For this example, we'll generate mock data
                const mockData = generateMockData(selectedStocks, timeframe);

                // Process the data
                processData(mockData);

                // Hide loading indicator
                d3.select("#heatmap-container").select(".loading").style("display", "none");
            } catch (error) {
                console.error("Error fetching data:", error);
                d3.select("#heatmap-container").select(".loading")
                    .text("Error loading data. Please try again.");
            }
        }

        function generateMockData(stocks, timeframe) {
            // Generate mock data based on selected stocks and timeframe
            const now = new Date();
            let interval, count;

            switch(timeframe) {
                case "1D":
                    interval = 15 * 60 * 1000; // 15 minutes
                    count = 6 * 4; // 6 hours * 4 intervals per hour
                    break;
                case "1W":
                    interval = 60 * 60 * 1000; // 1 hour
                    count = 24 * 7; // 24 hours * 7 days
                    break;
                case "1M":
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    count = 4 * 30; // 4 intervals per day * 30 days
                    break;
                case "3M":
                    interval = 12 * 60 * 60 * 1000; // 12 hours
                    count = 2 * 30 * 3; // 2 intervals per day * 30 days * 3 months
                    break;
                case "1Y":
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    count = 365; // 1 year
                    break;
                default:
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    count = 4 * 30; // 4 intervals per day * 30 days
            }

            const data = [];

            stocks.forEach(stock => {
                let basePrice = 100 + Math.random() * 200; // Random base price between 100-300
                let volatility = 0.01 + Math.random() * 0.05; // Random volatility

                for (let i = 0; i < count; i++) {
                    const timestamp = new Date(now.getTime() - (count - i) * interval);
                    const change = (Math.random() - 0.5) * volatility; // Random change
                    const price = basePrice * (1 + change);

                    data.push({
                        stock: stock,
                        timestamp: timestamp,
                        price: price,
                        change: change
                    });

                    // Update base price for next interval
                    basePrice = price;
                }
            });

            return data;
        }

        function processData(rawData) {
            // Group data by stock and timestamp
            const groupedData = d3.group(rawData, d => d.stock, d => d.timestamp);

            // Convert to array of objects with stock, timestamp, and change
            data = Array.from(groupedData, ([stock, timestamps]) => {
                return {
                    stock: stock,
                    values: Array.from(timestamps, ([timestamp, values]) => {
                        return {
                            timestamp: timestamp,
                            change: values[0].change
                        };
                    })
                };
            });

            // Sort stocks alphabetically
            data.sort((a, b) => a.stock.localeCompare(b.stock));

            // Sort timestamps chronologically
            data.forEach(stockData => {
                stockData.values.sort((a, b) => a.timestamp - b.timestamp);
            });

            // Update the visualization
            updateVisualization();
        }

        function updateVisualization() {
            if (data.length === 0) return;

            // Get all timestamps across all stocks
            const allTimestamps = data.flatMap(stock => stock.values.map(v => v.timestamp));
            const uniqueTimestamps = [...new Set(allTimestamps)].sort((a, b) => a - b);

            // Set up scales
            xScale = d3.scaleBand()
                .domain(uniqueTimestamps)
                .range([0, config.width])
                .padding(0.01);

            yScale = d3.scaleBand()
                .domain(data.map(d => d.stock))
                .range([0, config.height])
                .padding(0.1);

            // Create axes
            xAxis = svg.selectAll(".x-axis").data([null]);
            xAxis.enter()
                .append("g")
                .attr("class", "x-axis")
                .merge(xAxis)
                .attr("transform", `translate(0, ${config.height})`)
                .call(d3.axisBottom(xScale)
                    .tickFormat(d3.timeFormat("%b %d %H:%M"))
                    .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(uniqueTimestamps.length / 10) === 0)))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end")
                .attr("class", "axis-label");

            yAxis = svg.selectAll(".y-axis").data([null]);
            yAxis.enter()
                .append("g")
                .attr("class", "y-axis")
                .merge(yAxis)
                .call(d3.axisLeft(yScale))
                .selectAll("text")
                .attr("class", "axis-label");

            // Create heatmap cells
            heatmap = svg.selectAll(".heatmap")
                .data(data, d => d.stock);

            // Remove old cells
            heatmap.exit().remove();

            // Add new cells
            const newCells = heatmap.enter()
                .append("g")
                .attr("class", "heatmap")
                .attr("transform", d => `translate(0, ${yScale(d.stock)})`);

            // Add rectangles for each timestamp
            newCells.selectAll("rect")
                .data(d => d.values.map(v => ({
                    stock: d.stock,
                    timestamp: v.timestamp,
                    change: v.change
                })))
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.timestamp))
                .attr("y", 0)
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    const tooltip = d3.select("#tooltip");
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.stock}</strong><br>
                            ${d3.timeFormat("%b %d %H:%M")(d.timestamp)}<br>
                            Change: ${(d.change * 100).toFixed(2)}%
                        `);
                })
                .on("mousemove", function(event) {
                    d3.select("#tooltip")
                        .style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    d3.select("#tooltip").style("visibility", "hidden");
                });

            // Update existing cells
            heatmap.selectAll("rect")
                .data(d => d.values.map(v => ({
                    stock: d.stock,
                    timestamp: v.timestamp,
                    change: v.change
                })))
                .transition()
                .duration(500)
                .attr("x", d => xScale(d.timestamp))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change));
        }

        // Clean up when page is unloaded
        window.addEventListener('beforeunload', function() {
            stopAutoUpdate();
        });
    </script>
</body>
</html>
```

## Features of this Implementation:

1. **Interactive Heatmap**:
   - Visualizes stock price changes as color-coded cells
   - Uses D3.js for scalable vector graphics rendering

2. **Real-Time Updates**:
   - Auto-refreshes data every 5 minutes
   - Manual refresh button available
   - Simulates API calls with mock data generation

3. **Zoom/Pan Interactions**:
   - Mouse wheel zoom
   - Click-and-drag panning
   - Reset view button

4. **Customization Options**:
   - Select different timeframes (1D, 1W, 1M, 3M, 1Y)
   - Choose which stocks to display
   - Responsive design that works on different screen sizes

5. **Visual Enhancements**:
   - Color-coded legend
   - Tooltips showing detailed information
   - Loading indicators
   - Responsive axis labels

6. **Data Handling**:
   - Processes raw data into a format suitable for visualization
   - Handles multiple stocks and time periods

## How to Use:

1. Copy the entire code into an HTML file
2. Open the file in a web browser
3. Use the controls to customize the view:
   - Select timeframe from dropdown
   - Choose stocks by holding Ctrl/Cmd and clicking
   - Click "Update Data" to refresh
   - Use mouse to zoom/pan the heatmap
   - Click "Reset View" to return to default zoom

For a production environment, you would replace the `generateMockData()` function with actual API calls to a financial data service.

