## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 40, right: 20, bottom: 60, left: 80 },
    cellSize: 20,
    colors: ["#f7fbff", "#deebf7", "#c6dbef", "#9ecae1", "#6baed6", "#4292c6", "#2171b5", "#08519c", "#08306b"],
    updateInterval: 60000 // 1 minute
};

// Mock data generator (in a real app, this would fetch from an API)
function generateMockData(timeRange) {
    const now = new Date();
    let startDate, interval, numDays;

    switch(timeRange) {
        case '1d':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 60 * 60 * 1000; // 1 hour
            numDays = 1;
            break;
        case '1w':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 6 * 60 * 60 * 1000; // 6 hours
            numDays = 7;
            break;
        case '1m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 24 * 60 * 60 * 1000; // 1 day
            numDays = 30;
            break;
        case '3m':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 24 * 60 * 60 * 1000; // 1 day
            numDays = 90;
            break;
        case '1y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 7 * 24 * 60 * 60 * 1000; // 1 week
            numDays = 365;
            break;
        default:
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 24 * 60 * 60 * 1000; // 1 day
            numDays = 30;
    }

    // Generate random stocks (in a real app, this would be a list of actual stocks)
    const stocks = [];
    for (let i = 0; i < 20; i++) {
        stocks.push(`STOCK${String.fromCharCode(65 + i)}`);
    }

    // Generate time points
    const timePoints = [];
    let currentTime = new Date(startDate);
    while (currentTime <= now) {
        timePoints.push(new Date(currentTime));
        currentTime = new Date(currentTime.getTime() + interval);
    }

    // Generate random price data
    const data = [];
    const basePrices = {};
    stocks.forEach(stock => {
        basePrices[stock] = 100 + Math.random() * 100;
    });

    timePoints.forEach(time => {
        stocks.forEach(stock => {
            // Simulate price movement with some randomness
            const change = (Math.random() - 0.5) * 5;
            basePrices[stock] += change;

            data.push({
                stock,
                time: new Date(time),
                price: Math.max(0, basePrices[stock]),
                change: change
            });
        });
    });

    return { data, stocks, timePoints };
}

// Main visualization function
function createHeatmap(data, stocks, timePoints) {
    // Clear previous visualization
    d3.select("#heatmap").selectAll("*").remove();

    // Set up dimensions
    const width = config.width - config.margin.left - config.margin.right;
    const height = config.height - config.margin.top - config.margin.bottom;

    // Create SVG
    const svg = d3.select("#heatmap")
        .append("svg")
        .attr("width", config.width)
        .attr("height", config.height)
        .append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Create scales
    const xScale = d3.scaleBand()
        .domain(timePoints.map(d => d.toISOString()))
        .range([0, width])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, height])
        .padding(0.05);

    // Create color scale
    const colorScale = d3.scaleQuantile()
        .domain([d3.min(data, d => d.change), d3.max(data, d => d.change)])
        .range(config.colors);

    // Create tooltip
    const tooltip = d3.select("#tooltip");

    // Create cells
    const cells = svg.selectAll(".cell")
        .data(data)
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.time.toISOString()))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change))
        .on("mouseover", function(event, d) {
            tooltip.transition()
                .duration(200)
                .style("opacity", .9);

            tooltip.html(`
                <strong>${d.stock}</strong><br>
                Time: ${d.time.toLocaleString()}<br>
                Price: $${d.price.toFixed(2)}<br>
                Change: ${d.change > 0 ? '+' : ''}${d.change.toFixed(2)}%
            `)
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px");
        })
        .on("mouseout", function() {
            tooltip.transition()
                .duration(500)
                .style("opacity", 0);
        });

    // Add x-axis
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d => new Date(d).toLocaleDateString())
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(timePoints.length / 10) === 0));

    svg.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0,${height})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    // Add y-axis
    svg.append("g")
        .attr("class", "y-axis")
        .call(d3.axisLeft(yScale));

    // Add axis labels
    svg.append("text")
        .attr("class", "x-label")
        .attr("x", width / 2)
        .attr("y", height + config.margin.bottom - 10)
        .style("text-anchor", "middle")
        .text("Time");

    svg.append("text")
        .attr("class", "y-label")
        .attr("transform", "rotate(-90)")
        .attr("x", -height / 2)
        .attr("y", -config.margin.left + 20)
        .style("text-anchor", "middle")
        .text("Stock");

    // Create legend
    const legend = d3.select("#legend");
    legend.selectAll("*").remove();

    const legendData = colorScale.quantiles().map((d, i) => ({
        color: config.colors[i + 1],
        range: `${d.toFixed(2)}% - ${(colorScale.quantiles()[i + 1] || d3.max(data, d => d.change)).toFixed(2)}%`
    }));

    legend.selectAll(".legend-item")
        .data(legendData)
        .enter()
        .append("div")
        .attr("class", "legend-item")
        .html(d => `
            <div class="legend-color" style="background-color: ${d.color};"></div>
            <span>${d.range}</span>
        `);

    // Add zoom functionality
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on("zoom", zoomed);

    svg.call(zoom);

    function zoomed(event) {
        const { transform } = event;
        svg.attr("transform", transform);
    }

    // Add zoom control buttons
    d3.select("#zoomIn").on("click", () => {
        svg.transition().call(zoom.scaleBy, 1.5);
    });

    d3.select("#zoomOut").on("click", () => {
        svg.transition().call(zoom.scaleBy, 0.75);
    });

    d3.select("#resetZoom").on("click", () => {
        svg.transition().call(zoom.transform, d3.zoomIdentity);
    });

    // Hide loading indicator
    d3.select("#loading").style("display", "none");
}

// Initialize the visualization
function init() {
    const timeRange = d3.select("#timeRange").property("value");
    const { data, stocks, timePoints } = generateMockData(timeRange);

