    // Set up refresh button
    d3.select("#refreshBtn").on("click", () => {
        d3.select("#loading").style("display", "block");
        const timeRange = d3.select("#timeRange").property("value");
        const { data, stocks, timePoints } = generateMockData(timeRange);
        createHeatmap(data, stocks, timePoints);
    });

    // Set up time range change
    d3.select("#timeRange").on("change", () => {
        d3.select("#loading").style("display", "block");
        const timeRange = d3.select("#timeRange").property("value");
        const { data, stocks, timePoints } = generateMockData(timeRange);
