```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 30, right: 30, bottom: 30, left: 60 },
    cellSize: 20,
    updateInterval: 60000, // 1 minute
    apiEndpoint: 'https://api.example.com/stock-prices' // Replace with your actual API endpoint
};

// Global variables
let svg, xScale, yScale, colorScale, tooltip, zoom;
let data = [];
let currentTimeRange = '1M';
let isLoading = false;

// Initialize the heatmap
function initHeatmap() {
    // Create SVG container
    svg = d3.select('.heatmap')
        .attr('width', config.width)
        .attr('height', config.height);

    // Create tooltip
    tooltip = d3.select('#tooltip');

    // Create color scale
    colorScale = d3.scaleLinear()
        .domain([-5, 0, 5]) // Price change percentage range
        .range(['#e74c3c', '#ecf0f1', '#2ecc71']);

    // Create zoom behavior
    zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on('zoom', zoomed);

    svg.call(zoom);

    // Add color scale legend
    const legendWidth = 200;
    const legendHeight = 20;

    const legendSvg = d3.select('#colorScale')
        .append('svg')
        .attr('width', legendWidth)
        .attr('height', legendHeight);

    const legendGradient = legendSvg.append('defs')
        .append('linearGradient')
        .attr('id', 'legendGradient')
        .attr('x1', '0%')
        .attr('y1', '0%')
        .attr('x2', '100%')
        .attr('y2', '0%');

    legendGradient.append('stop')
        .attr('offset', '0%')
        .attr('stop-color', '#e74c3c');

    legendGradient.append('stop')
        .attr('offset', '50%')
        .attr('stop-color', '#ecf0f1');

    legendGradient.append('stop')
        .attr('offset', '100%')
        .attr('stop-color', '#2ecc71');

    legendSvg.append('rect')
        .attr('width', legendWidth)
        .attr('height', legendHeight)
        .style('fill', 'url(#legendGradient)');

    // Add event listeners
    d3.select('#timeRange').on('change', function() {
        currentTimeRange = this.value;
        fetchData();
    });

    d3.select('#refreshBtn').on('click', fetchData);
    d3.select('#zoomIn').on('click', () => zoomIn());
    d3.select('#zoomOut').on('click', () => zoomOut());
    d3.select('#resetZoom').on('click', () => resetZoom());

    // Initial data fetch
    fetchData();

    // Set up periodic updates
    setInterval(fetchData, config.updateInterval);
}

// Fetch data from API
async function fetchData() {
    if (isLoading) return;

    isLoading = true;
    d3.select('#loading').style('display', 'block');

    try {
        // In a real implementation, you would fetch data from your API
        // For this example, we'll generate mock data
        const mockData = generateMockData(currentTimeRange);

        // Process the data
        processData(mockData);

        // Update the visualization
        updateHeatmap();

    } catch (error) {
        console.error('Error fetching data:', error);
    } finally {
        isLoading = false;
        d3.select('#loading').style('display', 'none');
    }
}

// Generate mock data for demonstration
function generateMockData(timeRange) {
    // This is a simplified mock data generator
    // In a real application, you would fetch this from your API

    const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
    const now = new Date();
    let startDate, interval, points;

    switch(timeRange) {
        case '1D':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 3600000; // 1 hour
            points = 24;
            break;
        case '1W':
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 21600000; // 6 hours
            points = 28;
            break;
        case '1M':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 86400000; // 1 day
            points = 30;
            break;
        case '3M':
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 86400000; // 1 day
            points = 90;
            break;
        case '1Y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 86400000; // 1 day
            points = 365;
            break;
        case '5Y':
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 5);
            interval = 86400000 * 7; // 1 week
            points = 260;
            break;
        default:
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 86400000; // 1 day
            points = 30;
    }

    const data = [];

    for (let i = 0; i < points; i++) {
        const timestamp = new Date(startDate.getTime() + i * interval);

        stocks.forEach(stock => {
            // Generate random price change between -5% and +5%
            const change = (Math.random() * 10 - 5).toFixed(2);

            data.push({
                stock,
                timestamp,
                change: parseFloat(change)
            });
        });
    }

    return data;
}

// Process the data
function processData(rawData) {
    // Group data by stock and timestamp
    const groupedData = d3.group(rawData, d => d.stock, d => d.timestamp);

    // Convert to array of objects
    data = Array.from(groupedData, ([stock, timestamps]) => {
        return {
            stock,
            values: Array.from(timestamps, ([timestamp, values]) => {
                return {
                    timestamp,
                    change: values[0].change
                };
            })
        };
    });

    // Sort stocks alphabetically
    data.sort((a, b) => a.stock.localeCompare(b.stock));

    // Sort timestamps chronologically
    data.forEach(stock => {
        stock.values.sort((a, b) => a.timestamp - b.timestamp);
    });
}

// Update the heatmap visualization
function updateHeatmap() {
    if (data.length === 0) return;

    // Clear previous content
    svg.selectAll('*').remove();

    // Create scales
    const stocks = data.map(d => d.stock);
    const timestamps = data[0].values.map(d => d.timestamp);

    xScale = d3.scaleBand()
        .domain(timestamps)
        .range([config.margin.left, config.width - config.margin.right])
        .padding(0.05);

    yScale = d3.scaleBand()
        .domain(stocks)
        .range([config.height - config.margin.bottom, config.margin.top])
        .padding(0.05);

    // Create heatmap cells
    const cells = svg.selectAll('.cell')
        .data(data)
        .enter()
        .selectAll('.cell')
        .data(d => d.values.map(v => ({
            stock: d.stock,
            timestamp: v.timestamp,
            change: v.change
        })))
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.timestamp))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.change))
        .on('mouseover', showTooltip)
        .on('mouseout', hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat('%b %d'))
        .tickSizeOuter(0);

    const yAxis = d3.axisLeft(yScale)
        .tickSizeOuter(0);

    svg.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0, ${config.height - config.margin.bottom})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    svg.append('g')
        .attr('class', 'y-axis')
        .attr('transform', `translate(${config.margin.left}, 0)`)
        .call(yAxis);

    // Add axis labels
    svg.append('text')
        .attr('class', 'axis-label')
        .attr('x', config.width / 2)
        .attr('y', config.height - 5)
        .style('text-anchor', 'middle')
        .text('Time');

    svg.append('text')
        .attr('class', 'axis-label')
        .attr('transform', 'rotate(-90)')
        .attr('x', -config.height / 2)
        .attr('y', 15)
        .style('text-anchor', 'middle')
        .text('Stock');
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style('visibility', 'visible')
        .html(`
            <strong>${d.stock}</strong><br>
            ${d3.timeFormat('%b %d, %Y %H:%M')(d.timestamp)}<br>
            Change: ${d.change.toFixed(2)}%
        `)
        .style('left', (event.pageX + 10) + 'px')
        .style('top', (event.pageY - 28) + 'px');
}

// Hide tooltip
function hideTooltip() {
    tooltip.style('visibility', 'hidden');
}

// Zoom functions
function zoomed(event) {
    const { transform } = event;
    svg.selectAll('.cell')
        .attr('transform', transform);

    svg.select('.x-axis').call(
        d3.axisBottom(xScale).scale(transform.rescaleX(xScale))
    );

    svg.select('.y-axis').call(
        d3.axisLeft(yScale).scale(transform.rescaleY(yScale))
    );
}

function zoomIn() {
    svg.transition()
        .duration(750)
        .call(zoom.scaleBy, 1.5);
}

function zoomOut() {
    svg.transition()
        .duration(750)
        .call(zoom.scaleBy, 0.75);
}

function resetZoom() {
    svg.transition()
        .duration(750)
        .call(zoom.transform, d3.zoomIdentity);
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', initHeatmap);
