            dates.push(date);
        }

        // Generate data for each stock
        stocks.forEach(stock => {
            dates.forEach(date => {
                // Generate random price change percentage
                const change = (Math.random() * 20 - 10).toFixed(2);

                data.push({
                    stock: stock,
                    date: date,
                    change: parseFloat(change)
                });
            });
        });

        return data;
    }

    function getDaysForTimeframe(timeframe) {
        switch(timeframe) {
            case '1d': return 1;
            case '5d': return 5;
            case '1m': return 30;
            case '3m': return 90;
            case '1y': return 365;
            case '5y': return 365 * 5;
            default: return 365;
        }
    }

    function updateHeatmap() {
        if (currentData.length === 0) return;

        // Clear previous content
        svg.selectAll("*").remove();

        // Get unique stocks and dates
        const stocks = [...new Set(currentData.map(d => d.stock))];
        const dates = [...new Set(currentData.map(d => d.date))].sort((a, b) => a - b);

        // Set up scales
        xScale = d3.scaleBand()
            .domain(dates.map(d => d3.timeFormat("%Y-%m-%d")(d)))
            .range([config.margin.left, config.width - config.margin.right])
            .padding(0.01);

        yScale = d3.scaleBand()
            .domain(stocks)
            .range([config.margin.top, config.height - config.margin.bottom])
            .padding(0.01);

        colorScale = d3.scaleQuantile()
            .domain([d3.min(currentData, d => d.change), d3.max(currentData, d => d.change)])
            .range(config.colors);

        // Create heatmap cells
        const cells = svg.selectAll(".cell")
            .data(currentData)
            .enter()
            .append("rect")
            .attr("class", "cell")
            .attr("x", d => xScale(d3.timeFormat("%Y-%m-%d")(d.date)))
            .attr("y", d => yScale(d.stock))
            .attr("width", xScale.bandwidth())
            .attr("height", yScale.bandwidth())
            .attr("fill", d => colorScale(d.change))
            .on("mouseover", function(event, d) {
                tooltip.style("display", "block")
                    .html(`
                        <strong>${d.stock}</strong><br>
                        ${d3.timeFormat("%b %d, %Y")(d.date)}<br>
                        Change: ${d.change}%<br>
                        ${d.change > 0 ? '↑' : '↓'} ${Math.abs(d.change)}%
                    `);

                // Position tooltip near mouse
                const [x, y] = d3.pointer(event);
                tooltip.style("left", `${x + 10}px`)
                    .style("top", `${y + 10}px`);
            })
            .on("mouseout", function() {
                tooltip.style("display", "none");
            });

        // Add axes
        svg.append("g")
            .attr("transform", `translate(0,${config.margin.top})`)
            .call(d3.axisLeft(yScale).tickSize(0))
            .selectAll("text")
            .style("text-anchor", "end")
            .attr("dx", "-0.5em")
            .attr("dy", "0.32em");

        svg.append("g")
            .attr("transform", `translate(0,${config.height - config.margin.bottom})`)
            .call(d3.axisBottom(xScale).tickSize(0))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end")
            .attr("dx", "-0.8em")
            .attr("dy", "0.15em");

        // Update legend
        updateLegend();
    }

    function updateLegend() {
        const legend = d3.select("#legend");
        legend.selectAll("*").remove();

        // Create legend items
        const legendItems = legend.selectAll(".legend-item")
            .data(colorScale.quantiles())
            .enter()
            .append("div")
            .attr("class", "legend-item");

        legendItems.append("div")
            .attr("class", "legend-color")
            .style("background-color", (d, i) => config.colors[i]);

        legendItems.append("span")
            .text(d => `${d.toFixed(2)}%`);
    }

    function zoomed(event) {
        const { transform } = event;
        svg.selectAll(".cell")
            .attr("transform", transform);

        // Adjust axes
        svg.selectAll("g").remove();

        svg.append("g")
            .attr("transform", `translate(0,${config.margin.top})`)
            .call(d3.axisLeft(yScale.scale.copy().domain(yScale.domain()))
                .tickSize(0)
                .tickFormat(""))
            .selectAll("text")
            .style("text-anchor", "end")
            .attr("dx", "-0.5em")
            .attr("dy", "0.32em");

        svg.append("g")
            .attr("transform", `translate(0,${config.height - config.margin.bottom})`)
            .call(d3.axisBottom(xScale.scale.copy().domain(xScale.domain()))
                .tickSize(0)
                .tickFormat(""))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end")
            .attr("dx", "-0.8em")
            .attr("dy", "0.15em");
    }

    function resetView() {
        svg.transition()
            .duration(750)
            .call(zoom.transform, d3.zoomIdentity);
    }
});
```

