```javascript
// Configuration
const config = {
    width: 1000,
    height: 500,
    margin: { top: 30, right: 30, bottom: 30, left: 80 },
    colors: ["#d73027", "#fc8d59", "#fee090", "#ffffbf", "#e0f3f8", "#91bfdb", "#4575b4"],
    updateInterval: 30000 // 30 seconds
};

// Initialize variables
let svg, xScale, yScale, colorScale, zoom;
let data = [];
let isLoading = false;
let updateIntervalId;

// DOM elements
const timeframeSelect = document.getElementById('timeframe');
const stockSelect = document.getElementById('stock-select');
const updateBtn = document.getElementById('update-btn');
const heatmapContainer = document.getElementById('heatmap-container');
const loadingDiv = heatmapContainer.querySelector('.loading');
const tooltip = heatmapContainer.querySelector('.tooltip');
const legendDiv = document.getElementById('legend');

// Initialize the visualization
function init() {
    // Create SVG container
    svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", config.width)
        .attr("height", config.height);

    // Add zoom behavior
    zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on("zoom", zoomed);

    svg.call(zoom);

    // Create legend
    createLegend();

    // Set up event listeners
    updateBtn.addEventListener('click', fetchData);

    // Initial data fetch
    fetchData();

    // Set up periodic updates
    updateIntervalId = setInterval(fetchData, config.updateInterval);
}

// Create color legend
function createLegend() {
    const legendItems = [
        { label: "Max", color: config.colors[0] },
        { label: "High", color: config.colors[2] },
        { label: "Medium", color: config.colors[4] },
        { label: "Low", color: config.colors[6] }
    ];

    legendDiv.innerHTML = '';

    legendItems.forEach(item => {
        const legendItem = document.createElement('div');
        legendItem.className = 'legend-item';

        const colorBox = document.createElement('div');
        colorBox.className = 'legend-color';
        colorBox.style.backgroundColor = item.color;

        const label = document.createElement('span');
        label.textContent = item.label;

        legendItem.appendChild(colorBox);
        legendItem.appendChild(label);
        legendDiv.appendChild(legendItem);
    });
}

// Handle zoom events
function zoomed(event) {
    const { transform } = event;
    svg.selectAll('g').attr('transform', transform);
}

// Fetch data from API
async function fetchData() {
    if (isLoading) return;

    isLoading = true;
    loadingDiv.style.display = 'block';

    try {
        const timeframe = timeframeSelect.value;
        const selectedStocks = Array.from(stockSelect.selectedOptions).map(opt => opt.value);

        // In a real implementation, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
        // This is a mock implementation for demonstration
        const mockData = generateMockData(selectedStocks, timeframe);

        data = mockData;
        updateVisualization();
    } catch (error) {
        console.error("Error fetching data:", error);
        showError("Failed to load data. Please try again.");
    } finally {
        isLoading = false;
        loadingDiv.style.display = 'none';
    }
}

// Generate mock data for demonstration
function generateMockData(stocks, timeframe) {
    const now = new Date();
    const endDate = now.toISOString().split('T')[0];
    let startDate;

    // Set start date based on timeframe
    switch (timeframe) {
        case '1d':
            startDate = new Date(now.setDate(now.getDate() - 1)).toISOString().split('T')[0];
            break;
        case '1w':
            startDate = new Date(now.setDate(now.getDate() - 7)).toISOString().split('T')[0];
            break;
        case '1m':
            startDate = new Date(now.setMonth(now.getMonth() - 1)).toISOString().split('T')[0];
            break;
        case '3m':
            startDate = new Date(now.setMonth(now.getMonth() - 3)).toISOString().split('T')[0];
            break;
        case '1y':
            startDate = new Date(now.setFullYear(now.getFullYear() - 1)).toISOString().split('T')[0];
            break;
        default:
            startDate = new Date(now.setMonth(now.getMonth() - 1)).toISOString().split('T')[0];
    }

    // Generate dates between start and end
    const dates = [];
    let currentDate = new Date(startDate);
    while (currentDate <= new Date(endDate)) {
        dates.push(new Date(currentDate));
        currentDate.setDate(currentDate.getDate() + 1);
    }

    // Generate mock data for each stock and date
    const mockData = [];

    stocks.forEach(stock => {
        dates.forEach(date => {
            // Generate random price change between -5% and +5%
            const change = (Math.random() * 10 - 5) / 100;

            // Generate random volume (1M to 100M)
            const volume = Math.floor(Math.random() * 99000000) + 1000000;

            mockData.push({
                stock,
                date: date.toISOString().split('T')[0],
                change,
                volume
            });
        });
    });

    return mockData;
}

// Update the visualization with new data
function updateVisualization() {
    if (!data || data.length === 0) return;

    // Clear previous visualization
    svg.selectAll('*').remove();

    // Get unique stocks and dates
    const stocks = [...new Set(data.map(d => d.stock))];
    const dates = [...new Set(data.map(d => d.date))].sort();

    // Set up scales
    xScale = d3.scaleBand()
        .domain(dates)
        .range([config.margin.left, config.width - config.margin.right])
        .padding(0.05);

    yScale = d3.scaleBand()
        .domain(stocks)
        .range([config.margin.top, config.height - config.margin.bottom])
        .padding(0.05);

    // Get min and max change values for color scale
    const minChange = d3.min(data, d => d.change);
    const maxChange = d3.max(data, d => d.change);

    colorScale = d3.scaleQuantile()
        .domain([minChange, maxChange])
        .range(config.colors);

    // Create heatmap cells
    const cells = svg.selectAll('.cell')
        .data(data)
        .enter()
        .append('rect')
        .attr('class', 'cell')
        .attr('x', d => xScale(d.date))
        .attr('y', d => yScale(d.stock))
        .attr('width', xScale.bandwidth())
        .attr('height', yScale.bandwidth())
        .attr('fill', d => colorScale(d.change))
        .on('mouseover', showTooltip)
        .on('mouseout', hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat("%b %d"))
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

    const yAxis = d3.axisLeft(yScale);

    svg.append('g')
        .attr('class', 'x-axis')
        .attr('transform', `translate(0, ${config.height - config.margin.bottom})`)
        .call(xAxis)
        .selectAll('text')
        .attr('transform', 'rotate(-45)')
        .style('text-anchor', 'end');

    svg.append('g')
        .attr('class', 'y-axis')
        .attr('transform', `translate(${config.margin.left}, 0)`)
        .call(yAxis);

    // Add axis labels
    svg.append('text')
        .attr('class', 'x-label')
        .attr('x', config.width / 2)
        .attr('y', config.height - 5)
        .style('text-anchor', 'middle')
        .text('Date');

    svg.append('text')
        .attr('class', 'y-label')
        .attr('transform', 'rotate(-90)')
        .attr('x', -config.height / 2)
        .attr('y', 15)
        .style('text-anchor', 'middle')
        .text('Stock');
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style.display = 'block';
    tooltip.style.left = `${event.pageX + 10}px`;
    tooltip.style.top = `${event.pageY + 10}px`;

    const changePercent = (d.change * 100).toFixed(2);
    const volumeFormatted = d.volume.toLocaleString();

    tooltip.innerHTML = `
        <strong>${d.stock}</strong><br>
        Date: ${d.date}<br>
        Change: ${changePercent}%<br>
        Volume: ${volumeFormatted}
    `;
}

// Hide tooltip
function hideTooltip() {
    tooltip.style.display = 'none';
}

// Show error message
function showError(message) {
    const errorDiv = document.createElement('div');
    errorDiv.className = 'error';
    errorDiv.textContent = message;
    heatmapContainer.appendChild(errorDiv);

    setTimeout(() => {
        errorDiv.remove();
    }, 5000);
}

// Initialize the application when the page loads
document.addEventListener('DOMContentLoaded', init);

// Clean up when the page is unloaded
window.addEventListener('beforeunload', () => {
    if (updateIntervalId) {
        clearInterval(updateIntervalId);
    }
});
