    margin: { top: 50, right: 30, bottom: 50, left: 80 },
    updateInterval: 30000 // 30 seconds
};

// Color scale for the heatmap
const colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
    .domain([-0.1, 0.1]); // Percentage change range

// Main application class
class StockHeatmap {
    constructor() {
        this.data = [];
        this.svg = null;
        this.xScale = null;
        this.yScale = null;
        this.zoom = null;
        this.tooltip = d3.select(config.tooltip);
        this.legend = d3.select(config.legend);
        this.timeframe = d3.select(config.timeframeSelect).property('value');
        this.selectedStocks = Array.from(d3.select(config.stocksSelect).property('selectedOptions'))
            .map(opt => opt.value);

        this.init();
        this.setupEventListeners();
        this.fetchData();
        this.startAutoUpdate();
    }

    init() {
        // Clear any existing SVG
        d3.select(config.container).selectAll('svg').remove();

        // Create SVG container
        this.svg = d3.select(config.container)
            .append('svg')
            .attr('width', config.width)
            .attr('height', config.height);

        // Create zoom behavior
        this.zoom = d3.zoom()
            .scaleExtent([0.5, 10])
            .on('zoom', (event) => this.handleZoom(event));

        this.svg.call(this.zoom);

        // Create legend
        this.createLegend();
    }

    createLegend() {
        const legendData = [
            { color: colorScale(-0.1), label: '-10%' },
            { color: colorScale(-0.05), label: '-5%' },
            { color: colorScale(0), label: '0%' },
            { color: colorScale(0.05), label: '+5%' },
            { color: colorScale(0.1), label: '+10%' }
        ];

        this.legend.selectAll('*').remove();

        const legendItems = this.legend.selectAll('.legend-item')
            .data(legendData)
            .enter()
            .append('div')
            .attr('class', 'legend-item');

        legendItems.append('div')
            .attr('class', 'legend-color')
            .style('background-color', d => d.color);

        legendItems.append('span')
            .text(d => d.label);
    }

    setupEventListeners() {
        d3.select(config.updateBtn).on('click', () => this.handleUpdate());
        d3.select(config.resetBtn).on('click', () => this.resetView());
        d3.select(config.timeframeSelect).on('change', () => this.handleTimeframeChange());
        d3.select(config.stocksSelect).on('change', () => this.handleStocksChange());
    }

    handleUpdate() {
        this.timeframe = d3.select(config.timeframeSelect).property('value');
        this.selectedStocks = Array.from(d3.select(config.stocksSelect).property('selectedOptions'))
            .map(opt => opt.value);
        this.fetchData();
    }

    resetView() {
        this.svg.transition()
            .duration(750)
            .call(this.zoom.transform, d3.zoomIdentity);
    }

    handleTimeframeChange() {
        this.timeframe = d3.select(config.timeframeSelect).property('value');
    }

    handleStocksChange() {
        this.selectedStocks = Array.from(d3.select(config.stocksSelect).property('selectedOptions'))
            .map(opt => opt.value);
    }

    handleZoom(event) {
        const { transform } = event;
        this.svg.selectAll('g').attr('transform', transform);
    }

    async fetchData() {
        // Show loading indicator
        d3.select(config.container).select('.loading').style('display', 'block');

        try {
            // In a real implementation, this would fetch from an API
            // For demo purposes, we'll generate mock data
            this.data = await this.generateMockData();

            // Filter data based on selected stocks
            this.data = this.data.filter(d => this.selectedStocks.includes(d.symbol));

            // Process data
            this.processData();

            // Render heatmap
            this.renderHeatmap();

        } catch (error) {
            console.error('Error fetching data:', error);
            d3.select(config.container).select('.loading').text('Error loading data');
        } finally {
            // Hide loading indicator
            d3.select(config.container).select('.loading').style('display', 'none');
        }
    }

    async generateMockData() {
        // Generate mock data for demonstration
        // In a real app, this would come from an API like Alpha Vantage, Yahoo Finance, etc.

        const symbols = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA', 'FB', 'NVDA', 'JPM', 'V', 'WMT'];
        const timeframes = {
            '1d': { points: 24, interval: 'hour' },
            '1w': { points: 7, interval: 'day' },
            '1m': { points: 30, interval: 'day' },
            '3m': { points: 90, interval: 'day' },
            '1y': { points: 12, interval: 'month' }
        };

        const { points, interval } = timeframes[this.timeframe];
        const now = new Date();
        const data = [];

        for (const symbol of symbols) {
            for (let i = 0; i < points; i++) {
                const date = new Date(now);
                if (interval === 'hour') {
                    date.setHours(now.getHours() - i);
                } else if (interval === 'day') {
                    date.setDate(now.getDate() - i);
                } else if (interval === 'month') {
                    date.setMonth(now.getMonth() - i);
                }

                // Generate random price change between -10% and +10%
                const change = (Math.random() * 20 - 10) / 100;

                data.push({
                    symbol,
                    date: date.toISOString(),
                    change: change
                });
            }
        }

        return data;
    }

    processData() {
        // Group data by symbol
        const nestedData = d3.group(this.data, d => d.symbol);

        // Convert to array of objects with symbol and values
        this.processedData = Array.from(nestedData, ([symbol, values]) => ({
            symbol,
            values: values.sort((a, b) => new Date(a.date) - new Date(b.date))
        }));
    }

    renderHeatmap() {
        // Clear previous content
        this.svg.selectAll('*').remove();

        // Create scales
        const allDates = this.data.map(d => new Date(d.date));
        const minDate = d3.min(allDates);
        const maxDate = d3.max(allDates);

        this.xScale = d3.scaleTime()
            .domain([minDate, maxDate])
            .range([config.margin.left, config.width - config.margin.right]);

        this.yScale = d3.scaleBand()
            .domain(this.processedData.map(d => d.symbol))
            .range([config.margin.top, config.height - config.margin.bottom])
            .padding(0.1);

        // Create axes
        const xAxis = d3.axisBottom(this.xScale);
        const yAxis = d3.axisLeft(this.yScale);

        this.svg.append('g')
            .attr('transform', `translate(0, ${config.height - config.margin.bottom})`)
            .call(xAxis);

        this.svg.append('g')
            .attr('transform', `translate(${config.margin.left}, 0)`)
            .call(yAxis);

        // Create heatmap cells
        const cells = this.svg.selectAll('.cell')
            .data(this.processedData)
            .enter()
            .append('g')
            .attr('class', 'cell-group')
            .selectAll('.cell')
            .data(d => d.values.map(v => ({ ...v, symbol: d.symbol })))
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', d => this.xScale(new Date(d.date)))
            .attr('y', d => this.yScale(d.symbol))
            .attr('width', d => {
                const nextDate = new Date(d.date);
                if (this.timeframe === '1d') {
                    nextDate.setHours(nextDate.getHours() + 1);
                } else if (this.timeframe === '1w') {
                    nextDate.setDate(nextDate.getDate() + 1);
                } else if (this.timeframe === '1m') {
                    nextDate.setDate(nextDate.getDate() + 1);
                } else if (this.timeframe === '3m') {
                    nextDate.setDate(nextDate.getDate() + 3);
                } else if (this.timeframe === '1y') {
                    nextDate.setMonth(nextDate.getMonth() + 1);
                }
                return Math.max(0, this.xScale(nextDate) - this.xScale(new Date(d.date)));
            })
            .attr('height', this.yScale.bandwidth())
            .attr('fill', d => colorScale(d.change))
            .on('mouseover', (event, d) => this.showTooltip(event, d))
            .on('mouseout', () => this.hideTooltip())
            .on('click', (event, d) => this.handleCellClick(d));

        // Add axis labels
        this.svg.append('text')
            .attr('x', config.width / 2)
            .attr('y', config.height - 5)
            .style('text-anchor', 'middle')
            .text('Time');

        this.svg.append('text')
            .attr('transform', 'rotate(-90)')
            .attr('y', 15)
            .attr('x', -config.height / 2)
            .style('text-anchor', 'middle')
            .text('Stock Symbol');
    }

    showTooltip(event, data) {
        const date = new Date(data.date);
        const formattedDate = date.toLocaleString();
        const changePercent = (data.change * 100).toFixed(2);

        this.tooltip.style('display', 'block')
            .style('left', `${event.pageX + 10}px`)
            .style('top', `${event.pageY + 10}px`)
            .html(`
                <strong>${data.symbol}</strong><br>
                Date: ${formattedDate}<br>
                Change: <span style="color: ${data.change > 0 ? 'green' : 'red'}">${changePercent}%</span>
            `);
    }

    hideTooltip() {
        this.tooltip.style('display', 'none');
    }

    handleCellClick(data) {
        console.log('Cell clicked:', data);
        // In a real app, you might show more details or navigate to a stock detail page
    }

    startAutoUpdate() {
        setInterval(() => {
            console.log('Auto-updating data...');
            this.fetchData();
        }, config.updateInterval);
    }
}

// Initialize the application when the DOM is loaded
document.addEventListener('DOMContentLoaded', () => {
    new StockHeatmap();
});
