// Mock data generator for demonstration
function generateMockData(stockCount, timeframe) {
    const stocks = [];
    const now = new Date();
    const timeframes = {
        '1d': { days: 1, interval: 15 },
        '1w': { days: 7, interval: 60 },
        '1m': { days: 30, interval: 240 },
        '3m': { days: 90, interval: 1440 },
        '1y': { days: 365, interval: 1440 }
    };

    const { days, interval } = timeframes[timeframe];
    const pointsPerDay = 1440 / interval; // Minutes in a day divided by interval
    const totalPoints = days * pointsPerDay;

    // Generate random stock symbols
    for (let i = 0; i < stockCount; i++) {
        const symbol = `STK${String.fromCharCode(65 + i % 26)}${Math.floor(i / 26)}`;
        const data = [];

        let basePrice = 100 + Math.random() * 100;
        let volatility = 0.01 + Math.random() * 0.05;

        for (let j = 0; j < totalPoints; j++) {
            const timestamp = new Date(now.getTime() - (totalPoints - j) * interval * 60000);
            const change = (Math.random() - 0.5) * volatility * basePrice;
            basePrice += change;

            data.push({
                timestamp: timestamp,
                price: Math.max(0.01, basePrice)
            });
        }

        stocks.push({
            symbol: symbol,
            data: data
        });
    }

    return stocks;
}

// Main heatmap class
class StockHeatmap {
    constructor(containerId) {
        this.container = d3.select(containerId);
        this.width = this.container.node().clientWidth;
        this.height = this.container.node().clientHeight;
        this.margin = { top: 20, right: 20, bottom: 60, left: 80 };
        this.innerWidth = this.width - this.margin.left - this.margin.right;
        this.innerHeight = this.height - this.margin.top - this.margin.bottom;

        this.svg = this.container.append("svg")
            .attr("width", this.width)
            .attr("height", this.height)
            .append("g")
            .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        this.tooltip = d3.select("#tooltip");
        this.legend = d3.select("#legend");

        this.xScale = d3.scaleTime();
        this.yScale = d3.scaleBand().padding(0.1);
        this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn);

        this.zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        // Initialize with mock data
        this.updateData();
    }

    updateData() {
        const timeframe = d3.select("#timeframe").property("value");
        const stockCount = parseInt(d3.select("#stock-count").property("value")) || 20;

        // Show loading indicator
        this.container.select(".loading").style("display", "block");

        // Simulate API call with timeout
        setTimeout(() => {
            this.data = generateMockData(stockCount, timeframe);
            this.render();
            this.container.select(".loading").style("display", "none");
        }, 500);
    }

    render() {
        if (!this.data || this.data.length === 0) return;

        // Process data for heatmap
        const allTimestamps = this.data.flatMap(stock => stock.data.map(d => d.timestamp));
        const minTimestamp = d3.min(allTimestamps);
        const maxTimestamp = d3.max(allTimestamps);

        const allPrices = this.data.flatMap(stock => stock.data.map(d => d.price));
        const minPrice = d3.min(allPrices);
        const maxPrice = d3.max(allPrices);

        // Set up scales
        this.xScale.domain([minTimestamp, maxTimestamp])
            .range([0, this.innerWidth]);

        this.yScale.domain(this.data.map(d => d.symbol))
            .range([0, this.innerHeight]);

        this.colorScale.domain([minPrice, maxPrice]);

        // Create axes
        const xAxis = d3.axisBottom(this.xScale)
            .ticks(this.innerWidth / 100)
            .tickFormat(d3.timeFormat("%b %d %H:%M"));

        const yAxis = d3.axisLeft(this.yScale);

        // Remove previous elements
        this.svg.selectAll("*").remove();

        // Add axes
        this.svg.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${this.innerHeight})`)
            .call(xAxis)
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end");

        this.svg.append("g")
            .attr("class", "y-axis")
            .call(yAxis);

        // Add axis labels
        this.svg.append("text")
            .attr("class", "axis-label")
            .attr("x", this.innerWidth / 2)
            .attr("y", this.innerHeight + this.margin.bottom - 10)
            .style("text-anchor", "middle")
            .text("Time");

        this.svg.append("text")
            .attr("class", "axis-label")
            .attr("transform", "rotate(-90)")
            .attr("x", -this.innerHeight / 2)
            .attr("y", -this.margin.left + 20)
            .style("text-anchor", "middle")
            .text("Stock Symbol");

        // Create heatmap cells
        const cells = this.svg.selectAll(".cell")
            .data(this.data)
            .enter()
            .append("g")
            .attr("class", "cell-group")
            .selectAll(".cell")
            .data(d => d.data.map(dataPoint => ({
                symbol: d.symbol,
                ...dataPoint
            })))
            .enter()
            .append("rect")
            .attr("class", "cell")
            .attr("x", d => this.xScale(d.timestamp))
            .attr("y", (d, i, nodes) => {
                const symbol = nodes[i].parentNode.__data__.symbol;
                return this.yScale(symbol);
            })
            .attr("width", this.xScale(this.data[0].data[1].timestamp) - this.xScale(this.data[0].data[0].timestamp))
            .attr("height", this.yScale.bandwidth())
            .attr("fill", d => this.colorScale(d.price))
            .on("mouseover", (event, d) => {
                this.tooltip.style("display", "block")
                    .html(`
                        <strong>${d.symbol}</strong><br>
                        Time: ${d3.timeFormat("%Y-%m-%d %H:%M")(d.timestamp)}<br>
                        Price: $${d.price.toFixed(2)}
                    `);
            })
            .on("mousemove", (event) => {
                this.tooltip.style("left", (event.pageX + 10) + "px")
                    .style("top", (event.pageY + 10) + "px");
            })
            .on("mouseout", () => {
                this.tooltip.style("display", "none");
            });

        // Add legend
        this.renderLegend(minPrice, maxPrice);
    }

    renderLegend(minPrice, maxPrice) {
        this.legend.selectAll("*").remove();

        const legendData = [
            { color: this.colorScale(minPrice), label: `$${minPrice.toFixed(2)}` },
            { color: this.colorScale((minPrice + maxPrice) / 2), label: `$${((minPrice + maxPrice) / 2).toFixed(2)}` },
            { color: this.colorScale(maxPrice), label: `$${maxPrice.toFixed(2)}` }
        ];

        const legendItems = this.legend.selectAll(".legend-item")
            .data(legendData)
            .enter()
            .append("div")
            .attr("class", "legend-item");

        legendItems.append("div")
            .attr("class", "legend-color")
            .style("background-color", d => d.color);

        legendItems.append("span")
            .text(d => d.label);
    }

    zoomed(event) {
        const transform = event.transform;

        // Apply zoom to x-axis
        this.svg.select(".x-axis").call(
            d3.axisBottom(transform.rescaleX(this.xScale))
                .ticks(this.innerWidth / 100)
                .tickFormat(d3.timeFormat("%b %d %H:%M"))
        );

        // Apply zoom to cells
        this.svg.selectAll(".cell")
            .attr("x", d => transform.applyX(this.xScale(d.timestamp)))
            .attr("width", this.xScale(this.data[0].data[1].timestamp) - this.xScale(this.data[0].data[0].timestamp) / transform.k);
    }

    zoomIn() {
        this.svg.transition()
            .duration(750)
            .call(this.zoom.scaleBy, 1.5);
    }

    zoomOut() {
        this.svg.transition()
            .duration(750)
            .call(this.zoom.scaleBy, 0.5);
    }

    resetZoom() {
        this.svg.transition()
            .duration(750)
            .call(this.zoom.transform, d3.zoomIdentity);
    }
}

// Initialize the heatmap when the page loads
document.addEventListener("DOMContentLoaded", () => {
    const heatmap = new StockHeatmap("#heatmap-container");

    // Set up event listeners
    d3.select("#refresh-btn").on("click", () => heatmap.updateData());
    d3.select("#timeframe").on("change", () => heatmap.updateData());
    d3.select("#stock-count").on("change", () => heatmap.updateData());

    d3.select("#zoom-in").on("click", () => heatmap.zoomIn());
    d3.select("#zoom-out").on("click", () => heatmap.zoomOut());
    d3.select("#reset-zoom").on("click", () => heatmap.resetZoom());

    // Handle window resize
    window.addEventListener("resize", () => {
        heatmap.width = heatmap.container.node().clientWidth;
        heatmap.height = heatmap.container.node().clientHeight;
        heatmap.innerWidth = heatmap.width - heatmap.margin.left - heatmap.margin.right;
        heatmap.innerHeight = heatmap.height - heatmap.margin.top - heatmap.margin.bottom;

        heatmap.svg.attr("width", heatmap.width)
            .attr("height", heatmap.height);

        heatmap.render();
    });
});
```

