```javascript
// Configuration
const config = {
    width: 1000,
    height: 500,
    margin: { top: 50, right: 30, bottom: 30, left: 80 },
    colors: ["#d73027", "#fc8d59", "#fee090", "#ffffbf", "#e0f3f8", "#91bfdb", "#4575b4"],
    updateInterval: 30000 // 30 seconds
};

// Global variables
let svg, xScale, yScale, colorScale, zoom;
let data = [];
let isLoading = false;

// Initialize the heatmap
function initHeatmap() {
    // Clear previous SVG if it exists
    d3.select("#heatmap-container svg").remove();

    // Create SVG container
    svg = d3.select("#heatmap-container")
        .append("svg")
        .attr("width", config.width)
        .attr("height", config.height);

    // Add zoom behavior
    zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on("zoom", zoomed);

    svg.call(zoom);

    // Create scales
    xScale = d3.scaleBand();
    yScale = d3.scaleBand();
    colorScale = d3.scaleQuantile().range(config.colors);

    // Add tooltip
    const tooltip = d3.select(".tooltip");

    // Add legend
    createLegend();

    // Initial data load
    loadData();
}

// Create legend
function createLegend() {
    const legend = d3.select("#legend");
    legend.selectAll("*").remove();

    // Create legend items
    const legendItems = legend.selectAll(".legend-item")
        .data(config.colors)
        .enter()
        .append("div")
        .attr("class", "legend-item");

    legendItems.append("div")
        .attr("class", "legend-color")
        .style("background-color", d => d);

    legendItems.append("span")
        .text((d, i) => {
            const domain = colorScale.domain();
            const min = domain[0];
            const max = domain[domain.length - 1];
            const step = (max - min) / (config.colors.length - 1);
            return `${(min + i * step).toFixed(2)}`;
        });
}

// Handle zoom/pan
function zoomed(event) {
    const transform = event.transform;
    svg.selectAll(".heatmap-cell")
        .attr("transform", transform);
    svg.selectAll(".axis-x, .axis-y")
        .attr("transform", transform);
}

// Load data from API
async function loadData() {
    if (isLoading) return;

    isLoading = true;
    d3.select(".loading").style("display", "block");

    try {
        const timeframe = d3.select("#timeframe").property("value");
        const selectedStocks = Array.from(d3.select("#stock-select").property("selectedOptions"))
            .map(opt => opt.value);

        // In a real implementation, you would fetch from an API like Alpha Vantage or Yahoo Finance
        // This is a mock implementation for demonstration
        const mockData = generateMockData(selectedStocks, timeframe);

        // Process data
        processData(mockData);

        // Update visualization
        updateHeatmap();

        // Schedule next update
        setTimeout(loadData, config.updateInterval);
    } catch (error) {
        console.error("Error loading data:", error);
    } finally {
        isLoading = false;
        d3.select(".loading").style("display", "none");
    }
}

// Generate mock data for demonstration
function generateMockData(stocks, timeframe) {
    const now = new Date();
    let startDate, interval, points;

    // Set timeframe parameters
    switch (timeframe) {
        case "1d":
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 60 * 60 * 1000; // 1 hour
            points = 24;
            break;
        case "1w":
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 6 * 60 * 60 * 1000; // 6 hours
            points = 28;
            break;
        case "1m":
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 24 * 60 * 60 * 1000; // 1 day
            points = 30;
            break;
        case "3m":
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 3 * 24 * 60 * 60 * 1000; // 3 days
            points = 30;
            break;
        case "1y":
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 7 * 24 * 60 * 60 * 1000; // 1 week
            points = 52;
            break;
        default:
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 6 * 60 * 60 * 1000;
            points = 28;
    }

    // Generate time points
    const timePoints = [];
    for (let i = 0; i < points; i++) {
        const date = new Date(startDate.getTime() + i * interval);
        timePoints.push(date);
    }

    // Generate mock data for each stock
    const mockData = [];
    stocks.forEach(stock => {
        const basePrice = 100 + Math.random() * 200;
        const volatility = 0.01 + Math.random() * 0.05;

        timePoints.forEach(time => {
            const priceChange = (Math.random() - 0.5) * volatility * basePrice;
            const price = basePrice + priceChange;

            mockData.push({
                stock: stock,
                time: time,
                price: price,
                change: priceChange / basePrice * 100 // percentage change
            });
        });
    });

    return mockData;
}

// Process data for visualization
function processData(rawData) {
    data = rawData;

    // Update scales
    const stocks = [...new Set(data.map(d => d.stock))];
    const times = [...new Set(data.map(d => d.time))];

    xScale.domain(times)
        .range([config.margin.left, config.width - config.margin.right])
        .padding(0.05);

    yScale.domain(stocks)
        .range([config.height - config.margin.bottom, config.margin.top])
        .padding(0.05);

    const priceValues = data.map(d => d.price);
    colorScale.domain([d3.min(priceValues), d3.max(priceValues)]);
}

// Update the heatmap visualization
function updateHeatmap() {
    // Remove existing cells
    svg.selectAll(".heatmap-cell").remove();
    svg.selectAll(".axis-x, .axis-y").remove();

    // Add heatmap cells
    svg.selectAll(".heatmap-cell")
        .data(data)
        .enter()
        .append("rect")
        .attr("class", "heatmap-cell")
        .attr("x", d => xScale(d.time))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price))
        .on("mouseover", function(event, d) {
            const tooltip = d3.select(".tooltip");
            tooltip.style("visibility", "visible")
                .html(`
                    <strong>${d.stock}</strong><br>
                    Time: ${d.time.toLocaleString()}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change.toFixed(2)}%
                `)
                .style("top", (event.pageY - 10) + "px")
                .style("left", (event.pageX + 10) + "px");
        })
        .on("mouseout", function() {
            d3.select(".tooltip").style("visibility", "hidden");
        });

    // Add axes
    svg.append("g")
        .attr("class", "axis-x")
        .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
        .call(d3.axisBottom(xScale).tickFormat(d3.timeFormat("%b %d %H:%M")))
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    svg.append("g")
        .attr("class", "axis-y")
        .attr("transform", `translate(${config.margin.left}, 0)`)
        .call(d3.axisLeft(yScale));

    // Update legend
    createLegend();
}

// Event listeners
document.addEventListener("DOMContentLoaded", function() {
    initHeatmap();

    // Refresh button
    d3.select("#refresh-btn").on("click", loadData);

    // Timeframe change
    d3.select("#timeframe").on("change", loadData);

    // Stock selection change
    d3.select("#stock-select").on("change", loadData);
});
