                    updateLastUpdated();
                    state.isLoading = false;
                    elements.loadingIndicator.style.display = 'none';

                    // Set up periodic updates
                    clearInterval(state.updateTimer);
                    state.updateTimer = setInterval(loadData, config.updateInterval);
                }, 500);
            }

            // Generate mock data for demonstration
            function generateMockData() {
                // Generate a list of stock symbols
                const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
                state.stocks = stocks;

                // Generate dates based on selected time range
                const now = new Date();
                let startDate;

                switch (state.currentTimeRange) {
                    case '1d':
                        startDate = new Date(now);
                        startDate.setDate(now.getDate() - 1);
                        break;
                    case '1w':
                        startDate = new Date(now);
                        startDate.setDate(now.getDate() - 7);
                        break;
                    case '1m':
                        startDate = new Date(now);
                        startDate.setMonth(now.getMonth() - 1);
                        break;
                    case '3m':
                        startDate = new Date(now);
                        startDate.setMonth(now.getMonth() - 3);
                        break;
                    case '1y':
                        startDate = new Date(now);
                        startDate.setFullYear(now.getFullYear() - 1);
                        break;
                    default:
                        startDate = new Date(now);
                        startDate.setMonth(now.getMonth() - 1);
                }

                // Generate dates array
                const dates = [];
                const currentDate = new Date(startDate);

                while (currentDate <= now) {
                    dates.push(new Date(currentDate));
                    currentDate.setDate(currentDate.getDate() + 1);
                }

                state.dates = dates;

                // Generate mock price data
                const data = [];

                stocks.forEach(stock => {
                    dates.forEach(date => {
                        // Generate a random percentage change between -10% and +10%
                        const change = (Math.random() * 20 - 10).toFixed(2);

                        data.push({
                            stock,
                            date: date.toISOString().split('T')[0],
                            change: parseFloat(change)
                        });
                    });
                });

                state.data = data;
            }

            // Render the heatmap
            function renderHeatmap() {
                if (!state.data || state.data.length === 0) return;

                const svg = d3.select(config.container).select('svg');
                const g = svg.select('g');
                const heatmapWidth = config.width - config.margin.left - config.margin.right;
                const heatmapHeight = config.height - config.margin.top - config.margin.bottom;

                // Create scales
                const xScale = d3.scaleBand()
                    .domain(state.dates.map(d => d.toISOString().split('T')[0]))
                    .range([0, heatmapWidth])
                    .padding(0.05);

                const yScale = d3.scaleBand()
                    .domain(state.stocks)
                    .range([0, heatmapHeight])
                    .padding(0.05);

                // Create color scale
                const colorScale = d3.scaleThreshold()
                    .domain([-5, -1, -0.1, 0.1, 1, 5])
                    .range(config.colors);

                // Bind data to cells
                const cells = g.select('.heatmap-cells')
                    .selectAll('.heatmap-cell')
                    .data(state.data, d => `${d.stock}-${d.date}`);

                // Update existing cells
                cells.attr('x', d => xScale(d.date))
                    .attr('y', d => yScale(d.stock))
                    .attr('width', xScale.bandwidth())
                    .attr('height', yScale.bandwidth())
                    .attr('fill', d => colorScale(d.change));

                // Add new cells
                cells.enter()
                    .append('rect')
                    .attr('class', 'heatmap-cell')
                    .attr('x', d => xScale(d.date))
                    .attr('y', d => yScale(d.stock))
                    .attr('width', xScale.bandwidth())
                    .attr('height', yScale.bandwidth())
                    .attr('fill', d => colorScale(d.change))
                    .on('mouseover', (event, d) => {
                        showTooltip(event, d);
                    })
                    .on('mouseout', hideTooltip);

                // Remove old cells
                cells.exit().remove();

                // Update axes
                updateAxes();
            }

            // Update the axes based on current zoom/pan
            function updateAxes(transform = null) {
                const svg = d3.select(config.container).select('svg');
                const g = svg.select('g');
                const heatmapWidth = config.width - config.margin.left - config.margin.right;
                const heatmapHeight = config.height - config.margin.top - config.margin.bottom;

                // Create scales
                const xScale = d3.scaleBand()
                    .domain(state.dates.map(d => d.toISOString().split('T')[0]))
                    .range([0, heatmapWidth])
                    .padding(0.05);

                const yScale = d3.scaleBand()
                    .domain(state.stocks)
                    .range([0, heatmapHeight])
                    .padding(0.05);

                // Create axis generators
                const xAxis = d3.axisBottom(xScale)
                    .tickFormat(d3.timeFormat('%b %d'))
                    .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(state.dates.length / 10) === 0));

                const yAxis = d3.axisLeft(yScale);

                // Apply transform to axes if provided
                if (transform) {
                    const newXScale = transform.rescaleX(xScale);
                    const newYScale = transform.rescaleY(yScale);

                    xAxis.scale(newXScale);
                    yAxis.scale(newYScale);
                }

                // Update x-axis
                g.select('.x-axis')
                    .attr('transform', `translate(0, ${heatmapHeight})`)
                    .call(xAxis)
                    .selectAll('text')
                    .attr('transform', 'rotate(-45)')
                    .style('text-anchor', 'end');

                // Update y-axis
                g.select('.y-axis')
                    .call(yAxis);
            }

            // Show tooltip on hover
            function showTooltip(event, data) {
                const [x, y] = d3.pointer(event);

                d3.select(elements.tooltip)
                    .style('left', `${x + 10}px`)
                    .style('top', `${y + 10}px`)
                    .style('opacity', 1)
                    .html(`
                        <strong>${data.stock}</strong><br>
                        Date: ${data.date}<br>
                        Change: ${data.change >= 0 ? '+' : ''}${data.change}%
                    `);
            }

            // Hide tooltip
            function hideTooltip() {
                d3.select(elements.tooltip)
                    .style('opacity', 0);
            }

            // Update last updated time
            function updateLastUpdated() {
                const now = new Date();
                elements.lastUpdated.textContent = now.toLocaleString();
            }

            // Zoom the heatmap
            function zoomHeatmap(factor) {
                const svg = d3.select(config.container).select('svg');
                const currentTransform = d3.zoomTransform(svg.node());
                const newTransform = currentTransform.scale(factor);

                // Apply the new transform
                svg.transition()
                    .duration(300)
                    .call(svg.call(d3.zoom().transform, newTransform));
            }

            // Reset zoom and pan
            function resetZoom() {
                const svg = d3.select(config.container).select('svg');
                const initialTransform = d3.zoomIdentity
                    .translate(config.margin.left, config.margin.top)
                    .scale(1);

                svg.transition()
                    .duration(300)
                    .call(svg.call(d3.zoom().transform, initialTransform));

                state.currentZoom = 1;
                elements.zoomInBtn.disabled = false;
                elements.zoomOutBtn.disabled = false;
            }

            // Initialize the application
            initHeatmap();
        });
    </script>
</body>
</html>
