## JavaScript Implementation

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Configuration
    const config = {
        container: '#heatmap-container',
        tooltip: '#tooltip',
        timeframeSelect: '#timeframe',
        stockSelect: '#stock-select',
        updateBtn: '#update-btn',
        resetBtn: '#reset-btn',
        legend: '#legend',
        width: 1200,
        height: 600,
        margin: { top: 50, right: 30, bottom: 50, left: 80 }
    };

    // Initialize variables
    let svg, xScale, yScale, colorScale, xAxis, yAxis, zoom;
    let data = [];
    let selectedStocks = Array.from(document.querySelector(config.stockSelect).selectedOptions).map(opt => opt.value);
    let timeframe = document.querySelector(config.timeframeSelect).value;
    let isLoading = false;

    // Initialize the visualization
    function init() {
        // Create SVG container
        svg = d3.select(config.container)
            .append('svg')
            .attr('width', config.width)
            .attr('height', config.height);

        // Create zoom behavior
        zoom = d3.zoom()
            .scaleExtent([0.5, 10])
            .on('zoom', zoomed);

        svg.call(zoom);

        // Create scales
        xScale = d3.scaleBand().padding(0.1);
        yScale = d3.scaleBand().padding(0.1);
        colorScale = d3.scaleSequential(d3.interpolateRdYlGn).domain([0, 1]);

        // Create axes
        xAxis = svg.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0, ${config.height - config.margin.bottom})`);

        yAxis = svg.append('g')
            .attr('class', 'y-axis')
            .attr('transform', `translate(${config.margin.left}, 0)`);

        // Add axis labels
        svg.append('text')
            .attr('class', 'axis-label')
            .attr('x', config.width / 2)
            .attr('y', config.height - 10)
            .style('text-anchor', 'middle')
            .text('Time');

        svg.append('text')
            .attr('class', 'axis-label')
            .attr('transform', 'rotate(-90)')
            .attr('x', -config.height / 2)
            .attr('y', 20)
            .style('text-anchor', 'middle')
            .text('Stock');

        // Add tooltip
        const tooltip = d3.select(config.tooltip);

        // Event listeners
        document.querySelector(config.updateBtn).addEventListener('click', updateData);
        document.querySelector(config.resetBtn).addEventListener('click', resetView);
        document.querySelector(config.timeframeSelect).addEventListener('change', function() {
            timeframe = this.value;
            updateData();
        });
        document.querySelector(config.stockSelect).addEventListener('change', function() {
            selectedStocks = Array.from(this.selectedOptions).map(opt => opt.value);
            updateData();
        });

        // Initial data load
        updateData();
    }

    // Update data based on current selections
    function updateData() {
        if (isLoading) return;

        isLoading = true;
        d3.select(config.container).select('.loading').style('display', 'block');

        // In a real implementation, this would fetch from an API
        // For demo purposes, we'll generate mock data
        setTimeout(() => {
            generateMockData();
            updateVisualization();
            isLoading = false;
            d3.select(config.container).select('.loading').style('display', 'none');
        }, 500);
    }

    // Generate mock data for demonstration
    function generateMockData() {
        data = [];

        // Determine time range based on selected timeframe
        const now = new Date();
        let startDate;

        switch(timeframe) {
            case '1d':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 1);
                break;
            case '1w':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
                break;
            case '1m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                break;
            case '3m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 3);
                break;
            case '1y':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 1);
                break;
            default:
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
        }

        // Generate time points (hourly for 1 day, daily otherwise)
        const timePoints = [];
        let currentTime = new Date(startDate);

        while (currentTime <= now) {
            timePoints.push(new Date(currentTime));
            if (timeframe === '1d') {
                currentTime.setHours(currentTime.getHours() + 1);
            } else {
                currentTime.setDate(currentTime.getDate() + 1);
            }
        }

        // Generate data for each selected stock
        selectedStocks.forEach(stock => {
            timePoints.forEach(time => {
                // Generate a random price change percentage between -5% and +5%
                const changePercent = (Math.random() * 10 - 5).toFixed(2);

                data.push({
                    stock: stock,
                    time: time,
                    changePercent: parseFloat(changePercent)
                });
            });
        });
    }

    // Update the visualization with current data
    function updateVisualization() {
        if (!data.length) return;

        // Update scales
        const stocks = [...new Set(data.map(d => d.stock))];
        const times = [...new Set(data.map(d => d.time))];

        xScale.domain(times.map(d => d3.timeFormat('%Y-%m-%d %H:%M')(d)))
              .range([config.margin.left, config.width - config.margin.right]);

        yScale.domain(stocks)
              .range([config.height - config.margin.bottom, config.margin.top]);

        const minChange = d3.min(data, d => d.changePercent);
        const maxChange = d3.max(data, d => d.changePercent);
        colorScale.domain([minChange, maxChange]);

        // Update axes
        xAxis.call(d3.axisBottom(xScale)
            .tickFormat(d => {
                const date = new Date(d);
                if (timeframe === '1d') {
                    return d3.timeFormat('%H:%M')(date);
                } else {
                    return d3.timeFormat('%b %d')(date);
                }
            })
            .tickSizeOuter(0))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        yAxis.call(d3.axisLeft(yScale).tickSizeOuter(0));

        // Bind data to heatmap cells
        const cells = svg.selectAll('.heatmap-cell')
            .data(data, d => `${d.stock}-${d.time}`);

        // Enter new cells
        cells.enter()
            .append('rect')
            .attr('class', 'heatmap-cell')
            .attr('x', d => xScale(d3.timeFormat('%Y-%m-%d %H:%M')(d.time)))
            .attr('y', d => yScale(d.stock))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => colorScale(d.changePercent))
            .on('mouseover', function(event, d) {
                d3.select(config.tooltip)
                    .style('opacity', 1)
                    .html(`
                        <strong>${d.stock}</strong><br>
                        Time: ${d3.timeFormat('%Y-%m-%d %H:%M')(d.time)}<br>
                        Change: ${d.changePercent}%<br>
                        ${d.changePercent > 0 ? '↑' : '↓'}
                    `)
                    .style('left', (event.pageX + 10) + 'px')
                    .style('top', (event.pageY + 10) + 'px');
            })
            .on('mouseout', function() {
                d3.select(config.tooltip).style('opacity', 0);
            });

        // Update existing cells
        cells.transition()
            .duration(500)
            .attr('x', d => xScale(d3.timeFormat('%Y-%m-%d %H:%M')(d.time)))
            .attr('y', d => yScale(d.stock))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => colorScale(d.changePercent));

        // Remove old cells
        cells.exit().remove();

        // Update legend
        updateLegend();
    }

    // Update the color legend
    function updateLegend() {
        const legend = d3.select(config.legend);
        legend.selectAll('*').remove();

        const legendData = [
            { color: colorScale(colorScale.domain()[0]), label: `${colorScale.domain()[0]}%` },
            { color: colorScale((colorScale.domain()[0] + colorScale.domain()[1]) / 2), label: '0%' },
            { color: colorScale(colorScale.domain()[1]), label: `${colorScale.domain()[1]}%` }
        ];

        const legendItems = legend.selectAll('.legend-item')
            .data(legendData)
            .enter()
            .append('div')
            .attr('class', 'legend-item');

        legendItems.append('div')
            .attr('class', 'legend-color')
            .style('background-color', d => d.color);

        legendItems.append('span')
            .text(d => d.label);
    }

    // Handle zoom/pan interactions
    function zoomed(event) {
        const transform = event.transform;

        // Apply the zoom transform to the x and y scales
        const newXScale = transform.rescaleX(xScale);
        const newYScale = transform.rescaleY(yScale);

        // Update the axes with the new scales
        xAxis.call(d3.axisBottom(newXScale)
            .tickFormat(d => {
                const date = new Date(d);
                if (timeframe === '1d') {
                    return d3.timeFormat('%H:%M')(date);
                } else {
                    return d3.timeFormat('%b %d')(date);
                }
            })
            .tickSizeOuter(0))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        yAxis.call(d3.axisLeft(newYScale).tickSizeOuter(0));

        // Update the heatmap cells with the new scales
        svg.selectAll('.heatmap-cell')
            .attr('x', d => newXScale(d3.timeFormat('%Y-%m-%d %H:%M')(d.time)))
            .attr('y', d => newYScale(d.stock))
            .attr('width', newXScale.bandwidth())
            .attr('height', newYScale.bandwidth());
    }

    // Reset the view to default
    function resetView() {
        svg.transition()
            .duration(750)
            .call(zoom.transform, d3.zoomIdentity);
    }

    // Initialize the application
    init();

    // Simulate real-time updates (every 5 seconds)
    setInterval(() => {
        if (!isLoading) {
            updateData();
        }
    }, 5000);
});
