## JavaScript Implementation (script.js)

```javascript
// Main application class
class StockHeatmap {
    constructor() {
        this.container = d3.select("#heatmap-container");
        this.tooltip = d3.select(".tooltip");
        this.legend = d3.select("#legend");
        this.timeframeSelect = d3.select("#timeframe");
        this.stockSelect = d3.select("#stock-select");
        this.updateBtn = d3.select("#update-btn");
        this.zoomInBtn = d3.select("#zoom-in");
        this.zoomOutBtn = d3.select("#zoom-out");
        this.resetZoomBtn = d3.select("#reset-zoom");

        this.margin = { top: 30, right: 30, bottom: 30, left: 60 };
        this.width = this.container.node().getBoundingClientRect().width - this.margin.left - this.margin.right;
        this.height = this.container.node().getBoundingClientRect().height - this.margin.top - this.margin.bottom;

        this.svg = this.container.append("svg")
            .attr("width", this.width + this.margin.left + this.margin.right)
            .attr("height", this.height + this.margin.top + this.margin.bottom)
            .append("g")
            .attr("transform", `translate(${this.margin.left},${this.margin.top})`);

        this.xScale = d3.scaleBand();
        this.yScale = d3.scaleBand();
        this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1]);

        this.zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        this.data = [];
        this.stocks = [];
        this.dates = [];
        this.priceChanges = [];

        this.initEventListeners();
        this.loadInitialData();
    }

    initEventListeners() {
        this.updateBtn.on("click", () => this.loadData());
        this.timeframeSelect.on("change", () => this.loadData());
        this.stockSelect.on("change", () => this.loadData());

        this.zoomInBtn.on("click", () => {
            this.svg.transition().call(this.zoom.scaleBy, 1.5);
        });

        this.zoomOutBtn.on("click", () => {
            this.svg.transition().call(this.zoom.scaleBy, 0.75);
        });

        this.resetZoomBtn.on("click", () => {
            this.svg.transition().call(this.zoom.transform, d3.zoomIdentity);
        });
    }

    zoomed(event) {
        const transform = event.transform;
        this.svg.attr("transform", transform);
    }

    async loadInitialData() {
        // Simulate loading data from an API
        this.showLoading(true);

        // In a real implementation, you would fetch data from an API
        // For demo purposes, we'll generate mock data
        setTimeout(() => {
            this.generateMockData();
            this.processData();
            this.render();
            this.showLoading(false);
        }, 1000);
    }

    async loadData() {
        this.showLoading(true);

        // In a real implementation, you would fetch data based on selected parameters
        setTimeout(() => {
            this.generateMockData();
            this.processData();
            this.render();
            this.showLoading(false);
        }, 800);
    }

    generateMockData() {
        // Get selected stocks
        const selectedStocks = Array.from(this.stockSelect.node().selectedOptions)
            .map(option => option.value);

        // Get selected timeframe
        const timeframe = this.timeframeSelect.node().value;

        // Generate mock data based on selection
        const now = new Date();
        let startDate, numDays;

        switch(timeframe) {
            case '1d':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 1);
                numDays = 1;
                break;
            case '1w':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
                numDays = 7;
                break;
            case '1m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                numDays = 30;
                break;
            case '3m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 3);
                numDays = 90;
                break;
            case '1y':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 1);
                numDays = 365;
                break;
            default:
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
                numDays = 7;
        }

        // Generate dates
        const dates = [];
        for (let i = 0; i < numDays; i++) {
            const date = new Date(startDate);
            date.setDate(startDate.getDate() + i);
            dates.push(date.toISOString().split('T')[0]);
        }

        // Generate mock price changes for each stock and date
        this.data = selectedStocks.map(stock => {
            const stockData = dates.map(date => {
                // Generate a random price change between -10% and +10%
                const change = (Math.random() * 20 - 10) / 100;
                return {
                    stock,
                    date,
                    change: change
                };
            });
            return stockData;
        }).flat();
    }

    processData() {
        // Extract unique stocks and dates
        this.stocks = [...new Set(this.data.map(d => d.stock))];
        this.dates = [...new Set(this.data.map(d => d.date))];

        // Create a matrix of price changes
        this.priceChanges = this.stocks.map(stock => {
            return this.dates.map(date => {
                const entry = this.data.find(d => d.stock === stock && d.date === date);
                return entry ? entry.change : 0;
            });
        });

        // Update color scale domain based on actual data range
        const minChange = d3.min(this.data, d => d.change);
        const maxChange = d3.max(this.data, d => d.change);
        this.colorScale.domain([minChange, maxChange]);
    }

    render() {
        // Clear previous render
        this.svg.selectAll("*").remove();

        // Set up scales
        this.xScale.domain(this.dates)
            .range([0, this.width])
            .padding(0.05);

        this.yScale.domain(this.stocks)
            .range([0, this.height])
            .padding(0.05);

        // Create heatmap cells
        const cells = this.svg.selectAll(".cell")
            .data(this.data)
            .enter()
            .append("rect")
            .attr("class", "cell")
            .attr("x", d => this.xScale(d.date))
            .attr("y", d => this.yScale(d.stock))
            .attr("width", this.xScale.bandwidth())
            .attr("height", this.yScale.bandwidth())
            .attr("fill", d => this.colorScale(d.change))
            .on("mouseover", (event, d) => this.showTooltip(event, d))
            .on("mouseout", () => this.hideTooltip());

        // Add x-axis
        this.svg.append("g")
            .attr("class", "axis axis--x")
            .attr("transform", `translate(0,${this.height})`)
            .call(d3.axisBottom(this.xScale).tickSizeOuter(0))
            .selectAll("text")
            .attr("transform", "rotate(-45)")
            .style("text-anchor", "end");

        // Add y-axis
        this.svg.append("g")
            .attr("class", "axis axis--y")
            .call(d3.axisLeft(this.yScale).tickSizeOuter(0));

        // Add axis labels
        this.svg.append("text")
            .attr("class", "axis-label")
            .attr("x", this.width / 2)
            .attr("y", this.height + this.margin.bottom - 5)
            .style("text-anchor", "middle")
            .text("Date");

        this.svg.append("text")
            .attr("class", "axis-label")
            .attr("transform", "rotate(-90)")
            .attr("y", -this.margin.left + 15)
            .attr("x", -this.height / 2)
            .style("text-anchor", "middle")
            .text("Stock");

        // Render legend
        this.renderLegend();
    }

    renderLegend() {
        this.legend.selectAll("*").remove();

        // Create legend items
        const legendData = [
            { label: "Decrease", value: this.colorScale.domain()[0] },
            { label: "Neutral", value: 0 },
            { label: "Increase", value: this.colorScale.domain()[1] }
        ];

        const legendItems = this.legend.selectAll(".legend-item")
            .data(legendData)
            .enter()
            .append("div")
            .attr("class", "legend-item");

        legendItems.append("div")
            .attr("class", "legend-color")
            .style("background-color", d => this.colorScale(d.value));

        legendItems.append("div")
            .text(d => d.label);
    }

    showTooltip(event, data) {
        this.tooltip.style("visibility", "visible")
            .style("left", (event.pageX + 10) + "px")
            .style("top", (event.pageY - 28) + "px")
            .html(`
                <strong>${data.stock}</strong><br>
                Date: ${data.date}<br>
                Change: ${(data.change * 100).toFixed(2)}%
            `);
    }

    hideTooltip() {
        this.tooltip.style("visibility", "hidden");
    }

    showLoading(show) {
        this.container.select(".loading")
            .style("display", show ? "block" : "none");
    }
}

// Initialize the application when the DOM is loaded
document.addEventListener("DOMContentLoaded", () => {
    new StockHeatmap();
});
