## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    width: 1000,
    height: 500,
    margin: { top: 20, right: 20, bottom: 60, left: 80 },
    maxZoom: 10,
    minZoom: 0.5,
    updateInterval: 30000, // 30 seconds
    defaultTimeRange: '1m'
};

// Sample stock data (in a real app, this would come from an API)
const sampleStocks = [
    'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'BRK.B', 'JNJ', 'JPM', 'V',
    'PG', 'NVDA', 'HD', 'MA', 'DIS', 'PYPL', 'ADBE', 'NFLX', 'CRM', 'VZ'
];

// Initialize the heatmap
document.addEventListener('DOMContentLoaded', function() {
    const heatmapContainer = document.getElementById('heatmap');
    const tooltip = document.querySelector('.tooltip');
    const loadingElement = document.querySelector('.loading');
    const errorElement = document.querySelector('.error');
    const refreshBtn = document.getElementById('refresh-btn');
    const zoomInBtn = document.getElementById('zoom-in-btn');
    const zoomOutBtn = document.getElementById('zoom-out-btn');
    const resetBtn = document.getElementById('reset-btn');
    const timeButtons = document.querySelectorAll('.time-btn');

    let currentData = [];
    let currentTimeRange = config.defaultTimeRange;
    let zoomLevel = 1;
    let zoomTransform = d3.zoomIdentity;
    let updateIntervalId = null;

    // Set up D3
    const svg = d3.select(heatmapContainer)
        .append('svg')
        .attr('width', config.width)
        .attr('height', config.height);

    const g = svg.append('g')
        .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

    // Add zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([config.minZoom, config.maxZoom])
        .on('zoom', zoomed);

    svg.call(zoom);

    // Initialize with default time range
    timeButtons.forEach(btn => {
        if (btn.dataset.range === config.defaultTimeRange) {
            btn.classList.add('active');
        }

        btn.addEventListener('click', function() {
            timeButtons.forEach(b => b.classList.remove('active'));
            this.classList.add('active');
            currentTimeRange = this.dataset.range;
            fetchData();
        });
    });

    // Button event listeners
    refreshBtn.addEventListener('click', fetchData);
    zoomInBtn.addEventListener('click', () => {
        const newScale = Math.min(zoomLevel * 1.5, config.maxZoom);
        svg.transition().call(zoom.scaleTo, newScale);
    });
    zoomOutBtn.addEventListener('click', () => {
        const newScale = Math.max(zoomLevel * 0.75, config.minZoom);
        svg.transition().call(zoom.scaleTo, newScale);
    });
    resetBtn.addEventListener('click', () => {
        svg.transition().call(zoom.transform, d3.zoomIdentity);
    });

    // Fetch initial data
    fetchData();

    // Set up periodic updates
    updateIntervalId = setInterval(fetchData, config.updateInterval);

    // Clean up on page unload
    window.addEventListener('beforeunload', () => {
        if (updateIntervalId) clearInterval(updateIntervalId);
    });

    // Main data fetching function
    async function fetchData() {
        loadingElement.style.display = 'block';
        errorElement.style.display = 'none';

        try {
            // In a real app, this would be an API call to a stock data service
            // For this demo, we'll generate synthetic data
            const data = generateSyntheticData(currentTimeRange);
            currentData = data;
            renderHeatmap(data);
        } catch (error) {
            console.error('Error fetching data:', error);
            errorElement.textContent = 'Failed to load data. Please try again.';
            errorElement.style.display = 'block';
        } finally {
            loadingElement.style.display = 'none';
        }
    }

    // Generate synthetic data for demonstration
    function generateSyntheticData(timeRange) {
        const now = new Date();
        let startDate, numDays;

        switch (timeRange) {
            case '1d':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 1);
                numDays = 1;
                break;
            case '1w':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
                numDays = 7;
                break;
            case '1m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                numDays = 30;
                break;
            case '3m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 3);
                numDays = 90;
                break;
            case '6m':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 6);
                numDays = 180;
                break;
            case '1y':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 1);
                numDays = 365;
                break;
            case 'max':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 5);
                numDays = 365 * 5;
                break;
            default:
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                numDays = 30;
        }

        const data = [];
        const basePrices = {};

        // Initialize base prices
        sampleStocks.forEach(stock => {
            basePrices[stock] = 100 + Math.random() * 200;
        });

        // Generate daily data points
        for (let i = 0; i < numDays; i++) {
            const date = new Date(startDate);
            date.setDate(startDate.getDate() + i);

            sampleStocks.forEach(stock => {
                // Simulate price movement
                const change = (Math.random() - 0.5) * 5; // Random change between -2.5 and +2.5
                basePrices[stock] += change;

                // Ensure price stays positive
                basePrices[stock] = Math.max(0.01, basePrices[stock]);

                data.push({
                    stock,
                    date: date.toISOString().split('T')[0],
                    price: parseFloat(basePrices[stock].toFixed(2)),
                    change: parseFloat(change.toFixed(2))
                });
            });
        }

        return data;
    }

    // Render the heatmap
    function renderHeatmap(data) {
        // Clear previous content
        g.selectAll('*').remove();

        if (data.length === 0) {
            errorElement.textContent = 'No data available for the selected time range.';
            errorElement.style.display = 'block';
            return;
        }

        // Process data
        const stocks = [...new Set(data.map(d => d.stock))];
        const dates = [...new Set(data.map(d => d.date))].sort();

        // Create a matrix of prices
        const matrix = [];
        stocks.forEach(stock => {
            const stockData = data.filter(d => d.stock === stock);
            const row = dates.map(date => {
                const dayData = stockData.find(d => d.date === date);
                return dayData ? dayData.price : null;
            });
            matrix.push(row);
        });

        // Calculate dimensions
        const cellWidth = (config.width - config.margin.left - config.margin.right) / dates.length;
        const cellHeight = (config.height - config.margin.top - config.margin.bottom) / stocks.length;

        // Create scales
        const xScale = d3.scaleBand()
            .domain(dates)
            .range([0, config.width - config.margin.left - config.margin.right])
            .padding(0.01);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, config.height - config.margin.top - config.margin.bottom])
            .padding(0.01);

        // Color scale
        const colorScale = d3.scaleLinear()
            .domain([d3.min(data, d => d.price), d3.mean(data, d => d.price), d3.max(data, d => d.price)])
            .range(['#ff0000', '#ffffff', '#00ff00']);

        // Add cells
        const cells = g.selectAll('.cell')
            .data(matrix.flatMap((row, i) => row.map((price, j) => ({
                stock: stocks[i],
                date: dates[j],
                price: price,
                change: data.find(d => d.stock === stocks[i] && d.date === dates[j])?.change || 0
            }))))
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', d => xScale(d.date))
            .attr('y', d => yScale(d.stock))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => d.price ? colorScale(d.price) : '#eeeeee')
            .on('mouseover', function(event, d) {
                if (!d.price) return;

                tooltip.style('display', 'block');
                tooltip.html(`
                    <strong>${d.stock}</strong><br>
                    Date: ${d.date}<br>
                    Price: $${d.price.toFixed(2)}<br>
                    Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}
                `);

                // Position tooltip
                const [x, y] = d3.pointer(event);
                tooltip.style('left', `${x + 10}px`);
                tooltip.style('top', `${y + 10}px`);
            })
            .on('mouseout', function() {
                tooltip.style('display', 'none');
            });

        // Add axes
        const xAxis = g.append('g')
            .attr('class', 'axis axis--x')
            .attr('transform', `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
            .call(d3.axisBottom(xScale).tickFormat(d3.timeFormat('%b %d')));

        const yAxis = g.append('g')
            .attr('class', 'axis axis--y')
            .call(d3.axisLeft(yScale));

        // Rotate x-axis labels
        xAxis.selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');
    }

    // Zoom handler
    function zoomed(event) {
        zoomTransform = event.transform;
        zoomLevel = event.transform.k;

        // Update zoom buttons
        zoomInBtn.disabled = zoomLevel >= config.maxZoom;
        zoomOutBtn.disabled = zoomLevel <= config.minZoom;

        // Apply zoom to the main group
        g.attr('transform', event.transform);

        // Adjust axis labels
        g.selectAll('.axis--x text')
            .style('font-size', `${12 / event.transform.k}px`);

        g.selectAll('.axis--y text')
            .style('font-size', `${12 / event.transform.k}px`);
    }
});
