```javascript
// Configuration
const config = {
    apiKey: 'YOUR_API_KEY', // Replace with your actual API key
    baseUrl: 'https://www.alphavantage.co/query',
    updateInterval: 30000, // 30 seconds
    colorScale: d3.scaleSequential(d3.interpolateRdYlGn).domain([-0.1, 0.1])
};

// State variables
let currentData = [];
let svg, xScale, yScale, zoom;
let tooltip = d3.select(".tooltip");
let isLoading = false;

// Initialize the heatmap
function initHeatmap() {
    const container = d3.select("#heatmap-container");
    const width = container.node().getBoundingClientRect().width;
    const height = container.node().getBoundingClientRect().height;

    // Clear previous SVG if it exists
    container.select("svg").remove();

    // Create SVG
    svg = container.append("svg")
        .attr("width", width)
        .attr("height", height);

    // Add zoom behavior
    zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on("zoom", zoomed);

    svg.call(zoom);

    // Add zoom controls
    d3.select("#zoom-in").on("click", () => {
        svg.transition().call(zoom.scaleBy, 1.2);
    });

    d3.select("#zoom-out").on("click", () => {
        svg.transition().call(zoom.scaleBy, 0.8);
    });

    d3.select("#reset-zoom").on("click", () => {
        svg.transition().call(zoom.transform, d3.zoomIdentity);
    });

    // Add event listeners
    d3.select("#update-btn").on("click", fetchData);
    d3.select("#timeframe").on("change", fetchData);

    // Initial data fetch
    fetchData();
}

// Zoom handler
function zoomed(event) {
    const { transform } = event;
    svg.selectAll("g").attr("transform", transform);
}

// Fetch data from API
async function fetchData() {
    if (isLoading) return;

    isLoading = true;
    d3.select(".loading").style("display", "block");

    try {
        const timeframe = d3.select("#timeframe").property("value");
        const selectedStocks = Array.from(d3.select("#stock-select").property("selectedOptions"))
            .map(option => option.value);

        if (selectedStocks.length === 0) {
            alert("Please select at least one stock");
            return;
        }

        // For demo purposes, we'll use mock data since we don't have an actual API key
        // In a real implementation, you would call your API here
        const mockData = generateMockData(selectedStocks, timeframe);

        currentData = mockData;
        updateHeatmap();
    } catch (error) {
        console.error("Error fetching data:", error);
        alert("Failed to fetch stock data. Please try again.");
    } finally {
        isLoading = false;
        d3.select(".loading").style("display", "none");
    }
}

// Generate mock data for demonstration
function generateMockData(stocks, timeframe) {
    const data = [];
    const now = new Date();
    let days;

    switch (timeframe) {
        case '1D': days = 1; break;
        case '1W': days = 7; break;
        case '1M': days = 30; break;
        case '3M': days = 90; break;
        case '1Y': days = 365; break;
        case '5Y': days = 1825; break;
        default: days = 30;
    }

    // Generate dates
    const dates = [];
    for (let i = 0; i < days; i++) {
        const date = new Date(now);
        date.setDate(now.getDate() - i);
        dates.push(date.toISOString().split('T')[0]);
    }

    // Generate data for each stock
    stocks.forEach(stock => {
        const basePrice = 100 + Math.random() * 200;
        dates.forEach(date => {
            const dailyChange = (Math.random() - 0.5) * 0.2; // Random change between -10% and +10%
            const price = basePrice * (1 + dailyChange);

            data.push({
                stock,
                date,
                price: parseFloat(price.toFixed(2)),
                change: dailyChange
            });
        });
    });

    return data;
}

// Update the heatmap with new data
function updateHeatmap() {
    if (!currentData || currentData.length === 0) return;

    const container = d3.select("#heatmap-container");
    const width = container.node().getBoundingClientRect().width;
    const height = container.node().getBoundingClientRect().height;

    // Clear previous content
    svg.selectAll("*").remove();

    // Get unique stocks and dates
    const stocks = [...new Set(currentData.map(d => d.stock))];
    const dates = [...new Set(currentData.map(d => d.date))].sort();

    // Set up scales
    xScale = d3.scaleBand()
        .domain(dates)
        .range([0, width])
        .padding(0.05);

    yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, height])
        .padding(0.05);

    // Create heatmap cells
    const cells = svg.selectAll(".cell")
        .data(currentData)
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.date))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => config.colorScale(d.change))
        .on("mouseover", showTooltip)
        .on("mouseout", hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat("%b %d"))
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

    const yAxis = d3.axisLeft(yScale);

    svg.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0, ${height})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    svg.append("g")
        .attr("class", "y-axis")
        .call(yAxis);

    // Update legend
    updateLegend();
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style("display", "block")
        .html(`
            <strong>${d.stock}</strong><br>
            Date: ${d.date}<br>
            Price: $${d.price.toFixed(2)}<br>
            Change: ${(d.change * 100).toFixed(2)}%
        `)
        .style("left", `${event.pageX + 10}px`)
        .style("top", `${event.pageY + 10}px`);
}

// Hide tooltip
function hideTooltip() {
    tooltip.style("display", "none");
}

// Update the legend
function updateLegend() {
    const legend = d3.select("#legend");
    legend.selectAll("*").remove();

    const colorScale = config.colorScale;
    const domain = colorScale.domain();
    const steps = 10;

    for (let i = 0; i <= steps; i++) {
        const value = domain[0] + (domain[1] - domain[0]) * (i / steps);
        const color = colorScale(value);

        legend.append("div")
            .attr("class", "legend-item")
            .html(`
                <div class="legend-color" style="background-color: ${color}"></div>
                <span>${(value * 100).toFixed(1)}%</span>
            `);
    }
}

// Initialize the application when the page loads
document.addEventListener("DOMContentLoaded", () => {
    initHeatmap();

    // Set up periodic updates
    setInterval(fetchData, config.updateInterval);
});
