    margin: { top: 50, right: 30, bottom: 50, left: 80 },
    colors: ["#d73027", "#fc8d59", "#fee090", "#ffffbf", "#e0f3f8", "#91bfdb", "#4575b4"],
    timeRanges: {
        '1d': { days: 1, label: 'Daily' },
        '1w': { days: 7, label: 'Weekly' },
        '1m': { days: 30, label: 'Monthly' },
        '3m': { days: 90, label: 'Monthly' },
        '1y': { days: 365, label: 'Monthly' },
        '5y': { days: 365 * 5, label: 'Yearly' }
    }
};

// Sample stock data (in a real app, this would come from an API)
const sampleStocks = [
    "AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "BRK.A", "JNJ", "V", "PG",
    "JPM", "NVDA", "HD", "DIS", "PYPL", "ADBE", "NFLX", "CRM", "INTC", "VZ",
    "KO", "PEP", "T", "CMCSA", "XOM", "CVX", "WMT", "MA", "UNH", "BA"
];

// Generate sample data
function generateSampleData(timeRange) {
    const days = config.timeRanges[timeRange].days;
    const data = [];
    const now = new Date();

    sampleStocks.forEach(stock => {
        const stockData = [];
        const basePrice = 100 + Math.random() * 200;

        for (let i = 0; i < days; i++) {
            const date = new Date(now);
            date.setDate(date.getDate() - i);

            const price = basePrice * (1 + (Math.random() - 0.5) * 0.1);
            const volume = Math.floor(Math.random() * 10000000);

            stockData.push({
                date: date.toISOString().split('T')[0],
                price: parseFloat(price.toFixed(2)),
                volume: volume
            });
        }

        data.push({
            symbol: stock,
            data: stockData
        });
    });

    return data;
}

// Main visualization function
function createHeatmap(data, timeRange) {
    // Clear previous visualization
    d3.select(".heatmap-container").selectAll("*").remove();

    // Set up dimensions
    const margin = config.margin;
    const width = config.width - margin.left - margin.right;
    const height = config.height - margin.top - margin.bottom;

    // Create SVG
    const svg = d3.select(".heatmap-container")
        .append("svg")
        .attr("width", width + margin.left + margin.right)
        .attr("height", height + margin.top + margin.bottom)
        .append("g")
        .attr("transform", `translate(${margin.left},${margin.top})`);

    // Parse dates and find min/max values
    const parseDate = d3.timeParse("%Y-%m-%d");
    const dates = data[0].data.map(d => parseDate(d.date));
    const minDate = d3.min(dates);
    const maxDate = d3.max(dates);

    // Create scales
    const xScale = d3.scaleTime()
        .domain([minDate, maxDate])
        .range([0, width]);

    const yScale = d3.scaleBand()
        .domain(data.map(d => d.symbol))
        .range([0, height])
        .padding(0.1);

    // Find min and max prices across all stocks
    const allPrices = data.flatMap(stock => stock.data.map(d => d.price));
    const minPrice = d3.min(allPrices);
    const maxPrice = d3.max(allPrices);

    // Color scale
    const colorScale = d3.scaleQuantize()
        .domain([minPrice, maxPrice])
        .range(config.colors);

    // Create tooltip
    const tooltip = d3.select("#tooltip");

    // Create zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .on("zoom", zoomed);

    svg.call(zoom);

    // Create groups for each stock
    const stockGroups = svg.selectAll(".stock-group")
        .data(data)
        .enter()
        .append("g")
        .attr("class", "stock-group")
        .attr("transform", d => `translate(0, ${yScale(d.symbol)})`);

    // Add rectangles for each day
    stockGroups.selectAll("rect")
        .data(d => d.data)
        .enter()
        .append("rect")
        .attr("x", d => xScale(parseDate(d.date)))
        .attr("y", 0)
        .attr("width", width / dates.length)
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price))
        .on("mouseover", function(event, d) {
            tooltip.style("visibility", "visible")
                .html(`
                    <strong>${d3.select(this.parentNode).datum().symbol}</strong><br>
                    Date: ${d.date}<br>
                    Price: $${d.price}<br>
                    Volume: ${d.volume.toLocaleString()}
                `);
        })
        .on("mousemove", function(event) {
            tooltip.style("top", (event.pageY - 10) + "px")
                .style("left", (event.pageX + 10) + "px");
        })
        .on("mouseout", function() {
            tooltip.style("visibility", "hidden");
        });

    // Add x-axis
    svg.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0, ${height})`)
        .call(d3.axisBottom(xScale)
            .ticks(d3.timeMonth.every(config.timeRanges[timeRange].days > 30 ? 1 : 2))
            .tickFormat(d3.timeFormat("%b %Y")));

    // Add y-axis
    svg.append("g")
        .attr("class", "y-axis")
        .call(d3.axisLeft(yScale));

    // Add legend
    createLegend(colorScale);

    // Zoom function
    function zoomed(event) {
        const transform = event.transform;
        svg.attr("transform", transform);

        // Adjust axis scales
        const newXScale = transform.rescaleX(xScale);
        svg.select(".x-axis").call(d3.axisBottom(newXScale)
            .ticks(d3.timeMonth.every(config.timeRanges[timeRange].days > 30 ? 1 : 2))
            .tickFormat(d3.timeFormat("%b %Y")));
    }

    // Hide loading indicator
    d3.select("#loading").style("display", "none");
}

// Create legend
function createLegend(colorScale) {
    const legend = d3.select("#legend");
    legend.selectAll("*").remove();

    const domain = colorScale.domain();
    const range = colorScale.range();

    range.forEach((color, i) => {
        const minVal = domain[0] + (i * (domain[1] - domain[0]) / range.length);
        const maxVal = domain[0] + ((i + 1) * (domain[1] - domain[0]) / range.length);

        legend.append("div")
            .attr("class", "legend-item")
            .html(`
                <div class="legend-color" style="background-color: ${color}"></div>
                <span>${minVal.toFixed(2)} - ${maxVal.toFixed(2)}</span>
            `);
    });
}

// Initialize the visualization
function init() {
    const timeRange = d3.select("#timeRange").property("value");
    const data = generateSampleData(timeRange);

    // Show loading indicator
    d3.select("#loading").style("display", "block");

    // Simulate API delay
    setTimeout(() => {
        createHeatmap(data, timeRange);
    }, 500);

    // Set up event listeners
    d3.select("#timeRange").on("change", function() {
        const newTimeRange = d3.select(this).property("value");
        const newData = generateSampleData(newTimeRange);
        createHeatmap(newData, newTimeRange);
    });

    d3.select("#refreshBtn").on("click", function() {
        const timeRange = d3.select("#timeRange").property("value");
        const newData = generateSampleData(timeRange);
        createHeatmap(newData, timeRange);
    });

    // Zoom controls
    d3.select("#zoomIn").on("click", function() {
        const svg = d3.select(".heatmap-container svg");
        const currentTransform = d3.zoomTransform(svg.node());
        svg.transition().call(zoom.scaleBy, 1.5);
    });

    d3.select("#zoomOut").on("click", function() {
        const svg = d3.select(".heatmap-container svg");
        const currentTransform = d3.zoomTransform(svg.node());
        svg.transition().call(zoom.scaleBy, 0.75);
    });

    d3.select("#resetZoom").on("click", function() {
        const svg = d3.select(".heatmap-container svg");
        svg.transition().call(zoom.transform, d3.zoomIdentity);
    });
}

// Start the application
document.addEventListener("DOMContentLoaded", init);
```

