## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 50, right: 30, bottom: 30, left: 80 },
    colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"],
    updateInterval: 30000 // 30 seconds
};

// DOM elements
const heatmapContainer = d3.select("#heatmap-container");
const tooltip = d3.select(".tooltip");
const legendContainer = d3.select("#legend");
const timeframeSelect = d3.select("#timeframe");
const stockSelect = d3.select("#stock-select");
const updateBtn = d3.select("#update-btn");
const zoomInBtn = d3.select("#zoom-in");
const zoomOutBtn = d3.select("#zoom-out");
const resetZoomBtn = d3.select("#reset-zoom");

// State variables
let data = [];
let xScale, yScale, colorScale;
let zoom;
let simulation;
let isLoading = false;

// Initialize the heatmap
function initHeatmap() {
    // Clear previous content
    heatmapContainer.selectAll("*").remove();

    // Create SVG
    const svg = heatmapContainer.append("svg")
        .attr("width", config.width)
        .attr("height", config.height);

    // Create zoom behavior
    zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on("zoom", zoomed);

    // Apply zoom to SVG
    svg.call(zoom);

    // Create main group for the heatmap
    const g = svg.append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Add zoom controls
    zoomInBtn.on("click", () => {
        svg.transition().call(zoom.scaleBy, 1.2);
    });

    zoomOutBtn.on("click", () => {
        svg.transition().call(zoom.scaleBy, 0.8);
    });

    resetZoomBtn.on("click", () => {
        svg.transition().call(zoom.transform, d3.zoomIdentity);
    });

    // Add event listeners
    updateBtn.on("click", fetchData);
    timeframeSelect.on("change", fetchData);

    // Initial data fetch
    fetchData();
}

// Zoom handler
function zoomed(event) {
    const g = heatmapContainer.select("svg g");
    g.attr("transform", event.transform);
}

// Fetch data from API
async function fetchData() {
    if (isLoading) return;

    isLoading = true;
    heatmapContainer.select(".loading").style("display", "block");

    try {
        const selectedStocks = Array.from(stockSelect.node().selectedOptions).map(opt => opt.value);
        const timeframe = timeframeSelect.node().value;

        // In a real implementation, this would be an API call to your backend
        // For demo purposes, we'll generate mock data
        data = await generateMockData(selectedStocks, timeframe);

        // Process and render the data
        processData();
        renderHeatmap();
    } catch (error) {
        console.error("Error fetching data:", error);
    } finally {
        isLoading = false;
        heatmapContainer.select(".loading").style("display", "none");
    }
}

// Generate mock data for demonstration
function generateMockData(stocks, timeframe) {
    return new Promise((resolve) => {
        setTimeout(() => {
            const mockData = [];
            const now = new Date();
            const days = getDaysForTimeframe(timeframe);

            stocks.forEach(stock => {
                const basePrice = Math.random() * 100 + 50;
                const volatility = Math.random() * 0.1 + 0.01;

                for (let i = 0; i < days; i++) {
                    const date = new Date(now);
                    date.setDate(date.getDate() - i);

                    // Generate a random price change
                    const change = (Math.random() * 2 - 1) * volatility * basePrice;
                    const price = basePrice + change;

                    mockData.push({
                        stock,
                        date: date.toISOString().split('T')[0],
                        price: parseFloat(price.toFixed(2)),
                        change: parseFloat(change.toFixed(2))
                    });
                }
            });

            resolve(mockData);
        }, 500); // Simulate network delay
    });
}

// Get number of days for the selected timeframe
function getDaysForTimeframe(timeframe) {
    switch (timeframe) {
        case '1d': return 1;
        case '1w': return 7;
        case '1m': return 30;
        case '3m': return 90;
        case '1y': return 365;
        case '5y': return 365 * 5;
        default: return 30;
    }
}

// Process the data
function processData() {
    // Group data by stock and date
    const nestedData = d3.group(data, d => d.stock, d => d.date);

    // Convert to array of objects with stock, date, and price
    const processedData = [];
    nestedData.forEach((dates, stock) => {
        dates.forEach((values, date) => {
            processedData.push({
                stock,
                date,
                price: values[0].price,
                change: values[0].change
            });
        });
    });

    data = processedData;
}

// Render the heatmap
function renderHeatmap() {
    const svg = heatmapContainer.select("svg");
    const g = svg.select("g");

    // Clear previous content
    g.selectAll("*").remove();

    // Get unique stocks and dates
    const stocks = [...new Set(data.map(d => d.stock))];
    const dates = [...new Set(data.map(d => d.date))].sort();

    // Set up scales
    xScale = d3.scaleBand()
        .domain(dates)
        .range([0, config.width - config.margin.left - config.margin.right])
        .padding(0.05);

    yScale = d3.scaleBand()
        .domain(stocks)
        .range([0, config.height - config.margin.top - config.margin.bottom])
        .padding(0.1);

    // Get min and max price for color scale
    const priceExtent = d3.extent(data, d => d.price);
    colorScale = d3.scaleQuantile()
        .domain(priceExtent)
        .range(config.colors);

    // Create heatmap cells
    const cells = g.selectAll(".cell")
        .data(data)
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.date))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price))
        .on("mouseover", showTooltip)
        .on("mouseout", hideTooltip);

    // Add axes
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat("%b %d"))
        .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

    const yAxis = d3.axisLeft(yScale);

    g.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    g.append("g")
        .attr("class", "y-axis")
        .call(yAxis);

    // Add axis labels
    g.append("text")
        .attr("class", "x-axis-label")
        .attr("x", (config.width - config.margin.left - config.margin.right) / 2)
        .attr("y", config.height - config.margin.top - config.margin.bottom + 40)
        .style("text-anchor", "middle")
        .text("Date");

    g.append("text")
        .attr("class", "y-axis-label")
        .attr("transform", "rotate(-90)")
        .attr("x", - (config.height - config.margin.top - config.margin.bottom) / 2)
        .attr("y", -50)
        .style("text-anchor", "middle")
        .text("Stock");

    // Render legend
    renderLegend();

    // Set up real-time updates
    setupRealTimeUpdates();
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style("display", "block")
        .html(`
            <strong>${d.stock}</strong><br>
            Date: ${d.date}<br>
            Price: $${d.price.toFixed(2)}<br>
            Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}
        `);

    // Position tooltip near the mouse
    const [x, y] = d3.pointer(event);
    tooltip.style("left", `${x + 20}px`)
        .style("top", `${y + 20}px`);
}

// Hide tooltip
function hideTooltip() {
    tooltip.style("display", "none");
}

// Render the color legend
function renderLegend() {
    legendContainer.selectAll("*").remove();

    const legendItems = colorScale.range().map((color, i) => {
        const extent = colorScale.invertExtent(color);
        return {
            color,
            min: extent[0],
            max: extent[1]
        };
    });

    const legend = legendContainer.selectAll(".legend-item")
        .data(legendItems)
        .enter()
        .append("div")
        .attr("class", "legend-item");

    legend.append("div")
        .attr("class", "legend-color")
        .style("background-color", d => d.color);

    legend.append("span")
        .text(d => `$${d.min.toFixed(2)} - $${d.max.toFixed(2)}`);
}

// Set up real-time updates
function setupRealTimeUpdates() {
    // Clear any existing interval
    if (simulation) clearInterval(simulation);

    // Set up interval for updates
    simulation = setInterval(async () => {
        if (isLoading) return;

        try {
            const selectedStocks = Array.from(stockSelect.node().selectedOptions).map(opt => opt.value);
            const timeframe = timeframeSelect.node().value;

            // In a real implementation, this would fetch only the latest data
            // For demo purposes, we'll generate new mock data
            const newData = await generateMockData(selectedStocks, timeframe);

            // Update the data
            data = newData;

            // Process and render the updated data
            processData();
            renderHeatmap();
        } catch (error) {
            console.error("Error updating data:", error);
        }
    }, config.updateInterval);
}

// Initialize the application
document.addEventListener("DOMContentLoaded", initHeatmap);
