## JavaScript Implementation (app.js)

```javascript
// Main application code
document.addEventListener('DOMContentLoaded', function() {
    // Configuration
    const config = {
        container: '#heatmap-container',
        width: document.querySelector('#heatmap-container').clientWidth,
        height: document.querySelector('#heatmap-container').clientHeight,
        margin: { top: 30, right: 30, bottom: 30, left: 80 },
        tooltip: '#tooltip',
        legend: '#legend',
        timeframe: document.getElementById('timeframe').value,
        stocks: Array.from(document.getElementById('stock-select').selectedOptions).map(opt => opt.value)
    };

    // Initialize the heatmap
    const heatmap = new StockHeatmap(config);

    // Event listeners
    document.getElementById('update-btn').addEventListener('click', () => {
        heatmap.updateConfig({
            timeframe: document.getElementById('timeframe').value,
            stocks: Array.from(document.getElementById('stock-select').selectedOptions).map(opt => opt.value)
        });
        heatmap.fetchData();
    });

    document.getElementById('reset-btn').addEventListener('click', () => {
        heatmap.resetView();
    });

    // Initial data fetch
    heatmap.fetchData();

    // Set up periodic updates (every 30 seconds)
    setInterval(() => {
        heatmap.fetchData();
    }, 30000);
});

// Stock Heatmap class
class StockHeatmap {
    constructor(config) {
        this.config = config;
        this.data = [];
        this.svg = null;
        this.xScale = null;
        this.yScale = null;
        this.colorScale = null;
        this.zoom = null;
        this.tooltip = d3.select(config.tooltip);

        this.init();
    }

    init() {
        // Clear any existing SVG
        d3.select(this.config.container).selectAll('svg').remove();

        // Create SVG element
        this.svg = d3.select(this.config.container)
            .append('svg')
            .attr('width', this.config.width)
            .attr('height', this.config.height);

        // Add zoom behavior
        this.zoom = d3.zoom()
            .scaleExtent([0.5, 10])
            .on('zoom', (event) => this.zoomed(event));

        this.svg.call(this.zoom);

        // Add group for heatmap
        this.heatmapGroup = this.svg.append('g')
            .attr('class', 'heatmap-group');

        // Add axes groups
        this.xAxisGroup = this.svg.append('g')
            .attr('class', 'x-axis')
            .attr('transform', `translate(0, ${this.config.margin.top})`);

        this.yAxisGroup = this.svg.append('g')
            .attr('class', 'y-axis')
            .attr('transform', `translate(${this.config.margin.left}, 0)`);

        // Add legend
        this.createLegend();
    }

    updateConfig(newConfig) {
        Object.assign(this.config, newConfig);
        this.init(); // Reinitialize with new config
    }

    fetchData() {
        // In a real application, this would fetch from an API
        // For this demo, we'll generate mock data
        this.showLoading(true);

        // Simulate API call delay
        setTimeout(() => {
            this.generateMockData();
            this.render();
            this.showLoading(false);
        }, 500);
    }

    generateMockData() {
        const { timeframe, stocks } = this.config;
        const now = new Date();
        let startDate, interval, dateFormat;

        // Determine time range based on timeframe
        switch (timeframe) {
            case '1D':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 1);
                interval = d3.timeHour.every(1);
                dateFormat = d3.timeFormat('%H:%M');
                break;
            case '1W':
                startDate = new Date(now);
                startDate.setDate(now.getDate() - 7);
                interval = d3.timeDay.every(1);
                dateFormat = d3.timeFormat('%a %d');
                break;
            case '1M':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                interval = d3.timeDay.every(1);
                dateFormat = d3.timeFormat('%b %d');
                break;
            case '3M':
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 3);
                interval = d3.timeDay.every(3);
                dateFormat = d3.timeFormat('%b %d');
                break;
            case '1Y':
                startDate = new Date(now);
                startDate.setFullYear(now.getFullYear() - 1);
                interval = d3.timeMonth.every(1);
                dateFormat = d3.timeFormat('%b %Y');
                break;
            default:
                startDate = new Date(now);
                startDate.setMonth(now.getMonth() - 1);
                interval = d3.timeDay.every(1);
                dateFormat = d3.timeFormat('%b %d');
        }

        // Generate time points
        const timePoints = [];
        let currentDate = new Date(startDate);
        while (currentDate <= now) {
            timePoints.push(new Date(currentDate));
            currentDate = interval.offset(currentDate);
        }

        // Generate mock data for each stock and time point
        this.data = stocks.map(stock => {
            const basePrice = 100 + Math.random() * 200; // Random base price
            return {
                stock,
                values: timePoints.map(time => {
                    // Simulate price movement with some randomness
                    const change = (Math.random() - 0.5) * 5; // Random change between -2.5 and +2.5
                    const price = basePrice + change;

                    return {
                        time: new Date(time),
                        price: parseFloat(price.toFixed(2)),
                        formattedTime: dateFormat(time)
                    };
                })
            };
        });
    }

    render() {
        if (!this.data || this.data.length === 0) return;

        // Flatten data for color scale calculation
        const allPrices = this.data.flatMap(stock =>
            stock.values.map(d => d.price)
        );

        // Calculate dimensions
        const innerWidth = this.config.width - this.config.margin.left - this.config.margin.right;
        const innerHeight = this.config.height - this.config.margin.top - this.config.margin.bottom;

        // Create scales
        this.xScale = d3.scaleBand()
            .domain(this.data[0].values.map(d => d.formattedTime))
            .range([this.config.margin.left, this.config.width - this.config.margin.right])
            .padding(0.05);

        this.yScale = d3.scaleBand()
            .domain(this.data.map(d => d.stock))
            .range([this.config.margin.top, this.config.height - this.config.margin.bottom])
            .padding(0.05);

        this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([d3.min(allPrices), d3.max(allPrices)]);

        // Create axes
        const xAxis = d3.axisBottom(this.xScale)
            .tickSizeOuter(0);

        const yAxis = d3.axisLeft(this.yScale)
            .tickSizeOuter(0);

        this.xAxisGroup.call(xAxis)
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        this.yAxisGroup.call(yAxis);

        // Draw heatmap cells
        const cells = this.heatmapGroup.selectAll('.cell')
            .data(this.data.flatMap(stock =>
                stock.values.map(value => ({
                    stock: stock.stock,
                    time: value.formattedTime,
                    price: value.price
                }))
            ));

        cells.enter()
            .append('rect')
            .attr('class', 'cell')
            .merge(cells)
            .attr('x', d => this.xScale(d.time))
            .attr('y', d => this.yScale(d.stock))
            .attr('width', this.xScale.bandwidth())
            .attr('height', this.yScale.bandwidth())
            .attr('fill', d => this.colorScale(d.price))
            .on('mouseover', (event, d) => this.showTooltip(event, d))
            .on('mouseout', () => this.hideTooltip());

        cells.exit().remove();

        // Update legend
        this.updateLegend();
    }

    showTooltip(event, d) {
        this.tooltip.style('display', 'block')
            .html(`
                <strong>${d.stock}</strong><br>
                Time: ${d.time}<br>
                Price: $${d.price.toFixed(2)}
            `)
            .style('left', (event.pageX + 10) + 'px')
            .style('top', (event.pageY - 28) + 'px');
    }

    hideTooltip() {
        this.tooltip.style('display', 'none');
    }

    createLegend() {
        const legend = d3.select(this.config.legend);

        // Clear existing legend
        legend.selectAll('*').remove();

        // Add legend title
        legend.append('div')
            .style('text-align', 'center')
            .style('margin-bottom', '5px')
            .text('Price Legend');

        // Create legend items
        const legendItems = legend.append('div')
            .style('display', 'flex')
            .style('justify-content', 'center')
            .style('flex-wrap', 'wrap');

        // We'll update this when we have actual data
    }

    updateLegend() {
        if (!this.colorScale) return;

        const legend = d3.select(this.config.legend);
        const legendItems = legend.select('div');

        // Clear existing items
        legendItems.selectAll('*').remove();

        // Create color scale for legend
        const legendScale = d3.scaleLinear()
            .domain(this.colorScale.domain())
            .range([0, 200]);

        // Create gradient for legend
        const defs = legend.append('defs');
        const gradient = defs.append('linearGradient')
            .attr('id', 'legend-gradient')
            .attr('x1', '0%')
            .attr('y1', '0%')
            .attr('x2', '100%')
            .attr('y2', '0%');

        gradient.append('stop')
            .attr('offset', '0%')
            .attr('stop-color', this.colorScale(this.colorScale.domain()[0]));

        gradient.append('stop')
            .attr('offset', '100%')
            .attr('stop-color', this.colorScale(this.colorScale.domain()[1]));

        // Add gradient bar
        legendItems.append('svg')
            .attr('width', 200)
            .attr('height', 20)
            .append('rect')
            .attr('width', 200)
            .attr('height', 20)
            .style('fill', 'url(#legend-gradient)');

        // Add min and max labels
        legendItems.append('div')
            .style('margin-left', '5px')
            .html(`$${this.colorScale.domain()[0].toFixed(2)}`);

        legendItems.append('div')
            .style('margin-left', 'auto')
            .style('margin-right', '5px')
            .html(`$${this.colorScale.domain()[1].toFixed(2)}`);
    }

    zoomed(event) {
        this.heatmapGroup.attr('transform', event.transform);

        // Adjust axis scales
        const newXScale = event.transform.rescaleX(this.xScale);
        const newYScale = event.transform.rescaleY(this.yScale);

        // Update axes
        this.xAxisGroup.call(d3.axisBottom(newXScale).tickSizeOuter(0))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        this.yAxisGroup.call(d3.axisLeft(newYScale).tickSizeOuter(0));
    }

    resetView() {
        this.svg.transition()
            .duration(750)
            .call(this.zoom.transform, d3.zoomIdentity);
    }

    showLoading(show) {
        const loading = d3.select(this.config.container).select('.loading');
        if (show) {
            loading.style('display', 'block');
        } else {
            loading.style('display', 'none');
        }
    }
}
