        minStocks: 5,
        maxStocks: 50,
        defaultStocks: 20,
        minUpdateInterval: 100,
        maxUpdateInterval: 5000,
        defaultUpdateInterval: 1000,
        timeRanges: {
            '1h': 60,
            '4h': 240,
            '1d': 1440,
            '1w': 10080,
            '1m': 43200
        }
    };

