    const resetViewBtn = document.getElementById('resetView');
    const selectedStockDiv = document.getElementById('selectedStock');
    const legendContainer = d3.select('#legend');

    // State variables
    let currentData = [];
    let stocks = [];
    let timePoints = [];
    let colorScale;
    let zoom;
    let svg;
    let heatmapGroup;
    let xScale, yScale;
    let updateIntervalId = null;
    let currentTimeRange = config.timeRanges[timeRangeSelect.value];
    let currentStockCount = config.defaultStocks;
    let currentUpdateInterval = config.defaultUpdateInterval;

    // Initialize the visualization
    init();

    function init() {
        // Set up initial UI controls
        stockCountSlider.value = currentStockCount;
        stockCountValue.textContent = currentStockCount;
        updateIntervalSlider.value = currentUpdateInterval;
        updateIntervalValue.textContent = currentUpdateInterval;

        // Set up event listeners
        timeRangeSelect.addEventListener('change', handleTimeRangeChange);
        stockCountSlider.addEventListener('input', handleStockCountChange);
        updateIntervalSlider.addEventListener('input', handleUpdateIntervalChange);
