        // Start real-time updates
        startRealTimeUpdates();
    }

    function generateStocks() {
        // Generate random stock symbols
        const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        stocks = Array.from({ length: currentStockCount }, (_, i) => {
            const first = letters[Math.floor(Math.random() * letters.length)];
            const second = letters[Math.floor(Math.random() * letters.length)];
            return `${first}${second}${Math.floor(100 + Math.random() * 900)}`;
        });
    }

    function generateTimePoints() {
        // Generate time points based on selected range
        const now = new Date();
        const minutes = currentTimeRange;
        timePoints = Array.from({ length: minutes }, (_, i) => {
            const date = new Date(now.getTime() - (minutes - i) * 60000);
            return date.toISOString();
        });
    }

    function generateInitialData() {
        // Generate initial random data
        currentData = stocks.flatMap(stock =>
            timePoints.map(time => ({
                stock,
