            .attr('transform', `translate(${config.margin.left},${config.margin.top})`);

        // Set up scales
        xScale = d3.scaleBand()
            .domain(timePoints)
            .range([0, width])
            .padding(0.01);

        yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, height])
            .padding(0.01);

        // Set up color scale
        const minPrice = d3.min(currentData, d => d.price);
        const maxPrice = d3.max(currentData, d => d.price);
        colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
            .domain([minPrice, maxPrice]);

        // Create legend
        createLegend();

        // Set up zoom
        zoom = d3.zoom()
            .scaleExtent([1, 10])
            .translateExtent([[0, 0], [width, height]])
            .on('zoom', handleZoom);

        svg.call(zoom);

        // Draw the heatmap
        updateHeatmap();
    }

    function createLegend() {
        // Clear previous legend
        legendContainer.html('');

        // Create legend items
        const legendItems = [
            { label: 'Low', color: colorScale(colorScale.domain()[0]) },
            { label: 'Medium', color: colorScale((colorScale.domain()[0] + colorScale.domain()[1]) / 2) },
            { label: 'High', color: colorScale(colorScale.domain()[1]) }
        ];

        legendItems.forEach(item => {
            const legendItem = legendContainer.append('div')
                .attr('class', 'legend-item');

            legendItem.append('div')
                .attr('class', 'color-box')
                .style('background-color', item.color);

            legendItem.append('div')
                .text(item.label);
        });
    }

    function updateHeatmap() {
        // Remove existing cells
        heatmapGroup.selectAll('.cell').remove();

        // Create cells
        const cells = heatmapGroup.selectAll('.cell')
            .data(currentData)
            .enter()
            .append('rect')
            .attr('class', 'cell')
            .attr('x', d => xScale(d.time))
            .attr('y', d => yScale(d.stock))
            .attr('width', xScale.bandwidth())
            .attr('height', yScale.bandwidth())
            .attr('fill', d => colorScale(d.price))
            .on('mouseover', handleMouseOver)
            .on('mouseout', handleMouseOut)
            .on('click', handleClick);

        // Add axes
        updateAxes();
    }

    function updateAxes() {
        // Remove existing axes
        heatmapGroup.selectAll('.axis').remove();

        // Add X axis
        heatmapGroup.append('g')
            .attr('class', 'axis axis-x')
            .attr('transform', `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
            .call(d3.axisBottom(xScale)
                .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(xScale.domain().length / 10) === 0))
                .tickFormat(d => new Date(d).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })))
            .selectAll('text')
            .attr('transform', 'rotate(-45)')
            .style('text-anchor', 'end');

        // Add Y axis
        heatmapGroup.append('g')
            .attr('class', 'axis axis-y')
            .call(d3.axisLeft(yScale));
    }

    function handleZoom(event) {
        heatmapGroup.attr('transform', event.transform);
    }

    function resetView() {
        svg.transition()
            .duration(750)
            .call(zoom.transform, d3.zoomIdentity);
    }

    function handleMouseOver(event, d) {
        // Highlight the cell
        d3.select(this)
            .attr('stroke', '#000')
            .attr('stroke-width', 2);

        // Show stock info
        selectedStockDiv.innerHTML = `
            <strong>${d.stock}</strong><br>
            Time: ${new Date(d.time).toLocaleString()}<br>
            Price: $${d.price.toFixed(2)}<br>
            Change: ${d.change > 0 ? '+' : ''}${d.change.toFixed(2)}%
        `;
    }

    function handleMouseOut() {
        // Remove highlight
        d3.select(this)
            .attr('stroke', null)
            .attr('stroke-width', null);

        // Clear stock info
        selectedStockDiv.innerHTML = 'None selected';
    }

    function handleClick(event, d) {
        // Center the view on the clicked cell
        const x = xScale(d.time) + xScale.bandwidth() / 2;
        const y = yScale(d.stock) + yScale.bandwidth() / 2;

        svg.transition()
            .duration(750)
            .call(zoom.translateTo, x, y, [0.5, 0.5]);
    }

    function handleTimeRangeChange() {
        currentTimeRange = config.timeRanges[this.value];
        generateTimePoints();
        generateInitialData();
        createHeatmap();
    }

    function handleStockCountChange() {
        currentStockCount = parseInt(this.value);
        stockCountValue.textContent = currentStockCount;
        generateStocks();
        generateInitialData();
        createHeatmap();
    }

    function handleUpdateIntervalChange() {
        currentUpdateInterval = parseInt(this.value);
        updateIntervalValue.textContent = currentUpdateInterval;
        startRealTimeUpdates();
    }

    function startRealTimeUpdates() {
        // Clear any existing interval
        if (updateIntervalId) {
            clearInterval(updateIntervalId);
        }

        // Set up new interval
        updateIntervalId = setInterval(() => {
            // Simulate real-time updates by modifying some random data points
            const updates = Math.min(5, currentData.length);
            for (let i = 0; i < updates; i++) {
                const index = Math.floor(Math.random() * currentData.length);
                const change = (Math.random() - 0.5) * 2;
                currentData[index].price += change;
                currentData[index].change = change;
            }

            // Update the heatmap
            updateHeatmap();
        }, currentUpdateInterval);
    }

    // Clean up on page unload
    window.addEventListener('beforeunload', () => {
        if (updateIntervalId) {
            clearInterval(updateIntervalId);
        }
    });
});
