                legend.selectAll('*').remove();

                const colorScale = d3.scaleQuantile()
                    .range(config.colors);

                // We'll update the domain when we have actual data
                const legendItems = legend.selectAll('.legend-item')
                    .data(colorScale.range())
                    .enter()
                    .append('div')
                    .attr('class', 'legend-item');

                legendItems.append('div')
                    .attr('class', 'legend-color')
                    .style('background-color', d => d);

                legendItems.append('span')
                    .text((d, i) => {
                        // This will be updated when we have actual data
                        return '';
                    });
            }

            // Update legend with actual data ranges
            function updateLegend(min, max) {
                const legend = d3.select(config.legend);
                const legendItems = legend.selectAll('.legend-item');

                // Create a scale for the legend
                const legendScale = d3.scaleLinear()
                    .domain([min, max])
                    .range([0, config.colors.length - 1]);

                legendItems.each(function(d, i) {
                    const value = legendScale.invert(i);
                    d3.select(this).select('span')
                        .text(value.toFixed(2));
                });
            }

            // Handle zoom/pan
            function zoomed(event) {
                const transform = event.transform;
                svg.selectAll('.heatmap-cell')
                    .attr('transform', transform);
                svg.selectAll('.axis-x, .axis-y')
                    .call(transform.rescaleX(xScale), transform.rescaleY(yScale));
            }

            // Reset zoom
            function resetZoom() {
                svg.transition()
                    .duration(750)
                    .call(zoom.transform, d3.zoomIdentity);
            }

            // Update data based on current selections
            async function updateData() {
                if (isLoading) return;

                isLoading = true;
                d3.select(config.container).select('.loading').style('display', 'block');

                try {
                    const timeframe = d3.select(config.timeframeSelect).property('value');
                    const selectedStocks = Array.from(d3.select(config.stockSelect).property('selectedOptions'))
                        .map(option => option.value);

                    // In a real implementation, you would fetch data from an API
                    // For this example, we'll generate mock data
                    const data = await generateMockData(timeframe, selectedStocks);

                    heatmapData = data;
                    renderHeatmap();
                } catch (error) {
                    console.error('Error updating data:', error);
                    d3.select(config.container).append('div')
                        .attr('class', 'error')
                        .text('Error loading data. Please try again.');
                } finally {
                    isLoading = false;
                    d3.select(config.container).select('.loading').style('display', 'none');
                }
            }

            // Generate mock data for demonstration
            async function generateMockData(timeframe, stocks) {
                // Simulate API delay
                await new Promise(resolve => setTimeout(resolve, 500));

                const now = new Date();
                const endDate = moment(now).format('YYYY-MM-DD');
                let startDate;

                switch (timeframe) {
                    case '1d':
                        startDate = moment(now).subtract(1, 'day').format('YYYY-MM-DD');
                        break;
                    case '1w':
                        startDate = moment(now).subtract(1, 'week').format('YYYY-MM-DD');
                        break;
                    case '1m':
                        startDate = moment(now).subtract(1, 'month').format('YYYY-MM-DD');
                        break;
                    case '3m':
                        startDate = moment(now).subtract(3, 'months').format('YYYY-MM-DD');
                        break;
                    case '1y':
                        startDate = moment(now).subtract(1, 'year').format('YYYY-MM-DD');
                        break;
                    case '5y':
                        startDate = moment(now).subtract(5, 'years').format('YYYY-MM-DD');
                        break;
                    default:
                        startDate = moment(now).subtract(1, 'month').format('YYYY-MM-DD');
                }

                // Generate dates between start and end
                const dates = [];
                let currentDate = moment(startDate);
                while (currentDate <= moment(endDate)) {
                    dates.push(currentDate.format('YYYY-MM-DD'));
                    currentDate = currentDate.add(1, 'day');
                }

                // Generate mock data for each stock and date
                const data = [];
                stocks.forEach(stock => {
                    dates.forEach(date => {
                        // Generate a random price change percentage
                        const change = (Math.random() * 10 - 5).toFixed(2); // -5% to +5%

                        data.push({
                            stock: stock,
                            date: date,
                            change: parseFloat(change)
                        });
                    });
                });

                return data;
            }

            // Render the heatmap with current data
            function renderHeatmap() {
                if (!heatmapData || heatmapData.length === 0) return;

                // Clear previous heatmap
                svg.selectAll('*').remove();

                // Get unique stocks and dates
                const stocks = [...new Set(heatmapData.map(d => d.stock))];
                const dates = [...new Set(heatmapData.map(d => d.date))];

                // Calculate cell dimensions
                const cellWidth = (config.width - config.margin.left - config.margin.right) / dates.length;
                const cellHeight = (config.height - config.margin.top - config.margin.bottom) / stocks.length;

                // Create scales
                xScale = d3.scaleBand()
                    .domain(dates)
                    .range([config.margin.left, config.width - config.margin.right])
                    .padding(0.01);

                yScale = d3.scaleBand()
                    .domain(stocks)
                    .range([config.margin.top, config.height - config.margin.bottom])
                    .padding(0.01);

                // Get min and max values for color scale
                const minValue = d3.min(heatmapData, d => d.change);
                const maxValue = d3.max(heatmapData, d => d.change);

                colorScale = d3.scaleQuantile()
                    .domain([minValue, maxValue])
                    .range(config.colors);

                // Update legend with actual data ranges
                updateLegend(minValue, maxValue);

                // Create heatmap cells
                const cells = svg.selectAll('.heatmap-cell')
                    .data(heatmapData)
                    .enter()
                    .append('rect')
                    .attr('class', 'heatmap-cell')
                    .attr('x', d => xScale(d.date))
                    .attr('y', d => yScale(d.stock))
                    .attr('width', xScale.bandwidth())
                    .attr('height', yScale.bandwidth())
                    .attr('fill', d => colorScale(d.change))
                    .on('mouseover', function(event, d) {
                        const tooltip = d3.select(config.tooltip);
                        tooltip.style('display', 'block')
                            .html(`
                                <strong>${d.stock}</strong><br>
                                Date: ${d.date}<br>
                                Change: ${d.change}%
                            `)
                            .style('left', (event.pageX + 10) + 'px')
                            .style('top', (event.pageY + 10) + 'px');
                    })
                    .on('mouseout', function() {
                        d3.select(config.tooltip).style('display', 'none');
                    });

                // Add axes
                const xAxis = d3.axisBottom(xScale)
                    .tickFormat(d => moment(d).format('MMM D'))
                    .tickValues(xScale.domain().filter((d, i) => i % Math.ceil(dates.length / 10) === 0));

                const yAxis = d3.axisLeft(yScale);

                svg.append('g')
                    .attr('class', 'axis-x')
                    .attr('transform', `translate(0, ${config.height - config.margin.bottom})`)
                    .call(xAxis)
                    .selectAll('text')
                    .attr('transform', 'rotate(-45)')
                    .style('text-anchor', 'end');

                svg.append('g')
                    .attr('class', 'axis-y')
                    .attr('transform', `translate(${config.margin.left}, 0)`)
                    .call(yAxis);

                // Add axis labels
                svg.append('text')
                    .attr('class', 'axis-label')
                    .attr('x', config.width / 2)
                    .attr('y', config.height - 5)
                    .style('text-anchor', 'middle')
                    .text('Date');

                svg.append('text')
                    .attr('class', 'axis-label')
                    .attr('transform', 'rotate(-90)')
                    .attr('x', -config.height / 2)
                    .attr('y', 15)
                    .style('text-anchor', 'middle')
                    .text('Stock');
            }

            // Set up event listeners
            function setupEventListeners() {
                d3.select(config.updateButton).on('click', updateData);
                d3.select(config.timeframeSelect).on('change', updateData);
                d3.select(config.stockSelect).on('change', updateData);

                // Set up periodic updates
                clearInterval(updateIntervalId);
                updateIntervalId = setInterval(updateData, config.updateInterval);
            }

            // Initialize the application
            initHeatmap();
            setupEventListeners();

            // Clean up on page unload
            window.addEventListener('beforeunload', function() {
                clearInterval(updateIntervalId);
            });
        });
    </script>
</body>
