## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    width: 1200,
    height: 600,
    margin: { top: 30, right: 30, bottom: 30, left: 60 },
    colors: ["#d73027", "#fc8d59", "#fee08b", "#ffffbf", "#d9ef8b", "#91cf60", "#1a9850"],
    updateInterval: 30000 // 30 seconds
};

// DOM elements
const heatmapContainer = d3.select("#heatmap-container");
const timeframeSelect = d3.select("#timeframe");
const stocksSelect = d3.select("#stocks");
const updateBtn = d3.select("#update-btn");
const resetBtn = d3.select("#reset-btn");
const tooltip = d3.select("#tooltip");
const legendContainer = d3.select("#legend");

// State variables
let data = [];
let xScale, yScale, colorScale;
let zoom;
let simulation;

// Initialize the visualization
function init() {
    // Set up zoom behavior
    zoom = d3.zoom()
        .scaleExtent([0.5, 10])
        .on("zoom", zoomed);

    // Create SVG container
    const svg = heatmapContainer.append("svg")
        .attr("width", config.width)
        .attr("height", config.height)
        .call(zoom);

    // Create main group for the heatmap
    svg.append("g")
        .attr("class", "heatmap-group");

    // Create axes groups
    svg.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0, ${config.height - config.margin.bottom})`);

    svg.append("g")
        .attr("class", "y-axis")
        .attr("transform", `translate(${config.margin.left}, 0)`);

    // Create legend
    createLegend();

    // Load initial data
    updateData();

    // Set up event listeners
    timeframeSelect.on("change", updateData);
    stocksSelect.on("change", updateData);
    updateBtn.on("click", updateData);
    resetBtn.on("click", resetView);

    // Set up periodic updates
    setInterval(updateData, config.updateInterval);
}

// Create color legend
function createLegend() {
    const legendData = [
        { label: "Min", color: config.colors[0] },
        { label: "Max", color: config.colors[config.colors.length - 1] }
    ];

    const legendItems = legendContainer.selectAll(".legend-item")
        .data(legendData)
        .enter()
        .append("div")
        .attr("class", "legend-item");

    legendItems.append("div")
        .attr("class", "legend-color")
        .style("background-color", d => d.color);

    legendItems.append("span")
        .text(d => d.label);
}

// Fetch and update data
async function updateData() {
    const timeframe = timeframeSelect.property("value");
    const selectedStocks = Array.from(stocksSelect.property("selectedOptions")).map(opt => opt.value);

    // Show loading state
    heatmapContainer.select(".loading").style("display", "block");

    try {
        // In a real implementation, this would fetch from an API
        // For demo purposes, we'll generate mock data
        data = generateMockData(timeframe, selectedStocks);

        // Process and render the data
        processData();
        renderHeatmap();

        // Hide loading state
        heatmapContainer.select(".loading").style("display", "none");
    } catch (error) {
        console.error("Error updating data:", error);
        heatmapContainer.select(".loading").text("Error loading data. Please try again.");
    }
}

// Generate mock data for demonstration
function generateMockData(timeframe, stocks) {
    const now = new Date();
    let startDate, interval, pointsPerDay;

    // Set parameters based on timeframe
    switch (timeframe) {
        case "1D":
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 1);
            interval = 5 * 60 * 1000; // 5 minutes
            pointsPerDay = 24 * 12;
            break;
        case "1W":
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 30 * 60 * 1000; // 30 minutes
            pointsPerDay = 24 * 2;
            break;
        case "1M":
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 1);
            interval = 2 * 60 * 60 * 1000; // 2 hours
            pointsPerDay = 12;
            break;
        case "3M":
            startDate = new Date(now);
            startDate.setMonth(now.getMonth() - 3);
            interval = 4 * 60 * 60 * 1000; // 4 hours
            pointsPerDay = 6;
            break;
        case "1Y":
            startDate = new Date(now);
            startDate.setFullYear(now.getFullYear() - 1);
            interval = 24 * 60 * 60 * 1000; // 1 day
            pointsPerDay = 1;
            break;
        default:
            startDate = new Date(now);
            startDate.setDate(now.getDate() - 7);
            interval = 30 * 60 * 1000;
            pointsPerDay = 24 * 2;
    }

    const mockData = [];
    const days = Math.ceil((now - startDate) / (24 * 60 * 60 * 1000));

    stocks.forEach(stock => {
        let basePrice = 100 + Math.random() * 200;

        for (let day = 0; day < days; day++) {
            const dayDate = new Date(startDate);
            dayDate.setDate(startDate.getDate() + day);

            for (let point = 0; point < pointsPerDay; point++) {
                const timestamp = new Date(dayDate);
                timestamp.setTime(dayDate.getTime() + point * interval);

                // Simulate price movement
                const change = (Math.random() - 0.5) * 2;
                basePrice += change;

                mockData.push({
                    stock: stock,
                    date: timestamp,
                    price: Math.max(1, basePrice) // Ensure price is positive
                });
            }
        }
    });

    return mockData;
}

// Process the data for visualization
function processData() {
    // Group data by stock and date
    const nestedData = d3.group(data, d => d.stock, d => d.date);

    // Convert to array of objects with stock, date, and price
    const processedData = [];
    nestedData.forEach((dates, stock) => {
        dates.forEach((values, date) => {
            processedData.push({
                stock: stock,
                date: date,
                price: d3.mean(values, d => d.price)
            });
        });
    });

    data = processedData;
}

// Render the heatmap
function renderHeatmap() {
    const svg = heatmapContainer.select("svg");
    const heatmapGroup = svg.select(".heatmap-group");

    // Clear previous content
    heatmapGroup.selectAll("*").remove();

    // Set up scales
    const stocks = [...new Set(data.map(d => d.stock))];
    const dates = [...new Set(data.map(d => d.date))].sort((a, b) => a - b);
    const prices = data.map(d => d.price);

    xScale = d3.scaleBand()
        .domain(dates)
        .range([config.margin.left, config.width - config.margin.right])
        .padding(0.05);

    yScale = d3.scaleBand()
        .domain(stocks)
        .range([config.height - config.margin.bottom, config.margin.top])
        .padding(0.1);

    colorScale = d3.scaleQuantile()
        .domain([d3.min(prices), d3.max(prices)])
        .range(config.colors);

    // Create heatmap cells
    const cells = heatmapGroup.selectAll(".cell")
        .data(data)
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.date))
        .attr("y", d => yScale(d.stock))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.price))
        .on("mouseover", showTooltip)
        .on("mouseout", hideTooltip);

    // Update axes
    updateAxes();
}

// Update the axes
function updateAxes() {
    const svg = heatmapContainer.select("svg");

    // X-axis (time)
    const xAxis = d3.axisBottom(xScale)
        .tickFormat(d3.timeFormat("%b %d %H:%M"))
        .ticks(Math.min(10, xScale.domain().length));

    svg.select(".x-axis")
        .call(xAxis)
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    // Y-axis (stocks)
    const yAxis = d3.axisLeft(yScale);
    svg.select(".y-axis").call(yAxis);
}

// Show tooltip on hover
function showTooltip(event, d) {
    tooltip.style("display", "block")
        .html(`
            <strong>${d.stock}</strong><br>
            ${d3.timeFormat("%b %d, %Y %H:%M")(d.date)}<br>
            Price: $${d.price.toFixed(2)}
        `)
        .style("left", `${event.pageX + 10}px`)
        .style("top", `${event.pageY + 10}px`);
}

// Hide tooltip
function hideTooltip() {
    tooltip.style("display", "none");
}

// Handle zoom/pan
function zoomed(event) {
    const svg = heatmapContainer.select("svg");
    const heatmapGroup = svg.select(".heatmap-group");

    // Apply the zoom transform to the heatmap group
    heatmapGroup.attr("transform", event.transform);

    // Adjust the axes
    const newXScale = event.transform.rescaleX(xScale);
    const newYScale = event.transform.rescaleY(yScale);

    svg.select(".x-axis").call(d3.axisBottom(newXScale).tickFormat(d3.timeFormat("%b %d %H:%M")));
    svg.select(".y-axis").call(d3.axisLeft(newYScale));
}

// Reset the view to default
function resetView() {
    const svg = heatmapContainer.select("svg");
    svg.transition()
        .duration(750)
        .call(zoom.transform, d3.zoomIdentity);
}

// Initialize the visualization when the page loads
document.addEventListener("DOMContentLoaded", init);
```

