## JavaScript Implementation (app.js)

```javascript
// Configuration
const config = {
    width: 1000,
    height: 500,
    margin: { top: 30, right: 30, bottom: 30, left: 80 },
    colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"],
    updateInterval: 30000 // 30 seconds
};

// DOM elements
const heatmapContainer = d3.select("#heatmap-container");
const tooltip = d3.select("#tooltip");
const legendContainer = d3.select("#legend");
const timeframeSelect = document.getElementById("timeframe");
const stockSelect = document.getElementById("stock-select");
const updateBtn = document.getElementById("update-btn");

// Data variables
let stockData = [];
let currentTimeframe = timeframeSelect.value;
let selectedStocks = Array.from(stockSelect.selectedOptions).map(opt => opt.value);

// Initialize the visualization
function init() {
    // Set up event listeners
    timeframeSelect.addEventListener("change", handleTimeframeChange);
    updateBtn.addEventListener("click", fetchData);

    // Initial data fetch
    fetchData();

    // Set up periodic updates
    setInterval(fetchData, config.updateInterval);
}

// Fetch data from API (simulated with mock data)
async function fetchData() {
    showLoading(true);

    try {
        // In a real implementation, you would fetch from an API like:
        // const response = await fetch(`/api/stocks?symbols=${selectedStocks.join(',')}&timeframe=${currentTimeframe}`);
        // const data = await response.json();

        // Simulated data for demonstration
        const data = generateMockData();
        processData(data);
        renderHeatmap();
    } catch (error) {
        console.error("Error fetching data:", error);
        showLoading(false);
    }
}

// Process the raw data
function processData(data) {
    stockData = data.map(stock => {
        return {
            symbol: stock.symbol,
            name: stock.name,
            prices: stock.prices.map(price => ({
                date: new Date(price.date),
                price: price.price,
                change: price.change,
                volume: price.volume
            }))
        };
    });
}

// Render the heatmap
function renderHeatmap() {
    // Clear previous visualization
    heatmapContainer.selectAll("*").remove();

    if (stockData.length === 0) {
        showLoading(false);
        return;
    }

    // Calculate dimensions
    const innerWidth = config.width - config.margin.left - config.margin.right;
    const innerHeight = config.height - config.margin.top - config.margin.bottom;

    // Create SVG
    const svg = heatmapContainer.append("svg")
        .attr("width", config.width)
        .attr("height", config.height)
        .append("g")
        .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

    // Get all dates from the first stock (assuming all have same dates)
    const dates = stockData[0].prices.map(p => p.date);

    // Create scales
    const xScale = d3.scaleBand()
        .domain(dates.map(d => d.toISOString()))
        .range([0, innerWidth])
        .padding(0.05);

    const yScale = d3.scaleBand()
        .domain(stockData.map(d => d.symbol))
        .range([0, innerHeight])
        .padding(0.1);

    // Create color scale
    const allChanges = stockData.flatMap(stock =>
        stock.prices.map(p => p.change)
    );

    const colorScale = d3.scaleQuantile()
        .domain([d3.min(allChanges), d3.max(allChanges)])
        .range(config.colors);

    // Create zoom behavior
    const zoom = d3.zoom()
        .scaleExtent([1, 10])
        .translateExtent([[0, 0], [innerWidth, innerHeight]])
        .on("zoom", (event) => {
            svg.attr("transform", event.transform);
        });

    // Apply zoom to the SVG
    svg.call(zoom);

    // Add X axis
    svg.append("g")
        .attr("class", "x-axis")
        .attr("transform", `translate(0,${innerHeight})`)
        .call(d3.axisBottom(xScale)
            .tickFormat(d => moment(d).format("MMM D"))
            .tickSizeOuter(0))
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

    // Add Y axis
    svg.append("g")
        .attr("class", "y-axis")
        .call(d3.axisLeft(yScale));

    // Add cells
    const cells = svg.selectAll(".cell")
        .data(stockData.flatMap(stock =>
            stock.prices.map(price => ({
                symbol: stock.symbol,
                date: price.date,
                price: price.price,
                change: price.change,
                volume: price.volume
            }))
        ))
        .enter()
        .append("rect")
        .attr("class", "cell")
        .attr("x", d => xScale(d.date.toISOString()))
        .attr("y", d => yScale(d.symbol))
        .attr("width", xScale.bandwidth())
        .attr("height", yScale.bandwidth())
        .attr("fill", d => colorScale(d.change))
        .on("mouseover", showTooltip)
        .on("mouseout", hideTooltip);

    // Add legend
    renderLegend(colorScale);

    showLoading(false);
}

// Render the legend
function renderLegend(colorScale) {
    legendContainer.selectAll("*").remove();

    const thresholds = colorScale.quantiles();

    // Add min value
    legendContainer.append("div")
        .attr("class", "legend-item")
        .html(`<div class="legend-color" style="background-color: ${colorScale(colorScale.domain()[0])}"></div>
               <span>${colorScale.domain()[0].toFixed(2)}%</span>`);

    // Add quantile values
    thresholds.forEach((threshold, i) => {
        legendContainer.append("div")
            .attr("class", "legend-item")
            .html(`<div class="legend-color" style="background-color: ${colorScale(threshold)}"></div>
                   <span>${threshold.toFixed(2)}%</span>`);
    });

    // Add max value
    legendContainer.append("div")
        .attr("class", "legend-item")
        .html(`<div class="legend-color" style="background-color: ${colorScale(colorScale.domain()[1])}"></div>
               <span>${colorScale.domain()[1].toFixed(2)}%</span>`);
}

// Show tooltip on hover
function showTooltip(event, d) {
    const [x, y] = d3.pointer(event);

    tooltip.style("display", "block")
        .style("left", `${x + 10}px`)
        .style("top", `${y + 10}px`)
        .html(`
            <strong>${d.symbol}</strong><br>
            Date: ${moment(d.date).format("MMM D, YYYY")}<br>
            Price: $${d.price.toFixed(2)}<br>
            Change: ${d.change.toFixed(2)}%<br>
            Volume: ${d.volume.toLocaleString()}
        `);
}

// Hide tooltip
function hideTooltip() {
    tooltip.style("display", "none");
}

// Handle timeframe change
function handleTimeframeChange() {
    currentTimeframe = timeframeSelect.value;
    fetchData();
}

// Show/hide loading indicator
function showLoading(show) {
    const loading = heatmapContainer.select(".loading");
    if (show) {
        loading.style("display", "block");
    } else {
        loading.style("display", "none");
    }
}

// Generate mock data for demonstration
function generateMockData() {
    const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "TSLA", "META"];
    const stockNames = {
        "AAPL": "Apple Inc.",
        "MSFT": "Microsoft Corporation",
        "GOOGL": "Alphabet Inc.",
        "AMZN": "Amazon.com Inc.",
        "TSLA": "Tesla Inc.",
        "META": "Meta Platforms Inc."
    };

    const timeframes = {
        "1d": { days: 1, interval: 30 }, // 30 minutes
        "1w": { days: 7, interval: 60 }, // 1 hour
        "1m": { days: 30, interval: 1440 }, // 1 day
        "3m": { days: 90, interval: 1440 }, // 1 day
        "1y": { days: 365, interval: 1440 } // 1 day
    };

    const selected = Array.from(stockSelect.selectedOptions).map(opt => opt.value);
    const { days, interval } = timeframes[currentTimeframe];

    const mockData = selected.map(symbol => {
        const basePrice = 100 + Math.random() * 200;
        const prices = [];

        for (let i = 0; i < days * (1440 / interval); i++) {
            const date = new Date();
            date.setDate(date.getDate() - days + (i * (interval / 1440)));

            const change = (Math.random() * 10 - 5) * (1 - (i / (days * (1440 / interval))));
            const price = basePrice * (1 + change / 100);
            const volume = Math.floor(Math.random() * 10000000);

            prices.push({
                date: date.toISOString(),
                price: parseFloat(price.toFixed(2)),
                change: parseFloat(change.toFixed(2)),
                volume: volume
            });
        }

        return {
            symbol: symbol,
            name: stockNames[symbol],
            prices: prices
        };
    });

    return mockData;
}

// Initialize the application
init();
