                case "1y": timeRange = 365 * 24 * 60 * 60 * 1000; break;
                default: timeRange = 30 * 24 * 60 * 60 * 1000;
            }

            const startTime = now - timeRange;
            const timeSteps = Math.min(100, Math.floor(timeRange / (60 * 60 * 1000))); // At least 1 hour intervals

            for (let i = 0; i < timeSteps; i++) {
                const timestamp = startTime + (i * (timeRange / timeSteps));
                const date = new Date(timestamp);

                stocks.forEach(stock => {
