                .call(d3.axisBottom(xScale).tickFormat(d => new Date(d).toLocaleDateString()))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            g.append("g")
                .attr("class", "axis axis--y")
                .call(d3.axisLeft(yScale));

            // Add color legend
            const legend = g.append("g")
                .attr("class", "legend")
                .attr("transform", `translate(${config.width - config.margin.left - config.margin.right - 100}, 0)`);

            const legendScale = d3.scaleLinear()
                .domain([-0.05, 0.05])
                .range([0, 100]);

            const legendAxis = d3.axisBottom(legendScale)
                .ticks(5)
                .tickFormat(d => `${(d * 100).toFixed(0)}%`);

            legend.append("g")
                .attr("transform", "translate(0, 10)")
                .call(legendAxis);

            const legendWidth = 100;
            const legendHeight = 20;

            legend.selectAll(".legend-cell")
                .data(d3.range(100))
                .enter()
                .append("rect")
                .attr("class", "legend-cell")
                .attr("x", d => d)
                .attr("y", 0)
                .attr("width", 1)
                .attr("height", legendHeight)
                .attr("fill", d => config.colors[Math.floor(d / 10)]);
        }

        // Initial render
        updateHeatmap();

        // Simulate real-time updates
        setInterval(() => {
            // In a real app, you would fetch new data from an API
            const newData = generateSampleData();
            stockData = [...stockData.slice(-stockData.length + newData.length), ...newData];
            updateHeatmap();
