        // Mock data generator for demonstration
        function generateMockData(stock, timeframe) {
            const now = new Date();
            let interval, count;

            switch(timeframe) {
                case '1d':
                    interval = 5 * 60 * 1000; // 5 minutes
                    count = 24 * 12; // 12 points per hour
                    break;
                case '1w':
                    interval = 30 * 60 * 1000; // 30 minutes
                    count = 7 * 24 * 2; // 2 points per hour
                    break;
                case '1m':
                    interval = 2 * 60 * 60 * 1000; // 2 hours
                    count = 30 * 12; // 12 points per day
                    break;
                case '3m':
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    count = 90 * 4; // 4 points per day
                    break;
                case '1y':
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    count = 365;
                    break;
                default:
                    interval = 5 * 60 * 1000;
                    count = 24 * 12;
            }

            const data = [];
            const labels = [];
            const basePrice = 100 + Math.random() * 200;

            for (let i = 0; i < count; i++) {
                const timestamp = new Date(now - (count - i) * interval);
                const price = basePrice + (Math.random() * 20 - 10) + (i * 0.1);
                data.push(price.toFixed(2));

                // Format label based on timeframe
                if (timeframe === '1d') {
                    labels.push(timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}));
                } else {
                    labels.push(timestamp.toLocaleDateString());
                }
            }

            return {
                stock: stock,
                timeframe: timeframe,
                labels: labels,
                data: data
            };
        }

        // Create heatmap
        function createHeatmap(data) {
            const trace = {
                z: [data.data],
                x: data.labels,
                y: [data.stock],
                type: 'heatmap',
                colorscale: 'Portland',
                showscale: true,
                colorbar: {
                    title: 'Price ($)'
                }
            };

            const layout = {
                title: `${data.stock} Stock Price Heatmap (${data.timeframe})`,
                xaxis: {
                    title: 'Time',
                    automargin: true
                },
                yaxis: {
                    title: 'Stock',
                    automargin: true
                },
                margin: {
                    l: 50,
                    r: 50,
                    b: 100,
                    t: 50,
                    pad: 4
                },
                dragmode: 'pan',
                hovermode: 'closest'
            };

            Plotly.newPlot('heatmap', [trace], layout, {
                responsive: true,
                displayModeBar: true,
                modeBarButtonsToRemove: ['toImage'],
                displaylogo: false
            });
        }

        // Initialize with default values
        function init() {
            const stock = document.getElementById('stock-select').value;
            const timeframe = document.getElementById('timeframe-select').value;
            const data = generateMockData(stock, timeframe);
            createHeatmap(data);

            // Set up update button
            document.getElementById('update-btn').addEventListener('click', () => {
                const newStock = document.getElementById('stock-select').value;
                const newTimeframe = document.getElementById('timeframe-select').value;
                const newData = generateMockData(newStock, newTimeframe);
                createHeatmap(newData);
            });

            // Set up real-time updates (every 5 seconds)
            setInterval(() => {
                const currentStock = document.getElementById('stock-select').value;
                const currentTimeframe = document.getElementById('timeframe-select').value;
                const updatedData = generateMockData(currentStock, currentTimeframe);
                createHeatmap(updatedData);
            }, 5000);
        }

        // Initialize when DOM is loaded
        document.addEventListener('DOMContentLoaded', init);
    </script>
</body>
</html>
