    <div class="container">
        <h1>Stock Price Heatmap</h1>

        <div class="controls">
            <div class="time-range">
                <label for="time-range">Time Range:</label>
                <select id="time-range">
                    <option value="1h">1 Hour</option>
                    <option value="4h">4 Hours</option>
                    <option value="1d" selected>1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m">1 Month</option>
                </select>
            </div>
            <div>
                <button id="reset-zoom">Reset Zoom</button>
            </div>
        </div>

        <div id="heatmap-container"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 20, right: 20, bottom: 30, left: 50 },
            cellSize: 20,
            colors: ["#006837", "#1a9850", "#66bd63", "#a6d96a", "#d9ef8b", "#ffffbf", "#fee08b", "#fdae61", "#f46d43", "#d73027", "#a50026"]
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "NVDA", "JPM", "V", "WMT"];
        const timeIntervals = generateTimeIntervals('1d');

        // Initialize the heatmap
        const svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        // Create scales
        const xScale = d3.scaleBand()
            .domain(timeIntervals)
            .range([0, config.width - config.margin.left - config.margin.right])
            .padding(0.05);

        const yScale = d3.scaleBand()
            .domain(stocks)
            .range([0, config.height - config.margin.top - config.margin.bottom])
            .padding(0.05);

        const colorScale = d3.scaleQuantile()
            .range(config.colors);

        // Create axes
        const xAxis = d3.axisBottom(xScale)
            .tickFormat(d3.timeFormat("%H:%M"));

        const yAxis = d3.axisLeft(yScale);

        g.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
            .call(xAxis);

        g.append("g")
            .attr("class", "y-axis")
            .call(yAxis);

        // Add zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", zoomed);

        svg.call(zoom);

        function zoomed(event) {
            const transform = event.transform;
            g.attr("transform", `translate(${config.margin.left},${config.margin.top}) scale(${transform.k}) translate(${transform.x},${transform.y})`);
        }

        // Reset zoom button
        d3.select("#reset-zoom").on("click", () => {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        });

        // Time range selector
        d3.select("#time-range").on("change", function() {
            const range = this.value;
            updateTimeRange(range);
        });

        // Tooltip
        const tooltip = d3.select("body").append("div")
            .attr("class", "tooltip")
            .style("opacity", 0);

        // Generate initial data
        let heatmapData = generateRandomData();

        // Update the heatmap
        updateHeatmap();

        // Simulate real-time updates
        setInterval(() => {
            updateData();
            updateHeatmap();
        }, 5000);

        // Functions
        function generateTimeIntervals(range) {
            const now = new Date();
            const intervals = [];
            let count, step;

            switch(range) {
                case '1h':
                    count = 60;
                    step = 60 * 1000; // 1 minute
                    break;
                case '4h':
                    count = 240;
                    step = 60 * 1000;
                    break;
                case '1d':
                    count = 24 * 60;
                    step = 60 * 1000;
                    break;
                case '1w':
                    count = 7 * 24 * 60;
                    step = 60 * 1000;
                    break;
                case '1m':
                    count = 30 * 24 * 60;
                    step = 60 * 1000;
                    break;
                default:
                    count = 24 * 60;
                    step = 60 * 1000;
            }

            for (let i = 0; i < count; i++) {
                intervals.push(new Date(now - (count - i) * step));
            }

            return intervals;
        }

        function generateRandomData() {
            const data = [];
            const now = new Date();

            stocks.forEach(stock => {
                timeIntervals.forEach(time => {
                    data.push({
                        stock: stock,
                        time: time,
                        price: 100 + Math.random() * 100,
                        change: (Math.random() - 0.5) * 5
                    });
                });
            });

            return data;
        }

        function updateData() {
            // In a real app, this would fetch new data from an API
            // For this example, we'll just update the latest data points
            const latestTime = timeIntervals[timeIntervals.length - 1];

            stocks.forEach(stock => {
                const existingIndex = heatmapData.findIndex(d => d.stock === stock && d.time.getTime() === latestTime.getTime());
                if (existingIndex !== -1) {
                    // Update existing data point
                    heatmapData[existingIndex].price += (Math.random() - 0.5) * 2;
                    heatmapData[existingIndex].change = (Math.random() - 0.5) * 5;
                } else {
                    // Add new data point
                    heatmapData.push({
                        stock: stock,
                        time: latestTime,
                        price: 100 + Math.random() * 100,
                        change: (Math.random() - 0.5) * 5
                    });
                }
            });
        }

        function updateTimeRange(range) {
            const newTimeIntervals = generateTimeIntervals(range);
            timeIntervals.length = 0;
            timeIntervals.push(...newTimeIntervals);

            // Update scales
            xScale.domain(timeIntervals);

            // Update axes
            g.select(".x-axis")
                .transition()
                .duration(500)
                .call(xAxis);

            // Regenerate data
            heatmapData = generateRandomData();
            updateHeatmap();
        }

        function updateHeatmap() {
            // Update color scale domain
            colorScale.domain(d3.extent(heatmapData, d => d.change));

            // Bind data to cells
            const cells = g.selectAll(".cell")
                .data(heatmapData, d => `${d.stock}-${d.time}`);

            // Enter new cells
            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    tooltip.transition()
                        .duration(200)
                        .style("opacity", .9);
                    tooltip.html(`
                        <strong>${d.stock}</strong><br>
                        Time: ${d3.timeFormat("%H:%M")(d.time)}<br>
                        Price: $${d.price.toFixed(2)}<br>
                        Change: ${d.change.toFixed(2)}%
                    `)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    tooltip.transition()
                        .duration(500)
                        .style("opacity", 0);
                });

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr("fill", d => colorScale(d.change));

            // Remove old cells
            cells.exit().remove();
        }
    </script>
</body>
