        let svg, xScale, yScale, colorScale, zoom;
        let data = [];
        let currentSymbol = 'AAPL';
        let currentTimeframe = '1d';
        let updateIntervalId;

        // Initialize the visualization
        function init() {
            // Create SVG container
            svg = d3.select('.heatmap-container')
                .append('svg')
                .attr('width', config.width)
                .attr('height', config.height);

            // Create scales
            xScale = d3.scaleBand().padding(0.01);
            yScale = d3.scaleBand().padding(0.01);
            colorScale = d3.scaleQuantile()
                .range(['#ffffbf', '#fee090', '#fdae61', '#f46d43', '#d73027']);

            // Create zoom behavior
            zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on('zoom', zoomed);

            // Apply zoom to SVG
            svg.call(zoom);

            // Add tooltip
            const tooltip = d3.select('.tooltip');

            // Add reset button functionality
            d3.select('#reset').on('click', resetZoom);

            // Add event listeners for controls
            d3.select('#symbol').on('change', function() {
                currentSymbol = this.value;
                fetchData();
            });

            d3.select('#timeframe').on('change', function() {
                currentTimeframe = this.value;
                fetchData();
            });

            // Initial data fetch
            fetchData();

            // Set up periodic updates
            updateIntervalId = setInterval(fetchData, config.updateInterval);
        }

        // Fetch mock data (in a real app, this would be an API call)
        function fetchData() {
            // Simulate API call with mock data
            const mockData = generateMockData(currentSymbol, currentTimeframe);
            updateVisualization(mockData);
        }

        // Generate mock data for demonstration
        function generateMockData(symbol, timeframe) {
            const now = new Date();
            const timeframes = {
                '1d': { count: 24, interval: 'hour' },
                '1w': { count: 7, interval: 'day' },
                '1m': { count: 30, interval: 'day' },
                '3m': { count: 90, interval: 'day' },
                '1y': { count: 12, interval: 'month' }
            };

            const { count, interval } = timeframes[timeframe];
            const data = [];

            for (let i = 0; i < count; i++) {
                const date = new Date(now);
                if (interval === 'hour') {
                    date.setHours(now.getHours() - i);
                } else if (interval === 'day') {
                    date.setDate(now.getDate() - i);
                } else if (interval === 'month') {
                    date.setMonth(now.getMonth() - i);
                }

                const price = 100 + Math.random() * 100 - 50; // Random price between 50 and 150
                data.push({
                    date: date.toISOString().split('T')[0],
                    time: interval === 'hour' ? date.toISOString().split('T')[1].split('.')[0] : null,
                    price: parseFloat(price.toFixed(2))
                });
            }

            return data.reverse(); // Show oldest first
        }

        // Update the visualization with new data
        function updateVisualization(newData) {
            data = newData;

            // Update scales
            const xValues = data.map(d => d.time || d.date);
            const yValues = [currentSymbol];
            const prices = data.map(d => d.price);

            xScale.domain(xValues).range([config.margin.left, config.width - config.margin.right]);
            yScale.domain(yValues).range([config.height - config.margin.bottom, config.margin.top]);
            colorScale.domain([d3.min(prices), d3.max(prices)]);

            // Remove existing elements
            svg.selectAll('*').remove();

            // Add heatmap cells
            const cells = svg.selectAll('.cell')
                .data(data)
                .enter()
                .append('rect')
                .attr('class', 'cell')
                .attr('x', d => xScale(d.time || d.date))
                .attr('y', yScale(currentSymbol))
                .attr('width', xScale.bandwidth())
                .attr('height', yScale.bandwidth())
                .attr('fill', d => colorScale(d.price))
                .on('mouseover', function(event, d) {
                    const tooltip = d3.select('.tooltip');
                    tooltip.style('visibility', 'visible')
                        .html(`<strong>${currentSymbol}</strong><br>
                              Date: ${d.date}${d.time ? ' ' + d.time : ''}<br>
                              Price: $${d.price.toFixed(2)}`)
                        .style('top', (event.pageY - 10) + 'px')
                        .style('left', (event.pageX + 10) + 'px');
                })
                .on('mouseout', function() {
                    d3.select('.tooltip').style('visibility', 'hidden');
                });

            // Add axes
            const xAxis = d3.axisBottom(xScale);
            const yAxis = d3.axisLeft(yScale);

            svg.append('g')
                .attr('class', 'x-axis')
                .attr('transform', `translate(0,${config.height - config.margin.bottom})`)
                .call(xAxis)
                .selectAll('text')
                .attr('transform', 'rotate(-45)')
                .style('text-anchor', 'end');

            svg.append('g')
                .attr('class', 'y-axis')
                .attr('transform', `translate(${config.margin.left},0)`)
                .call(yAxis);

            // Add axis labels
            svg.append('text')
                .attr('class', 'x-label')
                .attr('x', config.width / 2)
                .attr('y', config.height - 5)
                .style('text-anchor', 'middle')
                .text('Time');

            svg.append('text')
                .attr('class', 'y-label')
                .attr('transform', 'rotate(-90)')
                .attr('x', -config.height / 2)
                .attr('y', 15)
                .style('text-anchor', 'middle')
                .text('Stock Symbol');
        }

        // Handle zoom/pan events
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the cells
            svg.selectAll('.cell')
                .attr('transform', transform);

            // Adjust the axes
            svg.select('.x-axis').call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            svg.select('.y-axis').call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }

        // Reset zoom to default
        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        // Initialize the visualization when the page loads
        window.onload = init;
    </script>
</body>
</html>
```

## Features

1. **Interactive Heatmap**:
   - Displays stock prices as color-coded cells
   - Hover over cells to see detailed information

2. **Real-time Updates**:
   - Simulates real-time data updates (every 5 seconds)
   - In a production app, you would replace the mock data with actual API calls

3. **Zoom/Pan Functionality**:
   - Mouse wheel to zoom in/out
   - Click and drag to pan
   - Reset button to return to default view

4. **Controls**:
   - Select different stock symbols
   - Choose different timeframes (1 day, 1 week, etc.)

5. **Responsive Design**:
