            padding: 8px 16px;
            background: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background: #45a049;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>

        <div class="controls">
            <div class="time-range">
                <button id="1h">1H</button>
                <button id="4h">4H</button>
                <button id="1d">1D</button>
                <button id="1w">1W</button>
                <button id="1m">1M</button>
            </div>
            <div>
                <span>Zoom: Scroll</span> |
                <span>Pan: Click & Drag</span>
            </div>
        </div>

        <div id="heatmap-container"></div>
        <div class="tooltip" id="tooltip"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1200,
            height: 600,
            margin: { top: 20, right: 20, bottom: 50, left: 60 },
            timeRange: '1d', // default time range
            updateInterval: 5000 // 5 seconds
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'PG'];
        let data = generateInitialData();

        // Initialize the heatmap
        const heatmap = new Heatmap('#heatmap-container', data, config);

        // Simulate real-time updates (in a real app, this would use Socket.IO or WebSockets)
        setInterval(() => {
            updateData();
            heatmap.update(data);
        }, config.updateInterval);

        // Time range buttons
        document.getElementById('1h').addEventListener('click', () => setTimeRange('1h'));
        document.getElementById('4h').addEventListener('click', () => setTimeRange('4h'));
        document.getElementById('1d').addEventListener('click', () => setTimeRange('1d'));
        document.getElementById('1w').addEventListener('click', () => setTimeRange('1w'));
        document.getElementById('1m').addEventListener('click', () => setTimeRange('1m'));

        // Generate initial random data
        function generateInitialData() {
            const now = new Date();
            const timePoints = generateTimePoints(now, config.timeRange);
            return stocks.map(stock => ({
                symbol: stock,
                values: timePoints.map(time => ({
                    time: time,
                    price: getRandomPrice(stock)
                }))
            }));
        }

        // Update data with new values
        function updateData() {
            const now = new Date();
            const timePoints = generateTimePoints(now, config.timeRange);

            data.forEach(stock => {
                // Keep only the most recent time points
                const existingTimes = stock.values.map(v => v.time);
                const newTimes = timePoints.filter(t => !existingTimes.includes(t));

                // Add new data points
                newTimes.forEach(time => {
                    stock.values.push({
                        time: time,
                        price: getRandomPrice(stock.symbol)
                    });
                });

                // Remove old data points if we've exceeded the time range
                const minTime = getMinTime(now, config.timeRange);
                stock.values = stock.values.filter(v => v.time >= minTime);
            });
        }

        // Generate time points based on time range
        function generateTimePoints(now, timeRange) {
            const points = [];
            const interval = getTimeInterval(timeRange);

            // Start from the earliest time in the range
            let current = getMinTime(now, timeRange);

            while (current <= now) {
                points.push(new Date(current));
                current = new Date(current.getTime() + interval);
            }

            return points;
        }

        // Get minimum time based on time range
        function getMinTime(now, timeRange) {
            const hours = {
                '1h': 1,
                '4h': 4,
                '1d': 24,
                '1w': 24 * 7,
                '1m': 24 * 30
            }[timeRange] || 24;

            return new Date(now.getTime() - hours * 60 * 60 * 1000);
        }

        // Get time interval based on time range
        function getTimeInterval(timeRange) {
            const intervals = {
                '1h': 5 * 60 * 1000,    // 5 minutes
                '4h': 15 * 60 * 1000,   // 15 minutes
                '1d': 60 * 60 * 1000,    // 1 hour
                '1w': 4 * 60 * 60 * 1000, // 4 hours
                '1m': 24 * 60 * 60 * 1000  // 1 day
            };

            return intervals[timeRange] || 60 * 60 * 1000;
        }

        // Get random price (simulating stock price changes)
        function getRandomPrice(symbol) {
            // Different base prices for different stocks
            const basePrices = {
                'AAPL': 150,
                'MSFT': 300,
                'GOOGL': 2800,
                'AMZN': 3300,
                'FB': 350,
                'TSLA': 700,
                'NVDA': 500,
                'JPM': 150,
                'V': 220,
                'PG': 140
            };

            const base = basePrices[symbol] || 100;
            const volatility = 0.02; // 2% volatility

            // Simulate price movement
            const change = (Math.random() - 0.5) * volatility * base;
            return Math.max(0.01, base + change);
        }

        // Set time range and regenerate data
        function setTimeRange(range) {
            config.timeRange = range;
            data = generateInitialData();
            heatmap.update(data);
        }

        // Heatmap class
        class Heatmap {
            constructor(container, data, config) {
                this.container = container;
                this.data = data;
                this.config = config;
                this.svg = null;
                this.xScale = null;
                this.yScale = null;
                this.colorScale = null;
                this.tooltip = document.getElementById('tooltip');

                this.init();
            }

            init() {
                // Clear previous content
                d3.select(this.container).html('');

                // Create SVG
                this.svg = d3.select(this.container)
                    .append('svg')
                    .attr('width', this.config.width)
                    .attr('height', this.config.height);

                // Set up scales
                this.updateScales();

                // Add zoom behavior
                this.zoom = d3.zoom()
                    .scaleExtent([1, 10])
                    .on('zoom', (event) => this.zoomed(event));

                this.svg.call(this.zoom);

                // Draw the heatmap
                this.draw();
            }

            updateScales() {
                // Get all time points across all stocks
                const allTimes = this.data.flatMap(stock =>
                    stock.values.map(v => v.time)
                ).sort((a, b) => a - b);

                // Get min and max prices
                const allPrices = this.data.flatMap(stock =>
                    stock.values.map(v => v.price)
                );
                const minPrice = d3.min(allPrices);
                const maxPrice = d3.max(allPrices);

                // Set up scales
                this.xScale = d3.scaleTime()
                    .domain(d3.extent(allTimes))
                    .range([this.config.margin.left, this.config.width - this.config.margin.right]);

                this.yScale = d3.scaleBand()
                    .domain(this.data.map(d => d.symbol))
                    .range([this.config.height - this.config.margin.bottom, this.config.margin.top])
                    .padding(0.1);

                this.colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
                    .domain([minPrice, maxPrice]);
            }

            draw() {
                // Clear previous content
                this.svg.selectAll('*').remove();

                // Add X axis
                this.svg.append('g')
                    .attr('transform', `translate(0,${this.config.height - this.config.margin.bottom})`)
                    .call(d3.axisBottom(this.xScale));

                // Add Y axis
                this.svg.append('g')
                    .attr('transform', `translate(${this.config.margin.left},0)`)
                    .call(d3.axisLeft(this.yScale));

                // Add grid lines
                this.svg.append('g')
                    .attr('class', 'grid')
                    .attr('transform', `translate(0,${this.config.height - this.config.margin.bottom})`)
                    .call(d3.axisBottom(this.xScale)
                        .tickSize(-(this.config.height - this.config.margin.top - this.config.margin.bottom))
                        .tickFormat(''));

                this.svg.append('g')
                    .attr('class', 'grid')
                    .attr('transform', `translate(${this.config.margin.left},0)`)
                    .call(d3.axisLeft(this.yScale)
                        .tickSize(-(this.config.width - this.config.margin.left - this.config.margin.right))
                        .tickFormat(''));

                // Add cells
                const cells = this.svg.selectAll('.cell')
                    .data(this.data)
                    .enter()
                    .append('g')
                    .attr('class', 'cell')
                    .attr('transform', d => `translate(0,${this.yScale(d.symbol)})`);

                cells.selectAll('rect')
                    .data(d => d.values)
                    .enter()
                    .append('rect')
                    .attr('x', d => this.xScale(d.time))
                    .attr('y', 0)
                    .attr('width', (d, i, nodes) => {
                        const nextTime = i < nodes.length - 1 ?
                            this.data[0].values[i+1].time :
                            new Date(this.xScale.domain()[1]);
                        return this.xScale(nextTime) - this.xScale(d.time);
                    })
                    .attr('height', this.yScale.bandwidth())
                    .attr('fill', d => this.colorScale(d.price))
                    .on('mouseover', (event, d) => {
                        this.tooltip.style('display', 'block');
                        this.tooltip.innerHTML = `
                            <strong>${d.time.toLocaleString()}</strong><br>
                            Price: $${d.price.toFixed(2)}
                        `;
                    })
                    .on('mousemove', (event) => {
                        this.tooltip.style('left', `${event.pageX + 10}px`);
                        this.tooltip.style('top', `${event.pageY + 10}px`);
                    })
                    .on('mouseout', () => {
                        this.tooltip.style('display', 'none');
                    });

                // Add color legend
                const legendWidth = 200;
                const legendHeight = 20;
                const legend = this.svg.append('g')
                    .attr('transform', `translate(${this.config.width - this.config.margin.right - legendWidth},${this.config.margin.top})`);

                legend.append('rect')
                    .attr('width', legendWidth)
                    .attr('height', legendHeight)
                    .style('fill', 'url(#legend-gradient)');

                legend.append('text')
                    .attr('x', 0)
                    .attr('y', -5)
                    .text(`Price: $${this.colorScale.domain()[0].toFixed(2)}`);

                legend.append('text')
                    .attr('x', legendWidth)
                    .attr('y', -5)
                    .attr('text-anchor', 'end')
                    .text(`$${this.colorScale.domain()[1].toFixed(2)}`);

                // Create gradient for legend
                const defs = this.svg.append('defs');
                const gradient = defs.append('linearGradient')
                    .attr('id', 'legend-gradient')
                    .attr('x1', '0%')
                    .attr('y1', '0%')
                    .attr('x2', '100%')
                    .attr('y2', '0%');

                gradient.append('stop')
                    .attr('offset', '0%')
                    .attr('stop-color', this.colorScale(this.colorScale.domain()[0]));

                gradient.append('stop')
                    .attr('offset', '100%')
                    .attr('stop-color', this.colorScale(this.colorScale.domain()[1]));
            }

            update(newData) {
                this.data = newData;
                this.updateScales();
                this.draw();
            }

            zoomed(event) {
                const transform = event.transform;

                // Apply the zoom to the x-axis
                const newXScale = transform.rescaleX(this.xScale);

                // Update the x-axis
                this.svg.selectAll('g').remove();

                // Add X axis
                this.svg.append('g')
                    .attr('transform', `translate(0,${this.config.height - this.config.margin.bottom})`)
                    .call(d3.axisBottom(newXScale));

                // Add Y axis
                this.svg.append('g')
                    .attr('transform', `translate(${this.config.margin.left},0)`)
                    .call(d3.axisLeft(this.yScale));

                // Update cells
                this.svg.selectAll('.cell')
                    .selectAll('rect')
                    .attr('x', d => newXScale(d.time))
                    .attr('width', (d, i, nodes) => {
                        const nextTime = i < nodes.length - 1 ?
                            this.data[0].values[i+1].time :
                            new Date(newXScale.domain()[1]);
                        return newXScale(nextTime) - newXScale(d.time);
                    });
            }
        }
    </script>
</body>
</html>
