            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            colors: ["#d73027", "#f46d43", "#fdae61", "#fee090", "#ffffbf", "#e0f3f8", "#abd9e9", "#74add1", "#4575b4"],
            updateInterval: 5000 // 5 seconds
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "NVDA", "JPM", "V", "WMT"];
        let currentData = generateMockData();

        // Initialize the visualization
        const svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        // Scales
        const xScale = d3.scaleBand()
            .range([0, config.width - config.margin.left - config.margin.right]);

        const yScale = d3.scaleBand()
            .range([0, config.height - config.margin.top - config.margin.bottom]);

        const colorScale = d3.scaleQuantile()
            .range(config.colors);

        // Axes
        const xAxis = g.append("g")
            .attr("class", "axis axis--x")
            .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`);

        const yAxis = g.append("g")
            .attr("class", "axis axis--y");

        // Tooltip
        const tooltip = d3.select("#tooltip");

        // Zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", zoomed);

        svg.call(zoom);

        // Initial render
        updateHeatmap();

        // Set up periodic updates
        setInterval(() => {
            currentData = generateMockData();
            updateHeatmap();
        }, config.updateInterval);

        // Event listeners
        d3.select("#reset-btn").on("click", resetZoom);
        d3.select("#time-range").on("change", function() {
            // In a real app, this would fetch new data based on the selected range
            currentData = generateMockData();
            updateHeatmap();
        });

        // Functions
        function updateHeatmap() {
            // Prepare data for heatmap
            const data = [];
            stocks.forEach(stock => {
                currentData[stock].forEach((price, i) => {
                    data.push({
                        stock: stock,
                        time: currentData.times[i],
                        price: price
                    });
                });
            });

            // Update scales
            xScale.domain(currentData.times);
            yScale.domain(stocks);
            colorScale.domain(d3.extent(data, d => d.price));

            // Update axes
            xAxis.call(d3.axisBottom(xScale)
                .tickFormat(d => d3.timeFormat("%H:%M")(new Date(d)))
                .tickSizeOuter(0))
                .selectAll("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            yAxis.call(d3.axisLeft(yScale)
                .tickSizeOuter(0))
                .selectAll("text")
                .attr("class", "axis-label");

            // Draw heatmap cells
            const cells = g.selectAll(".cell")
                .data(data, d => `${d.stock}-${d.time}`);

            cells.enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    tooltip.style("opacity", 1)
                        .html(`<strong>${d.stock}</strong><br>Time: ${d3.timeFormat("%Y-%m-%d %H:%M")(new Date(d.time))}<br>Price: $${d.price.toFixed(2)}`);
                })
                .on("mousemove", function(event) {
                    tooltip.style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("opacity", 0);
                })
                .merge(cells)
                .transition()
                .duration(500)
                .attr("fill", d => colorScale(d.price));

            cells.exit().remove();
        }

        function zoomed(event) {
            const { transform } = event;
            g.attr("transform", `translate(${config.margin.left + transform.x},${config.margin.top + transform.y}) scale(${transform.k})`);
        }

        function resetZoom() {
            svg.transition()
                .duration(750)
                .call(zoom.transform, d3.zoomIdentity);
        }

        function generateMockData() {
            const now = new Date();
            const data = { times: [] };
            const timeRange = d3.select("#time-range").property("value");

            // Generate time points based on selected range
            let timePoints;
            switch(timeRange) {
                case "1d":
                    timePoints = 24; // 1 hour intervals
                    break;
                case "1w":
                    timePoints = 168; // 1 hour intervals
                    break;
                case "1m":
                    timePoints = 30; // 1 day intervals
                    break;
                case "3m":
                    timePoints = 90; // 1 day intervals
                    break;
                case "1y":
                    timePoints = 365; // 1 day intervals
                    break;
                default:
                    timePoints = 30;
            }

            // Generate time points
            for (let i = 0; i < timePoints; i++) {
                const time = new Date(now);
                switch(timeRange) {
                    case "1d":
                        time.setHours(now.getHours() - (timePoints - i - 1));
                        break;
                    case "1w":
                        time.setHours(now.getHours() - (timePoints - i - 1));
                        break;
                    case "1m":
                        time.setDate(now.getDate() - (timePoints - i - 1));
                        break;
                    case "3m":
                        time.setDate(now.getDate() - (timePoints - i - 1));
                        break;
                    case "1y":
                        time.setDate(now.getDate() - (timePoints - i - 1));
                        break;
                }
                data.times.push(time.toISOString());
            }

            // Generate random prices for each stock
            stocks.forEach(stock => {
                data[stock] = [];
                const basePrice = 100 + Math.random() * 200;
                for (let i = 0; i < timePoints; i++) {
                    // Simulate some volatility
                    const volatility = 0.02 + Math.random() * 0.05;
                    const change = (Math.random() - 0.5) * volatility * basePrice;
                    const price = basePrice + change;
                    data[stock].push(price);
                }
            });

            return data;
        }
    </script>
</body>
</html>
```

