                .domain(stocks)
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.05);

            // Create color scale
            const colorScale = d3.scaleLinear()
                .domain([d3.min(stockData, d => d.price), d3.max(stockData, d => d.price)])
                .range(["#ff0000", "#00ff00"]); // Red to green

