                .attr("class", "y-label")
                .attr("transform", "rotate(-90)")
                .attr("x", - (config.height - config.margin.top - config.margin.bottom) / 2)
                .attr("y", -40)
                .style("text-anchor", "middle")
                .text("Stock Symbol");
        }

        // Generate mock data for demonstration
        function generateMockData(range = "1d") {
            const stocks = ["AAPL", "MSFT", "GOOGL", "AMZN", "FB", "TSLA", "NVDA", "PYPL", "ADBE", "INTC"];
            const now = new Date();
            const data = [];

            // Determine time range
            let timeStep, numPoints;
            switch(range) {
                case "1d":
                    timeStep = 30 * 60 * 1000; // 30 minutes
                    numPoints = 48;
                    break;
                case "1w":
                    timeStep = 2 * 60 * 60 * 1000; // 2 hours
                    numPoints = 84;
                    break;
                case "1m":
                    timeStep = 6 * 60 * 60 * 1000; // 6 hours
                    numPoints = 60;
                    break;
                case "3m":
                    timeStep = 12 * 60 * 60 * 1000; // 12 hours
                    numPoints = 90;
                    break;
                case "1y":
                    timeStep = 24 * 60 * 60 * 1000; // 1 day
                    numPoints = 365;
                    break;
                default:
                    timeStep = 30 * 60 * 1000;
                    numPoints = 48;
            }

            // Generate data points
            for (let i = 0; i < numPoints; i++) {
                const time = new Date(now.getTime() - (numPoints - i) * timeStep);
                stocks.forEach(stock => {
                    // Generate a random price with some trend
                    const basePrice = 100 + Math.random() * 200;
                    const trend = Math.sin(i * 0.1) * 20;
                    const noise = (Math.random() - 0.5) * 10;
                    const price = basePrice + trend + noise;

                    data.push({
                        stock,
                        time: time.toISOString(),
                        price: Math.max(0, price) // Ensure price is positive
                    });
                });
            }

            return data;
        }

        // Simulate data updates (in a real app, this would come from an API)
        function updateData() {
            // For demo purposes, we'll just modify some random data points
            const numUpdates = Math.floor(Math.random() * 5) + 1;

            for (let i = 0; i < numUpdates; i++) {
                const randomIndex = Math.floor(Math.random() * stockData.length);
                const change = (Math.random() - 0.5) * 5; // Random change between -2.5 and +2.5
                stockData[randomIndex].price = Math.max(0, stockData[randomIndex].price + change);
            }
        }

