            padding: 8px;
            border-radius: 4px;
            border: 1px solid #ddd;
        }
        .update-btn {
            padding: 8px 16px;
            background-color: #4CAF50;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        .update-btn:hover {
            background-color: #45a049;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>

        <div class="controls">
            <div>
                <label for="stock-selector">Select Stocks:</label>
                <select id="stock-selector" class="stock-selector" multiple>
                    <option value="AAPL" selected>AAPL</option>
                    <option value="MSFT" selected>MSFT</option>
                    <option value="GOOGL" selected>GOOGL</option>
                    <option value="AMZN" selected>AMZN</option>
                    <option value="TSLA">TSLA</option>
                    <option value="FB">FB</option>
                </select>
            </div>

            <div>
                <label for="time-range">Time Range:</label>
                <select id="time-range" class="time-range">
                    <option value="1d">1 Day</option>
                    <option value="1w" selected>1 Week</option>
                    <option value="1m">1 Month</option>
                    <option value="3m">3 Months</option>
                    <option value="1y">1 Year</option>
                </select>
            </div>

            <button id="update-btn" class="update-btn">Update Data</button>
        </div>

        <div id="heatmap"></div>
    </div>

    <script>
        // Mock data generator for demonstration
        function generateMockData(stocks, timeRange) {
            const now = new Date();
            const points = {
                '1d': 24 * 60, // 1 minute intervals for 1 day
                '1w': 7 * 24,  // 1 hour intervals for 1 week
                '1m': 30,      // 1 day intervals for 1 month
                '3m': 90,      // 1 day intervals for 3 months
                '1y': 12       // 1 month intervals for 1 year
            }[timeRange] || 30;

            const data = [];
            const times = [];

            // Generate time labels
            for (let i = 0; i < points; i++) {
                const date = new Date(now);
                if (timeRange === '1d') {
                    date.setMinutes(now.getMinutes() - i);
                } else if (timeRange === '1w') {
                    date.setHours(now.getHours() - i);
                } else if (timeRange === '1m' || timeRange === '3m') {
                    date.setDate(now.getDate() - i);
                } else if (timeRange === '1y') {
                    date.setMonth(now.getMonth() - i);
                }
                times.unshift(date.toLocaleString());
            }

            // Generate random price data for each stock
            stocks.forEach(stock => {
                const prices = [];
                let lastPrice = 100 + Math.random() * 200; // Random starting price

                for (let i = 0; i < points; i++) {
                    // Simulate price movement
                    lastPrice *= 1 + (Math.random() - 0.5) * 0.02;
                    prices.push(lastPrice.toFixed(2));
                }

                data.push({
                    z: [prices],
                    x: times,
                    y: [stock],
                    type: 'heatmap',
                    name: stock,
                    colorscale: 'Portland',
                    showscale: true
                });
            });

            return data;
        }

        // Initialize the heatmap
        function initHeatmap() {
            const stockSelector = document.getElementById('stock-selector');
            const timeRange = document.getElementById('time-range');
            const updateBtn = document.getElementById('update-btn');

            // Initial data
            const selectedStocks = Array.from(stockSelector.selectedOptions).map(opt => opt.value);
            const selectedTimeRange = timeRange.value;
            let data = generateMockData(selectedStocks, selectedTimeRange);

            // Create layout
            const layout = {
                title: 'Stock Price Heatmap',
                xaxis: { title: 'Time' },
                yaxis: { title: 'Stock' },
                margin: { t: 50, l: 100 },
                hovermode: 'closest'
            };

            // Create the plot
            Plotly.newPlot('heatmap', data, layout);

            // Update button click handler
            updateBtn.addEventListener('click', () => {
                const newStocks = Array.from(stockSelector.selectedOptions).map(opt => opt.value);
                const newTimeRange = timeRange.value;
                const newData = generateMockData(newStocks, newTimeRange);

                Plotly.react('heatmap', newData, layout);
            });

            // Simulate real-time updates every 5 seconds
            setInterval(() => {
                const currentStocks = Array.from(stockSelector.selectedOptions).map(opt => opt.value);
                const currentTimeRange = timeRange.value;
                const updatedData = generateMockData(currentStocks, currentTimeRange);

                // Update the plot
                Plotly.react('heatmap', updatedData, layout);
            }, 5000);
        }

        // Initialize when the page loads
        document.addEventListener('DOMContentLoaded', initHeatmap);
    </script>
</body>
</html>
```

