            numDays: 50,
            updateInterval: 3000 // 3 seconds
        };

        // Generate random stock data
        function generateStockData() {
            const stocks = [];
            const baseDate = new Date();
            baseDate.setDate(baseDate.getDate() - config.numDays);

            for (let i = 0; i < config.numStocks; i++) {
                const stock = {
                    symbol: `STOCK${String.fromCharCode(65 + i)}`,
                    prices: []
                };

                let lastPrice = 100 + Math.random() * 50;

                for (let j = 0; j < config.numDays; j++) {
                    // Simulate price movement
                    lastPrice *= 1 + (Math.random() - 0.5) * 0.05;
                    stock.prices.push({
                        date: new Date(baseDate.getTime() + j * 24 * 60 * 60 * 1000),
                        price: Math.max(1, lastPrice.toFixed(2))
                    });
