                svg.transition().call(zoom.transform, d3.zoomIdentity);
            });

            // Update function
            function update(data) {
                // Set domains
                const dates = data[0].prices.map(d => d.date);
                const stocks = data.map(d => d.symbol);

                xScale.domain(dates);
                yScale.domain(stocks);

                // Create axes
                const xAxis = d3.axisBottom(xScale)
                    .tickFormat(d3.timeFormat("%b %d"))
                    .tickSizeOuter(0);

                const yAxis = d3.axisLeft(yScale)
                    .tickSizeOuter(0);

                // Remove old axes
                svg.selectAll(".axis-x, .axis-y").remove();

                // Add x-axis
                svg.append("g")
                    .attr("class", "axis-x")
                    .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                    .call(xAxis)
                    .selectAll("text")
                    .attr("class", "axis-label")
                    .attr("transform", "rotate(-45)")
                    .style("text-anchor", "end");

                // Add y-axis
                svg.append("g")
                    .attr("class", "axis-y")
                    .attr("transform", `translate(${config.margin.left}, 0)`)
                    .call(yAxis)
                    .selectAll("text")
                    .attr("class", "axis-label");

                // Remove old cells
                svg.selectAll(".heatmap-cell").remove();

                // Add heatmap cells
                const cells = svg.selectAll(".heatmap-cell")
                    .data(data.flatMap(stock =>
                        stock.prices.map(price => ({
                            stock: stock.symbol,
                            date: price.date,
                            price: price.price
                        }))
                    ))
                    .enter()
                    .append("rect")
                    .attr("class", "heatmap-cell")
                    .attr("x", d => xScale(d.date))
                    .attr("y", d => yScale(d.stock))
                    .attr("width", xScale.bandwidth())
                    .attr("height", yScale.bandwidth())
                    .attr("fill", d => colorScale(d.price))
                    .on("mouseover", (event, d) => {
                        tooltip.transition()
                            .duration(200)
                            .style("opacity", .9);
                        tooltip.html(`<strong>${d.stock}</strong><br>${d3.timeFormat("%b %d")(d.date)}<br>Price: $${d.price}`)
                            .style("left", (event.pageX + 10) + "px")
                            .style("top", (event.pageY - 28) + "px");
                    })
                    .on("mouseout", () => {
                        tooltip.transition()
                            .duration(500)
                            .style("opacity", 0);
                    });
            }

            // Initial data load
            let stockData = generateStockData();
            update(stockData);

            // Set up real-time updates
            setInterval(() => {
                // Update prices slightly
                stockData = stockData.map(stock => {
                    const newPrices = stock.prices.map((price, i) => {
                        // Only update the last few days to simulate real-time
