                            };
                        }
                        return price;
                    });
                    return { ...stock, prices: newPrices };
                });

                update(stockData);
            }, config.updateInterval);
        }

        // Initialize when DOM is loaded
        document.addEventListener("DOMContentLoaded", initHeatmap);
    </script>
