    <script>
        // Configuration
        const config = {
            updateInterval: 5000, // 5 seconds
            timeWindow: 24, // hours
            timeResolution: 15, // minutes
            symbols: ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA']
        };

        // State
        let currentSymbol = 'AAPL';
        let priceData = {};
        let updateInterval;

        // Initialize
        document.addEventListener('DOMContentLoaded', () => {
            // Set up symbol selector
