        // Generate initial data for a symbol
        function generateInitialData(symbol) {
            const now = new Date();
            const startTime = new Date(now.getTime() - config.timeWindow * 60 * 60 * 1000);

            // Generate data points at timeResolution intervals
            const dataPoints = Math.floor(config.timeWindow * 60 / config.timeResolution);

            for (let i = 0; i < dataPoints; i++) {
                const timestamp = new Date(startTime.getTime() + i * config.timeResolution * 60 * 1000);
                const price = generateRandomPrice(symbol);

                priceData[symbol].timestamps.push(timestamp);
                priceData[symbol].prices.push(price);
            }
