            // Remove oldest data point
            priceData[symbol].timestamps.shift();
            priceData[symbol].prices.shift();

            // Add new data point
            const now = new Date();
            const price = generateRandomPrice(symbol);

            priceData[symbol].timestamps.push(now);
            priceData[symbol].prices.push(price);
