            for (let i = 0; i < prices.length; i++) {
                const row = [];
                for (let j = 0; j < prices.length; j++) {
                    // Simple difference metric (can be enhanced)
                    const diff = Math.abs(prices[i] - prices[j]);
                    row.push(diff);
                }
                zValues.push(row);
            }

            const data = [{
                z: zValues,
                x: xValues,
                y: xValues,
                type: 'heatmap',
                colorscale: 'Viridis',
                hoverongaps: false,
                colorbar: {
                    title: 'Price Difference'
                }
            }];

            const layout = {
                title: `${currentSymbol} Stock Price Heatmap`,
                xaxis: {
                    title: 'Time'
                },
                yaxis: {
                    title: 'Time',
                    autorange: 'reversed' // Show most recent at bottom
                },
                margin: {
                    l: 60,
                    r: 20,
                    b: 60,
                    t: 50
                }
            };

            Plotly.newPlot('heatmap', data, layout);
        }
    </script>
</body>
</html>
```

