        </div>
        <div class="legend" id="legend"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            cellSize: 20,
            colors: ["#006837", "#1a9850", "#66bd63", "#a6d96a", "#d9ef8b", "#ffffbf", "#fee08b", "#fdae61", "#f46d43", "#d73027", "#a50026"]
        };

        // Initialize chart
        const svg = d3.select(".chart-container")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        const tooltip = d3.select(".tooltip");

        // Color scale
        const colorScale = d3.scaleQuantile()
            .range(config.colors);

        // Zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([0.5, 10])
            .on("zoom", zoomed);

        svg.call(zoom);

        function zoomed(event) {
            g.attr("transform", event.transform);
        }

        // Generate mock data (in a real app, you would fetch from an API)
        function generateMockData(symbol, timeframe) {
            const now = new Date();
            const data = [];
            const days = {
                '1d': 1,
                '1w': 7,
                '1m': 30,
                '3m': 90,
                '1y': 365
            }[timeframe];

            const startDate = new Date(now);
            startDate.setDate(now.getDate() - days);

            // Generate dates
            const dates = [];
            for (let d = new Date(startDate); d <= now; d.setDate(d.getDate() + 1)) {
                dates.push(new Date(d));
            }

            // Generate times (9:30am to 4:00pm EST)
            const times = [];
            for (let h = 9; h <= 16; h++) {
                for (let m = 0; m < 60; m += 30) {
                    times.push(`${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`);
                }
            }

            // Generate random prices
            let lastPrice = 100 + Math.random() * 100;
            for (const date of dates) {
                for (const time of times) {
                    // Simulate price movement
                    lastPrice += (Math.random() - 0.5) * 2;
                    lastPrice = Math.max(1, lastPrice); // Ensure price doesn't go negative

                    data.push({
                        date: date.toISOString().split('T')[0],
                        time: time,
                        price: parseFloat(lastPrice.toFixed(2)),
                        symbol: symbol
                    });
                }
            }

            return data;
        }

        // Update chart with new data
        function updateChart(data) {
            // Clear previous chart
            g.selectAll("*").remove();

            if (data.length === 0) return;

            // Extract unique dates and times
            const dates = [...new Set(data.map(d => d.date))];
            const times = [...new Set(data.map(d => d.time))];

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(dates)
                .range([0, config.width - config.margin.left - config.margin.right])
                .padding(0.01);

            const yScale = d3.scaleBand()
                .domain(times)
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.01);

            // Set color domain based on price range
            const prices = data.map(d => d.price);
            colorScale.domain([d3.min(prices), d3.max(prices)]);

            // Create heatmap cells
            g.selectAll(".cell")
                .data(data)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(d.time))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    tooltip.style("visibility", "visible")
                        .html(`<strong>${d.symbol}</strong><br>
                              Date: ${d.date}<br>
                              Time: ${d.time}<br>
                              Price: $${d.price.toFixed(2)}`);
                })
                .on("mousemove", function(event) {
                    tooltip.style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                });

            // Add axes
            g.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
                .call(d3.axisBottom(xScale).tickValues(xScale.domain().filter((d, i) => i % 5 === 0)))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            g.append("g")
                .attr("class", "axis axis--y")
                .call(d3.axisLeft(yScale));

            // Add axis labels
            g.append("text")
                .attr("class", "axis-label")
                .attr("x", (config.width - config.margin.left - config.margin.right) / 2)
                .attr("y", config.height - config.margin.top - config.margin.bottom + 40)
                .style("text-anchor", "middle")
                .text("Date");

            g.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("y", -50)
                .attr("x", -(config.height - config.margin.top - config.margin.bottom) / 2)
                .style("text-anchor", "middle")
                .text("Time");

            // Update legend
            updateLegend();
        }

        // Update legend
        function updateLegend() {
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendItems = colorScale.quantiles().map((q, i) => ({
                color: config.colors[i],
                range: i === 0
                    ? `${colorScale.domain()[0].toFixed(2)} - ${q.toFixed(2)}`
                    : `${colorScale.quantiles()[i-1].toFixed(2)} - ${q.toFixed(2)}`
            }));

            // Add the last range
            legendItems.push({
                color: config.colors[config.colors.length - 1],
                range: `${colorScale.quantiles()[colorScale.quantiles().length - 1].toFixed(2)} - ${colorScale.domain()[1].toFixed(2)}`
            });

            legend.selectAll(".legend-item")
                .data(legendItems)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.range}</span>
                `);
        }

        // Initial load
        function loadData() {
            const symbol = d3.select("#symbol").property("value");
            const timeframe = d3.select("#timeframe").property("value");

            // In a real app, you would fetch data from an API like:
            // fetch(`/api/stock-data?symbol=${symbol}&timeframe=${timeframe}`)
            //     .then(response => response.json())
            //     .then(data => updateChart(data));

            // For this demo, we'll use mock data
            const data = generateMockData(symbol, timeframe);
            updateChart(data);
        }

        // Event listeners
        d3.select("#update").on("click", loadData);
        d3.select("#symbol").on("change", loadData);
        d3.select("#timeframe").on("change", loadData);

        // Initial load
        loadData();

        // Simulate real-time updates (every 5 seconds)
        setInterval(() => {
            loadData();
        }, 5000);
    </script>
</body>
</html>
