                            data.push({
                                date: date.toISOString().split('T')[0],
                                hour: h,
                                price: price,
                                volume: volume
                            });
                        }
                    }

                    resolve(data);
                }, 300); // Simulate network delay
            });
        }

        // Helper to get number of days for timeframe
        function getDaysForTimeframe(timeframe) {
            switch(timeframe) {
                case '1d': return 1;
                case '1w': return 7;
                case '1m': return 30;
                case '3m': return 90;
                case '1y': return 365;
                default: return 30;
