                    return `${date.getMonth()+1}/${date.getDate()}`;
                });

            const yAxis = d3.axisLeft(yScale)
                .tickFormat(d => `${d}:00`);

            g.append("g")
                .attr("class", "x axis")
                .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .style("text-anchor", "end")
                .attr("dx", "-.8em")
                .attr("dy", ".15em")
                .attr("transform", "rotate(-45)");

            g.append("g")
                .attr("class", "y axis")
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add axis labels
            g.append("text")
                .attr("class", "axis-label")
                .attr("x", (config.width - config.margin.left - config.margin.right) / 2)
                .attr("y", config.height - config.margin.top - config.margin.bottom + 40)
                .style("text-anchor", "middle")
                .text("Date");

            g.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("y", -50)
                .attr("x", -(config.height - config.margin.top - config.margin.bottom) / 2)
                .style("text-anchor", "middle")
                .text("Hour of Day");

            // Add color legend
            const legendWidth = 200;
            const legendHeight = 20;
            const legend = g.append("g")
                .attr("transform", `translate(${(config.width - config.margin.left - config.margin.right - legendWidth) / 2}, ${config.height - config.margin.top - config.margin.bottom + 60})`);

