<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>
        <div class="controls">
            <div>
                <button id="reset-btn">Reset Zoom</button>
                <button id="update-btn">Update Data</button>
            </div>
            <div class="legend">
                <div class="legend-item">
                    <div class="legend-color" style="background-color: #d73027;"></div>
                    <span>Low</span>
                </div>
                <div class="legend-item">
                    <div class="legend-color" style="background-color: #f46d43;"></div>
                    <span>Medium</span>
                </div>
                <div class="legend-item">
                    <div class="legend-color" style="background-color: #fee090;"></div>
                    <span>High</span>
                </div>
            </div>
        </div>
        <div id="heatmap-container"></div>
        <div class="tooltip" id="tooltip"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            numStocks: 20,
            numDays: 30,
            updateInterval: 5000 // 5 seconds
        };

        // Generate mock stock data
        function generateStockData() {
            const stocks = [];
            const stockNames = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT',
                               'PG', 'DIS', 'KO', 'BA', 'XOM', 'JNJ', 'PFE', 'VZ', 'INTC', 'CSCO'];

            for (let i = 0; i < config.numStocks; i++) {
                const stock = {
                    name: stockNames[i],
                    prices: []
                };

                // Generate random prices for each day
                let basePrice = 100 + Math.random() * 200;
                for (let j = 0; j < config.numDays; j++) {
                    // Simulate some trend with random fluctuations
                    basePrice *= 1 + (Math.random() - 0.5) * 0.02;
                    stock.prices.push(basePrice.toFixed(2));
                }

                stocks.push(stock);
            }

            return stocks;
        }

        // Initialize the heatmap
        function initHeatmap() {
            // Clear previous content
            d3.select("#heatmap-container").html("");

            // Create SVG
            const svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create tooltip
            const tooltip = d3.select("#tooltip");

            // Generate data
            const stockData = generateStockData();

            // Set up scales
            const xScale = d3.scaleBand()
                .domain(d3.range(config.numDays))
                .range([config.margin.left, config.width - config.margin.right])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(stockData.map(d => d.name))
                .range([config.margin.top, config.height - config.margin.bottom])
                .padding(0.05);

            // Find min and max prices for color scale
            const allPrices = stockData.flatMap(d => d.prices);
            const minPrice = Math.min(...allPrices);
            const maxPrice = Math.max(...allPrices);

            const colorScale = d3.scaleLinear()
                .domain([minPrice, (minPrice + maxPrice) / 2, maxPrice])
                .range(["#d73027", "#fee090", "#1a9850"]);

            // Create zoom behavior
            const zoom = d3.zoom()
                .scaleExtent([1, 10])
                .on("zoom", (event) => {
                    const { transform } = event;
                    svg.selectAll(".heatmap-cell")
                        .attr("transform", transform);
                    svg.selectAll(".x-axis")
                        .call(xAxis.scale(transform.rescaleX(xScale)));
                    svg.selectAll(".y-axis")
                        .call(yAxis.scale(transform.rescaleY(yScale)));
                });

            svg.call(zoom);

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d => `Day ${d + 1}`)
                .tickSizeOuter(0);

            const yAxis = d3.axisLeft(yScale)
                .tickSizeOuter(0);

            svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(0, ${config.height - config.margin.bottom})`)
                .call(xAxis)
                .selectAll("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            svg.append("g")
                .attr("class", "y-axis")
                .attr("transform", `translate(${config.margin.left}, 0)`)
                .call(yAxis)
                .selectAll("text")
                .attr("class", "axis-label");

            // Add heatmap cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(stockData)
                .enter()
                .append("g")
                .attr("class", "heatmap-cell")
                .selectAll("rect")
                .data(d => d.prices.map((price, i) => ({
                    stock: d.name,
                    day: i,
                    price: parseFloat(price)
                })))
                .enter()
                .append("rect")
                .attr("x", d => xScale(d.day))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    tooltip.style("visibility", "visible")
                        .html(`<strong>${d.stock}</strong><br>Day ${d.day + 1}: $${d.price.toFixed(2)}`);
                })
                .on("mousemove", function(event) {
                    tooltip.style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                });

            // Add reset button functionality
            d3.select("#reset-btn").on("click", () => {
                svg.transition()
                    .duration(750)
                    .call(zoom.transform, d3.zoomIdentity);
            });

            // Add update button functionality
            d3.select("#update-btn").on("click", () => {
                updateHeatmap();
            });

            // Set up automatic updates
            setInterval(updateHeatmap, config.updateInterval);

            // Store references for updates
            svg.node().heatmapData = {
                stockData,
                xScale,
                yScale,
                colorScale,
                cells
            };
        }

        // Update the heatmap with new data
        function updateHeatmap() {
            const svg = d3.select("#heatmap-container svg");
            if (!svg.node()) return;

            const data = svg.node().heatmapData;
            if (!data) return;

            // Generate new data
            const newStockData = generateStockData();

            // Update the data references
            data.stockData = newStockData;

            // Find new min and max prices
            const allPrices = newStockData.flatMap(d => d.prices);
            const minPrice = Math.min(...allPrices);
            const maxPrice = Math.max(...allPrices);

            // Update color scale
            data.colorScale.domain([minPrice, (minPrice + maxPrice) / 2, maxPrice]);

            // Update y-axis domain
            data.yScale.domain(newStockData.map(d => d.name));

            // Update cells
            const cells = svg.selectAll(".heatmap-cell")
                .data(newStockData)
                .selectAll("rect")
                .data(d => d.prices.map((price, i) => ({
                    stock: d.name,
                    day: i,
                    price: parseFloat(price)
                })));

            // Update existing cells
            cells.transition()
                .duration(500)
                .attr("fill", d => data.colorScale(d.price));

            // Update axes
            svg.select(".x-axis").call(d3.axisBottom(data.xScale).tickFormat(d => `Day ${d + 1}`));
            svg.select(".y-axis").call(d3.axisLeft(data.yScale));
        }

        // Initialize the heatmap when the page loads
        document.addEventListener("DOMContentLoaded", initHeatmap);
    </script>
</body>
</html>
```

