<body>
    <div class="container">
        <h1>Stock Price Heatmap</h1>

        <div class="controls">
            <div>
                <input type="text" class="symbol-input" placeholder="Enter stock symbol (e.g., AAPL)" value="AAPL">
                <button class="add-btn">Add Symbol</button>
                <div class="symbol-list"></div>
            </div>
            <div>
                <button class="zoom-btn" data-zoom="1">Zoom In</button>
                <button class="zoom-btn" data-zoom="-1">Zoom Out</button>
