        <div id="heatmap-container"></div>
        <div class="tooltip"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 1000,
            height: 500,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            updateInterval: 5000, // 5 seconds
            maxSymbols: 10,
            defaultSymbols: ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'META', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT']
        };

        // State
        let symbols = [...config.defaultSymbols];
        let data = [];
        let xScale, yScale, colorScale;
        let zoom;
        let svg, heatmapGroup, xAxisGroup, yAxisGroup;
        let tooltip;

        // Initialize the visualization
        function init() {
            // Create SVG container
            svg = d3.select("#heatmap-container")
                .append("svg")
                .attr("width", config.width)
                .attr("height", config.height);

            // Create a group for the heatmap
            heatmapGroup = svg.append("g")
                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

            // Create groups for axes
            xAxisGroup = svg.append("g")
                .attr("class", "x-axis")
                .attr("transform", `translate(${config.margin.left}, ${config.height - config.margin.bottom})`);

            yAxisGroup = svg.append("g")
                .attr("class", "y-axis")
                .attr("transform", `translate(${config.margin.left}, ${config.margin.top})`);

            // Add axis labels
            svg.append("text")
                .attr("class", "axis-label")
                .attr("x", config.width / 2)
                .attr("y", config.height - 5)
                .style("text-anchor", "middle")
                .text("Time");

            svg.append("text")
                .attr("class", "axis-label")
                .attr("transform", "rotate(-90)")
                .attr("x", -config.height / 2)
                .attr("y", 15)
                .style("text-anchor", "middle")
                .text("Stock Symbol");

            // Create tooltip
            tooltip = d3.select(".tooltip");

            // Set up zoom behavior
            zoom = d3.zoom()
                .scaleExtent([0.5, 10])
                .on("zoom", zoomed);

            svg.call(zoom);

            // Add event listeners
            document.querySelector(".add-btn").addEventListener("click", addSymbol);
            document.querySelector(".symbol-input").addEventListener("keypress", function(e) {
                if (e.key === "Enter") addSymbol();
            });

            document.querySelectorAll(".zoom-btn").forEach(btn => {
                btn.addEventListener("click", function() {
                    const zoomLevel = parseFloat(this.dataset.zoom);
                    if (zoomLevel === 0) {
                        svg.transition().duration(750).call(zoom.transform, d3.zoomIdentity);
                    } else {
                        const currentTransform = d3.zoomTransform(svg.node());
                        const newScale = currentTransform.k * (1 + zoomLevel * 0.5);
                        const newTransform = d3.zoomIdentity.scale(newScale);
                        svg.transition().duration(750).call(zoom.transform, newTransform);
                    }
                });
            });

            // Initial render
            renderSymbolList();
            fetchData();
            setInterval(fetchData, config.updateInterval);
        }

        // Handle zoom events
        function zoomed(event) {
            const transform = event.transform;
            heatmapGroup.attr("transform", transform);
            xAxisGroup.call(xAxis.scale(transform.rescaleX(xScale)));
            yAxisGroup.call(yAxis.scale(transform.rescaleY(yScale)));
        }

        // Add a new symbol
        function addSymbol() {
            const input = document.querySelector(".symbol-input");
            const symbol = input.value.trim().toUpperCase();

            if (symbol && !symbols.includes(symbol) && symbols.length < config.maxSymbols) {
                symbols.push(symbol);
                input.value = "";
                renderSymbolList();
                fetchData();
            }
        }

        // Remove a symbol
        function removeSymbol(symbol) {
            symbols = symbols.filter(s => s !== symbol);
            renderSymbolList();
            fetchData();
        }

        // Render the symbol list
        function renderSymbolList() {
            const container = document.querySelector(".symbol-list");
            container.innerHTML = "";

            symbols.forEach(symbol => {
                const tag = document.createElement("div");
                tag.className = "symbol-tag";
                tag.innerHTML = `
                    ${symbol}
                    <span class="remove-symbol" data-symbol="${symbol}">×</span>
                `;
                container.appendChild(tag);
            });

            // Add event listeners to remove buttons
            document.querySelectorAll(".remove-symbol").forEach(btn => {
                btn.addEventListener("click", function() {
                    removeSymbol(this.dataset.symbol);
                });
            });
        }

        // Fetch stock data (simulated with random data for demo)
        async function fetchData() {
            // In a real app, you would fetch from an API like Alpha Vantage, Yahoo Finance, etc.
            // This is a simulation for demonstration purposes

            const now = new Date();
            const endDate = now.toISOString().split('T')[0];
            const startDate = new Date(now.setDate(now.getDate() - 30)).toISOString().split('T')[0];

            // Generate random data for each symbol
            const newData = symbols.map(symbol => {
                const dailyData = [];
                for (let i = 0; i < 30; i++) {
                    const date = new Date(now.setDate(now.getDate() - 1));
                    const price = 100 + Math.random() * 100; // Random price between 100-200
                    dailyData.push({
                        date: date.toISOString().split('T')[0],
                        price: parseFloat(price.toFixed(2))
                    });
                }
                return { symbol, data: dailyData.reverse() };
            });

            // Update the data
            data = newData;

            // Render the heatmap
            renderHeatmap();
        }

        // Render the heatmap
        function renderHeatmap() {
            if (data.length === 0) return;

            // Flatten the data for easier processing
            const flatData = [];
            data.forEach(stock => {
                stock.data.forEach(day => {
                    flatData.push({
                        symbol: stock.symbol,
                        date: day.date,
                        price: day.price
                    });
                });
            });

            // Set up scales
            const allDates = [...new Set(flatData.map(d => d.date))];
            const allSymbols = [...new Set(flatData.map(d => d.symbol))];

            xScale = d3.scaleBand()
                .domain(allDates)
                .range([0, config.width - config.margin.left - config.margin.right])
                .padding(0.05);

            yScale = d3.scaleBand()
                .domain(allSymbols)
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.05);

            const priceExtent = d3.extent(flatData, d => d.price);
            colorScale = d3.scaleSequential(d3.interpolateRdYlGn)
                .domain([priceExtent[1], priceExtent[0]]); // Reverse to show green for higher prices

            // Create axes
            const xAxis = d3.axisBottom(xScale)
                .tickFormat(d => new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }))
                .tickValues(xScale.domain().filter((d, i) => i % 3 === 0)); // Show every 3rd date

            const yAxis = d3.axisLeft(yScale);

            // Update axes
            xAxisGroup.call(xAxis);
            yAxisGroup.call(yAxis);

            // Bind data to rectangles
            const rects = heatmapGroup.selectAll("rect")
                .data(flatData, d => `${d.symbol}-${d.date}`);

            // Enter new rectangles
            rects.enter()
                .append("rect")
                .attr("x", d => xScale(d.date))
                .attr("y", d => yScale(d.symbol))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.price))
                .on("mouseover", function(event, d) {
                    tooltip.style("visibility", "visible")
                        .html(`
                            <strong>${d.symbol}</strong><br>
                            Date: ${new Date(d.date).toLocaleDateString()}<br>
                            Price: $${d.price.toFixed(2)}
                        `);
                })
                .on("mousemove", function(event) {
                    tooltip.style("top", (event.pageY - 10) + "px")
                        .style("left", (event.pageX + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("visibility", "hidden");
                });

            // Update existing rectangles
            rects.transition()
                .duration(500)
                .attr("fill", d => colorScale(d.price));

            // Remove old rectangles
            rects.exit().remove();
        }

        // Initialize the visualization when the page loads
        window.addEventListener("load", init);
    </script>
</body>
</html>
