                <label for="time-range">Time Range:</label>
                <select id="time-range">
                    <option value="1d">1 Day</option>
                    <option value="1w">1 Week</option>
                    <option value="1m" selected>1 Month</option>
                    <option value="3m">3 Months</option>
                    <option value="1y">1 Year</option>
                </select>
            </div>
            <div>
                <button id="zoom-in">Zoom In</button>
                <button id="zoom-out">Zoom Out</button>
                <button id="reset-zoom">Reset Zoom</button>
            </div>
        </div>

        <div id="heatmap-container"></div>
    </div>

    <script>
        // Configuration
        const config = {
            width: 900,
            height: 550,
            margin: { top: 20, right: 20, bottom: 60, left: 80 },
            cellSize: 20,
            updateInterval: 5000, // 5 seconds
            maxZoom: 10,
            minZoom: 0.5
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
        let currentData = generateMockData();

        // Initialize the visualization
        const svg = d3.select("#heatmap-container")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        const tooltip = d3.select("body").append("div")
            .attr("class", "tooltip")
            .style("opacity", 0);

        // Color scale
        const colorScale = d3.scaleLinear()
            .domain([-5, 0, 5]) // Price change range
            .range(["#e63946", "#f1faee", "#2a9d8f"]);

        // Zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([config.minZoom, config.maxZoom])
            .on("zoom", zoomed);

        svg.call(zoom);

        // Button event listeners
        d3.select("#zoom-in").on("click", () => {
            svg.transition().call(zoom.scaleBy, 1.2);
        });

        d3.select("#zoom-out").on("click", () => {
            svg.transition().call(zoom.scaleBy, 0.8);
        });

        d3.select("#reset-zoom").on("click", () => {
            svg.transition().call(zoom.transform, d3.zoomIdentity);
        });

        d3.select("#time-range").on("change", function() {
            // In a real app, this would fetch new data based on the selected range
            currentData = generateMockData();
            updateHeatmap();
        });

        // Initial render
        updateHeatmap();

        // Set up real-time updates
        setInterval(() => {
            updateData();
            updateHeatmap();
        }, config.updateInterval);

        // Functions
        function generateMockData() {
            const data = [];
            const now = new Date();
            const timeRange = d3.select("#time-range").property("value");

            // Determine time range based on selection
            let startDate;
            switch(timeRange) {
                case '1d': startDate = new Date(now.getTime() - 24 * 60 * 60 * 1000); break;
                case '1w': startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000); break;
                case '1m': startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000); break;
                case '3m': startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000); break;
                case '1y': startDate = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000); break;
                default: startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
            }

            // Generate data points
            for (let i = 0; i < stocks.length; i++) {
                const stock = stocks[i];
                const currentTime = new Date(startDate);

                while (currentTime <= now) {
                    const priceChange = (Math.random() * 10 - 5).toFixed(2); // Random change between -5 and 5
                    data.push({
                        stock: stock,
                        time: new Date(currentTime),
                        priceChange: parseFloat(priceChange)
                    });

                    // Move to next time point (hourly for simplicity)
                    currentTime.setHours(currentTime.getHours() + 1);
                }
            }

            return data;
        }

        function updateData() {
            // In a real app, this would fetch new data from an API
            // For this demo, we'll just generate new mock data
            currentData = generateMockData();
        }

        function updateHeatmap() {
            // Clear previous elements
            g.selectAll("*").remove();

            // Process data into a matrix
            const timeExtent = d3.extent(currentData, d => d.time);
            const timeScale = d3.scaleTime()
                .domain(timeExtent)
                .range([0, config.width - config.margin.left - config.margin.right]);

            const stockScale = d3.scaleBand()
                .domain(stocks)
                .range([0, config.height - config.margin.top - config.margin.bottom]);

            // Create a nested data structure
            const nestedData = d3.group(currentData, d => d.stock, d => d.time);

            // Create cells
            const cells = g.selectAll(".cell")
                .data(currentData)
                .enter()
                .append("rect")
                .attr("class", "cell")
                .attr("x", d => timeScale(d.time))
                .attr("y", d => stockScale(d.stock))
                .attr("width", config.cellSize)
                .attr("height", config.cellSize)
                .attr("fill", d => colorScale(d.priceChange))
                .on("mouseover", function(event, d) {
                    tooltip.transition()
                        .duration(200)
                        .style("opacity", .9);
                    tooltip.html(`<strong>${d.stock}</strong><br/>${d.time.toLocaleString()}<br/>Change: ${d.priceChange}%`)
                        .style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY - 28) + "px");
                })
                .on("mouseout", function() {
                    tooltip.transition()
                        .duration(500)
                        .style("opacity", 0);
                });

            // Add axes
            const xAxis = d3.axisBottom(timeScale)
                .ticks(10)
                .tickFormat(d3.timeFormat("%b %d"));

            const yAxis = d3.axisLeft(stockScale);

            g.append("g")
                .attr("class", "axis axis--x")
                .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`)
                .call(xAxis);

            g.append("g")
                .attr("class", "axis axis--y")
                .call(yAxis);

            // Add color legend
            const legendWidth = 200;
            const legendHeight = 20;
            const legend = g.append("g")
                .attr("transform", `translate(${config.width - config.margin.left - config.margin.right - legendWidth},${config.height - config.margin.top - config.margin.bottom - 40})`);

            const legendScale = d3.scaleLinear()
                .domain([-5, 5])
                .range([0, legendWidth]);

            legend.selectAll("rect")
                .data(d3.range(-5, 5, 0.1))
                .enter()
                .append("rect")
                .attr("x", d => legendScale(d))
                .attr("y", 0)
                .attr("width", legendWidth / 100)
                .attr("height", legendHeight)
                .attr("fill", d => colorScale(d));

            legend.append("g")
                .attr("class", "axis axis--legend")
                .attr("transform", `translate(0,${legendHeight})`)
                .call(d3.axisBottom(legendScale).ticks(5));
        }

        function zoomed(event) {
            g.attr("transform", event.transform);
        }
    </script>
</body>
</html>
```

