        // Sample data - in a real app, this would come from an API
        const generateSampleData = (stock, timeframe) => {
            const now = new Date();
            let interval, count;

            switch(timeframe) {
                case '1d':
                    interval = 60 * 60 * 1000; // 1 hour
                    count = 24;
                    break;
                case '1w':
                    interval = 6 * 60 * 60 * 1000; // 6 hours
                    count = 24 * 7;
                    break;
                case '1m':
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    count = 30;
                    break;
                case '3m':
                    interval = 24 * 60 * 60 * 1000; // 1 day
                    count = 90;
                    break;
                case '1y':
                    interval = 7 * 24 * 60 * 60 * 1000; // 1 week
                    count = 52;
                    break;
                default:
                    interval = 24 * 60 * 60 * 1000;
                    count = 30;
