        };

        // Mock data generator for demonstration
        function generateMockData(symbols, timeframe) {
            const now = new Date();
            const data = [];
            const timestamps = [];

            // Generate timestamps based on timeframe
            const interval = {
                '1d': 60 * 60 * 1000, // 1 hour
                '1w': 6 * 60 * 60 * 1000, // 6 hours
                '1m': 24 * 60 * 60 * 1000, // 1 day
                '3m': 7 * 24 * 60 * 60 * 1000, // 1 week
                '1y': 30 * 24 * 60 * 60 * 1000 // 1 month
            }[timeframe];

            const points = {
                '1d': 24,
                '1w': 168,
                '1m': 30,
                '3m': 90,
                '1y': 12
            }[timeframe];

            for (let i = 0; i < points; i++) {
                const date = new Date(now.getTime() - (points - i) * interval);
                timestamps.push(date.toISOString().split('T')[0]);
            }

            // Generate random price data for each symbol
            symbols.forEach(symbol => {
                const basePrice = 100 + Math.random() * 1000;
