            const now = new Date();
            document.getElementById('status').textContent = `Updated: ${now.toLocaleTimeString()} | Showing ${config.initialSymbols.length} stocks for ${config.timeframe}`;
        }

        // Event listeners for controls
        document.getElementById('symbols').addEventListener('change', function() {
            config.initialSymbols = this.value.split(',').map(s => s.trim());
            initHeatmap();
