                case '1w':
                    points = 7 * 24 * 6; // 1 point per 10 minutes
                    interval = 10 * 60 * 1000;
                    break;
                case '1m':
                    points = 30 * 24 * 2; // 1 point per 30 minutes
                    interval = 30 * 60 * 1000;
                    break;
                case '3m':
                    points = 90 * 24; // 1 point per hour
                    interval = 60 * 60 * 1000;
                    break;
                case '1y':
                    points = 365; // 1 point per day
                    interval = 24 * 60 * 60 * 1000;
                    break;
            }

            const data = [];
            const labels = [];
            const times = [];

            for (let i = 0; i < points; i++) {
                const time = new Date(now.getTime() - (points - i) * interval);
                times.push(time);

                // Generate mock price data (simulating stock movement)
                const basePrice = 100 + Math.random() * 200;
                const price = basePrice + Math.sin(i * 0.1) * 20 + Math.random() * 10;

                // Generate mock volume data
                const volume = Math.floor(Math.random() * 1000000);

                data.push({
                    time: time,
                    price: price,
                    volume: volume
                });
            }

            // Create labels for x and y axes
            const uniqueDates = [...new Set(data.map(d => d.time.toDateString()))];
            const uniqueHours = [...new Set(data.map(d => d.time.getHours()))];

            return {
                data: data,
                xLabels: uniqueDates,
                yLabels: uniqueHours.map(h => `${h}:00`),
                stockSymbol: stockSymbol,
                timeframe: timeframe
            };
