            const z = [];
            const x = data.xLabels;
            const y = data.yLabels;

            // Create a 2D array for the heatmap
            for (let i = 0; i < y.length; i++) {
                const row = [];
                for (let j = 0; j < x.length; j++) {
                    // Find matching data point
                    const matchingData = data.data.find(d =>
                        d.time.toDateString() === x[j] &&
                        d.time.getHours() === parseInt(y[i])
                    );

                    // Use price as the value, or 0 if no data
                    row.push(matchingData ? matchingData.price : 0);
                }
                z.push(row);
            }

            // Create the heatmap
            const heatmapData = [{
                z: z,
                x: x,
                y: y,
                type: 'heatmap',
                colorscale: 'Portland',
                hoverinfo: 'x+y+z',
                hovertemplate: '<b>%{x}</b><br>%{y}<br>Price: $%{z:.2f}<extra></extra>'
