    <script>
        // Configuration
        const config = {
            width: 900,
            height: 550,
            margin: { top: 30, right: 30, bottom: 50, left: 60 },
            updateInterval: 5000, // 5 seconds
            maxDataPoints: 100
        };

        // Sample stock data (in a real app, this would come from an API)
        const stocks = ['AAPL', 'MSFT', 'GOOGL', 'AMZN', 'FB', 'TSLA', 'NVDA', 'JPM', 'V', 'WMT'];
        let data = generateInitialData();

        // Initialize the heatmap
        const svg = d3.select("#heatmap")
            .append("svg")
            .attr("width", config.width)
            .attr("height", config.height);

        const g = svg.append("g")
            .attr("transform", `translate(${config.margin.left},${config.margin.top})`);

        // Add tooltip
        const tooltip = d3.select("#tooltip");

        // Add axes
        const xAxisGroup = g.append("g")
            .attr("class", "x-axis")
            .attr("transform", `translate(0,${config.height - config.margin.top - config.margin.bottom})`);

        const yAxisGroup = g.append("g")
            .attr("class", "y-axis");

        // Add axis labels
        g.append("text")
            .attr("class", "axis-label")
            .attr("x", config.width / 2 - config.margin.left)
            .attr("y", config.height - config.margin.top - 10)
            .style("text-anchor", "middle")
            .text("Time");

        g.append("text")
            .attr("class", "axis-label")
            .attr("transform", "rotate(-90)")
            .attr("x", -config.height / 2 + config.margin.top)
            .attr("y", -40)
            .style("text-anchor", "middle")
            .text("Stock");

        // Add zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 10])
            .on("zoom", zoomed);

        svg.call(zoom);

        // Reset zoom button
        d3.select("#resetZoom").on("click", () => {
            svg.transition().duration(750).call(
                zoom.transform,
                d3.zoomIdentity
            );
        });

        // Time range selector
        d3.select("#timeRange").on("change", function() {
            const range = this.value;
            // In a real app, you would fetch new data based on the selected range
            console.log(`Time range changed to: ${range}`);
            // For demo purposes, we'll just regenerate data
            data = generateInitialData();
            updateHeatmap();
        });

        // Initial render
        updateHeatmap();

        // Set up periodic updates
        setInterval(() => {
            updateData();
            updateHeatmap();
        }, config.updateInterval);

        // Generate initial random data
        function generateInitialData() {
            const now = new Date();
            const dataPoints = [];

            for (let i = 0; i < config.maxDataPoints; i++) {
                const time = new Date(now.getTime() - (config.maxDataPoints - i) * 3600000); // 1 hour intervals

                stocks.forEach(stock => {
                    dataPoints.push({
                        stock,
                        time,
                        price: 100 + Math.random() * 100,
                        change: (Math.random() - 0.5) * 5
                    });
                });
            }

            return dataPoints;
        }

        // Update data with new values
        function updateData() {
            const now = new Date();

            // Remove oldest data point
            data = data.slice(stocks.length);

            // Add new data points
            stocks.forEach(stock => {
                data.push({
                    stock,
                    time: now,
                    price: 100 + Math.random() * 100,
                    change: (Math.random() - 0.5) * 5
                });
            });
        }

        // Update the heatmap visualization
        function updateHeatmap() {
            // Prepare data for heatmap
            const heatmapData = d3.rollup(
                data,
                v => d3.mean(v, d => d.change),
                d => d.stock,
                d => d.time
            );

            // Convert to array of objects
            const heatmapArray = Array.from(heatmapData, ([stock, timeMap]) => {
                return Array.from(timeMap, ([time, change]) => ({
                    stock,
                    time,
                    change
                }));
            }).flat();

            // Set up scales
            const xScale = d3.scaleBand()
                .domain([...new Set(heatmapArray.map(d => d.time))].sort((a, b) => a - b))
                .range([0, config.width - config.margin.left - config.margin.right])
                .padding(0.05);

            const yScale = d3.scaleBand()
                .domain(stocks)
                .range([0, config.height - config.margin.top - config.margin.bottom])
                .padding(0.05);

            const colorScale = d3.scaleDiverging()
                .domain([-5, 0, 5])
                .interpolator(d3.interpolateRdYlGn);

            // Update axes
            xAxisGroup.call(d3.axisBottom(xScale).tickFormat(d3.timeFormat("%H:%M")))
                .selectAll("text")
                .attr("transform", "rotate(-45)")
                .style("text-anchor", "end");

            yAxisGroup.call(d3.axisLeft(yScale));

            // Update legend
            const legend = d3.select("#legend");
            legend.selectAll("*").remove();

            const legendData = [
                { label: "Decrease", color: colorScale(-5) },
                { label: "Neutral", color: colorScale(0) },
                { label: "Increase", color: colorScale(5) }
            ];

            legend.selectAll(".legend-item")
                .data(legendData)
                .enter()
                .append("div")
                .attr("class", "legend-item")
                .html(d => `
                    <div class="legend-color" style="background-color: ${d.color};"></div>
                    <span>${d.label}</span>
                `);

            // Bind data to rectangles
            const rects = g.selectAll("rect")
                .data(heatmapArray, d => `${d.stock}-${d.time}`);

            // Enter new rectangles
            rects.enter()
                .append("rect")
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change))
                .on("mouseover", function(event, d) {
                    tooltip.style("opacity", 1)
                        .html(`
                            <strong>${d.stock}</strong><br>
                            Time: ${d3.timeFormat("%H:%M")(d.time)}<br>
                            Change: ${d.change.toFixed(2)}%
                        `);
                })
                .on("mousemove", function(event) {
                    tooltip.style("left", (event.pageX + 10) + "px")
                        .style("top", (event.pageY + 10) + "px");
                })
                .on("mouseout", function() {
                    tooltip.style("opacity", 0);
                });

            // Update existing rectangles
            rects.transition()
                .duration(500)
                .attr("x", d => xScale(d.time))
                .attr("y", d => yScale(d.stock))
                .attr("width", xScale.bandwidth())
                .attr("height", yScale.bandwidth())
                .attr("fill", d => colorScale(d.change));

            // Remove old rectangles
            rects.exit().remove();
        }

        // Handle zoom/pan
        function zoomed(event) {
            const transform = event.transform;

            // Apply the transform to the main group
            g.attr("transform", `translate(${config.margin.left + transform.x},${config.margin.top + transform.y}) scale(${transform.k})`);

            // Adjust the axes
            xAxisGroup.call(d3.axisBottom(xScale).scale(transform.rescaleX(xScale)));
            yAxisGroup.call(d3.axisLeft(yScale).scale(transform.rescaleY(yScale)));
        }
    </script>
