### 4. Main Board Component (Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useFirestore } from '../hooks/useFirestore';

const Board = () => {
  const { docs: columns, updateDocument: updateColumn } = useFirestore('columns');
  const { docs: tasks, addDocument: addTask, updateDocument: updateTask } = useFirestore('tasks');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState(null);

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    // If no destination, do nothing
    if (!destination) return;

    // If dropped in the same position, do nothing
    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Reordering columns
    if (type === 'column') {
      const newColumnOrder = Array.from(columns);
      const [removed] = newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, removed);

      // Update column order in Firestore
      newColumnOrder.forEach((column, index) => {
        updateColumn(column.id, { order: index });
      });
      return;
    }

    // Moving tasks between columns
    const startColumn = columns.find(col => col.id === source.droppableId);
    const finishColumn = columns.find(col => col.id === destination.droppableId);

    if (startColumn === finishColumn) {
      // Reordering tasks in the same column
      const columnTasks = tasks.filter(task => task.columnId === startColumn.id);
      const [removed] = columnTasks.splice(source.index, 1);
      columnTasks.splice(destination.index, 0, removed);

      // Update task order in Firestore
      columnTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });
    } else {
      // Moving tasks to a different column
      updateTask(draggableId, {
        columnId: finishColumn.id,
        order: destination.index
      });
    }
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleAddTask = (columnId) => {
    const newTask = {
      title: 'New Task',
      description: '',
      columnId,
      order: tasks.filter(task => task.columnId === columnId).length,
      createdAt: new Date().toISOString(),
      assignees: []
    };
    addTask(newTask);
  };

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="columns-container"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns
                .sort((a, b) => a.order - b.order)
                .map((column, index) => (
                  <Column
                    key={column.id}
                    column={column}
                    tasks={tasks
                      .filter(task => task.columnId === column.id)
                      .sort((a, b) => a.order - b.order)}
                    index={index}
                    onTaskClick={handleTaskClick}
                    onAddTask={handleAddTask}
                  />
                ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={selectedTask}
          onClose={() => setIsModalOpen(false)}
          onUpdate={updateTask}
        />
      )}
    </div>
  );
};

export default Board;
```

