```javascript
import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const TaskModal = ({ task, onClose, onUpdate }) => {
  const [title, setTitle] = useState(task.title);
  const [description, setDescription] = useState(task.description);
  const [assignees, setAssignees] = useState(task.assignees || []);
  const [newAssignee, setNewAssignee] = useState('');
  const { currentUser } = useAuth();

  useEffect(() => {
    setTitle(task.title);
    setDescription(task.description);
    setAssignees(task.assignees || []);
  }, [task]);

  const handleSubmit = (e) => {
    e.preventDefault();
    onUpdate(task.id, {
      title,
      description,
      assignees,
      updatedAt: new Date().toISOString(),
      updatedBy: currentUser.email
    });
    onClose();
  };

  const handleAddAssignee = () => {
    if (newAssignee && !assignees.includes(newAssignee)) {
      setAssignees([...assignees, newAssignee]);
      setNewAssignee('');
    }
  };

  const handleRemoveAssignee = (assigneeToRemove) => {
    setAssignees(assignees.filter(a => a !== assigneeToRemove));
  };

  return (
    <div className="modal-overlay">
      <div className="modal">
        <button className="close-button" onClick={onClose}>×</button>
        <h2>Edit Task</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Title</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label>Assignees</label>
            <div className="assignees-input">
              <input
                type="text"
                value={newAssignee}
                onChange={(e) => setNewAssignee(e.target.value)}
                placeholder="Add assignee email"
              />
              <button type="button" onClick={handleAddAssignee}>Add</button>
            </div>
            <div className="assignees-list">
              {assignees.map((assignee, index) => (
                <div key={index} className="assignee-item">
                  <span>{assignee}</span>
                  <button type="button" onClick={() => handleRemoveAssignee(assignee)}>×</button>
                </div>
              ))}
            </div>
          </div>

          <button type="submit" className="submit-button">Save Changes</button>
        </form>
      </div>
    </div>
  );
};

export default TaskModal;
```

