## Setup Instructions

1. Create a new React project:
```bash
npx create-react-app project-management-app
cd project-management-app
```

2. Install required dependencies:
```bash
npm install firebase react-beautiful-dnd react-router-dom
```

3. Set up Firebase:
   - Create a Firebase project at [Firebase Console](https://console.firebase.google.com/)
   - Enable Firestore and Authentication
   - Add your Firebase configuration to `firebase.js`

4. Initialize Firestore collections:
   - Create collections named 'columns' and 'tasks' in Firestore
   - Add initial columns with 'title' and 'order' fields

5. Run the application:
```bash
npm start
```

## Features Implemented

1. **Drag-and-Drop Interface**:
   - Reorder columns and tasks within columns
   - Move tasks between columns

2. **Real-time Collaboration**:
   - Firebase Firestore for real-time data synchronization
   - Automatic updates when data changes

3. **Task Management**:
   - Create, edit, and delete tasks
   - Assign tasks to team members
   - Track task status through columns

4. **User Interface**:
   - Clean, responsive design
   - Modal for detailed task editing
   - Visual feedback during drag operations

5. **Authentication**:
   - User authentication context
   - Track who created/updated tasks

This implementation provides a solid foundation that you can extend with additional features like comments, due dates, attachments, or more advanced user management as needed.

# Browser-Based Project Management Application

Here's a comprehensive code implementation for a project management application with drag-and-drop task boards and real-time collaboration features.

## Frontend (React + TypeScript)

```typescript
// src/App.tsx
import React, { useState, useEffect } from 'react';
import { DndProvider } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { io, Socket } from 'socket.io-client';
import Board from './components/Board';
import TaskModal from './components/TaskModal';
import UserList from './components/UserList';
import './App.css';

interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  assignee?: string;
  dueDate?: string;
  priority?: 'low' | 'medium' | 'high';
}

interface Column {
  id: string;
  title: string;
  taskIds: string[];
}

interface User {
  id: string;
  name: string;
  color: string;
}

const initialColumns: Column[] = [
  { id: 'todo', title: 'To Do', taskIds: [] },
  { id: 'in-progress', title: 'In Progress', taskIds: [] },
  { id: 'done', title: 'Done', taskIds: [] },
];

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Record<string, Task>>({});
  const [columns, setColumns] = useState<Column[]>(initialColumns);
  const [selectedTask, setSelectedTask] = useState<Task | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    // Initialize socket connection
    const newSocket = io('http://localhost:3001');
    setSocket(newSocket);

    // Set up socket listeners
    newSocket.on('connect', () => {
      console.log('Connected to server');
      // Join a room (could be based on project ID)
      newSocket.emit('joinRoom', 'project1');
    });

    newSocket.on('taskUpdate', (updatedTasks: Record<string, Task>) => {
      setTasks(updatedTasks);
    });

    newSocket.on('columnUpdate', (updatedColumns: Column[]) => {
      setColumns(updatedColumns);
    });

    newSocket.on('userUpdate', (updatedUsers: User[]) => {
      setUsers(updatedUsers);
    });

    newSocket.on('currentUser', (user: User) => {
      setCurrentUser(user);
    });

    // Clean up on unmount
    return () => {
      newSocket.disconnect();
    };
  }, []);

  const handleTaskSelect = (taskId: string) => {
    setSelectedTask(tasks[taskId]);
    setIsModalOpen(true);
  };

  const handleTaskUpdate = (updatedTask: Task) => {
    const updatedTasks = { ...tasks, [updatedTask.id]: updatedTask };
    setTasks(updatedTasks);

    if (socket) {
      socket.emit('updateTask', updatedTask);
    }
  };

  const handleTaskCreate = (newTask: Omit<Task, 'id'>) => {
    const taskId = Date.now().toString();
    const taskWithId = { ...newTask, id: taskId };
    const updatedTasks = { ...tasks, [taskId]: taskWithId };

    // Add to the first column (To Do)
    const updatedColumns = columns.map(column => {
      if (column.id === 'todo') {
        return { ...column, taskIds: [...column.taskIds, taskId] };
      }
      return column;
    });

    setTasks(updatedTasks);
    setColumns(updatedColumns);

    if (socket) {
      socket.emit('createTask', taskWithId);
      socket.emit('updateColumns', updatedColumns);
    }
  };

  const handleTaskDelete = (taskId: string) => {
    const { [taskId]: _, ...remainingTasks } = tasks;
    const updatedColumns = columns.map(column => ({
      ...column,
      taskIds: column.taskIds.filter(id => id !== taskId),
    }));

    setTasks(remainingTasks);
    setColumns(updatedColumns);

    if (socket) {
      socket.emit('deleteTask', taskId);
      socket.emit('updateColumns', updatedColumns);
    }
  };

  const handleColumnUpdate = (updatedColumns: Column[]) => {
    setColumns(updatedColumns);

    if (socket) {
      socket.emit('updateColumns', updatedColumns);
    }
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <header className="app-header">
          <h1>Project Management Board</h1>
          {currentUser && (
            <div className="user-info">
              <span style={{ color: currentUser.color }}>⬤</span>
              <span>{currentUser.name}</span>
            </div>
          )}
        </header>

        <div className="app-content">
          <UserList users={users} currentUser={currentUser} />

          <Board
            tasks={tasks}
            columns={columns}
            onTaskSelect={handleTaskSelect}
            onColumnUpdate={handleColumnUpdate}
          />

          <button
            className="add-task-button"
            onClick={() => {
              setSelectedTask(null);
              setIsModalOpen(true);
            }}
          >
            + Add Task
          </button>
        </div>

        {isModalOpen && (
          <TaskModal
            task={selectedTask}
            onClose={() => setIsModalOpen(false)}
            onSave={selectedTask ? handleTaskUpdate : handleTaskCreate}
            onDelete={selectedTask ? handleTaskDelete : undefined}
            users={users}
          />
        )}
      </div>
    </DndProvider>
  );
};

export default App;
