// src/components/Board.tsx
import React from 'react';
import { useDrop } from 'react-dnd';
import Column from './Column';

interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  assignee?: string;
  dueDate?: string;
  priority?: 'low' | 'medium' | 'high';
}

interface Column {
  id: string;
  title: string;
  taskIds: string[];
}

interface BoardProps {
  tasks: Record<string, Task>;
  columns: Column[];
  onTaskSelect: (taskId: string) => void;
  onColumnUpdate: (columns: Column[]) => void;
}

const Board: React.FC<BoardProps> = ({ tasks, columns, onTaskSelect, onColumnUpdate }) => {
  const [, drop] = useDrop(() => ({
    accept: 'TASK',
    drop: (item: { id: string; fromColumnId: string }, monitor) => {
      const didDrop = monitor.didDrop();
      if (!didDrop) {
        // If dropped outside any column, return to original position
        return { moved: false };
      }
      return { moved: true };
    },
  }));

  const moveTask = (taskId: string, fromColumnId: string, toColumnId: string) => {
    if (fromColumnId === toColumnId) return;

    const updatedColumns = columns.map(column => {
      if (column.id === fromColumnId) {
        return {
          ...column,
          taskIds: column.taskIds.filter(id => id !== taskId),
        };
      }
      if (column.id === toColumnId) {
        return {
          ...column,
          taskIds: [...column.taskIds, taskId],
        };
      }
      return column;
    });

    // Update task status
    const updatedTask = { ...tasks[taskId], status: toColumnId };
    const updatedTasks = { ...tasks, [taskId]: updatedTask };

    onColumnUpdate(updatedColumns);
    // You would also emit the task update here if needed
  };

  return (
    <div className="board" ref={drop}>
      {columns.map(column => (
        <Column
          key={column.id}
          column={column}
          tasks={tasks}
          onTaskSelect={onTaskSelect}
          onTaskMove={moveTask}
        />
      ))}
    </div>
  );
};

export default Board;
