// src/components/Column.tsx
import React from 'react';
import { useDrop } from 'react-dnd';
import TaskCard from './TaskCard';

interface Task {
  id: string;
  title: string;
  description: string;
  status: string;
  assignee?: string;
  dueDate?: string;
  priority?: 'low' | 'medium' | 'high';
}

interface ColumnProps {
  column: {
    id: string;
    title: string;
    taskIds: string[];
  };
  tasks: Record<string, Task>;
  onTaskSelect: (taskId: string) => void;
  onTaskMove: (taskId: string, fromColumnId: string, toColumnId: string) => void;
}

const Column: React.FC<ColumnProps> = ({ column, tasks, onTaskSelect, onTaskMove }) => {
  const [{ isOver }, drop] = useDrop(() => ({
    accept: 'TASK',
    drop: (item: { id: string; fromColumnId: string }) => {
      onTaskMove(item.id, item.fromColumnId, column.id);
      return { moved: true };
    },
    collect: (monitor) => ({
      isOver: !!monitor.isOver(),
    }),
  }));

  return (
    <div
      className={`column ${isOver ? 'column-drag-over' : ''}`}
      ref={drop}
    >
      <h2 className="column-title">{column.title}</h2>
      <div className="task-list">
        {column.taskIds.map(taskId => (
          <TaskCard
            key={taskId}
            task={tasks[taskId]}
            onClick={() => onTaskSelect(taskId)}
            fromColumnId={column.id}
          />
        ))}
      </div>
    </div>
  );
};

