## Backend (Node.js + Socket.io)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const cors = require('cors');

const app = express();
app.use(cors());

const server = http.createServer(app);
const io = socketIo(server, {
  cors: {
    origin: "http://localhost:3000",
    methods: ["GET", "POST"]
  }
});

// In-memory storage for demo purposes
const tasks = {};
const columns = [
  { id: 'todo', title: 'To Do', taskIds: [] },
  { id: 'in-progress', title: 'In Progress', taskIds: [] },
  { id: 'done', title: 'Done', taskIds: [] },
];
const users = [
  { id: '1', name: 'Alice', color: '#FF5733' },
  { id: '2', name: 'Bob', color: '#33FF57' },
  { id: '3', name: 'Charlie', color: '#3357FF' },
];

io.on('connection', (socket) => {
  console.log('New client connected');

  // Assign a random user for this connection
  const randomUser = users[Math.floor(Math.random() * users.length)];
  socket.emit('currentUser', randomUser);

  // Join a room (could be based on project ID)
  socket.on('joinRoom', (roomId) => {
    socket.join(roomId);
    console.log(`User ${randomUser.name} joined room ${roomId}`);

    // Send initial data to the client
    socket.emit('taskUpdate', tasks);
    socket.emit('columnUpdate', columns);
    socket.emit('userUpdate', users);
  });

  // Task events
  socket.on('createTask', (task) => {
    tasks[task.id] = task;
    io.to('project1').emit('taskUpdate', tasks);
  });

  socket.on('updateTask', (task) => {
    tasks[task.id] = task;
    io.to('project1').emit('taskUpdate', tasks);
  });

  socket.on('deleteTask', (taskId) => {
    delete tasks[taskId];
    io.to('project1').emit('taskUpdate', tasks);
  });

  // Column events
  socket.on('updateColumns', (updatedColumns) => {
    updatedColumns.forEach(column => {
      const existingColumn = columns.find(c => c.id === column.id);
      if (existingColumn) {
        existingColumn.taskIds = column.taskIds;
      }
    });
    io.to('project1').emit('columnUpdate', columns);
  });

  // User events
  socket.on('userUpdate', (updatedUsers) => {
    users.splice(0, users.length, ...updatedUsers);
    io.to('project1').emit('userUpdate', users);
  });

  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
