### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskForm from './TaskForm';
import { db } from '../firebase/config';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });
  const [tasks, setTasks] = useState({});
  const [showForm, setShowForm] = useState(false);
  const { currentUser } = useAuth();

  useEffect(() => {
    const unsubscribe = db.collection('tasks')
      .where('userId', '==', currentUser.uid)
      .onSnapshot(snapshot => {
        const newTasks = {};
        const newColumns = {
          'todo': { id: 'todo', title: 'To Do', taskIds: [] },
          'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
          'done': { id: 'done', title: 'Done', taskIds: [] }
        };

        snapshot.forEach(doc => {
          const task = { id: doc.id, ...doc.data() };
          newTasks[task.id] = task;
          newColumns[task.status].taskIds.push(task.id);
        });

        setTasks(newTasks);
        setColumns(newColumns);
      });

    return () => unsubscribe();
  }, [currentUser.uid]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds
      };

      setColumns({
        ...columns,
        [newColumn.id]: newColumn
      });
    } else {
      const startTaskIds = Array.from(start.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...start,
        taskIds: startTaskIds
      };

      const finishTaskIds = Array.from(finish.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finish,
        taskIds: finishTaskIds
      };

      setColumns({
        ...columns,
        [newStart.id]: newStart,
        [newFinish.id]: newFinish
      });

      // Update task status in Firestore
      db.collection('tasks').doc(draggableId).update({
        status: destination.droppableId
      });
    }
  };

  const addTask = (task) => {
    const newTask = {
      ...task,
      userId: currentUser.uid,
      createdAt: new Date(),
      status: 'todo'
    };

    db.collection('tasks').add(newTask);
    setShowForm(false);
  };

  return (
    <div className="board">
      <div className="board-header">
        <h1>Project Management Board</h1>
        <button onClick={() => setShowForm(true)}>Add Task</button>
      </div>

      {showForm && (
        <TaskForm
          onSubmit={addTask}
          onCancel={() => setShowForm(false)}
        />
      )}

      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable
          droppableId="board"
          direction="horizontal"
          type="column"
        >
          {(provided) => (
            <div
              className="board-columns"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {Object.keys(columns).map((columnId, index) => {
                const column = columns[columnId];
                const columnTasks = column.taskIds.map(taskId => tasks[taskId]);

                return (
                  <Column
                    key={column.id}
                    column={column}
                    tasks={columnTasks}
                    index={index}
                  />
                );
              })}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
