### 2. Auth Context (AuthContext.js)

```javascript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth } from '../firebase';
import { onAuthStateChanged } from 'firebase/auth';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    currentUser,
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  return useContext(AuthContext);
};
```

### 3. Firestore Hook (useFirestore.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { collection, query, onSnapshot, doc, updateDoc, addDoc, deleteDoc } from 'firebase/firestore';

export const useFirestore = (collectionName) => {
  const [docs, setDocs] = useState([]);

  useEffect(() => {
    const q = query(collection(db, collectionName));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const documents = [];
      querySnapshot.forEach((doc) => {
        documents.push({ ...doc.data(), id: doc.id });
      });
      setDocs(documents);
    });

    return () => unsubscribe();
  }, [collectionName]);

  const addDocument = async (document) => {
    await addDoc(collection(db, collectionName), document);
  };

  const updateDocument = async (id, updates) => {
    const docRef = doc(db, collectionName, id);
    await updateDoc(docRef, updates);
  };

  const deleteDocument = async (id) => {
    const docRef = doc(db, collectionName, id);
    await deleteDoc(docRef);
  };

  return { docs, addDocument, updateDocument, deleteDocument };
};
```

### 4. Board Component (Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskForm from './TaskForm';
import { useFirestore } from '../hooks/useFirestore';

const Board = () => {
  const { docs: tasks, updateDocument } = useFirestore('tasks');
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  // Organize tasks by column
  React.useEffect(() => {
    const newColumns = { ...columns };
    Object.keys(newColumns).forEach(columnId => {
      newColumns[columnId].taskIds = tasks
        .filter(task => task.status === columnId)
        .map(task => task.id);
    });
    setColumns(newColumns);
  }, [tasks]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Update task status in Firestore
    updateDocument(draggableId, { status: destination.droppableId });
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns-container">
          {Object.keys(columns).map((columnId) => (
            <Droppable key={columnId} droppableId={columnId}>
              {(provided) => (
                <div
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                  className="column-wrapper"
                >
                  <Column
                    column={columns[columnId]}
                    tasks={tasks.filter(task => task.status === columnId)}
                  />
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
      <TaskForm />
    </div>
  );
};

export default Board;
```

