import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import Board from './components/Board';
import Navbar from './components/Navbar';
import { auth } from './firebase';
import { onAuthStateChanged } from 'firebase/auth';

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setUser(user);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading) {
    return <div>Loading...</div>;
  }

  return (
    <Router>
      <AuthProvider value={{ user }}>
        <div className="app">
          <Navbar />
          <Routes>
            <Route path="/" element={<Board />} />
          </Routes>
        </div>
      </AuthProvider>
    </Router>
  );
}

export default App;
```

### 3. Board.jsx (Main Board Component)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { db } from '../firebase';
import { collection, query, onSnapshot, doc, updateDoc, addDoc } from 'firebase/firestore';
import { useAuth } from '../context/AuthContext';
import TaskModal from './TaskModal';
import UserPresence from './UserPresence';

const Board = () => {
  const [columns, setColumns] = useState({});
  const [tasks, setTasks] = useState({});
  const [selectedTask, setSelectedTask] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { user } = useAuth();

  useEffect(() => {
    const q = query(collection(db, 'columns'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const cols = {};
      querySnapshot.forEach((doc) => {
        cols[doc.id] = { id: doc.id, ...doc.data() };
      });
      setColumns(cols);
    });

    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const q = query(collection(db, 'tasks'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const ts = {};
      querySnapshot.forEach((doc) => {
        ts[doc.id] = { id: doc.id, ...doc.data() };
      });
      setTasks(ts);
    });

    return () => unsubscribe();
  }, []);

  const onDragEnd = async (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    if (type === 'column') {
      const newColumnOrder = Object.keys(columns);
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, draggableId);

      // Update column order in Firestore
      const batch = db.batch();
      newColumnOrder.forEach((columnId, index) => {
        const columnRef = doc(db, 'columns', columnId);
        batch.update(columnRef, { order: index });
      });
      await batch.commit();
      return;
    }

    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      // Update column in Firestore
      const columnRef = doc(db, 'columns', newColumn.id);
      await updateDoc(columnRef, { taskIds: newTaskIds });

      return;
    }

    // Moving from one list to another
    const startTaskIds = Array.from(start.taskIds);
    startTaskIds.splice(source.index, 1);
    const newStart = {
      ...start,
      taskIds: startTaskIds,
    };

    const finishTaskIds = Array.from(finish.taskIds);
    finishTaskIds.splice(destination.index, 0, draggableId);
    const newFinish = {
      ...finish,
      taskIds: finishTaskIds,
    };

    // Update both columns in Firestore
    const startRef = doc(db, 'columns', newStart.id);
    const finishRef = doc(db, 'columns', newFinish.id);

    await updateDoc(startRef, { taskIds: newStart.taskIds });
    await updateDoc(finishRef, { taskIds: newFinish.taskIds });

    // Update task's columnId
    const taskRef = doc(db, 'tasks', draggableId);
    await updateDoc(taskRef, { columnId: newFinish.id });
  };

  const handleAddColumn = async () => {
    const columnName = prompt('Enter column name:');
    if (columnName) {
      const newColumn = {
        title: columnName,
        taskIds: [],
        order: Object.keys(columns).length,
      };
      await addDoc(collection(db, 'columns'), newColumn);
    }
  };

  const handleTaskClick = (taskId) => {
    setSelectedTask(tasks[taskId]);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedTask(null);
  };

  const handleUpdateTask = async (updatedTask) => {
    const taskRef = doc(db, 'tasks', updatedTask.id);
    await updateDoc(taskRef, updatedTask);
    handleCloseModal();
  };

  const handleAddTask = async (columnId) => {
    const taskName = prompt('Enter task name:');
    if (taskName) {
      const newTask = {
        title: taskName,
        description: '',
        columnId,
        createdAt: new Date().toISOString(),
        createdBy: user.uid,
      };

      const docRef = await addDoc(collection(db, 'tasks'), newTask);

      // Update column's taskIds
      const columnRef = doc(db, 'columns', columnId);
      const column = columns[columnId];
      const updatedTaskIds = [...column.taskIds, docRef.id];
      await updateDoc(columnRef, { taskIds: updatedTaskIds });
    }
  };

  return (
    <div className="board-container">
      <UserPresence />
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {Object.values(columns)
                .sort((a, b) => a.order - b.order)
                .map((column, index) => (
                  <Column
                    key={column.id}
                    column={column}
                    tasks={tasks}
                    index={index}
                    onTaskClick={handleTaskClick}
                    onAddTask={handleAddTask}
                  />
                ))}
              {provided.placeholder}
              <button className="add-column-btn" onClick={handleAddColumn}>
                + Add Column
              </button>
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {isModalOpen && selectedTask && (
        <TaskModal
          task={selectedTask}
          onClose={handleCloseModal}
          onUpdate={handleUpdateTask}
        />
      )}
    </div>
  );
};

export default Board;
```

