### 7. UserPresence.jsx (Real-time User Presence)

```javascript
import React, { useEffect, useState } from 'react';
import { db } from '../firebase';
import { collection, doc, setDoc, onSnapshot, serverTimestamp } from 'firebase/firestore';
import { useAuth } from '../context/AuthContext';

const UserPresence = () => {
  const [users, setUsers] = useState([]);
  const { user } = useAuth();

  useEffect(() => {
    if (!user) return;

    // Add current user to presence
    const userRef = doc(db, 'presence', user.uid);
    setDoc(userRef, {
      uid: user.uid,
      displayName: user.displayName,
      photoURL: user.photoURL,
      lastSeen: serverTimestamp(),
    });

    // Clean up on unmount
    return () => {
      setDoc(userRef, {
        uid: user.uid,
        displayName: user.displayName,
        photoURL: user.photoURL,
        lastSeen: serverTimestamp(),
      }, { merge: true });
    };
  }, [user]);

  useEffect(() => {
    const unsubscribe = onSnapshot(collection(db, 'presence'), (snapshot) => {
      const activeUsers = [];
      snapshot.forEach((doc) => {
        activeUsers.push(doc.data());
      });
      setUsers(activeUsers);
    });

    return () => unsubscribe();
  }, []);

  return (
    <div className="user-presence">
      <h4>Active Users ({users.length})</h4>
      <div className="user-list">
        {users.map((user) => (
          <div key={user.uid} className="user-avatar" title={user.displayName}>
            <img src={user.photoURL} alt={user.displayName} />
          </div>
        ))}
      </div>
    </div>
  );
};

export default UserPresence;
```

### 8. Navbar.jsx (Navigation Bar)

```javascript
import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { auth, provider } from '../firebase';
import { signInWithPopup, signOut } from 'firebase/auth';

const Navbar = () => {
  const { user } = useAuth();

  const handleLogin = async () => {
    try {
      await signInWithPopup(auth, provider);
    } catch (error) {
      console.error('Error signing in:', error);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error('Error signing out:', error);
    }
  };

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <Link to="/" className="logo">
          <h1>TaskBoard</h1>
        </Link>
        <div className="nav-links">
          {user ? (
            <>
              <span className="user-info">
                <img src={user.photoURL} alt={user.displayName} className="user-avatar" />
                {user.displayName}
              </span>
              <button onClick={handleLogout} className="logout-btn">Logout</button>
            </>
          ) : (
            <button onClick={handleLogin} className="login-btn">Login with Google</button>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
```

