### 3. Board.jsx (Main Board Component)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useFirestore } from '../hooks/useFirestore';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const { user } = useAuth();
  const { data: columns, updateData: updateColumns } = useFirestore('columns');
  const [selectedTask, setSelectedTask] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    if (type === 'column') {
      const newColumnOrder = Array.from(columns.columnOrder);
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, draggableId);

      updateColumns({
        ...columns,
        columnOrder: newColumnOrder
      });
      return;
    }

    const startColumn = columns.columns[source.droppableId];
    const finishColumn = columns.columns[destination.droppableId];

    if (startColumn === finishColumn) {
      const newTaskIds = Array.from(startColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...startColumn,
        taskIds: newTaskIds
      };

      updateColumns({
        ...columns,
        columns: {
          ...columns.columns,
          [newColumn.id]: newColumn
        }
      });
      return;
    }

    // Moving from one column to another
    const startTaskIds = Array.from(startColumn.taskIds);
    startTaskIds.splice(source.index, 1);
    const newStartColumn = {
      ...startColumn,
      taskIds: startTaskIds
    };

    const finishTaskIds = Array.from(finishColumn.taskIds);
    finishTaskIds.splice(destination.index, 0, draggableId);
    const newFinishColumn = {
      ...finishColumn,
      taskIds: finishTaskIds
    };

    updateColumns({
      ...columns,
      columns: {
        ...columns.columns,
        [newStartColumn.id]: newStartColumn,
        [newFinishColumn.id]: newFinishColumn
      }
    });
  };

  const handleTaskClick = (taskId, columnId) => {
    const task = columns.tasks[taskId];
    setSelectedTask({ ...task, columnId });
    setIsModalOpen(true);
  };

  const handleAddTask = (columnId) => {
    const newTaskId = `task-${Date.now()}`;
    const newTask = {
      id: newTaskId,
      content: 'New Task',
      description: '',
      assignee: user.uid,
      createdAt: new Date().toISOString()
    };

    const column = columns.columns[columnId];
    const newTaskIds = [...column.taskIds, newTaskId];

    updateColumns({
      ...columns,
      tasks: {
        ...columns.tasks,
        [newTaskId]: newTask
      },
      columns: {
        ...columns.columns,
        [columnId]: {
          ...column,
          taskIds: newTaskIds
        }
      }
    });
  };

  const handleAddColumn = () => {
    const newColumnId = `column-${Date.now()}`;
    const newColumn = {
      id: newColumnId,
      title: 'New Column',
      taskIds: []
    };

    updateColumns({
      ...columns,
      columns: {
        ...columns.columns,
        [newColumnId]: newColumn
      },
      columnOrder: [...columns.columnOrder, newColumnId]
    });
  };

  if (!columns) return <div>Loading...</div>;

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable
          droppableId="all-columns"
          direction="horizontal"
          type="column"
        >
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns.columnOrder.map((columnId, index) => {
                const column = columns.columns[columnId];
                const tasks = column.taskIds.map(taskId => columns.tasks[taskId]);

                return (
                  <Column
                    key={column.id}
                    column={column}
                    tasks={tasks}
                    index={index}
                    onTaskClick={handleTaskClick}
                    onAddTask={handleAddTask}
                  />
                );
              })}
              {provided.placeholder}
              <button
                className="add-column-btn"
                onClick={handleAddColumn}
              >
                + Add Column
              </button>
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={selectedTask}
          onClose={() => setIsModalOpen(false)}
          updateColumns={updateColumns}
          columns={columns}
        />
      )}
    </div>
  );
};

export default Board;
```

