import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const TaskModal = ({ task, onClose, updateColumns, columns }) => {
  const { user } = useAuth();
  const [editedTask, setEditedTask] = useState({ ...task });
  const [users, setUsers] = useState([]);

  useEffect(() => {
    // In a real app, you would fetch users from your database
    // This is a mock implementation
    setUsers([
      { id: user.uid, name: user.displayName || 'You', email: user.email },
      // Add more users as needed
    ]);
  }, [user]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setEditedTask(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleAssigneeChange = (e) => {
    setEditedTask(prev => ({
      ...prev,
      assignee: e.target.value
    }));
  };

  const handleSave = () => {
    const updatedTasks = {
      ...columns.tasks,
      [editedTask.id]: editedTask
    };

    updateColumns({
      ...columns,
      tasks: updatedTasks
    });
    onClose();
  };

  const handleDelete = () => {
    const column = columns.columns[editedTask.columnId];
    const newTaskIds = column.taskIds.filter(id => id !== editedTask.id);

    const updatedColumns = {
      ...columns.columns,
      [editedTask.columnId]: {
        ...column,
        taskIds: newTaskIds
      }
    };

    const updatedTasks = { ...columns.tasks };
    delete updatedTasks[editedTask.id];

    updateColumns({
      ...columns,
      columns: updatedColumns,
      tasks: updatedTasks
    });

    onClose();
  };

  return (
    <div className="modal-overlay">
      <div className="modal">
        <div className="modal-header">
          <h2>Task Details</h2>
          <button className="close-btn" onClick={onClose}>×</button>
