### 7. useFirestore.js (Custom Hook for Firestore)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { doc, onSnapshot, updateDoc } from 'firebase/firestore';

export const useFirestore = (collectionName) => {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const docRef = doc(db, collectionName, 'boardData');

    const unsubscribe = onSnapshot(docRef, (doc) => {
      if (doc.exists()) {
        setData(doc.data());
      } else {
        // Initialize with default data if document doesn't exist
        const defaultData = {
          tasks: {},
          columns: {
            'column-1': {
              id: 'column-1',
              title: 'To Do',
              taskIds: []
            },
            'column-2': {
              id: 'column-2',
              title: 'In Progress',
              taskIds: []
            },
            'column-3': {
              id: 'column-3',
              title: 'Done',
              taskIds: []
            }
          },
          columnOrder: ['column-1', 'column-2', 'column-3']
        };
        setData(defaultData);
      }
    }, (err) => {
      setError(err.message);
    });

    return () => unsubscribe();
  }, [collectionName]);

  const updateData = async (newData) => {
    try {
      const docRef = doc(db, collectionName, 'boardData');
      await updateDoc(docRef, newData);
    } catch (err) {
      setError(err.message);
    }
  };

  return { data, error, updateData };
};
```

### 8. AuthContext.jsx (Authentication Context)

```javascript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth, provider } from '../firebase';
import { signInWithPopup, signOut, onAuthStateChanged } from 'firebase/auth';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const login = () => {
    return signInWithPopup(auth, provider);
  };

  const logout = () => {
    return signOut(auth);
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setUser(user);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    user,
    login,
    logout
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  return useContext(AuthContext);
};
```

