```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useTasks } from '../../hooks/useTasks';
import { useAuth } from '../../context/AuthContext';

const Board = () => {
  const { currentUser } = useAuth();
  const { tasks, loading, addTask, updateTask } = useTasks(currentUser?.uid);
  const [newTaskTitle, setNewTaskTitle] = useState('');

  const columns = [
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
  ];

  const onDragEnd = (result) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId === destination.droppableId) {
      // Reordering within the same column
      const columnTasks = tasks.filter(task => task.columnId === source.droppableId);
      const [removed] = columnTasks.splice(source.index, 1);
      columnTasks.splice(destination.index, 0, removed);

      // Update all tasks in the column with new positions
      columnTasks.forEach((task, index) => {
        updateTask(task.id, { position: index });
      });
    } else {
      // Moving to a different column
      const sourceTasks = tasks.filter(task => task.columnId === source.droppableId);
      const destTasks = tasks.filter(task => task.columnId === destination.droppableId);

      const [removed] = sourceTasks.splice(source.index, 1);
      destTasks.splice(destination.index, 0, { ...removed, columnId: destination.droppableId });

      // Update the moved task
      updateTask(removed.id, {
        columnId: destination.droppableId,
        position: destination.index
      });

      // Update positions in source column
      sourceTasks.forEach((task, index) => {
        updateTask(task.id, { position: index });
      });

      // Update positions in destination column
      destTasks.forEach((task, index) => {
        updateTask(task.id, { position: index });
      });
    }
  };

  const handleAddTask = (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    addTask({
      title: newTaskTitle,
      columnId: 'todo',
      position: tasks.filter(task => task.columnId === 'todo').length
    });

    setNewTaskTitle('');
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="board-container">
      <form onSubmit={handleAddTask} className="add-task-form">
        <input
          type="text"
          value={newTaskTitle}
          onChange={(e) => setNewTaskTitle(e.target.value)}
          placeholder="Add a new task..."
        />
        <button type="submit">Add Task</button>
      </form>

      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.columnId === column.id)}
              updateTask={updateTask}
            />
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

