### 2. Authentication Context (context/AuthContext.js)

```javascript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth, provider } from '../firebase/firebase';
import { signInWithPopup, signOut, onAuthStateChanged } from 'firebase/auth';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const signInWithGoogle = async () => {
    try {
      await signInWithPopup(auth, provider);
    } catch (error) {
      console.error("Error signing in with Google", error);
    }
  };

  const logout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error("Error signing out", error);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setUser(user);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return (
    <AuthContext.Provider value={{ user, signInWithGoogle, logout }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
```

### 3. Task Hook (hooks/useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  doc,
  deleteDoc
} from 'firebase/firestore';

export const useTasks = (projectId) => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!projectId) return;

    const q = query(
      collection(db, 'tasks'),
      where('projectId', '==', projectId)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      querySnapshot.forEach((doc) => {
        tasksData.push({ id: doc.id, ...doc.data() });
      });
      setTasks(tasksData);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [projectId]);

  const addTask = async (task) => {
    try {
      await addDoc(collection(db, 'tasks'), task);
    } catch (error) {
      console.error("Error adding task: ", error);
    }
  };

  const updateTask = async (taskId, updates) => {
    try {
      const taskRef = doc(db, 'tasks', taskId);
      await updateDoc(taskRef, updates);
    } catch (error) {
      console.error("Error updating task: ", error);
    }
  };

  const deleteTask = async (taskId) => {
    try {
      await deleteDoc(doc(db, 'tasks', taskId));
    } catch (error) {
      console.error("Error deleting task: ", error);
    }
  };

  return { tasks, loading, addTask, updateTask, deleteTask };
};
```

### 4. Board Component (components/Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskForm from './TaskForm';
import { useTasks } from '../hooks/useTasks';

const Board = ({ projectId }) => {
  const { tasks, loading, addTask, updateTask, deleteTask } = useTasks(projectId);
  const [showForm, setShowForm] = useState(false);
  const [selectedTask, setSelectedTask] = useState(null);

  const columns = ['To Do', 'In Progress', 'Review', 'Done'];

  const onDragEnd = (result) => {
    if (!result.destination) return;

    const { source, destination } = result;

    if (source.droppableId === destination.droppableId) {
      // Reordering within the same column
      const columnTasks = tasks.filter(task => task.status === source.droppableId);
      const [removed] = columnTasks.splice(source.index, 1);
      columnTasks.splice(destination.index, 0, removed);

      // Update all tasks in the column
      columnTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });
    } else {
      // Moving to a different column
      const sourceTasks = tasks.filter(task => task.status === source.droppableId);
      const [movedTask] = sourceTasks.splice(source.index, 1);

      const destinationTasks = tasks.filter(task => task.status === destination.droppableId);
      destinationTasks.splice(destination.index, 0, movedTask);

      // Update the moved task's status and order
      updateTask(movedTask.id, {
        status: destination.droppableId,
        order: destination.index
      });

      // Update orders in both columns
      sourceTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });

      destinationTasks.forEach((task, index) => {
        updateTask(task.id, { order: index });
      });
    }
  };

  const handleAddTask = (task) => {
    addTask({
      ...task,
      projectId,
      status: 'To Do',
      order: tasks.filter(t => t.status === 'To Do').length,
      createdAt: new Date().toISOString()
    });
    setShowForm(false);
  };

  const handleEditTask = (task) => {
    setSelectedTask(task);
    setShowForm(true);
  };

  const handleUpdateTask = (updatedTask) => {
    updateTask(selectedTask.id, updatedTask);
    setShowForm(false);
    setSelectedTask(null);
  };

  if (loading) return <div>Loading tasks...</div>;

  return (
    <div className="board">
      <button onClick={() => { setShowForm(true); setSelectedTask(null); }}>
        Add New Task
      </button>

      {showForm && (
        <TaskForm
          onSubmit={selectedTask ? handleUpdateTask : handleAddTask}
          onCancel={() => { setShowForm(false); setSelectedTask(null); }}
          initialData={selectedTask}
        />
      )}

      <DragDropContext onDragEnd={onDragEnd}>
        <div className="columns-container">
          {columns.map((column) => (
            <Droppable key={column} droppableId={column}>
              {(provided) => (
                <div
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                  className="column"
                >
                  <Column
                    title={column}
                    tasks={tasks.filter(task => task.status === column).sort((a, b) => a.order - b.order)}
                    onEditTask={handleEditTask}
                    onDeleteTask={deleteTask}
                  />
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

