### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useTasks } from '../hooks/useTasks';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const { currentUser } = useAuth();
  const [projectId, setProjectId] = useState('default-project');
  const { tasks, loading, addTask, updateTask } = useTasks(projectId);
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  useEffect(() => {
    if (!loading) {
      const newColumns = { ...columns };
      Object.keys(newColumns).forEach(columnId => {
        newColumns[columnId].taskIds = tasks
          .filter(task => task.status === columnId)
          .map(task => task.id);
      });
      setColumns(newColumns);
    }
  }, [tasks, loading]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const startColumn = columns[source.droppableId];
    const finishColumn = columns[destination.droppableId];

    if (startColumn === finishColumn) {
      const newTaskIds = Array.from(startColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...startColumn,
        taskIds: newTaskIds
      };

      setColumns({
        ...columns,
        [newColumn.id]: newColumn
      });
    } else {
      const startTaskIds = Array.from(startColumn.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...startColumn,
        taskIds: startTaskIds
      };

      const finishTaskIds = Array.from(finishColumn.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finishColumn,
        taskIds: finishTaskIds
      };

      setColumns({
        ...columns,
        [newStart.id]: newStart,
        [newFinish.id]: newFinish
      });

      // Update task status in database
      updateTask(draggableId, { status: destination.droppableId });
    }
  };

  const handleAddTask = (title, description) => {
    addTask({
      title,
      description,
      status: 'todo',
      projectId,
      createdBy: currentUser.uid,
      createdAt: new Date().toISOString(),
      assignee: null,
      priority: 'medium'
    });
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board-columns">
          {Object.values(columns).map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.status === column.id)}
              onAddTask={handleAddTask}
            />
          ))}
        </div>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

### 6. Column Component (components/Column.jsx)

```javascript
import React, { useState } from 'react';
import { Droppable } from 'react-beautiful-dnd';
import Task from './Task';
import TaskModal from './TaskModal';

const Column = ({ column, tasks, onAddTask }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);

  return (
    <div className="column">
      <h3>{column.title}</h3>
      <Droppable droppableId={column.id}>
        {(provided, snapshot) => (
          <div
            ref={provided.innerRef}
            {...provided.droppableProps}
            className={`tasks-container ${snapshot.isDraggingOver ? 'dragging-over' : ''}`}
          >
            {tasks.map((task, index) => (
              <Task key={task.id} task={task} index={index} />
            ))}
            {provided.placeholder}
          </div>
        )}
      </Droppable>
      <button
        className="add-task-btn"
        onClick={() => setIsModalOpen(true)}
      >
        + Add Task
      </button>

      {isModalOpen && (
        <TaskModal
          onClose={() => setIsModalOpen(false)}
          onSubmit={(title, description) => {
            onAddTask(title, description);
            setIsModalOpen(false);
          }}
        />
      )}
    </div>
  );
};

export default Column;
```

