### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useTasks } from '../hooks/useTasks';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const { user } = useAuth();
  const [projectId, setProjectId] = useState('default-project');
  const { tasks, loading, addTask, updateTask, deleteTask, updateTaskOrder } = useTasks(projectId);
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  useEffect(() => {
    if (!loading) {
      const newColumns = { ...columns };
      Object.keys(newColumns).forEach(columnId => {
        newColumns[columnId].taskIds = tasks
          .filter(task => task.columnId === columnId)
          .sort((a, b) => a.order - b.order)
          .map(task => task.id);
      });
      setColumns(newColumns);
    }
  }, [tasks, loading]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      setColumns({
        ...columns,
        [newColumn.id]: newColumn,
      });

      updateTaskOrder(newColumn.id, newTaskIds);
    } else {
      const startTaskIds = Array.from(start.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...start,
        taskIds: startTaskIds,
      };

      const finishTaskIds = Array.from(finish.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finish,
        taskIds: finishTaskIds,
      };

      setColumns({
        ...columns,
        [newStart.id]: newStart,
        [newFinish.id]: newFinish,
      });

      updateTask(draggableId, {
        columnId: newFinish.id,
        order: destination.index
      });
    }
  };

  const handleAddTask = (columnId) => {
    const newTask = {
      title: 'New Task',
      description: '',
      columnId,
      order: columns[columnId].taskIds.length,
      projectId,
      createdBy: user.uid,
      createdAt: new Date().toISOString(),
      assignees: []
    };
    addTask(newTask);
  };

  return (
    <div className="board-container">
      <h1>Project Management Board</h1>
      <div className="user-info">
        <span>Logged in as: {user.displayName}</span>
        <button onClick={() => auth.signOut()}>Logout</button>
      </div>

      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable
          droppableId="board"
          direction="horizontal"
          type="column"
        >
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {Object.values(columns).map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  tasks={tasks.filter(task => task.columnId === column.id)}
                  index={index}
                  onAddTask={handleAddTask}
                  onUpdateTask={updateTask}
                  onDeleteTask={deleteTask}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

