### 3. Board Component (components/Board/Board.js)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { db } from '../../firebase/firebase';
import { collection, doc, onSnapshot, updateDoc, addDoc } from 'firebase/firestore';
import { useAuth } from '../../context/AuthContext';

const Board = () => {
  const [columns, setColumns] = useState({});
  const [tasks, setTasks] = useState({});
  const { currentUser } = useAuth();

  useEffect(() => {
    if (!currentUser) return;

    const unsubscribeColumns = onSnapshot(
      collection(db, `users/${currentUser.uid}/columns`),
      (snapshot) => {
        const columnsData = {};
        snapshot.forEach((doc) => {
          columnsData[doc.id] = { id: doc.id, ...doc.data() };
        });
        setColumns(columnsData);
      }
    );

    const unsubscribeTasks = onSnapshot(
      collection(db, `users/${currentUser.uid}/tasks`),
      (snapshot) => {
        const tasksData = {};
        snapshot.forEach((doc) => {
          tasksData[doc.id] = { id: doc.id, ...doc.data() };
        });
        setTasks(tasksData);
      }
    );

    return () => {
      unsubscribeColumns();
      unsubscribeTasks();
    };
  }, [currentUser]);

  const onDragEnd = async (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    if (type === 'column') {
      const newColumnOrder = Array.from(Object.keys(columns));
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, draggableId);

      const batch = [];
      newColumnOrder.forEach((columnId, index) => {
        batch.push(updateDoc(doc(db, `users/${currentUser.uid}/columns`, columnId), {
          order: index
        }));
      });

      await Promise.all(batch);
      return;
    }

    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      await updateDoc(doc(db, `users/${currentUser.uid}/columns`, newColumn.id), {
        taskIds: newTaskIds
      });
    } else {
      const startTaskIds = Array.from(start.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...start,
        taskIds: startTaskIds,
      };

      const finishTaskIds = Array.from(finish.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finish,
        taskIds: finishTaskIds,
      };

      await Promise.all([
        updateDoc(doc(db, `users/${currentUser.uid}/columns`, newStart.id), {
          taskIds: startTaskIds
        }),
        updateDoc(doc(db, `users/${currentUser.uid}/columns`, newFinish.id), {
          taskIds: finishTaskIds
        }),
        updateDoc(doc(db, `users/${currentUser.uid}/tasks`, draggableId), {
          columnId: newFinish.id
        })
      ]);
    }
  };

  const addColumn = async () => {
    const columnName = prompt('Enter column name:');
    if (!columnName) return;

    const newColumnRef = await addDoc(collection(db, `users/${currentUser.uid}/columns`), {
      title: columnName,
      taskIds: [],
      order: Object.keys(columns).length
    });

    setColumns({
      ...columns,
      [newColumnRef.id]: {
        id: newColumnRef.id,
        title: columnName,
        taskIds: [],
        order: Object.keys(columns).length
      }
    });
  };

  const addTask = async (columnId) => {
    const taskContent = prompt('Enter task content:');
    if (!taskContent) return;

    const newTaskRef = await addDoc(collection(db, `users/${currentUser.uid}/tasks`), {
      content: taskContent,
      columnId: columnId
    });

    const column = columns[columnId];
    const newTaskIds = Array.from(column.taskIds);
    newTaskIds.push(newTaskRef.id);

    await updateDoc(doc(db, `users/${currentUser.uid}/columns`, columnId), {
      taskIds: newTaskIds
    });

    setTasks({
      ...tasks,
      [newTaskRef.id]: {
        id: newTaskRef.id,
        content: taskContent,
        columnId: columnId
      }
    });
  };

  const sortedColumns = Object.values(columns).sort((a, b) => a.order - b.order);

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {sortedColumns.map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  tasks={tasks}
                  index={index}
                  addTask={addTask}
                />
              ))}
              {provided.placeholder}
              <button className="add-column-btn" onClick={addColumn}>
                + Add Column
              </button>
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

