### 2. Authentication Context (context/AuthContext.js)

```javascript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth } from '../firebase/firebase';
import { onAuthStateChanged } from 'firebase/auth';

const AuthContext = createContext();

export function useAuth() {
  return useContext(AuthContext);
}

export function AuthProvider({ children }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setCurrentUser(user);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    currentUser,
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}
```

### 3. Task Hook (hooks/useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import {
  collection,
  query,
  where,
  onSnapshot,
  addDoc,
  updateDoc,
  doc,
  deleteDoc
} from 'firebase/firestore';

export function useTasks(userId) {
  const [tasks, setTasks] = useState([]);
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  useEffect(() => {
    if (!userId) return;

    const q = query(collection(db, 'tasks'), where('userId', '==', userId));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      const newColumns = { ...columns };

      // Reset columns
      Object.keys(newColumns).forEach(columnId => {
        newColumns[columnId].taskIds = [];
      });

      querySnapshot.forEach((doc) => {
        const task = { id: doc.id, ...doc.data() };
        tasksData.push(task);
        newColumns[task.status].taskIds.push(task.id);
      });

      setTasks(tasksData);
      setColumns(newColumns);
    });

    return () => unsubscribe();
  }, [userId]);

  const addTask = async (title, description, status = 'todo') => {
    await addDoc(collection(db, 'tasks'), {
      title,
      description,
      status,
      userId,
      createdAt: new Date().toISOString()
    });
  };

  const updateTask = async (taskId, updates) => {
    const taskRef = doc(db, 'tasks', taskId);
    await updateDoc(taskRef, updates);
  };

  const deleteTask = async (taskId) => {
    await deleteDoc(doc(db, 'tasks', taskId));
  };

  const moveTask = async (taskId, newStatus) => {
    const taskRef = doc(db, 'tasks', taskId);
    await updateDoc(taskRef, { status: newStatus });
  };

  return { tasks, columns, addTask, updateTask, deleteTask, moveTask };
}
```

### 4. Board Components

#### Board.js

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from '../TaskModal';
import { useTasks } from '../../hooks/useTasks';
import { useAuth } from '../../context/AuthContext';

const Board = () => {
  const { currentUser } = useAuth();
  const { tasks, columns, addTask, updateTask, deleteTask, moveTask } = useTasks(currentUser?.uid);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentTask, setCurrentTask] = useState(null);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    moveTask(draggableId, destination.droppableId);
  };

  const handleAddTask = (title, description) => {
    addTask(title, description);
    setIsModalOpen(false);
  };

  const handleEditTask = (taskId, updates) => {
    updateTask(taskId, updates);
    setIsModalOpen(false);
    setCurrentTask(null);
  };

  const handleDeleteTask = (taskId) => {
    deleteTask(taskId);
    setIsModalOpen(false);
    setCurrentTask(null);
  };

  return (
    <div className="board-container">
      <button
        className="add-task-btn"
        onClick={() => {
          setCurrentTask(null);
          setIsModalOpen(true);
        }}
      >
        Add New Task
      </button>

      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable
          droppableId="board"
          direction="horizontal"
          type="column"
        >
          {(provided) => (
            <div
              className="board"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {Object.entries(columns).map(([columnId, column], index) => (
                <Column
                  key={columnId}
                  column={column}
                  tasks={tasks.filter(task => task.status === columnId)}
                  index={index}
                  onEditTask={(task) => {
                    setCurrentTask(task);
                    setIsModalOpen(true);
                  }}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      <TaskModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={currentTask ? handleEditTask : handleAddTask}
        task={currentTask}
        onDelete={currentTask ? handleDeleteTask : null}
      />
    </div>
  );
};

export default Board;
```

