### 2. Authentication Context (context/AuthContext.js)

```javascript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth, provider } from '../firebase/firebase';
import { signInWithPopup, signOut, onAuthStateChanged } from 'firebase/auth';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  const signInWithGoogle = async () => {
    try {
      await signInWithPopup(auth, provider);
    } catch (error) {
      console.error("Error signing in with Google", error);
    }
  };

  const logout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error("Error signing out", error);
    }
  };

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (user) => {
      setUser(user);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return (
    <AuthContext.Provider value={{ user, signInWithGoogle, logout }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => useContext(AuthContext);
```

### 3. Task Hook (hooks/useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import {
  collection,
  query,
  onSnapshot,
  doc,
  addDoc,
  updateDoc,
  deleteDoc,
  orderBy
} from 'firebase/firestore';

export const useTasks = (projectId) => {
  const [tasks, setTasks] = useState([]);
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  useEffect(() => {
    if (!projectId) return;

    const tasksQuery = query(
      collection(db, `projects/${projectId}/tasks`),
      orderBy('createdAt')
    );

    const unsubscribe = onSnapshot(tasksQuery, (snapshot) => {
      const tasksData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));

      // Update tasks state
      setTasks(tasksData);

      // Update columns based on task status
      const newColumns = { ...columns };
      Object.keys(newColumns).forEach(columnId => {
        newColumns[columnId].taskIds = tasksData
          .filter(task => task.status === columnId)
          .map(task => task.id);
      });

      setColumns(newColumns);
    });

    return () => unsubscribe();
  }, [projectId]);

  const addTask = async (title, description = '', status = 'todo', assignee = null) => {
    if (!projectId) return;

    try {
      await addDoc(collection(db, `projects/${projectId}/tasks`), {
        title,
        description,
        status,
        assignee,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Error adding task: ", error);
    }
  };

  const updateTask = async (taskId, updates) => {
    if (!projectId) return;

    try {
      const taskRef = doc(db, `projects/${projectId}/tasks`, taskId);
      await updateDoc(taskRef, {
        ...updates,
        updatedAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Error updating task: ", error);
    }
  };

  const deleteTask = async (taskId) => {
    if (!projectId) return;

    try {
      await deleteDoc(doc(db, `projects/${projectId}/tasks`, taskId));
    } catch (error) {
      console.error("Error deleting task: ", error);
    }
  };

  const moveTask = async (taskId, newStatus) => {
    if (!projectId) return;

    try {
      const taskRef = doc(db, `projects/${projectId}/tasks`, taskId);
      await updateDoc(taskRef, {
        status: newStatus,
        updatedAt: new Date().toISOString()
      });
    } catch (error) {
      console.error("Error moving task: ", error);
    }
  };

  return { tasks, columns, addTask, updateTask, deleteTask, moveTask };
};
```

### 4. Main Board Component (components/Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useTasks } from '../hooks/useTasks';

const Board = ({ projectId }) => {
  const { tasks, columns, addTask, updateTask, deleteTask, moveTask } = useTasks(projectId);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState(null);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    // If dropped outside a column
    if (!destination) return;

    // If dropped in the same position
    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    // Move task to new column
    moveTask(draggableId, destination.droppableId);
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleAddTask = (title) => {
    addTask(title);
  };

  const handleUpdateTask = (updates) => {
    if (selectedTask) {
      updateTask(selectedTask.id, updates);
      setIsModalOpen(false);
    }
  };

  const handleDeleteTask = () => {
    if (selectedTask) {
      deleteTask(selectedTask.id);
      setIsModalOpen(false);
    }
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board-columns">
          {Object.values(columns).map((column) => (
            <Droppable key={column.id} droppableId={column.id}>
              {(provided) => (
                <div
                  ref={provided.innerRef}
                  {...provided.droppableProps}
                  className="column-container"
                >
                  <Column
                    column={column}
                    tasks={tasks.filter(task => task.status === column.id)}
                    onTaskClick={handleTaskClick}
                  />
                  {provided.placeholder}
                </div>
              )}
            </Droppable>
          ))}
        </div>
      </DragDropContext>

      <button className="add-task-btn" onClick={() => handleAddTask('New Task')}>
        + Add Task
      </button>

      {isModalOpen && selectedTask && (
        <TaskModal
          task={selectedTask}
          onClose={() => setIsModalOpen(false)}
          onUpdate={handleUpdateTask}
          onDelete={handleDeleteTask}
        />
      )}
    </div>
  );
};

export default Board;
```

