### 7. Task Modal (components/TaskModal.jsx)

```javascript
import React, { useState } from 'react';

const TaskModal = ({ task, onClose, onUpdate, onDelete }) => {
  const [title, setTitle] = useState(task.title);
  const [description, setDescription] = useState(task.description || '');
  const [status, setStatus] = useState(task.status);
  const [assignee, setAssignee] = useState(task.assignee || null);

  const handleSubmit = (e) => {
    e.preventDefault();
    onUpdate({ title, description, status, assignee });
  };

  return (
    <div className="modal-overlay">
      <div className="modal">
        <button className="close-btn" onClick={onClose}>×</button>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Title</label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Description</label>
            <textarea
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          <div className="form-group">
            <label>Status</label>
            <select
              value={status}
              onChange={(e) => setStatus(e.target.value)}
            >
              <option value="todo">To Do</option>
              <option value="in-progress">In Progress</option>
              <option value="done">Done</option>
            </select>
          </div>

          <div className="form-group">
            <label>Assignee</label>
            <input
              type="text"
              value={assignee ? assignee.name : ''}
              onChange={(e) => setAssignee({ name: e.target.value })}
              placeholder="Enter assignee name"
            />
          </div>

          <div className="modal-actions">
            <button type="button" className="delete-btn" onClick={onDelete}>
              Delete Task
            </button>
            <button type="submit" className="save-btn">
              Save Changes
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TaskModal;
```

