### 2. Auth Context (context/AuthContext.js)

```javascript
import React, { createContext, useContext, useEffect, useState } from 'react';
import { auth, googleProvider } from '../firebase';

const AuthContext = createContext();

export function useAuth() {
  return useContext(AuthContext);
}

export function AuthProvider({ children }) {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);

  function signup(email, password) {
    return auth.createUserWithEmailAndPassword(email, password);
  }

  function login(email, password) {
    return auth.signInWithEmailAndPassword(email, password);
  }

  function logout() {
    return auth.signOut();
  }

  function loginWithGoogle() {
    return auth.signInWithPopup(googleProvider);
  }

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(user => {
      setCurrentUser(user);
      setLoading(false);
    });

    return unsubscribe;
  }, []);

  const value = {
    currentUser,
    signup,
    login,
    logout,
    loginWithGoogle
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
}
```

### 3. Firestore Hook (hooks/useFirestore.js)

```javascript
import { useState, useEffect } from 'react';
import { firestore } from '../firebase';

export function useFirestore(collectionName) {
  const [docs, setDocs] = useState([]);

  useEffect(() => {
    const unsubscribe = firestore.collection(collectionName)
      .orderBy('createdAt', 'desc')
      .onSnapshot(snapshot => {
        const documents = [];
        snapshot.forEach(doc => {
          documents.push({ id: doc.id, ...doc.data() });
        });
        setDocs(documents);
      });

    return () => unsubscribe();
  }, [collectionName]);

  return docs;
}

export function useBoard(boardId) {
  const [board, setBoard] = useState(null);

  useEffect(() => {
    if (!boardId) return;

    const unsubscribe = firestore.collection('boards').doc(boardId)
      .onSnapshot(doc => {
        setBoard({ id: doc.id, ...doc.data() });
      });

    return () => unsubscribe();
  }, [boardId]);

  return board;
}
```

