### 5. Board Component (components/Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useBoard } from '../hooks/useFirestore';
import { firestore } from '../firebase';

const Board = ({ boardId }) => {
  const [columns, setColumns] = useState([]);
  const [selectedTask, setSelectedTask] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const board = useBoard(boardId);

  useEffect(() => {
    if (board) {
      setColumns(board.columns || []);
    }
  }, [board]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    ) {
      return;
    }

    if (type === 'column') {
      const newColumnOrder = Array.from(columns);
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, columns[source.index]);

      setColumns(newColumnOrder);
      return;
    }

    const startColumn = columns.find(column => column.id === source.droppableId);
    const finishColumn = columns.find(column => column.id === destination.droppableId);

    if (startColumn === finishColumn) {
      const newTaskIds = Array.from(startColumn.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...startColumn,
        taskIds: newTaskIds
      };

      const newColumns = columns.map(column =>
        column.id === newColumn.id ? newColumn : column
      );

      setColumns(newColumns);
    } else {
      const startTaskIds = Array.from(startColumn.taskIds);
      startTaskIds.splice(source.index, 1);
      const newStart = {
        ...startColumn,
        taskIds: startTaskIds
      };

      const finishTaskIds = Array.from(finishColumn.taskIds);
      finishTaskIds.splice(destination.index, 0, draggableId);
      const newFinish = {
        ...finishColumn,
        taskIds: finishTaskIds
      };

      const newColumns = columns.map(column => {
        if (column.id === newStart.id) return newStart;
        if (column.id === newFinish.id) return newFinish;
        return column;
      });

      setColumns(newColumns);
    }

    // Update in Firestore
    firestore.collection('boards').doc(boardId).update({
      columns: columns
    });
  };

  const handleTaskClick = (task) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const handleAddTask = (columnId) => {
    const newTask = {
      id: `task-${Date.now()}`,
      title: 'New Task',
      description: '',
      status: columnId,
      createdAt: new Date(),
      assignee: null
    };

    const column = columns.find(col => col.id === columnId);
    const newTaskIds = [...column.taskIds, newTask.id];

    const newColumn = {
      ...column,
      taskIds: newTaskIds
    };

    const newColumns = columns.map(col =>
      col.id === columnId ? newColumn : col
    );

    setColumns(newColumns);

    // Add task to Firestore
    firestore.collection('tasks').doc(newTask.id).set(newTask);
    firestore.collection('boards').doc(boardId).update({
      columns: newColumns
    });
  };

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="columns-container"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {columns.map((column, index) => (
                <Column
                  key={column.id}
                  column={column}
                  index={index}
                  onTaskClick={handleTaskClick}
                  onAddTask={handleAddTask}
                />
              ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>

      {isModalOpen && (
        <TaskModal
          task={selectedTask}
          onClose={() => setIsModalOpen(false)}
        />
      )}
    </div>
  );
};

export default Board;
