### 5. Board Component (Board.jsx)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import { useFirestore } from '../hooks/useFirestore';
import { useAuth } from '../context/AuthContext';

const Board = () => {
  const { currentUser } = useAuth();
  const { docs: columns, updateDocument: updateColumn } = useFirestore('columns');
  const { docs: tasks, updateDocument: updateTask } = useFirestore('tasks');
  const [localColumns, setLocalColumns] = useState([]);

  useEffect(() => {
    setLocalColumns(columns);
  }, [columns]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    if (!destination) return;

    if (type === 'column') {
      // Reorder columns
      const newColumnOrder = Array.from(localColumns);
      const [removed] = newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, removed);

      setLocalColumns(newColumnOrder);
      // Update order in Firestore
      newColumnOrder.forEach((column, index) => {
        updateColumn(column.id, { order: index });
      });
    } else {
      // Reorder tasks within a column or between columns
      const startColumn = localColumns.find(col => col.id === source.droppableId);
      const finishColumn = localColumns.find(col => col.id === destination.droppableId);

      if (startColumn === finishColumn) {
        // Reorder within the same column
        const newTaskIds = Array.from(startColumn.taskIds);
        newTaskIds.splice(source.index, 1);
        newTaskIds.splice(destination.index, 0, draggableId);

        const newColumn = {
          ...startColumn,
          taskIds: newTaskIds
        };

        setLocalColumns(localColumns.map(col =>
          col.id === newColumn.id ? newColumn : col
        ));

        // Update task order in Firestore
        newTaskIds.forEach((taskId, index) => {
          updateTask(taskId, { order: index });
        });
      } else {
        // Move to another column
        const startTaskIds = Array.from(startColumn.taskIds);
        startTaskIds.splice(source.index, 1);
        const newStartColumn = {
          ...startColumn,
          taskIds: startTaskIds
        };

        const finishTaskIds = Array.from(finishColumn.taskIds);
        finishTaskIds.splice(destination.index, 0, draggableId);
        const newFinishColumn = {
          ...finishColumn,
          taskIds: finishTaskIds
        };

        setLocalColumns(localColumns.map(col => {
          if (col.id === newStartColumn.id) return newStartColumn;
          if (col.id === newFinishColumn.id) return newFinishColumn;
          return col;
        }));

        // Update task column and order in Firestore
        updateTask(draggableId, {
          columnId: newFinishColumn.id,
          order: destination.index
        });

        // Update task orders in both columns
        startTaskIds.forEach((taskId, index) => {
          updateTask(taskId, { order: index });
        });

        finishTaskIds.forEach((taskId, index) => {
          updateTask(taskId, { order: index });
        });
      }
    }
  };

  return (
    <div className="board-container">
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId="all-columns" direction="horizontal" type="column">
          {(provided) => (
            <div
              className="columns-container"
              {...provided.droppableProps}
              ref={provided.innerRef}
            >
              {localColumns
                .sort((a, b) => a.order - b.order)
                .map((column, index) => (
                  <Column
                    key={column.id}
                    column={column}
                    tasks={tasks.filter(task => task.columnId === column.id)}
                    index={index}
                  />
                ))}
              {provided.placeholder}
            </div>
          )}
        </Droppable>
      </DragDropContext>
    </div>
  );
};

export default Board;
```

