### 7. App Component (App.js)

```javascript
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { auth, provider } from './firebase';
import { signInWithPopup, signOut } from 'firebase/auth';
import Board from './components/Board';
import Navbar from './components/Navbar';
import './styles/styles.css';

function App() {
  const [user, setUser] = useState(null);
  const [projects, setProjects] = useState([]);
  const [currentProject, setCurrentProject] = useState(null);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged((user) => {
      setUser(user);
      if (user) {
        // Load user's projects
        // This would be implemented with Firestore queries
      }
    });

    return () => unsubscribe();
  }, []);

  const handleLogin = async () => {
    try {
      await signInWithPopup(auth, provider);
    } catch (error) {
      console.error("Error signing in: ", error);
    }
  };

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error("Error signing out: ", error);
    }
  };

  return (
    <Router>
      <div className="app">
        <Navbar
          user={user}
          onLogin={handleLogin}
          onLogout={handleLogout}
          projects={projects}
          currentProject={currentProject}
          onProjectChange={setCurrentProject}
        />

        <div className="main-content">
          {user ? (
            currentProject ? (
              <Board projectId={currentProject.id} />
            ) : (
              <div className="welcome-message">
                <h2>Welcome to Project Management</h2>
                <p>Select a project to get started</p>
              </div>
            )
          ) : (
            <div className="auth-message">
              <h2>Please sign in to access your projects</h2>
              <button onClick={handleLogin} className="btn-primary">Sign in with Google</button>
            </div>
          )}
        </div>
      </div>
    </Router>
  );
}

export default App;
