### 3. Project Context (ProjectContext.tsx)
```tsx
import React, { createContext, useContext, useState, useEffect } from 'react';
import { Project, Task, Column } from '../types';
import { getProjects, getProjectById, updateTask } from '../services/api';
import { initSocket } from '../services/socket';

interface ProjectContextType {
  projects: Project[];
  currentProject: Project | null;
  loading: boolean;
  error: string | null;
  fetchProjects: () => Promise<void>;
  fetchProject: (id: string) => Promise<void>;
  updateTask: (taskId: string, updates: Partial<Task>) => Promise<void>;
  moveTask: (taskId: string, sourceColumnId: string, destColumnId: string, index: number) => Promise<void>;
}

const ProjectContext = createContext<ProjectContextType | undefined>(undefined);

export const ProjectProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [projects, setProjects] = useState<Project[]>([]);
  const [currentProject, setCurrentProject] = useState<Project | null>(null);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const socket = initSocket();

  useEffect(() => {
    if (socket) {
      socket.on('task-updated', (updatedTask: Task) => {
        if (currentProject) {
          const updatedColumns = currentProject.columns.map(column => ({
            ...column,
            tasks: column.tasks.map(task =>
              task.id === updatedTask.id ? updatedTask : task
            )
          }));
          setCurrentProject({ ...currentProject, columns: updatedColumns });
        }
      });

      socket.on('task-moved', ({ taskId, sourceColumnId, destColumnId, index }: {
        taskId: string;
        sourceColumnId: string;
        destColumnId: string;
        index: number;
      }) => {
        if (currentProject) {
          const sourceColumn = currentProject.columns.find(c => c.id === sourceColumnId);
          const destColumn = currentProject.columns.find(c => c.id === destColumnId);

          if (sourceColumn && destColumn) {
            const taskToMove = sourceColumn.tasks.find(t => t.id === taskId);

            if (taskToMove) {
              const updatedSourceTasks = sourceColumn.tasks.filter(t => t.id !== taskId);
              const updatedDestTasks = [...destColumn.tasks];
              updatedDestTasks.splice(index, 0, taskToMove);

              const updatedColumns = currentProject.columns.map(column => {
                if (column.id === sourceColumnId) {
                  return { ...column, tasks: updatedSourceTasks };
                }
                if (column.id === destColumnId) {
                  return { ...column, tasks: updatedDestTasks };
                }
                return column;
              });

              setCurrentProject({ ...currentProject, columns: updatedColumns });
            }
          }
        }
      });

      return () => {
        socket.off('task-updated');
        socket.off('task-moved');
      };
    }
  }, [currentProject, socket]);

  const fetchProjects = async () => {
    setLoading(true);
    try {
      const data = await getProjects();
      setProjects(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch projects');
    } finally {
      setLoading(false);
    }
  };

  const fetchProject = async (id: string) => {
    setLoading(true);
    try {
      const data = await getProjectById(id);
      setCurrentProject(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch project');
    } finally {
      setLoading(false);
    }
  };

  const updateTaskHandler = async (taskId: string, updates: Partial<Task>) => {
    if (!currentProject) return;

    try {
      const updatedTask = await updateTask(taskId, updates);
      if (socket) {
        socket.emit('update-task', updatedTask);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update task');
    }
  };

  const moveTaskHandler = async (taskId: string, sourceColumnId: string, destColumnId: string, index: number) => {
    if (!currentProject) return;

    try {
      const updatedTask = await updateTask(taskId, {
        columnId: destColumnId,
        position: index
      });

      if (socket) {
        socket.emit('move-task', {
          taskId,
          sourceColumnId,
          destColumnId,
          index
        });
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to move task');
    }
  };

  return (
    <ProjectContext.Provider
      value={{
        projects,
        currentProject,
        loading,
        error,
        fetchProjects,
        fetchProject,
        updateTask: updateTaskHandler,
        moveTask: moveTaskHandler,
      }}
    >
      {children}
    </ProjectContext.Provider>
  );
};

export const useProject = () => {
  const context = useContext(ProjectContext);
  if (context === undefined) {
    throw new Error('useProject must be used within a ProjectProvider');
  }
  return context;
};
```

### 4. Board Component (Board.tsx)
```tsx
import React from 'react';
import { DragDropContext, Droppable, DropResult } from 'react-beautiful-dnd';
import Column from './Column';
import { useProject } from '../../context/ProjectContext';
import { Column as ColumnType } from '../../types';

const Board: React.FC = () => {
  const { currentProject, moveTask } = useProject();

  const onDragEnd = (result: DropResult) => {
    const { source, destination, draggableId } = result;

    // Dropped outside the list
    if (!destination) return;

    // Same position
    if (
      source.droppableId === destination.droppableId &&
      source.index === destination.index
    ) {
      return;
    }

    moveTask(draggableId, source.droppableId, destination.droppableId, destination.index);
  };

  if (!currentProject) {
    return <div>Loading project...</div>;
  }

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <Droppable droppableId="board" direction="horizontal" type="column">
        {(provided) => (
          <div
            className="board"
            {...provided.droppableProps}
            ref={provided.innerRef}
          >
            {currentProject.columns.map((column: ColumnType, index: number) => (
              <Column key={column.id} column={column} index={index} />
            ))}
            {provided.placeholder}
          </div>
        )}
      </Droppable>
    </DragDropContext>
  );
};

export default Board;
```

