### 6. Task Card Component (TaskCard.tsx)
```tsx
import React, { useState } from 'react';
import { Draggable } from 'react-beautiful-dnd';
import { Task } from '../../types';
import { useProject } from '../../context/ProjectContext';
import Modal from '../Modal';

interface TaskCardProps {
  task: Task;
  index: number;
}

const TaskCard: React.FC<TaskCardProps> = ({ task, index }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { updateTask } = useProject();

  const handleStatusChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newStatus = e.target.value;
    updateTask(task.id, { status: newStatus });
  };

  return (
    <>
      <Draggable draggableId={task.id} index={index}>
        {(provided, snapshot) => (
          <div
            className={`task-card ${snapshot.isDragging ? 'dragging' : ''}`}
            ref={provided.innerRef}
            {...provided.draggableProps}
            {...provided.dragHandleProps}
            onClick={() => setIsModalOpen(true)}
          >
            <div className="task-header">
              <h4>{task.title}</h4>
              <select
                value={task.status}
                onChange={handleStatusChange}
                onClick={(e) => e.stopPropagation()}
              >
                <option value="todo">To Do</option>
                <option value="in-progress">In Progress</option>
                <option value="done">Done</option>
              </select>
            </div>
            <p className="task-description">{task.description}</p>
            <div className="task-meta">
              <span className="task-priority">{task.priority}</span>
              <span className="task-assignee">{task.assignee?.name || 'Unassigned'}</span>
            </div>
          </div>
        )}
      </Draggable>

      {isModalOpen && (
        <Modal onClose={() => setIsModalOpen(false)}>
          <div className="task-modal">
            <h2>{task.title}</h2>
            <div className="task-modal-content">
              <p>{task.description}</p>
              <div className="task-details">
                <div>
                  <strong>Status:</strong> {task.status}
                </div>
                <div>
                  <strong>Priority:</strong> {task.priority}
                </div>
                <div>
                  <strong>Assignee:</strong> {task.assignee?.name || 'Unassigned'}
                </div>
                <div>
                  <strong>Due Date:</strong> {task.dueDate || 'Not set'}
                </div>
              </div>
            </div>
          </div>
        </Modal>
      )}
    </>
  );
};

export default TaskCard;
```

### 7. API Service (api.ts)
```typescript
import axios from 'axios';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:5000/api';

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add request interceptor for auth
api.interceptors.request.use((config) => {
  const token = localStorage.getItem('token');
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export const getProjects = async () => {
  const response = await api.get('/projects');
  return response.data;
};

export const getProjectById = async (id: string) => {
  const response = await api.get(`/projects/${id}`);
  return response.data;
};

export const createProject = async (projectData: Partial<Project>) => {
  const response = await api.post('/projects', projectData);
  return response.data;
};

export const updateProject = async (id: string, updates: Partial<Project>) => {
  const response = await api.patch(`/projects/${id}`, updates);
  return response.data;
};

export const deleteProject = async (id: string) => {
  await api.delete(`/projects/${id}`);
};

export const createTask = async (taskData: Partial<Task>) => {
  const response = await api.post('/tasks', taskData);
  return response.data;
};

export const updateTask = async (id: string, updates: Partial<Task>) => {
  const response = await api.patch(`/tasks/${id}`, updates);
  return response.data;
};

export const deleteTask = async (id: string) => {
  await api.delete(`/tasks/${id}`);
};

export default api;
```

### 8. Socket Service (socket.ts)
```typescript
import { io, Socket } from 'socket.io-client';

let socket: Socket | null = null;

export const initSocket = (): Socket | null => {
  if (!socket) {
    const SOCKET_URL = process.env.REACT_APP_SOCKET_URL || 'http://localhost:5000';
    socket = io(SOCKET_URL, {
      withCredentials: true,
      transports: ['websocket'],
    });

    socket.on('connect', () => {
      console.log('Connected to socket server');
    });

    socket.on('disconnect', () => {
      console.log('Disconnected from socket server');
    });
  }

  return socket;
};

export const disconnectSocket = () => {
  if (socket) {
    socket.disconnect();
    socket = null;
  }
};
```

