### 5. Task Controller (taskController.js)
```javascript
const Task = require('../models/Task');
const Project = require('../models/Project');

exports.createTask = async (req, res) => {
  const { title, description, status, priority, assignee, dueDate, columnId } = req.body;

  try {
    const project = await Project.findOne({
      _id: req.params.projectId,
      members: req.user.id
    });

    if (!project) {
      return res.status(404).json({ message: 'Project not found or you are not a member' });
    }

    const column = project.columns.id(columnId);
    if (!column) {
      return res.status(404).json({ message: 'Column not found' });
    }

    const task = new Task({
      title,
      description,
      status,
      priority,
      assignee,
      dueDate,
      columnId,
      projectId: req.params.projectId,
      position: column.tasks.length
    });

    const newTask = await task.save();

    // Add task reference to column
    column.tasks.push(newTask._id);
    await project.save();

    res.status(201).json(newTask);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
};

exports.updateTask = async (req, res) => {
  try {
    const task = await Task.findById(req.params.id).populate('assignee', 'name email avatar');

    if (!task) {
      return res.status(404).json({ message: 'Task not found' });
    }

    const project = await Project.findById(task.projectId);
    if (!project.members.some(member => member.id === req.user.id)) {
      return res.status(403).json({ message: 'Not authorized to update this task' });
    }

    // Handle column change if needed
    if (req.body.columnId && req.body.columnId !== task.columnId) {
      // Remove from old column
      const oldColumn = project.columns.id(task.columnId);
      if (oldColumn) {
        oldColumn.tasks = oldColumn.tasks.filter(t => t.toString() !== task._id.toString());
      }

      // Add to new column
      const newColumn = project.columns.id(req.body.columnId);
      if (newColumn) {
        newColumn.tasks.push(task._id);
      }

      task.columnId = req.body.columnId;
    }

    // Update other fields
    const updates = Object.keys(req.body);
    updates.forEach(update => task[update] = req.body[update]);

    await task.save();
    await project.save();

    res.json(task);
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
};

exports.deleteTask = async (req, res) => {
  try {
    const task = await Task.findById(req.params.id);

    if (!task) {
      return res.status(404).json({ message: 'Task not found' });
    }

    const project = await Project.findById(task.projectId);
    if (!project.members.some(member => member.id === req.user.id)) {
      return res.status(403).json({ message: 'Not authorized to delete this task' });
    }

    // Remove task from column
    const column = project.columns.id(task.columnId);
    if (column) {
      column.tasks = column.tasks.filter(t => t.toString() !== task._id.toString());
    }

    await task.remove();
    await project.save();

    res.json({ message: 'Task deleted' });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};
