### 6. Socket Service (socketService.js)
```javascript
const socketIo = require('socket.io');

let io;

const initSocket = (server) => {
  io = socketIo(server, {
    cors: {
      origin: process.env.CLIENT_URL || 'http://localhost:3000',
      methods: ['GET', 'POST'],
      credentials: true
    }
  });

  io.on('connection', (socket) => {
    console.log('New client connected');

    socket.on('join-project', (projectId) => {
      socket.join(projectId);
      console.log(`Client joined project ${projectId}`);
    });

    socket.on('update-task', (task) => {
      socket.to(task.projectId).emit('task-updated', task);
    });

    socket.on('move-task', ({ taskId, sourceColumnId, destColumnId, index }) => {
      socket.to(taskId).emit('task-moved', { taskId, sourceColumnId, destColumnId, index });
    });

    socket.on('disconnect', () => {
      console.log('Client disconnected');
    });
  });
};

const getIo = () => {
  if (!io) {
    throw new Error('Socket.io not initialized!');
  }
  return io;
};

module.exports = { initSocket, getIo };
```

