### 3. Task Hook (hooks/useTasks.js)

```javascript
import { useState, useEffect } from 'react';
import { db } from '../firebase/firebase';
import {
  collection,
  query,
  where,
  onSnapshot,
  doc,
  updateDoc,
  addDoc,
  deleteDoc
} from 'firebase/firestore';

export function useTasks(projectId) {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!projectId) return;

    const q = query(
      collection(db, 'tasks'),
      where('projectId', '==', projectId)
    );

    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      querySnapshot.forEach((doc) => {
        tasksData.push({ id: doc.id, ...doc.data() });
      });
      setTasks(tasksData);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [projectId]);

  const addTask = async (task) => {
    await addDoc(collection(db, 'tasks'), task);
  };

  const updateTask = async (taskId, updates) => {
    const taskRef = doc(db, 'tasks', taskId);
    await updateDoc(taskRef, updates);
  };

  const deleteTask = async (taskId) => {
    await deleteDoc(doc(db, 'tasks', taskId));
  };

  return { tasks, loading, addTask, updateTask, deleteTask };
}
```

### 4. Board Component (components/Board.jsx)

```javascript
import React, { useState } from 'react';
import { DragDropContext, Droppable } from 'react-beautiful-dnd';
import Column from './Column';
import TaskModal from './TaskModal';
import { useTasks } from '../hooks/useTasks';

const Board = ({ projectId }) => {
  const { tasks, loading, addTask, updateTask, deleteTask } = useTasks(projectId);
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState(null);

  // Organize tasks into columns
  React.useEffect(() => {
    if (!loading) {
      const newColumns = { ...columns };
      Object.keys(newColumns).forEach(columnId => {
        newColumns[columnId].taskIds = tasks
          .filter(task => task.status === columnId)
          .map(task => task.id);
      });
      setColumns(newColumns);
    }
  }, [tasks, loading]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    // If no destination or moved in the same place
    if (!destination || (destination.droppableId === source.droppableId && destination.index === source.index)) {
      return;
    }

    // Update task status in database
    updateTask(draggableId, { status: destination.droppableId });
  };

  const openModal = (task = null) => {
    setSelectedTask(task);
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setSelectedTask(null);
  };

  const handleSaveTask = async (taskData) => {
    if (selectedTask) {
      await updateTask(selectedTask.id, taskData);
    } else {
      await addTask({
        ...taskData,
        projectId,
        status: 'todo',
        createdAt: new Date().toISOString()
      });
    }
    closeModal();
  };

  const handleDeleteTask = async (taskId) => {
    await deleteTask(taskId);
    closeModal();
  };

  if (loading) return <div>Loading board...</div>;

  return (
    <div className="board">
      <DragDropContext onDragEnd={onDragEnd}>
        <div className="board-columns">
          {Object.values(columns).map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks.filter(task => task.status === column.id)}
              openModal={openModal}
            />
          ))}
        </div>
      </DragDropContext>

      <button className="add-task-btn" onClick={() => openModal()}>
        + Add Task
      </button>

      {isModalOpen && (
        <TaskModal
          task={selectedTask}
          onClose={closeModal}
          onSave={handleSaveTask}
          onDelete={selectedTask ? handleDeleteTask : null}
        />
      )}
    </div>
  );
};

export default Board;
```

