## JavaScript Implementation

```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize the app
    const app = new TaskBoardApp();
    app.init();
});

class TaskBoardApp {
    constructor() {
        this.columns = [];
        this.tasks = [];
        this.currentUser = 'Guest';
        this.socket = null;
        this.drake = null;
        this.modal = {
            task: document.getElementById('task-modal'),
            column: document.getElementById('column-modal')
        };
    }

    init() {
        // Load data from localStorage or create default board
        this.loadData();

        // Initialize UI
        this.initUI();

        // Initialize drag-and-drop
        this.initDragula();

        // Initialize real-time collaboration
        this.initSocketIO();

        // Set up event listeners
        this.setupEventListeners();
    }

    loadData() {
        // Try to load from localStorage
        const savedData = localStorage.getItem('taskBoardData');

        if (savedData) {
            const data = JSON.parse(savedData);
            this.columns = data.columns || [];
            this.tasks = data.tasks || [];
        } else {
            // Create default columns if no data exists
            this.columns = [
                { id: this.generateId(), title: 'To Do' },
                { id: this.generateId(), title: 'In Progress' },
                { id: this.generateId(), title: 'Done' }
            ];
            this.tasks = [];
        }
    }

    saveData() {
        const data = {
            columns: this.columns,
            tasks: this.tasks
        };
        localStorage.setItem('taskBoardData', JSON.stringify(data));
    }

    initUI() {
        // Update current user display
        document.getElementById('current-user').textContent = this.currentUser;

        // Render columns and tasks
        this.renderBoard();
    }

    renderBoard() {
        const board = document.getElementById('board');
        board.innerHTML = '';

        this.columns.forEach(column => {
            const columnElement = this.createColumnElement(column);
            board.appendChild(columnElement);
        });
    }

    createColumnElement(column) {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = column.id;

        const columnHeader = document.createElement('div');
        columnHeader.className = 'column-header';

        const columnTitle = document.createElement('h3');
        columnTitle.className = 'column-title';
        columnTitle.textContent = column.title;

        const columnActions = document.createElement('div');
        columnActions.className = 'column-actions';

        const editBtn = document.createElement('button');
        editBtn.className = 'btn secondary';
        editBtn.innerHTML = '<i class="fas fa-edit"></i>';
        editBtn.addEventListener('click', () => this.showColumnModal(column.id));

        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'btn danger';
        deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
        deleteBtn.addEventListener('click', () => this.deleteColumn(column.id));

        const addTaskBtn = document.createElement('button');
        addTaskBtn.className = 'btn primary';
        addTaskBtn.innerHTML = '<i class="fas fa-plus"></i>';
        addTaskBtn.addEventListener('click', () => this.showTaskModal(null, column.id));

        columnActions.appendChild(editBtn);
        columnActions.appendChild(deleteBtn);
        columnActions.appendChild(addTaskBtn);

        columnHeader.appendChild(columnTitle);
        columnHeader.appendChild(columnActions);

        const taskList = document.createElement('div');
        taskList.className = 'task-list';

        // Filter tasks for this column
        const columnTasks = this.tasks.filter(task => task.columnId === column.id);
        columnTasks.forEach(task => {
            const taskElement = this.createTaskElement(task);
            taskList.appendChild(taskElement);
        });

        columnElement.appendChild(columnHeader);
        columnElement.appendChild(taskList);

        return columnElement;
    }

    createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.dataset.taskId = task.id;

        const taskHeader = document.createElement('div');
        taskHeader.className = 'task-header';

        const taskTitle = document.createElement('h4');
        taskTitle.className = 'task-title';
        taskTitle.textContent = task.title;

        const taskPriority = document.createElement('span');
        taskPriority.className = `task-priority ${task.priority}`;
        taskPriority.textContent = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);

        taskHeader.appendChild(taskTitle);
        taskHeader.appendChild(taskPriority);

        const taskDescription = document.createElement('p');
        taskDescription.className = 'task-description';
        taskDescription.textContent = task.description || 'No description';

        const taskMeta = document.createElement('div');
        taskMeta.className = 'task-meta';

        const assignee = document.createElement('span');
        assignee.textContent = task.assignee || 'Unassigned';

        const dueDate = document.createElement('span');
        dueDate.textContent = task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date';

        taskMeta.appendChild(assignee);
        taskMeta.appendChild(dueDate);

        const taskActions = document.createElement('div');
        taskActions.className = 'task-actions';

        const editBtn = document.createElement('button');
        editBtn.className = 'btn secondary small';
        editBtn.innerHTML = '<i class="fas fa-edit"></i>';
        editBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.showTaskModal(task.id);
        });

        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'btn danger small';
        deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
        deleteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            this.deleteTask(task.id);
        });

        taskActions.appendChild(editBtn);
        taskActions.appendChild(deleteBtn);

        taskElement.appendChild(taskHeader);
        taskElement.appendChild(taskDescription);
        taskElement.appendChild(taskMeta);
        taskElement.appendChild(taskActions);

        // Add click event to show task details
        taskElement.addEventListener('click', () => this.showTaskModal(task.id));

        return taskElement;
    }

    initDragula() {
        const containers = document.querySelectorAll('.task-list');

        this.drake = dragula([...containers], {
            moves: (el, container, handle) => {
                // Only allow dragging of tasks, not buttons
                return el.classList.contains('task');
            },
            accepts: (el, target, source, sibling) => {
                // Allow dropping in any task list
                return target.classList.contains('task-list');
            }
        });

        this.drake.on('drop', (el, target, source, sibling) => {
            const taskId = el.dataset.taskId;
            const newColumnId = target.closest('.column').dataset.columnId;

            // Update task's column
            const taskIndex = this.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                this.tasks[taskIndex].columnId = newColumnId;

                // Save changes
                this.saveData();

                // Broadcast the change to other clients
                if (this.socket) {
                    this.socket.emit('task-moved', {
                        taskId,
                        newColumnId,
                        user: this.currentUser
                    });
                }
            }
        });
    }

    initSocketIO() {
        // Connect to Socket.io server (in a real app, this would be your server URL)
        this.socket = io('http://localhost:3000');

        this.socket.on('connect', () => {
            console.log('Connected to real-time server');
        });

        this.socket.on('task-updated', (data) => {
            // Update local task
            const taskIndex = this.tasks.findIndex(t => t.id === data.task.id);
            if (taskIndex !== -1) {
                this.tasks[taskIndex] = data.task;
            } else {
                this.tasks.push(data.task);
            }

            // Re-render the board
            this.renderBoard();

            // Reinitialize drag-and-drop
            this.initDragula();
        });

        this.socket.on('task-deleted', (taskId) => {
            // Remove task from local data
            this.tasks = this.tasks.filter(t => t.id !== taskId);

            // Re-render the board
            this.renderBoard();

            // Reinitialize drag-and-drop
            this.initDragula();
        });

        this.socket.on('task-moved', (data) => {
            // Update task's column
            const taskIndex = this.tasks.findIndex(t => t.id === data.taskId);
            if (taskIndex !== -1) {
                this.tasks[taskIndex].columnId = data.newColumnId;
            }

            // Re-render the board
            this.renderBoard();

            // Reinitialize drag-and-drop
            this.initDragula();
        });

        this.socket.on('column-updated', (data) => {
            // Update local column
            const columnIndex = this.columns.findIndex(c => c.id === data.column.id);
            if (columnIndex !== -1) {
                this.columns[columnIndex] = data.column;
            } else {
                this.columns.push(data.column);
            }

            // Re-render the board
            this.renderBoard();

            // Reinitialize drag-and-drop
            this.initDragula();
        });

        this.socket.on('column-deleted', (columnId) => {
            // Remove column and its tasks
            this.columns = this.columns.filter(c => c.id !== columnId);
            this.tasks = this.tasks.filter(t => t.columnId !== columnId);

            // Re-render the board
            this.renderBoard();

            // Reinitialize drag-and-drop
            this.initDragula();
        });
    }

    setupEventListeners() {
        // Add column button
        document.getElementById('add-column-btn').addEventListener('click', () => {
            this.showColumnModal();
        });

        // Save button
        document.getElementById('save-btn').addEventListener('click', () => {
            this.saveData();
            alert('Board saved successfully!');
        });

        // Change user button
        document.getElementById('change-user').addEventListener('click', () => {
            const newUser = prompt('Enter your name:', this.currentUser);
            if (newUser) {
                this.currentUser = newUser;
                document.getElementById('current-user').textContent = this.currentUser;
            }
        });

        // Modal close buttons
        document.querySelectorAll('.close').forEach(closeBtn => {
            closeBtn.addEventListener('click', () => {
                this.modal.task.style.display = 'none';
                this.modal.column.style.display = 'none';
            });
        });

        // Window click to close modals
        window.addEventListener('click', (event) => {
            if (event.target === this.modal.task) {
                this.modal.task.style.display = 'none';
            }
            if (event.target === this.modal.column) {
                this.modal.column.style.display = 'none';
            }
        });

        // Task form submission
        document.getElementById('task-form').addEventListener('submit', (e) => {
            e.preventDefault();
            this.saveTask();
        });

        // Column form submission
        document.getElementById('column-form').addEventListener('submit', (e) => {
            e.preventDefault();
            this.saveColumn();
        });
    }

    showTaskModal(taskId = null, columnId = null) {
        const modal = this.modal.task;
        const form = document.getElementById('task-form');

        // Reset form
        form.reset();
        document.getElementById('task-id').value = '';

        if (taskId) {
            // Edit existing task
            const task = this.tasks.find(t => t.id === taskId);
            if (task) {
                document.getElementById('task-id').value = task.id;
                document.getElementById('task-title').value = task.title;
                document.getElementById('task-description').value = task.description || '';
                document.getElementById('task-assignee').value = task.assignee || '';
                document.getElementById('task-due-date').value = task.dueDate || '';
                document.getElementById('task-priority').value = task.priority || 'medium';
            }
        } else if (columnId) {
            // New task in specific column
            document.getElementById('task-id').value = this.generateId();
            // Set default values
            document.getElementById('task-priority').value = 'medium';
        }

        modal.style.display = 'block';
    }

    showColumnModal(columnId = null) {
        const modal = this.modal.column;
        const form = document.getElementById('column-form');

        // Reset form
        form.reset();
        document.getElementById('column-id').value = '';

        if (columnId) {
            // Edit existing column
            const column = this.columns.find(c => c.id === columnId);
            if (column) {
                document.getElementById('column-id').value = column.id;
                document.getElementById('column-title').value = column.title;
            }
        } else {
            // New column
            document.getElementById('column-id').value = this.generateId();
        }

        modal.style.display = 'block';
    }

    saveTask() {
        const taskId = document.getElementById('task-id').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const assignee = document.getElementById('task-assignee').value;
        const dueDate = document.getElementById('task-due-date').value;
        const priority = document.getElementById('task-priority').value;

        // Find the column for this task
        let columnId = null;
        if (taskId) {
            // Existing task - find its current column
            const existingTask = this.tasks.find(t => t.id === taskId);
            if (existingTask) {
                columnId = existingTask.columnId;
            }
        } else {
            // New task - find the first column (or use the one from the modal)
            columnId = this.columns.length > 0 ? this.columns[0].id : null;
        }

        if (!columnId) {
            alert('Please create a column first');
            return;
        }

        const task = {
            id: taskId || this.generateId(),
            title,
            description,
            assignee,
            dueDate,
            priority,
            columnId
        };

        // Update or add task
        const taskIndex = this.tasks.findIndex(t => t.id === task.id);
        if (taskIndex !== -1) {
            this.tasks[taskIndex] = task;
        } else {
            this.tasks.push(task);
        }

        // Save changes
        this.saveData();

        // Broadcast the change to other clients
        if (this.socket) {
            this.socket.emit('task-updated', {
                task,
                user: this.currentUser
            });
        }

        // Close modal and refresh UI
        this.modal.task.style.display = 'none';
        this.renderBoard();
        this.initDragula();
    }

    saveColumn() {
        const columnId = document.getElementById('column-id').value;
        const title = document.getElementById('column-title').value;

        const column = {
            id: columnId || this.generateId(),
            title
        };

        // Update or add column
        const columnIndex = this.columns.findIndex(c => c.id === column.id);
        if (columnIndex !== -1) {
            this.columns[columnIndex] = column;
        } else {
            this.columns.push(column);
        }

        // Save changes
        this.saveData();

        // Broadcast the change to other clients
        if (this.socket) {
            this.socket.emit('column-updated', {
                column,
                user: this.currentUser
            });
        }

        // Close modal and refresh UI
        this.modal.column.style.display = 'none';
        this.renderBoard();
        this.initDragula();
    }

    deleteTask(taskId) {
        if (confirm('Are you sure you want to delete this task?')) {
            // Remove task from local data
            this.tasks = this.tasks.filter(t => t.id !== taskId);

            // Save changes
            this.saveData();

            // Broadcast the change to other clients
            if (this.socket) {
                this.socket.emit('task-deleted', {
                    taskId,
                    user: this.currentUser
                });
            }

            // Refresh UI
            this.renderBoard();
            this.initDragula();
        }
    }

    deleteColumn(columnId) {
        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            // Remove column and its tasks
            this.columns = this.columns.filter(c => c.id !== columnId);
            this.tasks = this.tasks.filter(t => t.columnId !== columnId);

            // Save changes
            this.saveData();

            // Broadcast the change to other clients
            if (this.socket) {
                this.socket.emit('column-deleted', {
                    columnId,
                    user: this.currentUser
                });
            }

            // Refresh UI
            this.renderBoard();
            this.initDragula();
        }
    }

    generateId() {
        return '_' + Math.random().toString(36).substr(2, 9);
    }
}
