## Server Setup for Real-Time Collaboration

For the real-time collaboration to work, you'll need a simple Node.js server with Socket.io. Create a file named `server.js`:

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files from the current directory
app.use(express.static(__dirname));

// Socket.io connection handler
io.on('connection', (socket) => {
    console.log('A user connected');

    // Task events
    socket.on('task-updated', (data) => {
        socket.broadcast.emit('task-updated', data);
    });

    socket.on('task-deleted', (data) => {
        socket.broadcast.emit('task-deleted', data.taskId);
    });

    socket.on('task-moved', (data) => {
        socket.broadcast.emit('task-moved', data);
    });

    // Column events
    socket.on('column-updated', (data) => {
        socket.broadcast.emit('column-updated', data);
    });

    socket.on('column-deleted', (data) => {
        socket.broadcast.emit('column-deleted', data.columnId);
    });

    socket.on('disconnect', () => {
        console.log('User disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

## How to Run the Application

1. Save all the files in the same directory.
2. Install the required Node.js packages:
   ```bash
   npm init -y
   npm install express socket.io
   ```
3. Start the server:
   ```bash
   node server.js
   ```
4. Open your browser and navigate to `http://localhost:3000`

