## JavaScript Implementation (app.js)

```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();
const auth = firebase.auth();

// DOM Elements
const boardsContainer = document.getElementById('boards');
const projectsList = document.getElementById('projects-list');
const currentProjectName = document.getElementById('current-project-name');
const addColumnBtn = document.getElementById('add-column-btn');
const newProjectBtn = document.getElementById('new-project-btn');
const inviteBtn = document.getElementById('invite-btn');
const logoutBtn = document.getElementById('logout-btn');
const userNameElement = document.getElementById('user-name');

// Modals
const taskModal = document.getElementById('task-modal');
const projectModal = document.getElementById('project-modal');
const inviteModal = document.getElementById('invite-modal');

// Modal forms
const taskForm = document.getElementById('task-form');
const projectForm = document.getElementById('project-form');
const inviteForm = document.getElementById('invite-form');

// Modal close buttons
const closeButtons = document.querySelectorAll('.close');

// App state
let currentUser = null;
let currentProjectId = null;
let currentTaskId = null;
let currentColumnId = null;

// Initialize the app
function initApp() {
    // Set up authentication state observer
    auth.onAuthStateChanged((user) => {
        if (user) {
            currentUser = user;
            userNameElement.textContent = user.email || 'User';
            loadProjects();
        } else {
            // User is signed out
            currentUser = null;
            userNameElement.textContent = 'Guest';
            // Show login UI or redirect to login page
        }
    });

    // Set up event listeners
    setupEventListeners();

    // Load initial data
    if (currentUser) {
        loadProjects();
    }
}

// Set up event listeners
function setupEventListeners() {
    // Project list click
    projectsList.addEventListener('click', (e) => {
        const projectItem = e.target.closest('li');
        if (projectItem) {
            const projectId = projectItem.dataset.projectId;
            loadProject(projectId);
        }
    });

    // Add column button
    addColumnBtn.addEventListener('click', () => {
        const columnName = prompt('Enter column name:');
        if (columnName && currentProjectId) {
            addColumn(currentProjectId, columnName);
        }
    });

    // New project button
    newProjectBtn.addEventListener('click', () => {
        projectModal.style.display = 'block';
    });

    // Invite button
    inviteBtn.addEventListener('click', () => {
        inviteModal.style.display = 'block';
    });

    // Logout button
    logoutBtn.addEventListener('click', () => {
        auth.signOut();
    });

    // Close modal buttons
    closeButtons.forEach(button => {
        button.addEventListener('click', () => {
            button.closest('.modal').style.display = 'none';
        });
    });

    // Window click to close modals
    window.addEventListener('click', (e) => {
        if (e.target.classList.contains('modal')) {
            e.target.style.display = 'none';
        }
    });

    // Project form submission
    projectForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const projectName = document.getElementById('project-name').value;
        const projectDescription = document.getElementById('project-description').value;

        createProject(projectName, projectDescription);
        projectModal.style.display = 'none';
        projectForm.reset();
    });

    // Task form submission
    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const dueDate = document.getElementById('task-due-date').value;
        const assignee = document.getElementById('task-assignee').value;
        const priority = document.getElementById('task-priority').value;

        if (currentTaskId) {
            // Update existing task
            updateTask(currentProjectId, currentColumnId, currentTaskId, {
                title,
                description,
                dueDate,
                assignee,
                priority
            });
        } else {
            // Create new task
            addTask(currentProjectId, currentColumnId, {
                title,
                description,
                dueDate,
                assignee,
                priority,
                createdBy: currentUser.uid,
                createdAt: Date.now()
            });
        }

        taskModal.style.display = 'none';
        taskForm.reset();
    });

    // Invite form submission
    inviteForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = document.getElementById('invite-email').value;
        const role = document.getElementById('invite-role').value;

        // In a real app, you would send an invitation email here
        alert(`Invitation sent to ${email} as ${role}`);
        inviteModal.style.display = 'none';
        inviteForm.reset();
    });
}

// Load projects from Firebase
function loadProjects() {
    if (!currentUser) return;

    const projectsRef = database.ref(`users/${currentUser.uid}/projects`);

    projectsRef.on('value', (snapshot) => {
        projectsList.innerHTML = '';
        const projects = snapshot.val();

        if (projects) {
            Object.keys(projects).forEach(projectId => {
                const project = projects[projectId];
                const projectItem = document.createElement('li');
                projectItem.dataset.projectId = projectId;
                projectItem.textContent = project.name;

                if (projectId === currentProjectId) {
                    projectItem.classList.add('active');
                }

                projectsList.appendChild(projectItem);
            });

            // Load the first project if none is selected
            if (!currentProjectId && Object.keys(projects).length > 0) {
                loadProject(Object.keys(projects)[0]);
            }
        } else {
            // No projects, show empty state
            projectsList.innerHTML = '<li>No projects found</li>';
        }
    });
}

// Load a specific project
function loadProject(projectId) {
    currentProjectId = projectId;

    // Update UI
    const projectRef = database.ref(`users/${currentUser.uid}/projects/${projectId}`);
    projectRef.once('value', (snapshot) => {
        const project = snapshot.val();
        currentProjectName.textContent = project.name;

        // Update active project in sidebar
        document.querySelectorAll('#projects-list li').forEach(item => {
            item.classList.toggle('active', item.dataset.projectId === projectId);
        });
    });

    // Load columns for this project
    loadColumns(projectId);
}

// Load columns for a project
function loadColumns(projectId) {
    const columnsRef = database.ref(`users/${currentUser.uid}/projects/${projectId}/columns`);

    columnsRef.on('value', (snapshot) => {
        boardsContainer.innerHTML = '';
        const columns = snapshot.val();

        if (columns) {
            Object.keys(columns).forEach(columnId => {
                const column = columns[columnId];
                renderColumn(columnId, column);
            });
        } else {
            // No columns, show empty state
            boardsContainer.innerHTML = '<div class="empty-state">No columns found. Add a column to get started.</div>';
        }
    });
}

// Render a column
function renderColumn(columnId, column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = columnId;

    columnElement.innerHTML = `
        <div class="column-header">
            <span class="column-title">${column.name}</span>
            <div class="column-actions">
                <button class="add-task-btn" data-column-id="${columnId}"><i class="fas fa-plus"></i></button>
                <button class="delete-column-btn" data-column-id="${columnId}"><i class="fas fa-trash"></i></button>
            </div>
        </div>
        <div class="column-body" id="column-${columnId}">
            <!-- Tasks will be loaded here -->
        </div>
    `;

    boardsContainer.appendChild(columnElement);

    // Set up drag and drop for this column
    setupDragAndDrop(columnId);

    // Load tasks for this column
    loadTasks(currentProjectId, columnId);

    // Set up event listeners for this column
    const addTaskBtn = columnElement.querySelector('.add-task-btn');
    const deleteColumnBtn = columnElement.querySelector('.delete-column-btn');

    addTaskBtn.addEventListener('click', () => {
        currentColumnId = columnId;
        currentTaskId = null;
        taskModal.style.display = 'block';
        document.getElementById('modal-title').textContent = 'Add New Task';
    });

    deleteColumnBtn.addEventListener('click', () => {
        if (confirm('Are you sure you want to delete this column?')) {
            deleteColumn(currentProjectId, columnId);
        }
    });
}

// Set up drag and drop for a column
function setupDragAndDrop(columnId) {
    const columnBody = document.getElementById(`column-${columnId}`);

    columnBody.addEventListener('dragover', (e) => {
        e.preventDefault();
        const afterElement = getDragAfterElement(columnBody, e.clientY);
        const draggable = document.querySelector('.dragging');

        if (afterElement == null) {
            columnBody.appendChild(draggable);
        } else {
            columnBody.insertBefore(draggable, afterElement);
        }
    });

    columnBody.addEventListener('drop', (e) => {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const fromColumnId = e.dataTransfer.getData('fromColumnId');

        if (fromColumnId !== columnId) {
            // Move task to new column
            moveTask(currentProjectId, fromColumnId, columnId, taskId);
        }
    });
}

// Helper function for drag and drop positioning
function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Load tasks for a column
function loadTasks(projectId, columnId) {
    const tasksRef = database.ref(`users/${currentUser.uid}/projects/${projectId}/columns/${columnId}/tasks`);

    tasksRef.on('value', (snapshot) => {
        const columnBody = document.getElementById(`column-${columnId}`);
        columnBody.innerHTML = '';
        const tasks = snapshot.val();

        if (tasks) {
            Object.keys(tasks).forEach(taskId => {
                const task = tasks[taskId];
                renderTask(projectId, columnId, taskId, task);
            });
        }
    });
}

// Render a task
function renderTask(projectId, columnId, taskId, task) {
    const columnBody = document.getElementById(`column-${columnId}`);
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.taskId = taskId;

    taskElement.innerHTML = `
        <div class="task-header">
            <span class="task-title">${task.title}</span>
            <span class="task-priority ${task.priority}">${task.priority}</span>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span>${task.assignee || 'Unassigned'}</span>
            <span>${task.dueDate ? new Date(task.dueDate).toLocaleDateString() : ''}</span>
        </div>
    `;

    // Set up drag events
    taskElement.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', taskId);
        e.dataTransfer.setData('fromColumnId', columnId);
        taskElement.classList.add('dragging');
    });

    taskElement.addEventListener('dragend', () => {
        taskElement.classList.remove('dragging');
    });

    // Set up click to edit
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('.task-actions')) {
            currentProjectId = projectId;
            currentColumnId = columnId;
            currentTaskId = taskId;

            // Populate form with task data
            document.getElementById('task-title').value = task.title;
            document.getElementById('task-description').value = task.description || '';
            document.getElementById('task-due-date').value = task.dueDate || '';
            document.getElementById('task-assignee').value = task.assignee || '';
            document.getElementById('task-priority').value = task.priority || 'medium';

            document.getElementById('modal-title').textContent = 'Edit Task';
            taskModal.style.display = 'block';
        }
    });

    columnBody.appendChild(taskElement);
}

// Create a new project
function createProject(name, description) {
    if (!currentUser) return;

    const projectRef = database.ref(`users/${currentUser.uid}/projects`).push();
    projectRef.set({
        name,
        description,
        createdAt: Date.now(),
        createdBy: currentUser.uid
    });

    // Create default columns
    const defaultColumns = ['To Do', 'In Progress', 'Done'];
    defaultColumns.forEach(columnName => {
        addColumn(projectRef.key, columnName);
    });
}

// Add a new column to a project
function addColumn(projectId, columnName) {
    if (!currentUser) return;

    const columnRef = database.ref(`users/${currentUser.uid}/projects/${projectId}/columns`).push();
    columnRef.set({
        name: columnName,
        createdAt: Date.now(),
        createdBy: currentUser.uid
    });
}

// Delete a column
function deleteColumn(projectId, columnId) {
    if (!currentUser) return;

    database.ref(`users/${currentUser.uid}/projects/${projectId}/columns/${columnId}`).remove();
}

// Add a new task to a column
function addTask(projectId, columnId, taskData) {
    if (!currentUser) return;

    const taskRef = database.ref(`users/${currentUser.uid}/projects/${projectId}/columns/${columnId}/tasks`).push();
    taskRef.set(taskData);
}

// Update a task
function updateTask(projectId, columnId, taskId, taskData) {
    if (!currentUser) return;

    database.ref(`users/${currentUser.uid}/projects/${projectId}/columns/${columnId}/tasks/${taskId}`).update(taskData);
}

// Move a task between columns
function moveTask(projectId, fromColumnId, toColumnId, taskId) {
    if (!currentUser) return;

    // Get the task data
    const taskRef = database.ref(`users/${currentUser.uid}/projects/${projectId}/columns/${fromColumnId}/tasks/${taskId}`);

    taskRef.once('value', (snapshot) => {
        const taskData = snapshot.val();

        if (taskData) {
            // Add to new column
            const newTaskRef = database.ref(`users/${currentUser.uid}/projects/${projectId}/columns/${toColumnId}/tasks`).push();
            newTaskRef.set(taskData);

            // Remove from old column
            taskRef.remove();
        }
    });
}

// Initialize the app when the page loads
window.addEventListener('DOMContentLoaded', initApp);
```

## Features Implemented

1. **Project Management**:
   - Create and manage multiple projects
   - Each project has its own set of columns (boards)

2. **Drag-and-Drop Interface**:
   - Tasks can be dragged between columns
   - Visual feedback during drag operations
   - Real-time updates when tasks are moved

3. **Task Management**:
   - Create, edit, and delete tasks
   - Task details include title, description, due date, assignee, and priority
   - Visual indicators for task priority

4. **Real-time Collaboration** (via Firebase):
   - All changes are synchronized across all connected clients
   - Projects, columns, and tasks are stored in Firebase Realtime Database
   - Authentication system to manage user access

5. **Responsive Design**:
   - Works on desktop and mobile devices
   - Adapts layout based on screen size

