## JavaScript Implementation (app.js)

```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();

// DOM elements
const boardsContainer = document.getElementById('boardsContainer');
const addBoardBtn = document.getElementById('addBoardBtn');
const addTaskBtn = document.getElementById('addTaskBtn');
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const boardModal = new bootstrap.Modal(document.getElementById('boardModal'));
const saveTaskBtn = document.getElementById('saveTaskBtn');
const saveBoardBtn = document.getElementById('saveBoardBtn');

// Task form elements
const taskForm = document.getElementById('taskForm');
const taskTitle = document.getElementById('taskTitle');
const taskDescription = document.getElementById('taskDescription');
const taskPriority = document.getElementById('taskPriority');
const taskAssignee = document.getElementById('taskAssignee');
const taskDueDate = document.getElementById('taskDueDate');

// Board form elements
const boardForm = document.getElementById('boardForm');
const boardName = document.getElementById('boardName');

// App state
let currentTaskId = null;
let currentBoardId = null;
let dragulaInstance = null;

// Initialize the app
function initApp() {
    // Load boards from Firestore
    loadBoards();

    // Set up event listeners
    setupEventListeners();

    // Initialize drag-and-drop
    initDragula();
}

// Load boards from Firestore
function loadBoards() {
    db.collection('boards').orderBy('order').onSnapshot((snapshot) => {
        boardsContainer.innerHTML = '';

        snapshot.forEach((doc) => {
            const board = doc.data();
            const boardElement = createBoardElement(doc.id, board);
            boardsContainer.appendChild(boardElement);

            // Load tasks for this board
            loadTasks(doc.id);
        });

        // Reinitialize drag-and-drop after boards are loaded
        if (dragulaInstance) {
            dragulaInstance.destroy();
        }
        initDragula();
    });
}

// Load tasks for a specific board
function loadTasks(boardId) {
    db.collection('boards').doc(boardId).collection('tasks')
        .orderBy('order')
        .onSnapshot((snapshot) => {
            const boardElement = document.getElementById(`board-${boardId}`);
            const tasksContainer = boardElement.querySelector('.tasks-container');

            tasksContainer.innerHTML = '';

            snapshot.forEach((doc) => {
                const task = doc.data();
                const taskElement = createTaskElement(doc.id, task);
                tasksContainer.appendChild(taskElement);
            });
        });
}

// Create a board element
function createBoardElement(boardId, board) {
    const boardElement = document.createElement('div');
    boardElement.className = 'col-md-4 board';
    boardElement.id = `board-${boardId}`;

    boardElement.innerHTML = `
        <div class="board-header">
            <h3 class="board-title">${board.name}</h3>
            <div class="dropdown">
                <button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">
                    <i class="bi bi-three-dots-vertical"></i>
                </button>
                <ul class="dropdown-menu">
                    <li><a class="dropdown-item" href="#" onclick="editBoard('${boardId}')">Edit Board</a></li>
                    <li><a class="dropdown-item text-danger" href="#" onclick="deleteBoard('${boardId}')">Delete Board</a></li>
                </ul>
            </div>
        </div>
        <div class="tasks-container"></div>
        <button class="btn btn-sm btn-outline-primary w-100 mt-2" onclick="addTask('${boardId}')">Add Task</button>
    `;

    return boardElement;
}

// Create a task element
function createTaskElement(taskId, task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.id = `task-${taskId}`;
    taskElement.dataset.taskId = taskId;
    taskElement.dataset.boardId = task.boardId;

    const priorityClass = `priority-${task.priority || 'medium'}`;

    taskElement.innerHTML = `
        <div class="task-header">
            <span class="task-priority ${priorityClass}">${task.priority || 'medium'}</span>
            <h5 class="task-title">${task.title}</h5>
        </div>
        <p class="task-description">${task.description || ''}</p>
        <div class="task-meta">
            <span>${task.assignee || 'Unassigned'}</span>
            <span>${task.dueDate || ''}</span>
        </div>
    `;

    taskElement.addEventListener('click', () => editTask(task.boardId, taskId));

    return taskElement;
}

// Initialize drag-and-drop with Dragula
function initDragula() {
    const containers = Array.from(document.querySelectorAll('.tasks-container'));

    dragulaInstance = dragula(containers, {
        moves: function (el, container, handle) {
            return el.classList.contains('task');
        },
        accepts: function (el, target, source, sibling) {
            return target.classList.contains('tasks-container');
        }
    });

    // Handle drop event
    dragulaInstance.on('drop', (el, target, source, sibling) => {
        const taskId = el.dataset.taskId;
        const newBoardId = target.parentElement.id.replace('board-', '');
        const oldBoardId = source.parentElement.id.replace('board-', '');

        if (newBoardId !== oldBoardId) {
            // Task moved to a different board
            moveTaskBetweenBoards(taskId, oldBoardId, newBoardId);
        } else {
            // Task reordered within the same board
            updateTaskOrder(newBoardId);
        }
    });
}

// Move task between boards
function moveTaskBetweenBoards(taskId, oldBoardId, newBoardId) {
    const taskRef = db.collection('boards').doc(oldBoardId).collection('tasks').doc(taskId);

    taskRef.get().then((doc) => {
        if (doc.exists) {
            const taskData = doc.data();

            // Add to new board
            db.collection('boards').doc(newBoardId).collection('tasks').doc(taskId).set({
                ...taskData,
                boardId: newBoardId,
                order: Date.now() // Temporary order, will be updated
            }).then(() => {
                // Delete from old board
                taskRef.delete().then(() => {
                    // Update order in new board
                    updateTaskOrder(newBoardId);
                });
            });
        }
    });
}

// Update task order in a board
function updateTaskOrder(boardId) {
    const tasksContainer = document.querySelector(`#board-${boardId} .tasks-container`);
    const tasks = Array.from(tasksContainer.querySelectorAll('.task'));

    tasks.forEach((taskElement, index) => {
        const taskId = taskElement.dataset.taskId;
        db.collection('boards').doc(boardId).collection('tasks').doc(taskId).update({
            order: index
        });
    });
}

// Set up event listeners
function setupEventListeners() {
    addBoardBtn.addEventListener('click', () => {
        boardForm.reset();
        currentBoardId = null;
        boardModal.show();
    });

    addTaskBtn.addEventListener('click', () => {
        // Default to first board if available
        const firstBoard = document.querySelector('.board');
        if (firstBoard) {
            addTask(firstBoard.id.replace('board-', ''));
        } else {
            alert('Please create a board first');
        }
    });

    saveBoardBtn.addEventListener('click', () => {
        if (boardForm.checkValidity()) {
            if (currentBoardId) {
                // Update existing board
                db.collection('boards').doc(currentBoardId).update({
                    name: boardName.value
                });
            } else {
                // Create new board
                db.collection('boards').add({
                    name: boardName.value,
                    order: Date.now()
                });
            }
            boardModal.hide();
        } else {
            boardForm.reportValidity();
        }
    });

    saveTaskBtn.addEventListener('click', () => {
        if (taskForm.checkValidity()) {
            const taskData = {
                title: taskTitle.value,
                description: taskDescription.value,
                priority: taskPriority.value,
                assignee: taskAssignee.value,
                dueDate: taskDueDate.value,
                boardId: currentBoardId,
                order: Date.now()
            };

            if (currentTaskId) {
                // Update existing task
                db.collection('boards').doc(currentBoardId).collection('tasks').doc(currentTaskId).update(taskData);
            } else {
                // Create new task
                db.collection('boards').doc(currentBoardId).collection('tasks').add(taskData);
            }
            taskModal.hide();
        } else {
            taskForm.reportValidity();
        }
    });
}

// Add a new task to a board
function addTask(boardId) {
    currentBoardId = boardId;
    currentTaskId = null;
    taskForm.reset();
    taskModal.show();
}

// Edit an existing task
function editTask(boardId, taskId) {
    currentBoardId = boardId;
    currentTaskId = taskId;

    // Load task data
    db.collection('boards').doc(boardId).collection('tasks').doc(taskId).get().then((doc) => {
        if (doc.exists) {
            const task = doc.data();
            taskTitle.value = task.title || '';
            taskDescription.value = task.description || '';
            taskPriority.value = task.priority || 'medium';
            taskAssignee.value = task.assignee || '';
            taskDueDate.value = task.dueDate || '';

            taskModal.show();
        }
    });
}

// Edit a board
function editBoard(boardId) {
    currentBoardId = boardId;

    // Load board data
    db.collection('boards').doc(boardId).get().then((doc) => {
        if (doc.exists) {
            const board = doc.data();
            boardName.value = board.name || '';
            boardModal.show();
        }
    });
}

// Delete a board
function deleteBoard(boardId) {
    if (confirm('Are you sure you want to delete this board and all its tasks?')) {
        // First delete all tasks in the board
        db.collection('boards').doc(boardId).collection('tasks').get().then((snapshot) => {
            const batch = db.batch();
            snapshot.forEach((doc) => {
                batch.delete(doc.ref);
            });
            return batch.commit();
        }).then(() => {
            // Then delete the board
            db.collection('boards').doc(boardId).delete();
        });
    }
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
```

## Features Implemented

1. **Drag-and-Drop Task Management**:
   - Tasks can be dragged between boards
   - Tasks can be reordered within a board
   - Uses Dragula library for smooth drag-and-drop functionality

2. **Real-time Collaboration**:
   - Uses Firebase Firestore for real-time database updates
   - All changes are synchronized across all connected clients
   - Automatic updates when data changes in the database

3. **Board Management**:
   - Create, edit, and delete boards
   - Each board can contain multiple tasks

4. **Task Management**:
   - Create, edit, and delete tasks
   - Tasks have titles, descriptions, priorities, assignees, and due dates
   - Tasks are displayed with visual indicators for priority

5. **Responsive Design**:
   - Uses Bootstrap for responsive layout
   - Works on different screen sizes

