    });
}

// Load tasks for a specific column
function loadTasksForColumn(columnId) {
    const taskList = document.getElementById(`task-list-${columnId}`);

    db.collection('columns').doc(columnId)
        .collection('tasks')
        .orderBy('order')
        .onSnapshot(snapshot => {
            taskList.innerHTML = '';
            snapshot.forEach(doc => {
                const taskData = doc.data();
                createTaskElement(columnId, doc.id, taskData);
            });
        });
}

// Create a task element
function createTaskElement(columnId, taskId, taskData) {
    const taskList = document.getElementById(`task-list-${columnId}`);
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.dataset.taskId = taskId;
    taskElement.dataset.columnId = columnId;

    taskElement.innerHTML = `
        <div class="task-title">${taskData.title}</div>
        <div class="task-meta">
            <span class="task-priority ${taskData.priority}">${taskData.priority}</span>
            ${taskData.assignee ? `<span class="task-assignee">${taskData.assignee}</span>` : ''}
            ${taskData.dueDate ? `<span class="task-due-date">${taskData.dueDate}</span>` : ''}
        </div>
    `;

    taskList.appendChild(taskElement);

    // Add click event to open task modal
    taskElement.addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(columnId, taskId, taskData);
    });
}

// Initialize drag and drop functionality
function initDragAndDrop() {
    const columns = document.querySelectorAll('.column');

    columns.forEach(column => {
        const taskList = column.querySelector('.task-list');
        const columnId = column.dataset.columnId;

        new Sortable(taskList, {
            group: 'tasks',
            animation: 150,
            ghostClass: 'sortable-ghost',
            chosenClass: 'sortable-chosen',
            onEnd: (evt) => {
                const taskId = evt.item.dataset.taskId;
                const newColumnId = evt.to.closest('.column').dataset.columnId;
                const oldColumnId = evt.from.closest('.column').dataset.columnId;

                if (newColumnId !== oldColumnId) {
                    // Task moved to a different column
                    moveTaskBetweenColumns(taskId, oldColumnId, newColumnId, evt.newIndex);
                } else {
                    // Task reordered within the same column
                    updateTaskOrder(taskId, newColumnId, evt.newIndex);
                }
            }
        });
    });
}

// Move task between columns
function moveTaskBetweenColumns(taskId, oldColumnId, newColumnId, newOrder) {
    const batch = db.batch();

    // Get the task document
    const taskRef = db.collection('columns').doc(oldColumnId).collection('tasks').doc(taskId);

    // Update the task in the new column
    const newTaskRef = db.collection('columns').doc(newColumnId).collection('tasks').doc(taskId);

    // Get the task data
    taskRef.get().then(doc => {
        if (doc.exists) {
            const taskData = doc.data();

            // Delete from old column
            batch.delete(taskRef);

            // Add to new column with updated order
            batch.set(newTaskRef, {
                ...taskData,
                order: newOrder
            });

            // Update order of other tasks in the new column
            updateOtherTaskOrders(newColumnId, newOrder, batch);

            // Commit the batch
            batch.commit().then(() => {
                console.log('Task moved successfully');
            }).catch(error => {
                console.error('Error moving task:', error);
            });
        }
    });
}

// Update task order within the same column
function updateTaskOrder(taskId, columnId, newOrder) {
    const taskRef = db.collection('columns').doc(columnId).collection('tasks').doc(taskId);

    taskRef.update({
        order: newOrder
    }).then(() => {
        console.log('Task order updated');
    }).catch(error => {
        console.error('Error updating task order:', error);
    });
}

// Update order of other tasks when a task is moved
function updateOtherTaskOrders(columnId, newOrder, batch) {
    const tasksRef = db.collection('columns').doc(columnId).collection('tasks');

    tasksRef.where('order', '>=', newOrder).get().then(snapshot => {
        snapshot.forEach(doc => {
            if (doc.id !== currentTaskId) {
                const taskRef = tasksRef.doc(doc.id);
                batch.update(taskRef, {
                    order: doc.data().order + 1
                });
            }
        });
    });
}

// Open column modal
function openColumnModal() {
    columnModal.style.display = 'flex';
    document.getElementById('column-name').value = '';
}

// Close column modal
function closeColumnModalHandler() {
    columnModal.style.display = 'none';
}

// Handle column form submission
function handleColumnSubmit(e) {
    e.preventDefault();
    const columnName = document.getElementById('column-name').value.trim();

    if (columnName) {
        // Get the current highest order
        db.collection('columns').orderBy('order', 'desc').limit(1).get().then(snapshot => {
            let newOrder = 0;
            if (!snapshot.empty) {
                newOrder = snapshot.docs[0].data().order + 1;
            }

            // Add new column
            db.collection('columns').add({
                name: columnName,
                order: newOrder
            }).then(() => {
                closeColumnModalHandler();
            }).catch(error => {
                console.error('Error adding column:', error);
            });
        });
    }
}

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column and all its tasks?')) {
        // First delete all tasks in the column
        const tasksRef = db.collection('columns').doc(columnId).collection('tasks');
        tasksRef.get().then(snapshot => {
            const batch = db.batch();
            snapshot.forEach(doc => {
                batch.delete(tasksRef.doc(doc.id));
            });
            return batch.commit();
        }).then(() => {
            // Then delete the column
            return db.collection('columns').doc(columnId).delete();
        }).then(() => {
            console.log('Column deleted successfully');
        }).catch(error => {
            console.error('Error deleting column:', error);
        });
    }
}

// Open task modal
function openTaskModal(columnId, taskId = null, taskData = null) {
    currentTaskId = taskId;
    currentTaskColumnId = columnId;

    taskModal.style.display = 'flex';

    if (taskId) {
        // Editing existing task
        document.getElementById('modal-title').textContent = 'Edit Task';
        document.getElementById('task-title').value = taskData.title || '';
        document.getElementById('task-description').value = taskData.description || '';
        document.getElementById('task-assignee').value = taskData.assignee || '';
        document.getElementById('task-due-date').value = taskData.dueDate || '';
        document.getElementById('task-priority').value = taskData.priority || 'medium';
        deleteTaskBtn.style.display = 'block';
    } else {
        // Creating new task
        document.getElementById('modal-title').textContent = 'Add New Task';
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        document.getElementById('task-assignee').value = '';
        document.getElementById('task-due-date').value = '';
        document.getElementById('task-priority').value = 'medium';
        deleteTaskBtn.style.display = 'none';
    }
}

// Close task modal
function closeTaskModalHandler() {
    taskModal.style.display = 'none';
    currentTaskId = null;
    currentTaskColumnId = null;
}

// Handle task form submission
function handleTaskSubmit(e) {
    e.preventDefault();

    const title = document.getElementById('task-title').value.trim();
    const description = document.getElementById('task-description').value.trim();
    const assignee = document.getElementById('task-assignee').value.trim();
    const dueDate = document.getElementById('task-due-date').value;
    const priority = document.getElementById('task-priority').value;

    if (title) {
        const taskData = {
            title,
            description,
            assignee,
            dueDate,
            priority,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };

        if (currentTaskId) {
            // Update existing task
            db.collection('columns').doc(currentTaskColumnId)
                .collection('tasks').doc(currentTaskId)
                .update(taskData)
                .then(() => {
                    closeTaskModalHandler();
                })
                .catch(error => {
                    console.error('Error updating task:', error);
                });
        } else {
            // Create new task
            db.collection('columns').doc(currentTaskColumnId)
                .collection('tasks')
                .orderBy('order', 'desc')
                .limit(1)
                .get()
                .then(snapshot => {
                    let newOrder = 0;
                    if (!snapshot.empty) {
                        newOrder = snapshot.docs[0].data().order + 1;
                    }

                    return db.collection('columns').doc(currentTaskColumnId)
                        .collection('tasks')
                        .add({
                            ...taskData,
                            order: newOrder
                        });
                })
                .then(() => {
                    closeTaskModalHandler();
                })
                .catch(error => {
                    console.error('Error adding task:', error);
                });
        }
    }
}

// Handle task deletion
function handleDeleteTask() {
    if (currentTaskId && currentTaskColumnId && confirm('Are you sure you want to delete this task?')) {
        db.collection('columns').doc(currentTaskColumnId)
            .collection('tasks').doc(currentTaskId)
            .delete()
            .then(() => {
                closeTaskModalHandler();
            })
            .catch(error => {
                console.error('Error deleting task:', error);
            });
    }
}

// Handle logout
function handleLogout() {
    auth.signOut().then(() => {
        console.log('User signed out');
    }).catch(error => {
        console.error('Error signing out:', error);
    });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
