```javascript
// Firebase configuration (replace with your own config)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();
const auth = firebase.auth();

// DOM Elements
const board = document.getElementById('board');
const projectsList = document.getElementById('projects-list');
const projectTitle = document.getElementById('project-title');
const addColumnBtn = document.getElementById('add-column-btn');
const addTaskBtn = document.getElementById('add-task-btn');
const newProjectBtn = document.getElementById('new-project-btn');
const logoutBtn = document.getElementById('logout-btn');
const userName = document.getElementById('user-name');

// Modals
const taskModal = document.getElementById('task-modal');
const columnModal = document.getElementById('column-modal');
const projectModal = document.getElementById('project-modal');

// Form Elements
const taskForm = document.getElementById('task-form');
const columnForm = document.getElementById('column-form');
const projectForm = document.getElementById('project-form');

// Close buttons
const closeButtons = document.querySelectorAll('.close');

// App state
let currentProjectId = null;
let currentTaskId = null;
let currentColumnId = null;

// Initialize the app
function initApp() {
    // Check authentication state
    auth.onAuthStateChanged(user => {
        if (user) {
            userName.textContent = user.displayName || user.email;
            loadProjects();
        } else {
            // Redirect to login or show login form
            userName.textContent = 'Guest';
            showLogin();
        }
    });

    // Set up event listeners
    setupEventListeners();

    // Load default project if none selected
    if (!currentProjectId) {
        loadDefaultProject();
    }
}

// Set up event listeners
function setupEventListeners() {
    // Modal close buttons
    closeButtons.forEach(btn => {
        btn.addEventListener('click', () => {
            btn.closest('.modal').style.display = 'none';
        });
    });

    // Window click to close modals
    window.addEventListener('click', (e) => {
        if (e.target.classList.contains('modal')) {
            e.target.style.display = 'none';
        }
    });

    // Add column button
    addColumnBtn.addEventListener('click', () => {
        columnModal.style.display = 'flex';
    });

    // Add task button
    addTaskBtn.addEventListener('click', () => {
        currentTaskId = null;
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        document.getElementById('task-assignee').value = '';
        document.getElementById('task-due-date').value = '';
        document.getElementById('task-priority').value = 'medium';
        taskModal.style.display = 'flex';
    });

    // New project button
    newProjectBtn.addEventListener('click', () => {
        projectModal.style.display = 'flex';
    });

    // Logout button
    logoutBtn.addEventListener('click', () => {
        auth.signOut().then(() => {
            window.location.reload();
        });
    });

    // Form submissions
    taskForm.addEventListener('submit', handleTaskFormSubmit);
    columnForm.addEventListener('submit', handleColumnFormSubmit);
    projectForm.addEventListener('submit', handleProjectFormSubmit);
}

// Handle task form submission
function handleTaskFormSubmit(e) {
    e.preventDefault();

    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const assignee = document.getElementById('task-assignee').value;
    const dueDate = document.getElementById('task-due-date').value;
    const priority = document.getElementById('task-priority').value;

    if (!currentProjectId) return;

    if (currentTaskId) {
        // Update existing task
        database.ref(`projects/${currentProjectId}/tasks/${currentTaskId}`).update({
            title,
            description,
            assignee,
            dueDate,
            priority,
            updatedAt: firebase.database.ServerValue.TIMESTAMP
        });
    } else {
        // Create new task in the first column
        const firstColumnId = document.querySelector('.column').dataset.columnId;
        if (firstColumnId) {
            const newTaskRef = database.ref(`projects/${currentProjectId}/columns/${firstColumnId}/tasks`).push();
            newTaskRef.set({
                id: newTaskRef.key,
                title,
                description,
                assignee,
                dueDate,
                priority,
                createdAt: firebase.database.ServerValue.TIMESTAMP,
                updatedAt: firebase.database.ServerValue.TIMESTAMP,
                columnId: firstColumnId
            });
        }
    }

    taskModal.style.display = 'none';
}

// Handle column form submission
function handleColumnFormSubmit(e) {
    e.preventDefault();

    const name = document.getElementById('column-name').value;

    if (!currentProjectId) return;

    const newColumnRef = database.ref(`projects/${currentProjectId}/columns`).push();
    newColumnRef.set({
        id: newColumnRef.key,
        name,
        order: 0,
        createdAt: firebase.database.ServerValue.TIMESTAMP
    });

    columnModal.style.display = 'none';
    document.getElementById('column-name').value = '';
}

// Handle project form submission
function handleProjectFormSubmit(e) {
    e.preventDefault();

    const name = document.getElementById('project-name').value;
    const description = document.getElementById('project-description').value;

    const newProjectRef = database.ref('projects').push();
    newProjectRef.set({
        id: newProjectRef.key,
        name,
        description,
        createdAt: firebase.database.ServerValue.TIMESTAMP,
        updatedAt: firebase.database.ServerValue.TIMESTAMP,
        createdBy: auth.currentUser.uid
    });

    projectModal.style.display = 'none';
    document.getElementById('project-name').value = '';
    document.getElementById('project-description').value = '';
}

// Load projects from Firebase
function loadProjects() {
    const userId = auth.currentUser.uid;
    database.ref('projects').orderByChild('createdBy').equalTo(userId).on('value', (snapshot) => {
        projectsList.innerHTML = '';

        snapshot.forEach(project => {
            const projectData = project.val();
            const li = document.createElement('li');
            li.textContent = projectData.name;
            li.dataset.projectId = projectData.id;

            if (projectData.id === currentProjectId) {
                li.classList.add('active');
            }

            li.addEventListener('click', () => {
                document.querySelectorAll('.project-list li').forEach(item => {
                    item.classList.remove('active');
                });
                li.classList.add('active');
                loadProject(projectData.id);
            });

            projectsList.appendChild(li);
        });
    });
}

// Load a specific project
function loadProject(projectId) {
    currentProjectId = projectId;

    // Get project details
    database.ref(`projects/${projectId}`).once('value', (snapshot) => {
        const project = snapshot.val();
        projectTitle.textContent = project.name;
    });

    // Set up real-time listeners for columns and tasks
    setupProjectListeners(projectId);
}

// Set up real-time listeners for a project
function setupProjectListeners(projectId) {
    // Listen for column changes
    database.ref(`projects/${projectId}/columns`).on('value', (snapshot) => {
        board.innerHTML = '';

        const columns = [];
        snapshot.forEach(column => {
            columns.push(column.val());
        });

        // Sort columns by order
        columns.sort((a, b) => a.order - b.order);

        // Create columns in the DOM
        columns.forEach(column => {
            createColumnElement(column);
        });

        // Set up drag and drop for all tasks
        setupDragAndDrop();
    });
}

// Create a column element in the DOM
function createColumnElement(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = column.id;

    columnElement.innerHTML = `
        <div class="column-header">
            <span class="column-title">${column.name}</span>
            <div class="column-actions">
                <button class="btn delete-column" data-column-id="${column.id}"><i class="fas fa-trash"></i></button>
            </div>
        </div>
        <div class="column-content" data-column-id="${column.id}"></div>
    `;

    board.appendChild(columnElement);

    // Listen for tasks in this column
    database.ref(`projects/${currentProjectId}/columns/${column.id}/tasks`).on('value', (snapshot) => {
        const columnContent = columnElement.querySelector('.column-content');
        columnContent.innerHTML = '';

        const tasks = [];
        snapshot.forEach(task => {
            tasks.push(task.val());
        });

        // Sort tasks by creation date
        tasks.sort((a, b) => a.createdAt - b.createdAt);

        // Create task elements
        tasks.forEach(task => {
            createTaskElement(task, columnContent);
        });
    });

    // Set up delete column button
    columnElement.querySelector('.delete-column').addEventListener('click', (e) => {
        e.stopPropagation();
        const columnId = e.target.closest('.delete-column').dataset.columnId;
        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            deleteColumn(columnId);
        }
    });
}

// Create a task element in the DOM
function createTaskElement(task, columnContent) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.taskId = task.id;
    taskElement.dataset.columnId = task.columnId;

    taskElement.innerHTML = `
        <div class="task-header">
            <span class="task-title">${task.title}</span>
            <span class="task-priority ${task.priority}">${task.priority}</span>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span>${task.assignee || 'Unassigned'}</span>
            <span>${task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date'}</span>
        </div>
    `;

    // Set up drag events
    taskElement.addEventListener('dragstart', handleDragStart);
    taskElement.addEventListener('dragend', handleDragEnd);

    // Set up click to edit
    taskElement.addEventListener('click', () => {
        currentTaskId = task.id;
        document.getElementById('task-title').value = task.title;
        document.getElementById('task-description').value = task.description || '';
        document.getElementById('task-assignee').value = task.assignee || '';
        document.getElementById('task-due-date').value = task.dueDate || '';
        document.getElementById('task-priority').value = task.priority || 'medium';
        taskModal.style.display = 'flex';
    });

    columnContent.appendChild(taskElement);
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const columns = document.querySelectorAll('.column-content');

    columns.forEach(column => {
        column.addEventListener('dragover', handleDragOver);
        column.addEventListener('dragenter', handleDragEnter);
        column.addEventListener('dragleave', handleDragLeave);
        column.addEventListener('drop', handleDrop);
    });
}

// Drag and drop event handlers
function handleDragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
    e.target.classList.add('dragging');
    setTimeout(() => {
        e.target.style.display = 'none';
    }, 0);
}

function handleDragEnd(e) {
    e.target.classList.remove('dragging');
    e.target.style.display = 'block';
}

function handleDragOver(e) {
    e.preventDefault();
}

function handleDragEnter(e) {
    e.preventDefault();
    e.target.classList.add('drag-over');
}

function handleDragLeave(e) {
    e.target.classList.remove('drag-over');
}

function handleDrop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    const taskId = e.dataTransfer.getData('text/plain');
    const newColumnId = e.target.dataset.columnId;

    if (!taskId || !newColumnId) return;

    // Get the task data
    database.ref(`projects/${currentProjectId}/tasks/${taskId}`).once('value', (snapshot) => {
        const task = snapshot.val();
        if (!task) return;

        // Remove from old column
        database.ref(`projects/${currentProjectId}/columns/${task.columnId}/tasks/${taskId}`).remove();

        // Add to new column
        task.columnId = newColumnId;
        database.ref(`projects/${currentProjectId}/columns/${newColumnId}/tasks/${taskId}`).set(task);

        // Update the task in the tasks collection
        database.ref(`projects/${currentProjectId}/tasks/${taskId}`).update({
            columnId: newColumnId,
            updatedAt: firebase.database.ServerValue.TIMESTAMP
        });
    });
}

// Delete a column and all its tasks
function deleteColumn(columnId) {
    // First remove all tasks in this column
    database.ref(`projects/${currentProjectId}/columns/${columnId}/tasks`).once('value', (snapshot) => {
        snapshot.forEach(task => {
            database.ref(`projects/${currentProjectId}/tasks/${task.key}`).remove();
        });

        // Then remove the column itself
        database.ref(`projects/${currentProjectId}/columns/${columnId}`).remove();
    });
}

// Load default project if no projects exist
function loadDefaultProject() {
    database.ref('projects').orderByChild('createdBy').equalTo(auth.currentUser.uid).limitToLast(1).once('value', (snapshot) => {
        if (snapshot.exists()) {
            snapshot.forEach(project => {
                loadProject(project.val().id);
            });
        } else {
            // Create a default project
            const newProjectRef = database.ref('projects').push();
            newProjectRef.set({
                id: newProjectRef.key,
                name: 'My First Project',
                description: 'Welcome to TaskBoard Pro!',
                createdAt: firebase.database.ServerValue.TIMESTAMP,
                updatedAt: firebase.database.ServerValue.TIMESTAMP,
                createdBy: auth.currentUser.uid
            }).then(() => {
                loadProject(newProjectRef.key);
            });
        }
    });
}

// Show login form (simplified for this example)
function showLogin() {
    // In a real app, you would show a proper login form
    // For this example, we'll just sign in anonymously
    auth.signInAnonymously().catch((error) => {
        console.error("Error signing in:", error);
    });
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
