## JavaScript Implementation

```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize the app
    const app = new TaskBoardApp();
    app.init();
});

class TaskBoardApp {
    constructor() {
        // DOM elements
        this.boardContainer = document.getElementById('board-container');
        this.addColumnBtn = document.getElementById('add-column-btn');
        this.addTaskBtn = document.getElementById('add-task-btn');
        this.taskModal = document.getElementById('task-modal');
        this.columnModal = document.getElementById('column-modal');
        this.taskForm = document.getElementById('task-form');
        this.columnForm = document.getElementById('column-form');
        this.projectTitle = document.getElementById('project-title');
        this.userName = document.getElementById('user-name');
        this.logoutBtn = document.getElementById('logout-btn');

        // Data
        this.columns = [];
        this.tasks = [];
        this.currentUser = 'Guest';
        this.projectId = 'default-project';

        // WebSocket connection
        this.socket = null;

        // Drag and drop state
        this.draggedTask = null;
    }

    init() {
        // Load data from localStorage
        this.loadData();

        // Set up event listeners
        this.setupEventListeners();

        // Initialize WebSocket connection
        this.setupWebSocket();

        // Render the board
        this.renderBoard();
    }

    setupEventListeners() {
        // Column modal
        this.addColumnBtn.addEventListener('click', () => this.showColumnModal());
        document.querySelectorAll('.close-modal').forEach(btn => {
            btn.addEventListener('click', () => this.closeModals());
        });

        // Task modal
        this.addTaskBtn.addEventListener('click', () => this.showTaskModal());
        this.taskForm.addEventListener('submit', (e) => this.handleTaskFormSubmit(e));

        // Column form
        this.columnForm.addEventListener('submit', (e) => this.handleColumnFormSubmit(e));

        // User actions
        this.logoutBtn.addEventListener('click', () => this.logout());

        // Drag and drop
        this.boardContainer.addEventListener('dragover', (e) => this.handleDragOver(e));
        this.boardContainer.addEventListener('drop', (e) => this.handleDrop(e));
    }

    setupWebSocket() {
        // In a real app, you would connect to your WebSocket server
        // For this example, we'll simulate real-time updates
        console.log('Setting up WebSocket connection...');

        // Simulate receiving updates from other users
        setInterval(() => {
            // In a real app, you would listen for 'task-updated' events
            // For demo purposes, we'll just check for changes
            this.checkForRemoteChanges();
        }, 3000);
    }

    checkForRemoteChanges() {
        // In a real app, this would be handled by WebSocket events
        // For demo purposes, we'll just reload data from localStorage
        const savedData = localStorage.getItem('taskBoardData');
        if (savedData) {
            const parsedData = JSON.parse(savedData);
            if (parsedData.columns && parsedData.tasks) {
                // Compare with current data
                const columnsChanged = JSON.stringify(this.columns) !== JSON.stringify(parsedData.columns);
                const tasksChanged = JSON.stringify(this.tasks) !== JSON.stringify(parsedData.tasks);

                if (columnsChanged || tasksChanged) {
                    this.columns = parsedData.columns;
                    this.tasks = parsedData.tasks;
                    this.renderBoard();
                    console.log('Received updates from other users');
                }
            }
        }
    }

    loadData() {
        const savedData = localStorage.getItem('taskBoardData');
        if (savedData) {
            const parsedData = JSON.parse(savedData);
            this.columns = parsedData.columns || [];
            this.tasks = parsedData.tasks || [];
            this.currentUser = parsedData.currentUser || 'Guest';
            this.projectId = parsedData.projectId || 'default-project';
            this.projectTitle.textContent = parsedData.projectTitle || 'My Project';
            this.userName.textContent = this.currentUser;
        } else {
            // Default columns
            this.columns = [
                { id: 'todo', title: 'To Do' },
                { id: 'in-progress', title: 'In Progress' },
                { id: 'done', title: 'Done' }
            ];
            this.saveData();
        }
    }

    saveData() {
        const dataToSave = {
            columns: this.columns,
            tasks: this.tasks,
            currentUser: this.currentUser,
            projectId: this.projectId,
            projectTitle: this.projectTitle.textContent
        };
        localStorage.setItem('taskBoardData', JSON.stringify(dataToSave));

        // In a real app, you would emit changes to the server via WebSocket
        // For demo purposes, we're just using localStorage
    }

    renderBoard() {
        this.boardContainer.innerHTML = '';

        this.columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.columnId = column.id;

            columnElement.innerHTML = `
                <div class="column-header">
                    <span class="column-title">${column.title}</span>
                    <div class="column-actions">
                        <button class="edit-column-btn" data-column-id="${column.id}">
                            <i class="fas fa-edit"></i>
                        </button>
                        <button class="delete-column-btn" data-column-id="${column.id}">
                            <i class="fas fa-trash"></i>
                        </button>
                    </div>
                </div>
                <div class="task-list" data-column-id="${column.id}"></div>
            `;

            this.boardContainer.appendChild(columnElement);
        });

        // Render tasks
        this.tasks.forEach(task => {
            this.renderTask(task);
        });

        // Add event listeners to column buttons
        document.querySelectorAll('.edit-column-btn').forEach(btn => {
            btn.addEventListener('click', (e) => this.editColumn(e));
        });

        document.querySelectorAll('.delete-column-btn').forEach(btn => {
            btn.addEventListener('click', (e) => this.deleteColumn(e));
        });
    }

    renderTask(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.draggable = true;
        taskElement.dataset.taskId = task.id;
        taskElement.dataset.columnId = task.columnId;

        taskElement.innerHTML = `
            <div class="task-header">
                <span class="task-title">${task.title}</span>
                <span class="task-priority ${task.priority}">${task.priority}</span>
            </div>
            <div class="task-description">${task.description || ''}</div>
            <div class="task-meta">
                <span>${task.assignee || 'Unassigned'}</span>
                <span>${task.dueDate ? new Date(task.dueDate).toLocaleDateString() : ''}</span>
            </div>
        `;

        // Add drag event listeners
        taskElement.addEventListener('dragstart', (e) => this.handleDragStart(e));
        taskElement.addEventListener('click', () => this.showTaskModal(task.id));

        // Find the column and append the task
        const column = document.querySelector(`.task-list[data-column-id="${task.columnId}"]`);
        if (column) {
            column.appendChild(taskElement);
        }
    }

    showColumnModal(columnId = null) {
        const modal = this.columnModal;
        const form = this.columnForm;
        const columnNameInput = document.getElementById('column-name');

        if (columnId) {
            // Editing existing column
            const column = this.columns.find(c => c.id === columnId);
            if (column) {
                columnNameInput.value = column.title;
                form.dataset.columnId = columnId;
            }
        } else {
            // Adding new column
            columnNameInput.value = '';
            delete form.dataset.columnId;
        }

        modal.style.display = 'flex';
    }

    showTaskModal(taskId = null) {
        const modal = this.taskModal;
        const form = this.taskForm;

        // Reset form
        form.reset();
        document.getElementById('task-id').value = '';

        if (taskId) {
            // Editing existing task
            const task = this.tasks.find(t => t.id === taskId);
            if (task) {
                document.getElementById('task-id').value = task.id;
                document.getElementById('task-title').value = task.title;
                document.getElementById('task-description').value = task.description || '';
                document.getElementById('task-assignee').value = task.assignee || '';
                document.getElementById('task-due-date').value = task.dueDate || '';
                document.getElementById('task-priority').value = task.priority || 'medium';
            }
        }

        modal.style.display = 'flex';
    }

    closeModals() {
        this.taskModal.style.display = 'none';
        this.columnModal.style.display = 'none';
    }

    handleTaskFormSubmit(e) {
        e.preventDefault();

        const taskId = document.getElementById('task-id').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const assignee = document.getElementById('task-assignee').value;
        const dueDate = document.getElementById('task-due-date').value;
        const priority = document.getElementById('task-priority').value;

        if (taskId) {
            // Update existing task
            const taskIndex = this.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                this.tasks[taskIndex] = {
                    ...this.tasks[taskIndex],
                    title,
                    description,
                    assignee,
                    dueDate,
                    priority
                };
            }
        } else {
            // Add new task to the first column
            const firstColumn = this.columns[0];
            if (firstColumn) {
                const newTask = {
                    id: Date.now().toString(),
                    title,
                    description,
                    assignee,
                    dueDate,
                    priority,
                    columnId: firstColumn.id,
                    createdBy: this.currentUser,
                    createdAt: new Date().toISOString()
                };
                this.tasks.push(newTask);
            }
        }

        this.saveData();
        this.renderBoard();
        this.closeModals();
    }

    handleColumnFormSubmit(e) {
        e.preventDefault();

        const columnId = this.columnForm.dataset.columnId;
        const columnName = document.getElementById('column-name').value;

        if (columnId) {
            // Update existing column
            const columnIndex = this.columns.findIndex(c => c.id === columnId);
            if (columnIndex !== -1) {
                this.columns[columnIndex].title = columnName;
            }
        } else {
            // Add new column
            const newColumn = {
                id: Date.now().toString(),
                title: columnName
            };
            this.columns.push(newColumn);
        }

        this.saveData();
        this.renderBoard();
        this.closeModals();
    }

    editColumn(e) {
        const columnId = e.target.closest('button').dataset.columnId;
        this.showColumnModal(columnId);
    }

    deleteColumn(e) {
        const columnId = e.target.closest('button').dataset.columnId;

        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            // Remove column
            this.columns = this.columns.filter(c => c.id !== columnId);

            // Remove tasks in this column
            this.tasks = this.tasks.filter(t => t.columnId !== columnId);

            this.saveData();
            this.renderBoard();
        }
    }

    logout() {
        // In a real app, you would handle authentication here
        this.currentUser = 'Guest';
        this.userName.textContent = this.currentUser;
        alert('Logged out successfully');
    }

    // Drag and drop functionality
    handleDragStart(e) {
        this.draggedTask = e.target;
        e.target.classList.add('dragging');
        e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
        e.dataTransfer.effectAllowed = 'move';
    }

    handleDragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';

        const taskList = e.target.closest('.task-list');
        if (taskList) {
            const afterElement = this.getDragAfterElement(taskList, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement) {
                taskList.insertBefore(draggable, afterElement);
            } else {
                taskList.appendChild(draggable);
            }
        }
    }

    handleDrop(e) {
        e.preventDefault();

        if (this.draggedTask) {
            this.draggedTask.classList.remove('dragging');

            const taskId = e.dataTransfer.getData('text/plain');
            const newColumnId = e.target.closest('.task-list')?.dataset.columnId;

            if (taskId && newColumnId) {
                // Update task's column
                const taskIndex = this.tasks.findIndex(t => t.id === taskId);
                if (taskIndex !== -1) {
                    this.tasks[taskIndex].columnId = newColumnId;
                    this.saveData();

                    // In a real app, you would emit this change to the server
                }
            }

            this.draggedTask = null;
        }
    }

    getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;

            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }
}
