// Project functions
function loadProjects() {
    if (!currentUser) return;

    const projectsRef = database.ref(`users/${currentUser.uid}/projects`);
    projectsRef.on('value', snapshot => {
        projectList.innerHTML = '';
        const projects = snapshot.val();

        if (!projects) {
            welcomeMessage.classList.remove('d-none');
            boardContainer.classList.add('d-none');
            return;
        }

        Object.keys(projects).forEach(projectId => {
            const project = projects[projectId];
            const projectItem = document.createElement('a');
            projectItem.href = '#';
            projectItem.className = `list-group-item list-group-item-action project-item ${currentProjectId === projectId ? 'active' : ''}`;
            projectItem.textContent = project.name;
            projectItem.dataset.projectId = projectId;
            projectItem.addEventListener('click', () => loadProject(projectId));
            projectList.appendChild(projectItem);
        });

        // Load the first project if none is selected
        if (!currentProjectId && Object.keys(projects).length > 0) {
            loadProject(Object.keys(projects)[0]);
        }
    });
}

function createProject() {
    if (!currentUser || !projectName.value.trim()) return;

    const newProjectRef = database.ref(`users/${currentUser.uid}/projects`).push();
    const projectId = newProjectRef.key;

    const projectData = {
        name: projectName.value.trim(),
        description: projectDescription.value.trim(),
        createdAt: firebase.database.ServerValue.TIMESTAMP,
        owner: currentUser.uid,
        columns: {
            'todo': {
                name: 'To Do',
                order: 0
            },
            'in-progress': {
                name: 'In Progress',
                order: 1
            },
            'done': {
                name: 'Done',
                order: 2
            }
        }
    };

    newProjectRef.set(projectData)
        .then(() => {
            projectForm.reset();
            newProjectModal.hide();
            loadProject(projectId);
        })
        .catch(error => {
            console.error('Error creating project:', error);
            alert('Failed to create project: ' + error.message);
        });
}

function loadProject(projectId) {
    if (!currentUser) return;

    currentProjectId = projectId;

    // Update active project in UI
    document.querySelectorAll('.project-item').forEach(item => {
        item.classList.toggle('active', item.dataset.projectId === projectId);
    });

    // Load project data
    const projectRef = database.ref(`users/${currentUser.uid}/projects/${projectId}`);
    projectRef.on('value', snapshot => {
        const project = snapshot.val();
        if (!project) return;

        projectTitle.textContent = project.name;
        welcomeMessage.classList.add('d-none');
        boardContainer.classList.remove('d-none');

        // Load columns
        loadColumns(project.columns || {});

        // Load team members
        loadTeamMembers(projectId);
    });
}

function loadColumns(columns) {
    board.innerHTML = '';

    // Sort columns by order
    const sortedColumns = Object.entries(columns).sort((a, b) => a[1].order - b[1].order);

    sortedColumns.forEach(([columnId, column]) => {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = columnId;

        columnElement.innerHTML = `
            <div class="column-header">
                <h3 class="column-title">${column.name}</h3>
                <div class="column-actions">
                    <button class="btn btn-sm btn-outline-secondary edit-column-btn" data-column-id="${columnId}">Edit</button>
                    <button class="btn btn-sm btn-outline-danger delete-column-btn" data-column-id="${columnId}">Delete</button>
                </div>
            </div>
            <div class="column-body" id="column-${columnId}">
                <!-- Tasks will be loaded here -->
            </div>
            <button class="btn btn-sm btn-outline-secondary add-task-btn" data-column-id="${columnId}">+ Add Task</button>
        `;

        board.appendChild(columnElement);

        // Load tasks for this column
        loadTasks(columnId);

        // Set up event listeners for column actions
        columnElement.querySelector('.add-task-btn').addEventListener('click', (e) => {
            currentColumnId = e.target.dataset.columnId;
            currentTaskId = null;
            taskForm.reset();
            taskModal.show();
        });

        columnElement.querySelector('.edit-column-btn').addEventListener('click', (e) => {
            const columnId = e.target.dataset.columnId;
            const newName = prompt('Enter new column name:');
            if (newName && newName.trim()) {
                database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/columns/${columnId}/name`)
                    .set(newName.trim());
            }
        });

        columnElement.querySelector('.delete-column-btn').addEventListener('click', (e) => {
            const columnId = e.target.dataset.columnId;
            if (confirm('Are you sure you want to delete this column? All tasks in it will be lost.')) {
                database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/columns/${columnId}`)
                    .remove();
            }
        });
    });
}

function addColumn() {
    if (!currentUser || !currentProjectId) return;

    const columnName = prompt('Enter column name:');
    if (!columnName || !columnName.trim()) return;

    const columnsRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/columns`);
    columnsRef.once('value', snapshot => {
        const columns = snapshot.val() || {};
        const order = Object.keys(columns).length;

        const newColumnRef = columnsRef.push();
        newColumnRef.set({
            name: columnName.trim(),
            order: order
        });
    });
}

function loadTasks(columnId) {
    if (!currentUser || !currentProjectId) return;

    const tasksRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/tasks`)
        .orderByChild('columnId')
        .equalTo(columnId);

    tasksRef.on('value', snapshot => {
        const columnBody = document.getElementById(`column-${columnId}`);
        if (!columnBody) return;

        columnBody.innerHTML = '';

        const tasks = snapshot.val();
        if (!tasks) return;

        Object.keys(tasks).forEach(taskId => {
            const task = tasks[taskId];
            const taskElement = document.createElement('div');
            taskElement.className = 'task';
            taskElement.dataset.taskId = taskId;
            taskElement.dataset.columnId = columnId;

            let assigneeName = 'Unassigned';
            if (task.assignee) {
                const member = document.querySelector(`.member-item[data-user-id="${task.assignee}"]`);
                assigneeName = member ? member.querySelector('.member-name').textContent : 'Unknown';
            }

            taskElement.innerHTML = `
                <div class="task-title">${task.title}</div>
                <div class="task-meta">
                    <span>${assigneeName}</span>
                    <span class="priority-${task.priority || 'medium'}">${task.priority || 'medium'}</span>
                </div>
            `;

            taskElement.addEventListener('click', () => {
                currentTaskId = taskId;
                currentColumnId = columnId;
                loadTaskDetails(task);
                taskModal.show();
            });

            columnBody.appendChild(taskElement);
        });
    });
}

function loadTaskDetails(task) {
    taskTitle.value = task.title || '';
    taskDescription.value = task.description || '';
    taskAssignee.value = task.assignee || '';
    taskDueDate.value = task.dueDate || '';
    taskPriority.value = task.priority || 'medium';
}

function saveTask() {
    if (!currentUser || !currentProjectId || !currentColumnId) return;

    const taskData = {
        title: taskTitle.value.trim(),
        description: taskDescription.value.trim(),
        assignee: taskAssignee.value,
        dueDate: taskDueDate.value,
        priority: taskPriority.value,
        columnId: currentColumnId,
        updatedAt: firebase.database.ServerValue.TIMESTAMP
    };

    if (!taskData.title) {
        alert('Task title is required');
        return;
    }

    let taskRef;
    if (currentTaskId) {
        taskRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/tasks/${currentTaskId}`);
    } else {
        taskRef = database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/tasks`).push();
    }

    taskRef.set(taskData)
        .then(() => {
            taskForm.reset();
            taskModal.hide();
        })
        .catch(error => {
            console.error('Error saving task:', error);
            alert('Failed to save task: ' + error.message);
        });
}

// Team functions
function loadTeamMembers(projectId) {
    if (!currentUser) return;

    const membersRef = database.ref(`projects/${projectId}/members`);
    membersRef.on('value', snapshot => {
        teamMembers.innerHTML = '';
        const members = snapshot.val() || {};

        // Add owner as first member
        const ownerItem = document.createElement('div');
        ownerItem.className = 'member-item';
        ownerItem.dataset.userId = currentUser.uid;
        ownerItem.innerHTML = `
            <div class="member-avatar"></div>
            <div>
                <div class="member-name">${currentUser.displayName || currentUser.email}</div>
                <div class="member-role">Owner</div>
            </div>
        `;
        teamMembers.appendChild(ownerItem);

        // Add other members
        Object.keys(members).forEach(userId => {
            const member = members[userId];
            const memberItem = document.createElement('div');
            memberItem.className = 'member-item';
            memberItem.dataset.userId = userId;
            memberItem.innerHTML = `
                <div class="member-avatar"></div>
                <div>
                    <div class="member-name">${member.name || member.email}</div>
                    <div class="member-role">${member.role}</div>
                </div>
            `;
            teamMembers.appendChild(memberItem);
        });

        // Update assignee dropdown in task form
        updateAssigneeDropdown();
    });
}

function updateAssigneeDropdown() {
    taskAssignee.innerHTML = '<option value="">Unassigned</option>';

    document.querySelectorAll('.member-item').forEach(member => {
        const userId = member.dataset.userId;
        const name = member.querySelector('.member-name').textContent;
        const option = document.createElement('option');
        option.value = userId;
        option.textContent = name;
        taskAssignee.appendChild(option);
    });
}

function shareProject() {
    if (!currentUser || !currentProjectId || !shareEmail.value.trim()) return;

    const email = shareEmail.value.trim();
    const role = shareRole.value;

    // In a real app, you would send an invitation email here
    // For this demo, we'll just add the member to the project
    const membersRef = database.ref(`projects/${currentProjectId}/members`);
    membersRef.once('value', snapshot => {
        const members = snapshot.val() || {};

        // Check if user already exists (in a real app, you'd look up by email)
        const existingMember = Object.values(members).find(m => m.email === email);
        if (existingMember) {
            alert('This user is already a member of the project');
            return;
        }

        // Add new member
        const newMemberRef = membersRef.push();
        newMemberRef.set({
            email: email,
            role: role,
            addedBy: currentUser.uid,
            addedAt: firebase.database.ServerValue.TIMESTAMP
        });

        shareProjectModal.hide();
        shareEmail.value = '';
    });
}

// Drag-and-drop functionality
function initDragula() {
    drake = dragula({
        isContainer: function (el) {
            return el.classList.contains('column-body');
        },
        moves: function (el, source, handle, sibling) {
            return el.classList.contains('task');
        },
        accepts: function (el, target, source, sibling) {
            return target.classList.contains('column-body');
        }
    });

    drake.on('drop', function (el, target, source, sibling) {
        if (!currentUser || !currentProjectId) return;

        const taskId = el.dataset.taskId;
        const newColumnId = target.parentElement.dataset.columnId;

        // Update task's column in database
        database.ref(`users/${currentUser.uid}/projects/${currentProjectId}/tasks/${taskId}/columnId`)
            .set(newColumnId)
            .catch(error => {
                console.error('Error moving task:', error);
                // Revert the UI change if the database update fails
                source.appendChild(el);
            });
    });
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
