## JavaScript Implementation

```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize the app
    const app = new TaskBoardApp();
    app.init();
});

class TaskBoardApp {
    constructor() {
        this.currentUser = 'Guest';
        this.tasks = JSON.parse(localStorage.getItem('tasks')) || {
            todo: [],
            'in-progress': [],
            done: []
        };
        this.draggedTask = null;
    }

    init() {
        this.cacheDOM();
        this.bindEvents();
        this.renderTasks();
        this.setupDragAndDrop();
        this.setupRealTimeUpdates();
    }

    cacheDOM() {
        this.$boards = document.querySelectorAll('.board');
        this.$taskLists = document.querySelectorAll('.task-list');
        this.$addTaskBtns = document.querySelectorAll('.add-task-btn');
        this.$modal = document.getElementById('task-modal');
        this.$closeModal = document.querySelector('.close-modal');
        this.$taskForm = document.getElementById('task-form');
        this.$currentUser = document.getElementById('current-user');
        this.$changeUserBtn = document.getElementById('change-user');
    }

    bindEvents() {
        // Add task buttons
        this.$addTaskBtns.forEach(btn => {
            btn.addEventListener('click', () => this.openTaskModal(null, btn.dataset.board));
        });

        // Close modal
        this.$closeModal.addEventListener('click', () => this.closeTaskModal());

        // Form submission
        this.$taskForm.addEventListener('submit', (e) => {
            e.preventDefault();
            this.saveTask();
        });

        // Change user
        this.$changeUserBtn.addEventListener('click', () => this.changeUser());
    }

    openTaskModal(taskId, boardId) {
        const modalTitle = document.getElementById('modal-title');
        const taskIdInput = document.getElementById('task-id');
        const taskBoardInput = document.getElementById('task-board');
        const taskTitleInput = document.getElementById('task-title');
        const taskDescInput = document.getElementById('task-description');
        const taskPriorityInput = document.getElementById('task-priority');
        const taskAssigneeInput = document.getElementById('task-assignee');

        if (taskId) {
            // Editing existing task
            modalTitle.textContent = 'Edit Task';
            const task = this.findTaskById(taskId);

            if (task) {
                taskIdInput.value = task.id;
                taskBoardInput.value = task.board;
                taskTitleInput.value = task.title;
                taskDescInput.value = task.description || '';
                taskPriorityInput.value = task.priority || 'medium';
                taskAssigneeInput.value = task.assignee || '';
            }
        } else {
            // Adding new task
            modalTitle.textContent = 'Add New Task';
            taskIdInput.value = '';
            taskBoardInput.value = boardId;
            taskTitleInput.value = '';
            taskDescInput.value = '';
            taskPriorityInput.value = 'medium';
            taskAssigneeInput.value = '';
        }

        this.$modal.style.display = 'block';
    }

    closeTaskModal() {
        this.$modal.style.display = 'none';
    }

    saveTask() {
        const taskId = document.getElementById('task-id').value;
        const boardId = document.getElementById('task-board').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const priority = document.getElementById('task-priority').value;
        const assignee = document.getElementById('task-assignee').value;

        if (!title.trim()) {
            alert('Please enter a task title');
            return;
        }

        if (taskId) {
            // Update existing task
            const task = this.findTaskById(taskId);
            if (task) {
                // Remove from old board if board changed
                if (task.board !== boardId) {
                    this.tasks[task.board] = this.tasks[task.board].filter(t => t.id !== taskId);
                }

                // Update task properties
                task.title = title;
                task.description = description;
                task.priority = priority;
                task.assignee = assignee;
                task.board = boardId;
            }
        } else {
            // Create new task
            const newTask = {
                id: Date.now().toString(),
                title,
                description,
                priority,
                assignee,
                board: boardId,
                createdBy: this.currentUser,
                createdAt: new Date().toISOString()
            };

            this.tasks[boardId].push(newTask);
        }

        this.saveTasksToStorage();
        this.renderTasks();
        this.closeTaskModal();

        // Broadcast update to other users (simulated with localStorage event)
        this.broadcastUpdate('task_updated');
    }

    findTaskById(taskId) {
        for (const board in this.tasks) {
            const task = this.tasks[board].find(t => t.id === taskId);
            if (task) return task;
        }
        return null;
    }

    renderTasks() {
        this.$taskLists.forEach(list => {
            list.innerHTML = '';
            const boardId = list.id.replace('-list', '');

            this.tasks[boardId].forEach(task => {
                const taskCard = this.createTaskCard(task);
                list.appendChild(taskCard);
            });
        });
    }

    createTaskCard(task) {
        const taskCard = document.createElement('div');
        taskCard.className = 'task-card';
        taskCard.draggable = true;
        taskCard.dataset.taskId = task.id;
        taskCard.dataset.boardId = task.board;

        taskCard.innerHTML = `
            <div class="task-card-header">
                <h3 class="task-title">${task.title}</h3>
                <span class="task-priority ${task.priority}">${task.priority}</span>
            </div>
            ${task.description ? `<p class="task-description">${task.description}</p>` : ''}
            <div class="task-footer">
                <div class="task-assignee">
                    <i class="fas fa-user"></i>
                    <span>${task.assignee || 'Unassigned'}</span>
                </div>
                <div class="task-actions">
                    <button class="task-action-btn edit-task" data-task-id="${task.id}">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button class="task-action-btn delete-task" data-task-id="${task.id}">
                        <i class="fas fa-trash"></i>
                    </button>
                </div>
            </div>
        `;

        // Add event listeners for drag and drop
        taskCard.addEventListener('dragstart', (e) => this.handleDragStart(e));
        taskCard.addEventListener('dragend', (e) => this.handleDragEnd(e));

        // Add event listeners for edit and delete buttons
        taskCard.querySelector('.edit-task').addEventListener('click', (e) => {
            e.stopPropagation();
            this.openTaskModal(task.id, task.board);
        });

        taskCard.querySelector('.delete-task').addEventListener('click', (e) => {
            e.stopPropagation();
            this.deleteTask(task.id);
        });

        return taskCard;
    }

    setupDragAndDrop() {
        this.$taskLists.forEach(list => {
            list.addEventListener('dragover', (e) => this.handleDragOver(e));
            list.addEventListener('dragenter', (e) => this.handleDragEnter(e));
            list.addEventListener('dragleave', (e) => this.handleDragLeave(e));
            list.addEventListener('drop', (e) => this.handleDrop(e));
        });
    }

    handleDragStart(e) {
        this.draggedTask = e.target;
        e.target.classList.add('dragging');
        e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
        e.dataTransfer.effectAllowed = 'move';
    }

    handleDragEnd(e) {
        e.target.classList.remove('dragging');
        this.draggedTask = null;
    }

    handleDragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    }

    handleDragEnter(e) {
        e.preventDefault();
        if (e.target.classList.contains('task-list')) {
            e.target.classList.add('drag-over');
        }
    }

    handleDragLeave(e) {
        if (e.target.classList.contains('task-list')) {
            e.target.classList.remove('drag-over');
        }
    }

    handleDrop(e) {
        e.preventDefault();
        e.target.classList.remove('drag-over');

        if (!this.draggedTask) return;

        const taskId = e.dataTransfer.getData('text/plain');
        const newBoardId = e.target.id.replace('-list', '');

        // Find the task and update its board
        const task = this.findTaskById(taskId);
        if (task && task.board !== newBoardId) {
            // Remove from old board
            this.tasks[task.board] = this.tasks[task.board].filter(t => t.id !== taskId);

            // Add to new board
            task.board = newBoardId;
            this.tasks[newBoardId].push(task);

            this.saveTasksToStorage();
            this.renderTasks();

            // Broadcast update to other users
            this.broadcastUpdate('task_moved');
        }
    }

    deleteTask(taskId) {
        if (confirm('Are you sure you want to delete this task?')) {
            for (const board in this.tasks) {
                this.tasks[board] = this.tasks[board].filter(task => task.id !== taskId);
            }

            this.saveTasksToStorage();
            this.renderTasks();

            // Broadcast update to other users
            this.broadcastUpdate('task_deleted');
        }
    }

    changeUser() {
        const newUser = prompt('Enter your username:', this.currentUser);
        if (newUser && newUser.trim()) {
            this.currentUser = newUser.trim();
            this.$currentUser.textContent = `User: ${this.currentUser}`;
        }
    }

    saveTasksToStorage() {
        localStorage.setItem('tasks', JSON.stringify(this.tasks));
    }

    setupRealTimeUpdates() {
        // Simulate real-time updates with localStorage events
        window.addEventListener('storage', (e) => {
            if (e.key === 'tasks') {
                this.tasks = JSON.parse(e.newValue) || {
                    todo: [],
                    'in-progress': [],
                    done: []
                };
                this.renderTasks();
            }
        });
    }

    broadcastUpdate(eventType) {
        // In a real app, this would use WebSockets or similar
        // For this demo, we'll just trigger a storage event
        localStorage.setItem('tasks', JSON.stringify(this.tasks));
    }
}
