```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();
const auth = firebase.auth();

// DOM Elements
const boardsContainer = document.getElementById('boards-container');
const addBoardBtn = document.getElementById('add-board-btn');
const boardModal = document.getElementById('board-modal');
const taskModal = document.getElementById('task-modal');
const boardForm = document.getElementById('board-form');
const taskForm = document.getElementById('task-form');
const searchInput = document.getElementById('search-tasks');
const userNameElement = document.getElementById('user-name');
const logoutBtn = document.getElementById('logout-btn');

// App state
let currentUser = null;
let currentBoardId = null;
let currentTaskId = null;
let boards = {};

// Initialize the app
function initApp() {
    // Check authentication state
    auth.onAuthStateChanged(user => {
        if (user) {
            currentUser = user;
            userNameElement.textContent = user.displayName || user.email;
            loadBoards();
        } else {
            // Redirect to login or show login form
            userNameElement.textContent = 'Guest';
            // In a real app, you would show a login form here
            console.log('User not logged in');
        }
    });

    // Event listeners
    addBoardBtn.addEventListener('click', openBoardModal);
    boardForm.addEventListener('submit', createBoard);
    taskForm.addEventListener('submit', saveTask);
    searchInput.addEventListener('input', filterTasks);
    logoutBtn.addEventListener('click', logout);

    // Close modals when clicking X
    document.querySelectorAll('.close-modal').forEach(btn => {
        btn.addEventListener('click', () => {
            boardModal.style.display = 'none';
            taskModal.style.display = 'none';
        });
    });

    // Close modals when clicking outside
    window.addEventListener('click', (e) => {
        if (e.target === boardModal) boardModal.style.display = 'none';
        if (e.target === taskModal) taskModal.style.display = 'none';
    });
}

// Load boards from Firebase
function loadBoards() {
    if (!currentUser) return;

    const boardsRef = database.ref(`users/${currentUser.uid}/boards`);
    boardsRef.on('value', (snapshot) => {
        boards = snapshot.val() || {};
        renderBoards();
    });
}

// Render all boards
function renderBoards() {
    boardsContainer.innerHTML = '';

    for (const boardId in boards) {
        const board = boards[boardId];
        const boardElement = createBoardElement(boardId, board);
        boardsContainer.appendChild(boardElement);

        // Initialize drag and drop for this board
        initDragAndDrop(boardId);
    }
}

// Create a board element
function createBoardElement(boardId, board) {
    const boardElement = document.createElement('div');
    boardElement.className = 'board';
    boardElement.dataset.boardId = boardId;

    boardElement.innerHTML = `
        <div class="board-header">
            <h3 class="board-title">${board.name}</h3>
            <div class="board-actions">
                <button class="btn add-task-btn" data-board-id="${boardId}">
                    <i class="fas fa-plus"></i> Add Task
                </button>
                <button class="btn danger delete-board-btn" data-board-id="${boardId}">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
        <div class="task-list" id="task-list-${boardId}">
            ${renderTasks(board.tasks || {})}
        </div>
    `;

    // Add event listeners for add task button
    boardElement.querySelector('.add-task-btn').addEventListener('click', (e) => {
        currentBoardId = e.target.dataset.boardId;
        currentTaskId = null;
        openTaskModal();
    });

    // Add event listener for delete board button
    boardElement.querySelector('.delete-board-btn').addEventListener('click', (e) => {
        if (confirm('Are you sure you want to delete this board?')) {
            deleteBoard(e.target.dataset.boardId);
        }
    });

    return boardElement;
}

// Render tasks for a board
function renderTasks(tasks) {
    let tasksHtml = '';

    for (const taskId in tasks) {
        const task = tasks[taskId];
        tasksHtml += createTaskCard(taskId, task);
    }

    return tasksHtml;
}

// Create a task card element
function createTaskCard(taskId, task) {
    return `
        <div class="task-card" data-task-id="${taskId}">
            <div class="task-title">${task.title}</div>
            <div class="task-description">${task.description || ''}</div>
            <div class="task-meta">
                <span class="task-priority ${task.priority || 'low'}">
                    ${task.priority ? task.priority.charAt(0).toUpperCase() + task.priority.slice(1) : 'Low'}
                </span>
                <span class="task-due-date">${task.dueDate || ''}</span>
            </div>
        </div>
    `;
}

// Initialize drag and drop for a board
function initDragAndDrop(boardId) {
    const taskList = document.getElementById(`task-list-${boardId}`);

    Sortable.create(taskList, {
        group: 'tasks',
        animation: 150,
        onEnd: function (evt) {
            const fromBoardId = evt.from.closest('.board').dataset.boardId;
            const toBoardId = evt.to.closest('.board').dataset.boardId;
            const taskId = evt.item.dataset.taskId;

            if (fromBoardId !== toBoardId) {
                moveTask(taskId, fromBoardId, toBoardId, evt.newIndex);
            } else if (evt.oldIndex !== evt.newIndex) {
                reorderTasks(toBoardId, evt.oldIndex, evt.newIndex);
            }
        }
    });
}

// Open board creation modal
function openBoardModal() {
    boardModal.style.display = 'flex';
    document.getElementById('board-name').value = '';
}

// Create a new board
function createBoard(e) {
    e.preventDefault();

    if (!currentUser) return;

    const boardName = document.getElementById('board-name').value.trim();
    if (!boardName) return;

    const newBoardRef = database.ref(`users/${currentUser.uid}/boards`).push();
    newBoardRef.set({
        name: boardName,
        createdAt: firebase.database.ServerValue.TIMESTAMP,
        tasks: {}
    });

    boardModal.style.display = 'none';
}

// Delete a board
function deleteBoard(boardId) {
    if (!currentUser) return;

    database.ref(`users/${currentUser.uid}/boards/${boardId}`).remove();
}

// Open task modal
function openTaskModal(task = null) {
    taskModal.style.display = 'flex';

    if (task) {
        document.getElementById('modal-title').textContent = 'Edit Task';
        document.getElementById('task-title').value = task.title || '';
        document.getElementById('task-description').value = task.description || '';
        document.getElementById('task-due-date').value = task.dueDate || '';
        document.getElementById('task-priority').value = task.priority || 'low';
        document.getElementById('task-assignee').value = task.assignee || '';
    } else {
        document.getElementById('modal-title').textContent = 'Create Task';
        document.getElementById('task-form').reset();
    }
}

// Save task (create or update)
function saveTask(e) {
    e.preventDefault();

    if (!currentUser || !currentBoardId) return;

    const taskData = {
        title: document.getElementById('task-title').value.trim(),
        description: document.getElementById('task-description').value.trim(),
        dueDate: document.getElementById('task-due-date').value,
        priority: document.getElementById('task-priority').value,
        assignee: document.getElementById('task-assignee').value.trim(),
        createdAt: firebase.database.ServerValue.TIMESTAMP,
        createdBy: currentUser.uid
    };

    if (!taskData.title) return;

    if (currentTaskId) {
        // Update existing task
        database.ref(`users/${currentUser.uid}/boards/${currentBoardId}/tasks/${currentTaskId}`)
            .update(taskData);
    } else {
        // Create new task
        const newTaskRef = database.ref(`users/${currentUser.uid}/boards/${currentBoardId}/tasks`).push();
        newTaskRef.set(taskData);
    }

    taskModal.style.display = 'none';
}

// Move task between boards
function moveTask(taskId, fromBoardId, toBoardId, newIndex) {
    if (!currentUser) return;

    const taskRef = database.ref(`users/${currentUser.uid}/boards/${fromBoardId}/tasks/${taskId}`);
    taskRef.once('value', (snapshot) => {
        const taskData = snapshot.val();

        // Remove from old board
        taskRef.remove();

        // Add to new board
        const newTaskRef = database.ref(`users/${currentUser.uid}/boards/${toBoardId}/tasks`).push();
        newTaskRef.set(taskData);

        // Reorder if needed
        if (newIndex !== undefined) {
            reorderTasks(toBoardId, Object.keys(boards[toBoardId].tasks || {}).length - 1, newIndex);
        }
    });
}

// Reorder tasks within a board
function reorderTasks(boardId, oldIndex, newIndex) {
    if (!currentUser || oldIndex === newIndex) return;

    const tasksRef = database.ref(`users/${currentUser.uid}/boards/${boardId}/tasks`);
    tasksRef.once('value', (snapshot) => {
        const tasks = snapshot.val();
        if (!tasks) return;

        const taskIds = Object.keys(tasks);
        const [movedTaskId] = taskIds.splice(oldIndex, 1);
        taskIds.splice(newIndex, 0, movedTaskId);

        const updatedTasks = {};
        taskIds.forEach((id, index) => {
            updatedTasks[id] = tasks[id];
        });

        tasksRef.set(updatedTasks);
    });
}

// Filter tasks based on search input
function filterTasks() {
    const searchTerm = searchInput.value.toLowerCase();

    document.querySelectorAll('.task-card').forEach(taskCard => {
        const taskTitle = taskCard.querySelector('.task-title').textContent.toLowerCase();
        const taskDescription = taskCard.querySelector('.task-description').textContent.toLowerCase();

        if (taskTitle.includes(searchTerm) || taskDescription.includes(searchTerm)) {
            taskCard.style.display = 'block';
        } else {
            taskCard.style.display = 'none';
        }
    });
}

// Logout function
function logout() {
    auth.signOut().then(() => {
        currentUser = null;
        boardsContainer.innerHTML = '';
        userNameElement.textContent = 'Guest';
    });
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
