const newCollaboratorEmailInput = document.getElementById('new-collaborator-email');
const addCollaboratorBtn = document.getElementById('add-collaborator-btn');

// App State
let currentProjectId = null;
let currentTaskId = null;
let projects = [];
let socket = null;

// Initialize the app
function initApp() {
    // Load projects from localStorage
    loadProjects();

    // Set up event listeners
    setupEventListeners();

    // Connect to WebSocket server for real-time updates
    setupWebSocket();

    // Load the first project or create a default one
    if (projects.length === 0) {
        createDefaultProject();
    } else {
        loadProject(projects[0].id);
    }
}

// Load projects from localStorage
function loadProjects() {
    const savedProjects = localStorage.getItem('taskBoardProjects');
    if (savedProjects) {
        projects = JSON.parse(savedProjects);
        renderProjectList();
    }
}

// Save projects to localStorage
function saveProjects() {
    localStorage.setItem('taskBoardProjects', JSON.stringify(projects));
}

// Create a default project if none exists
function createDefaultProject() {
    const defaultProject = {
        id: generateId(),
        name: 'My Project',
        description: 'Default project',
        columns: [
            { id: generateId(), name: 'To Do', tasks: [] },
            { id: generateId(), name: 'In Progress', tasks: [] },
            { id: generateId(), name: 'Done', tasks: [] }
        ],
        collaborators: []
    };

    projects.push(defaultProject);
    saveProjects();
    loadProject(defaultProject.id);
}

// Load a project by ID
function loadProject(projectId) {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    currentProjectId = projectId;
    projectTitle.textContent = project.name;
    renderBoard(project);
    highlightActiveProject(projectId);

    // Notify other collaborators about the project change
    if (socket) {
        socket.emit('projectChange', {
            projectId: currentProjectId,
            user: userName.textContent
        });
    }
}

// Render the project list in the sidebar
function renderProjectList() {
    projectList.innerHTML = '';

    projects.forEach(project => {
        const li = document.createElement('li');
        li.textContent = project.name;
        li.dataset.projectId = project.id;

        if (project.id === currentProjectId) {
            li.classList.add('active');
        }

        li.addEventListener('click', () => loadProject(project.id));
        projectList.appendChild(li);
    });
}

// Highlight the active project in the sidebar
function highlightActiveProject(projectId) {
    const projectItems = document.querySelectorAll('#project-list li');
    projectItems.forEach(item => {
        item.classList.remove('active');
        if (item.dataset.projectId === projectId) {
            item.classList.add('active');
        }
    });
}

// Render the board with columns and tasks
function renderBoard(project) {
    board.innerHTML = '';

    project.columns.forEach(column => {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = column.id;

        columnElement.innerHTML = `
            <div class="column-header">
                <h3>${column.name}</h3>
                <div class="column-actions">
                    <button class="edit-column-btn" title="Edit column">
                        <i class="fas fa-pencil-alt"></i>
                    </button>
                    <button class="delete-column-btn" title="Delete column">
                        <i class="fas fa-trash-alt"></i>
                    </button>
                </div>
            </div>
            <div class="column-body" data-column-id="${column.id}">
                ${column.tasks.map(task => createTaskElement(task)).join('')}
                <div class="add-task-btn" data-column-id="${column.id}">
                    <i class="fas fa-plus"></i> Add Task
                </div>
            </div>
        `;

        board.appendChild(columnElement);
    });

    // Add event listeners for column actions
    document.querySelectorAll('.edit-column-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const columnId = e.target.closest('.column').dataset.columnId;
            editColumn(columnId);
        });
    });

    document.querySelectorAll('.delete-column-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            const columnId = e.target.closest('.column').dataset.columnId;
            deleteColumn(columnId);
        });
    });

    // Add event listeners for add task buttons
    document.querySelectorAll('.add-task-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const columnId = e.target.closest('.add-task-btn').dataset.columnId;
            openTaskModal(null, columnId);
        });
    });

    // Set up drag and drop
    setupDragAndDrop();
}

// Create a task element
function createTaskElement(task) {
    return `
        <div class="task" draggable="true" data-task-id="${task.id}">
            <div class="task-header">
                <div class="task-title">${task.title}</div>
                <div class="task-priority ${task.priority}"></div>
            </div>
            <div class="task-meta">
                <div class="task-due-date">${task.dueDate ? formatDate(task.dueDate) : ''}</div>
                <div class="task-assignee">
                    ${task.assignee ? `<i class="fas fa-user"></i> ${task.assignee}` : ''}
                </div>
            </div>
        </div>
    `;
}

// Format date for display
function formatDate(dateString) {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric'
    });
}

// Open the task modal for editing or creating a new task
function openTaskModal(taskId, columnId) {
    const project = projects.find(p => p.id === currentProjectId);
    if (!project) return;

    if (taskId) {
        // Editing existing task
        const column = project.columns.find(c => c.tasks.some(t => t.id === taskId));
        if (!column) return;

        const task = column.tasks.find(t => t.id === taskId);
        if (!task) return;

        currentTaskId = taskId;
        document.getElementById('modal-title').textContent = 'Edit Task';
        taskTitleInput.value = task.title;
        taskDescriptionInput.value = task.description || '';
        taskDueDateInput.value = task.dueDate || '';
