        currentTaskId = null;
        document.getElementById('modal-title').textContent = 'Add New Task';
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskDueDateInput.value = '';
        taskPriorityInput.value = 'medium';
