// Delete a column
function deleteColumn(columnId) {
    const project = projects.find(p => p.id === currentProjectId);
    if (!project) return;

    if (project.columns.length <= 1) {
        alert('You cannot delete the last column.');
        return;
    }

    if (!confirm('Are you sure you want to delete this column and all its tasks?')) {
        return;
    }

    project.columns = project.columns.filter(c => c.id !== columnId);
    saveProjects();
    renderBoard(project);

    // Notify collaborators
    if (socket) {
        socket.emit('columnDeleted', {
            projectId: currentProjectId,
            columnId: columnId,
            user: userName.textContent
        });
    }
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const tasks = document.querySelectorAll('.task');
    const columnBodies = document.querySelectorAll('.column-body');

    tasks.forEach(task => {
        task.addEventListener('dragstart', handleDragStart);
    });

    columnBodies.forEach(columnBody => {
        columnBody.addEventListener('dragover', handleDragOver);
        columnBody.addEventListener('dragenter', handleDragEnter);
        columnBody.addEventListener('dragleave', handleDragLeave);
        columnBody.addEventListener('drop', handleDrop);
    });
}

// Drag and drop event handlers
function handleDragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
    e.target.classList.add('dragging');
    setTimeout(() => {
        e.target.style.display = 'none';
    }, 0);
}

function handleDragOver(e) {
    e.preventDefault();
}

function handleDragEnter(e) {
    e.preventDefault();
    e.target.classList.add('drag-over');
}

function handleDragLeave(e) {
    e.target.classList.remove('drag-over');
}

function handleDrop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    const taskId = e.dataTransfer.getData('text/plain');
    const columnId = e.target.dataset.columnId;

    if (!taskId || !columnId) return;

    // Find the task in its current column
    let sourceColumn = null;
    let taskToMove = null;

    projects.forEach(project => {
        project.columns.forEach(column => {
            const taskIndex = column.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                sourceColumn = column;
                taskToMove = column.tasks.splice(taskIndex, 1)[0];
            }
        });
    });

    if (!sourceColumn || !taskToMove) return;

    // Add the task to the new column
    const targetColumn = projects.find(p => p.id === currentProjectId)
        .columns.find(c => c.id === columnId);

    if (targetColumn) {
        targetColumn.tasks.push(taskToMove);
        saveProjects();
        renderBoard(projects.find(p => p.id === currentProjectId));

        // Notify collaborators
        if (socket) {
            socket.emit('taskMoved', {
                projectId: currentProjectId,
                taskId: taskId,
                sourceColumnId: sourceColumn.id,
                targetColumnId: columnId,
                user: userName.textContent
            });
        }
    }
}

