### 3. Main App Component (App.js)

```javascript
import React, { useState, useEffect } from 'react';
import { DragDropContext } from 'react-beautiful-dnd';
import Board from './components/Board';
import { db } from './firebase';
import { collection, query, onSnapshot, doc, updateDoc } from 'firebase/firestore';
import './styles/main.css';

function App() {
  const [tasks, setTasks] = useState([]);
  const [columns, setColumns] = useState({
    'todo': { id: 'todo', title: 'To Do', taskIds: [] },
    'in-progress': { id: 'in-progress', title: 'In Progress', taskIds: [] },
    'done': { id: 'done', title: 'Done', taskIds: [] }
  });

  useEffect(() => {
    const q = query(collection(db, 'tasks'));
    const unsubscribe = onSnapshot(q, (querySnapshot) => {
      const tasksData = [];
      const newColumns = { ...columns };

      // Reset taskIds arrays
      Object.keys(newColumns).forEach(columnId => {
        newColumns[columnId].taskIds = [];
      });

      querySnapshot.forEach((doc) => {
        const task = { id: doc.id, ...doc.data() };
        tasksData.push(task);
        newColumns[task.status].taskIds.push(task.id);
      });

      setTasks(tasksData);
      setColumns(newColumns);
    });

    return () => unsubscribe();
  }, []);

  const onDragEnd = async (result) => {
    const { destination, source, draggableId } = result;

    // If no destination or dropped in the same place
    if (!destination || (destination.droppableId === source.droppableId && destination.index === source.index)) {
      return;
    }

    // Update the task status in Firestore
    try {
      const taskRef = doc(db, 'tasks', draggableId);
      await updateDoc(taskRef, {
        status: destination.droppableId
      });
    } catch (error) {
      console.error("Error updating task status: ", error);
    }
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>Project Management Board</h1>
      </header>
      <DragDropContext onDragEnd={onDragEnd}>
        <Board columns={columns} tasks={tasks} />
      </DragDropContext>
    </div>
  );
}

export default App;
```

