## 3. JavaScript (app.js)

```javascript
// DOM Elements
const board = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnName = document.getElementById('new-column-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskForm = document.getElementById('task-form');
const deleteTaskBtn = document.getElementById('delete-task-btn');
const userName = document.getElementById('user-name');
const logoutBtn = document.getElementById('logout-btn');

// State
let currentBoard = {
    columns: [],
    tasks: []
};
let currentTaskId = null;
let currentUser = 'Guest';
let socket = null;

// Initialize the app
function initApp() {
    // Load saved data from localStorage
    loadBoardData();

    // Set up event listeners
    setupEventListeners();

    // Initialize WebSocket connection
    setupWebSocket();

    // Render the initial board
    renderBoard();
}

// Load board data from localStorage
function loadBoardData() {
    const savedData = localStorage.getItem('taskBoardData');
    if (savedData) {
        currentBoard = JSON.parse(savedData);
    } else {
        // Default columns if no data exists
        currentBoard.columns = [
            { id: 'todo', title: 'To Do' },
            { id: 'in-progress', title: 'In Progress' },
            { id: 'done', title: 'Done' }
        ];
    }
}

// Save board data to localStorage
function saveBoardData() {
    localStorage.setItem('taskBoardData', JSON.stringify(currentBoard));
}

// Set up event listeners
function setupEventListeners() {
    addColumnBtn.addEventListener('click', addNewColumn);
    newColumnName.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') addNewColumn();
    });

    closeModal.addEventListener('click', closeTaskModal);
    taskForm.addEventListener('submit', saveTask);
    deleteTaskBtn.addEventListener('click', deleteTask);

    logoutBtn.addEventListener('click', () => {
        currentUser = 'Guest';
        userName.textContent = currentUser;
    });

    // Set up drag and drop events
    board.addEventListener('dragover', (e) => {
        e.preventDefault();
        const afterElement = getDragAfterElement(board, e.clientX);
        const draggable = document.querySelector('.dragging');

        if (afterElement == null) {
            board.appendChild(draggable);
        } else {
            board.insertBefore(draggable, afterElement);
        }
    });
}

// Set up WebSocket connection
function setupWebSocket() {
    // In a real app, you would connect to your WebSocket server
    // socket = io('http://localhost:3000');

    // For demo purposes, we'll simulate WebSocket behavior
    console.log('WebSocket connection initialized (simulated)');

    // Simulate receiving updates from other users
    setTimeout(() => {
        console.log('Simulating real-time update from another user');
        // In a real app, you would receive updates via WebSocket
        // and then update the local state and UI accordingly
    }, 5000);
}

// Add a new column to the board
function addNewColumn() {
    const columnName = newColumnName.value.trim();
    if (!columnName) return;

    const newColumn = {
        id: `col-${Date.now()}`,
        title: columnName
    };

    currentBoard.columns.push(newColumn);
    saveBoardData();
    renderBoard();

    newColumnName.value = '';

    // Broadcast the change to other users
    broadcastChange('column-added', newColumn);
}

// Render the entire board
function renderBoard() {
    board.innerHTML = '';

    currentBoard.columns.forEach(column => {
        const columnElement = createColumnElement(column);
        board.appendChild(columnElement);
    });

    // Add tasks to their respective columns
    currentBoard.tasks.forEach(task => {
        const taskElement = createTaskElement(task);
        const columnElement = document.querySelector(`[data-column-id="${task.columnId}"] .task-list`);
        if (columnElement) {
            columnElement.appendChild(taskElement);
        }
    });
}

// Create a column element
function createColumnElement(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = column.id;

    columnElement.innerHTML = `
        <div class="column-header">
            <h3 class="column-title">${column.title}</h3>
            <div class="column-actions">
                <button class="edit-column-btn" title="Edit column">
                    <i class="fas fa-pencil-alt"></i>
                </button>
                <button class="delete-column-btn" title="Delete column">
                    <i class="fas fa-trash-alt"></i>
                </button>
            </div>
        </div>
        <div class="task-list" data-column-id="${column.id}"></div>
        <button class="add-task-btn" data-column-id="${column.id}">
            <i class="fas fa-plus"></i> Add Task
        </button>
    `;

    // Set up column event listeners
    const addTaskBtn = columnElement.querySelector('.add-task-btn');
    addTaskBtn.addEventListener('click', () => openTaskModal(null, column.id));

    const editColumnBtn = columnElement.querySelector('.edit-column-btn');
    editColumnBtn.addEventListener('click', () => editColumn(column.id));

    const deleteColumnBtn = columnElement.querySelector('.delete-column-btn');
    deleteColumnBtn.addEventListener('click', () => deleteColumn(column.id));

    return columnElement;
}

// Create a task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task-card';
    taskElement.draggable = true;
    taskElement.dataset.taskId = task.id;

    // Set priority class
    const priorityClass = task.priority ? `task-priority ${task.priority}` : '';

    taskElement.innerHTML = `
        <h4 class="task-title">${task.title}</h4>
        <p class="task-description">${task.description || ''}</p>
        <div class="task-meta">
            <span class="${priorityClass}">${task.priority ? task.priority.charAt(0).toUpperCase() + task.priority.slice(1) : ''}</span>
            <span class="task-assignee">${task.assignee || ''}</span>
        </div>
    `;

    // Set up drag events
    taskElement.addEventListener('dragstart', () => {
        taskElement.classList.add('dragging');
        setTimeout(() => {
            taskElement.style.display = 'none';
        }, 0);
    });

    taskElement.addEventListener('dragend', () => {
        taskElement.classList.remove('dragging');
        taskElement.style.display = 'block';

        // Update task position in the DOM
        const newColumnId = taskElement.closest('.column').dataset.columnId;
        if (newColumnId !== task.columnId) {
            // Task was moved to a different column
            task.columnId = newColumnId;
            saveBoardData();

            // Broadcast the change to other users
            broadcastChange('task-moved', {
                taskId: task.id,
                newColumnId: newColumnId
            });
        }
    });

    // Open task modal on click
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('.task-priority')) {
            openTaskModal(task.id);
        }
    });

    return taskElement;
}

// Open the task modal for editing or creating a new task
function openTaskModal(taskId = null, columnId = null) {
    currentTaskId = taskId;

    if (taskId) {
        // Editing existing task
        const task = currentBoard.tasks.find(t => t.id === taskId);
        if (task) {
            document.getElementById('modal-title').textContent = 'Edit Task';
            document.getElementById('task-title').value = task.title;
            document.getElementById('task-description').value = task.description || '';
            document.getElementById('task-assignee').value = task.assignee || '';
            document.getElementById('task-due-date').value = task.dueDate || '';
            document.getElementById('task-priority').value = task.priority || 'medium';
            deleteTaskBtn.style.display = 'block';
        }
    } else {
        // Creating new task
        document.getElementById('modal-title').textContent = 'Add New Task';
        document.getElementById('task-form').reset();
        deleteTaskBtn.style.display = 'none';
    }

    taskModal.classList.add('active');
}

// Close the task modal
function closeTaskModal() {
    taskModal.classList.remove('active');
}

// Save a task (create or update)
function saveTask(e) {
    e.preventDefault();

    const title = document.getElementById('task-title').value.trim();
    if (!title) return;

    const taskData = {
        title,
        description: document.getElementById('task-description').value.trim(),
        assignee: document.getElementById('task-assignee').value.trim(),
        dueDate: document.getElementById('task-due-date').value,
        priority: document.getElementById('task-priority').value,
        columnId: currentTaskId ?
            currentBoard.tasks.find(t => t.id === currentTaskId).columnId :
            document.querySelector('.task-card.dragging')?.closest('.column')?.dataset.columnId ||
            currentBoard.columns[0].id
    };

    if (currentTaskId) {
        // Update existing task
        const taskIndex = currentBoard.tasks.findIndex(t => t.id === currentTaskId);
        if (taskIndex !== -1) {
            currentBoard.tasks[taskIndex] = { ...currentBoard.tasks[taskIndex], ...taskData };
            broadcastChange('task-updated', currentBoard.tasks[taskIndex]);
        }
    } else {
        // Create new task
        const newTask = {
            id: `task-${Date.now()}`,
            ...taskData
        };
        currentBoard.tasks.push(newTask);
        broadcastChange('task-created', newTask);
    }

    saveBoardData();
    renderBoard();
    closeTaskModal();
}

// Delete a task
function deleteTask() {
    if (!currentTaskId) return;

    currentBoard.tasks = currentBoard.tasks.filter(task => task.id !== currentTaskId);
    saveBoardData();
    renderBoard();
    closeTaskModal();

    broadcastChange('task-deleted', { taskId: currentTaskId });
}

// Edit a column
function editColumn(columnId) {
    const column = currentBoard.columns.find(c => c.id === columnId);
    if (!column) return;

    const newName = prompt('Enter new column name:', column.title);
    if (newName && newName.trim() !== column.title) {
        column.title = newName.trim();
        saveBoardData();
        renderBoard();

        broadcastChange('column-updated', column);
    }
}

// Delete a column
function deleteColumn(columnId) {
    if (!confirm('Are you sure you want to delete this column and all its tasks?')) return;

    currentBoard.columns = currentBoard.columns.filter(c => c.id !== columnId);
    currentBoard.tasks = currentBoard.tasks.filter(t => t.columnId !== columnId);
    saveBoardData();
    renderBoard();

    broadcastChange('column-deleted', { columnId });
}

// Helper function to get the element after which we should insert the dragged item
function getDragAfterElement(container, x) {
    const draggableElements = [...container.querySelectorAll('.column:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = x - box.left - box.width / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Broadcast changes to other users via WebSocket
function broadcastChange(eventType, data) {
    if (socket) {
        socket.emit(eventType, {
            user: currentUser,
            data: data
        });
    } else {
        // Simulate WebSocket behavior
        console.log(`Broadcasting ${eventType}:`, data);
    }
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
```

