## JavaScript Implementation

```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize the app
    const app = new TaskBoardApp();
    app.init();
});

class TaskBoardApp {
    constructor() {
        this.columns = [];
        this.tasks = [];
        this.drake = null;
        this.socket = null;
        this.userId = this.generateUserId();
        this.modal = document.getElementById('task-modal');
        this.taskForm = document.getElementById('task-form');
        this.currentTaskId = null;
    }

    init() {
        // Load saved data from localStorage
        this.loadFromLocalStorage();

        // Initialize UI
        this.renderBoard();

        // Set up event listeners
        this.setupEventListeners();

        // Initialize drag-and-drop
        this.initDragula();

        // Initialize real-time collaboration
        this.initSocketIO();

        // Update user name display
        document.getElementById('user-name').textContent = `User ${this.userId}`;
    }

    generateUserId() {
        return Math.floor(Math.random() * 10000);
    }

    loadFromLocalStorage() {
        const savedColumns = localStorage.getItem('taskBoardColumns');
        const savedTasks = localStorage.getItem('taskBoardTasks');

        if (savedColumns) {
            this.columns = JSON.parse(savedColumns);
        } else {
            // Default columns if none exist
            this.columns = [
                { id: this.generateId(), title: 'To Do' },
                { id: this.generateId(), title: 'In Progress' },
                { id: this.generateId(), title: 'Done' }
            ];
        }

        if (savedTasks) {
            this.tasks = JSON.parse(savedTasks);
        }
    }

    saveToLocalStorage() {
        localStorage.setItem('taskBoardColumns', JSON.stringify(this.columns));
        localStorage.setItem('taskBoardTasks', JSON.stringify(this.tasks));
    }

    generateId() {
        return Date.now().toString(36) + Math.random().toString(36).substr(2);
    }

    renderBoard() {
        const boardElement = document.getElementById('board');
        boardElement.innerHTML = '';

        this.columns.forEach(column => {
            const columnElement = this.createColumnElement(column);
            boardElement.appendChild(columnElement);

            // Render tasks in this column
            const taskListElement = columnElement.querySelector('.task-list');
            this.renderTasks(column.id, taskListElement);
        });
    }

    createColumnElement(column) {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.columnId = column.id;

        columnElement.innerHTML = `
            <div class="column-header">
                <h3 class="column-title">${column.title}</h3>
                <div class="column-actions">
                    <button class="edit-column-btn" title="Edit Column">✏️</button>
                    <button class="delete-column-btn" title="Delete Column">🗑️</button>
                </div>
            </div>
            <div class="task-list" data-column-id="${column.id}"></div>
        `;

        return columnElement;
    }

    renderTasks(columnId, taskListElement) {
        taskListElement.innerHTML = '';

        const columnTasks = this.tasks.filter(task => task.columnId === columnId);

        columnTasks.forEach(task => {
            const taskElement = this.createTaskElement(task);
            taskListElement.appendChild(taskElement);
        });
    }

    createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.dataset.taskId = task.id;

        const dueDate = task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date';

        taskElement.innerHTML = `
            <h4 class="task-title">${task.title}</h4>
            <p class="task-description">${task.description || ''}</p>
            <div class="task-meta">
                <span class="task-assignee">${task.assignee || 'Unassigned'}</span>
                <span class="task-due-date">${dueDate}</span>
            </div>
        `;

        return taskElement;
    }

    setupEventListeners() {
        // Add column button
        document.getElementById('add-column-btn').addEventListener('click', () => {
            const columnTitle = prompt('Enter column title:');
            if (columnTitle) {
                const newColumn = {
                    id: this.generateId(),
                    title: columnTitle
                };
                this.columns.push(newColumn);
                this.saveToLocalStorage();
                this.renderBoard();
                this.initDragula();
            }
        });

        // Add task button
        document.getElementById('add-task-btn').addEventListener('click', () => {
            if (this.columns.length === 0) {
                alert('Please add a column first');
                return;
            }

            this.currentTaskId = null;
            this.openTaskModal();
        });

        // Column edit/delete buttons
        document.getElementById('board').addEventListener('click', (e) => {
            if (e.target.classList.contains('edit-column-btn')) {
                const columnElement = e.target.closest('.column');
                const columnId = columnElement.dataset.columnId;
                const column = this.columns.find(c => c.id === columnId);

                const newTitle = prompt('Edit column title:', column.title);
                if (newTitle) {
                    column.title = newTitle;
                    this.saveToLocalStorage();
                    this.renderBoard();
                    this.initDragula();
                }
            }

            if (e.target.classList.contains('delete-column-btn')) {
                const columnElement = e.target.closest('.column');
                const columnId = columnElement.dataset.columnId;

                if (confirm('Are you sure you want to delete this column and all its tasks?')) {
                    // Remove tasks in this column
                    this.tasks = this.tasks.filter(task => task.columnId !== columnId);

                    // Remove column
                    this.columns = this.columns.filter(column => column.id !== columnId);

                    this.saveToLocalStorage();
                    this.renderBoard();
                    this.initDragula();
                }
            }
        });

        // Task card click
        document.getElementById('board').addEventListener('click', (e) => {
            const taskElement = e.target.closest('.task-card');
            if (taskElement) {
                const taskId = taskElement.dataset.taskId;
                this.currentTaskId = taskId;
                this.openTaskModal(taskId);
            }
        });

        // Modal close button
        document.querySelector('.close').addEventListener('click', () => {
            this.closeTaskModal();
        });

        // Modal form submission
        this.taskForm.addEventListener('submit', (e) => {
            e.preventDefault();
            this.saveTask();
        });

        // Click outside modal to close
        window.addEventListener('click', (e) => {
            if (e.target === this.modal) {
                this.closeTaskModal();
            }
        });
    }

    openTaskModal(taskId = null) {
        if (taskId) {
            const task = this.tasks.find(t => t.id === taskId);
            if (task) {
                document.getElementById('task-id').value = task.id;
                document.getElementById('task-title').value = task.title;
                document.getElementById('task-description').value = task.description || '';
                document.getElementById('task-assignee').value = task.assignee || '';
                document.getElementById('task-due-date').value = task.dueDate || '';
            }
        } else {
            // Clear form for new task
            this.taskForm.reset();
            document.getElementById('task-id').value = '';
        }

        this.modal.style.display = 'block';
    }

    closeTaskModal() {
        this.modal.style.display = 'none';
    }

    saveTask() {
        const taskId = document.getElementById('task-id').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const assignee = document.getElementById('task-assignee').value;
        const dueDate = document.getElementById('task-due-date').value;

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        let task;
        if (taskId) {
            // Update existing task
            task = this.tasks.find(t => t.id === taskId);
            if (task) {
                task.title = title;
                task.description = description;
                task.assignee = assignee;
                task.dueDate = dueDate;
            }
        } else {
            // Create new task
            if (this.columns.length === 0) {
                alert('Please add a column first');
                return;
            }

            task = {
                id: this.generateId(),
                title,
                description,
                assignee,
                dueDate,
                columnId: this.columns[0].id // Default to first column
            };
            this.tasks.push(task);
        }

        this.saveToLocalStorage();
        this.renderBoard();
        this.closeTaskModal();

        // Emit task update to other clients if connected
        if (this.socket && this.socket.connected) {
            this.socket.emit('taskUpdated', task);
        }
    }

    initDragula() {
        // Destroy previous dragula instance if it exists
        if (this.drake) {
            this.drake.destroy();
        }

        const containers = Array.from(document.querySelectorAll('.task-list'));

        this.drake = dragula(containers, {
            moves: function(el, container, handle) {
                return el.classList.contains('task-card');
            },
            accepts: function(el, target, source, sibling) {
                return target.classList.contains('task-list');
            }
        });

        // Handle drop event
        this.drake.on('drop', (el, target, source, sibling) => {
            const taskId = el.dataset.taskId;
            const newColumnId = target.dataset.columnId;

            // Update task's column
            const task = this.tasks.find(t => t.id === taskId);
            if (task) {
                task.columnId = newColumnId;
                this.saveToLocalStorage();

                // Emit task move to other clients if connected
                if (this.socket && this.socket.connected) {
                    this.socket.emit('taskMoved', {
                        taskId: task.id,
                        newColumnId: newColumnId
                    });
                }
            }
        });
    }

    initSocketIO() {
        // Connect to server
        this.socket = io();

        // Connection status
        const connectionStatus = document.getElementById('connection-status');

        this.socket.on('connect', () => {
            connectionStatus.textContent = 'Connected';
            connectionStatus.classList.add('connected');
        });

        this.socket.on('disconnect', () => {
            connectionStatus.textContent = 'Disconnected';
            connectionStatus.classList.remove('connected');
        });

        // Listen for task updates from other clients
        this.socket.on('taskUpdated', (updatedTask) => {
            const existingTaskIndex = this.tasks.findIndex(t => t.id === updatedTask.id);

            if (existingTaskIndex !== -1) {
                // Update existing task
                this.tasks[existingTaskIndex] = updatedTask;
            } else {
                // Add new task
                this.tasks.push(updatedTask);
            }

            this.saveToLocalStorage();
            this.renderBoard();
        });

        // Listen for task moves from other clients
        this.socket.on('taskMoved', (data) => {
            const task = this.tasks.find(t => t.id === data.taskId);
            if (task) {
                task.columnId = data.newColumnId;
                this.saveToLocalStorage();
                this.renderBoard();
            }
        });

        // Listen for column updates from other clients
        this.socket.on('columnsUpdated', (updatedColumns) => {
            this.columns = updatedColumns;
            this.saveToLocalStorage();
            this.renderBoard();
            this.initDragula();
        });
    }
}
