## JavaScript Implementation (app.js)

```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();

// DOM elements
const boardsContainer = document.getElementById('boardsContainer');
const projectsList = document.getElementById('projectsList');
const membersList = document.getElementById('membersList');
const addProjectBtn = document.getElementById('addProjectBtn');
const inviteBtn = document.getElementById('inviteBtn');
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const projectModal = new bootstrap.Modal(document.getElementById('projectModal'));

// Current state
let currentProjectId = null;
let currentTask = null;

// Initialize the app
function initApp() {
    // Load projects
    loadProjects();

    // Set up event listeners
    setupEventListeners();

    // Initialize drag-and-drop
    initDragula();
}

// Load projects from Firestore
function loadProjects() {
    db.collection('projects').orderBy('createdAt', 'desc').onSnapshot((snapshot) => {
        projectsList.innerHTML = '';
        snapshot.forEach((doc) => {
            const project = doc.data();
            const projectElement = document.createElement('a');
            projectElement.href = '#';
            projectElement.className = `list-group-item list-group-item-action ${currentProjectId === doc.id ? 'active' : ''}`;
            projectElement.textContent = project.name;
            projectElement.dataset.projectId = doc.id;
            projectElement.addEventListener('click', (e) => {
                e.preventDefault();
                loadProject(doc.id);
            });
            projectsList.appendChild(projectElement);
        });
    });
}

// Load a specific project
function loadProject(projectId) {
    currentProjectId = projectId;

    // Update active project in UI
    document.querySelectorAll('#projectsList a').forEach(el => {
        el.classList.remove('active');
        if (el.dataset.projectId === projectId) {
            el.classList.add('active');
        }
    });

    // Load boards for this project
    loadBoards(projectId);

    // Load members for this project
    loadMembers(projectId);
}

// Load boards (columns) for a project
function loadBoards(projectId) {
    db.collection('projects').doc(projectId).collection('boards')
        .orderBy('order')
        .onSnapshot((snapshot) => {
            boardsContainer.innerHTML = '';
            snapshot.forEach((doc) => {
                const board = doc.data();
                const boardElement = createBoardElement(doc.id, board);
                boardsContainer.appendChild(boardElement);

                // Load tasks for this board
                loadTasks(projectId, doc.id);
            });

            // Add "Add Board" button
            const addBoardBtn = document.createElement('button');
            addBoardBtn.className = 'btn btn-outline-secondary add-board-btn';
            addBoardBtn.textContent = '+ Add Board';
            addBoardBtn.addEventListener('click', () => {
                const boardName = prompt('Enter board name:');
                if (boardName) {
                    addBoard(projectId, boardName);
                }
            });
            boardsContainer.appendChild(addBoardBtn);
        });
}

// Create a board element
function createBoardElement(boardId, boardData) {
    const boardElement = document.createElement('div');
    boardElement.className = 'board';
    boardElement.dataset.boardId = boardId;

    const boardHeader = document.createElement('div');
    boardHeader.className = 'board-header';

    const boardTitle = document.createElement('h5');
    boardTitle.className = 'board-title';
    boardTitle.textContent = boardData.name;

    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'btn btn-sm btn-outline-danger';
    deleteBtn.innerHTML = '&times;';
    deleteBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (confirm('Are you sure you want to delete this board?')) {
            deleteBoard(currentProjectId, boardId);
        }
    });

    boardHeader.appendChild(boardTitle);
    boardHeader.appendChild(deleteBtn);

    const taskList = document.createElement('div');
    taskList.className = 'task-list';
    taskList.dataset.boardId = boardId;

    const addTaskBtn = document.createElement('button');
    addTaskBtn.className = 'btn btn-sm btn-outline-primary add-task-btn';
    addTaskBtn.textContent = '+ Add Task';
    addTaskBtn.addEventListener('click', () => {
        currentTask = null;
        document.getElementById('taskTitle').value = '';
        document.getElementById('taskDescription').value = '';
        document.getElementById('taskDueDate').value = '';
        document.getElementById('taskPriority').value = 'medium';
        taskModal.show();
    });

    boardElement.appendChild(boardHeader);
    boardElement.appendChild(taskList);
    boardElement.appendChild(addTaskBtn);

    return boardElement;
}

// Load tasks for a board
function loadTasks(projectId, boardId) {
    db.collection('projects').doc(projectId).collection('boards').doc(boardId)
        .collection('tasks')
        .orderBy('order')
        .onSnapshot((snapshot) => {
            const taskList = document.querySelector(`.task-list[data-board-id="${boardId}"]`);
            if (!taskList) return;

            taskList.innerHTML = '';
            snapshot.forEach((doc) => {
                const task = doc.data();
                const taskElement = createTaskElement(doc.id, task);
                taskList.appendChild(taskElement);
            });
        });
}

// Create a task element
function createTaskElement(taskId, taskData) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task-card';
    taskElement.dataset.taskId = taskId;

    const taskTitle = document.createElement('div');
    taskTitle.className = 'task-title';
    taskTitle.textContent = taskData.title;

    const taskMeta = document.createElement('div');
    taskMeta.className = 'task-meta';

    if (taskData.dueDate) {
        const dueDate = new Date(taskData.dueDate);
        const formattedDate = dueDate.toLocaleDateString();
        const dateSpan = document.createElement('span');
        dateSpan.textContent = `Due: ${formattedDate}`;
        taskMeta.appendChild(dateSpan);
    }

    if (taskData.priority) {
        const prioritySpan = document.createElement('span');
        prioritySpan.className = `priority-${taskData.priority} ms-2`;
        prioritySpan.textContent = `Priority: ${taskData.priority}`;
        taskMeta.appendChild(prioritySpan);
    }

    taskElement.appendChild(taskTitle);
    taskElement.appendChild(taskMeta);

    taskElement.addEventListener('click', (e) => {
        e.stopPropagation();
        currentTask = {
            id: taskId,
            ...taskData
        };
        document.getElementById('taskTitle').value = taskData.title || '';
        document.getElementById('taskDescription').value = taskData.description || '';
        document.getElementById('taskDueDate').value = taskData.dueDate || '';
        document.getElementById('taskPriority').value = taskData.priority || 'medium';
        taskModal.show();
    });

    return taskElement;
}

// Initialize Dragula for drag-and-drop
function initDragula() {
    const drake = dragula({
        isContainer: function (el) {
            return el.classList.contains('task-list');
        },
        moves: function (el, source, handle, sibling) {
            return el.classList.contains('task-card');
        },
        accepts: function (el, target, source, sibling) {
            return target.classList.contains('task-list');
        }
    });

    drake.on('drop', function (el, target, source, sibling) {
        const taskId = el.dataset.taskId;
        const newBoardId = target.dataset.boardId;
        const oldBoardId = source.dataset.boardId;

        if (newBoardId !== oldBoardId) {
            // Task moved to a different board
            updateTaskBoard(currentProjectId, oldBoardId, newBoardId, taskId);
        }

        // Update task order in the new board
        updateTaskOrder(currentProjectId, newBoardId);
    });
}

// Update task order when reordered
function updateTaskOrder(projectId, boardId) {
    const taskList = document.querySelector(`.task-list[data-board-id="${boardId}"]`);
    if (!taskList) return;

    const tasks = taskList.querySelectorAll('.task-card');
    const batch = db.batch();

    tasks.forEach((taskElement, index) => {
        const taskId = taskElement.dataset.taskId;
        const taskRef = db.collection('projects').doc(projectId)
            .collection('boards').doc(boardId)
            .collection('tasks').doc(taskId);

        batch.update(taskRef, { order: index });
    });

    batch.commit().catch((error) => {
        console.error("Error updating task order: ", error);
    });
}

// Add a new board to a project
function addBoard(projectId, boardName) {
    const boardRef = db.collection('projects').doc(projectId).collection('boards').doc();

    boardRef.set({
        name: boardName,
        order: Date.now(),
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    }).catch((error) => {
        console.error("Error adding board: ", error);
    });
}

// Delete a board
function deleteBoard(projectId, boardId) {
    // First delete all tasks in the board
    const tasksRef = db.collection('projects').doc(projectId)
        .collection('boards').doc(boardId)
        .collection('tasks');

    tasksRef.get().then((snapshot) => {
        const batch = db.batch();
        snapshot.forEach((doc) => {
            batch.delete(doc.ref);
        });
        return batch.commit();
    }).then(() => {
        // Then delete the board
        return db.collection('projects').doc(projectId)
            .collection('boards').doc(boardId).delete();
    }).catch((error) => {
        console.error("Error deleting board: ", error);
    });
}

// Update a task's board when moved
function updateTaskBoard(projectId, oldBoardId, newBoardId, taskId) {
    const taskRef = db.collection('projects').doc(projectId)
        .collection('boards').doc(oldBoardId)
        .collection('tasks').doc(taskId);

    taskRef.get().then((doc) => {
        if (doc.exists) {
            const taskData = doc.data();

            // Add to new board
            const newTaskRef = db.collection('projects').doc(projectId)
                .collection('boards').doc(newBoardId)
                .collection('tasks').doc(taskId);

            return newTaskRef.set({
                ...taskData,
                order: Date.now()
            }).then(() => {
                // Delete from old board
                return taskRef.delete();
            });
        }
    }).catch((error) => {
        console.error("Error moving task: ", error);
    });
}

// Load members for a project
function loadMembers(projectId) {
    db.collection('projects').doc(projectId).collection('members')
        .onSnapshot((snapshot) => {
            membersList.innerHTML = '';
            snapshot.forEach((doc) => {
                const member = doc.data();
                const memberElement = document.createElement('div');
                memberElement.className = 'list-group-item d-flex justify-content-between align-items-center';
                memberElement.innerHTML = `
                    <span>${member.name || member.email}</span>
                    <span class="badge bg-primary rounded-pill">${member.role || 'Member'}</span>
                `;
                membersList.appendChild(memberElement);
            });
        });
}

// Set up event listeners
function setupEventListeners() {
    // Add project button
    addProjectBtn.addEventListener('click', () => {
        document.getElementById('projectName').value = '';
        document.getElementById('projectDescription').value = '';
        projectModal.show();
    });

    // Create project button
    document.getElementById('createProjectBtn').addEventListener('click', () => {
        const projectName = document.getElementById('projectName').value;
        const projectDescription = document.getElementById('projectDescription').value;

        if (projectName) {
            createProject(projectName, projectDescription);
            projectModal.hide();
        }
    });

    // Save task button
    document.getElementById('saveTaskBtn').addEventListener('click', () => {
        const title = document.getElementById('taskTitle').value;
        const description = document.getElementById('taskDescription').value;
        const dueDate = document.getElementById('taskDueDate').value;
        const priority = document.getElementById('taskPriority').value;

        if (title) {
            if (currentTask) {
                // Update existing task
                updateTask(currentProjectId, currentTask.boardId, currentTask.id, {
                    title,
                    description,
                    dueDate,
                    priority
                });
            } else {
                // Create new task
                const boardId = document.querySelector('.task-list').dataset.boardId;
                createTask(currentProjectId, boardId, {
                    title,
                    description,
                    dueDate,
                    priority
                });
            }
            taskModal.hide();
        }
    });

    // Invite button
    inviteBtn.addEventListener('click', () => {
        const email = prompt('Enter email address to invite:');
        if (email && currentProjectId) {
            inviteMember(currentProjectId, email);
        }
    });
}

// Create a new project
function createProject(name, description) {
    const projectRef = db.collection('projects').doc();

    projectRef.set({
        name,
        description,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    }).then(() => {
        // Create default boards
        const defaultBoards = ['To Do', 'In Progress', 'Done'];
        const batch = db.batch();

        defaultBoards.forEach((boardName, index) => {
            const boardRef = projectRef.collection('boards').doc();
            batch.set(boardRef, {
                name: boardName,
                order: index,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        });

        return batch.commit();
    }).then(() => {
        // Load the new project
        loadProject(projectRef.id);
    }).catch((error) => {
        console.error("Error creating project: ", error);
    });
}

// Create a new task
function createTask(projectId, boardId, taskData) {
    const taskRef = db.collection('projects').doc(projectId)
        .collection('boards').doc(boardId)
        .collection('tasks').doc();

    taskRef.set({
        ...taskData,
        order: Date.now(),
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    }).catch((error) => {
        console.error("Error creating task: ", error);
    });
}

// Update an existing task
function updateTask(projectId, boardId, taskId, taskData) {
    const taskRef = db.collection('projects').doc(projectId)
        .collection('boards').doc(boardId)
        .collection('tasks').doc(taskId);

    taskRef.update({
        ...taskData,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
    }).catch((error) => {
        console.error("Error updating task: ", error);
    });
}

// Invite a member to a project
function inviteMember(projectId, email) {
    const memberRef = db.collection('projects').doc(projectId)
        .collection('members').doc(email);

    memberRef.set({
        email,
        role: 'Member',
        invitedAt: firebase.firestore.FieldValue.serverTimestamp()
    }).catch((error) => {
        console.error("Error inviting member: ", error);
    });
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
