```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();
    let userName = 'Guest';

    // DOM elements
    const board = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column-btn');
    const addTaskBtn = document.getElementById('add-task-btn');
    const userNameInput = document.getElementById('user-name-input');
    const setNameBtn = document.getElementById('set-name-btn');
    const connectionStatus = document.getElementById('connection-status');
    const userNameDisplay = document.getElementById('user-name');

    // Initialize drag-and-drop
    const drake = dragula({
        isContainer: function (el) {
            return el.classList.contains('task-list');
        },
        moves: function (el, source, handle, sibling) {
            return el.classList.contains('task');
        }
    });

    // Load saved state from localStorage
    let boardState = JSON.parse(localStorage.getItem('taskBoardState')) || {
        columns: [
            { id: 'todo', title: 'To Do', tasks: [] },
            { id: 'in-progress', title: 'In Progress', tasks: [] },
            { id: 'done', title: 'Done', tasks: [] }
        ]
    };

    // Render the board
    function renderBoard() {
        board.innerHTML = '';

        boardState.columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.columnId = column.id;

            columnElement.innerHTML = `
                <div class="column-header">
                    <h3 class="column-title">${column.title}</h3>
                    <div class="column-actions">
                        <button class="edit-column-btn" title="Edit column">✏️</button>
                        <button class="delete-column-btn" title="Delete column">🗑️</button>
                    </div>
                </div>
                <div class="task-list" data-column-id="${column.id}">
                    ${column.tasks.map(task => `
                        <div class="task" data-task-id="${task.id}">
                            <div class="task-header">
                                <span class="task-title">${task.title}</span>
                                <div class="task-actions">
                                    <button class="edit-task-btn" title="Edit task">✏️</button>
                                    <button class="delete-task-btn" title="Delete task">🗑️</button>
                                </div>
                            </div>
                            <div class="task-content">${task.content || ''}</div>
                            <div class="task-meta">
                                <span>Created by: ${task.createdBy || 'Unknown'}</span>
                                <span>${new Date(task.createdAt).toLocaleString()}</span>
                            </div>
                        </div>
                    `).join('')}
                </div>
            `;

            board.appendChild(columnElement);
        });

        // Add event listeners to new elements
        setupEventListeners();
    }

    // Set up event listeners
    function setupEventListeners() {
        // Column event listeners
        document.querySelectorAll('.edit-column-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const columnId = this.closest('.column').dataset.columnId;
                editColumn(columnId);
            });
        });

        document.querySelectorAll('.delete-column-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const columnId = this.closest('.column').dataset.columnId;
                deleteColumn(columnId);
            });
        });

        // Task event listeners
        document.querySelectorAll('.edit-task-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const taskId = this.closest('.task').dataset.taskId;
                const columnId = this.closest('.task-list').dataset.columnId;
                editTask(columnId, taskId);
            });
        });

        document.querySelectorAll('.delete-task-btn').forEach(btn => {
            btn.addEventListener('click', function() {
                const taskId = this.closest('.task').dataset.taskId;
                const columnId = this.closest('.task-list').dataset.columnId;
                deleteTask(columnId, taskId);
            });
        });

        // Dragula events
        drake.on('drop', function(el, target, source, sibling) {
            const taskId = el.dataset.taskId;
            const oldColumnId = source.dataset.columnId;
            const newColumnId = target.dataset.columnId;

            if (oldColumnId !== newColumnId) {
                moveTask(oldColumnId, newColumnId, taskId);
            }

            // Save state to localStorage
            localStorage.setItem('taskBoardState', JSON.stringify(boardState));
        });
    }

    // Add a new column
    function addColumn() {
        const columnTitle = prompt('Enter column title:');
        if (columnTitle) {
            const newColumn = {
                id: 'col-' + Date.now(),
                title: columnTitle,
                tasks: []
            };

            boardState.columns.push(newColumn);
            renderBoard();

            // Save to localStorage
            localStorage.setItem('taskBoardState', JSON.stringify(boardState));

            // Notify other users
            socket.emit('columnAdded', newColumn);
        }
    }

    // Edit a column
    function editColumn(columnId) {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            const newTitle = prompt('Edit column title:', column.title);
            if (newTitle && newTitle !== column.title) {
                column.title = newTitle;
                renderBoard();

                // Save to localStorage
                localStorage.setItem('taskBoardState', JSON.stringify(boardState));

                // Notify other users
                socket.emit('columnUpdated', column);
            }
        }
    }

    // Delete a column
    function deleteColumn(columnId) {
        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            boardState.columns = boardState.columns.filter(c => c.id !== columnId);
            renderBoard();

            // Save to localStorage
            localStorage.setItem('taskBoardState', JSON.stringify(boardState));

            // Notify other users
            socket.emit('columnDeleted', columnId);
        }
    }

    // Add a new task
    function addTask() {
        const columnId = prompt('Enter column ID to add task to:');
        const column = boardState.columns.find(c => c.id === columnId);

        if (column) {
            const taskTitle = prompt('Enter task title:');
            const taskContent = prompt('Enter task description (optional):');

            if (taskTitle) {
                const newTask = {
                    id: 'task-' + Date.now(),
                    title: taskTitle,
                    content: taskContent || '',
                    createdBy: userName,
                    createdAt: new Date().toISOString()
                };

                column.tasks.push(newTask);
                renderBoard();

                // Save to localStorage
                localStorage.setItem('taskBoardState', JSON.stringify(boardState));

                // Notify other users
                socket.emit('taskAdded', { columnId, task: newTask });
            }
        } else {
            alert('Column not found!');
        }
    }

    // Edit a task
    function editTask(columnId, taskId) {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            const task = column.tasks.find(t => t.id === taskId);
            if (task) {
                const newTitle = prompt('Edit task title:', task.title);
                const newContent = prompt('Edit task description:', task.content || '');

                if (newTitle && (newTitle !== task.title || newContent !== task.content)) {
                    task.title = newTitle;
                    task.content = newContent;
                    renderBoard();

                    // Save to localStorage
                    localStorage.setItem('taskBoardState', JSON.stringify(boardState));

                    // Notify other users
                    socket.emit('taskUpdated', { columnId, task });
                }
            }
        }
    }

    // Delete a task
    function deleteTask(columnId, taskId) {
        if (confirm('Are you sure you want to delete this task?')) {
            const column = boardState.columns.find(c => c.id === columnId);
            if (column) {
                column.tasks = column.tasks.filter(t => t.id !== taskId);
                renderBoard();

                // Save to localStorage
                localStorage.setItem('taskBoardState', JSON.stringify(boardState));

                // Notify other users
                socket.emit('taskDeleted', { columnId, taskId });
            }
        }
    }

    // Move a task between columns
    function moveTask(oldColumnId, newColumnId, taskId) {
        const oldColumn = boardState.columns.find(c => c.id === oldColumnId);
        const newColumn = boardState.columns.find(c => c.id === newColumnId);

        if (oldColumn && newColumn) {
            const taskIndex = oldColumn.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                const [task] = oldColumn.tasks.splice(taskIndex, 1);
                newColumn.tasks.push(task);

                // Notify other users
                socket.emit('taskMoved', {
                    oldColumnId,
                    newColumnId,
                    taskId,
                    task
                });
            }
        }
    }

    // Set user name
    function setUserName() {
        const newName = userNameInput.value.trim();
        if (newName) {
            userName = newName;
            userNameDisplay.textContent = userName;
            userNameInput.value = '';

            // Notify other users
            socket.emit('userNameChanged', userName);
        }
    }

    // Socket.io event handlers
    socket.on('connect', () => {
        connectionStatus.textContent = 'Connected';
        connectionStatus.style.color = 'green';

        // Request current board state from server
        socket.emit('requestBoardState');
    });

    socket.on('disconnect', () => {
        connectionStatus.textContent = 'Disconnected';
        connectionStatus.style.color = 'red';
    });

    socket.on('boardState', (state) => {
        boardState = state;
        renderBoard();
    });

    socket.on('columnAdded', (column) => {
        boardState.columns.push(column);
        renderBoard();
    });

    socket.on('columnUpdated', (updatedColumn) => {
        const index = boardState.columns.findIndex(c => c.id === updatedColumn.id);
        if (index !== -1) {
            boardState.columns[index] = updatedColumn;
            renderBoard();
        }
    });

    socket.on('columnDeleted', (columnId) => {
        boardState.columns = boardState.columns.filter(c => c.id !== columnId);
        renderBoard();
    });

    socket.on('taskAdded', ({ columnId, task }) => {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            column.tasks.push(task);
            renderBoard();
        }
    });

    socket.on('taskUpdated', ({ columnId, task }) => {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            const index = column.tasks.findIndex(t => t.id === task.id);
            if (index !== -1) {
                column.tasks[index] = task;
                renderBoard();
            }
        }
    });

    socket.on('taskDeleted', ({ columnId, taskId }) => {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            column.tasks = column.tasks.filter(t => t.id !== taskId);
            renderBoard();
        }
    });

    socket.on('taskMoved', ({ oldColumnId, newColumnId, taskId, task }) => {
        const oldColumn = boardState.columns.find(c => c.id === oldColumnId);
        const newColumn = boardState.columns.find(c => c.id === newColumnId);

        if (oldColumn && newColumn) {
            const taskIndex = oldColumn.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                oldColumn.tasks.splice(taskIndex, 1);
                newColumn.tasks.push(task);
                renderBoard();
            }
        }
    });

    socket.on('userNameChanged', (name) => {
        // This would be used to show other users' names in the UI
        console.log('User name changed:', name);
    });

    // Event listeners for buttons
    addColumnBtn.addEventListener('click', addColumn);
    addTaskBtn.addEventListener('click', addTask);
    setNameBtn.addEventListener('click', setUserName);

    // Initial render
    renderBoard();
});
