// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Store the board state in memory (in a real app, use a database)
let boardState = {
    columns: [
        { id: 'todo', title: 'To Do', tasks: [] },
        { id: 'in-progress', title: 'In Progress', tasks: [] },
        { id: 'done', title: 'Done', tasks: [] }
    ]
};

// Serve static files
app.use(express.static('public'));

// Socket.io connection handler
io.on('connection', (socket) => {
    console.log('New client connected');

    // Send the current board state to the new client
    socket.emit('boardState', boardState);

    // Handle column events
    socket.on('columnAdded', (column) => {
        boardState.columns.push(column);
        socket.broadcast.emit('columnAdded', column);
    });

    socket.on('columnUpdated', (updatedColumn) => {
        const index = boardState.columns.findIndex(c => c.id === updatedColumn.id);
        if (index !== -1) {
            boardState.columns[index] = updatedColumn;
            socket.broadcast.emit('columnUpdated', updatedColumn);
        }
    });

    socket.on('columnDeleted', (columnId) => {
        boardState.columns = boardState.columns.filter(c => c.id !== columnId);
        socket.broadcast.emit('columnDeleted', columnId);
    });

    // Handle task events
    socket.on('taskAdded', ({ columnId, task }) => {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            column.tasks.push(task);
            socket.broadcast.emit('taskAdded', { columnId, task });
        }
    });

    socket.on('taskUpdated', ({ columnId, task }) => {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            const index = column.tasks.findIndex(t => t.id === task.id);
            if (index !== -1) {
                column.tasks[index] = task;
                socket.broadcast.emit('taskUpdated', { columnId, task });
            }
        }
    });

    socket.on('taskDeleted', ({ columnId, taskId }) => {
        const column = boardState.columns.find(c => c.id === columnId);
        if (column) {
            column.tasks = column.tasks.filter(t => t.id !== taskId);
            socket.broadcast.emit('taskDeleted', { columnId, taskId });
        }
    });

    socket.on('taskMoved', ({ oldColumnId, newColumnId, taskId, task }) => {
        const oldColumn = boardState.columns.find(c => c.id === oldColumnId);
        const newColumn = boardState.columns.find(c => c.id === newColumnId);

        if (oldColumn && newColumn) {
            const taskIndex = oldColumn.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                oldColumn.tasks.splice(taskIndex, 1);
                newColumn.tasks.push(task);
                socket.broadcast.emit('taskMoved', { oldColumnId, newColumnId, taskId, task });
            }
        }
    });

    // Handle user name changes
    socket.on('userNameChanged', (name) => {
        socket.broadcast.emit('userNameChanged', name);
    });

    // Handle client requesting current board state
    socket.on('requestBoardState', () => {
        socket.emit('boardState', boardState);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
