import React, { useState, useEffect } from 'react';
import { DragDropContext } from 'react-beautiful-dnd';
import Board from './components/Board';
import { useFirestore } from './hooks/useFirestore';
import { AuthContext } from './context/AuthContext';

function App() {
  const { user } = React.useContext(AuthContext);
  const { data: boardData, updateBoard } = useFirestore('boards', 'default-board');
  const [columns, setColumns] = useState({});

  useEffect(() => {
    if (boardData) {
      setColumns(boardData.columns);
    }
  }, [boardData]);

  const onDragEnd = (result) => {
    const { destination, source, draggableId, type } = result;

    // If no destination or moved to same position
    if (!destination || (destination.droppableId === source.droppableId && destination.index === source.index)) {
      return;
    }

    // Handle column reordering
    if (type === 'column') {
      const newColumnOrder = Array.from(columns.columnOrder);
      newColumnOrder.splice(source.index, 1);
      newColumnOrder.splice(destination.index, 0, draggableId);

      const newState = {
        ...columns,
        columnOrder: newColumnOrder,
      };

      setColumns(newState);
      updateBoard(newState);
      return;
    }

    // Handle task reordering within same column
    const start = columns[source.droppableId];
    const finish = columns[destination.droppableId];

    if (start === finish) {
      const newTaskIds = Array.from(start.taskIds);
      newTaskIds.splice(source.index, 1);
      newTaskIds.splice(destination.index, 0, draggableId);

      const newColumn = {
        ...start,
        taskIds: newTaskIds,
      };

      const newState = {
        ...columns,
        [newColumn.id]: newColumn,
      };

      setColumns(newState);
      updateBoard(newState);
      return;
    }

    // Handle task moving between columns
    const startTaskIds = Array.from(start.taskIds);
    startTaskIds.splice(source.index, 1);
    const newStart = {
      ...start,
      taskIds: startTaskIds,
    };

    const finishTaskIds = Array.from(finish.taskIds);
    finishTaskIds.splice(destination.index, 0, draggableId);
    const newFinish = {
      ...finish,
      taskIds: finishTaskIds,
    };

    const newState = {
      ...columns,
      [newStart.id]: newStart,
      [newFinish.id]: newFinish,
    };

    setColumns(newState);
    updateBoard(newState);
  };

  if (!user) {
    return <div>Please sign in to access the board</div>;
  }

  return (
    <div className="app">
      <DragDropContext onDragEnd={onDragEnd}>
        <Board columns={columns} />
      </DragDropContext>
    </div>
  );
}

export default App;
```

