### 5. useFirestore.js (Custom Hook for Firebase)

```jsx
import { useState, useEffect } from 'react';
import { db } from '../firebase';
import { doc, onSnapshot, updateDoc } from 'firebase/firestore';

export const useFirestore = (collection, documentId) => {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    const docRef = doc(db, collection, documentId);

    const unsubscribe = onSnapshot(docRef, (docSnapshot) => {
      if (docSnapshot.exists()) {
        setData(docSnapshot.data());
      } else {
        setError('Document does not exist');
      }
    }, (err) => {
      setError(err.message);
    });

    return () => unsubscribe();
  }, [collection, documentId]);

  const updateDocument = async (newData) => {
    try {
      const docRef = doc(db, collection, documentId);
      await updateDoc(docRef, newData);
    } catch (err) {
      setError(err.message);
    }
  };

  return { data, error, updateDocument };
};
```

### 6. UserPresence.jsx (Real-time User Presence)

```jsx
import React, { useEffect, useState } from 'react';
import { db } from '../firebase';
import { collection, doc, onSnapshot, setDoc, serverTimestamp } from 'firebase/firestore';

const UserPresence = () => {
  const [users, setUsers] = useState([]);
  const { user } = React.useContext(AuthContext);

  useEffect(() => {
    if (!user) return;

    // Add current user to presence
    const userRef = doc(db, 'presence', user.uid);
    setDoc(userRef, {
      uid: user.uid,
      displayName: user.displayName || 'Anonymous',
      lastSeen: serverTimestamp(),
    });

    // Listen for presence changes
    const presenceRef = collection(db, 'presence');
    const unsubscribe = onSnapshot(presenceRef, (snapshot) => {
      const activeUsers = [];
      snapshot.forEach((doc) => {
        activeUsers.push(doc.data());
      });
      setUsers(activeUsers);
    });

    // Clean up on unmount
    return () => {
      if (userRef) {
        setDoc(userRef, {
          uid: user.uid,
          displayName: user.displayName || 'Anonymous',
          lastSeen: serverTimestamp(),
        }, { merge: true });
      }
      unsubscribe();
    };
  }, [user]);

  return (
    <div className="user-presence">
      <h4>Active Users:</h4>
      <div className="user-list">
        {users.map((user) => (
          <div key={user.uid} className="user">
            <span className="user-avatar">{user.displayName.charAt(0)}</span>
            <span className="user-name">{user.displayName}</span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default UserPresence;
```

