```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();
const auth = firebase.auth();

// DOM Elements
const projectList = document.getElementById('project-list');
const boardsContainer = document.getElementById('boards-container');
const projectTitle = document.getElementById('project-title');
const boardContainer = document.getElementById('board-container');
const welcomeMessage = document.getElementById('welcome-message');
const userStatus = document.getElementById('user-status');
const loginBtn = document.getElementById('login-btn');
const newProjectBtn = document.getElementById('new-project-btn');
const addProjectBtn = document.getElementById('add-project-btn');
const addBoardBtn = document.getElementById('add-board-btn');
const addTaskBtn = document.getElementById('add-task-btn');
const saveTaskBtn = document.getElementById('save-task-btn');
const saveProjectBtn = document.getElementById('save-project-btn');

// Modal elements
const taskModal = new bootstrap.Modal(document.getElementById('taskModal'));
const projectModal = new bootstrap.Modal(document.getElementById('projectModal'));

// State variables
let currentProjectId = null;
let currentTaskId = null;
let currentUser = null;

// Authentication state observer
auth.onAuthStateChanged((user) => {
    if (user) {
        currentUser = user;
        userStatus.textContent = `Logged in as ${user.email}`;
        loginBtn.textContent = 'Logout';
        loadProjects();
    } else {
        currentUser = null;
        userStatus.textContent = 'Not logged in';
        loginBtn.textContent = 'Login';
        projectList.innerHTML = '';
        boardsContainer.innerHTML = '';
        boardContainer.classList.add('d-none');
        welcomeMessage.classList.remove('d-none');
    }
});

// Event listeners
loginBtn.addEventListener('click', () => {
    if (currentUser) {
        auth.signOut();
    } else {
        // Simple email/password login for demo purposes
        const email = prompt('Enter your email:');
        const password = prompt('Enter your password:');

        if (email && password) {
            auth.signInWithEmailAndPassword(email, password)
                .catch((error) => {
                    alert(error.message);
                });
        }
    }
});

newProjectBtn.addEventListener('click', () => {
    if (!currentUser) {
        alert('Please login first');
        return;
    }
    projectModal.show();
});

addProjectBtn.addEventListener('click', () => {
    if (!currentUser) {
        alert('Please login first');
        return;
    }
    projectModal.show();
});

addBoardBtn.addEventListener('click', () => {
    if (!currentProjectId) return;

    const boardName = prompt('Enter board name:');
    if (boardName) {
        const boardRef = database.ref(`projects/${currentProjectId}/boards`).push();
        boardRef.set({
            name: boardName,
            order: Date.now()
        });
    }
});

addTaskBtn.addEventListener('click', () => {
    if (!currentProjectId) return;

    currentTaskId = null;
    document.getElementById('task-title').value = '';
    document.getElementById('task-description').value = '';
    document.getElementById('task-priority').value = 'medium';
    document.getElementById('task-due-date').value = '';
    document.getElementById('task-assignee').value = '';

    taskModal.show();
});

saveTaskBtn.addEventListener('click', () => {
    if (!currentProjectId) return;

    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const priority = document.getElementById('task-priority').value;
    const dueDate = document.getElementById('task-due-date').value;
    const assignee = document.getElementById('task-assignee').value;

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (currentTaskId) {
        // Update existing task
        database.ref(`projects/${currentProjectId}/tasks/${currentTaskId}`).update({
            title,
            description,
            priority,
            dueDate,
            assignee
        });
    } else {
        // Create new task
        const taskRef = database.ref(`projects/${currentProjectId}/tasks`).push();
        taskRef.set({
            title,
            description,
            priority,
            dueDate,
            assignee,
            boardId: null, // Will be set when dragged to a board
            order: Date.now()
        });
    }

    taskModal.hide();
});

saveProjectBtn.addEventListener('click', () => {
    const name = document.getElementById('project-name').value;
    const description = document.getElementById('project-description').value;

    if (!name) {
        alert('Please enter a project name');
        return;
    }

    if (currentProjectId) {
        // Update existing project
        database.ref(`projects/${currentProjectId}`).update({
            name,
            description
        });
    } else {
        // Create new project
        const projectRef = database.ref('projects').push();
        projectRef.set({
            name,
            description,
            createdBy: currentUser.uid,
            createdAt: firebase.database.ServerValue.TIMESTAMP
        });

        // Create default boards
        const defaultBoards = ['To Do', 'In Progress', 'Done'];
        defaultBoards.forEach((boardName, index) => {
            projectRef.child('boards').push().set({
                name: boardName,
                order: index
            });
        });
    }

    projectModal.hide();
});

// Load projects from Firebase
function loadProjects() {
    if (!currentUser) return;

    database.ref('projects').orderByChild('createdBy').equalTo(currentUser.uid).on('value', (snapshot) => {
        projectList.innerHTML = '';

        if (snapshot.exists()) {
            snapshot.forEach((childSnapshot) => {
                const project = childSnapshot.val();
                const projectId = childSnapshot.key;

                const projectItem = document.createElement('a');
                projectItem.href = '#';
                projectItem.className = `list-group-item list-group-item-action ${currentProjectId === projectId ? 'active' : ''}`;
                projectItem.textContent = project.name;
                projectItem.dataset.projectId = projectId;

                projectItem.addEventListener('click', (e) => {
                    e.preventDefault();
                    loadProject(projectId);
                });

                projectList.appendChild(projectItem);
            });
        } else {
            projectList.innerHTML = '<div class="list-group-item text-muted">No projects found</div>';
        }
    });
}

// Load a specific project
function loadProject(projectId) {
    currentProjectId = projectId;

    // Update UI
    document.querySelectorAll('.list-group-item').forEach(item => {
        item.classList.remove('active');
        if (item.dataset.projectId === projectId) {
            item.classList.add('active');
        }
    });

    boardContainer.classList.remove('d-none');
    welcomeMessage.classList.add('d-none');

    // Load project data
    database.ref(`projects/${projectId}`).once('value', (snapshot) => {
        const project = snapshot.val();
        projectTitle.textContent = project.name;
    });

    // Load boards
    database.ref(`projects/${projectId}/boards`).orderByChild('order').on('value', (snapshot) => {
        boardsContainer.innerHTML = '';

        if (snapshot.exists()) {
            snapshot.forEach((childSnapshot) => {
                const board = childSnapshot.val();
                const boardId = childSnapshot.key;

                const boardElement = document.createElement('div');
                boardElement.className = 'board';
                boardElement.dataset.boardId = boardId;

                boardElement.innerHTML = `
                    <div class="board-header">
                        <h3 class="board-title">${board.name}</h3>
                        <div class="dropdown">
                            <button class="btn btn-sm btn-outline-secondary dropdown-toggle" type="button" data-bs-toggle="dropdown" aria-expanded="false">
                                <i class="fas fa-ellipsis-h"></i>
                            </button>
                            <ul class="dropdown-menu">
                                <li><a class="dropdown-item" href="#" data-action="rename">Rename</a></li>
                                <li><a class="dropdown-item" href="#" data-action="delete">Delete</a></li>
                            </ul>
                        </div>
                    </div>
                    <div class="board-body" id="board-${boardId}">
                        <!-- Tasks will be loaded here -->
                    </div>
                    <button class="add-task-btn" data-board-id="${boardId}">
                        <i class="fas fa-plus me-1"></i> Add Task
                    </button>
                `;

                boardsContainer.appendChild(boardElement);

                // Load tasks for this board
                loadTasksForBoard(projectId, boardId);
            });
        } else {
            boardsContainer.innerHTML = '<div class="text-muted">No boards found. Add a board to get started.</div>';
        }

        // Add event listeners for board actions
        document.querySelectorAll('.dropdown-item').forEach(item => {
            item.addEventListener('click', (e) => {
                e.preventDefault();
                const action = item.dataset.action;
                const boardId = item.closest('.board').dataset.boardId;

                if (action === 'rename') {
                    const newName = prompt('Enter new board name:', item.closest('.board').querySelector('.board-title').textContent);
                    if (newName) {
                        database.ref(`projects/${projectId}/boards/${boardId}`).update({
                            name: newName
                        });
                    }
                } else if (action === 'delete') {
                    if (confirm('Are you sure you want to delete this board? All tasks in this board will be moved to unassigned.')) {
                        // Move tasks to unassigned before deleting board
                        database.ref(`projects/${projectId}/tasks`).orderByChild('boardId').equalTo(boardId).once('value', (tasksSnapshot) => {
                            tasksSnapshot.forEach((taskSnapshot) => {
                                database.ref(`projects/${projectId}/tasks/${taskSnapshot.key}`).update({
                                    boardId: null
                                });
                            });

                            // Delete the board
                            database.ref(`projects/${projectId}/boards/${boardId}`).remove();
                        });
                    }
                }
            });
        });

        // Add event listeners for add task buttons
        document.querySelectorAll('.add-task-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                const boardId = btn.dataset.boardId;
                currentTaskId = null;
                document.getElementById('task-title').value = '';
                document.getElementById('task-description').value = '';
                document.getElementById('task-priority').value = 'medium';
                document.getElementById('task-due-date').value = '';
                document.getElementById('task-assignee').value = '';

                // Set the boardId for the new task
                saveTaskBtn.dataset.boardId = boardId;

                taskModal.show();
            });
        });
    });

    // Load unassigned tasks
    loadUnassignedTasks(projectId);
}

// Load tasks for a specific board
function loadTasksForBoard(projectId, boardId) {
    database.ref(`projects/${projectId}/tasks`).orderByChild('boardId').equalTo(boardId).on('value', (snapshot) => {
        const boardBody = document.getElementById(`board-${boardId}`);
        boardBody.innerHTML = '';

        if (snapshot.exists()) {
            snapshot.forEach((childSnapshot) => {
                const task = childSnapshot.val();
                const taskId = childSnapshot.key;

                const taskElement = document.createElement('div');
                taskElement.className = 'task';
                taskElement.draggable = true;
                taskElement.dataset.taskId = taskId;

                taskElement.innerHTML = `
                    <div class="task-title">${task.title}</div>
                    <div class="task-meta">
                        <span class="priority-${task.priority}">${task.priority}</span>
                        ${task.dueDate ? ` • Due: ${task.dueDate}` : ''}
                        ${task.assignee ? ` • ${task.assignee}` : ''}
                    </div>
                `;

                // Add drag event listeners
                taskElement.addEventListener('dragstart', handleDragStart);
                taskElement.addEventListener('dragend', handleDragEnd);

                // Add click event to edit task
                taskElement.addEventListener('click', (e) => {
                    if (e.target.closest('.task')) {
                        currentTaskId = taskId;
                        document.getElementById('task-title').value = task.title || '';
                        document.getElementById('task-description').value = task.description || '';
                        document.getElementById('task-priority').value = task.priority || 'medium';
                        document.getElementById('task-due-date').value = task.dueDate || '';
                        document.getElementById('task-assignee').value = task.assignee || '';

                        taskModal.show();
                    }
                });

                boardBody.appendChild(taskElement);
            });
        } else {
            boardBody.innerHTML = '<div class="text-muted text-center py-3">No tasks in this board</div>';
        }
    });
}

// Load unassigned tasks
function loadUnassignedTasks(projectId) {
    database.ref(`projects/${projectId}/tasks`).orderByChild('boardId').equalTo(null).on('value', (snapshot) => {
        const unassignedContainer = document.createElement('div');
        unassignedContainer.className = 'board';
        unassignedContainer.innerHTML = `
            <div class="board-header">
                <h3 class="board-title">Unassigned</h3>
            </div>
            <div class="board-body" id="unassigned-tasks">
                <!-- Unassigned tasks will be loaded here -->
            </div>
        `;

        boardsContainer.appendChild(unassignedContainer);

        const unassignedBody = document.getElementById('unassigned-tasks');
        unassignedBody.innerHTML = '';

        if (snapshot.exists()) {
            snapshot.forEach((childSnapshot) => {
                const task = childSnapshot.val();
                const taskId = childSnapshot.key;

                const taskElement = document.createElement('div');
                taskElement.className = 'task';
                taskElement.draggable = true;
                taskElement.dataset.taskId = taskId;

                taskElement.innerHTML = `
                    <div class="task-title">${task.title}</div>
                    <div class="task-meta">
                        <span class="priority-${task.priority}">${task.priority}</span>
                        ${task.dueDate ? ` • Due: ${task.dueDate}` : ''}
                        ${task.assignee ? ` • ${task.assignee}` : ''}
                    </div>
                `;

                // Add drag event listeners
                taskElement.addEventListener('dragstart', handleDragStart);
                taskElement.addEventListener('dragend', handleDragEnd);

                // Add click event to edit task
                taskElement.addEventListener('click', (e) => {
                    if (e.target.closest('.task')) {
                        currentTaskId = taskId;
                        document.getElementById('task-title').value = task.title || '';
                        document.getElementById('task-description').value = task.description || '';
                        document.getElementById('task-priority').value = task.priority || 'medium';
                        document.getElementById('task-due-date').value = task.dueDate || '';
                        document.getElementById('task-assignee').value = task.assignee || '';

                        taskModal.show();
                    }
                });

                unassignedBody.appendChild(taskElement);
            });
        } else {
