// Drag and Drop functionality
let draggedTask = null;

function handleDragStart(e) {
    draggedTask = this;
    e.dataTransfer.setData('text/plain', this.dataset.taskId);
    setTimeout(() => {
        this.style.opacity = '0.4';
    }, 0);
}

function handleDragEnd(e) {
    this.style.opacity = '1';
    draggedTask = null;
}

// Add drop event listeners to boards
boardsContainer.addEventListener('dragover', (e) => {
    e.preventDefault();
    const board = e.target.closest('.board');
    if (board) {
        board.classList.add('drag-over');
    }
});

boardsContainer.addEventListener('dragleave', (e) => {
    const board = e.target.closest('.board');
    if (board) {
        board.classList.remove('drag-over');
    }
});

boardsContainer.addEventListener('drop', (e) => {
    e.preventDefault();
    const board = e.target.closest('.board');
    if (board && draggedTask) {
        board.classList.remove('drag-over');

        const taskId = draggedTask.dataset.taskId;
        const boardId = board.dataset.boardId || null; // null for unassigned

        // Update task's boardId in Firebase
        database.ref(`projects/${currentProjectId}/tasks/${taskId}`).update({
            boardId: boardId,
            order: Date.now() // Update order to move to the end of the board
        });
    }
});
