// Initialize the application
document.addEventListener('DOMContentLoaded', function() {
    // DOM elements
    const board = document.getElementById('board');
    const addColumnBtn = document.getElementById('add-column-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const modalTitle = document.getElementById('modal-title');
    const connectionStatus = document.getElementById('connection-status');
    const userNameElement = document.getElementById('user-name');

    // State variables
    let currentUser = 'Guest';
    let currentBoardState = [];
    let currentTaskId = null;
    let currentColumnId = null;
    let socket = null;

    // Initialize the app
    initApp();

    // Initialize the application
    function initApp() {
        // Set up WebSocket connection
        setupWebSocket();

        // Load saved board state
        loadBoardState();

        // Set up event listeners
        setupEventListeners();

        // Set user name
        setUserName();
    }

    // Set up WebSocket connection
    function setupWebSocket() {
        // In a real app, you would connect to your server
        // socket = io('http://your-server-url');

        // For this demo, we'll simulate WebSocket behavior
        connectionStatus.textContent = 'Connected';
        connectionStatus.className = 'connected';

        // Simulate receiving updates from other users
        setTimeout(() => {
            // In a real app, you would listen for 'board-update' events
            // socket.on('board-update', (newState) => {
            //     updateBoardState(newState);
            // });

            // For demo purposes, we'll simulate receiving updates
            simulateCollaboration();
        }, 1000);
    }

    // Simulate collaboration from other users
    function simulateCollaboration() {
        // This would be replaced with actual WebSocket events in a real app
        setTimeout(() => {
            const randomColumnIndex = Math.floor(Math.random() * currentBoardState.length);
            const randomColumn = currentBoardState[randomColumnIndex];

            if (randomColumn && randomColumn.tasks.length > 0) {
                const randomTaskIndex = Math.floor(Math.random() * randomColumn.tasks.length);
                const randomTask = randomColumn.tasks[randomTaskIndex];

                // Simulate moving a task
                const newColumnIndex = (randomColumnIndex + 1) % currentBoardState.length;
                const newColumn = currentBoardState[newColumnIndex];

                if (newColumn) {
                    // Move the task
                    randomColumn.tasks.splice(randomTaskIndex, 1);
                    newColumn.tasks.push(randomTask);

                    // Update the UI
                    renderBoard();

                    // Save the state
                    saveBoardState();

                    // In a real app, you would emit this change to the server
                    // socket.emit('task-moved', {
                    //     taskId: randomTask.id,
                    //     fromColumnId: randomColumn.id,
                    //     toColumnId: newColumn.id,
                    //     user: currentUser
                    // });
                }
            }

            // Continue simulating collaboration
            simulateCollaboration();
        }, 10000 + Math.random() * 20000); // Random interval between 10-30 seconds
    }

    // Set user name
    function setUserName() {
        // In a real app, you would get this from authentication
        const savedName = localStorage.getItem('taskboard-user');
        if (savedName) {
            currentUser = savedName;
        } else {
            currentUser = prompt('Enter your name:', 'Guest') || 'Guest';
            localStorage.setItem('taskboard-user', currentUser);
        }
        userNameElement.textContent = currentUser;
    }

    // Set up event listeners
    function setupEventListeners() {
        // Add column button
        addColumnBtn.addEventListener('click', () => {
            const columnName = prompt('Enter column name:', 'New Column');
            if (columnName) {
                addColumn(columnName);
            }
        });

        // Close modal
        closeModal.addEventListener('click', () => {
            taskModal.style.display = 'none';
        });

        // Form submission
        taskForm.addEventListener('submit', (e) => {
            e.preventDefault();
            saveTask();
        });

        // Make the board scrollable horizontally
        board.addEventListener('wheel', (e) => {
            if (e.deltaY !== 0) {
                e.preventDefault();
                board.scrollLeft += e.deltaY;
            }
        });
    }

    // Add a new column to the board
    function addColumn(title) {
        const columnId = Date.now().toString();
        const newColumn = {
            id: columnId,
            title: title,
            tasks: []
        };

        currentBoardState.push(newColumn);
        renderBoard();
        saveBoardState();

        // In a real app, you would emit this change to the server
        // socket.emit('column-added', newColumn);
    }

    // Delete a column
    function deleteColumn(columnId) {
        if (confirm('Are you sure you want to delete this column and all its tasks?')) {
            currentBoardState = currentBoardState.filter(column => column.id !== columnId);
            renderBoard();
            saveBoardState();

            // In a real app, you would emit this change to the server
            // socket.emit('column-deleted', columnId);
        }
    }

    // Rename a column
    function renameColumn(columnId) {
        const column = currentBoardState.find(col => col.id === columnId);
        if (column) {
            const newName = prompt('Enter new column name:', column.title);
            if (newName && newName !== column.title) {
                column.title = newName;
                renderBoard();
                saveBoardState();

                // In a real app, you would emit this change to the server
                // socket.emit('column-renamed', { columnId, newName });
            }
        }
    }

    // Add a new task to a column
    function addTask(columnId) {
        currentColumnId = columnId;
        currentTaskId = null;

        // Reset form
        taskForm.reset();
        modalTitle.textContent = 'Add New Task';
        taskModal.style.display = 'block';
    }

    // Edit an existing task
    function editTask(taskId, columnId) {
        currentTaskId = taskId;
        currentColumnId = columnId;

        const column = currentBoardState.find(col => col.id === columnId);
        if (column) {
            const task = column.tasks.find(t => t.id === taskId);
            if (task) {
                document.getElementById('task-title').value = task.title;
                document.getElementById('task-description').value = task.description || '';
                document.getElementById('task-priority').value = task.priority || 'medium';
                document.getElementById('task-due-date').value = task.dueDate || '';
                document.getElementById('task-assignee').value = task.assignee || '';

                modalTitle.textContent = 'Edit Task';
                taskModal.style.display = 'block';
            }
        }
    }

    // Save task (add or update)
    function saveTask() {
        const title = document.getElementById('task-title').value.trim();
        const description = document.getElementById('task-description').value.trim();
        const priority = document.getElementById('task-priority').value;
        const dueDate = document.getElementById('task-due-date').value;
        const assignee = document.getElementById('task-assignee').value.trim();

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        const column = currentBoardState.find(col => col.id === currentColumnId);
        if (column) {
            if (currentTaskId) {
                // Update existing task
                const taskIndex = column.tasks.findIndex(t => t.id === currentTaskId);
                if (taskIndex !== -1) {
                    column.tasks[taskIndex] = {
                        ...column.tasks[taskIndex],
                        title,
                        description,
                        priority,
                        dueDate,
                        assignee,
                        updatedBy: currentUser,
                        updatedAt: new Date().toISOString()
                    };

                    // In a real app, you would emit this change to the server
                    // socket.emit('task-updated', {
                    //     taskId: currentTaskId,
                    //     columnId: currentColumnId,
                    //     task: column.tasks[taskIndex]
                    // });
                }
            } else {
                // Add new task
                const newTask = {
                    id: Date.now().toString(),
                    title,
                    description,
                    priority,
                    dueDate,
                    assignee,
                    createdBy: currentUser,
                    createdAt: new Date().toISOString(),
                    updatedBy: currentUser,
                    updatedAt: new Date().toISOString()
                };

                column.tasks.push(newTask);

                // In a real app, you would emit this change to the server
                // socket.emit('task-added', {
                //     columnId: currentColumnId,
                //     task: newTask
                // });
            }

            renderBoard();
            saveBoardState();
            taskModal.style.display = 'none';
        }
    }

    // Delete a task
    function deleteTask(taskId, columnId) {
        if (confirm('Are you sure you want to delete this task?')) {
            const column = currentBoardState.find(col => col.id === columnId);
            if (column) {
                column.tasks = column.tasks.filter(task => task.id !== taskId);
                renderBoard();
                saveBoardState();

                // In a real app, you would emit this change to the server
                // socket.emit('task-deleted', { taskId, columnId });
            }
        }
    }

    // Render the entire board
    function renderBoard() {
        board.innerHTML = '';

        currentBoardState.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.columnId = column.id;

            // Column header
            const columnHeader = document.createElement('div');
            columnHeader.className = 'column-header';

            const columnTitle = document.createElement('div');
            columnTitle.className = 'column-title';
            columnTitle.textContent = column.title;

            const columnActions = document.createElement('div');
            columnActions.className = 'column-actions';

            const renameBtn = document.createElement('i');
            renameBtn.className = 'fas fa-edit';
            renameBtn.title = 'Rename column';
            renameBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                renameColumn(column.id);
            });

            const deleteBtn = document.createElement('i');
            deleteBtn.className = 'fas fa-trash';
            deleteBtn.title = 'Delete column';
            deleteBtn.addEventListener('click', (e) => {
                e.stopPropagation();
                deleteColumn(column.id);
            });

            columnActions.appendChild(renameBtn);
            columnActions.appendChild(deleteBtn);
            columnHeader.appendChild(columnTitle);
            columnHeader.appendChild(columnActions);

            // Task list
            const taskList = document.createElement('div');
            taskList.className = 'task-list';
            taskList.dataset.columnId = column.id;

            // Make the task list a drop target
            taskList.addEventListener('dragover', (e) => {
                e.preventDefault();
                taskList.classList.add('drag-over');
            });

            taskList.addEventListener('dragleave', () => {
                taskList.classList.remove('drag-over');
            });

            taskList.addEventListener('drop', (e) => {
                e.preventDefault();
                taskList.classList.remove('drag-over');

                const taskId = e.dataTransfer.getData('text/plain');
                const fromColumnId = e.dataTransfer.getData('fromColumnId');

                if (taskId && fromColumnId) {
                    moveTask(taskId, fromColumnId, column.id);
                }
            });

            // Render tasks
            column.tasks.forEach(task => {
                const taskElement = document.createElement('div');
                taskElement.className = 'task';
                taskElement.draggable = true;
                taskElement.dataset.taskId = task.id;
                taskElement.dataset.columnId = column.id;

                // Drag events
                taskElement.addEventListener('dragstart', (e) => {
                    e.dataTransfer.setData('text/plain', task.id);
                    e.dataTransfer.setData('fromColumnId', column.id);
                    taskElement.classList.add('dragging');
                });

                taskElement.addEventListener('dragend', () => {
                    taskElement.classList.remove('dragging');
                });

                // Task content
                const taskHeader = document.createElement('div');
                taskHeader.className = 'task-header';

                const taskTitle = document.createElement('div');
                taskTitle.className = 'task-title';
                taskTitle.textContent = task.title;

                const taskPriority = document.createElement('div');
                taskPriority.className = `task-priority ${task.priority || 'medium'}`;
                taskPriority.textContent = (task.priority || 'medium').charAt(0).toUpperCase() + (task.priority || 'medium').slice(1);

                taskHeader.appendChild(taskTitle);
                taskHeader.appendChild(taskPriority);

                const taskDescription = document.createElement('div');
                taskDescription.className = 'task-description';
                taskDescription.textContent = task.description || '';

                const taskMeta = document.createElement('div');
                taskMeta.className = 'task-meta';

                const assignee = document.createElement('span');
                assignee.textContent = task.assignee ? `Assigned: ${task.assignee}` : 'Unassigned';

                const dueDate = document.createElement('span');
                dueDate.textContent = task.dueDate ? `Due: ${formatDate(task.dueDate)}` : 'No due date';

                taskMeta.appendChild(assignee);
                taskMeta.appendChild(dueDate);

                // Task actions
                const taskActions = document.createElement('div');
                taskActions.className = 'task-actions';

                const editBtn = document.createElement('i');
                editBtn.className = 'fas fa-edit';
                editBtn.title = 'Edit task';
                editBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    editTask(task.id, column.id);
                });

                const deleteBtn = document.createElement('i');
                deleteBtn.className = 'fas fa-trash';
                deleteBtn.title = 'Delete task';
                deleteBtn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    deleteTask(task.id, column.id);
                });

                taskActions.appendChild(editBtn);
                taskActions.appendChild(deleteBtn);

                taskElement.appendChild(taskHeader);
                taskElement.appendChild(taskDescription);
                taskElement.appendChild(taskMeta);
                taskElement.appendChild(taskActions);

                // Click to edit
                taskElement.addEventListener('click', () => {
                    editTask(task.id, column.id);
                });

                taskList.appendChild(taskElement);
            });

            // Add task button
            const addTaskBtn = document.createElement('div');
            addTaskBtn.className = 'add-task-btn';
            addTaskBtn.innerHTML = '<i class="fas fa-plus"></i> Add Task';
            addTaskBtn.addEventListener('click', () => {
                addTask(column.id);
            });

            columnElement.appendChild(columnHeader);
            columnElement.appendChild(taskList);
            columnElement.appendChild(addTaskBtn);

            board.appendChild(columnElement);
        });
    }

    // Move a task between columns
    function moveTask(taskId, fromColumnId, toColumnId) {
        if (fromColumnId === toColumnId) return;

        const fromColumn = currentBoardState.find(col => col.id === fromColumnId);
        const toColumn = currentBoardState.find(col => col.id === toColumnId);

        if (fromColumn && toColumn) {
            const taskIndex = fromColumn.tasks.findIndex(task => task.id === taskId);
            if (taskIndex !== -1) {
                const [movedTask] = fromColumn.tasks.splice(taskIndex, 1);
                toColumn.tasks.push(movedTask);

                renderBoard();
                saveBoardState();

                // In a real app, you would emit this change to the server
                // socket.emit('task-moved', {
                //     taskId,
                //     fromColumnId,
                //     toColumnId,
                //     user: currentUser
                // });
            }
        }
    }

    // Save board state to localStorage
    function saveBoardState() {
        localStorage.setItem('taskboard-state', JSON.stringify(currentBoardState));
    }

    // Load board state from localStorage
    function loadBoardState() {
        const savedState = localStorage.getItem('taskboard-state');
        if (savedState) {
            try {
                currentBoardState = JSON.parse(savedState);
                renderBoard();
            } catch (e) {
                console.error('Error loading board state:', e);
                // Initialize with default columns if there's an error
                initializeDefaultBoard();
            }
        } else {
            initializeDefaultBoard();
        }
    }

    // Initialize with default columns
    function initializeDefaultBoard() {
        currentBoardState = [
            {
                id: '1',
                title: 'To Do',
                tasks: []
            },
            {
                id: '2',
                title: 'In Progress',
                tasks: []
            },
            {
                id: '3',
                title: 'Done',
                tasks: []
            }
        ];
        renderBoard();
        saveBoardState();
    }

    // Format date for display
    function formatDate(dateString) {
        if (!dateString) return '';
        const date = new Date(dateString);
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    }

    // Update board state from server (simulated)
    function updateBoardState(newState) {
        currentBoardState = newState;
        renderBoard();
    }
});
