## Backend Implementation (Optional)

For a complete real-time collaboration feature, you would need a backend server. Here's a basic Node.js/Express implementation using Socket.io:

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static(path.join(__dirname, 'public')));

// Store board state in memory (in a real app, use a database)
let boardState = {
    columns: [
        { id: '1', title: 'To Do', tasks: [] },
        { id: '2', title: 'In Progress', tasks: [] },
        { id: '3', title: 'Done', tasks: [] }
    ]
};

// Socket.io connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Send current board state to the new client
    socket.emit('board-state', boardState);

    // Handle column additions
    socket.on('column-added', (newColumn) => {
        boardState.columns.push(newColumn);
        socket.broadcast.emit('column-added', newColumn);
    });

    // Handle column deletions
    socket.on('column-deleted', (columnId) => {
        boardState.columns = boardState.columns.filter(col => col.id !== columnId);
        socket.broadcast.emit('column-deleted', columnId);
    });

    // Handle column renames
    socket.on('column-renamed', ({ columnId, newName }) => {
        const column = boardState.columns.find(col => col.id === columnId);
        if (column) {
            column.title = newName;
            socket.broadcast.emit('column-renamed', { columnId, newName });
        }
    });

    // Handle task additions
    socket.on('task-added', ({ columnId, task }) => {
        const column = boardState.columns.find(col => col.id === columnId);
        if (column) {
            column.tasks.push(task);
            socket.broadcast.emit('task-added', { columnId, task });
        }
    });

    // Handle task updates
    socket.on('task-updated', ({ taskId, columnId, task }) => {
        const column = boardState.columns.find(col => col.id === columnId);
        if (column) {
            const taskIndex = column.tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                column.tasks[taskIndex] = task;
                socket.broadcast.emit('task-updated', { taskId, columnId, task });
            }
        }
    });

    // Handle task deletions
    socket.on('task-deleted', ({ taskId, columnId }) => {
        const column = boardState.columns.find(col => col.id === columnId);
        if (column) {
            column.tasks = column.tasks.filter(task => task.id !== taskId);
            socket.broadcast.emit('task-deleted', { taskId, columnId });
        }
    });

    // Handle task movements
    socket.on('task-moved', ({ taskId, fromColumnId, toColumnId, user }) => {
        const fromColumn = boardState.columns.find(col => col.id === fromColumnId);
        const toColumn = boardState.columns.find(col => col.id === toColumnId);

        if (fromColumn && toColumn) {
            const taskIndex = fromColumn.tasks.findIndex(task => task.id === taskId);
            if (taskIndex !== -1) {
                const [movedTask] = fromColumn.tasks.splice(taskIndex, 1);
                toColumn.tasks.push(movedTask);

                // Broadcast the move to all other clients
                socket.broadcast.emit('task-moved', {
                    taskId,
                    fromColumnId,
                    toColumnId,
                    user
                });
            }
        }
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

## Features Implemented

1. **Drag-and-Drop Tasks**:
