## JavaScript Implementation

```javascript
// app.js
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.IO connection
    const socket = io();

    // DOM Elements
    const board = document.getElementById('board');
    const projectsList = document.getElementById('projects-list');
    const projectTitle = document.getElementById('project-title');
    const addColumnBtn = document.getElementById('add-column-btn');
    const newProjectBtn = document.getElementById('new-project-btn');
    const shareBtn = document.getElementById('share-btn');
    const logoutBtn = document.getElementById('logout-btn');

    // Modals
    const taskModal = document.getElementById('task-modal');
    const projectModal = document.getElementById('project-modal');
    const shareModal = document.getElementById('share-modal');

    // Modal close buttons
    const closeButtons = document.querySelectorAll('.close');

    // Form elements
    const taskForm = document.getElementById('task-form');
    const projectForm = document.getElementById('project-form');

    // Current state
    let currentProjectId = null;
    let currentUser = 'Guest';
    let projects = [];
    let tasks = [];

    // Initialize the app
    initApp();

    function initApp() {
        // Load user data from localStorage
        loadUserData();

        // Set up event listeners
        setupEventListeners();

        // Initialize drag-and-drop
        initDragula();

        // Load initial data
        loadProjects();

        // Set up real-time updates
        setupSocketEvents();
    }

    function loadUserData() {
        const savedUser = localStorage.getItem('taskboardUser');
        if (savedUser) {
            currentUser = savedUser;
            document.getElementById('username').textContent = currentUser;
        }
    }

    function setupEventListeners() {
        // Project list click
        projectsList.addEventListener('click', function(e) {
            if (e.target.tagName === 'LI') {
                const projectId = e.target.dataset.id;
                loadProject(projectId);
            }
        });

        // Add column button
        addColumnBtn.addEventListener('click', addColumn);

        // New project button
        newProjectBtn.addEventListener('click', function() {
            projectModal.style.display = 'block';
        });

        // Share button
        shareBtn.addEventListener('click', function() {
            if (currentProjectId) {
                const project = projects.find(p => p.id === currentProjectId);
                document.getElementById('share-link').value = `${window.location.origin}/share/${project.id}`;
                shareModal.style.display = 'block';
            }
        });

        // Logout button
        logoutBtn.addEventListener('click', function() {
            localStorage.removeItem('taskboardUser');
            window.location.reload();
        });

        // Close modal buttons
        closeButtons.forEach(button => {
            button.addEventListener('click', function() {
                this.closest('.modal').style.display = 'none';
            });
        });

        // Window click to close modals
        window.addEventListener('click', function(e) {
            if (e.target.classList.contains('modal')) {
                e.target.style.display = 'none';
            }
        });

        // Task form submission
        taskForm.addEventListener('submit', function(e) {
            e.preventDefault();
            saveTask();
        });

        // Project form submission
        projectForm.addEventListener('submit', function(e) {
            e.preventDefault();
            createProject();
        });

        // Copy share link
        document.getElementById('copy-link-btn').addEventListener('click', function() {
            const copyText = document.getElementById('share-link');
            copyText.select();
            document.execCommand('copy');
            alert('Link copied to clipboard!');
        });

        // Add collaborator
        document.getElementById('add-collaborator-btn').addEventListener('click', addCollaborator);
    }

    function initDragula() {
        const drake = dragula({
            isContainer: function(el) {
                return el.classList.contains('column');
            },
            moves: function(el, source, handle, sibling) {
                return el.classList.contains('task-card');
            }
        });

        drake.on('drop', function(el, target, source, sibling) {
            const taskId = el.dataset.id;
            const newColumnId = target.closest('.column').dataset.id;

            // Update task in local data
            const taskIndex = tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                tasks[taskIndex].columnId = newColumnId;

                // Save to localStorage
                saveTasksToLocalStorage();

                // Emit update to server
                socket.emit('taskUpdated', {
                    projectId: currentProjectId,
                    task: tasks[taskIndex]
                });
            }
        });
    }

    function loadProjects() {
        // Load from localStorage or use default
        const savedProjects = localStorage.getItem('taskboardProjects');
        if (savedProjects) {
            projects = JSON.parse(savedProjects);
        } else {
            // Create default project
            const defaultProject = {
                id: 'proj-' + Date.now(),
                name: 'My First Project',
                description: 'Default project',
                columns: [
                    { id: 'col-1', title: 'To Do' },
                    { id: 'col-2', title: 'In Progress' },
                    { id: 'col-3', title: 'Done' }
                ],
                collaborators: []
            };
            projects.push(defaultProject);
            saveProjectsToLocalStorage();
        }

        // Render projects list
        renderProjectsList();

        // Load first project by default
        if (projects.length > 0) {
            loadProject(projects[0].id);
        }
    }

    function renderProjectsList() {
        projectsList.innerHTML = '';
        projects.forEach(project => {
            const li = document.createElement('li');
            li.textContent = project.name;
            li.dataset.id = project.id;
            if (project.id === currentProjectId) {
                li.classList.add('active');
            }
            projectsList.appendChild(li);
        });
    }

    function loadProject(projectId) {
        currentProjectId = projectId;
        const project = projects.find(p => p.id === projectId);

        if (!project) return;

        // Update UI
        projectTitle.textContent = project.name;
        renderProjectsList();

        // Load tasks for this project
        loadTasks(projectId);

        // Render board
        renderBoard(project);
    }

    function renderBoard(project) {
        board.innerHTML = '';

        project.columns.forEach(column => {
            const columnElement = document.createElement('div');
            columnElement.className = 'column';
            columnElement.dataset.id = column.id;

            const columnHeader = document.createElement('div');
            columnHeader.className = 'column-header';

            const columnTitle = document.createElement('div');
            columnTitle.className = 'column-title';
            columnTitle.textContent = column.title;

            const columnActions = document.createElement('div');
            columnActions.className = 'column-actions';

            const addTaskBtn = document.createElement('button');
            addTaskBtn.className = 'add-task-btn';
            addTaskBtn.innerHTML = '<i class="fas fa-plus"></i>';
            addTaskBtn.addEventListener('click', function() {
                openTaskModal(null, column.id);
            });

            columnActions.appendChild(addTaskBtn);
            columnHeader.appendChild(columnTitle);
            columnHeader.appendChild(columnActions);

            const columnContent = document.createElement('div');
            columnContent.className = 'column-content';

            columnElement.appendChild(columnHeader);
            columnElement.appendChild(columnContent);

            board.appendChild(columnElement);

            // Render tasks in this column
            renderTasks(column.id, columnContent);
        });
    }

    function renderTasks(columnId, container) {
        const columnTasks = tasks.filter(task => task.columnId === columnId);

        columnTasks.forEach(task => {
            const taskCard = createTaskCard(task);
            container.appendChild(taskCard);
        });
    }

    function createTaskCard(task) {
        const taskCard = document.createElement('div');
        taskCard.className = 'task-card';
        taskCard.dataset.id = task.id;

        const taskTitle = document.createElement('div');
        taskTitle.className = 'task-title';
        taskTitle.textContent = task.title;

        const taskMeta = document.createElement('div');
        taskMeta.className = 'task-meta';

        const assignee = document.createElement('span');
        assignee.textContent = task.assignee || 'Unassigned';

        const priority = document.createElement('span');
        priority.className = `priority-${task.priority}`;
        priority.textContent = task.priority.charAt(0).toUpperCase() + task.priority.slice(1);

        taskMeta.appendChild(assignee);
        taskMeta.appendChild(priority);

        taskCard.appendChild(taskTitle);
        taskCard.appendChild(taskMeta);

        // Add click event to open task details
        taskCard.addEventListener('click', function(e) {
            if (!e.target.classList.contains('add-task-btn')) {
                openTaskModal(task.id);
            }
        });

        return taskCard;
    }

    function openTaskModal(taskId, columnId = null) {
        if (taskId) {
            // Edit existing task
            const task = tasks.find(t => t.id === taskId);
            if (task) {
                document.getElementById('task-id').value = task.id;
                document.getElementById('task-title').value = task.title;
                document.getElementById('task-description').value = task.description || '';
                document.getElementById('task-assignee').value = task.assignee || '';
                document.getElementById('task-due-date').value = task.dueDate || '';
                document.getElementById('task-priority').value = task.priority || 'medium';
            }
        } else {
            // New task
            document.getElementById('task-form').reset();
            document.getElementById('task-id').value = '';
            // Set the column ID for new tasks
            if (columnId) {
                document.getElementById('task-id').dataset.columnId = columnId;
            }
        }

        taskModal.style.display = 'block';
    }

    function saveTask() {
        const taskId = document.getElementById('task-id').value;
        const columnId = document.getElementById('task-id').dataset.columnId || null;

        const task = {
            id: taskId || 'task-' + Date.now(),
            projectId: currentProjectId,
            columnId: columnId || (taskId ? tasks.find(t => t.id === taskId).columnId : null),
            title: document.getElementById('task-title').value,
            description: document.getElementById('task-description').value,
            assignee: document.getElementById('task-assignee').value,
            dueDate: document.getElementById('task-due-date').value,
            priority: document.getElementById('task-priority').value,
            createdBy: currentUser,
            createdAt: taskId ? tasks.find(t => t.id === taskId).createdAt : new Date().toISOString()
        };

        if (taskId) {
            // Update existing task
            const index = tasks.findIndex(t => t.id === taskId);
            if (index !== -1) {
                tasks[index] = task;
            }
        } else {
            // Add new task
            tasks.push(task);
        }

        // Save to localStorage
        saveTasksToLocalStorage();

        // Emit update to server
        socket.emit('taskUpdated', {
            projectId: currentProjectId,
            task: task
        });

        // Close modal and refresh board
        taskModal.style.display = 'none';
        loadProject(currentProjectId);
    }

    function addColumn() {
        const columnName = prompt('Enter column name:');
        if (columnName) {
            const project = projects.find(p => p.id === currentProjectId);
            if (project) {
                const newColumn = {
                    id: 'col-' + Date.now(),
                    title: columnName
                };
                project.columns.push(newColumn);

                // Save to localStorage
                saveProjectsToLocalStorage();

                // Emit update to server
                socket.emit('columnAdded', {
                    projectId: currentProjectId,
                    column: newColumn
                });

                // Refresh board
                renderBoard(project);
            }
        }
    }

    function createProject() {
        const projectName = document.getElementById('project-name').value;
        const projectDescription = document.getElementById('project-description').value;

        if (projectName) {
            const newProject = {
                id: 'proj-' + Date.now(),
                name: projectName,
                description: projectDescription,
                columns: [
                    { id: 'col-1', title: 'To Do' },
                    { id: 'col-2', title: 'In Progress' },
                    { id: 'col-3', title: 'Done' }
                ],
                collaborators: []
            };

            projects.push(newProject);

            // Save to localStorage
            saveProjectsToLocalStorage();

            // Emit update to server
            socket.emit('projectCreated', newProject);

            // Close modal and refresh list
            projectModal.style.display = 'none';
            renderProjectsList();

            // Load the new project
            loadProject(newProject.id);
        }
    }

    function addCollaborator() {
        const email = document.getElementById('new-collaborator').value.trim();
        if (email) {
            const project = projects.find(p => p.id === currentProjectId);
            if (project) {
                if (!project.collaborators.includes(email)) {
                    project.collaborators.push(email);

                    // Save to localStorage
                    saveProjectsToLocalStorage();

                    // Emit update to server
                    socket.emit('collaboratorAdded', {
                        projectId: currentProjectId,
                        email: email
                    });

                    // Update UI
                    updateCollaboratorsList(project.collaborators);
                    document.getElementById('new-collaborator').value = '';
                } else {
                    alert('This email is already a collaborator.');
                }
            }
        }
    }

    function updateCollaboratorsList(collaborators) {
        const list = document.getElementById('collaborators-list');
        list.innerHTML = '';

        collaborators.forEach(email => {
            const item = document.createElement('div');
            item.className = 'collaborator-item';

            const emailSpan = document.createElement('span');
            emailSpan.textContent = email;

            const removeBtn = document.createElement('button');
            removeBtn.className = 'remove-collaborator';
            removeBtn.innerHTML = '<i class="fas fa-times"></i>';
            removeBtn.addEventListener('click', function() {
                removeCollaborator(email);
            });

            item.appendChild(emailSpan);
            item.appendChild(removeBtn);
            list.appendChild(item);
        });
    }

    function removeCollaborator(email) {
        const project = projects.find(p => p.id === currentProjectId);
        if (project) {
            project.collaborators = project.collaborators.filter(c => c !== email);

            // Save to localStorage
            saveProjectsToLocalStorage();

            // Emit update to server
            socket.emit('collaboratorRemoved', {
                projectId: currentProjectId,
                email: email
            });

            // Update UI
            updateCollaboratorsList(project.collaborators);
        }
    }

    function loadTasks(projectId) {
        // Load from localStorage or use empty array
        const savedTasks = localStorage.getItem('taskboardTasks');
        if (savedTasks) {
            tasks = JSON.parse(savedTasks).filter(task => task.projectId === projectId);
        } else {
            tasks = [];
        }
    }

    function saveProjectsToLocalStorage() {
        localStorage.setItem('taskboardProjects', JSON.stringify(projects));
    }

    function saveTasksToLocalStorage() {
        // Save all tasks (not just current project)
        localStorage.setItem('taskboardTasks', JSON.stringify(tasks));
    }

    function setupSocketEvents() {
        // Listen for project updates
        socket.on('projectUpdated', function(data) {
            if (data.projectId === currentProjectId) {
                loadProject(currentProjectId);
            }
        });

        // Listen for task updates
        socket.on('taskUpdated', function(data) {
            if (data.projectId === currentProjectId) {
                // Update local task
                const index = tasks.findIndex(t => t.id === data.task.id);
                if (index !== -1) {
                    tasks[index] = data.task;
                } else {
                    tasks.push(data.task);
                }

                // Refresh board
                loadProject(currentProjectId);
            }
        });

        // Listen for column additions
        socket.on('columnAdded', function(data) {
            if (data.projectId === currentProjectId) {
                const project = projects.find(p => p.id === currentProjectId);
                if (project) {
                    project.columns.push(data.column);
                    renderBoard(project);
                }
            }
        });

        // Listen for collaborator additions
        socket.on('collaboratorAdded', function(data) {
            if (data.projectId === currentProjectId) {
                const project = projects.find(p => p.id === currentProjectId);
                if (project) {
                    if (!project.collaborators.includes(data.email)) {
                        project.collaborators.push(data.email);
                        updateCollaboratorsList(project.collaborators);
                    }
                }
            }
        });

        // Listen for collaborator removals
        socket.on('collaboratorRemoved', function(data) {
            if (data.projectId === currentProjectId) {
                const project = projects.find(p => p.id === currentProjectId);
                if (project) {
                    project.collaborators = project.collaborators.filter(c => c !== data.email);
                    updateCollaboratorsList(project.collaborators);
                }
            }
        });
    }
});
