## Server Implementation (Node.js with Express and Socket.IO)

```javascript
// server.js
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static(path.join(__dirname, 'public')));

// Socket.IO connection
io.on('connection', (socket) => {
    console.log('New client connected');

    // Handle project creation
    socket.on('projectCreated', (project) => {
        // Broadcast to all connected clients except the sender
        socket.broadcast.emit('projectUpdated', {
            projectId: project.id,
            action: 'created'
        });
    });

    // Handle task updates
    socket.on('taskUpdated', (data) => {
        // Broadcast to all connected clients except the sender
        socket.broadcast.emit('taskUpdated', data);
    });

    // Handle column additions
    socket.on('columnAdded', (data) => {
        // Broadcast to all connected clients except the sender
        socket.broadcast.emit('columnAdded', data);
    });

    // Handle collaborator additions
    socket.on('collaboratorAdded', (data) => {
        // Broadcast to all connected clients except the sender
        socket.broadcast.emit('collaboratorAdded', data);
    });

    // Handle collaborator removals
    socket.on('collaboratorRemoved', (data) => {
        // Broadcast to all connected clients except the sender
        socket.broadcast.emit('collaboratorRemoved', data);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
