## 3. JavaScript (app.js)

```javascript
// DOM Elements
const board = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnNameInput = document.getElementById('new-column-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const saveTaskBtn = document.getElementById('save-task-btn');
const deleteTaskBtn = document.getElementById('delete-task-btn');
const connectionStatus = document.getElementById('connection-status');
const userNameDisplay = document.getElementById('user-name');

// State
let currentBoard = {
    columns: []
};
let currentTask = null;
let currentColumnId = null;
let socket = null;
let userId = generateId();

// Initialize the app
function init() {
    // Load saved board from localStorage
    const savedBoard = localStorage.getItem('taskBoard');
    if (savedBoard) {
        currentBoard = JSON.parse(savedBoard);
        renderBoard();
    } else {
        // Create default columns if no saved board
        currentBoard.columns = [
            { id: generateId(), name: 'To Do', tasks: [] },
            { id: generateId(), name: 'In Progress', tasks: [] },
            { id: generateId(), name: 'Done', tasks: [] }
        ];
        saveBoard();
        renderBoard();
    }

    // Set up event listeners
    setupEventListeners();

    // Connect to WebSocket server
    connectToServer();

    // Set random username
    const names = ['Alex', 'Jamie', 'Taylor', 'Morgan', 'Casey', 'Riley', 'Quinn', 'Skyler'];
    userNameDisplay.textContent = names[Math.floor(Math.random() * names.length)];
}

function setupEventListeners() {
    // Add column button
    addColumnBtn.addEventListener('click', addColumn);

    // Modal close button
    closeModal.addEventListener('click', closeTaskModal);

    // Save task button
    saveTaskBtn.addEventListener('click', saveTask);

    // Delete task button
    deleteTaskBtn.addEventListener('click', deleteTask);

    // Click outside modal to close
    window.addEventListener('click', (e) => {
        if (e.target === taskModal) {
            closeTaskModal();
        }
    });

    // Allow pressing Enter to add column
    newColumnNameInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') {
            addColumn();
        }
    });
}

function connectToServer() {
    // In a real app, you would connect to your WebSocket server
    // For this demo, we'll simulate real-time updates with local events
    connectionStatus.textContent = 'Connected';
    connectionStatus.classList.add('connected');

    // Simulate receiving updates from other users
    setInterval(() => {
        // In a real app, this would come from the server
        // For demo purposes, we'll just check for changes periodically
        const savedBoard = localStorage.getItem('taskBoard');
        if (savedBoard) {
            const newBoard = JSON.parse(savedBoard);
            if (JSON.stringify(newBoard) !== JSON.stringify(currentBoard)) {
                currentBoard = newBoard;
                renderBoard();
            }
        }
    }, 2000);
}

// Board rendering functions
function renderBoard() {
    board.innerHTML = '';

    currentBoard.columns.forEach(column => {
        const columnElement = createColumnElement(column);
        board.appendChild(columnElement);
    });

    // Save to localStorage
    saveBoard();
}

function createColumnElement(column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = column.id;

    // Column header
    const header = document.createElement('div');
    header.className = 'column-header';

    const title = document.createElement('h3');
    title.textContent = column.name;

    const actions = document.createElement('div');
    actions.className = 'column-actions';

    const renameBtn = document.createElement('button');
    renameBtn.innerHTML = '<i class="fas fa-edit"></i>';
    renameBtn.title = 'Rename column';
    renameBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        renameColumn(column.id);
    });

    const deleteBtn = document.createElement('button');
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.title = 'Delete column';
    deleteBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        deleteColumn(column.id);
    });

    actions.appendChild(renameBtn);
    actions.appendChild(deleteBtn);
    header.appendChild(title);
    header.appendChild(actions);

    // Column body
    const body = document.createElement('div');
    body.className = 'column-body';

    // Tasks
    column.tasks.forEach(task => {
        const taskElement = createTaskElement(task, column.id);
        body.appendChild(taskElement);
    });

    // Add task button
    const addTaskBtn = document.createElement('div');
    addTaskBtn.className = 'add-task-btn';
    addTaskBtn.innerHTML = '<i class="fas fa-plus"></i> Add Task';
    addTaskBtn.addEventListener('click', () => {
        openTaskModal(null, column.id);
    });

    // Set up drag and drop for column
    setupColumnDragAndDrop(columnElement, body);

    columnElement.appendChild(header);
    columnElement.appendChild(body);
    columnElement.appendChild(addTaskBtn);

    return columnElement;
}

function createTaskElement(task, columnId) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.taskId = task.id;
    taskElement.dataset.columnId = columnId;

    // Task header
    const header = document.createElement('div');
    header.className = 'task-header';

    const title = document.createElement('div');
    title.className = 'task-title';
    title.textContent = task.title;

    const editBtn = document.createElement('button');
    editBtn.innerHTML = '<i class="fas fa-edit"></i>';
    editBtn.title = 'Edit task';
    editBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(task.id, columnId);
    });

    header.appendChild(title);
    header.appendChild(editBtn);

    // Task meta
    const meta = document.createElement('div');
    meta.className = 'task-meta';

    if (task.assignee) {
        const assignee = document.createElement('span');
        assignee.innerHTML = `<i class="fas fa-user"></i> ${task.assignee}`;
        meta.appendChild(assignee);
    }

    if (task.dueDate) {
        const dueDate = document.createElement('span');
        dueDate.innerHTML = `<i class="fas fa-calendar"></i> ${formatDate(task.dueDate)}`;
        meta.appendChild(dueDate);
    }

    // Task description
    const description = document.createElement('div');
    description.className = 'task-description';
    description.textContent = task.description || 'No description';

    // Assemble task element
    taskElement.appendChild(header);
    taskElement.appendChild(meta);
    taskElement.appendChild(description);

    // Set up drag and drop for task
    setupTaskDragAndDrop(taskElement);

    return taskElement;
}

// Drag and drop functions
function setupColumnDragAndDrop(columnElement, body) {
    // Allow dropping tasks into columns
    body.addEventListener('dragover', (e) => {
        e.preventDefault();
        columnElement.classList.add('over');
    });

    body.addEventListener('dragleave', () => {
        columnElement.classList.remove('over');
    });

    body.addEventListener('drop', (e) => {
        e.preventDefault();
        columnElement.classList.remove('over');

        const taskId = e.dataTransfer.getData('text/plain');
        const sourceColumnId = e.dataTransfer.getData('sourceColumnId');
        const targetColumnId = columnElement.dataset.columnId;

        if (sourceColumnId !== targetColumnId) {
            moveTask(taskId, sourceColumnId, targetColumnId);
        }
    });
}

function setupTaskDragAndDrop(taskElement) {
    taskElement.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', taskElement.dataset.taskId);
        e.dataTransfer.setData('sourceColumnId', taskElement.dataset.columnId);
        taskElement.classList.add('dragging');
    });

    taskElement.addEventListener('dragend', () => {
        taskElement.classList.remove('dragging');
    });

    // Click to edit task
    taskElement.addEventListener('click', (e) => {
        if (!e.target.closest('button')) {
            openTaskModal(taskElement.dataset.taskId, taskElement.dataset.columnId);
        }
    });
}

// Task management functions
function openTaskModal(taskId, columnId) {
    currentTask = taskId;
    currentColumnId = columnId;

    if (taskId) {
        // Edit existing task
        const column = currentBoard.columns.find(c => c.id === columnId);
        const task = column.tasks.find(t => t.id === taskId);

        document.getElementById('modal-title').textContent = 'Edit Task';
        document.getElementById('task-title').value = task.title;
        document.getElementById('task-description').value = task.description || '';
        document.getElementById('task-assignee').value = task.assignee || '';
        document.getElementById('task-due-date').value = task.dueDate || '';

        deleteTaskBtn.style.display = 'block';
    } else {
        // Create new task
        document.getElementById('modal-title').textContent = 'Add New Task';
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        document.getElementById('task-assignee').value = '';
        document.getElementById('task-due-date').value = '';

        deleteTaskBtn.style.display = 'none';
    }

    taskModal.classList.add('show');
}

function closeTaskModal() {
    taskModal.classList.remove('show');
    currentTask = null;
    currentColumnId = null;
}

function saveTask() {
    const title = document.getElementById('task-title').value.trim();
    const description = document.getElementById('task-description').value.trim();
    const assignee = document.getElementById('task-assignee').value.trim();
    const dueDate = document.getElementById('task-due-date').value;

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    const column = currentBoard.columns.find(c => c.id === currentColumnId);

    if (currentTask) {
        // Update existing task
        const taskIndex = column.tasks.findIndex(t => t.id === currentTask);
        if (taskIndex !== -1) {
            column.tasks[taskIndex] = {
                ...column.tasks[taskIndex],
                title,
                description,
                assignee,
                dueDate
            };
        }
    } else {
        // Add new task
        const newTask = {
            id: generateId(),
            title,
            description,
            assignee,
            dueDate,
            createdBy: userNameDisplay.textContent,
            createdAt: new Date().toISOString()
        };
        column.tasks.push(newTask);
    }

    saveBoard();
    renderBoard();
    closeTaskModal();
}

function deleteTask() {
    if (!currentTask || !currentColumnId) return;

    const column = currentBoard.columns.find(c => c.id === currentColumnId);
    column.tasks = column.tasks.filter(t => t.id !== currentTask);

    saveBoard();
    renderBoard();
    closeTaskModal();
}

function moveTask(taskId, sourceColumnId, targetColumnId) {
    if (sourceColumnId === targetColumnId) return;

    const sourceColumn = currentBoard.columns.find(c => c.id === sourceColumnId);
    const targetColumn = currentBoard.columns.find(c => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;

    const taskIndex = sourceColumn.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceColumn.tasks.splice(taskIndex, 1);
    targetColumn.tasks.push(task);

    saveBoard();
    renderBoard();
}

// Column management functions
function addColumn() {
    const columnName = newColumnNameInput.value.trim();
    if (!columnName) return;

    currentBoard.columns.push({
        id: generateId(),
        name: columnName,
        tasks: []
    });

    newColumnNameInput.value = '';
    saveBoard();
    renderBoard();
}

function renameColumn(columnId) {
    const column = currentBoard.columns.find(c => c.id === columnId);
    if (!column) return;

    const newName = prompt('Enter new column name:', column.name);
    if (newName && newName.trim()) {
        column.name = newName.trim();
        saveBoard();
        renderBoard();
    }
}

function deleteColumn(columnId) {
    if (currentBoard.columns.length <= 1) {
        alert('You must have at least one column');
        return;
    }

    if (!confirm('Are you sure you want to delete this column and all its tasks?')) {
        return;
    }

    currentBoard.columns = currentBoard.columns.filter(c => c.id !== columnId);
    saveBoard();
    renderBoard();
}

// Helper functions
function saveBoard() {
    localStorage.setItem('taskBoard', JSON.stringify(currentBoard));
}

function generateId() {
    return Math.random().toString(36).substring(2, 9);
}

function formatDate(dateString) {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric'
    });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', init);
```

## 4. Server Setup (server.js)

```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static(path.join(__dirname)));

// Socket.io connection handling
io.on('connection', (socket) => {
    console.log('New client connected');

    // Handle board updates
    socket.on('boardUpdate', (boardData) => {
        // Broadcast to all other clients
        socket.broadcast.emit('boardUpdate', boardData);
    });

    socket.on('disconnect', () => {
        console.log('Client disconnected');
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

