```javascript
// Firebase configuration
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const todoList = document.getElementById('todo-list');
const inProgressList = document.getElementById('in-progress-list');
const doneList = document.getElementById('done-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const taskModal = document.getElementById('task-modal');
const loginModal = document.getElementById('login-modal');
const closeBtns = document.querySelectorAll('.close');
const taskForm = document.getElementById('task-form');
const loginBtn = document.getElementById('login-btn');
const userName = document.getElementById('user-name');

// Initialize FirebaseUI
const ui = new firebaseui.auth.AuthUI(auth);

// Task data
let tasks = [];

// Initialize the app
function initApp() {
    // Set up event listeners
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            openTaskModal(null, btn.dataset.board);
        });
    });

    closeBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            btn.closest('.modal').style.display = 'none';
        });
    });

    taskForm.addEventListener('submit', saveTask);

    loginBtn.addEventListener('click', () => {
        loginModal.style.display = 'block';
    });

    // Set up drag and drop
    setupDragAndDrop();

    // Load tasks from Firestore
    loadTasks();

    // Auth state listener
    auth.onAuthStateChanged(user => {
        if (user) {
            userName.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
            loginBtn.onclick = () => {
                auth.signOut();
                userName.textContent = 'Guest';
                loginBtn.textContent = 'Login';
                loginBtn.onclick = () => loginModal.style.display = 'block';
            };
        } else {
            userName.textContent = 'Guest';
            loginBtn.textContent = 'Login';
            loginBtn.onclick = () => loginModal.style.display = 'block';
        }
    });

    // Initialize FirebaseUI
    ui.start('#firebaseui-auth-container', {
        signInOptions: [
            firebase.auth.EmailAuthProvider.PROVIDER_ID,
            firebase.auth.GoogleAuthProvider.PROVIDER_ID
        ],
        signInSuccessUrl: window.location.href,
        callbacks: {
            signInSuccessWithAuthResult: () => {
                loginModal.style.display = 'none';
                return false;
            }
        }
    });
}

// Load tasks from Firestore
function loadTasks() {
    db.collection('tasks').orderBy('createdAt').onSnapshot(snapshot => {
        tasks = [];
        snapshot.docChanges().forEach(change => {
            if (change.type === 'added' || change.type === 'modified') {
                const task = { id: change.doc.id, ...change.doc.data() };
                tasks.push(task);
            } else if (change.type === 'removed') {
                tasks = tasks.filter(t => t.id !== change.doc.id);
            }
        });
        renderTasks();
    });
}

// Render tasks to the boards
function renderTasks() {
    // Clear all boards
    todoList.innerHTML = '';
    inProgressList.innerHTML = '';
    doneList.innerHTML = '';

    // Add tasks to their respective boards
    tasks.forEach(task => {
        const taskElement = createTaskElement(task);
        if (task.board === 'todo') {
            todoList.appendChild(taskElement);
        } else if (task.board === 'in-progress') {
            inProgressList.appendChild(taskElement);
        } else if (task.board === 'done') {
            doneList.appendChild(taskElement);
        }
    });
}

// Create a task element
function createTaskElement(task) {
    const taskCard = document.createElement('div');
    taskCard.className = 'task-card';
    taskCard.draggable = true;
    taskCard.dataset.id = task.id;
    taskCard.dataset.board = task.board;

    taskCard.innerHTML = `
        <div class="task-card-header">
            <div class="task-title">${task.title}</div>
            <div class="task-actions">
                <button class="edit-btn" data-id="${task.id}"><i class="fas fa-edit"></i></button>
                <button class="delete-btn" data-id="${task.id}"><i class="fas fa-trash"></i></button>
            </div>
        </div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span>${task.assignee || 'Unassigned'}</span>
            <span>${task.dueDate ? new Date(task.dueDate).toLocaleDateString() : ''}</span>
        </div>
    `;

    // Set up drag events
    taskCard.addEventListener('dragstart', dragStart);
    taskCard.addEventListener('dragend', dragEnd);

    // Set up edit and delete buttons
    taskCard.querySelector('.edit-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(task.id, task.board);
    });

    taskCard.querySelector('.delete-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteTask(task.id);
    });

    return taskCard;
}

// Open the task modal
function openTaskModal(taskId, board) {
    const modalTitle = document.getElementById('modal-title');
    const taskIdInput = document.getElementById('task-id');
    const taskBoardInput = document.getElementById('task-board');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const taskAssigneeInput = document.getElementById('task-assignee');
    const taskDueDateInput = document.getElementById('task-due-date');

    if (taskId) {
        // Edit existing task
        modalTitle.textContent = 'Edit Task';
        const task = tasks.find(t => t.id === taskId);
        taskIdInput.value = task.id;
        taskBoardInput.value = task.board;
        taskTitleInput.value = task.title;
        taskDescriptionInput.value = task.description || '';
        taskAssigneeInput.value = task.assignee || '';
        taskDueDateInput.value = task.dueDate || '';
    } else {
        // Add new task
        modalTitle.textContent = 'Add Task';
        taskIdInput.value = '';
        taskBoardInput.value = board;
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskAssigneeInput.value = '';
        taskDueDateInput.value = '';
    }

    taskModal.style.display = 'block';
}

// Save a task
function saveTask(e) {
    e.preventDefault();

    const taskId = document.getElementById('task-id').value;
    const board = document.getElementById('task-board').value;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const assignee = document.getElementById('task-assignee').value;
    const dueDate = document.getElementById('task-due-date').value;

    const taskData = {
        title,
        description,
        assignee,
        dueDate,
        board,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (taskId) {
        // Update existing task
        db.collection('tasks').doc(taskId).update(taskData);
    } else {
        // Add new task
        db.collection('tasks').add(taskData);
    }

    taskModal.style.display = 'none';
    taskForm.reset();
}

// Delete a task
function deleteTask(taskId) {
    if (confirm('Are you sure you want to delete this task?')) {
        db.collection('tasks').doc(taskId).delete();
    }
}

// Drag and drop functionality
function setupDragAndDrop() {
    const boards = document.querySelectorAll('.board');

    boards.forEach(board => {
        const taskList = board.querySelector('.task-list');

        taskList.addEventListener('dragover', dragOver);
        taskList.addEventListener('dragenter', dragEnter);
        taskList.addEventListener('dragleave', dragLeave);
        taskList.addEventListener('drop', drop);
    });
}

function dragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.dataset.id);
    e.target.classList.add('dragging');
    setTimeout(() => {
        e.target.style.display = 'none';
    }, 0);
}

function dragEnd(e) {
    e.target.classList.remove('dragging');
    e.target.style.display = 'block';
}

function dragOver(e) {
    e.preventDefault();
}

function dragEnter(e) {
    e.preventDefault();
    e.target.classList.add('drag-over');
}

function dragLeave(e) {
    e.target.classList.remove('drag-over');
}

function drop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    const taskId = e.dataTransfer.getData('text/plain');
    const newBoard = e.target.closest('.board').id;

    // Update the task in Firestore
    db.collection('tasks').doc(taskId).update({
        board: newBoard
    });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
```

