// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();
const auth = firebase.auth();

// DOM elements
const todoList = document.getElementById('todo-list');
const inProgressList = document.getElementById('in-progress-list');
const doneList = document.getElementById('done-list');
const taskModal = document.getElementById('task-modal');
const modalTitle = document.getElementById('modal-title');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const saveTaskBtn = document.getElementById('save-task');
const deleteTaskBtn = document.getElementById('delete-task');
const loginBtn = document.getElementById('login-btn');
const userNameSpan = document.getElementById('user-name');

// State variables
let currentTaskId = null;
let currentBoard = null;
let currentUser = null;

// Initialize the app
function initApp() {
    // Set up drag and drop
    setupDragAndDrop();

    // Set up authentication listener
    auth.onAuthStateChanged(user => {
        if (user) {
            currentUser = user;
            userNameSpan.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
            loginBtn.onclick = logout;
        } else {
            currentUser = null;
            userNameSpan.textContent = 'Guest';
            loginBtn.textContent = 'Login';
            loginBtn.onclick = login;
        }
    });

    // Load tasks from Firebase
    loadTasks();
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const taskLists = document.querySelectorAll('.task-list');

    taskLists.forEach(list => {
        list.addEventListener('dragover', e => {
            e.preventDefault();
            const afterElement = getDragAfterElement(list, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement == null) {
                list.appendChild(draggable);
            } else {
                list.insertBefore(draggable, afterElement);
            }
        });

        list.addEventListener('drop', e => {
            e.preventDefault();
            const taskId = e.dataTransfer.getData('text/plain');
            const newBoard = list.parentElement.id;

            // Update task status in Firebase
            const taskRef = database.ref(`tasks/${taskId}`);
            taskRef.update({ status: newBoard });
        });
    });
}

function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Load tasks from Firebase
function loadTasks() {
    const tasksRef = database.ref('tasks');

    tasksRef.on('value', snapshot => {
        const tasks = snapshot.val();

        // Clear all task lists
        todoList.innerHTML = '';
        inProgressList.innerHTML = '';
        doneList.innerHTML = '';

        // Add tasks to appropriate lists
        for (const taskId in tasks) {
            const task = tasks[taskId];
            const taskElement = createTaskElement(taskId, task.title, task.description);

            if (task.status === 'todo') {
                todoList.appendChild(taskElement);
            } else if (task.status === 'in-progress') {
                inProgressList.appendChild(taskElement);
            } else if (task.status === 'done') {
                doneList.appendChild(taskElement);
            }
        }
    });
}

// Create a task element
function createTaskElement(id, title, description) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.id = id;

    taskElement.innerHTML = `
        <h3>${title}</h3>
        <p>${description}</p>
    `;

    taskElement.addEventListener('dragstart', e => {
        e.dataTransfer.setData('text/plain', id);
        taskElement.classList.add('dragging');
    });

    taskElement.addEventListener('dragend', () => {
        taskElement.classList.remove('dragging');
    });

    taskElement.addEventListener('click', () => {
        openTaskModal(id, title, description);
    });

    return taskElement;
}

// Add a new task
function addTask(board) {
    currentBoard = board;
    currentTaskId = null;
    modalTitle.textContent = 'Add Task';
    taskTitleInput.value = '';
    taskDescriptionInput.value = '';
    deleteTaskBtn.style.display = 'none';
    taskModal.style.display = 'block';
}

// Open task modal for editing
function openTaskModal(id, title, description) {
    currentTaskId = id;
    currentBoard = null;
    modalTitle.textContent = 'Edit Task';
    taskTitleInput.value = title;
    taskDescriptionInput.value = description;
    deleteTaskBtn.style.display = 'block';
    taskModal.style.display = 'block';
}

// Close the task modal
function closeModal() {
    taskModal.style.display = 'none';
}

// Save task to Firebase
function saveTask() {
    const title = taskTitleInput.value.trim();
    const description = taskDescriptionInput.value.trim();

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (currentTaskId) {
        // Update existing task
        const taskRef = database.ref(`tasks/${currentTaskId}`);
        taskRef.update({
            title,
            description,
            updatedAt: firebase.database.ServerValue.TIMESTAMP
        });
    } else {
        // Add new task
        const newTaskRef = database.ref('tasks').push();
        newTaskRef.set({
            title,
            description,
            status: currentBoard,
            createdAt: firebase.database.ServerValue.TIMESTAMP,
            updatedAt: firebase.database.ServerValue.TIMESTAMP,
            createdBy: currentUser ? currentUser.uid : 'anonymous'
        });
    }

    closeModal();
}

// Delete task from Firebase
function deleteTask() {
    if (currentTaskId) {
        if (confirm('Are you sure you want to delete this task?')) {
            const taskRef = database.ref(`tasks/${currentTaskId}`);
            taskRef.remove();
            closeModal();
        }
    }
}

// Authentication functions
function login() {
    // Simple email/password login for demo purposes
    const email = prompt('Enter your email:');
    const password = prompt('Enter your password:');

    if (email && password) {
        auth.signInWithEmailAndPassword(email, password)
            .catch(error => {
                alert(error.message);
            });
    }
}

function logout() {
    auth.signOut();
}

// Event listeners
saveTaskBtn.addEventListener('click', saveTask);
deleteTaskBtn.addEventListener('click', deleteTask);

// Initialize the app when the page loads
window.addEventListener('DOMContentLoaded', initApp);
