## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const taskLists = document.querySelectorAll('.task-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskForm = document.getElementById('task-form');
const modalTitle = document.getElementById('modal-title');
const taskIdInput = document.getElementById('task-id');
const taskStatusInput = document.getElementById('task-status');
const taskTitleInput = document.getElementById('task-title');
const taskDescriptionInput = document.getElementById('task-description');
const taskPriorityInput = document.getElementById('task-priority');
const taskAssigneeInput = document.getElementById('task-assignee');
const userStatus = document.getElementById('user-status');

// Initialize the app
function initApp() {
    // Set up drag and drop
    setupDragAndDrop();

    // Set up event listeners
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            openTaskModal(null, btn.dataset.status);
        });
    });

    closeModal.addEventListener('click', closeTaskModal);
    taskForm.addEventListener('submit', handleTaskSubmit);

    // Listen for real-time updates from Firebase
    database.ref('tasks').on('value', (snapshot) => {
        const tasks = snapshot.val();
        updateTaskBoards(tasks);
    });

    // Check connection status
    database.ref('.info/connected').on('value', (snapshot) => {
        if (snapshot.val() === true) {
            userStatus.textContent = 'Connected';
            userStatus.style.color = 'green';
        } else {
            userStatus.textContent = 'Disconnected';
            userStatus.style.color = 'red';
        }
    });
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    taskLists.forEach(list => {
        list.addEventListener('dragover', (e) => {
            e.preventDefault();
            const afterElement = getDragAfterElement(list, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement == null) {
                list.appendChild(draggable);
            } else {
                list.insertBefore(draggable, afterElement);
            }
        });
    });

    document.querySelectorAll('.task-card').forEach(card => {
        card.addEventListener('dragstart', () => {
            card.classList.add('dragging');
        });

        card.addEventListener('dragend', () => {
            card.classList.remove('dragging');
            const newStatus = card.closest('.task-list').dataset.status;
            const taskId = card.dataset.id;

            // Update task status in Firebase
            database.ref(`tasks/${taskId}`).update({
                status: newStatus
            });
        });
    });
}

// Helper function for drag and drop positioning
function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task-card:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Open the task modal
function openTaskModal(taskId, status) {
    if (taskId) {
        // Edit existing task
        modalTitle.textContent = 'Edit Task';
        taskIdInput.value = taskId;

        // Get task data from Firebase
        database.ref(`tasks/${taskId}`).once('value').then((snapshot) => {
            const task = snapshot.val();
            taskStatusInput.value = task.status;
            taskTitleInput.value = task.title;
            taskDescriptionInput.value = task.description || '';
            taskPriorityInput.value = task.priority || 'medium';
            taskAssigneeInput.value = task.assignee || '';
        });
    } else {
        // Add new task
        modalTitle.textContent = 'Add New Task';
        taskIdInput.value = '';
        taskStatusInput.value = status;
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskPriorityInput.value = 'medium';
        taskAssigneeInput.value = '';
    }

    taskModal.style.display = 'flex';
}

// Close the task modal
function closeTaskModal() {
    taskModal.style.display = 'none';
}

// Handle task form submission
function handleTaskSubmit(e) {
    e.preventDefault();

    const taskId = taskIdInput.value;
    const taskData = {
        title: taskTitleInput.value,
        description: taskDescriptionInput.value,
        priority: taskPriorityInput.value,
        assignee: taskAssigneeInput.value,
        status: taskStatusInput.value,
        createdAt: firebase.database.ServerValue.TIMESTAMP
    };

    if (taskId) {
        // Update existing task
        database.ref(`tasks/${taskId}`).update(taskData);
    } else {
        // Create new task
        database.ref('tasks').push(taskData);
    }

    closeTaskModal();
}

// Update the task boards with data from Firebase
function updateTaskBoards(tasks) {
    // Clear all task lists
    taskLists.forEach(list => {
        list.innerHTML = '';
    });

    // Update task counts
    const counts = {
        todo: 0,
        'in-progress': 0,
        done: 0
    };

    // Add tasks to the appropriate lists
    if (tasks) {
        Object.entries(tasks).forEach(([id, task]) => {
            const taskElement = createTaskElement(id, task);
            const taskList = document.querySelector(`.task-list[data-status="${task.status}"]`);

            if (taskList) {
                taskList.appendChild(taskElement);
                counts[task.status]++;
            }
        });
    }

    // Update task counts in headers
    document.querySelector('#todo .task-count').textContent = counts.todo;
    document.querySelector('#in-progress .task-count').textContent = counts['in-progress'];
    document.querySelector('#done .task-count').textContent = counts.done;

    // Re-setup drag and drop for new elements
    setupDragAndDrop();
}

// Create a task card element
function createTaskElement(id, task) {
    const taskCard = document.createElement('div');
    taskCard.className = `task-card priority-${task.priority || 'medium'}`;
    taskCard.draggable = true;
    taskCard.dataset.id = id;

    taskCard.innerHTML = `
        <div class="task-title">${task.title}</div>
        ${task.description ? `<div class="task-description">${task.description}</div>` : ''}
        <div class="task-meta">
            <span>${task.assignee || 'Unassigned'}</span>
            <span>${task.priority ? task.priority.charAt(0).toUpperCase() + task.priority.slice(1) : 'Medium'}</span>
        </div>
    `;

    // Add click event to edit task
    taskCard.addEventListener('click', (e) => {
        if (!e.target.closest('.task-meta')) {
            openTaskModal(id, task.status);
        }
    });

    return taskCard;
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
