## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const boardContainer = document.getElementById('board-container');
const addColumnBtn = document.getElementById('add-column-btn');
const loginBtn = document.getElementById('login-btn');
const userNameElement = document.getElementById('user-name');

// Current user
let currentUser = null;

// Initialize the app
function initApp() {
    // Check authentication state
    firebase.auth().onAuthStateChanged((user) => {
        if (user) {
            currentUser = user;
            userNameElement.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
        } else {
            currentUser = null;
            userNameElement.textContent = 'Guest';
            loginBtn.textContent = 'Login';
        }
    });

    // Load board data
    loadBoardData();

    // Set up event listeners
    addColumnBtn.addEventListener('click', showAddColumnModal);
    loginBtn.addEventListener('click', toggleLogin);
}

// Load board data from Firebase
function loadBoardData() {
    const boardRef = database.ref('boards/default');

    boardRef.on('value', (snapshot) => {
        const boardData = snapshot.val() || {};
        renderBoard(boardData);
    });
}

// Render the entire board
function renderBoard(boardData) {
    boardContainer.innerHTML = '';

    // Sort columns by order
    const columns = Object.entries(boardData.columns || {}).sort((a, b) => a[1].order - b[1].order);

    columns.forEach(([columnId, columnData]) => {
        const columnElement = createColumnElement(columnId, columnData);
        boardContainer.appendChild(columnElement);
    });

    // Make tasks draggable
    setupDragAndDrop();
}

// Create a column element
function createColumnElement(columnId, columnData) {
    const column = document.createElement('div');
    column.className = 'column';
    column.dataset.columnId = columnId;

    const columnHeader = document.createElement('div');
    columnHeader.className = 'column-header';

    const columnTitle = document.createElement('div');
    columnTitle.className = 'column-title';
    columnTitle.textContent = columnData.title;

    const columnActions = document.createElement('div');
    columnActions.className = 'column-actions';

    const editBtn = document.createElement('button');
    editBtn.innerHTML = '<i class="fas fa-pencil-alt"></i>';
    editBtn.addEventListener('click', () => showEditColumnModal(columnId, columnData.title));

    const deleteBtn = document.createElement('button');
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', () => deleteColumn(columnId));

    columnActions.appendChild(editBtn);
    columnActions.appendChild(deleteBtn);
    columnHeader.appendChild(columnTitle);
    columnHeader.appendChild(columnActions);

    const taskList = document.createElement('div');
    taskList.className = 'task-list';
    taskList.dataset.columnId = columnId;

    // Sort tasks by order
    const tasks = Object.entries(columnData.tasks || {}).sort((a, b) => a[1].order - b[1].order);

    tasks.forEach(([taskId, taskData]) => {
        const taskElement = createTaskElement(taskId, taskData);
        taskList.appendChild(taskElement);
    });

    const addTaskBtn = document.createElement('div');
    addTaskBtn.className = 'add-task-btn';
    addTaskBtn.innerHTML = '<i class="fas fa-plus"></i> Add Task';
    addTaskBtn.addEventListener('click', () => showAddTaskModal(columnId));

    column.appendChild(columnHeader);
    column.appendChild(taskList);
    column.appendChild(addTaskBtn);

    return column;
}

// Create a task element
function createTaskElement(taskId, taskData) {
    const task = document.createElement('div');
    task.className = 'task';
    task.draggable = true;
    task.dataset.taskId = taskId;

    const taskTitle = document.createElement('div');
    taskTitle.className = 'task-title';
    taskTitle.textContent = taskData.title;

    const taskMeta = document.createElement('div');
    taskMeta.className = 'task-meta';

    const taskAssignee = document.createElement('span');
    taskAssignee.textContent = taskData.assignee || 'Unassigned';

    const taskDueDate = document.createElement('span');
    taskDueDate.textContent = taskData.dueDate || '';

    taskMeta.appendChild(taskAssignee);
    taskMeta.appendChild(taskDueDate);

    task.appendChild(taskTitle);
    task.appendChild(taskMeta);

    return task;
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    const taskLists = document.querySelectorAll('.task-list');
    const tasks = document.querySelectorAll('.task');

    tasks.forEach(task => {
        task.addEventListener('dragstart', handleDragStart);
        task.addEventListener('dragend', handleDragEnd);
    });

    taskLists.forEach(list => {
        list.addEventListener('dragover', handleDragOver);
        list.addEventListener('dragenter', handleDragEnter);
        list.addEventListener('dragleave', handleDragLeave);
        list.addEventListener('drop', handleDrop);
    });
}

// Drag and drop event handlers
function handleDragStart(e) {
    e.dataTransfer.setData('text/plain', e.target.dataset.taskId);
    e.target.classList.add('dragging');
    setTimeout(() => {
        e.target.style.display = 'none';
    }, 0);
}

function handleDragEnd(e) {
    e.target.classList.remove('dragging');
    e.target.style.display = 'block';
}

function handleDragOver(e) {
    e.preventDefault();
}

function handleDragEnter(e) {
    e.preventDefault();
    if (e.target.classList.contains('task-list')) {
        e.target.classList.add('drag-over');
    }
}

function handleDragLeave(e) {
    if (e.target.classList.contains('task-list')) {
        e.target.classList.remove('drag-over');
    }
}

function handleDrop(e) {
    e.preventDefault();
    e.target.classList.remove('drag-over');

    const taskId = e.dataTransfer.getData('text/plain');
    const newColumnId = e.target.dataset.columnId;

    if (newColumnId) {
        moveTask(taskId, newColumnId);
    }
}

// Move a task to a new column
function moveTask(taskId, newColumnId) {
    const boardRef = database.ref('boards/default');

    boardRef.transaction((boardData) => {
        if (!boardData) return boardData;

        // Find the old column and task
        let oldColumnId = null;
        let taskData = null;

        for (const columnId in boardData.columns) {
            if (boardData.columns[columnId].tasks && boardData.columns[columnId].tasks[taskId]) {
                oldColumnId = columnId;
                taskData = boardData.columns[columnId].tasks[taskId];
                delete boardData.columns[columnId].tasks[taskId];
                break;
            }
        }

        if (oldColumnId && taskData) {
            // Add to new column
            if (!boardData.columns[newColumnId].tasks) {
                boardData.columns[newColumnId].tasks = {};
            }

            // Find the highest order in the new column
            let maxOrder = 0;
            for (const taskId in boardData.columns[newColumnId].tasks) {
                if (boardData.columns[newColumnId].tasks[taskId].order > maxOrder) {
                    maxOrder = boardData.columns[newColumnId].tasks[taskId].order;
                }
            }

            taskData.order = maxOrder + 1;
            boardData.columns[newColumnId].tasks[taskId] = taskData;
        }

        return boardData;
    });
}

// Add a new column
function addColumn(title) {
    const boardRef = database.ref('boards/default/columns');

    // Find the highest order
    boardRef.once('value').then((snapshot) => {
        const columns = snapshot.val() || {};
        let maxOrder = 0;

        for (const columnId in columns) {
            if (columns[columnId].order > maxOrder) {
                maxOrder = columns[columnId].order;
            }
        }

        const newColumnRef = boardRef.push();
        newColumnRef.set({
            title: title,
            order: maxOrder + 1,
            tasks: {}
        });
    });
}

// Edit a column
function editColumn(columnId, newTitle) {
    const columnRef = database.ref(`boards/default/columns/${columnId}`);
    columnRef.update({ title: newTitle });
}

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column?')) {
        const columnRef = database.ref(`boards/default/columns/${columnId}`);
        columnRef.remove();
    }
}

// Add a new task
function addTask(columnId, title, description, assignee, dueDate) {
    const tasksRef = database.ref(`boards/default/columns/${columnId}/tasks`);

    // Find the highest order
    tasksRef.once('value').then((snapshot) => {
        const tasks = snapshot.val() || {};
        let maxOrder = 0;

        for (const taskId in tasks) {
            if (tasks[taskId].order > maxOrder) {
                maxOrder = tasks[taskId].order;
            }
        }

        const newTaskRef = tasksRef.push();
        newTaskRef.set({
            title: title,
            description: description,
            assignee: assignee,
            dueDate: dueDate,
            order: maxOrder + 1,
            createdBy: currentUser ? currentUser.uid : 'anonymous',
            createdAt: firebase.database.ServerValue.TIMESTAMP
        });
    });
}

// Modal functions
function showAddColumnModal() {
    const modal = createModal('Add New Column', `
        <div class="form-group">
            <label for="column-title">Column Title</label>
            <input type="text" id="column-title" placeholder="Enter column title">
        </div>
    `, () => {
        const title = document.getElementById('column-title').value.trim();
        if (title) {
            addColumn(title);
            closeModal(modal);
        }
    });

    document.body.appendChild(modal);
}

function showEditColumnModal(columnId, currentTitle) {
    const modal = createModal('Edit Column', `
        <div class="form-group">
            <label for="column-title">Column Title</label>
            <input type="text" id="column-title" value="${currentTitle}" placeholder="Enter column title">
        </div>
    `, () => {
        const title = document.getElementById('column-title').value.trim();
        if (title) {
            editColumn(columnId, title);
            closeModal(modal);
        }
    });

    document.body.appendChild(modal);
}

function showAddTaskModal(columnId) {
    const modal = createModal('Add New Task', `
        <div class="form-group">
            <label for="task-title">Task Title</label>
            <input type="text" id="task-title" placeholder="Enter task title">
        </div>
        <div class="form-group">
            <label for="task-description">Description</label>
            <textarea id="task-description" placeholder="Enter task description"></textarea>
        </div>
        <div class="form-group">
            <label for="task-assignee">Assignee</label>
            <input type="text" id="task-assignee" placeholder="Enter assignee name">
        </div>
        <div class="form-group">
            <label for="task-due-date">Due Date</label>
            <input type="date" id="task-due-date">
        </div>
    `, () => {
        const title = document.getElementById('task-title').value.trim();
        const description = document.getElementById('task-description').value.trim();
        const assignee = document.getElementById('task-assignee').value.trim();
        const dueDate = document.getElementById('task-due-date').value;

        if (title) {
            addTask(columnId, title, description, assignee, dueDate);
            closeModal(modal);
        }
    });

    document.body.appendChild(modal);
}

function createModal(title, content, onSubmit) {
    const modal = document.createElement('div');
    modal.className = 'modal';

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const modalHeader = document.createElement('div');
    modalHeader.className = 'modal-header';

    const modalTitle = document.createElement('h2');
    modalTitle.textContent = title;

    const closeBtn = document.createElement('button');
    closeBtn.className = 'modal-close';
    closeBtn.innerHTML = '&times;';
    closeBtn.addEventListener('click', () => closeModal(modal));

    modalHeader.appendChild(modalTitle);
    modalHeader.appendChild(closeBtn);

    const modalBody = document.createElement('div');
    modalBody.innerHTML = content;

    const modalFooter = document.createElement('div');
    modalFooter.className = 'modal-footer';

    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'secondary';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.addEventListener('click', () => closeModal(modal));

    const submitBtn = document.createElement('button');
    submitBtn.className = 'primary';
    submitBtn.textContent = 'Save';
    submitBtn.addEventListener('click', onSubmit);

    modalFooter.appendChild(cancelBtn);
    modalFooter.appendChild(submitBtn);

    modalContent.appendChild(modalHeader);
    modalContent.appendChild(modalBody);
    modalContent.appendChild(modalFooter);
    modal.appendChild(modalContent);

    return modal;
}

function closeModal(modal) {
    document.body.removeChild(modal);
}

// Login/Logout functionality
function toggleLogin() {
    if (currentUser) {
        firebase.auth().signOut();
    } else {
        // Simple email/password login for demo purposes
        const email = prompt('Enter your email:');
        const password = prompt('Enter your password:');

        if (email && password) {
            firebase.auth().signInWithEmailAndPassword(email, password)
                .catch((error) => {
                    alert(error.message);
                });
        }
    }
}

// Initialize the app when the page loads
window.addEventListener('DOMContentLoaded', initApp);
```

## Setup Instructions

1. **Firebase Setup**:
   - Create a Firebase project at [Firebase Console](https://console.firebase.google.com/)
   - Enable Realtime Database
   - Get your Firebase configuration and replace the placeholder values in the JavaScript file

2. **Run the Application**:
   - Simply open the HTML file in a browser to run the application
   - For a production environment, you would need to host it on a web server

## Features

1. **Drag-and-Drop Tasks**: Tasks can be dragged between columns
2. **Real-time Collaboration**: Changes are synchronized across all clients using Firebase
3. **Basic Authentication**: Simple login/logout functionality
4. **Column Management**: Add, edit, and delete columns
5. **Task Management**: Add tasks with titles, descriptions, assignees, and due dates
6. **Responsive Design**: Works on mobile and desktop devices

## Limitations

1. This is a minimal implementation with basic functionality
2. Authentication is simplified (email/password only)
3. No user management or permissions system
4. No task details view or comments
5. No proper error handling for production use

You can extend this basic version with additional features like task details, user management, notifications, and more advanced UI components as needed.

# Minimal Browser-Based Project Management App

Here's a minimal working version of a project management application with drag-and-drop task boards and real-time collaboration. This implementation uses HTML, CSS, and JavaScript with Firebase for real-time synchronization.

