## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own config)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const db = firebase.firestore();
const auth = firebase.auth();

// DOM elements
const taskLists = document.querySelectorAll('.task-list');
const addTaskBtns = document.querySelectorAll('.add-task-btn');
const taskModal = document.getElementById('task-modal');
const loginModal = document.getElementById('login-modal');
const closeBtns = document.querySelectorAll('.close');
const taskForm = document.getElementById('task-form');
const loginBtn = document.getElementById('login-btn');
const userName = document.getElementById('user-name');

// Modal state
let currentModal = null;

// Initialize Firebase UI
const ui = new firebaseui.auth.AuthUI(auth);

// Task data
let tasks = [];

// Initialize the app
function initApp() {
    // Set up drag and drop
    setupDragAndDrop();

    // Set up event listeners
    setupEventListeners();

    // Load tasks from Firestore
    loadTasks();

    // Set up auth state listener
    auth.onAuthStateChanged(user => {
        if (user) {
            userName.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
        } else {
            userName.textContent = 'Guest';
            loginBtn.textContent = 'Login';
        }
    });
}

// Set up drag and drop functionality
function setupDragAndDrop() {
    taskLists.forEach(list => {
        list.addEventListener('dragover', e => {
            e.preventDefault();
            const afterElement = getDragAfterElement(list, e.clientY);
            const draggable = document.querySelector('.dragging');

            if (afterElement == null) {
                list.appendChild(draggable);
            } else {
                list.insertBefore(draggable, afterElement);
            }
        });
    });

    document.querySelectorAll('.task').forEach(task => {
        task.addEventListener('dragstart', () => {
            task.classList.add('dragging');
        });

        task.addEventListener('dragend', () => {
            task.classList.remove('dragging');
            const newStatus = task.closest('.board').id;
            const taskId = task.dataset.id;

            // Update task status in Firestore
            if (auth.currentUser) {
                db.collection('tasks').doc(taskId).update({
                    status: newStatus,
                    updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                }).catch(error => {
                    console.error("Error updating task status: ", error);
                });
            } else {
                // For guest users, update locally
                const taskIndex = tasks.findIndex(t => t.id === taskId);
                if (taskIndex !== -1) {
                    tasks[taskIndex].status = newStatus;
                    updateTaskCounts();
                }
            }
        });
    });
}

function getDragAfterElement(container, y) {
    const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

    return draggableElements.reduce((closest, child) => {
        const box = child.getBoundingClientRect();
        const offset = y - box.top - box.height / 2;

        if (offset < 0 && offset > closest.offset) {
            return { offset: offset, element: child };
        } else {
            return closest;
        }
    }, { offset: Number.NEGATIVE_INFINITY }).element;
}

// Set up event listeners
function setupEventListeners() {
    // Add task buttons
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            openTaskModal(null, btn.dataset.status);
        });
    });

    // Close buttons
    closeBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            if (currentModal) {
                currentModal.style.display = 'none';
                currentModal = null;
            }
        });
    });

    // Task form submission
    taskForm.addEventListener('submit', e => {
        e.preventDefault();
        saveTask();
    });

    // Login button
    loginBtn.addEventListener('click', () => {
        if (auth.currentUser) {
            auth.signOut();
        } else {
            openLoginModal();
        }
    });

    // Click outside modal to close
    window.addEventListener('click', e => {
        if (currentModal && e.target === currentModal) {
            currentModal.style.display = 'none';
            currentModal = null;
        }
    });
}

// Open task modal
function openTaskModal(taskId, status) {
    const modalTitle = document.getElementById('modal-title');
    const taskTitle = document.getElementById('task-title');
    const taskDescription = document.getElementById('task-description');
    const taskAssignee = document.getElementById('task-assignee');
    const taskDueDate = document.getElementById('task-due-date');
    const taskIdInput = document.getElementById('task-id');
    const taskStatusInput = document.getElementById('task-status');

    if (taskId) {
        // Edit existing task
        modalTitle.textContent = 'Edit Task';
        const task = tasks.find(t => t.id === taskId);
        if (task) {
            taskTitle.value = task.title;
            taskDescription.value = task.description || '';
            taskAssignee.value = task.assignee || '';
            taskDueDate.value = task.dueDate || '';
            taskIdInput.value = task.id;
            taskStatusInput.value = task.status;
        }
    } else {
        // Add new task
        modalTitle.textContent = 'Add New Task';
        taskTitle.value = '';
        taskDescription.value = '';
        taskAssignee.value = '';
        taskDueDate.value = '';
        taskIdInput.value = '';
        taskStatusInput.value = status;
    }

    taskModal.style.display = 'block';
    currentModal = taskModal;
}

// Save task to Firestore or local storage
function saveTask() {
    const taskId = document.getElementById('task-id').value;
    const status = document.getElementById('task-status').value;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const assignee = document.getElementById('task-assignee').value;
    const dueDate = document.getElementById('task-due-date').value;

    if (auth.currentUser) {
        // Save to Firestore
        const taskData = {
            title,
            description,
            assignee,
            dueDate,
            status,
            createdBy: auth.currentUser.uid,
            createdAt: firebase.firestore.FieldValue.serverTimestamp(),
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };

        if (taskId) {
            // Update existing task
            db.collection('tasks').doc(taskId).update(taskData)
                .then(() => {
                    taskModal.style.display = 'none';
                    currentModal = null;
                })
                .catch(error => {
                    console.error("Error updating task: ", error);
                });
        } else {
            // Add new task
            db.collection('tasks').add(taskData)
                .then(() => {
                    taskModal.style.display = 'none';
                    currentModal = null;
                })
                .catch(error => {
                    console.error("Error adding task: ", error);
                });
        }
    } else {
        // Save locally for guest users
        const task = {
            id: taskId || Date.now().toString(),
            title,
            description,
            assignee,
            dueDate,
            status,
            createdAt: new Date().toISOString()
        };

        if (taskId) {
            // Update existing task
            const index = tasks.findIndex(t => t.id === taskId);
            if (index !== -1) {
                tasks[index] = task;
            }
        } else {
            // Add new task
            tasks.push(task);
        }

        renderTasks();
        taskModal.style.display = 'none';
        currentModal = null;
    }
}

// Delete task
function deleteTask(taskId) {
    if (auth.currentUser) {
        // Delete from Firestore
        db.collection('tasks').doc(taskId).delete()
            .catch(error => {
                console.error("Error deleting task: ", error);
            });
    } else {
        // Delete locally
        tasks = tasks.filter(task => task.id !== taskId);
        renderTasks();
    }
}

// Load tasks from Firestore or local storage
function loadTasks() {
    if (auth.currentUser) {
        // Load from Firestore
        db.collection('tasks')
            .where('createdBy', '==', auth.currentUser.uid)
            .orderBy('createdAt', 'desc')
            .onSnapshot(snapshot => {
                tasks = [];
                snapshot.forEach(doc => {
                    tasks.push({ id: doc.id, ...doc.data() });
                });
                renderTasks();
            });
    } else {
        // Load from local storage
        const savedTasks = localStorage.getItem('tasks');
        if (savedTasks) {
            tasks = JSON.parse(savedTasks);
            renderTasks();
        }
    }
}

// Render tasks to the board
function renderTasks() {
    // Clear all task lists
    taskLists.forEach(list => {
        list.innerHTML = '';
    });

    // Add tasks to appropriate lists
    tasks.forEach(task => {
        const taskElement = createTaskElement(task);
        const taskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
        if (taskList) {
            taskList.appendChild(taskElement);
        }
    });

    // Update task counts
    updateTaskCounts();

    // Save to local storage for guest users
    if (!auth.currentUser) {
        localStorage.setItem('tasks', JSON.stringify(tasks));
    }

    // Re-setup drag and drop
    setupDragAndDrop();
}

// Create task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.dataset.id = task.id;

    taskElement.innerHTML = `
        <h3>${task.title}</h3>
        <p class="description">${task.description || ''}</p>
        <div class="meta">
            <span class="assignee">${task.assignee || 'Unassigned'}</span>
            <span class="due-date">${task.dueDate ? new Date(task.dueDate).toLocaleDateString() : 'No due date'}</span>
        </div>
        <div class="task-actions">
            <button class="edit-btn" title="Edit">
                <i class="fas fa-edit"></i> Edit
            </button>
            <button class="delete-btn" title="Delete">
                <i class="fas fa-trash"></i> Delete
            </button>
        </div>
    `;

    // Set up event listeners for task actions
    const editBtn = taskElement.querySelector('.edit-btn');
    const deleteBtn = taskElement.querySelector('.delete-btn');

    editBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openTaskModal(task.id, task.status);
    });

    deleteBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        if (confirm('Are you sure you want to delete this task?')) {
            deleteTask(task.id);
        }
    });

    return taskElement;
}

// Update task counts in board headers
function updateTaskCounts() {
    const todoCount = tasks.filter(task => task.status === 'todo').length;
    const inProgressCount = tasks.filter(task => task.status === 'in-progress').length;
    const doneCount = tasks.filter(task => task.status === 'done').length;

    document.querySelector('#todo .task-count').textContent = todoCount;
    document.querySelector('#in-progress .task-count').textContent = inProgressCount;
    document.querySelector('#done .task-count').textContent = doneCount;
}

// Open login modal
function openLoginModal() {
    loginModal.style.display = 'block';
    currentModal = loginModal;

    // Initialize Firebase UI
    ui.start('#firebaseui-auth-container', {
        signInOptions: [
            firebase.auth.EmailAuthProvider.PROVIDER_ID,
            firebase.auth.GoogleAuthProvider.PROVIDER_ID
        ],
        signInSuccessUrl: window.location.href,
        signInFlow: 'popup',
        callbacks: {
            signInSuccessWithAuthResult: () => {
                loginModal.style.display = 'none';
                currentModal = null;
                return false;
            }
        }
    });
}

// Initialize the app when the DOM is loaded
document.addEventListener('DOMContentLoaded', initApp);
```

## Features

1. **Drag-and-Drop Interface**:
   - Tasks can be dragged between columns (To Do, In Progress, Done)
   - Visual feedback during dragging

2. **Task Management**:
   - Add, edit, and delete tasks
   - Task details include title, description, assignee, and due date
   - Task status tracking

3. **Real-time Collaboration**:
   - Firebase integration for real-time updates
   - Authentication with Firebase Auth
   - Firestore database for task storage

4. **Responsive Design**:
   - Works on mobile and desktop
   - Clean, modern UI with appropriate spacing

5. **User Experience**:
   - Modal dialogs for adding/editing tasks
   - Task counts in each column
   - Visual feedback for interactions

