```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const userCountSpan = document.getElementById('user-count');

    // Current task being edited (null for new tasks)
    let currentTaskId = null;
    let currentColumn = null;

    // Sample initial data
    let tasks = [
        { id: '1', title: 'Design homepage', description: 'Create wireframe for the main page', status: 'todo' },
        { id: '2', title: 'Implement login', description: 'Set up authentication system', status: 'in-progress' },
        { id: '3', title: 'Write documentation', description: 'Document the API endpoints', status: 'done' }
    ];

    // Initialize the board
    function initBoard() {
        tasks.forEach(task => {
            addTaskToDOM(task);
        });

        setupDragAndDrop();
    }

    // Add a task to the DOM
    function addTaskToDOM(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;
        taskElement.dataset.status = task.status;

        taskElement.innerHTML = `
            <h3>${task.title}</h3>
            <p>${task.description}</p>
        `;

        const columnId = `${task.status}-tasks`;
        document.getElementById(columnId).appendChild(taskElement);

        // Add event listeners for editing
        taskElement.addEventListener('dblclick', () => {
            openTaskModal(task.id);
        });
    }

    // Open the task modal for editing or creating
    function openTaskModal(taskId = null) {
        currentTaskId = taskId;

        if (taskId) {
            const task = tasks.find(t => t.id === taskId);
            taskTitleInput.value = task.title;
            taskDescriptionInput.value = task.description;
        } else {
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
        }

        taskModal.style.display = 'block';
    }

    // Close the task modal
    function closeTaskModal() {
        taskModal.style.display = 'none';
        currentTaskId = null;
    }

    // Save a task (new or edited)
    function saveTask() {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        if (currentTaskId) {
            // Update existing task
            const taskIndex = tasks.findIndex(t => t.id === currentTaskId);
            if (taskIndex !== -1) {
                tasks[taskIndex].title = title;
                tasks[taskIndex].description = description;

                // Update DOM
                const taskElement = document.querySelector(`.task-card[data-id="${currentTaskId}"]`);
                if (taskElement) {
                    taskElement.querySelector('h3').textContent = title;
                    taskElement.querySelector('p').textContent = description;
                }

                // Emit update to server
                socket.emit('updateTask', tasks[taskIndex]);
            }
        } else {
            // Create new task
            const newTask = {
                id: Date.now().toString(),
                title,
                description,
                status: currentColumn || 'todo'
            };

            tasks.push(newTask);
            addTaskToDOM(newTask);

            // Emit new task to server
            socket.emit('newTask', newTask);
        }

        closeTaskModal();
    }

    // Set up drag and drop functionality
    function setupDragAndDrop() {
        taskLists.forEach(list => {
            list.addEventListener('dragover', (e) => {
                e.preventDefault();
                const afterElement = getDragAfterElement(list, e.clientY);
                const draggable = document.querySelector('.dragging');

                if (afterElement == null) {
                    list.appendChild(draggable);
                } else {
                    list.insertBefore(draggable, afterElement);
                }
            });
        });

        document.querySelectorAll('.task-card').forEach(card => {
            card.addEventListener('dragstart', () => {
                card.classList.add('dragging');
            });

            card.addEventListener('dragend', () => {
                card.classList.remove('dragging');

                // Update task status based on new column
                const newStatus = card.parentElement.parentElement.dataset.status;
                const taskId = card.dataset.id;

                const taskIndex = tasks.findIndex(t => t.id === taskId);
                if (taskIndex !== -1 && tasks[taskIndex].status !== newStatus) {
                    tasks[taskIndex].status = newStatus;
                    card.dataset.status = newStatus;

                    // Emit status change to server
                    socket.emit('updateTaskStatus', {
                        id: taskId,
                        status: newStatus
                    });
                }
            });
        });
    }

    // Helper function for drag and drop positioning
    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.task-card:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;

            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('userCount', (count) => {
        userCountSpan.textContent = count;
    });

    socket.on('newTask', (task) => {
        if (!tasks.some(t => t.id === task.id)) {
            tasks.push(task);
            addTaskToDOM(task);
        }
    });

    socket.on('updateTask', (updatedTask) => {
        const taskIndex = tasks.findIndex(t => t.id === updatedTask.id);
        if (taskIndex !== -1) {
            tasks[taskIndex] = updatedTask;

            // Update DOM
            const taskElement = document.querySelector(`.task-card[data-id="${updatedTask.id}"]`);
            if (taskElement) {
                taskElement.querySelector('h3').textContent = updatedTask.title;
                taskElement.querySelector('p').textContent = updatedTask.description;
            }
        }
    });

    socket.on('updateTaskStatus', ({ id, status }) => {
        const taskIndex = tasks.findIndex(t => t.id === id);
        if (taskIndex !== -1) {
            tasks[taskIndex].status = status;

            // Update DOM
            const taskElement = document.querySelector(`.task-card[data-id="${id}"]`);
            if (taskElement) {
                taskElement.dataset.status = status;
                const newColumn = document.getElementById(`${status}-tasks`);
                if (newColumn) {
                    newColumn.appendChild(taskElement);
                }
            }
        }
    });

    // Event listeners
    addTaskButtons.forEach(button => {
        button.addEventListener('click', (e) => {
            currentColumn = e.target.closest('.board-column').dataset.status;
            openTaskModal();
        });
    });

    closeModal.addEventListener('click', closeTaskModal);

    saveTaskBtn.addEventListener('click', saveTask);

    window.addEventListener('click', (e) => {
        if (e.target === taskModal) {
            closeTaskModal();
        }
    });

    // Initialize the app
    initBoard();
});
