## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM Elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const modal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const changeUserBtn = document.getElementById('change-user');
    const currentUserSpan = document.getElementById('current-user');

    // Current user (for demo purposes)
    let currentUser = localStorage.getItem('pmUser') || 'Guest';
    currentUserSpan.textContent = currentUser;

    // Sample tasks data
    let tasks = JSON.parse(localStorage.getItem('pmTasks')) || [
        { id: '1', title: 'Design homepage', description: 'Create wireframe for new homepage', status: 'todo', priority: 'high', user: 'User1' },
        { id: '2', title: 'Implement API', description: 'Develop backend API endpoints', status: 'in-progress', priority: 'medium', user: 'User2' },
        { id: '3', title: 'Write documentation', description: 'Document API endpoints and usage', status: 'done', priority: 'low', user: 'User1' }
    ];

    // Render all tasks
    function renderTasks() {
        taskLists.forEach(list => {
            list.innerHTML = '';
            const status = list.dataset.status;
            const statusTasks = tasks.filter(task => task.status === status);

            statusTasks.forEach(task => {
                const taskElement = createTaskElement(task);
                list.appendChild(taskElement);
            });
        });

        // Save to localStorage
        localStorage.setItem('pmTasks', JSON.stringify(tasks));
    }

    // Create task element
    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;

        taskElement.innerHTML = `
            <div class="task-header">
                <span class="task-title">${task.title}</span>
                <span class="task-priority priority-${task.priority}">${task.priority}</span>
            </div>
            <div class="task-description">${task.description || ''}</div>
            <div class="task-meta">
                <span>Created by: ${task.user}</span>
                <div class="task-actions">
                    <button class="edit" data-id="${task.id}"><i class="fas fa-edit"></i></button>
                    <button class="delete" data-id="${task.id}"><i class="fas fa-trash"></i></button>
                </div>
            </div>
        `;

        // Add drag event listeners
        taskElement.addEventListener('dragstart', handleDragStart);
        taskElement.addEventListener('dragend', handleDragEnd);

        // Add edit and delete event listeners
        taskElement.querySelector('.edit').addEventListener('click', (e) => {
            e.stopPropagation();
            openEditTaskModal(task.id);
        });

        taskElement.querySelector('.delete').addEventListener('click', (e) => {
            e.stopPropagation();
            deleteTask(task.id);
        });

        return taskElement;
    }

    // Drag and drop functionality
    function handleDragStart(e) {
        e.target.classList.add('dragging');
        e.dataTransfer.setData('text/plain', e.target.dataset.id);
        e.dataTransfer.effectAllowed = 'move';
    }

    function handleDragEnd(e) {
        e.target.classList.remove('dragging');
    }

    function handleDragOver(e) {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
    }

    function handleDrop(e) {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const newStatus = e.currentTarget.dataset.status;

        // Update task status
        const taskIndex = tasks.findIndex(task => task.id === taskId);
        if (taskIndex !== -1) {
            tasks[taskIndex].status = newStatus;

            // Emit update to server
            socket.emit('taskUpdate', tasks[taskIndex]);

            // Re-render tasks
            renderTasks();
        }
    }

    // Set up drop zones
    taskLists.forEach(list => {
        list.addEventListener('dragover', handleDragOver);
        list.addEventListener('drop', handleDrop);
    });

    // Modal functionality
    function openAddTaskModal(status) {
        document.getElementById('modal-title').textContent = 'Add New Task';
        document.getElementById('task-id').value = '';
        document.getElementById('task-status').value = status;
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        document.getElementById('task-priority').value = 'medium';
        modal.style.display = 'flex';
    }

    function openEditTaskModal(taskId) {
        const task = tasks.find(t => t.id === taskId);
        if (task) {
            document.getElementById('modal-title').textContent = 'Edit Task';
            document.getElementById('task-id').value = task.id;
            document.getElementById('task-status').value = task.status;
            document.getElementById('task-title').value = task.title;
            document.getElementById('task-description').value = task.description || '';
            document.getElementById('task-priority').value = task.priority;
            modal.style.display = 'flex';
        }
    }

    function closeModalHandler() {
        modal.style.display = 'none';
    }

    // Event listeners
    addTaskButtons.forEach(button => {
        button.addEventListener('click', () => {
            openAddTaskModal(button.dataset.status);
        });
    });

    closeModal.addEventListener('click', closeModalHandler);

    window.addEventListener('click', (e) => {
        if (e.target === modal) {
            closeModalHandler();
        }
    });

    // Form submission
    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const taskId = document.getElementById('task-id').value;
        const status = document.getElementById('task-status').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const priority = document.getElementById('task-priority').value;

        if (taskId) {
            // Update existing task
            const taskIndex = tasks.findIndex(task => task.id === taskId);
            if (taskIndex !== -1) {
                tasks[taskIndex] = {
                    ...tasks[taskIndex],
                    title,
                    description,
                    priority,
                    status
                };

                // Emit update to server
                socket.emit('taskUpdate', tasks[taskIndex]);
            }
        } else {
            // Create new task
            const newTask = {
                id: Date.now().toString(),
                title,
                description,
                status,
                priority,
                user: currentUser
            };

            tasks.push(newTask);

            // Emit new task to server
            socket.emit('newTask', newTask);
        }

        renderTasks();
        closeModalHandler();
    });

    // Delete task
    function deleteTask(taskId) {
        if (confirm('Are you sure you want to delete this task?')) {
            tasks = tasks.filter(task => task.id !== taskId);

            // Emit delete to server
            socket.emit('taskDelete', taskId);

            renderTasks();
        }
    }

    // Change user
    changeUserBtn.addEventListener('click', () => {
        const newUser = prompt('Enter your name:', currentUser);
        if (newUser) {
            currentUser = newUser;
            currentUserSpan.textContent = currentUser;
            localStorage.setItem('pmUser', currentUser);
        }
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('taskUpdate', (updatedTask) => {
        const taskIndex = tasks.findIndex(task => task.id === updatedTask.id);
        if (taskIndex !== -1) {
            tasks[taskIndex] = updatedTask;
            renderTasks();
        }
    });

    socket.on('newTask', (newTask) => {
        tasks.push(newTask);
        renderTasks();
    });

    socket.on('taskDelete', (taskId) => {
        tasks = tasks.filter(task => task.id !== taskId);
        renderTasks();
    });

    // Initial render
    renderTasks();
});
