## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const boardContainer = document.getElementById('board-container');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnName = document.getElementById('new-column-name');
const connectBtn = document.getElementById('connect-btn');
const userStatus = document.getElementById('user-status');

// State
let currentUserId = null;
let columns = {};

// Initialize the app
function initApp() {
    // Set up event listeners
    addColumnBtn.addEventListener('click', addColumn);
    connectBtn.addEventListener('click', connectUser);

    // Load existing data from Firebase
    loadData();

    // Set up modal for task editing
    setupModal();
}

// Connect a user (simplified for demo)
function connectUser() {
    currentUserId = 'user-' + Math.floor(Math.random() * 1000);
    userStatus.textContent = `Connected as ${currentUserId}`;
    connectBtn.textContent = 'Disconnect';
    connectBtn.style.backgroundColor = '#f44336';
    connectBtn.removeEventListener('click', connectUser);
    connectBtn.addEventListener('click', disconnectUser);

    // Listen for real-time updates
    setupRealTimeListeners();
}

function disconnectUser() {
    currentUserId = null;
    userStatus.textContent = 'Not connected';
    connectBtn.textContent = 'Connect';
    connectBtn.style.backgroundColor = '#4CAF50';
    connectBtn.removeEventListener('click', disconnectUser);
    connectBtn.addEventListener('click', connectUser);

    // Remove real-time listeners
    removeRealTimeListeners();
}

// Load data from Firebase
function loadData() {
    database.ref('columns').once('value').then((snapshot) => {
        const data = snapshot.val();
        if (data) {
            columns = data;
            renderColumns();
        }
    });
}

// Set up real-time listeners
function setupRealTimeListeners() {
    database.ref('columns').on('value', (snapshot) => {
        columns = snapshot.val() || {};
        renderColumns();
    });
}

// Remove real-time listeners
function removeRealTimeListeners() {
    database.ref('columns').off();
}

// Render all columns
function renderColumns() {
    boardContainer.innerHTML = '';

    for (const columnId in columns) {
        const column = columns[columnId];
        const columnElement = createColumnElement(columnId, column);
        boardContainer.appendChild(columnElement);
    }

    // Initialize drag and drop for all columns
    initDragAndDrop();
}

// Create a column element
function createColumnElement(columnId, column) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.dataset.columnId = columnId;

    const columnHeader = document.createElement('div');
    columnHeader.className = 'column-header';

    const columnTitle = document.createElement('div');
    columnTitle.className = 'column-title';
    columnTitle.textContent = column.name;

    const columnActions = document.createElement('div');
    columnActions.className = 'column-actions';

    const editBtn = document.createElement('button');
    editBtn.innerHTML = '<i class="fas fa-edit"></i>';
    editBtn.addEventListener('click', () => editColumn(columnId, column.name));

    const deleteBtn = document.createElement('button');
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', () => deleteColumn(columnId));

    columnActions.appendChild(editBtn);
    columnActions.appendChild(deleteBtn);

    columnHeader.appendChild(columnTitle);
    columnHeader.appendChild(columnActions);

    const taskList = document.createElement('div');
    taskList.className = 'task-list';
    taskList.dataset.columnId = columnId;

    // Add tasks to the column
    if (column.tasks) {
        for (const taskId in column.tasks) {
            const task = column.tasks[taskId];
            const taskElement = createTaskElement(taskId, task);
            taskList.appendChild(taskElement);
        }
    }

    const addTaskForm = createAddTaskForm(columnId);

    columnElement.appendChild(columnHeader);
    columnElement.appendChild(taskList);
    columnElement.appendChild(addTaskForm);

    return columnElement;
}

// Create a task element
function createTaskElement(taskId, task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.dataset.taskId = taskId;

    const taskHeader = document.createElement('div');
    taskHeader.className = 'task-header';

    const taskTitle = document.createElement('div');
    taskTitle.className = 'task-title';
    taskTitle.textContent = task.title;

    const taskActions = document.createElement('div');
    taskActions.className = 'task-actions';

    const editBtn = document.createElement('button');
    editBtn.innerHTML = '<i class="fas fa-edit"></i>';
    editBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        editTask(taskId, task);
    });

    const deleteBtn = document.createElement('button');
    deleteBtn.innerHTML = '<i class="fas fa-trash"></i>';
    deleteBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        deleteTask(taskId);
    });

    taskActions.appendChild(editBtn);
    taskActions.appendChild(deleteBtn);

    taskHeader.appendChild(taskTitle);
    taskHeader.appendChild(taskActions);

    const taskContent = document.createElement('div');
    taskContent.className = 'task-content';
    taskContent.textContent = task.description;

    taskElement.appendChild(taskHeader);
    taskElement.appendChild(taskContent);

    return taskElement;
}

// Create add task form
function createAddTaskForm(columnId) {
    const form = document.createElement('div');
    form.className = 'add-task';

    const titleInput = document.createElement('input');
    titleInput.type = 'text';
    titleInput.placeholder = 'Task title';

    const descInput = document.createElement('textarea');
    descInput.placeholder = 'Task description';
    descInput.rows = 3;

    const addBtn = document.createElement('button');
    addBtn.textContent = 'Add Task';
    addBtn.addEventListener('click', () => {
        if (titleInput.value.trim()) {
            addTask(columnId, {
                title: titleInput.value.trim(),
                description: descInput.value.trim()
            });
            titleInput.value = '';
            descInput.value = '';
        }
    });

    form.appendChild(titleInput);
    form.appendChild(descInput);
    form.appendChild(addBtn);

    return form;
}

// Add a new column
function addColumn() {
    if (!newColumnName.value.trim()) return;

    const columnId = 'col-' + Date.now();
    const column = {
        name: newColumnName.value.trim(),
        tasks: {}
    };

    // Save to Firebase
    database.ref(`columns/${columnId}`).set(column);

    newColumnName.value = '';
}

// Edit a column
function editColumn(columnId, currentName) {
    const newName = prompt('Enter new column name:', currentName);
    if (newName && newName.trim() !== currentName) {
        database.ref(`columns/${columnId}/name`).set(newName.trim());
    }
}

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column?')) {
        database.ref(`columns/${columnId}`).remove();
    }
}

// Add a new task
function addTask(columnId, taskData) {
    const taskId = 'task-' + Date.now();
    const task = {
        ...taskData,
        createdBy: currentUserId || 'anonymous',
        createdAt: firebase.database.ServerValue.TIMESTAMP
    };

    // Save to Firebase
    database.ref(`columns/${columnId}/tasks/${taskId}`).set(task);
}

// Edit a task
function editTask(taskId, currentTask) {
    // Find which column the task belongs to
    let columnId = null;
    for (const colId in columns) {
        if (columns[colId].tasks && columns[colId].tasks[taskId]) {
            columnId = colId;
            break;
        }
    }

    if (!columnId) return;

    // Show modal for editing
    showTaskModal(columnId, taskId, currentTask);
}

// Delete a task
function deleteTask(taskId) {
    if (confirm('Are you sure you want to delete this task?')) {
        // Find which column the task belongs to
        for (const columnId in columns) {
            if (columns[columnId].tasks && columns[columnId].tasks[taskId]) {
                database.ref(`columns/${columnId}/tasks/${taskId}`).remove();
                break;
            }
        }
    }
}

// Initialize drag and drop functionality
function initDragAndDrop() {
    const taskLists = document.querySelectorAll('.task-list');

    taskLists.forEach(taskList => {
        new Sortable(taskList, {
            group: 'tasks',
            animation: 150,
            ghostClass: 'sortable-ghost',
            onEnd: function(evt) {
                const fromColumnId = evt.from.dataset.columnId;
                const toColumnId = evt.to.dataset.columnId;
                const taskId = evt.item.dataset.taskId;

                if (fromColumnId !== toColumnId) {
                    // Task moved to a different column
                    moveTaskBetweenColumns(fromColumnId, toColumnId, taskId);
                } else {
                    // Task reordered within the same column
                    reorderTasksInColumn(fromColumnId);
                }
            }
        });
    });
}

// Move task between columns
function moveTaskBetweenColumns(fromColumnId, toColumnId, taskId) {
    const task = columns[fromColumnId].tasks[taskId];

    // Remove from old column
    database.ref(`columns/${fromColumnId}/tasks/${taskId}`).remove();

    // Add to new column
    database.ref(`columns/${toColumnId}/tasks/${taskId}`).set(task);
}

// Reorder tasks within a column
function reorderTasksInColumn(columnId) {
    const taskList = document.querySelector(`.task-list[data-column-id="${columnId}"]`);
    const taskElements = taskList.querySelectorAll('.task');

    // Create a new tasks object with updated order
    const updatedTasks = {};
    taskElements.forEach((taskElement, index) => {
        const taskId = taskElement.dataset.taskId;
        updatedTasks[taskId] = columns[columnId].tasks[taskId];
    });

    // Update Firebase
    database.ref(`columns/${columnId}/tasks`).set(updatedTasks);
}

// Modal for task editing
function setupModal() {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.id = 'task-modal';

    const modalContent = document.createElement('div');
    modalContent.className = 'modal-content';

    const modalHeader = document.createElement('div');
    modalHeader.className = 'modal-header';

    const modalTitle = document.createElement('h2');
    modalTitle.textContent = 'Edit Task';

    const modalClose = document.createElement('button');
    modalClose.className = 'modal-close';
    modalClose.innerHTML = '&times;';
    modalClose.addEventListener('click', () => modal.style.display = 'none');

    modalHeader.appendChild(modalTitle);
    modalHeader.appendChild(modalClose);

    const modalBody = document.createElement('div');
    modalBody.className = 'modal-body';

    const titleInput = document.createElement('input');
    titleInput.type = 'text';
    titleInput.placeholder = 'Task title';
    titleInput.id = 'modal-task-title';

    const descInput = document.createElement('textarea');
    descInput.placeholder = 'Task description';
    descInput.rows = 5;
    descInput.id = 'modal-task-desc';

    modalBody.appendChild(titleInput);
    modalBody.appendChild(descInput);

    const modalFooter = document.createElement('div');
    modalFooter.className = 'modal-footer';

    const saveBtn = document.createElement('button');
    saveBtn.className = 'primary';
    saveBtn.textContent = 'Save';
    saveBtn.addEventListener('click', () => {
        saveTaskEdits();
        modal.style.display = 'none';
    });

    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'secondary';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.addEventListener('click', () => modal.style.display = 'none');

    modalFooter.appendChild(cancelBtn);
    modalFooter.appendChild(saveBtn);

    modalContent.appendChild(modalHeader);
    modalContent.appendChild(modalBody);
    modalContent.appendChild(modalFooter);

    modal.appendChild(modalContent);

    document.body.appendChild(modal);
}

// Show task modal
function showTaskModal(columnId, taskId, task) {
    const modal = document.getElementById('task-modal');
    const titleInput = document.getElementById('modal-task-title');
    const descInput = document.getElementById('modal-task-desc');

    titleInput.value = task.title;
    descInput.value = task.description;

    // Store the current task info for saving
    modal.dataset.columnId = columnId;
    modal.dataset.taskId = taskId;

    modal.style.display = 'flex';
}

// Save task edits
function saveTaskEdits() {
    const modal = document.getElementById('task-modal');
    const columnId = modal.dataset.columnId;
    const taskId = modal.dataset.taskId;
    const titleInput = document.getElementById('modal-task-title');
    const descInput = document.getElementById('modal-task-desc');

    const updatedTask = {
        title: titleInput.value.trim(),
        description: descInput.value.trim(),
        createdBy: columns[columnId].tasks[taskId].createdBy,
        createdAt: columns[columnId].tasks[taskId].createdAt,
        updatedAt: firebase.database.ServerValue.TIMESTAMP
    };

    database.ref(`columns/${columnId}/tasks/${taskId}`).set(updatedTask);
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
```

## Setup Instructions

1. **Firebase Setup**:
   - Create a Firebase project at [https://firebase.google.com](https://firebase.google.com)
   - Enable Realtime Database
   - Get your Firebase configuration and replace the placeholder values in the JavaScript file

2. **Run the App**:
   - Save all three files (index.html, styles.css, app.js) in the same directory
   - Open index.html in a web browser

## Features

1. **Drag-and-Drop Tasks**: Tasks can be dragged between columns and reordered within columns
2. **Real-time Collaboration**: Changes made by one user are instantly visible to others
3. **Basic CRUD Operations**:
   - Create, read, update, and delete columns
   - Create, read, update, and delete tasks
4. **User Connection**: Simple user connection/disconnection system
5. **Responsive Design**: Works on different screen sizes

## Limitations

This is a minimal implementation. For a production app, you would want to add:
- User authentication
- More robust error handling
- Task details view
- User presence indicators
- More sophisticated task properties (due dates, assignees, etc.)
- Better UI/UX polish

The app uses Firebase for real-time synchronization, but you could replace this with any other real-time backend solution.

