```javascript
document.addEventListener('DOMContentLoaded', function() {
    const socket = io();
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const userCountElement = document.getElementById('user-count');

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskButtons.forEach(button => {
        button.addEventListener('click', function() {
            const column = this.closest('.board-column');
            const status = column.dataset.status;
            const taskName = prompt('Enter task name:');

            if (taskName) {
                const taskId = Date.now().toString();
                const task = {
                    id: taskId,
                    name: taskName,
                    status: status
                };

                socket.emit('addTask', task);
            }
        });
    });

    // Socket.io event listeners
    socket.on('taskAdded', (task) => {
        addTaskToDOM(task);
    });

    socket.on('taskMoved', (task) => {
        moveTaskInDOM(task);
    });

    socket.on('userCount', (count) => {
        userCountElement.textContent = count;
    });

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.dataset.id);
        e.target.classList.add('dragging');
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function drop(e) {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const taskElement = document.querySelector(`[data-id="${taskId}"]`);
        const newStatus = e.currentTarget.closest('.board-column').dataset.status;

        if (taskElement) {
            taskElement.classList.remove('dragging');
            e.currentTarget.appendChild(taskElement);

            const task = {
                id: taskId,
                name: taskElement.textContent,
                status: newStatus
            };

            socket.emit('moveTask', task);
        }
    }

    // DOM manipulation functions
    function addTaskToDOM(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.textContent = task.name;
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;

        taskElement.addEventListener('dragstart', dragStart);

        const targetList = document.getElementById(`${task.status}-tasks`);
        targetList.appendChild(taskElement);
    }

    function moveTaskInDOM(task) {
        const taskElement = document.querySelector(`[data-id="${task.id}"]`);
        if (taskElement) {
            const targetList = document.getElementById(`${task.status}-tasks`);
            targetList.appendChild(taskElement);
        }
    }
});
```

## 4. server.js
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

let tasks = [];
let userCount = 0;

// Serve static files
app.use(express.static(__dirname));

// Socket.io connection
io.on('connection', (socket) => {
    userCount++;
    io.emit('userCount', userCount);

    // Send existing tasks to new user
    socket.emit('initialTasks', tasks);

    // Handle task addition
    socket.on('addTask', (task) => {
        tasks.push(task);
        io.emit('taskAdded', task);
    });

    // Handle task movement
    socket.on('moveTask', (task) => {
        const index = tasks.findIndex(t => t.id === task.id);
        if (index !== -1) {
            tasks[index].status = task.status;
            io.emit('taskMoved', task);
        }
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        userCount--;
        io.emit('userCount', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

