## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own config)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const board = document.getElementById('board');
const addColumnBtn = document.getElementById('add-column-btn');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close');
const taskForm = document.getElementById('task-form');
const userStatus = document.getElementById('user-status');

// Sample initial data (will be replaced by Firebase data)
let initialData = {
    columns: [
        { id: 'col1', title: 'To Do', tasks: [] },
        { id: 'col2', title: 'In Progress', tasks: [] },
        { id: 'col3', title: 'Done', tasks: [] }
    ]
};

// Current state
let currentColumnId = null;
let currentTaskId = null;

// Initialize the app
function initApp() {
    // Check if we have data in Firebase
    database.ref('board').once('value').then((snapshot) => {
        if (snapshot.exists()) {
            initialData = snapshot.val();
        } else {
            // Initialize with default data
            database.ref('board').set(initialData);
        }
        renderBoard();
        setupEventListeners();
    });

    // Set up real-time listener
    database.ref('board').on('value', (snapshot) => {
        initialData = snapshot.val();
        renderBoard();
    });

    // Simulate user connection status
    setTimeout(() => {
        userStatus.textContent = "Connected";
        userStatus.style.color = "green";
    }, 1000);
}

// Render the entire board
function renderBoard() {
    board.innerHTML = '';

    initialData.columns.forEach(column => {
        const columnElement = document.createElement('div');
        columnElement.className = 'column';
        columnElement.dataset.id = column.id;

        columnElement.innerHTML = `
            <div class="column-header">
                <div class="column-title">${column.title}</div>
                <div class="column-actions">
                    <button class="edit-column" title="Edit column"><i class="fas fa-edit"></i></button>
                    <button class="delete-column" title="Delete column"><i class="fas fa-trash"></i></button>
                </div>
            </div>
            <div class="task-list" id="task-list-${column.id}"></div>
            <div class="add-task">
                <button class="add-task-btn" data-column-id="${column.id}"><i class="fas fa-plus"></i> Add Task</button>
            </div>
        `;

        board.appendChild(columnElement);

        // Render tasks for this column
        const taskList = columnElement.querySelector('.task-list');
        column.tasks.forEach(task => {
            const taskElement = createTaskElement(task);
            taskList.appendChild(taskElement);
        });

        // Make the task list sortable
        new Sortable(taskList, {
            group: 'shared', // set both lists to same group
            animation: 150,
            ghostClass: 'sortable-ghost',
            chosenClass: 'sortable-chosen',
            onEnd: function (evt) {
                handleTaskMove(evt);
            }
        });
    });
}

// Create a task element
function createTaskElement(task) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task-card';
    taskElement.dataset.id = task.id;

    taskElement.innerHTML = `
        <div class="task-title">${task.title}</div>
        <div class="task-description">${task.description || ''}</div>
        <div class="task-meta">
            <span>${task.assignee || ''}</span>
            <span>${task.dueDate || ''}</span>
        </div>
    `;

    taskElement.addEventListener('click', () => openTaskModal(task.id));

    return taskElement;
}

// Handle task movement between columns
function handleTaskMove(evt) {
    const fromColumnId = evt.from.parentElement.dataset.id;
    const toColumnId = evt.to.parentElement.dataset.id;
    const taskId = evt.item.dataset.id;

    if (fromColumnId === toColumnId) return;

    // Find the task in the source column
    const fromColumn = initialData.columns.find(col => col.id === fromColumnId);
    const taskIndex = fromColumn.tasks.findIndex(t => t.id === taskId);
    const [movedTask] = fromColumn.tasks.splice(taskIndex, 1);

    // Add to the destination column
    const toColumn = initialData.columns.find(col => col.id === toColumnId);
    toColumn.tasks.push(movedTask);

    // Update Firebase
    database.ref('board').set(initialData);
}

// Set up event listeners
function setupEventListeners() {
    // Add column button
    addColumnBtn.addEventListener('click', () => {
        const columnTitle = prompt('Enter column title:');
        if (columnTitle) {
            const newColumn = {
                id: 'col' + Date.now(),
                title: columnTitle,
                tasks: []
            };

            initialData.columns.push(newColumn);
            database.ref('board').set(initialData);
        }
    });

    // Add task buttons
    document.querySelectorAll('.add-task-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            currentColumnId = e.target.dataset.columnId;
            currentTaskId = null;
            openTaskModal();
        });
    });

    // Edit column buttons
    document.querySelectorAll('.edit-column').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const columnId = e.target.closest('.column').dataset.id;
            const column = initialData.columns.find(col => col.id === columnId);
            const newTitle = prompt('Enter new column title:', column.title);

            if (newTitle && newTitle !== column.title) {
                column.title = newTitle;
                database.ref('board').set(initialData);
            }
        });
    });

    // Delete column buttons
    document.querySelectorAll('.delete-column').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const columnId = e.target.closest('.column').dataset.id;
            if (confirm('Are you sure you want to delete this column?')) {
                initialData.columns = initialData.columns.filter(col => col.id !== columnId);
                database.ref('board').set(initialData);
            }
        });
    });

    // Modal close button
    closeModal.addEventListener('click', closeTaskModal);

    // Form submission
    taskForm.addEventListener('submit', (e) => {
        e.preventDefault();
        saveTask();
    });
}

// Open task modal
function openTaskModal(taskId = null) {
    if (taskId) {
        // Edit existing task
        currentTaskId = taskId;
        const column = initialData.columns.find(col =>
            col.tasks.some(task => task.id === taskId)
        );
        const task = column.tasks.find(t => t.id === taskId);

        document.getElementById('task-id').value = task.id;
        document.getElementById('task-title').value = task.title;
        document.getElementById('task-description').value = task.description || '';
        document.getElementById('task-assignee').value = task.assignee || '';
        document.getElementById('task-due-date').value = task.dueDate || '';
    } else {
        // New task
        document.getElementById('task-id').value = '';
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        document.getElementById('task-assignee').value = '';
        document.getElementById('task-due-date').value = '';
    }

    taskModal.style.display = 'block';
}

// Close task modal
function closeTaskModal() {
    taskModal.style.display = 'none';
}

// Save task
function saveTask() {
    const taskId = document.getElementById('task-id').value;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const assignee = document.getElementById('task-assignee').value;
    const dueDate = document.getElementById('task-due-date').value;

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (taskId) {
        // Update existing task
        const column = initialData.columns.find(col =>
            col.tasks.some(task => task.id === taskId)
        );
        const task = column.tasks.find(t => t.id === taskId);

        task.title = title;
        task.description = description;
        task.assignee = assignee;
        task.dueDate = dueDate;
    } else {
        // Add new task
        const newTask = {
            id: 'task' + Date.now(),
            title,
            description,
            assignee,
            dueDate
        };

        const column = initialData.columns.find(col => col.id === currentColumnId);
        column.tasks.push(newTask);
    }

    database.ref('board').set(initialData);
    closeTaskModal();
}

// Close modal when clicking outside
window.addEventListener('click', (e) => {
    if (e.target === taskModal) {
        closeTaskModal();
    }
});

// Initialize the app
initApp();
```

## How to Use This Application

1. **Set up Firebase**:
   - Create a Firebase project at https://firebase.google.com/
   - Add a Realtime Database
   - Replace the placeholder values in the `firebaseConfig` object with your actual Firebase configuration

2. **Features**:
   - Drag-and-drop tasks between columns
   - Add, edit, and delete columns
   - Add, edit, and delete tasks
   - Real-time synchronization across all connected clients
