```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const userCountSpan = document.getElementById('user-count');

    // State variables
    let currentTaskId = null;
    let currentStatus = null;
    let draggedTask = null;

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Add task button click handlers
    addTaskButtons.forEach(button => {
        button.addEventListener('click', function() {
            currentStatus = this.getAttribute('data-status');
            currentTaskId = null;
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
            taskModal.style.display = 'block';
        });
    });

    // Close modal
    closeModal.addEventListener('click', function() {
        taskModal.style.display = 'none';
    });

    // Save task
    saveTaskBtn.addEventListener('click', function() {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (title) {
            if (currentTaskId) {
                // Update existing task
                socket.emit('updateTask', {
                    id: currentTaskId,
                    title,
                    description,
                    status: currentStatus
                });
            } else {
                // Create new task
                const newTask = {
                    id: Date.now().toString(),
                    title,
                    description,
                    status: currentStatus
                };
                socket.emit('addTask', newTask);
            }

            taskModal.style.display = 'none';
        }
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('taskAdded', (task) => {
        addTaskToDOM(task);
    });

    socket.on('taskUpdated', (task) => {
        updateTaskInDOM(task);
    });

    socket.on('taskMoved', (task) => {
        moveTaskInDOM(task);
    });

    socket.on('taskDeleted', (taskId) => {
        deleteTaskFromDOM(taskId);
    });

    socket.on('userCount', (count) => {
        userCountSpan.textContent = count;
    });

    // Drag and drop functions
    function dragStart(e) {
        draggedTask = e.target;
        e.dataTransfer.setData('text/plain', e.target.id);
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function dragEnter(e) {
        e.preventDefault();
        if (e.target.classList.contains('task-list')) {
            e.target.classList.add('drag-over');
        }
    }

    function dragLeave(e) {
        if (e.target.classList.contains('task-list')) {
            e.target.classList.remove('drag-over');
        }
    }

    function drop(e) {
        e.preventDefault();
        if (e.target.classList.contains('task-list')) {
            e.target.classList.remove('drag-over');

            const taskId = e.dataTransfer.getData('text/plain');
            const taskElement = document.getElementById(taskId);
            const newStatus = e.target.closest('.board-column').getAttribute('data-status');

            if (taskElement && newStatus) {
                // Update the task status
                const task = {
                    id: taskId,
                    title: taskElement.querySelector('h4').textContent,
                    description: taskElement.querySelector('p').textContent,
                    status: newStatus
                };

                socket.emit('moveTask', task);
            }
        }
    }

    // DOM manipulation functions
    function addTaskToDOM(task) {
        const taskElement = createTaskElement(task);
        const taskList = document.getElementById(`${task.status}-tasks`);
        taskList.appendChild(taskElement);
    }

    function updateTaskInDOM(task) {
        const existingTask = document.getElementById(task.id);
        if (existingTask) {
            existingTask.querySelector('h4').textContent = task.title;
            existingTask.querySelector('p').textContent = task.description;
        }
    }

    function moveTaskInDOM(task) {
        const taskElement = document.getElementById(task.id);
        if (taskElement) {
            const currentList = taskElement.parentNode;
            const newList = document.getElementById(`${task.status}-tasks`);

            if (currentList !== newList) {
                currentList.removeChild(taskElement);
                newList.appendChild(taskElement);
            }
        }
    }

    function deleteTaskFromDOM(taskId) {
        const taskElement = document.getElementById(taskId);
        if (taskElement) {
            taskElement.remove();
        }
    }

    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.id = task.id;
        taskElement.draggable = true;

        taskElement.innerHTML = `
            <h4>${task.title}</h4>
            <p>${task.description}</p>
        `;

        taskElement.addEventListener('dragstart', dragStart);

        // Add double-click to edit
        taskElement.addEventListener('dblclick', function() {
            currentTaskId = task.id;
            currentStatus = task.status;
            taskTitleInput.value = task.title;
            taskDescriptionInput.value = task.description;
            taskModal.style.display = 'block';
        });

        return taskElement;
    }

    // Close modal when clicking outside
    window.addEventListener('click', function(e) {
        if (e.target === taskModal) {
            taskModal.style.display = 'none';
        }
    });
});
