document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const modal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');

    let currentTask = null;
    let currentStatus = null;

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskButtons.forEach(button => {
        button.addEventListener('click', () => {
            currentStatus = button.getAttribute('data-status');
            currentTask = null;
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
            modal.style.display = 'block';
        });
    });

    // Modal controls
    closeModal.addEventListener('click', () => {
        modal.style.display = 'none';
    });

    saveTaskBtn.addEventListener('click', () => {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (title) {
            if (currentTask) {
                // Update existing task
                currentTask.querySelector('h3').textContent = title;
                currentTask.querySelector('p').textContent = description;

                socket.emit('updateTask', {
                    id: currentTask.id,
                    title,
                    description,
                    status: currentStatus
                });
            } else {
                // Create new task
                const taskId = 'task-' + Date.now();
                const taskElement = createTaskElement(taskId, title, description);

                document.querySelector(`.task-list[data-status="${currentStatus}"]`).appendChild(taskElement);

                socket.emit('addTask', {
                    id: taskId,
                    title,
                    description,
                    status: currentStatus
                });
            }

            modal.style.display = 'none';
        }
    });

    // Socket.IO events
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('userCount', (count) => {
        document.getElementById('user-count').textContent = count;
    });

    socket.on('taskAdded', (task) => {
        if (!document.getElementById(task.id)) {
            const taskElement = createTaskElement(task.id, task.title, task.description);
            document.querySelector(`.task-list[data-status="${task.status}"]`).appendChild(taskElement);
        }
    });

    socket.on('taskUpdated', (task) => {
        const existingTask = document.getElementById(task.id);
        if (existingTask) {
            existingTask.querySelector('h3').textContent = task.title;
            existingTask.querySelector('p').textContent = task.description;

            if (existingTask.parentElement.getAttribute('data-status') !== task.status) {
                document.querySelector(`.task-list[data-status="${task.status}"]`).appendChild(existingTask);
            }
        }
    });

    socket.on('taskRemoved', (taskId) => {
        const taskElement = document.getElementById(taskId);
        if (taskElement) {
            taskElement.remove();
        }
    });

    // Helper functions
    function createTaskElement(id, title, description) {
        const task = document.createElement('div');
        task.className = 'task';
        task.id = id;
        task.draggable = true;
        task.innerHTML = `
            <h3>${title}</h3>
            <p>${description}</p>
        `;

        task.addEventListener('dragstart', dragStart);
        task.addEventListener('click', () => {
            currentTask = task;
            currentStatus = task.parentElement.getAttribute('data-status');
            taskTitleInput.value = task.querySelector('h3').textContent;
            taskDescriptionInput.value = task.querySelector('p').textContent;
            modal.style.display = 'block';
        });

        return task;
    }

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.id);
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function dragEnter(e) {
        e.preventDefault();
        this.classList.add('drag-over');
    }

    function dragLeave() {
        this.classList.remove('drag-over');
    }

    function drop(e) {
        e.preventDefault();
        this.classList.remove('drag-over');

        const id = e.dataTransfer.getData('text/plain');
        const draggable = document.getElementById(id);
        const newStatus = this.getAttribute('data-status');

        if (draggable && newStatus) {
            this.appendChild(draggable);
            draggable.classList.remove('dragging');

            // Update task status
            socket.emit('updateTask', {
                id: draggable.id,
                title: draggable.querySelector('h3').textContent,
                description: draggable.querySelector('p').textContent,
                status: newStatus
            });
        }
    }
});
