## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // Generate a random user ID for this session
    const userId = 'user-' + Math.floor(Math.random() * 10000);
    document.getElementById('current-user').textContent = userId;

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const taskForm = document.getElementById('task-form');
    const modalTitle = document.getElementById('modal-title');

    // Task data
    let tasks = [];

    // Initialize drag and drop
    initDragAndDrop();

    // Event listeners
    addTaskButtons.forEach(button => {
        button.addEventListener('click', function() {
            openTaskModal(null, this.getAttribute('data-status'));
        });
    });

    closeModal.addEventListener('click', closeTaskModal);

    taskForm.addEventListener('submit', function(e) {
        e.preventDefault();
        saveTask();
    });

    // Socket.io event listeners
    socket.on('taskAdded', (task) => {
        if (task.userId !== userId) {
            addTaskToDOM(task);
            updateTaskCounts();
        }
    });

    socket.on('taskUpdated', (updatedTask) => {
        if (updatedTask.userId !== userId) {
            updateTaskInDOM(updatedTask);
            updateTaskCounts();
        }
    });

    socket.on('taskDeleted', (taskId) => {
        const taskElement = document.querySelector(`[data-task-id="${taskId}"]`);
        if (taskElement) {
            taskElement.remove();
            updateTaskCounts();
        }
    });

    // Initialize with some sample tasks
    function initSampleTasks() {
        const sampleTasks = [
            { id: 'task-1', title: 'Design homepage', description: 'Create wireframe for the main page', status: 'todo', assignee: 'John', dueDate: '2023-12-15', userId: userId },
            { id: 'task-2', title: 'Implement API', description: 'Develop backend API endpoints', status: 'in-progress', assignee: 'Sarah', dueDate: '2023-12-20', userId: userId },
            { id: 'task-3', title: 'Write documentation', description: 'Document the project setup', status: 'done', assignee: 'Mike', dueDate: '2023-12-10', userId: userId }
        ];

        sampleTasks.forEach(task => {
            addTaskToDOM(task);
        });

        updateTaskCounts();
    }

    // Initialize drag and drop functionality
    function initDragAndDrop() {
        taskLists.forEach(list => {
            list.addEventListener('dragover', function(e) {
                e.preventDefault();
                const afterElement = getDragAfterElement(list, e.clientY);
                const draggable = document.querySelector('.dragging');

                if (afterElement == null) {
                    list.appendChild(draggable);
                } else {
                    list.insertBefore(draggable, afterElement);
                }
            });
        });

        document.querySelectorAll('.task-card').forEach(card => {
            card.addEventListener('dragstart', () => {
                card.classList.add('dragging');
            });

            card.addEventListener('dragend', () => {
                card.classList.remove('dragging');

                // Update task status when dropped in a new column
                const newStatus = card.closest('.column').getAttribute('data-status');
                const taskId = card.getAttribute('data-task-id');
                const taskIndex = tasks.findIndex(t => t.id === taskId);

                if (taskIndex !== -1 && tasks[taskIndex].status !== newStatus) {
                    tasks[taskIndex].status = newStatus;
                    socket.emit('taskUpdated', tasks[taskIndex]);
                    updateTaskCounts();
                }
            });
        });
    }

    // Helper function to determine where to place the dragged element
    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.task-card:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;

            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

    // Open task modal for adding or editing
    function openTaskModal(taskId, status) {
        if (taskId) {
            // Edit existing task
            const task = tasks.find(t => t.id === taskId);
            if (task) {
                modalTitle.textContent = 'Edit Task';
                document.getElementById('task-id').value = task.id;
                document.getElementById('task-status').value = task.status;
                document.getElementById('task-title').value = task.title;
                document.getElementById('task-description').value = task.description || '';
                document.getElementById('task-assignee').value = task.assignee || '';
                document.getElementById('task-due-date').value = task.dueDate || '';
            }
        } else {
            // Add new task
            modalTitle.textContent = 'Add New Task';
            document.getElementById('task-id').value = '';
            document.getElementById('task-status').value = status;
            document.getElementById('task-title').value = '';
            document.getElementById('task-description').value = '';
            document.getElementById('task-assignee').value = '';
            document.getElementById('task-due-date').value = '';
        }

        taskModal.style.display = 'flex';
    }

    // Close task modal
    function closeTaskModal() {
        taskModal.style.display = 'none';
    }

    // Save task (add or update)
    function saveTask() {
        const taskId = document.getElementById('task-id').value;
        const status = document.getElementById('task-status').value;
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;
        const assignee = document.getElementById('task-assignee').value;
        const dueDate = document.getElementById('task-due-date').value;

        if (!title.trim()) {
            alert('Please enter a task title');
            return;
        }

        if (taskId) {
            // Update existing task
            const taskIndex = tasks.findIndex(t => t.id === taskId);
            if (taskIndex !== -1) {
                const updatedTask = {
                    ...tasks[taskIndex],
                    title,
                    description,
                    assignee,
                    dueDate,
                    status
                };

                tasks[taskIndex] = updatedTask;
                updateTaskInDOM(updatedTask);
                socket.emit('taskUpdated', updatedTask);
            }
        } else {
            // Add new task
            const newTask = {
                id: 'task-' + Date.now(),
                title,
                description,
                status,
                assignee,
                dueDate,
                userId
            };

            tasks.push(newTask);
            addTaskToDOM(newTask);
            socket.emit('taskAdded', newTask);
        }

        updateTaskCounts();
        closeTaskModal();
    }

    // Add task to DOM
    function addTaskToDOM(task) {
        const taskElement = createTaskElement(task);
        const listId = `${task.status}-list`;
        const taskList = document.getElementById(listId);

        if (taskList) {
            taskList.appendChild(taskElement);
        }
    }

    // Update task in DOM
    function updateTaskInDOM(task) {
        const existingTask = document.querySelector(`[data-task-id="${task.id}"]`);
        if (existingTask) {
            // If status changed, move to the correct column
            const currentStatus = existingTask.closest('.column').getAttribute('data-status');
            if (currentStatus !== task.status) {
                existingTask.remove();
                addTaskToDOM(task);
            } else {
                // Just update the content
                const taskElement = createTaskElement(task);
                existingTask.replaceWith(taskElement);
            }
        } else {
            // Task doesn't exist in DOM, add it
            addTaskToDOM(task);
        }
    }

    // Create task element
    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.setAttribute('draggable', 'true');
        taskElement.setAttribute('data-task-id', task.id);

        taskElement.innerHTML = `
            <h3>${task.title}</h3>
            ${task.description ? `<p>${task.description}</p>` : ''}
            <div class="task-meta">
                <span>${task.assignee || 'Unassigned'}</span>
                <span>${task.dueDate ? formatDate(task.dueDate) : 'No due date'}</span>
            </div>
            <div class="task-actions">
                <button class="edit-task" data-task-id="${task.id}"><i class="fas fa-edit"></i></button>
                <button class="delete-task" data-task-id="${task.id}"><i class="fas fa-trash"></i></button>
            </div>
        `;

        // Add event listeners for drag and drop
        taskElement.addEventListener('dragstart', () => {
            taskElement.classList.add('dragging');
        });

        taskElement.addEventListener('dragend', () => {
            taskElement.classList.remove('dragging');
        });

        // Add event listeners for edit and delete buttons
        taskElement.querySelector('.edit-task').addEventListener('click', function(e) {
            e.stopPropagation();
            openTaskModal(task.id, task.status);
        });

        taskElement.querySelector('.delete-task').addEventListener('click', function(e) {
            e.stopPropagation();
            if (confirm('Are you sure you want to delete this task?')) {
                deleteTask(task.id);
            }
        });

        return taskElement;
    }

    // Delete task
    function deleteTask(taskId) {
        tasks = tasks.filter(task => task.id !== taskId);
        const taskElement = document.querySelector(`[data-task-id="${taskId}"]`);
        if (taskElement) {
            taskElement.remove();
        }
        socket.emit('taskDeleted', taskId);
        updateTaskCounts();
    }

    // Update task counts in column headers
    function updateTaskCounts() {
        const columns = document.querySelectorAll('.column');

        columns.forEach(column => {
            const status = column.getAttribute('data-status');
            const taskCount = tasks.filter(task => task.status === status).length;
            column.querySelector('.task-count').textContent = taskCount;
        });
    }

    // Format date for display
    function formatDate(dateString) {
        if (!dateString) return '';
        const options = { year: 'numeric', month: 'short', day: 'numeric' };
        return new Date(dateString).toLocaleDateString(undefined, options);
    }

    // Initialize the app
    initSampleTasks();
});
