## JavaScript (app.js)

```javascript
// Firebase configuration (replace with your own config)
const firebaseConfig = {
    apiKey: "YOUR_API_KEY",
    authDomain: "YOUR_AUTH_DOMAIN",
    databaseURL: "YOUR_DATABASE_URL",
    projectId: "YOUR_PROJECT_ID",
    storageBucket: "YOUR_STORAGE_BUCKET",
    messagingSenderId: "YOUR_MESSAGING_SENDER_ID",
    appId: "YOUR_APP_ID"
};

// Initialize Firebase
firebase.initializeApp(firebaseConfig);
const database = firebase.database();

// DOM elements
const boardContainer = document.getElementById('board-container');
const addColumnBtn = document.getElementById('add-column-btn');
const newColumnName = document.getElementById('new-column-name');
const taskModal = document.getElementById('task-modal');
const closeModal = document.querySelector('.close-modal');
const taskTitle = document.getElementById('task-title');
const taskDescription = document.getElementById('task-description');
const saveTaskBtn = document.getElementById('save-task-btn');
const deleteTaskBtn = document.getElementById('delete-task-btn');
const loginBtn = document.getElementById('login-btn');
const userName = document.getElementById('user-name');

// Current task being edited
let currentTask = null;
let currentColumnId = null;

// Initialize the board
function initBoard() {
    // Listen for changes in the database
    database.ref('columns').on('value', (snapshot) => {
        boardContainer.innerHTML = '';
        const columns = snapshot.val() || {};

        // Sort columns by order
        const sortedColumns = Object.entries(columns).sort((a, b) => a[1].order - b[1].order);

        sortedColumns.forEach(([columnId, columnData]) => {
            addColumnToDOM(columnId, columnData.name, columnData.tasks || {});
        });

        // Initialize drag and drop for all columns
        initDragAndDrop();
    });
}

// Add a new column to the DOM
function addColumnToDOM(columnId, columnName, tasks = {}) {
    const column = document.createElement('div');
    column.className = 'column';
    column.dataset.columnId = columnId;

    column.innerHTML = `
        <div class="column-header">
            <span class="column-title">${columnName}</span>
            <div class="column-actions">
                <button class="delete-column-btn" data-column-id="${columnId}">
                    <i class="fas fa-trash"></i>
                </button>
            </div>
        </div>
        <div class="column-body">
            ${Object.entries(tasks).map(([taskId, taskData]) => `
                <div class="task" data-task-id="${taskId}" draggable="true">
                    <div class="task-title">${taskData.title}</div>
                    <div class="task-description">${taskData.description || ''}</div>
                </div>
            `).join('')}
            <div class="add-task-btn" data-column-id="${columnId}">+ Add Task</div>
        </div>
    `;

    boardContainer.appendChild(column);

    // Add event listeners for the new column
    column.querySelector('.delete-column-btn').addEventListener('click', () => deleteColumn(columnId));
    column.querySelector('.add-task-btn').addEventListener('click', () => openTaskModal(columnId));
}

// Initialize drag and drop functionality
function initDragAndDrop() {
    const columns = document.querySelectorAll('.column-body');

    columns.forEach(column => {
        new Sortable(column, {
            group: 'shared',
            animation: 150,
            ghostClass: 'sortable-ghost',
            onEnd: function (evt) {
                const taskId = evt.item.dataset.taskId;
                const fromColumnId = evt.from.parentElement.dataset.columnId;
                const toColumnId = evt.to.parentElement.dataset.columnId;

                if (fromColumnId !== toColumnId) {
                    // Task moved to a different column
                    moveTask(taskId, fromColumnId, toColumnId);
                }
            }
        });
    });
}

// Add a new column
addColumnBtn.addEventListener('click', () => {
    const columnName = newColumnName.value.trim();
    if (columnName) {
        const newColumnRef = database.ref('columns').push();
        newColumnRef.set({
            name: columnName,
            order: Date.now(),
            tasks: {}
        });
        newColumnName.value = '';
    }
});

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column?')) {
        database.ref(`columns/${columnId}`).remove();
    }
}

// Open task modal for adding or editing a task
function openTaskModal(columnId, taskId = null) {
    currentColumnId = columnId;
    currentTask = taskId;

    if (taskId) {
        // Editing existing task
        const taskRef = database.ref(`columns/${columnId}/tasks/${taskId}`);
        taskRef.once('value', (snapshot) => {
            const taskData = snapshot.val();
            taskTitle.value = taskData.title || '';
            taskDescription.value = taskData.description || '';
        });
    } else {
        // Adding new task
        taskTitle.value = '';
        taskDescription.value = '';
    }

    taskModal.style.display = 'flex';
}

// Close task modal
closeModal.addEventListener('click', () => {
    taskModal.style.display = 'none';
});

// Save task
saveTaskBtn.addEventListener('click', () => {
    const title = taskTitle.value.trim();
    const description = taskDescription.value.trim();

    if (!title) {
        alert('Please enter a task title');
        return;
    }

    if (currentTask) {
        // Update existing task
        database.ref(`columns/${currentColumnId}/tasks/${currentTask}`).update({
            title,
            description
        });
    } else {
        // Add new task
        const newTaskRef = database.ref(`columns/${currentColumnId}/tasks`).push();
        newTaskRef.set({
            title,
            description,
            order: Date.now()
        });
    }

    taskModal.style.display = 'none';
});

// Delete task
deleteTaskBtn.addEventListener('click', () => {
    if (currentTask && confirm('Are you sure you want to delete this task?')) {
        database.ref(`columns/${currentColumnId}/tasks/${currentTask}`).remove();
        taskModal.style.display = 'none';
    }
});

// Move task between columns
function moveTask(taskId, fromColumnId, toColumnId) {
    const taskRef = database.ref(`columns/${fromColumnId}/tasks/${taskId}`);

    taskRef.once('value', (snapshot) => {
        const taskData = snapshot.val();

        // Remove from old column
        taskRef.remove();

        // Add to new column
        const newTaskRef = database.ref(`columns/${toColumnId}/tasks`).push();
        newTaskRef.set({
            ...taskData,
            order: Date.now()
        });
    });
}

// Event delegation for task clicks
boardContainer.addEventListener('click', (e) => {
    if (e.target.closest('.task')) {
        const taskElement = e.target.closest('.task');
        const taskId = taskElement.dataset.taskId;
        const columnId = taskElement.closest('.column').dataset.columnId;
        openTaskModal(columnId, taskId);
    }
});

// Initialize the app
initBoard();
```

## Features

1. **Drag-and-Drop Interface**:
   - Tasks can be dragged between columns
   - Uses SortableJS for smooth drag-and-drop functionality

2. **Real-time Collaboration**:
   - Firebase Realtime Database for synchronization
   - Changes made by one user are instantly visible to others

3. **Basic Functionality**:
   - Create, edit, and delete tasks
   - Create and delete columns
   - Task details include title and description

4. **Responsive Design**:
   - Works on mobile and desktop devices

