## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', () => {
    const socket = io();
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const userCountElement = document.getElementById('user-count');

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('dragenter', dragEnter);
        list.addEventListener('dragleave', dragLeave);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskButtons.forEach(button => {
        button.addEventListener('click', () => {
            const column = button.getAttribute('data-column');
            const taskText = prompt('Enter task description:');
            if (taskText) {
                const taskId = Date.now().toString();
                const task = {
                    id: taskId,
                    text: taskText,
                    column: column
                };
                socket.emit('addTask', task);
            }
        });
    });

    // Socket.IO events
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('taskAdded', (task) => {
        addTaskToDOM(task);
    });

    socket.on('taskMoved', (task) => {
        moveTaskInDOM(task);
    });

    socket.on('taskDeleted', (taskId) => {
        deleteTaskFromDOM(taskId);
    });

    socket.on('userCount', (count) => {
        userCountElement.textContent = count;
    });

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.id);
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }

    function dragEnd(e) {
        e.target.classList.remove('dragging');
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function dragEnter(e) {
        e.preventDefault();
        e.target.classList.add('drag-over');
    }

    function dragLeave(e) {
        e.target.classList.remove('drag-over');
    }

    function drop(e) {
        e.preventDefault();
        e.target.classList.remove('drag-over');

        const taskId = e.dataTransfer.getData('text/plain');
        const taskElement = document.getElementById(taskId);
        const newColumn = e.target.closest('.column').id;

        if (taskElement && newColumn) {
            const task = {
                id: taskId,
                text: taskElement.textContent,
                column: newColumn
            };
            socket.emit('moveTask', task);
        }
    }

    // DOM manipulation functions
    function addTaskToDOM(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.id = task.id;
        taskElement.textContent = task.text;
        taskElement.draggable = true;

        taskElement.addEventListener('dragstart', dragStart);
        taskElement.addEventListener('dragend', dragEnd);

        // Add delete button
        const deleteBtn = document.createElement('button');
        deleteBtn.textContent = '×';
        deleteBtn.style.float = 'right';
        deleteBtn.style.background = 'none';
        deleteBtn.style.border = 'none';
        deleteBtn.style.cursor = 'pointer';
        deleteBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            socket.emit('deleteTask', task.id);
        });

        taskElement.appendChild(deleteBtn);

        const list = document.getElementById(`${task.column}-list`);
        list.appendChild(taskElement);
    }

    function moveTaskInDOM(task) {
        const taskElement = document.getElementById(task.id);
        if (taskElement) {
            const newList = document.getElementById(`${task.column}-list`);
            if (newList) {
                newList.appendChild(taskElement);
            }
        }
    }

    function deleteTaskFromDOM(taskId) {
        const taskElement = document.getElementById(taskId);
        if (taskElement) {
            taskElement.remove();
        }
    }
});
```

## 4. server.js
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

let tasks = [];
let userCount = 0;

// Serve static files
app.use(express.static(__dirname));

io.on('connection', (socket) => {
    userCount++;
    io.emit('userCount', userCount);

    // Send existing tasks to new user
    socket.emit('initialTasks', tasks);

    socket.on('addTask', (task) => {
        tasks.push(task);
        io.emit('taskAdded', task);
    });

    socket.on('moveTask', (task) => {
        const index = tasks.findIndex(t => t.id === task.id);
        if (index !== -1) {
            tasks[index].column = task.column;
            io.emit('taskMoved', task);
        }
    });

    socket.on('deleteTask', (taskId) => {
        tasks = tasks.filter(task => task.id !== taskId);
        io.emit('taskDeleted', taskId);
    });

    socket.on('disconnect', () => {
        userCount--;
        io.emit('userCount', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
```

