```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.IO connection
    const socket = io();

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskBtns = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescInput = document.getElementById('task-description');
    const userCountSpan = document.getElementById('user-count');

    // Current task being edited (null for new tasks)
    let currentTask = null;
    let currentColumn = null;

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('drop', drop);
    });

    // Add task button click handlers
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            currentTask = null;
            currentColumn = this.getAttribute('data-column');
            taskTitleInput.value = '';
            taskDescInput.value = '';
            taskModal.style.display = 'block';
        });
    });

    // Close modal
    closeModal.addEventListener('click', function() {
        taskModal.style.display = 'none';
    });

    // Save task
    saveTaskBtn.addEventListener('click', function() {
        const title = taskTitleInput.value.trim();
        const description = taskDescInput.value.trim();

        if (title) {
            if (currentTask) {
                // Update existing task
                currentTask.querySelector('h3').textContent = title;
                currentTask.querySelector('p').textContent = description;

                // Emit update to server
                socket.emit('update-task', {
                    id: currentTask.getAttribute('data-id'),
                    title,
                    description,
                    column: currentTask.parentElement.id
                });
            } else {
                // Create new task
                const taskId = Date.now().toString();
                const taskElement = createTaskElement(taskId, title, description);

                document.getElementById(`${currentColumn}-list`).appendChild(taskElement);

                // Emit new task to server
                socket.emit('new-task', {
                    id: taskId,
                    title,
                    description,
                    column: currentColumn
                });
            }

            taskModal.style.display = 'none';
        }
    });

    // Socket.IO event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('user-count', (count) => {
        userCountSpan.textContent = count;
    });

    socket.on('new-task', (task) => {
        if (!document.querySelector(`[data-id="${task.id}"]`)) {
            const taskElement = createTaskElement(task.id, task.title, task.description);
            document.getElementById(`${task.column}-list`).appendChild(taskElement);
        }
    });

    socket.on('update-task', (task) => {
        const existingTask = document.querySelector(`[data-id="${task.id}"]`);
        if (existingTask) {
            existingTask.querySelector('h3').textContent = task.title;
            existingTask.querySelector('p').textContent = task.description;

            // Move to correct column if needed
            const currentColumn = existingTask.parentElement.id;
            if (currentColumn !== task.column) {
                document.getElementById(`${task.column}-list`).appendChild(existingTask);
            }
        }
    });

    socket.on('delete-task', (taskId) => {
        const taskElement = document.querySelector(`[data-id="${taskId}"]`);
        if (taskElement) {
            taskElement.remove();
        }
    });

    // Helper function to create task element
    function createTaskElement(id, title, description) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.setAttribute('draggable', 'true');
        taskElement.setAttribute('data-id', id);

        taskElement.innerHTML = `
            <h3>${title}</h3>
            <p>${description}</p>
            <div class="task-actions">
                <button class="edit-task">Edit</button>
                <button class="delete-task">Delete</button>
            </div>
        `;

        // Add event listeners
        taskElement.addEventListener('dragstart', dragStart);
        taskElement.querySelector('.edit-task').addEventListener('click', function(e) {
            e.stopPropagation();
            currentTask = taskElement;
            currentColumn = taskElement.parentElement.id;
            taskTitleInput.value = taskElement.querySelector('h3').textContent;
            taskDescInput.value = taskElement.querySelector('p').textContent;
            taskModal.style.display = 'block';
        });

        taskElement.querySelector('.delete-task').addEventListener('click', function(e) {
            e.stopPropagation();
            if (confirm('Delete this task?')) {
                taskElement.remove();
                socket.emit('delete-task', id);
            }
        });

        return taskElement;
    }

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.getAttribute('data-id'));
        e.target.classList.add('dragging');
        setTimeout(() => {
            e.target.style.display = 'none';
        }, 0);
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function drop(e) {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const taskElement = document.querySelector(`[data-id="${taskId}"]`);

        if (taskElement) {
            taskElement.style.display = 'block';
            taskElement.classList.remove('dragging');
            e.target.appendChild(taskElement);

            // Emit move event to server
            socket.emit('move-task', {
                id: taskId,
                column: e.target.id
            });
        }
    }
});
```

## 4. server.js
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// Serve static files
app.use(express.static(__dirname));

// Store tasks in memory (for demo purposes)
let tasks = [];
let userCount = 0;

io.on('connection', (socket) => {
    userCount++;
    io.emit('user-count', userCount);

    // Send all existing tasks to the new client
    socket.emit('initial-tasks', tasks);

    // Handle new task
    socket.on('new-task', (task) => {
        tasks.push(task);
        socket.broadcast.emit('new-task', task);
    });

    // Handle task update
    socket.on('update-task', (task) => {
        const index = tasks.findIndex(t => t.id === task.id);
        if (index !== -1) {
            tasks[index] = task;
            socket.broadcast.emit('update-task', task);
        }
    });

    // Handle task move
    socket.on('move-task', (data) => {
        const index = tasks.findIndex(t => t.id === data.id);
        if (index !== -1) {
            tasks[index].column = data.column;
            socket.broadcast.emit('update-task', tasks[index]);
        }
    });

    // Handle task deletion
    socket.on('delete-task', (taskId) => {
        tasks = tasks.filter(t => t.id !== taskId);
        socket.broadcast.emit('delete-task', taskId);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        userCount--;
        io.emit('user-count', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
