const closeModalBtn = document.querySelector('.close-btn');
const taskForm = document.getElementById('task-form');
const loginBtn = document.getElementById('login-btn');
const userNameDisplay = document.getElementById('user-name');

// Sample initial data
const initialColumns = [
    { id: 'todo', title: 'To Do' },
    { id: 'in-progress', title: 'In Progress' },
    { id: 'done', title: 'Done' }
];

// Initialize the app
function initApp() {
    // Check auth state
    auth.onAuthStateChanged(user => {
        if (user) {
            userNameDisplay.textContent = user.displayName || user.email;
            loginBtn.textContent = 'Logout';
            loadBoardData();
        } else {
            userNameDisplay.textContent = 'Guest';
            loginBtn.textContent = 'Login';
            loadBoardData(); // Load without auth for demo purposes
        }
    });

    // Set up event listeners
    addColumnBtn.addEventListener('click', addNewColumn);
    closeModalBtn.addEventListener('click', closeModal);
    taskForm.addEventListener('submit', saveTask);
    loginBtn.addEventListener('click', toggleAuth);

    // Initialize with sample columns if none exist
    db.collection('columns').get().then(snapshot => {
        if (snapshot.empty) {
            initialColumns.forEach(column => {
                db.collection('columns').doc(column.id).set(column);
            });
        }
    });
}

// Load board data from Firestore
function loadBoardData() {
    // Clear existing columns
    boardContainer.innerHTML = '';

    // Load columns
    db.collection('columns').orderBy('title').onSnapshot(snapshot => {
        snapshot.docChanges().forEach(change => {
            if (change.type === 'added') {
                createColumnElement(change.doc.id, change.doc.data().title);
            } else if (change.type === 'modified') {
                const columnElement = document.getElementById(`column-${change.doc.id}`);
                if (columnElement) {
                    columnElement.querySelector('.column-title').textContent = change.doc.data().title;
                }
            } else if (change.type === 'removed') {
                const columnElement = document.getElementById(`column-${change.doc.id}`);
                if (columnElement) {
                    columnElement.remove();
                }
            }
        });

        // Initialize sortable for all columns
        document.querySelectorAll('.task-list').forEach(taskList => {
            new Sortable(taskList, {
                group: 'tasks',
                animation: 150,
                ghostClass: 'sortable-ghost',
                chosenClass: 'sortable-chosen',
                onEnd: function(evt) {
                    const taskId = evt.item.id.replace('task-', '');
                    const newColumnId = evt.to.closest('.column').id.replace('column-', '');
                    updateTaskColumn(taskId, newColumnId);
                }
            });
        });
    });

    // Load tasks
    db.collection('tasks').onSnapshot(snapshot => {
        snapshot.docChanges().forEach(change => {
            if (change.type === 'added') {
                createTaskElement(change.doc.id, change.doc.data());
            } else if (change.type === 'modified') {
                updateTaskElement(change.doc.id, change.doc.data());
            } else if (change.type === 'removed') {
                const taskElement = document.getElementById(`task-${change.doc.id}`);
                if (taskElement) {
                    taskElement.remove();
                }
            }
        });
    });
}

// Create a column element
function createColumnElement(columnId, columnTitle) {
    const columnElement = document.createElement('div');
    columnElement.className = 'column';
    columnElement.id = `column-${columnId}`;

    columnElement.innerHTML = `
        <div class="column-header">
            <span class="column-title">${columnTitle}</span>
            <div class="column-actions">
                <button class="edit-column-btn" title="Edit column"><i class="fas fa-pencil-alt"></i></button>
                <button class="delete-column-btn" title="Delete column"><i class="fas fa-trash"></i></button>
            </div>
        </div>
        <div class="task-list" id="task-list-${columnId}"></div>
        <button class="add-task-btn" data-column-id="${columnId}">
            <i class="fas fa-plus"></i> Add Task
        </button>
    `;

    boardContainer.appendChild(columnElement);

    // Set up column event listeners
    columnElement.querySelector('.edit-column-btn').addEventListener('click', () => editColumn(columnId));
    columnElement.querySelector('.delete-column-btn').addEventListener('click', () => deleteColumn(columnId));
    columnElement.querySelector('.add-task-btn').addEventListener('click', () => openTaskModal(columnId));
}

// Create a task element
function createTaskElement(taskId, taskData) {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.id = `task-${taskId}`;

    taskElement.innerHTML = `
        <div class="task-title">${taskData.title}</div>
        <div class="task-meta">
            <span>${taskData.assignee || ''}</span>
            <span>${taskData.dueDate || ''}</span>
        </div>
    `;

    taskElement.addEventListener('click', () => openTaskModal(taskData.columnId, taskId));

    const taskList = document.getElementById(`task-list-${taskData.columnId}`);
    if (taskList) {
        taskList.appendChild(taskElement);
    }
}

// Update a task element
function updateTaskElement(taskId, taskData) {
    const taskElement = document.getElementById(`task-${taskId}`);
    if (taskElement) {
        taskElement.querySelector('.task-title').textContent = taskData.title;
        taskElement.querySelector('.task-meta').innerHTML = `
            <span>${taskData.assignee || ''}</span>
            <span>${taskData.dueDate || ''}</span>
        `;
    }
}

// Add a new column
function addNewColumn() {
    const columnTitle = prompt('Enter column title:');
    if (columnTitle) {
        const columnId = `col-${Date.now()}`;
        db.collection('columns').doc(columnId).set({
            title: columnTitle
        });
    }
}

// Edit a column
function editColumn(columnId) {
    const columnElement = document.getElementById(`column-${columnId}`);
    const currentTitle = columnElement.querySelector('.column-title').textContent;
    const newTitle = prompt('Edit column title:', currentTitle);

    if (newTitle && newTitle !== currentTitle) {
        db.collection('columns').doc(columnId).update({
            title: newTitle
        });
    }
}

// Delete a column
function deleteColumn(columnId) {
    if (confirm('Are you sure you want to delete this column and all its tasks?')) {
        // First delete all tasks in this column
        db.collection('tasks').where('columnId', '==', columnId).get()
            .then(snapshot => {
                const batch = db.batch();
                snapshot.docs.forEach(doc => {
                    batch.delete(doc.ref);
                });
                return batch.commit();
            })
            .then(() => {
                // Then delete the column
                return db.collection('columns').doc(columnId).delete();
            })
            .catch(error => {
                console.error('Error deleting column:', error);
            });
    }
}

// Open task modal
function openTaskModal(columnId, taskId = null) {
    const modalTitle = document.querySelector('#task-modal h2');
    const taskIdInput = document.getElementById('task-id');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const taskAssigneeInput = document.getElementById('task-assignee');
    const taskDueDateInput = document.getElementById('task-due-date');

    if (taskId) {
        // Editing existing task
        modalTitle.textContent = 'Edit Task';
        taskIdInput.value = taskId;

        // Get task data from Firestore
        db.collection('tasks').doc(taskId).get().then(doc => {
            if (doc.exists) {
                const taskData = doc.data();
                taskTitleInput.value = taskData.title || '';
                taskDescriptionInput.value = taskData.description || '';
                taskAssigneeInput.value = taskData.assignee || '';
                taskDueDateInput.value = taskData.dueDate || '';
            }
        });
    } else {
        // Creating new task
        modalTitle.textContent = 'Add New Task';
        taskIdInput.value = '';
        taskTitleInput.value = '';
        taskDescriptionInput.value = '';
        taskAssigneeInput.value = '';
        taskDueDateInput.value = '';
    }

    // Store columnId in a data attribute for saving
    taskForm.dataset.columnId = columnId;

    taskModal.style.display = 'block';
}

// Close modal
function closeModal() {
    taskModal.style.display = 'none';
}

// Save task
function saveTask(e) {
    e.preventDefault();

    const taskId = document.getElementById('task-id').value;
    const columnId = taskForm.dataset.columnId;
    const title = document.getElementById('task-title').value;
    const description = document.getElementById('task-description').value;
    const assignee = document.getElementById('task-assignee').value;
    const dueDate = document.getElementById('task-due-date').value;

    const taskData = {
        title,
        description,
        assignee,
        dueDate,
        columnId,
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
    };

    if (taskId) {
        // Update existing task
        db.collection('tasks').doc(taskId).update(taskData);
    } else {
        // Create new task
        db.collection('tasks').add(taskData);
    }

    closeModal();
}

// Update task column when dragged
function updateTaskColumn(taskId, newColumnId) {
    db.collection('tasks').doc(taskId).update({
        columnId: newColumnId
    });
}

// Toggle authentication
function toggleAuth() {
    if (auth.currentUser) {
        auth.signOut();
    } else {
        // Simple email/password auth for demo
        const email = prompt('Enter your email:');
        const password = prompt('Enter your password:');

        if (email && password) {
            auth.signInWithEmailAndPassword(email, password)
                .catch(error => {
                    alert(error.message);
                });
        }
    }
}

// Initialize the app when the page loads
document.addEventListener('DOMContentLoaded', initApp);
```

