## 3. script.js
```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskBtns = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');
    const userCountSpan = document.getElementById('user-count');

    // Task data
    let tasks = [];
    let currentTaskId = null;
    let currentColumn = null;

    // Initialize drag and drop
    function initDragAndDrop() {
        taskLists.forEach(list => {
            list.addEventListener('dragover', (e) => {
                e.preventDefault();
                const afterElement = getDragAfterElement(list, e.clientY);
                const draggable = document.querySelector('.dragging');

                if (afterElement == null) {
                    list.appendChild(draggable);
                } else {
                    list.insertBefore(draggable, afterElement);
                }
            });
        });

        document.querySelectorAll('.task').forEach(task => {
            task.addEventListener('dragstart', () => {
                task.classList.add('dragging');
            });

            task.addEventListener('dragend', () => {
                task.classList.remove('dragging');

                // Update task status in the backend
                const newStatus = task.closest('.column').dataset.status;
                const taskId = task.dataset.id;

                socket.emit('updateTaskStatus', {
                    id: taskId,
                    status: newStatus
                });
            });
        });
    }

    function getDragAfterElement(container, y) {
        const draggableElements = [...container.querySelectorAll('.task:not(.dragging)')];

        return draggableElements.reduce((closest, child) => {
            const box = child.getBoundingClientRect();
            const offset = y - box.top - box.height / 2;

            if (offset < 0 && offset > closest.offset) {
                return { offset: offset, element: child };
            } else {
                return closest;
            }
        }, { offset: Number.NEGATIVE_INFINITY }).element;
    }

    // Render tasks
    function renderTasks() {
        taskLists.forEach(list => {
            list.innerHTML = '';
        });

        tasks.forEach(task => {
            const taskElement = document.createElement('div');
            taskElement.className = 'task';
            taskElement.draggable = true;
            taskElement.dataset.id = task.id;

            taskElement.innerHTML = `
                <h3>${task.title}</h3>
                <p>${task.description}</p>
            `;

            taskElement.addEventListener('click', (e) => {
                if (!e.target.closest('.task')) return;

                currentTaskId = task.id;
                taskTitleInput.value = task.title;
                taskDescriptionInput.value = task.description;
                taskModal.style.display = 'block';
            });

            const columnId = `${task.status}-tasks`;
            document.getElementById(columnId).appendChild(taskElement);
        });

        initDragAndDrop();
    }

    // Event listeners
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            currentTaskId = null;
            currentColumn = btn.closest('.column').dataset.status;
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
            taskModal.style.display = 'block';
        });
    });

    closeModal.addEventListener('click', () => {
        taskModal.style.display = 'none';
    });

    saveTaskBtn.addEventListener('click', () => {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (!title) return;

        if (currentTaskId) {
            // Update existing task
            socket.emit('updateTask', {
                id: currentTaskId,
                title,
                description
            });
        } else {
            // Create new task
            const newTask = {
                id: Date.now().toString(),
                title,
                description,
                status: currentColumn
            };

            socket.emit('addTask', newTask);
        }

        taskModal.style.display = 'none';
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('initialData', (data) => {
        tasks = data.tasks;
        renderTasks();
    });

    socket.on('taskAdded', (task) => {
        tasks.push(task);
        renderTasks();
    });

    socket.on('taskUpdated', (updatedTask) => {
        tasks = tasks.map(task =>
            task.id === updatedTask.id ? updatedTask : task
        );
        renderTasks();
    });

    socket.on('taskStatusUpdated', (data) => {
        tasks = tasks.map(task =>
            task.id === data.id ? { ...task, status: data.status } : task
        );
        renderTasks();
    });

    socket.on('userCount', (count) => {
        userCountSpan.textContent = count;
    });

    // Close modal when clicking outside
    window.addEventListener('click', (e) => {
        if (e.target === taskModal) {
            taskModal.style.display = 'none';
        }
    });
});
```

## 4. server.js
```javascript
const express = require('express');
const http = require('http');
const socketIo = require('socket.io');

const app = express();
const server = http.createServer(app);
const io = socketIo(server);

// In-memory storage for tasks
let tasks = [];
let userCount = 0;

// Serve static files
app.use(express.static(__dirname));

// Socket.io connection
io.on('connection', (socket) => {
    userCount++;
    io.emit('userCount', userCount);

    // Send initial data to the new client
    socket.emit('initialData', { tasks });

    // Handle task creation
    socket.on('addTask', (task) => {
        tasks.push(task);
        io.emit('taskAdded', task);
    });

    // Handle task updates
    socket.on('updateTask', (updatedTask) => {
        tasks = tasks.map(task =>
            task.id === updatedTask.id ? updatedTask : task
        );
        io.emit('taskUpdated', updatedTask);
    });

    // Handle task status updates
    socket.on('updateTaskStatus', (data) => {
        tasks = tasks.map(task =>
            task.id === data.id ? { ...task, status: data.status } : task
        );
        io.emit('taskStatusUpdated', data);
    });

    // Handle disconnection
    socket.on('disconnect', () => {
        userCount--;
        io.emit('userCount', userCount);
    });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});
