document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // Generate a random user ID for this session
    const userId = 'user-' + Math.floor(Math.random() * 10000);
    document.getElementById('current-user').textContent = userId;

    // DOM elements
    const taskLists = document.querySelectorAll('.task-list');
    const addTaskButtons = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const closeModal = document.querySelector('.close-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const taskTitleInput = document.getElementById('task-title');
    const taskDescriptionInput = document.getElementById('task-description');

    // Current task being edited (null for new tasks)
    let currentTaskId = null;
    let currentStatus = null;

    // Initialize drag and drop
    taskLists.forEach(list => {
        list.addEventListener('dragover', dragOver);
        list.addEventListener('drop', drop);
    });

    // Add task buttons
    addTaskButtons.forEach(button => {
        button.addEventListener('click', () => {
            currentTaskId = null;
            currentStatus = button.getAttribute('data-status');
            taskTitleInput.value = '';
            taskDescriptionInput.value = '';
            taskModal.style.display = 'flex';
        });
    });

    // Close modal
    closeModal.addEventListener('click', () => {
        taskModal.style.display = 'none';
    });

    // Save task
    saveTaskBtn.addEventListener('click', () => {
        const title = taskTitleInput.value.trim();
        const description = taskDescriptionInput.value.trim();

        if (!title) {
            alert('Please enter a task title');
            return;
        }

        if (currentTaskId) {
            // Update existing task
            const taskElement = document.getElementById(currentTaskId);
            taskElement.querySelector('h4').textContent = title;
            taskElement.querySelector('p').textContent = description;

            // Emit update to server
            socket.emit('updateTask', {
                id: currentTaskId,
                title,
                description,
                status: currentStatus,
                userId
            });
        } else {
            // Create new task
            const taskId = 'task-' + Date.now();
            const taskElement = createTaskElement(taskId, title, description, currentStatus, userId);

            // Add to the appropriate list
            const taskList = document.querySelector(`.task-list[data-status="${currentStatus}"]`);
            taskList.appendChild(taskElement);

            // Emit new task to server
            socket.emit('newTask', {
                id: taskId,
                title,
                description,
                status: currentStatus,
                userId
            });
        }

        taskModal.style.display = 'none';
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('userCount', (count) => {
        document.getElementById('online-users').textContent = `Online: ${count}`;
    });

    socket.on('taskAdded', (task) => {
        if (task.userId !== userId) {
            const taskElement = createTaskElement(task.id, task.title, task.description, task.status, task.userId);
            const taskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
            taskList.appendChild(taskElement);
        }
    });

    socket.on('taskUpdated', (task) => {
        if (task.userId !== userId) {
            const taskElement = document.getElementById(task.id);
            if (taskElement) {
                taskElement.querySelector('h4').textContent = task.title;
                taskElement.querySelector('p').textContent = task.description;

                // If status changed, move the task
                if (taskElement.closest('.task-list').getAttribute('data-status') !== task.status) {
                    const newTaskList = document.querySelector(`.task-list[data-status="${task.status}"]`);
                    newTaskList.appendChild(taskElement);
                }
            }
        }
    });

    socket.on('taskDeleted', (taskId) => {
        const taskElement = document.getElementById(taskId);
        if (taskElement) {
            taskElement.remove();
        }
    });

    // Helper functions
    function createTaskElement(id, title, description, status, creatorId) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task';
        taskElement.id = id;
        taskElement.draggable = true;
        taskElement.setAttribute('data-status', status);

        taskElement.innerHTML = `
            <h4>${title}</h4>
            <p>${description}</p>
            <div class="task-meta">
                <span><i class="fas fa-user"></i> ${creatorId}</span>
                <span><i class="fas fa-clock"></i> ${new Date().toLocaleString()}</span>
            </div>
        `;

        // Add event listeners
        taskElement.addEventListener('dragstart', dragStart);
        taskElement.addEventListener('click', () => {
            currentTaskId = id;
            currentStatus = status;
            taskTitleInput.value = title;
            taskDescriptionInput.value = description;
            taskModal.style.display = 'flex';
        });

        return taskElement;
    }

    // Drag and drop functions
    function dragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.id);
        setTimeout(() => {
            e.target.classList.add('dragging');
        }, 0);
    }

    function dragOver(e) {
        e.preventDefault();
    }

    function drop(e) {
        e.preventDefault();
        const taskId = e.dataTransfer.getData('text/plain');
        const taskElement = document.getElementById(taskId);
        const newStatus = e.currentTarget.getAttribute('data-status');

        if (taskElement && newStatus) {
            // Update the task's status
            taskElement.setAttribute('data-status', newStatus);

            // Move the task to the new list
            e.currentTarget.appendChild(taskElement);

            // Remove dragging class
            taskElement.classList.remove('dragging');

            // Emit the update to the server
            socket.emit('updateTask', {
                id: taskId,
                title: taskElement.querySelector('h4').textContent,
                description: taskElement.querySelector('p').textContent,
                status: newStatus,
                userId
            });
        }
    }
});
