document.addEventListener('DOMContentLoaded', function() {
    // Initialize Socket.io connection
    const socket = io();

    // DOM elements
    const taskLists = {
        todo: document.getElementById('todo-list'),
        'in-progress': document.getElementById('in-progress-list'),
        done: document.getElementById('done-list')
    };

    const addTaskBtns = document.querySelectorAll('.add-task-btn');
    const taskModal = document.getElementById('task-modal');
    const saveTaskBtn = document.getElementById('save-task');
    const cancelTaskBtn = document.getElementById('cancel-task');
    const userCountDisplay = document.getElementById('user-count');

    let currentColumn = null;

    // Sample initial tasks
    let tasks = [
        { id: '1', title: 'Design homepage', description: 'Create wireframe for main page', status: 'todo' },
        { id: '2', title: 'Implement API', description: 'Set up backend endpoints', status: 'in-progress' },
        { id: '3', title: 'Write documentation', description: 'Document API usage', status: 'done' }
    ];

    // Initialize the board
    function initBoard() {
        // Clear all lists
        Object.values(taskLists).forEach(list => list.innerHTML = '');

        // Add tasks to their respective columns
        tasks.forEach(task => {
            const taskElement = createTaskElement(task);
            taskLists[task.status].appendChild(taskElement);
        });

        // Set up drag and drop
        setupDragAndDrop();
    }

    // Create a task element
    function createTaskElement(task) {
        const taskElement = document.createElement('div');
        taskElement.className = 'task-card';
        taskElement.draggable = true;
        taskElement.dataset.id = task.id;

        taskElement.innerHTML = `
            <h3>${task.title}</h3>
            <p>${task.description}</p>
        `;

        // Set up drag events
        taskElement.addEventListener('dragstart', handleDragStart);
        taskElement.addEventListener('dragend', handleDragEnd);

        return taskElement;
    }

    // Set up drag and drop functionality
    function setupDragAndDrop() {
        const columns = document.querySelectorAll('.board-column');

        columns.forEach(column => {
            column.addEventListener('dragover', handleDragOver);
            column.addEventListener('dragenter', handleDragEnter);
            column.addEventListener('dragleave', handleDragLeave);
            column.addEventListener('drop', handleDrop);
        });
    }

    // Drag and drop event handlers
    function handleDragStart(e) {
        e.dataTransfer.setData('text/plain', e.target.dataset.id);
        e.target.classList.add('dragging');
        setTimeout(() => {
            e.target.style.display = 'none';
        }, 0);
    }

    function handleDragEnd(e) {
        e.target.classList.remove('dragging');
        e.target.style.display = 'block';
    }

    function handleDragOver(e) {
        e.preventDefault();
    }

    function handleDragEnter(e) {
        e.preventDefault();
        e.currentTarget.classList.add('drag-over');
    }

    function handleDragLeave(e) {
        e.currentTarget.classList.remove('drag-over');
    }

    function handleDrop(e) {
        e.preventDefault();
        e.currentTarget.classList.remove('drag-over');

        const taskId = e.dataTransfer.getData('text/plain');
        const newStatus = e.currentTarget.dataset.status;

        // Update task status
        const taskIndex = tasks.findIndex(t => t.id === taskId);
        if (taskIndex !== -1) {
            tasks[taskIndex].status = newStatus;

            // Emit update to server
            socket.emit('taskUpdate', tasks[taskIndex]);

            // Re-render the board
            initBoard();
        }
    }

    // Add task button click handler
    addTaskBtns.forEach(btn => {
        btn.addEventListener('click', function() {
            currentColumn = this.closest('.board-column').dataset.status;
            taskModal.style.display = 'flex';
        });
    });

    // Save task handler
    saveTaskBtn.addEventListener('click', function() {
        const title = document.getElementById('task-title').value;
        const description = document.getElementById('task-description').value;

        if (title.trim() === '') return;

        const newTask = {
            id: Date.now().toString(),
            title: title.trim(),
            description: description.trim(),
            status: currentColumn
        };

        // Add to local tasks array
        tasks.push(newTask);

        // Emit to server
        socket.emit('taskAdded', newTask);

        // Re-render the board
        initBoard();

        // Reset and close modal
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        taskModal.style.display = 'none';
    });

    // Cancel task handler
    cancelTaskBtn.addEventListener('click', function() {
        document.getElementById('task-title').value = '';
        document.getElementById('task-description').value = '';
        taskModal.style.display = 'none';
    });

    // Socket.io event handlers
    socket.on('connect', () => {
        console.log('Connected to server');
    });

    socket.on('userCount', (count) => {
        userCountDisplay.textContent = count;
    });

    socket.on('initialTasks', (initialTasks) => {
        tasks = initialTasks;
        initBoard();
    });

    socket.on('taskAdded', (newTask) => {
        tasks.push(newTask);
        initBoard();
    });

    socket.on('taskUpdated', (updatedTask) => {
        const index = tasks.findIndex(t => t.id === updatedTask.id);
        if (index !== -1) {
            tasks[index] = updatedTask;
            initBoard();
        }
    });

    // Initialize the board
    initBoard();
});
