# Low-Latency Trading Platform Architecture

Below is a high-performance, scalable trading platform design with a focus on low latency. This implementation uses modern C++ for core components and can be extended with additional services as needed.

## Core Components

### 1. Order Matching Engine (Core)

```cpp
#include <atomic>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <thread>
#include <memory>

class Order {
public:
    enum class Type { BUY, SELL };
    enum class Status { PENDING, PARTIAL, FILLED, CANCELLED };

    Order(uint64_t id, Type type, double price, uint64_t quantity, uint64_t timestamp)
        : id(id), type(type), price(price), quantity(quantity), remaining(quantity),
          timestamp(timestamp), status(Status::PENDING) {}

    uint64_t id;
    Type type;
    double price;
    uint64_t quantity;
    uint64_t remaining;
    uint64_t timestamp;
    Status status;
    std::vector<std::pair<uint64_t, uint64_t>> fills; // (order_id, quantity)
};

class OrderBook {
private:
    struct OrderCompare {
        bool operator()(const std::shared_ptr<Order>& a, const std::shared_ptr<Order>& b) const {
            if (a->price == b->price) {
                return a->timestamp > b->timestamp; // FIFO for same price
            }
            return a->price > b->price; // Min-heap for sells
        }
    };

    std::priority_queue<std::shared_ptr<Order>, std::vector<std::shared_ptr<Order>>, OrderCompare> buy_orders;
    std::priority_queue<std::shared_ptr<Order>, std::vector<std::shared_ptr<Order>>, OrderCompare> sell_orders;
    std::unordered_map<uint64_t, std::shared_ptr<Order>> open_orders;
    std::mutex mtx;

public:
    void addOrder(const std::shared_ptr<Order>& order) {
        std::lock_guard<std::mutex> lock(mtx);

        if (order->type == Order::Type::BUY) {
            buy_orders.push(order);
        } else {
            sell_orders.push(order);
        }
        open_orders[order->id] = order;
    }

    std::vector<std::pair<std::shared_ptr<Order>, std::shared_ptr<Order>>> matchOrders() {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<std::pair<std::shared_ptr<Order>, std::shared_ptr<Order>>> matches;

        while (!buy_orders.empty() && !sell_orders.empty()) {
            auto buy = buy_orders.top();
            auto sell = sell_orders.top();

            if (buy->price >= sell->price) {
                uint64_t match_qty = std::min(buy->remaining, sell->remaining);
                matches.emplace_back(buy, sell);

                buy->remaining -= match_qty;
                sell->remaining -= match_qty;

                buy->fills.emplace_back(sell->id, match_qty);
                sell->fills.emplace_back(buy->id, match_qty);

                if (buy->remaining == 0) {
                    buy->status = Order::Status::FILLED;
                    buy_orders.pop();
                    open_orders.erase(buy->id);
                }

                if (sell->remaining == 0) {
                    sell->status = Order::Status::FILLED;
                    sell_orders.pop();
                    open_orders.erase(sell->id);
                }
            } else {
                break;
            }
        }

        return matches;
    }

    bool cancelOrder(uint64_t order_id) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = open_orders.find(order_id);
        if (it == open_orders.end()) return false;

        it->second->status = Order::Status::CANCELLED;
        open_orders.erase(it);
        return true;
    }
};
```

### 2. Network Interface (ZeroMQ)

```cpp
#include <zmq.hpp>
#include <string>
#include <thread>
#include <atomic>

class NetworkInterface {
private:
    zmq::context_t context;
    zmq::socket_t publisher;
    zmq::socket_t subscriber;
    std::atomic<bool> running;
    std::thread network_thread;

    void run() {
        while (running) {
            zmq::message_t message;
            try {
                if (subscriber.recv(&message, ZMQ_DONTWAIT)) {
                    // Process incoming message
                    std::string msg_str(static_cast<char*>(message.data()), message.size());
                    // TODO: Parse and handle message
                }
            } catch (zmq::error_t& e) {
                if (e.num() != EAGAIN) {
                    std::cerr << "Network error: " << e.what() << std::endl;
                }
            }

            std::this_thread::sleep_for(std::chrono::microseconds(100));
        }
    }

public:
    NetworkInterface(const std::string& pub_endpoint, const std::string& sub_endpoint)
        : context(1), publisher(context, ZMQ_PUB), subscriber(context, ZMQ_SUB),
          running(false) {

        publisher.bind(pub_endpoint);
        subscriber.bind(sub_endpoint);
        subscriber.setsockopt(ZMQ_SUBSCRIBE, "", 0);
    }

    ~NetworkInterface() {
        stop();
    }

    void start() {
        running = true;
        network_thread = std::thread(&NetworkInterface::run, this);
    }

    void stop() {
        running = false;
        if (network_thread.joinable()) {
            network_thread.join();
        }
    }

    void publish(const std::string& message) {
        zmq::message_t msg(message.size());
        memcpy(msg.data(), message.c_str(), message.size());
        publisher.send(msg);
    }
};
