class TradingPlatform {
private:
    OrderBook order_book;
    NetworkInterface network;
    std::atomic<uint64_t> order_id_counter;
    std::atomic<bool> running;
    std::thread matching_thread;

    void matchingLoop() {
        while (running) {
            auto start = std::chrono::high_resolution_clock::now();

            auto matches = order_book.matchOrders();
            for (const auto& match : matches) {
                // Process matches (send to network, update positions, etc.)
                std::string trade_msg = "TRADE:" + std::to_string(match.first->id) +
                                       ":" + std::to_string(match.second->id) +
                                       ":" + std::to_string(match.first->price) +
                                       ":" + std::to_string(match.first->quantity - match.first->remaining);
                network.publish(trade_msg);
            }

            auto end = std::chrono::high_resolution_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

            // Adjust sleep time based on processing time
            int sleep_time = std::max(0, 1000 - static_cast<int>(duration.count()));
            std::this_thread::sleep_for(std::chrono::microseconds(sleep_time));
        }
    }

public:
    TradingPlatform(const std::string& pub_endpoint, const std::string& sub_endpoint)
        : network(pub_endpoint, sub_endpoint), order_id_counter(1), running(false) {}

    ~TradingPlatform() {
        stop();
    }

    void start() {
        running = true;
        network.start();
        matching_thread = std::thread(&TradingPlatform::matchingLoop, this);
    }

    void stop() {
        running = false;
        if (matching_thread.joinable()) {
            matching_thread.join();
        }
        network.stop();
    }

    uint64_t submitOrder(Order::Type type, double price, uint64_t quantity) {
        uint64_t id = order_id_counter++;
        auto timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();

        auto order = std::make_shared<Order>(id, type, price, quantity, timestamp);
        order_book.addOrder(order);

        // Notify network about new order
        std::string order_msg = "ORDER:" + std::to_string(id) +
                               ":" + (type == Order::Type::BUY ? "BUY" : "SELL") +
                               ":" + std::to_string(price) +
                               ":" + std::to_string(quantity);
        network.publish(order_msg);

        return id;
    }

    bool cancelOrder(uint64_t order_id) {
        bool success = order_book.cancelOrder(order_id);
        if (success) {
            std::string cancel_msg = "CANCEL:" + std::to_string(order_id);
            network.publish(cancel_msg);
        }
        return success;
    }
};
