```cpp
#include <atomic>
#include <vector>
#include <unordered_map>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <memory>

class Order {
public:
    enum class Type { BUY, SELL };
    enum class Status { NEW, PARTIAL, FILLED, CANCELLED };

    Order(uint64_t id, Type type, double price, uint64_t quantity, uint64_t timestamp)
        : id(id), type(type), price(price), quantity(quantity),
          remaining(quantity), status(Status::NEW), timestamp(timestamp) {}

    uint64_t id;
    Type type;
    double price;
    uint64_t quantity;
    uint64_t remaining;
    Status status;
    uint64_t timestamp;
};

class OrderBook {
private:
    struct PriceLevel {
        std::queue<std::shared_ptr<Order>> orders;
        uint64_t totalQuantity = 0;
    };

    std::unordered_map<double, PriceLevel> bids;
    std::unordered_map<double, PriceLevel> asks;
    std::mutex mtx;

    // Priority queues for efficient matching
    std::priority_queue<double, std::vector<double>, std::greater<double>> askPrices;
    std::priority_queue<double, std::vector<double>> bidPrices;

public:
    void addOrder(const std::shared_ptr<Order>& order) {
        std::lock_guard<std::mutex> lock(mtx);

        if (order->type == Order::Type::BUY) {
            bids[order->price].orders.push(order);
            bids[order->price].totalQuantity += order->quantity;
            bidPrices.push(order->price);
        } else {
            asks[order->price].orders.push(order);
            asks[order->price].totalQuantity += order->quantity;
            askPrices.push(order->price);
        }
    }

    std::vector<std::pair<std::shared_ptr<Order>, uint64_t>> matchOrders() {
        std::lock_guard<std::mutex> lock(mtx);
        std::vector<std::pair<std::shared_ptr<Order>, uint64_t>> matches;

        while (!bidPrices.empty() && !askPrices.empty()) {
            double bestBid = bidPrices.top();
            double bestAsk = askPrices.top();

            if (bestBid < bestAsk) break;

            auto& bidLevel = bids[bestBid];
            auto& askLevel = asks[bestAsk];

            while (!bidLevel.orders.empty() && !askLevel.orders.empty()) {
                auto& bidOrder = bidLevel.orders.front();
                auto& askOrder = askLevel.orders.front();

                uint64_t matchedQty = std::min(bidOrder->remaining, askOrder->remaining);

                matches.emplace_back(bidOrder, matchedQty);
                matches.emplace_back(askOrder, matchedQty);

                bidOrder->remaining -= matchedQty;
                askOrder->remaining -= matchedQty;
                bidLevel.totalQuantity -= matchedQty;
                askLevel.totalQuantity -= matchedQty;

                if (bidOrder->remaining == 0) {
                    bidOrder->status = Order::Status::FILLED;
                    bidLevel.orders.pop();
                }

                if (askOrder->remaining == 0) {
                    askOrder->status = Order::Status::FILLED;
                    askLevel.orders.pop();
                }
            }

            if (bidLevel.orders.empty()) {
                bids.erase(bestBid);
                bidPrices.pop();
            }

            if (askLevel.orders.empty()) {
                asks.erase(bestAsk);
                askPrices.pop();
            }
        }

        return matches;
    }

    // Additional methods for order cancellation, modification, etc.
};
```

### 2. Network Interface (ZeroMQ)

```cpp
#include <zmq.hpp>
#include <string>
#include <thread>
#include <atomic>
#include <functional>

class NetworkInterface {
private:
    zmq::context_t context;
    zmq::socket_t publisher;
    zmq::socket_t subscriber;
    std::thread workerThread;
    std::atomic<bool> running{false};

    std::function<void(const std::string&)> messageHandler;

public:
    NetworkInterface(const std::string& pubEndpoint, const std::string& subEndpoint)
        : context(1), publisher(context, ZMQ_PUB), subscriber(context, ZMQ_SUB) {

        publisher.bind(pubEndpoint);
        subscriber.bind(subEndpoint);
        subscriber.setsockopt(ZMQ_SUBSCRIBE, "", 0);
    }

    void start(std::function<void(const std::string&)> handler) {
        messageHandler = handler;
        running = true;
        workerThread = std::thread([this]() {
            zmq::pollitem_t items[] = {
                { subscriber, 0, ZMQ_POLLIN, 0 }
            };

            while (running) {
                zmq::message_t message;
                if (zmq::poll(&items[0], 1, 100) > 0) {
                    if (items[0].revents & ZMQ_POLLIN) {
                        subscriber.recv(&message);
                        std::string msg(static_cast<char*>(message.data()), message.size());
                        messageHandler(msg);
                    }
                }
            }
        });
    }

    void publish(const std::string& message) {
        zmq::message_t msg(message.data(), message.size());
        publisher.send(msg);
    }

    void stop() {
        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }
};
