NetworkConfig config;

// Initialize network interface
int init_interface(const char *if_name, NetworkInterface *iface) {
    struct ifreq ifr;
    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    // Get interface index
    strncpy(ifr.ifr_name, if_name, IFNAMSIZ);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl SIOCGIFINDEX");
        close(sock);
        return -1;
    }

    // Get MAC address
    if (ioctl(sock, SIOCGIFHWADDR, &ifr) < 0) {
        perror("ioctl SIOCGIFHWADDR");
        close(sock);
        return -1;
    }
    memcpy(iface->mac_addr, ifr.ifr_hwaddr.sa_data, ETH_ALEN);

    // Get IP address
    if (ioctl(sock, SIOCGIFADDR, &ifr) < 0) {
        perror("ioctl SIOCGIFADDR");
        close(sock);
        return -1;
    }
    struct sockaddr_in *ip_addr = (struct sockaddr_in *)&ifr.ifr_addr;
    iface->ip_addr = ip_addr->sin_addr.s_addr;

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sock, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sock);
        return -1;
    }

    iface->sock_fd = sock;
    strncpy(iface->if_name, if_name, IFNAMSIZ);
    return 0;
}

// Add a filter rule
void add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                     uint16_t src_port, uint16_t dst_port,
                     uint8_t protocol, bool allow) {
    if (config.rule_count >= MAX_RULES) {
        fprintf(stderr, "Maximum number of rules reached\n");
        return;
    }

    FilterRule *rule = &config.rules[config.rule_count++];
    rule->src_ip = src_ip;
    rule->dst_ip = dst_ip;
    rule->src_port = src_port;
    rule->dst_port = dst_port;
    rule->protocol = protocol;
    rule->allow = allow;
}

// Check if packet matches any filter rule
bool packet_matches_rule(const uint8_t *packet, int len) {
    struct ethhdr *eth = (struct ethhdr *)packet;
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));

    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return false; // Not an IP packet
    }

    // Check all rules
    for (int i = 0; i < config.rule_count; i++) {
        FilterRule *rule = &config.rules[i];

        // Check protocol
        if (rule->protocol != 0 && rule->protocol != ip->protocol) {
            continue;
        }

        // Check source IP
        if (rule->src_ip != 0 && rule->src_ip != ip->saddr) {
            continue;
        }

        // Check destination IP
        if (rule->dst_ip != 0 && rule->dst_ip != ip->daddr) {
            continue;
        }

        // Check ports if TCP or UDP
        if (ip->protocol == IPPROTO_TCP || ip->protocol == IPPROTO_UDP) {
            struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + ip->ihl * 4);

            if (rule->src_port != 0 && rule->src_port != ntohs(tcp->source)) {
                continue;
            }

            if (rule->dst_port != 0 && rule->dst_port != ntohs(tcp->dest)) {
                continue;
            }
        }

        // Rule matched
        return rule->allow;
    }

    // No matching rule found - default deny
    return false;
}

// Forward packet to another interface
void forward_packet(const uint8_t *packet, int len, int exclude_iface) {
    for (int i = 0; i < config.interface_count; i++) {
        if (i == exclude_iface) continue;

        NetworkInterface *iface = &config.interfaces[i];
        if (send(iface->sock_fd, packet, len, 0) < 0) {
            perror("send");
        }
    }
}

// Packet processing thread
void *packet_processor(void *arg) {
    int iface_idx = *(int *)arg;
    NetworkInterface *iface = &config.interfaces[iface_idx];

    uint8_t packet[MAX_PACKET_SIZE];
    struct sockaddr_ll from;
    socklen_t from_len = sizeof(from);

    while (config.running) {
        int len = recvfrom(iface->sock_fd, packet, MAX_PACKET_SIZE, 0,
                          (struct sockaddr *)&from, &from_len);

        if (len < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom");
            break;
        }

        // Check if packet matches any filter rule
        if (packet_matches_rule(packet, len)) {
            // Forward the packet to other interfaces
            forward_packet(packet, len, iface_idx);
        }
    }

    return NULL;
}

// Main function
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface1> [<interface2> ...]\n", argv[0]);
        return 1;
    }

    // Initialize configuration
    memset(&config, 0, sizeof(config));
    config.running = true;

    // Initialize interfaces
    for (int i = 1; i < argc && i < MAX_INTERFACES + 1; i++) {
        if (init_interface(argv[i], &config.interfaces[config.interface_count]) < 0) {
            fprintf(stderr, "Failed to initialize interface %s\n", argv[i]);
            continue;
        }
        config.interface_count++;
    }

    if (config.interface_count == 0) {
        fprintf(stderr, "No valid interfaces specified\n");
        return 1;
    }

    // Add some example filter rules
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, true); // Allow all ICMP
    add_filter_rule(0, 0, 0, 80, IPPROTO_TCP, true); // Allow HTTP
    add_filter_rule(0, 0, 0, 443, IPPROTO_TCP, true); // Allow HTTPS

    // Create processing threads for each interface
    pthread_t threads[MAX_INTERFACES];
    int iface_indices[MAX_INTERFACES];

    for (int i = 0; i < config.interface_count; i++) {
        iface_indices[i] = i;
        if (pthread_create(&threads[i], NULL, packet_processor, &iface_indices[i]) != 0) {
            perror("pthread_create");
            config.running = false;
            break;
        }
    }

    // Wait for termination signal
    printf("Network service running. Press Ctrl+C to stop...\n");
    while (config.running) {
        sleep(1);
    }

    // Cleanup
    for (int i = 0; i < config.interface_count; i++) {
        pthread_join(threads[i], NULL);
        close(config.interfaces[i].sock_fd);
    }

    return 0;
}
```

## Key Features for Ultra-Low Latency:

1. **Raw Socket Usage**: Direct access to Ethernet frames without TCP/IP stack overhead
2. **Minimal Memory Allocation**: Pre-allocated buffers and structures
3. **Efficient Packet Processing**: Linear rule checking with early termination
4. **Multi-threaded Design**: Parallel processing of packets from multiple interfaces
5. **Direct Memory Access**: Avoiding unnecessary copies of packet data

## Compilation and Usage:

1. Compile with:
   ```bash
   gcc -o net_service net_service.c -lpthread
   ```

2. Run with:
   ```bash
   sudo ./net_service eth0 eth1
   ```

## Performance Considerations:

1. **CPU Affinity**: For production use, bind threads to specific CPU cores
2. **Huge Pages**: Consider using huge pages for memory allocation
3. **Batching**: Process multiple packets in each iteration
4. **Kernel Bypass**: For even lower latency, consider DPDK or AF_XDP

This implementation provides a foundation that can be further optimized based on specific hardware and requirements.

# Ultra-Low-Latency Networking Service with Packet Filtering and Forwarding

Below is a C implementation of an ultra-low-latency networking service that performs packet-level filtering and forwarding. This design focuses on minimizing latency through:
- Direct memory access (DMA) for packet I/O
- Minimal processing in the fast path
- Efficient data structures for filtering
- Hardware acceleration where possible

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
