#include <netinet/udp.h>
#include <net/ethernet.h>
#include <arpa/inet.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <time.h>

// Configuration
#define MAX_RULES 1024
#define MAX_PACKET_SIZE 1500
#define NUM_WORKER_THREADS 4
#define BUFFER_SIZE (1024 * 1024 * 64) // 64MB

// Packet processing modes
typedef enum {
    MODE_DROP,
    MODE_FORWARD,
    MODE_MODIFY
} ProcessingMode;

// Filter rule structure
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    ProcessingMode action;
    uint32_t new_dst_ip; // For MODE_MODIFY
} FilterRule;

// Packet buffer structure
typedef struct {
    uint8_t *data;
    size_t length;
    struct timespec timestamp;
} PacketBuffer;

// Shared state
typedef struct {
    FilterRule rules[MAX_RULES];
    int rule_count;
    int running;
    PacketBuffer *packet_buffers;
    volatile int buffer_head;
    volatile int buffer_tail;
    pthread_mutex_t buffer_mutex;
    pthread_cond_t buffer_cond;
} SharedState;

// Initialize shared state
void init_shared_state(SharedState *state) {
    memset(state, 0, sizeof(SharedState));
    state->rule_count = 0;
    state->running = 1;
    state->packet_buffers = malloc(BUFFER_SIZE * sizeof(PacketBuffer));
    if (!state->packet_buffers) {
        perror("Failed to allocate packet buffers");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        state->packet_buffers[i].data = malloc(MAX_PACKET_SIZE);
        if (!state->packet_buffers[i].data) {
            perror("Failed to allocate packet data");
            exit(EXIT_FAILURE);
        }
    }

    pthread_mutex_init(&state->buffer_mutex, NULL);
    pthread_cond_init(&state->buffer_cond, NULL);
}

// Cleanup shared state
void cleanup_shared_state(SharedState *state) {
    state->running = 0;
    pthread_cond_broadcast(&state->buffer_cond);

    for (int i = 0; i < BUFFER_SIZE; i++) {
        free(state->packet_buffers[i].data);
    }
    free(state->packet_buffers);

    pthread_mutex_destroy(&state->buffer_mutex);
    pthread_cond_destroy(&state->buffer_cond);
}

// Add a filter rule
int add_filter_rule(SharedState *state, FilterRule rule) {
    if (state->rule_count >= MAX_RULES) {
        return -1;
    }

    state->rules[state->rule_count++] = rule;
    return 0;
}

// Packet processing function
void process_packet(SharedState *state, PacketBuffer *packet) {
    struct iphdr *ip_header;
    struct tcphdr *tcp_header;
    struct udphdr *udp_header;
    uint16_t src_port = 0, dst_port = 0;

    // Parse Ethernet header
    struct ether_header *eth_header = (struct ether_header *)packet->data;
    if (ntohs(eth_header->ether_type) != ETHERTYPE_IP) {
        return; // Not an IP packet
    }

    // Parse IP header
    ip_header = (struct iphdr *)(packet->data + sizeof(struct ether_header));

    // Check protocol
    switch (ip_header->protocol) {
        case IPPROTO_TCP:
            tcp_header = (struct tcphdr *)((uint8_t *)ip_header + (ip_header->ihl * 4));
            src_port = ntohs(tcp_header->source);
            dst_port = ntohs(tcp_header->dest);
            break;
        case IPPROTO_UDP:
            udp_header = (struct udphdr *)((uint8_t *)ip_header + (ip_header->ihl * 4));
            src_port = ntohs(udp_header->source);
            dst_port = ntohs(udp_header->dest);
            break;
        default:
            // Unsupported protocol
            return;
    }

    // Check against rules
    for (int i = 0; i < state->rule_count; i++) {
        FilterRule *rule = &state->rules[i];

        // Check protocol match
        if (rule->protocol != 0 && rule->protocol != ip_header->protocol) {
            continue;
        }

        // Check IP addresses
        if (rule->src_ip != 0 && rule->src_ip != ip_header->saddr) {
            continue;
        }
        if (rule->dst_ip != 0 && rule->dst_ip != ip_header->daddr) {
            continue;
        }

        // Check ports
        if (rule->src_port != 0 && rule->src_port != src_port) {
            continue;
        }
        if (rule->dst_port != 0 && rule->dst_port != dst_port) {
            continue;
        }

        // Rule matched - apply action
        switch (rule->action) {
            case MODE_DROP:
                // Packet is dropped (no further processing)
                return;
            case MODE_FORWARD:
                // Forward the packet (implementation depends on your setup)
                // This would typically involve sending to another interface
                break;
            case MODE_MODIFY:
                // Modify destination IP
                if (rule->new_dst_ip != 0) {
                    ip_header->daddr = rule->new_dst_ip;
                }
                break;
        }
    }

    // If we get here, packet passes all filters and is forwarded
    // In a real implementation, this would send the packet to the appropriate interface
}

// Worker thread function
void *worker_thread(void *arg) {
    SharedState *state = (SharedState *)arg;
    PacketBuffer packet;

    while (state->running) {
        pthread_mutex_lock(&state->buffer_mutex);

        // Wait for packets
        while (state->buffer_head == state->buffer_tail && state->running) {
            pthread_cond_wait(&state->buffer_cond, &state->buffer_mutex);
        }

        if (!state->running) {
            pthread_mutex_unlock(&state->buffer_mutex);
            break;
        }

        // Get packet from buffer
        packet = state->packet_buffers[state->buffer_tail];
        state->buffer_tail = (state->buffer_tail + 1) % BUFFER_SIZE;

        pthread_mutex_unlock(&state->buffer_mutex);

        // Process the packet
        process_packet(state, &packet);
    }

    return NULL;
}

// Packet capture function (simplified for example)
void capture_packets(SharedState *state, int sockfd) {
    uint8_t buffer[MAX_PACKET_SIZE];
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);

    while (state->running) {
        ssize_t len = recvfrom(sockfd, buffer, MAX_PACKET_SIZE, 0,
                              (struct sockaddr *)&client_addr, &client_len);
        if (len < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom failed");
            break;
        }

        // Add packet to buffer
        pthread_mutex_lock(&state->buffer_mutex);

        // Check if buffer is full
        if ((state->buffer_head + 1) % BUFFER_SIZE == state->buffer_tail) {
            // Buffer full - drop packet
            pthread_mutex_unlock(&state->buffer_mutex);
            continue;
        }

        // Copy packet data
        memcpy(state->packet_buffers[state->buffer_head].data, buffer, len);
        state->packet_buffers[state->buffer_head].length = len;
        clock_gettime(CLOCK_MONOTONIC, &state->packet_buffers[state->buffer_head].timestamp);

        state->buffer_head = (state->buffer_head + 1) % BUFFER_SIZE;

        pthread_cond_signal(&state->buffer_cond);
        pthread_mutex_unlock(&state->buffer_mutex);
    }
}

int main() {
    SharedState state;
    init_shared_state(&state);

    // Example: Add some filter rules
    FilterRule rule1 = {
        .src_ip = inet_addr("192.168.1.100"),
        .dst_ip = 0, // any destination
        .src_port = 0, // any source port
        .dst_port = 80, // HTTP
        .protocol = IPPROTO_TCP,
        .action = MODE_FORWARD
    };
    add_filter_rule(&state, rule1);

    FilterRule rule2 = {
        .src_ip = 0, // any source
        .dst_ip = inet_addr("192.168.1.200"),
        .src_port = 0,
        .dst_port = 22, // SSH
        .protocol = IPPROTO_TCP,
        .action = MODE_DROP
    };
    add_filter_rule(&state, rule2);

    // Create worker threads
    pthread_t workers[NUM_WORKER_THREADS];
    for (int i = 0; i < NUM_WORKER_THREADS; i++) {
        pthread_create(&workers[i], NULL, worker_thread, &state);
    }

    // Set up packet capture (simplified - in real implementation you'd use AF_PACKET)
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        cleanup_shared_state(&state);
        return EXIT_FAILURE;
    }

    // Bind to interface (simplified)
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);
    addr.sin_port = htons(0);

    if (bind(sockfd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind failed");
        close(sockfd);
        cleanup_shared_state(&state);
        return EXIT_FAILURE;
    }

    // Start packet capture
    capture_packets(&state, sockfd);

    // Cleanup
    close(sockfd);
    for (int i = 0; i < NUM_WORKER_THREADS; i++) {
        pthread_join(workers[i], NULL);
    }
    cleanup_shared_state(&state);

    return EXIT_SUCCESS;
}
