}

// Initialize shared state
void init_shared_state() {
    memset(&global_state, 0, sizeof(global_state));
    global_state.rule_count = 0;
    global_state.running = true;
    pthread_mutex_init(&global_state.stats_lock, NULL);
}

// Add a filter rule
bool add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                    uint16_t src_port, uint16_t dst_port,
                    uint8_t protocol, bool action) {
    if (global_state.rule_count >= MAX_RULES) {
        return false;
    }

    filter_rule_t *rule = &global_state.rules[global_state.rule_count++];
    rule->src_ip = src_ip;
    rule->dst_ip = dst_ip;
    rule->src_port = src_port;
    rule->dst_port = dst_port;
    rule->protocol = protocol;
    rule->action = action;

    return true;
}

// Check if packet matches any rule
bool packet_matches_rule(const struct iphdr *ip_hdr, const void *transport_hdr) {
    uint32_t src_ip = ip_hdr->saddr;
    uint32_t dst_ip = ip_hdr->daddr;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;

    if (ip_hdr->protocol == IPPROTO_TCP) {
        const struct tcphdr *tcp_hdr = (const struct tcphdr *)transport_hdr;
        src_port = ntohs(tcp_hdr->source);
        dst_port = ntohs(tcp_hdr->dest);
    } else if (ip_hdr->protocol == IPPROTO_UDP) {
        const struct udphdr *udp_hdr = (const struct udphdr *)transport_hdr;
        src_port = ntohs(udp_hdr->source);
        dst_port = ntohs(udp_hdr->dest);
    }

    for (int i = 0; i < global_state.rule_count; i++) {
        filter_rule_t *rule = &global_state.rules[i];

        // Check protocol first for quick rejection
        if (rule->protocol != 0 && rule->protocol != ip_hdr->protocol) {
            continue;
        }

        // Check source IP if specified
        if (rule->src_ip != 0 && rule->src_ip != src_ip) {
            continue;
        }

        // Check destination IP if specified
        if (rule->dst_ip != 0 && rule->dst_ip != dst_ip) {
            continue;
        }

        // Check source port if specified
        if (rule->src_port != 0 && rule->src_port != src_port) {
            continue;
        }

        // Check destination port if specified
        if (rule->dst_port != 0 && rule->dst_port != dst_port) {
            continue;
        }

        // Rule matched
        return rule->action;
    }

    // No matching rule found - default action is to forward
    return true;
}

// Worker thread function
void *worker_thread(void *arg) {
    worker_args_t *args = (worker_args_t *)arg;
    int sockfd = args->sockfd;
    shared_state_t *state = args->state;
    int worker_id = args->worker_id;

    char buffer[BUFFER_SIZE];
    struct sockaddr_in from_addr;
    socklen_t from_len = sizeof(from_addr);

    while (state->running) {
        // Receive packet
        ssize_t len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0,
                             (struct sockaddr *)&from_addr, &from_len);
        if (len < 0) {
            if (errno == EINTR) continue;
            perror("recvfrom failed");
            break;
        }

        // Update statistics
        pthread_mutex_lock(&state->stats_lock);
        state->stats.packets_received++;
        state->stats.bytes_processed += len;
        pthread_mutex_unlock(&state->stats_lock);

        // Process packet
        struct iphdr *ip_hdr = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        void *transport_hdr = buffer + sizeof(struct ethhdr) + (ip_hdr->ihl * 4);

        bool should_forward = packet_matches_rule(ip_hdr, transport_hdr);

        if (should_forward) {
            // Forward packet (in a real implementation, this would send to another interface)
            pthread_mutex_lock(&state->stats_lock);
            state->stats.packets_forwarded++;
            pthread_mutex_unlock(&state->stats_lock);

            // In a real implementation, you would send the packet out another interface here
            // sendto(sockfd, buffer, len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr));
        } else {
            // Drop packet
            pthread_mutex_lock(&state->stats_lock);
            state->stats.packets_dropped++;
            pthread_mutex_unlock(&state->stats_lock);
        }
    }

    return NULL;
}

// Print statistics
void print_stats() {
    pthread_mutex_lock(&global_state.stats_lock);
    printf("\n=== Statistics ===\n");
    printf("Packets received: %lu\n", global_state.stats.packets_received);
    printf("Packets forwarded: %lu\n", global_state.stats.packets_forwarded);
    printf("Packets dropped: %lu\n", global_state.stats.packets_dropped);
    printf("Bytes processed: %lu\n", global_state.stats.bytes_processed);
    pthread_mutex_unlock(&global_state.stats_lock);
}

int main(int argc, char *argv[]) {
