    add_filter_rule(0, 0, 0, 443, IPPROTO_TCP, true); // Allow HTTPS traffic
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, false); // Drop all ICMP

    // Create worker threads
    pthread_t workers[NUM_WORKERS];
    worker_args_t worker_args[NUM_WORKERS];

    for (int i = 0; i < NUM_WORKERS; i++) {
        worker_args[i].sockfd = sockfd;
        worker_args[i].state = &global_state;
        worker_args[i].worker_id = i;

        if (pthread_create(&workers[i], NULL, worker_thread, &worker_args[i]) != 0) {
            perror("pthread_create failed");
            global_state.running = false;
            break;
        }
    }

    // Main loop - just print stats periodically
    while (global_state.running) {
