#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <errno.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>

// Configuration structure
typedef struct {
    char *interface;
    uint16_t port;
    int filter_protocol; // IPPROTO_UDP, IPPROTO_TCP, etc.
    char *allowed_ip;
    int max_packet_size;
    int queue_size;
} Config;

// Packet processing statistics
typedef struct {
    uint64_t packets_received;
    uint64_t packets_filtered;
    uint64_t packets_forwarded;
    uint64_t bytes_processed;
} Stats;

// Global variables
volatile sig_atomic_t running = 1;
Stats stats = {0};

// Signal handler for graceful shutdown
void sigint_handler(int sig) {
    running = 0;
}

// Initialize raw socket
int init_raw_socket(const char *interface) {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, interface, IFNAMSIZ-1);

    if (setsockopt(sockfd, SOL_SOCKET, SO_BINDTODEVICE, (void *)&ifr, sizeof(ifr)) < 0) {
        perror("SO_BINDTODEVICE");
        close(sockfd);
        return -1;
    }

    // Set socket to non-blocking
    int flags = fcntl(sockfd, F_GETFL, 0);
    fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

    return sockfd;
}

// Packet filtering function
int filter_packet(const uint8_t *packet, size_t len, const Config *config) {
    // Check minimum packet size (Ethernet header + IP header)
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) {
        return 0;
    }

    // Get IP header
    struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));

    // Check protocol
    if (config->filter_protocol != 0 && ip->protocol != config->filter_protocol) {
        return 0;
    }

    // Check source IP if configured
    if (config->allowed_ip != NULL) {
        struct in_addr src_addr;
        src_addr.s_addr = ip->saddr;

        if (strcmp(inet_ntoa(src_addr), config->allowed_ip) != 0) {
            return 0;
        }
    }

    // For TCP/UDP, check port if configured
    if (config->port != 0) {
        if (ip->protocol == IPPROTO_TCP) {
            struct tcphdr *tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + (ip->ihl << 2));
            if (ntohs(tcp->source) != config->port && ntohs(tcp->dest) != config->port) {
                return 0;
            }
        } else if (ip->protocol == IPPROTO_UDP) {
            struct udphdr *udp = (struct udphdr *)(packet + sizeof(struct ethhdr) + (ip->ihl << 2));
            if (ntohs(udp->source) != config->port && ntohs(udp->dest) != config->port) {
                return 0;
            }
        }
    }

    return 1; // Packet passed all filters
}

// Packet forwarding function
void forward_packet(int sockfd, const uint8_t *packet, size_t len) {
    // In a real implementation, you would:
    // 1. Modify packet headers if needed
    // 2. Send to appropriate destination
    // 3. Handle any NAT or routing requirements

    // For this example, we'll just send the packet back out
    // (Note: This is just for demonstration - real forwarding would be more complex)

    struct sockaddr_ll dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sll_family = AF_PACKET;
    dest_addr.sll_protocol = htons(ETH_P_ALL);
    dest_addr.sll_ifindex = if_nametoindex("lo"); // Forward to loopback for demo

    if (sendto(sockfd, packet, len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("sendto");
    } else {
        stats.packets_forwarded++;
    }
}

// Packet processing thread
void *packet_processor(void *arg) {
    int sockfd = *(int *)arg;
    Config *config = (Config *)arg;

    uint8_t *buffer = malloc(config->max_packet_size);
    if (!buffer) {
        perror("malloc");
        return NULL;
    }

    while (running) {
        ssize_t len = recv(sockfd, buffer, config->max_packet_size, 0);
        if (len < 0) {
            if (errno != EAGAIN && errno != EWOULDBLOCK) {
                perror("recv");
            }
            usleep(100); // Small sleep to prevent busy waiting
            continue;
        }

        stats.packets_received++;
        stats.bytes_processed += len;

        if (filter_packet(buffer, len, config)) {
            forward_packet(sockfd, buffer, len);
        } else {
            stats.packets_filtered++;
        }
    }

    free(buffer);
    return NULL;
}

// Statistics printing thread
void *stats_printer(void *arg) {
    while (running) {
        sleep(1);
        printf("Stats - Received: %lu, Filtered: %lu, Forwarded: %lu, Bytes: %lu\n",
               stats.packets_received, stats.packets_filtered,
               stats.packets_forwarded, stats.bytes_processed);
    }
    return NULL;
}

int main(int argc, char *argv[]) {
    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Configuration
    Config config = {
        .interface = "eth0",
        .port = 0, // Any port
        .filter_protocol = IPPROTO_UDP, // Filter UDP packets
        .allowed_ip = NULL, // Allow any IP
        .max_packet_size = 2048,
        .queue_size = 1000
    };

    // Initialize raw socket
    int sockfd = init_raw_socket(config.interface);
    if (sockfd < 0) {
        return EXIT_FAILURE;
    }

    // Create processing thread
    pthread_t processor_thread;
    if (pthread_create(&processor_thread, NULL, packet_processor, &sockfd) != 0) {
        perror("pthread_create");
        close(sockfd);
        return EXIT_FAILURE;
    }

    // Create statistics thread
    pthread_t stats_thread;
    if (pthread_create(&stats_thread, NULL, stats_printer, NULL) != 0) {
        perror("pthread_create");
        running = 0;
        pthread_join(processor_thread, NULL);
        close(sockfd);
        return EXIT_FAILURE;
    }

    // Wait for shutdown
    pthread_join(processor_thread, NULL);
    pthread_join(stats_thread, NULL);

    close(sockfd);
    return EXIT_SUCCESS;
}
