class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t length) = 0;
    virtual ~PacketFilter() = default;
};

class BasicIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(const std::string& ip) {
        in_addr addr;
        inet_pton(AF_INET, ip.c_str(), &addr);
        allowedIPs[addr.s_addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t length) override {
        if (length < sizeof(ether_header) + sizeof(iphdr)) {
            return false;
        }

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet + sizeof(ether_header));

        // Check if source IP is allowed
        if (allowedIPs.find(ip->saddr) == allowedIPs.end()) {
            return false;
        }

        // Basic TCP/UDP port filtering (example)
        if (ip->protocol == IPPROTO_TCP && length >= sizeof(ether_header) + sizeof(iphdr) + sizeof(tcphdr)) {
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + sizeof(ether_header) + sizeof(iphdr));
            if (ntohs(tcp->dest) == 80 || ntohs(tcp->dest) == 443) {
                return true;
            }
        }

        return false;
    }
};

class LowLatencyNetworkService {
    int sockfd;
    std::atomic<bool> running;
    std::vector<std::thread> workers;
    std::vector<PacketFilter*> filters;
    std::string interface;
    int numWorkers;

public:
    LowLatencyNetworkService(const std::string& iface, int workers = 4)
        : interface(iface), numWorkers(workers), running(false) {
        // Set process priority to real-time
        setpriority(PRIO_PROCESS, 0, -20);

        // Create raw socket
        sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (sockfd < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(sockfd, F_GETFL, 0);
        fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

        // Bind to interface
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, interface.c_str(), IFNAMSIZ-1);

        if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
            perror("ioctl");
            throw std::runtime_error("Failed to get interface index");
        }

        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = ifr.ifr_ifindex;
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(sockfd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            throw std::runtime_error("Failed to bind socket");
        }

        // Lock memory to prevent paging
        if (mlockall(MCL_CURRENT | MCL_FUTURE) < 0) {
            perror("mlockall");
            throw std::runtime_error("Failed to lock memory");
        }
    }

    ~LowLatencyNetworkService() {
        stop();
        if (sockfd >= 0) {
            close(sockfd);
        }
        munlockall();
    }

    void addFilter(PacketFilter* filter) {
        filters.push_back(filter);
    }

    void start() {
        running = true;

        // Create worker threads
        for (int i = 0; i < numWorkers; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }
    }

    void stop() {
        running = false;
        for (auto& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
        workers.clear();
    }

private:
    void workerThread() {
        uint8_t buffer[65536];
        struct sockaddr_ll from;
        socklen_t fromlen = sizeof(from);

        while (running) {
            ssize_t len = recvfrom(sockfd, buffer, sizeof(buffer), 0,
                                 (struct sockaddr*)&from, &fromlen);

            if (len < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    // No data available, yield CPU
                    std::this_thread::yield();
                    continue;
                }
                perror("recvfrom");
                break;
            }

            // Process packet
            if (shouldForward(buffer, len)) {
                // Forward packet (in a real implementation, this would be more sophisticated)
                sendto(sockfd, buffer, len, 0, (struct sockaddr*)&from, fromlen);
            }
        }
    }

    bool shouldForward(const uint8_t* packet, size_t length) {
        for (auto filter : filters) {
            if (!filter->shouldForward(packet, length)) {
                return false;
            }
        }
        return true;
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface> [allowed_ip...]" << std::endl;
        return 1;
    }

    try {
        LowLatencyNetworkService service(argv[1]);

        // Add filters
        BasicIPFilter ipFilter;
        for (int i = 2; i < argc; ++i) {
            ipFilter.addAllowedIP(argv[i]);
        }
        service.addFilter(&ipFilter);

        std::cout << "Starting low-latency network service on " << argv[1] << std::endl;
        service.start();

        // Run until interrupted
        while (true) {
            std::this_thread::sleep_for(std::chrono::seconds(1));
        }

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

