// Configuration
#define MAX_RULES 1024
#define PACKET_BUFFER_SIZE (1 << 20) // 1MB packet buffer
#define MAX_PACKET_SIZE 1500
#define NUM_WORKER_THREADS 4

// Packet processing statistics
typedef struct {
    uint64_t packets_received;
    uint64_t packets_filtered;
    uint64_t packets_forwarded;
    uint64_t bytes_processed;
} stats_t;

// Rule structure for packet filtering
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint8_t action; // 0=drop, 1=forward
    uint8_t interface; // output interface index
} rule_t;

// Packet processing context
typedef struct {
    int sock_fd;
    int if_index;
    char if_name[IFNAMSIZ];
    uint8_t *packet_buffer;
    size_t buffer_size;
    rule_t *rules;
    int rule_count;
    stats_t stats;
    int running;
} packet_context_t;

// Rule matching function (optimized for speed)
static inline int match_rule(const rule_t *rule, const struct iphdr *ip,
                           const void *transport) {
    // Check protocol first (most selective)
    if (rule->protocol != 0 && rule->protocol != ip->protocol) {
        return 0;
    }

    // Check IP addresses
    if (rule->src_ip != 0 && rule->src_ip != ip->saddr) {
        return 0;
    }
    if (rule->dst_ip != 0 && rule->dst_ip != ip->daddr) {
        return 0;
    }

    // Check transport layer (TCP/UDP)
    if (ip->protocol == IPPROTO_TCP) {
        const struct tcphdr *tcp = (const struct tcphdr *)transport;
        if (rule->src_port != 0 && rule->src_port != ntohs(tcp->source)) {
            return 0;
        }
        if (rule->dst_port != 0 && rule->dst_port != ntohs(tcp->dest)) {
            return 0;
        }
    } else if (ip->protocol == IPPROTO_UDP) {
        const struct udphdr *udp = (const struct udphdr *)transport;
        if (rule->src_port != 0 && rule->src_port != ntohs(udp->source)) {
            return 0;
        }
        if (rule->dst_port != 0 && rule->dst_port != ntohs(udp->dest)) {
            return 0;
        }
    }

    return 1;
}

// Packet processing function
static void process_packet(packet_context_t *ctx, const uint8_t *packet, size_t len) {
    ctx->stats.packets_received++;
    ctx->stats.bytes_processed += len;

    // Parse Ethernet header
    const struct ethhdr *eth = (const struct ethhdr *)packet;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        return; // Not an IP packet
    }

    // Parse IP header
    const struct iphdr *ip = (const struct iphdr *)(packet + sizeof(struct ethhdr));
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) {
        return; // Invalid packet
    }

    // Get transport header
    const void *transport = (const uint8_t *)ip + (ip->ihl * 4);
    size_t transport_len = len - sizeof(struct ethhdr) - (ip->ihl * 4);

    // Check rules in order (first match wins)
    for (int i = 0; i < ctx->rule_count; i++) {
        if (match_rule(&ctx->rules[i], ip, transport)) {
            ctx->stats.packets_filtered++;

            if (ctx->rules[i].action == 1) { // Forward
                ctx->stats.packets_forwarded++;

                // In a real implementation, we would:
                // 1. Look up the output interface
                // 2. Modify MAC addresses if needed
                // 3. Send the packet out the appropriate interface
                // For this example, we'll just simulate forwarding

                // Simulate forwarding delay (in a real system, this would be hardware)
                volatile int delay = 0; // Prevent compiler optimization
                for (int j = 0; j < 100; j++) {
                    delay += j;
                }
            }
            return;
        }
    }

    // No matching rule found - drop packet
}

// Worker thread function
static void* worker_thread(void *arg) {
    packet_context_t *ctx = (packet_context_t *)arg;

    while (ctx->running) {
        // In a real implementation, we would use:
        // - DMA for packet I/O
        // - Kernel bypass techniques
        // - Hardware acceleration (e.g., DPDK, XDP)

        // For this example, we'll simulate packet reception
        uint8_t packet[MAX_PACKET_SIZE];
        ssize_t len = recv(ctx->sock_fd, packet, sizeof(packet), 0);

        if (len > 0) {
            process_packet(ctx, packet, len);
        } else if (len < 0 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("recv");
            break;
        }
    }

    return NULL;
}

// Initialize packet processing context
static int init_context(packet_context_t *ctx, const char *if_name) {
    memset(ctx, 0, sizeof(*ctx));

    // Create raw socket
    ctx->sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (ctx->sock_fd < 0) {
        perror("socket");
        return -1;
    }

    // Get interface index
    struct ifreq ifr;
    strncpy(ifr.ifr_name, if_name, IFNAMSIZ);
    if (ioctl(ctx->sock_fd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl SIOCGIFINDEX");
        close(ctx->sock_fd);
        return -1;
    }
    ctx->if_index = ifr.ifr_ifindex;
    strncpy(ctx->if_name, if_name, IFNAMSIZ);

    // Set socket to non-blocking
    int flags = fcntl(ctx->sock_fd, F_GETFL, 0);
    fcntl(ctx->sock_fd, F_SETFL, flags | O_NONBLOCK);

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ctx->if_index;
    sll.sll_protocol = htons(ETH_P_ALL);
    if (bind(ctx->sock_fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(ctx->sock_fd);
        return -1;
    }

    // Allocate packet buffer
    ctx->packet_buffer = malloc(PACKET_BUFFER_SIZE);
    if (!ctx->packet_buffer) {
        perror("malloc");
        close(ctx->sock_fd);
        return -1;
    }
    ctx->buffer_size = PACKET_BUFFER_SIZE;

    // Initialize rules (in a real system, these would be loaded from config)
    ctx->rules = malloc(MAX_RULES * sizeof(rule_t));
    if (!ctx->rules) {
        perror("malloc");
        free(ctx->packet_buffer);
        close(ctx->sock_fd);
        return -1;
    }
    ctx->rule_count = 0;

    // Add some sample rules
    rule_t rule;
    memset(&rule, 0, sizeof(rule));
    rule.protocol = IPPROTO_TCP;
    rule.dst_port = htons(80); // HTTP
    rule.action = 1; // Forward
    rule.interface = 1; // Example interface index
    ctx->rules[ctx->rule_count++] = rule;

    memset(&rule, 0, sizeof(rule));
    rule.protocol = IPPROTO_UDP;
    rule.dst_port = htons(53); // DNS
    rule.action = 1; // Forward
    rule.interface = 2; // Example interface index
    ctx->rules[ctx->rule_count++] = rule;

    ctx->running = 1;
    return 0;
}

// Clean up context
static void cleanup_context(packet_context_t *ctx) {
    ctx->running = 0;
    if (ctx->sock_fd >= 0) {
        close(ctx->sock_fd);
    }
    if (ctx->packet_buffer) {
        free(ctx->packet_buffer);
    }
    if (ctx->rules) {
        free(ctx->rules);
    }
}

// Main function
int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    packet_context_t ctx;
    if (init_context(&ctx, argv[1]) < 0) {
        return 1;
    }

    // Create worker threads
    pthread_t threads[NUM_WORKER_THREADS];
    for (int i = 0; i < NUM_WORKER_THREADS; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, &ctx) != 0) {
            perror("pthread_create");
            cleanup_context(&ctx);
            return 1;
        }
    }

    // Main monitoring loop
    while (1) {
        sleep(1);

        // Print statistics
        printf("Packets: %lu received, %lu filtered, %lu forwarded\n",
               ctx.stats.packets_received,
               ctx.stats.packets_filtered,
               ctx.stats.packets_forwarded);
        printf("Throughput: %.2f Mbps\n",
               (ctx.stats.bytes_processed * 8.0) / (1024 * 1024));

        // Reset counters for next interval
        ctx.stats.bytes_processed = 0;
    }

    // Clean up
    for (int i = 0; i < NUM_WORKER_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
    cleanup_context(&ctx);

    return 0;
}
