                }
                break;
        }
    }

    if (should_forward) {
        // Modify packet for forwarding
        ip_header->daddr = config.forward_ip;

        // Update checksum for IP header
        ip_header->check = 0;
        ip_header->check = checksum(ip_header, ip_header_len);

        // Update checksum for transport layer
        if (ip_header->protocol == IPPROTO_TCP) {
            struct tcphdr *tcp_header = (struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip_header_len);
            tcp_header->dest = config.forward_port;
            tcp_header->check = 0;
            // TCP checksum requires pseudo-header calculation
            // This is simplified - real implementation would need more work
            tcp_header->check = checksum(tcp_header, ntohs(ip_header->tot_len) - ip_header_len);
        } else if (ip_header->protocol == IPPROTO_UDP) {
            struct udphdr *udp_header = (struct udphdr *)(buffer + sizeof(struct ethhdr) + ip_header_len);
            udp_header->dest = config.forward_port;
            udp_header->check = 0;
            // UDP checksum calculation would go here
        }

        // Here you would actually send the packet to the forward destination
        // For this example, we'll just count it
        pthread_mutex_lock(&stats_mutex);
        stats.forwarded_packets++;
        pthread_mutex_unlock(&stats_mutex);
    } else {
        pthread_mutex_lock(&stats_mutex);
        stats.filtered_packets++;
        pthread_mutex_unlock(&stats_mutex);
    }
