#include <sys/ioctl.h>

class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
    virtual ~PacketFilter() = default;
};

class SimpleIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(const std::string& ip) {
        in_addr addr;
        inet_pton(AF_INET, ip.c_str(), &addr);
        allowedIPs[addr.s_addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(ether_header) + sizeof(iphdr)) {
            return false;
        }

        const iphdr* iph = reinterpret_cast<const iphdr*>(
            packet + sizeof(ether_header));

        if (allowedIPs.find(iph->saddr) != allowedIPs.end() ||
            allowedIPs.find(iph->daddr) != allowedIPs.end()) {
            return true;
        }

        return false;
    }
};

class LowLatencyForwarder {
    int rawSocket;
    std::atomic<bool> running;
    std::vector<std::thread> workers;
    PacketFilter* filter;
    std::string interfaceName;

public:
    LowLatencyForwarder(const std::string& iface, PacketFilter* f)
        : filter(f), interfaceName(iface), running(false) {
        rawSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (rawSocket < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create raw socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(rawSocket, F_GETFL, 0);
        fcntl(rawSocket, F_SETFL, flags | O_NONBLOCK);

        // Bind to specific interface
        struct ifreq ifr;
        strncpy(ifr.ifr_name, interfaceName.c_str(), IFNAMSIZ);
        if (ioctl(rawSocket, SIOCGIFINDEX, &ifr) < 0) {
            perror("ioctl");
            close(rawSocket);
            throw std::runtime_error("Failed to get interface index");
        }

        struct sockaddr_ll sll;
        memset(&sll, 0, sizeof(sll));
        sll.sll_family = AF_PACKET;
        sll.sll_ifindex = ifr.ifr_ifindex;
        sll.sll_protocol = htons(ETH_P_ALL);

        if (bind(rawSocket, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
            perror("bind");
            close(rawSocket);
            throw std::runtime_error("Failed to bind socket");
        }
    }

    ~LowLatencyForwarder() {
        stop();
        close(rawSocket);
    }

    void start(size_t numWorkers = 4) {
        running = true;
        for (size_t i = 0; i < numWorkers; ++i) {
            workers.emplace_back([this]() { workerThread(); });
        }
    }

    void stop() {
        running = false;
        for (auto& worker : workers) {
            if (worker.joinable()) {
                worker.join();
            }
        }
        workers.clear();
    }

private:
    void workerThread() {
        uint8_t buffer[65536];
        struct pollfd pfd = { rawSocket, POLLIN, 0 };

        while (running) {
            int ret = poll(&pfd, 1, 100);
            if (ret < 0) {
                perror("poll");
                break;
            }

            if (ret == 0) {
                continue; // timeout
            }

            if (pfd.revents & POLLIN) {
                ssize_t len = recv(rawSocket, buffer, sizeof(buffer), 0);
                if (len < 0) {
                    if (errno != EAGAIN && errno != EWOULDBLOCK) {
                        perror("recv");
                    }
                    continue;
                }

                if (filter->shouldForward(buffer, len)) {
                    // Forward the packet (in a real implementation, you'd modify headers as needed)
                    if (send(rawSocket, buffer, len, 0) < 0) {
                        perror("send");
                    }
                }
            }
        }
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface> [allowed_ips...]" << std::endl;
        return 1;
    }

    try {
        SimpleIPFilter filter;
        for (int i = 2; i < argc; ++i) {
