class PacketFilter {
public:
    struct Rule {
        uint32_t src_ip = 0;
        uint32_t dst_ip = 0;
        uint16_t src_port = 0;
        uint16_t dst_port = 0;
        uint8_t protocol = 0; // 0 = any, 6 = TCP, 17 = UDP
        bool allow = true;
    };

    void add_rule(const Rule& rule) {
        rules.push_back(rule);
    }

    bool should_forward(const uint8_t* packet, size_t len) {
        if (len < sizeof(ethhdr) + sizeof(iphdr)) {
            return false;
        }

        const ethhdr* eth = reinterpret_cast<const ethhdr*>(packet);
        const iphdr* ip = reinterpret_cast<const iphdr*>(packet + sizeof(ethhdr));

        if (ip->version != 4) {
            return false; // Only IPv4 for this example
        }

        uint32_t src_ip = ntohl(ip->saddr);
        uint32_t dst_ip = ntohl(ip->daddr);

        // Check all rules in order
        for (const auto& rule : rules) {
            if ((rule.src_ip == 0 || rule.src_ip == src_ip) &&
                (rule.dst_ip == 0 || rule.dst_ip == dst_ip)) {

                if (rule.protocol == 0 || rule.protocol == ip->protocol) {
                    // Check transport layer if needed
                    if (ip->protocol == IPPROTO_TCP || ip->protocol == IPPROTO_UDP) {
                        size_t ip_header_len = ip->ihl * 4;
                        if (len < sizeof(ethhdr) + ip_header_len + sizeof(tcphdr)) {
                            continue;
                        }

                        const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + sizeof(ethhdr) + ip_header_len);
                        uint16_t src_port = ntohs(tcp->source);
                        uint16_t dst_port = ntohs(tcp->dest);

                        if ((rule.src_port == 0 || rule.src_port == src_port) &&
                            (rule.dst_port == 0 || rule.dst_port == dst_port)) {
                            return rule.allow;
                        }
                    } else {
                        // For non-TCP/UDP protocols, just match IP
                        return rule.allow;
                    }
                }
            }
        }

        // Default deny if no rules match
        return false;
    }

private:
    std::vector<Rule> rules;
};

class PacketForwarder {
public:
    PacketForwarder(const std::string& iface_name)
        : iface_name(iface_name), running(false) {
        // Create raw socket
        sock_fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (sock_fd < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(sock_fd, F_GETFL, 0);
        fcntl(sock_fd, F_SETFL, flags | O_NONBLOCK);

        // Get interface index
        struct ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, iface_name.c_str(), IFNAMSIZ);
        if (ioctl(sock_fd, SIOCGIFINDEX, &ifr) < 0) {
            perror("ioctl SIOCGIFINDEX");
            close(sock_fd);
            throw std::runtime_error("Failed to get interface index");
        }
        if_index = ifr.ifr_ifindex;

        // Get MAC address
        if (ioctl(sock_fd, SIOCGIFHWADDR, &ifr) < 0) {
            perror("ioctl SIOCGIFHWADDR");
            close(sock_fd);
            throw std::runtime_error("Failed to get MAC address");
        }
        memcpy(mac_addr, ifr.ifr_hwaddr.sa_data, 6);

        // Set up packet socket address
        memset(&sock_addr, 0, sizeof(sock_addr));
        sock_addr.sll_family = AF_PACKET;
        sock_addr.sll_protocol = htons(ETH_P_ALL);
        sock_addr.sll_ifindex = if_index;

        if (bind(sock_fd, reinterpret_cast<struct sockaddr*>(&sock_addr), sizeof(sock_addr)) < 0) {
            perror("bind");
            close(sock_fd);
            throw std::runtime_error("Failed to bind socket");
        }
    }

