        filter.add_rule(rule);
    }

    void start() {
        if (running) return;

        running = true;
        worker_thread = std::thread([this]() { this->run(); });
    }

    void stop() {
        if (!running) return;

        running = false;
        if (worker_thread.joinable()) {
            worker_thread.join();
        }
    }

private:
    void run() {
        const size_t buffer_size = 65536;
        uint8_t buffer[buffer_size];
        struct pollfd pfd = {sock_fd, POLLIN, 0};

        while (running) {
            int ret = poll(&pfd, 1, 10); // 10ms timeout
            if (ret < 0) {
                if (errno == EINTR) continue;
                perror("poll");
                break;
            }

            if (ret == 0) continue; // timeout

            if (pfd.revents & POLLIN) {
                ssize_t len = recv(sock_fd, buffer, buffer_size, 0);
                if (len < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
                    perror("recv");
                    break;
                }

                if (filter.should_forward(buffer, len)) {
