class PacketFilter {
public:
    virtual bool shouldForward(const rte_mbuf* pkt) = 0;
    virtual ~PacketFilter() = default;
};

class BasicIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(uint32_t ip) { allowedIPs[ip] = true; }
    void removeAllowedIP(uint32_t ip) { allowedIPs.erase(ip); }

    bool shouldForward(const rte_mbuf* pkt) override {
        const struct rte_ipv4_hdr* ip_hdr = rte_pktmbuf_mtod_offset(
            pkt, struct rte_ipv4_hdr*, sizeof(struct rte_ether_hdr));

        if (ip_hdr->version_ihl != 0x45) return false; // Not IPv4

        return allowedIPs.find(ip_hdr->src_addr) != allowedIPs.end() ||
               allowedIPs.find(ip_hdr->dst_addr) != allowedIPs.end();
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;
public:
    void addAllowedPort(uint16_t port) { allowedPorts[port] = true; }
    void removeAllowedPort(uint16_t port) { allowedPorts.erase(port); }

    bool shouldForward(const rte_mbuf* pkt) override {
        const struct rte_ipv4_hdr* ip_hdr = rte_pktmbuf_mtod_offset(
            pkt, struct rte_ipv4_hdr*, sizeof(struct rte_ether_hdr));

        if (ip_hdr->next_proto_id == IPPROTO_TCP) {
            const struct rte_tcp_hdr* tcp_hdr = (struct rte_tcp_hdr*)(ip_hdr + 1);
            return allowedPorts.find(rte_be_to_cpu_16(tcp_hdr->src_port)) != allowedPorts.end() ||
                   allowedPorts.find(rte_be_to_cpu_16(tcp_hdr->dst_port)) != allowedPorts.end();
        } else if (ip_hdr->next_proto_id == IPPROTO_UDP) {
            const struct rte_udp_hdr* udp_hdr = (struct rte_udp_hdr*)(ip_hdr + 1);
            return allowedPorts.find(rte_be_to_cpu_16(udp_hdr->src_port)) != allowedPorts.end() ||
                   allowedPorts.find(rte_be_to_cpu_16(udp_hdr->dst_port)) != allowedPorts.end();
        }
        return false;
    }
};

class PacketForwarder {
    std::vector<std::shared_ptr<PacketFilter>> filters;
    uint16_t inputPort;
    uint16_t outputPort;
    std::atomic<bool> running{false};
    std::thread workerThread;

public:
    PacketForwarder(uint16_t inPort, uint16_t outPort)
        : inputPort(inPort), outputPort(outPort) {}

    void addFilter(std::shared_ptr<PacketFilter> filter) {
        filters.push_back(filter);
    }

    void start() {
        running = true;
        workerThread = std::thread([this]() { this->processPackets(); });
    }

    void stop() {
        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

    void processPackets() {
        struct rte_mbuf* bufs[32];
        uint16_t nb_rx;

        while (running) {
            // Receive packets
            nb_rx = rte_eth_rx_burst(inputPort, 0, bufs, 32);
            if (unlikely(nb_rx == 0)) {
                continue;
            }

            for (uint16_t i = 0; i < nb_rx; i++) {
                bool shouldForward = true;

                // Apply all filters
                for (const auto& filter : filters) {
                    if (!filter->shouldForward(bufs[i])) {
                        shouldForward = false;
                        break;
                    }
                }

                if (shouldForward) {
                    // Forward packet
                    uint16_t nb_tx = rte_eth_tx_burst(outputPort, 0, &bufs[i], 1);
                    if (unlikely(nb_tx < 1)) {
                        rte_pktmbuf_free(bufs[i]);
                    }
                } else {
                    rte_pktmbuf_free(bufs[i]);
                }
            }
        }
    }
};

class LowLatencyNetworkService {
    std::vector<PacketForwarder> forwarders;
    std::mutex configMutex;

public:
    bool initialize(int argc, char** argv) {
        // Initialize DPDK
        int ret = rte_eal_init(argc, argv);
        if (ret < 0) {
            std::cerr << "DPDK initialization failed" << std::endl;
            return false;
        }

        // Initialize ports
        uint16_t nb_ports = rte_eth_dev_count_avail();
        if (nb_ports < 2) {
            std::cerr << "At least 2 ports required" << std::endl;
            return false;
        }

        // Configure ports (simplified for example)
        for (uint16_t port_id = 0; port_id < nb_ports; port_id++) {
            rte_eth_dev_configure(port_id, 1, 1, nullptr);
            rte_eth_dev_adjust_nb_rx_tx_desc(port_id, &nb_rx_desc, &nb_tx_desc);
            rte_eth_rx_queue_setup(port_id, 0, nb_rx_desc, rte_eth_dev_socket_id(port_id), nullptr, nullptr);
            rte_eth_tx_queue_setup(port_id, 0, nb_tx_desc, rte_eth_dev_socket_id(port_id), nullptr);
            rte_eth_dev_start(port_id);
        }

        return true;
    }

    void addForwarder(uint16_t inPort, uint16_t outPort) {
        std::lock_guard<std::mutex> lock(configMutex);
        forwarders.emplace_back(inPort, outPort);
    }

    void addFilterToForwarder(size_t forwarderIdx, std::shared_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(configMutex);
        if (forwarderIdx < forwarders.size()) {
            forwarders[forwarderIdx].addFilter(filter);
        }
    }

    void startAllForwarders() {
        for (auto& forwarder : forwarders) {
            forwarder.start();
        }
    }

    void stopAllForwarders() {
        for (auto& forwarder : forwarders) {
            forwarder.stop();
        }
    }
};
