class PacketFilter {
public:
    virtual ~PacketFilter() = default;
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
};

class SimpleIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(const std::string& ip) {
        uint32_t addr = inet_addr(ip.c_str());
        allowedIPs[addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        return allowedIPs.find(ip->saddr) != allowedIPs.end() ||
               allowedIPs.find(ip->daddr) != allowedIPs.end();
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;
public:
    void addAllowedPort(uint16_t port) {
        allowedPorts[port] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr) + sizeof(udphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        const uint8_t* transport = packet + (ip->ihl * 4);

        if (ip->protocol == IPPROTO_UDP) {
            const udphdr* udp = reinterpret_cast<const udphdr*>(transport);
            return allowedPorts.find(ntohs(udp->source)) != allowedPorts.end() ||
                   allowedPorts.find(ntohs(udp->dest)) != allowedPorts.end();
        }
        else if (ip->protocol == IPPROTO_TCP) {
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(transport);
            return allowedPorts.find(ntohs(tcp->source)) != allowedPorts.end() ||
                   allowedPorts.find(ntohs(tcp->dest)) != allowedPorts.end();
        }

        return false;
    }
};

class PacketForwarder {
    int outputSocket;
    std::string destinationIP;
    uint16_t destinationPort;

public:
    PacketForwarder(const std::string& destIP, uint16_t destPort)
        : destinationIP(destIP), destinationPort(destPort) {
        outputSocket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (outputSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(outputSocket, F_GETFL, 0);
        fcntl(outputSocket, F_SETFL, flags | O_NONBLOCK);
    }

    ~PacketForwarder() {
        if (outputSocket >= 0) {
            close(outputSocket);
        }
    }

    bool forwardPacket(const uint8_t* packet, size_t len) {
        sockaddr_in destAddr{};
        destAddr.sin_family = AF_INET;
        destAddr.sin_addr.s_addr = inet_addr(destinationIP.c_str());
        destAddr.sin_port = htons(destinationPort);

        ssize_t sent = sendto(outputSocket, packet, len, 0,
                            (sockaddr*)&destAddr, sizeof(destAddr));

        return sent == static_cast<ssize_t>(len);
    }
};

class LowLatencyNetworkService {
    int inputSocket;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unique_ptr<PacketForwarder> forwarder;
    std::atomic<bool> running{false};
    std::thread workerThread;
    std::mutex mtx;
    std::condition_variable cv;

    void processPackets() {
        const size_t bufferSize = 65536; // 64KB buffer
        uint8_t buffer[bufferSize];
        pollfd pfd{inputSocket, POLLIN, 0};

        while (running) {
            int ret = poll(&pfd, 1, 10); // 10ms timeout
            if (ret <= 0) continue;

            ssize_t bytesRead = recv(inputSocket, buffer, bufferSize, 0);
            if (bytesRead <= 0) continue;

            bool shouldForward = true;
            for (const auto& filter : filters) {
                if (!filter->shouldForward(buffer, bytesRead)) {
                    shouldForward = false;
                    break;
                }
            }

            if (shouldForward && forwarder) {
                forwarder->forwardPacket(buffer, bytesRead);
            }
        }
    }

public:
    LowLatencyNetworkService(const std::string& listenIP, uint16_t listenPort,
                           const std::string& forwardIP, uint16_t forwardPort)
        : forwarder(std::make_unique<PacketForwarder>(forwardIP, forwardPort)) {

        inputSocket = socket(AF_INET, SOCK_RAW, IPPROTO_IP);
        if (inputSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(inputSocket, F_GETFL, 0);
        fcntl(inputSocket, F_SETFL, flags | O_NONBLOCK);

        // Bind to specific IP if needed
        if (!listenIP.empty()) {
            sockaddr_in bindAddr{};
            bindAddr.sin_family = AF_INET;
            bindAddr.sin_addr.s_addr = inet_addr(listenIP.c_str());
            bindAddr.sin_port = htons(listenPort);

            if (bind(inputSocket, (sockaddr*)&bindAddr, sizeof(bindAddr)) < 0) {
                perror("Bind failed");
                close(inputSocket);
                throw std::runtime_error("Failed to bind socket");
            }
        }
    }

    ~LowLatencyNetworkService() {
        stop();
        if (inputSocket >= 0) {
            close(inputSocket);
        }
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(mtx);
        filters.push_back(std::move(filter));
    }

    void start() {
        if (running) return;

        running = true;
        workerThread = std::thread([this]() { processPackets(); });
    }

    void stop() {
        if (!running) return;

        running = false;
        cv.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }
};

