#include <sys/socket.h>
#include <unistd.h>
#include <poll.h>

class PacketProcessor {
public:
    struct Packet {
        uint8_t* data;
        size_t length;
        std::chrono::high_resolution_clock::time_point timestamp;
    };

    virtual ~PacketProcessor() = default;
    virtual void process(Packet& packet) = 0;
};

class RuleBasedFilter : public PacketProcessor {
public:
    struct Rule {
        uint16_t src_port = 0;
        uint16_t dst_port = 0;
        uint32_t src_ip = 0;
        uint32_t dst_ip = 0;
        uint8_t protocol = 0; // 0 = any, 6 = TCP, 17 = UDP
        bool allow = true;
    };

    void add_rule(const Rule& rule) {
        rules_.push_back(rule);
    }

    void process(Packet& packet) override {
        if (packet.length < sizeof(iphdr)) {
            return; // Not enough data for IP header
        }

        iphdr* ip_header = reinterpret_cast<iphdr*>(packet.data);

        // Check if packet matches any rule
        for (const auto& rule : rules_) {
            if (rule.protocol != 0 && rule.protocol != ip_header->protocol) {
                continue;
            }

            if (rule.src_ip != 0 && rule.src_ip != ip_header->saddr) {
                continue;
            }

            if (rule.dst_ip != 0 && rule.dst_ip != ip_header->daddr) {
                continue;
            }

            // Check transport layer if needed
            if (ip_header->protocol == IPPROTO_TCP || ip_header->protocol == IPPROTO_UDP) {
                if (packet.length < sizeof(iphdr) + sizeof(tcphdr)) {
                    continue;
                }

                tcphdr* tcp_header = reinterpret_cast<tcphdr*>(packet.data + sizeof(iphdr));

                if (rule.src_port != 0 && rule.src_port != ntohs(tcp_header->source)) {
                    continue;
                }

                if (rule.dst_port != 0 && rule.dst_port != ntohs(tcp_header->dest)) {
                    continue;
                }
            }

            // Packet matches this rule
            if (!rule.allow) {
                // Drop packet
                packet.length = 0;
            }
            return;
        }

        // No matching rule - default action (allow)
    }

private:
    std::vector<Rule> rules_;
};

class PacketForwarder : public PacketProcessor {
public:
    PacketForwarder(int output_fd) : output_fd_(output_fd) {}

    void process(Packet& packet) override {
        if (packet.length == 0) {
            return; // Dropped packet
        }

        ssize_t sent = sendto(output_fd_, packet.data, packet.length, 0, nullptr, 0);
        if (sent < 0) {
            std::cerr << "Error sending packet: " << strerror(errno) << std::endl;
        }
    }

private:
    int output_fd_;
};

class NetworkService {
public:
    NetworkService(int input_fd, int output_fd)
        : input_fd_(input_fd), output_fd_(output_fd),
          filter_(std::make_unique<RuleBasedFilter>()),
          forwarder_(std::make_unique<PacketForwarder>(output_fd)) {

        // Set up poll structure
        poll_fds_[0].fd = input_fd_;
        poll_fds_[0].events = POLLIN;
        poll_fds_[1].fd = output_fd_;
        poll_fds_[1].events = POLLOUT;
    }

    void add_filter_rule(const RuleBasedFilter::Rule& rule) {
        filter_->add_rule(rule);
    }

    void run() {
        running_ = true;
        std::thread processing_thread([this]() { process_packets(); });

        while (running_) {
            int ret = poll(poll_fds_, 2, 1000);

            if (ret < 0) {
                if (errno == EINTR) continue;
                std::cerr << "Poll error: " << strerror(errno) << std::endl;
                break;
            }

            if (ret == 0) {
                continue; // Timeout
            }

            // Handle events if needed
        }

        running_ = false;
        processing_thread.join();
    }

    void stop() {
        running_ = false;
    }

private:
    void process_packets() {
        const size_t buffer_size = 65536; // Maximum packet size
        uint8_t buffer[buffer_size];

        while (running_) {
            ssize_t received = recv(input_fd_, buffer, buffer_size, 0);
            if (received < 0) {
                if (errno == EAGAIN || errno == EWOULDBLOCK) {
                    std::this_thread::sleep_for(std::chrono::microseconds(10));
                    continue;
                }
                std::cerr << "Error receiving packet: " << strerror(errno) << std::endl;
                continue;
            }

            PacketProcessor::Packet packet{
                buffer,
                static_cast<size_t>(received),
                std::chrono::high_resolution_clock::now()
            };

            // Process through filter
            filter_->process(packet);

            // Forward if not dropped
            forwarder_->process(packet);
        }
    }

    int input_fd_;
    int output_fd_;
    std::atomic<bool> running_{false};
    struct pollfd poll_fds_[2];

    std::unique_ptr<RuleBasedFilter> filter_;
    std::unique_ptr<PacketForwarder> forwarder_;
};

int main() {
    // Example usage
    int input_fd = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (input_fd < 0) {
        std::cerr << "Failed to create input socket: " << strerror(errno) << std::endl;
        return 1;
    }

    int output_fd = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (output_fd < 0) {
        std::cerr << "Failed to create output socket: " << strerror(errno) << std::endl;
        close(input_fd);
        return 1;
    }

    // Set socket options for raw sockets
    int one = 1;
    if (setsockopt(input_fd, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one)) < 0) {
        std::cerr << "Failed to set IP_HDRINCL: " << strerror(errno) << std::endl;
        close(input_fd);
