class PacketFilter {
public:
    virtual ~PacketFilter() = default;
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
};

class SimpleIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(const std::string& ip) {
        uint32_t addr = inet_addr(ip.c_str());
        allowedIPs[addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        return allowedIPs.find(ip->saddr) != allowedIPs.end() ||
               allowedIPs.find(ip->daddr) != allowedIPs.end();
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;
public:
    void addAllowedPort(uint16_t port) {
        allowedPorts[port] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr) + sizeof(tcphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        if (ip->protocol == IPPROTO_TCP) {
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + (ip->ihl << 2));
            return allowedPorts.find(ntohs(tcp->source)) != allowedPorts.end() ||
                   allowedPorts.find(ntohs(tcp->dest)) != allowedPorts.end();
        } else if (ip->protocol == IPPROTO_UDP) {
            const udphdr* udp = reinterpret_cast<const udphdr*>(packet + (ip->ihl << 2));
            return allowedPorts.find(ntohs(udp->source)) != allowedPorts.end() ||
                   allowedPorts.find(ntohs(udp->dest)) != allowedPorts.end();
        }
        return false;
    }
};

class PacketForwarder {
    int forwardSocket;
    std::string destinationIP;
    uint16_t destinationPort;

public:
    PacketForwarder(const std::string& destIP, uint16_t destPort)
        : destinationIP(destIP), destinationPort(destPort) {
        forwardSocket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (forwardSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }

        // Set socket to non-blocking
        int flags = fcntl(forwardSocket, F_GETFL, 0);
        fcntl(forwardSocket, F_SETFL, flags | O_NONBLOCK);
    }

    ~PacketForwarder() {
        if (forwardSocket >= 0) {
            close(forwardSocket);
        }
    }

    bool forwardPacket(const uint8_t* packet, size_t len) {
        sockaddr_in destAddr{};
        destAddr.sin_family = AF_INET;
        destAddr.sin_port = htons(destinationPort);
        inet_pton(AF_INET, destinationIP.c_str(), &destAddr.sin_addr);

        ssize_t sent = sendto(forwardSocket, packet, len, 0,
                            (sockaddr*)&destAddr, sizeof(destAddr));

        return sent == static_cast<ssize_t>(len);
    }
};

class NetworkService {
    int captureSocket;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unique_ptr<PacketForwarder> forwarder;
    std::atomic<bool> running{false};
    std::thread workerThread;
    std::mutex mtx;
    std::condition_variable cv;

    void captureAndProcess() {
        const size_t BUFFER_SIZE = 65536;
        uint8_t buffer[BUFFER_SIZE];

        while (running) {
            pollfd pfd{};
            pfd.fd = captureSocket;
            pfd.events = POLLIN;

            int ret = poll(&pfd, 1, 100); // 100ms timeout
            if (ret <= 0) continue;

            ssize_t bytesRead = recv(captureSocket, buffer, BUFFER_SIZE, 0);
            if (bytesRead <= 0) continue;

            bool shouldForward = true;
            for (const auto& filter : filters) {
                if (!filter->shouldForward(buffer, bytesRead)) {
                    shouldForward = false;
                    break;
                }
            }

            if (shouldForward && forwarder) {
                forwarder->forwardPacket(buffer, bytesRead);
            }
        }
    }

public:
    NetworkService(const std::string& captureInterface, const std::string& destIP, uint16_t destPort)
        : forwarder(std::make_unique<PacketForwarder>(destIP, destPort)) {
        captureSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (captureSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }

        // Bind to specific interface
        ifreq ifr{};
        strncpy(ifr.ifr_name, captureInterface.c_str(), IFNAMSIZ);
        if (setsockopt(captureSocket, SOL_SOCKET, SO_BINDTODEVICE, (void*)&ifr, sizeof(ifr)) < 0) {
            perror("Binding to interface failed");
            throw std::runtime_error("Binding to interface failed");
        }

        // Set socket to non-blocking
        int flags = fcntl(captureSocket, F_GETFL, 0);
        fcntl(captureSocket, F_SETFL, flags | O_NONBLOCK);
    }

    ~NetworkService() {
        stop();
        if (captureSocket >= 0) {
            close(captureSocket);
        }
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(mtx);
        filters.push_back(std::move(filter));
    }

    void start() {
        running = true;
        workerThread = std::thread(&NetworkService::captureAndProcess, this);
    }

    void stop() {
        running = false;
        cv.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }
};

int main() {
    try {
        // Create network service that captures on eth0 and forwards to 192.168.1.100:9000
        NetworkService service("eth0", "192.168.1.100", 9000);

        // Add IP filter (only allow packets from/to 192.168.1.10)
        auto ipFilter = std::make_unique<SimpleIPFilter>();
