#include <unistd.h>
#include <fcntl.h>
#include <poll.h>

class PacketProcessor {
public:
    virtual ~PacketProcessor() = default;
    virtual bool processPacket(const uint8_t* packet, size_t length) = 0;
};

class RuleBasedFilter : public PacketProcessor {
private:
    struct Rule {
        uint32_t src_ip;
        uint32_t dst_ip;
        uint16_t src_port;
        uint16_t dst_port;
        uint8_t protocol;
        bool allow;
    };

    std::vector<Rule> rules;
    std::mutex rules_mutex;

public:
    void addRule(uint32_t src_ip, uint32_t dst_ip,
                 uint16_t src_port, uint16_t dst_port,
                 uint8_t protocol, bool allow) {
        std::lock_guard<std::mutex> lock(rules_mutex);
        rules.push_back({src_ip, dst_ip, src_port, dst_port, protocol, allow});
    }

    bool processPacket(const uint8_t* packet, size_t length) override {
        const iphdr* ip_header = reinterpret_cast<const iphdr*>(packet);

        // Basic IP header validation
        if (length < sizeof(iphdr)) return false;
        if (ip_header->version != 4) return false;
        if (length < (ip_header->ihl * 4)) return false;

        uint32_t src_ip = ip_header->saddr;
        uint32_t dst_ip = ip_header->daddr;
        uint16_t src_port = 0;
        uint16_t dst_port = 0;
        uint8_t protocol = ip_header->protocol;

        // Extract transport layer ports if available
        if (protocol == IPPROTO_TCP || protocol == IPPROTO_UDP) {
            const uint8_t* transport_header = packet + (ip_header->ihl * 4);
            if (length < (ip_header->ihl * 4) + sizeof(tcphdr)) return false;

            if (protocol == IPPROTO_TCP) {
                const tcphdr* tcp_header = reinterpret_cast<const tcphdr*>(transport_header);
                src_port = ntohs(tcp_header->source);
                dst_port = ntohs(tcp_header->dest);
            } else {
                const udphdr* udp_header = reinterpret_cast<const udphdr*>(transport_header);
                src_port = ntohs(udp_header->source);
                dst_port = ntohs(udp_header->dest);
            }
        }

        // Check rules
        std::lock_guard<std::mutex> lock(rules_mutex);
        for (const auto& rule : rules) {
            bool match = true;

            if (rule.src_ip != 0 && rule.src_ip != src_ip) match = false;
            if (rule.dst_ip != 0 && rule.dst_ip != dst_ip) match = false;
            if (rule.src_port != 0 && rule.src_port != src_port) match = false;
            if (rule.dst_port != 0 && rule.dst_port != dst_port) match = false;
            if (rule.protocol != 0 && rule.protocol != protocol) match = false;

            if (match) {
                return rule.allow;
            }
        }

        // Default deny if no rules match
        return false;
    }
};

class PacketForwarder {
private:
    int forward_socket;
    std::string destination_ip;
    uint16_t destination_port;

public:
    PacketForwarder(const std::string& dest_ip, uint16_t dest_port)
        : destination_ip(dest_ip), destination_port(dest_port) {
        forward_socket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (forward_socket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Failed to create forward socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(forward_socket, F_GETFL, 0);
        fcntl(forward_socket, F_SETFL, flags | O_NONBLOCK);
    }

    ~PacketForwarder() {
        if (forward_socket >= 0) {
            close(forward_socket);
        }
    }

    bool forwardPacket(const uint8_t* packet, size_t length) {
        sockaddr_in dest_addr{};
        dest_addr.sin_family = AF_INET;
        dest_addr.sin_port = htons(destination_port);
        inet_pton(AF_INET, destination_ip.c_str(), &dest_addr.sin_addr);

        ssize_t sent = sendto(forward_socket, packet, length, 0,
                             reinterpret_cast<sockaddr*>(&dest_addr),
                             sizeof(dest_addr));

        return sent == static_cast<ssize_t>(length);
    }
};

class LowLatencyNetworkService {
private:
    int capture_socket;
    std::atomic<bool> running{false};
    std::thread processing_thread;
    std::vector<std::unique_ptr<PacketProcessor>> processors;
    std::unique_ptr<PacketForwarder> forwarder;
    std::mutex processor_mutex;

    void processingLoop() {
        const size_t buffer_size = 65536; // 64KB buffer
        uint8_t buffer[buffer_size];
        pollfd fds[1];

        fds[0].fd = capture_socket;
        fds[0].events = POLLIN;

        while (running) {
            int ret = poll(fds, 1, 10); // 10ms timeout

            if (ret < 0) {
                perror("Poll error");
                break;
            }

            if (ret == 0) {
                continue; // Timeout, no packets
            }

            if (fds[0].revents & POLLIN) {
                ssize_t bytes_read = recv(capture_socket, buffer, buffer_size, 0);

                if (bytes_read < 0) {
                    perror("Receive error");
                    continue;
                }

                // Process packet
                bool should_forward = true;

                {
                    std::lock_guard<std::mutex> lock(processor_mutex);
                    for (const auto& processor : processors) {
                        if (!processor->processPacket(buffer, bytes_read)) {
                            should_forward = false;
                            break;
                        }
                    }
                }

                // Forward if allowed
                if (should_forward && forwarder) {
                    forwarder->forwardPacket(buffer, bytes_read);
                }
            }
        }
    }

public:
    LowLatencyNetworkService(const std::string& capture_interface,
                            const std::string& forward_ip,
                            uint16_t forward_port) {
        // Create raw socket for packet capture
        capture_socket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (capture_socket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Failed to create capture socket");
        }

        // Bind to specific interface
        ifreq ifr;
        memset(&ifr, 0, sizeof(ifr));
        strncpy(ifr.ifr_name, capture_interface.c_str(), IFNAMSIZ-1);

        if (setsockopt(capture_socket, SOL_SOCKET, SO_BINDTODEVICE, &ifr, sizeof(ifr)) < 0) {
            perror("Socket bind failed");
            close(capture_socket);
            throw std::runtime_error("Failed to bind socket to interface");
        }

        // Set socket to non-blocking
        int flags = fcntl(capture_socket, F_GETFL, 0);
        fcntl(capture_socket, F_SETFL, flags | O_NONBLOCK);

        // Create forwarder if destination is specified
        if (!forward_ip.empty()) {
            forwarder = std::make_unique<PacketForwarder>(forward_ip, forward_port);
        }
    }

    ~LowLatencyNetworkService() {
