    std::vector<std::shared_ptr<PacketFilter>> filters;
    std::atomic<bool> running{false};
    std::thread worker_thread;
    std::mutex mtx;
    std::condition_variable cv;

public:
    PacketForwarder() : socket_fd(-1) {}

    ~PacketForwarder() {
        stop();
        if (socket_fd != -1) {
            close(socket_fd);
        }
