            int ret = poll(&pfd, 1, 10); // 10ms timeout
            if (ret <= 0) continue;

            if (pfd.revents & POLLIN) {
                ssize_t bytes_read = recv(socket_fd, buffer, buffer_size, 0);
                if (bytes_read <= 0) continue;

                // Apply filters
                bool should_forward = true;
                {
                    std::lock_guard<std::mutex> lock(mtx);
                    for (const auto& filter : filters) {
                        if (!filter->shouldForward(buffer, bytes_read)) {
                            should_forward = false;
                            break;
                        }
                    }
                }

                if (should_forward) {
                    // In a real implementation, we would forward the packet here
                    // For this example, we'll just print the packet info
                    processPacket(buffer, bytes_read);
                }
            }
        }
    }

    void processPacket(const uint8_t* packet, size_t length) {
        if (length < sizeof(iphdr)) return;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        char src_ip[INET_ADDRSTRLEN], dst_ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &ip->saddr, src_ip, INET_ADDRSTRLEN);
        inet_ntop(AF_INET, &ip->daddr, dst_ip, INET_ADDRSTRLEN);

        std::cout << "Forwarding packet: "
                  << src_ip << ":" << ntohs(ip->sport)
                  << " -> " << dst_ip << ":" << ntohs(ip->dport)
                  << " (" << length << " bytes)" << std::endl;
    }
};

