#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/udp.h>
#include <netinet/tcp.h>
#include <netinet/ether.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/if_packet.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <stdbool.h>

// Configuration structure
typedef struct {
    char* interface;
    uint16_t port;
    bool forward_all;
    char* forward_dest;
    uint16_t forward_port;
    bool verbose;
} Config;

// Packet filter rules
typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    bool allow;
} FilterRule;

// Global variables
Config config;
FilterRule* rules = NULL;
int rule_count = 0;
int sockfd = -1;
volatile sig_atomic_t running = 1;

// Signal handler for graceful shutdown
void sigint_handler(int sig) {
    running = 0;
}

// Initialize configuration with defaults
void init_config() {
    config.interface = "eth0";
    config.port = 0; // 0 means all ports
    config.forward_all = false;
    config.forward_dest = NULL;
    config.forward_port = 0;
    config.verbose = false;
}

// Add a filter rule
void add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                    uint16_t src_port, uint16_t dst_port,
                    uint8_t protocol, bool allow) {
    rule_count++;
    rules = realloc(rules, rule_count * sizeof(FilterRule));
    if (!rules) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    FilterRule* rule = &rules[rule_count - 1];
    rule->src_ip = src_ip;
    rule->dst_ip = dst_ip;
    rule->src_port = src_port;
    rule->dst_port = dst_port;
    rule->protocol = protocol;
    rule->allow = allow;
}

// Check if packet matches any filter rule
bool packet_matches_rule(const struct iphdr* iph, const void* transport_header) {
    if (rule_count == 0) return true; // No rules = allow all

    uint16_t src_port = 0, dst_port = 0;

    if (iph->protocol == IPPROTO_TCP) {
        const struct tcphdr* tcph = (struct tcphdr*)transport_header;
        src_port = ntohs(tcph->source);
        dst_port = ntohs(tcph->dest);
    } else if (iph->protocol == IPPROTO_UDP) {
        const struct udphdr* udph = (struct udphdr*)transport_header;
        src_port = ntohs(udph->source);
        dst_port = ntohs(udph->dest);
    }

    for (int i = 0; i < rule_count; i++) {
        FilterRule* rule = &rules[i];

        // Check protocol
        if (rule->protocol != 0 && rule->protocol != iph->protocol) {
            continue;
        }

        // Check source IP
        if (rule->src_ip != 0 && rule->src_ip != iph->saddr) {
            continue;
        }

        // Check destination IP
        if (rule->dst_ip != 0 && rule->dst_ip != iph->daddr) {
            continue;
        }

        // Check source port
        if (rule->src_port != 0 && rule->src_port != src_port) {
            continue;
        }

        // Check destination port
        if (rule->dst_port != 0 && rule->dst_port != dst_port) {
            continue;
        }

        // If we get here, the rule matches
        return rule->allow;
    }

    // No matching rule found - default deny
    return false;
}

// Forward packet to destination
void forward_packet(const uint8_t* packet, int len) {
    if (!config.forward_dest || config.forward_port == 0) {
        return;
    }

    struct sockaddr_in dest_addr;
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(config.forward_port);
    inet_pton(AF_INET, config.forward_dest, &dest_addr.sin_addr);

    if (sendto(sockfd, packet, len, 0,
               (struct sockaddr*)&dest_addr, sizeof(dest_addr)) < 0) {
        if (config.verbose) {
            perror("Failed to forward packet");
        }
    }
}

// Process incoming packet
void process_packet(const uint8_t* packet, int len) {
    struct iphdr* iph = (struct iphdr*)(packet + sizeof(struct ethhdr));

    // Verify IP header length
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) {
        if (config.verbose) {
            printf("Packet too short for IP header\n");
        }
        return;
    }

    // Calculate transport header position
    void* transport_header = (uint8_t*)iph + (iph->ihl * 4);

    // Check if packet matches filter rules
    if (!packet_matches_rule(iph, transport_header)) {
        if (config.verbose) {
            printf("Packet dropped by filter rules\n");
        }
        return;
    }

    // Forward packet if configured
    if (config.forward_all || config.forward_dest) {
        forward_packet(packet, len);
    }
}

// Main packet processing loop
void* packet_processor(void* arg) {
    uint8_t buffer[65536];
    struct sockaddr_ll sender;
    socklen_t sender_len = sizeof(sender);

    while (running) {
        int packet_len = recvfrom(sockfd, buffer, sizeof(buffer), 0,
                                 (struct sockaddr*)&sender, &sender_len);

        if (packet_len < 0) {
            if (running) { // Only print error if we're not shutting down
                perror("recvfrom failed");
            }
            continue;
        }

        process_packet(buffer, packet_len);
    }

    return NULL;
}

// Initialize raw socket
void init_socket() {
    struct sockaddr_ll sll;
    struct ifreq ifr;

    // Create raw socket
    sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Get interface index
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, config.interface, IFNAMSIZ - 1);
    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl SIOCGIFINDEX failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Bind to interface
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind failed");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Set socket to non-blocking if needed
    // fcntl(sockfd, F_SETFL, O_NONBLOCK);
}

// Main function
int main(int argc, char* argv[]) {
    // Initialize configuration
    init_config();

    // Parse command line arguments (simplified for example)
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            config.interface = argv[++i];
        } else if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            config.port = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            config.forward_all = true;
            config.forward_dest = argv[++i];
            if (i + 1 < argc && argv[i+1][0] != '-') {
                config.forward_port = atoi(argv[++i]);
            }
        } else if (strcmp(argv[i], "-v") == 0) {
            config.verbose = true;
        } else if (strcmp(argv[i], "-r") == 0 && i + 6 < argc) {
            // Add filter rule: -r src_ip dst_ip src_port dst_port protocol allow
            uint32_t src_ip = inet_addr(argv[++i]);
            uint32_t dst_ip = inet_addr(argv[++i]);
            uint16_t src_port = atoi(argv[++i]);
            uint16_t dst_port = atoi(argv[++i]);
            uint8_t protocol = atoi(argv[++i]);
            bool allow = atoi(argv[++i]) != 0;
            add_filter_rule(src_ip, dst_ip, src_port, dst_port, protocol, allow);
        }
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Initialize socket
    init_socket();

    // Start packet processing thread
    pthread_t processor_thread;
    if (pthread_create(&processor_thread, NULL, packet_processor, NULL) != 0) {
        perror("Failed to create processing thread");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    printf("Ultra-low-latency networking service running on %s\n", config.interface);
    if (config.forward_dest) {
        printf("Forwarding packets to %s:%d\n", config.forward_dest, config.forward_port);
    }

    // Wait for signal
    while (running) {
        sleep(1);
    }

    // Cleanup
    pthread_join(processor_thread, NULL);
    close(sockfd);
    free(rules);

    printf("Service stopped\n");
    return 0;
}
