#include <unistd.h>
#include <poll.h>

class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t length) = 0;
    virtual ~PacketFilter() = default;
};

class BasicIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(uint32_t ip) { allowedIPs[ip] = true; }
    void removeAllowedIP(uint32_t ip) { allowedIPs.erase(ip); }

    bool shouldForward(const uint8_t* packet, size_t length) override {
        if (length < sizeof(struct iphdr)) return false;

        const struct iphdr* iph = reinterpret_cast<const struct iphdr*>(packet);
        uint32_t src_ip = ntohl(iph->saddr);

        return allowedIPs.find(src_ip) != allowedIPs.end();
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;
public:
    void addAllowedPort(uint16_t port) { allowedPorts[port] = true; }
    void removeAllowedPort(uint16_t port) { allowedPorts.erase(port); }

    bool shouldForward(const uint8_t* packet, size_t length) override {
        if (length < sizeof(struct iphdr)) return false;

        const struct iphdr* iph = reinterpret_cast<const struct iphdr*>(packet);

        if (iph->protocol == IPPROTO_TCP && length >= sizeof(struct iphdr) + sizeof(struct tcphdr)) {
            const struct tcphdr* tcph = reinterpret_cast<const struct tcphdr*>(packet + sizeof(struct iphdr));
            uint16_t src_port = ntohs(tcph->source);
            return allowedPorts.find(src_port) != allowedPorts.end();
        }
        else if (iph->protocol == IPPROTO_UDP && length >= sizeof(struct iphdr) + sizeof(struct udphdr)) {
            const struct udphdr* udph = reinterpret_cast<const struct udphdr*>(packet + sizeof(struct iphdr));
            uint16_t src_port = ntohs(udph->source);
            return allowedPorts.find(src_port) != allowedPorts.end();
        }

        return false;
    }
};

class LowLatencyForwarder {
    int inputSocket;
    int outputSocket;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::atomic<bool> running;
    std::thread workerThread;

public:
    LowLatencyForwarder(const std::string& inputInterface, const std::string& outputInterface)
        : running(false) {

        // Create raw socket for input
        inputSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (inputSocket < 0) {
            perror("socket");
            throw std::runtime_error("Failed to create input socket");
        }

        // Create raw socket for output
        outputSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
        if (outputSocket < 0) {
            perror("socket");
            close(inputSocket);
            throw std::runtime_error("Failed to create output socket");
        }

        // Bind to interfaces (simplified - in production you'd need proper interface binding)
    }

    ~LowLatencyForwarder() {
        stop();
        close(inputSocket);
        close(outputSocket);
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        filters.push_back(std::move(filter));
    }

    void start() {
        if (running) return;

        running = true;
        workerThread = std::thread([this]() { this->processPackets(); });
    }

    void stop() {
        if (!running) return;

        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void processPackets() {
        const size_t bufferSize = 65536; // Jumbo frame size
        uint8_t buffer[bufferSize];

        struct pollfd pfd;
        pfd.fd = inputSocket;
        pfd.events = POLLIN;

        while (running) {
            int pollResult = poll(&pfd, 1, 10); // 10ms timeout
            if (pollResult <= 0) continue;

            ssize_t bytesRead = recv(inputSocket, buffer, bufferSize, 0);
            if (bytesRead <= 0) continue;

            // Apply all filters
            bool shouldForward = true;
            for (const auto& filter : filters) {
                if (!filter->shouldForward(buffer, bytesRead)) {
                    shouldForward = false;
                    break;
                }
            }

            if (shouldForward) {
                // Forward the packet
                send(outputSocket, buffer, bytesRead, 0);
            }
        }
    }
};

int main() {
    try {
        LowLatencyForwarder forwarder("eth0", "eth1");

        // Add some filters
        auto ipFilter = std::make_unique<BasicIPFilter>();
        ipFilter->addAllowedIP(inet_addr("192.168.1.100")); // Example IP
        forwarder.addFilter(std::move(ipFilter));

        auto portFilter = std::make_unique<PortFilter>();
        portFilter->addAllowedPort(80); // HTTP
        portFilter->addAllowedPort(443); // HTTPS
        forwarder.addFilter(std::move(portFilter));

        forwarder.start();

        std::cout << "Forwarder running. Press Enter to stop..." << std::endl;
        std::cin.get();

        forwarder.stop();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
