#include <net/ethernet.h>
#include <net/if.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/if_packet.h>
#include <pthread.h>
#include <time.h>
#include <stdbool.h>

#define MAX_PACKET_SIZE 65536
#define MAX_RULES 1024
#define MAX_THREADS 4

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    bool allow;
} FilterRule;

typedef struct {
    int sockfd;
    char ifname[IFNAMSIZ];
    FilterRule rules[MAX_RULES];
    int rule_count;
    pthread_mutex_t rule_mutex;
} NetworkService;

typedef struct {
    NetworkService *service;
    int thread_id;
} ThreadArgs;

// Global service instance
NetworkService service;

// Packet processing function
void process_packet(unsigned char *buffer, int size) {
    struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));
    int ip_header_len = ip_header->ihl * 4;

    // Check if it's an IPv4 packet
    if (ip_header->version != 4) {
        return;
    }

    // Get source and destination IPs
    uint32_t src_ip = ntohl(ip_header->saddr);
    uint32_t dst_ip = ntohl(ip_header->daddr);

    // Check transport layer protocol
    uint8_t protocol = ip_header->protocol;
    uint16_t src_port = 0, dst_port = 0;

    if (protocol == IPPROTO_TCP) {
        struct tcphdr *tcp_header = (struct tcphdr *)(buffer + sizeof(struct ethhdr) + ip_header_len);
        src_port = ntohs(tcp_header->source);
        dst_port = ntohs(tcp_header->dest);
    } else if (protocol == IPPROTO_UDP) {
        struct udphdr *udp_header = (struct udphdr *)(buffer + sizeof(struct ethhdr) + ip_header_len);
        src_port = ntohs(udp_header->source);
        dst_port = ntohs(udp_header->dest);
    }

    // Check against filter rules
    bool allowed = true;
    pthread_mutex_lock(&service.rule_mutex);
    for (int i = 0; i < service.rule_count; i++) {
        FilterRule *rule = &service.rules[i];

        // Check if rule matches
        if ((rule->src_ip == 0 || rule->src_ip == src_ip) &&
            (rule->dst_ip == 0 || rule->dst_ip == dst_ip) &&
            (rule->src_port == 0 || rule->src_port == src_port) &&
            (rule->dst_port == 0 || rule->dst_port == dst_port) &&
            (rule->protocol == 0 || rule->protocol == protocol)) {

            allowed = rule->allow;
            break;
        }
    }
    pthread_mutex_unlock(&service.rule_mutex);

    if (allowed) {
        // Forward the packet (simplified - in real implementation would send to another interface)
        printf("Forwarding packet from %u.%u.%u.%u:%u to %u.%u.%u.%u:%u\n",
               (src_ip >> 24) & 0xFF, (src_ip >> 16) & 0xFF, (src_ip >> 8) & 0xFF, src_ip & 0xFF, src_port,
               (dst_ip >> 24) & 0xFF, (dst_ip >> 16) & 0xFF, (dst_ip >> 8) & 0xFF, dst_ip & 0xFF, dst_port);
    } else {
        printf("Dropping packet from %u.%u.%u.%u:%u to %u.%u.%u.%u:%u\n",
               (src_ip >> 24) & 0xFF, (src_ip >> 16) & 0xFF, (src_ip >> 8) & 0xFF, src_ip & 0xFF, src_port,
               (dst_ip >> 24) & 0xFF, (dst_ip >> 16) & 0xFF, (dst_ip >> 8) & 0xFF, dst_ip & 0xFF, dst_port);
    }
}

// Worker thread function
void* worker_thread(void* arg) {
    ThreadArgs *args = (ThreadArgs *)arg;
    NetworkService *service = args->service;
    int thread_id = args->thread_id;

    unsigned char buffer[MAX_PACKET_SIZE];
    struct sockaddr_ll socket_address;
    socklen_t socklen = sizeof(socket_address);

    printf("Thread %d started\n", thread_id);

    while (1) {
        int packet_size = recvfrom(service->sockfd, buffer, MAX_PACKET_SIZE, 0,
                                 (struct sockaddr *)&socket_address, &socklen);

        if (packet_size < 0) {
            perror("recvfrom");
            continue;
        }

        process_packet(buffer, packet_size);
    }

    return NULL;
}

// Initialize the network service
void init_service(const char *ifname) {
    // Initialize service structure
    memset(&service, 0, sizeof(NetworkService));
    strncpy(service.ifname, ifname, IFNAMSIZ - 1);
    pthread_mutex_init(&service.rule_mutex, NULL);

    // Create raw socket
    service.sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (service.sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind to interface
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);

    if (setsockopt(service.sockfd, SOL_SOCKET, SO_BINDTODEVICE, (void *)&ifr, sizeof(ifr)) < 0) {
        perror("setsockopt");
        close(service.sockfd);
        exit(EXIT_FAILURE);
    }

    // Set socket to non-blocking
    int flags = fcntl(service.sockfd, F_GETFL, 0);
    fcntl(service.sockfd, F_SETFL, flags | O_NONBLOCK);

    printf("Service initialized on interface %s\n", ifname);
}

// Add a filter rule
void add_filter_rule(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port,
                    uint16_t dst_port, uint8_t protocol, bool allow) {
    if (service.rule_count >= MAX_RULES) {
        printf("Maximum number of rules reached\n");
        return;
    }

    pthread_mutex_lock(&service.rule_mutex);
    FilterRule *rule = &service.rules[service.rule_count++];
    rule->src_ip = src_ip;
    rule->dst_ip = dst_ip;
    rule->src_port = src_port;
    rule->dst_port = dst_port;
    rule->protocol = protocol;
    rule->allow = allow;
    pthread_mutex_unlock(&service.rule_mutex);

    printf("Added %s rule: %u.%u.%u.%u:%u -> %u.%u.%u.%u:%u (proto %u)\n",
           allow ? "allow" : "deny",
           (src_ip >> 24) & 0xFF, (src_ip >> 16) & 0xFF, (src_ip >> 8) & 0xFF, src_ip & 0xFF, src_port,
           (dst_ip >> 24) & 0xFF, (dst_ip >> 16) & 0xFF, (dst_ip >> 8) & 0xFF, dst_ip & 0xFF, dst_port,
           protocol);
}

// Start the service with multiple worker threads
void start_service() {
    pthread_t threads[MAX_THREADS];
    ThreadArgs args[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        args[i].service = &service;
        args[i].thread_id = i;
        pthread_create(&threads[i], NULL, worker_thread, &args[i]);
    }

    // Wait for threads to finish (they run indefinitely)
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    init_service(argv[1]);

    // Example rules (in a real application, these would come from configuration)
    add_filter_rule(0, 0, 0, 0, IPPROTO_ICMP, false); // Block all ICMP
    add_filter_rule(0, 0, 0, 80, IPPROTO_TCP, true); // Allow HTTP
    add_filter_rule(0, 0, 0, 443, IPPROTO_TCP, true); // Allow HTTPS

    start_service();

    return 0;
}
