// Configuration structure
typedef struct {
    char* interface;
    uint16_t port;
    bool filter_enabled;
    uint32_t allowed_ip;
    uint32_t allowed_netmask;
} Config;

// Packet processing statistics
typedef struct {
    uint64_t packets_received;
    uint64_t packets_filtered;
    uint64_t packets_forwarded;
    uint64_t bytes_processed;
} Stats;

// Global variables
Config config = {
    .interface = "eth0",
    .port = 5000,
    .filter_enabled = true,
    .allowed_ip = 0x0100007f, // 127.0.0.1
    .allowed_netmask = 0x00ffffff // 255.255.255.0
};

Stats stats = {0};

// Function to initialize raw socket
int init_raw_socket(const char* interface) {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    // Set socket to non-blocking
    int flags = fcntl(sockfd, F_GETFL, 0);
    fcntl(sockfd, F_SETFL, flags | O_NONBLOCK);

    // Bind to interface
    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex(interface);
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

// Function to check if IP is allowed
bool is_ip_allowed(uint32_t ip) {
    if (!config.filter_enabled) return true;
    return (ip & config.allowed_netmask) == (config.allowed_ip & config.allowed_netmask);
}

// Packet processing function
void process_packet(int sockfd, const uint8_t* packet, ssize_t len) {
    stats.packets_received++;
    stats.bytes_processed += len;

    // Check for minimum packet size (Ethernet header + IP header)
    if (len < sizeof(struct ethhdr) + sizeof(struct iphdr)) {
        return;
    }

    // Get IP header
    struct iphdr* iph = (struct iphdr*)(packet + sizeof(struct ethhdr));

    // Check for UDP packets
    if (iph->protocol == IPPROTO_UDP) {
        struct udphdr* udph = (struct udphdr*)(packet + sizeof(struct ethhdr) + iph->ihl * 4);

        // Check if destination port matches
        if (ntohs(udph->dest) == config.port) {
            // Check if source IP is allowed
            if (is_ip_allowed(iph->saddr)) {
                // Forward the packet (in this simple example, we just count it)
                stats.packets_forwarded++;
            } else {
                stats.packets_filtered++;
            }
        }
    }
}

// Worker thread function
void* worker_thread(void* arg) {
    int sockfd = *(int*)arg;
    uint8_t buffer[65536];

    while (1) {
        ssize_t len = recv(sockfd, buffer, sizeof(buffer), 0);
        if (len < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, yield CPU
                sched_yield();
                continue;
            }
            perror("recv");
            break;
        }

        process_packet(sockfd, buffer, len);
    }

    return NULL;
}

// Statistics thread function
void* stats_thread(void* arg) {
    while (1) {
        sleep(1);
        printf("Stats - Received: %lu, Filtered: %lu, Forwarded: %lu, Bytes: %lu\n",
               stats.packets_received, stats.packets_filtered,
               stats.packets_forwarded, stats.bytes_processed);
    }

    return NULL;
}

int main(int argc, char* argv[]) {
    // Parse command line arguments
    if (argc > 1) {
        config.interface = argv[1];
    }
    if (argc > 2) {
        config.port = atoi(argv[2]);
    }

