    if (sockfd < 0) {
        return 1;
    }

    // Create worker thread
    pthread_t worker;
    if (pthread_create(&worker, NULL, worker_thread, &sockfd) != 0) {
        perror("pthread_create");
        close(sockfd);
        return 1;
    }

