        if (shouldForward && forwarder) {
            forwarder->forwardPacket(packet.data(), packet.size());
        }

        // Return buffer to pool
        {
            std::lock_guard<std::mutex> lock(bufferPoolMutex);
            bufferPool.push_back(std::move(packet));
