        }

        // Set socket to non-blocking
        int flags = fcntl(captureSocket, F_GETFL, 0);
        fcntl(captureSocket, F_SETFL, flags | O_NONBLOCK);

        // Initialize buffer pool
        for (auto& buffer : bufferPool) {
            buffer.resize(65536); // Standard MTU
        }

        // Start worker threads
        running = true;
        for (size_t i = 0; i < numWorkers; ++i) {
            workerThreads.emplace_back([this]() {
                while (running) {
                    std::vector<uint8_t> packet;
                    {
                        std::unique_lock<std::mutex> lock(bufferPoolMutex);
                        if (bufferPool.empty()) {
                            bufferAvailable.wait(lock);
                            continue;
                        }
                        packet = std::move(bufferPool.back());
                        bufferPool.pop_back();
                    }

                    // Process the packet
                    processPacket(std::move(packet));
                }
            });
        }
    }

    ~NetworkService() {
        stop();
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(filterMutex);
        filters.push_back(std::move(filter));
    }

    void setForwarder(std::unique_ptr<PacketForwarder> forwarder) {
        this->forwarder = std::move(forwarder);
    }

    void start() {
        running = true;
        workerThreads.emplace_back([this]() { captureLoop(); });
    }

    void stop() {
        running = false;
        if (captureSocket >= 0) close(captureSocket);
        for (auto& thread : workerThreads) {
            if (thread.joinable()) thread.join();
        }
        workerThreads.clear();
    }
};

