#include <mutex>

class PacketFilter {
public:
    virtual bool shouldForward(const uint8_t* packet, size_t length) = 0;
    virtual ~PacketFilter() = default;
};

class SimplePortFilter : public PacketFilter {
    uint16_t port_;
public:
    explicit SimplePortFilter(uint16_t port) : port_(port) {}

    bool shouldForward(const uint8_t* packet, size_t length) override {
        if (length < sizeof(iphdr) + sizeof(udphdr)) {
            return false;
        }

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        if (ip->protocol != IPPROTO_UDP) {
            return false;
        }

        const udphdr* udp = reinterpret_cast<const udphdr*>(packet + (ip->ihl * 4));
        return ntohs(udp->dest) == port_;
    }
};

class PacketForwarder {
    int sockfd_;
    std::vector<std::unique_ptr<PacketFilter>> filters_;
    std::mutex filters_mutex_;

public:
    explicit PacketForwarder(int sockfd) : sockfd_(sockfd) {}

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(filters_mutex_);
        filters_.push_back(std::move(filter));
    }

    bool processPacket(const uint8_t* packet, size_t length) {
        std::lock_guard<std::mutex> lock(filters_mutex_);

        for (const auto& filter : filters_) {
            if (!filter->shouldForward(packet, length)) {
                return false;
            }
        }

        // Forward the packet
        ssize_t sent = send(sockfd_, packet, length, 0);
        return sent == static_cast<ssize_t>(length);
    }
};

class NetworkService {
    int listen_sock_;
    int forward_sock_;
    std::atomic<bool> running_{false};
    std::thread worker_thread_;
    PacketForwarder forwarder_;

public:
    NetworkService(int listen_port, const std::string& forward_ip, int forward_port)
        : forwarder_(createForwardSocket(forward_ip, forward_port)) {
        listen_sock_ = createListenSocket(listen_port);
    }

    ~NetworkService() {
        stop();
    }

    void start() {
        running_ = true;
        worker_thread_ = std::thread([this]() { this->run(); });
    }

    void stop() {
        running_ = false;
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
        close(listen_sock_);
        close(forward_sock_);
    }

private:
    int createListenSocket(int port) {
        int sock = socket(AF_INET, SOCK_RAW, IPPROTO_UDP);
        if (sock < 0) {
            perror("socket");
            exit(EXIT_FAILURE);
        }

        // Set socket options for low latency
        int one = 1;
        setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
        setsockopt(sock, SOL_SOCKET, SO_RCVBUF, &one, sizeof(one));

        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(port);

        if (bind(sock, (sockaddr*)&addr, sizeof(addr)) < 0) {
            perror("bind");
            close(sock);
            exit(EXIT_FAILURE);
        }

        return sock;
    }

    int createForwardSocket(const std::string& ip, int port) {
        int sock = socket(AF_INET, SOCK_RAW, IPPROTO_UDP);
        if (sock < 0) {
            perror("socket");
            exit(EXIT_FAILURE);
        }

        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        inet_pton(AF_INET, ip.c_str(), &addr.sin_addr);

        if (connect(sock, (sockaddr*)&addr, sizeof(addr)) < 0) {
            perror("connect");
            close(sock);
            exit(EXIT_FAILURE);
        }

        return sock;
    }

    void run() {
        const size_t buffer_size = 65536; // Jumbo frame size
        std::vector<uint8_t> buffer(buffer_size);

        while (running_) {
            ssize_t received = recv(listen_sock_, buffer.data(), buffer_size, 0);
            if (received < 0) {
                if (errno == EINTR) continue;
                perror("recv");
                break;
            }

            if (!forwarder_.processPacket(buffer.data(), received)) {
                // Packet was filtered out
                continue;
            }
        }
    }
};

