    std::string destination_ip_;
    uint16_t destination_port_;
    std::unique_ptr<PacketFilter> filter_;

public:
    PacketForwarder(int socket_fd, const std::string& dest_ip, uint16_t dest_port,
                   std::unique_ptr<PacketFilter> filter)
        : socket_fd_(socket_fd), destination_ip_(dest_ip),
          destination_port_(dest_port), filter_(std::move(filter)) {}

    bool forwardPacket(const uint8_t* packet, size_t length) {
        if (!filter_ || filter_->shouldForward(packet, length)) {
            sockaddr_in dest_addr{};
            dest_addr.sin_family = AF_INET;
            dest_addr.sin_port = htons(destination_port_);
            inet_pton(AF_INET, destination_ip_.c_str(), &dest_addr.sin_addr);

            ssize_t sent = sendto(socket_fd_, packet, length, 0,
                                 reinterpret_cast<sockaddr*>(&dest_addr),
                                 sizeof(dest_addr));

            return sent == static_cast<ssize_t>(length);
        }
        return false;
    }
};

class NetworkService {
    int listen_socket_;
    std::vector<std::unique_ptr<PacketForwarder>> forwarders_;
    std::atomic<bool> running_{false};
    std::thread worker_thread_;

    void workerLoop() {
        const int buffer_size = 65536; // Jumbo frame support
        uint8_t buffer[buffer_size];
        pollfd fds[1];
        fds[0].fd = listen_socket_;
        fds[0].events = POLLIN;

        while (running_) {
            int ret = poll(fds, 1, 10); // 10ms timeout
            if (ret <= 0) continue;

            if (fds[0].revents & POLLIN) {
                sockaddr_in src_addr{};
                socklen_t addr_len = sizeof(src_addr);

                ssize_t received = recvfrom(listen_socket_, buffer, buffer_size, 0,
                                          reinterpret_cast<sockaddr*>(&src_addr), &addr_len);

                if (received > 0) {
                    for (auto& forwarder : forwarders_) {
                        forwarder->forwardPacket(buffer, received);
                    }
                }
            }
        }
    }

public:
    NetworkService(uint16_t listen_port) {
        listen_socket_ = socket(AF_INET, SOCK_RAW, IPPROTO_UDP);
        if (listen_socket_ < 0) {
            throw std::runtime_error("Failed to create socket");
        }

        // Set socket to non-blocking
        int flags = fcntl(listen_socket_, F_GETFL, 0);
        fcntl(listen_socket_, F_SETFL, flags | O_NONBLOCK);

        // Bind to specific port (if needed)
        sockaddr_in bind_addr{};
        bind_addr.sin_family = AF_INET;
        bind_addr.sin_port = htons(listen_port);
        bind_addr.sin_addr.s_addr = INADDR_ANY;

        if (bind(listen_socket_, reinterpret_cast<sockaddr*>(&bind_addr), sizeof(bind_addr)) < 0) {
            close(listen_socket_);
            throw std::runtime_error("Failed to bind socket");
        }
    }

    ~NetworkService() {
        stop();
        if (listen_socket_ >= 0) {
            close(listen_socket_);
        }
    }

    void addForwarder(const std::string& dest_ip, uint16_t dest_port,
                    std::unique_ptr<PacketFilter> filter) {
        forwarders_.emplace_back(std::make_unique<PacketForwarder>(
            listen_socket_, dest_ip, dest_port, std::move(filter)));
    }

    void start() {
        running_ = true;
        worker_thread_ = std::thread(&NetworkService::workerLoop, this);
    }

    void stop() {
        running_ = false;
        if (worker_thread_.joinable()) {
            worker_thread_.join();
        }
    }
};

