    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
};

class SimpleIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(const std::string& ip) {
        uint32_t addr = inet_addr(ip.c_str());
        allowedIPs[addr] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        return allowedIPs.find(ip->saddr) != allowedIPs.end();
    }
};

class PortFilter : public PacketFilter {
    std::unordered_map<uint16_t, bool> allowedPorts;
public:
    void addAllowedPort(uint16_t port) {
        allowedPorts[port] = true;
    }

    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr) + sizeof(udphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        if (ip->protocol == IPPROTO_UDP) {
            const udphdr* udp = reinterpret_cast<const udphdr*>(packet + sizeof(iphdr));
            return allowedPorts.find(ntohs(udp->dest)) != allowedPorts.end();
        } else if (ip->protocol == IPPROTO_TCP) {
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(packet + sizeof(iphdr));
            return allowedPorts.find(ntohs(tcp->dest)) != allowedPorts.end();
        }
        return false;
    }
};

class PacketForwarder {
    int forwardSocket;
    std::string destinationIP;
    uint16_t destinationPort;

public:
    PacketForwarder(const std::string& destIP, uint16_t destPort)
        : destinationIP(destIP), destinationPort(destPort) {
        forwardSocket = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (forwardSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }

        // Set socket to non-blocking
        int flags = fcntl(forwardSocket, F_GETFL, 0);
        fcntl(forwardSocket, F_SETFL, flags | O_NONBLOCK);
    }

    ~PacketForwarder() {
        close(forwardSocket);
    }

    bool forwardPacket(const uint8_t* packet, size_t len) {
        sockaddr_in destAddr{};
        destAddr.sin_family = AF_INET;
        destAddr.sin_addr.s_addr = inet_addr(destinationIP.c_str());
        destAddr.sin_port = htons(destinationPort);

        ssize_t sent = sendto(forwardSocket, packet, len, 0,
                            reinterpret_cast<sockaddr*>(&destAddr), sizeof(destAddr));

        return sent == static_cast<ssize_t>(len);
    }
};

class LowLatencyNetworkService {
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unique_ptr<PacketForwarder> forwarder;
    std::atomic<bool> running{false};
    std::thread workerThread;
    std::mutex mtx;
    std::condition_variable cv;

    int listenSocket;
    uint16_t listenPort;

public:
    LowLatencyNetworkService(uint16_t port, const std::string& forwardIP, uint16_t forwardPort)
        : listenPort(port), forwarder(std::make_unique<PacketForwarder>(forwardIP, forwardPort)) {

        listenSocket = socket(AF_INET, SOCK_RAW, IPPROTO_UDP);
        if (listenSocket < 0) {
            perror("Socket creation failed");
            throw std::runtime_error("Socket creation failed");
        }

        // Set socket to non-blocking
        int flags = fcntl(listenSocket, F_GETFL, 0);
        fcntl(listenSocket, F_SETFL, flags | O_NONBLOCK);

        // Bind to port
        sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = INADDR_ANY;
        addr.sin_port = htons(port);

        if (bind(listenSocket, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
            perror("Bind failed");
            throw std::runtime_error("Bind failed");
        }
    }

    ~LowLatencyNetworkService() {
        stop();
        close(listenSocket);
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        std::lock_guard<std::mutex> lock(mtx);
        filters.push_back(std::move(filter));
    }

    void start() {
        running = true;
        workerThread = std::thread([this]() { this->run(); });
    }

    void stop() {
        running = false;
        cv.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void run() {
        const size_t bufferSize = 65536; // 64KB buffer
        std::vector<uint8_t> buffer(bufferSize);

        pollfd fds[1];
        fds[0].fd = listenSocket;
        fds[0].events = POLLIN;

        while (running) {
            int ret = poll(fds, 1, 10); // 10ms timeout

            if (ret < 0) {
                perror("Poll error");
                break;
            }

            if (ret == 0) {
                continue; // Timeout, check running flag
            }

            if (fds[0].revents & POLLIN) {
                sockaddr_in srcAddr{};
                socklen_t addrLen = sizeof(srcAddr);

                ssize_t bytesRead = recvfrom(listenSocket, buffer.data(), bufferSize, 0,
                                           reinterpret_cast<sockaddr*>(&srcAddr), &addrLen);

                if (bytesRead < 0) {
                    if (errno != EAGAIN && errno != EWOULDBLOCK) {
                        perror("Recvfrom error");
                    }
                    continue;
                }

                // Process packet
                bool shouldForward = true;
                for (const auto& filter : filters) {
                    if (!filter->shouldForward(buffer.data(), bytesRead)) {
                        shouldForward = false;
                        break;
                    }
                }

                if (shouldForward) {
                    forwarder->forwardPacket(buffer.data(), bytesRead);
                }
            }
        }
    }
};

