#include <poll.h>

class PacketFilter {
public:
    virtual ~PacketFilter() = default;
    virtual bool shouldForward(const uint8_t* packet, size_t len) = 0;
};

class SimpleIPFilter : public PacketFilter {
    std::unordered_map<uint32_t, bool> allowedIPs;
public:
    void addAllowedIP(uint32_t ip) { allowedIPs[ip] = true; }
    bool shouldForward(const uint8_t* packet, size_t len) override {
        if (len < sizeof(iphdr)) return false;
        const iphdr* ip = reinterpret_cast<const iphdr*>(packet);
        return allowedIPs.find(ip->saddr) != allowedIPs.end();
    }
};

class PacketForwarder {
    int outputSocket;
    std::string destinationIP;
    uint16_t destinationPort;
public:
    PacketForwarder(int sock, const std::string& ip, uint16_t port)
        : outputSocket(sock), destinationIP(ip), destinationPort(port) {}

    void forward(const uint8_t* packet, size_t len) {
        sockaddr_in destAddr{};
        destAddr.sin_family = AF_INET;
        destAddr.sin_port = htons(destinationPort);
        inet_pton(AF_INET, destinationIP.c_str(), &destAddr.sin_addr);

        sendto(outputSocket, packet, len, 0,
               reinterpret_cast<sockaddr*>(&destAddr), sizeof(destAddr));
    }
};

class NetworkService {
    int inputSocket;
    std::vector<std::unique_ptr<PacketFilter>> filters;
    std::unique_ptr<PacketForwarder> forwarder;
    std::atomic<bool> running{false};
    std::thread workerThread;

    void processPackets() {
        const size_t bufferSize = 65536; // Jumbo frame size
        uint8_t buffer[bufferSize];
        pollfd fds[1];
        fds[0].fd = inputSocket;
        fds[0].events = POLLIN;

        while (running) {
            int ret = poll(fds, 1, 1000); // 1 second timeout
            if (ret <= 0) continue;

            if (fds[0].revents & POLLIN) {
                sockaddr_in srcAddr{};
                socklen_t addrLen = sizeof(srcAddr);
                ssize_t len = recvfrom(inputSocket, buffer, bufferSize, 0,
                                     reinterpret_cast<sockaddr*>(&srcAddr), &addrLen);

                if (len > 0) {
                    bool shouldForward = true;
                    for (auto& filter : filters) {
                        if (!filter->shouldForward(buffer, len)) {
                            shouldForward = false;
                            break;
                        }
                    }

                    if (shouldForward && forwarder) {
                        forwarder->forward(buffer, len);
                    }
                }
            }
        }
    }

public:
    NetworkService(int inputSock, const std::string& destIP, uint16_t destPort)
        : inputSocket(inputSock) {
        int outputSock = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
        if (outputSock < 0) {
            perror("Failed to create output socket");
            throw std::runtime_error("Socket creation failed");
        }

        forwarder = std::make_unique<PacketForwarder>(outputSock, destIP, destPort);
    }

    ~NetworkService() {
        stop();
        if (inputSocket >= 0) close(inputSocket);
    }

    void addFilter(std::unique_ptr<PacketFilter> filter) {
        filters.push_back(std::move(filter));
    }

    void start() {
        running = true;
        workerThread = std::thread(&NetworkService::processPackets, this);
    }

    void stop() {
        running = false;
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }
};

int main() {
    // Create input socket (raw socket for packet capture)
    int inputSocket = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (inputSocket < 0) {
        perror("Failed to create input socket");
        return 1;
    }

    // Create network service
    NetworkService service(inputSocket, "192.168.1.100", 5000);

    // Add filters
    auto ipFilter = std::make_unique<SimpleIPFilter>();
    ipFilter->addAllowedIP(inet_addr("192.168.1.1"));
    ipFilter->addAllowedIP(inet_addr("192.168.1.2"));
    service.addFilter(std::move(ipFilter));

    // Start the service
    service.start();

    std::cout << "Network service running. Press Enter to stop..." << std::endl;
    std::cin.get();

    service.stop();
    return 0;
}
