    if (bind(forward_socket, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(raw_socket);
        close(forward_socket);
        return 1;
    }

    // Set socket to non-blocking
    fcntl(raw_socket, F_SETFL, O_NONBLOCK);

