        fprintf(stderr, "Rule limit reached\n");
        return;
    }

    rules[rule_count].src_ip = src_ip;
    rules[rule_count].dst_ip = dst_ip;
    rules[rule_count].src_port = src_port;
    rules[rule_count].dst_port = dst_port;
    rules[rule_count].protocol = protocol;
    rules[rule_count].action = action;
    rule_count++;
}

int match_rule(const struct iphdr *ip, const void *transport) {
    for (int i = 0; i < rule_count; i++) {
        if (rules[i].src_ip != 0 && rules[i].src_ip != ip->saddr) continue;
        if (rules[i].dst_ip != 0 && rules[i].dst_ip != ip->daddr) continue;

        if (rules[i].protocol == IPPROTO_TCP) {
            const struct tcphdr *tcp = (struct tcphdr *)transport;
            if (rules[i].src_port != 0 && rules[i].src_port != ntohs(tcp->source)) continue;
            if (rules[i].dst_port != 0 && rules[i].dst_port != ntohs(tcp->dest)) continue;
        } else if (rules[i].protocol == IPPROTO_UDP) {
            const struct udphdr *udp = (struct udphdr *)transport;
            if (rules[i].src_port != 0 && rules[i].src_port != ntohs(udp->source)) continue;
            if (rules[i].dst_port != 0 && rules[i].dst_port != ntohs(udp->dest)) continue;
        }

        return rules[i].action;
    }
    return 1; // Default action: forward
}

