    struct sockaddr_ll sll;
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);
    if (bind(sock_fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sock_fd);
        return 1;
    }

    // Create raw socket for sending packets
    int send_sock = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
    if (send_sock < 0) {
        perror("send socket");
        close(sock_fd);
        return 1;
    }

    // Set IP_HDRINCL to include our own IP header
    int one = 1;
    if (setsockopt(send_sock, IPPROTO_IP, IP_HDRINCL, &one, sizeof(one)) < 0) {
        perror("setsockopt");
        close(sock_fd);
        close(send_sock);
        return 1;
    }

    // Add some example rules
    add_rule(0, 0, 0, 0, IPPROTO_TCP, 1); // Forward all TCP by default
    add_rule(0, 0, 0, 0, IPPROTO_UDP, 1); // Forward all UDP by default
    // add_rule(inet_addr("192.168.1.100"), 0, 0, 0, IPPROTO_TCP, 0); // Example drop rule

    printf("Packet filter running on %s, forwarding to %s\n", interface, dest_ip_str);

    uint8_t buffer[BUFFER_SIZE];
    struct sockaddr_ll from;
    socklen_t from_len = sizeof(from);

    while (1) {
        ssize_t len = recvfrom(sock_fd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&from, &from_len);
        if (len < 0) {
            perror("recvfrom");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr *eth = (struct ethhdr *)buffer;
        if (ntohs(eth->h_proto) != ETH_P_IP) {
            continue; // Skip non-IP packets
        }

        // Parse IP header
        struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP) {
            continue; // Skip non-TCP/UDP packets
        }

        // Get transport header
        void *transport = (void *)ip + (ip->ihl * 4);

        // Check if packet matches any rules
        if (!match_rule(ip, transport)) {
            continue; // Drop packet
        }

        // Forward packet to destination
        struct sockaddr_in dest_addr;
        memset(&dest_addr, 0, sizeof(dest_addr));
        dest_addr.sin_family = AF_INET;
        dest_addr.sin_addr.s_addr = dest_ip;

        // For raw sockets, we need to include the IP header
        if (sendto(send_sock, ip, len - sizeof(struct ethhdr), 0,
                  (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
            perror("sendto");
        }
    }

    close(sock_fd);
    close(send_sock);
    return 0;
}
