        perror("bind");
        close(sockfd);
        close(send_sockfd);
        return 1;
    }

    // Get interface index for sending
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, forward_interface, IFNAMSIZ - 1);
    if (ioctl(send_sockfd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl SIOCGIFINDEX");
        close(sockfd);
        close(send_sockfd);
        return 1;
    }
    int forward_ifindex = ifr.ifr_ifindex;

    // Set up address structure for sending
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = forward_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    // Add some example rules (allow all TCP traffic from 192.168.1.100)
    add_rule(inet_addr("192.168.1.100"), 0, 0, 0, IPPROTO_TCP, true);
    // Deny all other traffic by default

    printf("Packet filter running on %s, forwarding to %s\n", interface, forward_interface);

    uint8_t buffer[BUFFER_SIZE];
    struct sockaddr_ll from;
    socklen_t from_len = sizeof(from);

    while (1) {
        ssize_t bytes_received = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&from, &from_len);
        if (bytes_received < 0) {
            perror("recvfrom");
            continue;
        }

        // Check if it's an IP packet
        struct ethhdr *eth_header = (struct ethhdr *)buffer;
        if (ntohs(eth_header->h_proto) != ETH_P_IP) {
            continue;
        }

        struct iphdr *ip_header = (struct iphdr *)(buffer + sizeof(struct ethhdr));
        void *transport_header = (void *)(buffer + sizeof(struct ethhdr) + (ip_header->ihl * 4));

        if (should_forward(ip_header, transport_header)) {
            // Forward the packet
            if (sendto(send_sockfd, buffer, bytes_received, 0, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
                perror("sendto");
            }
        }
    }

    close(sockfd);
    close(send_sockfd);
    return 0;
}
