    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = ifr.ifr_ifindex;
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

int add_filter_rule(uint32_t src_ip, uint32_t dst_ip,
                   uint16_t src_port, uint16_t dst_port,
                   uint8_t protocol, uint8_t action) {
    pthread_mutex_lock(&rules_mutex);
    if (rule_count >= MAX_RULES) {
        pthread_mutex_unlock(&rules_mutex);
        return -1;
    }

    rules[rule_count].src_ip = src_ip;
    rules[rule_count].dst_ip = dst_ip;
    rules[rule_count].src_port = src_port;
    rules[rule_count].dst_port = dst_port;
    rules[rule_count].protocol = protocol;
    rules[rule_count].action = action;
    rule_count++;
    pthread_mutex_unlock(&rules_mutex);
    return 0;
}

int should_forward(const struct iphdr *ip, const void *transport) {
    uint32_t src_ip = ip->saddr;
    uint32_t dst_ip = ip->daddr;
    uint16_t src_port = 0, dst_port = 0;

    if (ip->protocol == IPPROTO_TCP) {
        const struct tcphdr *tcp = (const struct tcphdr *)transport;
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (ip->protocol == IPPROTO_UDP) {
        const struct udphdr *udp = (const struct udphdr *)transport;
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    }

    pthread_mutex_lock(&rules_mutex);
    for (int i = 0; i < rule_count; i++) {
        if ((rules[i].src_ip == 0 || rules[i].src_ip == src_ip) &&
            (rules[i].dst_ip == 0 || rules[i].dst_ip == dst_ip) &&
            (rules[i].src_port == 0 || rules[i].src_port == src_port) &&
            (rules[i].dst_port == 0 || rules[i].dst_port == dst_port) &&
            (rules[i].protocol == 0 || rules[i].protocol == ip->protocol)) {
            pthread_mutex_unlock(&rules_mutex);
            return rules[i].action;
        }
    }
    pthread_mutex_unlock(&rules_mutex);

    // Default action: forward
    return 1;
}

void process_packet(int sockfd) {
    char buffer[BUFFER_SIZE];
    struct sockaddr_ll from;
    socklen_t from_len = sizeof(from);

    ssize_t len = recvfrom(sockfd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&from, &from_len);
    if (len < 0) {
        perror("recvfrom");
        return;
    }

    // Parse Ethernet header
    struct ethhdr *eth = (struct ethhdr *)buffer;
    if (ntohs(eth->h_proto) != ETH_P_IP) {
        // Not an IP packet, ignore
        return;
    }

    // Parse IP header
    struct iphdr *ip = (struct iphdr *)(buffer + sizeof(struct ethhdr));
    if (ip->version != 4) {
        // Not IPv4, ignore
        return;
    }

    // Get transport header
    void *transport = (void *)ip + (ip->ihl * 4);

    // Check if we should forward this packet
    if (should_forward(ip, transport)) {
        // Forward the packet
        if (sendto(sockfd, buffer, len, 0, (struct sockaddr *)&from, from_len) < 0) {
            perror("sendto");
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    int sockfd = create_raw_socket(argv[1]);
    if (sockfd < 0) {
        return 1;
    }

    // Example: Add a rule to forward all TCP traffic from 192.168.1.100 to port 80
    add_filter_rule(inet_addr("192.168.1.100"), 0, 0, 80, IPPROTO_TCP, 1);

    // Example: Add a rule to drop all UDP traffic to port 53 (DNS)
    add_filter_rule(0, 0, 0, 53, IPPROTO_UDP, 0);

    printf("Ultra-low-latency packet filter running on %s\n", argv[1]);

    while (1) {
        process_packet(sockfd);
    }

    close(sockfd);
    return 0;
}
