# High-Throughput Streaming Data Parser

Here's a Python implementation of a streaming data parser designed for handling gigabyte-scale input with minimal memory overhead. This solution uses generators and chunked processing to avoid loading the entire file into memory.

```python
import json
import csv
from io import StringIO
from typing import Iterator, Union, Dict, List, Any
import gzip
import bz2
import zlib

class StreamingDataParser:
    """
    A high-throughput streaming data parser for large files with minimal memory overhead.
    Supports JSON, CSV, and compressed formats (gzip, bzip2, zlib).
    """

    def __init__(self, chunk_size: int = 1024 * 1024):
        """
        Initialize the parser with a specified chunk size.

        Args:
            chunk_size: Size of chunks to read from file (in bytes)
        """
        self.chunk_size = chunk_size

    def parse(self, file_path: str, file_type: str = 'auto') -> Iterator[Union[Dict, List]]:
        """
        Parse a file streamingly, yielding one record at a time.

        Args:
            file_path: Path to the input file
            file_type: Type of file ('json', 'csv', 'auto', or 'auto_compressed')

        Yields:
            Parsed records (dict for JSON, list for CSV)
        """
        # Determine file type if auto-detected
        if file_type == 'auto':
            file_type = self._detect_file_type(file_path)
        elif file_type == 'auto_compressed':
            file_type = self._detect_file_type(file_path, compressed=True)

        # Open file with appropriate handler
        with self._open_file(file_path) as file:
            if file_type == 'json':
                yield from self._parse_json_stream(file)
            elif file_type == 'csv':
                yield from self._parse_csv_stream(file)
            else:
                raise ValueError(f"Unsupported file type: {file_type}")

    def _detect_file_type(self, file_path: str, compressed: bool = False) -> str:
        """Detect file type based on extension."""
        if compressed:
            # Try to open as compressed file to detect actual content
            try:
                with gzip.open(file_path, 'rt') as f:
                    first_char = f.read(1)
                    if first_char == '[' or first_char == '{':
                        return 'json'
                    elif ',' in first_char:
                        return 'csv'
            except (gzip.BadGzipFile, OSError):
                try:
                    with bz2.open(file_path, 'rt') as f:
                        first_char = f.read(1)
                        if first_char == '[' or first_char == '{':
                            return 'json'
                        elif ',' in first_char:
                            return 'csv'
                except (OSError, EOFError):
                    try:
                        with open(file_path, 'rb') as f:
                            decompressor = zlib.decompressobj()
                            first_char = decompressor.decompress(f.read(1)).decode()
                            if first_char == '[' or first_char == '{':
                                return 'json'
                            elif ',' in first_char:
                                return 'csv'
                    except:
                        pass

        # Fallback to extension-based detection
        if file_path.endswith('.json') or file_path.endswith('.json.gz') or file_path.endswith('.json.bz2'):
            return 'json'
        elif file_path.endswith('.csv') or file_path.endswith('.csv.gz') or file_path.endswith('.csv.bz2'):
            return 'csv'
        else:
            raise ValueError("Could not determine file type. Please specify explicitly.")

    def _open_file(self, file_path: str):
        """Open file with appropriate handler based on compression."""
        if file_path.endswith('.gz'):
            return gzip.open(file_path, 'rt', encoding='utf-8')
        elif file_path.endswith('.bz2'):
            return bz2.open(file_path, 'rt', encoding='utf-8')
        elif file_path.endswith('.zlib'):
            # For zlib-compressed files, we need to handle the decompression manually
            class ZlibFile:
                def __init__(self, path):
                    self.path = path
                    self.decompressor = zlib.decompressobj()
                    self.buffer = b''

                def __enter__(self):
                    self.file = open(self.path, 'rb')
                    return self

                def __exit__(self, exc_type, exc_val, exc_tb):
                    self.file.close()

                def read(self, size=-1):
                    if size == -1:
                        # Read all remaining data
                        data = self.file.read()
                        self.buffer += data
                        decompressed = self.decompressor.decompress(self.buffer)
                        remaining = self.decompressor.unused_data
                        self.buffer = remaining
                        return decompressed.decode('utf-8')
                    else:
                        # Read chunk by chunk
                        while len(self.buffer) < size:
                            data = self.file.read(self.chunk_size)
                            if not data:
                                break
                            self.buffer += data

                        decompressed = self.decompressor.decompress(self.buffer[:size])
                        remaining = self.decompressor.unused_data
                        self.buffer = self.buffer[size:] + remaining
                        return decompressed.decode('utf-8')

            return ZlibFile(file_path)
        else:
            return open(file_path, 'r', encoding='utf-8')

    def _parse_json_stream(self, file) -> Iterator[Dict]:
        """Parse JSON file streamingly, handling both array and line-delimited formats."""
        buffer = ''
        in_array = False
        array_depth = 0

        for chunk in iter(lambda: file.read(self.chunk_size), ''):
            buffer += chunk

            # Check if we're in an array
            if not in_array and buffer.lstrip().startswith('['):
                in_array = True
                array_depth = 1

            if in_array:
                # Parse array format
                try:
                    # Try to parse the entire buffer as JSON array
                    data = json.loads(buffer)
                    if isinstance(data, list):
                        yield from data
                        buffer = ''
                        in_array = False
                    else:
                        # If it's not a list, we might have partial data
                        continue
                except json.JSONDecodeError:
                    # If we can't parse the entire buffer, try to find a complete array
                    # by looking for the closing bracket at the current depth
                    pass
            else:
                # Parse line-delimited JSON
                while True:
                    # Find the next newline
                    newline_pos = buffer.find('\n')
                    if newline_pos == -1:
                        break

                    line = buffer[:newline_pos].strip()
                    buffer = buffer[newline_pos+1:]

                    if line:
                        try:
                            yield json.loads(line)
                        except json.JSONDecodeError as e:
                            # Skip malformed lines or handle as needed
                            print(f"Warning: Skipping malformed JSON line: {e}")

        # Process any remaining data in the buffer
        if buffer.strip():
            try:
                if in_array:
                    data = json.loads(buffer)
                    if isinstance(data, list):
                        yield from data
                else:
                    yield json.loads(buffer)
            except json.JSONDecodeError as e:
                print(f"Warning: Skipping malformed JSON data at end of file: {e}")

    def _parse_csv_stream(self, file) -> Iterator[List]:
        """Parse CSV file streamingly."""
        # Use StringIO to handle the buffer
        buffer = StringIO()
        reader = csv.reader(buffer)

        # Read the header first if it exists
        header = None
        first_chunk = True

        for chunk in iter(lambda: file.read(self.chunk_size), ''):
            buffer.write(chunk)
            buffer.seek(0)

            for row in reader:
                if first_chunk and not header:
                    header = row
                    first_chunk = False
                else:
                    yield row if not header else dict(zip(header, row))

            # Clear the buffer and prepare for next chunk
            buffer.seek(0)
            buffer.truncate()

        # Process any remaining data in the buffer
        buffer.seek(0)
        for row in reader:
            if header:
                yield dict(zip(header, row))
            else:
                yield row

