# High-Throughput Streaming Data Parser

Here's a Python implementation of a streaming data parser designed for handling gigabyte-scale input with minimal memory overhead. This solution uses generators and chunked processing to avoid loading the entire file into memory.

```python
import json
import csv
from io import StringIO
import gzip
import bz2
import lzma
from typing import Iterator, Union, Dict, List, Any

class StreamingDataParser:
    """
    A high-throughput streaming data parser for large files with minimal memory overhead.
    Supports JSON, CSV, and compressed formats (gzip, bzip2, xz).
    """

    def __init__(self, chunk_size: int = 1024 * 1024):
        """
        Initialize the parser with a chunk size (default: 1MB).
        """
        self.chunk_size = chunk_size

    def parse(self, file_path: str, file_type: str = 'auto') -> Iterator[Union[Dict, List]]:
        """
        Parse a file streamingly, yielding one record at a time.

        Args:
            file_path: Path to the input file
            file_type: File type ('json', 'csv', 'auto') or compression type ('gz', 'bz2', 'xz')

        Yields:
            Parsed records (dict for JSON, list for CSV)
        """
        # Determine file type and compression
        if file_type == 'auto':
            file_type = self._detect_file_type(file_path)

        # Open file with appropriate handler
        with self._open_file(file_path) as file:
            if file_type == 'json':
                yield from self._parse_json(file)
            elif file_type == 'csv':
                yield from self._parse_csv(file)
            else:
                raise ValueError(f"Unsupported file type: {file_type}")

    def _detect_file_type(self, file_path: str) -> str:
        """Detect file type from extension."""
        if file_path.endswith('.json') or file_path.endswith('.json.gz') or file_path.endswith('.json.bz2') or file_path.endswith('.json.xz'):
            return 'json'
        elif file_path.endswith('.csv') or file_path.endswith('.csv.gz') or file_path.endswith('.csv.bz2') or file_path.endswith('.csv.xz'):
            return 'csv'
        else:
            raise ValueError("Could not determine file type. Please specify explicitly.")

    def _open_file(self, file_path: str):
        """Open file with appropriate compression handler."""
        if file_path.endswith('.gz'):
            return gzip.open(file_path, 'rt', encoding='utf-8')
        elif file_path.endswith('.bz2'):
            return bz2.open(file_path, 'rt', encoding='utf-8')
        elif file_path.endswith('.xz'):
            return lzma.open(file_path, 'rt', encoding='utf-8')
        else:
            return open(file_path, 'r', encoding='utf-8')

    def _parse_json(self, file) -> Iterator[Dict]:
        """Parse JSON file streamingly."""
        buffer = StringIO()
        depth = 0
        in_string = False
        escape = False

        for chunk in iter(lambda: file.read(self.chunk_size), ''):
            for char in chunk:
                if escape:
                    escape = False
                elif char == '"':
                    in_string = not in_string
                elif not in_string:
                    if char == '{':
                        depth += 1
                    elif char == '}':
                        depth -= 1

                buffer.write(char)

                if depth == 0 and not in_string and buffer.tell() > 0:
                    try:
                        record = json.loads(buffer.getvalue())
                        yield record
                        buffer = StringIO()
                    except json.JSONDecodeError:
                        # Handle malformed JSON (optional: add error handling)
                        pass

    def _parse_csv(self, file) -> Iterator[List]:
        """Parse CSV file streamingly."""
        reader = csv.reader(file)
        header = next(reader)  # Read header
        yield header  # Optionally yield header

        for row in reader:
            yield row

    def parse_with_progress(self, file_path: str, file_type: str = 'auto', progress_callback=None) -> Iterator[Union[Dict, List]]:
        """
        Parse with progress tracking.

        Args:
            file_path: Path to the input file
            file_type: File type ('json', 'csv', 'auto')
            progress_callback: Optional callback function to report progress (bytes processed)

        Yields:
            Parsed records
        """
        bytes_processed = 0
        with self._open_file(file_path) as file:
            if file_type == 'auto':
                file_type = self._detect_file_type(file_path)

            if file_type == 'json':
                buffer = StringIO()
                depth = 0
                in_string = False
                escape = False

                while True:
                    chunk = file.read(self.chunk_size)
                    if not chunk:
                        break

                    bytes_processed += len(chunk)
                    if progress_callback:
                        progress_callback(bytes_processed)

                    for char in chunk:
                        if escape:
                            escape = False
                        elif char == '"':
                            in_string = not in_string
                        elif not in_string:
                            if char == '{':
                                depth += 1
                            elif char == '}':
                                depth -= 1

                        buffer.write(char)

                        if depth == 0 and not in_string and buffer.tell() > 0:
                            try:
                                record = json.loads(buffer.getvalue())
                                yield record
                                buffer = StringIO()
                            except json.JSONDecodeError:
                                pass
            elif file_type == 'csv':
                reader = csv.reader(file)
                header = next(reader)
                yield header

                for row in reader:
                    bytes_processed += len(','.join(row).encode('utf-8')) + len(row)  # Approximate
                    if progress_callback:
                        progress_callback(bytes_processed)
                    yield row

# Example usage
if __name__ == "__main__":
    def progress_callback(bytes_processed):
        print(f"Processed {bytes_processed / (1024 * 1024):.2f} MB", end='\r')

    parser = StreamingDataParser(chunk_size=1024 * 1024)  # 1MB chunks

    # Process a large JSON file
    for record in parser.parse_with_progress('large_file.json.gz', progress_callback=progress_callback):
        # Process each record here
        pass

    # Process a large CSV file
    for row in parser.parse('large_file.csv.bz2'):
        # Process each row here
        pass
