# High-Performance System Resource Monitor Daemon

Below is an initial implementation of a system daemon for monitoring and managing operating system resources. This implementation uses Python with a focus on performance and efficiency.

```python
#!/usr/bin/env python3
import os
import sys
import time
import psutil
import logging
import signal
import argparse
from threading import Thread, Event
from queue import Queue
from collections import defaultdict
import json
import socket
import struct
import fcntl

class ResourceMonitorDaemon:
    def __init__(self, config_file=None):
        self.running = Event()
        self.config = self._load_config(config_file)
        self.metrics_queue = Queue()
        self.alert_queue = Queue()
        self.threads = []
        self.setup_logging()

        # Initialize monitoring intervals
        self.monitor_intervals = {
            'cpu': self.config.get('monitor_intervals', {}).get('cpu', 1),
            'memory': self.config.get('monitor_intervals', {}).get('memory', 2),
            'disk': self.config.get('monitor_intervals', {}).get('disk', 5),
            'network': self.config.get('monitor_intervals', {}).get('network', 3),
            'process': self.config.get('monitor_intervals', {}).get('process', 10)
        }

        # Initialize thresholds
        self.thresholds = self.config.get('thresholds', {
            'cpu': 90,
            'memory': 85,
            'disk': 90,
            'network': 1000  # MB/s
        })

        # Initialize alert channels
        self.alert_channels = self.config.get('alert_channels', {
            'log': True,
            'syslog': False,
            'email': False,
            'sms': False
        })

        # Initialize control socket
        self.control_socket_path = self.config.get('control_socket', '/var/run/resmon.sock')
        self.control_socket = None

    def _load_config(self, config_file):
        """Load configuration from file or use defaults"""
        default_config = {
            'monitor_intervals': {
                'cpu': 1,
                'memory': 2,
                'disk': 5,
                'network': 3,
                'process': 10
            },
            'thresholds': {
                'cpu': 90,
                'memory': 85,
                'disk': 90,
                'network': 1000  # MB/s
            },
            'alert_channels': {
                'log': True,
                'syslog': False,
                'email': False,
                'sms': False
            },
            'control_socket': '/var/run/resmon.sock',
            'log_file': '/var/log/resmon.log',
            'pid_file': '/var/run/resmon.pid'
        }

        if config_file and os.path.exists(config_file):
            try:
                with open(config_file, 'r') as f:
                    config = json.load(f)
                # Merge with defaults
                for key in default_config:
                    if key not in config:
                        config[key] = default_config[key]
                return config
            except Exception as e:
                logging.error(f"Failed to load config file: {e}")
                return default_config
        return default_config

    def setup_logging(self):
        """Configure logging"""
        log_file = self.config.get('log_file', '/var/log/resmon.log')
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(log_file),
                logging.StreamHandler()
            ]
        )
        self.logger = logging.getLogger('ResourceMonitor')

    def write_pid_file(self):
        """Write PID file"""
        pid_file = self.config.get('pid_file', '/var/run/resmon.pid')
        try:
            with open(pid_file, 'w') as f:
                f.write(str(os.getpid()))
        except Exception as e:
            self.logger.error(f"Failed to write PID file: {e}")

    def remove_pid_file(self):
        """Remove PID file"""
        pid_file = self.config.get('pid_file', '/var/run/resmon.pid')
        try:
            if os.path.exists(pid_file):
                os.remove(pid_file)
        except Exception as e:
            self.logger.error(f"Failed to remove PID file: {e}")

    def setup_control_socket(self):
        """Set up Unix domain socket for control"""
        try:
            if os.path.exists(self.control_socket_path):
                os.remove(self.control_socket_path)

            self.control_socket = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
            self.control_socket.bind(self.control_socket_path)
            os.chmod(self.control_socket_path, 0o666)
            self.control_socket.listen(5)

            self.logger.info(f"Control socket created at {self.control_socket_path}")
        except Exception as e:
            self.logger.error(f"Failed to create control socket: {e}")
            self.control_socket = None

    def handle_control_commands(self):
        """Handle incoming control commands"""
        while self.running.is_set():
            try:
                if not self.control_socket:
                    time.sleep(1)
                    continue

                conn, addr = self.control_socket.accept()
                try:
                    data = conn.recv(1024).decode('utf-8').strip()
                    if not data:
                        continue

                    self.logger.info(f"Received control command: {data}")
                    response = self.process_control_command(data)
                    conn.sendall(response.encode('utf-8'))
                except Exception as e:
                    self.logger.error(f"Error handling control command: {e}")
                finally:
                    conn.close()
            except Exception as e:
                if self.running.is_set():
                    self.logger.error(f"Error in control socket: {e}")
                time.sleep(1)

    def process_control_command(self, command):
        """Process control commands"""
        parts = command.split()
        cmd = parts[0].lower()

        if cmd == 'status':
            return "Daemon is running"
        elif cmd == 'stop':
            self.running.clear()
            return "Stopping daemon..."
        elif cmd == 'reload':
            self.config = self._load_config(self.config.get('config_file'))
            return "Configuration reloaded"
        elif cmd == 'metrics':
            if not self.metrics_queue.empty():
                metrics = []
                while not self.metrics_queue.empty():
                    metrics.append(self.metrics_queue.get())
                return json.dumps(metrics)
            return "No metrics available"
        elif cmd == 'thresholds':
            if len(parts) > 1:
                try:
                    new_thresholds = json.loads(' '.join(parts[1:]))
                    self.thresholds.update(new_thresholds)
                    return "Thresholds updated"
                except Exception as e:
                    return f"Error updating thresholds: {e}"
            return json.dumps(self.thresholds)
        else:
            return f"Unknown command: {cmd}"

    def monitor_cpu(self):
        """Monitor CPU usage"""
        while self.running.is_set():
            try:
                cpu_percent = psutil.cpu_percent(interval=self.monitor_intervals['cpu'])
                cpu_times = psutil.cpu_times_percent()

                metrics = {
                    'timestamp': time.time(),
                    'type': 'cpu',
                    'usage': cpu_percent,
                    'times': {
                        'user': cpu_times.user,
                        'system': cpu_times.system,
                        'idle': cpu_times.idle,
                        'iowait': cpu_times.iowait
                    }
                }

                self.metrics_queue.put(metrics)

                # Check thresholds
                if cpu_percent > self.thresholds['cpu']:
                    alert = {
                        'type': 'cpu',
                        'level': 'warning',
                        'value': cpu_percent,
                        'threshold': self.thresholds['cpu'],
                        'message': f"CPU usage {cpu_percent}% exceeds threshold {self.thresholds['cpu']}%"
                    }
                    self.alert_queue.put(alert)

            except Exception as e:
                self.logger.error(f"Error monitoring CPU: {e}")
            time.sleep(self.monitor_intervals['cpu'])

    def monitor_memory(self):
        """Monitor memory usage"""
        while self.running.is_set():
            try:
                mem = psutil.virtual_memory()
                swap = psutil.swap_memory()

                metrics = {
                    'timestamp': time.time(),
                    'type': 'memory',
                    'total': mem.total,
                    'available': mem.available,
                    'used': mem.used,
                    'percent': mem.percent,
                    'swap_total': swap.total,
                    'swap_used': swap.used,
                    'swap_percent': swap.percent
                }

                self.metrics_queue.put(metrics)

                # Check thresholds
                if mem.percent > self.thresholds['memory']:
                    alert = {
                        'type': 'memory',
                        'level': 'warning',
                        'value': mem.percent,
                        'threshold': self.thresholds['memory'],
                        'message': f"Memory usage {mem.percent}% exceeds threshold {self.thresholds['memory']}%"
                    }
                    self.alert_queue.put(alert)

            except Exception as e:
                self.logger.error(f"Error monitoring memory: {e}")
            time.sleep(self.monitor_intervals['memory'])

    def monitor_disk(self):
        """Monitor disk usage"""
        while self.running.is_set():
            try:
                partitions = psutil.disk_partitions()
                disk_metrics = []

                for partition in partitions:
                    try:
                        usage = psutil.disk_usage(partition.mountpoint)
                        io_counters = psutil.disk_io_counters(perdisk=True).get(partition.device.split('/')[-1], None)

                        metrics = {
                            'timestamp': time.time(),
                            'type': 'disk',
                            'device': partition.device,
                            'mountpoint': partition.mountpoint,
                            'fstype': partition.fstype,
                            'total': usage.total,
                            'used': usage.used,
                            'free': usage.free,
                            'percent': usage.percent
                        }

                        if io_counters:
                            metrics.update({
                                'read_count': io_counters.read_count,
                                'write_count': io_counters.write_count,
                                'read_bytes': io_counters.read_bytes,
                                'write_bytes': io_counters.write_bytes,
                                'read_time': io_counters.read_time,
                                'write_time': io_counters.write_time
                            })

                        disk_metrics.append(metrics)

                        # Check thresholds
                        if usage.percent > self.thresholds['disk']:
                            alert = {
                                'type': 'disk',
                                'level': 'warning',
                                'device': partition.device,
                                'value': usage.percent,
                                'threshold': self.thresholds['disk'],
                                'message': f"Disk {partition.device} usage {usage.percent}% exceeds threshold {self.thresholds['disk']}%"
                            }
                            self.alert_queue.put(alert)

                    except Exception as e:
                        self.logger.error(f"Error monitoring disk {partition.device}: {e}")

                if disk_metrics:
                    self.metrics_queue.put(disk_metrics)

            except Exception as e:
                self.logger.error(f"Error monitoring disks: {e}")
            time.sleep(self.monitor_intervals['disk'])

    def monitor_network(self):
        """Monitor network usage"""
        last_io = None

        while self.running.is_set():
            try:
                current_io = psutil.net_io_counters(pernic=True)
                metrics = []

                if last_io is not None:
                    for nic, stats in current_io.items():
                        last_stats = last_io.get(nic, None)
                        if last_stats is None:
                            continue

                        bytes_sent = stats.bytes_sent - last_stats.bytes_sent
                        bytes_recv = stats.bytes_recv - last_stats.bytes_recv
                        packets_sent = stats.packets_sent - last_stats.packets_sent
                        packets_recv = stats.packets_recv - last_stats.packets_recv

                        metrics.append({
                            'timestamp': time.time(),
                            'type': 'network',
                            'interface': nic,
                            'bytes_sent': bytes_sent,
                            'bytes_recv': bytes_recv,
                            'packets_sent': packets_sent,
                            'packets_recv': packets_recv,
                            'errin': stats.errin,
                            'errout': stats.errout,
                            'dropin': stats.dropin,
                            'dropout': stats.dropout
                        })

                        # Check thresholds (convert to MB/s)
                        sent_mb = bytes_sent / (1024 * 1024)
                        recv_mb = bytes_recv / (1024 * 1024)

                        if sent_mb > self.thresholds['network'] or recv_mb > self.thresholds['network']:
                            alert = {
                                'type': 'network',
                                'level': 'warning',
                                'interface': nic,
                                'sent': sent_mb,
                                'received': recv_mb,
                                'threshold': self.thresholds['network'],
                                'message': f"Network {nic} usage exceeds threshold {self.thresholds['network']} MB/s"
                            }
                            self.alert_queue.put(alert)

                last_io = current_io

                if metrics:
                    self.metrics_queue.put(metrics)

            except Exception as e:
                self.logger.error(f"Error monitoring network: {e}")
            time.sleep(self.monitor_intervals['network'])

    def monitor_processes(self):
        """Monitor process information"""
        while self.running.is_set():
            try:
                processes = []
                for proc in psutil.process_iter(['pid', 'name', 'username', 'cpu_percent', 'memory_percent']):
                    try:
                        processes.append({
                            'pid': proc.info['pid'],
                            'name': proc.info['name'],
                            'user': proc.info['username'],
                            'cpu': proc.info['cpu_percent'],
                            'memory': proc.info['memory_percent']
                        })
                    except (psutil.NoSuchProcess, psutil.AccessDenied):
                        continue

                if processes:
                    self.metrics_queue.put({
                        'timestamp': time.time(),
                        'type': 'processes',
                        'processes': processes
                    })

            except Exception as e:
                self.logger.error(f"Error monitoring processes: {e}")
            time.sleep(self.monitor_intervals['process'])

    def alert_handler(self):
        """Handle alerts from the alert queue"""
        while self.running.is_set():
            try:
                alert = self.alert_queue.get(timeout=1)
                self.process_alert(alert)
            except Exception as e:
                if self.running.is_set():
                    self.logger.error(f"Error in alert handler: {e}")

    def process_alert(self, alert):
        """Process an alert based on configured channels"""
        alert_message = f"ALERT: {alert['message']}"

        if self.alert_channels.get('log', False):
            self.logger.warning(alert_message)

        if self.alert_channels.get('syslog', False):
            try:
                import syslog
                syslog.syslog(syslog.LOG_WARNING, alert_message)
            except Exception as e:
                self.logger.error(f"Error sending alert to syslog: {e}")

        if self.alert_channels.get('email', False):
            # Implement email sending logic here
            pass

        if self.alert_channels.get('sms', False):
            # Implement SMS sending logic here
            pass

    def signal_handler(self, signum, frame):
        """Handle termination signals"""
        self.logger.info(f"Received signal {signum}, shutting down...")
        self.running.clear()

    def start(self):
        """Start the daemon"""
        self.running.set()

        # Write PID file
        self.write_pid_file()

        # Set up signal handlers
        signal.signal(signal.SIGTERM, self.signal_handler)
        signal.signal(signal.SIGINT, self.signal_handler)

        # Set up control socket
        self.setup_control_socket()

        # Start monitoring threads
        self.threads = [
            Thread(target=self.monitor_cpu),
            Thread(target=self.monitor_memory),
            Thread(target=self.monitor_disk),
            Thread(target=self.monitor_network),
            Thread(target=self.monitor_processes),
            Thread(target=self.alert_handler),
            Thread(target=self.handle_control_commands)
        ]

        for thread in self.threads:
            thread.daemon = True
            thread.start()

        self.logger.info("Resource Monitor Daemon started")

        # Main loop
        while self.running.is_set():
            time.sleep(1)

        # Cleanup
        self.cleanup()

    def cleanup(self):
        """Clean up resources"""
        self.logger.info("Cleaning up resources...")

        # Stop all threads
        for thread in self.threads:
            if thread.is_alive():
                thread.join(timeout=2)

        # Close control socket
        if self.control_socket:
            try:
                self.control_socket.close()
                if os.path.exists(self.control_socket_path):
                    os.remove(self.control_socket_path)
            except Exception as e:
                self.logger.error(f"Error closing control socket: {e}")

        # Remove PID file
        self.remove_pid_file()

        self.logger.info("Resource Monitor Daemon stopped")

def main():
    parser = argparse.ArgumentParser(description='System Resource Monitor Daemon')
