import os
import sys
import time
import psutil
import logging
import signal
import argparse
from threading import Thread, Event
from queue import Queue
from collections import defaultdict
import json
import socket
import struct
import fcntl

class ResourceMonitorDaemon:
    def __init__(self, config_file=None, log_file=None):
        self.running = Event()
        self.shutdown_flag = Event()
        self.config = self._load_config(config_file)
        self.setup_logging(log_file)
        self.metrics_queue = Queue(maxsize=1000)
        self.threads = []
        self.metric_collectors = []
        self.metric_processors = []
        self.metric_exporters = []

        # Initialize system information
        self.system_info = {
            'hostname': socket.gethostname(),
            'boot_time': psutil.boot_time(),
            'cpu_count': psutil.cpu_count(),
            'total_memory': psutil.virtual_memory().total
        }

        # Initialize performance counters
        self.perf_counters = defaultdict(int)

    def _load_config(self, config_file):
        """Load configuration from file or use defaults"""
        default_config = {
            'interval': 1,  # seconds between metric collections
            'history_size': 300,  # number of samples to keep in memory
            'log_level': 'INFO',
            'metrics': {
                'cpu': True,
                'memory': True,
                'disk': True,
                'network': True,
                'processes': True
            },
            'exporters': {
                'console': True,
                'file': False,
                'network': False
            },
            'thresholds': {
                'cpu': 90,  # percentage
                'memory': 90,  # percentage
                'disk': 90,  # percentage
                'process_count': 1000
            }
        }

        if config_file and os.path.exists(config_file):
            try:
                with open(config_file, 'r') as f:
                    config = json.load(f)
                # Merge with defaults
                for key in default_config:
                    if key not in config:
                        config[key] = default_config[key]
                return config
            except Exception as e:
                self.logger.error(f"Failed to load config file: {e}")
                return default_config
        return default_config

    def setup_logging(self, log_file=None):
        """Configure logging"""
        self.logger = logging.getLogger('ResourceMonitor')
        self.logger.setLevel(getattr(logging, self.config['log_level'].upper(), logging.INFO))

        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')

        # Console handler
        ch = logging.StreamHandler()
        ch.setFormatter(formatter)
        self.logger.addHandler(ch)

        # File handler if specified
        if log_file:
            try:
                fh = logging.FileHandler(log_file)
                fh.setFormatter(formatter)
                self.logger.addHandler(fh)
            except Exception as e:
                self.logger.error(f"Failed to set up file logging: {e}")

    def _get_network_interfaces(self):
        """Get list of network interfaces"""
        interfaces = []
        for interface in psutil.net_if_stats():
            if interface != 'lo':
                interfaces.append(interface)
        return interfaces

    def _get_disk_partitions(self):
        """Get list of disk partitions"""
        partitions = []
        for partition in psutil.disk_partitions():
            if partition.fstype:
                partitions.append(partition.mountpoint)
        return partitions

    def collect_cpu_metrics(self):
        """Collect CPU metrics"""
        while not self.shutdown_flag.is_set():
            try:
                cpu_percent = psutil.cpu_percent(interval=None)
                cpu_times = psutil.cpu_times_percent(interval=None)

                metrics = {
                    'timestamp': time.time(),
                    'cpu_percent': cpu_percent,
                    'cpu_times': {
                        'user': cpu_times.user,
                        'system': cpu_times.system,
                        'idle': cpu_times.idle,
                        'iowait': getattr(cpu_times, 'iowait', 0)
                    }
                }

                self.metrics_queue.put(('cpu', metrics))
                self.perf_counters['cpu_collections'] += 1

                # Check threshold
                if cpu_percent > self.config['thresholds']['cpu']:
                    self.logger.warning(f"High CPU usage detected: {cpu_percent}%")

            except Exception as e:
                self.logger.error(f"Error collecting CPU metrics: {e}")

            time.sleep(self.config['interval'])

    def collect_memory_metrics(self):
        """Collect memory metrics"""
        while not self.shutdown_flag.is_set():
            try:
                mem = psutil.virtual_memory()
                swap = psutil.swap_memory()

                metrics = {
                    'timestamp': time.time(),
                    'total': mem.total,
                    'available': mem.available,
                    'used': mem.used,
                    'percent': mem.percent,
                    'swap_total': swap.total,
                    'swap_used': swap.used,
                    'swap_percent': swap.percent
                }

                self.metrics_queue.put(('memory', metrics))
                self.perf_counters['memory_collections'] += 1

                # Check threshold
                if mem.percent > self.config['thresholds']['memory']:
                    self.logger.warning(f"High memory usage detected: {mem.percent}%")

            except Exception as e:
                self.logger.error(f"Error collecting memory metrics: {e}")

            time.sleep(self.config['interval'])

    def collect_disk_metrics(self):
        """Collect disk metrics"""
        partitions = self._get_disk_partitions()

        while not self.shutdown_flag.is_set():
            try:
                metrics = {
                    'timestamp': time.time(),
                    'partitions': {}
                }

                for partition in partitions:
                    try:
                        usage = psutil.disk_usage(partition)
                        metrics['partitions'][partition] = {
                            'total': usage.total,
                            'used': usage.used,
                            'free': usage.free,
                            'percent': usage.percent
                        }

                        # Check threshold
                        if usage.percent > self.config['thresholds']['disk']:
                            self.logger.warning(f"High disk usage on {partition}: {usage.percent}%")

                    except Exception as e:
                        self.logger.error(f"Error collecting disk metrics for {partition}: {e}")

                self.metrics_queue.put(('disk', metrics))
                self.perf_counters['disk_collections'] += 1

            except Exception as e:
                self.logger.error(f"Error collecting disk metrics: {e}")

            time.sleep(self.config['interval'])

    def collect_network_metrics(self):
        """Collect network metrics"""
        interfaces = self._get_network_interfaces()
        prev_stats = {}

        while not self.shutdown_flag.is_set():
            try:
                metrics = {
                    'timestamp': time.time(),
                    'interfaces': {}
                }

                for interface in interfaces:
                    try:
                        stats = psutil.net_io_counters(pernic=True).get(interface, None)
                        if stats:
                            if interface in prev_stats:
                                # Calculate rates
                                bytes_sent = stats.bytes_sent - prev_stats[interface]['bytes_sent']
                                bytes_recv = stats.bytes_recv - prev_stats[interface]['bytes_recv']
                                packets_sent = stats.packets_sent - prev_stats[interface]['packets_sent']
                                packets_recv = stats.packets_recv - prev_stats[interface]['packets_recv']
                                errin = stats.errin - prev_stats[interface]['errin']
                                errout = stats.errout - prev_stats[interface]['errout']
                                dropin = stats.dropin - prev_stats[interface]['dropin']
                                dropout = stats.dropout - prev_stats[interface]['dropout']

                                metrics['interfaces'][interface] = {
                                    'bytes_sent': bytes_sent,
                                    'bytes_recv': bytes_recv,
                                    'packets_sent': packets_sent,
                                    'packets_recv': packets_recv,
                                    'errin': errin,
                                    'errout': errout,
                                    'dropin': dropin,
                                    'dropout': dropout
                                }
                            else:
                                # Store initial values
                                metrics['interfaces'][interface] = {
                                    'bytes_sent': 0,
                                    'bytes_recv': 0,
                                    'packets_sent': 0,
                                    'packets_recv': 0,
                                    'errin': 0,
                                    'errout': 0,
                                    'dropin': 0,
                                    'dropout': 0
                                }

                            prev_stats[interface] = {
                                'bytes_sent': stats.bytes_sent,
                                'bytes_recv': stats.bytes_recv,
                                'packets_sent': stats.packets_sent,
                                'packets_recv': stats.packets_recv,
                                'errin': stats.errin,
                                'errout': stats.errout,
                                'dropin': stats.dropin,
                                'dropout': stats.dropout
                            }

                    except Exception as e:
                        self.logger.error(f"Error collecting network metrics for {interface}: {e}")

                self.metrics_queue.put(('network', metrics))
                self.perf_counters['network_collections'] += 1

            except Exception as e:
                self.logger.error(f"Error collecting network metrics: {e}")

            time.sleep(self.config['interval'])

    def collect_process_metrics(self):
        """Collect process metrics"""
        while not self.shutdown_flag.is_set():
            try:
                processes = []
                for proc in psutil.process_iter(['pid', 'name', 'username', 'cpu_percent', 'memory_percent']):
                    try:
                        processes.append({
                            'pid': proc.info['pid'],
                            'name': proc.info['name'],
                            'username': proc.info['username'],
                            'cpu_percent': proc.info['cpu_percent'],
                            'memory_percent': proc.info['memory_percent']
                        })
                    except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                        continue

                metrics = {
                    'timestamp': time.time(),
                    'process_count': len(processes),
                    'top_processes': sorted(processes, key=lambda x: x['cpu_percent'], reverse=True)[:10]
                }

                self.metrics_queue.put(('process', metrics))
                self.perf_counters['process_collections'] += 1

                # Check threshold
                if len(processes) > self.config['thresholds']['process_count']:
                    self.logger.warning(f"High process count detected: {len(processes)}")

            except Exception as e:
                self.logger.error(f"Error collecting process metrics: {e}")

            time.sleep(self.config['interval'])

    def process_metrics(self):
        """Process metrics from the queue"""
        history = defaultdict(list)

        while not self.shutdown_flag.is_set():
            try:
                metric_type, metric_data = self.metrics_queue.get(timeout=1)

                # Add to history
                history[metric_type].append(metric_data)
                if len(history[metric_type]) > self.config['history_size']:
                    history[metric_type].pop(0)

                # Export metrics
                if self.config['exporters']['console']:
                    self.export_to_console(metric_type, metric_data)

                if self.config['exporters']['file']:
                    self.export_to_file(metric_type, metric_data)

                if self.config['exporters']['network']:
                    self.export_to_network(metric_type, metric_data)

                self.metrics_queue.task_done()

            except Exception as e:
