            elif metric_type == 'disk':
                for partition, usage in metric_data['partitions'].items():
                    self.logger.info(f"Disk {partition}: {usage['percent']:.1f}%")
            elif metric_type == 'network':
                for interface, stats in metric_data['interfaces'].items():
                    self.logger.info(f"Network {interface}: {stats['bytes_sent']} sent, {stats['bytes_recv']} recv")
            elif metric_type == 'process':
                self.logger.info(f"Processes: {metric_data['process_count']}")
        except Exception as e:
