    def start(self):
        """Start the daemon"""
        self.logger.info("Starting Resource Monitor Daemon")

        # Start metric collection threads
        if self.config['metrics']['cpu']:
            cpu_thread = Thread(target=self.collect_cpu_metrics, daemon=True)
            cpu_thread.start()
            self.metric_collectors.append(cpu_thread)

        if self.config['metrics']['memory']:
            memory_thread = Thread(target=self.collect_memory_metrics, daemon=True)
            memory_thread.start()
            self.metric_collectors.append(memory_thread)

        if self.config['metrics']['disk']:
            disk_thread = Thread(target=self.collect_disk_metrics, daemon=True)
            disk_thread.start()
            self.metric_collectors.append(disk_thread)

        if self.config['metrics']['network']:
            network_thread = Thread(target=self.collect_network_metrics, daemon=True)
            network_thread.start()
            self.metric_collectors.append(network_thread)

        if self.config['metrics']['processes']:
            process_thread = Thread(target=self.collect_process_metrics, daemon=True)
            process_thread.start()
            self.metric_collectors.append(process_thread)

        # Start metric processing thread
        process_thread = Thread(target=self.process_metrics, daemon=True)
        process_thread.start()
        self.metric_processors.append(process_thread)

        self.running.set()
        self.logger.info("Resource Monitor Daemon started successfully")

    def stop(self):
        """Stop the daemon"""
        self.logger.info("Stopping Resource Monitor Daemon")
        self.shutdown_flag.set()

        # Wait for threads to finish
        for thread in self.metric_collectors + self.metric_processors:
            thread.join(timeout=5)

        self.running.clear()
        self.logger.info("Resource Monitor Daemon stopped")

    def signal_handler(self, signum, frame):
        """Handle termination signals"""
        self.logger.info(f"Received signal {signum}, shutting down...")
        self.stop()
        sys.exit(0)

def daemonize():
    """Daemonize the process"""
    try:
        pid = os.fork()
        if pid > 0:
            # Exit first parent
            sys.exit(0)
    except OSError as e:
        sys.stderr.write(f"Fork #1 failed: {e}\n")
        sys.exit(1)

    # Decouple from parent environment
    os.chdir("/")
    os.setsid()
    os.umask(0)

    # Second fork
    try:
        pid = os.fork()
        if pid > 0:
            # Exit from second parent
            sys.exit(0)
    except OSError as e:
        sys.stderr.write(f"Fork #2 failed: {e}\n")
        sys.exit(1)

    # Redirect standard file descriptors
    sys.stdout.flush()
    sys.stderr.flush()
    si = open(os.devnull, 'r')
    so = open(os.devnull, 'a+')
    se = open(os.devnull, 'a+')

    os.dup2(si.fileno(), sys.stdin.fileno())
    os.dup2(so.fileno(), sys.stdout.fileno())
    os.dup2(se.fileno(), sys.stderr.fileno())

def main():
    parser = argparse.ArgumentParser(description='System Resource Monitor Daemon')
    parser.add_argument('--config', help='Path to configuration file')
    parser.add_argument('--log', help='Path to log file')
    parser.add_argument('--daemon', action='store_true', help='Run as daemon')
    parser.add_argument('--foreground', action='store_true', help='Run in foreground (default)')
    args = parser.parse_args()

    if args.daemon and not args.foreground:
        daemonize()

    monitor = ResourceMonitorDaemon(config_file=args.config, log_file=args.log)

    # Set up signal handlers
    signal.signal(signal.SIGTERM, monitor.signal_handler)
    signal.signal(signal.SIGINT, monitor.signal_handler)

    monitor.start()

    # Keep main thread alive
    while monitor.running.is_set():
        time.sleep(1)

if __name__ == '__main__':
