#define SENSOR_MAX_VOLTAGE 3.3f    // Maximum voltage from sensor
#define SENSOR_MIN_VALUE 0.0f      // Minimum value in sensor units
#define SENSOR_MAX_VALUE 100.0f     // Maximum value in sensor units

// Data processing variables
