    Serial.println(" ms");
    Serial.println();
}

void loop() {
    unsigned long currentTime = millis();

    // Check if it's time to take a new sample
    if (currentTime - lastSampleTime >= SAMPLE_INTERVAL) {
        lastSampleTime = currentTime;

        // Read and process sensor data
        float rawValue = readSensor();
        float processedValue = processData(rawValue);

        // Display the processed data
        displayData(processedValue);
    }

    // Other non-blocking tasks can go here
}

void setupSensor() {
    // Configure sensor pin
    pinMode(SENSOR_PIN, INPUT);

    // Initialize moving average array
    for (int i = 0; i < MOVING_AVG_WINDOW; i++) {
        sensorValues[i] = 0;
    }
}

float readSensor() {
    // Read raw analog value (0-1023 for 10-bit ADC)
    int rawADC = analogRead(SENSOR_PIN);

    // Convert to voltage (assuming 3.3V reference)
    float voltage = (rawADC / 1023.0) * SENSOR_MAX_VOLTAGE;

    // Convert to sensor units (linear mapping)
    float sensorValue = mapFloat(voltage, SENSOR_MIN_VOLTAGE, SENSOR_MAX_VOLTAGE,
                               SENSOR_MIN_VALUE, SENSOR_MAX_VALUE);

    return sensorValue;
}

// Helper function for floating-point mapping
float mapFloat(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

float processData(float rawValue) {
    // Apply moving average filter
    movingAverage -= sensorValues[currentIndex];  // Subtract the oldest value
    sensorValues[currentIndex] = rawValue;        // Add the new value
    movingAverage += rawValue;                    // Add to the sum

    currentIndex = (currentIndex + 1) % MOVING_AVG_WINDOW;  // Update index

    // Calculate the average
    float average = movingAverage / MOVING_AVG_WINDOW;

    // Additional processing can be added here (calibration, filtering, etc.)

    return average;
}

void displayData(float processedValue) {
    Serial.print("Raw Value: ");
    Serial.print(sensorValues[currentIndex], 2);
    Serial.print(" | Processed Value: ");
    Serial.print(processedValue, 2);
    Serial.print(" ");
    Serial.println(SENSOR_TYPE);

