#define SAMPLE_COUNT 10      // Number of samples to average
#define MIN_VALID_VALUE 10   // Minimum valid sensor reading
#define MAX_VALID_VALUE 1014 // Maximum valid sensor reading

// Global variables
int sensorValue = 0;
float processedValue = 0.0;

void setup() {
  // Initialize serial communication
  Serial.begin(9600);

  // Configure sensor pin
  pinMode(SENSOR_PIN, INPUT);

  // Initial message
  Serial.println("Sensor Data Processing Firmware v1.0");
  Serial.println("----------------------------------");
}

