  sensorValue = readSensor();
  processedValue = processData(sensorValue);

  // Output results
  Serial.print("Raw: ");
  Serial.print(sensorValue);
  Serial.print(" | Processed: ");
  Serial.println(processedValue);

  // Delay between readings
  delay(500);
}

