## Implementation (C++ for Arduino-like environment)

```cpp
#include <Arduino.h>
#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_ADXL345_U.h>

// Configuration
#define SAMPLE_WINDOW 100  // Number of samples for analysis
#define ANOMALY_THRESHOLD 2.5f  // Z-score threshold for anomaly detection
#define CALIBRATION_SAMPLES 1000  // Samples for initial calibration

// Sensor setup
Adafruit_ADXL345_Unified accel = Adafruit_ADXL345_Unified(12345);

// Data structures
struct AccelData {
    float x, y, z;
    float magnitude;
};

struct Stats {
    float mean;
    float stddev;
};

// Global variables
AccelData samples[SAMPLE_WINDOW];
Stats normalStats[3];  // For x, y, z axes
int sampleCount = 0;
bool calibrated = false;

void setup() {
    Serial.begin(115200);

    // Initialize accelerometer
    if (!accel.begin()) {
        Serial.println("No ADXL345 detected!");
        while (1);
    }

    // Set range to ±16g (can be adjusted based on expected motion)
    accel.setRange(ADXL345_RANGE_16_G);

    Serial.println("Initializing anomaly detection system...");
    calibrateSystem();
}

void loop() {
    // Read accelerometer data
    sensors_event_t event;
    accel.getEvent(&event);

    // Store current sample
    AccelData current;
    current.x = event.acceleration.x;
    current.y = event.acceleration.y;
    current.z = event.acceleration.z;
    current.magnitude = sqrt(current.x*current.x + current.y*current.y + current.z*current.z);

    // Add to sliding window
    samples[sampleCount % SAMPLE_WINDOW] = current;
    sampleCount++;

    // Process data when we have enough samples
    if (sampleCount >= SAMPLE_WINDOW) {
        processData();
    }

    delay(10);  // Adjust based on sensor sampling rate
}

void calibrateSystem() {
    Serial.println("Calibrating system - please keep device stationary...");

    float sumX = 0, sumY = 0, sumZ = 0;
    float sumSqX = 0, sumSqY = 0, sumSqZ = 0;

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        sensors_event_t event;
        accel.getEvent(&event);

        sumX += event.acceleration.x;
        sumY += event.acceleration.y;
        sumZ += event.acceleration.z;

        sumSqX += event.acceleration.x * event.acceleration.x;
        sumSqY += event.acceleration.y * event.acceleration.y;
        sumSqZ += event.acceleration.z * event.acceleration.z;

        delay(10);
    }

    // Calculate mean and standard deviation
    normalStats[0].mean = sumX / CALIBRATION_SAMPLES;
    normalStats[1].mean = sumY / CALIBRATION_SAMPLES;
    normalStats[2].mean = sumZ / CALIBRATION_SAMPLES;

    normalStats[0].stddev = sqrt((sumSqX / CALIBRATION_SAMPLES) - (normalStats[0].mean * normalStats[0].mean));
    normalStats[1].stddev = sqrt((sumSqY / CALIBRATION_SAMPLES) - (normalStats[1].mean * normalStats[1].mean));
    normalStats[2].stddev = sqrt((sumSqZ / CALIBRATION_SAMPLES) - (normalStats[2].mean * normalStats[2].mean));

    calibrated = true;
    Serial.println("Calibration complete!");
    Serial.print("X mean: "); Serial.print(normalStats[0].mean); Serial.print(", stddev: "); Serial.println(normalStats[0].stddev);
    Serial.print("Y mean: "); Serial.print(normalStats[1].mean); Serial.print(", stddev: "); Serial.println(normalStats[1].stddev);
    Serial.print("Z mean: "); Serial.print(normalStats[2].mean); Serial.print(", stddev: "); Serial.println(normalStats[2].stddev);
}

void processData() {
    // Calculate current statistics for the window
    float sumX = 0, sumY = 0, sumZ = 0;
    float sumSqX = 0, sumSqY = 0, sumSqZ = 0;

    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        sumX += samples[i].x;
        sumY += samples[i].y;
        sumZ += samples[i].z;

        sumSqX += samples[i].x * samples[i].x;
        sumSqY += samples[i].y * samples[i].y;
        sumSqZ += samples[i].z * samples[i].z;
    }

    float meanX = sumX / SAMPLE_WINDOW;
    float meanY = sumY / SAMPLE_WINDOW;
    float meanZ = sumZ / SAMPLE_WINDOW;

    float stddevX = sqrt((sumSqX / SAMPLE_WINDOW) - (meanX * meanX));
    float stddevY = sqrt((sumSqY / SAMPLE_WINDOW) - (meanY * meanY));
    float stddevZ = sqrt((sumSqZ / SAMPLE_WINDOW) - (meanZ * meanZ));

    // Calculate Z-scores for each axis
    float zScoreX = (meanX - normalStats[0].mean) / normalStats[0].stddev;
    float zScoreY = (meanY - normalStats[1].mean) / normalStats[1].stddev;
    float zScoreZ = (meanZ - normalStats[2].mean) / normalStats[2].stddev;

    // Check for anomalies
    bool anomalyDetected = false;
    if (abs(zScoreX) > ANOMALY_THRESHOLD ||
        abs(zScoreY) > ANOMALY_THRESHOLD ||
        abs(zScoreZ) > ANOMALY_THRESHOLD) {
        anomalyDetected = true;
    }

    // For magnitude-based anomaly detection
    float sumMag = 0, sumSqMag = 0;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        sumMag += samples[i].magnitude;
        sumSqMag += samples[i].magnitude * samples[i].magnitude;
    }

    float meanMag = sumMag / SAMPLE_WINDOW;
    float stddevMag = sqrt((sumSqMag / SAMPLE_WINDOW) - (meanMag * meanMag));

    // Output results
    Serial.print("X: "); Serial.print(meanX); Serial.print(" (Z: "); Serial.print(zScoreX); Serial.print(")");
    Serial.print(" Y: "); Serial.print(meanY); Serial.print(" (Z: "); Serial.print(zScoreY); Serial.print(")");
    Serial.print(" Z: "); Serial.print(meanZ); Serial.print(" (Z: "); Serial.print(zScoreZ); Serial.print(")");
    Serial.print(" Mag: "); Serial.print(meanMag); Serial.print(" (stddev: "); Serial.print(stddevMag); Serial.print(")");

    if (anomalyDetected) {
        Serial.println(" *** ANOMALY DETECTED ***");
        // Trigger appropriate action (buzzer, LED, etc.)
        triggerAlert();
    } else {
        Serial.println();
    }
}

void triggerAlert() {
    // Implement your alert mechanism here
    // Example: Flash LED or sound buzzer
    digitalWrite(LED_BUILTIN, HIGH);
    delay(100);
    digitalWrite(LED_BUILTIN, LOW);
}
