    buffer->head = 0;
    buffer->count = 0;
}

// Add a new sample to the buffer
void add_sample(AccelBuffer *buffer, AccelData sample) {
    buffer->data[buffer->head] = sample;
    buffer->head = (buffer->head + 1) % WINDOW_SIZE;

    if (buffer->count < WINDOW_SIZE) {
        buffer->count++;
    }
}

// Compute statistical features from the buffer
void compute_features(AccelBuffer *buffer, Features *features) {
    float sum_x = 0, sum_y = 0, sum_z = 0;
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    float sum_cross_xy = 0, sum_cross_xz = 0, sum_cross_yz = 0;

    for (int i = 0; i < buffer->count; i++) {
        AccelData sample = buffer->data[i];

        sum_x += sample.x;
        sum_y += sample.y;
        sum_z += sample.z;

        sum_sq_x += sample.x * sample.x;
        sum_sq_y += sample.y * sample.y;
        sum_sq_z += sample.z * sample.z;

        sum_cross_xy += sample.x * sample.y;
        sum_cross_xz += sample.x * sample.z;
        sum_cross_yz += sample.y * sample.z;
    }

    float n = (float)buffer->count;

    // Compute means
    float mean_x = sum_x / n;
    float mean_y = sum_y / n;
    float mean_z = sum_z / n;

    // Compute variances
    float var_x = (sum_sq_x / n) - (mean_x * mean_x);
    float var_y = (sum_sq_y / n) - (mean_y * mean_y);
    float var_z = (sum_sq_z / n) - (mean_z * mean_z);

    // Compute energy (sum of squares)
    float energy = sum_sq_x + sum_sq_y + sum_sq_z;

    // Compute correlation (simplified)
    float correlation = (sum_cross_xy + sum_cross_xz + sum_cross_yz) / (3 * n);

    // Store features
    features->mean = (mean_x + mean_y + mean_z) / 3.0f;
    features->variance = (var_x + var_y + var_z) / 3.0f;
    features->energy = energy;
    features->correlation = correlation;
}

