#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint8_t WINDOW_SIZE = 32;  // Samples per window
constexpr float THRESHOLD = 2.5f;    // Anomaly detection threshold
constexpr float ALPHA = 0.2f;        // Smoothing factor for moving average

// Data structure for accelerometer readings
struct AccelData {
    float x;
    float y;
    float z;
    uint32_t timestamp;
};

// Circular buffer for storing recent samples
class AccelBuffer {
private:
    std::vector<AccelData> buffer;
    size_t head = 0;
    size_t count = 0;

public:
    AccelBuffer(size_t size) : buffer(size) {}

    void addSample(const AccelData& sample) {
        buffer[head] = sample;
        head = (head + 1) % buffer.size();
        if (count < buffer.size()) count++;
    }

    bool isFull() const { return count == buffer.size(); }
    size_t size() const { return count; }

    const AccelData& operator[](size_t index) const {
        return buffer[(head + index) % buffer.size()];
    }
};

// Feature extraction functions
float calculateMagnitude(const AccelData& data) {
    return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

float calculateMeanMagnitude(const AccelBuffer& buffer) {
    float sum = 0.0f;
    for (size_t i = 0; i < buffer.size(); ++i) {
        sum += calculateMagnitude(buffer[i]);
    }
    return sum / buffer.size();
}

float calculateStdDev(const AccelBuffer& buffer, float mean) {
    float sum = 0.0f;
    for (size_t i = 0; i < buffer.size(); ++i) {
        float mag = calculateMagnitude(buffer[i]);
        sum += (mag - mean) * (mag - mean);
    }
    return std::sqrt(sum / buffer.size());
}

// Anomaly detection class
class AnomalyDetector {
private:
    AccelBuffer buffer;
    float prevMean = 0.0f;
    float prevStdDev = 0.0f;

public:
    AnomalyDetector(size_t windowSize) : buffer(windowSize) {}

    bool processSample(const AccelData& sample) {
        buffer.addSample(sample);

        if (!buffer.isFull()) {
            return false; // Not enough data yet
        }

        // Calculate current statistics
        float currentMean = calculateMeanMagnitude(buffer);
        float currentStdDev = calculateStdDev(buffer, currentMean);

        // Apply exponential smoothing to statistics
        float smoothedMean = ALPHA * currentMean + (1 - ALPHA) * prevMean;
        float smoothedStdDev = ALPHA * currentStdDev + (1 - ALPHA) * prevStdDev;

        prevMean = smoothedMean;
        prevStdDev = smoothedStdDev;

        // Calculate Z-score for the latest sample
        float latestMag = calculateMagnitude(buffer[buffer.size() - 1]);
        float zScore = (latestMag - smoothedMean) / (smoothedStdDev + 1e-6f);

        // Check if Z-score exceeds threshold
        return std::abs(zScore) > THRESHOLD;
    }
};

