# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation uses a simple statistical approach for anomaly detection, which is suitable for resource-constrained embedded systems.

## System Overview

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate statistical features
4. **Anomaly Detection**: Compare features against learned thresholds
5. **Alerting**: Trigger actions when anomalies are detected

## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <cstdint>

// Configuration parameters
constexpr uint16_t WINDOW_SIZE = 50;  // Number of samples in sliding window
constexpr float ANOMALY_THRESHOLD = 2.5f;  // Z-score threshold for anomaly
constexpr float MOVING_AVG_ALPHA = 0.1f;  // Smoothing factor for moving average

// Structure to hold accelerometer data
struct AccelData {
    float x;
    float y;
    float z;
    uint32_t timestamp;
};

// Circular buffer for storing recent samples
class CircularBuffer {
private:
    std::vector<AccelData> buffer;
    size_t head = 0;
    size_t tail = 0;
    bool full = false;

public:
    CircularBuffer(size_t size) : buffer(size) {}

    void push(const AccelData& data) {
        buffer[head] = data;
        if (full) {
            tail = (tail + 1) % buffer.size();
        }
        head = (head + 1) % buffer.size();
        full = head == tail;
    }

    bool isFull() const { return full; }
    size_t size() const {
        if (full) return buffer.size();
        if (head >= tail) return head - tail;
        return buffer.size() + head - tail;
    }

    AccelData operator[](size_t index) const {
        return buffer[(tail + index) % buffer.size()];
    }
};

// Anomaly detection class
class AccelAnomalyDetector {
private:
    CircularBuffer dataBuffer;
    float movingAvg[3] = {0, 0, 0};  // For x, y, z axes
    float movingVar[3] = {0, 0, 0};  // For x, y, z axes
    bool initialized = false;

public:
    AccelAnomalyDetector() : dataBuffer(WINDOW_SIZE) {}

    void processSample(const AccelData& sample) {
        // Store the sample
        dataBuffer.push(sample);

        // Update moving averages and variances
        if (!initialized && dataBuffer.isFull()) {
            // Initialize with first window of data
            float sum[3] = {0, 0, 0};
            for (size_t i = 0; i < WINDOW_SIZE; i++) {
                sum[0] += dataBuffer[i].x;
                sum[1] += dataBuffer[i].y;
                sum[2] += dataBuffer[i].z;
            }

            for (int axis = 0; axis < 3; axis++) {
                movingAvg[axis] = sum[axis] / WINDOW_SIZE;

                // Calculate variance
                float variance = 0;
                for (size_t i = 0; i < WINDOW_SIZE; i++) {
                    float diff = (axis == 0) ? dataBuffer[i].x - movingAvg[axis] :
                                (axis == 1) ? dataBuffer[i].y - movingAvg[axis] :
                                              dataBuffer[i].z - movingAvg[axis];
                    variance += diff * diff;
                }
                movingVar[axis] = variance / WINDOW_SIZE;
            }

            initialized = true;
        } else if (initialized) {
            // Update moving average and variance incrementally
            for (int axis = 0; axis < 3; axis++) {
                float current = (axis == 0) ? sample.x :
                                (axis == 1) ? sample.y : sample.z;

                // Update moving average
                movingAvg[axis] += MOVING_AVG_ALPHA * (current - movingAvg[axis]);

                // Update moving variance (Welford's algorithm)
                float diff = current - movingAvg[axis];
                movingVar[axis] += MOVING_AVG_ALPHA * (diff * diff - movingVar[axis]);
            }
        }
    }

    bool detectAnomaly() {
        if (!initialized || !dataBuffer.isFull()) {
            return false;  // Not enough data
        }

        // Calculate Z-scores for each axis
        for (int axis = 0; axis < 3; axis++) {
            float current = (axis == 0) ? dataBuffer[WINDOW_SIZE-1].x :
                           (axis == 1) ? dataBuffer[WINDOW_SIZE-1].y :
                                         dataBuffer[WINDOW_SIZE-1].z;

            float stdDev = sqrt(movingVar[axis]);
            if (stdDev == 0) continue;  // Avoid division by zero

            float zScore = fabs(current - movingAvg[axis]) / stdDev;

            if (zScore > ANOMALY_THRESHOLD) {
                return true;  // Anomaly detected
            }
        }

        return false;
    }

    // Helper function to get current statistics
    void getStatistics(float stats[6]) {
        for (int axis = 0; axis < 3; axis++) {
            stats[axis*2] = movingAvg[axis];
            stats[axis*2+1] = sqrt(movingVar[axis]);
        }
    }
};

// Example usage
