```
[Accelerometer] → [Data Collection] → [Preprocessing] → [Feature Extraction] → [Anomaly Detection] → [Alert/Logging]
```

## Implementation (C/C++ for Embedded Systems)

```c
#include <stdint.h>
#include <math.h>
#include <string.h>

// Configuration parameters
#define WINDOW_SIZE 50          // Number of samples in sliding window
#define THRESHOLD_MULTIPLIER 3.0 // Standard deviation multiplier for anomaly threshold
#define SAMPLE_RATE_HZ 100      // Accelerometer sample rate

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    AccelSample samples[WINDOW_SIZE];
    uint8_t count;
    float mean;
    float std_dev;
    float threshold;
} AnomalyDetector;

// Function prototypes
void init_anomaly_detector(AnomalyDetector* detector);
void process_sample(AnomalyDetector* detector, const AccelSample* sample);
bool detect_anomaly(const AnomalyDetector* detector, const AccelSample* sample);
void update_statistics(AnomalyDetector* detector);

// Initialize the anomaly detector
void init_anomaly_detector(AnomalyDetector* detector) {
    memset(detector->samples, 0, sizeof(detector->samples));
    detector->count = 0;
    detector->mean = 0.0f;
    detector->std_dev = 0.0f;
    detector->threshold = 0.0f;
}

// Process a new accelerometer sample
void process_sample(AnomalyDetector* detector, const AccelSample* sample) {
    // Add new sample to the window
    if (detector->count < WINDOW_SIZE) {
        detector->samples[detector->count++] = *sample;
    } else {
        // Shift window and add new sample
        memmove(detector->samples, detector->samples + 1,
                (WINDOW_SIZE - 1) * sizeof(AccelSample));
        detector->samples[WINDOW_SIZE - 1] = *sample;
    }

    // Update statistics if we have enough samples
    if (detector->count >= WINDOW_SIZE) {
        update_statistics(detector);
    }
}

// Detect anomaly in a sample
bool detect_anomaly(const AnomalyDetector* detector, const AccelSample* sample) {
    if (detector->count < WINDOW_SIZE) {
        return false; // Not enough data yet
    }

    // Calculate magnitude of current sample
    float magnitude = sqrtf(sample->x * sample->x +
                           sample->y * sample->y +
                           sample->z * sample->z);

    // Check if magnitude exceeds threshold
    return fabsf(magnitude - detector->mean) > detector->threshold;
}

// Update mean and standard deviation of the window
void update_statistics(AnomalyDetector* detector) {
    float sum = 0.0f;
    float sum_sq = 0.0f;

    // Calculate sum of magnitudes and sum of squares
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        float mag = sqrtf(detector->samples[i].x * detector->samples[i].x +
                         detector->samples[i].y * detector->samples[i].y +
                         detector->samples[i].z * detector->samples[i].z);
        sum += mag;
        sum_sq += mag * mag;
    }

    // Calculate mean and standard deviation
    detector->mean = sum / WINDOW_SIZE;
    float variance = (sum_sq / WINDOW_SIZE) - (detector->mean * detector->mean);
    detector->std_dev = sqrtf(variance);

    // Set threshold (mean + multiplier * std_dev)
    detector->threshold = THRESHOLD_MULTIPLIER * detector->std_dev;
}

// Example usage
int main() {
    AnomalyDetector detector;
    init_anomaly_detector(&detector);

    // Simulate receiving accelerometer data
    AccelSample sample;
    for (int i = 0; i < 1000; i++) {
