# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation is designed for resource-constrained embedded systems but can be adapted for more powerful devices.

## System Architecture

1. **Data Acquisition**: Read accelerometer data (X, Y, Z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate relevant features
4. **Anomaly Detection**: Compare features against learned patterns
5. **Alerting**: Trigger actions when anomalies are detected

## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint16_t WINDOW_SIZE = 50;  // Number of samples in processing window
constexpr float ANOMALY_THRESHOLD = 3.0f;  // Standard deviations for anomaly detection
constexpr float MOVING_AVG_ALPHA = 0.1f;  // For exponential moving average

// Simple circular buffer for sensor data
template<typename T, size_t Size>
class CircularBuffer {
private:
    T buffer[Size];
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        buffer[head] = value;
        head = (head + 1) % Size;
        if (count < Size) count++;
    }

    T operator[](size_t index) const {
        return buffer[(head + Size - 1 - index) % Size];
    }

    size_t size() const { return count; }
    bool full() const { return count == Size; }
};

// Accelerometer data structure
struct AccelData {
    float x, y, z;
    uint32_t timestamp;
};

// Feature vector structure
struct FeatureVector {
    float mean_x, mean_y, mean_z;
    float std_x, std_y, std_z;
    float magnitude_mean;
    float magnitude_std;
    float energy;
};

// Anomaly detection class
class AnomalyDetector {
private:
    CircularBuffer<AccelData, WINDOW_SIZE> data_buffer;
    CircularBuffer<FeatureVector, WINDOW_SIZE> feature_buffer;
    FeatureVector baseline_features;
    bool baseline_established = false;

    // Calculate statistics for a window of data
    FeatureVector calculateFeatures(const std::vector<AccelData>& window) {
        FeatureVector features = {0};

        // Calculate means
        for (const auto& sample : window) {
            features.mean_x += sample.x;
            features.mean_y += sample.y;
            features.mean_z += sample.z;
        }
        features.mean_x /= window.size();
        features.mean_y /= window.size();
        features.mean_z /= window.size();

        // Calculate standard deviations and magnitude
        float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
        float sum_mag = 0, sum_mag_sq = 0;

        for (const auto& sample : window) {
            float dx = sample.x - features.mean_x;
            float dy = sample.y - features.mean_y;
            float dz = sample.z - features.mean_z;

            sum_sq_x += dx * dx;
            sum_sq_y += dy * dy;
            sum_sq_z += dz * dz;

            float mag = std::sqrt(sample.x*sample.x + sample.y*sample.y + sample.z*sample.z);
            sum_mag += mag;
            sum_mag_sq += mag * mag;
        }

        features.std_x = std::sqrt(sum_sq_x / window.size());
        features.std_y = std::sqrt(sum_sq_y / window.size());
        features.std_z = std::sqrt(sum_sq_z / window.size());

        features.magnitude_mean = sum_mag / window.size();
        features.magnitude_std = std::sqrt((sum_mag_sq / window.size()) - (features.magnitude_mean * features.magnitude_mean));

        // Calculate energy (sum of squared magnitudes)
        features.energy = sum_mag_sq;

        return features;
    }

    // Compare current features against baseline
    float calculateAnomalyScore(const FeatureVector& current) {
        if (!baseline_established) return 0.0f;

        float score = 0.0f;

        // Compare each feature to baseline with standard deviation weighting
        score += std::abs(current.mean_x - baseline_features.mean_x) / baseline_features.std_x;
        score += std::abs(current.mean_y - baseline_features.mean_y) / baseline_features.std_y;
        score += std::abs(current.mean_z - baseline_features.mean_z) / baseline_features.std_z;

        score += std::abs(current.magnitude_mean - baseline_features.magnitude_mean) / baseline_features.magnitude_std;

        // Normalize by number of features
        return score / 5.0f;
    }

public:
    // Add new accelerometer reading
    void addSample(float x, float y, float z, uint32_t timestamp) {
        AccelData sample = {x, y, z, timestamp};
        data_buffer.push(sample);

        // Process when we have enough data
        if (data_buffer.full()) {
            // Extract current window
            std::vector<AccelData> window(WINDOW_SIZE);
            for (size_t i = 0; i < WINDOW_SIZE; i++) {
                window[i] = data_buffer[i];
            }

            // Calculate features
            FeatureVector features = calculateFeatures(window);
            feature_buffer.push(features);

            // Update baseline if we have enough data
            if (feature_buffer.full() && !baseline_established) {
                establishBaseline();
            }
        }
    }

    // Establish baseline features from initial data
    void establishBaseline() {
        if (!feature_buffer.full()) return;

        // Calculate mean of all features
        baseline_features = {0};

        for (size_t i = 0; i < feature_buffer.size(); i++) {
            baseline_features.mean_x += feature_buffer[i].mean_x;
            baseline_features.mean_y += feature_buffer[i].mean_y;
            baseline_features.mean_z += feature_buffer[i].mean_z;
            baseline_features.std_x += feature_buffer[i].std_x;
            baseline_features.std_y += feature_buffer[i].std_y;
            baseline_features.std_z += feature_buffer[i].std_z;
            baseline_features.magnitude_mean += feature_buffer[i].magnitude_mean;
            baseline_features.magnitude_std += feature_buffer[i].magnitude_std;
            baseline_features.energy += feature_buffer[i].energy;
        }

        baseline_features.mean_x /= feature_buffer.size();
        baseline_features.mean_y /= feature_buffer.size();
        baseline_features.mean_z /= feature_buffer.size();
        baseline_features.std_x /= feature_buffer.size();
        baseline_features.std_y /= feature_buffer.size();
        baseline_features.std_z /= feature_buffer.size();
        baseline_features.magnitude_mean /= feature_buffer.size();
        baseline_features.magnitude_std /= feature_buffer.size();
        baseline_features.energy /= feature_buffer.size();

        baseline_established = true;
    }

    // Check for anomalies in the most recent window
    bool checkForAnomaly() {
        if (!baseline_established || !feature_buffer.full()) {
            return false;
        }

        FeatureVector current_features = feature_buffer[0];
        float score = calculateAnomalyScore(current_features);

        return score > ANOMALY_THRESHOLD;
    }

    // Get current anomaly score (for debugging)
    float getAnomalyScore() {
        if (!baseline_established || !feature_buffer.full()) {
            return 0.0f;
        }

        return calculateAnomalyScore(feature_buffer[0]);
    }
};

// Example usage
int main() {
    AnomalyDetector detector;

    // Simulate some normal data
    for (int i = 0; i < 100; i++) {
        // Normal accelerometer readings (gravity + small noise)
        float x = 0.0f + (rand() % 100 - 50) / 1000.0f;  // ±0.05g
        float y = 0.0f + (rand() % 100 - 50) / 1000.0f;
        float z = 1.0f + (rand() % 100 - 50) / 1000.0f;  // 1g in z-axis
        detector.addSample(x, y, z, i);
    }

    // Check for anomalies (should be false for normal data)
    bool is_anomaly = detector.checkForAnomaly();
    float score = detector.getAnomalyScore();

    // Simulate an anomaly (sudden large acceleration)
    for (int i = 0; i < 10; i++) {
        detector.addSample(5.0f, 0.0f, 0.0f, 100 + i);  // 5g in x-axis
    }

    // Check again (should detect anomaly)
    is_anomaly = detector.checkForAnomaly();
    score = detector.getAnomalyScore();

    return 0;
}
```

