# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation is designed for resource-constrained embedded systems but can be adapted for more powerful platforms.

## System Overview

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate relevant features
4. **Anomaly Detection**: Compare features against learned normal behavior
5. **Alerting**: Trigger actions when anomalies are detected

## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint16_t WINDOW_SIZE = 50;  // Number of samples in analysis window
constexpr float THRESHOLD_MULTIPLIER = 3.0f;  // Anomaly threshold multiplier
constexpr float MOVING_AVG_ALPHA = 0.1f;  // Smoothing factor for moving average

// Simple circular buffer for storing sensor data
template<typename T, size_t N>
class CircularBuffer {
private:
    T buffer[N];
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        buffer[head] = value;
        head = (head + 1) % N;
        if (count < N) count++;
    }

    T operator[](size_t index) const {
        return buffer[(head + index) % N];
    }

    size_t size() const { return count; }
    bool full() const { return count == N; }
};

// Accelerometer data structure
struct AccelData {
    float x, y, z;
    float magnitude;
};

// Feature vector structure
struct FeatureVector {
    float mean_magnitude;
    float std_dev_magnitude;
    float max_magnitude;
    float min_magnitude;
    float energy;
};

// Anomaly detection pipeline
class AnomalyDetector {
private:
    CircularBuffer<AccelData, WINDOW_SIZE> data_buffer;
    CircularBuffer<FeatureVector, WINDOW_SIZE> feature_buffer;
    FeatureVector normal_profile;
    bool profile_learned = false;

    // Simple moving average filter
    float moving_avg = 0.0f;

    // Calculate magnitude of acceleration vector
    float calculateMagnitude(const AccelData& data) {
        return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    }

    // Calculate features from current window
    FeatureVector extractFeatures() {
        FeatureVector features;

        // Calculate mean magnitude
        float sum = 0.0f;
        for (size_t i = 0; i < data_buffer.size(); i++) {
            sum += data_buffer[i].magnitude;
        }
        features.mean_magnitude = sum / data_buffer.size();

        // Calculate standard deviation
        float variance = 0.0f;
        for (size_t i = 0; i < data_buffer.size(); i++) {
            float diff = data_buffer[i].magnitude - features.mean_magnitude;
            variance += diff * diff;
        }
        features.std_dev_magnitude = sqrt(variance / data_buffer.size());

        // Find min and max
        features.max_magnitude = -INFINITY;
        features.min_magnitude = INFINITY;
        for (size_t i = 0; i < data_buffer.size(); i++) {
            float mag = data_buffer[i].magnitude;
            if (mag > features.max_magnitude) features.max_magnitude = mag;
            if (mag < features.min_magnitude) features.min_magnitude = mag;
        }

        // Calculate energy (sum of squares)
        features.energy = 0.0f;
        for (size_t i = 0; i < data_buffer.size(); i++) {
            features.energy += data_buffer[i].magnitude * data_buffer[i].magnitude;
        }

        return features;
    }

    // Learn normal behavior profile
    void learnProfile() {
        if (data_buffer.full()) {
            normal_profile = extractFeatures();
            profile_learned = true;
        }
    }

    // Compare current features against normal profile
    bool isAnomaly(const FeatureVector& current) {
        if (!profile_learned) return false;

        // Simple threshold-based anomaly detection
        float mean_diff = fabs(current.mean_magnitude - normal_profile.mean_magnitude);
        float std_diff = fabs(current.std_dev_magnitude - normal_profile.std_dev_magnitude);

        bool mean_anomaly = mean_diff > (THRESHOLD_MULTIPLIER * normal_profile.std_dev_magnitude);
        bool std_anomaly = std_diff > (THRESHOLD_MULTIPLIER * normal_profile.std_dev_magnitude);

        return mean_anomaly || std_anomaly;
    }

public:
    // Process new accelerometer data
    bool processData(float x, float y, float z) {
        // Create new data point
        AccelData new_data;
        new_data.x = x;
        new_data.y = y;
        new_data.z = z;
        new_data.magnitude = calculateMagnitude(new_data);

        // Apply simple moving average filter
        if (data_buffer.size() == 0) {
            moving_avg = new_data.magnitude;
        } else {
            moving_avg = MOVING_AVG_ALPHA * new_data.magnitude + (1 - MOVING_AVG_ALPHA) * moving_avg;
        }

        // Store the filtered data
        new_data.magnitude = moving_avg;
        data_buffer.push(new_data);

        // Learn profile if we have enough data
        if (!profile_learned) {
            learnProfile();
            return false;
        }

        // Extract features and detect anomalies
        FeatureVector current_features = extractFeatures();
        feature_buffer.push(current_features);

        return isAnomaly(current_features);
    }

    // Reset the detector (e.g., when device is recalibrated)
    void reset() {
        data_buffer = CircularBuffer<AccelData, WINDOW_SIZE>();
        feature_buffer = CircularBuffer<FeatureVector, WINDOW_SIZE>();
        profile_learned = false;
    }
};
