## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint32_t WINDOW_SIZE = 50;  // Number of samples in sliding window
constexpr float ANOMALY_THRESHOLD = 3.0f;  // Z-score threshold for anomaly detection
constexpr float MOVING_AVG_ALPHA = 0.1f;  // Smoothing factor for moving average

// Structure to hold accelerometer data
struct AccelerometerData {
    float x;
    float y;
    float z;
    uint32_t timestamp;
};

// Circular buffer for storing recent samples
class CircularBuffer {
private:
    std::vector<AccelerometerData> buffer;
    size_t head = 0;
    size_t tail = 0;
    bool full = false;

public:
    CircularBuffer(size_t size) : buffer(size) {}

    void push(const AccelerometerData& data) {
        buffer[head] = data;
        if (full) {
            tail = (tail + 1) % buffer.size();
        }
        head = (head + 1) % buffer.size();
        full = head == tail;
    }

    std::vector<AccelerometerData> getData() const {
        std::vector<AccelerometerData> result;
        if (full) {
            result.insert(result.end(), buffer.begin() + head, buffer.end());
            result.insert(result.end(), buffer.begin(), buffer.begin() + head);
        } else {
            result.insert(result.end(), buffer.begin(), buffer.begin() + head);
        }
        return result;
    }

    bool isFull() const { return full; }
};

// Feature extraction class
class FeatureExtractor {
private:
    float movingAvgX = 0.0f;
    float movingAvgY = 0.0f;
    float movingAvgZ = 0.0f;

public:
    void updateMovingAverages(const AccelerometerData& data) {
        movingAvgX = MOVING_AVG_ALPHA * data.x + (1 - MOVING_AVG_ALPHA) * movingAvgX;
        movingAvgY = MOVING_AVG_ALPHA * data.y + (1 - MOVING_AVG_ALPHA) * movingAvgY;
        movingAvgZ = MOVING_AVG_ALPHA * data.z + (1 - MOVING_AVG_ALPHA) * movingAvgZ;
    }

    float calculateMagnitude(const AccelerometerData& data) {
        return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    }

    float calculateVariance(const std::vector<AccelerometerData>& window) {
        if (window.empty()) return 0.0f;

        float sum = 0.0f;
        float mean = 0.0f;

        // Calculate mean magnitude
        for (const auto& data : window) {
            sum += calculateMagnitude(data);
        }
        mean = sum / window.size();

        // Calculate variance
        sum = 0.0f;
        for (const auto& data : window) {
            float diff = calculateMagnitude(data) - mean;
            sum += diff * diff;
        }

        return sum / window.size();
    }

    float calculateZScore(const std::vector<AccelerometerData>& window, float currentValue) {
        if (window.empty()) return 0.0f;

        float sum = 0.0f;
        float mean = 0.0f;
        float variance = 0.0f;

        // Calculate mean
        for (const auto& data : window) {
            sum += calculateMagnitude(data);
        }
        mean = sum / window.size();

        // Calculate variance
        sum = 0.0f;
        for (const auto& data : window) {
            float diff = calculateMagnitude(data) - mean;
            sum += diff * diff;
        }
        variance = sum / window.size();

        if (variance == 0.0f) return 0.0f;

        return (currentValue - mean) / std::sqrt(variance);
    }
};

// Anomaly detection class
