        }

        // Get current window of data
        auto window = buffer.getData();

        // Calculate current magnitude
        float currentMagnitude = featureExtractor.calculateMagnitude(data);

        // Calculate Z-score
        float zScore = featureExtractor.calculateZScore(window, currentMagnitude);

        // Check for anomaly
        return std::abs(zScore) > ANOMALY_THRESHOLD;
    }
};

