        buffer.addSample(sample);

        if (buffer.isFull()) {
            // Calculate current magnitude features
            auto samples = buffer.getSamples();
            float sum = 0.0f;
            float sumSq = 0.0f;

            for (const auto& s : samples) {
                float mag = std::sqrt(s.x*s.x + s.y*s.y + s.z*s.z);
                sum += mag;
                sumSq += mag * mag;
            }

            float mean = sum / WINDOW_SIZE;
            float variance = (sumSq / WINDOW_SIZE) - (mean * mean);

            // Update moving averages
            if (movingAvgMagnitude == 0.0f) {
                movingAvgMagnitude = mean;
                movingVarMagnitude = variance;
            } else {
                movingAvgMagnitude = MOVING_AVG_ALPHA * mean + (1 - MOVING_AVG_ALPHA) * movingAvgMagnitude;
                movingVarMagnitude = MOVING_AVG_ALPHA * variance + (1 - MOVING_AVG_ALPHA) * movingVarMagnitude;
            }
