        if (movingVarMagnitude == 0.0f) return false;  // Avoid division by zero

        float stdDev = std::sqrt(movingVarMagnitude);
        float zScore = (currentMag - movingAvgMagnitude) / stdDev;

        return std::abs(zScore) > ANOMALY_THRESHOLD;
    }

