    bool isAnomaly;
    float anomalyScore;
    float magnitude;
};

// Circular buffer for storing recent samples
class CircularBuffer {
private:
    std::vector<AccelerometerData> buffer;
    size_t head = 0;
    size_t tail = 0;
    bool full = false;

public:
    CircularBuffer(size_t size) : buffer(size) {}

    void push(const AccelerometerData& data) {
        buffer[head] = data;
        if (full) {
            tail = (tail + 1) % buffer.size();
        }
        head = (head + 1) % buffer.size();
        full = head == tail;
    }

    std::vector<AccelerometerData> getData() const {
        std::vector<AccelerometerData> result;
        if (full) {
            result.insert(result.end(), buffer.begin() + head, buffer.end());
            result.insert(result.end(), buffer.begin(), buffer.begin() + head);
        } else {
            result.insert(result.end(), buffer.begin(), buffer.begin() + head);
        }
        return result;
    }

    bool isFull() const { return full; }
};

// Anomaly detection class
class AccelerometerAnomalyDetector {
private:
    CircularBuffer dataBuffer;
    float runningMean = 0.0f;
    float runningVariance = 0.0f;
    uint32_t sampleCount = 0;

public:
    AccelerometerAnomalyDetector() : dataBuffer(WINDOW_SIZE) {}

    // Process new accelerometer data
    AnomalyResult processData(const AccelerometerData& newData) {
        // Add new data to buffer
        dataBuffer.push(newData);

        // Only process if we have enough data
        if (!dataBuffer.isFull()) {
            return {false, 0.0f, 0.0f};
        }

        // Get current window of data
        auto windowData = dataBuffer.getData();

        // Calculate magnitude for each sample
        std::vector<float> magnitudes;
        for (const auto& sample : windowData) {
            float mag = std::sqrt(sample.x*sample.x + sample.y*sample.y + sample.z*sample.z);
            magnitudes.push_back(mag);
        }

        // Calculate statistics
        float mean = std::accumulate(magnitudes.begin(), magnitudes.end(), 0.0f) / magnitudes.size();
        float variance = 0.0f;
        for (float mag : magnitudes) {
            variance += (mag - mean) * (mag - mean);
        }
        variance /= magnitudes.size();
        float stddev = std::sqrt(variance);

        // Update running statistics (for adaptive thresholding)
        if (sampleCount == 0) {
            runningMean = mean;
            runningVariance = variance;
        } else {
            runningMean = runningMean * (1 - MOVING_AVG_ALPHA) + mean * MOVING_AVG_ALPHA;
            runningVariance = runningVariance * (1 - MOVING_AVG_ALPHA) + variance * MOVING_AVG_ALPHA;
        }
        sampleCount++;

        // Calculate current magnitude
        float currentMag = std::sqrt(newData.x*newData.x + newData.y*newData.y + newData.z*newData.z);

        // Calculate anomaly score (z-score)
        float anomalyScore = (currentMag - runningMean) / (std::sqrt(runningVariance) + 1e-6f);

        // Determine if anomaly
        bool isAnomaly = std::abs(anomalyScore) > ANOMALY_THRESHOLD;

        return {isAnomaly, anomalyScore, currentMag};
    }
};

