    float calculateMagnitude(const AccelData& data) {
        return std::sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    }

    float calculateVariance(const std::vector<AccelData>& window) {
        if (window.empty()) return 0.0f;

        // Calculate mean magnitude
        float sum = 0.0f;
        for (const auto& data : window) {
            sum += calculateMagnitude(data);
        }
        float mean = sum / window.size();

        // Calculate variance
        float variance = 0.0f;
        for (const auto& data : window) {
            float diff = calculateMagnitude(data) - mean;
            variance += diff * diff;
        }

        return variance / window.size();
    }

    float calculateStdDev(const std::vector<AccelData>& window) {
        return std::sqrt(calculateVariance(window));
    }
};

// Anomaly detection class
class AnomalyDetector {
private:
    CircularBuffer buffer;
    FeatureExtractor featureExtractor;
    float baselineStdDev = 0.0f;
    bool baselineEstablished = false;

public:
    AnomalyDetector() : buffer(WINDOW_SIZE) {}

    void processSample(const AccelData& data) {
        // Update moving averages
        featureExtractor.updateMovingAverages(data);

        // Add to circular buffer
        buffer.add(data);

        // If buffer is full, establish baseline or detect anomalies
        if (buffer.isFull()) {
            auto window = buffer.getWindow();

            if (!baselineEstablished) {
                // Establish baseline standard deviation
                baselineStdDev = featureExtractor.calculateStdDev(window);
                baselineEstablished = true;
            } else {
                // Calculate current standard deviation
                float currentStdDev = featureExtractor.calculateStdDev(window);

                // Check for anomaly
                if (std::abs(currentStdDev - baselineStdDev) > ANOMALY_THRESHOLD * baselineStdDev) {
                    // Anomaly detected - trigger action
                    handleAnomaly(data);
                }
            }
        }
    }

    void handleAnomaly(const AccelData& data) {
        // In a real system, this would trigger alerts, logging, etc.
        // For this example, we'll just print a message
        printf("ANOMALY DETECTED at timestamp %u: (%.2f, %.2f, %.2f)\n",
               data.timestamp, data.x, data.y, data.z);
    }
};

// Example usage
int main() {
    AnomalyDetector detector;

    // Simulate accelerometer data (in a real system, this would come from hardware)
    for (uint32_t i = 0; i < 200; ++i) {
        AccelData data;

        // Normal data (1g in z-axis)
        if (i < 100) {
            data.x = 0.0f;
            data.y = 0.0f;
            data.z = 9.81f;
        }
        // Anomalous data (sudden movement)
        else {
            data.x = 5.0f * std::sin(i * 0.1f);
            data.y = 5.0f * std::cos(i * 0.1f);
            data.z = 9.81f + 2.0f * std::sin(i * 0.2f);
        }

        data.timestamp = i;
        detector.processSample(data);
    }

    return 0;
}
