## Implementation (C-like Pseudocode)

```c
#include <stdint.h>
#include <math.h>

// Configuration parameters
#define SAMPLE_RATE_HZ 100
#define WINDOW_SIZE 50  // 50 samples (0.5 seconds at 100Hz)
#define FEATURE_WINDOW 10  // Number of windows to consider for baseline
#define THRESHOLD_MULTIPLIER 3.0f  // 3 standard deviations for anomaly detection

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

typedef struct {
    float mean;
    float stddev;
    float max;
    float min;
} FeatureStats;

// Circular buffer for raw data
AccelData raw_buffer[WINDOW_SIZE];
uint8_t buffer_index = 0;

// Feature storage
FeatureStats feature_history[FEATURE_WINDOW];
uint8_t feature_index = 0;

// Current feature statistics
FeatureStats current_features;

// Anomaly detection thresholds
FeatureStats baseline_thresholds;

// Function prototypes
void init_pipeline();
void process_sample(AccelData sample);
void update_baseline();
int detect_anomaly();
void apply_low_pass_filter(AccelData* data);
void calculate_features();
void update_thresholds();

// Initialize the pipeline
void init_pipeline() {
    // Initialize buffers
    for (int i = 0; i < WINDOW_SIZE; i++) {
        raw_buffer[i].x = 0;
        raw_buffer[i].y = 0;
        raw_buffer[i].z = 0;
    }

    // Initialize feature history
    for (int i = 0; i < FEATURE_WINDOW; i++) {
        feature_history[i].mean = 0;
        feature_history[i].stddev = 0;
        feature_history[i].max = 0;
        feature_history[i].min = 0;
    }

    // Initialize thresholds (will be updated during calibration)
    baseline_thresholds.mean = 0;
    baseline_thresholds.stddev = 0;
    baseline_thresholds.max = 0;
    baseline_thresholds.min = 0;
}

// Process a new accelerometer sample
void process_sample(AccelData sample) {
    // Apply low-pass filter to reduce noise
    apply_low_pass_filter(&sample);

    // Store in circular buffer
    raw_buffer[buffer_index] = sample;
    buffer_index = (buffer_index + 1) % WINDOW_SIZE;

    // When buffer is full, calculate features
    if (buffer_index == 0) {
        calculate_features();

        // Update feature history
        feature_history[feature_index] = current_features;
        feature_index = (feature_index + 1) % FEATURE_WINDOW;

        // Update baseline thresholds periodically
        if (feature_index == 0) {
            update_baseline();
        }

        // Check for anomalies
        if (detect_anomaly()) {
            // Trigger alert (implementation specific)
            trigger_alert();
        }
    }
}

// Simple low-pass filter implementation
void apply_low_pass_filter(AccelData* data) {
    static AccelData prev_filtered = {0, 0, 0};
    const float alpha = 0.2f;  // Filter coefficient

    data->x = alpha * data->x + (1.0f - alpha) * prev_filtered.x;
    data->y = alpha * data->y + (1.0f - alpha) * prev_filtered.y;
    data->z = alpha * data->z + (1.0f - alpha) * prev_filtered.z;

    prev_filtered = *data;
}

// Calculate features from current window
void calculate_features() {
    float sum_x = 0, sum_y = 0, sum_z = 0;
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    float max_x = -INFINITY, max_y = -INFINITY, max_z = -INFINITY;
    float min_x = INFINITY, min_y = INFINITY, min_z = INFINITY;

    // Calculate sums and max/min for each axis
    for (int i = 0; i < WINDOW_SIZE; i++) {
        sum_x += raw_buffer[i].x;
        sum_y += raw_buffer[i].y;
        sum_z += raw_buffer[i].z;

        sum_sq_x += raw_buffer[i].x * raw_buffer[i].x;
        sum_sq_y += raw_buffer[i].y * raw_buffer[i].y;
        sum_sq_z += raw_buffer[i].z * raw_buffer[i].z;

        if (raw_buffer[i].x > max_x) max_x = raw_buffer[i].x;
        if (raw_buffer[i].y > max_y) max_y = raw_buffer[i].y;
        if (raw_buffer[i].z > max_z) max_z = raw_buffer[i].z;

        if (raw_buffer[i].x < min_x) min_x = raw_buffer[i].x;
        if (raw_buffer[i].y < min_y) min_y = raw_buffer[i].y;
        if (raw_buffer[i].z < min_z) min_z = raw_buffer[i].z;
    }

    // Calculate mean and standard deviation for each axis
    float mean_x = sum_x / WINDOW_SIZE;
    float mean_y = sum_y / WINDOW_SIZE;
    float mean_z = sum_z / WINDOW_SIZE;

    float var_x = (sum_sq_x / WINDOW_SIZE) - (mean_x * mean_x);
    float var_y = (sum_sq_y / WINDOW_SIZE) - (mean_y * mean_y);
    float var_z = (sum_sq_z / WINDOW_SIZE) - (mean_z * mean_z);

    // Store combined features (could be improved with more sophisticated features)
    current_features.mean = (mean_x + mean_y + mean_z) / 3.0f;
    current_features.stddev = sqrtf((var_x + var_y + var_z) / 3.0f);
    current_features.max = fmaxf(fmaxf(max_x, max_y), max_z);
    current_features.min = fminf(fminf(min_x, min_y), min_z);
}

// Update baseline thresholds from feature history
void update_baseline() {
    float sum_mean = 0, sum_stddev = 0, sum_max = 0, sum_min = 0;

    for (int i = 0; i < FEATURE_WINDOW; i++) {
        sum_mean += feature_history[i].mean;
        sum_stddev += feature_history[i].stddev;
        sum_max += feature_history[i].max;
        sum_min += feature_history[i].min;
    }

    baseline_thresholds.mean = sum_mean / FEATURE_WINDOW;
    baseline_thresholds.stddev = sum_stddev / FEATURE_WINDOW;
    baseline_thresholds.max = sum_max / FEATURE_WINDOW;
    baseline_thresholds.min = sum_min / FEATURE_WINDOW;
}

// Detect anomalies based on current features vs baseline
int detect_anomaly() {
    // Check if any feature is outside the threshold range
    if (fabs(current_features.mean - baseline_thresholds.mean) > THRESHOLD_MULTIPLIER * baseline_thresholds.stddev) {
        return 1;
    }

    if (current_features.max > baseline_thresholds.max + THRESHOLD_MULTIPLIER * baseline_thresholds.stddev) {
        return 1;
    }

    if (current_features.min < baseline_thresholds.min - THRESHOLD_MULTIPLIER * baseline_thresholds.stddev) {
        return 1;
    }

    return 0;
}

// Example alert function (implementation specific)
void trigger_alert() {
    // Could blink LED, send message, etc.
    // For embedded systems, this might set a flag or trigger an interrupt
    // printf("ANOMALY DETECTED!\n");
}
