// Configuration
const int SAMPLE_WINDOW = 100;  // Number of samples for analysis
const float ANOMALY_THRESHOLD = 2.5;  // Z-score threshold for anomaly detection
const int FILTER_WINDOW = 5;  // Moving average filter window

// Sensor setup
Adafruit_ADXL345_Unified accel = Adafruit_ADXL345_Unified(12345);

