bool pipelineInitialized = false;

// Statistics for anomaly detection
float meanMagnitude = 0;
float stdDevMagnitude = 0;

// Filter buffers
float xFilter[FILTER_WINDOW] = {0};
float yFilter[FILTER_WINDOW] = {0};
float zFilter[FILTER_WINDOW] = {0};
int filterIndex = 0;

void setup() {
    Serial.begin(115200);
    while (!Serial);

    // Initialize accelerometer
    if (!accel.begin()) {
        Serial.println("No ADXL345 detected!");
        while (1);
    }

    // Set range to ±16g (adjust based on your sensor)
    accel.setRange(ADXL345_RANGE_16_G);

    Serial.println("Accelerometer initialized. Starting pipeline...");
}

void loop() {
    // Read raw accelerometer data
    sensors_event_t event;
    accel.getEvent(&event);

    // Apply moving average filter
    xFilter[filterIndex] = event.acceleration.x;
    yFilter[filterIndex] = event.acceleration.y;
    zFilter[filterIndex] = event.acceleration.z;

    float filteredX = 0, filteredY = 0, filteredZ = 0;
    for (int i = 0; i < FILTER_WINDOW; i++) {
        filteredX += xFilter[i];
        filteredY += yFilter[i];
        filteredZ += zFilter[i];
    }
    filteredX /= FILTER_WINDOW;
    filteredY /= FILTER_WINDOW;
    filteredZ /= FILTER_WINDOW;

    filterIndex = (filterIndex + 1) % FILTER_WINDOW;

    // Calculate magnitude
    float magnitude = sqrt(filteredX*filteredX + filteredY*filteredY + filteredZ*filteredZ);

    // Store current sample
    samples[sampleIndex] = {filteredX, filteredY, filteredZ, magnitude};
    sampleIndex = (sampleIndex + 1) % SAMPLE_WINDOW;

    // Initialize pipeline after first window of samples
    if (!pipelineInitialized && sampleIndex == 0) {
        calculateStatistics();
        pipelineInitialized = true;
        Serial.println("Pipeline initialized with initial statistics");
    }

    // Process data if pipeline is initialized
    if (pipelineInitialized) {
        // Update statistics periodically
        if (sampleIndex % (SAMPLE_WINDOW/10) == 0) {
            calculateStatistics();
        }

        // Check for anomalies
        float zScore = (magnitude - meanMagnitude) / (stdDevMagnitude + 0.001); // Small offset to avoid division by zero
        if (abs(zScore) > ANOMALY_THRESHOLD) {
            triggerAnomalyAlert(magnitude, zScore);
        }
    }

    delay(10); // Adjust based on your sampling rate needs
}

void calculateStatistics() {
    // Calculate mean magnitude
    float sum = 0;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        sum += samples[i].magnitude;
    }
    meanMagnitude = sum / SAMPLE_WINDOW;

    // Calculate standard deviation
    float sumSq = 0;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        float diff = samples[i].magnitude - meanMagnitude;
        sumSq += diff * diff;
    }
    stdDevMagnitude = sqrt(sumSq / SAMPLE_WINDOW);

    // Print statistics for debugging
    Serial.print("Stats - Mean: ");
    Serial.print(meanMagnitude);
    Serial.print(", StdDev: ");
    Serial.println(stdDevMagnitude);
}

void triggerAnomalyAlert(float magnitude, float zScore) {
