```python
import numpy as np
import matplotlib.pyplot as plt

class AnomalyDetector:
    def __init__(self, window_size=20, threshold_multiplier=3.0):
        self.window_size = window_size
        self.threshold_multiplier = threshold_multiplier
        self.window = []
        self.mean = None
        self.stddev = None

    def update(self, data):
        """Update the detector with new data point"""
        self.window.append(data)

        if len(self.window) > self.window_size:
            self.window.pop(0)

        if len(self.window) == self.window_size:
            self._compute_statistics()

    def _compute_statistics(self):
        """Compute mean and standard deviation for the window"""
        window_array = np.array(self.window)
        self.mean = np.mean(window_array, axis=0)
        self.stddev = np.std(window_array, axis=0)

    def detect_anomaly(self, data):
        """Detect anomaly using z-score method"""
        if len(self.window) < self.window_size:
            return False

        # Skip if stddev is zero (no variation)
        if np.any(self.stddev == 0):
            return False

        z_scores = np.abs((data - self.mean) / self.stddev)
        return np.any(z_scores > self.threshold_multiplier)

    def process(self, data):
        """Process new data point and return anomaly status"""
        self.update(data)
        return self.detect_anomaly(data)

# Example usage
