# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation is designed for resource-constrained embedded systems but can be adapted for more powerful platforms.

## System Architecture

1. **Data Acquisition**: Read accelerometer data (x, y, z axes)
2. **Preprocessing**: Filter and normalize the data
3. **Feature Extraction**: Compute relevant features
4. **Anomaly Detection**: Compare features against learned thresholds
5. **Alerting**: Trigger actions when anomalies are detected

## Implementation (C++ for Embedded Systems)

```cpp
#include <cmath>
#include <vector>
#include <algorithm>
#include <numeric>
#include <cstdint>

// Configuration parameters
constexpr uint8_t WINDOW_SIZE = 32;  // Number of samples in sliding window
constexpr float ANOMALY_THRESHOLD = 2.5f;  // Z-score threshold for anomaly
constexpr float MOVING_AVG_ALPHA = 0.1f;  // For exponential moving average

// Simple circular buffer for sensor data
template<typename T, size_t N>
class CircularBuffer {
private:
    T data[N];
    size_t head = 0;
    size_t count = 0;

public:
    void push(T value) {
        data[head] = value;
        head = (head + 1) % N;
        if (count < N) count++;
    }

    T operator[](size_t index) const {
        return data[(head + index) % N];
    }

    size_t size() const { return count; }
    bool full() const { return count == N; }
};

// Accelerometer data structure
struct AccelData {
    float x, y, z;
    uint32_t timestamp;
};

// Anomaly detection pipeline
class AnomalyDetector {
private:
    CircularBuffer<AccelData, WINDOW_SIZE> buffer;
    float movingAvgMagnitude = 0;
    float movingStdDev = 0;

    // Simple low-pass filter
    AccelData filterData(const AccelData& raw) {
        static AccelData filtered = {0, 0, 0, 0};
        const float alpha = 0.2f;  // Filter coefficient

        filtered.x = alpha * raw.x + (1 - alpha) * filtered.x;
        filtered.y = alpha * raw.y + (1 - alpha) * filtered.y;
        filtered.z = alpha * raw.z + (1 - alpha) * filtered.z;
        filtered.timestamp = raw.timestamp;

        return filtered;
    }

    // Compute magnitude of acceleration vector
    float computeMagnitude(const AccelData& data) {
        return std::sqrt(data.x*data.x + data.y*data.y + data.z*data.z);
    }

    // Update moving statistics
    void updateStatistics(float magnitude) {
        // Update moving average
        movingAvgMagnitude = MOVING_AVG_ALPHA * magnitude +
                           (1 - MOVING_AVG_ALPHA) * movingAvgMagnitude;

        // Update moving standard deviation (simplified)
        float diff = magnitude - movingAvgMagnitude;
        movingStdDev = MOVING_AVG_ALPHA * std::abs(diff) +
                      (1 - MOVING_AVG_ALPHA) * movingStdDev;
    }

public:
    // Process new accelerometer reading
    bool processSample(const AccelData& rawData) {
        // Step 1: Filter the data
        AccelData filtered = filterData(rawData);

        // Step 2: Store in circular buffer
        buffer.push(filtered);

        // Only process if we have enough samples
        if (!buffer.full()) {
            return false;
        }

        // Step 3: Compute magnitude
        float magnitude = computeMagnitude(filtered);

        // Step 4: Update statistics
        updateStatistics(magnitude);

        // Step 5: Detect anomaly (simple z-score approach)
        if (movingStdDev > 0) {
            float zScore = (magnitude - movingAvgMagnitude) / movingStdDev;
            if (std::abs(zScore) > ANOMALY_THRESHOLD) {
                return true;  // Anomaly detected
            }
        }

        return false;
    }

    // Get current statistics (for debugging)
    void getStatistics(float& avg, float& stddev) const {
        avg = movingAvgMagnitude;
        stddev = movingStdDev;
    }
};

// Example usage
int main() {
    AnomalyDetector detector;

    // Simulate some accelerometer data
    const uint32_t numSamples = 1000;
    for (uint32_t i = 0; i < numSamples; i++) {
        // Create sample data (normal pattern with occasional anomaly)
        float x = 0.1f * std::sin(0.1f * i);
        float y = 0.1f * std::cos(0.1f * i);
        float z = 1.0f;  // Gravity

        // Occasionally add an anomaly
        if (i % 100 == 0) {
            x += 2.0f;  // Sudden spike
        }

        AccelData sample = {x, y, z, i};

        // Process the sample
        bool isAnomaly = detector.processSample(sample);

        if (isAnomaly) {
            // Handle anomaly (e.g., trigger alarm, log event)
            float avg, stddev;
            detector.getStatistics(avg, stddev);
            printf("Anomaly detected at sample %u! Avg: %.2f, StdDev: %.2f\n",
                   i, avg, stddev);
        }
    }

    return 0;
}
```

