```cpp
#include <Arduino.h>
#include <Wire.h>
#include <Adafruit_Sensor.h>
#include <Adafruit_ADXL345_U.h>

// Configuration
const int SAMPLE_WINDOW = 100;  // Number of samples for analysis
const float ANOMALY_THRESHOLD = 2.5;  // Standard deviations from mean
const int WINDOW_SIZE = 10;  // Moving average window size

// Sensor object
Adafruit_ADXL345_Unified accel = Adafruit_ADXL345_Unified(12345);

// Data structures
float xData[SAMPLE_WINDOW];
float yData[SAMPLE_WINDOW];
float zData[SAMPLE_WINDOW];
float xAvg[WINDOW_SIZE];
float yAvg[WINDOW_SIZE];
float zAvg[WINDOW_SIZE];
int currentIndex = 0;
int avgIndex = 0;

// Feature storage
float meanX, meanY, meanZ;
float stdDevX, stdDevY, stdDevZ;

// Function prototypes
void readAccelerometer();
void preprocessData();
void calculateFeatures();
bool detectAnomaly();
void updateMovingAverages();
void alertAnomaly();

void setup() {
  Serial.begin(115200);

  // Initialize accelerometer
  if (!accel.begin()) {
    Serial.println("No ADXL345 detected!");
    while (1);
  }

  // Set range to ±16g
  accel.setRange(ADXL345_RANGE_16_G);

  // Initialize data arrays
  memset(xData, 0, sizeof(xData));
  memset(yData, 0, sizeof(yData));
  memset(zData, 0, sizeof(zData));
  memset(xAvg, 0, sizeof(xAvg));
  memset(yAvg, 0, sizeof(yAvg));
  memset(zAvg, 0, sizeof(zAvg));
}

void loop() {
  // Read new accelerometer data
  readAccelerometer();

  // Preprocess the data
  preprocessData();

  // Calculate statistical features
  calculateFeatures();

  // Detect anomalies
  if (detectAnomaly()) {
    alertAnomaly();
  }

  // Update moving averages
  updateMovingAverages();

  // Small delay to control sample rate
  delay(10);
}

void readAccelerometer() {
  sensors_event_t event;
  accel.getEvent(&event);

  // Store raw data
  xData[currentIndex] = event.acceleration.x;
  yData[currentIndex] = event.acceleration.y;
  zData[currentIndex] = event.acceleration.z;

  // Update index (circular buffer)
  currentIndex = (currentIndex + 1) % SAMPLE_WINDOW;
}

void preprocessData() {
  // Simple moving average filter to reduce noise
  float sumX = 0, sumY = 0, sumZ = 0;
  for (int i = 0; i < SAMPLE_WINDOW; i++) {
    sumX += xData[i];
    sumY += yData[i];
    sumZ += zData[i];
  }

  // Store filtered values (could be used instead of raw data)
  // For this example, we'll use raw data for simplicity
}

void calculateFeatures() {
  // Calculate means
  meanX = 0; meanY = 0; meanZ = 0;
  for (int i = 0; i < SAMPLE_WINDOW; i++) {
    meanX += xData[i];
    meanY += yData[i];
    meanZ += zData[i];
  }
  meanX /= SAMPLE_WINDOW;
  meanY /= SAMPLE_WINDOW;
  meanZ /= SAMPLE_WINDOW;

  // Calculate standard deviations
  stdDevX = 0; stdDevY = 0; stdDevZ = 0;
  for (int i = 0; i < SAMPLE_WINDOW; i++) {
    stdDevX += sq(xData[i] - meanX);
    stdDevY += sq(yData[i] - meanY);
    stdDevZ += sq(zData[i] - meanZ);
  }
  stdDevX = sqrt(stdDevX / SAMPLE_WINDOW);
  stdDevY = sqrt(stdDevY / SAMPLE_WINDOW);
  stdDevZ = sqrt(stdDevZ / SAMPLE_WINDOW);
}

bool detectAnomaly() {
  // Check if any axis exceeds threshold standard deviations
  if (abs(xData[currentIndex] - meanX) > ANOMALY_THRESHOLD * stdDevX ||
      abs(yData[currentIndex] - meanY) > ANOMALY_THRESHOLD * stdDevY ||
      abs(zData[currentIndex] - meanZ) > ANOMALY_THRESHOLD * stdDevZ) {
    return true;
  }

  // Check for sudden changes (optional)
  if (currentIndex > 0) {
    float deltaX = abs(xData[currentIndex] - xData[currentIndex - 1]);
    float deltaY = abs(yData[currentIndex] - yData[currentIndex - 1]);
    float deltaZ = abs(zData[currentIndex] - zData[currentIndex - 1]);

    if (deltaX > 2.0 || deltaY > 2.0 || deltaZ > 2.0) {  // Threshold in g
      return true;
    }
  }

  return false;
}

void updateMovingAverages() {
  // Update moving averages for each axis
  xAvg[avgIndex] = meanX;
  yAvg[avgIndex] = meanY;
  zAvg[avgIndex] = meanZ;

  avgIndex = (avgIndex + 1) % WINDOW_SIZE;
}

void alertAnomaly() {
  Serial.println("ANOMALY DETECTED!");
  Serial.print("X: "); Serial.print(xData[currentIndex]);
  Serial.print(" Y: "); Serial.print(yData[currentIndex]);
  Serial.print(" Z: "); Serial.println(zData[currentIndex]);

  // In a real system, you might:
  // - Trigger an alarm
  // - Send data to a cloud service
  // - Log the event
  // - Take corrective action
}
