# Embedded Sensor-Processing Pipeline for Anomaly Detection

Below is an initial implementation of an embedded sensor-processing pipeline that detects anomalies from accelerometer data. This implementation is designed for resource-constrained embedded systems but can be adapted for more powerful platforms.

## System Architecture

1. **Data Acquisition**: Read accelerometer data (X, Y, Z axes)
2. **Preprocessing**: Filter noise and normalize data
3. **Feature Extraction**: Calculate relevant features
4. **Anomaly Detection**: Compare features against learned thresholds
5. **Alert System**: Trigger actions when anomalies are detected

## Implementation (C/C++ for Embedded Systems)

```c
#include <stdint.h>
#include <math.h>
#include <string.h>

// Configuration parameters
#define WINDOW_SIZE 20          // Number of samples in sliding window
#define FEATURE_DIM 4           // Number of features (magnitude, mean, variance, peak)
#define ANOMALY_THRESHOLD 2.5   // Z-score threshold for anomaly detection
#define LEARNING_PERIOD 1000    // Samples to learn normal behavior

// Data structures
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

typedef struct {
    float magnitude;
    float mean;
    float variance;
    float peak;
} Features;

// Circular buffer for sliding window
typedef struct {
    AccelData data[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} AccelBuffer;

// Running statistics for anomaly detection
typedef struct {
    float mean[FEATURE_DIM];
    float std_dev[FEATURE_DIM];
    uint32_t sample_count;
} RunningStats;

// Initialize the system
void init_pipeline(AccelBuffer* buffer, RunningStats* stats) {
    memset(buffer, 0, sizeof(AccelBuffer));
    memset(stats, 0, sizeof(RunningStats));
}

// Add new accelerometer reading to buffer
void add_sample(AccelBuffer* buffer, AccelData sample) {
    buffer->data[buffer->head] = sample;
    buffer->head = (buffer->head + 1) % WINDOW_SIZE;
    if (buffer->count < WINDOW_SIZE) {
        buffer->count++;
    }
}

// Calculate features from current window
void calculate_features(const AccelBuffer* buffer, Features* features) {
    float sum_x = 0, sum_y = 0, sum_z = 0;
    float sum_sq_x = 0, sum_sq_y = 0, sum_sq_z = 0;
    float max_mag = 0;

    for (uint16_t i = 0; i < buffer->count; i++) {
        const AccelData* sample = &buffer->data[i];
        float mag = sqrtf(sample->x * sample->x + sample->y * sample->y + sample->z * sample->z);

        sum_x += sample->x;
        sum_y += sample->y;
        sum_z += sample->z;
        sum_sq_x += sample->x * sample->x;
        sum_sq_y += sample->y * sample->y;
        sum_sq_z += sample->z * sample->z;

        if (mag > max_mag) {
            max_mag = mag;
        }
    }

    float count = (float)buffer->count;
    features->magnitude = sqrtf((sum_sq_x + sum_sq_y + sum_sq_z) / count);
    features->mean = (sum_x + sum_y + sum_z) / (3 * count);
    features->variance = (sum_sq_x + sum_sq_y + sum_sq_z) / count - features->mean * features->mean;
    features->peak = max_mag;
}

// Update running statistics for anomaly detection
void update_stats(RunningStats* stats, const Features* features) {
    if (stats->sample_count == 0) {
        // First sample - initialize means
        stats->mean[0] = features->magnitude;
        stats->mean[1] = features->mean;
        stats->mean[2] = features->variance;
        stats->mean[3] = features->peak;
    } else {
        // Online update of mean and variance
        float alpha = 1.0f / (stats->sample_count + 1);
        for (int i = 0; i < FEATURE_DIM; i++) {
            float feature_val;
            switch (i) {
                case 0: feature_val = features->magnitude; break;
                case 1: feature_val = features->mean; break;
                case 2: feature_val = features->variance; break;
                case 3: feature_val = features->peak; break;
            }

            float delta = feature_val - stats->mean[i];
            stats->mean[i] += alpha * delta;
            stats->std_dev[i] += alpha * (delta * (feature_val - stats->mean[i]) - stats->std_dev[i]);
        }
    }

    stats->sample_count++;
}

// Detect anomalies using Z-score
bool detect_anomaly(const RunningStats* stats, const Features* features) {
    if (stats->sample_count < LEARNING_PERIOD) {
        return false; // Not enough data to detect anomalies
    }

    float z_scores[FEATURE_DIM];
    z_scores[0] = fabsf(features->magnitude - stats->mean[0]) / (stats->std_dev[0] + 1e-6f);
    z_scores[1] = fabsf(features->mean - stats->mean[1]) / (stats->std_dev[1] + 1e-6f);
    z_scores[2] = fabsf(features->variance - stats->mean[2]) / (stats->std_dev[2] + 1e-6f);
    z_scores[3] = fabsf(features->peak - stats->mean[3]) / (stats->std_dev[3] + 1e-6f);

    for (int i = 0; i < FEATURE_DIM; i++) {
        if (z_scores[i] > ANOMALY_THRESHOLD) {
            return true;
        }
    }

    return false;
}

// Main processing function
bool process_accelerometer_data(AccelData sample, AccelBuffer* buffer, RunningStats* stats) {
    // Add new sample to buffer
    add_sample(buffer, sample);

    // Only process when we have a full window
    if (buffer->count < WINDOW_SIZE) {
        return false;
    }

    // Calculate features
    Features features;
    calculate_features(buffer, &features);

    // Update statistics
    update_stats(stats, &features);

    // Detect anomalies
    return detect_anomaly(stats, &features);
}
```

