```python
import numpy as np
from collections import deque

class AnomalyDetector:
    def __init__(self, window_size=20, learning_period=1000, threshold=2.5):
        self.window_size = window_size
        self.learning_period = learning_period
        self.threshold = threshold
        self.buffer = deque(maxlen=window_size)
        self.stats = {
            'mean': np.zeros(4),
            'std_dev': np.zeros(4),
            'sample_count': 0
        }

    def add_sample(self, x, y, z):
        self.buffer.append((x, y, z))

    def calculate_features(self):
        if len(self.buffer) < self.window_size:
            return None

        data = np.array(self.buffer)
        magnitudes = np.sqrt(np.sum(data**2, axis=1))
        means = np.mean(data, axis=0)
        variances = np.var(data, axis=0)
        peak = np.max(magnitudes)

        return {
            'magnitude': np.mean(magnitudes),
            'mean': np.mean(means),
            'variance': np.mean(variances),
            'peak': peak
        }

    def update_stats(self, features):
        if features is None:
            return

        features_vec = np.array([
            features['magnitude'],
            features['mean'],
            features['variance'],
            features['peak']
        ])

        if self.stats['sample_count'] == 0:
            self.stats['mean'] = features_vec
        else:
            alpha = 1.0 / (self.stats['sample_count'] + 1)
            delta = features_vec - self.stats['mean']
            self.stats['mean'] += alpha * delta
            self.stats['std_dev'] += alpha * (delta * (features_vec - self.stats['mean']) - self.stats['std_dev'])

        self.stats['sample_count'] += 1

    def detect_anomaly(self, features):
        if features is None or self.stats['sample_count'] < self.learning_period:
            return False

        features_vec = np.array([
            features['magnitude'],
            features['mean'],
            features['variance'],
            features['peak']
        ])

        z_scores = np.abs(features_vec - self.stats['mean']) / (self.stats['std_dev'] + 1e-6)
        return np.any(z_scores > self.threshold)

    def process(self, x, y, z):
        self.add_sample(x, y, z)
        features = self.calculate_features()
        self.update_stats(features)
        return self.detect_anomaly(features)
