                         a.acceleration.z * a.acceleration.z);

  // Update moving average
  accelSum -= accelBuffer[bufferIndex];
  accelBuffer[bufferIndex] = totalAccel;
  accelSum += totalAccel;
  bufferIndex = (bufferIndex + 1) % SAMPLE_WINDOW;

  float avgAccel = accelSum / SAMPLE_WINDOW;

