#include <stdint.h>
#include <math.h>

// Configuration
#define WINDOW_SIZE 10      // Number of samples for moving average
#define THRESHOLD_MULTIPLIER 3.0f  // Anomaly threshold (standard deviations)

// Sensor data structure
typedef struct {
    float x;
    float y;
    float z;
} AccelData;

// Circular buffer for moving average
AccelData accelBuffer[WINDOW_SIZE];
uint8_t bufferIndex = 0;
bool bufferFull = false;

// Statistics for anomaly detection
AccelData mean = {0, 0, 0};
AccelData variance = {0, 0, 0};

// Initialize the pipeline
void initAnomalyDetection() {
    // Initialize buffer
    for (int i = 0; i < WINDOW_SIZE; i++) {
        accelBuffer[i].x = 0;
        accelBuffer[i].y = 0;
        accelBuffer[i].z = 0;
    }
}

// Update statistics with new data
void updateStatistics(AccelData newData) {
    // Store new data in circular buffer
    accelBuffer[bufferIndex] = newData;
    bufferIndex = (bufferIndex + 1) % WINDOW_SIZE;
    if (bufferIndex == 0) bufferFull = true;

    // Calculate new mean
    AccelData newMean = {0, 0, 0};
    for (int i = 0; i < (bufferFull ? WINDOW_SIZE : bufferIndex); i++) {
        newMean.x += accelBuffer[i].x;
        newMean.y += accelBuffer[i].y;
        newMean.z += accelBuffer[i].z;
    }
    int count = bufferFull ? WINDOW_SIZE : bufferIndex;
    newMean.x /= count;
    newMean.y /= count;
    newMean.z /= count;

    // Calculate new variance
    AccelData newVariance = {0, 0, 0};
    for (int i = 0; i < (bufferFull ? WINDOW_SIZE : bufferIndex); i++) {
        float diffX = accelBuffer[i].x - newMean.x;
        float diffY = accelBuffer[i].y - newMean.y;
        float diffZ = accelBuffer[i].z - newMean.z;
        newVariance.x += diffX * diffX;
        newVariance.y += diffY * diffY;
        newVariance.z += diffZ * diffZ;
    }
    newVariance.x /= count;
    newVariance.y /= count;
    newVariance.z /= count;

    // Update global statistics
    mean = newMean;
    variance = newVariance;
}

// Detect anomalies
bool detectAnomaly(AccelData currentData) {
    if (!bufferFull) return false;  // Not enough data

    // Calculate standard deviation
    AccelData stdDev = {
        sqrtf(variance.x),
        sqrtf(variance.y),
        sqrtf(variance.z)
    };

    // Check if any axis exceeds threshold
    float thresholdX = THRESHOLD_MULTIPLIER * stdDev.x;
    float thresholdY = THRESHOLD_MULTIPLIER * stdDev.y;
    float thresholdZ = THRESHOLD_MULTIPLIER * stdDev.z;

    return (fabsf(currentData.x - mean.x) > thresholdX) ||
           (fabsf(currentData.y - mean.y) > thresholdY) ||
           (fabsf(currentData.z - mean.z) > thresholdZ);
}

