        AccelData currentData = readAccelerometer();

        // Update statistics
        updateStatistics(currentData);

        // Detect anomalies
        if (detectAnomaly(currentData)) {
            // Anomaly detected - take action
            triggerAlarm();
        }

        // Delay for next sample
        delay(100);  // 10Hz sampling rate
    }
