    actuator->last_activation_time = 0.0f;
    actuator->is_active = true;

    system->actuator_count++;
    return true;
}

// Simple moving average filter
void filter_sensor_data(Sensor *sensor) {
    if (sensor->sample_count < SAMPLE_WINDOW_SIZE) {
        // Not enough samples yet
        sensor->filtered_value = sensor->current_value;
        sensor->sample_window[sensor->sample_count] = sensor->current_value;
        sensor->sample_count++;
    } else {
        // Calculate moving average
        float sum = 0.0f;
        for (int i = 0; i < SAMPLE_WINDOW_SIZE; i++) {
            sum += sensor->sample_window[i];
        }
        sensor->filtered_value = sum / SAMPLE_WINDOW_SIZE;

        // Shift window and add new sample
        for (int i = 0; i < SAMPLE_WINDOW_SIZE - 1; i++) {
            sensor->sample_window[i] = sensor->sample_window[i + 1];
        }
        sensor->sample_window[SAMPLE_WINDOW_SIZE - 1] = sensor->current_value;
    }
}

