        filter_sensor_data(sensor);

        // Simple rule: if filtered value exceeds threshold, activate actuator
        if (fabs(sensor->filtered_value) > FILTER_THRESHOLD) {
            // Find the first available actuator
            for (int j = 0; j < system->actuator_count; j++) {
                Actuator *actuator = &system->actuators[j];
                if (actuator->is_active && !actuator->state) {
