    }

    // Check for actuators that should be deactivated
    for (int i = 0; i < system->actuator_count; i++) {
        Actuator *actuator = &system->actuators[i];
        if (actuator->is_active && actuator->state &&
            (system->current_time - actuator->last_activation_time) > 1.0f) {
            actuator->state = false;
            printf("Actuator %s deactivated at time %.1f\n",
                   actuator->id, system->current_time);
        }
    }
