    ActuatorType type;
    bool state;
    float setpoint;
    time_t last_change;
} Actuator;

// System state structure
typedef struct {
    SensorData sensors[MAX_SENSORS];
    Actuator actuators[MAX_ACTUATORS];
    float sensor_buffer[MAX_SENSORS][SAMPLE_BUFFER_SIZE];
    int buffer_index[MAX_SENSORS];
    bool initialized;
} EdgeSystem;

// Initialize the edge system
void init_edge_system(EdgeSystem *system) {
    memset(system, 0, sizeof(EdgeSystem));

    // Initialize sensors
    system->sensors[0].type = SENSOR_TEMPERATURE;
    system->sensors[1].type = SENSOR_HUMIDITY;
    system->sensors[2].type = SENSOR_PRESSURE;
    system->sensors[3].type = SENSOR_LIGHT;
    system->sensors[4].type = SENSOR_MOTION;

    // Initialize actuators
    system->actuators[0].type = ACTUATOR_FAN;
    system->actuators[1].type = ACTUATOR_LIGHT;
    system->actuators[2].type = ACTUATOR_VALVE;

    // Initialize buffer indices
    for (int i = 0; i < MAX_SENSORS; i++) {
        system->buffer_index[i] = 0;
    }

    system->initialized = true;
    printf("Edge system initialized\n");
}

// Simple moving average filter
float apply_filter(float *buffer, int buffer_size, float new_value) {
    float sum = 0.0f;

    // Add new value to buffer
    buffer[buffer_size % SAMPLE_BUFFER_SIZE] = new_value;

    // Calculate average of last FILTER_WINDOW values
    int start = (buffer_size >= FILTER_WINDOW) ? buffer_size - FILTER_WINDOW + 1 : 0;
    int count = (buffer_size < FILTER_WINDOW) ? buffer_size + 1 : FILTER_WINDOW;

    for (int i = start; i <= buffer_size; i++) {
        sum += buffer[i % SAMPLE_BUFFER_SIZE];
    }

    return sum / count;
}

// Process incoming sensor data
void process_sensor_data(EdgeSystem *system, SensorType type, float raw_value) {
    if (!system->initialized) return;

    // Find the sensor index
    int sensor_idx = -1;
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (system->sensors[i].type == type) {
            sensor_idx = i;
            break;
        }
    }

    if (sensor_idx == -1) return;

    // Apply filter
    float filtered_value = apply_filter(
        system->sensor_buffer[sensor_idx],
        system->buffer_index[sensor_idx],
        raw_value
    );

    // Update sensor data
    system->sensors[sensor_idx].value = filtered_value;
    system->sensors[sensor_idx].timestamp = time(NULL);
    system->buffer_index[sensor_idx]++;

    // Trigger control logic
    control_actuators(system);
}

