    if (!system->initialized) return;

    // Example control logic - adjust based on your requirements
    for (int i = 0; i < MAX_ACTUATORS; i++) {
        Actuator *actuator = &system->actuators[i];
        time_t now = time(NULL);

        switch (actuator->type) {
            case ACTUATOR_FAN:
                // Turn on fan if temperature > 28°C
                if (system->sensors[0].value > 28.0f && !actuator->state) {
                    actuator->state = true;
                    actuator->last_change = now;
                    printf("Fan turned ON\n");
                }
                // Turn off fan if temperature < 25°C
                else if (system->sensors[0].value < 25.0f && actuator->state) {
                    actuator->state = false;
                    actuator->last_change = now;
                    printf("Fan turned OFF\n");
                }
                break;

            case ACTUATOR_LIGHT:
                // Turn on light if it's dark (light < 100 lux) and no motion
                if (system->sensors[3].value < 100.0f &&
                    system->sensors[4].value == 0.0f &&
                    !actuator->state) {
                    actuator->state = true;
                    actuator->last_change = now;
                    printf("Light turned ON\n");
                }
                // Turn off light if it's bright or there's motion
                else if ((system->sensors[3].value >= 100.0f ||
                         system->sensors[4].value > 0.0f) &&
                         actuator->state) {
                    actuator->state = false;
                    actuator->last_change = now;
                    printf("Light turned OFF\n");
                }
                break;

            case ACTUATOR_VALVE:
                // Example: Control based on humidity
