    for (int i = 0; i < MAX_SENSORS; i++) {
        system->sensors[i].active = false;
        system->sensors[i].history_index = 0;
        memset(system->sensors[i].history, 0, sizeof(system->sensors[i].history));
    }

    for (int i = 0; i < MAX_ACTUATORS; i++) {
        system->actuators[i].active = false;
        system->actuators[i].state = false;
    }
}

// Add a sensor to the system
bool add_sensor(EdgeSystem *system, const char *id) {
    if (system == NULL || id == NULL || system->sensor_count >= MAX_SENSORS) {
        return false;
    }

    for (int i = 0; i < system->sensor_count; i++) {
        if (strcmp(system->sensors[i].id, id) == 0) {
            return false; // Sensor already exists
        }
    }

    strncpy(system->sensors[system->sensor_count].id, id, sizeof(system->sensors[system->sensor_count].id) - 1);
    system->sensors[system->sensor_count].active = true;
    system->sensor_count++;
    return true;
}

// Add an actuator to the system
bool add_actuator(EdgeSystem *system, const char *id) {
    if (system == NULL || id == NULL || system->actuator_count >= MAX_ACTUATORS) {
        return false;
    }

    for (int i = 0; i < system->actuator_count; i++) {
        if (strcmp(system->actuators[i].id, id) == 0) {
            return false; // Actuator already exists
        }
    }

    strncpy(system->actuators[system->actuator_count].id, id, sizeof(system->actuators[system->actuator_count].id) - 1);
    system->actuators[system->actuator_count].active = true;
    system->actuator_count++;
    return true;
}

// Simple moving average filter
float moving_average_filter(Sensor *sensor, float new_value) {
    if (sensor == NULL) return new_value;

    // Update history
    sensor->history[sensor->history_index] = new_value;
    sensor->history_index = (sensor->history_index + 1) % SAMPLE_WINDOW;

    // Calculate average
    float sum = 0.0f;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
        sum += sensor->history[i];
    }

    return sum / SAMPLE_WINDOW;
}

