    // Find the sensor
    Sensor *sensor = NULL;
    for (int i = 0; i < system->sensor_count; i++) {
        if (strcmp(system->sensors[i].id, sensor_id) == 0 && system->sensors[i].active) {
            sensor = &system->sensors[i];
            break;
