#include <stdbool.h>
#include <string.h>
#include <time.h>

// Define maximum limits for resource constraints
#define MAX_SENSORS 5
#define MAX_ACTUATORS 3
#define MAX_DATA_POINTS 100
#define FILTER_WINDOW_SIZE 5

// Sensor types
typedef enum {
    TEMPERATURE,
    HUMIDITY,
    PRESSURE,
    LIGHT,
    MOTION
} SensorType;

// Actuator types
typedef enum {
    LED,
    FAN,
    VALVE,
    MOTOR
} ActuatorType;

// Sensor data structure
typedef struct {
    SensorType type;
    float value;
    time_t timestamp;
} SensorData;

// Actuator control structure
typedef struct {
    ActuatorType type;
    bool state;
    float setpoint;
} Actuator;

// Edge system structure
typedef struct {
    SensorData sensors[MAX_SENSORS];
    Actuator actuators[MAX_ACTUATORS];
    float data_buffer[MAX_SENSORS][MAX_DATA_POINTS];
    int buffer_index[MAX_SENSORS];
    bool initialized;
} EdgeSystem;

// Initialize the edge system
void init_edge_system(EdgeSystem *system) {
    if (system == NULL) return;

    // Initialize sensors
    for (int i = 0; i < MAX_SENSORS; i++) {
        system->sensors[i].type = TEMPERATURE + i; // Assign different types
        system->sensors[i].value = 0.0f;
        system->sensors[i].timestamp = 0;

        // Initialize data buffer
        for (int j = 0; j < MAX_DATA_POINTS; j++) {
            system->data_buffer[i][j] = 0.0f;
        }
        system->buffer_index[i] = 0;
    }

    // Initialize actuators
    for (int i = 0; i < MAX_ACTUATORS; i++) {
        system->actuators[i].type = LED + i; // Assign different types
        system->actuators[i].state = false;
        system->actuators[i].setpoint = 0.0f;
    }

    system->initialized = true;
}

// Add sensor reading to the system
void add_sensor_reading(EdgeSystem *system, SensorType type, float value) {
    if (system == NULL || !system->initialized) return;

    for (int i = 0; i < MAX_SENSORS; i++) {
        if (system->sensors[i].type == type) {
            // Update current value
            system->sensors[i].value = value;
            system->sensors[i].timestamp = time(NULL);

            // Add to circular buffer
            system->data_buffer[i][system->buffer_index[i]] = value;
            system->buffer_index[i] = (system->buffer_index[i] + 1) % MAX_DATA_POINTS;

            break;
        }
    }
}

// Simple moving average filter
float apply_filter(EdgeSystem *system, SensorType type) {
    if (system == NULL || !system->initialized) return 0.0f;

    float sum = 0.0f;
    int count = 0;

    for (int i = 0; i < MAX_SENSORS; i++) {
        if (system->sensors[i].type == type) {
            // Calculate moving average
            for (int j = 0; j < FILTER_WINDOW_SIZE; j++) {
                int index = (system->buffer_index[i] - 1 - j + MAX_DATA_POINTS) % MAX_DATA_POINTS;
                sum += system->data_buffer[i][index];
                count++;
            }
            break;
        }
    }

    return (count > 0) ? (sum / count) : 0.0f;
}

// Control actuator based on filtered sensor data
void control_actuator(EdgeSystem *system, ActuatorType type, float threshold) {
    if (system == NULL || !system->initialized) return;

    for (int i = 0; i < MAX_ACTUATORS; i++) {
        if (system->actuators[i].type == type) {
            // Get filtered sensor data (using first sensor for simplicity)
            float filtered_value = apply_filter(system, TEMPERATURE);

            // Simple control logic
            if (filtered_value > threshold) {
                system->actuators[i].state = true;
            } else {
                system->actuators[i].state = false;
            }

            // Update setpoint
            system->actuators[i].setpoint = threshold;

            break;
        }
    }
}

// Print system status
void print_system_status(EdgeSystem *system) {
    if (system == NULL || !system->initialized) return;

    printf("\n=== Edge System Status ===\n");

    // Print sensor data
    printf("\nSensors:\n");
    for (int i = 0; i < MAX_SENSORS; i++) {
        printf("- Type: %d, Current: %.2f, Filtered: %.2f\n",
               system->sensors[i].type,
               system->sensors[i].value,
               apply_filter(system, system->sensors[i].type));
    }

    // Print actuator states
    printf("\nActuators:\n");
    for (int i = 0; i < MAX_ACTUATORS; i++) {
        printf("- Type: %d, State: %s, Setpoint: %.2f\n",
               system->actuators[i].type,
               system->actuators[i].state ? "ON" : "OFF",
               system->actuators[i].setpoint);
    }
}

// Main function for demonstration
