```cpp
#include <Arduino.h>

// Configuration
const int SENSOR_PIN = A0;      // Analog input for sensor
const int ACTUATOR_PIN = 9;     // PWM output for actuator
const int SAMPLE_WINDOW = 100;  // ms between samples
const int FILTER_WINDOW = 5;   // Number of samples for moving average

// Global variables
int sensorValues[FILTER_WINDOW] = {0};
int filterIndex = 0;
float filteredValue = 0;
unsigned long lastSampleTime = 0;

// Initialize system
void setup() {
  pinMode(SENSOR_PIN, INPUT);
  pinMode(ACTUATOR_PIN, OUTPUT);

  // Initialize filter buffer
  for (int i = 0; i < FILTER_WINDOW; i++) {
    sensorValues[i] = analogRead(SENSOR_PIN);
  }

  Serial.begin(9600);
}

// Main loop
void loop() {
  unsigned long currentTime = millis();

  // Check if it's time for a new sample
  if (currentTime - lastSampleTime >= SAMPLE_WINDOW) {
    lastSampleTime = currentTime;

    // Read new sensor value
    int rawValue = analogRead(SENSOR_PIN);

    // Update moving average filter
    filteredValue -= sensorValues[filterIndex] / (float)FILTER_WINDOW;
    sensorValues[filterIndex] = rawValue;
    filteredValue += rawValue / (float)FILTER_WINDOW;
    filterIndex = (filterIndex + 1) % FILTER_WINDOW;

    // Simple threshold-based control
    if (filteredValue > 512) {  // Example threshold
      analogWrite(ACTUATOR_PIN, 255);  // Actuator on
    } else {
      analogWrite(ACTUATOR_PIN, 0);   // Actuator off
    }

    // Debug output (optional)
    Serial.print("Raw: ");
    Serial.print(rawValue);
    Serial.print(" Filtered: ");
    Serial.println(filteredValue);
  }

  // Yield to other tasks (important for resource-constrained systems)
  delay(1);
}
