<body>
    <div id="info">Loading...</div>
    <div id="controls">
        <button id="toggleWireframe">Toggle Wireframe</button>
        <button id="toggleLight">Toggle Light</button>
        <button id="changeShader">Change Shader</button>
        <button id="addObject">Add Object</button>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/loaders/GLTFLoader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/EffectComposer.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/RenderPass.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/ShaderPass.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/CopyShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/FXAAShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/ColorifyShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/HorizontalBlurShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/VerticalBlurShader.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x222222);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Post-processing
        const composer = new THREE.EffectComposer(renderer);
        const renderPass = new THREE.RenderPass(scene, camera);
        composer.addPass(renderPass);

        // FXAA pass for anti-aliasing
        const fxaaPass = new THREE.ShaderPass(THREE.FXAAShader);
        fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        composer.addPass(fxaaPass);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        scene.add(directionalLight);

        // Light helper
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
        scene.add(lightHelper);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Grid helper
        const gridHelper = new THREE.GridHelper(20, 20);
        scene.add(gridHelper);

        // Objects
        const objects = [];
        const objectTypes = ['box', 'sphere', 'cone', 'torus'];

        // Create initial objects
        for (let i = 0; i < 5; i++) {
            addRandomObject();
        }

        // Shader materials
        const shaderMaterials = [
            new THREE.MeshStandardMaterial({
                color: 0x3498db,
                roughness: 0.4,
                metalness: 0.6
            }),
            new THREE.MeshPhongMaterial({
                color: 0xe74c3c,
                specular: 0xffffff,
                shininess: 30
            }),
            new THREE.MeshToonMaterial({
                color: 0x2ecc71,
                gradientMap: new THREE.TextureLoader().load('https://threejs.org/examples/textures/gradientMaps/threeTone.jpg')
            }),
            new THREE.MeshPhysicalMaterial({
                color: 0x9b59b6,
                roughness: 0.2,
                metalness: 0.8,
                clearcoat: 1.0,
                clearcoatRoughness: 0.1
            })
        ];

        let currentShaderIndex = 0;

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Rotate objects
            objects.forEach(obj => {
                obj.rotation.x += 0.005;
                obj.rotation.y += 0.003;
            });

            // Update light position (optional)
            directionalLight.position.x = Math.sin(Date.now() * 0.001) * 7;
            directionalLight.position.z = Math.cos(Date.now() * 0.001) * 7;

            controls.update();
            composer.render();
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
        });

        // UI Controls
        document.getElementById('toggleWireframe').addEventListener('click', () => {
            objects.forEach(obj => {
                obj.material.wireframe = !obj.material.wireframe;
            });
        });

        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            lightHelper.visible = !lightHelper.visible;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            objects.forEach(obj => {
                obj.material = shaderMaterials[currentShaderIndex].clone();
                obj.material.needsUpdate = true;
            });
        });

        document.getElementById('addObject').addEventListener('click', addRandomObject);

        // Helper function to add random object
        function addRandomObject() {
            const type = objectTypes[Math.floor(Math.random() * objectTypes.length)];
            let geometry, material;

            switch(type) {
                case 'box':
                    geometry = new THREE.BoxGeometry(1, 1, 1);
                    break;
                case 'sphere':
                    geometry = new THREE.SphereGeometry(0.7, 32, 32);
                    break;
                case 'cone':
                    geometry = new THREE.ConeGeometry(0.7, 1.5, 32);
                    break;
                case 'torus':
                    geometry = new THREE.TorusGeometry(0.7, 0.3, 16, 32);
                    break;
            }

            material = shaderMaterials[currentShaderIndex].clone();
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(
                (Math.random() - 0.5) * 10,
                Math.random() * 2 + 0.5,
                (Math.random() - 0.5) * 10
            );
            mesh.castShadow = true;
            mesh.receiveShadow = true;

            scene.add(mesh);
            objects.push(mesh);
        }

        // Start animation
        animate();

        // Hide loading message
        document.getElementById('info').style.display = 'none';
    </script>
</body>
</html>
