            mesh.receiveShadow = true;

            // Add to scene and objects array
            scene.add(mesh);
            objects.push(mesh);

            return mesh;
        }

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update custom shader time
            const time = performance.now() * 0.001;
