        const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
        torusKnot.position.set(0, 2, 5);
        torusKnot.castShadow = true;
        torusKnot.receiveShadow = true;
        scene.add(torusKnot);
        objects.push(torusKnot);

        // Add some random objects
        for (let i = 0; i < 10; i++) {
            const geometry = new THREE.TorusGeometry(0.5, 0.2, 16, 32);
            const material = new THREE.MeshStandardMaterial({
                color: new THREE.Color(Math.random(), Math.random(), Math.random()),
                roughness: Math.random(),
                metalness: Math.random()
            });
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(
                (Math.random() - 0.5) * 20,
                Math.random() * 5,
                (Math.random() - 0.5) * 20
            );
            mesh.rotation.set(
                Math.random() * Math.PI,
                Math.random() * Math.PI,
                Math.random() * Math.PI
            );
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            scene.add(mesh);
            objects.push(mesh);
        }

        // Animation variables
        let time = 0;
        const clock = new THREE.Clock();

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            const delta = clock.getDelta();
            time += delta;

            // Animate objects
            cube.rotation.x += 0.01;
            cube.rotation.y += 0.01;

            sphere.position.y = 2 + Math.sin(time * 2) * 0.5;

            torusKnot.rotation.x += 0.005;
            torusKnot.rotation.y += 0.005;

            // Animate point light
            pointLight.position.x = Math.sin(time) * 10;
            pointLight.position.z = Math.cos(time) * 10;

            // Update controls
            controls.update();

            // Render
            composer.render();
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
        });

        // UI controls
        document.getElementById('toggleDirectional').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            directionalLightHelper.visible = !directionalLightHelper.visible;
        });

        document.getElementById('togglePoint').addEventListener('click', () => {
            pointLight.visible = !pointLight.visible;
            pointLightHelper.visible = !pointLightHelper.visible;
        });

        document.getElementById('toggleBloom').addEventListener('click', () => {
            bloomPass.enabled = !bloomPass.enabled;
        });

        document.getElementById('toggleOutline').addEventListener('click', () => {
            outlinePass.enabled = !outlinePass.enabled;
        });

        // Start animation
        animate();
    </script>
</body>
</html>
