        scene.add(directionalLight);

        // Light helper
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
        scene.add(lightHelper);

        // Shader materials
        const shaderMaterials = [
            // Basic material
            new THREE.MeshStandardMaterial({
                color: 0x3366ff,
                roughness: 0.4,
                metalness: 0.6
            }),

            // Toon shader
            new THREE.MeshToonMaterial({
                color: 0xff6600,
                gradientMap: createGradientTexture()
            }),

            // Custom shader
            new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color1: { value: new THREE.Color(0xff0000) },
                    color2: { value: new THREE.Color(0x00ff00) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.5;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color1;
                    uniform vec3 color2;
                    varying vec2 vUv;
                    void main() {
                        vec3 color = mix(color1, color2, vUv.y);
                        gl_FragColor = vec4(color, 1.0);
                    }
                `
            })
        ];

        // Create gradient texture for toon shader
        function createGradientTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 256;
            canvas.height = 1;
            const context = canvas.getContext('2d');

            const gradient = context.createLinearGradient(0, 0, 256, 0);
            gradient.addColorStop(0.0, 'rgba(0, 0, 0, 1.0)');
            gradient.addColorStop(0.5, 'rgba(128, 128, 128, 1.0)');
            gradient.addColorStop(1.0, 'rgba(255, 255, 255, 1.0)');

            context.fillStyle = gradient;
            context.fillRect(0, 0, 256, 1);

            const texture = new THREE.CanvasTexture(canvas);
            texture.minFilter = THREE.NearestFilter;
            texture.magFilter = THREE.NearestFilter;
            texture.generateMipmaps = false;

            return texture;
        }

        // Create objects
        const objects = [];
        let currentShaderIndex = 0;

        function createObject() {
            const geometry = new THREE.TorusKnotGeometry(1, 0.4, 100, 16);
            const material = shaderMaterials[currentShaderIndex].clone();
            const mesh = new THREE.Mesh(geometry, material);
            mesh.position.set(
                (Math.random() - 0.5) * 10,
                (Math.random() - 0.5) * 5,
                (Math.random() - 0.5) * 10
            );
            mesh.rotation.set(
                Math.random() * Math.PI,
                Math.random() * Math.PI,
                Math.random() * Math.PI
            );
            mesh.castShadow = true;
            mesh.receiveShadow = true;
            scene.add(mesh);
            objects.push(mesh);
            return mesh;
        }

        // Create initial objects
        for (let i = 0; i < 3; i++) {
            createObject();
        }

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Event listeners
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            lightHelper.visible = directionalLight.visible;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            objects.forEach(obj => {
                obj.material = shaderMaterials[currentShaderIndex].clone();
            });
        });

        document.getElementById('addObject').addEventListener('click', () => {
            createObject();
        });

        document.getElementById('lightSlider').addEventListener('input', (e) => {
            const intensity = parseFloat(e.target.value);
            directionalLight.intensity = intensity;
            document.getElementById('lightIntensity').textContent = intensity.toFixed(1);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update custom shader uniforms
            if (currentShaderIndex === 2) {
                objects.forEach(obj => {
                    obj.material.uniforms.time.value += 0.01;
                });
            }

            // Rotate objects slightly
            objects.forEach(obj => {
                obj.rotation.y += 0.005;
            });

            renderer.render(scene, camera);
        }

        animate();
    </script>
</body>
</html>
