        composer.addPass(fxaaPass);

        // Create scene objects
        function createScene() {
            // Ground plane
            const groundGeometry = new THREE.PlaneGeometry(20, 20);
            const groundMaterial = new THREE.MeshStandardMaterial({
                color: 0x333333,
                roughness: 0.8,
                metalness: 0.2
            });
            const ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            scene.add(ground);

            // Add some objects
            const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
            const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
            const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);

            const materials = [
                new THREE.MeshStandardMaterial({ color: 0xff0000, roughness: 0.3, metalness: 0.7 }),
                new THREE.MeshStandardMaterial({ color: 0x00ff00, roughness: 0.5, metalness: 0.3 }),
                new THREE.MeshStandardMaterial({ color: 0x0000ff, roughness: 0.2, metalness: 0.8 }),
                new THREE.MeshStandardMaterial({ color: 0xffff00, roughness: 0.4, metalness: 0.5 })
            ];

