            for (let i = 0; i < 5; i++) {
                const box = new THREE.Mesh(boxGeometry, materials[i % materials.length]);
                box.position.set(Math.random() * 10 - 5, 1, Math.random() * 10 - 5);
                box.castShadow = true;
                box.receiveShadow = true;
                scene.add(box);

