                sphere.position.set(Math.random() * 10 - 5, 1, Math.random() * 10 - 5);
                sphere.castShadow = true;
                sphere.receiveShadow = true;
                scene.add(sphere);

                const torus = new THREE.Mesh(torusGeometry, materials[(i + 2) % materials.length]);
                torus.position.set(Math.random() * 10 - 5, 1, Math.random() * 10 - 5);
                torus.castShadow = true;
                torus.receiveShadow = true;
                scene.add(torus);
