            // Add a custom shader material for one object
            const customMaterial = new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color1: { value: new THREE.Color(0xff00ff) },
                    color2: { value: new THREE.Color(0x00ffff) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.5;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color1;
                    uniform vec3 color2;
                    varying vec2 vUv;
                    void main() {
                        vec3 color = mix(color1, color2, vUv.x);
                        gl_FragColor = vec4(color, 1.0);
                    }
                `,
                wireframe: false
            });

            const customBox = new THREE.Mesh(boxGeometry, customMaterial);
            customBox.position.set(0, 3, 0);
            customBox.castShadow = true;
            customBox.receiveShadow = true;
            scene.add(customBox);
        }

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update custom shader uniform
            const time = performance.now() * 0.001;
            scene.traverse((object) => {
                if (object.material && object.material.uniforms && object.material.uniforms.time) {
                    object.material.uniforms.time.value = time;
                }
            });

            // Move point light in a circle
            pointLight.position.x = Math.sin(time) * 5;
            pointLight.position.z = Math.cos(time) * 5;

            // Render
            if (usePostprocessing) {
                composer.render();
            } else {
                renderer.render(scene, camera);
            }
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
            fxaaPass.material.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        });

