            const mesh = new THREE.Mesh(type.geometry, type.material);

            // Store original material for shader toggle
            mesh.userData.originalMaterial = type.material;

            mesh.position.set(
                (Math.random() - 0.5) * 10,
                Math.random() * 2 + 0.5,
                (Math.random() - 0.5) * 10
            );

            mesh.rotation.set(
