        cube.receiveShadow = true;
        scene.add(cube);
        objects.push(cube);

        // Create a sphere
        const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
        const sphereMaterial = new THREE.MeshStandardMaterial({
            color: 0xff0000,
            roughness: 0.3,
            metalness: 0.7
        });
        const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
        sphere.position.set(5, 1.5, 0);
        sphere.castShadow = true;
        sphere.receiveShadow = true;
        scene.add(sphere);
        objects.push(sphere);

        // Create a torus
        const torusGeometry = new THREE.TorusGeometry(2, 0.5, 16, 32);
        const torusMaterial = new THREE.MeshStandardMaterial({
            color: 0x0000ff,
            roughness: 0.5,
            metalness: 0.3
        });
        const torus = new THREE.Mesh(torusGeometry, torusMaterial);
        torus.position.set(0, 2, 5);
        torus.castShadow = true;
        torus.receiveShadow = true;
        scene.add(torus);
        objects.push(torus);

        // Shader materials
        const shaderMaterials = [
            // Standard material
            new THREE.MeshStandardMaterial({
                color: 0x00ff00,
                roughness: 0.4,
                metalness: 0.6
            }),

            // Toon shader
            new THREE.MeshToonMaterial({
                color: 0x00ff00,
                gradientMap: createGradientTexture()
            }),

            // Phong material
            new THREE.MeshPhongMaterial({
                color: 0x00ff00,
                specular: 0x111111,
                shininess: 30
            }),

            // Custom shader material
            new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0x00ff00) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.2;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    varying vec2 vUv;
                    void main() {
                        vec3 col = color * (0.5 + 0.5 * sin(vUv.x * 10.0 + vUv.y * 10.0));
                        gl_FragColor = vec4(col, 1.0);
                    }
                `
            })
        ];

        let currentShaderIndex = 0;

        // Helper function to create gradient texture for toon shader
        function createGradientTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 256;
            canvas.height = 1;
            const context = canvas.getContext('2d');

            const gradient = context.createLinearGradient(0, 0, 256, 0);
            gradient.addColorStop(0.0, 'rgba(0, 0, 0, 1.0)');
            gradient.addColorStop(0.5, 'rgba(128, 128, 128, 1.0)');
            gradient.addColorStop(1.0, 'rgba(255, 255, 255, 1.0)');

            context.fillStyle = gradient;
            context.fillRect(0, 0, 256, 1);

            const texture = new THREE.CanvasTexture(canvas);
            texture.generateMipmaps = false;
            texture.minFilter = THREE.LinearFilter;
            texture.magFilter = THREE.LinearFilter;

            return texture;
        }

        // UI Controls
        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            pointLight.visible = !pointLight.visible;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            objects.forEach(obj => {
                obj.material = shaderMaterials[currentShaderIndex];
            });
        });

        document.getElementById('addObject').addEventListener('click', () => {
            const randomGeometry = Math.random() > 0.5 ?
                new THREE.SphereGeometry(1, 32, 32) :
                new THREE.BoxGeometry(1.5, 1.5, 1.5);

            const randomColor = new THREE.Color(Math.random(), Math.random(), Math.random());
            const newMaterial = shaderMaterials[currentShaderIndex].clone();
            newMaterial.color = randomColor;

            const newObject = new THREE.Mesh(randomGeometry, newMaterial);
            newObject.position.set(
                (Math.random() - 0.5) * 20,
                1,
                (Math.random() - 0.5) * 20
            );
            newObject.castShadow = true;
            newObject.receiveShadow = true;
            scene.add(newObject);
            objects.push(newObject);
        });

        document.getElementById('lightSlider').addEventListener('input', (e) => {
            const intensity = parseFloat(e.target.value);
            directionalLight.intensity = intensity;
            pointLight.intensity = intensity;
            document.getElementById('lightIntensity').textContent = intensity.toFixed(1);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update custom shader time
            if (currentShaderIndex === 3) { // Custom shader
                shaderMaterials[3].uniforms.time.value += 0.01;
            }

            // Rotate objects slightly
            objects.forEach(obj => {
                obj.rotation.y += 0.005;
            });

            // Move point light in a circle
            const time = Date.now() * 0.001;
            pointLight.position.x = Math.sin(time) * 5;
            pointLight.position.z = Math.cos(time) * 5;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate();
    </script>
</body>
</html>
```

