        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        // Helper for light visualization
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
        scene.add(lightHelper);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Grid helper
        const gridHelper = new THREE.GridHelper(20, 20, 0x444444, 0x222222);
        scene.add(gridHelper);

        // Load a 3D model (example: a simple box if no model is loaded)
        const geometry = new THREE.BoxGeometry(2, 2, 2);
        const material = new THREE.MeshStandardMaterial({
            color: 0x00ff00,
            roughness: 0.5,
            metalness: 0.5
        });
        const cube = new THREE.Mesh(geometry, material);
        cube.position.y = 1;
        cube.castShadow = true;
        scene.add(cube);

        // Shader materials for different effects
        const shaderMaterials = {
            standard: new THREE.MeshStandardMaterial({
                color: 0x00ff00,
                roughness: 0.5,
                metalness: 0.5
            }),

            toon: new THREE.MeshToonMaterial({
                color: 0x00ff00,
                gradientMap: createGradientTexture()
            }),

            water: new THREE.MeshPhongMaterial({
                color: 0x00aaff,
                specular: 0x111111,
                shininess: 30,
                transparent: true,
                opacity: 0.8,
                side: THREE.DoubleSide
            }),

            fire: new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    resolution: { value: new THREE.Vector2() }
                },
                vertexShader: `
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform float time;
                    varying vec2 vUv;

                    void main() {
                        vec2 uv = vUv;
                        uv.x += sin(uv.y * 10.0 + time * 2.0) * 0.1;
                        uv.y += cos(uv.x * 10.0 + time * 3.0) * 0.1;

                        float r = 0.5 + 0.5 * sin(uv.x * 10.0 + time);
                        float g = 0.5 + 0.5 * sin(uv.x * 10.0 + time + 2.0);
                        float b = 0.5 + 0.5 * sin(uv.x * 10.0 + time + 4.0);

                        gl_FragColor = vec4(r, g, b, 0.8);
                    }
                `,
                transparent: true
            })
        };

        // Helper function to create gradient texture for toon shading
        function createGradientTexture() {
            const canvas = document.createElement('canvas');
            canvas.width = 256;
            canvas.height = 1;
            const context = canvas.getContext('2d');

            const gradient = context.createLinearGradient(0, 0, 256, 0);
            gradient.addColorStop(0.0, 'black');
            gradient.addColorStop(0.5, 'white');
            gradient.addColorStop(1.0, 'white');

            context.fillStyle = gradient;
            context.fillRect(0, 0, 256, 1);

            const texture = new THREE.CanvasTexture(canvas);
            texture.minFilter = THREE.NearestFilter;
            texture.magFilter = THREE.NearestFilter;
            texture.generateMipmaps = false;

            return texture;
        }

        // UI Controls
        const lightIntensitySlider = document.getElementById('lightIntensity');
        const shaderTypeSelect = document.getElementById('shaderType');

        lightIntensitySlider.addEventListener('input', (e) => {
            directionalLight.intensity = parseFloat(e.target.value);
        });

        shaderTypeSelect.addEventListener('change', (e) => {
            const shaderType = e.target.value;
            cube.material = shaderMaterials[shaderType];

            // Special handling for fire shader
            if (shaderType === 'fire') {
                cube.material.uniforms.resolution.value.set(window.innerWidth, window.innerHeight);
            }
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update fire shader time if active
            if (cube.material === shaderMaterials.fire) {
                cube.material.uniforms.time.value += 0.05;
            }

            // Rotate the cube slightly
            cube.rotation.y += 0.005;

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate();
    </script>
