                    varying vec3 vViewPosition;
                    void main() {
                        vec3 normal = normalize(vNormal);
                        vec3 viewPosition = normalize(vViewPosition);
                        vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                        vec3 halfVector = normalize(lightDir + viewPosition);

                        float diffuseLight = max(dot(normal, lightDir), 0.0);
                        float specularLight = pow(max(dot(normal, halfVector), 0.0), shininess);

                        vec3 col = (diffuse * diffuseLight + specular * specularLight + emissive) * vec3(1.0, 1.0, 1.0);
                        gl_FragColor = vec4(col, opacity);
                    }
                `,
                lights: true
            }),
            'Toon': new THREE.ShaderMaterial({
                uniforms: THREE.UniformsUtils.merge([
                    THREE.ShaderLib.toon.uniforms,
                    {
                        time: { value: 0 }
                    }
                ]),
                vertexShader: THREE.ShaderLib.toon.vertexShader,
                fragmentShader: `
                    uniform vec3 diffuse;
                    uniform vec3 specular;
                    uniform float shininess;
                    uniform float opacity;
                    varying vec3 vNormal;
                    varying vec3 vViewPosition;
                    void main() {
                        vec3 normal = normalize(vNormal);
                        vec3 viewPosition = normalize(vViewPosition);
                        vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                        vec3 halfVector = normalize(lightDir + viewPosition);

                        float diffuseLight = max(dot(normal, lightDir), 0.0);
                        float specularLight = pow(max(dot(normal, halfVector), 0.0), shininess);

                        // Toon shading effect
                        diffuseLight = floor(diffuseLight * 3.0) / 3.0;
                        specularLight = floor(specularLight * 3.0) / 3.0;

                        vec3 col = (diffuse * diffuseLight + specular * specularLight) * vec3(1.0, 1.0, 1.0);
                        gl_FragColor = vec4(col, opacity);
                    }
                `,
                lights: true
            }),
            'Fresnel': new THREE.ShaderMaterial({
                uniforms: {
                    'mRefractionRatio': { value: 1.02 },
                    'mFresnelBias': { value: 0.1 },
                    'mFresnelPower': { value: 2.0 },
                    'mFresnelScale': { value: 1.0 },
                    'tCube': { value: null }
                },
                vertexShader: `
                    uniform float mRefractionRatio;
                    uniform float mFresnelBias;
                    uniform float mFresnelScale;
                    uniform float mFresnelPower;
                    varying vec3 vReflect;
                    varying vec3 vRefract[3];
                    varying float vReflectionFactor;
                    void main() {
                        vec4 mvPosition = modelViewMatrix * vec4(position, 1.0);
                        vec4 worldPosition = modelMatrix * vec4(position, 1.0);
                        vec3 worldNormal = normalize(mat3(modelMatrix[0].xyz, modelMatrix[1].xyz, modelMatrix[2].xyz) * normal);
                        vec3 I = worldPosition.xyz - cameraPosition;
                        vReflect = reflect(I, worldNormal);
                        vRefract[0] = refract(normalize(I), worldNormal, mRefractionRatio);
                        vRefract[1] = refract(normalize(I), worldNormal, mRefractionRatio * 0.99);
                        vRefract[2] = refract(normalize(I), worldNormal, mRefractionRatio * 0.98);
                        vReflectionFactor = mFresnelBias + mFresnelScale * pow(1.0 + dot(normalize(I), worldNormal), mFresnelPower);
                        gl_Position = projectionMatrix * mvPosition;
                    }
                `,
                fragmentShader: `
                    uniform samplerCube tCube;
                    varying vec3 vReflect;
                    varying vec3 vRefract[3];
                    varying float vReflectionFactor;
                    void main() {
                        vec4 reflectedColor = textureCube(tCube, vec3(-vReflect.x, vReflect.yz));
                        vec4 refractedColor = vec4(1.0);
                        refractedColor.r = textureCube(tCube, vec3(-vRefract[0].x, vRefract[0].yz)).r;
                        refractedColor.g = textureCube(tCube, vec3(-vRefract[1].x, vRefract[1].yz)).g;
                        refractedColor.b = textureCube(tCube, vec3(-vRefract[2].x, vRefract[2].yz)).b;
                        gl_FragColor = mix(refractedColor, reflectedColor, clamp(vReflectionFactor, 0.0, 1.0));
                    }
                `,
                side: THREE.DoubleSide
            })
        };

        // Create a cube map for the Fresnel shader
        const path = 'https://threejs.org/examples/textures/cube/SwedishRoyalCastle/';
        const format = '.jpg';
        const urls = [
            path + 'px' + format, path + 'nx' + format,
            path + 'py' + format, path + 'ny' + format,
            path + 'pz' + format, path + 'nz' + format
        ];
        const reflectionCube = new THREE.CubeTextureLoader().load(urls);
        reflectionCube.format = THREE.RGBFormat;
        scene.background = reflectionCube;
        shaderMaterials['Fresnel'].uniforms.tCube.value = reflectionCube;

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Objects
        const objects = [];
        let currentShader = 'Phong';

        // Create initial objects
        function createInitialObjects() {
            // Box
            const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
            const boxMaterial = shaderMaterials[currentShader].clone();
            boxMaterial.uniforms.diffuse = { value: new THREE.Color(0xff0000) };
            boxMaterial.uniforms.specular = { value: new THREE.Color(0x111111) };
            boxMaterial.uniforms.shininess = { value: 30 };
            boxMaterial.uniforms.opacity = { value: 1 };
            const box = new THREE.Mesh(boxGeometry, boxMaterial);
            box.position.set(-4, 1, 0);
            box.castShadow = true;
            scene.add(box);
            objects.push(box);

            // Sphere
            const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
            const sphereMaterial = shaderMaterials[currentShader].clone();
            sphereMaterial.uniforms.diffuse = { value: new THREE.Color(0x00ff00) };
            sphereMaterial.uniforms.specular = { value: new THREE.Color(0x111111) };
            sphereMaterial.uniforms.shininess = { value: 30 };
            sphereMaterial.uniforms.opacity = { value: 1 };
            const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
            sphere.position.set(0, 1.5, 0);
            sphere.castShadow = true;
            scene.add(sphere);
            objects.push(sphere);

            // Torus
            const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 100);
            const torusMaterial = shaderMaterials[currentShader].clone();
            torusMaterial.uniforms.diffuse = { value: new THREE.Color(0x0000ff) };
            torusMaterial.uniforms.specular = { value: new THREE.Color(0x111111) };
            torusMaterial.uniforms.shininess = { value: 30 };
            torusMaterial.uniforms.opacity = { value: 1 };
            const torus = new THREE.Mesh(torusGeometry, torusMaterial);
            torus.position.set(4, 1, 0);
            torus.castShadow = true;
            scene.add(torus);
            objects.push(torus);
        }

        createInitialObjects();

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update time for shaders
            const time = performance.now() * 0.001;
            objects.forEach(obj => {
                if (obj.material.uniforms && obj.material.uniforms.time) {
                    obj.material.uniforms.time.value = time;
                }
            });

            // Rotate objects slightly
            objects.forEach(obj => {
                obj.rotation.y += 0.005;
            });

            // Animate light
            directionalLight.position.x = Math.sin(time) * 7;
            directionalLight.position.z = Math.cos(time) * 7;
            lightHelper.update();

            renderer.render(scene, camera);
        }

        animate();

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // UI Controls
        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            lightHelper.visible = !lightHelper.visible;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            const shaders = Object.keys(shaderMaterials);
            const currentIndex = shaders.indexOf(currentShader);
            const nextIndex = (currentIndex + 1) % shaders.length;
            currentShader = shaders[nextIndex];

            objects.forEach(obj => {
                obj.material = shaderMaterials[currentShader].clone();
                // Copy existing uniforms
                for (const key in obj.material.uniforms) {
                    if (obj.material.uniforms[key].value !== undefined) {
                        obj.material.uniforms[key].value = obj.material.uniforms[key].value;
                    }
                }
            });
        });

        document.getElementById('addObject').addEventListener('click', () => {
            const geometries = [
                new THREE.BoxGeometry(1, 1, 1),
                new THREE.SphereGeometry(1, 32, 32),
                new THREE.TorusGeometry(1, 0.3, 16, 100),
                new THREE.ConeGeometry(1, 2, 32),
                new THREE.CylinderGeometry(1, 1, 2, 32)
            ];

            const colors = [
                0xff0000, 0x00ff00, 0x0000ff,
                0xffff00, 0xff00ff, 0x00ffff
            ];

            const randomGeometry = geometries[Math.floor(Math.random() * geometries.length)];
            const randomColor = colors[Math.floor(Math.random() * colors.length)];

            const material = shaderMaterials[currentShader].clone();
            material.uniforms.diffuse = { value: new THREE.Color(randomColor) };
            material.uniforms.specular = { value: new THREE.Color(0x111111) };
            material.uniforms.shininess = { value: 30 };
            material.uniforms.opacity = { value: 1 };

            const mesh = new THREE.Mesh(randomGeometry, material);
            mesh.position.set(
                (Math.random() - 0.5) * 10,
                1 + (Math.random() - 0.5) * 2,
                (Math.random() - 0.5) * 10
            );
            mesh.castShadow = true;
            scene.add(mesh);
            objects.push(mesh);
        });

        document.getElementById('resetScene').addEventListener('click', () => {
            // Remove all objects
            objects.forEach(obj => {
                scene.remove(obj);
            });
            objects.length = 0;

            // Recreate initial objects
            createInitialObjects();
        });

        document.getElementById('lightIntensity').addEventListener('input', (e) => {
            directionalLight.intensity = parseFloat(e.target.value);
        });

        // Toggle controls visibility with 'H' key
        document.addEventListener('keydown', (e) => {
            if (e.key.toLowerCase() === 'h') {
                const controlsDiv = document.getElementById('controls');
                controlsDiv.style.display = controlsDiv.style.display === 'none' ? 'block' : 'none';
            }
        });
    </script>
</body>
</html>
```

## Features

1. **Dynamic Lighting System**:
   - Directional light with shadows
   - Ambient light for base illumination
   - Light helper for visualization
   - Light intensity control via UI

2. **Shader Effects**:
