# Real-Time 3D Scene Viewer with Dynamic Lighting and Shader Effects

Below is a complete implementation of a real-time 3D scene viewer using Three.js, a popular JavaScript 3D library. This implementation includes dynamic lighting, shader effects, and interactive controls.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Scene Viewer with Dynamic Lighting</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            font-family: Arial, sans-serif;
        }
        #info {
            position: absolute;
            top: 10px;
            width: 100%;
            text-align: center;
            color: white;
            z-index: 100;
            text-shadow: 1px 1px 2px black;
        }
        #controls {
            position: absolute;
            bottom: 10px;
            width: 100%;
            text-align: center;
            color: white;
            z-index: 100;
            text-shadow: 1px 1px 2px black;
        }
        canvas {
            display: block;
        }
    </style>
</head>
<body>
    <div id="info">
        <h1>3D Scene Viewer with Dynamic Lighting</h1>
        <p>Use mouse to look around, WASD to move, Q/E to move up/down</p>
    </div>
    <div id="controls">
        <button id="toggleWireframe">Toggle Wireframe</button>
        <button id="togglePostProcessing">Toggle Post-Processing</button>
        <button id="changeShader">Change Shader</button>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/EffectComposer.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/RenderPass.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/ShaderPass.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/CopyShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/FXAAShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/UnrealBloomPass.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/LuminosityHighPassShader.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 15);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Post-processing setup
        const composer = new THREE.EffectComposer(renderer);
        const renderPass = new THREE.RenderPass(scene, camera);
        composer.addPass(renderPass);

        // Bloom effect
        const bloomPass = new THREE.UnrealBloomPass(
            new THREE.Vector2(window.innerWidth, window.innerHeight),
            1.5, // strength
            0.4, // radius
            0.85 // threshold
        );
        composer.addPass(bloomPass);

        // FXAA pass
        const fxaaPass = new THREE.ShaderPass(THREE.FXAAShader);
        fxaaPass.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        composer.addPass(fxaaPass);

        // Shader materials
        const shaderMaterials = [
            // Standard material
            new THREE.MeshStandardMaterial({
                color: 0x3366ff,
                roughness: 0.4,
                metalness: 0.6,
                envMapIntensity: 1.0
            }),

            // Toon shader
            new THREE.ShaderMaterial({
                uniforms: {
                    uColor: { value: new THREE.Color(0xff6600) },
                    uLightPosition: { value: new THREE.Vector3(10, 10, 10) }
                },
                vertexShader: `
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 uColor;
                    uniform vec3 uLightPosition;
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        vec3 lightDir = normalize(uLightPosition - vPosition);
                        float diffuse = max(dot(vNormal, lightDir), 0.0);

                        // Toon shading
                        if (diffuse > 0.95) diffuse = 1.0;
                        else if (diffuse > 0.5) diffuse = 0.7;
                        else if (diffuse > 0.2) diffuse = 0.4;
                        else diffuse = 0.1;

                        gl_FragColor = vec4(uColor * diffuse, 1.0);
                    }
                `
            }),

            // Water shader
            new THREE.ShaderMaterial({
                uniforms: {
                    uTime: { value: 0 },
                    uColor: { value: new THREE.Color(0x0066ff) },
                    uLightPosition: { value: new THREE.Vector3(10, 10, 10) }
                },
                vertexShader: `
                    uniform float uTime;
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        vNormal = normalize(normalMatrix * normal);
                        vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;

                        // Simple wave effect
                        vec3 newPosition = position;
                        newPosition.z += sin(position.x * 2.0 + uTime * 2.0) * 0.2;
                        newPosition.z += cos(position.y * 2.0 + uTime * 1.5) * 0.1;

                        gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 uColor;
                    uniform vec3 uLightPosition;
                    varying vec3 vNormal;
                    varying vec3 vPosition;

                    void main() {
                        vec3 lightDir = normalize(uLightPosition - vPosition);
                        float diffuse = max(dot(vNormal, lightDir), 0.0);

                        // Add some specular highlights
                        vec3 viewDir = normalize(-vPosition);
                        vec3 reflectDir = reflect(-lightDir, vNormal);
                        float specular = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

                        gl_FragColor = vec4(uColor * (diffuse + specular * 0.5), 1.0);
                    }
                `
            })
        ];

        // Create scene objects
        function createScene() {
            // Ground plane
            const groundGeometry = new THREE.PlaneGeometry(50, 50);
            const groundMaterial = new THREE.MeshStandardMaterial({
                color: 0x333333,
                roughness: 0.8,
                metalness: 0.2
            });
            const ground = new THREE.Mesh(groundGeometry, groundMaterial);
            ground.rotation.x = -Math.PI / 2;
            ground.receiveShadow = true;
            scene.add(ground);

            // Add some cubes
            for (let i = 0; i < 10; i++) {
                const geometry = new THREE.BoxGeometry(
                    Math.random() * 3 + 1,
                    Math.random() * 5 + 1,
                    Math.random() * 3 + 1
                );

                const materialIndex = Math.floor(Math.random() * shaderMaterials.length);
                const material = shaderMaterials[materialIndex].clone();

                const cube = new THREE.Mesh(geometry, material);
                cube.position.set(
                    (Math.random() - 0.5) * 20,
                    geometry.parameters.height / 2,
                    (Math.random() - 0.5) * 20
                );
                cube.castShadow = true;
                cube.receiveShadow = true;
                scene.add(cube);
            }

            // Add a sphere
            const sphereGeometry = new THREE.SphereGeometry(2, 32, 32);
            const sphereMaterial = new THREE.MeshStandardMaterial({
                color: 0xff3366,
                roughness: 0.3,
                metalness: 0.7
            });
            const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
            sphere.position.set(5, 2, 5);
            sphere.castShadow = true;
            sphere.receiveShadow = true;
            scene.add(sphere);

            // Add a torus knot
            const torusGeometry = new THREE.TorusKnotGeometry(2, 0.8, 100, 16);
            const torusMaterial = new THREE.MeshStandardMaterial({
                color: 0x66ff66,
                roughness: 0.2,
                metalness: 0.8
            });
            const torus = new THREE.Mesh(torusGeometry, torusMaterial);
            torus.position.set(-5, 3, -5);
            torus.castShadow = true;
            torus.receiveShadow = true;
            scene.add(torus);

            // Add lights
            const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
            scene.add(ambientLight);

            const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
            directionalLight.position.set(10, 10, 10);
            directionalLight.castShadow = true;
            directionalLight.shadow.mapSize.width = 2048;
            directionalLight.shadow.mapSize.height = 2048;
            scene.add(directionalLight);

            const pointLight = new THREE.PointLight(0xff9900, 0.5, 20);
            pointLight.position.set(-5, 5, 0);
            scene.add(pointLight);

            // Add a helper for the directional light
            const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
            scene.add(lightHelper);

            // Add a helper for the point light
            const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
            scene.add(pointLightHelper);
        }

        // Initialize the scene
        createScene();

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update shader uniforms
            const time = performance.now() * 0.001;
            scene.traverse((object) => {
                if (object.material && object.material.uniforms) {
                    if (object.material.uniforms.uTime) {
                        object.material.uniforms.uTime.value = time;
                    }
                    if (object.material.uniforms.uLightPosition) {
                        object.material.uniforms.uLightPosition.value.set(
                            Math.sin(time) * 10,
                            10,
                            Math.cos(time) * 10
                        );
                    }
                }
            });

            // Render with or without post-processing
            if (usePostProcessing) {
                composer.render();
            } else {
                renderer.render(scene, camera);
            }
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
            fxaaPass.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        });

        // UI controls
        let usePostProcessing = true;
        let currentShaderIndex = 0;

        document.getElementById('toggleWireframe').addEventListener('click', () => {
            scene.traverse((object) => {
                if (object.isMesh) {
                    object.material.wireframe = !object.material.wireframe;
                }
            });
        });

        document.getElementById('togglePostProcessing').addEventListener('click', () => {
            usePostProcessing = !usePostProcessing;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            scene.traverse((object) => {
                if (object.isMesh) {
                    object.material = shaderMaterials[currentShaderIndex].clone();
                }
            });
        });

        // Start animation
        animate();
    </script>
</body>
</html>
