        <h3>Scene Controls</h3>
        <button id="toggleWireframe">Toggle Wireframe</button>
        <button id="toggleLight">Toggle Light</button>
        <button id="changeShader">Change Shader</button>
        <div>
            <label>Light Intensity: <input type="range" id="lightIntensity" min="0" max="2" step="0.1" value="1"></label>
        </div>
        <div>
            <label>Light Color: <input type="color" id="lightColor" value="#ffffff"></label>
        </div>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/build/three.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/controls/OrbitControls.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/ToonShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/shaders/FXAAShader.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/EffectComposer.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/RenderPass.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/three@0.132.2/examples/js/postprocessing/ShaderPass.js"></script>

    <script>
        // Scene setup
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x111111);

        // Camera setup
        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 5, 10);

        // Renderer setup
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // Controls
        const controls = new THREE.OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;

        // Post-processing
        const composer = new THREE.EffectComposer(renderer);
        const renderPass = new THREE.RenderPass(scene, camera);
        composer.addPass(renderPass);

        // FXAA pass for anti-aliasing
        const fxaaPass = new THREE.ShaderPass(THREE.FXAAShader);
        fxaaPass.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        composer.addPass(fxaaPass);

        // Lighting
        const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
        scene.add(ambientLight);

        const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
        directionalLight.position.set(5, 10, 7);
        directionalLight.castShadow = true;
        directionalLight.shadow.mapSize.width = 1024;
        directionalLight.shadow.mapSize.height = 1024;
        directionalLight.shadow.camera.near = 0.5;
        directionalLight.shadow.camera.far = 50;
        scene.add(directionalLight);

        // Helper to visualize light
        const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
        scene.add(lightHelper);

        // Ground plane
        const groundGeometry = new THREE.PlaneGeometry(20, 20);
        const groundMaterial = new THREE.MeshStandardMaterial({
            color: 0x333333,
            roughness: 0.8,
            metalness: 0.2
        });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Create a group for objects
        const objectGroup = new THREE.Group();
        scene.add(objectGroup);

        // Add some objects to the scene
        function createObjects() {
            // Clear existing objects
            while(objectGroup.children.length > 0) {
                objectGroup.remove(objectGroup.children[0]);
            }

            // Create a torus knot
            const torusGeometry = new THREE.TorusKnotGeometry(1, 0.4, 100, 16);
            const torusMaterial = new THREE.MeshStandardMaterial({
                color: 0x4488ff,
                roughness: 0.3,
                metalness: 0.7
            });
            const torus = new THREE.Mesh(torusGeometry, torusMaterial);
            torus.position.set(-3, 1, 0);
            torus.castShadow = true;
            torus.receiveShadow = true;
            objectGroup.add(torus);

            // Create a sphere
            const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
            const sphereMaterial = new THREE.MeshStandardMaterial({
                color: 0xff4444,
                roughness: 0.2,
                metalness: 0.8
            });
            const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
            sphere.position.set(3, 1, 0);
            sphere.castShadow = true;
            sphere.receiveShadow = true;
            objectGroup.add(sphere);

            // Create a box
            const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
            const boxMaterial = new THREE.MeshStandardMaterial({
                color: 0x44ff88,
                roughness: 0.5,
                metalness: 0.3
            });
            const box = new THREE.Mesh(boxGeometry, boxMaterial);
            box.position.set(0, 1, 3);
            box.castShadow = true;
            box.receiveShadow = true;
            objectGroup.add(box);

            // Create a cylinder
            const cylinderGeometry = new THREE.CylinderGeometry(0.8, 0.8, 2, 32);
            const cylinderMaterial = new THREE.MeshStandardMaterial({
                color: 0xffaa44,
                roughness: 0.4,
                metalness: 0.6
            });
            const cylinder = new THREE.Mesh(cylinderGeometry, cylinderMaterial);
            cylinder.position.set(0, 1, -3);
            cylinder.castShadow = true;
            cylinder.receiveShadow = true;
            objectGroup.add(cylinder);
        }

        createObjects();

        // Shader materials
        const shaderMaterials = [
            // Standard material
            new THREE.MeshStandardMaterial({
                color: 0x4488ff,
                roughness: 0.3,
                metalness: 0.7
            }),

            // Toon shader
            new THREE.ShaderMaterial({
                uniforms: THREE.UniformsUtils.clone(THREE.ToonShader.uniforms),
                vertexShader: THREE.ToonShader.vertexShader,
                fragmentShader: THREE.ToonShader.fragmentShader,
                defines: {
                    'USE_SHADOWMAP': ''
                }
            }),

            // Custom shader with noise
            new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(0x4488ff) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    varying vec3 vNormal;

                    void main() {
                        vUv = uv;
                        vNormal = normalize(normalMatrix * normal);
                        vec3 pos = position;

                        // Add some simple animation
                        pos.y += sin(pos.x * 2.0 + time) * 0.1;
                        pos.z += cos(pos.y * 2.0 + time) * 0.1;

                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    varying vec2 vUv;
                    varying vec3 vNormal;

                    void main() {
                        // Simple lighting
                        vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                        float diffuse = max(dot(vNormal, lightDir), 0.0);

                        // Add some pattern
                        float pattern = sin(vUv.x * 10.0) * sin(vUv.y * 10.0) * 0.2 + 0.8;

                        vec3 finalColor = color * diffuse * pattern;
                        gl_FragColor = vec4(finalColor, 1.0);
                    }
                `
            })
        ];

        let currentShaderIndex = 0;

        // UI Controls
        document.getElementById('toggleWireframe').addEventListener('click', () => {
            objectGroup.children.forEach(obj => {
                obj.material.wireframe = !obj.material.wireframe;
            });
        });

        document.getElementById('toggleLight').addEventListener('click', () => {
            directionalLight.visible = !directionalLight.visible;
            lightHelper.visible = directionalLight.visible;
        });

        document.getElementById('changeShader').addEventListener('click', () => {
            currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
            objectGroup.children.forEach(obj => {
                obj.material = shaderMaterials[currentShaderIndex].clone();
            });
        });

        document.getElementById('lightIntensity').addEventListener('input', (e) => {
            directionalLight.intensity = parseFloat(e.target.value);
        });

        document.getElementById('lightColor').addEventListener('input', (e) => {
            directionalLight.color.set(e.target.value);
        });

        // Toggle controls visibility
        document.addEventListener('keydown', (e) => {
            if (e.key === 'h' || e.key === 'H') {
                const controlsDiv = document.getElementById('controls');
                controlsDiv.style.display = controlsDiv.style.display === 'none' ? 'block' : 'none';
            }
        });

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
            composer.setSize(window.innerWidth, window.innerHeight);
            fxaaPass.uniforms['resolution'].value.set(1 / window.innerWidth, 1 / window.innerHeight);
        });

        // Animation loop
        function animate() {
            requestAnimationFrame(animate);

            // Update controls
            controls.update();

            // Update custom shader time
            if (currentShaderIndex === 2) {
                shaderMaterials[2].uniforms.time.value += 0.01;
            }

            // Rotate the object group slightly
            objectGroup.rotation.y += 0.005;

            // Render the scene
            composer.render();
        }

        animate();
    </script>
</body>
</html>
```

