    mesh.receiveShadow = true;

    scene.add(mesh);
    objects.push(mesh);
}

// Add some initial objects
for (let i = 0; i < 5; i++) {
    addRandomObject();
}

// Shader effects
let currentShader = 'none';
let composer, water, waterUniforms, bloomPass;

function setupShaderEffects() {
    // Remove previous composer if it exists
    if (composer) {
        composer.dispose();
    }

    // Create new composer
    composer = new THREE.EffectComposer(renderer);
    const renderPass = new THREE.RenderPass(scene, camera);
    composer.addPass(renderPass);

    // Apply selected shader effect
    switch (currentShader) {
        case 'toon':
            // Toon shading is handled by material properties
            objects.forEach(obj => {
                obj.material.gradientMap = createGradientTexture();
            });
            break;

        case 'water':
            // Water effect using WaterShader
            const waterGeometry = new THREE.PlaneGeometry(20, 20);
            waterUniforms = THREE.WaterShader.uniforms;
            waterUniforms.size.value = 1.0;
            waterUniforms.distortionScale.value = 3.7;

            const waterMaterial = new THREE.ShaderMaterial({
                uniforms: waterUniforms,
                vertexShader: THREE.WaterShader.vertexShader,
                fragmentShader: THREE.WaterShader.fragmentShader,
                transparent: true
            });

            water = new THREE.Mesh(waterGeometry, waterMaterial);
            water.rotation.x = -Math.PI / 2;
            water.position.y = 0.1;
            scene.add(water);
            break;

        case 'glow':
            // Glow effect using UnrealBloomPass
            bloomPass = new THREE.UnrealBloomPass(
                new THREE.Vector2(window.innerWidth, window.innerHeight),
                1.5, 0.4, 0.85
            );
            composer.addPass(bloomPass);
            break;

        default:
            // No shader effect
            break;
    }
}

// Helper function to create gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 1;
    const context = canvas.getContext('2d');

    const gradient = context.createLinearGradient(0, 0, 256, 0);
    gradient.addColorStop(0.0, 'rgba(0, 0, 0, 1)');
    gradient.addColorStop(0.5, 'rgba(128, 128, 128, 1)');
    gradient.addColorStop(1.0, 'rgba(255, 255, 255, 1)');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 1);

    const texture = new THREE.CanvasTexture(canvas);
    texture.generateMipmaps = false;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;

    return texture;
}

// UI Controls
document.getElementById('light-intensity').addEventListener('input', (e) => {
    const intensity = parseFloat(e.target.value);
    directionalLight.intensity = intensity;
    ambientLight.intensity = intensity * 0.5;
});

document.getElementById('shader-effect').addEventListener('change', (e) => {
    // Remove previous water mesh if it exists
    if (water) {
        scene.remove(water);
        water.geometry.dispose();
        water.material.dispose();
        water = null;
    }

    currentShader = e.target.value;
    setupShaderEffects();
});

document.getElementById('add-object').addEventListener('click', addRandomObject);

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update water shader if active
    if (currentShader === 'water' && waterUniforms) {
        waterUniforms.time.value += 0.01;
    }

    // Render
    if (composer) {
        composer.render();
    } else {
        renderer.render(scene, camera);
    }
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);

    if (composer) {
        composer.setSize(window.innerWidth, window.innerHeight);
    }
});

// Initialize
setupShaderEffects();
animate();
```

