        roughness: 0.2,
        metalness: 0.8
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(2, 0.5, 0);
    sphere.castShadow = true;
    scene.add(sphere);
    objects.push(sphere);

