// Setup shader materials
function setupShaderMaterials() {
    // Custom shader for the box
    const box = objects.find(obj => obj.geometry.type === 'BoxGeometry');
    if (box) {
        const customShader = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color: { value: new THREE.Color(0x00ff00) }
            },
            vertexShader: `
                uniform float time;
                varying vec2 vUv;
                void main() {
                    vUv = uv;
                    vec3 pos = position;
                    pos.y += sin(pos.x * 2.0 + time) * 0.1;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color;
                varying vec2 vUv;
                void main() {
                    vec3 col = color * (0.5 + 0.5 * sin(vUv.x * 10.0 + vUv.y * 10.0));
                    gl_FragColor = vec4(col, 1.0);
                }
            `,
            wireframe: false
        });

        shaderMaterials.box = customShader;
        box.material = customShader;
    }

    // Custom shader for the sphere
    const sphere = objects.find(obj => obj.geometry.type === 'SphereGeometry');
    if (sphere) {
        const customShader = new THREE.ShaderMaterial({
            uniforms: {
                time: { value: 0 },
                color: { value: new THREE.Color(0x0000ff) }
            },
            vertexShader: `
                uniform float time;
                varying vec3 vNormal;
                void main() {
                    vNormal = normalize(normalMatrix * normal);
                    vec3 pos = position;
                    pos += normal * sin(pos.x * 5.0 + time) * 0.1;
                    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                }
            `,
            fragmentShader: `
                uniform vec3 color;
                varying vec3 vNormal;
                void main() {
                    vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                    float diffuse = max(dot(vNormal, lightDir), 0.0);
                    vec3 col = color * (0.5 + 0.5 * diffuse);
                    gl_FragColor = vec4(col, 1.0);
                }
            `,
            wireframe: false
        });

        shaderMaterials.sphere = customShader;
        sphere.material = customShader;
    }
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();
    const time = clock.getElapsedTime();

    // Update shader uniforms
    if (shaderMaterials.box) {
        shaderMaterials.box.uniforms.time.value = time;
    }
    if (shaderMaterials.sphere) {
        shaderMaterials.sphere.uniforms.time.value = time;
    }

    // Animate point light
    pointLight.position.x = Math.sin(time) * 3;
    pointLight.position.z = Math.cos(time) * 3;

    // Update controls
    controls.update();

    // Render
    renderer.render(scene, camera);

    // Update stats
    stats.update();
}

