                child.material.needsUpdate = true;
                child.material.lights = false;
            }
        });
        currentLighting = 'static';
        document.getElementById('lighting').textContent = 'Lighting: Static';
    } else {
        // Switch back to dynamic lighting
        scene.traverse(function (child) {
            if (child.isMesh) {
                child.material.needsUpdate = true;
