    const shaders = ['standard', 'toon', 'phong', 'custom'];
    const currentIndex = shaders.indexOf(currentShader);
    const nextIndex = (currentIndex + 1) % shaders.length;
    currentShader = shaders[nextIndex];

    document.getElementById('shader').textContent = `Shader: ${currentShader.charAt(0).toUpperCase() + currentShader.slice(1)}`;

    // Apply shader to all meshes
    scene.traverse(function (child) {
