                color: originalMaterial.color,
                roughness: originalMaterial.roughness || 0.5,
                metalness: originalMaterial.metalness || 0.5
            });
            break;
        case 'toon':
            newMaterial = new THREE.MeshToonMaterial({
                color: originalMaterial.color,
                gradientMap: createGradientTexture()
            });
            break;
        case 'phong':
            newMaterial = new THREE.MeshPhongMaterial({
                color: originalMaterial.color,
                specular: 0x111111,
                shininess: 30
            });
            break;
        case 'custom':
            // Example of a custom shader
            newMaterial = new THREE.ShaderMaterial({
                uniforms: {
                    time: { value: 0 },
                    color: { value: new THREE.Color(originalMaterial.color) }
                },
                vertexShader: `
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vUv = uv;
                        vec3 pos = position;
                        pos.y += sin(pos.x * 2.0 + time) * 0.1;
                        gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
                    }
                `,
                fragmentShader: `
                    uniform vec3 color;
                    uniform float time;
                    varying vec2 vUv;
                    void main() {
                        vec3 col = color * (0.5 + 0.5 * sin(vUv.y * 10.0 + time));
                        gl_FragColor = vec4(col, 1.0);
                    }
                `,
                lights: true
            });
            break;
        default:
            newMaterial = originalMaterial;
    }

    // Copy shadow properties
    newMaterial.castShadow = originalMaterial.castShadow;
    newMaterial.receiveShadow = originalMaterial.receiveShadow;

    // Replace material
    mesh.material = newMaterial;
}

// Helper function to create a gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 1;
    const context = canvas.getContext('2d');

    const gradient = context.createLinearGradient(0, 0, 256, 0);
    gradient.addColorStop(0.0, 'rgba(0,0,0,1)');
    gradient.addColorStop(0.5, 'rgba(128,128,128,1)');
    gradient.addColorStop(1.0, 'rgba(255,255,255,1)');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 1);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.NearestFilter;
    texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    return texture;
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();

    // Update stats
    stats.update();

    // Update FPS display
    document.getElementById('fps').textContent = `FPS: ${Math.round(1 / delta)}`;

    // Update controls
    controls.update();

    // Update animation mixer
    if (mixer) {
        mixer.update(delta);
    }

    // Update custom shader uniforms
    if (currentShader === 'custom') {
        scene.traverse(function (child) {
            if (child.isMesh && child.material.isShaderMaterial) {
                child.material.uniforms.time.value += delta;
            }
        });
    }

    // Render scene
    renderer.render(scene, camera);
}

// Initialize the scene when the page loads
window.addEventListener('load', init);
```

