// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x111111);

// Camera setup
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 5, 10);

// Renderer setup
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1.0);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
directionalLight.shadow.camera.near = 0.5;
directionalLight.shadow.camera.far = 50;
scene.add(directionalLight);

// Helper to visualize light direction
const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
scene.add(lightHelper);

// Ground plane
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Create some objects
function createObjects() {
    // Box
    const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
    const boxMaterial = new THREE.MeshStandardMaterial({
        color: 0x00ff00,
        roughness: 0.4,
        metalness: 0.5
    });
    const box = new THREE.Mesh(boxGeometry, boxMaterial);
    box.position.set(-3, 1, 0);
    box.castShadow = true;
    scene.add(box);

    // Sphere
    const sphereGeometry = new THREE.SphereGeometry(1.5, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({
        color: 0xff0000,
        roughness: 0.3,
        metalness: 0.7
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(3, 1.5, 0);
    sphere.castShadow = true;
    scene.add(sphere);

    // Torus
    const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);
    const torusMaterial = new THREE.MeshStandardMaterial({
        color: 0x0000ff,
        roughness: 0.6,
        metalness: 0.3
    });
    const torus = new THREE.Mesh(torusGeometry, torusMaterial);
    torus.position.set(0, 1, -3);
    torus.castShadow = true;
    scene.add(torus);
}

createObjects();

// Shader effects
const shaderEffects = {
    standard: {
        vertexShader: null,
        fragmentShader: null,
        uniforms: {}
    },
    toon: {
        vertexShader: `
            varying vec3 vNormal;
            void main() {
                vNormal = normalize(normalMatrix * normal);
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            varying vec3 vNormal;
            void main() {
                vec3 lightDir = normalize(vec3(1.0, 1.0, 1.0));
                float intensity = dot(vNormal, lightDir);

                if (intensity > 0.95) intensity = 1.0;
                else if (intensity > 0.5) intensity = 0.6;
                else if (intensity > 0.25) intensity = 0.3;
                else intensity = 0.1;

                gl_FragColor = vec4(vec3(intensity), 1.0);
            }
        `,
        uniforms: {}
    },
    water: {
        vertexShader: `
            uniform float time;
            varying vec2 vUv;
            void main() {
                vUv = uv;
                vec3 newPosition = position + normal * sin(position.x * 5.0 + time * 2.0) * 0.1;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
            }
        `,
        fragmentShader: `
            uniform float time;
            varying vec2 vUv;
            void main() {
                float wave = sin(vUv.x * 10.0 + time * 2.0) * 0.5 + 0.5;
                vec3 color = mix(vec3(0.0, 0.2, 0.8), vec3(0.2, 0.4, 1.0), wave);
                gl_FragColor = vec4(color, 0.8);
            }
        `,
        uniforms: {
            time: { value: 0 }
        }
    },
    fire: {
        vertexShader: `
            uniform float time;
            varying vec2 vUv;
            varying float vNoise;
            void main() {
                vUv = uv;
                vNoise = sin(position.x * 10.0 + time * 5.0) * cos(position.y * 10.0 + time * 3.0);
                vec3 newPosition = position + normal * vNoise * 0.2;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
            }
        `,
        fragmentShader: `
            uniform float time;
            varying vec2 vUv;
            varying float vNoise;
            void main() {
                float noise = vNoise * 0.5 + 0.5;
                vec3 color = mix(vec3(1.0, 0.5, 0.0), vec3(1.0, 0.0, 0.0), noise);
                color = mix(color, vec3(1.0, 1.0, 0.5), sin(vUv.x * 10.0 + time * 10.0) * 0.5 + 0.5);
                gl_FragColor = vec4(color, noise * 0.8);
            }
        `,
        uniforms: {
            time: { value: 0 }
        }
    }
};

// Apply shader effect to objects
function applyShaderEffect(effectName) {
    const effect = shaderEffects[effectName];

    scene.traverse((object) => {
        if (object.isMesh && object !== ground) {
            if (effectName === 'standard') {
                // Reset to standard material
                object.material = new THREE.MeshStandardMaterial({
                    color: object.material.color,
                    roughness: object.material.roughness,
                    metalness: object.material.metalness
                });
            } else {
                // Create custom shader material
                const uniforms = {
                    ...effect.uniforms,
                    time: { value: 0 }
                };

                object.material = new THREE.ShaderMaterial({
                    uniforms: uniforms,
                    vertexShader: effect.vertexShader,
                    fragmentShader: effect.fragmentShader,
                    transparent: true
                });
            }
        }
    });
}

// UI Controls
document.getElementById('lightIntensity').addEventListener('input', (e) => {
    const intensity = parseFloat(e.target.value);
    directionalLight.intensity = intensity;
    document.getElementById('lightIntensityValue').textContent = intensity.toFixed(1);
});

document.getElementById('shaderEffect').addEventListener('change', (e) => {
    applyShaderEffect(e.target.value);
});

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update shader effects with time
    const time = performance.now() * 0.001;
    scene.traverse((object) => {
        if (object.material && object.material.uniforms && object.material.uniforms.time) {
            object.material.uniforms.time.value = time;
        }
    });

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
