```javascript
// Main scene setup
let scene, camera, renderer, controls;
let clock = new THREE.Clock();
let stats;

// Lighting
let ambientLight, directionalLight, pointLight, spotLight;
let lightingMode = 'standard';

// Shader materials
let shaderMaterials = {
    'phong': new THREE.MeshPhongMaterial({ color: 0x336699, shininess: 30 }),
    'toon': new THREE.MeshToonMaterial({ color: 0x336699 }),
    'lambert': new THREE.MeshLambertMaterial({ color: 0x336699 }),
    'custom': null
};
let currentShader = 'phong';

// Objects in scene
let objects = [];

// Initialize the scene
function init() {
    // Create scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);

    // Create camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 5, 10);

    // Create renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // Add orbit controls
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Add lights
    setupLights();

    // Create ground plane
    const groundGeometry = new THREE.PlaneGeometry(20, 20);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x444444,
        roughness: 0.8,
        metalness: 0.2
    });
    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Create some sample objects
    createSampleObjects();

    // Add custom shader material
    createCustomShaderMaterial();

    // Add event listeners
    window.addEventListener('resize', onWindowResize);
    window.addEventListener('keydown', onKeyDown);

    // Add stats
    stats = new Stats();
    document.body.appendChild(stats.dom);

    // Start animation loop
    animate();
}

// Setup lighting
function setupLights() {
    // Ambient light
    ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    scene.add(ambientLight);

    // Directional light (sun)
    directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(5, 10, 7);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    directionalLight.shadow.camera.near = 0.5;
    directionalLight.shadow.camera.far = 50;
    scene.add(directionalLight);

    // Point light
    pointLight = new THREE.PointLight(0xff9900, 0.5, 15);
    pointLight.position.set(-3, 3, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Spot light
    spotLight = new THREE.SpotLight(0x00ff99, 0.7, 20, Math.PI / 6, 0.5, 1);
    spotLight.position.set(3, 5, 3);
    spotLight.target.position.set(0, 0, 0);
    spotLight.castShadow = true;
    scene.add(spotLight);
    scene.add(spotLight.target);

    // Add light helpers
    const directionalLightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
    scene.add(directionalLightHelper);

    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
    scene.add(pointLightHelper);

    const spotLightHelper = new THREE.SpotLightHelper(spotLight);
    scene.add(spotLightHelper);
}

// Create sample objects
function createSampleObjects() {
    // Create a cube
    const cubeGeometry = new THREE.BoxGeometry(2, 2, 2);
    const cube = new THREE.Mesh(cubeGeometry, shaderMaterials[currentShader]);
    cube.position.set(-3, 1, 0);
    cube.castShadow = true;
    cube.receiveShadow = true;
    scene.add(cube);
    objects.push(cube);

    // Create a sphere
    const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
    const sphere = new THREE.Mesh(sphereGeometry, shaderMaterials[currentShader]);
    sphere.position.set(0, 1, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);
    objects.push(sphere);

    // Create a torus
    const torusGeometry = new THREE.TorusGeometry(1, 0.4, 16, 100);
    const torus = new THREE.Mesh(torusGeometry, shaderMaterials[currentShader]);
    torus.position.set(3, 1, 0);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);
    objects.push(torus);
}

// Create a custom shader material
function createCustomShaderMaterial() {
    const customShaderMaterial = new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            color: { value: new THREE.Color(0x336699) },
            lightPosition: { value: new THREE.Vector3(5, 10, 7) }
        },
        vertexShader: `
            uniform float time;
            varying vec3 vNormal;
            varying vec3 vPosition;

            void main() {
                vNormal = normalize(normalMatrix * normal);
                vPosition = position;

                // Simple wave effect
                vec3 newPosition = position + normal * sin(position.x * 5.0 + time) * 0.1;

                gl_Position = projectionMatrix * modelViewMatrix * vec4(newPosition, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 color;
            uniform vec3 lightPosition;
            varying vec3 vNormal;
            varying vec3 vPosition;

            void main() {
                // Simple lighting calculation
                vec3 lightDir = normalize(lightPosition - vPosition);
                float diffuse = max(dot(vNormal, lightDir), 0.0);

                // Combine color with lighting
                vec3 finalColor = color * (0.3 + diffuse * 0.7);

                gl_FragColor = vec4(finalColor, 1.0);
            }
        `,
        side: THREE.DoubleSide
    });

    shaderMaterials['custom'] = customShaderMaterial;
}

// Handle window resize
function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// Handle keyboard input
function onKeyDown(event) {
    switch (event.key.toLowerCase()) {
        case '1':
            changeLightingMode('standard');
            break;
        case '2':
            changeLightingMode('dim');
            break;
        case '3':
            changeLightingMode('night');
            break;
        case '4':
            changeShader('phong');
            break;
        case '5':
            changeShader('toon');
            break;
        case '6':
            changeShader('lambert');
            break;
        case '7':
            changeShader('custom');
            break;
        case 'h':
            showHelp();
            break;
    }
}

// Change lighting mode
function changeLightingMode(mode) {
    lightingMode = mode;
    document.getElementById('lightingMode').textContent = mode.charAt(0).toUpperCase() + mode.slice(1);

    switch (mode) {
        case 'standard':
            ambientLight.intensity = 0.5;
            directionalLight.intensity = 0.8;
            pointLight.intensity = 0.5;
            spotLight.intensity = 0.7;
            break;
        case 'dim':
            ambientLight.intensity = 0.2;
            directionalLight.intensity = 0.4;
            pointLight.intensity = 0.2;
            spotLight.intensity = 0.3;
            break;
        case 'night':
            ambientLight.intensity = 0.1;
            directionalLight.intensity = 0.2;
            pointLight.intensity = 0.1;
            spotLight.intensity = 0.1;
            break;
    }
}

// Change shader
function changeShader(shader) {
    currentShader = shader;
    document.getElementById('shaderMode').textContent = shader.charAt(0).toUpperCase() + shader.slice(1);

    objects.forEach(obj => {
        obj.material = shaderMaterials[shader];
    });
}

// Show help
function showHelp() {
    alert(`
3D Scene Viewer Controls:
- Lighting Modes:
  1: Standard lighting
  2: Dim lighting
  3: Night lighting
- Shader Types:
  4: Phong shader
  5: Toon shader
  6: Lambert shader
  7: Custom shader (with wave effect)
- H: Show this help
    `);
}

// Animation loop
function animate() {
    requestAnimationLoop(animate);

    const delta = clock.getDelta();
    const time = clock.getElapsedTime();

    // Update controls
    controls.update();

    // Update custom shader time uniform
    if (shaderMaterials['custom']) {
        shaderMaterials['custom'].uniforms.time.value = time;
    }

    // Animate objects
    objects.forEach((obj, index) => {
        obj.rotation.y += delta * (index + 1) * 0.5;
    });

    // Animate lights
    pointLight.position.x = Math.sin(time) * 3;
    pointLight.position.z = Math.cos(time) * 3;

    // Render scene
    renderer.render(scene, camera);

