const torusMaterial = new THREE.MeshStandardMaterial({
    color: 0x0000ff,
    roughness: 0.4,
    metalness: 0.6
});
const torus = new THREE.Mesh(torusGeometry, torusMaterial);
torus.position.set(0, 0.5, 2);
torus.castShadow = true;
torus.receiveShadow = true;
scene.add(torus);
objects.push(torus);

// Shader materials
const shaderMaterials = {
    standard: new THREE.MeshStandardMaterial({
        color: 0xffffff,
        roughness: 0.5,
        metalness: 0.5
    }),

    toon: new THREE.MeshToonMaterial({
        color: 0xffffff,
        gradientMap: createGradientTexture()
    }),

    water: new THREE.MeshPhongMaterial({
        color: 0x4488ff,
        specular: 0x111111,
        shininess: 30,
        transparent: true,
        opacity: 0.8,
        refractionRatio: 0.98
    }),

    fire: new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            resolution: { value: new THREE.Vector2() }
        },
        vertexShader: `
            varying vec2 vUv;
            void main() {
                vUv = uv;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform float time;
            varying vec2 vUv;

            void main() {
                vec2 uv = vUv;
                uv.x += sin(uv.y * 10.0 + time * 2.0) * 0.1;
                uv.y += cos(uv.x * 10.0 + time * 3.0) * 0.1;

                float r = sin(uv.x * 10.0 + time) * 0.5 + 0.5;
                float g = sin(uv.y * 10.0 + time * 1.5) * 0.5 + 0.5;
                float b = sin((uv.x + uv.y) * 10.0 + time * 2.0) * 0.5 + 0.5;

                gl_FragColor = vec4(r, g, b, 1.0);
            }
        `
    })
};

// Helper function to create gradient texture for toon shader
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 1;
    const context = canvas.getContext('2d');

    const gradient = context.createLinearGradient(0, 0, 256, 0);
    gradient.addColorStop(0.0, '#000000');
    gradient.addColorStop(0.5, '#ffffff');
    gradient.addColorStop(1.0, '#ffffff');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 1);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.NearestFilter;
    texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    return texture;
}

// UI Controls
