    const shaderType = e.target.value;
    objects.forEach(obj => {
        if (shaderType === 'fire') {
            obj.material = shaderMaterials[shaderType].clone();
        } else {
            obj.material = shaderMaterials[shaderType];
        }
    });
});

// Animation loop
