                    if (gl_FragColor.a < 0.5) discard;

                    // Toon shading
                    float intensity = dot(normalize(vNormal), normalize(vec3(1.0, 1.0, 1.0)));
                    if (intensity > 0.95) gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
                    else if (intensity > 0.5) gl_FragColor = vec4(0.6, 0.6, 0.6, 1.0);
                    else if (intensity > 0.25) gl_FragColor = vec4(0.4, 0.4, 0.4, 1.0);
                    else gl_FragColor = vec4(0.2, 0.2, 0.2, 1.0);
