controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
scene.add(directionalLight);

// Helper to visualize light direction
const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
scene.add(lightHelper);

// Ground plane
const groundGeometry = new THREE.PlaneGeometry(20, 20);
const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333,
    roughness: 0.8,
    metalness: 0.2
});
const ground = new THREE.Mesh(groundGeometry, groundMaterial);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Add some objects to the scene
function createObjects() {
    // Sphere
    const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({
        color: 0xff5555,
        roughness: 0.3,
        metalness: 0.5
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(-3, 1.5, 0);
    sphere.castShadow = true;
    scene.add(sphere);

    // Box
    const boxGeometry = new THREE.BoxGeometry(2, 2, 2);
    const boxMaterial = new THREE.MeshStandardMaterial({
        color: 0x5555ff,
        roughness: 0.4,
        metalness: 0.3
    });
    const box = new THREE.Mesh(boxGeometry, boxMaterial);
    box.position.set(3, 1, 0);
    box.castShadow = true;
    scene.add(box);

    // Torus
    const torusGeometry = new THREE.TorusGeometry(1.5, 0.5, 16, 32);
    const torusMaterial = new THREE.MeshStandardMaterial({
        color: 0x55ff55,
        roughness: 0.2,
        metalness: 0.7
    });
    const torus = new THREE.Mesh(torusGeometry, torusMaterial);
    torus.position.set(0, 1.5, -3);
    torus.castShadow = true;
    scene.add(torus);
}

createObjects();

// Shader effects
const shaderEffects = {
    none: {
        apply: (material) => {
            // Reset to standard material
            material.needsUpdate = true;
        }
    },
    toon: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.fragmentShader = shader.fragmentShader.replace(
                    '#include <dithering_fragment>',
                    `
                    #include <dithering_fragment>
                    if (gl_FragColor.a < 0.5) discard;
                    float intensity = dot(normalize(vNormal), normalize(vec3(1.0, 1.0, 1.0)));
                    if (intensity > 0.95) gl_FragColor.rgb = vec3(1.0, 0.8, 0.8);
                    else if (intensity > 0.75) gl_FragColor.rgb = vec3(0.8, 0.6, 0.6);
                    else if (intensity > 0.5) gl_FragColor.rgb = vec3(0.6, 0.4, 0.4);
                    else gl_FragColor.rgb = vec3(0.4, 0.2, 0.2);
                    `
                );
            };
            material.needsUpdate = true;
        }
    },
    water: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.uniforms.time = { value: 0 };
                shader.fragmentShader = shader.fragmentShader.replace(
                    'void main() {',
                    `
                    uniform float time;
                    void main() {
                        vec2 uv = vUv;
                        uv.x += sin(uv.y * 10.0 + time * 2.0) * 0.1;
                        uv.y += cos(uv.x * 10.0 + time * 3.0) * 0.1;
                    `
                );
            };
            material.needsUpdate = true;
        }
    },
    glow: {
        apply: (material) => {
            material.onBeforeCompile = (shader) => {
                shader.fragmentShader = shader.fragmentShader.replace(
                    '#include <dithering_fragment>',
                    `
                    #include <dithering_fragment>
                    vec3 glowColor = vec3(0.5, 0.8, 1.0);
                    float glowIntensity = 0.5;
                    vec3 viewDir = normalize(-vViewPosition);
                    float rim = 1.0 - max(dot(vNormal, viewDir), 0.0);
                    gl_FragColor.rgb += glowColor * pow(rim, 2.0) * glowIntensity;
                    `
                );
            };
            material.needsUpdate = true;
        }
    }
};

// Apply shader effect to all materials
function applyShaderEffect(effectName) {
    scene.traverse((object) => {
        if (object.isMesh) {
            const effect = shaderEffects[effectName || 'none'];
            effect.apply(object.material);
        }
    });
}

// UI Controls
document.getElementById('lightIntensity').addEventListener('input', (e) => {
    directionalLight.intensity = parseFloat(e.target.value);
});

document.getElementById('shaderEffect').addEventListener('change', (e) => {
    applyShaderEffect(e.target.value);
});

// Animation loop
let time = 0;
function animate() {
    requestAnimationFrame(animate);

    time += 0.01;

    // Update shader effects that need time
    scene.traverse((object) => {
        if (object.isMesh && object.material.uniforms && object.material.uniforms.time) {
            object.material.uniforms.time.value = time;
        }
    });

    controls.update();
    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start animation
animate();
