```javascript
// Main scene setup
let scene, camera, renderer, controls;
let clock = new THREE.Clock();
let mixer;
let lightHelpers = [];
let currentLightingMode = 'phong';
let currentShaderMode = 'standard';

// Initialize the scene
function init() {
    // Create scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);

    // Create camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 2, 5);

    // Create renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    document.body.appendChild(renderer.domElement);

    // Add orbit controls
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Add lights
    setupLights();

    // Add ground plane
    addGround();

    // Add sample objects
    addSampleObjects();

    // Handle window resize
    window.addEventListener('resize', onWindowResize);

    // Start animation loop
    animate();
}

// Setup lighting
function setupLights() {
    // Ambient light
    const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    scene.add(ambientLight);

    // Directional light (sun)
    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(5, 10, 7);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    directionalLight.shadow.camera.near = 0.5;
    directionalLight.shadow.camera.far = 50;
    scene.add(directionalLight);

    // Add light helper
    const directionalLightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
    scene.add(directionalLightHelper);
    lightHelpers.push(directionalLightHelper);

    // Point light
    const pointLight = new THREE.PointLight(0xff0000, 1, 10);
    pointLight.position.set(2, 2, 2);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Add light helper
    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
    scene.add(pointLightHelper);
    lightHelpers.push(pointLightHelper);

    // Spot light
    const spotLight = new THREE.SpotLight(0x00ff00, 1, 10, Math.PI / 6, 0.5, 1);
    spotLight.position.set(-2, 3, -2);
    spotLight.castShadow = true;
    scene.add(spotLight);

    // Add light helper
    const spotLightHelper = new THREE.SpotLightHelper(spotLight);
    scene.add(spotLightHelper);
    lightHelpers.push(spotLightHelper);
}

// Add ground plane
function addGround() {
    const groundGeometry = new THREE.PlaneGeometry(20, 20);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x333333,
        roughness: 0.8,
        metalness: 0.2
    });
    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Add grid helper
    const gridHelper = new THREE.GridHelper(20, 20, 0x444444, 0x444444);
    scene.add(gridHelper);
}

// Add sample objects
function addSampleObjects() {
    // Create a cube
    const cubeGeometry = new THREE.BoxGeometry(1, 1, 1);
    const cubeMaterial = new THREE.MeshStandardMaterial({
        color: 0x00ff00,
        roughness: 0.5,
        metalness: 0.5
    });
    const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
    cube.position.set(-2, 0.5, 0);
    cube.castShadow = true;
    cube.receiveShadow = true;
    scene.add(cube);

    // Create a sphere
    const sphereGeometry = new THREE.SphereGeometry(0.5, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({
        color: 0x0000ff,
        roughness: 0.3,
        metalness: 0.7
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(2, 0.5, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Create a torus knot
    const torusKnotGeometry = new THREE.TorusKnotGeometry(0.5, 0.2, 100, 16);
    const torusKnotMaterial = new THREE.MeshStandardMaterial({
        color: 0xff00ff,
        roughness: 0.2,
        metalness: 0.8
    });
    const torusKnot = new THREE.Mesh(torusKnotGeometry, torusKnotMaterial);
    torusKnot.position.set(0, 0.5, 2);
    torusKnot.castShadow = true;
    torusKnot.receiveShadow = true;
    scene.add(torusKnot);

    // Add animated object (teapot)
    const loader = new THREE.GLTFLoader();
    loader.load(
        'https://threejs.org/examples/models/gltf/WaterBottle/glTF/WaterBottle.gltf',
        function (gltf) {
            const model = gltf.scene;
            model.position.set(0, 0.5, -2);
            model.scale.set(0.5, 0.5, 0.5);
            model.traverse(function (child) {
                if (child.isMesh) {
                    child.castShadow = true;
                    child.receiveShadow = true;
                }
            });
            scene.add(model);

            // Set up animation if available
            if (gltf.animations && gltf.animations.length) {
                mixer = new THREE.AnimationMixer(model);
                const action = mixer.clipAction(gltf.animations[0]);
                action.play();
            }
        },
        undefined,
        function (error) {
            console.error('Error loading model:', error);
        }
    );
}

// Handle window resize
function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();

    // Update animation mixer if it exists
    if (mixer) {
        mixer.update(delta);
    }

    // Update controls
    controls.update();

    // Render scene
    renderer.render(scene, camera);
}

// Initialize the scene when the page loads
window.addEventListener('DOMContentLoaded', init);

// Add keyboard controls
document.addEventListener('keydown', function(event) {
    switch(event.key.toLowerCase()) {
        case 'h':
            alert('Controls:\n\n' +
                  'WASD - Move camera\n' +
                  'Mouse - Rotate/zoom camera\n' +
                  'L - Toggle lighting mode\n' +
                  'S - Toggle shader mode\n' +
                  'H - Show this help');
            break;
        case 'l':
            toggleLightingMode();
            break;
        case 's':
            toggleShaderMode();
            break;
    }
});

function toggleLightingMode() {
    const modes = ['phong', 'lambert', 'basic'];
    const currentIndex = modes.indexOf(currentLightingMode);
    const nextIndex = (currentIndex + 1) % modes.length;
    currentLightingMode = modes[nextIndex];

    // Update all materials in the scene
    scene.traverse(function(object) {
        if (object.isMesh) {
            let newMaterial;
            switch(currentLightingMode) {
                case 'phong':
                    newMaterial = new THREE.MeshPhongMaterial({
                        color: object.material.color,
                        specular: 0x111111,
                        shininess: 30
                    });
                    break;
                case 'lambert':
                    newMaterial = new THREE.MeshLambertMaterial({
                        color: object.material.color
                    });
                    break;
                case 'basic':
                    newMaterial = new THREE.MeshBasicMaterial({
                        color: object.material.color
                    });
                    break;
            }

            // Copy shadow properties
            newMaterial.castShadow = object.material.castShadow;
            newMaterial.receiveShadow = object.material.receiveShadow;

            object.material.dispose();
            object.material = newMaterial;
        }
    });

    document.getElementById('lightingMode').textContent = currentLightingMode.charAt(0).toUpperCase() + currentLightingMode.slice(1);
}

function toggleShaderMode() {
    const modes = ['standard', 'toon', 'wireframe'];
    const currentIndex = modes.indexOf(currentShaderMode);
    const nextIndex = (currentIndex + 1) % modes.length;
    currentShaderMode = modes[nextIndex];

    // Update all materials in the scene
    scene.traverse(function(object) {
        if (object.isMesh) {
            let newMaterial;
            const originalColor = object.material.color;

            switch(currentShaderMode) {
                case 'standard':
                    newMaterial = new THREE.MeshStandardMaterial({
                        color: originalColor,
                        roughness: 0.5,
                        metalness: 0.5
                    });
                    break;
                case 'toon':
                    newMaterial = new THREE.MeshToonMaterial({
                        color: originalColor,
                        gradientMap: createGradientTexture()
                    });
                    break;
                case 'wireframe':
                    newMaterial = new THREE.MeshBasicMaterial({
                        color: originalColor,
                        wireframe: true
                    });
                    break;
            }

            // Copy shadow properties
            newMaterial.castShadow = object.material.castShadow;
            newMaterial.receiveShadow = object.material.receiveShadow;

            object.material.dispose();
            object.material = newMaterial;
        }
    });

    document.getElementById('shaderMode').textContent = currentShaderMode.charAt(0).toUpperCase() + currentShaderMode.slice(1);
}

// Helper function to create gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 1;
    const context = canvas.getContext('2d');

    const gradient = context.createLinearGradient(0, 0, 256, 0);
    gradient.addColorStop(0.0, 'rgba(0, 0, 0, 1.0)');
    gradient.addColorStop(0.5, 'rgba(128, 128, 128, 1.0)');
    gradient.addColorStop(1.0, 'rgba(255, 255, 255, 1.0)');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 1);

    const texture = new THREE.CanvasTexture(canvas);
    texture.generateMipmaps = false;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;

    return texture;
}
