    // Remove previous shader if any
    if (currentShader) {
        objects.forEach(obj => {
            obj.material = obj.originalMaterial;
        });
    }

    currentShader = shaderEffects[effect];

    if (currentShader) {
        objects.forEach(obj => {
            obj.originalMaterial = obj.material;
            obj.material = currentShader;
        });
    }
}

// Shader effect implementations
function createToonShader() {
    return new THREE.MeshToonMaterial({
        color: 0xffffff,
        gradientMap: createGradientTexture()
    });
}

function createWaterShader() {
    const waterMaterial = new THREE.MeshPhongMaterial({
        color: 0x00aaff,
        specular: 0x111111,
        shininess: 30,
        transparent: true,
        opacity: 0.8,
        reflectivity: 0.5
    });

    // Add some animation to simulate water
    waterMaterial.onBeforeCompile = function(shader) {
        shader.uniforms.time = { value: 0 };
        shader.vertexShader = `
            uniform float time;
            ${shader.vertexShader}
        `.replace(
            '#include <begin_vertex>',
            `
            #include <begin_vertex>
            transformed.y += sin(position.x * 2.0 + time) * 0.1;
            transformed.y += cos(position.z * 2.0 + time) * 0.1;
            `
        );

        waterMaterial.userData.shader = shader;
    };

    return waterMaterial;
}

function createFireShader() {
    const fireMaterial = new THREE.MeshStandardMaterial({
        color: 0xff4400,
        emissive: 0xff4400,
        emissiveIntensity: 1.0,
        roughness: 0.7,
        metalness: 0.3,
        transparent: true,
        opacity: 0.9
    });

    // Add animation to simulate fire
    fireMaterial.onBeforeCompile = function(shader) {
        shader.uniforms.time = { value: 0 };
        shader.uniforms.seed = { value: Math.random() * 1000 };

        shader.vertexShader = `
            uniform float time;
            uniform float seed;
            ${shader.vertexShader}
        `.replace(
            '#include <begin_vertex>',
            `
            #include <begin_vertex>
            float noise = sin(position.x * 10.0 + time * 2.0 + seed) *
                          cos(position.y * 5.0 + time * 3.0 + seed) *
                          sin(position.z * 7.0 + time * 4.0 + seed);
            transformed.x += noise * 0.1;
            transformed.y += abs(noise) * 0.2;
            transformed.z += noise * 0.1;
            `
        );

        fireMaterial.userData.shader = shader;
    };

    return fireMaterial;
}

// Helper function to create gradient texture for toon shading
function createGradientTexture() {
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 1;
    const context = canvas.getContext('2d');

    const gradient = context.createLinearGradient(0, 0, 256, 0);
    gradient.addColorStop(0.0, 'rgba(0,0,0,1)');
    gradient.addColorStop(0.5, 'rgba(128,128,128,1)');
    gradient.addColorStop(1.0, 'rgba(255,255,255,1)');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 256, 1);

    const texture = new THREE.CanvasTexture(canvas);
    texture.minFilter = THREE.NearestFilter;
    texture.magFilter = THREE.NearestFilter;
    texture.generateMipmaps = false;

    return texture;
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update shader animations if any
    if (currentShader && currentShader.userData && currentShader.userData.shader) {
        currentShader.userData.shader.uniforms.time.value += 0.01;
    }

