const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
cube.position.set(-3, 1, 0);
cube.castShadow = true;
scene.add(cube);
objects.push(cube);

// Create a sphere
const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
const sphereMaterial = new THREE.MeshStandardMaterial({
    color: 0xff0000,
    roughness: 0.3,
    metalness: 0.7
});
const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
sphere.position.set(3, 1, 0);
sphere.castShadow = true;
scene.add(sphere);
objects.push(sphere);

// Create a torus
const torusGeometry = new THREE.TorusGeometry(1, 0.4, 16, 100);
const torusMaterial = new THREE.MeshStandardMaterial({
    color: 0x0000ff,
    roughness: 0.2,
    metalness: 0.8
});
const torus = new THREE.Mesh(torusGeometry, torusMaterial);
torus.position.set(0, 1, 3);
torus.castShadow = true;
scene.add(torus);
objects.push(torus);

// Shader materials
const shaderMaterials = [
    // Basic shader
    new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            color: { value: new THREE.Color(0x00ff00) }
        },
        vertexShader: `
            uniform float time;
            varying vec2 vUv;
            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.y += sin(pos.x * 2.0 + time) * 0.2;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 color;
            varying vec2 vUv;
            void main() {
                gl_FragColor = vec4(color, 1.0);
            }
        `
    }),

    // Toon shader
    new THREE.ShaderMaterial({
        uniforms: {
            uDirLightPos: { value: new THREE.Vector3(5, 10, 7) },
            uDirLightColor: { value: new THREE.Color(0xffffff) },
            uAmbientLightColor: { value: new THREE.Color(0x404040) }
        },
        vertexShader: `
            varying vec3 vNormal;
            varying vec3 vPosition;
            void main() {
                vNormal = normalize(normalMatrix * normal);
                vPosition = (modelViewMatrix * vec4(position, 1.0)).xyz;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 uDirLightPos;
            uniform vec3 uDirLightColor;
            uniform vec3 uAmbientLightColor;
            varying vec3 vNormal;
            varying vec3 vPosition;

            void main() {
                vec3 normal = normalize(vNormal);
                vec3 lightDir = normalize(uDirLightPos - vPosition);

                // Diffuse lighting
                float diff = max(dot(normal, lightDir), 0.0);
                diff = smoothstep(0.0, 1.0, diff);

                // Ambient lighting
                vec3 ambient = uAmbientLightColor;

                // Combine lighting
                vec3 color = ambient + diff * uDirLightColor;

                gl_FragColor = vec4(color, 1.0);
            }
        `
    }),

    // Water shader
    new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            color: { value: new THREE.Color(0x00aaff) }
        },
        vertexShader: `
            uniform float time;
            varying vec2 vUv;
            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.y += sin(pos.x * 5.0 + time * 2.0) * 0.1;
                pos.y += cos(pos.z * 5.0 + time * 2.0) * 0.1;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 color;
            varying vec2 vUv;
            void main() {
                vec3 c = color;
                c.r += sin(vUv.x * 10.0) * 0.1;
                c.g += cos(vUv.y * 10.0) * 0.1;
                gl_FragColor = vec4(c, 0.8);
            }
        `
    })
];

let currentShaderIndex = 0;

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update time for shaders
    const time = performance.now() * 0.001;

    // Update shader uniforms
    shaderMaterials.forEach(material => {
        if (material.uniforms.time) {
            material.uniforms.time.value = time;
        }
    });

    // Rotate objects
    objects.forEach(obj => {
        obj.rotation.x += 0.005;
        obj.rotation.y += 0.005;
    });

    // Update point light position
    pointLight.position.x = Math.sin(time) * 5;
    pointLight.position.z = Math.cos(time) * 5;

    controls.update();
    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// UI controls
document.getElementById('toggleLight').addEventListener('click', () => {
    pointLight.visible = !pointLight.visible;
});

document.getElementById('changeShader').addEventListener('click', () => {
    currentShaderIndex = (currentShaderIndex + 1) % shaderMaterials.length;
    objects.forEach(obj => {
        obj.material = shaderMaterials[currentShaderIndex];
    });
});

// Initialize
animate();
