// Main scene setup
let scene, camera, renderer, controls;
let ambientLight, directionalLight, pointLight;
let clock = new THREE.Clock();

// Initialize the scene
function init() {
    // Create scene
    scene = new THREE.Scene();
    scene.background = new THREE.Color(0x222222);

    // Create camera
    camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    camera.position.set(0, 2, 5);

    // Create renderer
    renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.shadowMap.enabled = true;
    document.body.appendChild(renderer.domElement);

    // Add orbit controls
    controls = new THREE.OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Add lights
    setupLights();

    // Add ground plane
    addGround();

    // Add some sample objects
    addSampleObjects();

    // Add event listeners
    window.addEventListener('resize', onWindowResize);
    document.addEventListener('keydown', onKeyDown);

    // Start animation loop
    animate();
}

// Set up lighting system
function setupLights() {
    // Ambient light
    ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    scene.add(ambientLight);

    // Directional light (sun)
    directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(5, 10, 7);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    scene.add(directionalLight);

    // Point light (like a lamp)
    pointLight = new THREE.PointLight(0xffaa00, 1, 20);
    pointLight.position.set(0, 3, 0);
    pointLight.castShadow = true;
    scene.add(pointLight);

    // Helper for point light
    const pointLightHelper = new THREE.PointLightHelper(pointLight, 0.5);
    scene.add(pointLightHelper);
}

// Add ground plane
function addGround() {
    const groundGeometry = new THREE.PlaneGeometry(20, 20);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x333333,
        roughness: 0.8,
        metalness: 0.2
    });

    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);
}

// Add sample objects
function addSampleObjects() {
    // Create a cube with custom shader
    const cubeGeometry = new THREE.BoxGeometry(1, 1, 1);
    const cubeMaterial = new THREE.ShaderMaterial({
        uniforms: {
            time: { value: 0 },
            color: { value: new THREE.Color(0x00ff00) }
        },
        vertexShader: `
            uniform float time;
            varying vec2 vUv;
            void main() {
                vUv = uv;
                vec3 pos = position;
                pos.y += sin(pos.x * 2.0 + time) * 0.2;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
            }
        `,
        fragmentShader: `
            uniform vec3 color;
            varying vec2 vUv;
            void main() {
                gl_FragColor = vec4(color * (0.5 + 0.5 * sin(vUv.x * 10.0)), 1.0);
            }
        `
    });

    const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
    cube.position.set(-2, 0.5, 0);
    cube.castShadow = true;
    scene.add(cube);

    // Create a sphere with environment mapping
    const sphereGeometry = new THREE.SphereGeometry(0.8, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({
        color: 0x00aaff,
        roughness: 0.2,
        metalness: 0.8,
        envMapIntensity: 1.0
    });

    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(2, 0.8, 0);
    sphere.castShadow = true;
    scene.add(sphere);

    // Add a torus knot
    const torusGeometry = new THREE.TorusKnotGeometry(0.5, 0.2, 100, 16);
    const torusMaterial = new THREE.MeshPhongMaterial({
        color: 0xff00aa,
        specular: 0x111111,
        shininess: 30
    });

    const torus = new THREE.Mesh(torusGeometry, torusMaterial);
    torus.position.set(0, 1, 0);
    torus.castShadow = true;
    scene.add(torus);
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update shader uniforms
    const time = clock.getElapsedTime();
    scene.traverse((object) => {
        if (object.material && object.material.uniforms && object.material.uniforms.time) {
            object.material.uniforms.time.value = time;
        }
    });

    // Rotate point light
    pointLight.position.x = Math.sin(time) * 3;
    pointLight.position.z = Math.cos(time) * 3;

    // Render scene
    renderer.render(scene, camera);
}

// Handle window resize
function onWindowResize() {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
}

// Handle keyboard input
function onKeyDown(event) {
    switch (event.code) {
        case 'KeyH':
            alert('Controls:\n\n' +
                  'WASD - Move camera\n' +
                  'Mouse - Rotate/zoom camera\n' +
                  'Buttons - Toggle lights');
            break;
        case 'KeyA':
            ambientLight.visible = !ambientLight.visible;
            break;
        case 'KeyD':
            directionalLight.visible = !directionalLight.visible;
            break;
        case 'KeyP':
            pointLight.visible = !pointLight.visible;
            break;
    }
}

// Initialize the scene when the page loads
window.onload = init;
