    const canvas = document.createElement('canvas');
    canvas.width = 16;
    canvas.height = 256;

    const context = canvas.getContext('2d');
    const gradient = context.createLinearGradient(0, 0, 0, 256);

    gradient.addColorStop(0.0, 'rgba(0, 0, 0, 1.0)');
    gradient.addColorStop(0.2, 'rgba(0.5, 0.5, 0.5, 1.0)');
    gradient.addColorStop(0.5, 'rgba(1.0, 1.0, 1.0, 1.0)');
    gradient.addColorStop(0.8, 'rgba(0.5, 0.5, 0.5, 1.0)');
    gradient.addColorStop(1.0, 'rgba(0, 0, 0, 1.0)');

    context.fillStyle = gradient;
    context.fillRect(0, 0, 16, 256);

    const texture = new THREE.CanvasTexture(canvas);
    texture.needsUpdate = true;

