    box.position.set(i * 2 - 2, 0.5, 2);
    box.castShadow = true;
    box.receiveShadow = true;
    scene.add(box);
}

// Animation loop
function animate() {
    requestAnimationFrame(animate);

    // Update controls
    controls.update();

    // Update shader uniforms
    customMaterial.uniforms.time.value += 0.01;
    customMaterial.uniforms.lightPosition.value.copy(directionalLight.position);

    // Rotate the shader mesh
    shaderMesh.rotation.y += 0.005;

    // Animate point light
    pointLight.position.x = Math.sin(Date.now() * 0.001) * 3;
    pointLight.position.z = Math.cos(Date.now() * 0.001) * 3;

    renderer.render(scene, camera);
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Toggle lights with 'L' key
let lightsVisible = true;
window.addEventListener('keydown', (e) => {
    if (e.key.toLowerCase() === 'l') {
        lightsVisible = !lightsVisible;
        lightHelpers.forEach(helper => helper.visible = lightsVisible);
    }
});

// Start animation
animate();
