// Scene setup
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x222222);

// Camera setup
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.set(0, 5, 10);

// Renderer setup
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.getElementById('scene-container').appendChild(renderer.domElement);

// Controls
const controls = new THREE.OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;

// Lighting
const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
directionalLight.position.set(5, 10, 7);
directionalLight.castShadow = true;
directionalLight.shadow.mapSize.width = 1024;
directionalLight.shadow.mapSize.height = 1024;
scene.add(directionalLight);

// Light helper
const lightHelper = new THREE.DirectionalLightHelper(directionalLight, 1);
scene.add(lightHelper);

// Post-processing setup
const composer = new THREE.EffectComposer(renderer);
const renderPass = new THREE.RenderPass(scene, camera);
composer.addPass(renderPass);

// Shader effects
let currentShaderPass = null;

// Create scene objects
function createScene() {
    // Ground
    const groundGeometry = new THREE.PlaneGeometry(20, 20);
    const groundMaterial = new THREE.MeshStandardMaterial({
        color: 0x3a5f0b,
        roughness: 0.8,
        metalness: 0.2
    });
    const ground = new THREE.Mesh(groundGeometry, groundMaterial);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = true;
    scene.add(ground);

    // Boxes
    const boxGeometry = new THREE.BoxGeometry(1, 1, 1);
    const boxMaterial = new THREE.MeshStandardMaterial({
        color: 0x3366ff,
        roughness: 0.3,
        metalness: 0.5
    });

    for (let i = 0; i < 5; i++) {
        const box = new THREE.Mesh(boxGeometry, boxMaterial);
        box.position.set(
            Math.random() * 8 - 4,
            0.5,
            Math.random() * 8 - 4
        );
        box.castShadow = true;
        box.receiveShadow = true;
        scene.add(box);
    }

    // Sphere
    const sphereGeometry = new THREE.SphereGeometry(1, 32, 32);
    const sphereMaterial = new THREE.MeshStandardMaterial({
        color: 0xff3366,
        roughness: 0.1,
        metalness: 0.8
    });
    const sphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
    sphere.position.set(3, 1, 0);
    sphere.castShadow = true;
    sphere.receiveShadow = true;
    scene.add(sphere);

    // Torus
    const torusGeometry = new THREE.TorusGeometry(1, 0.4, 16, 32);
    const torusMaterial = new THREE.MeshStandardMaterial({
        color: 0xffff33,
        roughness: 0.5,
        metalness: 0.3
    });
    const torus = new THREE.Mesh(torusGeometry, torusMaterial);
    torus.position.set(-3, 1, 0);
    torus.castShadow = true;
    torus.receiveShadow = true;
    scene.add(torus);
}

// Shader effect functions
function applyToonShader() {
    removeCurrentShader();

    const toonPass = new THREE.ShaderPass(THREE.ToonShader);
    toonPass.uniforms['uDirLightPos'].value = directionalLight.position;
    toonPass.uniforms['uDirLightColor'].value = directionalLight.color;
    toonPass.uniforms['uAmbientLightColor'].value = ambientLight.color;
    toonPass.uniforms['uBaseColor'].value = new THREE.Color(0xffffff);

    composer.addPass(toonPass);
    currentShaderPass = toonPass;
}

function applyWaterShader() {
    removeCurrentShader();

    const waterPass = new THREE.ShaderPass(THREE.WaterShader);
    waterPass.uniforms['time'].value = 0;
    waterPass.uniforms['distortionScale'].value = 3.7;

    composer.addPass(waterPass);
    currentShaderPass = waterPass;
}

function applyHeatHazeShader() {
    removeCurrentShader();

    const heatHazePass = new THREE.ShaderPass({
        uniforms: {
            tDiffuse: { value: null },
            time: { value: 0 },
            intensity: { value: 0.3 }
        },
        vertexShader: `
            varying vec2 vUv;
            void main() {
                vUv = uv;
                gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
            }
        `,
        fragmentShader: `
            uniform sampler2D tDiffuse;
            uniform float time;
            uniform float intensity;
            varying vec2 vUv;

            void main() {
                vec4 color = texture2D(tDiffuse, vUv);
                float noise = fract(sin(dot(vUv + time, vec2(12.9898, 78.233))) * 43758.5453);
                color.rgb += noise * intensity;
                gl_FragColor = color;
            }
        `
    });

    composer.addPass(heatHazePass);
    currentShaderPass = heatHazePass;
}

function removeCurrentShader() {
    if (currentShaderPass) {
        composer.removePass(currentShaderPass);
        currentShaderPass = null;
    }
}

// UI Controls
document.getElementById('light-intensity').addEventListener('input', (e) => {
    const intensity = parseFloat(e.target.value);
    directionalLight.intensity = intensity;
    ambientLight.intensity = intensity * 0.5;
});

document.getElementById('shader-effect').addEventListener('change', (e) => {
    const effect = e.target.value;

    switch (effect) {
        case 'toon':
            applyToonShader();
            break;
        case 'water':
            applyWaterShader();
            break;
        case 'heat':
            applyHeatHazeShader();
            break;
        default:
            removeCurrentShader();
    }
});

document.getElementById('light-color').addEventListener('input', (e) => {
    const color = new THREE.Color(e.target.value);
    directionalLight.color.set(color);
    lightHelper.update();
});

// Animation loop
let time = 0;
function animate() {
    requestAnimationFrame(animate);

    time += 0.01;

    // Update shader uniforms if they exist
    if (currentShaderPass) {
        if (currentShaderPass.uniforms.time) {
            currentShaderPass.uniforms.time.value = time;
        }
    }

    controls.update();
    composer.render();
}

// Handle window resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
    composer.setSize(window.innerWidth, window.innerHeight);
});

// Initialize
createScene();
animate();
