            float diffuse = max(dot(vNormal, lightDir), 0.0);

            // Color with time-based animation
            vec3 color = vec3(
                0.5 + 0.5 * sin(time + vPosition.x),
                0.5 + 0.5 * sin(time + vPosition.y),
                0.5 + 0.5 * sin(time + vPosition.z)
            );

            // Combine lighting with color
            gl_FragColor = vec4(color * (0.2 + 0.8 * diffuse), 1.0);
        }
    `,
    side: THREE.DoubleSide
});

