```cpp
// CustomPhysicsPlugin.cpp
#include "CustomPhysicsPlugin.h"
#include "Physics/PhysicsWorld.h"
#include "Physics/RigidBody.h"
#include "Physics/CollisionShape.h"

void CustomPhysicsPlugin::Initialize()
{
    // Initialize physics system
    CreatePhysicsWorld();

    // Register with engine systems
    Engine::GetInstance().RegisterPlugin(this);
}

void CustomPhysicsPlugin::Shutdown()
{
    // Clean up all physics objects
    for (auto body : m_RigidBodies)
    {
        DestroyRigidBody(body);
    }
    m_RigidBodies.clear();

    for (auto shape : m_CollisionShapes)
    {
        DestroyCollisionShape(shape);
    }
    m_CollisionShapes.clear();

    DestroyPhysicsWorld();

    // Unregister from engine systems
    Engine::GetInstance().UnregisterPlugin(this);
}

void CustomPhysicsPlugin::Update(float deltaTime)
{
    if (m_PhysicsWorld)
    {
        m_PhysicsWorld->StepSimulation(deltaTime);
    }
}

void CustomPhysicsPlugin::CreatePhysicsWorld()
{
    PhysicsWorldDesc worldDesc;
    worldDesc.gravity = Vector3(0.0f, -9.81f, 0.0f);
    worldDesc.solverIterations = 8;

    m_PhysicsWorld = new PhysicsWorld(worldDesc);
}

void CustomPhysicsPlugin::DestroyPhysicsWorld()
{
    if (m_PhysicsWorld)
    {
        delete m_PhysicsWorld;
        m_PhysicsWorld = nullptr;
    }
}

RigidBody* CustomPhysicsPlugin::CreateRigidBody(const RigidBodyDesc& desc)
{
    if (!m_PhysicsWorld) return nullptr;

    RigidBody* body = m_PhysicsWorld->CreateRigidBody(desc);
    m_RigidBodies.push_back(body);
    return body;
}

void CustomPhysicsPlugin::DestroyRigidBody(RigidBody* body)
{
    if (!m_PhysicsWorld || !body) return;

    auto it = std::find(m_RigidBodies.begin(), m_RigidBodies.end(), body);
    if (it != m_RigidBodies.end())
    {
        m_PhysicsWorld->DestroyRigidBody(body);
        m_RigidBodies.erase(it);
    }
}

CollisionShape* CustomPhysicsPlugin::CreateBoxShape(const Vector3& halfExtents)
{
    CollisionShape* shape = new BoxShape(halfExtents);
    m_CollisionShapes.push_back(shape);
    return shape;
}

CollisionShape* CustomPhysicsPlugin::CreateSphereShape(float radius)
{
    CollisionShape* shape = new SphereShape(radius);
    m_CollisionShapes.push_back(shape);
    return shape;
}

CollisionShape* CustomPhysicsPlugin::CreateCapsuleShape(float radius, float height)
{
    CollisionShape* shape = new CapsuleShape(radius, height);
    m_CollisionShapes.push_back(shape);
    return shape;
}

void CustomPhysicsPlugin::DestroyCollisionShape(CollisionShape* shape)
{
    auto it = std::find(m_CollisionShapes.begin(), m_CollisionShapes.end(), shape);
    if (it != m_CollisionShapes.end())
    {
        delete shape;
        m_CollisionShapes.erase(it);
    }
}
