// CustomPhysicsPlugin.h
#pragma once

#include "CoreMinimal.h"
#include "Modules/ModuleManager.h"

class FCustomPhysicsPluginModule : public IModuleInterface
{
public:
    /** IModuleInterface implementation */
    virtual void StartupModule() override;
    virtual void ShutdownModule() override;

    // Custom physics functions
    void ApplyCustomGravity(FVector& OutGravity, AActor* Actor);
    void CalculateCustomCollision(FHitResult& OutHit, const FVector& Start, const FVector& End, const FCollisionShape& CollisionShape);
    void SimulateCustomRigidBody(FBodyInstance* BodyInstance, float DeltaTime);
