    UE_LOG(LogTemp, Log, TEXT("Custom Physics Plugin unloaded"));
}

void FPhysicsPluginModule::ApplyCustomForce(FVector Force, float Duration)
{
    // Implementation for applying a custom force to physics objects
    for (auto& PhysicsObject : PhysicsObjects)
