## Physics Object Implementation

```cpp
// PhysicsObject.cpp
#include "PhysicsObject.h"

FPhysicsObject::FPhysicsObject(AActor* InOwner)
    : Owner(InOwner)
    , LinearVelocity(FVector::ZeroVector)
    , AngularVelocity(FVector::ZeroVector)
    , bIsRagdollEnabled(false)
    , Mass(1.0f)
    , CenterOfMass(FVector::ZeroVector)
{
    // Initialize physics properties from actor
    if (Owner)
    {
        UPrimitiveComponent* Primitive = Owner->FindComponentByClass<UPrimitiveComponent>();
        if (Primitive)
        {
            Mass = Primitive->GetMass();
            CenterOfMass = Primitive->GetCenterOfMass();
        }
    }
}

void FPhysicsObject::ApplyForce(FVector Force, float Duration)
{
    if (Owner && Owner->IsValidLowLevel())
    {
        // Simple physics integration (Euler integration)
        LinearVelocity += Force / Mass * Duration;

        // Apply to actor
        UPrimitiveComponent* Primitive = Owner->FindComponentByClass<UPrimitiveComponent>();
        if (Primitive)
        {
            Primitive->AddForce(Force);
        }
    }
}

void FPhysicsObject::SetGravity(FVector Gravity)
{
    // Apply gravity to this object
    ApplyForce(Gravity * Mass, 1.0f);
}

void FPhysicsObject::EnableRagdoll()
{
    if (Owner && !bIsRagdollEnabled)
    {
        // Enable ragdoll physics on the actor
        USkeletalMeshComponent* SkeletalMesh = Owner->FindComponentByClass<USkeletalMeshComponent>();
        if (SkeletalMesh)
        {
            SkeletalMesh->SetAllBodiesBelowSimulatePhysics(SkeletalMesh->GetBoneIndex("pelvis"), true, true);
            bIsRagdollEnabled = true;
        }
    }
}

void FPhysicsObject::DisableRagdoll()
{
    if (Owner && bIsRagdollEnabled)
    {
        // Disable ragdoll physics
        USkeletalMeshComponent* SkeletalMesh = Owner->FindComponentByClass<USkeletalMeshComponent>();
        if (SkeletalMesh)
        {
            SkeletalMesh->SetAllBodiesBelowSimulatePhysics(SkeletalMesh->GetBoneIndex("pelvis"), false, true);
            bIsRagdollEnabled = false;
        }
    }
}

bool FPhysicsObject::IsActive() const
{
    return Owner && Owner->IsValidLowLevel() && !Owner->IsPendingKill();
}
