    if (Actor && Actor->ActorHasTag("LowGravity"))
    {
        OutGravity = FVector(0.f, 0.f, -980.f); // Lower gravity
    }
    else
    {
        OutGravity = FVector(0.f, 0.f, -1960.f); // Standard gravity
