    BodyInstance->AddForce(CustomForce);

    // Update velocities
    LinearVelocity += CustomForce * DeltaTime / BodyInstance->GetBodyMass();
    BodyInstance->SetLinearVelocity(LinearVelocity, false);

    // Update position
    FVector NewPosition = BodyInstance->GetUnrealWorldTransform().GetLocation() + LinearVelocity * DeltaTime;
    BodyInstance->SetBodyTransform(FTransform(BodyInstance->GetUnrealWorldTransform().GetRotation(), NewPosition), ETeleportType::None);
}

