}

void FCustomPhysicsPluginModule::CalculateCustomCollision(FHitResult& OutHit, const FVector& Start, const FVector& End, const FCollisionQueryParams& Params)
{
    // Example: Custom collision detection with special materials
    FCollisionQueryParams CustomParams = Params;
    CustomParams.AddIgnoredActor(Params.GetWorld()->GetFirstPlayerController()->GetPawn());

    bool bHit = Params.GetWorld()->LineTraceSingleByChannel(
        OutHit,
        Start,
        End,
        ECC_Visibility,
        CustomParams
    );

    if (bHit && OutHit.GetActor() && OutHit.GetActor()->ActorHasTag("Bouncy"))
    {
        // Modify hit result for bouncy materials
        OutHit.Normal = -OutHit.Normal;
    }
}

void FCustomPhysicsPluginModule::SimulateCustomRigidBody(FBodyInstance* BodyInstance, float DeltaTime)
{
    if (!BodyInstance || !BodyInstance->IsValidBodyInstance())
        return;

    // Example: Custom rigid body simulation with additional forces
    FVector CustomForce = FVector::ZeroVector;

    // Apply vortex effect near certain objects
    for (TActorIterator<AActor> It(BodyInstance->GetWorld()); It; ++It)
    {
        AActor* Actor = *It;
        if (Actor && Actor->ActorHasTag("Vortex"))
        {
            FVector ToVortex = Actor->GetActorLocation() - BodyInstance->GetCOMPosition();
            float Distance = ToVortex.Size();

            if (Distance < 1000.f && Distance > 100.f)
            {
                CustomForce += ToVortex.GetSafeNormal() * (1000.f - Distance) * 5.f;
            }
        }
    }

    // Apply the custom force
    if (!CustomForce.IsNearlyZero())
    {
        BodyInstance->AddForce(CustomForce, true, true);
    }

    // Continue with standard simulation
    BodyInstance->UpdateBody(DeltaTime);
}
