// Example of how this would be used in a game engine component
public class PhysicsComponent : MonoBehaviour
{
    private IPhysicsWorld _physicsWorld;
    private IPhysicsObject _physicsBody;

    [SerializeField] private ColliderShapeType _shapeType;
    [SerializeField] private Vector3 _size = Vector3.one;
    [SerializeField] private float _mass = 1f;
    [SerializeField] private bool _isKinematic;

    private void Start()
    {
        // Get the physics world from the engine
        _physicsWorld = PhysicsEngine.GetPhysicsWorld();

        // Create appropriate shape based on serialized data
        ColliderShape shape = CreateShapeFromType(_shapeType);

        // Create physics material
        var material = new PhysicsMaterial
        {
            StaticFriction = 0.5f,
            DynamicFriction = 0.3f,
            Bounciness = 0.2f,
            Density = 1.0f
        };

        // Create physics body
        _physicsBody = _physicsWorld.CreateRigidBody(shape, material);
        _physicsBody.Mass = _mass;
        _physicsBody.IsKinematic = _isKinematic;
    }

    private ColliderShape CreateShapeFromType(ColliderShapeType type)
    {
        switch (type)
        {
            case ColliderShapeType.Box:
                return new BoxColliderShape(_size);
            case ColliderShapeType.Sphere:
                return new SphereColliderShape(_size.x * 0.5f); // Using x for radius
            // Other shape types...
            default:
                throw new ArgumentException("Unsupported collider shape type");
        }
    }

    private void FixedUpdate()
    {
        // Sync transform with physics body
        transform.position = _physicsBody.Position;
        transform.rotation = _physicsBody.Rotation;
    }

    private void OnDestroy()
    {
        if (_physicsWorld != null && _physicsBody != null)
        {
            _physicsWorld.DestroyRigidBody(_physicsBody);
        }
    }
}
