// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"
#include "Physics/PhysicsWorld.h"

PhysicsPlugin::PhysicsPlugin() : m_PhysicsWorld(nullptr) {
    // Register plugin with engine
    Engine::GetInstance()->RegisterPlugin(this);
}

PhysicsPlugin::~PhysicsPlugin() {
    // Unregister plugin
    Engine::GetInstance()->UnregisterPlugin(this);
}

void PhysicsPlugin::Initialize() {
    // Initialize physics backend
    m_PhysicsWorld = new PhysicsWorld();
    m_PhysicsWorld->Initialize();

    // Register component factories
    Engine::GetInstance()->RegisterComponentFactory("PhysicsBody", []() { return new PhysicsBody(); });
    Engine::GetInstance()->RegisterComponentFactory("PhysicsShape", []() { return new PhysicsShape(); });
    Engine::GetInstance()->RegisterComponentFactory("PhysicsMaterial", []() { return new PhysicsMaterial(); });
    Engine::GetInstance()->RegisterComponentFactory("PhysicsConstraint", []() { return new PhysicsConstraint(); });

    // Register debug drawing callback
    Engine::GetInstance()->RegisterDebugDrawCallback([this]() {
        if (m_PhysicsWorld) {
            m_PhysicsWorld->DebugDraw();
        }
    });
}

void PhysicsPlugin::Shutdown() {
    if (m_PhysicsWorld) {
        m_PhysicsWorld->Shutdown();
        delete m_PhysicsWorld;
        m_PhysicsWorld = nullptr;
    }

    // Unregister factories
    Engine::GetInstance()->UnregisterComponentFactory("PhysicsBody");
    Engine::GetInstance()->UnregisterComponentFactory("PhysicsShape");
    Engine::GetInstance()->UnregisterComponentFactory("PhysicsMaterial");
    Engine::GetInstance()->UnregisterComponentFactory("PhysicsConstraint");

    // Unregister debug callback
    Engine::GetInstance()->UnregisterDebugDrawCallback();
}

void PhysicsPlugin::Update(float deltaTime) {
    if (m_PhysicsWorld && m_PhysicsWorld->IsSimulationEnabled()) {
        m_PhysicsWorld->Update(deltaTime);
    }
}

PhysicsBody* PhysicsPlugin::CreatePhysicsBody() {
    return new PhysicsBody();
}

