    private List<ICollisionShape> collisionShapes = new List<ICollisionShape>();
    private float timeStep = 1.0f / 60.0f;
    private float gravity = -9.81f;

    public void AddPhysicsObject(IPhysicsObject obj)
    {
        physicsObjects.Add(obj);
    }

    public void RemovePhysicsObject(IPhysicsObject obj)
    {
        physicsObjects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Accumulate time and perform fixed time step updates
        float accumulatedTime = deltaTime;
        while (accumulatedTime >= timeStep)
        {
            Step(timeStep);
            accumulatedTime -= timeStep;
        }
    }

    private void Step(float deltaTime)
    {
        // Apply gravity
        foreach (var obj in physicsObjects)
        {
            if (!obj.IsStatic)
            {
                obj.ApplyForce(new Vector3(0, gravity * obj.Mass, 0), Vector3.Zero);
            }
        }

        // Collision detection
        DetectCollisions();

        // Integration (position/velocity update)
        Integrate(deltaTime);

        // Clear forces for next frame
        ClearForces();
    }

    private void DetectCollisions()
    {
        // Broad-phase collision detection (simple pairwise for now)
        for (int i = 0; i < physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < physicsObjects.Count; j++)
            {
                if (CheckCollision(physicsObjects[i], physicsObjects[j]))
                {
                    ResolveCollision(physicsObjects[i], physicsObjects[j]);
                }
            }
        }
    }

    private bool CheckCollision(IPhysicsObject a, IPhysicsObject b)
    {
        // Simplified collision check - would need proper collision shapes in real implementation
        float distance = Vector3.Distance(a.Position, b.Position);
        return distance < 1.0f; // Simple sphere collision check
    }

    private void ResolveCollision(IPhysicsObject a, IPhysicsObject b)
    {
        // Simple elastic collision response
        Vector3 normal = (b.Position - a.Position).Normalized();
        Vector3 relativeVelocity = b.Velocity - a.Velocity;

        float velocityAlongNormal = Vector3.Dot(relativeVelocity, normal);
        if (velocityAlongNormal > 0) return; // Objects moving apart

        float e = 0.8f; // Coefficient of restitution
        float j = -(1 + e) * velocityAlongNormal;
        j /= (1 / a.Mass) + (1 / b.Mass);

        Vector3 impulse = j * normal;

        a.ApplyImpulse(-impulse, a.Position);
        b.ApplyImpulse(impulse, b.Position);
    }

    private void Integrate(float deltaTime)
    {
        foreach (var obj in physicsObjects)
        {
            if (obj.IsStatic) continue;

            // Update linear position
            obj.Velocity += (obj.Acceleration * deltaTime);
            obj.Position += obj.Velocity * deltaTime;

            // Update angular position
            obj.AngularVelocity += (obj.AngularAcceleration * deltaTime);
            obj.Rotation *= Quaternion.FromAxisAngle(obj.AngularVelocity.Normalized(), obj.AngularVelocity.Length() * deltaTime);

            // Clear forces for next frame
            obj.Acceleration = Vector3.Zero;
            obj.AngularAcceleration = Vector3.Zero;
        }
    }

    private void ClearForces()
    {
        foreach (var obj in physicsObjects)
        {
            obj.Acceleration = Vector3.Zero;
            obj.AngularAcceleration = Vector3.Zero;
        }
    }
}

