// Physics world class
public class PhysicsWorld
{
    private List<IPhysicsObject> _objects = new List<IPhysicsObject>();
    private ICollisionDetector _collisionDetector;
    private List<(IPhysicsObject, IPhysicsObject)> _collisionPairs = new List<(IPhysicsObject, IPhysicsObject)>();

    public PhysicsWorld(ICollisionDetector collisionDetector)
    {
        _collisionDetector = collisionDetector;
    }

    public void AddObject(IPhysicsObject obj)
    {
        _objects.Add(obj);
    }

    public void RemoveObject(IPhysicsObject obj)
    {
        _objects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Clear previous collision pairs
        _collisionPairs.Clear();

        // Detect collisions
        for (int i = 0; i < _objects.Count; i++)
        {
            for (int j = i + 1; j < _objects.Count; j++)
            {
                if (_collisionDetector.CheckCollision(_objects[i], _objects[j], out var collisionInfo))
                {
                    _collisionPairs.Add((_objects[i], _objects[j]));
                    HandleCollision(_objects[i], _objects[j], collisionInfo);
                }
            }
        }

        // Update all objects
        foreach (var obj in _objects)
        {
            obj.Update(deltaTime);
        }
    }

    private void HandleCollision(IPhysicsObject a, IPhysicsObject b, CollisionInfo collisionInfo)
    {
        // Simple impulse-based collision response
        if (a.IsStatic && b.IsStatic) return;

        Vector3 relativeVelocity = b.Velocity - a.Velocity;
        float velocityAlongNormal = Vector3.Dot(relativeVelocity, collisionInfo.Normal);

        // Don't resolve if objects are moving apart
        if (velocityAlongNormal > 0) return;

        float restitution = 0.5f; // Bounciness
        float j = -(1 + restitution) * velocityAlongNormal;
        j /= a.IsStatic ? b.Mass : (1 / a.Mass + 1 / b.Mass);

        Vector3 impulse = j * collisionInfo.Normal;

        if (!a.IsStatic)
        {
            a.Velocity -= impulse * (1 / a.Mass);
        }

        if (!b.IsStatic)
        {
            b.Velocity += impulse * (1 / b.Mass);
        }
    }
}

// Plugin interface for engine integration
public interface IPhysicsPlugin
{
    PhysicsWorld CreatePhysicsWorld();
    IPhysicsObject CreateRigidBody(float mass, bool isStatic = false);
    void Update(float deltaTime);
}

