        m_world->SetTimeStep(settings.fixedTimeStep);
        return true;
    }

    void Shutdown() override {
        // Clean up all resources
        m_rigidBodies.clear();
        m_collisionShapes.clear();
        m_world.reset();
    }

    void StepSimulation(float deltaTime) override {
        m_world->StepSimulation(deltaTime);
