        if (!shape) return InvalidHandle;

        auto body = std::make_unique<RigidBody>(desc, shape);
        RigidBodyHandle handle = GenerateHandle();
        m_rigidBodies[handle] = std::move(body);
        m_world->AddRigidBody(m_rigidBodies[handle].get());
        return handle;
    }

    void DestroyRigidBody(RigidBodyHandle handle) override {
        auto it = m_rigidBodies.find(handle);
        if (it != m_rigidBodies.end()) {
            m_world->RemoveRigidBody(it->second.get());
            m_rigidBodies.erase(it);
        }
    }

