    std::unordered_map<CollisionShapeHandle, std::unique_ptr<CollisionShape>> m_collisionShapes;

    RigidBodyHandle GenerateHandle() {
        static RigidBodyHandle nextHandle = 1;
        return nextHandle++;
    }

    CollisionShape* GetCollisionShape(CollisionShapeHandle handle) {
        auto it = m_collisionShapes.find(handle);
        return it != m_collisionShapes.end() ? it->second.get() : nullptr;
    }

