## Physics World Implementation

```cpp
class PhysicsWorld {
public:
    void SetGravity(const Vector3& gravity) {
        m_gravity = gravity;
    }

    void SetTimeStep(float timeStep) {
        m_timeStep = timeStep;
    }

    void StepSimulation(float deltaTime) {
        // Simple fixed time step simulation
        m_accumulator += deltaTime;

        while (m_accumulator >= m_timeStep) {
            Integrate(m_timeStep);
            m_accumulator -= m_timeStep;
        }
    }

    void AddRigidBody(RigidBody* body) {
        m_rigidBodies.push_back(body);
    }

    void RemoveRigidBody(RigidBody* body) {
        auto it = std::find(m_rigidBodies.begin(), m_rigidBodies.end(), body);
        if (it != m_rigidBodies.end()) {
            m_rigidBodies.erase(it);
        }
    }

private:
    void Integrate(float deltaTime) {
        // Simple Euler integration
        for (auto body : m_rigidBodies) {
            if (body->IsKinematic()) continue;

            // Apply gravity
            Vector3 force = m_gravity * body->GetMass();
            body->ApplyForce(force);

            // Update velocity
            Vector3 acceleration = body->GetForce() / body->GetMass();
            body->SetLinearVelocity(body->GetLinearVelocity() + acceleration * deltaTime);

            // Update position
            Vector3 position = body->GetPosition() + body->GetLinearVelocity() * deltaTime;
            body->SetPosition(position);

            // Reset forces for next frame
            body->ClearForces();
        }

        // Collision detection and response would go here
    }

    Vector3 m_gravity = {0.0f, -9.81f, 0.0f};
    float m_timeStep = 1.0f / 60.0f;
    float m_accumulator = 0.0f;
    std::vector<RigidBody*> m_rigidBodies;
};
