```cpp
// PhysicsWorld.cpp
#include "PhysicsWorld.h"
#include "RigidBody.h"
#include "CollisionDetection.h"

PhysicsWorld::PhysicsWorld()
    : m_gravity(0.0f, -9.81f, 0.0f),
      m_fixedTimeStep(1.0f / 60.0f),
      m_accumulator(0.0f) {
}

PhysicsWorld::~PhysicsWorld() {
    for (auto body : m_rigidBodies) {
        delete body;
    }
}

void PhysicsWorld::Update(float deltaTime) {
    // Fixed time step simulation
    m_accumulator += deltaTime;

    while (m_accumulator >= m_fixedTimeStep) {
        // Integrate all rigid bodies
        for (auto body : m_rigidBodies) {
            if (!body->GetIsKinematic()) {
                body->Update(m_fixedTimeStep);
            }
        }

        // Detect and resolve collisions
        for (size_t i = 0; i < m_rigidBodies.size(); i++) {
            for (size_t j = i + 1; j < m_rigidBodies.size(); j++) {
                Collider* colliderA = m_rigidBodies[i]->GetCollider();
                Collider* colliderB = m_rigidBodies[j]->GetCollider();

                if (colliderA && colliderB) {
                    CollisionInfo info;
                    if (colliderA->CheckCollision(colliderB, info)) {
                        // Resolve collision
                        ResolveCollision(m_rigidBodies[i], m_rigidBodies[j], info);
                    }
                }
            }
        }

        m_accumulator -= m_fixedTimeStep;
    }
}

