```csharp
// Base interface for physics objects
public interface IPhysicsObject
{
    Vector3 Position { get; set; }
    Quaternion Rotation { get; set; }
    Vector3 Velocity { get; set; }
    Vector3 AngularVelocity { get; set; }
    float Mass { get; set; }
    bool IsStatic { get; set; }

    void ApplyForce(Vector3 force);
    void ApplyTorque(Vector3 torque);
    void Update(float deltaTime);
}

// Rigid body implementation
public class RigidBody : IPhysicsObject
{
    public Vector3 Position { get; set; }
    public Quaternion Rotation { get; set; }
    public Vector3 Velocity { get; set; }
    public Vector3 AngularVelocity { get; set; }
    public float Mass { get; set; } = 1.0f;
    public bool IsStatic { get; set; } = false;

    private Vector3 _forceAccumulator;
    private Vector3 _torqueAccumulator;
    private float _drag = 0.1f;
    private float _angularDrag = 0.1f;

    public void ApplyForce(Vector3 force)
    {
        if (IsStatic) return;
        _forceAccumulator += force;
    }

    public void ApplyTorque(Vector3 torque)
    {
        if (IsStatic) return;
        _torqueAccumulator += torque;
    }

    public void Update(float deltaTime)
    {
        if (IsStatic) return;

        // Apply forces
        Vector3 acceleration = _forceAccumulator / Mass;
        Velocity += acceleration * deltaTime;

        // Apply drag
        Velocity *= (1.0f - _drag * deltaTime);

        // Update position
        Position += Velocity * deltaTime;

        // Apply torques
        Vector3 angularAcceleration = _torqueAccumulator / Mass;
        AngularVelocity += angularAcceleration * deltaTime;

        // Apply angular drag
        AngularVelocity *= (1.0f - _angularDrag * deltaTime);

        // Update rotation
        Quaternion rotationChange = new Quaternion(AngularVelocity * deltaTime, 1.0f);
        Rotation = Quaternion.Multiply(Rotation, rotationChange);

        // Clear accumulators
        _forceAccumulator = Vector3.Zero;
        _torqueAccumulator = Vector3.Zero;
    }
}

// Collision detection interface
public interface ICollisionDetector
{
    bool CheckCollision(IPhysicsObject a, IPhysicsObject b, out CollisionInfo collisionInfo);
}

public struct CollisionInfo
{
    public Vector3 ContactPoint;
    public Vector3 Normal;
    public float PenetrationDepth;
}

// Basic collision detector implementation
public class BasicCollisionDetector : ICollisionDetector
{
    public bool CheckCollision(IPhysicsObject a, IPhysicsObject b, out CollisionInfo collisionInfo)
    {
        collisionInfo = new CollisionInfo();

        // Simple sphere-sphere collision detection
        if (a is SphereCollider sphereA && b is SphereCollider sphereB)
        {
            float distance = Vector3.Distance(sphereA.Position, sphereB.Position);
            float radiusSum = sphereA.Radius + sphereB.Radius;

            if (distance < radiusSum)
            {
                collisionInfo.ContactPoint = (sphereA.Position + sphereB.Position) / 2f;
                collisionInfo.Normal = Vector3.Normalize(sphereB.Position - sphereA.Position);
                collisionInfo.PenetrationDepth = radiusSum - distance;
                return true;
            }
        }

        return false;
    }
}

// Physics world class
public class PhysicsWorld
{
    private List<IPhysicsObject> _physicsObjects = new List<IPhysicsObject>();
    private ICollisionDetector _collisionDetector;
    private List<CollisionPair> _collisionPairs = new List<CollisionPair>();

    public PhysicsWorld(ICollisionDetector collisionDetector)
    {
        _collisionDetector = collisionDetector;
    }

    public void AddObject(IPhysicsObject obj)
    {
        _physicsObjects.Add(obj);
    }

    public void RemoveObject(IPhysicsObject obj)
    {
        _physicsObjects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Clear previous collision pairs
        _collisionPairs.Clear();

        // Update all physics objects
        foreach (var obj in _physicsObjects)
        {
            obj.Update(deltaTime);
        }

        // Detect collisions
        for (int i = 0; i < _physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < _physicsObjects.Count; j++)
            {
                if (_collisionDetector.CheckCollision(_physicsObjects[i], _physicsObjects[j], out var collisionInfo))
                {
                    _collisionPairs.Add(new CollisionPair(_physicsObjects[i], _physicsObjects[j], collisionInfo));
                }
            }
        }

        // Resolve collisions
        foreach (var pair in _collisionPairs)
        {
            ResolveCollision(pair);
        }
    }

    private void ResolveCollision(CollisionPair pair)
    {
        // Simple collision response (elastic collision)
        if (pair.ObjectA.IsStatic && pair.ObjectB.IsStatic)
            return;

        Vector3 relativeVelocity = pair.ObjectB.Velocity - pair.ObjectA.Velocity;
        float velocityAlongNormal = Vector3.Dot(relativeVelocity, pair.CollisionInfo.Normal);

        // Don't resolve if objects are moving apart
        if (velocityAlongNormal > 0)
            return;

        float restitution = 0.8f; // Bounciness
        float j = -(1 + restitution) * velocityAlongNormal;
        j /= (1 / pair.ObjectA.Mass) + (1 / pair.ObjectB.Mass);

        Vector3 impulse = j * pair.CollisionInfo.Normal;

        if (!pair.ObjectA.IsStatic)
            pair.ObjectA.Velocity -= impulse / pair.ObjectA.Mass;

        if (!pair.ObjectB.IsStatic)
            pair.ObjectB.Velocity += impulse / pair.ObjectB.Mass;

        // Position correction for penetration
        const float penetrationSlack = 0.05f;
        float penetrationCorrection = (Math.Max(pair.CollisionInfo.PenetrationDepth - penetrationSlack, 0.0f) /
                                      (1 / pair.ObjectA.Mass + 1 / pair.ObjectB.Mass)) * 0.2f;

        Vector3 correction = penetrationCorrection * pair.CollisionInfo.Normal;

        if (!pair.ObjectA.IsStatic)
            pair.ObjectA.Position -= correction / pair.ObjectA.Mass;

        if (!pair.ObjectB.IsStatic)
            pair.ObjectB.Position += correction / pair.ObjectB.Mass;
    }
}

public class CollisionPair
{
    public IPhysicsObject ObjectA { get; }
    public IPhysicsObject ObjectB { get; }
    public CollisionInfo CollisionInfo { get; }

    public CollisionPair(IPhysicsObject a, IPhysicsObject b, CollisionInfo info)
    {
        ObjectA = a;
        ObjectB = b;
        CollisionInfo = info;
    }
}

// Example collider implementations
