// PhysicsPluginImpl.cpp
#include "PhysicsPluginImpl.h"
#include <algorithm>

namespace GameEngine {
    PhysicsPluginImpl::PhysicsPluginImpl()
        : m_gravity(0.0f, -9.81f, 0.0f), m_fixedTimeStep(1.0f / 60.0f), m_accumulator(0.0f) {
    }

    PhysicsPluginImpl::~PhysicsPluginImpl() {
