        return true;
    }

    void PhysicsPluginImpl::Shutdown() {
        m_rigidBodies.clear();
    }

    void PhysicsPluginImpl::StepSimulation(float deltaTime) {
        // Fixed timestep simulation
        m_accumulator += deltaTime;

        while (m_accumulator >= m_fixedTimeStep) {
            // Apply gravity
            ApplyGravity(m_fixedTimeStep);

            // Integrate positions and velocities
            IntegrateBodies(m_fixedTimeStep);

            // Detect and resolve collisions
            auto collisions = DetectCollisions();
            ResolveCollisions(collisions);

            m_accumulator -= m_fixedTimeStep;
        }
    }

    void PhysicsPluginImpl::SetGravity(const Vector3& gravity) {
        m_gravity = gravity;
    }

    PhysicsPlugin::RigidBody* PhysicsPluginImpl::CreateRigidBody() {
        auto body = std::make_unique<RigidBody>();
        body->position = Vector3(0.0f, 0.0f, 0.0f);
        body->rotation = Quaternion::Identity();
        body->linearVelocity = Vector3(0.0f, 0.0f, 0.0f);
        body->angularVelocity = Vector3(0.0f, 0.0f, 0.0f);
        body->mass = 1.0f;
        body->inverseMass = 1.0f;
        body->isStatic = false;

        // Default inertia tensor (for a unit sphere)
        body->inertiaTensor = Matrix3x3::Identity() * (2.0f / 5.0f);
        body->inverseInertiaTensor = Matrix3x3::Identity() * (5.0f / 2.0f);

        RigidBody* rawPtr = body.get();
        m_rigidBodies.push_back(std::move(body));
        return rawPtr;
    }

    void PhysicsPluginImpl::DestroyRigidBody(RigidBody* body) {
        auto it = std::remove_if(m_rigidBodies.begin(), m_rigidBodies.end(),
            [body](const std::unique_ptr<RigidBody>& ptr) { return ptr.get() == body; });

        if (it != m_rigidBodies.end()) {
            m_rigidBodies.erase(it, m_rigidBodies.end());
        }
    }

    std::vector<PhysicsPlugin::CollisionInfo> PhysicsPluginImpl::DetectCollisions() {
        std::vector<CollisionInfo> collisions;

        // Naive O(n^2) collision detection
        for (size_t i = 0; i < m_rigidBodies.size(); ++i) {
            for (size_t j = i + 1; j < m_rigidBodies.size(); ++j) {
                RigidBody* bodyA = m_rigidBodies[i].get();
                RigidBody* bodyB = m_rigidBodies[j].get();

                // Simple sphere-sphere collision detection
                float radiusA = 0.5f; // Would come from collision shape
                float radiusB = 0.5f;
                Vector3 delta = bodyB->position - bodyA->position;
                float distanceSq = delta.LengthSquared();
                float radiusSum = radiusA + radiusB;

                if (distanceSq < radiusSum * radiusSum) {
                    CollisionInfo info;
                    info.bodyA = bodyA;
                    info.bodyB = bodyB;
                    info.contactPoint = (bodyA->position + bodyB->position) * 0.5f;
                    info.normal = delta.Normalized();
                    info.penetrationDepth = radiusSum - sqrtf(distanceSq);
                    collisions.push_back(info);
                }
            }
        }

        return collisions;
    }

    void PhysicsPluginImpl::ApplyForce(RigidBody* body, const Vector3& force, const Vector3& point) {
        if (body->isStatic) return;

        // Apply linear force
        body->linearVelocity += force * body->inverseMass;

        // Apply torque (angular force)
        Vector3 torque = Vector3::Cross(point - body->position, force);
        body->angularVelocity += body->inverseInertiaTensor * torque;
    }

    void PhysicsPluginImpl::ApplyImpulse(RigidBody* body, const Vector3& impulse, const Vector3& point) {
        if (body->isStatic) return;

        // Apply linear impulse
        body->linearVelocity += impulse * body->inverseMass;

        // Apply angular impulse
        Vector3 torque = Vector3::Cross(point - body->position, impulse);
        body->angularVelocity += body->inverseInertiaTensor * torque;
    }

    Vector3 PhysicsPluginImpl::GetVelocityAtPoint(const RigidBody* body, const Vector3& point) const {
        return body->linearVelocity + Vector3::Cross(body->angularVelocity, point - body->position);
    }

    void PhysicsPluginImpl::IntegrateBodies(float deltaTime) {
        for (auto& body : m_rigidBodies) {
            if (body->isStatic) continue;

            // Update linear position
            body->position += body->linearVelocity * deltaTime;

            // Update angular position (quaternion integration)
            Quaternion rotationDelta(0.0f,
                body->angularVelocity.x * deltaTime * 0.5f,
                body->angularVelocity.y * deltaTime * 0.5f,
                body->angularVelocity.z * deltaTime * 0.5f);
            body->rotation = (body->rotation + rotationDelta * body->rotation).Normalized();
        }
    }

    void PhysicsPluginImpl::ResolveCollisions(const std::vector<CollisionInfo>& collisions) {
        for (const auto& collision : collisions) {
            if (collision.bodyA->isStatic && collision.bodyB->isStatic) continue;

            // Simple position correction
            float totalInverseMass = collision.bodyA->inverseMass + collision.bodyB->inverseMass;
            if (totalInverseMass <= 0.0f) continue;

            Vector3 correction = collision.normal * (collision.penetrationDepth / totalInverseMass);
            collision.bodyA->position -= correction * collision.bodyA->inverseMass;
            collision.bodyB->position += correction * collision.bodyB->inverseMass;

            // Simple impulse-based collision response
            Vector3 relativeVelocity = collision.bodyB->linearVelocity - collision.bodyA->linearVelocity;
            float velocityAlongNormal = Vector3::Dot(relativeVelocity, collision.normal);

            // Don't resolve if objects are moving apart
            if (velocityAlongNormal > 0.0f) continue;

            // Calculate impulse scalar
            float restitution = 0.5f; // Coefficient of restitution
            float j = -(1.0f + restitution) * velocityAlongNormal;
            j /= totalInverseMass;

            // Apply impulse
            Vector3 impulse = collision.normal * j;
            collision.bodyA->linearVelocity -= impulse * collision.bodyA->inverseMass;
            collision.bodyB->linearVelocity += impulse * collision.bodyB->inverseMass;
        }
    }

    void PhysicsPluginImpl::ApplyGravity(float deltaTime) {
        for (auto& body : m_rigidBodies) {
            if (body->isStatic) continue;
            body->linearVelocity += m_gravity * deltaTime;
        }
    }

    // Factory function implementation
    extern "C" GAME_ENGINE_API PhysicsPlugin* CreatePhysicsPlugin() {
        return new PhysicsPluginImpl();
    }
}
