// Rigid body implementation
public class RigidBody : IPhysicsObject
{
    public Vector3 Position { get; set; }
    public Quaternion Rotation { get; set; }
    public Vector3 Velocity { get; set; }
    public Vector3 AngularVelocity { get; set; }
    public float Mass { get; set; }
    public bool IsKinematic { get; set; }

    private Vector3 _forceAccumulator;
    private Vector3 _torqueAccumulator;
    private float _inverseMass;

    public RigidBody(float mass, Vector3 position, Quaternion rotation)
    {
        Mass = mass;
        _inverseMass = mass > 0 ? 1.0f / mass : 0.0f;
        Position = position;
        Rotation = rotation;
        Velocity = Vector3.Zero;
        AngularVelocity = Vector3.Zero;
        IsKinematic = false;
    }

    public void ApplyForce(Vector3 force)
    {
        _forceAccumulator += force;
    }

    public void ApplyTorque(Vector3 torque)
    {
        _torqueAccumulator += torque;
    }

    public void Update(float deltaTime)
    {
        if (IsKinematic) return;

        // Apply forces
        Vector3 acceleration = _forceAccumulator * _inverseMass;
        Velocity += acceleration * deltaTime;

        // Apply torque (simplified)
        AngularVelocity += _torqueAccumulator * deltaTime;

        // Update position
        Position += Velocity * deltaTime;

        // Update rotation
        Quaternion angularRotation = new Quaternion(AngularVelocity * deltaTime, 1.0f);
        Rotation = Quaternion.Multiply(Rotation, angularRotation);

        // Clear accumulators
        _forceAccumulator = Vector3.Zero;
        _torqueAccumulator = Vector3.Zero;
    }
}

// Collision detection interface
public interface ICollisionDetector
{
    bool CheckCollision(IPhysicsObject a, IPhysicsObject b, out CollisionInfo collisionInfo);
}

// Simple sphere-sphere collision detector
public class SphereCollisionDetector : ICollisionDetector
{
    public bool CheckCollision(IPhysicsObject a, IPhysicsObject b, out CollisionInfo collisionInfo)
    {
        collisionInfo = new CollisionInfo();

        // Simplified - assumes both objects are spheres with radius equal to their mass
        float radiusA = a.Mass;
        float radiusB = b.Mass;

        float distance = Vector3.Distance(a.Position, b.Position);
        float minDistance = radiusA + radiusB;

        if (distance < minDistance)
        {
            collisionInfo.Normal = Vector3.Normalize(a.Position - b.Position);
            collisionInfo.Depth = minDistance - distance;
            collisionInfo.Point = a.Position + collisionInfo.Normal * radiusA;
            return true;
        }

        return false;
    }
}

// Collision response system
public class CollisionResponseSystem
{
    public void ResolveCollision(IPhysicsObject a, IPhysicsObject b, CollisionInfo collisionInfo)
    {
        // Simple impulse-based collision response
        if (a.IsKinematic && b.IsKinematic) return;

        Vector3 relativeVelocity = b.Velocity - a.Velocity;
        float velocityAlongNormal = Vector3.Dot(relativeVelocity, collisionInfo.Normal);

        // Don't resolve if objects are moving apart
        if (velocityAlongNormal > 0) return;

        float restitution = 0.8f; // Bounciness coefficient

        float j = -(1 + restitution) * velocityAlongNormal;
        j /= a.Mass + b.Mass;

        Vector3 impulse = j * collisionInfo.Normal;

        if (!a.IsKinematic)
        {
            a.Velocity -= impulse * a.Mass;
        }

        if (!b.IsKinematic)
        {
            b.Velocity += impulse * b.Mass;
        }

        // Position correction to prevent sinking
        const float penetrationSlack = 0.05f;
        float penetration = collisionInfo.Depth - penetrationSlack;
        if (penetration < 0) return;

        Vector3 correction = (penetration / (a.Mass + b.Mass)) * collisionInfo.Normal;

        if (!a.IsKinematic)
        {
            a.Position -= correction * a.Mass;
        }

        if (!b.IsKinematic)
        {
            b.Position += correction * b.Mass;
        }
    }
}

// Main physics system
public class PhysicsSystem
{
    private List<IPhysicsObject> _physicsObjects = new List<IPhysicsObject>();
    private ICollisionDetector _collisionDetector;
    private CollisionResponseSystem _collisionResponse;

    public PhysicsSystem()
    {
        _collisionDetector = new SphereCollisionDetector();
        _collisionResponse = new CollisionResponseSystem();
    }

    public void AddObject(IPhysicsObject obj)
    {
        _physicsObjects.Add(obj);
    }

    public void RemoveObject(IPhysicsObject obj)
    {
        _physicsObjects.Remove(obj);
    }

    public void Update(float deltaTime)
    {
        // Update all objects
        foreach (var obj in _physicsObjects)
        {
            obj.Update(deltaTime);
        }

        // Check for collisions
        for (int i = 0; i < _physicsObjects.Count; i++)
        {
            for (int j = i + 1; j < _physicsObjects.Count; j++)
            {
                if (_collisionDetector.CheckCollision(_physicsObjects[i], _physicsObjects[j], out var collisionInfo))
                {
                    _collisionResponse.ResolveCollision(_physicsObjects[i], _physicsObjects[j], collisionInfo);
                }
            }
        }
    }
}

