class PhysicsPluginImpl : public PhysicsPlugin {
public:
    PhysicsPluginImpl() : m_gravity(0.0f, -9.81f, 0.0f) {}

    bool Initialize(const PhysicsSettings& settings) override {
        // Initialize physics world
        m_timeAccumulator = 0.0f;
        m_fixedTimeStep = settings.fixedTimeStep;
        return true;
    }

    void Shutdown() override {
        // Clean up all physics objects
        for (auto body : m_rigidBodies) {
            delete body;
        }
        m_rigidBodies.clear();

        for (auto shape : m_collisionShapes) {
            delete shape;
        }
        m_collisionShapes.clear();
    }

    void StepSimulation(float deltaTime) override {
        m_timeAccumulator += deltaTime;

        while (m_timeAccumulator >= m_fixedTimeStep) {
            // Integrate all rigid bodies
            for (auto body : m_rigidBodies) {
                if (body->isStatic) continue;

                // Apply gravity
                body->linearVelocity += m_gravity * m_fixedTimeStep;

                // Semi-implicit Euler integration
                body->position += body->linearVelocity * m_fixedTimeStep;
                body->rotation += Quaternion(body->angularVelocity * m_fixedTimeStep, 1.0f) * body->rotation;
                body->rotation.Normalize();
            }

            // Broad phase - simple AABB tree or grid
            UpdateBroadPhase();

            // Narrow phase collision detection
            DetectCollisions();

            // Solve contacts
            SolveContacts();

            m_timeAccumulator -= m_fixedTimeStep;
        }
    }

