        auto body = new RigidBody();
        // Initialize body from description
        body->position = desc.position;
        body->rotation = desc.rotation;
        body->linearVelocity = desc.linearVelocity;
        body->angularVelocity = desc.angularVelocity;
        body->mass = desc.mass;
        body->inverseMass = (desc.mass > 0.0f) ? 1.0f / desc.mass : 0.0f;
        body->isStatic = desc.isStatic;

        // Calculate inertia tensor (simplified for demo)
        if (!body->isStatic) {
            // This is a very simplified calculation - real implementation would be more complex
            body->inertiaTensor = Matrix3x3::Identity() * body->mass;
            body->inverseInertiaTensor = Matrix3x3::Identity() * body->inverseMass;
        }

        m_rigidBodies.push_back(body);
        return body;
    }

    void DestroyRigidBody(RigidBody* body) override {
        auto it = std::find(m_rigidBodies.begin(), m_rigidBodies.end(), body);
        if (it != m_rigidBodies.end()) {
            delete *it;
            m_rigidBodies.erase(it);
        }
    }

