private:
    void UpdateBroadPhase() {
        // Simple implementation - would use a more sophisticated structure in production
        m_potentialPairs.clear();
        for (size_t i = 0; i < m_rigidBodies.size(); ++i) {
            for (size_t j = i + 1; j < m_rigidBodies.size(); ++j) {
                m_potentialPairs.emplace_back(m_rigidBodies[i], m_rigidBodies[j]);
            }
        }
    }

    void DetectCollisions() {
        // Simple sphere-sphere collision detection
        for (auto& pair : m_potentialPairs) {
            auto bodyA = pair.first;
            auto bodyB = pair.second;

            // Get collision shapes (simplified - would need proper shape association)
            // This is a placeholder for actual shape retrieval
            float radiusA = 1.0f; // Would come from actual shape
            float radiusB = 1.0f;

            Vector3 delta = bodyB->position - bodyA->position;
            float distanceSq = delta.LengthSquared();
            float radiusSum = radiusA + radiusB;

            if (distanceSq < radiusSum * radiusSum) {
                // Collision detected
                float distance = std::sqrt(distanceSq);
                Vector3 normal = delta / distance;

                CollisionResult result;
                result.hit = true;
                result.contactPoint = bodyA->position + normal * radiusA;
                result.normal = normal;
                result.penetrationDepth = radiusSum - distance;
                result.otherBody = bodyB;

                // Store collision for resolution
                m_contacts.emplace_back(bodyA, result);
            }
        }
    }

    void SolveContacts() {
        for (auto& contact : m_contacts) {
            auto bodyA = contact.first;
            auto& result = contact.second;

            // Simple impulse-based collision response
            if (bodyA->isStatic) continue;

            // Calculate relative velocity
            Vector3 relativeVelocity = result.otherBody->linearVelocity - bodyA->linearVelocity;

            // Calculate impulse magnitude
            float impulseMagnitude = -(1.0f + 0.5f) * Vector3::Dot(relativeVelocity, result.normal);
            impulseMagnitude /= bodyA->inverseMass + result.otherBody->inverseMass;

            // Apply impulse
            Vector3 impulse = result.normal * impulseMagnitude;
            bodyA->linearVelocity -= impulse * bodyA->inverseMass;
            result.otherBody->linearVelocity += impulse * result.otherBody->inverseMass;

            // Position correction for penetration
            const float penetrationSlack = 0.01f;
            float correction = (std::max(result.penetrationDepth - penetrationSlack, 0.0f) /
                              (bodyA->inverseMass + result.otherBody->inverseMass)) * 0.2f;

            bodyA->position -= result.normal * correction * bodyA->inverseMass;
            result.otherBody->position += result.normal * correction * result.otherBody->inverseMass;
        }

        m_contacts.clear();
    }

