    void PhysicsPluginImpl::Update(float deltaTime) {
        // Fixed timestep physics update
        m_accumulator += deltaTime;

        while (m_accumulator >= m_fixedTimeStep) {
            IntegrateBodies(m_fixedTimeStep);
            DetectCollisions();
            ResolveCollisions();
            m_accumulator -= m_fixedTimeStep;
        }
    }

    void PhysicsPluginImpl::Shutdown() {
        m_bodies.clear();
    }

    int PhysicsPluginImpl::CreateRigidBody(const RigidBodyDesc& desc) {
        RigidBody body;
        body.id = m_nextBodyId++;
        body.position = desc.position;
        body.rotation = desc.rotation;
        body.linearVelocity = Vector3(0.0f);
        body.angularVelocity = Vector3(0.0f);
        body.mass = desc.mass;
        body.isKinematic = desc.isKinematic;
        body.colliderType = desc.colliderType;

        m_bodies[body.id] = body;
        return body.id;
    }

    void PhysicsPluginImpl::RemoveRigidBody(int bodyId) {
        m_bodies.erase(bodyId);
    }

    void PhysicsPluginImpl::ApplyForce(int bodyId, const Vector3& force) {
        auto it = m_bodies.find(bodyId);
        if (it != m_bodies.end() && !it->second.isKinematic) {
            it->second.linearVelocity += force * (1.0f / it->second.mass) * m_fixedTimeStep;
        }
    }

    void PhysicsPluginImpl::ApplyImpulse(int bodyId, const Vector3& impulse) {
        auto it = m_bodies.find(bodyId);
        if (it != m_bodies.end() && !it->second.isKinematic) {
            it->second.linearVelocity += impulse * (1.0f / it->second.mass);
        }
    }

    void PhysicsPluginImpl::SetGravity(const Vector3& gravity) {
        m_gravity = gravity;
    }

