        return m_gravity;
    }

    bool PhysicsPluginImpl::Raycast(const Ray& ray, RaycastHit& hit, float maxDistance) {
        // Simple raycast implementation - would need proper collision detection
        float closestDistance = maxDistance;
        bool hitFound = false;

        for (const auto& pair : m_bodies) {
            const RigidBody& body = pair.second;

            // Simple sphere collision check for demonstration
            if (body.colliderType == ColliderType::Sphere) {
                // This is a simplified check - real implementation would need proper collision detection
                Vector3 center = body.position;
                float radius = 1.0f; // Would need to get actual radius from collider

                Vector3 oc = ray.origin - center;
                float a = Vector3::Dot(ray.direction, ray.direction);
                float b = 2.0f * Vector3::Dot(oc, ray.direction);
                float c = Vector3::Dot(oc, oc) - radius * radius;
                float discriminant = b * b - 4 * a * c;

                if (discriminant >= 0) {
                    float distance = (-b - sqrt(discriminant)) / (2.0f * a);
                    if (distance > 0 && distance < closestDistance) {
                        closestDistance = distance;
                        hit.bodyId = body.id;
                        hit.point = ray.origin + ray.direction * distance;
                        hit.normal = (hit.point - center).Normalized();
                        hit.distance = distance;
                        hitFound = true;
                    }
                }
            }
        }

        return hitFound;
    }

    void PhysicsPluginImpl::IntegrateBodies(float deltaTime) {
        for (auto& pair : m_bodies) {
            RigidBody& body = pair.second;

            if (body.isKinematic) continue;

            // Apply gravity
            body.linearVelocity += m_gravity * deltaTime;

            // Update position
            body.position += body.linearVelocity * deltaTime;

            // Update rotation (simplified)
            if (body.angularVelocity.LengthSquared() > 0.0f) {
                Quaternion rotationChange(0.0f, body.angularVelocity * deltaTime);
                body.rotation = (rotationChange * body.rotation).Normalized();
            }
        }
    }

    void PhysicsPluginImpl::DetectCollisions() {
        // Simple broad-phase collision detection
        // In a real implementation, this would use spatial partitioning
        std::vector<std::pair<int, int>> potentialCollisions;

        auto it1 = m_bodies.begin();
        while (it1 != m_bodies.end()) {
            auto it2 = it1;
            ++it2;
            while (it2 != m_bodies.end()) {
                // Simple distance check for demonstration
                Vector3 diff = it1->second.position - it2->second.position;
                float distanceSq = diff.LengthSquared();

                // Simple collision radius check (would need proper collision detection)
                if (distanceSq < 1.0f) { // 1.0f is a placeholder for actual collision radius
                    potentialCollisions.emplace_back(it1->first, it2->first);
                }
                ++it2;
            }
            ++it1;
        }

        // Narrow-phase collision detection would go here
    }

    void PhysicsPluginImpl::ResolveCollisions() {
        // Simple collision response
        // In a real implementation, this would handle proper physics responses
        for (auto& pair : m_bodies) {
            RigidBody& body = pair.second;

            // Simple ground collision for demonstration
            if (body.position.y < 0.0f) {
                body.position.y = 0.0f;
                body.linearVelocity.y = -body.linearVelocity.y * 0.5f; // Simple bounce
            }
        }
    }
