    // or your custom physics implementation

    m_initialized = true;
}

void PhysicsPlugin::Shutdown() {
    if (!m_initialized) return;

    // Clean up all physics worlds
    for (auto world : m_worlds) {
        delete world;
    }
    m_worlds.clear();

    // Shutdown physics engine backend

    m_initialized = false;
}

void PhysicsPlugin::Update(float deltaTime) {
    if (!m_initialized) return;

    // Update all physics worlds
    for (auto world : m_worlds) {
        world->Update(deltaTime);
    }
}

PhysicsWorld* PhysicsPlugin::CreatePhysicsWorld(const PhysicsWorldSettings& settings) {
    auto world = new PhysicsWorld(settings);
    m_worlds.push_back(world);
    return world;
}

void PhysicsPlugin::DestroyPhysicsWorld(PhysicsWorld* world) {
    auto it = std::find(m_worlds.begin(), m_worlds.end(), world);
    if (it != m_worlds.end()) {
        m_worlds.erase(it);
        delete world;
    }
}

