### src/CustomPhysicsPlugin.cpp

```cpp
#include "CustomPhysicsPlugin.h"
#include <algorithm>

namespace CustomPhysics {

PhysicsWorld::PhysicsWorld()
    : m_gravity({0.0f, -9.81f, 0.0f}), m_accumulator(0.0f) {}

PhysicsWorld::~PhysicsWorld() {
    for (auto body : m_bodies) {
        delete body;
    }
    m_bodies.clear();
}

void PhysicsWorld::Update(float deltaTime) {
    m_accumulator += deltaTime;

    while (m_accumulator >= m_fixedTimeStep) {
        // Fixed time step simulation
        for (auto body : m_bodies) {
            body->Integrate(m_fixedTimeStep);
        }

        DetectCollisions();
        m_accumulator -= m_fixedTimeStep;
    }
}

void PhysicsWorld::SetGravity(const Vector3& gravity) {
    m_gravity = gravity;
}

RigidBody* PhysicsWorld::CreateRigidBody(const RigidBodyDesc& desc) {
    RigidBody* body = new RigidBody(desc);
    m_bodies.push_back(body);
    return body;
}

void PhysicsWorld::DestroyRigidBody(RigidBody* body) {
    auto it = std::find(m_bodies.begin(), m_bodies.end(), body);
    if (it != m_bodies.end()) {
        m_bodies.erase(it);
        delete body;
    }
}

void PhysicsWorld::DetectCollisions() {
    // Simple broad-phase collision detection
    for (size_t i = 0; i < m_bodies.size(); ++i) {
        for (size_t j = i + 1; j < m_bodies.size(); ++j) {
            // In a real implementation, you'd have proper collision detection here
            // For this minimal example, we'll just assume all bodies collide
            // and resolve with simple restitution
            RigidBody* a = m_bodies[i];
            RigidBody* b = m_bodies[j];

            // Simple collision response
            Vector3 relativeVelocity = {
                b->GetVelocity().x - a->GetVelocity().x,
                b->GetVelocity().y - a->GetVelocity().y,
                b->GetVelocity().z - a->GetVelocity().z
            };

            // Calculate impulse magnitude
            float impulseMagnitude = -(1.0f + 0.5f) * relativeVelocity.y; // Simple restitution

            // Apply impulse
            a->ApplyImpulse({0.0f, impulseMagnitude, 0.0f});
            b->ApplyImpulse({0.0f, -impulseMagnitude, 0.0f});
        }
    }
}

} // namespace CustomPhysics
```

### src/RigidBody.cpp

```cpp
#include "RigidBody.h"

namespace CustomPhysics {

RigidBody::RigidBody(const RigidBodyDesc& desc)
    : m_position(desc.position),
      m_velocity(desc.velocity),
      m_acceleration({0.0f, 0.0f, 0.0f}),
      m_mass(desc.mass),
      m_restitution(desc.restitution),
      m_friction(desc.friction) {}

RigidBody::~RigidBody() {}

void RigidBody::Integrate(float deltaTime) {
    // Semi-implicit Euler integration
    m_velocity.x += m_acceleration.x * deltaTime;
    m_velocity.y += m_acceleration.y * deltaTime;
    m_velocity.z += m_acceleration.z * deltaTime;

    m_position.x += m_velocity.x * deltaTime;
    m_position.y += m_velocity.y * deltaTime;
    m_position.z += m_velocity.z * deltaTime;

    // Reset acceleration
    m_acceleration = {0.0f, 0.0f, 0.0f};
}

void RigidBody::ApplyForce(const Vector3& force) {
    if (m_mass > 0.0f) {
        m_acceleration.x += force.x / m_mass;
        m_acceleration.y += force.y / m_mass;
        m_acceleration.z += force.z / m_mass;
    }
}

void RigidBody::ApplyImpulse(const Vector3& impulse) {
    if (m_mass > 0.0f) {
        m_velocity.x += impulse.x / m_mass;
        m_velocity.y += impulse.y / m_mass;
        m_velocity.z += impulse.z / m_mass;
    }
}

} // namespace CustomPhysics
```

