### 6. CustomPhysicsComponent.cpp
```cpp
#include "CustomPhysicsComponent.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    PrimaryComponentTick.TickGroup = TG_PrePhysics;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    if (GetOwner() && GetOwner()->GetRootComponent())
    {
        SimulatePhysics(DeltaTime);

        // Apply the new position
        FVector NewLocation = GetOwner()->GetActorLocation() + Velocity * DeltaTime;
        GetOwner()->SetActorLocation(NewLocation);
    }
}

void UCustomPhysicsComponent::SimulatePhysics(float DeltaTime)
{
    // Apply gravity (simple implementation)
    const FVector Gravity(0.0f, 0.0f, -980.0f); // cm/s²
    Acceleration = Gravity / Mass;

    // Apply drag
    FVector DragForce = -DragCoefficient * Velocity.GetSafeNormal() * Velocity.SizeSquared();
    Acceleration += DragForce / Mass;

    // Update velocity
    Velocity += Acceleration * DeltaTime;

    // Simple ground collision (very basic)
    if (GetOwner()->GetActorLocation().Z < 0.0f)
    {
        Velocity.Z = FMath::Abs(Velocity.Z) * 0.5f; // Bounce with energy loss
        FVector Location = GetOwner()->GetActorLocation();
        Location.Z = 0.0f;
        GetOwner()->SetActorLocation(Location);
    }
}

void UCustomPhysicsComponent::AddForce(FVector Force)
{
    Acceleration += Force / Mass;
}
