#pragma once

#include <vector>
#include <memory>

namespace CustomPhysics {

// Basic vector math for simplicity
struct Vector3 {
    float x, y, z;

    Vector3(float x = 0, float y = 0, float z = 0) : x(x), y(y), z(z) {}

    Vector3 operator+(const Vector3& other) const {
        return Vector3(x + other.x, y + other.y, z + other.z);
    }

    Vector3& operator+=(const Vector3& other) {
        x += other.x; y += other.y; z += other.z;
        return *this;
    }

    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }
};

// Rigid body class
class RigidBody {
public:
    RigidBody(float mass, const Vector3& position, const Vector3& velocity = Vector3())
        : mass(mass), position(position), velocity(velocity) {}

    void ApplyForce(const Vector3& force, float deltaTime) {
        Vector3 acceleration = force * (1.0f / mass);
        velocity += acceleration * deltaTime;
    }

    void Update(float deltaTime) {
        position += velocity * deltaTime;
    }

    Vector3 GetPosition() const { return position; }
    Vector3 GetVelocity() const { return velocity; }

private:
    float mass;
    Vector3 position;
    Vector3 velocity;
};

// Physics world class
class PhysicsWorld {
public:
    void AddRigidBody(std::shared_ptr<RigidBody> body) {
        bodies.push_back(body);
    }

    void Update(float deltaTime) {
        for (auto& body : bodies) {
            body->Update(deltaTime);
        }
    }

    const std::vector<std::shared_ptr<RigidBody>>& GetBodies() const {
        return bodies;
    }

private:
    std::vector<std::shared_ptr<RigidBody>> bodies;
};

} // namespace CustomPhysics
