```csharp
using System;
using System.Runtime.InteropServices;
using UnityEngine;

public class PhysicsIntegration : MonoBehaviour
{
    [DllImport("CustomPhysicsPlugin")]
    private static extern IntPtr CreatePhysicsWorld();

    [DllImport("CustomPhysicsPlugin")]
    private static extern void AddRigidBody(IntPtr world, float mass, float x, float y, float z);

    [DllImport("CustomPhysicsPlugin")]
    private static extern void UpdatePhysicsWorld(IntPtr world, float deltaTime);

    [DllImport("CustomPhysicsPlugin")]
    private static extern void GetBodyPosition(IntPtr world, int index, out float x, out float y, out float z);

    private IntPtr physicsWorld;
    private GameObject[] physicsObjects;

    void Start()
    {
        physicsWorld = CreatePhysicsWorld();

        // Create some rigid bodies
        AddRigidBody(physicsWorld, 1.0f, 0, 5, 0);
        AddRigidBody(physicsWorld, 2.0f, 2, 5, 0);

        // Create visual representations
        physicsObjects = new GameObject[2];
        for (int i = 0; i < 2; i++)
        {
            physicsObjects[i] = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            physicsObjects[i].transform.localScale = Vector3.one * 0.5f;
        }
    }

    void Update()
    {
        UpdatePhysicsWorld(physicsWorld, Time.deltaTime);

        // Update visual positions
        for (int i = 0; i < physicsObjects.Length; i++)
        {
            GetBodyPosition(physicsWorld, i, out float x, out float y, out float z);
            physicsObjects[i].transform.position = new Vector3(x, y, z);
        }
    }
}
