```cpp
#include "CustomPhysicsComponent.h"

UCustomPhysicsComponent::UCustomPhysicsComponent()
{
    PrimaryComponentTick.bCanEverTick = true;
    PrimaryComponentTick.TickGroup = TG_PrePhysics;
}

void UCustomPhysicsComponent::BeginPlay()
{
    Super::BeginPlay();
}

void UCustomPhysicsComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
{
    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

    // Simple Euler integration for physics
    if (Mass > 0.0f)
    {
        // Linear motion
        Acceleration = (Acceleration - Velocity * DragCoefficient) / Mass;
        Velocity += Acceleration * DeltaTime;
        GetOwner()->AddActorWorldOffset(Velocity * DeltaTime);

        // Angular motion
        AngularAcceleration = (AngularAcceleration - AngularVelocity * AngularDragCoefficient) / Mass;
        AngularVelocity += AngularAcceleration * DeltaTime;
        FQuat RotationDelta(AngularVelocity * DeltaTime, 0.0f);
        GetOwner()->AddActorWorldRotation(RotationDelta);

        // Reset accelerations
        Acceleration = FVector::ZeroVector;
        AngularAcceleration = FVector::ZeroVector;
    }
}

void UCustomPhysicsComponent::ApplyForce(const FVector& Force)
{
    Acceleration += Force;
}

void UCustomPhysicsComponent::ApplyTorque(const FVector& Torque)
{
    AngularAcceleration += Torque;
}
