}

void RigidBodyComponent::Initialize() {
    // Initialization code
}

void RigidBodyComponent::Update(float deltaTime) {
    // Simple Euler integration
    m_acceleration = m_forceAccumulator / m_mass;
    m_velocity += m_acceleration * deltaTime;

    // Apply velocity to transform
    if (GetOwner()) {
        Vector3 position = GetOwner()->GetTransform().GetPosition();
        position += m_velocity * deltaTime;
        GetOwner()->GetTransform().SetPosition(position);
    }

    // Clear forces for next frame
    m_forceAccumulator = Vector3::Zero;
}

void RigidBodyComponent::SetMass(float mass) {
    m_mass = mass > 0.0f ? mass : 0.0001f; // Prevent division by zero
}

