```cpp
#include "CustomPhysics.h"
#include "RigidBody.h"

namespace CustomPhysics {

PhysicsEngine::PhysicsEngine(float gravity)
    : m_gravity(gravity) {}

PhysicsEngine::~PhysicsEngine() = default;

void PhysicsEngine::Update(float deltaTime) {
    for (auto& body : m_rigidBodies) {
        // Apply gravity
        body->ApplyForce(glm::vec3(0, m_gravity * body->GetMass(), 0));

        // Semi-implicit Euler integration
        glm::vec3 acceleration = body->GetAcceleration();
        body->SetVelocity(body->GetVelocity() + acceleration * deltaTime);
        body->SetPosition(body->GetPosition() + body->GetVelocity() * deltaTime);

        // Reset force accumulator
        body->ApplyForce(glm::vec3(0));
    }
}

RigidBody* PhysicsEngine::CreateRigidBody() {
    m_rigidBodies.push_back(std::make_unique<RigidBody>());
    return m_rigidBodies.back().get();
}

void PhysicsEngine::RemoveRigidBody(RigidBody* body) {
    auto it = std::remove_if(m_rigidBodies.begin(), m_rigidBodies.end(),
        [body](const std::unique_ptr<RigidBody>& rb) { return rb.get() == body; });
    m_rigidBodies.erase(it, m_rigidBodies.end());
}

} // namespace CustomPhysics
```

