```cpp
#include "PhysicsWorld.h"

UPhysicsWorld::UPhysicsWorld()
{
}

void UPhysicsWorld::AddPhysicsObject(UPhysicsObject* Object)
{
    if (Object && !PhysicsObjects.Contains(Object))
    {
        PhysicsObjects.Add(Object);
    }
}

void UPhysicsWorld::RemovePhysicsObject(UPhysicsObject* Object)
{
    PhysicsObjects.Remove(Object);
}

void UPhysicsWorld::UpdateWorld(float DeltaTime)
{
    // Update all objects
    for (UPhysicsObject* Object : PhysicsObjects)
    {
        if (Object)
        {
            Object->Update(DeltaTime);
        }
    }

    // Handle collisions
    HandleCollisions();
}

void UPhysicsWorld::HandleCollisions()
{
    // Simple O(n^2) collision detection
    for (int32 i = 0; i < PhysicsObjects.Num(); i++)
    {
        for (int32 j = i + 1; j < PhysicsObjects.Num(); j++)
        {
            UPhysicsObject* ObjA = PhysicsObjects[i];
            UPhysicsObject* ObjB = PhysicsObjects[j];

            if (ObjA && ObjB && ObjA->CheckCollision(ObjB))
            {
                // Simple elastic collision response
                FVector normal = (ObjB->Position - ObjA->Position).GetSafeNormal();
                float relativeVelocity = FVector::DotProduct(ObjB->Velocity - ObjA->Velocity, normal);

                if (relativeVelocity < 0.0f)
                {
                    float impulse = -2.0f * relativeVelocity / (1.0f / ObjA->Mass + 1.0f / ObjB->Mass);

                    ObjA->Velocity -= normal * (impulse / ObjA->Mass);
                    ObjB->Velocity += normal * (impulse / ObjB->Mass);
                }
            }
        }
    }
}
```

