# Real-Time Physics Simulation with Rigid Body Dynamics

Below is an initial implementation of a real-time physics simulation with rigid body dynamics and frame-rate constraints. This implementation uses a simple fixed-time-step approach with interpolation for smooth rendering.

```python
import numpy as np
from typing import List, Optional
import time

class Vector3:
    def __init__(self, x: float = 0.0, y: float = 0.0, z: float = 0.0):
        self.x = x
        self.y = y
        self.z = z

    def __add__(self, other):
        return Vector3(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other):
        return Vector3(self.x - other.x, self.y - other.y, self.z - other.z)

    def __mul__(self, scalar: float):
        return Vector3(self.x * scalar, self.y * scalar, self.z * scalar)

    def __rmul__(self, scalar: float):
        return self.__mul__(scalar)

    def dot(self, other):
        return self.x * other.x + self.y * other.y + self.z * other.z

    def cross(self, other):
        return Vector3(
            self.y * other.z - self.z * other.y,
            self.z * other.x - self.x * other.z,
            self.x * other.y - self.y * other.x
        )

    def length(self):
        return np.sqrt(self.x**2 + self.y**2 + self.z**2)

    def normalize(self):
        len = self.length()
        if len > 0:
            return self * (1.0 / len)
        return Vector3(0, 0, 0)

    def to_array(self):
        return np.array([self.x, self.y, self.z])

class RigidBody:
    def __init__(self, mass: float, position: Vector3, velocity: Vector3,
                 orientation: Vector3 = Vector3(0, 0, 0),
                 angular_velocity: Vector3 = Vector3(0, 0, 0)):
        self.mass = mass
        self.inv_mass = 1.0 / mass if mass != 0 else 0.0
        self.position = position
        self.velocity = velocity
        self.orientation = orientation
        self.angular_velocity = angular_velocity

        # For interpolation
        self.prev_position = position
        self.prev_orientation = orientation

    def apply_force(self, force: Vector3, dt: float):
        acceleration = force * self.inv_mass
        self.velocity += acceleration * dt

    def apply_impulse(self, impulse: Vector3):
        self.velocity += impulse * self.inv_mass

    def apply_torque(self, torque: Vector3, dt: float):
        # Simplified moment of inertia (assuming uniform sphere)
        # In a real implementation, this would be more complex
        inertia = 1.0  # Placeholder
        angular_acceleration = torque * (1.0 / inertia)
        self.angular_velocity += angular_acceleration * dt

    def integrate(self, dt: float):
        # Store previous state for interpolation
        self.prev_position = self.position
        self.prev_orientation = self.orientation

        # Update position and orientation
        self.position += self.velocity * dt
        self.orientation += self.angular_velocity * dt

class PhysicsWorld:
    def __init__(self, gravity: Vector3 = Vector3(0, -9.81, 0)):
        self.gravity = gravity
        self.bodies: List[RigidBody] = []
        self.time_accumulator = 0.0
        self.fixed_time_step = 1.0 / 60.0  # 60 FPS physics update
        self.max_sub_steps = 5  # Prevent spiral of death

    def add_body(self, body: RigidBody):
        self.bodies.append(body)

    def step(self, dt: float):
        # Frame-rate independent fixed time step
        self.time_accumulator += dt

        # Limit the maximum time step to prevent spiral of death
        if self.time_accumulator > self.fixed_time_step * self.max_sub_steps:
            self.time_accumulator = self.fixed_time_step * self.max_sub_steps

        # Perform multiple fixed time steps if needed
        steps = 0
        while self.time_accumulator >= self.fixed_time_step:
            self._fixed_step(self.fixed_time_step)
            self.time_accumulator -= self.fixed_time_step
            steps += 1

        # Calculate interpolation factor for rendering
        alpha = self.time_accumulator / self.fixed_time_step if steps > 0 else 0.0

        return alpha

    def _fixed_step(self, dt: float):
        # Apply gravity and integrate
        for body in self.bodies:
            # Apply gravity
            if body.inv_mass > 0:  # Skip static bodies
                body.apply_force(self.gravity * body.mass, dt)

            # Integrate
            body.integrate(dt)

            # Simple ground collision (for demo purposes)
            if body.position.y < 0:
                body.position.y = 0
                body.velocity.y = -body.velocity.y * 0.8  # Simple bounce with damping

    def get_interpolated_position(self, body: RigidBody, alpha: float) -> Vector3:
        """Interpolate between previous and current position for smooth rendering"""
        return body.prev_position + (body.position - body.prev_position) * alpha

    def get_interpolated_orientation(self, body: RigidBody, alpha: float) -> Vector3:
        """Interpolate between previous and current orientation for smooth rendering"""
        return body.prev_orientation + (body.orientation - body.prev_orientation) * alpha

class PhysicsSimulation:
    def __init__(self):
        self.world = PhysicsWorld()
        self.last_time = time.time()
        self.running = False

    def add_body(self, mass: float, position: Vector3, velocity: Vector3 = Vector3(0, 0, 0)):
        body = RigidBody(mass, position, velocity)
        self.world.add_body(body)
        return body

    def start(self):
        self.running = True
        self.last_time = time.time()
        self._main_loop()

    def _main_loop(self):
        while self.running:
            current_time = time.time()
            dt = current_time - self.last_time
            self.last_time = current_time

            # Step the physics simulation
            alpha = self.world.step(dt)

            # Here you would typically render the scene with interpolation
            # For this example, we'll just print the positions
            for body in self.world.bodies:
                interp_pos = self.world.get_interpolated_position(body, alpha)
                print(f"Body at position: ({interp_pos.x:.2f}, {interp_pos.y:.2f}, {interp_pos.z:.2f})")

            # Simple frame rate control (not exact)
            time.sleep(0.016)  # ~60 FPS

    def stop(self):
        self.running = False

# Example usage
if __name__ == "__main__":
    sim = PhysicsSimulation()

    # Add a few bodies
    sim.add_body(1.0, Vector3(0, 5, 0), Vector3(0, 0, 0))  # Will fall under gravity
    sim.add_body(2.0, Vector3(2, 10, 0), Vector3(0, 0, 0))  # Heavier, will fall faster
    sim.add_body(0.0, Vector3(0, 0, 0), Vector3(0, 0, 0))  # Static ground (mass=0)

    # Start the simulation
    try:
        sim.start()
    except KeyboardInterrupt:
        sim.stop()
```

## Key Features of This Implementation:

1. **Fixed Time Step Physics**: Uses a fixed time step (1/60th of a second) for stable physics simulation.

2. **Variable Frame Rate Handling**: Accumulates time and performs multiple fixed steps when needed.

3. **Interpolation for Smooth Rendering**: Uses linear interpolation between physics states for smooth visuals.

4. **Basic Rigid Body Dynamics**: Includes position, velocity, and simple collision response.

5. **Frame Rate Control**: Simple sleep-based frame rate control (in a real application, you'd use vsync).

6. **Vector Math**: Basic 3D vector operations for physics calculations.

## Limitations and Areas for Improvement:

1. **Collision Detection**: Currently only has simple ground collision. A proper collision system would be needed.

2. **Rotation**: Orientation is represented as Euler angles (simplified). Quaternions would be better.

3. **Performance**: This is a simple Python implementation. A real physics engine would use more efficient data structures.

4. **Error Handling**: Basic error handling is included, but more robust handling would be needed.

5. **Visualization**: The example just prints positions. A real application would need rendering.

This implementation provides a foundation that you can build upon to create a more complete physics simulation.

# Payment Processing Service for a Large Financial Institution

Below is a comprehensive implementation of a payment processing service for a financial institution. This includes core components like transaction processing, fraud detection, reconciliation, and reporting.

```python
import uuid
import datetime
import hashlib
import json
from enum import Enum
from typing import Optional, Dict, List
from dataclasses import dataclass
from abc import ABC, abstractmethod
import logging
from decimal import Decimal
import threading
import time

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class PaymentStatus(Enum):
    PENDING = "PENDING"
    PROCESSING = "PROCESSING"
    COMPLETED = "COMPLETED"
    FAILED = "FAILED"
    REVERSED = "REVERSED"
    REFUNDED = "REFUNDED"

class PaymentMethod(Enum):
    CREDIT_CARD = "CREDIT_CARD"
    DEBIT_CARD = "DEBIT_CARD"
    ACH = "ACH"
    WIRE = "WIRE"
    CHECK = "CHECK"
    CRYPTO = "CRYPTO"

class Currency(Enum):
    USD = "USD"
    EUR = "EUR"
    GBP = "GBP"
    JPY = "JPY"
    CAD = "CAD"
    AUD = "AUD"

@dataclass
class PaymentRequest:
    amount: Decimal
    currency: Currency
    payment_method: PaymentMethod
    source_account: str
    destination_account: str
    merchant_id: str
    customer_id: str
    description: Optional[str] = None
    metadata: Optional[Dict] = None
    fraud_check_required: bool = True

@dataclass
class PaymentResponse:
    payment_id: str
    status: PaymentStatus
    transaction_time: datetime.datetime
    confirmation_code: Optional[str] = None
    error_message: Optional[str] = None

@dataclass
class FraudCheckResult:
    is_fraudulent: bool
    risk_score: float
    reasons: List[str]

class PaymentProcessor(ABC):
    @abstractmethod
    def process_payment(self, payment_request: PaymentRequest) -> PaymentResponse:
        pass

    @abstractmethod
    def reverse_payment(self, payment_id: str) -> PaymentResponse:
        pass

    @abstractmethod
    def refund_payment(self, payment_id: str, amount: Decimal) -> PaymentResponse:
        pass

class FraudDetectionService:
    def __init__(self):
        # In a real implementation, this would connect to a fraud detection API
        self.rules = {
            "velocity": {"max_transactions": 5, "time_window": datetime.timedelta(minutes=15)},
            "amount": {"threshold": Decimal(10000.00)},
            "geolocation": {"allowed_countries": ["US", "CA", "UK"]}
        }
        self.transaction_history = {}

    def check_payment(self, payment_request: PaymentRequest) -> FraudCheckResult:
        risk_score = 0.0
        reasons = []

        # Check transaction velocity
        customer_id = payment_request.customer_id
        now = datetime.datetime.now()

        if customer_id in self.transaction_history:
            recent_transactions = [
                t for t in self.transaction_history[customer_id]
                if now - t["timestamp"] <= self.rules["velocity"]["time_window"]
            ]

            if len(recent_transactions) >= self.rules["velocity"]["max_transactions"]:
                risk_score += 0.3
                reasons.append("High transaction velocity")

        # Check transaction amount
        if payment_request.amount > self.rules["amount"]["threshold"]:
            risk_score += 0.4
            reasons.append("Transaction amount exceeds threshold")

        # Check geolocation (simplified)
        # In reality, this would use IP geolocation services
        if payment_request.currency not in [Currency.USD, Currency.CAD, Currency.GBP]:
            risk_score += 0.2
            reasons.append("Unusual currency for customer location")

        # Add to transaction history
        if customer_id not in self.transaction_history:
            self.transaction_history[customer_id] = []

        self.transaction_history[customer_id].append({
            "timestamp": now,
            "amount": payment_request.amount,
            "currency": payment_request.currency
        })

        is_fraudulent = risk_score >= 0.7

        return FraudCheckResult(
            is_fraudulent=is_fraudulent,
            risk_score=risk_score,
            reasons=reasons
        )

class PaymentGateway(PaymentProcessor):
    def __init__(self):
        self.fraud_service = FraudDetectionService()
        self.payment_records = {}
        self.lock = threading.Lock()

    def _generate_payment_id(self) -> str:
        return str(uuid.uuid4())

    def _generate_confirmation_code(self) -> str:
        return hashlib.sha256(str(uuid.uuid4()).encode()).hexdigest()[:12].upper()

    def _validate_payment_request(self, payment_request: PaymentRequest) -> bool:
        if payment_request.amount <= Decimal(0):
            return False
        if not payment_request.source_account or not payment_request.destination_account:
            return False
        return True

    def process_payment(self, payment_request: PaymentRequest) -> PaymentResponse:
        if not self._validate_payment_request(payment_request):
            return PaymentResponse(
                payment_id=self._generate_payment_id(),
                status=PaymentStatus.FAILED,
                transaction_time=datetime.datetime.now(),
                error_message="Invalid payment request"
            )

        payment_id = self._generate_payment_id()
        transaction_time = datetime.datetime.now()

        # Fraud check
        if payment_request.fraud_check_required:
            fraud_result = self.fraud_service.check_payment(payment_request)
            if fraud_result.is_fraudulent:
                logger.warning(f"Fraud detected for payment {payment_id}: {fraud_result.reasons}")
                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.FAILED,
                    transaction_time=transaction_time,
                    error_message=f"Fraud detected: {', '.join(fraud_result.reasons)}"
                )

        # Process payment based on method
        try:
            with self.lock:
                # Simulate processing delay
                time.sleep(0.1)

                # In a real implementation, this would connect to actual payment processors
                confirmation_code = self._generate_confirmation_code()

                # Store payment record
                self.payment_records[payment_id] = {
                    "request": payment_request,
                    "status": PaymentStatus.COMPLETED,
                    "transaction_time": transaction_time,
                    "confirmation_code": confirmation_code,
                    "amount_processed": payment_request.amount
                }

                logger.info(f"Payment processed successfully: {payment_id}")

                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.COMPLETED,
                    transaction_time=transaction_time,
                    confirmation_code=confirmation_code
                )
        except Exception as e:
            logger.error(f"Payment processing failed: {str(e)}")
            return PaymentResponse(
                payment_id=payment_id,
                status=PaymentStatus.FAILED,
                transaction_time=transaction_time,
                error_message=str(e)
            )

    def reverse_payment(self, payment_id: str) -> PaymentResponse:
        with self.lock:
            if payment_id not in self.payment_records:
                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.FAILED,
                    transaction_time=datetime.datetime.now(),
                    error_message="Payment not found"
                )

            record = self.payment_records[payment_id]
            if record["status"] != PaymentStatus.COMPLETED:
                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.FAILED,
                    transaction_time=datetime.datetime.now(),
                    error_message="Payment cannot be reversed in current state"
                )

            # Simulate reversal
            time.sleep(0.1)

            record["status"] = PaymentStatus.REVERSED
            logger.info(f"Payment reversed: {payment_id}")

            return PaymentResponse(
                payment_id=payment_id,
                status=PaymentStatus.REVERSED,
                transaction_time=datetime.datetime.now()
            )

    def refund_payment(self, payment_id: str, amount: Decimal) -> PaymentResponse:
        with self.lock:
            if payment_id not in self.payment_records:
                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.FAILED,
                    transaction_time=datetime.datetime.now(),
                    error_message="Payment not found"
                )

            record = self.payment_records[payment_id]
            if record["status"] != PaymentStatus.COMPLETED:
                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.FAILED,
                    transaction_time=datetime.datetime.now(),
                    error_message="Payment cannot be refunded in current state"
                )

            if amount > record["amount_processed"]:
                return PaymentResponse(
                    payment_id=payment_id,
                    status=PaymentStatus.FAILED,
                    transaction_time=datetime.datetime.now(),
                    error_message="Refund amount exceeds payment amount"
                )

            # Simulate refund processing
            time.sleep(0.1)

            # Update record
            record["amount_processed"] -= amount
            if record["amount_processed"] == Decimal(0):
                record["status"] = PaymentStatus.REFUNDED
            else:
                record["status"] = PaymentStatus.PARTIALLY_REFUNDED  # Assuming we have this status

            logger.info(f"Payment refunded: {payment_id}, amount: {amount}")

            return PaymentResponse(
                payment_id=payment_id,
                status=PaymentStatus.REFUNDED,
                transaction_time=datetime.datetime.now()
            )

class ReconciliationService:
    def __init__(self, payment_gateway: PaymentGateway):
        self.payment_gateway = payment_gateway
        self.reconciliation_records = {}

    def generate_daily_reconciliation(self, date: datetime.date) -> Dict:
        """Generate reconciliation report for a given date"""
        report = {
            "date": date,
            "total_transactions": 0,
            "total_amount": Decimal(0),
            "by_payment_method": {},
            "discrepancies": []
        }

        for payment_id, record in self.payment_gateway.payment_records.items():
            transaction_date = record["transaction_time"].date()
            if transaction_date != date:
                continue

            report["total_transactions"] += 1
            report["total_amount"] += record["amount_processed"]

            method = record["request"].payment_method.value
            if method not in report["by_payment_method"]:
                report["by_payment_method"][method] = {
                    "count": 0,
                    "amount": Decimal(0)
                }

            report["by_payment_method"][method]["count"] += 1
            report["by_payment_method"][method]["amount"] += record["amount_processed"]

            # Check for discrepancies (simplified)
            if record["status"] == PaymentStatus.FAILED and record["request"].amount > Decimal(100):
                report["discrepancies"].append({
                    "payment_id": payment_id,
                    "amount": record["request"].amount,
                    "reason": "Failed high-value transaction"
                })

        self.reconciliation_records[date] = report
        return report

    def compare_with_bank_statement(self, date: datetime.date, bank_statement: Dict) -> Dict:
        """Compare reconciliation report with bank statement"""
        if date not in self.reconciliation_records:
            raise ValueError("Reconciliation report not found for this date")

        report = self.reconciliation_records[date]
        comparison = {
            "date": date,
            "matches": True,
            "differences": []
        }

        # Compare total amount
        if report["total_amount"] != bank_statement["total_amount"]:
            comparison["matches"] = False
            comparison["differences"].append({
                "field": "total_amount",
                "expected": report["total_amount"],
                "actual": bank_statement["total_amount"]
            })

        # Compare by payment method
        for method, data in report["by_payment_method"].items():
            if method not in bank_statement["by_payment_method"]:
                comparison["matches"] = False
                comparison["differences"].append({
                    "field": f"payment_method_{method}",
                    "expected": data["amount"],
                    "actual": Decimal(0)
                })
            elif data["amount"] != bank_statement["by_payment_method"][method]["amount"]:
                comparison["matches"] = False
                comparison["differences"].append({
                    "field": f"payment_method_{method}",
                    "expected": data["amount"],
                    "actual": bank_statement["by_payment_method"][method]["amount"]
                })

        return comparison

class PaymentService:
    def __init__(self):
        self.payment_gateway = PaymentGateway()
        self.reconciliation_service = ReconciliationService(self.payment_gateway)

    def process_payment(self, payment_request: PaymentRequest) -> PaymentResponse:
        return self.payment_gateway.process_payment(payment_request)

    def reverse_payment(self, payment_id: str) -> PaymentResponse:
        return self.payment_gateway.reverse_payment(payment_id)

    def refund_payment(self, payment_id: str, amount: Decimal) -> PaymentResponse:
        return self.payment_gateway.refund_payment(payment_id, amount)

    def generate_reconciliation_report(self, date: datetime.date) -> Dict:
        return self.reconciliation_service.generate_daily_reconciliation(date)

    def reconcile_with_bank(self, date: datetime.date, bank_statement: Dict) -> Dict:
        return self.reconciliation_service.compare_with_bank_statement(date, bank_statement)

