    @Override
    public FraudCheckResult checkForFraud(PaymentRequest request) {
        // Check against fraud rules
        List<FraudRule> rules = fraudRuleRepository.findAllActiveRules();
        for (FraudRule rule : rules) {
            if (rule.matches(request)) {
                return new FraudCheckResult(true, rule.getDescription());
            }
        }

        // Check transaction history for suspicious patterns
        if (transactionHistoryService.hasSuspiciousPatterns(request.getAccountId())) {
            return new FraudCheckResult(true, "Suspicious transaction patterns detected");
        }

        return new FraudCheckResult(false, null);
    }
