  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id            String    @id @default(uuid())
  email         String    @unique
  passwordHash  String
  firstName     String
  lastName      String
  roles         Role[]    @relation("UserRoles")
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt
}

model Role {
  id          String    @id @default(uuid())
  name        String    @unique
  description String?
  users       User[]    @relation("UserRoles")
  permissions Permission[] @relation("RolePermissions")
}

model Permission {
  id          String    @id @default(uuid())
  name        String    @unique
  description String?
  roles       Role[]    @relation("RolePermissions")
}

model Customer {
  id            String    @id @default(uuid())
  name          String
  industry      String
  contactEmail  String
  contactPhone  String?
  erpId         String?   @unique
  crmId         String?   @unique
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt
}

model Order {
  id            String    @id @default(uuid())
  customerId    String
  customer      Customer  @relation(fields: [customerId], references: [id])
  orderNumber   String    @unique
  status        OrderStatus
  totalAmount   Float
  currency      String    @default("USD")
  items         OrderItem[]
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt
}

model OrderItem {
  id            String    @id @default(uuid())
  orderId       String
  order         Order     @relation(fields: [orderId], references: [id])
  productCode   String
  description   String
  quantity      Int
  unitPrice     Float
  totalPrice    Float
}

enum OrderStatus {
  DRAFT
  PENDING_APPROVAL
  APPROVED
  PROCESSING
  SHIPPED
  DELIVERED
  CANCELLED
}
