## API Controller Example

```typescript
// src/controllers/customerController.ts
import { Request, Response, NextFunction } from 'express';
import { PrismaClient, Customer } from '@prisma/client';
import { logger } from '../utils/logger';
import { erpService } from '../services/erpService';
import { crmService } from '../services/crmService';

const prisma = new PrismaClient();

interface CreateCustomerRequest {
  name: string;
  industry: string;
  contactEmail: string;
  contactPhone?: string;
}

interface UpdateCustomerRequest {
  name?: string;
  industry?: string;
  contactEmail?: string;
  contactPhone?: string;
}

export class CustomerController {
  public async createCustomer(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const { name, industry, contactEmail, contactPhone } = req.body as CreateCustomerRequest;

      // Validate input
      if (!name || !industry || !contactEmail) {
        res.status(400).json({ message: 'Missing required fields' });
        return;
      }

      // Create customer in local database
      const customer = await prisma.customer.create({
        data: {
          name,
          industry,
          contactEmail,
          contactPhone
        }
      });

      // Sync with ERP system
      const erpResponse = await erpService.createCustomer({
        name: customer.name,
        industry: customer.industry,
        email: customer.contactEmail,
        phone: customer.contactPhone || ''
      });

      // Sync with CRM system
      const crmResponse = await crmService.createCustomer({
        firstName: customer.name.split(' ')[0],
        lastName: customer.name.split(' ').slice(1).join(' '),
        email: customer.contactEmail,
        phone: customer.contactPhone || '',
        company: customer.name,
        industry: customer.industry
      });

      // Update customer with external IDs
      await prisma.customer.update({
        where: { id: customer.id },
        data: {
          erpId: erpResponse.customerId,
          crmId: crmResponse.customerId
        }
      });

      logger.info(`Created customer ${customer.id} with external IDs: ERP=${erpResponse.customerId}, CRM=${crmResponse.customerId}`);

      res.status(201).json(customer);
    } catch (error) {
      next(error);
    }
  }

  public async getCustomer(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const { id } = req.params;

      const customer = await prisma.customer.findUnique({
        where: { id },
        include: {
          orders: true
        }
      });

      if (!customer) {
        res.status(404).json({ message: 'Customer not found' });
        return;
      }

      res.status(200).json(customer);
    } catch (error) {
      next(error);
    }
  }

  public async updateCustomer(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const { id } = req.params;
      const { name, industry, contactEmail, contactPhone } = req.body as UpdateCustomerRequest;

      const existingCustomer = await prisma.customer.findUnique({
        where: { id }
      });

      if (!existingCustomer) {
        res.status(404).json({ message: 'Customer not found' });
        return;
      }

      // Update in local database
      const updatedCustomer = await prisma.customer.update({
        where: { id },
        data: {
          name: name || existingCustomer.name,
          industry: industry || existingCustomer.industry,
          contactEmail: contactEmail || existingCustomer.contactEmail,
          contactPhone: contactPhone || existingCustomer.contactPhone
        }
      });

      // Sync updates with ERP if ID exists
      if (existingCustomer.erpId) {
        await erpService.updateCustomer(existingCustomer.erpId, {
          name: updatedCustomer.name,
          industry: updatedCustomer.industry,
          email: updatedCustomer.contactEmail,
          phone: updatedCustomer.contactPhone || ''
        });
      }

      // Sync updates with CRM if ID exists
      if (existingCustomer.crmId) {
        await crmService.updateCustomer(existingCustomer.crmId, {
          firstName: updatedCustomer.name.split(' ')[0],
          lastName: updatedCustomer.name.split(' ').slice(1).join(' '),
          email: updatedCustomer.contactEmail,
          phone: updatedCustomer.contactPhone || '',
          company: updatedCustomer.name,
          industry: updatedCustomer.industry
        });
      }

      res.status(200).json(updatedCustomer);
    } catch (error) {
      next(error);
    }
  }

  public async deleteCustomer(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const { id } = req.params;

      const customer = await prisma.customer.findUnique({
        where: { id }
      });

      if (!customer) {
        res.status(404).json({ message: 'Customer not found' });
        return;
      }

      // Delete from ERP if ID exists
      if (customer.erpId) {
        await erpService.deleteCustomer(customer.erpId);
      }

      // Delete from CRM if ID exists
      if (customer.crmId) {
        await crmService.deleteCustomer(customer.crmId);
      }

      // Delete from local database
      await prisma.customer.delete({
        where: { id }
      });

      res.status(204).send();
    } catch (error) {
      next(error);
    }
  }
}
