// src/services/erpService.ts
import axios, { AxiosInstance } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';

interface ERPCreateCustomerRequest {
  name: string;
  industry: string;
  email: string;
  phone: string;
}

interface ERPCreateCustomerResponse {
  customerId: string;
  status: string;
}

interface ERPUpdateCustomerRequest {
  name?: string;
  industry?: string;
  email?: string;
  phone?: string;
}

interface ERPUpdateCustomerResponse {
  customerId: string;
  status: string;
}

export class ERPService {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.corporateSystems.erp.baseUrl,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.corporateSystems.erp.apiKey}`
      }
    });

    // Request interceptor for logging
    this.client.interceptors.request.use(request => {
      logger.info(`ERP Request: ${request.method?.toUpperCase()} ${request.url}`);
      return request;
    });

    // Response interceptor for logging and error handling
    this.client.interceptors.response.use(
      response => {
        logger.info(`ERP Response: ${response.status} ${response.config.url}`);
        return response;
      },
      error => {
        logger.error(`ERP Error: ${error.response?.status} ${error.config.url}`);
        return Promise.reject(error);
      }
    );
  }

  public async createCustomer(data: ERPCreateCustomerRequest): Promise<ERPCreateCustomerResponse> {
    try {
      const response = await this.client.post('/customers', data);
      return response.data as ERPCreateCustomerResponse;
    } catch (error) {
      logger.error('Failed to create customer in ERP:', error);
      throw new Error('ERP integration failed');
    }
  }

  public async updateCustomer(customerId: string, data: ERPUpdateCustomerRequest): Promise<ERPUpdateCustomerResponse> {
    try {
      const response = await this.client.put(`/customers/${customerId}`, data);
      return response.data as ERPUpdateCustomerResponse;
    } catch (error) {
      logger.error(`Failed to update customer ${customerId} in ERP:`, error);
      throw new Error('ERP integration failed');
    }
  }

  public async deleteCustomer(customerId: string): Promise<void> {
    try {
      await this.client.delete(`/customers/${customerId}`);
    } catch (error) {
      logger.error(`Failed to delete customer ${customerId} in ERP:`, error);
      throw new Error('ERP integration failed');
    }
  }
}

export const erpService = new ERPService();
