// src/modules/order/order.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Order, OrderStatus } from './order.entity';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderStatusDto } from './dto/update-order-status.dto';
import { ErpService } from '../erp/erp.service';
import { CrmService } from '../crm/crm.service';
import { EventEmitter2 } from '@nestjs/event-emitter';

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    private readonly erpService: ErpService,
    private readonly crmService: CrmService,
    private readonly eventEmitter: EventEmitter2,
  ) {}

  async createOrder(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for customer ${createOrderDto.customerId}`);

    // Validate customer exists in CRM
    const customerExists = await this.crmService.validateCustomer(createOrderDto.customerId);
    if (!customerExists) {
      throw new Error('Customer not found in CRM system');
    }

    // Calculate total amount
    const totalAmount = createOrderDto.items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0,
    );

    const order = this.orderRepository.create({
      ...createOrderDto,
      totalAmount,
      status: 'PENDING',
    });

    const savedOrder = await this.orderRepository.save(order);

    // Emit event for other services to react
    this.eventEmitter.emit('order.created', savedOrder);

    return savedOrder;
  }

  async updateOrderStatus(id: string, updateOrderStatusDto: UpdateOrderStatusDto): Promise<Order> {
    this.logger.log(`Updating status for order ${id} to ${updateOrderStatusDto.status}`);

    const order = await this.orderRepository.findOne({ where: { id } });
    if (!order) {
      throw new Error('Order not found');
    }

    // Validate status transition
    if (!this.isValidStatusTransition(order.status, updateOrderStatusDto.status)) {
      throw new Error(`Invalid status transition from ${order.status} to ${updateOrderStatusDto.status}`);
    }

    order.status = updateOrderStatusDto.status;
    const updatedOrder = await this.orderRepository.save(order);

    // Sync with ERP if status changed to SHIPPED
    if (updateOrderStatusDto.status === 'SHIPPED') {
      await this.erpService.syncOrderShipment(updatedOrder);
    }

    this.eventEmitter.emit('order.status.updated', updatedOrder);

    return updatedOrder;
  }

  private isValidStatusTransition(currentStatus: OrderStatus, newStatus: OrderStatus): boolean {
    const validTransitions: Record<OrderStatus, OrderStatus[]> = {
      PENDING: ['PROCESSING', 'CANCELLED'],
      PROCESSING: ['SHIPPED', 'CANCELLED'],
      SHIPPED: ['DELIVERED'],
      DELIVERED: [],
      CANCELLED: [],
    };

    return validTransitions[currentStatus].includes(newStatus);
  }

  async getOrderById(id: string): Promise<Order> {
    const order = await this.orderRepository.findOne({ where: { id } });
    if (!order) {
      throw new Error('Order not found');
    }
    return order;
  }

  async getOrdersByCustomer(customerId: string): Promise<Order[]> {
    return this.orderRepository.find({ where: { customerId } });
  }
}
