## External System Integration

```typescript
// src/modules/erp/erp.service.ts
import { Injectable, HttpException, HttpStatus } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { Order } from '../order/order.entity';
import { firstValueFrom } from 'rxjs';
import { Logger } from 'winston';

@Injectable()
export class ErpService {
  private readonly erpBaseUrl: string;
  private readonly apiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
    private readonly logger: Logger,
  ) {
    this.erpBaseUrl = this.configService.get<string>('externalServices.erp.baseUrl');
    this.apiKey = this.configService.get<string>('externalServices.erp.apiKey');
  }

  async syncOrderShipment(order: Order): Promise<void> {
    this.logger.info(`Syncing order ${order.id} with ERP system`);

    try {
      const response = await firstValueFrom(
        this.httpService.post(
          `${this.erpBaseUrl}/api/shipments`,
          {
            orderId: order.id,
            customerId: order.customerId,
            items: order.items.map(item => ({
              productId: item.productId,
              quantity: item.quantity,
              sku: item.sku,
            })),
            totalAmount: order.totalAmount,
          },
          {
            headers: {
              'Authorization': `Bearer ${this.apiKey}`,
              'Content-Type': 'application/json',
            },
          },
        ),
      );

      if (response.status !== 201) {
        throw new HttpException('Failed to sync with ERP', HttpStatus.INTERNAL_SERVER_ERROR);
      }

      this.logger.info(`Successfully synced order ${order.id} with ERP`);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} with ERP: ${error.message}`);
      throw new HttpException('ERP integration failed', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }

  async validateInventory(items: { productId: string; quantity: number }[]): Promise<boolean> {
    try {
      const response = await firstValueFrom(
        this.httpService.post(
          `${this.erpBaseUrl}/api/inventory/check`,
          { items },
          {
            headers: {
              'Authorization': `Bearer ${this.apiKey}`,
              'Content-Type': 'application/json',
            },
          },
        ),
      );

      return response.data.allAvailable;
    } catch (error) {
      this.logger.error(`Inventory validation failed: ${error.message}`);
      throw new HttpException('Inventory validation failed', HttpStatus.INTERNAL_SERVER_ERROR);
    }
  }
}
