## Integration with Corporate Systems

```typescript
// src/modules/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { AxiosResponse } from 'axios';
import { Order } from '../../orders/entities/order.entity';
import { ERPOrderResponse } from './interfaces/erp-order-response.interface';

@Injectable()
export class ErpService {
  private readonly logger = new Logger(ErpService.name);
  private readonly baseUrl: string;
  private readonly apiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.baseUrl = this.configService.get<string>('corporateSystems.erp.baseUrl');
    this.apiKey = this.configService.get<string>('corporateSystems.erp.apiKey');
  }

  async syncOrderToERP(order: Order): Promise<ERPOrderResponse> {
    try {
      const erpOrderPayload = this.mapOrderToERPPayload(order);

      const response: AxiosResponse<ERPOrderResponse> = await firstValueFrom(
        this.httpService.post(`${this.baseUrl}/api/orders`, erpOrderPayload, {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      this.logger.log(`Successfully synced order ${order.id} to ERP`);
      return response.data;
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} to ERP: ${error.message}`);
      throw new Error(`ERP synchronization failed: ${error.message}`);
    }
  }

  private mapOrderToERPPayload(order: Order): any {
    // Map our internal order structure to ERP's expected format
    return {
      orderId: order.id,
      orderNumber: order.orderNumber,
      orderDate: order.orderDate.toISOString(),
      customer: {
        name: order.customerName,
        email: order.customerEmail,
        phone: order.customerPhone,
      },
      amount: order.totalAmount,
      currency: order.currency,
      status: this.mapOrderStatusToERP(order.status),
      items: [], // Would be populated with actual order items
    };
  }

  private mapOrderStatusToERP(status: OrderStatus): string {
    const statusMap = {
      [OrderStatus.PENDING]: 'NEW',
      [OrderStatus.PROCESSING]: 'IN_PROGRESS',
      [OrderStatus.SHIPPED]: 'SHIPPED',
      [OrderStatus.DELIVERED]: 'DELIVERED',
      [OrderStatus.CANCELLED]: 'CANCELLED',
    };

    return statusMap[status] || 'UNKNOWN';
  }
}
