  }

  @Post(':id/sync-erp')
  @Roles(Role.ADMIN, Role.MANAGER)
  @ApiOperation({ summary: 'Sync order to ERP system' })
  @ApiResponse({ status: 200, description: 'Order synced to ERP successfully' })
  @ApiResponse({ status: 400, description: 'Bad Request' })
  @ApiResponse({ status: 403, description: 'Forbidden' })
  @ApiResponse({ status: 404, description: 'Order not found' })
  async syncToERP(@Param('id') id: string): Promise<void> {
    return this.ordersService.syncToERP(id);
  }
}
