## Integration with Corporate Systems

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios, { AxiosInstance } from 'axios';
import { Order } from '../../orders/entities/order.entity';
import { ERPOrderResponseDto } from './dto/erp-order-response.dto';

@Injectable()
export class ERPService {
  private readonly logger = new Logger(ERPService.name);
  private readonly erpClient: AxiosInstance;

  constructor(private configService: ConfigService) {
    this.erpClient = axios.create({
      baseURL: this.configService.get('ERP_API_BASE_URL'),
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${this.configService.get('ERP_API_KEY')}`,
      },
      timeout: 5000,
    });
  }

  async syncOrderToERP(order: Order): Promise<ERPOrderResponseDto> {
    try {
      this.logger.log(`Syncing order ${order.orderReference} to ERP`);

      const erpOrderPayload = this.mapOrderToERPPayload(order);

      const response = await this.erpClient.post<ERPOrderResponseDto>(
        '/api/orders',
        erpOrderPayload,
      );

      this.logger.log(`Successfully synced order ${order.orderReference} to ERP`);
      return response.data;
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.orderReference} to ERP: ${error.message}`);
      throw error;
    }
  }

  private mapOrderToERPPayload(order: Order): any {
    return {
      orderNumber: order.orderReference,
      customerId: order.customerId,
      orderDate: order.createdAt.toISOString(),
      requestedDeliveryDate: order.requestedDeliveryDate?.toISOString(),
      totalAmount: order.totalAmount,
      items: order.items.map(item => ({
        productCode: item.productSku,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
        lineTotal: item.quantity * item.unitPrice,
      })),
    };
  }
}
