## Service Layer with Dependency Injection

```typescript
// src/services/userService.ts
import { PrismaClient, User } from '@prisma/client';
import { CreateUserDto, UpdateUserDto } from '../types/dto';
import { logger } from '../utils/logger';
import { hashPassword } from '../utils/auth';

export class UserService {
  constructor(private prisma: PrismaClient) {}

  async createUser(userData: CreateUserDto): Promise<User> {
    try {
      const hashedPassword = await hashPassword(userData.password);

      const user = await this.prisma.user.create({
        data: {
          ...userData,
          password: hashedPassword
        }
      });

      logger.info('User created successfully', { userId: user.id });
      return user;
    } catch (error) {
      logger.error('Failed to create user', { error, userData });
      throw error;
    }
  }

  async getUserById(id: string): Promise<User | null> {
    try {
      return await this.prisma.user.findUnique({
        where: { id }
      });
    } catch (error) {
      logger.error('Failed to fetch user', { error, userId: id });
      throw error;
    }
  }

  async updateUser(id: string, updateData: UpdateUserDto): Promise<User> {
    try {
      const user = await this.prisma.user.update({
        where: { id },
        data: updateData
      });

      logger.info('User updated successfully', { userId: id });
      return user;
    } catch (error) {
      logger.error('Failed to update user', { error, userId: id });
      throw error;
    }
  }

  async deleteUser(id: string): Promise<User> {
    try {
      const user = await this.prisma.user.delete({
        where: { id }
      });

      logger.info('User deleted successfully', { userId: id });
      return user;
    } catch (error) {
      logger.error('Failed to delete user', { error, userId: id });
      throw error;
    }
  }

  async searchUsers(query: string, page: number = 1, pageSize: number = 10): Promise<{ users: User[]; total: number }> {
    try {
      const skip = (page - 1) * pageSize;

      const [users, total] = await this.prisma.$transaction([
        this.prisma.user.findMany({
          where: {
            OR: [
              { firstName: { contains: query, mode: 'insensitive' } },
              { lastName: { contains: query, mode: 'insensitive' } },
              { email: { contains: query, mode: 'insensitive' } },
              { username: { contains: query, mode: 'insensitive' } }
            ]
          },
          skip,
          take: pageSize,
          orderBy: { createdAt: 'desc' }
        }),
        this.prisma.user.count({
          where: {
            OR: [
              { firstName: { contains: query, mode: 'insensitive' } },
              { lastName: { contains: query, mode: 'insensitive' } },
              { email: { contains: query, mode: 'insensitive' } },
              { username: { contains: query, mode: 'insensitive' } }
            ]
          }
        })
      ]);

      return { users, total };
    } catch (error) {
      logger.error('Failed to search users', { error, query });
      throw error;
    }
