## Integration Service with External Systems

```typescript
// src/services/integrationService.ts
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { PrismaClient } from '@prisma/client';
import { config } from '../config';
import { logger } from '../utils/logger';
import { ERPSystemResponse } from '../types/models';

export class IntegrationService {
  private erpClient: AxiosInstance;

  constructor(private prisma: PrismaClient) {
    this.erpClient = axios.create({
      baseURL: config.ERP_SYSTEM_URL,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.ERP_SYSTEM_API_KEY}`
      },
      timeout: 10000
    });

    // Request interceptor
    this.erpClient.interceptors.request.use((config) => {
      logger.debug('ERP System Request', {
        method: config.method,
        url: config.url,
        data: config.data
      });
      return config;
    });

    // Response interceptor
    this.erpClient.interceptors.response.use(
      (response) => {
        logger.debug('ERP System Response', {
          status: response.status,
          data: response.data
        });
        return response;
      },
      (error) => {
        logger.error('ERP System Error', {
          message: error.message,
          config: error.config,
          response: error.response?.data
        });
        return Promise.reject(error);
      }
    );
  }

  async syncUserToERP(userId: string): Promise<ERPSystemResponse<any>> {
    try {
      const user = await this.prisma.user.findUnique({
        where: { id: userId },
        select: {
          id: true,
          username: true,
          email: true,
          firstName: true,
          lastName: true,
          department: true,
          role: true,
          isActive: true
        }
      });

      if (!user) {
        throw new Error('User not found');
      }

      const response: AxiosResponse<ERPSystemResponse<any>> = await this.erpClient.post('/api/users/sync', {
        userId: user.id,
        username: user.username,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        department: user.department,
        role: user.role,
        isActive: user.isActive
      });

      await this.prisma.integrationLog.create({
        data: {
          systemName: 'ERP',
          operation: 'syncUser',
          status: 'success',
          requestData: {
            userId: user.id,
            username: user.username,
            email: user.email
          },
          responseData: response.data
        }
      });

      return response.data;
    } catch (error) {
      await this.prisma.integrationLog.create({
        data: {
          systemName: 'ERP',
          operation: 'syncUser',
          status: 'error',
          requestData: { userId },
          errorDetails: error instanceof Error ? error.message : 'Unknown error'
        }
      });

      throw error;
    }
  }

  async getERPUserDetails(userId: string): Promise<ERPSystemResponse<any>> {
    try {
      const response = await this.erpClient.get(`/api/users/${userId}`);
      return response.data;
    } catch (error) {
      throw error;
    }
  }
}
