export class UserController {
  constructor(
    private userService: UserService,
    private integrationService: IntegrationService
  ) {}

  async createUser(req: Request<{}, {}, CreateUserDto>, res: Response, next: NextFunction) {
    try {
      const user = await this.userService.createUser(req.body);

      // Sync with ERP system in background
      this.integrationService.syncUserToERP(user.id)
        .catch(err => logger.error('ERP sync failed', { error: err, userId: user.id }));

      res.status(201).json({
        status: 'success',
        data: user
      });
    } catch (error) {
      next(new AppError('Failed to create user', 400, error));
    }
  }

  async getUser(req: Request<{ id: string }>, res: Response, next: NextFunction) {
    try {
      const user = await this.userService.getUserById(req.params.id);

      if (!user) {
        return next(new AppError('User not found', 404));
      }

      res.status(200).json({
        status: 'success',
        data: user
      });
    } catch (error) {
      next(new AppError('Failed to fetch user', 400, error));
    }
  }

  async updateUser(req: Request<{ id: string }, {}, UpdateUserDto>, res: Response, next: NextFunction) {
    try {
      const user = await this.userService.updateUser(req.params.id, req.body);

      // Sync with ERP system in background
      this.integrationService.syncUserToERP(user.id)
        .catch(err => logger.error('ERP sync failed', { error: err, userId: user.id }));

      res.status(200).json({
        status: 'success',
        data: user
      });
    } catch (error) {
      next(new AppError('Failed to update user', 400, error));
    }
  }

  async deleteUser(req: Request<{ id: string }>, res: Response, next: NextFunction) {
    try {
      await this.userService.deleteUser(req.params.id);

      res.status(204).json({
        status: 'success',
        data: null
      });
    } catch (error) {
      next(new AppError('Failed to delete user', 400, error));
    }
  }

  async searchUsers(req: Request<{}, {}, {}, { q: string; page?: string; pageSize?: string }>, res: Response, next: NextFunction) {
    try {
      const { q, page = '1', pageSize = '10' } = req.query;

      if (!q) {
        return next(new AppError('Search query is required', 400));
      }

      const pageNum = parseInt(page as string, 10);
      const pageSizeNum = parseInt(pageSize as string, 10);

      const { users, total } = await this.userService.searchUsers(q, pageNum, pageSizeNum);

      res.status(200).json({
        status: 'success',
        data: users,
        pagination: {
          total,
          page: pageNum,
          pageSize: pageSizeNum,
          totalPages: Math.ceil(total / pageSizeNum)
        }
      });
    } catch (error) {
      next(new AppError('Failed to search users', 400, error));
    }
  }
