  @ManyToOne(() => Customer, (customer) => customer.orders)
  customer: Customer;

  @ApiProperty({ type: [OrderItem], description: 'Items in the order' })
  @OneToMany(() => OrderItem, (orderItem) => orderItem.order, { cascade: true })
  items: OrderItem[];

