## Service Layer with Strict Typing

```typescript
// src/modules/order/order.service.ts
import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Order } from './entities/order.entity';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { CustomerService } from '../customer/customer.service';
import { OrderItem } from './entities/order-item.entity';
import { OrderStatus } from './enums/order-status.enum';
import { CorporateSystemsService } from '../../shared/services/corporate-systems.service';

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    private readonly customerService: CustomerService,
    private readonly corporateSystemsService: CorporateSystemsService,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating new order for customer: ${createOrderDto.customerReference}`);

    const customer = await this.customerService.findByReference(
      createOrderDto.customerReference,
    );

    if (!customer) {
      throw new NotFoundException(
        `Customer with reference ${createOrderDto.customerReference} not found`,
      );
    }

    const order = new Order();
    order.customer = customer;
    order.status = createOrderDto.status || OrderStatus.PENDING;
    order.currency = createOrderDto.currency;
    order.expectedDeliveryDate = createOrderDto.expectedDeliveryDate
      ? new Date(createOrderDto.expectedDeliveryDate)
      : null;

    // Calculate total amount
    order.totalAmount = createOrderDto.items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0,
    );

    // Create order items
    order.items = createOrderDto.items.map((itemDto) => {
      const item = new OrderItem();
      item.productId = itemDto.productId;
      item.quantity = itemDto.quantity;
      item.unitPrice = itemDto.unitPrice;
      return item;
    });

    // Generate reference number (could be more sophisticated)
    order.referenceNumber = `ORD-${new Date().getFullYear()}-${Math.floor(
      Math.random() * 10000,
    )}`;

    const savedOrder = await this.orderRepository.save(order);

    // Notify ERP system about the new order
    await this.corporateSystemsService.notifyErpAboutOrder(savedOrder);

    return savedOrder;
  }

  async findAll(): Promise<Order[]> {
    return this.orderRepository.find({
      relations: ['customer', 'items'],
    });
  }

  async findOne(id: number): Promise<Order> {
    const order = await this.orderRepository.findOne({
      where: { id },
      relations: ['customer', 'items'],
    });

    if (!order) {
      throw new NotFoundException(`Order with ID ${id} not found`);
    }

    return order;
  }

  async update(id: number, updateOrderDto: UpdateOrderDto): Promise<Order> {
    const order = await this.findOne(id);

    if (updateOrderDto.status) {
      order.status = updateOrderDto.status;
    }

    if (updateOrderDto.expectedDeliveryDate) {
      order.expectedDeliveryDate = new Date(updateOrderDto.expectedDeliveryDate);
    }

    const updatedOrder = await this.orderRepository.save(order);

    // Notify ERP system about status change
    if (updateOrderDto.status) {
      await this.corporateSystemsService.notifyErpAboutOrderStatusChange(
        updatedOrder,
      );
    }

    return updatedOrder;
  }

  async remove(id: number): Promise<void> {
    const order = await this.findOne(id);
    await this.orderRepository.remove(order);
  }
}
