// src/shared/services/corporate-systems.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Order } from '../../modules/order/entities/order.entity';
import { OrderStatus } from '../../modules/order/enums/order-status.enum';

@Injectable()
export class CorporateSystemsService {
  private readonly logger = new Logger(CorporateSystemsService.name);

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {}

  async notifyErpAboutOrder(order: Order): Promise<void> {
    const erpConfig = this.configService.get('corporateSystems.erp');
    const url = `${erpConfig.baseUrl}/api/orders`;

    try {
      const response = await firstValueFrom(
        this.httpService.post(
          url,
          this.mapOrderToErpFormat(order),
          {
            headers: {
              'X-API-KEY': erpConfig.apiKey,
              'Content-Type': 'application/json',
            },
          },
        ),
      );

      this.logger.log(
        `Successfully notified ERP about order ${order.referenceNumber}`,
      );
    } catch (error) {
      this.logger.error(
        `Failed to notify ERP about order ${order.referenceNumber}`,
        error.stack,
      );
      // Implement retry logic or dead letter queue here
      throw error;
    }
  }

  async notifyErpAboutOrderStatusChange(order: Order): Promise<void> {
    const erpConfig = this.configService.get('corporateSystems.erp');
    const url = `${erpConfig.baseUrl}/api/orders/${order.referenceNumber}/status`;

    try {
      const response = await firstValueFrom(
        this.httpService.put(
          url,
          { status: order.status },
          {
            headers: {
              'X-API-KEY': erpConfig.apiKey,
              'Content-Type': 'application/json',
            },
          },
        ),
      );

      this.logger.log(
        `Successfully updated order status in ERP for ${order.referenceNumber}`,
      );
    } catch (error) {
      this.logger.error(
        `Failed to update order status in ERP for ${order.referenceNumber}`,
        error.stack,
      );
      throw error;
    }
  }

  private mapOrderToErpFormat(order: Order): any {
    // Map our internal order format to ERP's expected format
    return {
      orderId: order.referenceNumber,
      customerId: order.customer.referenceNumber,
      orderDate: order.createdAt.toISOString(),
      status: order.status,
      items: order.items.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      })),
      totalAmount: order.totalAmount,
      currency: order.currency,
      expectedDeliveryDate: order.expectedDeliveryDate?.toISOString(),
    };
  }
}
