## Service Layer with Strict Typing

```typescript
// src/services/orderService.ts
import { PrismaClient } from '@prisma/client';
import { Order, CreateOrderDTO, UpdateOrderStatusDTO } from '../types/orderTypes';
import { logger } from '../utils/logger';
import { InventoryService } from './inventoryService';
import { IntegrationService } from './integrationService';

export class OrderService {
  private prisma: PrismaClient;
  private inventoryService: InventoryService;
  private integrationService: IntegrationService;

  constructor() {
    this.prisma = new PrismaClient();
    this.inventoryService = new InventoryService();
    this.integrationService = new IntegrationService();
  }

  async createOrder(orderData: CreateOrderDTO): Promise<Order> {
    try {
      // Validate inventory availability
      await this.inventoryService.validateInventory(orderData.items);

      // Create order in database
      const order = await this.prisma.order.create({
        data: {
          customerId: orderData.customerId,
          items: {
            create: orderData.items.map(item => ({
              productId: item.productId,
              quantity: item.quantity,
              // Price will be fetched from product catalog
              price: 0 // Temporary value
            }))
          },
          status: 'pending'
        },
        include: {
          items: true
        }
      });

      // Update inventory
      await this.inventoryService.reserveInventory(orderData.items);

      // Notify ERP system
      await this.integrationService.notifyERPSystem('order_created', order);

      return this.mapToOrder(order);
    } catch (error) {
      logger.error('Error creating order:', error);
      throw error;
    }
  }

  async updateOrderStatus(orderId: string, updateData: UpdateOrderStatusDTO): Promise<Order> {
    try {
      const order = await this.prisma.order.update({
        where: { id: orderId },
        data: { status: updateData.status },
        include: { items: true }
      });

      // Notify relevant systems based on status change
      switch (updateData.status) {
        case 'processing':
          await this.integrationService.notifyERPSystem('order_processing', order);
          break;
        case 'shipped':
          await this.integrationService.notifyShippingSystem(order);
          break;
        case 'delivered':
          await this.integrationService.notifyAccountingSystem(order);
          break;
      }

      return this.mapToOrder(order);
    } catch (error) {
      logger.error('Error updating order status:', error);
      throw error;
    }
  }

  private mapToOrder(dbOrder: any): Order {
    return {
      id: dbOrder.id,
      customerId: dbOrder.customerId,
      items: dbOrder.items.map((item: any) => ({
        productId: item.productId,
        quantity: item.quantity,
        price: item.price
      })),
      status: dbOrder.status as OrderStatus,
      createdAt: dbOrder.createdAt,
      updatedAt: dbOrder.updatedAt
    };
  }
}
