  async notifyERPSystem(eventType: string, order: Order): Promise<void> {
    try {
      const payload = {
        eventType,
        orderId: order.id,
        customerId: order.customerId,
        items: order.items,
        timestamp: new Date().toISOString()
      };

      await this.erpClient.post('/api/events', payload);
      logger.info(`Successfully notified ERP system about ${eventType} for order ${order.id}`);
    } catch (error) {
      logger.error(`Failed to notify ERP system: ${error}`);
      // Implement retry logic or dead letter queue here
      throw error;
    }
  }

  async notifyShippingSystem(order: Order): Promise<void> {
    try {
      const payload = {
        orderId: order.id,
        customerId: order.customerId,
        items: order.items,
        shippingAddress: await this.getCustomerShippingAddress(order.customerId)
      };

      await this.shippingClient.post('/api/shipments', payload);
      logger.info(`Successfully notified shipping system for order ${order.id}`);
    } catch (error) {
      logger.error(`Failed to notify shipping system: ${error}`);
      throw error;
    }
  }

  async notifyAccountingSystem(order: Order): Promise<void> {
    try {
      const payload = {
        orderId: order.id,
        customerId: order.customerId,
        items: order.items,
        totalAmount: order.items.reduce((sum, item) => sum + (item.price * item.quantity), 0)
      };

      await this.accountingClient.post('/api/invoices', payload);
      logger.info(`Successfully notified accounting system for order ${order.id}`);
    } catch (error) {
      logger.error(`Failed to notify accounting system: ${error}`);
      throw error;
    }
  }

