## Integration with ERP System

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Order } from '../../orders/entities/order.entity';
import { ERPOrderDto } from './dto/erp-order.dto';

@Injectable()
export class ERPService {
  private readonly logger = new Logger(ERPService.name);
  private readonly erpBaseUrl: string;
  private readonly erpApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('ERP_BASE_URL');
    this.erpApiKey = this.configService.get<string>('ERP_API_KEY');
  }

  async syncOrderToERP(order: Order): Promise<void> {
    try {
      const erpOrderDto = this.mapToERPOrderDto(order);

      const response = await firstValueFrom(
        this.httpService.post(`${this.erpBaseUrl}/api/orders`, erpOrderDto, {
          headers: {
            'Authorization': `Bearer ${this.erpApiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      this.logger.log(`Successfully synced order ${order.id} to ERP. Response: ${JSON.stringify(response.data)}`);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} to ERP: ${error.message}`);
      throw new Error(`ERP synchronization failed: ${error.message}`);
    }
  }

  private mapToERPOrderDto(order: Order): ERPOrderDto {
    return {
      orderId: order.id,
      customerId: order.customerId,
      orderDate: order.createdAt.toISOString(),
      status: order.status,
      items: order.items.map(item => ({
        productSku: item.productSku,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
        totalPrice: item.quantity * item.unitPrice,
      })),
      totalAmount: order.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0),
    };
  }
}
