      await Promise.all([
        this.erpService.syncOrderToERP(order),
        this.crmService.updateCustomerOrderHistory(order.customerId, order),
      ]);

      this.logger.log(`Successfully processed order.created event for order ${order.id}`);
    } catch (error) {
      this.logger.error(`Failed to process order.created event for order ${order.id}: ${error.message}`);
