## Core Implementation

```typescript
// src/app.ts
import express, { Express, Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import { PrismaClient } from '@prisma/client';
import { logger } from './utils/logger';
import { errorHandler } from './middleware/errorHandler';
import { authMiddleware } from './middleware/authMiddleware';
import { auditMiddleware } from './middleware/auditMiddleware';
import { rateLimiter } from './middleware/rateLimiter';
import { config } from './config';
import { userRoutes } from './routes/userRoutes';
import { orderRoutes } from './routes/orderRoutes';
import { integrationRoutes } from './routes/integrationRoutes';
import { healthCheckRoutes } from './routes/healthCheckRoutes';
import { swaggerDocs } from './utils/swagger';

export class App {
  private app: Express;
  private prisma: PrismaClient;

  constructor() {
    this.app = express();
    this.prisma = new PrismaClient();
    this.initializeMiddleware();
    this.initializeRoutes();
    this.initializeErrorHandling();
    this.initializeSwagger();
  }

  private initializeMiddleware(): void {
    // Security middleware
    this.app.use(helmet());
    this.app.use(cors({
      origin: config.allowedOrigins,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization']
    }));

    // Request parsing
    this.app.use(express.json({ limit: '10kb' }));
    this.app.use(express.urlencoded({ extended: true, limit: '10kb' }));

    // Logging
    this.app.use((req: Request, res: Response, next: NextFunction) => {
      logger.info(`${req.method} ${req.path}`);
      next();
    });

    // Rate limiting
    this.app.use(rateLimiter);

    // Database connection check
    this.app.use(async (req: Request, res: Response, next: NextFunction) => {
      try {
        await this.prisma.$queryRaw`SELECT 1`;
        next();
      } catch (error) {
        logger.error('Database connection error', error);
        res.status(503).json({ error: 'Service unavailable - database connection error' });
      }
    });
  }

  private initializeRoutes(): void {
    // Health check endpoint (public)
    this.app.use('/health', healthCheckRoutes);

    // Protected routes
    this.app.use('/api/users', authMiddleware, auditMiddleware, userRoutes);
    this.app.use('/api/orders', authMiddleware, auditMiddleware, orderRoutes);
    this.app.use('/api/integrations', authMiddleware, auditMiddleware, integrationRoutes);
  }

  private initializeErrorHandling(): void {
    this.app.use(errorHandler);
  }

  private initializeSwagger(): void {
    swaggerDocs(this.app);
  }

  public getApp(): Express {
    return this.app;
  }

  public async start(): Promise<void> {
    try {
      await this.prisma.$connect();
      logger.info('Database connection established');

      this.app.listen(config.port, () => {
        logger.info(`Server running on port ${config.port}`);
      });
    } catch (error) {
      logger.error('Failed to start server', error);
      process.exit(1);
    }
  }

  public async stop(): Promise<void> {
    await this.prisma.$disconnect();
    logger.info('Server stopped');
  }
}

// Start the application
const app = new App();
app.start();

// Handle graceful shutdown
process.on('SIGTERM', async () => {
  await app.stop();
  process.exit(0);
});

process.on('SIGINT', async () => {
  await app.stop();
  process.exit(0);
});
