model User {
  id            String    @id @default(uuid())
  email         String    @unique
  password      String
  firstName     String
  lastName      String
  role          Role      @default(USER)
  status        UserStatus @default(ACTIVE)
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt
  orders        Order[]
  auditLogs     AuditLog[]
}

model Order {
  id            String    @id @default(uuid())
  orderNumber   String    @unique
  customerId    String
  status        OrderStatus
  totalAmount   Decimal
  currency      String
  items         Json
  createdAt     DateTime  @default(now())
  updatedAt     DateTime  @updatedAt
  user          User      @relation(fields: [userId], references: [id])
  userId        String
  erpSyncStatus ErpSyncStatus @default(PENDING)
  erpSyncDate   DateTime?
  auditLogs     AuditLog[]
}

model AuditLog {
  id        String   @id @default(uuid())
  action    String
  entity    String
  entityId  String
  oldValue  Json?
  newValue  Json?
  userId    String
  user      User     @relation(fields: [userId], references: [id])
