  totalAmount: z.number().positive(),
  currency: z.string().length(3),
  items: z.array(OrderItemSchema),
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
  erpSyncStatus: z.enum(['PENDING', 'SYNCED', 'FAILED', 'RETRYING']),
  erpSyncDate: z.string().datetime().optional()
});

export const CreateOrderSchema = OrderSchema.omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  erpSyncStatus: true,
  erpSyncDate: true
});

export const UpdateOrderSchema = OrderSchema.omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  erpSyncStatus: true,
  erpSyncDate: true
}).partial();

export const ErpOrderSchema = z.object({
  externalOrderId: z.string().min(1),
  status: z.enum(['CREATED', 'PROCESSING', 'COMPLETED', 'FAILED']),
  message: z.string().optional()
});

export type User = z.infer<typeof UserSchema>;
export type CreateUser = z.infer<typeof CreateUserSchema>;
export type UpdateUser = z.infer<typeof UpdateUserSchema>;
export type Order = z.infer<typeof OrderSchema>;
export type CreateOrder = z.infer<typeof CreateOrderSchema>;
export type UpdateOrder = z.infer<typeof UpdateOrderSchema>;
export type ErpOrder = z.infer<typeof ErpOrderSchema>;
