## Integration Service with ERP System

```typescript
// src/services/integrationService.ts
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { Order, ErpOrder } from '../types/apiContracts';

export class IntegrationService {
  private erpClient: AxiosInstance;

  constructor() {
    this.erpClient = axios.create({
      baseURL: config.ERP_API_URL,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.ERP_API_KEY}`
      },
      timeout: 10000
    });

    // Add request interceptor
    this.erpClient.interceptors.request.use(
      (config) => {
        logger.debug(`ERP Request: ${config.method?.toUpperCase()} ${config.url}`);
        return config;
      },
      (error) => {
        logger.error('ERP Request Error', error);
        return Promise.reject(error);
      }
    );

    // Add response interceptor
    this.erpClient.interceptors.response.use(
      (response) => {
        logger.debug(`ERP Response: ${response.status} ${response.config.url}`);
        return response;
      },
      (error) => {
        logger.error('ERP Response Error', error);
        return Promise.reject(error);
      }
    );
  }

  async syncOrderToErp(order: Order): Promise<ErpOrder> {
    try {
      const response: AxiosResponse<ErpOrder> = await this.erpClient.post('/orders', {
        orderId: order.id,
        orderNumber: order.orderNumber,
        customerId: order.customerId,
        items: order.items,
        totalAmount: order.totalAmount,
        currency: order.currency
      });

      logger.info(`Order ${order.id} synced to ERP successfully`);
      return response.data;
    } catch (error) {
      logger.error(`Failed to sync order ${order.id} to ERP`, error);
      throw error;
    }
  }

  async getErpOrderStatus(externalOrderId: string): Promise<ErpOrder> {
    try {
      const response: AxiosResponse<ErpOrder> = await this.erpClient.get(`/orders/${externalOrderId}`);
      return response.data;
    } catch (error) {
      logger.error(`Failed to get ERP order status for ${externalOrderId}`, error);
      throw error;
    }
  }

  async updateErpOrderStatus(externalOrderId: string, status: string): Promise<ErpOrder> {
    try {
      const response: AxiosResponse<ErpOrder> = await this.erpClient.put(`/orders/${externalOrderId}/status`, {
        status
      });
      return response.data;
    } catch (error) {
      logger.error(`Failed to update ERP order status for ${externalOrderId}`, error);
      throw error;
    }
  }
}
