```typescript
// src/middleware/auditMiddleware.ts
import { Request, Response, NextFunction } from 'express';
import { PrismaClient } from '@prisma/client';
import { logger } from '../utils/logger';

const prisma = new PrismaClient();

export const auditMiddleware = async (req: Request, res: Response, next: NextFunction) => {
  const originalSend = res.send;
  const originalJson = res.json;

  res.send = function (body?: any): Response {
    res.send = originalSend;
    res.json = originalJson;

    if (req.method !== 'GET' && req.user) {
      const auditData = {
        action: req.method,
        entity: req.path.split('/')[2] || 'unknown',
        entityId: req.params.id || 'unknown',
        oldValue: req.body.oldValue || null,
        newValue: req.body.newValue || null,
        userId: req.user.id
      };

      prisma.auditLog.create({ data: auditData })
        .catch(err => logger.error('Failed to create audit log', err));
    }

    return res.send(body);
  };

  res.json = function (body: any): Response {
    res.send = originalSend;
    res.json = originalJson;

    if (req.method !== 'GET' && req.user) {
      const auditData = {
        action: req.method,
        entity: req.path.split('/')[2] || 'unknown',
        entityId: req.params.id || 'unknown',
        oldValue: req.body.oldValue || null,
        newValue: req.body.newValue || null,
        userId: req.user.id
      };

      prisma.auditLog.create({ data: auditData })
        .catch(err => logger.error('Failed to create audit log', err));
    }

    return res.json(body);
  };

  next();
};
