import { ERPUser, ERPUserResponse } from './interfaces/erp.interface';
import { User } from '../../users/entities/user.entity';

@Injectable()
export class ErpService {
  private readonly logger = new Logger(ErpService.name);
  private readonly erpClient: AxiosInstance;

  constructor(private configService: ConfigService) {
    this.erpClient = axios.create({
      baseURL: this.configService.get<string>('ERP_API_URL'),
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': this.configService.get<string>('ERP_API_KEY'),
      },
