  async syncUserWithERP(user: User): Promise<ERPUserResponse> {
    try {
      const erpUser: ERPUser = {
        employeeId: user.id,
        email: user.email,
        name: user.name,
        department: user.department || 'Unassigned',
        phone: user.phone || '',
        isActive: user.isActive,
      };

      this.logger.log(`Syncing user ${user.id} with ERP system`);

      const response = await this.erpClient.post<ERPUserResponse>(
        '/api/employees',
        erpUser,
      );

      this.logger.log(`Successfully synced user ${user.id} with ERP`);
      return response.data;
