## Audit Logging System

```typescript
// src/audit/audit.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AuditLog } from './entities/audit-log.entity';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class AuditService {
  private readonly logger = new Logger(AuditService.name);
  private readonly isAuditEnabled: boolean;

  constructor(
    @InjectRepository(AuditLog)
    private auditLogRepository: Repository<AuditLog>,
    private configService: ConfigService,
  ) {
    this.isAuditEnabled = this.configService.get<boolean>('AUDIT_LOG_ENABLED');
  }

  async logAction(
    action: string,
    entityType: string,
    entityId: string,
    userId: string,
    oldValue?: any,
    newValue?: any,
  ): Promise<AuditLog> {
    if (!this.isAuditEnabled) {
      this.logger.debug('Audit logging is disabled');
      return null;
    }

    try {
      const auditLog = this.auditLogRepository.create({
        action,
        entityType,
        entityId,
        userId,
        oldValue: oldValue ? JSON.stringify(oldValue) : null,
        newValue: newValue ? JSON.stringify(newValue) : null,
      });

      return await this.auditLogRepository.save(auditLog);
    } catch (error) {
      this.logger.error(`Failed to log audit action: ${error.message}`);
      throw new Error(`Audit logging failed: ${error.message}`);
    }
  }

  async getAuditLogs(
    entityType?: string,
    entityId?: string,
    limit: number = 100,
  ): Promise<AuditLog[]> {
    const query = this.auditLogRepository.createQueryBuilder('auditLog');

    if (entityType) {
      query.andWhere('auditLog.entityType = :entityType', { entityType });
    }

    if (entityId) {
      query.andWhere('auditLog.entityId = :entityId', { entityId });
    }

    query.orderBy('auditLog.createdAt', 'DESC').limit(limit);

    return query.getMany();
  }
}
