Below is a comprehensive implementation of a backend microservice for a large enterprise with strict type safety requirements and integration capabilities. This example uses TypeScript, NestJS (a Node.js framework), and follows enterprise patterns.

## Core Architecture

```typescript
// src/main.ts - Application entry point
import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';
import { ValidationPipe } from '@nestjs/common';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { Logger } from 'nestjs-pino';
import { ConfigService } from '@nestjs/config';

async function bootstrap() {
  const app = await NestFactory.create(AppModule, {
    logger: ['error', 'warn', 'log'],
  });

  // Configuration
  const configService = app.get(ConfigService);
  const port = configService.get<number>('PORT') || 3000;

  // Global validation
  app.useGlobalPipes(
    new ValidationPipe({
      transform: true,
      whitelist: true,
      forbidNonWhitelisted: true,
    }),
  );

  // API Documentation
  const config = new DocumentBuilder()
    .setTitle('Enterprise Microservice API')
    .setDescription('API documentation for enterprise microservice')
    .setVersion('1.0')
    .addBearerAuth()
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);

  // Health checks
  app.enableShutdownHooks();

  // CORS configuration for corporate environments
  app.enableCors({
    origin: configService.get<string>('ALLOWED_ORIGINS')?.split(',') || [],
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    credentials: true,
  });

  // Start the application
  await app.listen(port, '0.0.0.0');
  app.get(Logger).log(`Application is running on: ${await app.getUrl()}`);
}

bootstrap();
