## Integration with Corporate Systems

```typescript
// src/infrastructure/integrations/erp-integration.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { catchError } from 'rxjs/operators';
import { AxiosError } from 'axios';

@Injectable()
export class ErpIntegrationService {
  private readonly logger = new Logger(ErpIntegrationService.name);
  private readonly erpBaseUrl: string;
  private readonly erpApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('ERP_BASE_URL') || '';
    this.erpApiKey = this.configService.get<string>('ERP_API_KEY') || '';
  }

  async syncUserToErp(userId: string): Promise<void> {
    try {
      const response = await firstValueFrom(
        this.httpService
          .post(
            `${this.erpBaseUrl}/api/users/sync`,
            { userId },
            {
              headers: {
                'X-API-KEY': this.erpApiKey,
                'Content-Type': 'application/json',
              },
            },
          )
          .pipe(
            catchError((error: AxiosError) => {
              this.logger.error(`ERP sync failed for user ${userId}: ${error.message}`);
              throw error;
            }),
          ),
      );

      this.logger.log(`Successfully synced user ${userId} to ERP. Status: ${response.status}`);
    } catch (error) {
      this.logger.error(`Failed to sync user ${userId} to ERP: ${error.message}`);
      throw error;
    }
  }

  async getUserFromErp(userId: string): Promise<any> {
    try {
      const response = await firstValueFrom(
        this.httpService
          .get(`${this.erpBaseUrl}/api/users/${userId}`, {
            headers: {
              'X-API-KEY': this.erpApiKey,
            },
          })
          .pipe(
            catchError((error: AxiosError) => {
              this.logger.error(`ERP fetch failed for user ${userId}: ${error.message}`);
              throw error;
            }),
          ),
      );

      return response.data;
    } catch (error) {
      this.logger.error(`Failed to fetch user ${userId} from ERP: ${error.message}`);
      throw error;
    }
  }
}
