## Service Layer with Business Logic

```typescript
// src/orders/orders.service.ts
import { Injectable, Inject, ConflictException, NotFoundException } from '@nestjs/common';
import { OrderRepository } from './repositories/order.repository';
import { OrderItemRepository } from './repositories/order-item.repository';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { Order } from './entities/order.entity';
import { OrderStatus } from './enums/order-status.enum';
import { InventoryService } from '../inventory/inventory.service';
import { PaymentService } from '../payment/payment.service';
import { NotificationService } from '../notification/notification.service';
import { AuditService } from '../audit/audit.service';

@Injectable()
export class OrdersService {
  constructor(
    @Inject('OrderRepository')
    private readonly orderRepository: OrderRepository,
    @Inject('OrderItemRepository')
    private readonly orderItemRepository: OrderItemRepository,
    private readonly inventoryService: InventoryService,
    private readonly paymentService: PaymentService,
    private readonly notificationService: NotificationService,
    private readonly auditService: AuditService,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    // Check inventory availability
    for (const item of createOrderDto.items) {
      const inventory = await this.inventoryService.checkAvailability(
        item.productSku,
        item.quantity,
      );

      if (!inventory) {
        throw new ConflictException(
          `Insufficient inventory for product ${item.productSku}`,
        );
      }
    }

    // Create order
    const order = await this.orderRepository.create(createOrderDto);

    // Process payment
    try {
      await this.paymentService.processPayment({
        orderId: order.id,
        amount: order.totalAmount,
        currency: order.currency,
        customerId: order.customerId,
      });

      // Update order status to PAID
      await this.orderRepository.updateStatus(order.id, OrderStatus.PAID);

      // Reserve inventory
      for (const item of createOrderDto.items) {
        await this.inventoryService.reserveInventory(
          item.productSku,
          item.quantity,
          order.id,
        );
      }

      // Send confirmation notification
      await this.notificationService.sendOrderConfirmation(order);

      // Log audit event
      await this.auditService.log({
        action: 'ORDER_CREATED',
        entityType: 'Order',
        entityId: order.id,
        details: `Order created with total amount ${order.totalAmount}`,
      });

      return order;
    } catch (error) {
      // If payment fails, update order status to FAILED
      await this.orderRepository.updateStatus(order.id, OrderStatus.FAILED);

      // Log audit event
      await this.auditService.log({
        action: 'ORDER_FAILED',
        entityType: 'Order',
        entityId: order.id,
        details: `Order payment failed: ${error.message}`,
      });

      throw error;
    }
  }

  async findAll(): Promise<Order[]> {
    return this.orderRepository.findAll();
  }

  async findOne(id: string): Promise<Order> {
    const order = await this.orderRepository.findOne(id);
    if (!order) {
      throw new NotFoundException(`Order with ID ${id} not found`);
    }
    return order;
  }

  async update(id: string, updateOrderDto: UpdateOrderDto): Promise<Order> {
    const order = await this.findOne(id);

    // Business logic for updating order
    // ...

    return this.orderRepository.save(order);
  }

  async cancel(id: string): Promise<Order> {
    const order = await this.findOne(id);

    if (order.status !== OrderStatus.PAID) {
      throw new ConflictException('Only paid orders can be cancelled');
    }

    // Business logic for cancellation
    // ...

    // Update order status to CANCELLED
    const cancelledOrder = await this.orderRepository.updateStatus(
      id,
      OrderStatus.CANCELLED,
    );

    // Log audit event
    await this.auditService.log({
      action: 'ORDER_CANCELLED',
      entityType: 'Order',
      entityId: id,
      details: 'Order was cancelled by customer',
    });

    return cancelledOrder;
  }
}
