```typescript
// src/integrations/sap/sap.service.ts
import { Injectable, Inject } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Logger } from 'nestjs-pino';
import { SapClient } from './sap.client';
import { SapOrderDto } from './dto/sap-order.dto';
import { Order } from '../../orders/entities/order.entity';

@Injectable()
export class SapService {
  constructor(
    private readonly configService: ConfigService,
    private readonly logger: Logger,
    @Inject('SapClient') private readonly sapClient: SapClient,
  ) {}

  async syncOrderToSap(order: Order): Promise<void> {
    try {
      const sapOrderDto: SapOrderDto = this.mapOrderToSapDto(order);

      this.logger.log(`Syncing order ${order.id} to SAP`);
      await this.sapClient.sendOrder(sapOrderDto);

      this.logger.log(`Successfully synced order ${order.id} to SAP`);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} to SAP: ${error.message}`);
      throw error;
    }
  }

  private mapOrderToSapDto(order: Order): SapOrderDto {
    return {
      orderId: order.id,
      customerId: order.customerId,
      orderDate: order.createdAt.toISOString(),
      totalAmount: order.totalAmount.toString(),
      currency: order.currency,
      status: this.mapOrderStatusToSapStatus(order.status),
      items: order.items.map((item) => ({
        productSku: item.productSku,
        quantity: item.quantity.toString(),
        price: item.price.toString(),
      })),
    };
  }

  private mapOrderStatusToSapStatus(status: OrderStatus): string {
    const statusMap: Record<OrderStatus, string> = {
      [OrderStatus.PENDING]: 'P',
      [OrderStatus.PAID]: 'A',
      [OrderStatus.SHIPPED]: 'S',
      [OrderStatus.DELIVERED]: 'D',
      [OrderStatus.CANCELLED]: 'C',
      [OrderStatus.FAILED]: 'F',
    };

    return statusMap[status];
  }
}
