## Integration with Corporate Systems

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { AxiosResponse } from 'axios';
import { ERPOrderDto } from './dto/erp-order.dto';
import { ERPInventoryDto } from './dto/erp-inventory.dto';

@Injectable()
export class ERPIntegrationService {
  private readonly logger = new Logger(ERPIntegrationService.name);
  private readonly erpBaseUrl: string;
  private readonly erpApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('ERP_BASE_URL');
    this.erpApiKey = this.configService.get<string>('ERP_API_KEY');
  }

  async syncOrderToERP(order: ERPOrderDto): Promise<void> {
    try {
      const response = await firstValueFrom(
        this.httpService.post(`${this.erpBaseUrl}/api/orders`, order, {
          headers: {
            'Authorization': `Bearer ${this.erpApiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      this.logger.log(`Successfully synced order ${order.orderNumber} to ERP`);
      this.handleERPResponse(response);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.orderNumber} to ERP`, error.stack);
      throw new Error(`ERP synchronization failed: ${error.message}`);
    }
  }

  async syncInventoryToERP(inventory: ERPInventoryDto): Promise<void> {
    try {
      const response = await firstValueFrom(
        this.httpService.put(`${this.erpBaseUrl}/api/inventory/${inventory.sku}`, inventory, {
          headers: {
            'Authorization': `Bearer ${this.erpApiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      this.logger.log(`Successfully synced inventory for SKU ${inventory.sku} to ERP`);
      this.handleERPResponse(response);
    } catch (error) {
      this.logger.error(`Failed to sync inventory for SKU ${inventory.sku} to ERP`, error.stack);
      throw new Error(`ERP inventory synchronization failed: ${error.message}`);
    }
  }

  private handleERPResponse(response: AxiosResponse): void {
    if (response.status >= 400) {
      this.logger.error(`ERP API error: ${response.status} - ${response.statusText}`);
      throw new Error(`ERP API error: ${response.status}`);
    }
  }
}
```

