```typescript
// src/modules/order/order.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Order, OrderStatus } from './order.entity';
import { OrderItem } from './order-item.entity';
import { Customer } from '../customer/customer.entity';
import { ERPService } from '../../integrations/erp/erp.service';
import { CRMService } from '../../integrations/crm/crm.service';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderStatusDto } from './dto/update-order-status.dto';

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    @InjectRepository(OrderItem)
    private readonly orderItemRepository: Repository<OrderItem>,
    private readonly erpService: ERPService,
    private readonly crmService: CRMService,
  ) {}

  async createOrder(createOrderDto: CreateOrderDto): Promise<Order> {
    try {
      // Create order in local database
      const order = this.orderRepository.create({
        ...createOrderDto,
        status: OrderStatus.PENDING,
      });

      // Create order items
      const orderItems = createOrderDto.items.map((item) =>
        this.orderItemRepository.create({
          ...item,
          order,
        }),
      );

      order.items = orderItems;

      // Save to database
      const savedOrder = await this.orderRepository.save(order);

      // Integrate with ERP system
      const erpResponse = await this.erpService.createOrder(savedOrder);
      savedOrder.erpReferenceId = erpResponse.referenceId;

      // Integrate with CRM system
      const crmResponse = await this.crmService.updateOrderStatus(
        savedOrder.customer.id,
        savedOrder.id,
        OrderStatus.PENDING,
      );
      savedOrder.crmReferenceId = crmResponse.referenceId;

      // Update with integration references
      await this.orderRepository.save(savedOrder);

      this.logger.log(`Order created with ID: ${savedOrder.id}`);
      return savedOrder;
    } catch (error) {
      this.logger.error(`Failed to create order: ${error.message}`);
      throw error;
    }
  }

  async updateOrderStatus(
    orderId: string,
    updateOrderStatusDto: UpdateOrderStatusDto,
  ): Promise<Order> {
    try {
      const order = await this.orderRepository.findOne({
        where: { id: orderId },
        relations: ['customer'],
      });

      if (!order) {
        throw new Error('Order not found');
      }

      // Update status in local database
      order.status = updateOrderStatusDto.status;
      const updatedOrder = await this.orderRepository.save(order);

      // Update status in ERP system
      await this.erpService.updateOrderStatus(
        updatedOrder.erpReferenceId,
        updateOrderStatusDto.status,
      );

      // Update status in CRM system
      await this.crmService.updateOrderStatus(
        updatedOrder.customer.id,
        updatedOrder.crmReferenceId,
        updateOrderStatusDto.status,
      );

      this.logger.log(`Order status updated to ${updateOrderStatusDto.status} for order ID: ${orderId}`);
      return updatedOrder;
    } catch (error) {
      this.logger.error(`Failed to update order status: ${error.message}`);
      throw error;
    }
  }

  async getOrderById(orderId: string): Promise<Order> {
    try {
      const order = await this.orderRepository.findOne({
        where: { id: orderId },
        relations: ['customer', 'items'],
      });

      if (!order) {
        throw new Error('Order not found');
      }

      return order;
    } catch (error) {
      this.logger.error(`Failed to get order: ${error.message}`);
      throw error;
    }
  }
}
