## ERP Integration Service

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, HttpException, HttpStatus, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Order, OrderStatus } from '../../modules/order/order.entity';

@Injectable()
export class ERPService {
  private readonly logger = new Logger(ERPService.name);
  private readonly baseUrl: string;
  private readonly apiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.baseUrl = this.configService.get<string>('externalServices.erp.baseUrl');
    this.apiKey = this.configService.get<string>('externalServices.erp.apiKey');
  }

  async createOrder(order: Order): Promise<{ referenceId: string }> {
    try {
      const erpOrder = this.mapToERPOrder(order);

      const response = await firstValueFrom(
        this.httpService.post(`${this.baseUrl}/api/orders`, erpOrder, {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      this.logger.log(`Successfully created order in ERP with reference ID: ${response.data.referenceId}`);
      return { referenceId: response.data.referenceId };
    } catch (error) {
      this.logger.error(`Failed to create order in ERP: ${error.message}`);
      throw new HttpException(
        'Failed to create order in ERP system',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  async updateOrderStatus(
    erpReferenceId: string,
    status: OrderStatus,
  ): Promise<void> {
    try {
      await firstValueFrom(
        this.httpService.patch(
          `${this.baseUrl}/api/orders/${erpReferenceId}/status`,
          { status: this.mapStatusToERP(status) },
          {
            headers: {
              'Authorization': `Bearer ${this.apiKey}`,
              'Content-Type': 'application/json',
            },
          },
        ),
      );

      this.logger.log(`Successfully updated order status in ERP for reference ID: ${erpReferenceId}`);
    } catch (error) {
      this.logger.error(`Failed to update order status in ERP: ${error.message}`);
      throw new HttpException(
        'Failed to update order status in ERP system',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  private mapToERPOrder(order: Order): any {
    return {
      orderId: order.id,
      customerId: order.customer.id,
      referenceNumber: order.referenceNumber,
      items: order.items.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      })),
      totalAmount: order.totalAmount,
      status: this.mapStatusToERP(order.status),
    };
  }

  private mapStatusToERP(status: OrderStatus): string {
    const statusMap = {
      [OrderStatus.PENDING]: 'PENDING',
      [OrderStatus.PROCESSING]: 'PROCESSING',
      [OrderStatus.SHIPPED]: 'SHIPPED',
      [OrderStatus.DELIVERED]: 'DELIVERED',
      [OrderStatus.CANCELLED]: 'CANCELLED',
    };

    return statusMap[status] || 'PENDING';
  }
}
