## Service Layer with Strict Typing

```typescript
// src/orders/orders.service.ts
import { Injectable, NotFoundException, Inject } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Order } from './entities/order.entity';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { OrderItem } from './entities/order-item.entity';
import { InventoryService } from '../inventory/inventory.service';
import { LoggerService } from '../logging/logger.service';
import { MetricsService } from '../metrics/metrics.service';
import { OrderStatus } from './types/order-status.type';

@Injectable()
export class OrdersService {
  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    @InjectRepository(OrderItem)
    private readonly orderItemRepository: Repository<OrderItem>,
    private readonly inventoryService: InventoryService,
    private readonly logger: LoggerService,
    private readonly metrics: MetricsService,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for customer ${createOrderDto.customerId}`);

    // Check inventory availability
    for (const item of createOrderDto.items) {
      const inventory = await this.inventoryService.checkAvailability(item.productId, item.quantity);
      if (!inventory) {
        throw new Error(`Insufficient inventory for product ${item.productId}`);
      }
    }

    // Calculate total amount
    const totalAmount = createOrderDto.items.reduce(
      (sum, item) => sum + item.quantity * item.unitPrice,
      0,
    );

    // Create order entity
    const order = this.orderRepository.create({
      ...createOrderDto,
      totalAmount,
      status: 'pending' as OrderStatus,
    });

    // Create order items
    order.items = createOrderDto.items.map((item) =>
      this.orderItemRepository.create({
        ...item,
        order,
      }),
    );

    // Save to database
    const savedOrder = await this.orderRepository.save(order);

    // Record metrics
    this.metrics.increment('orders.created');
    this.metrics.record('orders.total_amount', totalAmount);

    return savedOrder;
  }

  async findAll(): Promise<Order[]> {
    return this.orderRepository.find({ relations: ['items'] });
  }

  async findOne(id: string): Promise<Order> {
    const order = await this.orderRepository.findOne({
      where: { id },
      relations: ['items'],
    });

    if (!order) {
      throw new NotFoundException(`Order with ID ${id} not found`);
    }

    return order;
  }

  async update(id: string, updateOrderDto: UpdateOrderDto): Promise<Order> {
    const order = await this.findOne(id);

    // Apply updates
    Object.assign(order, updateOrderDto);

    // Save changes
    return this.orderRepository.save(order);
  }

  async remove(id: string): Promise<void> {
    const order = await this.findOne(id);
    await this.orderRepository.remove(order);
  }

  async processOrder(id: string): Promise<Order> {
    const order = await this.findOne(id);

    if (order.status !== 'pending') {
      throw new Error(`Order ${id} cannot be processed in current state`);
    }

    // Reserve inventory
    for (const item of order.items) {
      await this.inventoryService.reserveInventory(item.productId, item.quantity);
    }

    // Update status
    order.status = 'processing';

    // Save changes
    return this.orderRepository.save(order);
  }
}
