import { LoggerService } from '../../logging/logger.service';
import { MetricsService } from '../../metrics/metrics.service';
import { ErpOrderDto } from './dto/erp-order.dto';
import { Order } from '../../orders/entities/order.entity';

@Injectable()
export class ErpService {
  private readonly erpBaseUrl: string;
  private readonly erpApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
    private readonly logger: LoggerService,
    private readonly metrics: MetricsService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('ERP_BASE_URL');
    this.erpApiKey = this.configService.get<string>('ERP_API_KEY');
  }

  async syncOrderToErp(order: Order): Promise<void> {
    this.logger.log(`Syncing order ${order.id} to ERP system`);

    const erpOrder: ErpOrderDto = {
      orderId: order.id,
      customerId: order.customerId,
      totalAmount: order.totalAmount,
      status: order.status,
      items: order.items.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      })),
      createdAt: order.createdAt.toISOString(),
    };

    try {
      const response = await firstValueFrom(
        this.httpService.post(`${this.erpBaseUrl}/api/orders`, erpOrder, {
          headers: {
            'Authorization': `Bearer ${this.erpApiKey}`,
            'Content-Type': 'application/json',
          },
        }),
      );

      this.logger.log(`Successfully synced order ${order.id} to ERP. Response: ${JSON.stringify(response.data)}`);
      this.metrics.increment('erp.sync.success');
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} to ERP`, error);
      this.metrics.increment('erp.sync.failure');
      throw error;
    }
  }

  async getCustomerDetails(customerId: string): Promise<any> {
    this.logger.log(`Fetching customer details for ${customerId} from ERP`);

    try {
      const response = await firstValueFrom(
        this.httpService.get(`${this.erpBaseUrl}/api/customers/${customerId}`, {
          headers: {
            'Authorization': `Bearer ${this.erpApiKey}`,
          },
        }),
      );

      this.metrics.increment('erp.customer.fetch.success');
      return response.data;
    } catch (error) {
      this.logger.error(`Failed to fetch customer ${customerId} from ERP`, error);
      this.metrics.increment('erp.customer.fetch.failure');
      throw error;
    }
  }
}
