## Core Implementation

```typescript
// src/app.ts
import express, { Express, Request, Response, NextFunction } from 'express';
import helmet from 'helmet';
import cors from 'cors';
import { PrismaClient } from '@prisma/client';
import { logger } from './utils/logger';
import { errorHandler } from './middleware/errorHandler';
import { authMiddleware } from './middleware/auth';
import { swaggerDocs } from './utils/swagger';
import { config } from './config';
import { userRouter } from './routes/user';
import { integrationRouter } from './routes/integration';
import { healthCheckRouter } from './routes/health';

export class EnterpriseMicroservice {
  private app: Express;
  private prisma: PrismaClient;

  constructor() {
    this.app = express();
    this.prisma = new PrismaClient();
    this.initializeMiddleware();
    this.initializeRoutes();
    this.initializeErrorHandling();
    this.initializeSwagger();
  }

  private initializeMiddleware(): void {
    // Security middleware
    this.app.use(helmet());
    this.app.use(cors({
      origin: config.allowedOrigins,
      methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
      allowedHeaders: ['Content-Type', 'Authorization']
    }));

    // Request parsing
    this.app.use(express.json({ limit: '10kb' }));
    this.app.use(express.urlencoded({ extended: true, limit: '10kb' }));

    // Request logging
    this.app.use((req: Request, res: Response, next: NextFunction) => {
      logger.info(`${req.method} ${req.path}`, {
        ip: req.ip,
        userAgent: req.get('User-Agent'),
        requestId: req.headers['x-request-id']
      });
      next();
    });

    // Database connection health check
    this.app.use(async (req: Request, res: Response, next: NextFunction) => {
      try {
        await this.prisma.$queryRaw`SELECT 1`;
        next();
      } catch (error) {
        logger.error('Database connection failed', { error });
        res.status(503).json({ error: 'Service unavailable - database connection failed' });
      }
    });
  }

  private initializeRoutes(): void {
    // Health check endpoint
    this.app.use('/health', healthCheckRouter);

    // Protected routes
    this.app.use('/api/users', authMiddleware, userRouter);
    this.app.use('/api/integrations', authMiddleware, integrationRouter);

    // Default 404 handler
    this.app.use((req: Request, res: Response) => {
      res.status(404).json({ error: 'Not Found' });
    });
  }

  private initializeErrorHandling(): void {
    this.app.use(errorHandler);
  }

  private initializeSwagger(): void {
    swaggerDocs(this.app);
  }

  public async start(): Promise<void> {
    try {
      await this.prisma.$connect();
      logger.info('Database connection established');

      this.app.listen(config.port, () => {
        logger.info(`Server running on port ${config.port}`);
      });
    } catch (error) {
      logger.error('Failed to start server', { error });
      process.exit(1);
    }
  }

  public async stop(): Promise<void> {
    await this.prisma.$disconnect();
    logger.info('Database connection closed');
  }
}

// Start the service
const service = new EnterpriseMicroservice();
service.start();

// Handle shutdown signals
process.on('SIGTERM', async () => {
  logger.info('SIGTERM received');
  await service.stop();
  process.exit(0);
});

process.on('SIGINT', async () => {
  logger.info('SIGINT received');
  await service.stop();
  process.exit(0);
});
