## Integration Service with ERP System

```typescript
// src/services/integration.ts
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { IntegrationStatus, SyncStatus } from '@prisma/client';
import { PrismaClient } from '@prisma/client';
import { IntegrationError } from '../errors/integrationError';

interface ERPSystemResponse<T> {
  data: T;
  status: string;
  timestamp: string;
}

interface ERPUser {
  id: string;
  email: string;
  name: string;
  department: string;
  employmentStatus: 'ACTIVE' | 'TERMINATED' | 'ON_LEAVE';
}

interface ERPSyncResult {
  success: boolean;
  recordsProcessed: number;
  errors?: Array<{
    recordId: string;
    message: string;
  }>;
}

export class IntegrationService {
  private axiosInstance: AxiosInstance;
  private prisma: PrismaClient;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: config.ERP_SYSTEM_URL,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.ERP_SYSTEM_API_KEY}`
      },
      timeout: 10000
    });

    this.prisma = new PrismaClient();
  }

  async syncUserData(userId: string): Promise<ERPSyncResult> {
    try {
      // Get user from our system
      const user = await this.prisma.user.findUnique({
        where: { id: userId },
        include: { integrations: true }
      });

      if (!user) {
        throw new IntegrationError('User not found', 404);
      }

      // Check if integration is active
      const erpIntegration = user.integrations.find(i => i.systemName === 'ERP');
      if (!erpIntegration || erpIntegration.status !== IntegrationStatus.ACTIVE) {
        throw new IntegrationError('ERP integration not active', 400);
      }

      // Create sync record
      const syncRecord = await this.prisma.syncHistory.create({
        data: {
          integrationId: erpIntegration.id,
          status: SyncStatus.IN_PROGRESS,
          startedAt: new Date(),
          recordsSynced: 0
        }
      });

      try {
        // Fetch user data from ERP system
        const response: AxiosResponse<ERPSystemResponse<ERPUser>> = await this.axiosInstance.get(
          `/api/users/${erpIntegration.systemId}`
        );

        if (response.data.status !== 'success') {
          throw new IntegrationError('ERP system returned error', 502);
        }

        const erpUser = response.data.data;

        // Update our user record with ERP data
        await this.prisma.user.update({
          where: { id: userId },
          data: {
            name: erpUser.name,
            status: erpUser.employmentStatus === 'ACTIVE' ? 'ACTIVE' : 'SUSPENDED'
          }
        });

        // Update sync record
        await this.prisma.syncHistory.update({
          where: { id: syncRecord.id },
          data: {
            status: SyncStatus.COMPLETED,
            completedAt: new Date(),
            recordsSynced: 1
          }
        });

        return {
          success: true,
          recordsProcessed: 1
        };
      } catch (error) {
        // Update sync record with error
        await this.prisma.syncHistory.update({
          where: { id: syncRecord.id },
          data: {
            status: SyncStatus.FAILED,
            completedAt: new Date(),
            errors: {
              message: error instanceof Error ? error.message : 'Unknown error',
              stack: error instanceof Error ? error.stack : undefined
            }
          }
        });

        throw error;
      }
    } catch (error) {
      logger.error('Failed to sync user data with ERP', {
        userId,
        error: error instanceof Error ? error.message : 'Unknown error'
      });
      throw error;
    }
  }

  async getERPUserData(userId: string): Promise<ERPUser> {
    try {
      const response: AxiosResponse<ERPSystemResponse<ERPUser>> = await this.axiosInstance.get(
        `/api/users/${userId}`
      );

      if (response.data.status !== 'success') {
        throw new IntegrationError('ERP system returned error', 502);
      }

      return response.data.data;
    } catch (error) {
      logger.error('Failed to fetch ERP user data', {
        userId,
        error: error instanceof Error ? error.message : 'Unknown error'
      });
      throw error;
    }
  }
}
