## Example Service with Strict Typing

```typescript
// src/order/order.service.ts
import { Injectable, Inject, Logger } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Order } from './entities/order.entity';
import { OrderItem } from './entities/order-item.entity';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { OrderStatus } from './enums/order-status.enum';
import { firstValueFrom } from 'rxjs';
import { InventoryCheckDto } from './dto/inventory-check.dto';
import { PaymentRequestDto } from './dto/payment-request.dto';

@Injectable()
export class OrderService {
  private readonly logger = new Logger(OrderService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: Repository<Order>,
    @InjectRepository(OrderItem)
    private readonly orderItemRepository: Repository<OrderItem>,
    @Inject('INVENTORY_SERVICE') private readonly inventoryClient: ClientProxy,
    @Inject('PAYMENT_SERVICE') private readonly paymentClient: ClientProxy,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating new order for user ${createOrderDto.userId}`);

    // Check inventory availability
    const inventoryCheckDto: InventoryCheckDto = {
      items: createOrderDto.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
      })),
    };

    try {
      const inventoryResponse = await firstValueFrom(
        this.inventoryClient.send('inventory.check', inventoryCheckDto)
      );

      if (!inventoryResponse.available) {
        throw new Error('Some items are not available in sufficient quantity');
      }
    } catch (error) {
      this.logger.error('Inventory check failed', error.stack);
      throw error;
    }

    // Calculate total amount
    const totalAmount = createOrderDto.items.reduce(
      (sum, item) => sum + (item.price * item.quantity),
      0
    );

    // Create order entity
    const order = this.orderRepository.create({
      ...createOrderDto,
      totalAmount,
      status: OrderStatus.PENDING,
    });

    // Create order items
    const orderItems = createOrderDto.items.map(item =>
      this.orderItemRepository.create({
        ...item,
        order,
      })
    );

    order.items = orderItems;

    // Save to database
    const savedOrder = await this.orderRepository.save(order);

    // Process payment
    const paymentRequest: PaymentRequestDto = {
      orderId: savedOrder.id,
      amount: savedOrder.totalAmount,
      currency: savedOrder.currency,
      userId: savedOrder.userId,
    };

    try {
      const paymentResponse = await firstValueFrom(
        this.paymentClient.send('payment.process', paymentRequest)
      );

      if (paymentResponse.status === 'success') {
        savedOrder.status = OrderStatus.PAID;
        await this.orderRepository.save(savedOrder);
      } else {
        savedOrder.status = OrderStatus.PAYMENT_FAILED;
        await this.orderRepository.save(savedOrder);
        throw new Error('Payment processing failed');
      }
    } catch (error) {
      this.logger.error('Payment processing failed', error.stack);
      throw error;
    }

    return savedOrder;
  }

  async findAll(): Promise<Order[]> {
    return this.orderRepository.find({ relations: ['items'] });
  }

  async findOne(id: number): Promise<Order> {
    return this.orderRepository.findOne({
      where: { id },
      relations: ['items'],
    });
  }

  async update(id: number, updateOrderDto: UpdateOrderDto): Promise<Order> {
    await this.orderRepository.update(id, updateOrderDto);
    return this.findOne(id);
  }

  async remove(id: number): Promise<void> {
    await this.orderRepository.delete(id);
  }

  async cancelOrder(id: number): Promise<Order> {
    const order = await this.findOne(id);

    if (!order) {
      throw new Error('Order not found');
    }

    if (order.status !== OrderStatus.PENDING && order.status !== OrderStatus.PAID) {
      throw new Error('Only pending or paid orders can be cancelled');
    }

    // Additional business logic for cancellation
    order.status = OrderStatus.CANCELLED;
    return this.orderRepository.save(order);
  }
}
