## Service Integration with ERP System

```typescript
// src/modules/order/services/erp-integration.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Order } from '../entities/order.entity';
import { AxiosRequestConfig } from 'axios';

@Injectable()
export class ErpIntegrationService {
  private readonly logger = new Logger(ErpIntegrationService.name);
  private readonly erpBaseUrl: string;
  private readonly erpApiKey: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('externalSystems.erp.baseUrl');
    this.erpApiKey = this.configService.get<string>('externalSystems.erp.apiKey');
  }

  async syncOrderToErp(order: Order): Promise<void> {
    try {
      const erpOrderPayload = this.mapToErpOrder(order);

      const config: AxiosRequestConfig = {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.erpApiKey}`,
          'X-Correlation-ID': order.id,
        },
      };

      const response = await firstValueFrom(
        this.httpService.post(`${this.erpBaseUrl}/api/orders`, erpOrderPayload, config)
      );

      this.logger.log(`Successfully synced order ${order.id} to ERP. ERP Order ID: ${response.data.id}`);
    } catch (error) {
      this.logger.error(`Failed to sync order ${order.id} to ERP: ${error.message}`);
      throw error;
    }
  }

  private mapToErpOrder(order: Order): any {
    // Map our internal order structure to ERP's expected format
    return {
      orderId: order.id,
      customerId: order.customerId,
      totalAmount: order.totalAmount,
      status: this.mapOrderStatusToErp(order.status),
      items: order.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPrice: item.unitPrice,
      })),
      createdAt: order.createdAt.toISOString(),
    };
  }

  private mapOrderStatusToErp(status: OrderStatus): string {
    const statusMap = {
      [OrderStatus.PENDING]: 'NEW',
      [OrderStatus.PROCESSING]: 'PROCESSING',
      [OrderStatus.SHIPPED]: 'SHIPPED',
      [OrderStatus.DELIVERED]: 'DELIVERED',
      [OrderStatus.CANCELLED]: 'CANCELLED',
    };

    return statusMap[status] || 'UNKNOWN';
  }
}
