## Event-Driven Architecture with Kafka

```typescript
// src/modules/order/services/order-event.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { Kafka, Producer, Consumer } from 'kafkajs';
import { Order } from '../entities/order.entity';

@Injectable()
export class OrderEventService {
  private readonly logger = new Logger(OrderEventService.name);
  private kafka: Kafka;
  private producer: Producer;
  private consumer: Consumer;

  constructor(private readonly configService: ConfigService) {
    this.kafka = new Kafka({
      clientId: 'order-service',
      brokers: this.configService.get<string>('kafka.brokers').split(','),
      ssl: this.configService.get<boolean>('kafka.ssl'),
      sasl: {
        mechanism: 'plain',
        username: this.configService.get<string>('kafka.username'),
        password: this.configService.get<string>('kafka.password'),
      },
    });

    this.producer = this.kafka.producer();
    this.consumer = this.kafka.consumer({ groupId: 'order-service-group' });
  }

  async onModuleInit() {
    await this.producer.connect();
    await this.consumer.connect();
    await this.subscribeToTopics();
  }

  async onModuleDestroy() {
    await this.producer.disconnect();
    await this.consumer.disconnect();
  }

  async publishOrderCreatedEvent(order: Order): Promise<void> {
    try {
      await this.producer.send({
        topic: 'order.created',
        messages: [
          {
            key: order.id,
            value: JSON.stringify({
              orderId: order.id,
              customerId: order.customerId,
              totalAmount: order.totalAmount,
              status: order.status,
              createdAt: order.createdAt.toISOString(),
            }),
          },
        ],
      });

      this.logger.log(`Published order.created event for order ${order.id}`);
    } catch (error) {
      this.logger.error(`Failed to publish order.created event: ${error.message}`);
      throw error;
    }
  }

  private async subscribeToTopics() {
    await this.consumer.subscribe({ topic: 'order.status.updated' });

    await this.consumer.run({
      eachMessage: async ({ topic, partition, message }) => {
        try {
          const event = JSON.parse(message.value.toString());
          this.logger.log(`Received event from ${topic}: ${JSON.stringify(event)}`);

          // Process the event (e.g., update order status in database)
          // This would typically be handled by a separate service
        } catch (error) {
          this.logger.error(`Error processing message from ${topic}: ${error.message}`);
        }
      },
    });
  }
}
