// src/orders/orders.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Order } from './entities/order.entity';
import { OrderItem } from './entities/order-item.entity';
import { CreateOrderDto } from './dto/create-order.dto';
import { UpdateOrderDto } from './dto/update-order.dto';
import { OrderRepository } from './repositories/order.repository';
import { OrderItemRepository } from './repositories/order-item.repository';
import { ERPIntegrationService } from '../integrations/erp/erp.service';
import { CRMIntegrationService } from '../integrations/crm/crm.service';
import { OrderStatus } from './enums/order-status.enum';

@Injectable()
export class OrdersService {
  private readonly logger = new Logger(OrdersService.name);

  constructor(
    @InjectRepository(Order)
    private readonly orderRepository: OrderRepository,
    @InjectRepository(OrderItem)
    private readonly orderItemRepository: OrderItemRepository,
    private readonly erpIntegrationService: ERPIntegrationService,
    private readonly crmIntegrationService: CRMIntegrationService,
  ) {}

  async create(createOrderDto: CreateOrderDto): Promise<Order> {
    this.logger.log(`Creating order for customer ${createOrderDto.customerId}`);

    const order = new Order();
    order.customerId = createOrderDto.customerId;
    order.orderDate = new Date(createOrderDto.orderDate);
    order.expectedDeliveryDate = new Date(createOrderDto.expectedDeliveryDate);
    order.shippingAddress = createOrderDto.shippingAddress;
    order.status = createOrderDto.status;

    const savedOrder = await this.orderRepository.save(order);

    // Process order items
    const orderItems = createOrderDto.items.map(item => {
      const orderItem = new OrderItem();
      orderItem.order = savedOrder;
      orderItem.productSku = item.productSku;
      orderItem.quantity = item.quantity;
      orderItem.unitPrice = item.unitPrice;
      return orderItem;
    });

    await this.orderItemRepository.save(orderItems);

    // Integrate with ERP system
    await this.erpIntegrationService.createOrder(savedOrder);

    // Update CRM with order information
    await this.crmIntegrationService.updateCustomerOrderHistory(
      savedOrder.customerId,
      savedOrder.id,
    );

    return savedOrder;
  }

  async findAll(): Promise<Order[]> {
    return this.orderRepository.find({ relations: ['items'] });
  }

  async findOne(id: string): Promise<Order> {
    return this.orderRepository.findOne({
      where: { id },
      relations: ['items'],
    });
  }

  async update(id: string, updateOrderDto: UpdateOrderDto): Promise<Order> {
    const order = await this.orderRepository.findOneBy({ id });

    if (!order) {
      throw new Error('Order not found');
    }

    // Update order fields
    if (updateOrderDto.status) {
      order.status = updateOrderDto.status;
    }

    if (updateOrderDto.expectedDeliveryDate) {
      order.expectedDeliveryDate = new Date(updateOrderDto.expectedDeliveryDate);
    }

    const updatedOrder = await this.orderRepository.save(order);

    // Notify ERP system of status change
    if (updateOrderDto.status) {
      await this.erpIntegrationService.updateOrderStatus(
        updatedOrder.id,
        updatedOrder.status,
      );
    }

    return updatedOrder;
  }

  async remove(id: string): Promise<void> {
    const order = await this.orderRepository.findOneBy({ id });

    if (!order) {
      throw new Error('Order not found');
    }

    // Cancel order in ERP system
    await this.erpIntegrationService.cancelOrder(order.id);

    // Remove order items first
    await this.orderItemRepository.delete({ order: { id } });

    // Then remove the order
    await this.orderRepository.remove(order);
  }
}
