## ERP Integration Service Example

```typescript
// src/integrations/erp/erp.service.ts
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Order } from '../../orders/entities/order.entity';
import { OrderStatus } from '../../orders/enums/order-status.enum';

@Injectable()
export class ERPIntegrationService {
  private readonly logger = new Logger(ERPIntegrationService.name);
  private readonly erpBaseUrl: string;

  constructor(
    private readonly configService: ConfigService,
    private readonly httpService: HttpService,
  ) {
    this.erpBaseUrl = this.configService.get<string>('ERP_API_BASE_URL');
  }

  async createOrder(order: Order): Promise<void> {
    try {
      const response = await firstValueFrom(
        this.httpService.post(`${this.erpBaseUrl}/orders`, {
          orderId: order.id,
          customerId: order.customerId,
          orderDate: order.orderDate.toISOString(),
          expectedDeliveryDate: order.expectedDeliveryDate.toISOString(),
          shippingAddress: order.shippingAddress,
          status: order.status,
        }),
      );

      this.logger.log(`Successfully created order in ERP: ${response.data.orderId}`);
    } catch (error) {
      this.logger.error(`Failed to create order in ERP: ${error.message}`);
      throw new Error('ERP integration failed');
    }
  }

  async updateOrderStatus(orderId: string, status: OrderStatus): Promise<void> {
    try {
      await firstValueFrom(
        this.httpService.patch(`${this.erpBaseUrl}/orders/${orderId}/status`, {
          status,
        }),
      );

      this.logger.log(`Successfully updated order status in ERP: ${orderId}`);
    } catch (error) {
      this.logger.error(`Failed to update order status in ERP: ${error.message}`);
      throw new Error('ERP integration failed');
    }
  }

  async cancelOrder(orderId: string): Promise<void> {
    try {
      await firstValueFrom(
        this.httpService.delete(`${this.erpBaseUrl}/orders/${orderId}`),
      );

      this.logger.log(`Successfully canceled order in ERP: ${orderId}`);
    } catch (error) {
      this.logger.error(`Failed to cancel order in ERP: ${error.message}`);
      throw new Error('ERP integration failed');
    }
  }
}
