// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createLogger } from './utils/logger';
import { configureMiddleware } from './middleware';
import { initializeDatabase } from './database';
import { registerRoutes } from './routes';
import { initializeIntegrationClients } from './integrations';
import { validateConfig } from './config/validation';
import { setupErrorHandling } from './error-handling';

const logger = createLogger('app');

async function bootstrap() {
  try {
    // Validate configuration
    const config = validateConfig();

    // Initialize database connection
    const dbConnection = await initializeDatabase(config.database);

    // Initialize integration clients
    const integrationClients = await initializeIntegrationClients(config.integrations);

    // Create Express app
    const app = express();

    // Configure middleware
    configureMiddleware(app, config);

    // Register routes
    registerRoutes(app, dbConnection, integrationClients);

    // Setup error handling
    setupErrorHandling(app);

    // Create HTTP server
    const server = createServer(app);

    // Start server
    const port = config.server.port || 3000;
    server.listen(port, () => {
      logger.info(`Server running on port ${port}`);
    });

    // Handle shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        dbConnection.close();
        logger.info('Server closed.');
        process.exit(0);
      });
    });

    return { app, server, dbConnection, integrationClients };
  } catch (error) {
    logger.error('Failed to start application:', error);
    process.exit(1);
  }
}

