import { Pool, PoolClient } from 'pg';

export interface DatabaseConnection {
  pool: Pool;
  query: <T = any>(text: string, params?: any[]) => Promise<{ rows: T[] }>;
  getClient: () => Promise<PoolClient>;
  close: () => Promise<void>;
}

// src/database/index.ts - Database implementation
import { Pool, PoolClient } from 'pg';
import { DatabaseConfig } from '../config/types';
import { DatabaseConnection } from './types';
import { createLogger } from '../utils/logger';

const logger = createLogger('database');

export async function initializeDatabase(config: DatabaseConfig): Promise<DatabaseConnection> {
  const pool = new Pool({
    host: config.host,
    port: config.port,
    user: config.username,
    password: config.password,
    database: config.database,
    ssl: config.ssl ? { rejectUnauthorized: false } : false,
    max: config.poolSize || 10,
    connectionTimeoutMillis: config.connectTimeout || 5000,
  });

  // Test the connection
  try {
    const client = await pool.connect();
    client.release();
    logger.info('Database connection established successfully');
  } catch (error) {
    logger.error('Failed to connect to database:', error);
    throw error;
  }

  return {
    pool,
    query: async <T = any>(text: string, params?: any[]) => {
      const start = Date.now();
      try {
        const result = await pool.query<T>(text, params);
        const duration = Date.now() - start;
        logger.debug(`Executed query in ${duration}ms: ${text}`);
        return result;
      } catch (error) {
        logger.error(`Query failed: ${text}`, error);
        throw error;
      }
    },
    getClient: async () => {
      const client = await pool.connect();
      return client;
    },
    close: async () => {
      await pool.end();
      logger.info('Database connection pool closed');
    },
  };
}
