import { IntegrationConfig } from '../config/types';
import { IntegrationClient } from './types';
import { createLogger } from '../utils/logger';
import { ERPClient } from './erp';
import { CRMClient } from './crm';

const logger = createLogger('integrations');

export async function initializeIntegrationClients(configs: IntegrationConfig[]): Promise<Record<string, IntegrationClient<any>>> {
  const clients: Record<string, IntegrationClient<any>> = {};

  for (const config of configs) {
    try {
      let client: IntegrationClient<any>;

      switch (config.name.toLowerCase()) {
        case 'erp':
          client = new ERPClient(config);
          break;
        case 'crm':
          client = new CRMClient(config);
          break;
        // Add other integration clients as needed
        default:
          logger.warn(`Unknown integration type: ${config.name}`);
          continue;
      }

      // Verify the client is working
      const isHealthy = await client.healthCheck();
      if (!isHealthy) {
        throw new Error(`Integration ${config.name} health check failed`);
      }

      clients[config.name] = client;
      logger.info(`Initialized integration client: ${config.name}`);
    } catch (error) {
      logger.error(`Failed to initialize integration client ${config.name}:`, error);
      throw error;
    }
  }

  return clients;
}
