      throw error;
    }

    // Create in database
    const query = `
      INSERT INTO customers (name, email, phone, address, status)
      VALUES ($1, $2, $3, $4, $5)
      RETURNING *;
    `;

    const params = [
      customer.name,
      customer.email,
      customer.phone,
      customer.address,
      'pending',
    ];

    try {
      const result = await this.db.query<Customer>(query, params);
      const newCustomer = result.rows[0];

      // Sync with CRM
      try {
        await this.crmClient.execute({
          action: 'createCustomer',
          customer: newCustomer,
        });
      } catch (error) {
        logger.error('Failed to sync customer with CRM:', error);
