// src/middleware/validation.ts - Request validation middleware
import { Request, Response, NextFunction } from 'express';
import { z, ZodSchema } from 'zod';
import { createLogger } from '../utils/logger';

const logger = createLogger('middleware:validation');

interface ValidationSchema {
  body?: Record<string, any>;
  query?: Record<string, any>;
  params?: Record<string, any>;
}

export function validateRequest(schema: ValidationSchema) {
  return (req: Request, res: Response, next: NextFunction) => {
    try {
      // Convert the schema to Zod schema
      const zodSchema = z.object({
        body: schema.body ? z.object(schema.body) : z.any().optional(),
        query: schema.query ? z.object(schema.query) : z.any().optional(),
        params: schema.params ? z.object(schema.params) : z.any().optional(),
      });

      // Validate the request
      const result = zodSchema.safeParse({
        body: req.body,
        query: req.query,
        params: req.params,
      });

      if (!result.success) {
        logger.warn('Validation failed:', result.error);
        return res.status(400).json({
          message: 'Validation failed',
          errors: result.error.errors,
        });
      }

      next();
    } catch (error) {
      logger.error('Validation middleware error:', error);
      next(error);
    }
  };
}

