## Example Service Layer

```typescript
// src/services/invoice-service.ts
import { Invoice, InvoiceSchema } from '../models/invoice';
import { withTransaction, query } from '../database';
import { CorporateIntegrations } from '../integrations';
import { logger } from '../utils/logger';
import { z } from 'zod';

export class InvoiceService {
  constructor(private integrations: CorporateIntegrations) {}

  async createInvoice(invoiceData: Omit<Invoice, 'id' | 'createdAt' | 'updatedAt'>): Promise<Invoice> {
    const validatedData = InvoiceSchema.omit({
      id: true,
      createdAt: true,
      updatedAt: true,
    }).parse(invoiceData);

    return withTransaction(async (client) => {
      // Insert into local database
      const result = await client.query(
        `INSERT INTO invoices (
          number, customer_id, date, due_date, status,
          items, total_amount, currency
        ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
        RETURNING *`,
        [
          validatedData.number,
          validatedData.customerId,
          validatedData.date,
          validatedData.dueDate,
          validatedData.status,
          JSON.stringify(validatedData.items),
          validatedData.totalAmount,
          validatedData.currency,
        ]
      );

      const invoice = InvoiceSchema.parse(result.rows[0]);

      // Sync with ERP system
      try {
        await this.integrations.erp.createInvoice({
          invoiceId: invoice.id,
          number: invoice.number,
          customerId: invoice.customerId,
          date: invoice.date,
          dueDate: invoice.dueDate,
          items: invoice.items,
          totalAmount: invoice.totalAmount,
          currency: invoice.currency,
        });
      } catch (error) {
        logger.error(`Failed to sync invoice ${invoice.id} with ERP`, error);
        // Consider implementing a retry mechanism or dead letter queue
      }

      return invoice;
    });
  }

  async getInvoiceById(id: string): Promise<Invoice | null> {
    const result = await query(
      'SELECT * FROM invoices WHERE id = $1',
      [id],
      InvoiceSchema
    );

    return result.length > 0 ? result[0] : null;
  }

  async updateInvoiceStatus(
    id: string,
    status: z.infer<typeof InvoiceStatus>
  ): Promise<Invoice> {
    const validatedStatus = InvoiceStatus.parse(status);

    return withTransaction(async (client) => {
      const result = await client.query(
        `UPDATE invoices SET status = $1, updated_at = NOW()
         WHERE id = $2 RETURNING *`,
        [validatedStatus, id]
      );

      if (result.rows.length === 0) {
        throw new Error(`Invoice with ID ${id} not found`);
      }

      const updatedInvoice = InvoiceSchema.parse(result.rows[0]);

      // Sync status with ERP
      try {
        await this.integrations.erp.updateInvoiceStatus(
          updatedInvoice.id,
          updatedInvoice.status
        );
      } catch (error) {
        logger.error(
          `Failed to sync status for invoice ${updatedInvoice.id} with ERP`,
          error
        );
        // Consider implementing a compensation pattern
      }

      return updatedInvoice;
    });
  }
}
