// src/validators/order-validator.ts - Type-safe validation with Zod
import { z } from 'zod';
import { OrderRequest } from '../models';

const orderItemSchema = z.object({
  productId: z.string().min(1),
  quantity: z.number().int().positive(),
  unitPrice: z.number().positive(),
  discount: z.number().min(0).max(1).optional(),
});

const shippingAddressSchema = z.object({
  street: z.string().min(1),
  city: z.string().min(1),
  state: z.string().min(1),
  postalCode: z.string().min(1),
  country: z.string().min(1),
});

const orderRequestSchema = z.object({
  customerId: z.string().min(1),
  items: z.array(orderItemSchema).min(1),
  shippingAddress: shippingAddressSchema,
  paymentMethod: z.enum(['credit_card', 'bank_transfer', 'invoice']),
  notes: z.string().optional(),
});

export function validateOrderRequest(data: unknown): {
  success: boolean;
  data?: OrderRequest;
  errors?: z.ZodError['errors'];
} {
  const result = orderRequestSchema.safeParse(data);

  if (!result.success) {
    return {
      success: false,
      errors: result.error.errors,
    };
  }

  return {
    success: true,
    data: result.data,
  };
}
