## Message Broker Integration

```typescript
// src/message-broker/index.ts - Type-safe message broker integration
import amqp, { Channel, Connection } from 'amqplib';
import { config } from '../config';
import { logger } from '../utils/logger';

interface MessageBrokerConfig {
  url: string;
  exchange: string;
  queue: string;
}

export class MessageBroker {
  private connection: Connection | null = null;
  private channel: Channel | null = null;
  private config: MessageBrokerConfig;

  constructor(config: MessageBrokerConfig) {
    this.config = config;
  }

  async connect(): Promise<void> {
    try {
      this.connection = await amqp.connect(this.config.url);
      this.channel = await this.connection.createChannel();

      // Assert exchange and queue
      await this.channel.assertExchange(this.config.exchange, 'direct', { durable: true });
      await this.channel.assertQueue(this.config.queue, { durable: true });
      await this.channel.bindQueue(this.config.queue, this.config.exchange, '');

      logger.info('Message broker connected and configured');
    } catch (error) {
      logger.error('Failed to connect to message broker', { error });
      throw error;
    }
  }

  async publish<T>(message: T, routingKey: string = ''): Promise<void> {
    if (!this.channel) {
      throw new Error('Message broker not connected');
    }

    try {
      const buffer = Buffer.from(JSON.stringify(message));
      this.channel.publish(this.config.exchange, routingKey, buffer, { persistent: true });
      logger.debug('Message published', { routingKey, message });
    } catch (error) {
      logger.error('Failed to publish message', { error, message });
      throw error;
    }
  }

  async consume<T>(callback: (message: T) => Promise<void>): Promise<void> {
    if (!this.channel) {
      throw new Error('Message broker not connected');
    }

    try {
      await this.channel.consume(this.config.queue, async (msg) => {
        if (msg) {
          try {
            const content = msg.content.toString();
            const message: T = JSON.parse(content);
            await callback(message);
            this.channel?.ack(msg);
          } catch (error) {
            logger.error('Failed to process message', { error, message: msg.content.toString() });
            this.channel?.nack(msg);
          }
        }
      });

      logger.info('Started consuming messages');
    } catch (error) {
      logger.error('Failed to start consuming messages', { error });
      throw error;
    }
  }

  async close(): Promise<void> {
    try {
      if (this.channel) {
        await this.channel.close();
      }
      if (this.connection) {
        await this.connection.close();
      }
      logger.info('Message broker connection closed');
    } catch (error) {
      logger.error('Failed to close message broker connection', { error });
      throw error;
    }
  }
}

let messageBroker: MessageBroker;

export async function initializeMessageBroker(): Promise<void> {
  messageBroker = new MessageBroker({
    url: config.messageBroker.url,
    exchange: config.messageBroker.exchange,
    queue: config.messageBroker.queue,
  });

  await messageBroker.connect();

  // Start consuming messages
  messageBroker.consume(async (message) => {
    logger.info('Received message', { message });
    // Process the message here
  });
}

export async function closeMessageBrokerConnections(): Promise<void> {
  if (messageBroker) {
    await messageBroker.close();
  }
}

export { messageBroker };
