## Error Handling Middleware

```typescript
// src/error-handling.ts - Comprehensive error handling middleware
import { Request, Response, NextFunction } from 'express';
import { logger } from './utils/logger';
import { config } from './config';

interface AppError extends Error {
  statusCode?: number;
  isOperational?: boolean;
  details?: any;
}

export class OperationalError extends Error implements AppError {
  statusCode: number;
  isOperational: boolean;
  details?: any;

  constructor(message: string, statusCode: number, details?: any) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    this.details = details;

    Error.captureStackTrace(this, this.constructor);
  }
}

export class ValidationError extends OperationalError {
  constructor(message: string, details?: any) {
    super(message, 400, details);
    this.name = 'ValidationError';
  }
}

export class NotFoundError extends OperationalError {
  constructor(message: string) {
    super(message, 404);
    this.name = 'NotFoundError';
  }
}

export class UnauthorizedError extends OperationalError {
  constructor(message: string) {
    super(message, 401);
    this.name = 'UnauthorizedError';
  }
}

export class ForbiddenError extends OperationalError {
  constructor(message: string) {
    super(message, 403);
    this.name = 'ForbiddenError';
  }
}

export class InternalServerError extends OperationalError {
  constructor(message: string, details?: any) {
    super(message, 500, details);
    this.name = 'InternalServerError';
  }
}

export function configureErrorHandling(app: express.Application): void {
  // 404 handler
  app.use((req: Request, res: Response, next: NextFunction) => {
    const err = new NotFoundError(`Route ${req.originalUrl} not found`);
    next(err);
  });

  // Error handler
  app.use((err: AppError, req: Request, res: Response, next: NextFunction) => {
    err.statusCode = err.statusCode || 500;
    err.message = err.message || 'Internal Server Error';

    // Log the error
    logger.error(err.message, {
      statusCode: err.statusCode,
      stack: err.stack,
      details: err.details,
    });

    // Send error response
    const errorResponse = {
      status: 'error',
      message: err.message,
      ...(config.env === 'development' && { stack: err.stack }),
      ...(err.details && { details: err.details }),
    };

    res.status(err.statusCode).json(errorResponse);
  });

  // Unhandled promise rejections
  process.on('unhandledRejection', (reason: Error | any) => {
    logger.error('Unhandled Rejection', {
      message: reason.message,
      stack: reason.stack,
    });

    // Exit process if it's a critical error
    if (reason instanceof Error && reason.name === 'InternalServerError') {
      process.exit(1);
    }
  });

  // Uncaught exceptions
  process.on('uncaughtException', (error: Error) => {
    logger.error('Uncaught Exception', {
      message: error.message,
      stack: error.stack,
    });

    // Exit process
    process.exit(1);
  });
}
