interface HealthCheckResult {
  status: 'healthy' | 'degraded' | 'unhealthy';
  version: string;
  uptime: number;
  checks: {
    database: {
      status: 'healthy' | 'unhealthy';
      error?: string;
    };
    cache: {
      status: 'healthy' | 'unhealthy';
      error?: string;
    };
    messageBroker: {
      status: 'healthy' | 'unhealthy';
      error?: string;
    };
    erpIntegration: {
      status: 'healthy' | 'unhealthy';
      error?: string;
    };
    crmIntegration: {
      status: 'healthy' | 'unhealthy';
      error?: string;
    };
  };
}

export function initializeHealthChecks(app: Application): void {
  // Basic health check
  app.get('/health', async (req: Request, res: Response) => {
    res.status(200).json({ status: 'healthy' });
  });

  // Detailed health check
  app.get('/health/detailed', async (req: Request, res: Response) => {
    const result: HealthCheckResult = {
      status: 'healthy',
      version: process.env.npm_package_version || 'unknown',
      uptime: process.uptime(),
      checks: {
        database: { status: 'healthy' },
        cache: { status: 'healthy' },
        messageBroker: { status: 'healthy' },
        erpIntegration: { status: 'healthy' },
        crmIntegration: { status: 'healthy' },
      },
    };

    try {
      // Check database
      await database.query('SELECT 1');
    } catch (error) {
      result.checks.database.status = 'unhealthy';
      result.checks.database.error = error instanceof Error ? error.message : 'Unknown error';
      result.status = 'degraded';
    }

    try {
      // Check cache
      await cache.ping();
    } catch (error) {
      result.checks.cache.status = 'unhealthy';
      result.checks.cache.error = error instanceof Error ? error.message : 'Unknown error';
      result.status = 'degraded';
    }

    try {
      // Check message broker
      // Note: AMQP doesn't have a simple ping, so we'll just check if we can publish
      await messageBroker.publish({ type: 'health-check', timestamp: new Date().toISOString() });
    } catch (error) {
      result.checks.messageBroker.status = 'unhealthy';
      result.checks.messageBroker.error = error instanceof Error ? error.message : 'Unknown error';
      result.status = 'degraded';
    }

    try {
      // Check ERP integration
      // Perform a simple query that doesn't modify data
      await erpSystem.getCustomerDetails('health-check');
    } catch (error) {
      result.checks.erpIntegration.status = 'unhealthy';
      result.checks.erpIntegration.error = error instanceof Error ? error.message : 'Unknown error';
      result.status = 'degraded';
    }

    try {
      // Check CRM integration
      // Perform a simple query that doesn't modify data
      await crmSystem.getContactDetails('health-check');
    } catch (error) {
      result.checks.crmIntegration.status = 'unhealthy';
      result.checks.crmIntegration.error = error instanceof Error ? error.message : 'Unknown error';
      result.status = 'degraded';
    }

    // Determine overall status
    if (result.checks.database.status === 'unhealthy' ||
        result.checks.cache.status === 'unhealthy' ||
        result.checks.messageBroker.status === 'unhealthy') {
      result.status = 'unhealthy';
    }

    // Set appropriate HTTP status code
    const statusCode = result.status === 'healthy' ? 200 :
                      result.status === 'degraded' ? 200 :
                      503;

    res.status(statusCode).json(result);
  });

  // Readiness check
  app.get('/health/ready', async (req: Request, res: Response) => {
    try {
      // Check critical dependencies
      await database.query('SELECT 1');
      await cache.ping();
      await messageBroker.publish({ type: 'readiness-check', timestamp: new Date().toISOString() });

      res.status(200).json({ status: 'ready' });
    } catch (error) {
      logger.error('Readiness check failed', { error });
      res.status(503).json({ status: 'not ready', error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

  // Liveness check
  app.get('/health/live', (req: Request, res: Response) => {
    res.status(200).json({ status: 'alive' });
  });
}
