## Cache Layer

```typescript
// src/cache/index.ts - Type-safe cache layer
import { createClient, RedisClientType } from 'redis';
import { config } from '../config';
import { logger } from '../utils/logger';

interface CacheConfig {
  host: string;
  port: number;
  password?: string;
}

export class Cache {
  private client: RedisClientType;

  constructor(config: CacheConfig) {
    this.client = createClient({
      socket: {
        host: config.host,
        port: config.port,
      },
      password: config.password,
    });

    this.client.on('error', (err) => {
      logger.error('Redis client error', { error: err });
    });

    this.client.on('connect', () => {
      logger.info('Connected to Redis');
    });

    this.client.on('reconnecting', () => {
      logger.info('Reconnecting to Redis');
    });
  }

  async connect(): Promise<void> {
    try {
      await this.client.connect();
    } catch (error) {
      logger.error('Failed to connect to Redis', { error });
      throw error;
    }
  }

  async get<T>(key: string): Promise<T | null> {
    try {
      const value = await this.client.get(key);
      return value ? JSON.parse(value) : null;
    } catch (error) {
      logger.error('Failed to get value from cache', { error, key });
      throw error;
    }
  }

  async set<T>(key: string, value: T, ttl?: number): Promise<void> {
    try {
      const stringValue = JSON.stringify(value);
      if (ttl) {
        await this.client.setEx(key, ttl, stringValue);
      } else {
        await this.client.set(key, stringValue);
      }
    } catch (error) {
      logger.error('Failed to set value in cache', { error, key });
      throw error;
    }
  }

  async del(key: string): Promise<void> {
    try {
      await this.client.del(key);
    } catch (error) {
      logger.error('Failed to delete value from cache', { error, key });
      throw error;
    }
  }

  async ping(): Promise<string> {
    try {
      return await this.client.ping();
    } catch (error) {
      logger.error('Failed to ping Redis', { error });
      throw error;
    }
  }

  async close(): Promise<void> {
    try {
      await this.client.quit();
      logger.info('Redis connection closed');
    } catch (error) {
      logger.error('Failed to close Redis connection', { error });
      throw error;
    }
  }
}

let cache: Cache;

export async function initializeCache(): Promise<void> {
  cache = new Cache({
    host: config.cache.host,
    port: config.cache.port,
    password: config.cache.password,
  });

  await cache.connect();

  // Test the connection
  try {
    await cache.ping();
    logger.info('Cache connection established');
  } catch (error) {
    logger.error('Cache connection failed', { error });
    throw error;
  }
}

export async function closeCacheConnections(): Promise<void> {
  if (cache) {
    await cache.close();
  }
}

export { cache };
