type EventTypes = keyof typeof EventSchemas;

export class EventBus extends EventEmitter {
  async publish<T extends EventTypes>(eventType: T, data: z.infer<(typeof EventSchemas)[T]>) {
    try {
      // Validate event data against schema
      const validatedData = EventSchemas[eventType].parse(data);

      logger.debug(`Publishing event: ${eventType}`, validatedData);
      this.emit(eventType, validatedData);
    } catch (error) {
      logger.error(`Failed to publish event ${eventType}: ${error}`);
      throw error;
    }
  }

  subscribe<T extends EventTypes>(eventType: T, listener: (data: z.infer<(typeof EventSchemas)[T]>) => void) {
    logger.debug(`Subscribing to event: ${eventType}`);
    this.on(eventType, listener);
  }
}

let eventBus: EventBus;

export async function setupEventBus(): Promise<EventBus> {
  if (!eventBus) {
    eventBus = new EventBus();
    logger.info('Event bus initialized');
  }
  return eventBus;
}

export function getEventBus(): EventBus {
  if (!eventBus) {
    throw new Error('Event bus not initialized');
  }
  return eventBus;
}
