### 6. Service Layer (services/user.service.ts)

```typescript
import { Injectable, NotFoundException, ConflictException } from '@nestjs/common';
import { IUserRepository } from '../interfaces/user.repository.interface';
import { CreateUserDto, UpdateUserDto, UserResponseDto } from '../dtos/user.dto';
import { ICorporateIntegrationService } from '../interfaces/corporate-integration.interface';

@Injectable()
export class UserService {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly corporateIntegrationService: ICorporateIntegrationService,
  ) {}

  async createUser(createUserDto: CreateUserDto): Promise<UserResponseDto> {
    // Check if user already exists
    const existingUser = await this.userRepository.findByEmail(createUserDto.email);
    if (existingUser) {
      throw new ConflictException('User with this email already exists');
    }

    // Create user in local database
    const user = await this.userRepository.create(createUserDto);

    // Integrate with corporate systems if enabled
    if (config.ENABLE_CORPORATE_INTEGRATION) {
      await this.corporateIntegrationService.syncUserToCorporateSystem(user);
    }

    return this.mapToResponseDto(user);
  }

  async getAllUsers(): Promise<UserResponseDto[]> {
    const users = await this.userRepository.findAll();
    return users.map(user => this.mapToResponseDto(user));
  }

  async getUserById(id: string): Promise<UserResponseDto> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundException('User not found');
    }
    return this.mapToResponseDto(user);
  }

  async updateUser(id: string, updateUserDto: UpdateUserDto): Promise<UserResponseDto> {
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new NotFoundException('User not found');
    }

    const updatedUser = await this.userRepository.update(id, updateUserDto);

    // Update corporate systems if enabled
    if (config.ENABLE_CORPORATE_INTEGRATION) {
      await this.corporateIntegrationService.syncUserToCorporateSystem(updatedUser);
    }

    return this.mapToResponseDto(updatedUser);
  }

  async deleteUser(id: string): Promise<void> {
    const userExists = await this.userRepository.exists(id);
    if (!userExists) {
      throw new NotFoundException('User not found');
    }

    // Deactivate in corporate systems if enabled
    if (config.ENABLE_CORPORATE_INTEGRATION) {
      await this.corporateIntegrationService.deactivateUserInCorporateSystem(id);
    }

    await this.userRepository.delete(id);
  }

  private mapToResponseDto(user: User): UserResponseDto {
    return {
      id: user.id,
      firstName: user.firstName,
      lastName: user.lastName,
      email: user.email,
      department: user.department,
      role: user.role,
      hireDate: user.hireDate,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    };
  }
}
```

### 7. Corporate Integration Service (services/corporate-integration.service.ts)

```typescript
import { Injectable, Logger } from '@nestjs/common';
import { ICorporateIntegrationService } from '../interfaces/corporate-integration.interface';
import { User } from '../entities/user.entity';
import { config } from '../config/config';
import axios, { AxiosInstance } from 'axios';

@Injectable()
export class CorporateIntegrationService implements ICorporateIntegrationService {
  private readonly logger = new Logger(CorporateIntegrationService.name);
  private readonly httpClient: AxiosInstance;

  constructor() {
    this.httpClient = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      headers: {
        'Authorization': `Bearer ${config.CORPORATE_API_KEY}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async syncUserToCorporateSystem(user: User): Promise<void> {
    try {
      const corporateUserPayload = this.mapUserToCorporateFormat(user);
      await this.httpClient.post('/users', corporateUserPayload);
      this.logger.log(`Successfully synced user ${user.id} to corporate system`);
    } catch (error) {
      this.logger.error(`Failed to sync user ${user.id} to corporate system`, error);
      throw error;
    }
  }

  async deactivateUserInCorporateSystem(userId: string): Promise<void> {
    try {
      await this.httpClient.patch(`/users/${userId}`, { status: 'INACTIVE' });
      this.logger.log(`Successfully deactivated user ${userId} in corporate system`);
    } catch (error) {
      this.logger.error(`Failed to deactivate user ${userId} in corporate system`, error);
      throw error;
    }
  }

  private mapUserToCorporateFormat(user: User): any {
    // Map our internal user format to the corporate system's expected format
    return {
      employeeId: user.id,
      fullName: `${user.firstName} ${user.lastName}`,
      emailAddress: user.email,
      departmentCode: user.department || 'UNKNOWN',
      role: this.mapRoleToCorporateFormat(user.role),
      employmentStatus: 'ACTIVE',
      hireDate: user.hireDate?.toISOString(),
    };
  }

  private mapRoleToCorporateFormat(role: UserRole): string {
    const roleMapping = {
      [UserRole.ADMIN]: 'SYSTEM_ADMIN',
      [UserRole.MANAGER]: 'DEPARTMENT_MANAGER',
      [UserRole.EMPLOYEE]: 'REGULAR_EMPLOYEE',
      [UserRole.GUEST]: 'CONTRACTOR',
    };
    return roleMapping[role] || 'UNKNOWN';
  }
}
```

### 8. Controller (controllers/user.controller.ts)

```typescript
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Param,
  Body,
  HttpCode,
  HttpStatus,
  UsePipes,
  ValidationPipe,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiParam } from '@nestjs/swagger';
import { UserService } from '../services/user.service';
import { CreateUserDto, UpdateUserDto, UserResponseDto } from '../dtos/user.dto';

@ApiTags('users')
@Controller('users')
@UsePipes(new ValidationPipe({ transform: true }))
export class UserController {
  constructor(private readonly userService: UserService) {}

  @Post()
  @ApiOperation({ summary: 'Create a new user' })
  @ApiResponse({ status: 201, description: 'User created', type: UserResponseDto })
  @ApiResponse({ status: 400, description: 'Bad request' })
  @ApiResponse({ status: 409, description: 'User already exists' })
  async createUser(@Body() createUserDto: CreateUserDto): Promise<UserResponseDto> {
    return this.userService.createUser(createUserDto);
  }

  @Get()
  @ApiOperation({ summary: 'Get all users' })
  @ApiResponse({ status: 200, description: 'List of users', type: [UserResponseDto] })
  async getAllUsers(): Promise<UserResponseDto[]> {
    return this.userService.getAllUsers();
  }

  @Get(':id')
  @ApiOperation({ summary: 'Get user by ID' })
  @ApiParam({ name: 'id', description: 'User ID' })
  @ApiResponse({ status: 200, description: 'User found', type: UserResponseDto })
  @ApiResponse({ status: 404, description: 'User not found' })
  async getUserById(@Param('id') id: string): Promise<UserResponseDto> {
    return this.userService.getUserById(id);
  }

  @Put(':id')
  @ApiOperation({ summary: 'Update user by ID' })
  @ApiParam({ name: 'id', description: 'User ID' })
  @ApiResponse({ status: 200, description: 'User updated', type: UserResponseDto })
  @ApiResponse({ status: 400, description: 'Bad request' })
  @ApiResponse({ status: 404, description: 'User not found' })
  async updateUser(
    @Param('id') id: string,
    @Body() updateUserDto: UpdateUserDto,
  ): Promise<UserResponseDto> {
    return this.userService.updateUser(id, updateUserDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  @ApiOperation({ summary: 'Delete user by ID' })
  @ApiParam({ name: 'id', description: 'User ID' })
  @ApiResponse({ status: 204, description: 'User deleted' })
  @ApiResponse({ status: 404, description: 'User not found' })
  async deleteUser(@Param('id') id: string): Promise<void> {
    return this.userService.deleteUser(id);
  }
}
