## Core Architecture

```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createLogger } from './utils/logger';
import { configureMiddleware } from './middleware';
import { configureRoutes } from './routes';
import { initializeDatabase } from './database';
import { initializeCache } from './cache';
import { initializeEventBus } from './event-bus';
import { initializeHealthChecks } from './health';
import { initializeMetrics } from './metrics';
import { initializeConfig } from './config';
import { initializeSecurity } from './security';

const logger = createLogger('app');

async function bootstrap() {
  try {
    // Initialize configuration
    const config = await initializeConfig();

    // Create Express app
    const app = express();

    // Configure middleware
    configureMiddleware(app, config);

    // Initialize core services
    const db = await initializeDatabase(config);
    const cache = await initializeCache(config);
    const eventBus = await initializeEventBus(config);
    const security = await initializeSecurity(config);

    // Configure routes
    configureRoutes(app, { db, cache, eventBus, security });

    // Initialize monitoring
    initializeHealthChecks(app, { db, cache, eventBus });
    initializeMetrics(app);

    // Create HTTP server
    const server = createServer(app);

    // Start server
    const port = config.get('server.port') || 3000;
    server.listen(port, () => {
      logger.info(`Server running on port ${port}`);
    });

    // Handle shutdown
    process.on('SIGTERM', () => gracefulShutdown(server, 'SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown(server, 'SIGINT'));

    return { app, server, config };
  } catch (error) {
    logger.error('Failed to start application', { error });
    process.exit(1);
  }
}

function gracefulShutdown(server: any, signal: string) {
  logger.info(`Received ${signal}, shutting down gracefully`);
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });

  // Force shutdown if not closed in 10 seconds
  setTimeout(() => {
    logger.error('Forcing shutdown');
    process.exit(1);
  }, 10000);
}

// Start the application
bootstrap().catch((error) => {
  logger.error('Application startup failed', { error });
  process.exit(1);
});
