## Corporate System Integration Layer

```typescript
// src/integrations/corporate-systems.ts
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { createLogger } from '../utils/logger';
import { Config } from '../config';

const logger = createLogger('corporate-systems');

interface ERPSystemConfig {
  baseUrl: string;
  apiKey: string;
  timeout: number;
}

interface HRSystemConfig {
  baseUrl: string;
  username: string;
  password: string;
}

export class ERPSystem {
  private client: AxiosInstance;
  private config: ERPSystemConfig;

  constructor(config: ERPSystemConfig) {
    this.config = config;
    this.client = axios.create({
      baseURL: config.baseUrl,
      timeout: config.timeout,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.apiKey}`,
      },
    });

    // Add request interceptor
    this.client.interceptors.request.use((config) => {
      logger.debug('ERP Request', { url: config.url, method: config.method });
      return config;
    });

    // Add response interceptor
    this.client.interceptors.response.use(
      (response) => {
        logger.debug('ERP Response', { status: response.status });
        return response;
      },
      (error) => {
        logger.error('ERP Request Failed', {
          message: error.message,
          config: error.config,
          response: error.response?.data,
        });
        return Promise.reject(error);
      }
    );
  }

  async getEmployeeData(employeeId: string): Promise<EmployeeData> {
    try {
      const response = await this.client.get(`/employees/${employeeId}`);
      return response.data as EmployeeData;
    } catch (error) {
      logger.error('Failed to get employee data', { employeeId, error });
      throw new Error(`Failed to fetch employee data: ${error.message}`);
    }
  }

  async updateEmployeeSalary(employeeId: string, newSalary: number): Promise<void> {
    try {
      await this.client.put(`/employees/${employeeId}/salary`, { newSalary });
    } catch (error) {
      logger.error('Failed to update employee salary', { employeeId, newSalary, error });
      throw new Error(`Failed to update employee salary: ${error.message}`);
    }
  }
}

export class HRSystem {
  private client: AxiosInstance;
  private config: HRSystemConfig;

  constructor(config: HRSystemConfig) {
    this.config = config;
    this.client = axios.create({
      baseURL: config.baseUrl,
      auth: {
        username: config.username,
        password: config.password,
      },
    });
  }

  async getEmployeeDetails(employeeId: string): Promise<HREmployeeDetails> {
    try {
      const response = await this.client.get(`/employees/${employeeId}/details`);
      return response.data as HREmployeeDetails;
    } catch (error) {
      logger.error('Failed to get HR employee details', { employeeId, error });
      throw new Error(`Failed to fetch HR employee details: ${error.message}`);
    }
  }
}

// Type definitions for corporate system data
export interface EmployeeData {
  id: string;
  name: string;
  department: string;
  position: string;
  salary: number;
  hireDate: Date;
  status: 'active' | 'inactive' | 'on-leave';
}

export interface HREmployeeDetails {
  id: string;
  benefits: {
    healthInsurance: boolean;
    retirementPlan: boolean;
    stockOptions: number;
  };
  performanceReviews: Array<{
    year: number;
    rating: 'excellent' | 'good' | 'average' | 'poor';
    comments: string;
  }>;
}

export class CorporateSystems {
  erp: ERPSystem;
  hr: HRSystem;

  constructor(config: Config) {
    this.erp = new ERPSystem(config.corporateSystems.erp);
    this.hr = new HRSystem(config.corporateSystems.hr);
  }
}

export async function initializeCorporateSystems(config: Config): Promise<CorporateSystems> {
  return new CorporateSystems(config);
}
