```typescript
// src/controllers/employee-controller.ts
import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { createLogger } from '../utils/logger';
import { EmployeeService } from '../services/employee-service';
import { validateRequest } from '../middleware/validation';
import { Employee } from '../domain/employee';

const logger = createLogger('employee-controller');

export class EmployeeController {
  constructor(private employeeService: EmployeeService) {}

  // GET /employees/:id
  async getEmployee(req: Request, res: Response, next: NextFunction) {
    try {
      const employeeId = req.params.id;

      // Validate input
      const validationResult = z.string().uuid().safeParse(employeeId);
      if (!validationResult.success) {
        return res.status(400).json({
          error: 'Invalid employee ID format',
          details: validationResult.error.issues,
        });
      }

      const employee = await this.employeeService.getEmployee(employeeId);
      if (!employee) {
        return res.status(404).json({ error: 'Employee not found' });
      }

      res.json(employee);
    } catch (error) {
      logger.error('Failed to get employee', { error });
      next(error);
    }
  }

  // PUT /employees/:id/salary
  async updateSalary(req: Request, res: Response, next: NextFunction) {
    try {
      const employeeId = req.params.id;
      const { newSalary } = req.body;

      // Validate input
      const validationResult = z.object({
        employeeId: z.string().uuid(),
        newSalary: z.number().positive(),
      }).safeParse({ employeeId, newSalary });

      if (!validationResult.success) {
        return res.status(400).json({
          error: 'Invalid request data',
          details: validationResult.error.issues,
        });
      }

      const updatedEmployee = await this.employeeService.updateSalary(
        employeeId,
        newSalary
      );

      res.json(updatedEmployee);
    } catch (error) {
      logger.error('Failed to update employee salary', { error });
      next(error);
    }
  }

  // GET /employees/:id/combined
  async getCombinedEmployeeData(req: Request, res: Response, next: NextFunction) {
    try {
      const employeeId = req.params.id;

      // Validate input
      const validationResult = z.string().uuid().safeParse(employeeId);
      if (!validationResult.success) {
        return res.status(400).json({
          error: 'Invalid employee ID format',
          details: validationResult.error.issues,
        });
      }

      const combinedData = await this.employeeService.getCombinedEmployeeData(employeeId);
      res.json(combinedData);
    } catch (error) {
      logger.error('Failed to get combined employee data', { error });
      next(error);
    }
  }
}
