## Service Layer with Dependency Injection

```typescript
// src/services/employee-service.ts
import { createLogger } from '../utils/logger';
import { Database } from '../database';
import { CorporateSystems } from '../integrations/corporate-systems';
import { Employee, mapToEmployee } from '../domain/employee';
import { Cache } from '../cache';

const logger = createLogger('employee-service');

export class EmployeeService {
  constructor(
    private db: Database,
    private cache: Cache,
    private corporateSystems: CorporateSystems
  ) {}

  async getEmployee(employeeId: string): Promise<Employee | null> {
    // Try to get from cache first
    const cacheKey = `employee:${employeeId}`;
    const cachedEmployee = await this.cache.get<Employee>(cacheKey);
    if (cachedEmployee) {
      logger.debug('Employee found in cache', { employeeId });
      return cachedEmployee;
    }

    // If not in cache, fetch from corporate systems
    try {
      const [erpData, hrDetails] = await Promise.all([
        this.corporateSystems.erp.getEmployeeData(employeeId),
        this.corporateSystems.hr.getEmployeeDetails(employeeId),
      ]);

      const employee = mapToEmployee(erpData, hrDetails);

      // Cache the result
      await this.cache.set(cacheKey, employee, 3600); // Cache for 1 hour

      return employee;
    } catch (error) {
      logger.error('Failed to fetch employee data', { employeeId, error });
      return null;
    }
  }

  async updateSalary(employeeId: string, newSalary: number): Promise<Employee> {
    // Update in ERP system
    await this.corporateSystems.erp.updateEmployeeSalary(employeeId, newSalary);

    // Invalidate cache
    const cacheKey = `employee:${employeeId}`;
    await this.cache.del(cacheKey);

    // Return updated employee data
    return this.getEmployee(employeeId) as Promise<Employee>;
  }

  async getCombinedEmployeeData(employeeId: string): Promise<CombinedEmployeeData> {
    const employee = await this.getEmployee(employeeId);
    if (!employee) {
      throw new Error('Employee not found');
    }

    // Additional processing can be done here
    return {
      ...employee,
      performanceSummary: this.calculatePerformanceSummary(employee.performanceReviews),
    };
  }

  private calculatePerformanceSummary(reviews: Employee['performanceReviews']): PerformanceSummary {
    if (reviews.length === 0) {
      return { averageRating: 'none', highestRating: 'none' };
    }

    const ratings = reviews.map(r => r.rating);
    const ratingValues = {
      excellent: 4,
      good: 3,
      average: 2,
      poor: 1,
    };

    const numericRatings = ratings.map(r => ratingValues[r as keyof typeof ratingValues]);
    const average = numericRatings.reduce((sum, val) => sum + val, 0) / numericRatings.length;

    let averageRating: 'excellent' | 'good' | 'average' | 'poor';
    if (average >= 3.5) averageRating = 'excellent';
    else if (average >= 2.5) averageRating = 'good';
    else if (average >= 1.5) averageRating = 'average';
    else averageRating = 'poor';

    const highestRating = ratings.reduce((highest, current) => {
      return ratingValues[current as keyof typeof ratingValues] >
             ratingValues[highest as keyof typeof ratingValues]
        ? current
        : highest;
    });

    return {
      averageRating,
      highestRating,
    };
  }
}

interface CombinedEmployeeData extends Employee {
  performanceSummary: PerformanceSummary;
}

interface PerformanceSummary {
  averageRating: 'excellent' | 'good' | 'average' | 'poor' | 'none';
  highestRating: 'excellent' | 'good' | 'average' | 'poor' | 'none';
}
