## Testing Framework

```typescript
// src/test/test-utils.ts
import { z } from 'zod';
import { createLogger } from '../utils/logger';
import { Database } from '../database';
import { Cache } from '../cache';
import { CorporateSystems } from '../integrations/corporate-systems';

const logger = createLogger('test-utils');

export interface TestContext {
  db: Database;
  cache: Cache;
  corporateSystems: CorporateSystems;
  cleanupTasks: Array<() => Promise<void>>;
}

export async function setupTestContext(): Promise<TestContext> {
  // Initialize test database
  const db = new Database({
    url: process.env.TEST_DB_URL || 'postgres://test:test@localhost:5432/test_db',
    poolSize: 1,
    ssl: false,
  });

  // Initialize test cache
  const cache = new Cache({
    host: process.env.TEST_REDIS_HOST || 'localhost',
    port: parseInt(process.env.TEST_REDIS_PORT || '6380'),
    ttl: 300, // 5 minutes for tests
  });

  // Initialize test corporate systems with mock implementations
  const corporateSystems = new CorporateSystems({
    corporateSystems: {
      erp: {
        baseUrl: 'http://mock-erp.example.com',
        apiKey: 'test-api-key',
        timeout: 5000,
      },
      hr: {
        baseUrl: 'http://mock-hr.example.com',
        username: 'test',
        password: 'test',
      },
    },
  });

  // Add cleanup tasks
  const cleanupTasks: Array<() => Promise<void>> = [
    async () => {
      // Clear test database
      await db.query('TRUNCATE TABLE employees CASCADE');
    },
    async () => {
      // Flush test cache
      await cache.flush();
    },
  ];

  return { db, cache, corporateSystems, cleanupTasks };
}

export async function teardownTestContext(context: TestContext): Promise<void> {
  try {
    // Execute all cleanup tasks
    await Promise.all(context.cleanupTasks.map(task => task()));

    // Close connections
    await context.db.close();
    await context.cache.close();
  } catch (error) {
    logger.error('Failed to clean up test context', { error });
    throw error;
  }
}

