## Database Layer with Type Safety

```typescript
// src/database/index.ts
import { Pool, PoolClient } from 'pg';
import { z } from 'zod';
import { createLogger } from '../utils/logger';

const logger = createLogger('database');

interface DatabaseConfig {
  url: string;
  poolSize: number;
}

export class Database {
  private pool: Pool;

  constructor(config: DatabaseConfig) {
    this.pool = new Pool({
      connectionString: config.url,
      max: config.poolSize,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 2000,
    });

    this.pool.on('error', (err) => {
      logger.error('Unexpected error on idle client', err);
    });
  }

  async query<T>(text: string, params?: any[]): Promise<T[]> {
    const start = Date.now();
    try {
      const result = await this.pool.query(text, params);
      const duration = Date.now() - start;
      logger.debug(`Executed query in ${duration}ms: ${text}`);
      return result.rows;
    } catch (err) {
      logger.error(`Error executing query: ${text}`, err);
      throw err;
    }
  }

  async getClient(): Promise<PoolClient> {
    const client = await this.pool.connect();
    const query = client.query;
    const release = client.release;

    // Set a timeout of 5 seconds
    const timeout = setTimeout(() => {
      logger.error('A client has been checked out for more than 5 seconds!');
    }, 5000);

    // Monkey patch the query method to keep track of the last query executed
    client.query = (...args: Parameters<typeof query>) => {
      logger.debug('Executing query:', args[0]);
      return query.apply(client, args);
    };

    client.release = () => {
      // Clear our timeout
      clearTimeout(timeout);
      // Set the methods back to their old un-monkey-patched version
      client.query = query;
      client.release = release;
      return release.apply(client);
    };

    return client;
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

// Example of a type-safe repository
export class UserRepository {
  constructor(private db: Database) {}

  private userSchema = z.object({
    id: z.string().uuid(),
    username: z.string().min(3).max(50),
    email: z.string().email(),
    role: z.enum(['admin', 'user', 'guest']),
    createdAt: z.date(),
    updatedAt: z.date()
  });

  type User = z.infer<typeof this.userSchema>;

  async getUserById(id: string): Promise<User | null> {
    const query = 'SELECT * FROM users WHERE id = $1';
    const result = await this.db.query<User>(query, [id]);
    if (result.length === 0) return null;
    return this.userSchema.parse(result[0]);
  }

  async createUser(user: Omit<User, 'id' | 'createdAt' | 'updatedAt'>): Promise<User> {
    const query = `
      INSERT INTO users (username, email, role)
      VALUES ($1, $2, $3)
      RETURNING *`;
    const result = await this.db.query<User>(query, [
      user.username,
      user.email,
      user.role
    ]);
    return this.userSchema.parse(result[0]);
  }
}

export async function initializeDatabase(config: any): Promise<Database> {
  const dbConfig: DatabaseConfig = {
    url: config.get('database.url'),
    poolSize: config.get('database.poolSize')
  };

  const db = new Database(dbConfig);

  // Test the connection
  try {
    await db.query('SELECT 1');
    logger.info('Database connection established');
    return db;
  } catch (err) {
    logger.error('Failed to connect to database', err);
    await db.close();
    throw err;
  }
}
