## Corporate System Integration Layer

```typescript
// src/integrations/corporate-systems.ts
import axios, { AxiosInstance, AxiosRequestConfig } from 'axios';
import { z } from 'zod';
import { createLogger } from '../utils/logger';

const logger = createLogger('corporate-systems');

interface CorporateSystemConfig {
  baseUrl: string;
  apiKey: string;
  timeout: number;
}

abstract class CorporateSystemClient {
  protected client: AxiosInstance;
  protected config: CorporateSystemConfig;

  constructor(config: CorporateSystemConfig) {
    this.config = config;
    this.client = axios.create({
      baseURL: config.baseUrl,
      timeout: config.timeout,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.apiKey}`
      }
    });

    this.client.interceptors.request.use((config) => {
      logger.debug(`Request to ${config.baseURL}${config.url}`, {
        method: config.method,
        data: config.data
      });
      return config;
    });

    this.client.interceptors.response.use(
      (response) => {
        logger.debug(`Response from ${response.config.baseURL}${response.config.url}`, {
          status: response.status,
          data: response.data
        });
        return response;
      },
      (error) => {
        logger.error(`Error in request to ${error.config?.baseURL}${error.config?.url}`, {
          status: error.response?.status,
          data: error.response?.data,
          message: error.message
        });
        return Promise.reject(error);
      }
    );
  }

  protected async request<T>(config: AxiosRequestConfig): Promise<T> {
    try {
      const response = await this.client.request<T>(config);
      return response.data;
    } catch (error) {
      if (axios.isAxiosError(error)) {
        throw new CorporateSystemError(
          error.response?.status || 500,
          error.message,
          error.response?.data
        );
      }
      throw error;
    }
  }
}

export class ERPClient extends CorporateSystemClient {
  // Define schemas for ERP responses
  private employeeSchema = z.object({
    employeeId: z.string(),
    firstName: z.string(),
    lastName: z.string(),
    department: z.string(),
    position: z.string(),
    hireDate: z.string().datetime(),
    status: z.enum(['active', 'inactive', 'terminated'])
  });

  type Employee = z.infer<typeof this.employeeSchema>;

  async getEmployeeById(employeeId: string): Promise<Employee> {
    const response = await this.request<Employee>({
      method: 'GET',
      url: `/employees/${employeeId}`
    });
    return this.employeeSchema.parse(response);
  }

  async getEmployeesByDepartment(department: string): Promise<Employee[]> {
    const response = await this.request<Employee[]>({
      method: 'GET',
      url: '/employees',
      params: { department }
    });
    return z.array(this.employeeSchema).parse(response);
  }
}

export class CRMClient extends CorporateSystemClient {
  // Define schemas for CRM responses
  private customerSchema = z.object({
    customerId: z.string(),
    name: z.string(),
    email: z.string().email(),
    phone: z.string().optional(),
    address: z.object({
      street: z.string(),
      city: z.string(),
      state: z.string(),
      zipCode: z.string()
    }).optional(),
    status: z.enum(['prospect', 'active', 'inactive']),
    createdAt: z.string().datetime()
  });

  type Customer = z.infer<typeof this.customerSchema>;

  async getCustomerById(customerId: string): Promise<Customer> {
    const response = await this.request<Customer>({
      method: 'GET',
      url: `/customers/${customerId}`
    });
    return this.customerSchema.parse(response);
  }

  async createCustomer(customer: Omit<Customer, 'customerId' | 'createdAt'>): Promise<Customer> {
    const response = await this.request<Customer>({
      method: 'POST',
      url: '/customers',
      data: customer
    });
    return this.customerSchema.parse(response);
  }
}

export class HRISClient extends CorporateSystemClient {
  // Define schemas for HRIS responses
  private timeOffRequestSchema = z.object({
    requestId: z.string(),
    employeeId: z.string(),
    startDate: z.string().datetime(),
    endDate: z.string().datetime(),
    type: z.enum(['vacation', 'sick', 'personal', 'unpaid']),
    status: z.enum(['pending', 'approved', 'rejected']),
    comments: z.string().optional()
  });

  type TimeOffRequest = z.infer<typeof this.timeOffRequestSchema>;

  async getTimeOffRequests(employeeId: string): Promise<TimeOffRequest[]> {
    const response = await this.request<TimeOffRequest[]>({
      method: 'GET',
      url: '/time-off',
      params: { employeeId }
    });
    return z.array(this.timeOffRequestSchema).parse(response);
  }

  async submitTimeOffRequest(request: Omit<TimeOffRequest, 'requestId' | 'status'>): Promise<TimeOffRequest> {
    const response = await this.request<TimeOffRequest>({
      method: 'POST',
      url: '/time-off',
      data: request
    });
    return this.timeOffRequestSchema.parse(response);
  }
}

export class CorporateSystemError extends Error {
  constructor(
    public statusCode: number,
    message: string,
    public details?: any
  ) {
    super(message);
    this.name = 'CorporateSystemError';
  }
}

export async function initializeCorporateSystems(config: any): Promise<{
  erp: ERPClient;
  crm: CRMClient;
  hris: HRISClient;
}> {
  const erpConfig: CorporateSystemConfig = {
    baseUrl: config.get('corporateSystems.erp.baseUrl'),
    apiKey: config.get('corporateSystems.erp.apiKey'),
    timeout: config.get('corporateSystems.erp.timeout')
  };

  const crmConfig: CorporateSystemConfig = {
    baseUrl: config.get('corporateSystems.crm.baseUrl'),
    apiKey: config.get('corporateSystems.crm.apiKey'),
    timeout: config.get('corporateSystems.crm.timeout')
  };

  const hrisConfig: CorporateSystemConfig = {
    baseUrl: config.get('corporateSystems.hris.baseUrl'),
    apiKey: config.get('corporateSystems.hris.apiKey'),
    timeout: config.get('corporateSystems.hris.timeout')
  };

  return {
    erp: new ERPClient(erpConfig),
    crm: new CRMClient(crmConfig),
    hris: new HRISClient(hrisConfig)
  };
}
