## API Controller with Type Safety

```typescript
// src/controllers/user.controller.ts
import { Request, Response, NextFunction } from 'express';
import { z } from 'zod';
import { UserRepository } from '../database';
import { createLogger } from '../utils/logger';
import { validateRequest } from '../middleware/validation';
import { ERPClient } from '../integrations/corporate-systems';

const logger = createLogger('user-controller');

export class UserController {
  constructor(
    private userRepository: UserRepository,
    private erpClient: ERPClient
  ) {}

  // Define request schemas
  private createUserSchema = z.object({
    body: z.object({
      username: z.string().min(3).max(50),
      email: z.string().email(),
      role: z.enum(['admin', 'user', 'guest']).default('user'),
      employeeId: z.string().optional()
    })
  });

  private getUserSchema = z.object({
    params: z.object({
      id: z.string().uuid()
    })
  });

  // Controller methods
  async createUser(req: Request, res: Response, next: NextFunction) {
    try {
      // Validate request
      const validated = this.createUserSchema.parse(req);

      // If employeeId is provided, validate with ERP
      let employeeData = null;
      if (validated.body.employeeId) {
        try {
          employeeData = await this.erpClient.getEmployeeById(validated.body.employeeId);
        } catch (error) {
          logger.error('Failed to validate employee with ERP', error);
          return res.status(400).json({
            error: 'Invalid employee ID',
            details: 'Employee not found in corporate HR system'
          });
        }
      }

      // Create user
      const user = await this.userRepository.createUser({
        username: validated.body.username,
        email: validated.body.email,
        role: validated.body.role
      });

      // Return response
      res.status(201).json({
        user,
        employeeData
      });
    } catch (error) {
      next(error);
    }
  }

  async getUser(req: Request, res: Response, next: NextFunction) {
    try {
      // Validate request
      const validated = this.getUserSchema.parse(req);

      // Get user
      const user = await this.userRepository.getUserById(validated.params.id);

      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }

      // Return response
      res.json({ user });
    } catch (error) {
      next(error);
    }
  }

  // Register routes
  registerRoutes(app: any) {
    app.post(
      '/users',
      validateRequest(this.createUserSchema),
      this.createUser.bind(this)
    );

    app.get(
      '/users/:id',
      validateRequest(this.getUserSchema),
      this.getUser.bind(this)
    );
  }
}
