## Error Handling System

```typescript
// src/error-handling/index.ts
import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { createLogger } from '../utils/logger';
import { CorporateSystemError } from '../integrations/corporate-systems';

const logger = createLogger('error-handler');

export class AppError extends Error {
  constructor(
    public statusCode: number,
    message: string,
    public details?: any
  ) {
    super(message);
    this.name = this.constructor.name;
    Error.captureStackTrace(this, this.constructor);
  }
}

export function initializeErrorHandling(app: any) {
  // Catch 404 and forward to error handler
  app.use((req: Request, res: Response, next: NextFunction) => {
    const err = new AppError(404, 'Not Found');
    next(err);
  });

  // Error handler
  app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
    // Handle Zod validation errors
    if (err instanceof ZodError) {
      logger.warn('Validation error', {
        errors: err.errors,
        path: req.path
      });
      return res.status(400).json({
        error: 'Validation failed',
        details: err.errors
      });
    }

    // Handle corporate system errors
    if (err instanceof CorporateSystemError) {
      logger.error('Corporate system error', {
        status: err.statusCode,
        message: err.message,
        details: err.details,
        path: req.path
      });

      return res.status(err.statusCode).json({
        error: 'Corporate system integration failed',
        details: err.details || err.message
      });
    }

    // Handle application errors
    if (err instanceof AppError) {
      logger.error('Application error', {
        status: err.statusCode,
        message: err.message,
        details: err.details,
        path: req.path
      });

      return res.status(err.statusCode).json({
        error: err.message,
        details: err.details
      });
    }

    // Handle other errors
    logger.error('Unexpected error', {
      message: err.message,
      stack: err.stack,
      path: req.path
    });

    // Don't expose stack traces in production
    const response = {
      error: 'Internal Server Error',
      ...(process.env.NODE_ENV === 'development' && {
        details: err.message,
        stack: err.stack
      })
    };

    res.status(500).json(response);
  });
}
