// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { configureMiddleware } from './middleware';
import { configureRoutes } from './routes';
import { configureErrorHandling } from './error-handling';
import { configureHealthChecks } from './health';
import { configureLogging } from './logging';
import { initializeDatabase } from './database';
import { initializeCache } from './cache';
import { initializeMessageBroker } from './message-broker';
import { initializeApiClients } from './api-clients';
import { validateConfig } from './config';

async function bootstrap() {
  // Validate configuration first
  validateConfig();

  // Initialize core services
  const db = await initializeDatabase();
  const cache = await initializeCache();
  const messageBroker = await initializeMessageBroker();
  const apiClients = await initializeApiClients();

  // Create Express app
