## Message Broker Integration

```typescript
// src/message-broker.ts - Type-safe message broker integration
import { connect, Connection, Channel } from 'amqplib';
import { getConfig } from './config';
import { z } from 'zod';

const messageBrokerConfigSchema = z.object({
  url: z.string().url(),
  exchange: z.string().default('enterprise.events'),
  queues: z.record(z.string()),
});

type MessageBrokerConfig = z.infer<typeof messageBrokerConfigSchema>;

export class MessageBroker {
  private connection: Connection | null = null;
  private channel: Channel | null = null;

  constructor(private config: MessageBrokerConfig) {}

  async connect(): Promise<void> {
    this.connection = await connect(this.config.url);
    this.channel = await this.connection.createChannel();

    // Assert exchange
    await this.channel.assertExchange(this.config.exchange, 'topic', { durable: true });

    // Assert queues
    for (const [queueName, routingKey] of Object.entries(this.config.queues)) {
      await this.channel.assertQueue(queueName, { durable: true });
      await this.channel.bindQueue(queueName, this.config.exchange, routingKey);
    }
  }

  async publish(routingKey: string, message: unknown): Promise<void> {
    if (!this.channel) {
      throw new Error('Message broker not connected');
    }

    const messageBuffer = Buffer.from(JSON.stringify(message));
    this.channel.publish(this.config.exchange, routingKey, messageBuffer);
  }

  async consume(queueName: string, handler: (message: unknown) => Promise<void>): Promise<void> {
    if (!this.channel) {
      throw new Error('Message broker not connected');
    }

    await this.channel.consume(queueName, async (msg) => {
      if (msg) {
        try {
          const content = JSON.parse(msg.content.toString());
          await handler(content);
          this.channel?.ack(msg);
        } catch (error) {
          console.error('Error processing message:', error);
          this.channel?.nack(msg);
        }
      }
    });
  }

  async close(): Promise<void> {
    if (this.connection) {
      await this.connection.close();
    }
  }
}

export async function initializeMessageBroker(): Promise<MessageBroker> {
  const config = getConfig();

  const brokerConfig = messageBrokerConfigSchema.parse({
    url: config.RABBITMQ_URL,
    exchange: 'enterprise.events',
    queues: {
      'order.processing': 'order.created',
      'payment.processing': 'payment.requested',
      // Other queues...
    },
  });

  const broker = new MessageBroker(brokerConfig);
  await broker.connect();
  return broker;
}
