## Database Layer with Type Safety

```typescript
// src/database/index.ts - Type-safe database layer
import { Pool, PoolClient } from 'pg';
import { appConfig } from '../config';
import { logger } from '../utils/logger';
import { DatabaseError } from '../errors';

interface DatabaseConfig {
  connectionString: string;
  max: number;
}

export class Database {
  private pool: Pool;

  constructor(config: DatabaseConfig) {
    this.pool = new Pool({
      connectionString: config.connectionString,
      max: config.max,
    });

    this.pool.on('error', (err) => {
      logger.error('Unexpected database error', { error: err });
    });
  }

  public async query<T extends Record<string, unknown>>(
    text: string,
    params?: unknown[]
  ): Promise<T[]> {
    try {
      const result = await this.pool.query(text, params);
      return result.rows as T[];
    } catch (error) {
      logger.error('Database query failed', { error, query: text });
      throw new DatabaseError('Database query failed', error);
    }
  }

  public async getClient(): Promise<PoolClient> {
    try {
      return await this.pool.connect();
    } catch (error) {
      logger.error('Failed to get database client', { error });
      throw new DatabaseError('Failed to get database client', error);
    }
  }

  public async close(): Promise<void> {
    await this.pool.end();
    logger.info('Database connection pool closed');
  }
}

let databaseInstance: Database | null = null;

export const initializeDatabase = async (): Promise<Database> => {
  if (!databaseInstance) {
    databaseInstance = new Database({
      connectionString: appConfig.database.url,
      max: appConfig.database.poolSize,
    });

    // Test the connection
    try {
      await databaseInstance.query('SELECT 1');
      logger.info('Database connection established');
    } catch (error) {
      logger.error('Failed to establish database connection', { error });
      throw error;
    }
  }

  return databaseInstance;
};
