## Corporate System Integration Layer

```typescript
// src/integrations/corporate-systems.ts - Type-safe corporate system integration
import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
import { appConfig } from '../config';
import { logger } from '../utils/logger';
import { IntegrationError } from '../errors';

interface CorporateSystemConfig {
  baseURL: string;
  apiKey: string;
  timeout?: number;
}

interface CorporateSystemResponse<T> {
  data: T;
  status: number;
  headers: Record<string, string>;
}

export class CorporateSystemIntegration {
  private client: AxiosInstance;
  private config: CorporateSystemConfig;

  constructor(config: CorporateSystemConfig) {
    this.config = config;
    this.client = axios.create({
      baseURL: config.baseURL,
      timeout: config.timeout || 5000,
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': config.apiKey,
      },
    });

    // Add request interceptor
    this.client.interceptors.request.use((config) => {
      logger.debug('Corporate system request', {
        method: config.method,
        url: config.url,
      });
      return config;
    });

    // Add response interceptor
    this.client.interceptors.response.use(
      (response) => {
        logger.debug('Corporate system response', {
          status: response.status,
          url: response.config.url,
        });
        return response;
      },
      (error) => {
        logger.error('Corporate system request failed', {
          error: error.message,
          config: error.config,
        });
        return Promise.reject(error);
      }
    );
  }

  public async get<T>(
    endpoint: string,
    params?: Record<string, unknown>
  ): Promise<CorporateSystemResponse<T>> {
    try {
      const response = await this.client.get<T>(endpoint, { params });
      return this.transformResponse(response);
    } catch (error) {
      throw new IntegrationError('Corporate system GET request failed', error);
    }
  }

  public async post<T>(
    endpoint: string,
    data: unknown,
    config?: AxiosRequestConfig
  ): Promise<CorporateSystemResponse<T>> {
    try {
      const response = await this.client.post<T>(endpoint, data, config);
      return this.transformResponse(response);
    } catch (error) {
      throw new IntegrationError('Corporate system POST request failed', error);
    }
  }

  // Add other HTTP methods as needed (PUT, DELETE, PATCH)

  private transformResponse<T>(
    response: AxiosResponse<T>
  ): CorporateSystemResponse<T> {
    return {
      data: response.data,
      status: response.status,
      headers: response.headers as Record<string, string>,
    };
  }
}

let corporateSystemInstance: CorporateSystemIntegration | null = null;

export const initializeCorporateSystemIntegration = (): CorporateSystemIntegration => {
