## Repository Pattern Implementation

```typescript
// src/repositories/user.repository.ts - Type-safe repository pattern
import { Database } from '../database';
import { User, UserCreate, UserUpdate } from '../models/user.model';
import { logger } from '../utils/logger';
import { RepositoryError } from '../errors';

export class UserRepository {
  constructor(private db: Database) {}

  public async findById(id: string): Promise<User | null> {
    try {
      const query = `
        SELECT * FROM users
        WHERE id = $1
      `;
      const result = await this.db.query<User>(query, [id]);
      return result.length > 0 ? result[0] : null;
    } catch (error) {
      logger.error('Failed to find user by ID', { error, id });
      throw new RepositoryError('Failed to find user by ID', error);
    }
  }

  public async findByEmail(email: string): Promise<User | null> {
    try {
      const query = `
        SELECT * FROM users
        WHERE email = $1
      `;
      const result = await this.db.query<User>(query, [email]);
      return result.length > 0 ? result[0] : null;
    } catch (error) {
      logger.error('Failed to find user by email', { error, email });
      throw new RepositoryError('Failed to find user by email', error);
    }
  }

  public async create(user: UserCreate): Promise<User> {
    try {
      const query = `
        INSERT INTO users (
          username, email, first_name, last_name, department, role, status
        ) VALUES (
          $1, $2, $3, $4, $5, $6, $7
        ) RETURNING *
      `;
      const values = [
        user.username,
        user.email,
        user.firstName,
        user.lastName,
        user.department,
        user.role,
        user.status,
      ];
      const result = await this.db.query<User>(query, values);
      return result[0];
    } catch (error) {
      logger.error('Failed to create user', { error, user });
      throw new RepositoryError('Failed to create user', error);
    }
  }

  public async update(id: string, user: UserUpdate): Promise<User | null> {
    try {
      const fields = Object.keys(user);
      if (fields.length === 0) {
        return this.findById(id);
      }

      const setClause = fields
        .map((field, index) => `${field} = $${index + 2}`)
        .join(', ');

      const query = `
        UPDATE users
        SET ${setClause}
        WHERE id = $1
        RETURNING *
      `;

      const values = [id, ...Object.values(user)];
      const result = await this.db.query<User>(query, values);
      return result.length > 0 ? result[0] : null;
    } catch (error) {
      logger.error('Failed to update user', { error, id, user });
      throw new RepositoryError('Failed to update user', error);
    }
  }

  public async delete(id: string): Promise<boolean> {
    try {
      const query = `
        DELETE FROM users
        WHERE id = $1
      `;
      const result = await this.db.query(query, [id]);
      return result.length > 0;
    } catch (error) {
      logger.error('Failed to delete user', { error, id });
      throw new RepositoryError('Failed to delete user', error);
    }
  }
}
