// src/services/user.service.ts - Service layer with dependency injection
import { UserRepository } from '../repositories/user.repository';
import { User, UserCreate, UserUpdate } from '../models/user.model';
import { logger } from '../utils/logger';
import { ServiceError } from '../errors';
import { CorporateSystemIntegration } from '../integrations/corporate-systems';

export class UserService {
  constructor(
    private userRepository: UserRepository,
    private corporateSystem: CorporateSystemIntegration
  ) {}

  public async getUserById(id: string): Promise<User> {
    try {
      const user = await this.userRepository.findById(id);
      if (!user) {
        throw new ServiceError('User not found', 404);
      }
      return user;
    } catch (error) {
      logger.error('Failed to get user by ID', { error, id });
      throw new ServiceError('Failed to get user', error);
    }
  }

  public async createUser(user: UserCreate): Promise<User> {
    try {
      // Validate user data against corporate system
      const validationResponse = await this.corporateSystem.post<{
        isValid: boolean;
        message?: string;
      }>('/validate-user', user);

      if (!validationResponse.data.isValid) {
        throw new ServiceError(
          validationResponse.data.message || 'User validation failed',
          400
        );
      }

      // Create user in local database
      const createdUser = await this.userRepository.create(user);

      // Notify corporate system about new user
      await this.corporateSystem.post('/user-created', createdUser);

      return createdUser;
    } catch (error) {
      logger.error('Failed to create user', { error, user });
      throw new ServiceError('Failed to create user', error);
    }
  }

  public async updateUser(id: string, user: UserUpdate): Promise<User> {
    try {
      const existingUser = await this.userRepository.findById(id);
      if (!existingUser) {
        throw new ServiceError('User not found', 404);
      }

      // Validate update against corporate system
      const validationResponse = await this.corporateSystem.post<{
        isValid: boolean;
        message?: string;
      }>('/validate-user-update', { id, ...user });

      if (!validationResponse.data.isValid) {
        throw new ServiceError(
          validationResponse.data.message || 'User update validation failed',
          400
        );
      }

      const updatedUser = await this.userRepository.update(id, user);

      if (!updatedUser) {
        throw new ServiceError('Failed to update user', 500);
      }

      // Notify corporate system about update
      await this.corporateSystem.post('/user-updated', updatedUser);

      return updatedUser;
    } catch (error) {
      logger.error('Failed to update user', { error, id, user });
      throw new ServiceError('Failed to update user', error);
    }
  }

  public async deleteUser(id: string): Promise<boolean> {
    try {
      const user = await this.userRepository.findById(id);
      if (!user) {
        throw new ServiceError('User not found', 404);
      }

      // Check with corporate system if deletion is allowed
      const validationResponse = await this.corporateSystem.post<{
        isAllowed: boolean;
        message?: string;
      }>('/validate-user-deletion', { id });

      if (!validationResponse.data.isAllowed) {
        throw new ServiceError(
          validationResponse.data.message || 'User deletion not allowed',
          403
        );
      }

      const deleted = await this.userRepository.delete(id);

      if (deleted) {
        // Notify corporate system about deletion
        await this.corporateSystem.post('/user-deleted', { id });
      }

      return deleted;
    } catch (error) {
      logger.error('Failed to delete user', { error, id });
      throw new ServiceError('Failed to delete user', error);
    }
  }
}
