// src/controllers/user.controller.ts - Controller with request validation
import { Request, Response, NextFunction } from 'express';
import { UserService } from '../services/user.service';
import { UserCreateSchema, UserUpdateSchema } from '../models/user.model';
import { logger } from '../utils/logger';
import { ValidationError } from '../errors';

export class UserController {
  constructor(private userService: UserService) {}

  public async getUser(
    req: Request<{ id: string }>,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      const { id } = req.params;
      const user = await this.userService.getUserById(id);
      res.json(user);
    } catch (error) {
      next(error);
    }
  }

  public async createUser(
    req: Request<{}, {}, UserCreateSchema>,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      const validation = UserCreateSchema.safeParse(req.body);
      if (!validation.success) {
        throw new ValidationError('Invalid user data', validation.error);
      }

      const user = await this.userService.createUser(validation.data);
      res.status(201).json(user);
    } catch (error) {
      next(error);
    }
  }

  public async updateUser(
    req: Request<{ id: string }, {}, UserUpdateSchema>,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      const { id } = req.params;
      const validation = UserUpdateSchema.safeParse(req.body);
      if (!validation.success) {
        throw new ValidationError('Invalid user update data', validation.error);
      }

      const user = await this.userService.updateUser(id, validation.data);
      res.json(user);
    } catch (error) {
      next(error);
    }
  }

  public async deleteUser(
    req: Request<{ id: string }>,
    res: Response,
    next: NextFunction
  ): Promise<void> {
    try {
      const { id } = req.params;
      const deleted = await this.userService.deleteUser(id);
      res.status(deleted ? 204 : 404).end();
    } catch (error) {
      next(error);
    }
  }
