## Dependency Injection Container

```typescript
// src/container.ts - Dependency injection container
import { asClass, asFunction, asValue, createContainer } from 'awilix';
import { scopePerRequest } from 'awilix-express';
import { Database, initializeDatabase } from './database';
import { UserRepository } from './repositories/user.repository';
import { UserService } from './services/user.service';
import { UserController } from './controllers/user.controller';
import { initializeCorporateSystemIntegration } from './integrations/corporate-systems';
import { logger } from './utils/logger';

export const configureContainer = async () => {
  const container = createContainer();

  // Register core services
  container.register({
    logger: asValue(logger),
    db: asFunction(initializeDatabase).singleton(),
    corporateSystem: asFunction(initializeCorporateSystemIntegration).singleton(),
  });

  // Register repositories
  container.register({
    userRepository: asClass(UserRepository).scoped(),
  });

  // Register services
  container.register({
    userService: asClass(UserService).scoped(),
  });

  // Register controllers
  container.register({
    userController: asClass(UserController).scoped(),
  });

  // Enable scope per request for Express
  container.loadModules(
    [
      'repositories/*.js',
      'services/*.js',
      'controllers/*.js',
      'integrations/*.js',
    ],
    {
      cwd: __dirname,
      formatName: 'camelCase',
      resolverOptions: {
        register: asClass,
        lifetime: scopePerRequest,
      },
    }
  );

  return container;
};
