## Health Checks and Monitoring

```typescript
// src/health-checks.ts - Health check endpoints
import express from 'express';
import { initializeDatabase } from './database';
import { initializeCache } from './cache';
import { initializeMessageBroker } from './message-broker';
import { logger } from './utils/logger';

interface HealthCheckResult {
  status: 'healthy' | 'unhealthy';
  details?: Record<string, unknown>;
}

export const initializeHealthChecks = (app: express.Application): void => {
  app.get('/health/ready', async (req, res) => {
    try {
      // Check database connection
      const db = await initializeDatabase();
      await db.query('SELECT 1');

      // Check cache connection
      const cache = await initializeCache();
      await cache.ping();

      // Check message broker connection
      const broker = await initializeMessageBroker();
      await broker.checkConnection();

      res.status(200).json({ status: 'healthy' });
    } catch (error) {
      logger.error('Readiness check failed', { error });
      res.status(503).json({
        status: 'unhealthy',
        details: {
          error: error instanceof Error ? error.message : 'Unknown error',
        },
      });
    }
  });

  app.get('/health/live', (req, res) => {
    res.status(200).json({ status: 'healthy' });
  });

  app.get('/health/details', async (req, res) => {
    const result: Record<string, HealthCheckResult> = {};

    try {
      // Database check
      const db = await initializeDatabase();
      await db.query('SELECT 1');
      result.database = { status: 'healthy' };
    } catch (error) {
      result.database = {
        status: 'unhealthy',
        details: {
          error: error instanceof Error ? error.message : 'Unknown error',
        },
      };
    }

    try {
      // Cache check
      const cache = await initializeCache();
      await cache.ping();
      result.cache = { status: 'healthy' };
    } catch (error) {
      result.cache = {
        status: 'unhealthy',
        details: {
          error: error instanceof Error ? error.message : 'Unknown error',
        },
      };
    }

    try {
      // Message broker check
      const broker = await initializeMessageBroker();
      await broker.checkConnection();
      result.messageBroker = { status: 'healthy' };
    } catch (error) {
      result.messageBroker = {
        status: 'unhealthy',
        details: {
          error: error instanceof Error ? error.message : 'Unknown error',
        },
      };
    }

    const overallStatus = Object.values(result).every(
      (check) => check.status === 'healthy'
    )
      ? 'healthy'
      : 'unhealthy';

    res.status(overallStatus === 'healthy' ? 200 : 503).json({
      status: overallStatus,
      checks: result,
    });
  });
};
