### 6. Service Layer Implementation (`services/user.service.ts`)

```typescript
import { Injectable, NotFoundException } from '@nestjs/common';
import { UserRepository } from '@/repositories/user.repository';
import { CreateUserDto, UpdateUserDto, UserResponseDto } from '@/dtos/user.dto';
import { LegacySystemIntegrationService } from '@/services/legacy-system-integration.service';
import { ERPIntegrationService } from '@/services/erp-integration.service';
import { logger } from '@/utils/logger';

@Injectable()
export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly legacySystemIntegration: LegacySystemIntegrationService,
    private readonly erpIntegration: ERPIntegrationService,
  ) {}

  async createUser(userData: CreateUserDto): Promise<UserResponseDto> {
    try {
      // Create user in our system
      const user = await this.userRepository.create(userData);

      // Integrate with legacy system
      await this.legacySystemIntegration.syncUser(user);

      // Integrate with ERP system
      await this.erpIntegration.syncUser(user);

      return this.mapToResponseDto(user);
    } catch (error) {
      logger.error(`Failed to create user: ${error.message}`);
      throw error;
    }
  }

  async getAllUsers(): Promise<UserResponseDto[]> {
    const users = await this.userRepository.findAll();
    return users.map(user => this.mapToResponseDto(user));
  }

  async getUserById(id: string): Promise<UserResponseDto> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundException(`User with ID ${id} not found`);
    }
    return this.mapToResponseDto(user);
  }

  async updateUser(id: string, userData: UpdateUserDto): Promise<UserResponseDto> {
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new NotFoundException(`User with ID ${id} not found`);
    }

    const updatedUser = await this.userRepository.update(id, userData);

    // Sync updates with external systems
    await this.legacySystemIntegration.syncUser(updatedUser!);
    await this.erpIntegration.syncUser(updatedUser!);

    return this.mapToResponseDto(updatedUser!);
  }

  async deleteUser(id: string): Promise<void> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundException(`User with ID ${id} not found`);
    }

    // Deactivate in external systems before deletion
    await this.legacySystemIntegration.deactivateUser(id);
    await this.erpIntegration.deactivateUser(id);

    await this.userRepository.delete(id);
  }

  private mapToResponseDto(user: User): UserResponseDto {
    return {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
      hireDate: user.hireDate?.toISOString().split('T')[0] || '',
      createdAt: user.createdAt.toISOString(),
      updatedAt: user.updatedAt.toISOString(),
    };
  }
}
