### 8. External System Integration Service (`services/legacy-system-integration.service.ts`)

```typescript
import { Injectable } from '@nestjs/common';
import { config } from '@/config';
import { User } from '@/entities/user.entity';
import { HttpService } from '@nestjs/axios';
import { lastValueFrom } from 'rxjs';
import { logger } from '@/utils/logger';

@Injectable()
export class LegacySystemIntegrationService {
  private readonly baseUrl: string;
  private readonly apiKey: string;
  private readonly timeout: number;

  constructor(private readonly httpService: HttpService) {
    this.baseUrl = config.externalServices.legacySystem.baseUrl;
    this.apiKey = config.externalServices.legacySystem.apiKey;
    this.timeout = config.externalServices.legacySystem.timeout;
  }

  async syncUser(user: User): Promise<void> {
    try {
      const response = await lastValueFrom(
        this.httpService.post(`${this.baseUrl}/users`, this.mapUserToLegacyFormat(user), {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
            'Content-Type': 'application/json',
          },
          timeout: this.timeout,
        })
      );

      logger.info(`Successfully synced user ${user.id} with legacy system. Response: ${JSON.stringify(response.data)}`);
    } catch (error) {
      logger.error(`Failed to sync user ${user.id} with legacy system: ${error.message}`);
      throw new Error(`Legacy system integration failed: ${error.message}`);
    }
  }

  async deactivateUser(userId: string): Promise<void> {
    try {
      await lastValueFrom(
        this.httpService.delete(`${this.baseUrl}/users/${userId}`, {
          headers: {
            'Authorization': `Bearer ${this.apiKey}`,
          },
          timeout: this.timeout,
        })
      );

      logger.info(`Successfully deactivated user ${userId} in legacy system`);
    } catch (error) {
      logger.error(`Failed to deactivate user ${userId} in legacy system: ${error.message}`);
      throw new Error(`Legacy system deactivation failed: ${error.message}`);
    }
  }

  private mapUserToLegacyFormat(user: User): any {
    return {
      legacyId: user.id,
      fullName: user.name,
      emailAddress: user.email,
      accessLevel: this.mapRoleToLegacyAccessLevel(user.role),
      employmentStartDate: user.hireDate?.toISOString().split('T')[0],
    };
  }

  private mapRoleToLegacyAccessLevel(role: string): string {
    const roleMapping: Record<string, string> = {
      ADMIN: 'SUPER_USER',
      MANAGER: 'MANAGER',
      EMPLOYEE: 'STANDARD',
      GUEST: 'READ_ONLY',
    };
    return roleMapping[role] || 'STANDARD';
  }
}
