import axios, { AxiosInstance } from 'axios';
import { z } from 'zod';
import { config } from '../config/config';

const CorporateUserSchema = z.object({
  employeeId: z.string(),
  fullName: z.string(),
  department: z.string(),
  position: z.string(),
  email: z.string().email(),
  status: z.enum(['ACTIVE', 'INACTIVE', 'ON_LEAVE']),
});

