export class CorporateService {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      headers: {
        'Authorization': `Bearer ${config.CORPORATE_API_KEY}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async getUserByEmployeeId(employeeId: string): Promise<CorporateUser> {
    try {
      const response = await this.client.get(`/employees/${employeeId}`);
      return CorporateUserSchema.parse(response.data);
    } catch (error) {
      if (axios.isAxiosError(error)) {
        throw new Error(`Corporate API error: ${error.response?.status} - ${error.response?.data.message}`);
      }
      throw error;
    }
  }

  async validateUserAccess(employeeId: string): Promise<boolean> {
    const user = await this.getUserByEmployeeId(employeeId);
    return user.status === 'ACTIVE';
  }
}
