import { IUserRepository } from '../interfaces/user.repository';
import { User } from '../entities/user.entity';
import { CreateUserDto, UpdateUserDto } from '../dto/user.dto';
import { CorporateService } from './corporate.service';

export class UserService {
  constructor(
    private userRepository: IUserRepository,
    private corporateService: CorporateService
  ) {}

  async createUser(userData: CreateUserDto): Promise<User> {
    // Validate with corporate system
    const corporateUser = await this.corporateService.getUserByEmployeeId(userData.corporateId);

    if (corporateUser.email !== userData.email) {
      throw new Error('Email does not match corporate records');
    }

    const user: Omit<User, 'id' | 'createdAt' | 'updatedAt'> = {
      ...userData,
      roles: userData.roles || ['USER'],
    };

    return this.userRepository.create(user);
  }

  async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new Error('User not found');
    }
    return user;
  }

  async updateUser(id: string, userData: UpdateUserDto): Promise<User> {
    return this.userRepository.update(id, userData);
  }

  async deleteUser(id: string): Promise<void> {
    await this.userRepository.delete(id);
  }
}
