## Core Architecture

```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createLogger } from './utils/logger';
import { configureMiddleware } from './middleware';
import { configureRoutes } from './routes';
import { initializeDatabase } from './database';
import { initializeCache } from './cache';
import { initializeMessageBroker } from './message-broker';
import { initializeHealthChecks } from './health';
import { initializeConfig } from './config';
import { initializeTracing } from './tracing';
import { initializeMetrics } from './metrics';

const logger = createLogger('app');

async function bootstrap() {
  try {
    // Initialize configuration
    const config = await initializeConfig();

    // Initialize tracing and metrics
    const tracer = initializeTracing(config);
    const metrics = initializeMetrics(config);

    // Create Express app
    const app = express();

    // Configure middleware
    configureMiddleware(app, config, tracer, metrics);

    // Initialize infrastructure
    const db = await initializeDatabase(config);
    const cache = await initializeCache(config);
    const messageBroker = await initializeMessageBroker(config);

    // Configure routes
    configureRoutes(app, db, cache, messageBroker, tracer, metrics);

    // Health checks
    initializeHealthChecks(app, db, cache, messageBroker);

    // Create HTTP server
    const server = createServer(app);

    // Start server
    const port = config.get('server.port') || 3000;
    server.listen(port, () => {
      logger.info(`Server running on port ${port}`);
      logger.info(`Environment: ${config.get('env')}`);
    });

    // Handle shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

    return { app, server, db, cache, messageBroker };
  } catch (error) {
    logger.error('Failed to start application', { error });
    process.exit(1);
  }
}

// Start the application
bootstrap();
