## Database Layer with Type Safety

```typescript
// src/database/index.ts
import { Pool, PoolClient } from 'pg';
import { createLogger } from '../utils/logger';
import { Config } from '../config/types';

const logger = createLogger('database');

interface DatabaseConfig {
  url: string;
  poolSize: number;
}

export interface Database {
  query: <T = any>(text: string, params?: any[]) => Promise<T[]>;
  getClient: () => Promise<PoolClient>;
  transaction: <T>(callback: (client: PoolClient) => Promise<T>) => Promise<T>;
}

export async function initializeDatabase(config: Config): Promise<Database> {
  const dbConfig: DatabaseConfig = config.get('database');

  logger.info('Initializing database connection pool', {
    poolSize: dbConfig.poolSize,
  });

  const pool = new Pool({
    connectionString: dbConfig.url,
    max: dbConfig.poolSize,
    idleTimeoutMillis: 30000,
    connectionTimeoutMillis: 2000,
  });

  // Test the connection
  try {
    await pool.query('SELECT 1');
    logger.info('Database connection established successfully');
  } catch (error) {
    logger.error('Failed to connect to database', { error });
    throw error;
  }

  const database: Database = {
    query: async <T = any>(text: string, params?: any[]): Promise<T[]> => {
      const start = Date.now();
      try {
        const result = await pool.query(text, params);
        logger.debug('Database query executed', {
          query: text,
          duration: Date.now() - start,
          rowCount: result.rowCount,
        });
        return result.rows as T[];
      } catch (error) {
        logger.error('Database query failed', {
          query: text,
          error: error.message,
          duration: Date.now() - start,
        });
        throw error;
      }
    },

    getClient: async (): Promise<PoolClient> => {
      const client = await pool.connect();
      logger.debug('Database client acquired');
      return client;
    },

    transaction: async <T>(callback: (client: PoolClient) => Promise<T>): Promise<T> => {
      const client = await pool.connect();
      try {
        await client.query('BEGIN');
        const result = await callback(client);
        await client.query('COMMIT');
        logger.debug('Transaction committed successfully');
        return result;
      } catch (error) {
        await client.query('ROLLBACK');
        logger.error('Transaction rolled back', { error });
        throw error;
      } finally {
        client.release();
      }
    },
  };

  return database;
}
