// src/repositories/user-repository.ts
import { Database } from '../database';
import { User, UserCreate, UserUpdate } from '../models/user';
import { createLogger } from '../utils/logger';

const logger = createLogger('user-repository');

export interface UserRepository {
  create(user: UserCreate): Promise<User>;
  getById(id: string): Promise<User | null>;
  getByEmail(email: string): Promise<User | null>;
  update(id: string, user: UserUpdate): Promise<User>;
  delete(id: string): Promise<void>;
  list(limit?: number, offset?: number): Promise<User[]>;
}

export function createUserRepository(db: Database): UserRepository {
  return {
    async create(user: UserCreate): Promise<User> {
      const query = `
        INSERT INTO users (username, email, first_name, last_name, department, role, status)
        VALUES ($1, $2, $3, $4, $5, $6, $7)
        RETURNING *;
      `;

      const params = [
        user.username,
        user.email,
        user.firstName,
        user.lastName,
        user.department,
        user.role,
        user.status || 'ACTIVE',
      ];

      const result = await db.query<User>(query, params);
      logger.debug('User created', { userId: result[0].id });
      return result[0];
    },

    async getById(id: string): Promise<User | null> {
      const query = 'SELECT * FROM users WHERE id = $1';
      const result = await db.query<User>(query, [id]);
      return result[0] || null;
    },

    async getByEmail(email: string): Promise<User | null> {
      const query = 'SELECT * FROM users WHERE email = $1';
      const result = await db.query<User>(query, [email]);
      return result[0] || null;
    },

    async update(id: string, user: UserUpdate): Promise<User> {
      const fields = Object.keys(user).map((key, index) => `${key} = $${index + 2}`);
      const values = Object.values(user);

      const query = `
        UPDATE users
        SET ${fields.join(', ')}, updated_at = NOW()
        WHERE id = $1
        RETURNING *;
      `;

      const result = await db.query<User>(query, [id, ...values]);
      if (!result[0]) {
        throw new Error(`User with id ${id} not found`);
      }
      logger.debug('User updated', { userId: id });
      return result[0];
    },

    async delete(id: string): Promise<void> {
      const query = 'DELETE FROM users WHERE id = $1';
      await db.query(query, [id]);
      logger.debug('User deleted', { userId: id });
    },

    async list(limit = 100, offset = 0): Promise<User[]> {
      const query = 'SELECT * FROM users ORDER BY created_at DESC LIMIT $1 OFFSET $2';
      return db.query<User>(query, [limit, offset]);
    },
  };
}
