## Service Layer with Business Logic

```typescript
// src/services/user-service.ts
import { UserRepository } from '../repositories/user-repository';
import { User, UserCreate, UserUpdate } from '../models/user';
import { createLogger } from '../utils/logger';
import { Cache } from '../cache';
import { MessageBroker } from '../message-broker';
import { z } from 'zod';

const logger = createLogger('user-service');

export interface UserService {
  createUser(user: UserCreate): Promise<User>;
  getUserById(id: string): Promise<User>;
  getUserByEmail(email: string): Promise<User>;
  updateUser(id: string, user: UserUpdate): Promise<User>;
  deleteUser(id: string): Promise<void>;
  listUsers(limit?: number, offset?: number): Promise<User[]>;
}

export function createUserService(
  userRepository: UserRepository,
  cache: Cache,
  messageBroker: MessageBroker
): UserService {
  const CACHE_KEY_PREFIX = 'user:';

  return {
    async createUser(user: UserCreate): Promise<User> {
      // Validate input
      const validatedUser = UserCreateSchema.parse(user);

      // Check if email already exists
      const existingUser = await userRepository.getByEmail(validatedUser.email);
      if (existingUser) {
        throw new Error('Email already in use');
      }

      // Create user
      const createdUser = await userRepository.create(validatedUser);

      // Invalidate cache
      await cache.del(`${CACHE_KEY_PREFIX}${createdUser.id}`);
      await cache.del(`${CACHE_KEY_PREFIX}email:${createdUser.email}`);

      // Publish event
      await messageBroker.publish('user.created', createdUser);

      logger.info('User created successfully', { userId: createdUser.id });
      return createdUser;
    },

    async getUserById(id: string): Promise<User> {
      // Validate input
      z.string().uuid().parse(id);

      // Try cache first
      const cacheKey = `${CACHE_KEY_PREFIX}${id}`;
      const cachedUser = await cache.get<User>(cacheKey);
      if (cachedUser) {
        logger.debug('User retrieved from cache', { userId: id });
        return cachedUser;
      }

      // Get from database
      const user = await userRepository.getById(id);
      if (!user) {
        throw new Error('User not found');
      }

      // Cache the result
      await cache.set(cacheKey, user, 3600); // Cache for 1 hour

      logger.debug('User retrieved from database', { userId: id });
      return user;
    },

    async getUserByEmail(email: string): Promise<User> {
      // Validate input
      z.string().email().parse(email);

      // Try cache first
      const cacheKey = `${CACHE_KEY_PREFIX}email:${email}`;
      const cachedUser = await cache.get<User>(cacheKey);
      if (cachedUser) {
        logger.debug('User retrieved from cache by email', { email });
        return cachedUser;
      }

      // Get from database
      const user = await userRepository.getByEmail(email);
      if (!user) {
        throw new Error('User not found');
      }

      // Cache the result
      await cache.set(cacheKey, user, 3600); // Cache for 1 hour

      logger.debug('User retrieved from database by email', { email });
      return user;
    },

    async updateUser(id: string, user: UserUpdate): Promise<User> {
      // Validate input
      z.string().uuid().parse(id);
      const validatedUpdate = UserUpdateSchema.parse(user);

      // Check if user exists
      const existingUser = await userRepository.getById(id);
      if (!existingUser) {
        throw new Error('User not found');
      }

      // Update user
      const updatedUser = await userRepository.update(id, validatedUpdate);

      // Invalidate cache
      await cache.del(`${CACHE_KEY_PREFIX}${id}`);
      await cache.del(`${CACHE_KEY_PREFIX}email:${updatedUser.email}`);

      // Publish event
      await messageBroker.publish('user.updated', updatedUser);

      logger.info('User updated successfully', { userId: id });
      return updatedUser;
    },

    async deleteUser(id: string): Promise<void> {
      // Validate input
      z.string().uuid().parse(id);

      // Check if user exists
      const existingUser = await userRepository.getById(id);
      if (!existingUser) {
        throw new Error('User not found');
      }

      // Delete user
      await userRepository.delete(id);

      // Invalidate cache
      await cache.del(`${CACHE_KEY_PREFIX}${id}`);
      await cache.del(`${CACHE_KEY_PREFIX}email:${existingUser.email}`);

      // Publish event
      await messageBroker.publish('user.deleted', { id });

      logger.info('User deleted successfully', { userId: id });
    },

    async listUsers(limit = 100, offset = 0): Promise<User[]> {
      // Validate input
      z.number().int().positive().parse(limit);
      z.number().int().min(0).parse(offset);

      // Get from database
      const users = await userRepository.list(limit, offset);

      logger.debug('Users listed', { count: users.length, limit, offset });
      return users;
    },
  };
}
