## Integration with Corporate Systems

```typescript
// src/integrations/erp-integration.ts
import axios, { AxiosInstance } from 'axios';
import { createLogger } from '../utils/logger';
import { Config } from '../config/types';
import { z } from 'zod';

const logger = createLogger('erp-integration');

const ERPOrderSchema = z.object({
  orderId: z.string().uuid(),
  customerId: z.string().uuid(),
  items: z.array(
    z.object({
      productId: z.string().uuid(),
      quantity: z.number().int().positive(),
      price: z.number().positive(),
    })
  ),
  totalAmount: z.number().positive(),
  status: z.enum(['PENDING', 'PROCESSING', 'SHIPPED', 'DELIVERED', 'CANCELLED']),
  createdAt: z.string().datetime(),
});

type ERPOrder = z.infer<typeof ERPOrderSchema>;

export interface ERPIntegration {
  getOrder(orderId: string): Promise<ERPOrder>;
  createOrder(order: Omit<ERPOrder, 'orderId' | 'status' | 'createdAt'>): Promise<ERPOrder>;
  updateOrderStatus(orderId: string, status: ERPOrder['status']): Promise<ERPOrder>;
}

export function createERPIntegration(config: Config): ERPIntegration {
  const erpConfig = config.get('corporateSystems.erp');

  const client: AxiosInstance = axios.create({
    baseURL: erpConfig.baseUrl,
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${erpConfig.apiKey}`,
    },
    timeout: 10000,
  });

  // Add request interceptor for logging
  client.interceptors.request.use((config) => {
    logger.debug('ERP request', {
      method: config.method,
      url: config.url,
      data: config.data,
    });
    return config;
  });

  // Add response interceptor for logging and error handling
  client.interceptors.response.use(
    (response) => {
      logger.debug('ERP response', {
        status: response.status,
        data: response.data,
      });
      return response;
    },
    (error) => {
      logger.error('ERP request failed', {
        message: error.message,
        config: error.config,
        response: error.response?.data,
      });
      return Promise.reject(error);
    }
  );

  return {
    async getOrder(orderId: string): Promise<ERPOrder> {
      try {
        const response = await client.get(`/orders/${orderId}`);
        return ERPOrderSchema.parse(response.data);
      } catch (error) {
        logger.error('Failed to get order from ERP', { orderId, error: error.message });
        throw new Error(`Failed to get order ${orderId} from ERP`);
      }
    },

    async createOrder(order: Omit<ERPOrder, 'orderId' | 'status' | 'createdAt'>): Promise<ERPOrder> {
      try {
        const response = await client.post('/orders', order);
        return ERPOrderSchema.parse(response.data);
      } catch (error) {
        logger.error('Failed to create order in ERP', { order, error: error.message });
        throw new Error('Failed to create order in ERP');
      }
    },

    async updateOrderStatus(orderId: string, status: ERPOrder['status']): Promise<ERPOrder> {
      try {
        const response = await client.patch(`/orders/${orderId}/status`, { status });
        return ERPOrderSchema.parse(response.data);
      } catch (error) {
        logger.error('Failed to update order status in ERP', {
          orderId,
          status,
          error: error.message,
        });
        throw new Error(`Failed to update order ${orderId} status in ERP`);
      }
    },
  };
}
