## Repository Pattern for Data Access

```typescript
// src/repositories/user.repository.ts - Type-safe repository
import { User, CreateUser, UpdateUser } from '../models/user';
import { query, transaction } from '../database';
import { createLogger } from '../utils/logger';

const logger = createLogger('user-repository');

export class UserRepository {
  async create(userData: CreateUser): Promise<User> {
    const sql = `
      INSERT INTO users (username, email, first_name, last_name, department, role, is_active)
      VALUES ($1, $2, $3, $4, $5, $6, $7)
      RETURNING *;
    `;

    const params = [
      userData.username,
      userData.email,
      userData.firstName,
      userData.lastName,
      userData.department,
      userData.role,
      userData.isActive,
    ];

    const result = await query<User>(sql, params);
    return result[0];
  }

  async findById(id: string): Promise<User | null> {
    const sql = 'SELECT * FROM users WHERE id = $1;';
    const result = await query<User>(sql, [id]);
    return result.length ? result[0] : null;
  }

  async findByEmail(email: string): Promise<User | null> {
    const sql = 'SELECT * FROM users WHERE email = $1;';
    const result = await query<User>(sql, [email]);
    return result.length ? result[0] : null;
  }

  async update(id: string, userData: UpdateUser): Promise<User | null> {
    const fields = Object.keys(userData);
    if (fields.length === 0) return null;

    const setClause = fields.map((field, index) =>
      `${this.toSnakeCase(field)} = $${index + 1}`
    ).join(', ');

    const sql = `
      UPDATE users
      SET ${setClause}, updated_at = NOW()
      WHERE id = $${fields.length + 1}
      RETURNING *;
    `;

    const params = [...Object.values(userData), id];
    const result = await query<User>(sql, params);
    return result.length ? result[0] : null;
  }

  async delete(id: string): Promise<boolean> {
    const sql = 'DELETE FROM users WHERE id = $1 RETURNING id;';
    const result = await query<{ id: string }>(sql, [id]);
    return result.length > 0;
  }

  private toSnakeCase(str: string): string {
    return str.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
  }
}
```

## Service Layer with Business Logic

```typescript
// src/services/user.service.ts - Business logic layer
import { UserRepository } from '../repositories/user.repository';
import { User, CreateUser, UpdateUser } from '../models/user';
import { createLogger } from '../utils/logger';
import { UserAlreadyExistsError, UserNotFoundError } from '../errors';

const logger = createLogger('user-service');

export class UserService {
  constructor(private userRepository: UserRepository) {}

  async createUser(userData: CreateUser): Promise<User> {
    // Check if user with email already exists
    const existingUser = await this.userRepository.findByEmail(userData.email);
    if (existingUser) {
      throw new UserAlreadyExistsError(`User with email ${userData.email} already exists`);
    }

    // Business logic validation
    if (userData.role === 'ADMIN' && !this.isAuthorizedToCreateAdmin()) {
      throw new Error('Not authorized to create admin users');
    }

    // Create user
    const user = await this.userRepository.create(userData);

    logger.info('User created successfully', { userId: user.id });
    return user;
  }

  async getUserById(id: string): Promise<User> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new UserNotFoundError(`User with ID ${id} not found`);
    }
    return user;
  }

  async updateUser(id: string, userData: UpdateUser): Promise<User> {
    // Check if user exists
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new UserNotFoundError(`User with ID ${id} not found`);
    }

    // Business logic validation
    if (userData.role && userData.role === 'ADMIN' && !this.isAuthorizedToCreateAdmin()) {
      throw new Error('Not authorized to update to admin role');
    }

    // Update user
    const updatedUser = await this.userRepository.update(id, userData);
    if (!updatedUser) {
      throw new Error('Failed to update user');
    }

    logger.info('User updated successfully', { userId: id });
    return updatedUser;
  }

  async deleteUser(id: string): Promise<boolean> {
    // Check if user exists
    const existingUser = await this.userRepository.findById(id);
    if (!existingUser) {
      throw new UserNotFoundError(`User with ID ${id} not found`);
    }

    // Business logic validation
    if (existingUser.role === 'ADMIN' && !this.isAuthorizedToDeleteAdmin()) {
      throw new Error('Not authorized to delete admin users');
    }

    // Delete user
    const success = await this.userRepository.delete(id);
    if (!success) {
      throw new Error('Failed to delete user');
    }

    logger.info('User deleted successfully', { userId: id });
    return true;
  }

  private isAuthorizedToCreateAdmin(): boolean {
    // Implement actual authorization logic
    return true;
  }

  private isAuthorizedToDeleteAdmin(): boolean {
    // Implement actual authorization logic
    return true;
  }
}
