## Dependency Injection Container

```typescript
// src/di-container.ts - Dependency injection container
import { UserRepository } from './repositories/user.repository';
import { UserService } from './services/user.service';
import { UserController } from './controllers/user.controller';
import { ERPIntegration } from './integrations/erp-integration';

class DIContainer {
  private static instance: DIContainer;
  private services: Map<string, any> = new Map();

  private constructor() {
    // Initialize services
    this.services.set('UserRepository', new UserRepository());
    this.services.set('UserService', new UserService(this.get('UserRepository')));
    this.services.set('UserController', new UserController(this.get('UserService')));
    this.services.set('ERPIntegration', new ERPIntegration());
  }

  public static getInstance(): DIContainer {
    if (!DIContainer.instance) {
      DIContainer.instance = new DIContainer();
    }
    return DIContainer.instance;
  }

  public get<T>(serviceName: string): T {
    const service = this.services.get(serviceName);
    if (!service) {
      throw new Error(`Service ${serviceName} not found`);
    }
    return service as T;
  }
}

export const container = DIContainer.getInstance();
