```typescript
// src/app.ts - Main application entry point
import express from 'express';
import { createServer } from 'http';
import { createLogger } from './utils/logger';
import { configureMiddleware } from './middleware';
import { configureRoutes } from './routes';
import { initializeDatabase } from './database';
import { initializeCorporateIntegrations } from './integrations';
import { validateEnvironment } from './config/environment';

const logger = createLogger('app');

async function bootstrap() {
  try {
    // Validate environment variables
    validateEnvironment();

    // Initialize database connection
    const dbConnection = await initializeDatabase();
    logger.info('Database connection established');

    // Initialize corporate integrations
    const integrations = await initializeCorporateIntegrations();
    logger.info('Corporate integrations initialized');

    // Create Express app
    const app = express();

    // Configure middleware
    configureMiddleware(app);

    // Configure routes
    configureRoutes(app, { dbConnection, integrations });

    // Create HTTP server
    const server = createServer(app);

    // Start server
    const PORT = process.env.PORT || 3000;
    server.listen(PORT, () => {
      logger.info(`Server running on port ${PORT}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

    return { app, server, dbConnection, integrations };
  } catch (error) {
    logger.error('Failed to start application:', error);
    process.exit(1);
  }
}

// Start the application
bootstrap();
