## Type-Safe Database Layer

```typescript
// src/database/index.ts
import { Pool, PoolConfig } from 'pg';
import { createLogger } from '../utils/logger';
import { DatabaseError } from '../errors';

const logger = createLogger('database');

interface DatabaseConfig {
  host: string;
  port: number;
  database: string;
  user: string;
  password: string;
  maxConnections?: number;
  idleTimeoutMillis?: number;
}

export interface DatabaseConnection {
  query: <T = any>(sql: string, params?: any[]) => Promise<{ rows: T[] }>;
  transaction: <T>(callback: (client: DatabaseConnection) => Promise<T>) => Promise<T>;
}

export async function initializeDatabase(): Promise<DatabaseConnection> {
  const config: DatabaseConfig = {
    host: process.env.DB_HOST!,
    port: parseInt(process.env.DB_PORT!, 10),
    database: process.env.DB_NAME!,
    user: process.env.DB_USER!,
    password: process.env.DB_PASSWORD!,
    maxConnections: parseInt(process.env.DB_MAX_CONNECTIONS || '10', 10),
    idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT || '30000', 10),
  };

  const poolConfig: PoolConfig = {
    ...config,
    connectionTimeoutMillis: 5000,
    max: config.maxConnections,
    idleTimeoutMillis: config.idleTimeoutMillis,
  };

  const pool = new Pool(poolConfig);

  // Test the connection
  try {
    await pool.query('SELECT 1');
  } catch (error) {
    logger.error('Database connection test failed:', error);
    throw new DatabaseError('Failed to connect to database');
  }

  const dbConnection: DatabaseConnection = {
    query: async <T = any>(sql: string, params?: any[]) => {
      try {
        const result = await pool.query<T>(sql, params);
        return { rows: result.rows };
      } catch (error) {
        logger.error(`Query failed: ${sql}`, error);
        throw new DatabaseError('Database query failed', { sql, params });
      }
    },

    transaction: async <T>(callback: (client: DatabaseConnection) => Promise<T>) => {
      const client = await pool.connect();
      try {
        await client.query('BEGIN');
        const result = await callback({
          query: async <T = any>(sql: string, params?: any[]) => {
            const result = await client.query<T>(sql, params);
            return { rows: result.rows };
          },
          transaction: async () => {
            throw new Error('Nested transactions not supported');
          },
        });
        await client.query('COMMIT');
        return result;
      } catch (error) {
        await client.query('ROLLBACK');
        logger.error('Transaction failed and rolled back', error);
        throw error;
      } finally {
        client.release();
      }
    },
  };

  return dbConnection;
}
