## Example Service Implementation

```typescript
// src/services/order-service.ts
import { DatabaseConnection } from '../database';
import { CorporateIntegrations } from '../integrations';
import { Order, OrderSchema, OrderStatus } from '../types/api-contracts';
import { ServiceError } from '../errors';
import { createLogger } from '../utils/logger';

const logger = createLogger('order-service');

export class OrderService {
  constructor(
    private db: DatabaseConnection,
    private integrations: CorporateIntegrations
  ) {}

  async createOrder(orderData: Omit<Order, 'id' | 'createdAt' | 'updatedAt'>): Promise<Order> {
    try {
      // Validate input
      const validatedData = OrderSchema.omit({
        id: true,
        createdAt: true,
        updatedAt: true,
      }).parse(orderData);

      // Check if customer exists in corporate system
      const customerExists = await this.integrations.sap.checkCustomerExists(
        validatedData.customerId
      );

      if (!customerExists) {
        throw new ServiceError('Customer not found in corporate system');
      }

      // Create order in database
      const { rows } = await this.db.query<Order>(
        `INSERT INTO orders (
          order_number, customer_id, status, total_amount, approved_by, approval_date
        ) VALUES ($1, $2, $3, $4, $5, $6)
        RETURNING *`,
        [
          validatedData.orderNumber,
          validatedData.customerId,
          validatedData.status,
          validatedData.totalAmount,
          validatedData.approvedBy,
          validatedData.approvalDate,
        ]
      );

      const createdOrder = rows[0];

      // Create order items
      for (const item of validatedData.items) {
        await this.db.query(
          `INSERT INTO order_items (
            order_id, product_id, quantity, unit_price, total_price
          ) VALUES ($1, $2, $3, $4, $5)`,
          [
            createdOrder.id,
            item.productId,
            item.quantity,
            item.unitPrice,
            item.totalPrice,
          ]
        );
      }

      // Sync with ERP system
      await this.integrations.oracle.createOrder(createdOrder);

      logger.info(`Order ${createdOrder.id} created successfully`);
      return createdOrder;
    } catch (error) {
      logger.error('Failed to create order:', error);
      throw new ServiceError('Failed to create order', { orderData });
    }
  }

  async getOrderById(orderId: string): Promise<Order> {
    try {
      const { rows } = await this.db.query<Order>(
        `SELECT * FROM orders WHERE id = $1`,
        [orderId]
      );

      if (rows.length === 0) {
        throw new ServiceError('Order not found');
      }

      const order = rows[0];

      // Get order items
      const { rows: items } = await this.db.query(
        `SELECT * FROM order_items WHERE order_id = $1`,
        [order.id]
      );

      return { ...order, items };
    } catch (error) {
      logger.error(`Failed to get order ${orderId}:`, error);
      throw new ServiceError('Failed to get order', { orderId });
    }
  }

  async updateOrderStatus(orderId: string, newStatus: OrderStatus): Promise<Order> {
    try {
      // Validate status transition
      const currentOrder = await this.getOrderById(orderId);

      // Business logic for status transitions
      if (currentOrder.status === 'DELIVERED' && newStatus !== 'DELIVERED') {
        throw new ServiceError('Cannot change status of a delivered order');
      }

      // Update in database
      const { rows } = await this.db.query<Order>(
        `UPDATE orders SET status = $1, updated_at = NOW() WHERE id = $2 RETURNING *`,
        [newStatus, orderId]
      );

      if (rows.length === 0) {
        throw new ServiceError('Order not found');
      }

      const updatedOrder = rows[0];

      // Sync with ERP system
      await this.integrations.oracle.updateOrderStatus(updatedOrder.id, newStatus);

      logger.info(`Order ${orderId} status updated to ${newStatus}`);
      return { ...updatedOrder, items: currentOrder.items };
    } catch (error) {
      logger.error(`Failed to update order status for ${orderId}:`, error);
      throw new ServiceError('Failed to update order status', { orderId, newStatus });
    }
  }
}
