### 7. Example Service (services/UserService.ts)

```typescript
import { IUser } from '@entities/User';
import { IUserRepository } from '@interfaces/IUserRepository';
import { UserRepository } from '@repositories/UserRepository';
import { hashPassword, comparePasswords } from '@utils/passwordUtils';
import { generateJwtToken } from '@utils/jwtUtils';
import { BadRequestError, NotFoundError, UnauthorizedError } from '@exceptions/HttpExceptions';

export class UserService {
  private userRepository: IUserRepository;

  constructor(userRepository: IUserRepository = new UserRepository()) {
    this.userRepository = userRepository;
  }

  async register(userData: Partial<IUser>): Promise<{ user: IUser; token: string }> {
    const existingUser = await this.userRepository.findByEmail(userData.email || '');
    if (existingUser) {
      throw new BadRequestError('Email already in use');
    }

    const hashedPassword = await hashPassword(userData.password || '');
    const user = await this.userRepository.create({
      ...userData,
      password: hashedPassword,
    });

    const token = generateJwtToken({ id: user._id, roles: user.roles });
    return { user, token };
  }

  async login(email: string, password: string): Promise<{ user: IUser; token: string }> {
    const user = await this.userRepository.findByEmail(email);
    if (!user) {
      throw new UnauthorizedError('Invalid credentials');
    }

    const isPasswordValid = await comparePasswords(password, user.password);
    if (!isPasswordValid) {
      throw new UnauthorizedError('Invalid credentials');
    }

    const token = generateJwtToken({ id: user._id, roles: user.roles });
    return { user, token };
  }

  async getUserById(id: string): Promise<IUser> {
    const user = await this.userRepository.findById(id);
    if (!user) {
      throw new NotFoundError('User not found');
    }
    return user;
  }

  async updateUser(id: string, updateData: Partial<IUser>): Promise<IUser> {
    if (updateData.password) {
      updateData.password = await hashPassword(updateData.password);
    }

    const updatedUser = await this.userRepository.update(id, updateData);
    if (!updatedUser) {
      throw new NotFoundError('User not found');
    }
    return updatedUser;
  }

  async deleteUser(id: string): Promise<void> {
    const deletedUser = await this.userRepository.delete(id);
    if (!deletedUser) {
      throw new NotFoundError('User not found');
    }
  }

  async listUsers(page: number = 1, limit: number = 10): Promise<{ users: IUser[]; total: number }> {
    return this.userRepository.list(page, limit);
  }
}
```

