### 10. Example Middleware (middlewares/authMiddleware.ts)

```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { config } from '@config/config';
import { UnauthorizedError, ForbiddenError } from '@exceptions/HttpExceptions';

interface JwtPayload {
  id: string;
  roles: string[];
}

export const authenticate = (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    throw new UnauthorizedError('Authentication required');
  }

  const token = authHeader.split(' ')[1];

  try {
    const decoded = jwt.verify(token, config.jwt.secret) as JwtPayload;
    req.user = { id: decoded.id, roles: decoded.roles };
    next();
  } catch (error) {
    throw new UnauthorizedError('Invalid or expired token');
  }
};

export const authorize = (requiredRoles: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      throw new UnauthorizedError('Authentication required');
    }

    const hasRequiredRole = requiredRoles.some(role => req.user?.roles.includes(role));

    if (!hasRequiredRole) {
      throw new ForbiddenError('Insufficient permissions');
    }

    next();
  };
};
```

