import axios, { AxiosInstance } from 'axios';
import { config } from '@config/config';
import { ILegacySystemIntegrationService } from '@interfaces/ILegacySystemIntegrationService';
import { parseStringPromise } from 'xml2js';

export class LegacySystemIntegrationService implements ILegacySystemIntegrationService {
  private axiosInstance: AxiosInstance;

  constructor() {
    this.axiosInstance = axios.create({
      baseURL: config.externalServices.legacySystem.baseUrl,
      headers: {
        'Content-Type': 'application/xml',
      },
    });
  }

  async getLegacyCustomerData(customerId: string): Promise<any> {
    try {
      const response = await this.axiosInstance.get(`/customer/${customerId}`);
      const parsedData = await parseStringPromise(response.data);
      return this.transformLegacyCustomerData(parsedData);
    } catch (error) {
      console.error('Legacy system integration error:', error);
      throw error;
    }
  }

  private transformLegacyCustomerData(legacyData: any): any {
    // Transform legacy XML data to our standard format
    return {
      id: legacyData.Customer.ID[0],
      name: legacyData.Customer.Name[0],
      address: {
        street: legacyData.Customer.Address[0].Street[0],
        city: legacyData.Customer.Address[0].City[0],
        zipCode: legacyData.Customer.Address[0].ZipCode[0],
      },
      contact: {
        email: legacyData.Customer.Contact[0].Email[0],
        phone: legacyData.Customer.Contact[0].Phone[0],
      },
    };
  }
}
