      if (error instanceof ValidationError) {
        return {
          success: false,
          error: {
            code: error.code,
            message: error.message,
            details: error.validationErrors
          }
        };
      }
      return {
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'An unexpected error occurred'
        }
      };
    }
