  private config: IntegrationConfig;

  constructor(config: IntegrationConfig) {
    this.config = config;
    this.client = axios.create({
      baseURL: config.baseUrl,
      timeout: config.timeout,
      headers: {
        'Content-Type': 'application/json',
        'X-Integration-Service': 'enterprise-backend'
      }
    });

    this.setupInterceptors();
  }

  private setupInterceptors(): void {
    this.client.interceptors.request.use((config) => {
      // Add authentication based on config
      if (this.config.auth.type === 'apiKey') {
        config.headers['X-API-Key'] = this.config.auth.credentials;
      }
      return config;
    });

    this.client.interceptors.response.use(
      (response) => response,
      (error) => {
        logger.error('HR System integration error', { error: error.toJSON() });
        return Promise.reject(error);
      }
    );
  }

  async getEmployeeDetails(employeeId: string): Promise<HRSystemResponse<HRSystemEmployee>> {
    try {
      const response = await this.client.get<HRSystemEmployee>(
        `/employees/${employeeId}`,
        {
          headers: {
            'X-Request-ID': this.generateRequestId()
          }
        }
      );

      return {
        status: 'success',
        data: response.data
      };
    } catch (error) {
      if (axios.isAxiosError(error)) {
        return {
          status: 'error',
          error: {
            code: error.response?.status.toString() || 'UNKNOWN_ERROR',
            message: error.response?.data?.message || error.message
          }
        };
      }

      return {
        status: 'error',
        error: {
          code: 'INTERNAL_ERROR',
          message: 'An unexpected error occurred'
        }
      };
    }
  }

  private generateRequestId(): string {
    return `hr-integration-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
