## API Layer with Express

```typescript
// src/api/server.ts - API layer with strict typing
import express, { Request, Response, NextFunction } from 'express';
import { UserService } from '../services/user-service';
import { ServiceResponse, CorporateUser } from '../core/types';
import { logger } from '../core/logger';
import { ValidationError } from '../core/errors';

interface RequestWithUser extends Request {
  user?: CorporateUser;
}

export class ApiServer {
  private app: express.Application;
  private userService: UserService;

  constructor(userService: UserService) {
    this.app = express();
    this.userService = userService;
    this.setupMiddleware();
    this.setupRoutes();
    this.setupErrorHandling();
  }

  private setupMiddleware(): void {
    this.app.use(express.json());
    this.app.use((req: Request, res: Response, next: NextFunction) => {
      res.setHeader('X-Service-Version', '1.0.0');
      next();
    });
  }

  private setupRoutes(): void {
    const router = express.Router();

    // Example route with strict typing
    router.get(
      '/users/:id',
      this.validateUserId,
      async (req: RequestWithUser, res: Response) => {
        const userId = req.params.id;

        const result = await this.userService.getUserById(userId);

        if (!result.success) {
          return res.status(404).json(result);
        }

        res.json(result);
      }
    );

    this.app.use('/api', router);
  }

  private validateUserId(
    req: Request,
    res: Response,
    next: NextFunction
  ): void {
    const userId = req.params.id;

    if (!userId || typeof userId !== 'string') {
      const error = new ValidationError('Invalid user ID', [
        'ID must be a non-empty string'
      ]);
      return next(error);
    }

    next();
  }

  private setupErrorHandling(): void {
    this.app.use(
      (err: Error, req: Request, res: Response, next: NextFunction) => {
        logger.error('API Error', { error: err, path: req.path });

        if (err instanceof ValidationError) {
          return res.status(400).json({
            success: false,
            error: {
              code: err.code,
              message: err.message,
              details: err.validationErrors
            }
          } as ServiceResponse<never>);
        }

        res.status(500).json({
          success: false,
          error: {
            code: 'INTERNAL_ERROR',
            message: 'An unexpected error occurred'
          }
        } as ServiceResponse<never>);
      }
    );
  }

  public start(port: number): void {
    this.app.listen(port, () => {
      logger.info(`API server running on port ${port}`);
    });
  }
}
