export type CacheClient = RedisClientType;

export async function getCachedData<T>(key: string): Promise<T | null> {
  try {
    const data = await redisClient.get(key);
    return data ? JSON.parse(data) as T : null;
  } catch (error) {
    logger.error(`Failed to get cached data for key ${key}:`, error);
    return null;
  }
}

export async function setCachedData<T>(key: string, value: T, ttl?: number): Promise<void> {
  try {
    await redisClient.set(key, JSON.stringify(value), ttl ? { EX: ttl } : undefined);
  } catch (error) {
    logger.error(`Failed to set cached data for key ${key}:`, error);
  }
}
