## Message Broker Integration

```typescript
// src/message-broker/index.ts - Type-safe message broker
import amqp, { Connection, Channel } from 'amqplib';
import { createLogger } from '../utils/logger';
import { config } from '../config';

const logger = createLogger('message-broker');
let connection: Connection;
let channel: Channel;

export async function initializeMessageBroker() {
  try {
    connection = await amqp.connect(config.RABBITMQ_URL);
    channel = await connection.createChannel();

    // Ensure queues exist
    await channel.assertQueue('orders.processed', { durable: true });
    await channel.assertQueue('inventory.updated', { durable: true });

    logger.info('Message broker connected and queues asserted');
    return { connection, channel };
  } catch (error) {
    logger.error('Message broker connection failed:', error);
    throw error;
  }
}

export type MessageBroker = {
  connection: Connection;
  channel: Channel;
};

export async function publishMessage<T>(queue: string, message: T): Promise<void> {
  try {
    channel.sendToQueue(queue, Buffer.from(JSON.stringify(message)), {
      persistent: true,
    });
  } catch (error) {
    logger.error(`Failed to publish message to queue ${queue}:`, error);
  }
}

export async function consumeMessages<T>(
  queue: string,
  callback: (message: T) => Promise<void>
): Promise<void> {
  try {
    await channel.consume(queue, async (msg) => {
      if (msg) {
        try {
          const content = JSON.parse(msg.content.toString()) as T;
          await callback(content);
          channel.ack(msg);
        } catch (error) {
          logger.error(`Error processing message from queue ${queue}:`, error);
          channel.nack(msg);
        }
      }
    });
  } catch (error) {
    logger.error(`Failed to consume messages from queue ${queue}:`, error);
  }
}
