## Service Layer with Type Safety

```typescript
// src/services/order.service.ts - Type-safe order service
import { DatabaseClient } from '../database';
import { CacheClient, getCachedData, setCachedData } from '../cache';
import { MessageBroker, publishMessage } from '../message-broker';
import { createLogger } from '../utils/logger';
import { Order, OrderItem } from '@prisma/client';

const logger = createLogger('order-service');

export class OrderService {
  constructor(
    private db: DatabaseClient,
    private cache: CacheClient,
    private messageBroker: MessageBroker
  ) {}

  async createOrder(data: {
    customerId: string;
    items: Array<{
      productId: string;
      quantity: number;
      price: number;
    }>;
    shippingAddress: {
      street: string;
      city: string;
      state: string;
      zipCode: string;
      country: string;
    };
  }): Promise<Order> {
    try {
      // Calculate total
      const total = data.items.reduce((sum, item) => sum + item.price * item.quantity, 0);

      // Create order in database
      const order = await this.db.order.create({
        data: {
          customerId: data.customerId,
          total,
          status: 'PENDING',
          shippingAddress: data.shippingAddress,
          items: {
            create: data.items.map(item => ({
              productId: item.productId,
              quantity: item.quantity,
              price: item.price,
            })),
          },
        },
        include: {
          items: true,
        },
      });

      // Publish order created event
      await publishMessage('orders.created', {
        orderId: order.id,
        customerId: order.customerId,
        total: order.total,
      });

      // Cache the order
      await setCachedData(`order:${order.id}`, order, 3600); // Cache for 1 hour

      return order;
    } catch (error) {
      logger.error('Failed to create order:', error);
      throw error;
    }
  }

  async getOrderById(id: string): Promise<Order | null> {
    try {
      // Try to get from cache first
      const cachedOrder = await getCachedData<Order>(`order:${id}`);
      if (cachedOrder) {
        return cachedOrder;
      }

      // If not in cache, get from database
      const order = await this.db.order.findUnique({
        where: { id },
        include: { items: true },
      });

      // Cache the result if found
      if (order) {
        await setCachedData(`order:${id}`, order, 3600);
      }

      return order;
    } catch (error) {
      logger.error(`Failed to get order by ID ${id}:`, error);
      throw error;
    }
  }
}
