```typescript
// src/health/index.ts - Comprehensive health checks
import { Express } from 'express';
import { DatabaseClient } from '../database';
import { CacheClient } from '../cache';
import { MessageBroker } from '../message-broker';
import { createLogger } from '../utils/logger';

const logger = createLogger('health');

export function initializeHealthChecks(
  app: Express,
  dependencies: {
    db: DatabaseClient;
    cache: CacheClient;
    messageBroker: MessageBroker;
  }
) {
  app.get('/health/ready', async (req, res) => {
    try {
      // Check database connection
      await dependencies.db.$queryRaw`SELECT 1`;

      // Check cache connection
      await dependencies.cache.ping();

      // Check message broker connection
      if (!dependencies.messageBroker.connection || dependencies.messageBroker.connection.connection.stream.destroyed) {
        throw new Error('Message broker connection lost');
      }

      res.status(200).json({ status: 'ready' });
    } catch (error) {
      logger.error('Readiness check failed:', error);
      res.status(503).json({ status: 'unhealthy', error: error instanceof Error ? error.message : 'Unknown error' });
    }
  });

  app.get('/health/live', (req, res) => {
    res.status(200).json({ status: 'live' });
  });

  app.get('/health/metrics', async (req, res) => {
    try {
      // In a real implementation, you would collect actual metrics
      const metrics = {
        database: 'connected',
        cache: 'connected',
        messageBroker: 'connected',
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage(),
      };

      res.status(200).json(metrics);
    } catch (error) {
      logger.error('Metrics collection failed:', error);
      res.status(500).json({ error: 'Failed to collect metrics' });
    }
  });
