```typescript
// src/services/user-service.ts
import { User, ServiceResponse } from '../core/types';
import { validateUser } from '../validators/user-validator';
import { CorporateSystemClient } from '../clients/corporate-system-client';

export class UserService {
  private corporateClient: CorporateSystemClient;

  constructor(config: CorporateSystemConfig) {
    this.corporateClient = new CorporateSystemClient(config);
  }

  async getUserById(userId: string): Promise<ServiceResponse<User>> {
    try {
      // Validate input
      if (!userId || typeof userId !== 'string') {
        throw new Error('Invalid user ID');
      }

      // Fetch from corporate systems
      const userData = await this.corporateClient.fetchUser(userId);

      // Validate response
      const validatedUser = validateUser(userData);

      return {
        success: true,
        data: validatedUser,
        metadata: {
          requestId: this.generateRequestId(),
          timestamp: new Date(),
          version: '1.0.0'
        }
      };
    } catch (error) {
      return {
        success: false,
        error: {
          code: 'USER_FETCH_ERROR',
          message: error instanceof Error ? error.message : 'Unknown error',
          details: error
        },
        metadata: {
          requestId: this.generateRequestId(),
          timestamp: new Date(),
          version: '1.0.0'
        }
      };
    }
  }

  private generateRequestId(): string {
    return `req-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }
}
