```typescript
import express, { Application, Request, Response, NextFunction } from 'express';
import { connectToDatabase } from '@/config/database';
import { connectToKafka } from '@/config/kafka';
import { logger } from '@/utils/logger';
import exampleRouter from '@/controllers/example.controller';

export class App {
  public app: Application;

  constructor() {
    this.app = express();
    this.initializeMiddlewares();
    this.initializeRoutes();
    this.initializeErrorHandling();
    this.initializeDatabase();
    this.initializeMessageBroker();
  }

  private initializeMiddlewares() {
    this.app.use(express.json());
    this.app.use(express.urlencoded({ extended: true }));
  }

  private initializeRoutes() {
    this.app.use('/api/example', exampleRouter);
    this.app.get('/health', (req: Request, res: Response) => {
      res.status(200).json({ status: 'healthy' });
    });
  }

  private initializeErrorHandling() {
    this.app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
      logger.error(err.stack);
      res.status(500).json({ message: 'Internal Server Error' });
    });
  }

  private async initializeDatabase() {
    try {
      await connectToDatabase();
      logger.info('Database connection established');
    } catch (error) {
      logger.error('Database connection failed', error);
      process.exit(1);
    }
  }

  private async initializeMessageBroker() {
    try {
      await connectToKafka();
      logger.info('Kafka connection established');
    } catch (error) {
      logger.error('Kafka connection failed', error);
      process.exit(1);
    }
  }

  public listen(port: number) {
    this.app.listen(port, () => {
      logger.info(`Server is running on port ${port}`);
    });
  }
}
```

