```typescript
import { AppDataSource } from '@/config/database';
import { ExampleEntity } from '@/entities/example.entity';
import { CreateExampleDto, UpdateExampleDto } from '@/dtos/example.dto';
import { producer } from '@/config/kafka';

export class ExampleService {
  private exampleRepository = AppDataSource.getRepository(ExampleEntity);

  async createExample(data: CreateExampleDto): Promise<ExampleEntity> {
    const example = this.exampleRepository.create(data);
    const savedExample = await this.exampleRepository.save(example);

    // Publish event to Kafka
    await producer.send({
      topic: 'example-created',
      messages: [{ value: JSON.stringify(savedExample) }],
    });

    return savedExample;
  }

  async getExampleById(id: string): Promise<ExampleEntity | null> {
    return this.exampleRepository.findOneBy({ id });
  }

  async updateExample(id: string, data: UpdateExampleDto): Promise<ExampleEntity | null> {
    await this.exampleRepository.update(id, data);
    return this.getExampleById(id);
  }

  async deleteExample(id: string): Promise<void> {
    await this.exampleRepository.delete(id);

    // Publish event to Kafka
    await producer.send({
      topic: 'example-deleted',
      messages: [{ value: JSON.stringify({ id }) }],
    });
  }
}
```

