```typescript
// src/integrations/corporateApiClient.ts
import axios, { AxiosInstance, AxiosResponse } from 'axios';

interface CorporateUser {
  id: string;
  name: string;
  email: string;
  department: string;
  role: string;
}

interface CorporateApiResponse<T> {
  data: T;
  status: number;
  message: string;
}

export class CorporateApiClient {
  private client: AxiosInstance;

  constructor(baseURL: string, apiKey: string) {
    this.client = axios.create({
      baseURL,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async verifyConnection(): Promise<boolean> {
    try {
      const response = await this.client.get('/health');
      return response.status === 200;
    } catch (error) {
      console.error('Corporate API connection failed:', error);
      return false;
    }
  }

  async getUserById(userId: string): Promise<CorporateUser> {
    const response: AxiosResponse<CorporateApiResponse<CorporateUser>> =
      await this.client.get(`/users/${userId}`);

    if (response.data.status !== 200) {
      throw new Error(`Failed to fetch user: ${response.data.message}`);
    }

    return response.data.data;
  }
}
