// src/services/userService.ts
import { getRepository } from 'typeorm';
import { User } from '../entities/User';
import { CorporateApiClient } from '../integrations/corporateApiClient';

export class UserService {
  private corporateApi: CorporateApiClient;

  constructor() {
    this.corporateApi = new CorporateApiClient(
      process.env.CORPORATE_API_URL || '',
      process.env.CORPORATE_API_KEY || ''
    );
  }

  async getUserById(id: string): Promise<User> {
    // First try to get from local DB
    const userRepository = getRepository(User);
    let user = await userRepository.findOne({ where: { id } });

    if (!user) {
      // If not found locally, fetch from corporate system
      const corporateUser = await this.corporateApi.getUserById(id);

      // Map corporate user to our entity
      user = userRepository.create({
        id: corporateUser.id,
        name: corporateUser.name,
        email: corporateUser.email,
      });

      await userRepository.save(user);
    }

    return user;
  }
}
