import { IExample, IExampleCreate, IExampleUpdate } from '../interfaces/example.interface';

export class ExampleService {
  private examples: IExample[] = [];

  async create(data: IExampleCreate): Promise<IExample> {
    const example: IExample = {
      id: Date.now().toString(),
      ...data,
      createdAt: new Date(),
      updatedAt: new Date()
    };
    this.examples.push(example);
    return example;
  }

  async findAll(): Promise<IExample[]> {
    return this.examples;
  }

  async findOne(id: string): Promise<IExample | undefined> {
    return this.examples.find(example => example.id === id);
  }

  async update(id: string, data: IExampleUpdate): Promise<IExample | undefined> {
    const index = this.examples.findIndex(example => example.id === id);
    if (index === -1) return undefined;

    const updatedExample = {
      ...this.examples[index],
      ...data,
      updatedAt: new Date()
    };

    this.examples[index] = updatedExample;
    return updatedExample;
  }

  async delete(id: string): Promise<boolean> {
    const initialLength = this.examples.length;
    this.examples = this.examples.filter(example => example.id !== id);
    return this.examples.length !== initialLength;
  }
}
