import express, { Application } from 'express';
import { ExampleController } from './controllers/example.controller';
import { ExampleService } from './services/example.service';
import { IntegrationService } from './services/integration.service';
import { errorHandler } from './middlewares/error.middleware';
import { validateRequest } from './middlewares/validation.middleware';
import { CreateExampleDto, UpdateExampleDto } from './dtos/example.dto';

export class App {
  public app: Application;
  private exampleController: ExampleController;

  constructor() {
    this.app = express();
    this.configureMiddleware();
    this.initializeControllers();
    this.configureErrorHandling();
  }

  private configureMiddleware(): void {
    this.app.use(express.json());
    // Add other middleware like CORS, rate limiting, etc.
  }

  private initializeControllers(): void {
    const exampleService = new ExampleService();
    const integrationService = new IntegrationService(process.env.CORPORATE_API_URL || '');
    this.exampleController = new ExampleController(exampleService);

    // Example routes with validation
    this.app.post(
      '/examples',
      validateRequest(CreateExampleDto),
      this.exampleController.create.bind(this.exampleController)
    );

    this.app.get(
      '/examples',
      this.exampleController.findAll.bind(this.exampleController)
    );

    this.app.get(
      '/examples/:id',
      this.exampleController.findOne.bind(this.exampleController)
    );

    this.app.put(
      '/examples/:id',
      validateRequest(UpdateExampleDto),
      this.exampleController.update.bind(this.exampleController)
    );

