    timestamp: new Date().toISOString(),
    dependencies: {},
  };

  try {
    // Check database connection
    const dbConnection = getConnection();
    healthStatus.dependencies.database = {
      status: 'healthy',
      database: dbConnection.options.database,
    };
  } catch (error) {
    healthStatus.status = 'unhealthy';
    healthStatus.dependencies.database = {
      status: 'unhealthy',
      error: error.message,
    };
  }

  try {
    // Check corporate API connection
    const corporateApi = getCorporateApiClient();
    const apiHealth = await corporateApi.healthCheck();
    healthStatus.dependencies.corporateApi = {
      status: 'healthy',
      ...apiHealth,
    };
  } catch (error) {
    healthStatus.status = 'unhealthy';
    healthStatus.dependencies.corporateApi = {
      status: 'unhealthy',
      error: error.message,
    };
  }

  res.status(healthStatus.status === 'healthy' ? 200 : 503).json(healthStatus);
});

