import { User } from '../entities/user.entity';
import { CreateUserDto, UpdateUserDto } from '../dtos/user.dto';
import { CorporateSystemService } from './corporateSystem.service';

export class UserService {
  private users: User[] = [];
  private corporateSystemService: CorporateSystemService;

  constructor() {
    this.corporateSystemService = new CorporateSystemService();
  }

  async createUser(createUserDto: CreateUserDto): Promise<User> {
    const user: User = {
      id: this.generateId(),
      ...createUserDto,
      dateOfBirth: createUserDto.dateOfBirth ? new Date(createUserDto.dateOfBirth) : undefined,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Integrate with corporate system
    const corporateSystemId = await this.corporateSystemService.registerUser(user);
    user.corporateSystemId = corporateSystemId;

    this.users.push(user);
    return user;
  }

  async getUserById(id: string): Promise<User | undefined> {
    return this.users.find(user => user.id === id);
  }

  async updateUser(id: string, updateUserDto: UpdateUserDto): Promise<User | undefined> {
    const userIndex = this.users.findIndex(user => user.id === id);
    if (userIndex === -1) return undefined;

    const updatedUser = {
      ...this.users[userIndex],
      ...updateUserDto,
      dateOfBirth: updateUserDto.dateOfBirth ? new Date(updateUserDto.dateOfBirth) : this.users[userIndex].dateOfBirth,
      updatedAt: new Date(),
    };

    this.users[userIndex] = updatedUser;

    // Update in corporate system if needed
    if (updatedUser.corporateSystemId) {
      await this.corporateSystemService.updateUser(updatedUser.corporateSystemId, updatedUser);
    }

    return updatedUser;
  }

  private generateId(): string {
    return Math.random().toString(36).substring(2, 15) +
           Math.random().toString(36).substring(2, 15);
  }
}
```

