  async registerUser(user: User): Promise<string> {
    try {
      const response = await this.httpClient.post('/users', {
        firstName: user.firstName,
        lastName: user.lastName,
        email: user.email,
        dateOfBirth: user.dateOfBirth?.toISOString(),
      });

      return response.data.id;
    } catch (error) {
      console.error('Failed to register user in corporate system:', error);
      throw new Error('Corporate system integration failed');
    }
  }

  async updateUser(corporateSystemId: string, user: User): Promise<void> {
    try {
      await this.httpClient.put(`/users/${corporateSystemId}`, {
        firstName: user.firstName,
        lastName: user.lastName,
        email: user.email,
        dateOfBirth: user.dateOfBirth?.toISOString(),
      });
    } catch (error) {
      console.error('Failed to update user in corporate system:', error);
      throw new Error('Corporate system integration failed');
    }
  }
}
