```typescript
import { ExampleEntity, ExampleEntityImpl } from '../entities/example.entity';

export interface ExampleRepository {
  create(data: Omit<ExampleEntity, 'id' | 'createdAt' | 'updatedAt'>): Promise<ExampleEntity>;
  findById(id: string): Promise<ExampleEntity | null>;
  update(id: string, data: Partial<ExampleEntity>): Promise<ExampleEntity | null>;
  delete(id: string): Promise<boolean>;
}

export class InMemoryExampleRepository implements ExampleRepository {
  private store: Map<string, ExampleEntity> = new Map();

  async create(data: Omit<ExampleEntity, 'id' | 'createdAt' | 'updatedAt'>): Promise<ExampleEntity> {
    const id = crypto.randomUUID();
    const entity = new ExampleEntityImpl(id, data.name, data.description);
    this.store.set(id, entity);
    return entity;
  }

  async findById(id: string): Promise<ExampleEntity | null> {
    return this.store.get(id) || null;
  }

  async update(id: string, data: Partial<ExampleEntity>): Promise<ExampleEntity | null> {
    const existing = this.store.get(id);
    if (!existing) return null;

    const updated = { ...existing, ...data, updatedAt: new Date() };
    this.store.set(id, updated);
    return updated;
  }

  async delete(id: string): Promise<boolean> {
    return this.store.delete(id);
  }
}
```

