import { Request, Response } from 'express';
import { ExampleService } from '../services/example.service';
import { CreateExampleDtoSchema, UpdateExampleDtoSchema } from '../dtos/example.dto';

export class ExampleController {
  constructor(private service: ExampleService) {}

  async createExample(req: Request, res: Response) {
    const validated = CreateExampleDtoSchema.parse(req.body);
    const result = await this.service.createExample(validated);
    res.status(201).json(result);
  }

  async getExample(req: Request, res: Response) {
    const { id } = req.params;
    const result = await this.service.getExample(id);

    if (!result) {
      res.status(404).json({ message: 'Example not found' });
      return;
    }

    res.json(result);
  }

  async updateExample(req: Request, res: Response) {
    const { id } = req.params;
    const validated = UpdateExampleDtoSchema.parse(req.body);
    const result = await this.service.updateExample(id, validated);

    if (!result) {
      res.status(404).json({ message: 'Example not found' });
      return;
    }

    res.json(result);
  }

  async deleteExample(req: Request, res: Response) {
    const { id } = req.params;
    const success = await this.service.deleteExample(id);

    if (!success) {
