import express from 'express';
import { ExampleController } from './controllers/example.controller';
import { ExampleService } from './services/example.service';
import { InMemoryExampleRepository } from './repositories/example.repository';
import { validateRequest } from './middlewares/validation.middleware';
import { CreateExampleDtoSchema, UpdateExampleDtoSchema } from './dtos/example.dto';

export function createApp() {
  const app = express();

  // Middleware
  app.use(express.json());

  // Repositories
  const exampleRepository = new InMemoryExampleRepository();

  // Services
  const exampleService = new ExampleService(exampleRepository);

  // Controllers
  const exampleController = new ExampleController(exampleService);

  // Routes
  app.post(
    '/examples',
    validateRequest(CreateExampleDtoSchema),
    exampleController.createExample.bind(exampleController)
  );

  app.get('/examples/:id', exampleController.getExample.bind(exampleController));

  app.put(
    '/examples/:id',
    validateRequest(UpdateExampleDtoSchema),
    exampleController.updateExample.bind(exampleController)
  );

  app.delete('/examples/:id', exampleController.deleteExample.bind(exampleController));

  // Health check
  app.get('/health', (req, res) => {
    res.status(200).json({ status: 'healthy' });
  });

  return app;
}
