## Corporate System Integration

```typescript
// src/integrations/corporate-system.ts - Type-safe integration client
import axios, { AxiosInstance } from 'axios';
import { z } from 'zod';
import { config } from '../config';
import { logger } from '../utils/logger';

const CorporateSystemResponseSchema = z.object({
  status: z.string(),
  data: z.record(z.string(), z.unknown()),
  metadata: z.object({
    requestId: z.string(),
    timestamp: z.string().datetime(),
  }),
});

type CorporateSystemResponse = z.infer<typeof CorporateSystemResponseSchema>;

export class CorporateSystemClient {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.CORPORATE_SYSTEM_URL,
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.API_KEY}`,
      },
      timeout: 5000,
    });

    this.client.interceptors.response.use(
      (response) => {
        // Validate response schema
        const parsed = CorporateSystemResponseSchema.safeParse(response.data);
        if (!parsed.success) {
          logger.error('Invalid corporate system response schema', {
            errors: parsed.error.errors,
          });
          throw new Error('Invalid corporate system response');
        }
        return response;
      },
      (error) => {
        logger.error('Corporate system integration error', {
          message: error.message,
          config: error.config,
        });
        return Promise.reject(error);
      }
    );
  }

  async getUserData(corporateId: string): Promise<CorporateSystemResponse> {
    try {
      const response = await this.client.get(`/users/${corporateId}`);
      return response.data;
    } catch (error) {
      logger.error('Failed to fetch user data from corporate system', {
        corporateId,
        error: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }
  }
}
