    // Process request
    const { userId, action, details } = req.body;

    // Integrate with corporate system
    const corporateResponse = await corporateIntegrationService.sendRequest<ExampleResponseData>({
      requestId: `req-${Date.now()}`,
      timestamp: new Date().toISOString(),
      payload: { userId, action, details }
    });

    if (corporateResponse.status === 'error') {
      return res.status(502).json({
        success: false,
        error: {
          code: corporateResponse.errorDetails?.code || 'CORPORATE_ERROR',
          message: corporateResponse.errorDetails?.message || 'Corporate system error'
        }
      });
    }

    // Return success response
    res.status(200).json({
      success: true,
      data: corporateResponse.data as ExampleResponseData
    });
  } catch (error) {
    res.status(500).json({
      success: false,
      error: {
        code: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred',
        details: error instanceof Error ? error.message : undefined
      }
    });
  }
};
