```typescript
// src/integrations/corporate-api.ts
import axios, { AxiosInstance } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';
import { User, UserSchema } from '../types/api-contracts';

class CorporateApiClient {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.CORPORATE_API_URL,
      headers: {
        'Authorization': `Bearer ${config.CORPORATE_API_KEY}`,
        'X-Service-Name': config.SERVICE_NAME,
      },
      timeout: 5000,
    });

    // Add request/response interceptors for logging and error handling
    this.setupInterceptors();
  }

  private setupInterceptors() {
    this.client.interceptors.request.use((config) => {
      logger.debug(`Corporate API Request: ${config.method?.toUpperCase()} ${config.url}`);
      return config;
    });

    this.client.interceptors.response.use(
      (response) => {
        logger.debug(`Corporate API Response: ${response.status} ${response.config.url}`);
        return response;
      },
      (error) => {
        logger.error(`Corporate API Error: ${error.message}`, {
          config: error.config,
          response: error.response?.data,
        });
        return Promise.reject(error);
      }
    );
  }

  async getUserByCorporateId(corporateId: string): Promise<User> {
    try {
      const response = await this.client.get(`/users/${corporateId}`);
      const validatedData = UserSchema.parse(response.data);
      return validatedData;
    } catch (error) {
      logger.error(`Failed to get user from corporate API: ${error}`);
      throw new Error('Failed to retrieve user from corporate system');
    }
  }

  async syncUserData(user: User): Promise<void> {
    try {
      await this.client.post('/users/sync', user);
    } catch (error) {
      logger.error(`Failed to sync user data: ${error}`);
      throw new Error('Failed to synchronize user data with corporate system');
    }
  }
}

export const corporateApiClient = new CorporateApiClient();
