import { config } from './config';
import { logger } from './utils/logger';
import { setupMiddleware } from './middleware';
import { setupRoutes } from './routes';
import { setupHealthChecks } from './health';
import { setupErrorHandling } from './error-handling';
import { setupDatabase } from './database';
import { setupCorporateIntegrations } from './integrations';

async function bootstrap() {
  try {
    // Initialize database connection
    const dbConnection = await setupDatabase(config.database);

    // Create Express app
    const app = express();

    // Setup middleware
    setupMiddleware(app);

    // Setup routes
    setupRoutes(app, dbConnection);

    // Setup health checks
    setupHealthChecks(app);

    // Setup error handling
    setupErrorHandling(app);

    // Setup corporate integrations
    await setupCorporateIntegrations(app);

    // Create HTTP server
    const server = createServer(app);

    // Start listening
    server.listen(config.port, () => {
      logger.info(`Service running on port ${config.port}`);
    });

    // Handle shutdown gracefully
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    logger.error('Failed to start service:', error);
    process.exit(1);
  }
}

bootstrap();
