// src/database/index.ts
import { Pool, PoolConfig } from 'pg';
import { logger } from '../utils/logger';
import { config } from '../config';

interface DatabaseConfig {
  connectionString: string;
  maxConnections?: number;
  idleTimeoutMillis?: number;
}

export async function setupDatabase(dbConfig: DatabaseConfig) {
  const poolConfig: PoolConfig = {
    connectionString: dbConfig.connectionString,
    max: dbConfig.maxConnections || 20,
    idleTimeoutMillis: dbConfig.idleTimeoutMillis || 30000,
    connectionTimeoutMillis: 5000,
  };

  const pool = new Pool(poolConfig);

  // Test the connection
  try {
    await pool.query('SELECT 1');
    logger.info('Database connection established successfully');
  } catch (error) {
    logger.error('Failed to connect to database:', error);
    throw error;
  }

  return pool;
}

// Example typed query function
export async function query<T>(pool: Pool, sql: string, params?: any[]): Promise<T[]> {
  const result = await pool.query(sql, params);
  return result.rows as T[];
}
