  try {
    // Initialize corporate integrations first
    await initializeCorporateIntegrations();

    const app = express();
    const server = createServer(app);

    // Setup middleware
    setupMiddleware(app);

    // Setup routes
    setupRoutes(app);

    // Setup health checks
    setupHealthChecks(app);

    // Start server
    server.listen(config.port, () => {
      logger.info(`Service running on port ${config.port}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received. Shutting down gracefully...');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    logger.error('Service startup failed', { error });
    process.exit(1);
  }
}

