// src/services/order.service.ts
import { Order, OrderCreateRequest, OrderResponse } from '../models/order.model';
import { ErpIntegration } from '../integrations/erp.integration';
import { CrmIntegration } from '../integrations/crm.integration';
import { logger } from '../utils/logger';

export class OrderService {
  constructor(
    private erpIntegration: ErpIntegration,
    private crmIntegration: CrmIntegration
  ) {}

  async createOrder(request: OrderCreateRequest): Promise<OrderResponse> {
    // Validate request
    if (!request.customerId || !request.items || request.items.length === 0) {
      throw new Error('Invalid order request');
    }

    // Create order in local system
    const order: Order = {
      id: this.generateOrderId(),
      customerId: request.customerId,
      items: request.items.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        price: this.getProductPrice(item.productId) // Would normally fetch from product service
      })),
      totalAmount: this.calculateTotal(request.items),
      status: 'pending',
      createdAt: new Date(),
      updatedAt: new Date()
    };

    // Sync with ERP
    const erpSyncStatus = await this.syncWithErp(order);

    // Sync with CRM
    const crmSyncStatus = await this.syncWithCrm(order);

    return {
      order,
      metadata: {
        erpSyncStatus,
        crmSyncStatus
      }
    };
  }

  private async syncWithErp(order: Order): Promise<'pending' | 'completed' | 'failed'> {
    try {
      await this.erpIntegration.createOrder(order);
      return 'completed';
    } catch (error) {
      logger.error('ERP sync failed', { orderId: order.id, error });
      return 'failed';
    }
  }

  private async syncWithCrm(order: Order): Promise<'pending' | 'completed' | 'failed'> {
    try {
      await this.crmIntegration.updateCustomerOrder(order);
      return 'completed';
    } catch (error) {
      logger.error('CRM sync failed', { orderId: order.id, error });
      return 'failed';
    }
  }

  // Helper methods would be implemented here
