```typescript
// src/integrations/corporateApi.ts - Type-safe corporate API client
import axios, { AxiosInstance, AxiosResponse } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';

interface CorporateApiResponse<T> {
  data: T;
  status: number;
  headers: Record<string, string>;
}

class CorporateApiClient {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.CORPORATE_API_BASE_URL,
      headers: {
        'Authorization': `Bearer ${config.CORPORATE_API_KEY}`,
        'Content-Type': 'application/json',
        'X-Service-Name': 'enterprise-microservice'
      },
      timeout: 5000
    });

    // Request interceptor for logging
    this.client.interceptors.request.use(request => {
      logger.debug(`Corporate API Request: ${request.method} ${request.url}`);
      return request;
    });

    // Response interceptor for error handling
    this.client.interceptors.response.use(
      response => response,
      error => {
        logger.error(`Corporate API Error: ${error.message}`);
        throw error;
      }
    );
  }

  async get<T>(endpoint: string): Promise<CorporateApiResponse<T>> {
    const response = await this.client.get<T>(endpoint);
    return this.transformResponse(response);
  }

  async post<T>(endpoint: string, data: unknown): Promise<CorporateApiResponse<T>> {
    const response = await this.client.post<T>(endpoint, data);
    return this.transformResponse(response);
  }

  private transformResponse<T>(response: AxiosResponse<T>): CorporateApiResponse<T> {
    return {
      data: response.data,
      status: response.status,
      headers: response.headers as Record<string, string>
    };
  }
}

export const corporateApi = new CorporateApiClient();
