## Example Service Layer

```typescript
// src/services/userService.ts - Type-safe service layer
import { getRepository, Repository } from 'typeorm';
import { User } from '../entities/User';
import { corporateApi } from '../integrations/corporateApi';
import { logger } from '../utils/logger';

interface UserCreateInput {
  firstName: string;
  lastName: string;
  email: string;
}

interface UserUpdateInput {
  firstName?: string;
  lastName?: string;
  isActive?: boolean;
}

interface CorporateUserSyncResult {
  success: boolean;
  message: string;
}

export class UserService {
  private userRepository: Repository<User>;

  constructor() {
    this.userRepository = getRepository(User);
  }

  async createUser(input: UserCreateInput): Promise<User> {
    const user = this.userRepository.create(input);
    await this.userRepository.save(user);

    // Sync with corporate system
    await this.syncWithCorporateSystem(user.id);

    return user;
  }

  async updateUser(id: string, input: UserUpdateInput): Promise<User> {
    const user = await this.userRepository.findOne(id);
    if (!user) {
      throw new Error('User not found');
    }

    Object.assign(user, input);
    await this.userRepository.save(user);

    // Sync with corporate system
    await this.syncWithCorporateSystem(user.id);

    return user;
  }

  async getUser(id: string): Promise<User | undefined> {
    return this.userRepository.findOne(id);
  }

  private async syncWithCorporateSystem(userId: string): Promise<CorporateUserSyncResult> {
    try {
      const user = await this.userRepository.findOne(userId);
      if (!user) {
        return { success: false, message: 'User not found' };
      }

      const response = await corporateApi.post<{ status: string }>(
        '/users/sync',
        {
          id: user.id,
          firstName: user.firstName,
          lastName: user.lastName,
          email: user.email,
          isActive: user.isActive
        }
      );

      if (response.status === 200) {
        logger.info(`Successfully synced user ${userId} with corporate system`);
        return { success: true, message: 'Sync successful' };
      }

      return { success: false, message: 'Sync failed' };
    } catch (error) {
      logger.error(`Failed to sync user ${userId} with corporate system:`, error);
      return { success: false, message: error instanceof Error ? error.message : 'Unknown error' };
    }
  }
}
