export class UserController {
  private userService: UserService;

  constructor() {
    this.userService = new UserService();
  }

  async createUser(req: Request<{}, {}, CreateUserRequestBody>, res: Response, next: NextFunction) {
    try {
      const { firstName, lastName, email } = req.body;

      // Validate input
      validate(req.body, {
        firstName: { type: 'string', required: true, minLength: 1, maxLength: 100 },
        lastName: { type: 'string', required: true, minLength: 1, maxLength: 100 },
        email: { type: 'string', required: true, pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/ }
      });

      const user = await this.userService.createUser({ firstName, lastName, email });

      res.status(201).json({
        success: true,
        data: user
      });
    } catch (error) {
      logger.error('Error creating user:', error);
      next(error);
    }
  }

  async updateUser(req: Request<{ id: string }, {}, UpdateUserRequestBody>, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;
      const { firstName, lastName, isActive } = req.body;

      // Validate input
      validate(req.body, {
        firstName: { type: 'string', required: false, minLength: 1, maxLength: 100 },
        lastName: { type: 'string', required: false, minLength: 1, maxLength: 100 },
        isActive: { type: 'boolean', required: false }
      });

      const user = await this.userService.updateUser(id, { firstName, lastName, isActive });

      res.json({
        success: true,
        data: user
      });
    } catch (error) {
      logger.error('Error updating user:', error);
      next(error);
    }
  }

  async getUser(req: Request<{ id: string }>, res: Response, next: NextFunction) {
    try {
      const { id } = req.params;

      const user = await this.userService.getUser(id);

      if (!user) {
