## Validation Utility

```typescript
// src/utils/validation.ts - Type-safe validation utility
interface ValidationRule {
  type: 'string' | 'number' | 'boolean' | 'object' | 'array';
  required?: boolean;
  minLength?: number;
  maxLength?: number;
  pattern?: RegExp;
  min?: number;
  max?: number;
  items?: ValidationRule;
  properties?: Record<string, ValidationRule>;
}

export function validate(data: unknown, schema: Record<string, ValidationRule>): void {
  if (typeof data !== 'object' || data === null) {
    throw new Error('Input must be an object');
  }

  for (const [key, rule] of Object.entries(schema)) {
    const value = (data as Record<string, unknown>)[key];

    // Check required fields
    if (rule.required && (value === undefined || value === null)) {
      throw new Error(`Field ${key} is required`);
    }

    // Skip validation for optional fields that are not provided
    if (!rule.required && (value === undefined || value === null)) {
      continue;
    }

    // Type checking
    if (rule.type === 'string' && typeof value !== 'string') {
      throw new Error(`Field ${key} must be a string`);
    }

    if (rule.type === 'number' && typeof value !== 'number') {
      throw new Error(`Field ${key} must be a number`);
    }

    if (rule.type === 'boolean' && typeof value !== 'boolean') {
      throw new Error(`Field ${key} must be a boolean`);
    }

    if (rule.type === 'object' && (typeof value !== 'object' || value === null)) {
      throw new Error(`Field ${key} must be an object`);
    }

    if (rule.type === 'array' && !Array.isArray(value)) {
      throw new Error(`Field ${key} must be an array`);
    }

    // String-specific validation
    if (rule.type === 'string' && typeof value === 'string') {
      if (rule.minLength !== undefined && value.length < rule.minLength) {
        throw new Error(`Field ${key} must be at least ${rule.minLength} characters long`);
      }

      if (rule.maxLength !== undefined && value.length > rule.maxLength) {
        throw new Error(`Field ${key} must be at most ${rule.maxLength} characters long`);
      }

      if (rule.pattern && !rule.pattern.test(value)) {
        throw new Error(`Field ${key} does not match the required pattern`);
      }
    }

    // Number-specific validation
    if (rule.type === 'number' && typeof value === 'number') {
      if (rule.min !== undefined && value < rule.min) {
        throw new Error(`Field ${key} must be at least ${rule.min}`);
      }

      if (rule.max !== undefined && value > rule.max) {
        throw new Error(`Field ${key} must be at most ${rule.max}`);
      }
    }

    // Array-specific validation
    if (rule.type === 'array' && Array.isArray(value) && rule.items) {
      for (const item of value) {
        validate({ item }, { item: rule.items });
      }
    }

    // Object-specific validation
    if (rule.type === 'object' && typeof value === 'object' && value !== null && rule.properties) {
      validate(value, rule.properties);
    }
  }
}
