## Corporate API Client with Strict Typing

```typescript
// src/integrations/corporateApiClient.ts - Type-safe corporate API client
import axios, { AxiosInstance } from 'axios';
import { logger } from '../utils/logger';

interface CorporateApiResponse<T> {
  data: T;
  status: 'success' | 'error';
  message?: string;
}

export class CorporateApiClient {
  private client: AxiosInstance;

  constructor(baseURL: string, apiKey: string) {
    this.client = axios.create({
      baseURL,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async healthCheck(): Promise<void> {
    try {
      const response = await this.client.get<CorporateApiResponse<{ status: string }>>('/health');
      if (response.data.status !== 'success' || response.data.data.status !== 'healthy') {
        throw new Error('Corporate API health check failed');
      }
    } catch (error) {
      logger.error('Corporate API health check failed:', error);
      throw error;
    }
  }

  async validateUserEmail(email: string): Promise<boolean> {
    try {
      const response = await this.client.post<CorporateApiResponse<{ isValid: boolean }>>(
        '/users/validate-email',
        { email }
      );

      if (response.data.status !== 'success') {
        throw new Error(response.data.message || 'Email validation failed');
      }

      return response.data.data.isValid;
    } catch (error) {
      logger.error('Email validation failed:', error);
      throw error;
    }
  }
}
