import { Order, OrderItem } from '../interfaces/order.interface';

export class CreateOrderDto {
  customerId: string;
  items: OrderItem[];

  constructor(data: Partial<CreateOrderDto>) {
    this.customerId = data.customerId!;
    this.items = data.items!;
