import { Order, OrderItem } from '../interfaces/order.interface';
import { DatabaseService } from './database.service';
import { OrderEntity } from '../entities/order.entity';

export class OrderService {
  private dbService: DatabaseService;

  constructor(dbService: DatabaseService) {
    this.dbService = dbService;
  }

  async createOrder(customerId: string, items: OrderItem[]): Promise<Order> {
    const totalAmount = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    const order = new OrderEntity();
    order.customerId = customerId;
    order.items = items;
    order.totalAmount = totalAmount;
    order.status = 'pending';

    const savedOrder = await this.dbService.getRepository(OrderEntity).save(order);
    return savedOrder;
  }

  async getOrderById(id: string): Promise<Order | null> {
    return this.dbService.getRepository(OrderEntity).findOne({ where: { id } });
  }

  async updateOrderStatus(id: string, status: Order['status']): Promise<Order | null> {
    await this.dbService.getRepository(OrderEntity).update(id, { status });
    return this.getOrderById(id);
  }
}
