import { Router, Request, Response } from 'express';
import { OrderService } from '../services/order.service';
import { CreateOrderDto, OrderResponseDto } from '../dto/order.dto';
import { KafkaService } from '../services/kafka.service';
import { logger } from '../utils/logger';

export class OrderController {
  public router: Router;
  private orderService: OrderService;
  private kafkaService: KafkaService;

  constructor(kafkaService: KafkaService) {
    this.router = Router();
    this.kafkaService = kafkaService;
    this.orderService = new OrderService(new DatabaseService());
    this.initializeRoutes();
  }

  private initializeRoutes(): void {
    this.router.post('/', this.createOrder.bind(this));
    this.router.get('/:id', this.getOrder.bind(this));
    this.router.patch('/:id/status', this.updateOrderStatus.bind(this));
  }

  private async createOrder(req: Request, res: Response): Promise<void> {
    try {
      const dto = new CreateOrderDto(req.body);

      if (!dto.validate()) {
        res.status(400).json({ error: 'Invalid order data' });
        return;
      }

      const order = await this.orderService.createOrder(dto.customerId, dto.items);

      // Publish event to Kafka
      await this.kafkaService.sendMessage('order.created', new OrderResponseDto(order));

      res.status(201).json(new OrderResponseDto(order));
    } catch (error) {
      logger.error(`Error creating order: ${error}`);
      res.status(500).json({ error: 'Failed to create order' });
    }
  }

  private async getOrder(req: Request, res: Response): Promise<void> {
    try {
      const order = await this.orderService.getOrderById(req.params.id);

      if (!order) {
        res.status(404).json({ error: 'Order not found' });
        return;
      }

      res.json(new OrderResponseDto(order));
    } catch (error) {
      logger.error(`Error fetching order: ${error}`);
      res.status(500).json({ error: 'Failed to fetch order' });
    }
  }

  private async updateOrderStatus(req: Request, res: Response): Promise<void> {
    try {
      const { status } = req.body;
      const order = await this.orderService.updateOrderStatus(req.params.id, status);

      if (!order) {
        res.status(404).json({ error: 'Order not found' });
        return;
      }

      // Publish event to Kafka
      await this.kafkaService.sendMessage('order.status.updated', new OrderResponseDto(order));

      res.json(new OrderResponseDto(order));
    } catch (error) {
      logger.error(`Error updating order status: ${error}`);
      res.status(500).json({ error: 'Failed to update order status' });
    }
  }
}
