```typescript
import { ExampleEntity } from '../entities/example.entity';

export interface IExampleRepository {
  findAll(): Promise<ExampleEntity[]>;
  findById(id: string): Promise<ExampleEntity | null>;
  create(data: Omit<ExampleEntity, 'id'>): Promise<ExampleEntity>;
  update(id: string, data: Partial<ExampleEntity>): Promise<ExampleEntity>;
  delete(id: string): Promise<void>;
}

export class ExampleRepository implements IExampleRepository {
  private data: ExampleEntity[] = [];

  async findAll(): Promise<ExampleEntity[]> {
    return this.data;
  }

  async findById(id: string): Promise<ExampleEntity | null> {
    return this.data.find(item => item.id === id) || null;
  }

  async create(data: Omit<ExampleEntity, 'id'>): Promise<ExampleEntity> {
    const newItem = new ExampleEntity({
      ...data,
      id: this.generateId()
    });
    this.data.push(newItem);
    return newItem;
  }

  async update(id: string, data: Partial<ExampleEntity>): Promise<ExampleEntity> {
    const index = this.data.findIndex(item => item.id === id);
    if (index === -1) {
      throw new Error('Item not found');
    }
    this.data[index] = { ...this.data[index], ...data };
    return this.data[index];
  }

  async delete(id: string): Promise<void> {
    this.data = this.data.filter(item => item.id !== id);
  }

  private generateId(): string {
    return Math.random().toString(36).substring(2, 9);
  }
}
