### 7. Express Application Setup (`app.ts`)

```typescript
import express, { Application } from 'express';
import { ExampleController } from './controllers/example.controller';
import { ExampleService } from './services/example.service';
import { ExampleRepository } from './repositories/example.repository';
import { validationMiddleware } from './middlewares/validation.middleware';
import { CreateExampleDto, UpdateExampleDto } from './dto/example.dto';

export class App {
  public app: Application;
  private exampleController: ExampleController;

  constructor() {
    this.app = express();
    this.initializeMiddlewares();
    this.initializeControllers();
    this.initializeErrorHandling();
  }

  private initializeMiddlewares(): void {
    this.app.use(express.json());
    this.app.use(express.urlencoded({ extended: true }));
  }

  private initializeControllers(): void {
    const exampleRepository = new ExampleRepository();
    const exampleService = new ExampleService(exampleRepository);
    this.exampleController = new ExampleController(exampleService);

    // Example routes with validation middleware
    this.app.get('/examples', this.exampleController.getAll.bind(this.exampleController));
    this.app.get('/examples/:id', this.exampleController.getById.bind(this.exampleController));
    this.app.post(
      '/examples',
      validationMiddleware(CreateExampleDto),
      this.exampleController.create.bind(this.exampleController)
    );
    this.app.put(
      '/examples/:id',
      validationMiddleware(UpdateExampleDto),
      this.exampleController.update.bind(this.exampleController)
    );
    this.app.delete('/examples/:id', this.exampleController.delete.bind(this.exampleController));
  }

  private initializeErrorHandling(): void {
    this.app.use((err: Error, req: express.Request, res: express.Response, next: express.NextFunction) => {
      console.error(err.stack);
      res.status(500).json({ error: 'Something went wrong!' });
    });
  }
}
```

