// src/integrations/externalApi.ts
import axios, { AxiosInstance, AxiosRequestConfig } from 'axios';
import { config } from '../config';
import { logger } from '../utils/logger';

export interface ExternalApiResponse<T> {
  data: T;
  status: number;
  headers: Record<string, string>;
}

export class ExternalApiClient {
  private client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: config.EXTERNAL_API_BASE_URL,
      timeout: config.EXTERNAL_API_TIMEOUT,
      headers: {
        'Content-Type': 'application/json',
        'X-Service-Name': config.SERVICE_NAME,
        'X-Service-Version': config.SERVICE_VERSION,
      },
    });

    // Request interceptor for logging
    this.client.interceptors.request.use((config) => {
      logger.debug(`External API Request: ${config.method?.toUpperCase()} ${config.url}`);
      return config;
    });

    // Response interceptor for logging and error handling
    this.client.interceptors.response.use(
      (response) => {
        logger.debug(`External API Response: ${response.status} ${response.config.url}`);
        return response;
      },
      (error) => {
        if (error.response) {
          logger.error(
            `External API Error: ${error.response.status} ${error.config.url}`,
            error.response.data
          );
        } else if (error.request) {
          logger.error('External API Error: No response received', error.message);
        } else {
          logger.error('External API Error:', error.message);
        }
        return Promise.reject(error);
      }
    );
  }

  async get<T>(url: string, config?: AxiosRequestConfig): Promise<ExternalApiResponse<T>> {
    const response = await this.client.get<T>(url, config);
    return {
      data: response.data,
      status: response.status,
      headers: response.headers,
    };
  }

  async post<T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<ExternalApiResponse<T>> {
    const response = await this.client.post<T>(url, data, config);
    return {
      data: response.data,
      status: response.status,
      headers: response.headers,
    };
  }

  // Add other HTTP methods as needed
}

export const externalApiClient = new ExternalApiClient();
