## Health Check Endpoint

```typescript
// src/routes/healthCheck.ts
import express from 'express';
import mongoose from 'mongoose';
import { getIntegrationClients } from '../integrations';

const router = express.Router();

router.get('/', async (req, res) => {
  const healthStatus: Record<string, { status: string; details?: any }> = {
    service: { status: 'healthy' },
    database: { status: 'unknown' },
    integrations: { status: 'unknown' },
  };

  // Check database connection
  if (mongoose.connection.readyState === 1) {
    healthStatus.database.status = 'healthy';
  } else {
    healthStatus.database.status = 'unhealthy';
    healthStatus.database.details = {
      state: mongoose.connection.readyState,
    };
  }

  // Check integrations
  try {
    const clients = getIntegrationClients();
    await Promise.all([
      clients.erp.testConnection(),
      clients.sso.testConnection(),
    ]);
    healthStatus.integrations.status = 'healthy';
  } catch (error) {
    healthStatus.integrations.status = 'unhealthy';
    healthStatus.integrations.details = error instanceof Error ? error.message : 'Unknown error';
  }

  // Determine overall status
  const isHealthy = Object.values(healthStatus).every(
    (service) => service.status === 'healthy'
  );

  res.status(isHealthy ? 200 : 503).json({
    status: isHealthy ? 'healthy' : 'unhealthy',
    services: healthStatus,
  });
});

export const healthCheckRouter = router;
