### 5. Infrastructure Layer (Data Access)

```csharp
// Enterprise.Backend.Infrastructure/DependencyInjection.cs
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.EntityFrameworkCore;
using Enterprise.Backend.Application.Common.Interfaces;
using Enterprise.Backend.Infrastructure.Persistence;
using Enterprise.Backend.Infrastructure.Services;

namespace Enterprise.Backend.Infrastructure
{
    public static class DependencyInjection
    {
        public static IServiceCollection AddInfrastructureServices(this IServiceCollection services, IConfiguration configuration)
        {
            // Add DbContext with SQL Server
            services.AddDbContext<ApplicationDbContext>(options =>
                options.UseSqlServer(
                    configuration.GetConnectionString("DefaultConnection"),
                    b => b.MigrationsAssembly(typeof(ApplicationDbContext).Assembly.FullName)));

            // Add Cosmos DB context
            services.AddSingleton<ICosmosDbService>(InitializeCosmosClientInstanceAsync(configuration).GetAwaiter().GetResult());

            // Add repositories
            services.AddScoped<ICustomerRepository, CustomerRepository>();
            services.AddScoped<IOrderRepository, OrderRepository>();

            // Add Azure services
            services.AddScoped<IBlobStorageService, BlobStorageService>();
            services.AddScoped<IQueueService, QueueService>();

            // Add identity services
            services.AddScoped<IIdentityService, IdentityService>();

            return services;
        }

        private static async Task<CosmosDbService> InitializeCosmosClientInstanceAsync(IConfiguration configuration)
        {
            var endpointUri = configuration["CosmosDb:EndpointUri"];
            var primaryKey = configuration["CosmosDb:PrimaryKey"];
            var databaseName = configuration["CosmosDb:DatabaseName"];
            var containerName = configuration["CosmosDb:ContainerName"];

            var cosmosClient = new CosmosClient(endpointUri, primaryKey);
            var database = await cosmosClient.CreateDatabaseIfNotExistsAsync(databaseName);
            await database.Database.CreateContainerIfNotExistsAsync(containerName, "/id");

            return new CosmosDbService(cosmosClient, databaseName, containerName);
        }
    }
}
