### 8. Example CQRS Command Handler

```csharp
// Enterprise.Backend.Application/Customers/Commands/CreateCustomer/CreateCustomerCommandHandler.cs
using System.Threading;
using System.Threading.Tasks;
using Enterprise.Backend.Application.Common.Interfaces;
using Enterprise.Backend.Domain.Entities;
using MediatR;

namespace Enterprise.Backend.Application.Customers.Commands.CreateCustomer
{
    public class CreateCustomerCommandHandler : IRequestHandler<CreateCustomerCommand, int>
    {
        private readonly IApplicationDbContext _context;

        public CreateCustomerCommandHandler(IApplicationDbContext context)
        {
            _context = context;
        }

        public async Task<int> Handle(CreateCustomerCommand request, CancellationToken cancellationToken)
        {
            var entity = new Customer(
                request.FirstName,
                request.LastName,
                request.Email,
                request.PhoneNumber,
                request.DateOfBirth);

            if (request.Address != null)
            {
                entity.UpdateAddress(new Address(
                    request.Address.Street,
                    request.Address.City,
                    request.Address.State,
                    request.Address.PostalCode,
                    request.Address.Country));
            }

            _context.Customers.Add(entity);

            await _context.SaveChangesAsync(cancellationToken);

            return entity.Id;
        }
    }
}
