### 4. Database Service (services/databaseService.js)

```javascript
const sql = require('mssql');
const { CosmosClient } = require('@azure/cosmos');
const config = require('../config/config');

let sqlPool;
let cosmosClient;
let cosmosDatabase;
let cosmosContainer;

async function initializeDatabase() {
  try {
    // Initialize SQL Server connection
    sqlPool = await new sql.ConnectionPool(config.database.sqlServer).connect();

    // Initialize Cosmos DB connection
    cosmosClient = new CosmosClient({ endpoint: config.database.cosmosDB.endpoint, key: config.database.cosmosDB.key });
    const { database } = await cosmosClient.databases.createIfNotExists({ id: config.database.cosmosDB.databaseId });
    cosmosDatabase = database;
    const { container } = await database.containers.createIfNotExists({ id: config.database.cosmosDB.containerId });
    cosmosContainer = container;

    return true;
  } catch (error) {
    console.error('Database initialization failed:', error);
    throw error;
  }
}

async function executeSqlQuery(query, params = []) {
  try {
    const request = sqlPool.request();
    params.forEach(param => {
      request.input(param.name, param.type, param.value);
    });
    return await request.query(query);
  } catch (error) {
    console.error('SQL query execution failed:', error);
    throw error;
  }
}

async function queryCosmos(query, parameters) {
  try {
    const { resources } = await cosmosContainer.items.query({
      query,
      parameters
    }).fetchAll();
    return resources;
  } catch (error) {
    console.error('Cosmos DB query failed:', error);
    throw error;
  }
}

module.exports = {
  initializeDatabase,
  executeSqlQuery,
  queryCosmos,
  sqlPool,
  cosmosClient,
  cosmosDatabase,
  cosmosContainer
};
```

### 5. Authentication Middleware (middleware/authMiddleware.js)

```javascript
const jwt = require('jsonwebtoken');
const { verifyToken } = require('../services/authService');
const config = require('../config/config');

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, config.auth.jwtSecret, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

function authorizeRoles(allowedRoles) {
  return (req, res, next) => {
    if (!req.user || !req.user.roles) {
      return res.status(403).json({ error: 'Access denied' });
    }

    const hasPermission = allowedRoles.some(role => req.user.roles.includes(role));
    if (!hasPermission) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

module.exports = {
  authenticateToken,
  authorizeRoles
};
