```javascript
const { BlobServiceClient } = require('@azure/storage-blob');
const { ServiceBusClient } = require('@azure/service-bus');
const config = require('../config/config');

class AzureService {
  constructor() {
    this.blobServiceClient = BlobServiceClient.fromConnectionString(config.azure.storage.connectionString);
    this.containerClient = this.blobServiceClient.getContainerClient(config.azure.storage.containerName);
    this.serviceBusClient = new ServiceBusClient(config.azure.serviceBus.connectionString);
    this.sender = this.serviceBusClient.createSender(config.azure.serviceBus.queueName);
  }

  async uploadFile(fileName, fileContent) {
    try {
      const blockBlobClient = this.containerClient.getBlockBlobClient(fileName);
      await blockBlobClient.upload(fileContent, fileContent.length);
      return blockBlobClient.url;
    } catch (error) {
      console.error('Azure file upload failed:', error);
      throw error;
    }
  }

  async sendMessage(message) {
    try {
      const messageBuffer = Buffer.from(JSON.stringify(message));
      await this.sender.sendMessages({ body: messageBuffer });
    } catch (error) {
      console.error('Azure Service Bus message sending failed:', error);
      throw error;
    }
  }

  async close() {
    await this.sender.close();
    await this.serviceBusClient.close();
  }
}

module.exports = new AzureService();
