// Services/BlobStorageService.cs
using Azure.Storage.Blobs;
using Azure.Storage.Blobs.Models;

namespace EnterpriseBackend.Services
{
    public interface IBlobStorageService
    {
        Task<Uri> UploadFileAsync(Stream fileStream, string fileName, string contentType);
        Task<Stream> DownloadFileAsync(string fileName);
        Task DeleteFileAsync(string fileName);
        Task<IEnumerable<string>> ListFilesAsync();
    }

    public class BlobStorageService : IBlobStorageService
    {
        private readonly BlobServiceClient _blobServiceClient;
        private readonly string _containerName;
        private readonly ILogger<BlobStorageService> _logger;

        public BlobStorageService(IConfiguration configuration, ILogger<BlobStorageService> logger)
        {
            _blobServiceClient = new BlobServiceClient(configuration["AzureStorage:ConnectionString"]);
            _containerName = configuration["AzureStorage:ContainerName"];
            _logger = logger;
        }

        public async Task<Uri> UploadFileAsync(Stream fileStream, string fileName, string contentType)
        {
            try
            {
                var containerClient = _blobServiceClient.GetBlobContainerClient(_containerName);
                await containerClient.CreateIfNotExistsAsync();

                var blobClient = containerClient.GetBlobClient(fileName);

                var blobHttpHeader = new BlobHttpHeaders
                {
                    ContentType = contentType
                };

                await blobClient.UploadAsync(fileStream, blobHttpHeader);

                _logger.LogInformation($"File {fileName} uploaded successfully to Azure Blob Storage");
                return blobClient.Uri;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error uploading file {fileName} to Azure Blob Storage");
                throw;
            }
        }

        public async Task<Stream> DownloadFileAsync(string fileName)
        {
            try
            {
                var containerClient = _blobServiceClient.GetBlobContainerClient(_containerName);
                var blobClient = containerClient.GetBlobClient(fileName);

                var response = await blobClient.DownloadAsync();
                _logger.LogInformation($"File {fileName} downloaded successfully from Azure Blob Storage");

                return response.Value.Content;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error downloading file {fileName} from Azure Blob Storage");
                throw;
            }
        }

        public async Task DeleteFileAsync(string fileName)
        {
            try
            {
                var containerClient = _blobServiceClient.GetBlobContainerClient(_containerName);
                var blobClient = containerClient.GetBlobClient(fileName);

                await blobClient.DeleteIfExistsAsync();
                _logger.LogInformation($"File {fileName} deleted successfully from Azure Blob Storage");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error deleting file {fileName} from Azure Blob Storage");
                throw;
            }
        }

        public async Task<IEnumerable<string>> ListFilesAsync()
        {
            try
            {
                var containerClient = _blobServiceClient.GetBlobContainerClient(_containerName);
                var files = new List<string>();

                await foreach (var blobItem in containerClient.GetBlobsAsync())
                {
                    files.Add(blobItem.Name);
                }

                _logger.LogInformation($"Listed {files.Count} files from Azure Blob Storage");
                return files;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error listing files from Azure Blob Storage");
                throw;
            }
        }
    }
}
