public class EnterpriseBackgroundService : BackgroundService
{
    private readonly ILogger<EnterpriseBackgroundService> _logger;
    private readonly IDataRepository _dataRepository;
    private readonly ICacheService _cacheService;
    private readonly IIntegrationService _integrationService;

    public EnterpriseBackgroundService(
        ILogger<EnterpriseBackgroundService> logger,
        IDataRepository dataRepository,
        ICacheService cacheService,
        IIntegrationService integrationService)
    {
        _logger = logger;
        _dataRepository = dataRepository;
        _cacheService = cacheService;
        _integrationService = integrationService;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Enterprise Service is starting.");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                // Process business logic
                await ProcessBusinessOperations();

                // Check for integration with legacy systems
                await _integrationService.CheckForPendingIntegrations();

                await Task.Delay(TimeSpan.FromMinutes(1), stoppingToken);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error in Enterprise Service");
                await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
            }
        }

        _logger.LogInformation("Enterprise Service is stopping.");
    }

    private async Task ProcessBusinessOperations()
    {
        // Example business logic processing
        var pendingOrders = await _dataRepository.GetPendingOrders();

        foreach (var order in pendingOrders)
        {
            // Process order
            order.Status = "Processing";
            await _dataRepository.UpdateOrder(order);

            // Cache processed order
            await _cacheService.Set($"order:{order.Id}", order, TimeSpan.FromHours(1));
        }
    }
}
