### 3. Data Layer (Azure SQL + Cosmos DB)

```csharp
// DataRepository.cs - Data access layer
using System.Data.SqlClient;
using Microsoft.Azure.Cosmos;
using Microsoft.Extensions.Configuration;

public interface IDataRepository
{
    Task<IEnumerable<Order>> GetPendingOrders();
    Task UpdateOrder(Order order);
    Task<Customer> GetCustomerById(string id);
}

public class AzureSqlRepository : IDataRepository
{
    private readonly string _connectionString;
    private readonly CosmosClient _cosmosClient;

    public AzureSqlRepository(IConfiguration configuration)
    {
        _connectionString = configuration.GetConnectionString("AzureSqlConnection");
        _cosmosClient = new CosmosClient(configuration.GetConnectionString("CosmosDbConnection"));
    }

    public async Task<IEnumerable<Order>> GetPendingOrders()
    {
        var orders = new List<Order>();

        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(
                "SELECT * FROM Orders WHERE Status = 'Pending'",
                connection);

            using (var reader = await command.ExecuteReaderAsync())
            {
                while (await reader.ReadAsync())
                {
                    orders.Add(new Order
                    {
                        Id = reader.GetInt32(0),
                        CustomerId = reader.GetString(1),
                        Status = reader.GetString(2),
                        Amount = reader.GetDecimal(3)
                    });
                }
            }
        }

        return orders;
    }

    public async Task UpdateOrder(Order order)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand(
                "UPDATE Orders SET Status = @Status WHERE Id = @Id",
                connection);

            command.Parameters.AddWithValue("@Status", order.Status);
            command.Parameters.AddWithValue("@Id", order.Id);

            await command.ExecuteNonQueryAsync();
        }
    }

    public async Task<Customer> GetCustomerById(string id)
    {
        var container = _cosmosClient.GetContainer("Customers", "CustomerDetails");
        var response = await container.ReadItemAsync<Customer>(id, new PartitionKey(id));
        return response.Resource;
    }
}
