// IntegrationService.cs - Legacy system integration
using System.Net.Http;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.Configuration;

public interface IIntegrationService
{
    Task CheckForPendingIntegrations();
    Task<bool> SendOrderToLegacySystem(Order order);
}

public class LegacySystemIntegrationService : IIntegrationService
{
    private readonly HttpClient _httpClient;
    private readonly string _legacyApiUrl;
    private readonly IDataRepository _dataRepository;

    public LegacySystemIntegrationService(
        HttpClient httpClient,
        IConfiguration configuration,
        IDataRepository dataRepository)
    {
        _httpClient = httpClient;
        _legacyApiUrl = configuration["LegacySystem:ApiUrl"];
        _dataRepository = dataRepository;
    }

    public async Task CheckForPendingIntegrations()
    {
        var pendingOrders = await _dataRepository.GetPendingOrders();

        foreach (var order in pendingOrders)
        {
            if (await SendOrderToLegacySystem(order))
            {
                order.Status = "Integrated";
                await _dataRepository.UpdateOrder(order);
            }
        }
    }

    public async Task<bool> SendOrderToLegacySystem(Order order)
    {
        try
        {
            var request = new HttpRequestMessage(HttpMethod.Post, $"{_legacyApiUrl}/api/orders");
            request.Content = new StringContent(
                JsonSerializer.Serialize(order),
                Encoding.UTF8,
                "application/json");

            var response = await _httpClient.SendAsync(request);

            if (response.IsSuccessStatusCode)
            {
                return true;
            }

            // Log error
            var errorContent = await response.Content.ReadAsStringAsync();
            // Log errorContent
            return false;
        }
        catch (Exception ex)
        {
            // Log exception
            return false;
        }
    }
}
