using System.DirectoryServices;
using System.Threading.Tasks;
using EnterpriseBackend.Application.Common.Interfaces;

namespace EnterpriseBackend.Infrastructure.Integration
{
    public class ActiveDirectoryService : IActiveDirectoryService
    {
        private readonly string _domain;
        private readonly string _adminUsername;
        private readonly string _adminPassword;

        public ActiveDirectoryService(string domain, string adminUsername, string adminPassword)
        {
            _domain = domain;
            _adminUsername = adminUsername;
            _adminPassword = adminPassword;
        }

        public async Task CreateUserAsync(string username, string firstName, string lastName, string department)
        {
            await Task.Run(() =>
            {
                using (var entry = new DirectoryEntry($"LDAP://{_domain}", _adminUsername, _adminPassword))
                {
                    using (var userEntry = entry.Children.Add($"CN={username},OU=Users,{_domain}"))
                    {
                        userEntry.Properties["samAccountName"].Value = username;
                        userEntry.Properties["userPrincipalName"].Value = $"{username}@{_domain}";
                        userEntry.Properties["givenName"].Value = firstName;
                        userEntry.Properties["sn"].Value = lastName;
                        userEntry.Properties["department"].Value = department;
                        userEntry.Properties["userAccountControl"].Value = 0x200; // Normal account
                        userEntry.CommitChanges();
                    }
                }
            });
        }

        public async Task<bool> AuthenticateUserAsync(string username, string password)
        {
            return await Task.Run(() =>
            {
                try
                {
                    using (var entry = new DirectoryEntry($"LDAP://{_domain}", username, password))
                    {
                        var nativeObject = entry.NativeObject;
                        return true;
                    }
                }
                catch
                {
                    return false;
                }
            });
        }
    }
}
