```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.OpenApi.Models;
using System;
using System.IO;
using System.Reflection;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System.Text;
using Microsoft.AspNetCore.OData;
using Microsoft.OData.Edm;
using Microsoft.OData.ModelBuilder;
using Enterprise.Backend.Models;
using Enterprise.Backend.Repositories;
using Enterprise.Backend.Services;
using Enterprise.Backend.Infrastructure;
using Enterprise.Backend.Middleware;
using MediatR;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend
{
    public class Startup
    {
        public Startup(IConfiguration configuration)
        {
            Configuration = configuration;
        }

        public IConfiguration Configuration { get; }

        public void ConfigureServices(IServiceCollection services)
        {
            // Configure CORS for enterprise clients
            services.AddCors(options =>
            {
                options.AddPolicy("EnterprisePolicy", builder =>
                {
                    builder.WithOrigins(
                        "https://*.enterprise.com",
                        "https://*.azurewebsites.net")
                        .AllowAnyHeader()
                        .AllowAnyMethod();
                });
            });

            // Add controllers with OData support
            services.AddControllers()
                .AddOData(opt => opt
                    .Select()
                    .Filter()
                    .Expand()
                    .Count()
                    .SetMaxTop(100)
                    .AddRouteComponents("odata", GetEdmModel()));

            // Configure authentication (Azure AD + Windows Auth)
            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
                options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
            })
            .AddJwtBearer(options =>
            {
                options.Authority = $"https://login.microsoftonline.com/{Configuration["AzureAd:TenantId"]}/v2.0";
                options.TokenValidationParameters = new TokenValidationParameters
                {
                    ValidateIssuer = true,
                    ValidIssuer = $"https://login.microsoftonline.com/{Configuration["AzureAd:TenantId"]}/v2.0",
                    ValidateAudience = true,
                    ValidAudience = Configuration["AzureAd:Audience"],
                    ValidateLifetime = true
                };
            })
            .AddNegotiate(); // For Windows Authentication

            // Add authorization policies
            services.AddAuthorization(options =>
            {
                options.AddPolicy("RequireAdminRole", policy =>
                    policy.RequireRole("Admin"));
            });

            // Configure database context (hybrid SQL)
            services.AddDbContext<EnterpriseDbContext>(options =>
            {
                options.UseSqlServer(Configuration.GetConnectionString("OnPremSql"));
                options.UseSqlServer(Configuration.GetConnectionString("AzureSql"));
            });

            // Register repositories
            services.AddScoped<IEmployeeRepository, EmployeeRepository>();
            services.AddScoped<IDepartmentRepository, DepartmentRepository>();

            // Register services
            services.AddScoped<IEmployeeService, EmployeeService>();
            services.AddScoped<IDepartmentService, DepartmentService>();

            // Add MediatR for CQRS pattern
            services.AddMediatR(Assembly.GetExecutingAssembly());

            // Configure Swagger for API documentation
            services.AddSwaggerGen(c =>
            {
                c.SwaggerDoc("v1", new OpenApiInfo
                {
                    Title = "Enterprise Backend API",
                    Version = "v1",
                    Description = "Backend services for enterprise applications",
                    Contact = new OpenApiContact
                    {
                        Name = "Enterprise IT Support",
                        Email = "it-support@enterprise.com"
                    }
                });

                // Include XML comments
                var xmlFile = $"{Assembly.GetExecutingAssembly().GetName().Name}.xml";
                var xmlPath = Path.Combine(AppContext.BaseDirectory, xmlFile);
                c.IncludeXmlComments(xmlPath);

                // Add JWT authentication to Swagger
                c.AddSecurityDefinition("Bearer", new OpenApiSecurityScheme
                {
                    Description = "JWT Authorization header using the Bearer scheme",
                    Name = "Authorization",
                    In = ParameterLocation.Header,
                    Type = SecuritySchemeType.ApiKey,
                    Scheme = "Bearer"
                });

                c.AddSecurityRequirement(new OpenApiSecurityRequirement
                {
                    {
                        new OpenApiSecurityScheme
                        {
                            Reference = new OpenApiReference
                            {
                                Type = ReferenceType.SecurityScheme,
                                Id = "Bearer"
                            }
                        },
                        Array.Empty<string>()
                    }
                });
            });

            // Add health checks
            services.AddHealthChecks()
                .AddSqlServer(Configuration.GetConnectionString("OnPremSql"), name: "OnPremSQL")
                .AddSqlServer(Configuration.GetConnectionString("AzureSql"), name: "AzureSQL")
                .AddAzureBlobStorage(Configuration["AzureStorage:ConnectionString"], name: "AzureStorage");

            // Add response caching
            services.AddResponseCaching();

            // Add distributed caching for enterprise scenarios
            services.AddStackExchangeRedisCache(options =>
            {
                options.Configuration = Configuration["Redis:ConnectionString"];
                options.InstanceName = "EnterpriseBackend_";
            });
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            if (env.IsDevelopment())
            {
                app.UseDeveloperExceptionPage();
            }
            else
            {
                app.UseExceptionHandler("/error");
                app.UseHsts();
            }

            // Enable middleware
            app.UseHttpsRedirection();
            app.UseStaticFiles();
            app.UseRouting();

            // Enable CORS
            app.UseCors("EnterprisePolicy");

            // Enable authentication and authorization
            app.UseAuthentication();
            app.UseAuthorization();

            // Enable response caching
            app.UseResponseCaching();

            // Enable Swagger
            app.UseSwagger();
            app.UseSwaggerUI(c =>
            {
                c.SwaggerEndpoint("/swagger/v1/swagger.json", "Enterprise Backend API V1");
                c.RoutePrefix = "api-docs";
            });

            // Enable health checks
            app.UseHealthChecks("/health");

            // Add custom middleware
            app.UseMiddleware<RequestLoggingMiddleware>();
            app.UseMiddleware<PerformanceMonitoringMiddleware>();

            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }

        private static IEdmModel GetEdmModel()
        {
            var builder = new ODataConventionModelBuilder();
            builder.EntitySet<Employee>("Employees");
            builder.EntitySet<Department>("Departments");
            return builder.GetEdmModel();
        }
    }
}
