### 4. Employee Repository (Hybrid SQL)

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Enterprise.Backend.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;

namespace Enterprise.Backend.Repositories
{
    public interface IEmployeeRepository
    {
        Task<Employee> GetByIdAsync(int id);
        Task<IEnumerable<Employee>> GetAllAsync();
        Task<Employee> AddAsync(Employee employee);
        Task<Employee> UpdateAsync(Employee employee);
        Task<bool> DeleteAsync(int id);
    }

    public class EmployeeRepository : IEmployeeRepository
    {
        private readonly EnterpriseDbContext _context;
        private readonly ILogger<EmployeeRepository> _logger;

        public EmployeeRepository(EnterpriseDbContext context, ILogger<EmployeeRepository> logger)
        {
            _context = context ?? throw new ArgumentNullException(nameof(context));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public async Task<Employee> GetByIdAsync(int id)
        {
            try
            {
                // Try Azure SQL first
                var employee = await _context.Employees
                    .FromSqlRaw("SELECT * FROM Employees WHERE Id = {0}", id)
                    .FirstOrDefaultAsync();

                if (employee == null)
                {
                    // Fallback to on-prem SQL if not found in Azure
                    employee = await _context.Employees
                        .FromSqlRaw("SELECT * FROM Employees WHERE Id = {0}", id)
                        .FirstOrDefaultAsync();
                }

                return employee;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error getting employee with ID {id}");
                throw;
            }
        }

        public async Task<IEnumerable<Employee>> GetAllAsync()
        {
            try
            {
                // Get from Azure SQL first
                var azureEmployees = await _context.Employees
                    .FromSqlRaw("SELECT * FROM Employees")
                    .ToListAsync();

                // Get from on-prem SQL
                var onPremEmployees = await _context.Employees
                    .FromSqlRaw("SELECT * FROM Employees")
                    .ToListAsync();

                // Merge results (simple approach - could be optimized)
                return azureEmployees.Union(onPremEmployees, new EmployeeComparer());
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error getting all employees");
                throw;
            }
        }

        public async Task<Employee> AddAsync(Employee employee)
        {
            if (employee == null)
            {
                throw new ArgumentNullException(nameof(employee));
            }

            try
            {
                // Add to both databases (could be optimized with transaction)
                await _context.Employees.AddAsync(employee);
                await _context.SaveChangesAsync();

                // Add to Azure SQL
                await _context.Employees.AddAsync(employee);
                await _context.SaveChangesAsync();

                return employee;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error adding employee {employee.FirstName} {employee.LastName}");
                throw;
            }
        }

        public async Task<Employee> UpdateAsync(Employee employee)
        {
            if (employee == null)
            {
                throw new ArgumentNullException(nameof(employee));
            }

            try
            {
                // Update in both databases
                _context.Employees.Update(employee);
                await _context.SaveChangesAsync();

                // Update in Azure SQL
                _context.Employees.Update(employee);
                await _context.SaveChangesAsync();

                return employee;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error updating employee with ID {employee.Id}");
                throw;
            }
        }

        public async Task<bool> DeleteAsync(int id)
        {
            try
            {
                var employee = await GetByIdAsync(id);
                if (employee == null)
                {
                    return false;
                }

                // Delete from both databases
                _context.Employees.Remove(employee);
                await _context.SaveChangesAsync();

                // Delete from Azure SQL
                _context.Employees.Remove(employee);
                await _context.SaveChangesAsync();

                return true;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error deleting employee with ID {id}");
                throw;
            }
        }
    }

    // Custom comparer for merging results
    public class EmployeeComparer : IEqualityComparer<Employee>
    {
        public bool Equals(Employee x, Employee y)
        {
            if (x == null || y == null)
                return false;

            return x.Id == y.Id;
        }

        public int GetHashCode(Employee obj)
        {
            return obj.Id.GetHashCode();
        }
    }
}
