using Microsoft.EntityFrameworkCore;
using Enterprise.Backend.Models;

namespace Enterprise.Backend.Infrastructure
{
    public class EnterpriseDbContext : DbContext
    {
        public EnterpriseDbContext(DbContextOptions<EnterpriseDbContext> options)
            : base(options)
        {
        }

        public DbSet<Employee> Employees { get; set; }
        public DbSet<Department> Departments { get; set; }

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            // Configure entity relationships
            modelBuilder.Entity<Employee>()
                .HasOne(e => e.Department)
                .WithMany(d => d.Employees)
                .HasForeignKey(e => e.DepartmentId);

            // Configure hybrid SQL routing
            modelBuilder.Entity<Employee>().ToTable("Employees", "dbo");
            modelBuilder.Entity<Department>().ToTable("Departments", "dbo");

            base.OnModelCreating(modelBuilder);
        }
    }
}
