// Infrastructure/DependencyInjection.cs
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace EnterpriseBackend.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddInfrastructureServices(
        this IServiceCollection services,
        IConfiguration configuration)
    {
        // Configure Cosmos DB
        services.AddSingleton<ICosmosDbService>(InitializeCosmosClientInstanceAsync(configuration).GetAwaiter().GetResult());

        // Configure Azure Service Bus
        services.AddSingleton<IServiceBusService>(new ServiceBusService(
            configuration["AzureServiceBus:ConnectionString"],
            configuration["AzureServiceBus:QueueName"]));

        // Add repositories
        services.AddScoped<IUserRepository, UserRepository>();
        services.AddScoped<IOrderRepository, OrderRepository>();

        return services;
    }

    private static async Task<CosmosDbService> InitializeCosmosClientInstanceAsync(IConfiguration configuration)
    {
        var databaseName = configuration["CosmosDb:DatabaseName"];
        var containerName = configuration["CosmosDb:ContainerName"];
        var account = configuration["CosmosDb:AccountEndpoint"];
        var key = configuration["CosmosDb:AccountKey"];

        var cosmosClient = new CosmosClient(account, key);
        var database = await cosmosClient.CreateDatabaseIfNotExistsAsync(databaseName);
        await database.Database.CreateContainerIfNotExistsAsync(containerName, "/id");

        return new CosmosDbService(cosmosClient, databaseName, containerName);
    }
}

// Infrastructure/Persistence/CosmosDbService.cs
public interface ICosmosDbService
{
    Task<ItemResponse<T>> AddItemAsync<T>(T item, string partitionKey);
    Task<ItemResponse<T>> GetItemAsync<T>(string id, string partitionKey);
    Task<IEnumerable<T>> GetItemsAsync<T>(string queryString);
}

public class CosmosDbService : ICosmosDbService
{
    private readonly Container _container;

    public CosmosDbService(CosmosClient cosmosClient, string databaseName, string containerName)
    {
        _container = cosmosClient.GetContainer(databaseName, containerName);
    }

    public async Task<ItemResponse<T>> AddItemAsync<T>(T item, string partitionKey)
    {
        return await _container.CreateItemAsync(item, new PartitionKey(partitionKey));
    }

    public async Task<ItemResponse<T>> GetItemAsync<T>(string id, string partitionKey)
    {
        try
        {
            return await _container.ReadItemAsync<T>(id, new PartitionKey(partitionKey));
        }
        catch (CosmosException ex) when (ex.StatusCode == HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<IEnumerable<T>> GetItemsAsync<T>(string queryString)
    {
        var query = _container.GetItemQueryIterator<T>(new QueryDefinition(queryString));
        var results = new List<T>();

        while (query.HasMoreResults)
        {
            var response = await query.ReadNextAsync();
            results.AddRange(response.ToList());
        }

        return results;
    }
}
