### 6. Example Controller

```csharp
// Api/Controllers/OrdersController.cs
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace EnterpriseBackend.Api.Controllers;

[Authorize]
[ApiController]
[Route("api/[controller]")]
public class OrdersController : ControllerBase
{
    private readonly IOrderService _orderService;
    private readonly IWindowsOrderService _windowsOrderService;
    private readonly ILogger<OrdersController> _logger;

    public OrdersController(
        IOrderService orderService,
        IWindowsOrderService windowsOrderService,
        ILogger<OrdersController> logger)
    {
        _orderService = orderService;
        _windowsOrderService = windowsOrderService;
        _logger = logger;
    }

    [HttpGet("{id}")]
    public async Task<ActionResult<Order>> GetOrder(string id)
    {
        try
        {
            _logger.LogInformation("Fetching order {OrderId}", id);

            // Try to get from modern system first
            var order = await _orderService.GetOrderAsync(id);

            if (order == null)
            {
                // Fall back to legacy Windows system
                order = await _windowsOrderService.GetOrderFromLegacySystem(id);

                if (order != null)
                {
                    // Store in modern system for future requests
                    await _orderService.CreateOrderAsync(order);
                }
            }

            return order == null ? NotFound() : Ok(order);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error fetching order {OrderId}", id);
            return StatusCode(500, "Internal server error");
        }
    }

    [HttpPost]
    public async Task<ActionResult<Order>> CreateOrder(Order order)
    {
        try
        {
            _logger.LogInformation("Creating order {OrderId}", order.Id);

            // Create in modern system
            var createdOrder = await _orderService.CreateOrderAsync(order);

            // Also process in legacy Windows system
            await _windowsOrderService.ProcessOrderInLegacySystem(createdOrder);

            return CreatedAtAction(nameof(GetOrder), new { id = createdOrder.Id }, createdOrder);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error creating order {OrderId}", order.Id);
            return StatusCode(500, "Internal server error");
        }
    }
}
