public class AzureStorageService : IStorageService
{
    private readonly CloudBlobClient _blobClient;
    private readonly ILogger<AzureStorageService> _logger;

    public AzureStorageService(IConfiguration configuration, ILogger<AzureStorageService> logger)
    {
        var storageConnectionString = configuration["AzureStorage:ConnectionString"];
        var storageAccount = CloudStorageAccount.Parse(storageConnectionString);
        _blobClient = storageAccount.CreateCloudBlobClient();
        _logger = logger;
    }

    public async Task<string> UploadFileAsync(Stream fileStream, string fileName, string containerName)
    {
        try
        {
            var container = _blobClient.GetContainerReference(containerName);
            await container.CreateIfNotExistsAsync();

            var blob = container.GetBlockBlobReference(fileName);
            await blob.UploadFromStreamAsync(fileStream);

            return blob.Uri.ToString();
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error uploading file {fileName} to container {containerName}");
            throw;
        }
    }

