// Services/EnterpriseService.cs
public class EnterpriseService : IEnterpriseService
{
    private readonly IEnterpriseRepository _repository;
    private readonly ILogger<EnterpriseService> _logger;
    private readonly IAzureServiceBusClient _serviceBusClient;

    public EnterpriseService(
        IEnterpriseRepository repository,
        ILogger<EnterpriseService> logger,
        IAzureServiceBusClient serviceBusClient)
    {
        _repository = repository;
        _logger = logger;
        _serviceBusClient = serviceBusClient;
    }

    public async Task<OperationResult> ProcessEnterpriseData(EnterpriseDataDto data)
    {
        using var activity = ActivitySource.StartActivity("ProcessEnterpriseData");

        try
        {
            // Validate input
            if (!data.IsValid())
            {
                return OperationResult.Failure("Invalid data");
            }

            // Process data
            var result = await _repository.ProcessData(data);

            // Publish event
            await _serviceBusClient.SendMessage(new EnterpriseEvent
            {
                DataId = result.Id,
                EventType = "DataProcessed",
                Timestamp = DateTime.UtcNow
            });

            return OperationResult.Success(result);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing enterprise data");
            throw;
        }
    }
}
