        try
        {
            // Business logic for data processing
            var entity = new EnterpriseData
            {
                // Map properties
                Id = Guid.NewGuid(),
                CreatedDate = DateTime.UtcNow,
                // ... other properties
            };

            _context.EnterpriseData.Add(entity);
            await _context.SaveChangesAsync();

            await transaction.CommitAsync();

            return entity;
        }
        catch (Exception ex)
        {
