// Auth/AzureAdAuthService.cs
using Microsoft.Extensions.Configuration;
using Microsoft.Identity.Client;
using System;
using System.Threading.Tasks;

namespace EnterpriseBackend.Auth
{
    public class AzureAdAuthService : IAuthService
    {
        private readonly IConfiguration _configuration;
        private readonly IConfidentialClientApplication _confidentialClient;

        public AzureAdAuthService(IConfiguration configuration)
        {
            _configuration = configuration;

            _confidentialClient = ConfidentialClientApplicationBuilder
                .Create(_configuration["AzureAd:ClientId"])
                .WithClientSecret(_configuration["AzureAd:ClientSecret"])
                .WithAuthority(new Uri(_configuration["AzureAd:Instance"] + _configuration["AzureAd:TenantId"]))
                .Build();
        }

        public async Task<string> GetAccessTokenForAppAsync()
        {
            var scopes = new[] { "https://graph.microsoft.com/.default" };
            var result = await _confidentialClient.AcquireTokenForClient(scopes)
                .ExecuteAsync();

            return result.AccessToken;
        }

        public async Task<string> GetAccessTokenForUserAsync(string[] scopes, string userAssertion)
        {
            var result = await _confidentialClient.AcquireTokenOnBehalfOf(scopes, new UserAssertion(userAssertion))
                .ExecuteAsync();

            return result.AccessToken;
        }
    }
}
