// AzureFunctions/OrderProcessor.cs
using Microsoft.Azure.WebJobs;
using Microsoft.Extensions.Logging;
using System;

namespace EnterpriseBackend.AzureFunctions
{
    public static class OrderProcessor
    {
        [FunctionName("ProcessOrder")]
        public static void Run(
            [QueueTrigger("orders-to-process", Connection = "AzureWebJobsStorage")]Order order,
            [CosmosDB(
                databaseName: "EnterpriseDB",
                collectionName: "ProcessedOrders",
                ConnectionStringSetting = "CosmosDBConnection")] out dynamic processedOrder,
            ILogger log)
        {
            log.LogInformation($"Processing order {order.Id} for customer {order.CustomerId}");

            try
            {
                // Business logic for processing the order
                order.Status = "Processed";
                order.ProcessedDate = DateTime.UtcNow;

                // Output to Cosmos DB for analytics
                processedOrder = new
                {
                    id = order.Id.ToString(),
                    customerId = order.CustomerId,
                    totalAmount = order.TotalAmount,
                    status = order.Status,
                    processedDate = order.ProcessedDate
                };

                log.LogInformation($"Successfully processed order {order.Id}");
            }
            catch (Exception ex)
            {
                log.LogError(ex, $"Error processing order {order.Id}");
                processedOrder = null;
            }
        }
    }
}
