// EnterpriseBackendService.cs
using System;
using System.ServiceProcess;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Serilog;
using Serilog.Events;

namespace Enterprise.Backend.Service
{
    public class EnterpriseBackendService : ServiceBase
    {
        private IHost _host;
        private readonly ILogger<EnterpriseBackendService> _logger;

        public EnterpriseBackendService(ILogger<EnterpriseBackendService> logger)
        {
            _logger = logger;
            ServiceName = "EnterpriseBackendService";
            CanStop = true;
            CanShutdown = true;
            CanPauseAndContinue = true;
        }

        protected override void OnStart(string[] args)
        {
            _logger.LogInformation("Starting Enterprise Backend Service...");

            try
            {
                _host = CreateHostBuilder(args).Build();
                _host.Start();

                _logger.LogInformation("Enterprise Backend Service started successfully.");
            }
            catch (Exception ex)
            {
                _logger.LogCritical(ex, "Failed to start Enterprise Backend Service");
                throw;
            }
        }

        protected override void OnStop()
        {
            _logger.LogInformation("Stopping Enterprise Backend Service...");

            try
            {
                _host?.StopAsync().GetAwaiter().GetResult();
                _host?.Dispose();
                _logger.LogInformation("Enterprise Backend Service stopped successfully.");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error stopping Enterprise Backend Service");
            }
        }

        private static IHostBuilder CreateHostBuilder(string[] args) =>
            Host.CreateDefaultBuilder(args)
                .UseWindowsService()
                .ConfigureServices((hostContext, services) =>
                {
                    // Configure logging
                    Log.Logger = new LoggerConfiguration()
                        .MinimumLevel.Information()
                        .MinimumLevel.Override("Microsoft", LogEventLevel.Warning)
                        .Enrich.FromLogContext()
                        .WriteTo.File(
                            path: @"C:\Logs\EnterpriseBackendService\Log-.txt",
                            rollingInterval: RollingInterval.Day,
                            retainedFileCountLimit: 30)
                        .WriteTo.AzureTableStorage(
                            storageTableName: "ServiceLogs",
                            connectionString: hostContext.Configuration["Azure:Storage:ConnectionString"],
                            restrictedToMinimumLevel: LogEventLevel.Information)
                        .CreateLogger();

                    services.AddLogging(loggingBuilder =>
                    {
                        loggingBuilder.ClearProviders();
                        loggingBuilder.AddSerilog();
                    });

                    // Register services
                    services.AddSingleton<IConfigurationService, ConfigurationService>();
                    services.AddSingleton<IAzureIntegrationService, AzureIntegrationService>();
                    services.AddSingleton<IDataProcessingService, DataProcessingService>();
                    services.AddHostedService<WorkerService>();

                    // Health checks
                    services.AddHealthChecks()
                        .AddCheck<ServiceHealthCheck>("ServiceHealthCheck");
                })
                .ConfigureLogging(logging =>
                {
                    logging.ClearProviders();
                    logging.AddConsole();
                });
    }

    static class Program
