// AzureIntegrationService.cs
using Azure.Identity;
using Azure.Storage.Blobs;
using Azure.Storage.Queues;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using System;
using System.Threading.Tasks;

namespace Enterprise.Backend.Service
{
    public interface IAzureIntegrationService
    {
        Task ProcessQueueMessagesAsync();
        Task UploadToBlobStorageAsync(string containerName, string blobName, Stream content);
        Task<string> GetConfigurationValueAsync(string key);
    }

    public class AzureIntegrationService : IAzureIntegrationService
    {
        private readonly IConfiguration _configuration;
        private readonly ILogger<AzureIntegrationService> _logger;
        private readonly BlobServiceClient _blobServiceClient;
        private readonly QueueServiceClient _queueServiceClient;

        public AzureIntegrationService(
            IConfiguration configuration,
            ILogger<AzureIntegrationService> logger)
        {
            _configuration = configuration;
            _logger = logger;

            // Use DefaultAzureCredential for managed identity authentication
            var credential = new DefaultAzureCredential();

            _blobServiceClient = new BlobServiceClient(
                new Uri(_configuration["Azure:Storage:BlobEndpoint"]),
                credential);

            _queueServiceClient = new QueueServiceClient(
                new Uri(_configuration["Azure:Storage:QueueEndpoint"]),
                credential);
        }

        public async Task ProcessQueueMessagesAsync()
        {
            try
            {
                var queueName = _configuration["Azure:Storage:QueueName"];
                var queueClient = _queueServiceClient.GetQueueClient(queueName);

                await queueClient.CreateIfNotExistsAsync();

                while (true)
                {
                    var messages = queueClient.ReceiveMessagesAsync(maxMessages: 10);

                    await foreach (var message in messages)
                    {
                        try
                        {
                            // Process message
                            _logger.LogInformation($"Processing message: {message.MessageId}");

                            // Process the message content here
                            // await ProcessMessageContent(message.MessageText);

                            // Delete the message after processing
                            await queueClient.DeleteMessageAsync(message.MessageId, message.PopReceipt);
                        }
                        catch (Exception ex)
                        {
                            _logger.LogError(ex, $"Error processing message {message.MessageId}");
                        }
                    }

                    await Task.Delay(1000); // Polling interval
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error in queue processing");
                throw;
            }
        }

        public async Task UploadToBlobStorageAsync(string containerName, string blobName, Stream content)
        {
            try
            {
                var containerClient = _blobServiceClient.GetBlobContainerClient(containerName);
                await containerClient.CreateIfNotExistsAsync();

                var blobClient = containerClient.GetBlobClient(blobName);
                await blobClient.UploadAsync(content, overwrite: true);

                _logger.LogInformation($"Uploaded blob {blobName} to container {containerName}");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error uploading blob {blobName}");
                throw;
            }
        }

        public async Task<string> GetConfigurationValueAsync(string key)
        {
            try
            {
                // In a real implementation, you might fetch from Azure App Configuration
                return _configuration[key];
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, $"Error getting configuration value for {key}");
                throw;
            }
        }
    }
}
