## 3. Worker Service for Background Processing

```csharp
// WorkerService.cs
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using System;
using System.Threading;
using System.Threading.Tasks;

namespace Enterprise.Backend.Service
{
    public class WorkerService : BackgroundService
    {
        private readonly ILogger<WorkerService> _logger;
        private readonly IDataProcessingService _dataProcessingService;
        private readonly IAzureIntegrationService _azureIntegrationService;

        public WorkerService(
            ILogger<WorkerService> logger,
            IDataProcessingService dataProcessingService,
            IAzureIntegrationService azureIntegrationService)
        {
            _logger = logger;
            _dataProcessingService = dataProcessingService;
            _azureIntegrationService = azureIntegrationService;
        }

        protected override async Task ExecuteAsync(CancellationToken stoppingToken)
        {
            _logger.LogInformation("Worker Service is starting.");

            // Start processing queue messages in the background
            _ = Task.Run(() => _azureIntegrationService.ProcessQueueMessagesAsync(), stoppingToken);

            while (!stoppingToken.IsCancellationRequested)
            {
                try
                {
                    _logger.LogInformation("Worker Service is running.");

                    // Perform periodic processing
                    await _dataProcessingService.ProcessDataAsync();

                    // Wait for the next interval
                    await Task.Delay(TimeSpan.FromMinutes(5), stoppingToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error in worker service execution");
                    await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
                }
            }

            _logger.LogInformation("Worker Service is stopping.");
        }
    }
}
