### 3. Business Layer

```csharp
// src/Business/Services/OrderService.cs
using EnterpriseBackend.Business.Interfaces;
using EnterpriseBackend.Business.Models;
using EnterpriseBackend.Data.Repositories;
using Microsoft.Extensions.Logging;

namespace EnterpriseBackend.Business.Services;

public class OrderService : IOrderService
{
    private readonly IOrderRepository _orderRepository;
    private readonly ILogger<OrderService> _logger;

    public OrderService(IOrderRepository orderRepository, ILogger<OrderService> logger)
    {
        _orderRepository = orderRepository;
        _logger = logger;
    }

    public async Task<Order> CreateOrderAsync(Order order)
    {
        try
        {
            // Business validation
            if (order.Items == null || !order.Items.Any())
            {
                throw new ArgumentException("Order must contain at least one item");
            }

            // Calculate totals
            order.TotalAmount = order.Items.Sum(i => i.Quantity * i.UnitPrice);

            // Save to database
            var createdOrder = await _orderRepository.AddAsync(order);

            // Log successful operation
            _logger.LogInformation("Order created successfully. OrderId: {OrderId}", createdOrder.Id);

            return createdOrder;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error creating order");
            throw;
        }
    }

    public async Task<Order> GetOrderByIdAsync(int orderId)
    {
        try
        {
            var order = await _orderRepository.GetByIdAsync(orderId);

            if (order == null)
            {
                _logger.LogWarning("Order not found. OrderId: {OrderId}", orderId);
                throw new KeyNotFoundException($"Order with ID {orderId} not found");
            }

            return order;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error retrieving order. OrderId: {OrderId}", orderId);
            throw;
        }
    }
}
