// src/Integration/AzureServiceBus/OrderEventPublisher.cs
using Azure.Messaging.ServiceBus;
using EnterpriseBackend.Business.Models;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using System.Text.Json;

namespace EnterpriseBackend.Integration.AzureServiceBus;

public class OrderEventPublisher : IOrderEventPublisher
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly string _topicName;
    private readonly ILogger<OrderEventPublisher> _logger;

    public OrderEventPublisher(
        ServiceBusClient serviceBusClient,
        IConfiguration configuration,
        ILogger<OrderEventPublisher> logger)
    {
        _serviceBusClient = serviceBusClient;
        _topicName = configuration["AzureServiceBus:OrderTopic"];
        _logger = logger;
    }

    public async Task PublishOrderCreatedEventAsync(Order order)
    {
        try
        {
            var sender = _serviceBusClient.CreateSender(_topicName);

            var messageBody = JsonSerializer.Serialize(new
            {
                OrderId = order.Id,
                CustomerId = order.CustomerId,
                TotalAmount = order.TotalAmount,
                OrderDate = order.OrderDate,
                Status = "Created"
            });

            var message = new ServiceBusMessage(messageBody)
            {
                ContentType = "application/json",
                MessageId = Guid.NewGuid().ToString(),
                CorrelationId = order.Id.ToString()
            };

            await sender.SendMessageAsync(message);
            _logger.LogInformation("Published OrderCreated event for OrderId: {OrderId}", order.Id);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error publishing OrderCreated event for OrderId: {OrderId}", order.Id);
            throw;
        }
    }
}
