// File: Services/EnterpriseApiService.cs
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using System;
using System.Threading.Tasks;

namespace Enterprise.Backend.Services
{
    [ApiController]
    [Route("api/[controller]")]
    public class EnterpriseApiService : ControllerBase
    {
        private readonly ILogger<EnterpriseApiService> _logger;
        private readonly IBusinessLogicService _businessLogic;
        private readonly IDataAccessService _dataAccess;

        public EnterpriseApiService(
            ILogger<EnterpriseApiService> logger,
            IBusinessLogicService businessLogic,
            IDataAccessService dataAccess)
        {
            _logger = logger;
            _businessLogic = businessLogic;
            _dataAccess = dataAccess;
        }

        [HttpGet("health")]
        public IActionResult GetHealthStatus()
        {
            _logger.LogInformation("Health check requested");
            return Ok(new { Status = "Healthy", Timestamp = DateTime.UtcNow });
        }

        [HttpPost("process")]
        [Authorize(Roles = "Admin,Processor")]
        public async Task<IActionResult> ProcessEnterpriseData([FromBody] EnterpriseRequest request)
        {
            try
            {
                _logger.LogInformation("Processing enterprise request: {RequestId}", request.RequestId);

                // Validate request
                if (!ModelState.IsValid)
                {
                    return BadRequest(ModelState);
                }

                // Process through business logic
                var result = await _businessLogic.ProcessRequestAsync(request);

                // Persist data
                await _dataAccess.SaveProcessingResultAsync(result);

                // Return response
                return Ok(new EnterpriseResponse
                {
                    Success = true,
                    Result = result,
                    Timestamp = DateTime.UtcNow
                });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing enterprise request");
                return StatusCode(500, new { Error = "Internal server error", Details = ex.Message });
            }
        }

        [HttpGet("data/{id}")]
        [Authorize]
        public async Task<IActionResult> GetEnterpriseData(string id)
        {
            try
            {
                var data = await _dataAccess.GetEnterpriseDataAsync(id);
                if (data == null)
                {
                    return NotFound();
                }
                return Ok(data);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error retrieving enterprise data");
                return StatusCode(500, "Internal server error");
            }
        }
    }

    public class EnterpriseRequest
    {
        public string RequestId { get; set; }
        public string CustomerId { get; set; }
        public string DataPayload { get; set; }
        public DateTime RequestDate { get; set; } = DateTime.UtcNow;
    }

    public class EnterpriseResponse
    {
        public bool Success { get; set; }
        public object Result { get; set; }
        public DateTime Timestamp { get; set; }
    }
}
