// File: Data/DataAccessService.cs
using System.Data.SqlClient;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;

namespace Enterprise.Backend.Data
{
    public interface IDataAccessService
    {
        Task SaveProcessingResultAsync(object result);
        Task<object> GetEnterpriseDataAsync(string id);
    }

    public class SqlDataAccessService : IDataAccessService
    {
        private readonly IConfiguration _configuration;
        private readonly string _connectionString;

        public SqlDataAccessService(IConfiguration configuration)
        {
            _configuration = configuration;
            _connectionString = _configuration.GetConnectionString("EnterpriseDb");
        }

        public async Task SaveProcessingResultAsync(object result)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            // Example: Save to database
            var command = new SqlCommand(
                "INSERT INTO ProcessingResults (ResultData, CreatedDate) VALUES (@ResultData, @CreatedDate)",
                connection);

            command.Parameters.AddWithValue("@ResultData", result.ToString());
            command.Parameters.AddWithValue("@CreatedDate", DateTime.UtcNow);

            await command.ExecuteNonQueryAsync();
        }

        public async Task<object> GetEnterpriseDataAsync(string id)
        {
            using var connection = new SqlConnection(_connectionString);
            await connection.OpenAsync();

            var command = new SqlCommand(
                "SELECT * FROM EnterpriseData WHERE Id = @Id",
                connection);

            command.Parameters.AddWithValue("@Id", id);

            using var reader = await command.ExecuteReaderAsync();
            if (await reader.ReadAsync())
            {
                return new
                {
                    Id = reader["Id"],
                    Data = reader["Data"],
                    CreatedDate = reader["CreatedDate"]
                };
            }

            return null;
        }
    }
}
