### 4. Event Bus with Azure Service Bus

```csharp
// Shared/EventBus/AzureServiceBusEventBus.cs
using Azure.Messaging.ServiceBus;
using Microsoft.Extensions.Configuration;
using System;
using System.Text.Json;
using System.Threading.Tasks;

public class AzureServiceBusEventBus : IEventBus
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly IConfiguration _configuration;

    public AzureServiceBusEventBus(IConfiguration configuration)
    {
        _configuration = configuration;
        _serviceBusClient = new ServiceBusClient(_configuration["AzureServiceBus:ConnectionString"]);
    }

    public async Task Publish<T>(T @event) where T : class
    {
        var sender = _serviceBusClient.CreateSender(_configuration["AzureServiceBus:TopicName"]);
        var message = new ServiceBusMessage(JsonSerializer.Serialize(@event));
        await sender.SendMessageAsync(message);
    }

    public async Task Subscribe<T>(Func<T, Task> handler) where T : class
    {
        var processor = _serviceBusClient.CreateProcessor(
            _configuration["AzureServiceBus:TopicName"],
            _configuration["AzureServiceBus:SubscriptionName"]);

        processor.ProcessMessageAsync += async args =>
        {
            var body = args.Message.Body.ToString();
            var @event = JsonSerializer.Deserialize<T>(body);
            await handler(@event);
            await args.CompleteMessageAsync(args.Message);
        };

        processor.ProcessErrorAsync += errorArgs =>
        {
            // Handle errors
            return Task.CompletedTask;
        };

        await processor.StartProcessingAsync();
    }
}
