```javascript
const { BlobServiceClient } = require('@azure/storage-blob');
const config = require('../config');

class AzureStorageService {
  constructor() {
    this.blobServiceClient = BlobServiceClient.fromConnectionString(
      config.azure.storageConnectionString
    );
  }

  async uploadFile(containerName, fileName, fileBuffer) {
    const containerClient = this.blobServiceClient.getContainerClient(containerName);
    await containerClient.createIfNotExists();

    const blockBlobClient = containerClient.getBlockBlobClient(fileName);
    await blockBlobClient.upload(fileBuffer, fileBuffer.length);

    return blockBlobClient.url;
  }

  async downloadFile(containerName, fileName) {
    const containerClient = this.blobServiceClient.getContainerClient(containerName);
    const blockBlobClient = containerClient.getBlockBlobClient(fileName);

    const downloadResponse = await blockBlobClient.download();
    return await this.streamToBuffer(downloadResponse.readableStreamBody);
  }

  async streamToBuffer(readableStream) {
    return new Promise((resolve, reject) => {
      const chunks = [];
      readableStream.on('data', (data) => {
        chunks.push(data instanceof Buffer ? data : Buffer.from(data));
      });
      readableStream.on('end', () => {
        resolve(Buffer.concat(chunks));
      });
      readableStream.on('error', reject);
    });
  }
}

module.exports = new AzureStorageService();
