```csharp
// Services/MessageService.cs
using Azure.Messaging.ServiceBus;
using Microsoft.Extensions.Configuration;
using System.Text.Json;

public class MessageService : IMessageService
{
    private readonly ServiceBusClient _serviceBusClient;
    private readonly string _queueName;

    public MessageService(IConfiguration configuration)
    {
        _serviceBusClient = new ServiceBusClient(configuration["AzureServiceBus:ConnectionString"]);
        _queueName = configuration["AzureServiceBus:QueueName"];
    }

    public async Task SendMessageAsync<T>(T message)
    {
        var sender = _serviceBusClient.CreateSender(_queueName);
        var serviceBusMessage = new ServiceBusMessage(JsonSerializer.Serialize(message));
        await sender.SendMessageAsync(serviceBusMessage);
    }

    public async Task ProcessMessagesAsync(Func<ProcessMessageEventArgs, Task> handler)
    {
        var processor = _serviceBusClient.CreateProcessor(_queueName, new ServiceBusProcessorOptions());

        processor.ProcessMessageAsync += handler;
        processor.ProcessErrorAsync += ErrorHandler;

        await processor.StartProcessingAsync();
    }

    private static Task ErrorHandler(ProcessErrorEventArgs args)
    {
        // Log errors to Windows Event Log or Azure Monitor
        Console.WriteLine($"Error: {args.Exception.Message}");
        return Task.CompletedTask;
    }
}
