// Services/HybridConnectionService.cs
using Microsoft.Azure.Relay;

public class HybridConnectionService : IHybridConnectionService
{
    private readonly string _connectionString;
    private readonly string _hybridConnectionName;

    public HybridConnectionService(IConfiguration configuration)
    {
        _connectionString = configuration["HybridConnection:ConnectionString"];
        _hybridConnectionName = configuration["HybridConnection:Name"];
    }

    public async Task<string> SendRequestAsync(string requestData)
    {
        var tokenProvider = TokenProvider.CreateSharedAccessSignatureTokenProvider(
            _connectionString.Split('=')[1]);

        var hybridConnection = new HybridConnectionClient(
            new Uri($"sb://{_connectionString.Split(';')[0].Split('=')[1]}/{_hybridConnectionName}"),
            tokenProvider);

        var relayConnection = await hybridConnection.CreateConnectionAsync();
        var stream = relayConnection.Stream;

        using (var writer = new StreamWriter(stream))
        {
            await writer.WriteLineAsync(requestData);
            await writer.FlushAsync();
        }

        using (var reader = new StreamReader(stream))
        {
            return await reader.ReadToEndAsync();
        }
    }
}
