```csharp
// KeyVaultConfigurationProvider.cs
public class KeyVaultConfigurationProvider : ConfigurationProvider
{
    private readonly KeyVaultClient _keyVaultClient;
    private readonly string _vaultBaseUrl;

    public KeyVaultConfigurationProvider(KeyVaultClient keyVaultClient, string vaultBaseUrl)
    {
        _keyVaultClient = keyVaultClient;
        _vaultBaseUrl = vaultBaseUrl;
    }

    public override void Load()
    {
        var secrets = _keyVaultClient.GetSecretsAsync(_vaultBaseUrl).GetAwaiter().GetResult();
        var data = new Dictionary<string, string>();

        foreach (var secret in secrets)
        {
            var secretBundle = _keyVaultClient.GetSecretAsync(secret.Id).GetAwaiter().GetResult();
            data[secret.Id.Replace(_vaultBaseUrl, "").Trim('/')] = secretBundle.Value;
        }

        Data = data;
    }
}
```

