// Example of repository pattern implementation
public class UserRepository : IUserRepository
{
    private readonly IConfiguration _config;
    private readonly ILogger<UserRepository> _logger;

    public UserRepository(IConfiguration config, ILogger<UserRepository> logger)
    {
        _config = config;
        _logger = logger;
    }

    public async Task<User> GetUserById(string id)
    {
        try
        {
            // Use SQL Server for relational data
            using var connection = new SqlConnection(_config.GetConnectionString("SqlServer"));
            var user = await connection.QueryFirstOrDefaultAsync<User>(
                "SELECT * FROM Users WHERE Id = @Id", new { Id = id });

            // Use Cosmos DB for document data
            if (user != null)
            {
                var cosmosClient = new CosmosClient(_config["CosmosDb:ConnectionString"]);
                var container = cosmosClient.GetContainer("Users", "UserDetails");
                var response = await container.ReadItemAsync<UserDetails>(user.Id, new PartitionKey(user.Id));
                user.Details = response.Resource;
            }

            return user;
