        ISqlRepository sqlRepo,
        ICosmosRepository cosmosRepo,
        IAzureStorageRepository storageRepo)
    {
        _sqlRepo = sqlRepo;
        _cosmosRepo = cosmosRepo;
        _storageRepo = storageRepo;
    }

