    }

    public async Task<ServiceResponse> ExecuteWindowsServiceOperation(string serviceName, string operation)
    {
        try
        {
            // Use Windows Service Management API or PowerShell remoting
            using var client = new ServiceController(serviceName, _config["WindowsServer:Hostname"]);
