public class AzureFunctionClient : IAzureFunctionClient
{
    private readonly HttpClient _httpClient;
    private readonly IConfiguration _config;

    public AzureFunctionClient(HttpClient httpClient, IConfiguration config)
    {
        _httpClient = httpClient;
        _config = config;
    }

    public async Task<FunctionResponse> InvokeFunction(string functionName, object payload)
    {
        var functionUrl = $"{_config["AzureFunctions:BaseUrl"]}/api/{functionName}";
        var request = new HttpRequestMessage(HttpMethod.Post, functionUrl)
        {
            Content = new StringContent(JsonSerializer.Serialize(payload), Encoding.UTF8, "application/json")
        };

        var response = await _httpClient.SendAsync(request);
        var content = await response.Content.ReadAsStringAsync();

        return new FunctionResponse
        {
            IsSuccess = response.IsSuccessStatusCode,
            Content = content
        };
    }
}
