public class AzureStorageService : IStorageService
{
    private readonly CloudStorageAccount _storageAccount;
    private readonly ILogger<AzureStorageService> _logger;

    public AzureStorageService(IConfiguration configuration, ILogger<AzureStorageService> logger)
    {
        _storageAccount = CloudStorageAccount.Parse(configuration["AzureStorage:ConnectionString"]);
        _logger = logger;
    }

    public async Task UploadFileAsync(string containerName, string fileName, Stream content)
    {
        try
        {
            var blobClient = _storageAccount.CreateCloudBlobClient();
            var container = blobClient.GetContainerReference(containerName);
            await container.CreateIfNotExistsAsync();

            var blob = container.GetBlockBlobReference(fileName);
            await blob.UploadFromStreamAsync(content);
        }
        catch (Exception ex)
