        IOrderRepository repository,
        IWindowsIntegrationService windowsService,
        IAzureIntegrationService azureService)
    {
        _repository = repository;
        _windowsService = windowsService;
        _azureService = azureService;
    }

    public async Task<Order> ProcessOrder(Order order)
    {
        // Business logic
        var validationResult = await _windowsService.ValidateOrder(order);

        if (validationResult.IsValid)
        {
            // Process with Azure services
            await _azureService.QueueOrderProcessing(order);
            return await _repository.SaveOrder(order);
        }

        throw new ValidationException(validationResult.Errors);
    }
}
