public class SqlDataRepository : IDataRepository
{
    private readonly string _connectionString;

    public SqlDataRepository(IConfiguration configuration)
    {
        _connectionString = configuration.GetConnectionString("DefaultConnection");
    }

    public async Task<bool> SaveDataAsync(DataModel data)
    {
        using var connection = new SqlConnection(_connectionString);
        await connection.OpenAsync();

        // Example SQL command
        var command = new SqlCommand("INSERT INTO DataTable (Field1, Field2) VALUES (@Value1, @Value2)", connection);
        command.Parameters.AddWithValue("@Value1", data.Field1);
        command.Parameters.AddWithValue("@Value2", data.Field2);

        var rowsAffected = await command.ExecuteNonQueryAsync();
        return rowsAffected > 0;
    }
}
```

