# High-Performance Web Server in Go

Here's a high-performance web server implementation in Go that can handle a large number of concurrent requests efficiently. This example uses Go's built-in `net/http` package with optimizations for high concurrency.

```go
package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"syscall"
	"time"
)

func main() {
	// Parse command line flags
	port := flag.Int("port", 8080, "Port to listen on")
	workers := flag.Int("workers", runtime.NumCPU(), "Number of worker goroutines")
	timeout := flag.Duration("timeout", 30*time.Second, "Request timeout duration")
	flag.Parse()

	// Set GOMAXPROCS to match the number of CPU cores
	runtime.GOMAXPROCS(runtime.NumCPU())

	// Create a new server with optimized settings
	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      newRouter(),
		ReadTimeout:  *timeout,
		WriteTimeout: *timeout,
		IdleTimeout:  *timeout,
	}

	// Channel to listen for interrupt signals
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	// Start the server in a goroutine
	go func() {
		log.Printf("Server starting on port %d with %d workers", *port, *workers)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Could not listen on %s: %v\n", server.Addr, err)
		}
	}()

	// Block until we receive a signal
	<-stop

	// Create a context with timeout for shutdown
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Shutdown the server gracefully
	log.Println("Shutting down server...")
	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("Server shutdown failed: %v", err)
	}
	log.Println("Server stopped")
}

func newRouter() http.Handler {
	// Create a new ServeMux (router)
	mux := http.NewServeMux()

	// Register handlers
	mux.HandleFunc("/", homeHandler)
	mux.HandleFunc("/health", healthHandler)
	mux.HandleFunc("/api/data", dataHandler)

	// Wrap with middleware
	handler := loggingMiddleware(mux)
	handler = recoveryMiddleware(handler)

	return handler
}

// Middleware for logging requests
func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s %v", r.Method, r.URL.Path, r.RemoteAddr, time.Since(start))
	})
}

// Middleware for panic recovery
func recoveryMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				log.Printf("Panic recovered: %v", err)
				http.Error(w, "Internal Server Error", http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// Handlers
func homeHandler(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	w.Write([]byte("Welcome to the high-performance Go web server!"))
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status": "healthy"}`))
}

func dataHandler(w http.ResponseWriter, r *http.Request) {
	// Simulate some work
	time.Sleep(100 * time.Millisecond)

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"message": "Data processed successfully"}`))
}
```

