	runtime.GOMAXPROCS(runtime.NumCPU())

	// Create a new server with optimized settings
	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      http.HandlerFunc(handler),
		ReadTimeout:  *readTimeout,
		WriteTimeout: *writeTimeout,
		IdleTimeout:  *idleTimeout,
	}

	// Configure the server to handle many connections
	server.SetKeepAlivesEnabled(true)

	// Create a listener with a large backlog
	listener, err := net.Listen("tcp", server.Addr)
	if err != nil {
		log.Fatalf("Failed to create listener: %v", err)
	}

	// Set TCP keepalive parameters
	tcpListener := listener.(*net.TCPListener)
	tcpListener.SetKeepAlive(true)
	tcpListener.SetKeepAlivePeriod(30 * time.Second)

	// Set TCP buffer sizes
	tcpListener.SetReadBuffer(64 * 1024)  // 64KB read buffer
	tcpListener.SetWriteBuffer(64 * 1024) // 64KB write buffer

	log.Printf("Server starting on port %d with max connections %d", *port, *maxConns)

	// Channel to listen for termination signals
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	// Start the server in a goroutine
	go func() {
		if err := server.Serve(tcpListener); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server error: %v", err)
		}
	}()

	// Wait for termination signal
	<-stop

	// Create a context with timeout for graceful shutdown
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Shutdown the server gracefully
	log.Println("Shutting down server...")
	if err := server.Shutdown(ctx); err != nil {
		log.Printf("Server shutdown error: %v", err)
	} else {
		log.Println("Server stopped gracefully")
	}
}

