	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"syscall"
	"time"
)

func main() {
	// Parse command line flags
	port := flag.Int("port", 8080, "Port to listen on")
	maxConns := flag.Int("max-conns", 10000, "Maximum number of concurrent connections")
	readTimeout := flag.Duration("read-timeout", 5*time.Second, "Read timeout duration")
	writeTimeout := flag.Duration("write-timeout", 10*time.Second, "Write timeout duration")
	idleTimeout := flag.Duration("idle-timeout", 120*time.Second, "Idle timeout duration")
	flag.Parse()

	// Set GOMAXPROCS to match the number of CPU cores
	runtime.GOMAXPROCS(runtime.NumCPU())

	// Create a new server with optimized settings
	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      http.HandlerFunc(handleRequest),
		ReadTimeout:  *readTimeout,
		WriteTimeout: *writeTimeout,
		IdleTimeout:  *idleTimeout,
	}

	// Configure the server to handle many connections
	server.SetKeepAlivesEnabled(true)

	// Create a listener with backlog size
	listener, err := net.Listen("tcp", server.Addr)
	if err != nil {
		log.Fatalf("Failed to create listener: %v", err)
	}

	// Set TCP keep-alive parameters
	tcpListener := listener.(*net.TCPListener)
	tcpListener.SetKeepAlive(true)
	tcpListener.SetKeepAlivePeriod(30 * time.Second)

	// Set TCP buffer sizes
	tcpListener.SetReadBuffer(16 * 1024)  // 16KB read buffer
	tcpListener.SetWriteBuffer(32 * 1024) // 32KB write buffer

	// Set maximum number of open files
	var rLimit syscall.Rlimit
	if err := syscall.Getrlimit(syscall.RLIMIT_NOFILE, &rLimit); err != nil {
		log.Printf("Error getting rlimit: %v", err)
	} else {
		rLimit.Cur = rLimit.Max
		if err := syscall.Setrlimit(syscall.RLIMIT_NOFILE, &rLimit); err != nil {
			log.Printf("Error setting rlimit: %v", err)
		}
	}

	// Channel to listen for OS signals
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, os.Interrupt, syscall.SIGTERM)

	// Start the server in a goroutine
	go func() {
		log.Printf("Server starting on port %d", *port)
		if err := server.Serve(tcpListener); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server error: %v", err)
		}
	}()

	// Wait for interrupt signal
	<-stop

	// Create a context with timeout for shutdown
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	// Shutdown the server gracefully
	log.Println("Shutting down server...")
	if err := server.Shutdown(ctx); err != nil {
		log.Printf("Server shutdown error: %v", err)
	} else {
		log.Println("Server stopped")
	}
}

