	go processData("task1", &wg, results)
	go processData("task2", &wg, results)
	go processData("task3", &wg, results)

	go func() {
		wg.Wait()
		close(results)
	}()

	// Collect results
	var response string
	for result := range results {
		response += result + "\n"
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write([]byte(response))
}

func processData(task string, wg *sync.WaitGroup, results chan<- string) {
