	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      newRouter(),
		ReadTimeout:  *readTimeout,
		WriteTimeout: *writeTimeout,
		IdleTimeout:  *idleTimeout,
	}

	// Configure the server to limit concurrent connections
	limiter := make(chan struct{}, *maxConns)
	server.ConnState = func(conn net.Conn, state http.ConnState) {
		switch state {
		case http.StateNew:
			select {
			case limiter <- struct{}{}:
				// Connection accepted
			default:
				// Too many connections, reject
				conn.Close()
			}
		case http.StateClosed, http.StateHijacked:
			<-limiter
		}
	}

	// Start the server in a goroutine
	go func() {
		log.Printf("Server starting on port %d", *port)
		if err := server.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server error: %v", err)
		}
	}()

	// Wait for interrupt signal
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	// Shutdown the server gracefully
	log.Println("Shutting down server...")
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("Server shutdown error: %v", err)
	}

	log.Println("Server stopped")
}

func newRouter() http.Handler {
	router := http.NewServeMux()

	// Register routes
	router.HandleFunc("/", handleRoot)
	router.HandleFunc("/health", handleHealth)
	router.HandleFunc("/api/data", handleData)

	// Add middleware
	handler := loggingMiddleware(router)
	handler = recoveryMiddleware(handler)

	return handler
}

// Middleware for logging requests
func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s %v", r.Method, r.URL.Path, r.RemoteAddr, time.Since(start))
	})
}

// Middleware for recovering from panics
func recoveryMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if err := recover(); err != nil {
				log.Printf("Panic recovered: %v", err)
				http.Error(w, "Internal server error", http.StatusInternalServerError)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

// Handler functions
func handleRoot(w http.ResponseWriter, r *http.Request) {
	if r.URL.Path != "/" {
		http.NotFound(w, r)
		return
	}
	fmt.Fprintf(w, "Welcome to the high-performance Go web server!")
}

func handleHealth(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"status": "ok"}`)
}

func handleData(w http.ResponseWriter, r *http.Request) {
	// Simulate some work
	time.Sleep(10 * time.Millisecond)

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"message": "Data processed successfully"}`)
}
```

