# High-Performance Web Server in Go

Here's a high-performance web server implementation in Go that can handle a large number of concurrent requests efficiently. This example uses Go's built-in `net/http` package with optimizations for high concurrency.

```go
package main

import (
	"context"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"runtime"
	"syscall"
	"time"
)

func main() {
	// Parse command line flags
	port := flag.Int("port", 8080, "Port to listen on")
	maxConns := flag.Int("max-conns", 10000, "Maximum number of concurrent connections")
	readTimeout := flag.Duration("read-timeout", 5*time.Second, "Read timeout duration")
	writeTimeout := flag.Duration("write-timeout", 10*time.Second, "Write timeout duration")
	idleTimeout := flag.Duration("idle-timeout", 120*time.Second, "Idle timeout duration")
	flag.Parse()

	// Set GOMAXPROCS to utilize all available CPU cores
	runtime.GOMAXPROCS(runtime.NumCPU())

	// Create a new server with optimized settings
	server := &http.Server{
		Addr:         fmt.Sprintf(":%d", *port),
		Handler:      http.HandlerFunc(handleRequest),
		ReadTimeout:  *readTimeout,
		WriteTimeout: *writeTimeout,
		IdleTimeout:  *idleTimeout,
	}

	// Configure the server for high concurrency
	server.SetKeepAlivesEnabled(true)

	// Create a listener with connection limits
	listener, err := newListener(*port, *maxConns)
	if err != nil {
		log.Fatalf("Failed to create listener: %v", err)
	}

	// Start the server in a goroutine
	go func() {
		log.Printf("Server starting on port %d", *port)
		if err := server.Serve(listener); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server error: %v", err)
		}
	}()

	// Wait for interrupt signal
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	// Graceful shutdown
	log.Println("Shutting down server...")
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := server.Shutdown(ctx); err != nil {
		log.Fatalf("Server shutdown error: %v", err)
	}
	log.Println("Server stopped")
}

func handleRequest(w http.ResponseWriter, r *http.Request) {
	// Simple response - replace with your actual request handling logic
	w.Header().Set("Content-Type", "text/plain")
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Hello, World! Request handled by %s\n", r.RemoteAddr)
}

// newListener creates a TCP listener with connection limits
func newListener(port, maxConns int) (*net.TCPListener, error) {
	addr := fmt.Sprintf(":%d", port)
	tcpAddr, err := net.ResolveTCPAddr("tcp", addr)
	if err != nil {
		return nil, err
	}

	listener, err := net.ListenTCP("tcp", tcpAddr)
	if err != nil {
		return nil, err
	}

	// Set socket options for better performance
	if err := setSocketOptions(listener); err != nil {
		return nil, err
	}

	return listener, nil
}

// setSocketOptions configures socket options for better performance
func setSocketOptions(listener *net.TCPListener) error {
	file, err := listener.File()
	if err != nil {
		return err
	}
	defer file.Close()

	// Set socket options
	if err := syscall.SetsockoptInt(int(file.Fd()), syscall.SOL_SOCKET, syscall.SO_REUSEADDR, 1); err != nil {
		return err
	}

	// Set TCP keepalive
	if err := syscall.SetsockoptInt(int(file.Fd()), syscall.SOL_SOCKET, syscall.SO_KEEPALIVE, 1); err != nil {
		return err
	}

	// Set TCP_NODELAY to disable Nagle's algorithm
	if err := syscall.SetsockoptInt(int(file.Fd()), syscall.IPPROTO_TCP, syscall.TCP_NODELAY, 1); err != nil {
		return err
	}

	return nil
}
```

