# Minimal Evaluation Harness for Language Models

Below is a minimal working version of an evaluation harness that:
1. Takes a set of prompts
2. Runs them against multiple language models
3. Scores the responses
4. Outputs the results

```python
import json
from typing import List, Dict, Callable
from abc import ABC, abstractmethod

# Base class for language models
class LanguageModel(ABC):
    @abstractmethod
    def generate_response(self, prompt: str) -> str:
        pass

# Example implementation for a local model (you would replace with actual API calls)
class LocalModel(LanguageModel):
    def __init__(self, name: str, model_path: str):
        self.name = name
        self.model_path = model_path

    def generate_response(self, prompt: str) -> str:
        # In a real implementation, this would call the actual model
        # For this example, we'll just return a mock response
        return f"Mock response from {self.name} to: {prompt}"

# Evaluation harness
class EvaluationHarness:
    def __init__(self, models: List[LanguageModel], evaluators: Dict[str, Callable[[str, str], float]]):
        self.models = models
        self.evaluators = evaluators

    def evaluate(self, prompts: List[str], ground_truths: List[str]) -> Dict:
        results = {
            "models": [model.name for model in self.models],
            "prompts": prompts,
            "results": []
        }

        for prompt, ground_truth in zip(prompts, ground_truths):
            prompt_results = {"prompt": prompt, "ground_truth": ground_truth, "model_results": []}

            for model in self.models:
                response = model.generate_response(prompt)
                scores = {}

                for evaluator_name, evaluator in self.evaluators.items():
                    score = evaluator(response, ground_truth)
                    scores[evaluator_name] = score

                prompt_results["model_results"].append({
                    "model": model.name,
                    "response": response,
                    "scores": scores
                })

            results["results"].append(prompt_results)

        return results

# Example evaluators
def exact_match(response: str, ground_truth: str) -> float:
    return 1.0 if response.strip() == ground_truth.strip() else 0.0

def length_match(response: str, ground_truth: str) -> float:
    return len(response) / len(ground_truth) if ground_truth else 0.0

# Example usage
if __name__ == "__main__":
    # Define models to evaluate
    models = [
        LocalModel("Model A", "path/to/model_a"),
        LocalModel("Model B", "path/to/model_b")
    ]

    # Define evaluators
    evaluators = {
        "exact_match": exact_match,
        "length_match": length_match
    }

    # Create harness
    harness = EvaluationHarness(models, evaluators)

    # Define prompts and ground truths
    prompts = [
        "What is the capital of France?",
        "Explain quantum computing in simple terms."
    ]
    ground_truths = [
        "The capital of France is Paris.",
        "Quantum computing uses quantum bits to perform calculations."
    ]

    # Run evaluation
    results = harness.evaluate(prompts, ground_truths)

    # Output results
    print(json.dumps(results, indent=2))
```

